/// Whether a dispatch instantiation replays a template's checked relations
/// or serves an expression. Result-type queries serve expressions: they
/// lower argument evidence and complete iterator results exactly as the
/// expression's own lowering does, so the two agree on every result cell.
const DispatchInstantiationPhase = enum {
    template_relation_replay,
    expression_lowering,
};

/// How a specialization request refers to its procedure. Checking records a
/// `recursive_reference` when a lookup targets a member of an on-stack
/// recursive binding group; only such a request with the active
/// specialization's substitution may join an in-progress ancestor before its
/// fresh interface cells are related. Every other
/// request instantiates a scheme (a scheme use, a dispatch target, a generated
/// codec's component call, or a compiler-generated component edge) and
/// identifies with an existing specialization only through an exact interface.
const DraftRequestEdge = enum {
    instantiation,
    recursive_reference,
};

/// Coordinator-facing view of one frozen graph's finalized type/name domain.
/// Keeping this boundary explicit prevents program output from depending on
/// graph-store ownership. The identity mode preserves shared-store bodies;
/// private stores attach one cumulative relocation at ordered commit.
const CommittedGraphTypes = struct {
    source_store: *Type.Store,
    source_names: *const names.NameStore,
    graph: ?*InstGraph,
    sealer: ?*GraphTypeFinals,
    destination: ?struct {
        store: *Type.Store,
        names: *names.NameStore,
        relocation: *Type.Store.TypeRelocation,
    } = null,

    fn shared(graph: *InstGraph, sealer: *GraphTypeFinals) CommittedGraphTypes {
        return .{
            .source_store = graph.types,
            .source_names = graph.name_store,
            .graph = graph,
            .sealer = sealer,
        };
    }

    fn relocated(
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
        destination: *Type.Store,
        destination_names: *names.NameStore,
        relocation: *Type.Store.TypeRelocation,
    ) CommittedGraphTypes {
        return .{
            .source_store = graph.types,
            .source_names = graph.name_store,
            .graph = graph,
            .sealer = sealer,
            .destination = .{
                .store = destination,
                .names = destination_names,
                .relocation = relocation,
            },
        };
    }

    /// Commit already-sealed types from an immutable copied workspace
    /// domain. Coordinator commit deliberately has no graph or graph sealer.
    fn relocatedStore(
        source_store: *Type.Store,
        source_names: *const names.NameStore,
        destination: *Type.Store,
        destination_names: *names.NameStore,
        relocation: *Type.Store.TypeRelocation,
    ) CommittedGraphTypes {
        return .{
            .source_store = source_store,
            .source_names = source_names,
            .graph = null,
            .sealer = null,
            .destination = .{
                .store = destination,
                .names = destination_names,
                .relocation = relocation,
            },
        };
    }

    /// Commit several types through one import: types already relocated are
    /// answered from the relocation map and the rest share one closure walk
    /// and one interning transaction. The result is owned by the caller.
    fn commitTypes(self: *CommittedGraphTypes, allocator: Allocator, tys: []const Type.TypeId) Allocator.Error![]Type.TypeId {
        const committed = try allocator.alloc(Type.TypeId, tys.len);
        errdefer allocator.free(committed);
        const destination = self.destination orelse {
            @memcpy(committed, tys);
            return committed;
        };
        var pending = std.ArrayList(Type.TypeId).empty;
        defer pending.deinit(allocator);
        var pending_slots = std.ArrayList(usize).empty;
        defer pending_slots.deinit(allocator);
        for (tys, 0..) |ty, index| {
            if (self.graph) |graph| try graph.assertTypeHasNoActiveSnapshots(ty);
            if (@backingInt(ty) >= self.source_store.epochBoundary().types) {
                Common.compilerBug("sealed body type does not belong to its immutable store epoch");
            }
            if (destination.relocation.get(self.source_store, ty)) |mapped| {
                committed[index] = mapped;
            } else {
                try pending.append(allocator, ty);
                try pending_slots.append(allocator, index);
            }
        }
        if (pending.items.len != 0) {
            var imported = try destination.store.importTypes(
                destination.names,
                self.source_store,
                self.source_names,
                destination.relocation,
                pending.items,
            );
            defer imported.deinit();
            for (pending_slots.items, imported.roots) |slot, root| committed[slot] = root;
        }
        return committed;
    }

    fn commitType(self: *CommittedGraphTypes, ty: Type.TypeId) Allocator.Error!Type.TypeId {
        if (self.graph) |graph| try graph.assertTypeHasNoActiveSnapshots(ty);
        const destination = self.destination orelse return ty;
        if (@backingInt(ty) >= self.source_store.epochBoundary().types) {
            Common.compilerBug("sealed body type does not belong to its immutable store epoch");
        }
        if (destination.relocation.get(self.source_store, ty)) |mapped| return mapped;
        var imported = try destination.store.importTypes(
            destination.names,
            self.source_store,
            self.source_names,
            destination.relocation,
            &.{ty},
        );
        defer imported.deinit();
        return imported.roots[0];
    }

    /// Commit an export name interned in the source domain's name store.
    fn commitExportName(self: *CommittedGraphTypes, name: names.ExportNameId) Allocator.Error!names.ExportNameId {
        const destination = self.destination orelse return name;
        return destination.names.internExportName(self.source_names.exportNameText(name));
    }

    fn sealNode(self: *CommittedGraphTypes, node: NodeId) Allocator.Error!Type.TypeId {
        const sealer = self.sealer orelse
            Common.compilerBug("graph-free Monotype coordinator commit attempted to seal a graph node");
        return self.commitType(try sealer.sealNode(node));
    }

    fn sealType(self: *CommittedGraphTypes, ty: Type.TypeId) Allocator.Error!Type.TypeId {
        if (self.sealer) |sealer| return self.commitType(try sealer.sealType(ty));
        return self.commitType(ty);
    }

    fn commitRecordFieldName(
        self: *CommittedGraphTypes,
        name: names.RecordFieldNameId,
    ) Allocator.Error!names.RecordFieldNameId {
        const destination = self.destination orelse return name;
        return destination.relocation.namesRelocation().relocateRecordFieldLabel(
            self.source_names,
            name,
        );
    }

    fn commitTagName(
        self: *CommittedGraphTypes,
        name: names.TagNameId,
    ) Allocator.Error!names.TagNameId {
        const destination = self.destination orelse return name;
        return destination.relocation.namesRelocation().relocateTagLabel(
            self.source_names,
            name,
        );
    }

    fn commitTypeDef(
        self: *CommittedGraphTypes,
        source: Type.TypeDef,
    ) Allocator.Error!Type.TypeDef {
        const destination = self.destination orelse return source;
        const relocation = destination.relocation.namesRelocation();
        var committed = source;
        committed.module = try relocation.relocateModuleIdentity(self.source_names, source.module);
        committed.type_name = try relocation.relocateTypeName(self.source_names, source.type_name);
        if (committed.iterator_topology) |*topology| {
            topology.len_field = try relocation.relocateRecordFieldLabel(self.source_names, topology.len_field);
            topology.step_field = try relocation.relocateRecordFieldLabel(self.source_names, topology.step_field);
            topology.known_tag = try relocation.relocateTagLabel(self.source_names, topology.known_tag);
            topology.unknown_tag = try relocation.relocateTagLabel(self.source_names, topology.unknown_tag);
            topology.done_tag = try relocation.relocateTagLabel(self.source_names, topology.done_tag);
            topology.one_tag = try relocation.relocateTagLabel(self.source_names, topology.one_tag);
            topology.skip_tag = try relocation.relocateTagLabel(self.source_names, topology.skip_tag);
            topology.item_field = try relocation.relocateRecordFieldLabel(self.source_names, topology.item_field);
            topology.rest_field = try relocation.relocateRecordFieldLabel(self.source_names, topology.rest_field);
        }
        return committed;
    }
};

/// A deferred request is counted at its caller-facing draft edge. Resolving
/// that edge after the caller seals must not count the same logical request a
/// second time.
const TemplateRequestAccounting = enum {
    count,
    already_counted,
};

/// Options used while lowering checked modules into Monotype IR.
pub const InlineExpectMode = enum {
    run,
    omit,
    /// Retain conditions and the producer-declared expect-free continuation.
    shared,

    fn includesConditions(self: InlineExpectMode) bool {
        return self != .omit;
    }

    fn continuationMode(self: InlineExpectMode) checked.InlineExpectMode {
        return switch (self) {
            .run => .run,
            .omit, .shared => .omit,
        };
    }
};

/// Configuration for lowering checked modules into Monotype IR.
pub const Options = struct {
    /// Preserve source-level procedure names for consumers that present runtime
    /// diagnostics from lowered code.
    proc_debug_names: bool = false,
    /// The object cache to ask for closed specializations at reservation.
    spec_cache: ?Common.SpecCacheLookup = null,
    /// Optional deterministic counters for specialization-shape tests.
    specialization_counters: ?*SpecializationCounters = null,
    /// Optional deterministic workload diagnostics. The checked pipeline
    /// supplies this only for detailed `--timings` reporting.
    diagnostics: ?*Diagnostics = null,
    /// Whether inline expects should be lowered at all. Optimized runtime builds
    /// omit them before their conditions can affect control-flow decisions.
    inline_expects: InlineExpectMode = .run,
    /// Restore stored constants as readonly static-data candidates when their
    /// ConstStore shape may require runtime storage.
    static_data_literals: bool = false,
    /// Produce immutable selected-root reads for a shared evaluation/runtime session.
    comptime_value_reads: bool = false,
    /// Turn each specialized custom literal's conversion into a literal root
    /// whose completed value the specialization reads. The consumer that
    /// asks for this evaluates every literal root the program registers.
    literal_roots: bool = false,
    target_usize: base.target.TargetUsize = base.target.TargetUsize.native,
    /// Optional executor for isolated procedure roots and ordinary
    /// specialization batches.
    post_check_executor: ?base.post_check_task_executor.Executor = null,
    /// Optional phase timings for the work owned by Monotype lowering.
    timing: ?*Timing = null,
};

/// Aggregate execution measurements for executor-backed Monotype work.
///
/// Worker work is the sum of task callback elapsed times, not process or thread
/// CPU time, so it may exceed Monotype wall time when callbacks overlap.
pub const ParallelMetricsSnapshot = struct {
    /// Sum of executor callback intervals; overlapping work is counted once per
    /// callback and can therefore exceed wall time.
    worker_work_ns: u64 = 0,
    /// Sum of validation, discard, and ordered commit intervals after executor
    /// barriers.
    coordinator_post_batch_work_ns: u64 = 0,
    root_tasks_submitted: u64 = 0,
    root_tasks_committed: u64 = 0,
    specialization_tasks_submitted: u64 = 0,
    specialization_tasks_committed: u64 = 0,
    specialization_tasks_discarded_ready: u64 = 0,
    /// Root batches plus ordinary-specialization streaming sessions.
    task_waves: u64 = 0,
    /// Largest executor width represented by any aggregated lowering.
    peak_worker_lanes_available: u64 = 0,
    /// Largest number of lanes used by any one aggregated lowering.
    peak_worker_lanes_used: u64 = 0,
    /// Tasks after the first task on a lane within one lowering invocation.
    within_lowering_lane_reuse_tasks: u64 = 0,
    /// Largest number of lightweight specialization identities waiting in the
    /// deterministic FIFO.
    peak_specialization_jobs_pending: u64 = 0,
    /// Largest number of completed heavyweight shards retained at one ordered
    /// commit barrier.
    peak_specialization_shards_retained: u64 = 0,
};

/// Timings for coordinator wall phases and aggregate executor work owned by
/// Monotype lowering.
pub const Timing = struct {
    std_io: std.Io,
    setup_ns: u64 = 0,
    procedure_specialization_ns: u64 = 0,
    procedure_root_wrapper_ns: u64 = 0,
    procedure_lookup_reservation_ns: u64 = 0,
    procedure_dispatch_evidence_ns: u64 = 0,
    procedure_body_graph_setup_ns: u64 = 0,
    procedure_body_lowering_ns: u64 = 0,
    procedure_body_type_graph_ns: u64 = 0,
    procedure_body_call_dispatch_ns: u64 = 0,
    procedure_body_draft_ir_ns: u64 = 0,
    procedure_body_reachability_ns: u64 = 0,
    procedure_body_source_mapping_ns: u64 = 0,
    procedure_body_local_proc_context_ns: u64 = 0,
    procedure_body_finalization_ns: u64 = 0,
    procedure_completion_ns: u64 = 0,
    procedure_parallel_wait_ns: u64 = 0,
    layout_requests_ns: u64 = 0,
    static_data_requests_ns: u64 = 0,
    finalization_ns: u64 = 0,
    parallel: ParallelMetricsSnapshot = .{},
    body_work_timing_enabled: bool = false,
    active_procedure_phase: ?ProcedureTimingPhase = null,
    active_procedure_phase_started_ns: i64 = 0,
    active_body_work_phase: ?BodyWorkTimingPhase = null,
    active_body_work_started_ns: i64 = 0,

    pub fn init(std_io: std.Io) Timing {
        return .{ .std_io = std_io };
    }

    pub fn snapshot(self: *const Timing) TimingSnapshot {
        var result: TimingSnapshot = .{};
        inline for (@typeInfo(TimingSnapshot).@"struct".field_names) |field_name| {
            @field(result, field_name) = @field(self, field_name);
        }
        return result;
    }

    fn start(self: *const Timing) i64 {
        return timingNowNs(self.std_io);
    }

    fn finish(self: *Timing, started_ns: i64, phase: TimingPhase) void {
        const finished_ns: i64 = @intCast(@max(0, std.Io.Timestamp.now(self.std_io, .awake).nanoseconds));
        const elapsed_ns: u64 = @intCast(@max(0, finished_ns - started_ns));
        switch (phase) {
            .setup => self.setup_ns +%= elapsed_ns,
            .procedure_specialization => self.procedure_specialization_ns +%= elapsed_ns,
            .layout_requests => self.layout_requests_ns +%= elapsed_ns,
            .static_data_requests => self.static_data_requests_ns +%= elapsed_ns,
            .finalization => self.finalization_ns +%= elapsed_ns,
        }
    }

    fn startProcedureBreakdown(self: *Timing) void {
        if (self.active_procedure_phase != null) Common.invariant("Monotype procedure timing started twice");
        self.active_procedure_phase = .root_wrapper;
        self.active_procedure_phase_started_ns = self.start();
    }

    fn finishProcedureBreakdown(self: *Timing) void {
        self.switchProcedurePhase(null);
    }

    fn switchProcedurePhase(self: *Timing, next: ?ProcedureTimingPhase) void {
        const current = self.active_procedure_phase orelse {
            if (next != null) Common.invariant("Monotype procedure subphase started outside procedure lowering");
            return;
        };
        const now = self.start();
        const elapsed_ns: u64 = @intCast(@max(0, now - self.active_procedure_phase_started_ns));
        switch (current) {
            .root_wrapper => self.procedure_root_wrapper_ns +%= elapsed_ns,
            .lookup_reservation => self.procedure_lookup_reservation_ns +%= elapsed_ns,
            .dispatch_evidence => self.procedure_dispatch_evidence_ns +%= elapsed_ns,
            .body_graph_setup => self.procedure_body_graph_setup_ns +%= elapsed_ns,
            .body_lowering => self.procedure_body_lowering_ns +%= elapsed_ns,
            .body_finalization => self.procedure_body_finalization_ns +%= elapsed_ns,
            .completion => self.procedure_completion_ns +%= elapsed_ns,
            .parallel_wait => self.procedure_parallel_wait_ns +%= elapsed_ns,
        }
        self.active_procedure_phase = next;
        self.active_procedure_phase_started_ns = now;
    }

    fn switchBodyWorkPhase(self: *Timing, next: ?BodyWorkTimingPhase) void {
        const now = self.start();
        if (self.active_body_work_phase) |phase| {
            const elapsed_ns: u64 = @intCast(@max(0, now - self.active_body_work_started_ns));
            switch (phase) {
                .type_graph => self.procedure_body_type_graph_ns +%= elapsed_ns,
                .call_dispatch => self.procedure_body_call_dispatch_ns +%= elapsed_ns,
                .draft_ir => self.procedure_body_draft_ir_ns +%= elapsed_ns,
                .reachability => self.procedure_body_reachability_ns +%= elapsed_ns,
                .source_mapping => self.procedure_body_source_mapping_ns +%= elapsed_ns,
                .local_proc_context => self.procedure_body_local_proc_context_ns +%= elapsed_ns,
            }
        }
        self.active_body_work_phase = next;
        self.active_body_work_started_ns = now;
    }
};

fn timingNowNs(std_io: std.Io) i64 {
    return @intCast(@max(0, std.Io.Timestamp.now(std_io, .awake).nanoseconds));
}

/// Immutable Monotype phase timings consumed by checked-pipeline reporting.
pub const TimingSnapshot = struct {
    setup_ns: u64 = 0,
    procedure_specialization_ns: u64 = 0,
    procedure_root_wrapper_ns: u64 = 0,
    procedure_lookup_reservation_ns: u64 = 0,
    procedure_dispatch_evidence_ns: u64 = 0,
    procedure_body_graph_setup_ns: u64 = 0,
    procedure_body_lowering_ns: u64 = 0,
    procedure_body_type_graph_ns: u64 = 0,
    procedure_body_call_dispatch_ns: u64 = 0,
    procedure_body_draft_ir_ns: u64 = 0,
    procedure_body_reachability_ns: u64 = 0,
    procedure_body_source_mapping_ns: u64 = 0,
    procedure_body_local_proc_context_ns: u64 = 0,
    procedure_body_finalization_ns: u64 = 0,
    procedure_completion_ns: u64 = 0,
    procedure_parallel_wait_ns: u64 = 0,
    layout_requests_ns: u64 = 0,
    static_data_requests_ns: u64 = 0,
    finalization_ns: u64 = 0,
    parallel: ParallelMetricsSnapshot = .{},
};

const TimingPhase = enum {
    setup,
    procedure_specialization,
    layout_requests,
    static_data_requests,
    finalization,
};

const TimingPhaseScope = struct {
    timing: ?*Timing = null,
    started_ns: i64 = 0,
    phase: TimingPhase = undefined,

    fn begin(timing: ?*Timing, phase: TimingPhase) TimingPhaseScope {
        const active = timing orelse return .{};
        return .{
            .timing = active,
            .started_ns = active.start(),
            .phase = phase,
        };
    }

    fn end(self: *TimingPhaseScope) void {
        const timing = self.timing orelse return;
        timing.finish(self.started_ns, self.phase);
        self.timing = null;
    }
};

const ProcedureTimingPhase = enum {
    root_wrapper,
    lookup_reservation,
    dispatch_evidence,
    body_graph_setup,
    body_lowering,
    body_finalization,
    completion,
    parallel_wait,
};

const ProcedureTimingScope = struct {
    timing: ?*Timing = null,
    previous: ProcedureTimingPhase = undefined,

    fn begin(timing: ?*Timing, phase: ProcedureTimingPhase) ProcedureTimingScope {
        const active = timing orelse return .{};
        const previous = active.active_procedure_phase orelse return .{};
        active.switchProcedurePhase(phase);
        return .{ .timing = active, .previous = previous };
    }

    fn end(self: *ProcedureTimingScope) void {
        const timing = self.timing orelse return;
        timing.switchProcedurePhase(self.previous);
        self.timing = null;
    }
};

/// Aggregate elapsed coordinator work after an executor batch has completed,
/// including validation, discard, and ordered commit.
///
/// This overlaps the coordinator's procedure wall-time classification and is
/// therefore reported as work rather than as another sequential phase.
const ParallelCoordinatorTimingScope = struct {
    timing: ?*Timing = null,
    started_ns: i64 = 0,

    fn begin(timing: ?*Timing) ParallelCoordinatorTimingScope {
        const active = timing orelse return .{};
        return .{ .timing = active, .started_ns = active.start() };
    }

    fn end(self: *ParallelCoordinatorTimingScope) void {
        const timing = self.timing orelse return;
        const finished_ns = timing.start();
        const elapsed_ns: u64 = @intCast(@max(0, finished_ns - self.started_ns));
        timing.parallel.coordinator_post_batch_work_ns +%= elapsed_ns;
        self.timing = null;
    }
};

const BodyWorkTimingPhase = enum {
    type_graph,
    call_dispatch,
    draft_ir,
    reachability,
    source_mapping,
    local_proc_context,
};

/// Measure mutually-exclusive work nested inside procedure-body lowering.
/// A nested category pauses its parent category and restores it on exit, so
/// the reported rows never double-count one another.
const BodyWorkTimingScope = struct {
    timing: ?*Timing = null,
    previous: ?BodyWorkTimingPhase = null,
    changed: bool = false,

    fn begin(timing: ?*Timing, phase: BodyWorkTimingPhase) BodyWorkTimingScope {
        const active = timing orelse return .{};
        if (!active.body_work_timing_enabled) return .{};
        if (active.active_procedure_phase != .body_lowering) return .{};
        const previous = active.active_body_work_phase;
        if (previous == phase) return .{};
        active.switchBodyWorkPhase(phase);
        return .{ .timing = active, .previous = previous, .changed = true };
    }

    fn end(self: *BodyWorkTimingScope) void {
        if (!self.changed) return;
        const timing = self.timing.?;
        timing.switchBodyWorkPhase(self.previous);
        self.timing = null;
        self.changed = false;
    }
};

/// Deterministic counters used by specialization-shape tests.
pub const SpecializationCounters = specialize.Counters;

/// Deterministic counts for body-context, type-instantiation, and call work.
pub const BodyDiagnostics = struct {
    /// Nested specialization candidate-index probes and candidates examined.
    nested_lookup_probes: u64 = 0,
    /// Entries examined while mapping draft functions to committed identities.
    draft_commit_lookup_steps: u64 = 0,
    graphs_created: u64 = 0,
    body_contexts_created: u64 = 0,
    instantiation_scopes_created: u64 = 0,
    checked_node_requests: u64 = 0,
    checked_node_cache_hits: u64 = 0,
    checked_node_cache_misses: u64 = 0,
    fresh_checked_node_requests: u64 = 0,
    call_expressions: u64 = 0,
    dispatch_expressions: u64 = 0,
    deferred_template_requests: u64 = 0,
    spec_jobs_enqueued: u64 = 0,
    spec_jobs_executed: u64 = 0,
    spec_jobs_skipped_ready: u64 = 0,
    spec_job_shards_lowered: u64 = 0,
    spec_job_shards_committed: u64 = 0,
    caller_owned_template_bodies_lowered: u64 = 0,
    eager_iterator_template_bodies_lowered: u64 = 0,
    deferred_template_reuses: u64 = 0,
    deferred_template_bodies_lowered: u64 = 0,
    lowered_template_bodies_discarded: u64 = 0,
    lowered_nested_bodies_discarded: u64 = 0,
    expr_relation_requests: u64 = 0,
    argument_spans_prepared: u64 = 0,
    arguments_prepared: u64 = 0,
    direct_call_request_reuses: u64 = 0,
    nested_callable_checks: u64 = 0,
    nested_lambdas_prepared: u64 = 0,
    nested_closures_prepared: u64 = 0,
    /// Requests that project symbolic evidence over their checked callable.
    callable_evidence_symbolic_requests: u64 = 0,
    /// Immutable evidence vectors copied because at least one entry resolved.
    callable_evidence_vector_copies: u64 = 0,
};

/// Deterministic Monotype workload counts. These diagnose how much exact
/// instantiation and call preparation occurred; they never affect lowering.
pub const Diagnostics = struct {
    specialization: SpecializationCounters = .{},
    graph: solve.GraphDiagnostics = .{},
    body: BodyDiagnostics = .{},

    pub fn add(self: *Diagnostics, other: Diagnostics) void {
        addFlatCounters(SpecializationCounters, &self.specialization, other.specialization);
        addFlatCounters(solve.GraphDiagnostics, &self.graph, other.graph);
        addFlatCounters(BodyDiagnostics, &self.body, other.body);
    }
};

/// Workload diagnostics produced by one ordinary specialization shard. These
/// remain shard-owned until ordered coordinator commit records them.
const SpecJobDiagnostics = struct {
    graph: solve.GraphDiagnostics = .{},
    body: BodyDiagnostics = .{},

    fn addTo(self: SpecJobDiagnostics, destination: *Diagnostics) void {
        addFlatCounters(solve.GraphDiagnostics, &destination.graph, self.graph);
        addFlatCounters(BodyDiagnostics, &destination.body, self.body);
    }
};

fn addFlatCounters(comptime T: type, destination: *T, source: T) void {
    inline for (@typeInfo(T).@"struct".field_names) |field_name| {
        @field(destination, field_name) = @field(destination, field_name) +| @field(source, field_name);
    }
}

/// Lower checked modules and explicit roots into Monotype IR.
pub fn run(
    allocator: Allocator,
    modules: Common.CheckedModules,
    roots: Common.RootRequests,
    options: Options,
) Common.LowerError!Ast.Program {
    if (roots.requests.len == 0 and roots.layout_requests.len == 0 and roots.static_data_requests.len == 0) {
        Common.invariant("Monotype lowering requires explicit roots, layout requests, or static data requests");
    }

    var setup_timing_scope = TimingPhaseScope.begin(options.timing, .setup);
    defer setup_timing_scope.end();
    var program = Ast.Program.init(allocator);
    errdefer program.deinit();

    var builder = Builder.init(allocator, modules, &program, options);
    defer builder.deinit();
    try builder.seedProgramModuleTables();
    // Cache admission must know the current app filling before any body is
    // skipped. Checked bindings are immutable throughout this producer.
    program.platform_requirement_filling = builder.platformRequirementFilling();
    var digest_stats: Type.Store.DigestStats = .{};
    program.types.digest_stats = if (builder.counters != null) &digest_stats else null;
    defer {
        program.types.digest_stats = null;
        builder.addDigestStats(digest_stats);
    }
    try builder.initHostedCatalog();
    setup_timing_scope.end();

    // Wave 1: roots in listed order, then the specialization queue. Each
    // root remains a distinct job whose result lands in root order; symbolic
    // requests discovered while roots seal are reserved immediately and their
    // bodies drain afterward in deterministic dispatch order.
    {
        var procedure_timing_scope = TimingPhaseScope.begin(options.timing, .procedure_specialization);
        defer procedure_timing_scope.end();
        if (options.timing) |timing| timing.startProcedureBreakdown();
        defer if (options.timing) |timing| timing.finishProcedureBreakdown();
        try builder.lowerIsolatedRoots(roots.requests, roots.source_modules);
        try builder.drainPendingSpecJobs();
    }

    // Wave 2: layout requests lower types serially and discover no
    // specializations, so the queue must still be empty afterward.
    {
        var layout_timing_scope = TimingPhaseScope.begin(options.timing, .layout_requests);
        defer layout_timing_scope.end();
        for (roots.layout_requests) |checked_ty| {
            try builder.lowerLayoutRequest(checked_ty);
        }
        builder.requirePendingSpecJobsDrained();
    }

    // Wave 3: static-data restoration in listed order, then a second
    // specialization queue drain for the template bodies it discovered.
    {
        var static_data_timing_scope = TimingPhaseScope.begin(options.timing, .static_data_requests);
        defer static_data_timing_scope.end();
        for (roots.static_data_requests) |request| {
            try builder.lowerStaticDataRequest(request);
        }
        try builder.drainPendingSpecJobs();
    }

    {
        var finalization_timing_scope = TimingPhaseScope.begin(options.timing, .finalization);
        defer finalization_timing_scope.end();
        program.next_symbol = builder.symbols.coordinator.next;
        builder.stampSingleSourceCalls();
        try program.sealRemainingCaptureIdentities();
        try recordComptimeValueReads(allocator, &program);
        program.freeze();

        if (@import("builtin").mode == .debug) {
            verifyMonotypeTypeStore(&program);
            verifyMonotypeCompletedTypeIds(&program);
            verifyMonotypeCallTargets(&program);
            builder.spec_store.validateLookupIntegrity();
            verifyMonotypeSpecsReady(&program);
        }
    }

    program.types.digest_stats = null;
    return program;
}

/// Record the evaluated roots this program reads a completed value of.
///
/// A root-slot read is this stage's own explicit record of that demand, so
/// the program states it once here instead of leaving every later consumer to
/// rediscover it. Whoever materializes completed values materializes exactly
/// these: a root nothing reads is still evaluated for its diagnostics, and its
/// value is retained only by the checked module data that asked for it.
/// Find `name` in a record row. Rows are normalized with fields in sorted
/// label order (design.md "Rows are normalized once"), so the lookup is a
/// binary search by label text.
fn sortedRecordField(fields: anytype, name_store: *const names.NameStore, name: names.RecordFieldNameId) Type.Field {
    var low: usize = 0;
    var high: usize = GuardedList.borrowLen(fields);
    while (low < high) {
        const mid = low + (high - low) / 2;
        const field = GuardedList.at(fields, mid);
        if (field.name == name) return field;
        if (name_store.recordFieldLabelTextLessThan(field.name, name)) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    Common.invariant("record pattern field was absent from checked record type");
}

fn recordComptimeValueReads(allocator: Allocator, program: *Ast.Program) Allocator.Error!void {
    var recorded = std.AutoHashMap(EntryRoot, void).init(allocator);
    defer recorded.deinit();
    for (program.exprsView()) |expr| {
        if (expr.data != .comptime_value) continue;
        const root = program.getComptimeValueRoot(expr.data.comptime_value.root);
        // A literal root belongs to this program alone: every consumer that
        // lowers its reads also evaluates it, so no checked module data asks
        // for its completed value.
        const checked_root = switch (root.root) {
            .checked => |id| id,
            .literal => continue,
        };
        const entry = try recorded.getOrPut(.{ .module = root.module, .root = checked_root });
        if (entry.found_existing) continue;
        try program.addComptimeValueRead(root);
    }
}

/// Every specialization record must have finished lowering by the time the
/// program completes: reservations are drained by the graph that made them,
/// and `SpecBuilder` owns the only `reserved → lowering → ready` transitions.
fn verifyMonotypeSpecsReady(program: *const Ast.Program) void {
    for (program.specsView()) |record| {
        if (record.status != .ready) {
            Common.invariant("completed Monotype program contained an unfinished specialization record");
        }
    }
}

const ModuleIndexSlot = union(enum) {
    root,
    import: u32,
    relation: u32,
};

/// A checked module's tables, built once per builder (`Builder.module_views`)
/// and shared by reference: a view is read on nearly every lowering step, so
/// it is never copied.
const ModuleView = *const ModuleViewData;

const ModuleViewData = struct {
    code_generation_key: ?checked.ModuleId = null,
    key: checked.ModuleId,
    module_env: *const can.ModuleEnv,
    module_identity: checked.ModuleIdentity,
    names: *const names.NameStore,
    types: checked.CheckedTypeStoreView,
    bodies: checked.CheckedBodyStoreView,
    exhaustiveness_sites: *const checked.CheckedExhaustivenessSiteTable,
    checked_const_bodies: *const checked.CheckedConstBodyTable,
    templates: *const checked.CheckedProcedureTemplateTable,
    compile_time_roots: *const checked.CompileTimeRootTable,
    entry_wrappers: *const checked.EntryWrapperTable,
    intrinsic_wrappers: *const checked.IntrinsicWrapperTable,
    hosted_procs: *const checked.HostedProcTable,
    hosted_bindings: *const checked.HostedBindingTable,
    static_dispatch_plans: *const static_dispatch.StaticDispatchPlanTable,
    method_registry: *const static_dispatch.MethodRegistry,
    method_lookup_scope: []const checked.ModuleId,
    resolved_refs: *const checked.ResolvedValueTable,
    nested_proc_sites: *const checked.NestedProcSiteTable,
    exported_procedure_bindings: checked.ExportedProcedureBindingView,
    exported_const_templates: checked.ExportedConstTemplateView,
    top_level_procedure_bindings: *const checked.TopLevelProcedureBindingTable,
    platform_required_bindings: *const checked.PlatformRequiredBindingTable,
    callable_eval_templates: checked.CallableEvalTemplateTableView,
    hoisted_constants: *const checked.HoistedConstTable,
    const_templates: *const checked.ConstTemplateTable,
    const_store: *const checked.ConstStore,
    interface_capabilities: *const checked.ModuleInterfaceCapabilities,
};

const ConstNode = struct {
    module: ModuleView,
    id: checked.ConstNodeId,
};

const CallableInstantiation = struct {
    view: ModuleView,
    callable_ty: checked.CheckedTypeId,
};

/// The substitution checking applied to a selected target's scheme at the
/// edge that selected it: one checked type per quantified variable, in the
/// target scheme's `scheme_vars` order, read in `view`.
const CheckedTargetSubstitution = struct {
    view: ModuleView,
    tys: []const checked.CheckedTypeId,
};

const DraftLocalProcContextId = enum(u32) { _ };

const MethodLookup = struct {
    view: ModuleView,
    target: static_dispatch.MethodTarget,
    instantiation: ?CallableInstantiation = null,
    /// The checked edge's substitution for the target's scheme, when checking
    /// selected this target for this relation.
    substitution: ?CheckedTargetSubstitution = null,
    /// Exact lexical declaration instance for a local method target. Checked
    /// binder ids identify source syntax, not the specialization-local capture
    /// environment in which that declaration was lowered.
    local_proc_context: ?DraftLocalProcContextId = null,
};

/// One resolved dispatch requirement supplied to a specialization: either a
/// concrete method target (with the target's own requirements resolved in
/// `nested`) or a compiler-derived structural implementation. Fully
/// materialized at the requesting call edge—checked `constraint(k)` refs are
/// substituted from the requester's own evidence there—so a specialization's
/// vector is self-contained (dictionary passing evaluated at compile time).
const SpecEvidence = union(enum) {
    target: *const SpecEvidenceTarget,
    structural: SpecStructuralEvidence,
    /// Callable-reachable evidence that remains symbolic while a reusable
    /// compile-time value is produced and resolves from the eventual request.
    /// Its position in the owning vector selects the checked parameter; no
    /// index from a forwarding frame may survive into the destination schema.
    from_callable: struct {
        independent_callable: bool,
        callable_contracts: []const SpecEvidence = &.{},
    },
    /// Abstract local scheme parameter, supplied by the checked use edge.
    from_scheme: u32,
    /// The edge left the requirement's dispatcher unsolved: no value of that
    /// type can ever reach the dispatch. Monotype represents that non-returning
    /// path with an ordinary Roc runtime crash instead of a dispatch call.
    unreachable_value,
    /// Checking rejected the edge's requirement (a reported missing method);
    /// if `roc run` continues and reaches the dispatch, Monotype emits an
    /// ordinary Roc runtime crash instead of returning a value.
    checked_error,
};

/// A structural derivation for one requirement. A derivation the site
/// recorded retains the checked entry, whose generated-codec contract names
/// the exact internal method instantiations; a derivation selected while
/// deriving a requirement from a receiver cell carries no checked entry.
const CheckedSpecStructuralEvidence = struct {
    view: ModuleView,
    evidence: static_dispatch.StructuralEvidence,
};
const SpecStructuralEvidence = struct {
    derivation: static_dispatch.StructuralDerivation,
    checked: ?CheckedSpecStructuralEvidence = null,
    callable_contracts: []const SpecEvidence = &.{},
};

const SpecEvidenceTarget = struct {
    view: ModuleView,
    target: static_dispatch.MethodTarget,
    instantiation: ?CallableInstantiation,
    local_proc_context: ?DraftLocalProcContextId,
    nested: NestedSpecEvidence,
    /// The substitution checking applied to the target's scheme where it
    /// selected the target, which binds quantified variables that neither the
    /// target's root nor its requirement's callable reaches. It is consumed
    /// when the target specializes and is not part of the evidence's
    /// identity: those variables are determined by the selected targets, and
    /// the specialization is keyed by its completed substitution.
    substitution: ?CheckedTargetSubstitution = null,
    callable_contracts: []const SpecEvidence = &.{},
};

/// Whether materialized evidence selects a local procedure, as a target or
/// anywhere in a target's nested evidence and callable contracts.
fn specEvidenceSelectsLocalProc(entry: SpecEvidence) bool {
    switch (entry) {
        .target => |target| {
            if (target.target.kind == .local_proc) return true;
            switch (target.nested) {
                .resolved => |nested| for (nested) |child| {
                    if (specEvidenceSelectsLocalProc(child)) return true;
                },
                .synthesize => {},
            }
            for (target.callable_contracts) |contract| {
                if (specEvidenceSelectsLocalProc(contract)) return true;
            }
            return false;
        },
        .from_callable => |from_callable| {
            for (from_callable.callable_contracts) |contract| {
                if (specEvidenceSelectsLocalProc(contract)) return true;
            }
            return false;
        },
        .structural, .from_scheme, .unreachable_value, .checked_error => return false,
    }
}

/// Whether relating `contract` to its requirements relates anything: only a
/// selected target or a checked structural derivation, directly or as a
/// callable contract, is related to the requirement it satisfies.
fn evidenceContractRelatesAnything(contract: []const SpecEvidence) bool {
    for (contract) |entry| {
        switch (entry) {
            .target => return true,
            .structural => |structural| if (structural.checked != null) return true,
            .from_callable, .from_scheme, .unreachable_value, .checked_error => {},
        }
        if (evidenceContractRelatesAnything(evidenceCallableContracts(entry))) return true;
    }
    return false;
}

fn evidenceCallableContracts(evidence: SpecEvidence) []const SpecEvidence {
    return switch (evidence) {
        .target => |target| target.callable_contracts,
        .structural => |structural| structural.callable_contracts,
        .from_callable => |use| use.callable_contracts,
        .from_scheme, .unreachable_value, .checked_error => &.{},
    };
}

fn withCallableContracts(arena: Allocator, evidence: SpecEvidence, contracts: []const SpecEvidence) Allocator.Error!SpecEvidence {
    const current = evidenceCallableContracts(evidence);
    if (current.len == contracts.len and (contracts.len == 0 or current.ptr == contracts.ptr)) return evidence;
    return switch (evidence) {
        .target => |target| blk: {
            const copy = try arena.create(SpecEvidenceTarget);
            copy.* = target.*;
            copy.callable_contracts = contracts;
            break :blk .{ .target = copy };
        },
        .structural => |structural| blk: {
            var copy = structural;
            copy.callable_contracts = contracts;
            break :blk .{ .structural = copy };
        },
        .from_callable => |use| .{ .from_callable = .{
            .independent_callable = use.independent_callable,
            .callable_contracts = contracts,
        } },
        .from_scheme, .unreachable_value, .checked_error => evidence,
    };
}

/// An empty side vector explicitly leaves callable-derived evidence to the
/// request. Record-owned evidence must always have its exact indexed contract.
fn selectCallableContract(evidence: SpecEvidence, index: ?u32) ?SpecEvidence {
    const contract_index = index orelse return null;
    const contracts = evidenceCallableContracts(evidence);
    if (contracts.len == 0) return null;
    if (contract_index >= contracts.len) Common.invariant("dispatch callable contract index out of bounds");
    return contracts[contract_index];
}

/// A target's own requirements: resolved by checked evidence in checked module data,
/// or synthesized lazily at the target's consumption site (compiler-generated
/// edges have no checked records; the concrete callable type is only known
/// where the call lowers).
const NestedSpecEvidence = union(enum) {
    resolved: []const SpecEvidence,
    synthesize,
};

/// Whether evidence is being derived for Monotype body lowering or only to
/// close a specialization request's type interface. A local method's checked
/// declaration is sufficient for specialization-interface relation replay;
/// Monotype body uses must additionally carry the exact BodyDraft local
/// capture context. Either purpose relates each selected target's callable
/// to its constraint in the live graph: those relations are part of the
/// request's interface, not a side effect of lowering.
const EvidenceMaterializationPurpose = enum {
    body_lowering,
    specialization_interface,
    /// Materialize the input to an interface summary. Its selected contracts
    /// are related on the detached expansion graph and captured in the summary.
    interface_summary_input,
};

/// One quantified variable's binding at a specialization request: the live
/// graph cell the request substitutes for it, or checking's rejection of the
/// instantiation at that variable (a reported error; a dispatch that reaches
/// it crashes).
const SubstSlot = union(enum) {
    node: NodeId,
    checked_error,
};

/// The substitution a request applies to a scheme: one slot per quantified
/// variable, in the scheme's `scheme_vars` order. A specialization is the
/// scheme plus this vector, and every dispatch requirement's evidence is
/// derived from the slot its receiver occupies.
const SpecSubstitution = []const SubstSlot;

/// A callee scheme's requirement schema: the module that owns the scheme, its
/// quantified variables in slot order, and its evidence parameters in
/// scheme_vars order.
const SchemeRequirements = struct {
    view: ModuleView,
    /// The scheme's root type; null for a scheme with no callable root (a
    /// value without a template body).
    root: ?checked.CheckedTypeId,
    scheme_vars: []const checked.CheckedTypeId,
    params: []const static_dispatch.EvidenceParamRecord,
    /// Where `params` starts in `view`'s checked requirement pool; with the
    /// module, it names the requirement row.
    params_start: u32,
};

/// A substitution slot sealed to a durable Monotype type, for requests that
/// leave their requesting graph (reserved roots and queued bodies).
const SealedSubstSlot = union(enum) {
    ty: Type.TypeId,
    checked_error,
};

const SealedSubstitution = []const SealedSubstSlot;

/// Whether a template's body relates anything to its interface beyond its
/// checked root: a dispatch relation or a checked specialization relation.
fn templateHasInterfaceRelations(view: ModuleView, template: *const checked.CheckedProcedureTemplate) bool {
    return template.dispatch_relations.len != 0 or view.templates.specializationRelations(template).len != 0;
}

/// Whether a procedure template's checked function type is its complete
/// specialization interface. With no type variables in that root, none
/// quantified by its scheme (hidden requirement receivers included), and no
/// evidence supplied by its callers, a request is exactly the checked root:
/// the template's relation table relates only cells private to its own body,
/// so requesters never replay it.
fn templateInterfaceIsClosed(view: ModuleView, template: *const checked.CheckedProcedureTemplate) bool {
    const raw = @backingInt(template.checked_fn_root);
    if (raw >= view.types.roots.len) {
        Common.invariant("procedure template interface query referenced a missing checked root");
    }
    return template.scheme_vars.len == 0 and
        template.evidence_params.len == 0 and
        !view.types.roots[raw].contains_identity_variables;
}

/// A Roc template without evidence parameters cannot dispatch on its quantified
/// variables, so its interface relates a variable that occurs only in value
/// positions of its function type by unification alone. A request captures
/// such a variable's representation-neutral instantiation as a hole: one
/// summary serves every instantiation, and relating the summary back to the
/// request fills the hole. Row tails and arguments of nominal types other than
/// `List` and `Box` are not value positions.
fn parametricSchemeVarMask(
    allocator: Allocator,
    builder: *Builder,
    view: ModuleView,
    template: *const checked.CheckedProcedureTemplate,
) Allocator.Error![]const bool {
    const scheme_vars = view.templates.templateSchemeVars(template);
    if (template.target != .roc or template.evidence_params.len != 0 or scheme_vars.len == 0) {
        const mask = try allocator.alloc(bool, scheme_vars.len);
        @memset(mask, false);
        return mask;
    }
    return try valuePositionMask(allocator, builder, view, template.checked_fn_root, scheme_vars, null);
}

/// A checked nominal declaration, identified across modules.
const NominalDeclarationKey = struct {
    module: [32]u8,
    declaration: u32,
};

/// The declaration whose backing is being analyzed, and which of its
/// parameters the current fixpoint iteration assumes occur only as values.
const SelfDeclarationAssumption = struct {
    key: NominalDeclarationKey,
    assumed: []const bool,
};

/// Whether each of `targets` occurs reachable from `root` only as a value:
/// through function arguments and results, tuple items, record fields, tag
/// payloads, aliases, and the arguments of container nominals. A target also
/// reached as a row extension, a padding field, or the argument of a nominal
/// whose own parameters are not all values is excluded, as is a target that
/// never occurs. `self_declaration` names the nominal whose backing is being
/// walked; a recursive use of it passes each argument on as a value exactly
/// when the current fixpoint iteration assumes that parameter is one.
fn valuePositionMask(
    allocator: Allocator,
    builder: *Builder,
    view: ModuleView,
    root: checked.CheckedTypeId,
    targets: []const checked.CheckedTypeId,
    self_declaration: ?SelfDeclarationAssumption,
) Allocator.Error![]bool {
    const mask = try allocator.alloc(bool, targets.len);
    errdefer allocator.free(mask);
    @memset(mask, false);
    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const arena = scratch.allocator();
    const excluded = try arena.alloc(bool, targets.len);
    @memset(excluded, false);
    // Every visited type asks whether it is a target, so many targets are
    // indexed; the first position of a repeated target answers.
    const target_scan_limit = 16;
    var target_positions = collections.DenseMap(checked.CheckedTypeId, u32).init(arena);
    if (targets.len > target_scan_limit) {
        for (targets, 0..) |target, index| {
            const entry = try target_positions.getOrPut(target);
            if (!entry.found_existing) entry.value_ptr.* = @intCast(index);
        }
    }
    const Visit = struct { ty: checked.CheckedTypeId, value_position: bool };
    var pending = std.ArrayList(Visit).empty;
    var visited = [_]collections.DenseMap(checked.CheckedTypeId, void){
        collections.DenseMap(checked.CheckedTypeId, void).init(arena),
        collections.DenseMap(checked.CheckedTypeId, void).init(arena),
    };
    try pending.append(arena, .{ .ty = root, .value_position = true });
    while (pending.pop()) |visit| {
        if ((try visited[@intFromBool(visit.value_position)].getOrPut(visit.ty)).found_existing) continue;
        const target_index: ?usize = if (targets.len > target_scan_limit)
            if (target_positions.get(visit.ty)) |index| index else null
        else for (targets, 0..) |target, index| {
            if (target == visit.ty) break index;
        } else null;
        if (target_index) |index| {
            if (visit.value_position) mask[index] = true else excluded[index] = true;
            continue;
        }
        switch (view.types.payload(visit.ty)) {
            .function => |function| {
                for (function.args) |arg| try pending.append(arena, .{ .ty = arg, .value_position = visit.value_position });
                try pending.append(arena, .{ .ty = function.ret, .value_position = visit.value_position });
            },
            .tuple => |items| for (items) |item| try pending.append(arena, .{ .ty = item, .value_position = visit.value_position }),
            .record => |record| {
                for (record.fields) |field| try pending.append(arena, .{ .ty = field.ty, .value_position = visit.value_position });
                try pending.append(arena, .{ .ty = record.ext, .value_position = false });
            },
            .tag_union => |tag_union| {
                for (tag_union.tags) |tag| {
                    for (tag.argsSlice(view.types)) |arg| try pending.append(arena, .{ .ty = arg, .value_position = visit.value_position });
                }
                try pending.append(arena, .{ .ty = tag_union.ext, .value_position = false });
            },
            .nominal => |nominal| {
                for (nominal.padding_field_types) |padding| try pending.append(arena, .{ .ty = padding, .value_position = false });
                if (nominal.builtin) |builtin_nominal| {
                    const container = builtin_nominal == .list or builtin_nominal == .box or builtin_nominal == .try_;
                    for (nominal.args) |arg| try pending.append(arena, .{ .ty = arg, .value_position = visit.value_position and container });
                    continue;
                }
                const source = builder.nominalDeclarationSource(view, nominal) orelse {
                    for (nominal.args) |arg| try pending.append(arena, .{ .ty = arg, .value_position = false });
                    continue;
                };
                const key = NominalDeclarationKey{ .module = source.view.key.bytes, .declaration = @backingInt(source.declaration.id) };
                if (self_declaration) |current| if (std.meta.eql(current.key, key)) {
                    if (current.assumed.len != nominal.args.len) Common.invariant("checked nominal declaration arity differed from nominal type use");
                    for (nominal.args, current.assumed) |arg, is_value| try pending.append(arena, .{ .ty = arg, .value_position = visit.value_position and is_value });
                    continue;
                };
                const arg_values = try builder.nominalParameterValueMask(source.view, source.declaration, key);
                if (arg_values) |values| {
                    if (values.len != nominal.args.len) Common.invariant("checked nominal declaration arity differed from nominal type use");
                    for (nominal.args, values) |arg, is_value| try pending.append(arena, .{ .ty = arg, .value_position = visit.value_position and is_value });
                } else {
                    for (nominal.args) |arg| try pending.append(arena, .{ .ty = arg, .value_position = false });
                }
            },
            .alias => |alias| try pending.append(arena, .{ .ty = alias.backing, .value_position = visit.value_position }),
            .pending,
            .err,
            .flex,
            .rigid,
            .empty_record,
            .empty_tag_union,
            => {},
        }
    }
    for (mask, excluded) |*is_value, is_excluded| {
        if (is_excluded) is_value.* = false;
    }
    return mask;
}

/// A request's parametric substitution cells and their request-root positions.
const ParametricHoles = struct {
    nodes: []const NodeId = &.{},
    root_indices: []const u32 = &.{},
};

/// The requirement schema of a procedure template's scheme.
fn templateSchemaIn(view: ModuleView, template: *const checked.CheckedProcedureTemplate) SchemeRequirements {
    return .{
        .view = view,
        .root = template.checked_fn_root,
        .scheme_vars = view.templates.templateSchemeVars(template),
        .params = view.templates.evidenceParams(template),
        .params_start = template.evidence_params.start,
    };
}

/// A checked plan's recorded entries for a target's requirements, with the
/// module whose tables those entries index.
const EvidenceContract = struct {
    view: ModuleView,
    entries: []const static_dispatch.CheckedEvidence,
};

/// Evidence supplied when a selected method target becomes a specialization.
/// Checked entries remain producer-owned contracts; an evidence-dependent
/// call can instead carry the materialized contract from its enclosing
/// specialization. A compiler-generated edge derives from its live request.
const TargetEvidenceSource = union(enum) {
    derive,
    checked: EvidenceContract,
    materialized_contract: []const SpecEvidence,
};

/// The substitution an evidence node recorded for its target's scheme, or
/// null for a monomorphic target.
fn checkedTargetSubstitution(site_view: ModuleView, node: static_dispatch.EvidenceNode) ?CheckedTargetSubstitution {
    if (node.subst.len == 0) return null;
    const table = site_view.static_dispatch_plans;
    const start: usize = node.subst.start;
    const len: usize = node.subst.len;
    if (start > table.site_substitutions.len or len > table.site_substitutions.len - start) {
        Common.invariant("checked target substitution range was outside its checked module");
    }
    return .{ .view = site_view, .tys = table.site_substitutions[start .. start + len] };
}

/// A materialized contract already names the checked targets and their nested
/// contracts. Once its callable relations have been consumed, those edge-local
/// callable identities must not distinguish otherwise identical specializations.
/// Keep the immutable vector and targets unless removing an identity changes them.
fn normalizeMaterializedEvidence(
    arena: Allocator,
    contract: []const SpecEvidence,
) Allocator.Error![]const SpecEvidence {
    // Each entry's callable contracts normalize first; a contract vector is
    // a frame of its own, so contract nesting never becomes native call depth.
    const Frame = struct {
        contract: []const SpecEvidence,
        next: usize = 0,
        normalized: ?[]SpecEvidence = null,
    };
    // Shallow contract nesting keeps its frames in place, so an unchanged
    // vector allocates nothing.
    var frame_fallback_buffer: [8 * @sizeOf(Frame)]u8 align(@alignOf(usize)) = undefined;
    var frame_fallback = std.heap.BufferFirstAllocator.init(&frame_fallback_buffer, arena);
    const frame_allocator = frame_fallback.allocator();
    var frames = std.ArrayList(Frame).empty;
    defer frames.deinit(frame_allocator);
    try frames.append(frame_allocator, .{ .contract = contract });
    var delivered: ?[]const SpecEvidence = null;
    while (true) {
        const frame = &frames.items[frames.items.len - 1];
        if (frame.next == frame.contract.len and delivered == null) {
            const finished = frames.pop().?;
            const result = finished.normalized orelse finished.contract;
            if (frames.items.len == 0) return result;
            delivered = result;
            continue;
        }
        const entry = frame.contract[frame.next];
        const original_contracts = evidenceCallableContracts(entry);
        const contracts = delivered orelse if (original_contracts.len == 0) original_contracts else {
            try frames.append(frame_allocator, .{ .contract = original_contracts });
            continue;
        };
        delivered = null;
        frame.next += 1;
        const contracts_changed = contracts.ptr != original_contracts.ptr;
        var replacement = entry;
        switch (entry) {
            .target => |target| {
                if (target.instantiation == null and !contracts_changed) continue;
                const copy = try arena.create(SpecEvidenceTarget);
                copy.* = target.*;
                copy.instantiation = null;
                copy.callable_contracts = contracts;
                replacement = .{ .target = copy };
            },
            .structural, .from_callable => {
                if (!contracts_changed) continue;
                replacement = try withCallableContracts(arena, entry, contracts);
            },
            .from_scheme, .unreachable_value, .checked_error => continue,
        }
        if (frame.normalized == null) frame.normalized = try arena.dupe(SpecEvidence, frame.contract);
        frame.normalized.?[frame.next - 1] = replacement;
    }
}

fn substitutionsShareClasses(graph: *InstGraph, left: SpecSubstitution, right: SpecSubstitution) bool {
    if (left.len != right.len) return false;
    for (left, right) |left_slot, right_slot| {
        switch (left_slot) {
            .checked_error => if (right_slot != .checked_error) return false,
            .node => |left_node| switch (right_slot) {
                .checked_error => return false,
                .node => |right_node| if (!graph.sameClass(left_node, right_node)) return false,
            },
        }
    }
    return true;
}

/// The substitution and the evidence derived from it for one request edge.
const EdgeEvidence = struct {
    subst: SpecSubstitution,
    vector: []const SpecEvidence,
};

/// The evidence vectors in scope while lowering a body: the innermost
/// generalized callable's vector plus its lexical parents (nested local
/// functions see their own vector at depth 0 and enclosing callables' vectors
/// at higher depths, like compile-time captures).
const LexicalDispatchScope = union(enum) {
    root,
    generalized: check.CheckedIds.DispatchScopeId,
};

const EvidenceScope = struct {
    owner: names.ProcTemplate,
    lexical: LexicalDispatchScope,

    fn eql(a: EvidenceScope, b: EvidenceScope) bool {
        return names.procedureTemplateRefEql(a.owner, b.owner) and std.meta.eql(a.lexical, b.lexical);
    }
};

const EvidenceChain = struct {
    scope: EvidenceScope,
    /// Stored evidence is graph-free until a nested body creates its own
    /// instantiation context. It must remain graph-free across root requests.
    origin: enum { specialization, stored_function } = .specialization,
    vector: []const SpecEvidence = &.{},
    /// The scheme this frame's vector answers for, and the substitution the
    /// vector was derived from. A body lowered inside this frame forwards an
    /// requirement on a still-open cell to the frame entry that owns that
    /// cell. Restored compile-time functions carry their retained vector
    /// only.
    schema: ?SchemeRequirements = null,
    subst: SpecSubstitution = &.{},
    parent: ?*const EvidenceChain = null,

    fn atScope(self: *const EvidenceChain, scope: EvidenceScope) ?EvidenceChain {
        var chain: ?*const EvidenceChain = self;
        while (chain) |frame| : (chain = frame.parent) {
            if (EvidenceScope.eql(frame.scope, scope)) return frame.*;
        }
        return null;
    }

    fn at(self: *const EvidenceChain, ref: static_dispatch.EvidenceChainIndex) ?SpecEvidence {
        var chain: *const EvidenceChain = self;
        var depth = ref.depth;
        while (depth > 0) : (depth -= 1) {
            chain = chain.parent orelse return null;
        }
        if (ref.index >= chain.vector.len) return null;
        return chain.vector[ref.index];
    }
};

fn rootEvidence(owner: names.ProcTemplate, vector: []const SpecEvidence) EvidenceChain {
    return .{
        .scope = .{ .owner = owner, .lexical = .root },
        .vector = vector,
    };
}

/// The root frame of a template specialization: its requirement vector
/// together with the substitution and schema it was derived from.
fn rootEvidenceWithSubstitution(
    owner: names.ProcTemplate,
    schema: SchemeRequirements,
    edge: EdgeEvidence,
) EvidenceChain {
    return .{
        .scope = .{ .owner = owner, .lexical = .root },
        .vector = edge.vector,
        .schema = schema,
        .subst = edge.subst,
    };
}

fn enterEvidenceScope(
    builder: *Builder,
    evidence: EvidenceChain,
    scope_id: checked.DispatchScopeId,
    checked_expr: checked.CheckedExprId,
    edge: EdgeEvidence,
) Allocator.Error!EvidenceChain {
    const vector = edge.vector;
    const owner = evidence.scope.owner;
    const view = builder.moduleForDigest(names.procTemplateModuleDigest(owner));
    const raw_scope = @backingInt(scope_id);
    if (raw_scope >= view.templates.dispatch_scopes.len) {
        Common.invariant("local procedure evidence scope was outside the checked scope table");
    }
    const scope_record = view.templates.dispatch_scopes[raw_scope];
    if (scope_record.checked_expr != checked_expr) {
        Common.invariant("local procedure evidence scope did not own the checked local expression");
    }
    const params_start: usize = scope_record.evidence_params.start;
    const params_len: usize = scope_record.evidence_params.len;
    if (params_start > view.templates.evidence_params_pool.len or
        params_len > view.templates.evidence_params_pool.len - params_start)
    {
        Common.invariant("local procedure evidence scope requirements were outside the checked params pool");
    }
    if (vector.len != params_len) {
        Common.invariant("local procedure use did not supply its exact checked evidence vector");
    }
    const expected_parent: LexicalDispatchScope = if (scope_record.parent) |parent|
        .{ .generalized = parent }
    else
        .root;
    // A local use may come from a sibling scope. Its checked declaration
    // parent, not the use-site head, owns the enclosing evidence depths.
    const lexical_parent = evidence.atScope(.{
        .owner = owner,
        .lexical = expected_parent,
    }) orelse Common.invariant("local procedure evidence omitted its checked lexical parent");
    const scheme_vars = view.templates.scopeSchemeVars(&scope_record);
    if (edge.subst.len != scheme_vars.len) {
        Common.invariant("local procedure evidence substitution length differed from its scope's quantified variables");
    }
    const parent = try builder.evidence_arena.allocator().create(EvidenceChain);
    parent.* = lexical_parent;
    return .{
        .scope = .{ .owner = owner, .lexical = .{ .generalized = scope_id } },
        .vector = vector,
        .schema = .{
            .view = view,
            .root = scope_record.scheme_root,
            .scheme_vars = scheme_vars,
            .params = view.templates.evidence_params_pool[params_start .. params_start + params_len],
            .params_start = @intCast(params_start),
        },
        .subst = edge.subst,
        .parent = parent,
    };
}

fn relateFunctionRequestInterface(graph: *InstGraph, public_fn: NodeId, private_fn: NodeId) Allocator.Error!void {
    try relateRequestComponentAtWidth(graph, public_fn, private_fn, .exact);
}

/// Relate a fresh checked procedure-template instance to a caller request that the
/// checker formed through a construction-width relation. Ordinary structure
/// still unifies exactly; only explicit optional/defaulted record fields may
/// be absorbed by a closed row.
fn relateConstructionFunctionRequestInterface(graph: *InstGraph, checked_fn: NodeId, request_fn: NodeId) Allocator.Error!void {
    try relateRequestComponentAtWidth(graph, checked_fn, request_fn, .construction);
}

fn relateRequestComponent(graph: *InstGraph, left_node: NodeId, right_node: NodeId) Allocator.Error!void {
    try relateRequestComponentAtWidth(graph, left_node, right_node, .exact);
}

fn unifyRequestComponentAtWidth(
    graph: *InstGraph,
    left_node: NodeId,
    right_node: NodeId,
    row_width: solve.RowWidthRelation,
) Allocator.Error!void {
    switch (row_width) {
        .exact => try graph.unify(left_node, right_node),
        .construction => try graph.unifyConstruction(left_node, right_node),
    }
}

fn relateOpaqueRequestComponentAtWidth(
    graph: *InstGraph,
    public_node: NodeId,
    private_node: NodeId,
    row_width: solve.RowWidthRelation,
) Allocator.Error!void {
    switch (row_width) {
        .exact => try graph.relateOpaqueInterface(public_node, private_node),
        .construction => try graph.relateOpaqueConstructionInterface(public_node, private_node),
    }
}

fn relatePublicPrivateRequestComponentAtWidth(
    graph: *InstGraph,
    public_node: NodeId,
    private_node: NodeId,
    row_width: solve.RowWidthRelation,
) Allocator.Error!void {
    switch (row_width) {
        .exact => try graph.relateOpaqueInterface(public_node, private_node),
        .construction => {
            if (try graph.containsFinishedMono(public_node) or
                try graph.containsFinishedMono(private_node))
            {
                try graph.relateOpaqueConstructionInterface(public_node, private_node);
            } else {
                try graph.selectGeneratedPrivateConstructionRepresentation(public_node, private_node);
            }
        },
    }
}

/// Relate two request components at `row_width`. Matching private
/// containers relate their children before joining; each such container is
/// an explicit frame, so component depth never becomes native call depth.
fn relateRequestComponentAtWidth(
    graph: *InstGraph,
    root_left: NodeId,
    root_right: NodeId,
    row_width: solve.RowWidthRelation,
) Allocator.Error!void {
    const Op = union(enum) {
        pair: struct { left: NodeId, right: NodeId },
        /// Named containers match only when both have a backing or neither
        /// does; matching backings relate as a pair.
        named_backing: struct { left: ?NodeId, right: ?NodeId },
    };
    const Frame = struct {
        left: NodeId,
        right: NodeId,
        finish: RequestContainerJoin,
        ops_start: usize,
        next: usize,
    };
    var frames: std.ArrayListUnmanaged(Frame) = .empty;
    defer frames.deinit(graph.allocator);
    var ops: std.ArrayListUnmanaged(Op) = .empty;
    defer ops.deinit(graph.allocator);

    var pending_pair: ?[2]NodeId = .{ root_left, root_right };
    while (true) {
        if (pending_pair) |pair| {
            pending_pair = null;
            const left_node = pair[0];
            const right_node = pair[1];
            switch (try requestComponentRelation(graph, left_node, right_node)) {
                .unify => try unifyRequestComponentAtWidth(graph, left_node, right_node, row_width),
                .public_private => try relatePublicPrivateRequestComponentAtWidth(graph, left_node, right_node, row_width),
                .private_public => try relatePublicPrivateRequestComponentAtWidth(graph, right_node, left_node, row_width),
                .matching_containers => {
                    if (graph.sameClass(left_node, right_node)) {
                        // Already one component.
                    } else {
                        const ops_start = ops.items.len;
                        const finish = try appendMatchingRequestContainerOps(Op, graph, &ops, left_node, right_node, row_width);
                        if (finish) |how| {
                            try frames.append(graph.allocator, .{ .left = left_node, .right = right_node, .finish = how, .ops_start = ops_start, .next = ops_start });
                        } else {
                            ops.shrinkRetainingCapacity(ops_start);
                            try unifyRequestComponentAtWidth(graph, left_node, right_node, row_width);
                        }
                    }
                },
            }
        }
        if (frames.items.len == 0) return;

        const frame = &frames.items[frames.items.len - 1];
        if (frame.next < ops.items.len) {
            const op = ops.items[frame.next];
            frame.next += 1;
            switch (op) {
                .pair => |pair| pending_pair = .{ pair.left, pair.right },
                .named_backing => |backing| {
                    const matched = if (backing.left) |left_backing| blk: {
                        const right_backing = backing.right orelse break :blk false;
                        pending_pair = .{ left_backing, right_backing };
                        break :blk true;
                    } else backing.right == null;
                    if (!matched) {
                        // The named pair does not match after all.
                        const failed = frames.pop().?;
                        ops.shrinkRetainingCapacity(failed.ops_start);
                        try unifyRequestComponentAtWidth(graph, failed.left, failed.right, row_width);
                    }
                },
            }
            continue;
        }

        const done = frames.pop().?;
        ops.shrinkRetainingCapacity(done.ops_start);
        switch (done.finish) {
            .join => try graph.joinRelatedRequestContainer(done.left, done.right),
            .named => try graph.relateNamedInstances(done.left, done.right),
        }
    }
}

/// How two matching containers join once their children are related.
const RequestContainerJoin = enum { join, named };

/// How a request component pair relates.
fn requestComponentRelation(
    graph: *InstGraph,
    left_node: NodeId,
    right_node: NodeId,
) Allocator.Error!enum { unify, public_private, private_public, matching_containers } {
    const left_root_private = (try isGeneratedPrivateRootNode(graph, left_node));
    const right_root_private = (try isGeneratedPrivateRootNode(graph, right_node));
    if (left_root_private and right_root_private) return .unify;
    if (right_root_private) return .public_private;
    if (left_root_private) return .private_public;

    const left_private = try graph.containsGeneratedPrivate(left_node);
    const right_private = try graph.containsGeneratedPrivate(right_node);
    if (left_private and right_private) return .matching_containers;
    if (right_private) return .public_private;
    if (left_private) return .private_public;
    return .unify;
}

/// List the child pairs two matching containers relate before they join,
/// returning how they join; null when the containers do not match and the
/// pair unifies instead.
fn appendMatchingRequestContainerOps(
    comptime Op: type,
    graph: *InstGraph,
    ops: *std.ArrayListUnmanaged(Op),
    left_node: NodeId,
    right_node: NodeId,
    row_width: solve.RowWidthRelation,
) Allocator.Error!?RequestContainerJoin {
    const gpa = graph.allocator;
    const left_content = (try graph.content(left_node));
    const right_content = (try graph.content(right_node));
    switch (left_content) {
        .list => |left_elem| switch (right_content) {
            .list => |right_elem| {
                try ops.append(gpa, .{ .pair = .{ .left = left_elem, .right = right_elem } });
                return .join;
            },
            .redirect, .leaf, .unresolved, .primitive, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => {},
        },
        .box => |left_elem| switch (right_content) {
            .box => |right_elem| {
                try ops.append(gpa, .{ .pair = .{ .left = left_elem, .right = right_elem } });
                return .join;
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => {},
        },
        .tuple => |left_items| switch (right_content) {
            .tuple => |right_items| {
                if (left_items.len != right_items.len) {
                    Common.invariant("request component relation received tuples of different arity");
                }
                for (left_items, right_items) |left_item, right_item| {
                    try ops.append(gpa, .{ .pair = .{ .left = left_item, .right = right_item } });
                }
                return .join;
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => {},
        },
        .func => |left_fn| switch (right_content) {
            .func => |right_fn| {
                if (left_fn.args.len != right_fn.args.len) {
                    Common.invariant("request component relation received functions of different arity");
                }
                for (left_fn.args, right_fn.args) |left_arg, right_arg| {
                    try ops.append(gpa, .{ .pair = .{ .left = left_arg, .right = right_arg } });
                }
                try ops.append(gpa, .{ .pair = .{ .left = left_fn.ret, .right = right_fn.ret } });
                return .join;
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => {},
        },
        .tag_union => switch (right_content) {
            .tag_union => {
                try relateOpaqueRequestComponentAtWidth(graph, left_node, right_node, row_width);
                return .join;
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => {},
        },
        .record => switch (right_content) {
            .record => {
                try relateOpaqueRequestComponentAtWidth(graph, left_node, right_node, row_width);
                return .join;
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .empty_tag_union, .empty_record, .named, .erased, .zst => {},
        },
        .named => |left_named| switch (right_content) {
            .named => |right_named| {
                if (!sameNamedValueDefinition(left_named, right_named)) return null;
                for (left_named.args, right_named.args) |left_arg, right_arg| {
                    try ops.append(gpa, .{ .pair = .{ .left = left_arg, .right = right_arg } });
                }
                try ops.append(gpa, .{ .named_backing = .{
                    .left = if (left_named.backing) |backing| backing.node else null,
                    .right = if (right_named.backing) |backing| backing.node else null,
                } });
                return .named;
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => {},
        },
        .redirect, .leaf, .unresolved, .primitive, .empty_tag_union, .empty_record, .erased, .zst => {},
    }
    return null;
}

const DeferredConstructorPair = struct {
    checked_node: NodeId,
    request_node: NodeId,
};

/// Transfer only type-constructor evidence from a procedure's checked scheme
/// into an independent caller-owned request. Function arguments and returns,
/// record fields, tuple items, and tag payloads are traversal paths here: they
/// are not themselves related. Explicit named arguments and the element
/// arguments of List and Box are the only relation boundaries.
fn constrainDeferredTemplateTypeArguments(
    graph: *InstGraph,
    checked_fn_node: NodeId,
    request_fn_node: NodeId,
) Allocator.Error!void {
    var seen = std.AutoHashMap(DeferredConstructorPair, void).init(graph.allocator);
    defer seen.deinit();
    try constrainDeferredTemplateTypeArgumentsAt(graph, checked_fn_node, request_fn_node, &seen);
}

/// Backing node of a transparent alias wrapper. Nominal wrappers,
/// runtime-layout-only backings, and generated-private backings are
/// boundaries this traversal must not cross.
fn transparentAliasBacking(graph: *InstGraph, content: anytype) ?NodeId {
    switch (content) {
        .named => |named| {
            if (named.kind != .alias) return null;
            const backing = named.backing orelse return null;
            if (backing.use != .inspectable) return null;
            if (backing.authority == .generated_private) return null;
            return graph.rootNode(backing.node);
        },
        .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return null,
    }
}

/// One pending step of transferring type-constructor evidence.
const DeferredConstructorStep = union(enum) {
    at: DeferredConstructorPair,
    argument: DeferredConstructorPair,
    relate_named: DeferredConstructorPair,
    field_kind: struct { checked: InstField, request: InstField },
};

/// Run the transfer from an explicit continuation stack, in exactly the
/// order a direct descent would take its steps, so type depth never becomes
/// native call depth.
fn constrainDeferredTemplateTypeArgumentsAt(
    graph: *InstGraph,
    checked_node: NodeId,
    request_node: NodeId,
    seen: *std.AutoHashMap(DeferredConstructorPair, void),
) Allocator.Error!void {
    var pending: std.ArrayListUnmanaged(DeferredConstructorStep) = .empty;
    defer pending.deinit(graph.allocator);
    try pending.append(graph.allocator, .{ .at = .{ .checked_node = checked_node, .request_node = request_node } });
    while (pending.pop()) |step| {
        const start = pending.items.len;
        switch (step) {
            .at => |pair| try deferredTemplateTypeArgumentsStep(graph, pair.checked_node, pair.request_node, seen, &pending),
            .argument => |pair| {
                const checked_root = graph.rootNode(pair.checked_node);
                const request_root = graph.rootNode(pair.request_node);
                if (checked_root == request_root) continue;
                if ((try graph.content(checked_root)) == .unresolved) {
                    try relateRequestComponent(graph, checked_root, request_root);
                    continue;
                }
                try pending.append(graph.allocator, .{ .at = .{ .checked_node = checked_root, .request_node = request_root } });
            },
            .relate_named => |pair| try graph.relateNamedInstances(pair.checked_node, pair.request_node),
            .field_kind => |fields| graph.relateRecordFieldKind(fields.checked, fields.request),
        }
        std.mem.reverse(DeferredConstructorStep, pending.items[start..]);
    }
}

fn deferredTemplateTypeArgumentsStep(
    graph: *InstGraph,
    checked_node: NodeId,
    request_node: NodeId,
    seen: *std.AutoHashMap(DeferredConstructorPair, void),
    pending: *std.ArrayListUnmanaged(DeferredConstructorStep),
) Allocator.Error!void {
    const gpa = graph.allocator;
    const checked_root = graph.rootNode(checked_node);
    const request_root = graph.rootNode(request_node);
    if (checked_root == request_root) return;
    const entry = try seen.getOrPut(.{
        .checked_node = checked_root,
        .request_node = request_root,
    });
    if (entry.found_existing) return;

    const checked_content = (try graph.content(checked_root));
    const request_content = (try graph.content(request_root));

    // A transparent alias names its backing without adding structure, and
    // aliases cannot introduce phantom parameters, so every alias argument
    // occurs in the backing: descending to the backing when only one side is
    // alias-wrapped loses nothing and restores the congruent constructor pair.
    // Same-definition named pairs keep the direct argument relation below;
    // for nominal pairs that relation is also what pins phantom arguments,
    // which never occur in the backing.
    if (std.meta.activeTag(checked_content) != std.meta.activeTag(request_content)) {
        if (transparentAliasBacking(graph, checked_content)) |backing| {
            return try pending.append(gpa, .{ .at = .{ .checked_node = backing, .request_node = request_root } });
        }
        if (transparentAliasBacking(graph, request_content)) |backing| {
            return try pending.append(gpa, .{ .at = .{ .checked_node = checked_root, .request_node = backing } });
        }
    }
    switch (checked_content) {
        .unresolved => return,
        .list => |checked_elem| switch (request_content) {
            .list => |request_elem| try pending.append(gpa, .{ .argument = .{ .checked_node = checked_elem, .request_node = request_elem } }),
            .redirect, .leaf, .unresolved, .primitive, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return,
        },
        .box => |checked_elem| switch (request_content) {
            .box => |request_elem| try pending.append(gpa, .{ .argument = .{ .checked_node = checked_elem, .request_node = request_elem } }),
            .redirect, .leaf, .unresolved, .primitive, .list, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return,
        },
        .named => |checked_named| switch (request_content) {
            .named => |request_named| {
                if (!sameNamedValueDefinition(checked_named, request_named)) {
                    if (transparentAliasBacking(graph, checked_content)) |backing| {
                        return try pending.append(gpa, .{ .at = .{ .checked_node = backing, .request_node = request_root } });
                    }
                    if (transparentAliasBacking(graph, request_content)) |backing| {
                        return try pending.append(gpa, .{ .at = .{ .checked_node = checked_root, .request_node = backing } });
                    }
                    return;
                }
                for (checked_named.args, request_named.args) |checked_arg, request_arg| {
                    try pending.append(gpa, .{ .argument = .{ .checked_node = checked_arg, .request_node = request_arg } });
                }
                try pending.append(gpa, .{ .relate_named = .{ .checked_node = checked_root, .request_node = request_root } });
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return,
        },
        .func => |checked_fn| switch (request_content) {
            .func => |request_fn| {
                if (checked_fn.args.len != request_fn.args.len) {
                    Common.invariant("deferred procedure function traversal changed arity");
                }
                for (checked_fn.args, request_fn.args) |checked_arg, request_arg| {
                    try pending.append(gpa, .{ .at = .{ .checked_node = checked_arg, .request_node = request_arg } });
                }
                try pending.append(gpa, .{ .at = .{ .checked_node = checked_fn.ret, .request_node = request_fn.ret } });
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return,
        },
        .tuple => |checked_items| switch (request_content) {
            .tuple => |request_items| {
                if (checked_items.len != request_items.len) {
                    Common.invariant("deferred procedure tuple traversal changed arity");
                }
                for (checked_items, request_items) |checked_item, request_item| {
                    try pending.append(gpa, .{ .at = .{ .checked_node = checked_item, .request_node = request_item } });
                }
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return,
        },
        .record => |checked_record| switch (request_content) {
            .record => |request_record| {
                var request_index: std.AutoHashMapUnmanaged(names.RecordFieldNameId, usize) = .empty;
                defer request_index.deinit(graph.allocator);
                try request_index.ensureTotalCapacity(graph.allocator, @intCast(request_record.fields.len));
                for (request_record.fields, 0..) |request_field, index| {
                    request_index.putAssumeCapacity(request_field.name, index);
                }
                for (checked_record.fields) |checked_field| {
                    const index = request_index.get(checked_field.name) orelse continue;
                    const request_field = request_record.fields[index];
                    try pending.append(gpa, .{ .field_kind = .{ .checked = checked_field, .request = request_field } });
                    try pending.append(gpa, .{ .argument = .{
                        .checked_node = checked_field.value_ty orelse checked_field.ty,
                        .request_node = request_field.value_ty orelse request_field.ty,
                    } });
                    try pending.append(gpa, .{ .argument = .{ .checked_node = checked_field.ty, .request_node = request_field.ty } });
                }
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .empty_tag_union, .empty_record, .named, .erased, .zst => return,
        },
        .tag_union => |checked_union| switch (request_content) {
            .tag_union => |request_union| {
                // Sorted heads pair their shared labels in one merge pass.
                graph.sortTagHead(checked_root);
                graph.sortTagHead(request_root);
                var request_pos: usize = 0;
                for (checked_union.tags) |checked_tag| {
                    while (request_pos < request_union.tags.len and
                        graph.name_store.tagLabelTextLessThan(request_union.tags[request_pos].name, checked_tag.name))
                    {
                        request_pos += 1;
                    }
                    if (request_pos == request_union.tags.len) break;
                    const request_tag = request_union.tags[request_pos];
                    if (request_tag.name != checked_tag.name) continue;
                    if (checked_tag.payloads.len != request_tag.payloads.len) {
                        Common.invariant("deferred procedure tag traversal changed payload arity");
                    }
                    for (checked_tag.payloads, request_tag.payloads) |checked_payload, request_payload| {
                        try pending.append(gpa, .{ .at = .{ .checked_node = checked_payload, .request_node = request_payload } });
                    }
                }
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return,
        },
        .primitive, .empty_tag_union, .empty_record, .erased, .zst => {},
        .redirect, .leaf => unreachable,
    }
}

fn isGeneratedPrivateRootNode(graph: *InstGraph, node: NodeId) Allocator.Error!bool {
    return switch ((try graph.content(node))) {
        .named => |named| if (named.backing) |backing|
            backing.authority == .generated_private
        else
            false,
        .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => false,
    };
}

/// Choose producer-authored generated-private evidence for a live draft result
/// while keeping ordinary graph unification unable to cross the public/private
/// boundary. The directed selection capability rejects imported Monotypes.
fn selectRequestRepresentation(graph: *InstGraph, declared_node: NodeId, produced_node: NodeId) Allocator.Error!void {
    const declared_private = try graph.containsGeneratedPrivate(declared_node);
    const produced_private = try graph.containsGeneratedPrivate(produced_node);
    if (declared_private != produced_private) {
        const public_node = if (declared_private) produced_node else declared_node;
        const private_node = if (declared_private) declared_node else produced_node;
        if (try graph.containsFinishedMono(public_node) or try graph.containsFinishedMono(private_node)) {
            // The finished request remains an immutable interface snapshot;
            // the expression and its enclosing producer boundary carry the
            // distinct private result representation.
            try graph.relateOpaqueInterface(public_node, private_node);
        } else {
            try graph.selectGeneratedPrivateRepresentation(public_node, private_node);
        }
    } else {
        try relateRequestComponent(graph, declared_node, produced_node);
    }
}

/// A procedure template's checked result row, once it is known closed.
const ClosedResultRow = struct {
    /// The checked row itself: the function result's own row, or the error
    /// argument row of a `Builtin.Try` result.
    row: checked.CheckedTypeId,
    /// Whether the row sits inside a `Builtin.Try` result, so the adapter
    /// unwraps and re-wraps through the checker-recorded capability.
    behind_try: bool,
};

/// Whether a checked tag row is closed for result-row widening. This is
/// `CheckedTypePayload.variableSealsToRowDefault`, the same rule the checker's
/// `checkedResultRowIsClosed` uses to decide whether to record the `Try`
/// capability, so the two cannot drift. A rigid tail is parametric—the
/// caller supplies the row—and is therefore not closed.
fn checkedResultRowIsClosed(view: ModuleView, root: checked.CheckedTypeId) bool {
    var current = root;
    var remaining = view.types.payloadCount();
    while (remaining > 0) : (remaining -= 1) {
        const payload = checkedPayload(view, current);
        switch (payload) {
            .alias => |alias| current = alias.backing,
            .tag_union => |tag_union| current = tag_union.ext,
            .empty_tag_union => return true,
            .flex, .rigid => |variable| return payload.variableSealsToRowDefault() and
                variable.row_default == .empty_tag_union,
            .pending, .err, .record, .tuple, .nominal, .function, .empty_record => return false,
        }
    }
    Common.invariant("checked result row extension chain was cyclic");
}

/// The template's checked result row when it is closed, so a request at a
/// row that includes it is served by a generated widening adapter (design.md
/// "Result-Row Widening Adapter"). Mirrors the checker's
/// `checkedRootHasClosedResultRow`, which gates recording the `Try`
/// capability this adapter consumes.
fn closedResultRowOrNull(view: ModuleView, checked_fn_root: checked.CheckedTypeId) ?ClosedResultRow {
    const function = switch (resolvedPayload(view, checked_fn_root).payload) {
        .function => |function| function,
        .pending, .err, .flex, .rigid, .alias, .record, .tuple, .nominal, .empty_record, .tag_union, .empty_tag_union => return null,
    };
    const ret = resolvedPayload(view, function.ret);
    switch (ret.payload) {
        .nominal => |nominal| {
            if (nominal.builtin != .try_) return null;
            if (nominal.args.len != 2) {
                Common.invariant("Builtin.Try checked type did not have exactly two type arguments");
            }
            if (!checkedResultRowIsClosed(view, nominal.args[1])) return null;
            return .{ .row = nominal.args[1], .behind_try = true };
        },
        .tag_union, .empty_tag_union => {
            if (!checkedResultRowIsClosed(view, ret.root)) return null;
            return .{ .row = ret.root, .behind_try = false };
        },
        .pending, .err, .flex, .rigid, .alias, .record, .tuple, .function, .empty_record => return null,
    }
}

/// Number of explicit labels a closed checked row lists. The declared-row
/// guard in `resultRowWideningAdapterOrNull` compares this against the lowered
/// declared row.
fn checkedClosedRowLabelCount(view: ModuleView, root: checked.CheckedTypeId) usize {
    var count: usize = 0;
    var current = root;
    var remaining = view.types.payloadCount();
    while (remaining > 0) : (remaining -= 1) {
        switch (checkedPayload(view, current)) {
            .alias => |alias| current = alias.backing,
            .tag_union => |tag_union| {
                count += tag_union.tags.len;
                current = tag_union.ext;
            },
            .empty_tag_union, .flex, .rigid => return count,
            .pending, .err, .record, .tuple, .nominal, .function, .empty_record => Common.invariant("closed result row chain left its row"),
        }
    }
    Common.invariant("checked result row extension chain was cyclic");
}

const HostedTryAdapterCapability = struct {
    def: Type.TypeDef,
    ok_tag: names.TagNameId,
    err_tag: names.TagNameId,
    ok_type_arg_index: usize,
    err_type_arg_index: usize,
};

const GraphHostedTryInfo = struct {
    ok: NodeId,
    err: NodeId,
};

const GraphHostedTryWidening = struct {
    public_try: GraphHostedTryInfo,
    request_try: GraphHostedTryInfo,
    public_err: []const InstTag,
    request_err: []const InstTag,
};

fn graphTagByName(
    tags: []const InstTag,
    name: names.TagNameId,
) ?InstTag {
    for (tags) |tag| {
        if (tag.name == name) return tag;
    }
    return null;
}

/// Graph-side counterpart of `Builder.hostedTryNamedOrNull`: cross transparent
/// alias layers before matching the capability's def.
///
/// This crossing is symmetry with the Monotype side rather than a path a
/// fixture reaches. `test/fx-open/hosted_alias_try_question.roc` declares its
/// hosted result through an alias and still arrives here as the bare `Try`
/// nominal: instantiating the checked root into the graph resolves the alias,
/// while `lowerType` keeps it. It is kept so the two sides cannot answer
/// differently if that ever stops holding.
fn graphHostedTryInfoOrNull(
    graph: *InstGraph,
    capability: HostedTryAdapterCapability,
    node: NodeId,
) Allocator.Error!?GraphHostedTryInfo {
    var current = node;
    // Bounded by the graph's node count, the bound `InstGraph`'s own chain
    // walks use. A one-step self-check would still spin on a backing cycle
    // through two or more nodes, and a hang is the worst outcome for a guard
    // whose only job is termination. `compilerBug`, not `invariant`: an
    // `unreachable` outside Debug turns the hang into undefined behavior
    // instead of a diagnostic.
    var remaining = graph.nodes.items.len;
    const named = while (remaining > 0) : (remaining -= 1) {
        const probe = switch ((try graph.content(current))) {
            .named => |probe| probe,
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return null,
        };
        if (sameTypeDef(probe.def, capability.def)) break probe;
        if (probe.kind != .alias) return null;
        const backing = probe.backing orelse return null;
        current = backing.node;
    } else Common.compilerBug("transparent alias backing chain was cyclic");
    if (capability.ok_type_arg_index >= named.args.len or
        capability.err_type_arg_index >= named.args.len)
    {
        Common.invariant("hosted Try capability referenced a missing type argument");
    }
    return .{
        .ok = named.args[capability.ok_type_arg_index],
        .err = named.args[capability.err_type_arg_index],
    };
}

fn graphHostedTryWideningOrNull(
    graph: *InstGraph,
    capability: HostedTryAdapterCapability,
    public_ret: NodeId,
    request_ret: NodeId,
) Allocator.Error!?GraphHostedTryWidening {
    const public_try = (try graphHostedTryInfoOrNull(graph, capability, public_ret)) orelse return null;
    const request_try = (try graphHostedTryInfoOrNull(graph, capability, request_ret)) orelse return null;
    const public_err = (try graph.tagRowNodesOrNull(public_try.err)) orelse return null;
    const request_err = (try graph.tagRowNodesOrNull(request_try.err)) orelse return null;

    // A declared label the request dropped, or a payload arity it changed,
    // would make the adapter re-tag into a layout the caller does not read.
    if (request_err.tags.len < public_err.tags.len) {
        Common.compilerBug("hosted Try request removed a declared error label");
    }
    for (public_err.tags) |public_tag| {
        const request_tag = graphTagByName(request_err.tags, public_tag.name) orelse
            Common.compilerBug("hosted Try request removed a declared error label");
        if (public_tag.payloads.len != request_tag.payloads.len) {
            Common.compilerBug("hosted Try request changed a declared error payload arity");
        }
    }
    return .{
        .public_try = public_try,
        .request_try = request_try,
        .public_err = public_err.tags,
        .request_err = request_err.tags,
    };
}

/// Relate a hosted request whose `Try` result has additional error labels.
/// Declared labels and every non-row component remain exact graph relations;
/// only the request's extra error labels stay outside the checked public row.
fn relateHostedTryWidening(
    graph: *InstGraph,
    capability: HostedTryAdapterCapability,
    public_fn: NodeId,
    request_fn: NodeId,
) Allocator.Error!bool {
    const public = try graph.functionNodes(public_fn);
    const request = try graph.functionNodes(request_fn);
    if (public.args.len != request.args.len) {
        Common.invariant("hosted function request changed arity from its checked interface");
    }
    const widening = try graphHostedTryWideningOrNull(graph, capability, public.ret, request.ret) orelse return false;
    if (widening.request_err.len == widening.public_err.len) return false;

    for (public.args, request.args) |public_arg, request_arg| {
        try relateRequestComponent(graph, public_arg, request_arg);
    }
    try relateRequestComponent(graph, widening.public_try.ok, widening.request_try.ok);
    for (widening.public_err) |public_tag| {
        const request_tag = graphTagByName(widening.request_err, public_tag.name) orelse unreachable;
        for (public_tag.payloads, request_tag.payloads) |public_payload, request_payload| {
            try relateRequestComponent(graph, public_payload, request_payload);
        }
    }
    return true;
}

fn hostedTryWideningRequestHasAdditionalErrors(
    graph: *InstGraph,
    capability: HostedTryAdapterCapability,
    public_fn: NodeId,
    request_ret: NodeId,
) Allocator.Error!bool {
    const public = try graph.functionNodes(public_fn);
    const widening = try graphHostedTryWideningOrNull(graph, capability, public.ret, request_ret) orelse return false;
    return widening.request_err.len > widening.public_err.len;
}

/// Returns whether the hosted `Try` widening claimed the request, which is the
/// answer hosted template completion consumes: the adapter keeps the extern
/// boundary at the declared host ABI and re-tags into the requested error row.
fn relateHostedFunctionRequestInterface(
    graph: *InstGraph,
    capability: ?HostedTryAdapterCapability,
    public_fn: NodeId,
    request_fn: NodeId,
) Allocator.Error!bool {
    if (capability) |hosted_try| {
        if (try relateHostedTryWidening(graph, hosted_try, public_fn, request_fn)) return true;
    }
    try relateFunctionRequestInterface(graph, public_fn, request_fn);
    return false;
}

/// A public/request node pair this relation still owes a graph relation.
const RequestNodePair = struct {
    public: NodeId,
    request: NodeId,
};

/// The components of the one result cell a request widened.
const ResultRowWidening = struct {
    /// Result components that stay exact graph relations: the `Try` result's
    /// remaining type arguments.
    exact: []const RequestNodePair,
    /// The single row the request widened. Its shared labels' payload cells
    /// relate exactly and the two extensions stay unrelated, so the request's
    /// extra labels remain outside the template's closed row.
    widened: RequestNodePair,
};

/// Type-argument index of `Builtin.Try`'s error row. `closedResultRowOrNull`
/// names `args[1]` as the closed row and the checker's
/// `hostedTryAdapterCapabilityForCheckedRoot` records the same index, so this
/// relation and the adapter open one and the same cell.
const try_error_type_arg_index: usize = 1;

/// Whether a node is directly function-shaped.
fn isFunctionNode(graph: *InstGraph, node: NodeId) Allocator.Error!bool {
    return switch ((try graph.content(node))) {
        .func => true,
        .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => false,
    };
}

/// Whether a node is a bare tag row. A nominal or opaque named type is not:
/// reading a row through its backing would inspect a representation this
/// relation has no business seeing, and a runtime-layout-only backing rejects
/// the read outright.
fn isBareTagRowNode(graph: *InstGraph, node: NodeId) Allocator.Error!bool {
    return switch ((try graph.content(node))) {
        .tag_union, .empty_tag_union => true,
        .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_record, .named, .erased, .zst => false,
    };
}

/// Whether `request_row` lists every label of the closed `public_row` at the
/// same payload arity, plus at least one more. Nothing is related here.
fn requestRowIncludesClosedRow(
    graph: *InstGraph,
    public_row: NodeId,
    request_row: NodeId,
) Allocator.Error!bool {
    if (!(try isBareTagRowNode(graph, public_row)) or !(try isBareTagRowNode(graph, request_row))) return false;
    const public = (try graph.tagRowNodesOrNull(public_row)) orelse return false;
    const request = (try graph.tagRowNodesOrNull(request_row)) orelse return false;
    if (request.tags.len <= public.tags.len) return false;
    if (!try graph.tagRowIsClosed(public_row)) return false;
    for (public.tags) |public_tag| {
        const request_tag = graphTagByName(request.tags, public_tag.name) orelse return false;
        if (public_tag.payloads.len != request_tag.payloads.len) return false;
    }
    return true;
}

/// Recognize the one result cell the adapter can re-tag. `declared_row` is the
/// checker's own answer for this template, so the cell opened here is exactly
/// the cell `resultRowWideningAdapterSourceType` builds a narrowed source type
/// for: a `Try` result's error argument, or the function's own result row. The
/// adapter-reachable set is exactly those two. Every other component—a
/// `Try`'s `Ok` argument (`hostedTryReturnInjectionExpr` rejects an `Ok` type
/// change outright), an alias's type arguments, a nested row—relates exactly,
/// so a widening there meets the ordinary closed-row rejection instead of
/// silently passing a request no adapter will serve.
fn resultRowWideningOrNull(
    graph: *InstGraph,
    declared_row: ClosedResultRow,
    public_ret: NodeId,
    request_ret: NodeId,
) Allocator.Error!?ResultRowWidening {
    if (!declared_row.behind_try) {
        if (!try requestRowIncludesClosedRow(graph, public_ret, request_ret)) return null;
        return .{ .exact = &.{}, .widened = .{ .public = public_ret, .request = request_ret } };
    }
    const public_named = switch ((try graph.content(public_ret))) {
        .named => |named| named,
        .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return null,
    };
    const request_named = switch ((try graph.content(request_ret))) {
        .named => |named| named,
        .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return null,
    };
    // Only the `Try` nominal itself. An alias node's type arguments are not
    // the `Try` arguments the adapter reads, and crossing to its backing row
    // would inspect a representation this relation has no business seeing.
    if (public_named.kind != .nominal or request_named.kind != .nominal) return null;
    if (!sameTypeDef(public_named.def, request_named.def) or
        public_named.args.len != request_named.args.len or
        public_named.args.len <= try_error_type_arg_index)
    {
        return null;
    }
    const public_err = public_named.args[try_error_type_arg_index];
    const request_err = request_named.args[try_error_type_arg_index];
    if (!try requestRowIncludesClosedRow(graph, public_err, request_err)) return null;
    const exact = try graph.arena().alloc(RequestNodePair, public_named.args.len - 1);
    var exact_index: usize = 0;
    for (public_named.args, request_named.args, 0..) |public_arg, request_arg, index| {
        if (index == try_error_type_arg_index) continue;
        exact[exact_index] = .{ .public = public_arg, .request = request_arg };
        exact_index += 1;
    }
    // The nominal's backing repeats the same rows, so relating it would unify
    // them; it stays outside this relation exactly as the hosted `Try`
    // widening leaves it.
    return .{ .exact = exact, .widened = .{ .public = public_err, .request = request_err } };
}

/// Relate the labels a widened row shares with the template's closed row. The
/// two row nodes and their extensions stay unrelated, which is exactly what
/// keeps the request's extra labels outside the closed row.
fn relateIncludedRowPayloads(
    graph: *InstGraph,
    public_row: NodeId,
    request_row: NodeId,
) Allocator.Error!void {
    // Each guard here stands between the adapter and a wrong tag layout, so
    // all of them stop the build in every mode.
    if (!(try isBareTagRowNode(graph, public_row)) or !(try isBareTagRowNode(graph, request_row))) {
        Common.compilerBug("result-row widening related a non-tag-union row");
    }
    const public = (try graph.tagRowNodesOrNull(public_row)) orelse
        Common.compilerBug("result-row widening related a non-tag-union row");
    const request = (try graph.tagRowNodesOrNull(request_row)) orelse
        Common.compilerBug("result-row widening related a non-tag-union row");
    for (public.tags) |public_tag| {
        const request_tag = graphTagByName(request.tags, public_tag.name) orelse
            Common.compilerBug("result-row widening request removed a declared label");
        if (public_tag.payloads.len != request_tag.payloads.len) {
            Common.compilerBug("result-row widening request changed a declared payload arity");
        }
        for (public_tag.payloads, request_tag.payloads) |public_payload, request_payload| {
            try relateRequestComponent(graph, public_payload, request_payload);
        }
    }
}

/// Recognize a request whose result row includes the template's closed
/// checked row (design.md "Result-Row Widening Adapter"). Nothing is related
/// here, so a site that cannot reach an adapter can ask the question and then
/// decline without having already taken the rows apart.
fn resultRowWideningRequestOrNull(
    graph: *InstGraph,
    declared_row: ClosedResultRow,
    public_fn: NodeId,
    request_fn: NodeId,
) Allocator.Error!?ResultRowWidening {
    if (graph.sameClass(public_fn, request_fn)) return null;
    // Only a directly function-shaped pair is inspected here. Reading a
    // function interface through a named backing is the caller's ordinary
    // relation's business, not this one's.
    if (!(try isFunctionNode(graph, public_fn)) or !(try isFunctionNode(graph, request_fn))) return null;
    const public = try graph.functionNodes(public_fn);
    const request = try graph.functionNodes(request_fn);
    if (public.args.len != request.args.len) {
        Common.compilerBug("result-row widening request changed arity from its checked interface");
    }
    return try resultRowWideningOrNull(graph, declared_row, public.ret, request.ret);
}

/// Relate a recognized result-row widening. Arguments and every non-row
/// component stay exact graph relations; only the request's extra result
/// labels stay outside the template's row, so the request survives to template
/// completion where the widening adapter is generated.
fn applyResultRowWidening(
    graph: *InstGraph,
    widening: ResultRowWidening,
    public_fn: NodeId,
    request_fn: NodeId,
) Allocator.Error!void {
    const public = try graph.functionNodes(public_fn);
    const request = try graph.functionNodes(request_fn);
    for (public.args, request.args) |public_arg, request_arg| {
        try relateRequestComponent(graph, public_arg, request_arg);
    }
    for (widening.exact) |pair| {
        try relateRequestComponent(graph, pair.public, pair.request);
    }
    try relateIncludedRowPayloads(graph, widening.widened.public, widening.widened.request);
}

/// Whether the site asking for a result-row widening relation can reach the
/// generated adapter that serves it.
///
/// design.md "Result-Row Widening Adapter": because the relation deliberately
/// declines to unify the two rows, it must fail CLOSED. A request related this
/// way that then does NOT reach an adapter leaves a callee producing one tag
/// layout and a caller reading another—a wrong value rather than a crash. A
/// site that cannot reach `completeTemplateReservation` therefore states
/// `.no_adapter` and relates exactly instead, so the widening meets the
/// ordinary `unifyTagRows` rejection.
const AdapterReachability = enum {
    /// The request is served by a procedure template specialization, whose
    /// completion mints the adapter for a recorded widening.
    adapter_reachable,
    /// No `completeTemplateReservation` runs for this request: a `.local_proc`
    /// dispatch target has no `checked_fn_root` and no template reservation, and
    /// a caller-owned specialization lowers its body inline at the declared
    /// interface.
    no_adapter,
};

/// Whether a resolved dispatch target's callee can reach a widening adapter.
/// Only a procedure template is specialized through
/// `completeTemplateReservation`; a lambda-bound local procedure has no
/// `checked_fn_root` and no template reservation, and a structural registry
/// result has no callable body at all, so neither can ever be served by one.
fn dispatchTargetAdapterReachability(target: static_dispatch.MethodTarget) AdapterReachability {
    return switch (target.kind) {
        .procedure => .adapter_reachable,
        .local_proc, .structural => .no_adapter,
    };
}

/// `relateFunctionRequestInterface` for a template whose checked result row
/// may be closed: when the request's result row includes it, the two relate
/// component-wise without unifying the rows. Returns whether the relation
/// declined to unify, which is exactly the answer template completion consumes.
fn relateClosedResultRowRequestInterface(
    graph: *InstGraph,
    view: ModuleView,
    checked_fn_ty: checked.CheckedTypeId,
    public_fn: NodeId,
    request_fn: NodeId,
    reachability: AdapterReachability,
) Allocator.Error!bool {
    const declared_row = closedResultRowOrNull(view, checked_fn_ty) orelse return false;
    const widening = (try resultRowWideningRequestOrNull(graph, declared_row, public_fn, request_fn)) orelse
        return false;
    switch (reachability) {
        .adapter_reachable => {},
        .no_adapter => return false,
    }
    try applyResultRowWidening(graph, widening, public_fn, request_fn);
    return true;
}

/// Rendered length `hostedExternAbiViolationMessage` never exceeds.
const hosted_extern_abi_message_max = 512;

/// Longest hosted symbol string the violation message reproduces in full.
const hosted_extern_abi_message_symbol_max = 128;

/// Render the report `requireHostedExternAtDeclaredAbi` aborts with. The symbol
/// string is the identity of the extern the host linked against, so it leads;
/// the two type digests then say which of the two types the boundary took.
fn hostedExternAbiViolationMessage(
    buf: []u8,
    symbol_text: []const u8,
    declared_digest: names.TypeDigest,
    emitted_digest: names.TypeDigest,
) []const u8 {
    const symbol = symbol_text[0..@min(symbol_text.len, hosted_extern_abi_message_symbol_max)];
    return std.fmt.bufPrint(
        buf,
        "hosted extern \"{s}\" was specialized at type {s} instead of the type {s} its host ABI declares",
        .{
            symbol,
            std.fmt.bytesToHex(emitted_digest.bytes[0..8].*, .lower),
            std.fmt.bytesToHex(declared_digest.bytes[0..8].*, .lower),
        },
    ) catch "a hosted extern was specialized at a type other than the one its host ABI declares";
}

fn relateCheckedNodeToMono(graph: *InstGraph, checked_node: NodeId, mono_node: NodeId) Allocator.Error!void {
    _ = try checkedMonoRequestNode(graph, checked_node, mono_node, .exact);
}

/// Relate a checker-public node to an explicit Monotype request node. The
/// returned node is the one specialization identity must consume: ordinary
/// Monotypes join the checked class, while generated-private evidence remains
/// a distinct request node related recursively to the public interface.
fn checkedMonoRequestNode(
    graph: *InstGraph,
    checked_node: NodeId,
    mono_node: NodeId,
    row_width: solve.RowWidthRelation,
) Allocator.Error!NodeId {
    if (try graph.containsGeneratedPrivate(mono_node)) {
        try relateRequestComponentAtWidth(graph, checked_node, mono_node, row_width);
        return mono_node;
    }
    var seen = std.AutoHashMap(CheckedMonoRequestPair, void).init(graph.allocator);
    defer seen.deinit();
    try relateCheckedMonoRequestNodeAt(graph, checked_node, mono_node, row_width, &seen);
    return checked_node;
}

const CheckedMonoRequestPair = struct {
    checked: NodeId,
    request: NodeId,
};

/// One step of relating a checked node to a request node, in the order a
/// direct walk takes it.
const CheckedMonoRequestOp = union(enum) {
    relate: CheckedMonoRequestPair,
    field_kind: struct { checked: InstField, request: InstField },
    join_container: CheckedMonoRequestPair,
    named_instances: CheckedMonoRequestPair,
    unify: CheckedMonoRequestPair,
};

/// A related pair whose steps are `ops[ops_start..ops_end]`. The pair stays
/// in `seen` until its steps finish, so a cycle through it relates once.
const CheckedMonoRequestFrame = struct {
    pair: ?CheckedMonoRequestPair,
    ops_start: usize,
    ops_end: usize,
    next: usize,
};

fn relateCheckedMonoRequestNodeAt(
    graph: *InstGraph,
    checked_node: NodeId,
    request_node: NodeId,
    row_width: solve.RowWidthRelation,
    seen: *std.AutoHashMap(CheckedMonoRequestPair, void),
) Allocator.Error!void {
    const allocator = graph.allocator;
    var ops = std.ArrayList(CheckedMonoRequestOp).empty;
    defer ops.deinit(allocator);
    var frames = std.ArrayList(CheckedMonoRequestFrame).empty;
    defer {
        for (frames.items) |frame| if (frame.pair) |pair| {
            _ = seen.remove(pair);
        };
        frames.deinit(allocator);
    }
    try beginCheckedMonoRequestPair(graph, checked_node, request_node, row_width, false, seen, &ops, &frames);
    while (frames.items.len > 0) {
        const top = frames.items.len - 1;
        const frame = &frames.items[top];
        if (frame.next == frame.ops_end) {
            const finished = frames.pop().?;
            if (finished.pair) |pair| _ = seen.remove(pair);
            ops.shrinkRetainingCapacity(finished.ops_start);
            continue;
        }
        const op = ops.items[frame.next];
        frame.next += 1;
        switch (op) {
            .relate => |pair| try beginCheckedMonoRequestPair(graph, pair.checked, pair.request, row_width, true, seen, &ops, &frames),
            .field_kind => |fields| graph.relateRecordFieldKind(fields.checked, fields.request),
            .join_container => |pair| try graph.joinRelatedRequestContainer(pair.checked, pair.request),
            .named_instances => |pair| try graph.relateNamedInstances(pair.checked, pair.request),
            .unify => |pair| switch (row_width) {
                .exact => try graph.unify(pair.checked, pair.request),
                .construction => try graph.unifyConstruction(pair.checked, pair.request),
            },
        }
    }
}

/// Relate a pair at once when that needs no component, and otherwise push
/// a frame listing its components and the steps between and after them.
fn beginCheckedMonoRequestPair(
    graph: *InstGraph,
    checked_node: NodeId,
    request_node: NodeId,
    row_width: solve.RowWidthRelation,
    /// Whether these are components of a pair this walk already found
    /// public. Every step of the walk relates two public classes, which
    /// merges only classes already reachable from them, so a component of a
    /// public pair stays public for the rest of the walk.
    enclosing_public: bool,
    seen: *std.AutoHashMap(CheckedMonoRequestPair, void),
    ops: *std.ArrayList(CheckedMonoRequestOp),
    frames: *std.ArrayList(CheckedMonoRequestFrame),
) Allocator.Error!void {
    const allocator = graph.allocator;
    const checked_root = graph.rootNode(checked_node);
    const request_root = graph.rootNode(request_node);
    if (checked_root == request_root) return;

    if (!enclosing_public) {
        if (try graph.containsGeneratedPrivate(checked_root) or
            try graph.containsGeneratedPrivate(request_root))
        {
            try relateRequestComponentAtWidth(graph, checked_root, request_root, row_width);
            return;
        }
    }

    // Two unread leaves of one type relate without being read.
    if (graph.leafType(checked_root)) |checked_leaf| if (graph.leafType(request_root)) |request_leaf| if (checked_leaf == request_leaf) {
        try unifyRequestComponentAtWidth(graph, checked_root, request_root, row_width);
        return;
    };

    const roots: CheckedMonoRequestPair = .{ .checked = checked_root, .request = request_root };
    const entry = try seen.getOrPut(roots);
    if (entry.found_existing) return;
    try frames.ensureUnusedCapacity(allocator, 1);
    const ops_start = ops.items.len;
    errdefer {
        ops.shrinkRetainingCapacity(ops_start);
        _ = seen.remove(roots);
    }

    const checked_content = (try graph.content(checked_root));
    const request_content = (try graph.content(request_root));
    const structural = structural: switch (checked_content) {
        .named => |checked_named| switch (request_content) {
            .named => |request_named| {
                if (!sameNamedValueDefinition(checked_named, request_named)) break :structural false;
                // A declaration's arguments are components of the value the
                // same way a record's fields are. Relating only the backing
                // reaches every argument the backing mentions, so this
                // relation exists for the phantom arguments: the ones the
                // backing never mentions.
                for (checked_named.args, request_named.args) |checked_arg, request_arg| {
                    try ops.append(allocator, .{ .relate = .{ .checked = checked_arg, .request = request_arg } });
                }
                const checked_backing = checked_named.backing orelse {
                    try ops.append(allocator, .{ .unify = roots });
                    break :structural true;
                };
                const request_backing = request_named.backing orelse {
                    try ops.append(allocator, .{ .unify = roots });
                    break :structural true;
                };
                try ops.append(allocator, .{ .relate = .{ .checked = checked_backing.node, .request = request_backing.node } });
                try ops.append(allocator, .{ .named_instances = roots });
                break :structural true;
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => break :structural false,
        },
        .list => |checked_elem| switch (request_content) {
            .list => |request_elem| {
                try ops.append(allocator, .{ .relate = .{ .checked = checked_elem, .request = request_elem } });
                try ops.append(allocator, .{ .join_container = roots });
                break :structural true;
            },
            .redirect, .leaf, .unresolved, .primitive, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => break :structural false,
        },
        .box => |checked_elem| switch (request_content) {
            .box => |request_elem| {
                try ops.append(allocator, .{ .relate = .{ .checked = checked_elem, .request = request_elem } });
                try ops.append(allocator, .{ .join_container = roots });
                break :structural true;
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => break :structural false,
        },
        .tuple => |checked_items| switch (request_content) {
            .tuple => |request_items| {
                if (checked_items.len != request_items.len) {
                    Common.invariant("checked Monotype request related tuples of different arity");
                }
                for (checked_items, request_items) |checked_item, request_item| {
                    try ops.append(allocator, .{ .relate = .{ .checked = checked_item, .request = request_item } });
                }
                try ops.append(allocator, .{ .join_container = roots });
                break :structural true;
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => break :structural false,
        },
        .func => |checked_fn| switch (request_content) {
            .func => |request_fn| {
                if (checked_fn.args.len != request_fn.args.len) {
                    Common.invariant("checked Monotype request related functions of different arity");
                }
                for (checked_fn.args, request_fn.args) |checked_arg, request_arg| {
                    try ops.append(allocator, .{ .relate = .{ .checked = checked_arg, .request = request_arg } });
                }
                try ops.append(allocator, .{ .relate = .{ .checked = checked_fn.ret, .request = request_fn.ret } });
                try ops.append(allocator, .{ .join_container = roots });
                break :structural true;
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => break :structural false,
        },
        .record => |checked_row| switch (request_content) {
            .record => |request_row| {
                if (checked_row.fields.len != request_row.fields.len) break :structural false;
                for (checked_row.fields, request_row.fields) |checked_field, request_field| {
                    if (checked_field.name != request_field.name) break :structural false;
                }
                for (checked_row.fields, request_row.fields) |checked_field, request_field| {
                    try ops.append(allocator, .{ .field_kind = .{ .checked = checked_field, .request = request_field } });
                    try ops.append(allocator, .{ .relate = .{
                        .checked = checked_field.value_ty orelse checked_field.ty,
                        .request = request_field.value_ty orelse request_field.ty,
                    } });
                    try ops.append(allocator, .{ .relate = .{ .checked = checked_field.ty, .request = request_field.ty } });
                }
                try ops.append(allocator, .{ .relate = .{ .checked = checked_row.ext, .request = request_row.ext } });
                try ops.append(allocator, .{ .join_container = roots });
                break :structural true;
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .empty_tag_union, .empty_record, .named, .erased, .zst => break :structural false,
        },
        .tag_union => switch (request_content) {
            .tag_union => {
                // Earlier components of this request can instantiate an
                // extension with a tag already present in the head. Compare
                // complete normalized rows before relating their residuals.
                try graph.normalizeTagRow(checked_root);
                try graph.normalizeTagRow(request_root);
                const checked_row = (try graph.content(checked_root)).tag_union;
                const request_row = (try graph.content(request_root)).tag_union;
                if (checked_row.tags.len != request_row.tags.len) break :structural false;
                for (checked_row.tags, request_row.tags) |checked_tag, request_tag| {
                    if (checked_tag.name != request_tag.name or checked_tag.payloads.len != request_tag.payloads.len) break :structural false;
                }
                for (checked_row.tags, request_row.tags) |checked_tag, request_tag| {
                    for (checked_tag.payloads, request_tag.payloads) |checked_payload, request_payload| {
                        try ops.append(allocator, .{ .relate = .{ .checked = checked_payload, .request = request_payload } });
                    }
                }
                try ops.append(allocator, .{ .relate = .{ .checked = checked_row.ext, .request = request_row.ext } });
                try ops.append(allocator, .{ .join_container = roots });
                break :structural true;
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => break :structural false,
        },
        .redirect, .leaf, .unresolved, .primitive, .empty_tag_union, .empty_record, .erased, .zst => break :structural false,
    };
    if (!structural) try ops.append(allocator, .{ .unify = roots });
    frames.appendAssumeCapacity(.{
        .pair = roots,
        .ops_start = ops_start,
        .ops_end = ops.items.len,
        .next = ops_start,
    });
}

fn sameNamedValueDefinition(left: anytype, right: anytype) bool {
    return left.kind == right.kind and
        sameTypeDef(left.def, right.def) and
        left.builtin_owner == right.builtin_owner and
        left.args.len == right.args.len;
}

fn functionRequestNode(
    graph: *InstGraph,
    source_fn: NodeId,
    request_args: []const NodeId,
    request_ret: NodeId,
) Allocator.Error!NodeId {
    for (request_args) |request_arg| {
        if (try graph.containsGeneratedPrivate(request_arg)) {
            const request_fn = try graph.newNode(.{ .func = .{
                .args = try graph.arena().dupe(NodeId, request_args),
                .ret = request_ret,
            } });
            try graph.registerRequestSourceInterface(request_fn, source_fn);
            return request_fn;
        }
    }
    if (try graph.containsGeneratedPrivate(request_ret)) {
        const request_fn = try graph.newNode(.{ .func = .{
            .args = try graph.arena().dupe(NodeId, request_args),
            .ret = request_ret,
        } });
        try graph.registerRequestSourceInterface(request_fn, source_fn);
        return request_fn;
    }
    return source_fn;
}

const SpecEvidencePair = struct { a: SpecEvidence, b: SpecEvidence };

fn specEvidenceEql(allocator: Allocator, a: SpecEvidence, b: SpecEvidence) Allocator.Error!bool {
    return try specEvidenceVectorEql(allocator, &.{a}, &.{b});
}

/// Nested evidence follows type nesting, so pairs are compared from a
/// worklist rather than by recursion.
fn specEvidenceVectorEql(allocator: Allocator, a: []const SpecEvidence, b: []const SpecEvidence) Allocator.Error!bool {
    if (a.len != b.len) return false;
    if (a.ptr == b.ptr) return true;
    var pending = std.ArrayList(SpecEvidencePair).empty;
    defer pending.deinit(allocator);
    for (a, b) |a_entry, b_entry| try pending.append(allocator, .{ .a = a_entry, .b = b_entry });
    while (pending.pop()) |pair| {
        if (!try specEvidenceShallowEql(allocator, pair.a, pair.b, &pending)) return false;
    }
    return true;
}

/// Compare one evidence pair, queueing the pairs of its nested evidence.
fn specEvidenceShallowEql(
    allocator: Allocator,
    a: SpecEvidence,
    b: SpecEvidence,
    pending: *std.ArrayList(SpecEvidencePair),
) Allocator.Error!bool {
    const a_contracts = evidenceCallableContracts(a);
    const b_contracts = evidenceCallableContracts(b);
    if (a_contracts.len != b_contracts.len) return false;
    for (a_contracts, b_contracts) |a_contract, b_contract| try pending.append(allocator, .{ .a = a_contract, .b = b_contract });
    return switch (a) {
        .target => |a_target| switch (b) {
            .target => |b_target| blk: {
                if (!Ast.valueEql(a_target.view.key, b_target.view.key)) break :blk false;
                if (!specMethodTargetEql(a_target, b_target)) break :blk false;
                if (a_target.local_proc_context != b_target.local_proc_context) break :blk false;
                if (a_target.instantiation) |a_instantiation| {
                    const b_instantiation = b_target.instantiation orelse break :blk false;
                    if (!Ast.valueEql(a_instantiation.view.key, b_instantiation.view.key)) break :blk false;
                    if (!Ast.valueEql(
                        a_instantiation.view.types.rootKey(a_instantiation.callable_ty),
                        b_instantiation.view.types.rootKey(b_instantiation.callable_ty),
                    )) break :blk false;
                } else if (b_target.instantiation != null) {
                    break :blk false;
                }
                switch (a_target.nested) {
                    .synthesize => if (b_target.nested != .synthesize) break :blk false,
                    .resolved => |a_nested| switch (b_target.nested) {
                        .synthesize => break :blk false,
                        .resolved => |b_nested| {
                            if (a_nested.len != b_nested.len) break :blk false;
                            for (a_nested, b_nested) |a_entry, b_entry| {
                                try pending.append(allocator, .{ .a = a_entry, .b = b_entry });
                            }
                        },
                    },
                }
                break :blk true;
            },
            .structural, .from_callable, .from_scheme, .unreachable_value, .checked_error => false,
        },
        .structural => |a_structural| switch (b) {
            .structural => |b_structural| specStructuralEvidenceEql(a_structural, b_structural),
            .target, .from_callable, .from_scheme, .unreachable_value, .checked_error => false,
        },
        .from_callable => |a_use| switch (b) {
            .from_callable => |b_use| a_use.independent_callable == b_use.independent_callable,
            .target, .structural, .from_scheme, .unreachable_value, .checked_error => false,
        },
        .from_scheme => |index| b == .from_scheme and b.from_scheme == index,
        .unreachable_value => b == .unreachable_value,
        .checked_error => b == .checked_error,
    };
}

fn codecEvidenceIdentity(evidence: CheckedSpecStructuralEvidence) ?static_dispatch.GeneratedCodecDerivationId {
    const id = evidence.evidence.generated_codec_derivation orelse return null;
    return evidence.view.static_dispatch_plans.generated_codec_derivations[@backingInt(id)].identity;
}

fn specStructuralEvidenceEql(left: SpecStructuralEvidence, right: SpecStructuralEvidence) bool {
    if (!std.meta.eql(left.derivation, right.derivation)) return false;
    if ((left.checked == null) != (right.checked == null)) return false;
    if (left.checked == null) return true;
    const left_checked = left.checked.?;
    const right_checked = right.checked.?;
    return moduleBytesEqual(left_checked.view.key.bytes, right_checked.view.key.bytes) and
        codecEvidenceIdentity(left_checked) == codecEvidenceIdentity(right_checked) and
        std.meta.eql(
            left_checked.view.types.rootKey(left_checked.evidence.dispatcher_ty),
            right_checked.view.types.rootKey(right_checked.evidence.dispatcher_ty),
        ) and
        std.meta.eql(
            left_checked.view.types.rootKey(left_checked.evidence.callable_ty),
            right_checked.view.types.rootKey(right_checked.evidence.callable_ty),
        );
}

fn specMethodTargetEql(left: *const SpecEvidenceTarget, right: *const SpecEvidenceTarget) bool {
    return left.target.module_idx == right.target.module_idx and
        left.target.def_idx == right.target.def_idx and
        Ast.valueEql(left.target.kind, right.target.kind) and
        Ast.valueEql(
            left.view.types.rootKey(left.target.callable_ty),
            right.view.types.rootKey(right.target.callable_ty),
        );
}

/// Every evidence vector nested in `evidence`, visited from a worklist.
const SpecEvidenceWalk = struct {
    pending: std.ArrayList([]const SpecEvidence) = .empty,

    fn deinit(walk: *SpecEvidenceWalk, allocator: Allocator) void {
        walk.pending.deinit(allocator);
    }

    /// The next evidence entry; its callable contracts and a target's nested
    /// evidence are queued.
    fn next(walk: *SpecEvidenceWalk, allocator: Allocator, cursor: *[]const SpecEvidence) Allocator.Error!?SpecEvidence {
        while (cursor.len == 0) cursor.* = walk.pending.pop() orelse return null;
        const entry = cursor.*[0];
        cursor.* = cursor.*[1..];
        const contracts = evidenceCallableContracts(entry);
        if (contracts.len != 0) try walk.pending.append(allocator, contracts);
        switch (entry) {
            .target => |target| switch (target.nested) {
                .resolved => |nested| try walk.pending.append(allocator, nested),
                .synthesize => {},
            },
            .structural, .from_callable, .from_scheme, .unreachable_value, .checked_error => {},
        }
        return entry;
    }
};

fn specEvidenceRequiresLocalContext(allocator: Allocator, evidence: []const SpecEvidence) Allocator.Error!bool {
    var walk = SpecEvidenceWalk{};
    defer walk.deinit(allocator);
    var cursor = evidence;
    while (try walk.next(allocator, &cursor)) |entry| switch (entry) {
        .target => |target| if (target.local_proc_context != null) return true,
        .structural, .from_callable, .from_scheme, .unreachable_value, .checked_error => {},
    };
    return false;
}

fn specEvidenceContainsStructural(allocator: Allocator, evidence: []const SpecEvidence) Allocator.Error!bool {
    var walk = SpecEvidenceWalk{};
    defer walk.deinit(allocator);
    var cursor = evidence;
    while (try walk.next(allocator, &cursor)) |entry| switch (entry) {
        .structural => return true,
        .target, .from_callable, .from_scheme, .unreachable_value, .checked_error => {},
    };
    return false;
}

fn optionalTypeDigestEql(left: ?names.TypeDigest, right: ?names.TypeDigest) bool {
    if (left) |left_digest| {
        const right_digest = right orelse return false;
        return std.mem.eql(u8, &left_digest.bytes, &right_digest.bytes);
    }
    return right == null;
}

/// Draft specialization identity of a codec-anchored request. The anchored
/// contract supplies the body's checker-proven codec edges, and static
/// dispatch for one request type has exactly one resolution, so every contract
/// that prepared a call at an equal request type supplies equal edges. The
/// request type, evidence, and lexical context therefore identify the
/// specialization; which contract or derivation boundary supplied the edges
/// does not, and only codec kind separates anchored requests.
fn draftCodecContractSpecializationEql(
    left: ?DraftCodecContractContext,
    right: ?DraftCodecContractContext,
) bool {
    if ((left == null) != (right == null)) return false;
    if (left == null) return true;
    return left.?.anchor.kind == right.?.anchor.kind;
}

fn evidenceChainRequiresLocalContext(allocator: Allocator, evidence: EvidenceChain) Allocator.Error!bool {
    var frame = evidence;
    while (true) {
        if (try specEvidenceRequiresLocalContext(allocator, frame.vector)) return true;
        frame = (frame.parent orelse return false).*;
    }
}

fn specEvidenceLocalOwner(
    allocator: Allocator,
    draft: *const BodyDraftStore,
    evidence: []const SpecEvidence,
) Allocator.Error!?DraftOwner {
    var owner: ?DraftOwner = null;
    var walk = SpecEvidenceWalk{};
    defer walk.deinit(allocator);
    var cursor = evidence;
    while (try walk.next(allocator, &cursor)) |entry| switch (entry) {
        .target => |target| {
            if (target.local_proc_context) |context_id| {
                const raw = @backingInt(context_id);
                if (raw >= draft.local_proc_contexts.items.len) {
                    Common.invariant("specialization evidence referenced an unknown local declaration context");
                }
                const target_owner = draft.local_proc_contexts.items[raw].lexical_owner;
                if (owner) |existing| {
                    if (!std.meta.eql(existing, target_owner)) {
                        Common.invariant("one specialization depended on local methods from different lexical owners");
                    }
                } else owner = target_owner;
            }
        },
        .structural, .from_callable, .from_scheme, .unreachable_value, .checked_error => {},
    };
    return owner;
}

fn evidenceChainEql(allocator: Allocator, a: EvidenceChain, b: EvidenceChain) Allocator.Error!bool {
    var left = a;
    var right = b;
    while (true) {
        if (!EvidenceScope.eql(left.scope, right.scope)) return false;
        if (!try specEvidenceVectorEql(allocator, left.vector, right.vector)) return false;
        // The same parent frame is the same remaining chain.
        if (left.parent == right.parent) return true;
        if (left.parent) |left_parent| {
            const right_parent = right.parent orelse return false;
            left = left_parent.*;
            right = right_parent.*;
        } else return right.parent == null;
    }
}

const ScopedMethodDispatch = struct {
    scope: [32]u8,
    owner_tag: u8,
    owner_first: u32,
    owner_second: u32,
    owner_third: u32,
    method: u32,

    fn init(scope: checked.ModuleId, owner: static_dispatch.MethodOwner, method: names.MethodNameId) ScopedMethodDispatch {
        const owner_fields: struct { tag: u8, first: u32, second: u32, third: u32 } = switch (owner) {
            .builtin => |builtin| .{
                .tag = 1,
                .first = @backingInt(builtin),
                .second = 0,
                .third = 0,
            },
            .nominal => |nominal| .{
                .tag = 0,
                .first = @backingInt(nominal.module),
                .second = @backingInt(nominal.type_name),
                .third = if (nominal.source_decl) |source_decl| source_decl +| 1 else 0,
            },
        };
        return .{
            .scope = scope.bytes,
            .owner_tag = owner_fields.tag,
            .owner_first = owner_fields.first,
            .owner_second = owner_fields.second,
            .owner_third = owner_fields.third,
            .method = @backingInt(method),
        };
    }
};

/// What an exact registry lookup by method name found for a compiler-generated
/// edge. `rejected` is a declared method whose declaration canonicalization or
/// checking rejected: it has no runtime target and its diagnostic is already
/// reported, so the edge is a `checked_error` dispatch, exactly as
/// `EvidencePass` resolves a checked dispatch that lands on it.
const MethodLookupResult = union(enum) {
    target: MethodLookup,
    rejected,
};

const ScopedMethodResolution = union(enum) {
    missing,
    found: MethodLookupResult,
};

const FunctionShape = struct {
    args: Type.Span,
    ret: Type.TypeId,
};

const HostedCatalogEntry = struct {
    template: names.ProcTemplate,
    external_symbol_name: names.ExternalSymbolNameId,
    binding: union(enum) { unavailable, mapped: u32 },
    order: []const u8,
    target_checked_module_digest: [32]u8,
    def_idx: u32,
};

const HostedProcedureKey = struct {
    checked_module_digest: [32]u8,
    def_idx: u32,
};

const HostedBindingView = struct {
    table: *const checked.HostedBindingTable,
    names: *const names.NameStore,
};

/// A context's binder relations, shared by the nested contexts it creates
/// (`BodyContext.nestedRelationBase`): a context relating each binder's type
/// to its local, and which local each binder was related to.
const NestedRelationBase = struct {
    ctx: BodyContext,
    related: collections.DenseMap(checked.PatternBinderId, DraftLocalId),
    /// Every variable node the relations instantiated, in instantiation
    /// order; `ctx` records them through `relation_variables`.
    variables: std.ArrayList(InstantiatedVariable) = .empty,

    fn relate(self: *NestedRelationBase, entry: BinderMap.Entry) Allocator.Error!void {
        try self.ctx.constrainCheckedInterfaceToCell(checkedBinderType(self.ctx.view, entry.binder), self.ctx.localTypeCell(entry.local));
        try self.related.put(entry.binder, entry.local);
    }
};

/// A checked variable and the node an instantiation gave it.
const InstantiatedVariable = struct {
    checked_ty: checked.CheckedTypeId,
    node: NodeId,
};

/// Each lexical environment has its own version. Forks share inherited bindings;
/// the active indexed view replays only changes when retained branches switch.
const BinderMap = struct {
    const Map = collections.VersionedDenseMap(checked.PatternBinderId, DraftLocalId);
    values: Map,
    binder_count: usize,

    const Entry = struct { binder: checked.PatternBinderId, local: DraftLocalId };
    const Iterator = struct {
        inner: Map.Iterator,
        fn next(self: *Iterator) ?Entry {
            const entry = self.inner.next() orelse return null;
            return .{ .binder = entry.key_ptr.*, .local = entry.value_ptr.* };
        }
    };

    fn init(allocator: Allocator, binder_count: usize) Allocator.Error!BinderMap {
        return .{ .values = Map.init(allocator), .binder_count = binder_count };
    }

    fn deinit(self: *BinderMap) void {
        self.values.deinit();
    }

    fn fork(self: *const BinderMap) BinderMap {
        return .{ .values = self.values.fork(), .binder_count = self.binder_count };
    }

    fn checkBinder(self: *const BinderMap, binder: checked.PatternBinderId) void {
        if (@backingInt(binder) >= self.binder_count) Common.invariant("pattern binder was outside its checked body store");
    }

    fn get(self: *const BinderMap, binder: checked.PatternBinderId) ?DraftLocalId {
        self.checkBinder(binder);
        return self.values.get(binder);
    }

    fn put(self: *BinderMap, binder: checked.PatternBinderId, local: DraftLocalId) Allocator.Error!void {
        self.checkBinder(binder);
        try self.values.put(binder, local);
    }

    fn restore(self: *BinderMap, binder: checked.PatternBinderId, previous: ?DraftLocalId) void {
        self.checkBinder(binder);
        self.values.restore(binder, previous);
    }

    fn remove(self: *BinderMap, binder: checked.PatternBinderId) bool {
        self.checkBinder(binder);
        return self.values.remove(binder);
    }

    fn contains(self: *const BinderMap, binder: checked.PatternBinderId) bool {
        return self.get(binder) != null;
    }

    fn count(self: *const BinderMap) usize {
        return self.values.count();
    }

    fn iterator(self: *const BinderMap) Iterator {
        return .{ .inner = self.values.iterator() };
    }

    fn sortedEntries(self: *const BinderMap, allocator: Allocator) Allocator.Error![]Entry {
        const entries = try allocator.alloc(Entry, self.count());
        var iter = self.iterator();
        for (entries) |*entry| entry.* = iter.next().?;
        std.mem.sort(Entry, entries, {}, struct {
            fn lessThan(_: void, left: Entry, right: Entry) bool {
                return @backingInt(left.binder) < @backingInt(right.binder);
            }
        }.lessThan);
        return entries;
    }
};
const TypedBinder = struct {
    binder: checked.PatternBinderId,
    type_digest: names.TypeDigest,
};
const TypedBinders = collections.VersionedHashMap(TypedBinder, DraftLocalId);
const LocalProcContexts = collections.VersionedHashMap(DraftLocalProcAddress, DraftLocalProcContextId);
const LexicalBinderEntry = struct {
    kind: u8,
    binder: u32,
    local: u32,
    type_digest: names.TypeDigest,
};
const DraftLocalProcDeclaration = struct {
    module: [32]u8,
    binder: checked.PatternBinderId,
    expr: checked.CheckedExprId,
    context_anchor: ?checked.CheckedStatementId,

    fn address(self: DraftLocalProcDeclaration) DraftLocalProcAddress {
        return .{ .module = self.module, .binder = self.binder, .expr = self.expr };
    }
};
const DraftLocalProcAddress = struct {
    module: [32]u8,
    binder: checked.PatternBinderId,
    expr: checked.CheckedExprId,
};
const LocalProcContext = struct {
    declaration: DraftLocalProcDeclaration,
    lexical_owner: DraftOwner,
    owner_template: names.ProcTemplate,
    base_key: names.TypeDigest,
    /// Stable specialization identity supplied directly when ConstStore
    /// restoration replaces source locals with newly materialized captures.
    /// Ordinary source contexts derive identity from `base_key` and entries.
    restored_specialization_key: ?names.TypeDigest = null,
    entries: []LexicalBinderEntry,
    evidence: EvidenceChain,
};

/// Producer-authored lexical context retained by a ConstStore closure. The
/// checked use supplies the exact local-procedure declaration; this scope
/// supplies the declaration context that existed before the closure body's
/// own arguments were bound.
const RestoredLocalProcScope = struct {
    source_context_digest: names.TypeDigest,
    base_key: names.TypeDigest,
    entries: []const LexicalBinderEntry,
};

const StoredConstFnEvidence = struct {
    nodes: []const check.ConstStore.ConstFnEvidence,
    frames: []const check.ConstStore.ConstFnEvidenceFrame,
    head: ?u32,
    /// `Ast.fnEvidenceDigest` of exactly these fields. It is computed once
    /// when the value is built, or taken from the template that recorded it
    /// alongside the same fields, so no consumer rehashes the topology.
    digest: Ast.EvidenceDigest,

    fn init(
        nodes: []const check.ConstStore.ConstFnEvidence,
        frames: []const check.ConstStore.ConstFnEvidenceFrame,
        head: ?u32,
    ) StoredConstFnEvidence {
        return .{ .nodes = nodes, .frames = frames, .head = head, .digest = Ast.fnEvidenceDigest(nodes, frames, head) };
    }

    fn empty() StoredConstFnEvidence {
        return init(&.{}, &.{}, null);
    }

    /// The evidence a function template recorded, with the digest it
    /// recorded for those same fields.
    fn recorded(
        nodes: []const check.ConstStore.ConstFnEvidence,
        frames: []const check.ConstStore.ConstFnEvidenceFrame,
        head: ?u32,
        digest: Ast.EvidenceDigest,
    ) StoredConstFnEvidence {
        if (@import("builtin").mode == .debug and !std.meta.eql(digest, Ast.fnEvidenceDigest(nodes, frames, head))) {
            Common.invariant("function template evidence digest did not match its recorded topology");
        }
        return .{ .nodes = nodes, .frames = frames, .head = head, .digest = digest };
    }
};

/// What `Builder.constFnEvidence` reads from a chain: each frame's lexical
/// scope and vector, reached through `parent`. Chain frames are written once
/// when created and never mutated, so two chains whose head frames agree on
/// these identities convert to the same stored evidence.
const StoredEvidenceSource = struct {
    lexical: LexicalDispatchScope,
    vector_ptr: usize,
    vector_len: usize,
    parent: ?*const EvidenceChain,

    fn of(chain: EvidenceChain) StoredEvidenceSource {
        return .{
            .lexical = chain.scope.lexical,
            .vector_ptr = @intFromPtr(chain.vector.ptr),
            .vector_len = chain.vector.len,
            .parent = chain.parent,
        };
    }
};

const StoredEvidenceStorage = struct {
    nodes_ptr: usize,
    nodes_len: usize,
    frames_ptr: usize,
    frames_len: usize,
};

const DraftEvidenceSpans = struct {
    nodes: DraftSpan(check.ConstStore.ConstFnEvidence),
    frames: DraftSpan(check.ConstStore.ConstFnEvidenceFrame),
};

const StoredEvidenceCacheEntry = struct {
    source: StoredEvidenceSource,
    stored: StoredConstFnEvidence,
};

fn specializationEvidenceView(evidence: StoredConstFnEvidence) specialize.EvidenceView {
    return .{ .nodes = evidence.nodes, .frames = evidence.frames, .head = evidence.head, .digest = evidence.digest };
}

fn storedConstFnEvidenceEql(left: StoredConstFnEvidence, right: StoredConstFnEvidence) bool {
    if (!std.meta.eql(left.digest, right.digest)) return false;
    return Ast.fnEvidenceEql(left.nodes, left.frames, left.head, right.nodes, right.frames, right.head);
}

/// `Builder.site_evidence_memo`'s key: the site's checked evidence and
/// substitution spans, the scheme's requirement row, and the views and
/// purpose the evidence is materialized for.
const SiteEvidenceMemoKey = struct {
    view: usize,
    method_scope: usize,
    refs: usize,
    refs_len: usize,
    subst: usize,
    subst_len: usize,
    params: usize,
    params_len: usize,
    purpose: EvidenceMaterializationPurpose,
};

const SiteEvidenceMemo = struct {
    contract: []const SpecEvidence,
    vector: []const SpecEvidence,
};

const CheckedSpanKey = struct {
    view: usize,
    span: usize,
    len: usize,
};

/// Whether evidence names a local procedure context anywhere, which belongs
/// to the context that selected it.
fn evidenceVectorHasLocalProcContext(vector: []const SpecEvidence) bool {
    for (vector) |entry| {
        switch (entry) {
            .target => |target| {
                if (target.local_proc_context != null) return true;
                switch (target.nested) {
                    .resolved => |nested| if (evidenceVectorHasLocalProcContext(nested)) return true,
                    .synthesize => {},
                }
            },
            .structural, .from_callable, .from_scheme, .unreachable_value, .checked_error => {},
        }
        if (evidenceVectorHasLocalProcContext(evidenceCallableContracts(entry))) return true;
    }
    return false;
}

/// `Builder.const_evidence_memo`'s key: an evidence chain's innermost vector
/// and its frame count.
const ConstEvidenceMemoKey = struct {
    vector: usize,
    len: usize,
    frames: usize,
};

fn programViewFnEvidence(program: Ast.ProgramView, template: Ast.FnTemplate) StoredConstFnEvidence {
    return StoredConstFnEvidence.recorded(
        program.constFnEvidence(template.const_evidence),
        program.constFnEvidenceFrames(template.const_evidence_frames),
        template.const_evidence_frame_head,
        template.evidence_digest,
    );
}

/// Where a committed function's evidence sits in the program's evidence
/// lists.
fn programFnEvidenceSpan(template: Ast.FnTemplate) specialize.ProgramEvidenceSpan {
    return .{
        .nodes_start = template.const_evidence.start,
        .nodes_len = template.const_evidence.len,
        .frames_start = template.const_evidence_frames.start,
        .frames_len = template.const_evidence_frames.len,
        .head = template.const_evidence_frame_head,
    };
}

fn draftFnEvidence(body_draft: *const BodyDraftStore, template: DraftFnTemplate) StoredConstFnEvidence {
    return StoredConstFnEvidence.recorded(
        body_draft.constFnEvidence(template.const_evidence),
        body_draft.constFnEvidenceFrames(template.const_evidence_frames),
        template.const_evidence_frame_head,
        template.evidence_digest,
    );
}

/// Pass-local lowering state for one procedure template specialization,
/// keyed by the specialization's function id. Its identity, type views, and
/// status live on the `Ast.SpecRecord` owned by `spec_store`; this entry only
/// remembers which definition receives the body. Every path that reserves a
/// proc-template record in `spec_store` must register its entry here, or the
/// next reuse lookup hits the missing-lowering-state invariant.
const LoweredTemplate = struct {
    def: Ast.DefId,
    spec: Ast.SpecId,
    /// Evidence for the template scheme's dispatch requirements, in enumeration
    /// evidence-param order, supplied by the first requesting edge. Reused
    /// specializations debug-assert later edges agree (evidence is a function
    /// of the monomorphic type, so agreement is an invariant, not a choice).
    evidence: []const SpecEvidence = &.{},
    /// Exact durable topology for the complete lexical evidence chain.
    topology: ?StoredConstFnEvidence = null,
    /// The request relation's answer recorded by the first requesting edge. A
    /// specialization is either a widening adapter or a definition at its own
    /// requested row, never both, so a later edge that reuses this identity
    /// with the other answer is a disagreement about the callee's tag layout.
    widened_result_row: bool = false,
};

const TemplateReservation = struct {
    def: Ast.DefId,
    fn_id: Ast.FnId,
    symbol: Common.Symbol,
};

/// How a template specialization's body is produced once its identity is
/// reserved. Roots, restored constant functions, and hosted adapter sources
/// lower the body immediately; a seal-time symbolic request only reserves the
/// identity and queues the body for the scheduler's wave drain. Iterator
/// producers needed before seal stay draft-local instead of entering this
/// coordinator-owned path.
const TemplateBodyScheduling = enum { immediate, queued };

/// Bound running plus completed-but-unaccepted jobs. Extra slots let free
/// lanes continue working when an earlier dispatch delays ordered acceptance.
pub const parallel_spec_jobs_per_lane: usize = 64;
const SharedSummaries = WorkerInputs.AppendIndex(InterfaceReplayAddress, InterfaceSummaryEntry);

const SpecJobRunId = enum(u32) { _ };
var next_spec_job_run_id = std.atomic.Value(u32).init(0);

/// One reserved specialization whose body has not lowered yet, in the
/// deterministic scheduler FIFO. Every field is durable for the builder's
/// lifetime: evidence lives in the evidence arena, the requested type is
/// sealed, and the reservation already owns its global ids, so the job
/// outlives the requesting graph and draft.
const PendingSpecJob = struct {
    /// Logical enqueue order across the whole build. The inline executor
    /// accepts queue entries strictly in this order. Representation-sensitive
    /// immediate claims are completed as inline work of the executing body;
    /// their stale queue entry is accepted later as a ready skip.
    dispatch_index: u64,
    spec: Ast.SpecId,
    reservation: TemplateReservation,
    fn_template: Ast.FnTemplate,
    template_ref: names.ProcTemplate,
    method_scope: checked.ModuleId,
    source_fn_ty: checked.CheckedTypeId,
    source_fn_key: names.TypeDigest,
    fn_ty: Type.TypeId,
    evidence: []const SpecEvidence,
    subst: ?SealedSubstitution,
    signature_relation: Ast.SignatureRelation,
    codec_contract: ?SealedCodecContractContext,
    /// The request relation's own answer for this specialization: whether it
    /// declined to unify the template's closed checked result row with the
    /// requested one. Completion mints a widening adapter exactly when this is
    /// set (design.md "Result-Row Widening Adapter").
    widened_result_row: bool,
};

/// One reserved template body lowered into graph-local and draft-local state,
/// before its final ids and solved root type are committed.
const PendingTemplateBody = struct {
    reservation: TemplateReservation,
    fn_template: Ast.FnTemplate,
    signature_relation: Ast.SignatureRelation,
    root_node: NodeId,
    lowered: LoweredTemplateBody,
};

/// Graph-free completion data retained by an ordinary specialization result.
/// Every type belongs to the immutable store epoch carried by the shard.
const SealedPendingTemplateBody = struct {
    reservation: TemplateReservation,
    fn_template: Ast.FnTemplate,
    signature_relation: Ast.SignatureRelation,
    root_ty: Type.TypeId,
    lowered: SealedLoweredTemplateBody,
};

const SpecJobEpoch = enum(u64) { _ };
/// Stable specialization workspace identity used to preserve per-worker epochs.
pub const SpecJobWorkerId = enum(u32) { serial = std.math.maxInt(u32), _ };

/// Result-owned type/name suffix from one specialization workspace epoch.
///
/// Dense ids remain in the workspace domain. Ordered coordinator absorption
/// copies that domain before relocating reachable roots into the program.
const SpecJobStoreEpoch = struct {
    types: Type.Store.EpochDelta,
    names: names.NameStore.EpochDelta,

    fn deinit(self: *SpecJobStoreEpoch) void {
        self.names.deinit();
        self.types.deinit();
        self.* = undefined;
    }
};

/// Persistent private type/name domain for serialized ordinary specialization jobs.
/// Exactly one mutable graph/draft writer may borrow it at a time. Captured
/// type/name suffixes own their bytes, so completed results do not retain that
/// borrow and the next writer can begin before ordered coordinator acceptance.
const SpecJobWorkspace = struct {
    allocator: Allocator,
    types: Type.Store,
    name_store: names.NameStore,
    interface_summaries: InterfaceSummaryCache,
    captured_interface_summaries: usize = 0,
    checked_type_cache: std.AutoHashMap(CheckedTypeAddress, Type.TypeId),
    captured_types: Type.Store.EpochBoundary,
    captured_names: names.NameStore.EpochBoundary,
    program: ?*Ast.Program = null,
    program_to_workspace: ?Type.Store.TypeRelocation = null,
    workspace_to_program: ?Type.Store.TypeRelocation = null,
    next_epoch: u64 = 0,
    active_epoch: ?SpecJobEpoch = null,

    fn init(allocator: Allocator) SpecJobWorkspace {
        var types = Type.Store.init(allocator);
        var name_store = names.NameStore.init(allocator);
        return .{
            .allocator = allocator,
            .captured_types = types.epochBoundary(),
            .captured_names = name_store.epochBoundary(),
            .types = types,
            .name_store = name_store,
            .interface_summaries = InterfaceSummaryCache.init(allocator),
            .checked_type_cache = std.AutoHashMap(CheckedTypeAddress, Type.TypeId).init(allocator),
        };
    }

    fn bindProgram(self: *SpecJobWorkspace, program: *Ast.Program) void {
        if (self.program) |bound| {
            if (bound != program) {
                Common.compilerBug("Monotype specialization workspace changed coordinator programs");
            }
        } else {
            self.program = program;
        }
    }

    fn beginEpoch(self: *SpecJobWorkspace, program: *Ast.Program) SpecJobEpoch {
        self.bindProgram(program);
        if (self.active_epoch != null) {
            Common.compilerBug("Monotype specialization workspace began overlapping epochs");
        }
        if (self.next_epoch == std.math.maxInt(u64)) {
            Common.compilerBug("Monotype specialization workspace exhausted epoch identities");
        }
        const epoch: SpecJobEpoch = @fromBackingInt(@intCast(self.next_epoch));
        self.next_epoch += 1;
        self.active_epoch = epoch;
        return epoch;
    }

    fn requireEpoch(self: *const SpecJobWorkspace, epoch: SpecJobEpoch) void {
        if (self.active_epoch == null or self.active_epoch.? != epoch) {
            Common.compilerBug("Monotype specialization shard used a stale workspace epoch");
        }
    }

    fn finishEpoch(self: *SpecJobWorkspace, epoch: SpecJobEpoch) void {
        self.requireEpoch(epoch);
        self.active_epoch = null;
    }

    fn captureStoreEpoch(
        self: *SpecJobWorkspace,
        epoch: SpecJobEpoch,
    ) Allocator.Error!SpecJobStoreEpoch {
        self.requireEpoch(epoch);
        const type_end = self.types.epochBoundary();
        const name_end = self.name_store.epochBoundary();
        var type_segment = try Type.Store.EpochDelta.capture(
            self.allocator,
            &self.types,
            self.captured_types,
            type_end,
        );
        errdefer type_segment.deinit();
        const name_segment = try names.NameStore.EpochDelta.capture(
            self.allocator,
            &self.name_store,
            self.captured_names,
            name_end,
        );
        self.captured_types = type_end;
        self.captured_names = name_end;
        return .{ .types = type_segment, .names = name_segment };
    }

    fn programTypeRelocation(
        self: *SpecJobWorkspace,
        program: *Ast.Program,
    ) *Type.Store.TypeRelocation {
        self.bindProgram(program);
        if (self.program_to_workspace == null) {
            self.program_to_workspace = Type.Store.TypeRelocation.init(
                self.allocator,
                &program.types,
                &program.names,
                &self.types,
                &self.name_store,
            );
        }
        return &self.program_to_workspace.?;
    }

    fn committedTypeRelocation(
        self: *SpecJobWorkspace,
        program: *Ast.Program,
    ) *Type.Store.TypeRelocation {
        self.bindProgram(program);
        if (self.workspace_to_program == null) {
            self.workspace_to_program = Type.Store.TypeRelocation.init(
                self.allocator,
                &self.types,
                &self.name_store,
                &program.types,
                &program.names,
            );
        }
        return &self.workspace_to_program.?;
    }

    fn deinit(self: *SpecJobWorkspace) void {
        if (self.active_epoch != null) {
            Common.compilerBug("Monotype specialization workspace deinitialized during an active epoch");
        }
        if (self.workspace_to_program) |*relocation| relocation.deinit();
        if (self.program_to_workspace) |*relocation| relocation.deinit();
        self.interface_summaries.deinit();
        self.checked_type_cache.deinit();
        self.types.deinit();
        self.name_store.deinit();
        self.* = undefined;
    }
};

/// Persistent state for one specialization execution lane. Executor-backed
/// lanes retain it for the worker-pool lifetime; the serial path owns the same
/// shape directly. Barriers end task-result ownership, while the workspace
/// retains cumulative relocation state for later tasks.
pub const SpecJobWorkerState = struct {
    worker_id: SpecJobWorkerId,
    allocator: Allocator,
    workspace: SpecJobWorkspace,
    graph: ?*InstGraph = null,
    builder: ?*Builder = null,
    /// Stable-address lane view of the captured worker read set.
    /// It borrows snapshot storage and contains no coordinator output rows.
    input_program: ?*Ast.Program = null,
    tasks_started: u64 = 0,
    counters: SpecializationCounters = .{},
    diagnostics: Diagnostics = .{},

    pub fn init(allocator: Allocator, worker_id: SpecJobWorkerId) SpecJobWorkerState {
        return .{
            .worker_id = worker_id,
            .allocator = allocator,
            .workspace = SpecJobWorkspace.init(allocator),
        };
    }

    pub fn deinit(self: *SpecJobWorkerState) void {
        if (self.builder) |builder| {
            builder.deinit();
            self.allocator.destroy(builder);
        }
        if (self.graph) |graph| graph.destroy();
        self.workspace.deinit();
        if (self.input_program) |program| self.allocator.destroy(program);
        self.* = undefined;
    }
};

/// Cumulative copy of one worker's type/name domain. Executor lanes own their
/// copy for the pool lifetime; the serial path owns an equivalent directly.
/// Only the coordinator mutates it, in dispatch order, before any contained id
/// is read.
const SpecJobCommitDomain = struct {
    allocator: Allocator,
    types: Type.Store,
    name_store: names.NameStore,
    program: ?*Ast.Program = null,
    relocation: ?Type.Store.TypeRelocation = null,

    fn init(allocator: Allocator) SpecJobCommitDomain {
        return .{
            .allocator = allocator,
            .types = Type.Store.init(allocator),
            .name_store = names.NameStore.init(allocator),
        };
    }

    fn absorb(self: *SpecJobCommitDomain, epoch: *const SpecJobStoreEpoch) Allocator.Error!void {
        if (!std.meta.eql(self.name_store.epochBoundary(), epoch.names.begin) or
            !std.meta.eql(self.types.epochBoundary(), epoch.types.begin))
        {
            Common.compilerBug("specialization worker epochs reached ordered commit out of sequence");
        }
        // Reserve both stores before advancing either durable boundary. An OOM
        // leaves the epoch retryable and preserves exact cross-store continuity.
        try epoch.names.prepareAppend(&self.name_store);
        try epoch.types.prepareAppend(&self.types);
        epoch.names.appendPrepared(&self.name_store);
        epoch.types.appendPrepared(&self.types);
    }

    fn committedTypeRelocation(
        self: *SpecJobCommitDomain,
        program: *Ast.Program,
    ) *Type.Store.TypeRelocation {
        if (self.program) |bound| {
            if (bound != program) {
                Common.compilerBug("Monotype specialization commit domain changed coordinator programs");
            }
        } else {
            self.program = program;
        }
        if (self.relocation == null) {
            self.relocation = Type.Store.TypeRelocation.init(
                self.allocator,
                &self.types,
                &self.name_store,
                &program.types,
                &program.names,
            );
        }
        return &self.relocation.?;
    }

    fn deinit(self: *SpecJobCommitDomain) void {
        if (self.relocation) |*relocation| relocation.deinit();
        self.types.deinit();
        self.name_store.deinit();
        self.* = undefined;
    }
};

/// Monotype state retained by one executor lane. Keeping the source
/// workspace and its ordered destination copy together makes their cumulative
/// relocation domains follow the worker rather than a particular coordinator
/// `Builder`. A new Monotype run reinitializes the same retained entry because
/// its stores belong to a different destination program.
const SpecJobLaneState = struct {
    run_id: SpecJobRunId,
    worker: SpecJobWorkerState,
    commit_domain: SpecJobCommitDomain,

    fn init(
        allocator: Allocator,
        worker_id: SpecJobWorkerId,
        run_id: SpecJobRunId,
    ) SpecJobLaneState {
        return .{
            .run_id = run_id,
            .worker = SpecJobWorkerState.init(allocator, worker_id),
            .commit_domain = SpecJobCommitDomain.init(allocator),
        };
    }

    fn deinit(self: *SpecJobLaneState) void {
        self.commit_domain.deinit();
        self.worker.deinit();
        self.* = undefined;
    }
};

/// Address identity used to reserve this module's entry in an executor lane.
const SpecJobLaneStateKey = struct {
    var value: u8 = undefined;
};

/// One immutable graph-free result handed from ordinary body lowering to
/// ordered coordinator commit.
const CompletedSpecJobShard = struct {
    worker_id: SpecJobWorkerId,
    commit_domain: *SpecJobCommitDomain,
    dispatch_index: u64,
    worker_local_symbol_count: u32,
    specialization_counter_delta: ?SpecializationCounters = null,
    interface_summaries: []const InterfaceSummaryEntry = &.{},
    store_epoch: SpecJobStoreEpoch,
    body_draft: BodyDraftStore,
    pending: SealedPendingTemplateBody,
    diagnostics: ?*SpecJobDiagnostics,
    diagnostics_committed: bool = false,
    store_epoch_absorbed: bool = false,

    fn deinit(self: *CompletedSpecJobShard) void {
        const allocator = self.body_draft.allocator;
        self.body_draft.deinit();
        allocator.free(self.interface_summaries);
        self.store_epoch.deinit();
        if (self.diagnostics) |diagnostics| {
            allocator.destroy(diagnostics);
        }
        self.* = undefined;
    }
};

/// Graph-free procedure-use root result. Keeping this shape separate prevents
/// root commit concerns from leaking into ordinary specialization shards.
const CompletedProcedureRootShard = struct {
    worker_id: SpecJobWorkerId,
    commit_domain: *SpecJobCommitDomain,
    worker_local_symbol_count: u32,
    specialization_counter_delta: ?SpecializationCounters = null,
    interface_summaries: []const InterfaceSummaryEntry = &.{},
    store_epoch: SpecJobStoreEpoch,
    body_draft: BodyDraftStore,
    root_ty: Type.TypeId,
    root_def: DraftDefId,
    diagnostics: ?*SpecJobDiagnostics,
    diagnostics_committed: bool = false,
    store_epoch_absorbed: bool = false,

    fn deinit(self: *CompletedProcedureRootShard) void {
        const allocator = self.body_draft.allocator;
        self.body_draft.deinit();
        allocator.free(self.interface_summaries);
        self.store_epoch.deinit();
        if (self.diagnostics) |diagnostics| allocator.destroy(diagnostics);
        self.* = undefined;
    }
};

/// Captured immutable input for a root batch or one streaming specialization.
const SpecJobWorkerInputs = struct {
    run_id: SpecJobRunId,
    modules: Common.CheckedModules,
    module_views: []const ModuleViewData,
    source_file_ids: *const SourceFileIds,
    lowering_module_ids: *const LoweringModuleIds,
    snapshot: *const WorkerInputs.Snapshot,
    proc_debug_names: bool,
    interface_summaries: *const SharedSummaries,
    interface_summary_end: usize,
    collect_counters: bool,
    collect_diagnostics: bool,
    inline_expects: InlineExpectMode,
    static_data_literals: bool,
    comptime_value_reads: bool,
    literal_roots: bool,
    declared_comptime_root_functions: *const DeclaredComptimeRootFunctions,
    hosted_catalog: []const HostedCatalogEntry,
    current_loc: base.SourceLoc,
    current_region: base.Region,
    timing_std_io: ?std.Io,
};

const PreparedSpecJob = struct {
    job: PendingSpecJob,
    view: ModuleView,
    method_scope: ModuleView,
    template: checked.CheckedProcedureTemplate,
};

/// Caller-owned task storage. Executor callbacks write only their own element.
const SpecJobTaskContext = struct {
    inputs: SpecJobWorkerInputs,
    snapshot: WorkerInputs.Snapshot,
    prepared: PreparedSpecJob,
    shard: ?CompletedSpecJobShard = null,
    failed: bool = false,
    completed: bool = false,
    /// The entry completes on the coordinator when its acceptance turn comes.
    /// It holds its place in dispatch order without occupying a worker lane,
    /// so later entries can reach free lanes before it runs.
    coordinator_only: bool = false,
    worker_work_ns: u64 = 0,
    lane_task_started: bool = false,
    first_task_on_lane: bool = false,
};

/// Fixed ring of caller-owned task contexts, retained through ordered acceptance.
const SpecJobTaskBuffers = struct {
    contexts: []SpecJobTaskContext = &.{},

    fn deinit(self: *SpecJobTaskBuffers, allocator: Allocator) void {
        allocator.free(self.contexts);
        self.* = .{};
    }
};

/// Caller-owned root task storage lets unordered executor completion be
/// validated before any ordered coordinator commit begins.
const ProcedureRootTaskContext = struct {
    source_module: checked.ModuleId,
    inputs: *const SpecJobWorkerInputs,
    request: checked.RootRequest,
    shard: ?CompletedProcedureRootShard = null,
    failed: bool = false,
    completed: bool = false,
    worker_work_ns: u64 = 0,
    lane_task_started: bool = false,
    first_task_on_lane: bool = false,
};

const FinalBodyOutputCounts = struct {
    exprs: usize = 0,
    pats: usize = 0,
    locals: usize = 0,
    typed_locals: usize = 0,
    layout_requests: usize = 0,
    runtime_schema_requests: usize = 0,

    fn fromProgram(program: *const Ast.Program) FinalBodyOutputCounts {
        return .{
            .exprs = program.exprCount(),
            .pats = program.patCount(),
            .locals = program.localCount(),
            .typed_locals = program.typedLocalCount(),
            .layout_requests = program.layoutRequestCount(),
            .runtime_schema_requests = program.runtimeSchemaRequestCount(),
        };
    }

    fn addDelta(self: *FinalBodyOutputCounts, before: FinalBodyOutputCounts, after: FinalBodyOutputCounts) void {
        self.exprs += after.exprs - before.exprs;
        self.pats += after.pats - before.pats;
        self.locals += after.locals - before.locals;
        self.typed_locals += after.typed_locals - before.typed_locals;
        self.layout_requests += after.layout_requests - before.layout_requests;
        self.runtime_schema_requests += after.runtime_schema_requests - before.runtime_schema_requests;
    }
};

fn localFnIdFromSlot(slot: Ast.FnSlot) Ast.FnId {
    return switch (slot) {
        .local => |fn_id| fn_id,
    };
}

const LambdaArgLet = struct {
    pat: DraftPatId,
    value: DraftExprId,
};

const MergeBinder = struct {
    binder: checked.PatternBinderId,
    before: DraftLocalId,
    ty: DraftTypeCell,
};

const LoweredLambdaArgs = struct {
    args: DraftSpan(DraftTypedLocal),
    body: DraftExprId,
    ret: DraftTypeCell,
};

const LoweredCall = struct {
    ret_ty: DraftTypeCell,
    data: DraftExprData,
};

const LoweringDemand = enum {
    runtime_value,
    inspect_only,
    uninhabited_result,
};

const FieldNameBound = enum {
    shortest,
    longest,
};

const FieldNamesIterMode = enum {
    all,
    for_size,
};

const ConstExprAddress = struct {
    store_module_bytes: [32]u8,
    type_module_bytes: [32]u8,
    node: u32,
    mono_ty: u32,
};

const StaticDataUse = struct {
    module: checked.ModuleId,
    node: checked.ConstNodeId,
    checked_type: checked.CheckedTypeId,
    ty: Type.TypeId,
};

fn constStringBackingLength(view: ModuleView, str: check.ConstStore.ConstStr) u64 {
    return @max(view.const_store.strBytes(str).len, view.const_store.blobData(str.data).len);
}

fn constStaticDataStorage(view: ModuleView, node: checked.ConstNodeId) Common.StaticDataStorage {
    var current = node;
    while (true) switch (view.const_store.get(current)) {
        .str => |str| return .{ .string_backing = constStringBackingLength(view, str) },
        .nominal => |nominal| current = nominal.backing,
        .pending => Common.invariant("pending const reached static storage metadata production"),
        .zst, .scalar, .fn_value, .list, .box, .tuple, .record, .tag, .crash, .checked_error => return .aggregate,
    };
}

const ConstNodeAddress = struct {
    module: checked.ModuleId,
    node: checked.ConstNodeId,
};

/// Key for a memoized structural-derivation helper def. `value_ty` is the type
/// being derived over; `result_ty` is the derivation's auxiliary type (the
/// produced Str for inspect, the Bool for equality, the Hasher for hashing).
///
/// These memos are deliberately NOT specialization records in `spec_store`:
/// helper defs have no `FnId` (they are `def_ref` targets, not callable
/// specializations), and their keys are process-local interned type ids with
/// no durable digest, so they cannot participate in cross-shard reuse. The
/// specialization identity story lives entirely in `specialize.SpecBuilder`.
const GeneratedHelperDefAddress = struct {
    value_ty: u32,
    result_ty: u32,
};

/// Exact Monotype inputs for one generated structural encoder helper. These
/// helpers belong to the active body draft: they capture that encoder
/// construction's encoding value and precomputed field names, while their
/// value and state are explicit arguments. The result type is addressed by
/// content: each nesting level builds its result from its parent's, so a
/// recursive shape reaches its own helper again through a distinct but equal
/// result type, and must find the helper already reserved for it.
const GeneratedEncoderDefAddress = struct {
    value_ty: u32,
    encoding_ty: u32,
    state_ty: u32,
    result: names.TypeDigest,
};

/// Exact Monotype inputs for one generated structural parser helper, with the
/// result type addressed by content exactly as for encoder helpers.
const GeneratedParserDefAddress = struct {
    value_ty: u32,
    encoding_ty: u32,
    state_ty: u32,
    result: names.TypeDigest,
};

/// Exact child identity for a compiler-generated parser success record.
/// Generated Monotype types are immutable, so equal child ids must reuse one
/// record id instead of appending structurally identical nodes to the store.
const GeneratedParseResultOkTypeAddress = struct {
    value_ty: u32,
    rest_ty: u32,
};

/// Exact child identity for a compiler-generated Try instantiation. The
/// template carries the nominal identity and backing authority; the two child
/// types determine its instantiated arguments and backing tag payloads.
const GeneratedTryTypeAddress = struct {
    template_ty: u32,
    ok_ty: u32,
    err_ty: u32,
};

/// Process-local O(1) reuse key for a checker-classified closed direct
/// procedure call. `evidence` is an interned producer identity in `module`;
/// the plan's closed callable type is likewise structurally interned there.
/// The method scope remains part of specialization identity because imported
/// bodies resolve compiler-generated method calls in that scope.
const ClosedDirectCallIdentity = struct {
    callable: CheckedTypeAddress,
    evidence: static_dispatch.EvidenceNodeId,
    method_scope: checked.ModuleId,
};

/// Tracks a memoized structural-derivation helper def (is_eq / inspect /
/// to_hash). `reserved` means the def id is allocated but its body has not yet
/// been filled in (used to break recursion); `ready` means the body is complete.
const DraftGeneratedHelperDefEntry = union(enum) {
    reserved: DraftDefId,
    ready: DraftDefId,

    fn id(self: DraftGeneratedHelperDefEntry) DraftDefId {
        return switch (self) {
            .reserved, .ready => |def_id| def_id,
        };
    }
};

fn codecContractIdentityDigest(contract: ?Ast.CodecContractIdentity) names.TypeDigest {
    const actual = contract orelse return .{};
    var hasher = TypeDigestHasher.init();
    hasher.update("roc.monotype.codec_contract.v4");
    hasher.update(&actual.module.bytes);
    var integer: [4]u8 = undefined;
    std.mem.writeInt(u32, &integer, @backingInt(actual.derivation), .little);
    hasher.update(&integer);
    hasher.update(&.{@backingInt(actual.kind)});
    hasher.update(&actual.constructor_ty_digest.bytes);
    hasher.update(&actual.shape_ty_digest.bytes);
    return .{ .bytes = hasher.finalResult() };
}

/// A nominal identity paired with the name domain that owns it.
const QualifiedTypeDef = struct {
    name_store: *const names.NameStore,
    def: Type.TypeDef,
};

const SymbolDomain = enum {
    coordinator,
    worker_local,
};

/// Routes symbol allocation without changing the many lowering sites which
/// create symbols. Worker-local allocation is reset for each ordinary shard;
/// coordinator allocation remains the durable program domain.
const SymbolDomains = struct {
    coordinator: Common.SymbolGen = .{},
    worker_local: Common.SymbolGen = .{},
    active: SymbolDomain = .coordinator,

    fn fresh(self: *SymbolDomains) Common.Symbol {
        const generator = switch (self.active) {
            .coordinator => &self.coordinator,
            .worker_local => &self.worker_local,
        };
        if (generator.next == std.math.maxInt(u32)) {
            Common.compilerBug("Monotype symbol domain overflow");
        }
        return generator.fresh();
    }

    fn freshCoordinator(self: *SymbolDomains) Common.Symbol {
        if (self.coordinator.next == std.math.maxInt(u32)) {
            Common.compilerBug("Monotype symbol domain overflow");
        }
        return self.coordinator.fresh();
    }
};

fn appendRuntimeSchemaRequestToProgram(
    program: *Ast.Program,
    request: Ast.RuntimeSchemaRequest,
) Allocator.Error!void {
    for (program.runtimeSchemaRequestsView()) |existing| {
        if (existing.def.module == request.def.module and
            existing.def.type_name == request.def.type_name)
        {
            return;
        }
    }
    try program.addRuntimeSchemaRequest(request);
}

const DeclaredComptimeRootFunctions = std.AutoHashMap(EntryRoot, Ast.FnId);

/// Checked module keys cross independent checking environments. Their local
/// module indices do not; distinct checked modules routinely share an index.
const SourceFileIds = std.AutoHashMap([32]u8, u32);

/// `Common.LoweringModuleId` of every checked module in the lowering input,
/// keyed by checked module identity. Separate from `SourceFileIds` because the
/// two domains have different lifetimes: source-file ordinals are remapped
/// when LIR images from different programs are packed together, while a
/// lowering module id names a row of one program's own module table.
const LoweringModuleIds = std.AutoHashMap([32]u8, Common.LoweringModuleId);

const Builder = struct {
    allocator: Allocator,
    spec_job_run_id: SpecJobRunId,
    modules: Common.CheckedModules,
    root_view: checked.ImportedModuleView,
    /// Checked module key -> position in the lowering input; built lazily on
    /// first lookup (see `buildModuleIndex`).
    module_index: std.AutoHashMap([32]u8, ModuleIndexSlot),
    /// Every input module's view: the root, then imports, then relation
    /// modules. A worker's builder borrows its coordinator's views instead,
    /// so a view it hands back stays valid for the whole run.
    module_views: []ModuleViewData = &.{},
    borrowed_module_views: ?[]const ModuleViewData = null,
    /// Program source-file id of every checked module in the lowering input,
    /// keyed by checked module identity. The coordinator seeds this table
    /// before lowering any body; workers borrow it for this lowering run.
    source_file_ids: SourceFileIds,
    borrowed_source_file_ids: ?*const SourceFileIds = null,
    /// Dense module id of every checked module in the lowering input, seeded
    /// beside `source_file_ids` and borrowed by workers the same way. Rows
    /// that retain a module-local checked id record their owner through this.
    lowering_module_ids: LoweringModuleIds,
    borrowed_lowering_module_ids: ?*const LoweringModuleIds = null,
    program: *Ast.Program,
    current_loc: base.SourceLoc,
    current_region: base.Region,
    proc_debug_names: bool,
    /// The object cache consulted for closed specializations, if any.
    spec_cache: ?Common.SpecCacheLookup,
    counters: ?*SpecializationCounters,
    diagnostics: ?*Diagnostics,
    /// Result-owned sink while one ordinary specialization shard is lowering or
    /// committing. Scheduler diagnostics continue to target `diagnostics`.
    active_spec_job_diagnostics: ?*SpecJobDiagnostics = null,
    inline_expects: InlineExpectMode,
    static_data_literals: bool,
    comptime_value_reads: bool,
    literal_roots: bool,
    declared_comptime_root_functions: DeclaredComptimeRootFunctions,
    borrowed_comptime_root_functions: ?*const DeclaredComptimeRootFunctions = null,
    post_check_executor: ?base.post_check_task_executor.Executor,
    timing: ?*Timing,
    /// Marks callbacks that must leave coordinator-owned stores unchanged.
    spec_job_parallel_callback: bool = false,
    /// Set while a coordinator-domain scope is open; see
    /// `ProgramTypeDestination`.
    force_program_type_destination: bool = false,
    symbols: SymbolDomains = .{},
    next_instantiation_scope: u64 = 0,
    type_cache: std.AutoHashMap(CheckedTypeAddress, Type.TypeId),
    /// Deterministic FIFO of reserved specializations awaiting body lowering.
    /// Wave drains execute entries in dispatch order; an executing body may
    /// append new entries, which the same drain then reaches.
    pending_spec_jobs: collections.RingQueue(PendingSpecJob) = .empty,
    next_spec_dispatch_index: u64 = 0,
    /// Next logical queue entry the coordinator may accept. This first boundary
    /// validates FIFO accounting; later worker results also buffer ordinary
    /// body appends behind this index.
    next_spec_accept_index: u64 = 0,
    /// Serial execution uses the same worker-tagged ownership protocol as
    /// executor callbacks.
    spec_job_worker: ?SpecJobWorkerState = null,
    /// Coordinator-owned exact-prefix copy of immutable specialization
    /// epochs. It is the concrete source for cumulative workspace-to-program
    /// relocation after worker results stop borrowing the mutable workspace.
    spec_job_commit_domain: ?SpecJobCommitDomain = null,
    spec_job_task_buffers: SpecJobTaskBuffers = .{},
    worker_inputs: WorkerInputs.ProgramInputs = .{},
    shared_summaries: ?SharedSummaries = null,
    interface_summaries: InterfaceSummaryCache,
    /// Per template, which quantified variables its interface relates only
    /// by unification (see `parametricSchemeVarMask`).
    parametric_scheme_vars: std.AutoHashMapUnmanaged(names.ProcTemplate, []const bool) = .empty,
    /// Per nominal declaration, whether each parameter occurs in its backing only
    /// as a value; null while the declaration is being analyzed or when it cannot be.
    nominal_parameter_value_masks: std.AutoHashMapUnmanaged(NominalDeclarationKey, ?[]const bool) = .empty,
    coordinator_interface_summaries: ?*const SharedSummaries = null,
    coordinator_interface_summary_end: usize = 0,
    interface_summary_checks: u32 = 0,
    spec_store: specialize.SpecBuilder,
    lowered_templates: collections.DenseMap(Ast.FnId, LoweredTemplate),
    /// `monoTypeMentionsFunction`'s answers, indexed by program type id. A
    /// program type store rollback frees ids for reuse, so the column is cut
    /// back to the rollback floor before each read.
    function_mentions: std.ArrayList(FunctionMention) = .empty,
    /// The types on `monoTypeMentionsFunction`'s current walk path and those
    /// its walk finished open, kept for its capacity between walks.
    function_scan_path: collections.DenseMap(Type.TypeId, void),
    /// Resolved copies of symbolic callable evidence vectors, by callee
    /// template. Repeated requests over the same open leaves resolve every
    /// slot identically, so they read an equal copy back instead of
    /// allocating another identical vector.
    resolved_callable_vectors: std.AutoHashMap(u64, std.ArrayList([]const SpecEvidence)),
    /// Nested-fn specialization records keyed by function id; the durable
    /// identity and status live on the `Ast.SpecRecord`.
    lowered_nested_by_fn: collections.DenseMap(Ast.FnId, Ast.SpecId),
    nested_site_cache: std.AutoHashMap(NestedSiteAddress, names.ProcSiteId),
    /// Each checked expression's reassigned binders in source order (see
    /// `collectReassignedBindersInExpr`), as spans of
    /// `reassigned_binder_pool`. They depend only on the checked expression
    /// and the compilation's expect mode, so every body shares them.
    reassigned_binders_memo: std.AutoHashMapUnmanaged(ReassignedBinderAddress, ReassignedBinderSpan) = .empty,
    /// Whether each checked type reaches the error type (see
    /// `checkedTypeContainsError`).
    checked_type_contains_error: std.AutoHashMapUnmanaged(CheckedTypeAddress, bool) = .empty,
    /// Whether each checked type is representation-fixed (see
    /// `checkedTypeRepresentationFixed`).
    checked_type_representation_fixed: std.AutoHashMapUnmanaged(CheckedTypeAddress, bool) = .empty,
    /// Each scheme's quantified variables by slot, keyed by the scheme's
    /// variable list, for resolving an enclosing variable to its evidence
    /// frame's substitution.
    scheme_var_slots: std.AutoHashMapUnmanaged(SchemeVarsAddress, std.AutoHashMapUnmanaged(checked.CheckedTypeId, u32)) = .empty,
    reassigned_binder_pool: std.ArrayList(checked.PatternBinderId) = .empty,
    const_expr_cache: std.AutoHashMap(ConstExprAddress, Ast.ExprId),
    static_data_ids: std.AutoHashMap(StaticDataUse, Common.StaticDataId),
    /// Static-data uses indexed by `StaticDataId`. These types have crossed the
    /// ordered commit boundary; raw ids are only a fast exact-key path, while
    /// structural equality remains the reuse authority across instantiations.
    static_data_uses: std.ArrayList(StaticDataUse),
    static_data_eligibility: std.AutoHashMap(ConstNodeAddress, bool),
    hosted_catalog: []HostedCatalogEntry = &.{},
    /// Exact `(owner, method)` -> target map over every reachable module's
    /// method registry, for compiler-generated component lookups (structural
    /// derivation internals, inspect/parser/encode helpers, path synthesis).
    /// Built once; keys use the same program-name interning as `typeDef`, so
    /// owners derived from monomorphic type content correlate directly.
    /// Scoped method-target resolutions. The same owner and method pair may
    /// resolve to different targets depending on which module's method-lookup
    /// registry scope applies. Checked modules output the ordered registry
    /// scope; this memo only accelerates repeated exact lookups during the
    /// build and never changes the checked outcome.
    scoped_method_targets: std.AutoHashMapUnmanaged(ScopedMethodDispatch, ScopedMethodResolution) = .{},
    /// Scoped inspect-override resolutions, memoized like
    /// `scoped_method_targets`. `null` means inspection renders the owner's
    /// default form.
    scoped_inspect_overrides: std.AutoHashMapUnmanaged(ScopedMethodDispatch, ?MethodLookup) = .{},
    /// Exact checked identity of the compiler-provided `Try` nominal. `Try`
    /// deliberately retains nominal static-dispatch ownership, so it cannot use
    /// `builtin_owner`; structural parser lowering still needs its producer
    /// identity to distinguish optional fields from user nominals that declare
    /// a custom `parser_for` method.
    builtin_try_def: ?QualifiedTypeDef = null,
    u64_ty: ?Type.TypeId = null,
    bool_ty: ?Type.TypeId = null,
    /// The specialization graph currently being lowered. Template body
    /// requests made anywhere inside that specialization defer to its end,
    /// when its types are final and specialization keys are stable.
    active_graph: ?*InstGraph = null,
    /// Body draft owned by `active_graph`. Nested functions and procedure
    /// bodies that explicitly depend on local lexical evidence append here;
    /// context-free procedure requests retain only their live interfaces and
    /// resolve after this graph seals.
    active_body_draft: ?*BodyDraftStore = null,
    /// The globally reserved root owned by `active_graph`, if that graph is
    /// lowering a procedure body. Its explicit ownership and initial argument
    /// classes classify recursive calls without folding unrelated sibling
    /// requests together.
    active_template_root: ?ActiveTemplateRoot = null,
    final_body_output_allowance: FinalBodyOutputCounts = .{},
    /// Owns every materialized `SpecEvidence` tree; freed wholesale with the
    /// builder.
    evidence_arena: std.heap.ArenaAllocator,
    /// The stored form `constFnEvidence` last produced for each innermost
    /// evidence vector, which callers lowering one request pass repeatedly.
    const_evidence_memo: std.AutoHashMap(ConstEvidenceMemoKey, StoredConstFnEvidence),
    /// Stored conversions by `Ast.fnEvidenceBucket`, each checked for exact
    /// equality before reuse.
    const_evidence_by_content: std.AutoHashMap(u64, StoredConstFnEvidence),
    /// Site evidence derived where it cannot depend on the lowering context
    /// (`BodyContext.deriveSiteEvidenceVector`).
    site_evidence_memo: std.AutoHashMap(SiteEvidenceMemoKey, SiteEvidenceMemo),
    /// Whether a checked substitution span holds only ground types.
    checked_span_ground: std.AutoHashMap(CheckedSpanKey, bool),

    /// The store this scope emits restored const expressions into.
    fn constEmit(self: *Builder) *Ast.Program {
        return self.program;
    }

    /// Const restoration must intern names in the destination program.
    fn constNameStore(self: *Builder) *names.NameStore {
        return self.activeNameStore();
    }

    /// Pin the active type/name destination to the coordinator program for a
    /// scope whose inputs and outputs are program ids. A reservation claimed by
    /// an immediate caller completes wherever that caller was lowering, which
    /// can be inside an ordinary specialization shard whose private workspace
    /// is the active destination—but the completion itself is coordinator
    /// work either way: it reads `lower_fn_ty`, a program id, and writes the
    /// program's definitions. Without this pin, a type lowered for that
    /// completion would land in the workspace and then be compared against
    /// program ids, which is an out-of-bounds read in debug and an arbitrary
    /// in-bounds read—a wrong type, silently—in release.
    const ProgramTypeDestination = struct {
        builder: *Builder,
        saved: bool,

        fn begin(builder: *Builder) ProgramTypeDestination {
            if (builder.spec_job_parallel_callback) {
                Common.compilerBug("parallel specialization worker opened a coordinator type destination");
            }
            const saved = builder.force_program_type_destination;
            builder.force_program_type_destination = true;
            return .{ .builder = builder, .saved = saved };
        }

        fn end(self: ProgramTypeDestination) void {
            self.builder.force_program_type_destination = self.saved;
        }
    };

    fn hasPrivateTypeDestination(self: *const Builder) bool {
        if (self.force_program_type_destination) return false;
        const draft = self.active_body_draft orelse return false;
        const workspace = draft.spec_job_workspace orelse return false;
        if (workspace.active_epoch == null) return false;
        if (self.active_graph == null) {
            Common.compilerBug("active specialization workspace has no ordinary body destination");
        }
        return true;
    }

    fn activeTypeStore(self: *Builder) *Type.Store {
        if (self.hasPrivateTypeDestination()) return &self.active_body_draft.?.spec_job_workspace.?.types;
        return &self.program.types;
    }

    fn activeNameStore(self: *Builder) *names.NameStore {
        if (self.hasPrivateTypeDestination()) return &self.active_body_draft.?.spec_job_workspace.?.name_store;
        return &self.program.names;
    }

    fn activeCheckedTypeCache(self: *Builder) *std.AutoHashMap(CheckedTypeAddress, Type.TypeId) {
        if (self.hasPrivateTypeDestination()) return &self.active_body_draft.?.spec_job_workspace.?.checked_type_cache;
        return &self.type_cache;
    }

    /// This scope's expression-data type for restored const values.
    const ConstExprData = Ast.ExprData;
    const ConstExprId = Ast.ExprId;
    const ConstExprSpan = Ast.Span(Ast.ExprId);
    const ConstFieldExpr = Ast.FieldExpr;
    const ConstFieldExprSpan = Ast.Span(Ast.FieldExpr);

    /// This scope's mapping from a stored scalar to expression data.
    fn constScalarData(_: *Builder, scalar: checked.ConstScalar) ConstExprData {
        return restoreScalar(Ast.ExprData, scalar);
    }

    /// An empty compile-time list restores as the `with_capacity` it was
    /// evaluated with, so the first append at runtime goes in place; one
    /// evaluated with no capacity is the empty literal.
    fn constEmptyListData(self: *Builder, capacity: u64) Allocator.Error!ConstExprData {
        if (capacity == 0) return .{ .list = try self.program.addExprSpan(&[0]Ast.ExprId{}) };
        const requested = try self.program.addExpr(.{ .ty = try self.primitiveType(.u64), .data = restoreScalar(Ast.ExprData, .{ .u64 = capacity }) });
        return .{ .low_level = .{ .op = .list_with_capacity, .args = try self.program.addExprSpan(&.{requested}) } };
    }

    fn init(allocator: Allocator, modules: Common.CheckedModules, program: *Ast.Program, options: Options) Builder {
        const counters = options.specialization_counters orelse
            if (options.diagnostics) |diagnostics| &diagnostics.specialization else null;
        const raw_spec_job_run_id = next_spec_job_run_id.fetchAdd(1, .monotonic);
        if (raw_spec_job_run_id == std.math.maxInt(u32)) {
            Common.compilerBug("Monotype specialization run identity overflow");
        }
        var spec_store = specialize.SpecBuilder.init(allocator, &program.names, &program.types, &program.specs);
        spec_store.counters = counters;
        return .{
            .allocator = allocator,
            .spec_job_run_id = @fromBackingInt(@intCast(raw_spec_job_run_id)),
            .modules = modules,
            .root_view = checked.importedView(modules.root.module),
            .module_index = std.AutoHashMap([32]u8, ModuleIndexSlot).init(allocator),
            .source_file_ids = SourceFileIds.init(allocator),
            .lowering_module_ids = LoweringModuleIds.init(allocator),
            .program = program,
            .current_loc = program.current_loc,
            .current_region = program.current_region,
            .proc_debug_names = options.proc_debug_names,
            .spec_cache = options.spec_cache,
            .counters = counters,
            .diagnostics = options.diagnostics,
            .active_spec_job_diagnostics = null,
            .inline_expects = options.inline_expects,
            .static_data_literals = options.static_data_literals,
            .comptime_value_reads = options.comptime_value_reads,
            .literal_roots = options.literal_roots,
            .declared_comptime_root_functions = DeclaredComptimeRootFunctions.init(allocator),
            .post_check_executor = options.post_check_executor,
            .timing = options.timing,
            .type_cache = std.AutoHashMap(CheckedTypeAddress, Type.TypeId).init(allocator),
            .interface_summaries = InterfaceSummaryCache.init(allocator),
            .spec_store = spec_store,
            .lowered_templates = collections.DenseMap(Ast.FnId, LoweredTemplate).init(allocator),
            .function_scan_path = collections.DenseMap(Type.TypeId, void).init(allocator),
            .resolved_callable_vectors = std.AutoHashMap(u64, std.ArrayList([]const SpecEvidence)).init(allocator),
            .lowered_nested_by_fn = collections.DenseMap(Ast.FnId, Ast.SpecId).init(allocator),
            .nested_site_cache = std.AutoHashMap(NestedSiteAddress, names.ProcSiteId).init(allocator),
            .const_expr_cache = std.AutoHashMap(ConstExprAddress, Ast.ExprId).init(allocator),
            .static_data_ids = std.AutoHashMap(StaticDataUse, Common.StaticDataId).init(allocator),
            .static_data_uses = .empty,
            .static_data_eligibility = std.AutoHashMap(ConstNodeAddress, bool).init(allocator),
            .evidence_arena = std.heap.ArenaAllocator.init(allocator),
            .const_evidence_memo = std.AutoHashMap(ConstEvidenceMemoKey, StoredConstFnEvidence).init(allocator),
            .const_evidence_by_content = std.AutoHashMap(u64, StoredConstFnEvidence).init(allocator),
            .site_evidence_memo = std.AutoHashMap(SiteEvidenceMemoKey, SiteEvidenceMemo).init(allocator),
            .checked_span_ground = std.AutoHashMap(CheckedSpanKey, bool).init(allocator),
        };
    }

    const SourceFileSeed = struct {
        key: checked.ModuleId,
        name: []const u8,
        qualified_name: []const u8,

        fn lessThan(_: void, left: SourceFileSeed, right: SourceFileSeed) bool {
            switch (std.mem.order(u8, left.qualified_name, right.qualified_name)) {
                .lt => return true,
                .gt => return false,
                .eq => {},
            }
            return std.mem.lessThan(u8, &left.key.bytes, &right.key.bytes);
        }
    };

    /// Every checked module in the lowering input, ordered by qualified module
    /// name and then checked module identity. Module indices are local to
    /// independently checked environments, and cannot identify source files
    /// across those environments. Scheduling cannot decide source-file order.
    fn canonicalSourceFiles(self: *Builder) Allocator.Error![]SourceFileSeed {
        const capacity = 1 + self.modules.imports.len + self.modules.root.relation_modules.len;
        var seeds = try std.ArrayList(SourceFileSeed).initCapacity(self.allocator, capacity);
        errdefer seeds.deinit(self.allocator);
        try self.source_file_ids.ensureTotalCapacity(@intCast(capacity));
        try self.lowering_module_ids.ensureTotalCapacity(@intCast(capacity));
        self.appendSourceFileSeed(&seeds, self.rootModuleView());
        for (0..self.modules.imports.len) |index| {
            self.appendSourceFileSeed(&seeds, self.importModuleView(index));
        }
        for (0..self.modules.root.relation_modules.len) |index| {
            self.appendSourceFileSeed(&seeds, self.relationModuleView(index));
        }
        std.mem.sort(SourceFileSeed, seeds.items, {}, SourceFileSeed.lessThan);
        return seeds.toOwnedSlice(self.allocator);
    }

    fn appendSourceFileSeed(
        self: *Builder,
        seeds: *std.ArrayList(SourceFileSeed),
        view: ModuleView,
    ) void {
        const gop = self.source_file_ids.getOrPutAssumeCapacity(view.key.bytes);
        if (gop.found_existing) return;
        // The sorted final ordinal replaces this reservation before workers
        // can borrow the table. Use the same index for deduplication and lookup.
        gop.value_ptr.* = @intCast(seeds.items.len);
        seeds.appendAssumeCapacity(.{
            .key = view.key,
            .name = view.module_env.module_name,
            .qualified_name = view.module_env.qualifiedModuleName(),
        });
    }

    /// Coordinator only: seed the ordered source-file and checked-module
    /// tables in the program before any body is lowered. Both completed lookup
    /// tables remain immutable until all workers have finished this lowering
    /// run, so a worker's rows name the same owners the coordinator's do.
    fn seedProgramModuleTables(self: *Builder) Allocator.Error!void {
        std.debug.assert(self.borrowed_source_file_ids == null);
        std.debug.assert(self.borrowed_lowering_module_ids == null);
        std.debug.assert(self.source_file_ids.count() == 0);
        std.debug.assert(self.lowering_module_ids.count() == 0);
        if (self.program.sourceFileCount() != 0) {
            Common.invariant("Monotype program source files were seeded after lowering began");
        }
        if (self.program.lowering_modules.len() != 0) {
            Common.invariant("Monotype program checked modules were seeded after lowering began");
        }
        const seeds = try self.canonicalSourceFiles();
        defer self.allocator.free(seeds);
        try self.program.source_files.ensureUnusedCapacity(self.allocator, seeds.len);
        try self.program.lowering_modules.ensureUnusedCapacity(self.allocator, seeds.len);
        for (seeds, 0..) |seed, index| {
            const id = try self.program.addSourceFile(.{
                .name = seed.name,
                .qualified_name = seed.qualified_name,
                .module_identity = seed.key.module_identity_hash,
            });
            if (id != index) Common.invariant("Monotype program source file id did not match its sorted position");
            self.source_file_ids.getPtr(seed.key.bytes).?.* = id;
            const module_id = try self.program.addLoweringModule(seed.key);
            self.lowering_module_ids.putAssumeCapacity(seed.key.bytes, module_id);
        }
    }

    fn sourceFileIds(self: *const Builder) *const SourceFileIds {
        return self.borrowed_source_file_ids orelse &self.source_file_ids;
    }

    fn loweringModuleIds(self: *const Builder) *const LoweringModuleIds {
        return self.borrowed_lowering_module_ids orelse &self.lowering_module_ids;
    }

    /// Dense id of the checked module that owns a module-local checked id.
    fn loweringModuleId(self: *const Builder, key: checked.ModuleId) Common.LoweringModuleId {
        return self.loweringModuleIds().get(key.bytes) orelse
            Common.invariant("checked module reached lowering without a seeded lowering module id");
    }

    /// Final program source-file id of a checked module's source locations.
    fn sourceFileId(self: *const Builder, view: ModuleView) u32 {
        return self.sourceFileIds().get(view.key.bytes) orelse
            Common.invariant("checked module reached body lowering without an assigned source file id");
    }

    fn ensureSpecJobWorkerBuilder(
        worker: *SpecJobWorkerState,
        inputs: *const SpecJobWorkerInputs,
    ) Allocator.Error!*Builder {
        if (worker.input_program == null) worker.input_program = try worker.allocator.create(Ast.Program);
        worker.input_program.?.* = inputs.snapshot.workerProgram(worker.allocator);
        if (worker.builder) |builder| {
            builder.coordinator_interface_summaries = inputs.interface_summaries;
            builder.coordinator_interface_summary_end = inputs.interface_summary_end;
            return builder;
        }

        const builder = try worker.allocator.create(Builder);
        errdefer worker.allocator.destroy(builder);
        builder.* = Builder.init(worker.allocator, inputs.modules, worker.input_program.?, .{
            .proc_debug_names = inputs.proc_debug_names,
            .specialization_counters = if (inputs.collect_counters) &worker.counters else null,
            .diagnostics = if (inputs.collect_diagnostics) &worker.diagnostics else null,
            .inline_expects = inputs.inline_expects,
            .static_data_literals = inputs.static_data_literals,
            .comptime_value_reads = inputs.comptime_value_reads,
            .literal_roots = inputs.literal_roots,
            .post_check_executor = null,
            .timing = null,
        });
        errdefer builder.deinit();
        builder.borrowed_source_file_ids = inputs.source_file_ids;
        builder.borrowed_module_views = inputs.module_views;
        builder.borrowed_lowering_module_ids = inputs.lowering_module_ids;
        builder.borrowed_comptime_root_functions = inputs.declared_comptime_root_functions;
        builder.hosted_catalog = try worker.allocator.dupe(HostedCatalogEntry, inputs.hosted_catalog);
        builder.current_loc = inputs.current_loc;
        builder.current_region = inputs.current_region;
        builder.coordinator_interface_summaries = inputs.interface_summaries;
        builder.coordinator_interface_summary_end = inputs.interface_summary_end;
        worker.builder = builder;
        return builder;
    }

    fn deinitSpecJobLaneState(opaque_state: *anyopaque) void {
        const state: *SpecJobLaneState = @ptrCast(@alignCast(opaque_state));
        const allocator = state.worker.allocator;
        state.deinit();
        allocator.destroy(state);
    }

    fn ensureSpecJobLaneState(
        executor_worker: base.post_check_task_executor.Worker,
        inputs: *const SpecJobWorkerInputs,
    ) Allocator.Error!*SpecJobLaneState {
        const key: *const anyopaque = @ptrCast(&SpecJobLaneStateKey.value);
        if (executor_worker.lane_state.get(key)) |opaque_state| {
            const state: *SpecJobLaneState = @ptrCast(@alignCast(opaque_state));
            if (@backingInt(state.worker.worker_id) != executor_worker.id) {
                Common.compilerBug("Monotype lane state moved between executor workers");
            }
            if (state.run_id != inputs.run_id) {
                state.deinit();
                state.* = SpecJobLaneState.init(
                    executor_worker.allocator,
                    @fromBackingInt(@intCast(executor_worker.id)),
                    inputs.run_id,
                );
            }
            return state;
        }

        if (executor_worker.id >= std.math.maxInt(u32)) {
            Common.compilerBug("post-check executor returned an invalid specialization worker id");
        }
        const state = try executor_worker.allocator.create(SpecJobLaneState);
        state.* = SpecJobLaneState.init(
            executor_worker.allocator,
            @fromBackingInt(@intCast(executor_worker.id)),
            inputs.run_id,
        );
        errdefer {
            state.deinit();
            executor_worker.allocator.destroy(state);
        }
        try executor_worker.lane_state.put(key, state, deinitSpecJobLaneState);
        return state;
    }

    fn deinit(self: *Builder) void {
        var parametric_masks = self.parametric_scheme_vars.valueIterator();
        while (parametric_masks.next()) |mask| self.allocator.free(mask.*);
        self.parametric_scheme_vars.deinit(self.allocator);
        var nominal_masks = self.nominal_parameter_value_masks.valueIterator();
        while (nominal_masks.next()) |mask| if (mask.*) |values| self.allocator.free(values);
        self.nominal_parameter_value_masks.deinit(self.allocator);
        self.source_file_ids.deinit();
        self.lowering_module_ids.deinit();
        self.declared_comptime_root_functions.deinit();
        self.module_index.deinit();
        self.spec_job_task_buffers.deinit(self.allocator);
        if (self.spec_job_commit_domain) |*domain| domain.deinit();
        if (self.spec_job_worker) |*worker| worker.deinit();
        self.scoped_method_targets.deinit(self.allocator);
        self.scoped_inspect_overrides.deinit(self.allocator);
        self.allocator.free(self.hosted_catalog);
        self.static_data_eligibility.deinit();
        self.static_data_uses.deinit(self.allocator);
        self.static_data_ids.deinit();
        self.const_expr_cache.deinit();
        self.nested_site_cache.deinit();
        self.reassigned_binders_memo.deinit(self.allocator);
        self.checked_type_contains_error.deinit(self.allocator);
        self.checked_type_representation_fixed.deinit(self.allocator);
        var scheme_var_slots = self.scheme_var_slots.valueIterator();
        while (scheme_var_slots.next()) |slots| slots.deinit(self.allocator);
        self.scheme_var_slots.deinit(self.allocator);
        self.reassigned_binder_pool.deinit(self.allocator);
        self.lowered_nested_by_fn.deinit();
        self.lowered_templates.deinit();
        self.function_mentions.deinit(self.allocator);
        self.function_scan_path.deinit();
        var resolved_vectors = self.resolved_callable_vectors.valueIterator();
        while (resolved_vectors.next()) |vectors| vectors.deinit(self.allocator);
        self.resolved_callable_vectors.deinit();
        if (self.shared_summaries) |*summaries| summaries.deinit();
        self.worker_inputs.deinit(self.allocator);
        self.interface_summaries.deinit();
        self.spec_store.deinit();
        self.pending_spec_jobs.deinit(self.allocator);
        self.type_cache.deinit();
        self.const_evidence_memo.deinit();
        self.const_evidence_by_content.deinit();
        self.site_evidence_memo.deinit();
        self.checked_span_ground.deinit();
        self.evidence_arena.deinit();
        // Workers borrow these views, so they go last.
        self.allocator.free(self.module_views);
    }

    fn count(self: *Builder, comptime field: []const u8) void {
        if (self.counters) |counters| {
            @field(counters, field) += 1;
        }
    }

    fn countBy(self: *Builder, comptime field: []const u8, amount: usize) void {
        if (self.counters) |counters| {
            @field(counters, field) += @intCast(amount);
        }
    }

    /// The slot of `variable` among a scheme's quantified variables. Small
    /// schemes are scanned; larger ones are indexed once per compilation.
    fn schemeVarSlot(
        self: *Builder,
        scheme_vars: []const checked.CheckedTypeId,
        variable: checked.CheckedTypeId,
    ) Allocator.Error!?u32 {
        const scan_limit = 16;
        if (scheme_vars.len <= scan_limit) {
            for (scheme_vars, 0..) |scheme_var, slot| {
                if (scheme_var == variable) return @intCast(slot);
            }
            return null;
        }
        const entry = try self.scheme_var_slots.getOrPut(self.allocator, .{
            .ptr = @intFromPtr(scheme_vars.ptr),
            .len = scheme_vars.len,
        });
        if (!entry.found_existing) {
            entry.value_ptr.* = .empty;
            errdefer _ = self.scheme_var_slots.remove(entry.key_ptr.*);
            try entry.value_ptr.ensureTotalCapacity(self.allocator, @intCast(scheme_vars.len));
            // The first slot of a repeated variable answers, as a scan would.
            var slot = scheme_vars.len;
            while (slot > 0) {
                slot -= 1;
                entry.value_ptr.putAssumeCapacity(scheme_vars[slot], @intCast(slot));
            }
        }
        return entry.value_ptr.get(variable);
    }

    fn countBodyDiagnostic(self: *Builder, comptime field: []const u8) void {
        if (self.bodyDiagnosticSink()) |body| {
            @field(body, field) += 1;
        }
    }

    fn countBodyDiagnosticBy(self: *Builder, comptime field: []const u8, amount: usize) void {
        if (self.bodyDiagnosticSink()) |body| {
            @field(body, field) += @intCast(amount);
        }
    }

    fn countCoordinatorBodyDiagnostic(self: *Builder, comptime field: []const u8) void {
        if (self.diagnostics) |diagnostics| {
            @field(diagnostics.body, field) += 1;
        }
    }

    fn bodyDiagnosticSink(self: *Builder) ?*BodyDiagnostics {
        if (self.active_spec_job_diagnostics) |diagnostics| return &diagnostics.body;
        if (self.diagnostics) |diagnostics| return &diagnostics.body;
        return null;
    }

    fn graphDiagnosticSink(self: *Builder) ?*solve.GraphDiagnostics {
        if (self.active_spec_job_diagnostics) |diagnostics| return &diagnostics.graph;
        if (self.diagnostics) |diagnostics| return &diagnostics.graph;
        return null;
    }

    fn allocateInstantiationScope(self: *Builder) InstantiationScopeId {
        if (self.next_instantiation_scope == std.math.maxInt(u64)) {
            Common.invariant("Monotype instantiation scope identity exhausted");
        }
        const id: InstantiationScopeId = @fromBackingInt(@intCast(self.next_instantiation_scope));
        self.next_instantiation_scope += 1;
        self.countBodyDiagnostic("instantiation_scopes_created");
        return id;
    }

    fn createGraph(self: *Builder) Allocator.Error!*InstGraph {
        return self.createGraphForStores(&self.program.types, &self.program.names);
    }

    fn createGraphForStore(self: *Builder, types_: *Type.Store) Allocator.Error!*InstGraph {
        return self.createGraphForStores(types_, &self.program.names);
    }

    fn createGraphForStores(
        self: *Builder,
        types_: *Type.Store,
        name_store: *names.NameStore,
    ) Allocator.Error!*InstGraph {
        const graph = try InstGraph.create(self.allocator, types_, name_store);
        if (self.bodyDiagnosticSink()) |body| {
            body.graphs_created += 1;
        }
        if (self.graphDiagnosticSink()) |graph_diagnostics| {
            graph.setDiagnostics(graph_diagnostics);
        }
        return graph;
    }

    /// Borrow the graph tied to this worker lane, resetting only per-body
    /// solver state while retaining its allocated capacity and store identity.
    fn acquireSpecJobGraph(
        self: *Builder,
        worker: *SpecJobWorkerState,
    ) Allocator.Error!*InstGraph {
        if (worker.graph) |graph| {
            if (graph.types != &worker.workspace.types or
                graph.name_store != &worker.workspace.name_store)
            {
                Common.compilerBug("Monotype worker graph changed lane-local stores");
            }
            graph.reset();
            if (self.graphDiagnosticSink()) |graph_diagnostics| {
                graph.setDiagnostics(graph_diagnostics);
            }
            return graph;
        }
        const graph = try self.createGraphForStores(
            &worker.workspace.types,
            &worker.workspace.name_store,
        );
        worker.graph = graph;
        return graph;
    }

    fn specializationTypeDigest(self: *Builder, ty: Type.TypeId) names.TypeDigest {
        return self.specializationTypeDigestIn(&self.program.types, &self.program.names, ty);
    }

    fn codecContractIdentity(
        self: *Builder,
        contract: ?SealedCodecContractContext,
    ) ?Ast.CodecContractIdentity {
        const actual = contract orelse return null;
        return .{
            .module = .{ .bytes = actual.anchor.view.key.bytes },
            .derivation = actual.anchor.derivation,
            .kind = switch (actual.anchor.kind) {
                .parser => .parser,
                .encoder => .encoder,
            },
            .constructor_ty_digest = self.specializationTypeDigest(actual.constructor_ty),
            .constructor_ty = actual.constructor_ty,
            .shape_ty_digest = self.specializationTypeDigest(actual.shape_ty),
            .shape_ty = actual.shape_ty,
        };
    }

    fn commitInterfaceSummaries(self: *Builder, entries: []const InterfaceSummaryEntry, committed_types: *CommittedGraphTypes) Allocator.Error!void {
        if (entries.len == 0) return;
        // Relocate every settled leaf in one import and interning transaction.
        // The copies below then reuse that complete relocation map.
        var roots = std.ArrayList(Type.TypeId).empty;
        defer roots.deinit(self.allocator);
        for (entries) |entry| {
            try roots.appendSlice(self.allocator, entry.request.leaves);
            const summary = switch (entry.summary) {
                .unchanged => continue,
                .constraints => |constraints| constraints,
            };
            for (summary.nodes) |node| switch (node) {
                .mono => |ty| try roots.append(self.allocator, ty),
                .open => {},
            };
            for (summary.open_nodes) |node| {
                if (node.finished) |ty| try roots.append(self.allocator, ty);
            }
        }
        const committed = try committed_types.commitTypes(self.allocator, roots.items);
        defer self.allocator.free(committed);
        const relocation = InterfaceSummaryRelocation{
            .source_names = committed_types.source_names,
            .destination_names = &self.program.names,
            .committed = committed_types,
        };
        var scratch = std.heap.ArenaAllocator.init(self.allocator);
        defer scratch.deinit();
        for (entries) |entry| {
            _ = scratch.reset(.retain_capacity);
            const summary = try entry.summary.copy(scratch.allocator(), relocation);
            _ = try self.interface_summaries.insert(&self.program.types, &self.program.names, .{
                .address = entry.address,
                .evidence = entry.evidence,
                .request = try entry.request.copy(scratch.allocator(), relocation),
                .summary = summary,
            });
        }
    }

    fn addDigestStats(self: *Builder, stats: Type.Store.DigestStats) void {
        self.countBy("all_digest_root_requests", @intCast(stats.root_requests));
        self.countBy("all_digest_node_misses", @intCast(stats.cache_misses));
        self.countBy("commit_digest_root_requests", @intCast(stats.commit_root_requests));
        self.countBy("commit_digest_node_misses", @intCast(stats.commit_node_misses));
    }

    fn specializationTypeDigestIn(
        self: *Builder,
        types_: *Type.Store,
        name_store: *const names.NameStore,
        ty: Type.TypeId,
    ) names.TypeDigest {
        // Every consumer resolves collisions with typeEql. Checked type ids
        // and other stored provenance must not split equal requests into
        // different buckets as worker-local representatives change.
        if (self.counters != null) {
            self.count("specialization_type_digest_requests");
            var stats: Type.Store.DigestStats = .{};
            const digest = types_.equalityDigestCached(name_store, ty, &stats);
            self.addDigestStats(stats);
            self.countBy("specialization_type_digest_cache_hits", @intCast(stats.cache_hits));
            self.countBy("specialization_type_digest_cache_misses", @intCast(stats.cache_misses));
            self.countBy("specialization_type_digest_nodes_visited", @intCast(stats.nodes_visited));
            return digest;
        }
        return types_.equalityDigestCached(name_store, ty, null);
    }

    fn graphCaptureAbiDigest(
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
        capture_nodes: []const NodeId,
    ) Allocator.Error!names.TypeDigest {
        var hasher = TypeDigestHasher.init();
        hasher.update("roc.monotype.capture_abi");
        hashU32(&hasher, @intCast(capture_nodes.len));
        for (capture_nodes) |node| {
            const ty = try sealer.sealNode(node);
            const digest = graph.types.typeDigest(graph.name_store, ty);
            hasher.update(&digest.bytes);
        }
        return .{ .bytes = hasher.finalResult() };
    }

    fn initHostedCatalog(self: *Builder) Allocator.Error!void {
        var entries = std.ArrayList(HostedCatalogEntry).empty;
        defer entries.deinit(self.allocator);

        try self.appendHostedCatalogFromView(&entries, self.rootModuleView());
        for (self.modules.imports, 0..) |imported, index| {
            if (self.importModuleAlreadyScanned(imported.key, index)) continue;
            try self.appendHostedCatalogFromView(&entries, self.importModuleView(index));
        }
        for (self.modules.root.relation_modules, 0..) |relation, index| {
            if (self.relationModuleAlreadyScanned(relation.key, index)) continue;
            try self.appendHostedCatalogFromView(&entries, self.relationModuleView(index));
        }

        if (self.hostedBindingView()) |binding_view| {
            // The platform header's hosted section is the complete list of
            // functions the host supplies, and it is what gives each one its
            // external symbol and dispatch slot. Retain declarations omitted
            // from that list as explicitly unavailable: they have no host slot
            // and lower to error bodies, preserving checking's section error.
            var declared_by_target = std.AutoHashMap(HostedProcedureKey, usize).init(self.allocator);
            defer declared_by_target.deinit();
            try declared_by_target.ensureTotalCapacity(@intCast(entries.items.len));
            for (entries.items, 0..) |entry, index| {
                declared_by_target.putAssumeCapacityNoClobber(.{
                    .checked_module_digest = entry.target_checked_module_digest,
                    .def_idx = entry.def_idx,
                }, index);
            }

            for (binding_view.table.bindings, 0..) |binding, dispatch_index| {
                const entry_index = declared_by_target.get(.{
                    .checked_module_digest = binding.target_checked_module.bytes,
                    .def_idx = @backingInt(binding.target_def),
                }) orelse Common.invariant("hosted section names a function with no hosted declaration in scope");
                const entry = &entries.items[entry_index];
                entry.binding = .{ .mapped = @intCast(dispatch_index) };
                entry.external_symbol_name = try self.program.names.internExternalSymbolName(
                    binding_view.names.externalSymbolNameText(binding.external_symbol_name),
                );
            }

            // Retain every declaration: an omitted declaration is explicitly
            // unavailable, never a missing catalog lookup or invented host slot.
            self.hosted_catalog = try entries.toOwnedSlice(self.allocator);
            return;
        }

        // Without a platform header there is no section to bind against, so
        // every declaration in scope is its own dispatch slot in a stable order.
        const SortContext = struct {
            pub fn lessThan(_: void, a: HostedCatalogEntry, b: HostedCatalogEntry) bool {
                return switch (std.mem.order(u8, a.order, b.order)) {
                    .lt => true,
                    .gt => false,
                    .eq => if (a.def_idx != b.def_idx)
                        a.def_idx < b.def_idx
                    else
                        std.mem.order(u8, &a.target_checked_module_digest, &b.target_checked_module_digest) == .lt,
                };
            }
        };
        std.mem.sort(HostedCatalogEntry, entries.items, {}, SortContext.lessThan);
        for (entries.items, 0..) |*entry, index| {
            entry.binding = .{ .mapped = @intCast(index) };
        }

        self.hosted_catalog = try entries.toOwnedSlice(self.allocator);
    }

    fn hostedBindingView(self: *Builder) ?HostedBindingView {
        const root = self.rootModuleView();
        if (root.module_identity.kind == .platform) {
            return .{ .table = root.hosted_bindings, .names = root.names };
        }
        for (0..self.modules.imports.len) |index| {
            const view = self.importModuleView(index);
            if (view.module_identity.kind == .platform) {
                return .{ .table = view.hosted_bindings, .names = view.names };
            }
        }
        for (0..self.modules.root.relation_modules.len) |index| {
            const view = self.relationModuleView(index);
            if (view.module_identity.kind == .platform) {
                return .{ .table = view.hosted_bindings, .names = view.names };
            }
        }
        return null;
    }

    fn appendHostedCatalogFromView(self: *Builder, entries: *std.ArrayList(HostedCatalogEntry), view: ModuleView) Allocator.Error!void {
        for (view.hosted_procs.procs) |proc| {
            try entries.append(self.allocator, .{
                .template = proc.template,
                .external_symbol_name = try self.program.names.internExternalSymbolName(view.names.externalSymbolNameText(proc.external_symbol_name)),
                .binding = .unavailable,
                .order = proc.orderKey(view.hosted_procs),
                .target_checked_module_digest = view.key.bytes,
                .def_idx = @backingInt(proc.def_idx),
            });
        }
    }

    fn hostedEntry(self: *Builder, template: names.ProcTemplate) HostedCatalogEntry {
        for (self.hosted_catalog) |entry| {
            if (names.procedureTemplateRefEql(entry.template, template)) return entry;
        }
        Common.invariant("hosted procedure template was not output in the hosted catalog");
    }

    fn hostedFn(self: *Builder, template: names.ProcTemplate) Ast.HostedFn {
        const entry = self.hostedEntry(template);
        return .{
            .template = template,
            .external_symbol_name = entry.external_symbol_name,
            .dispatch_index = switch (entry.binding) {
                .mapped => |index| index,
                .unavailable => Common.invariant("unavailable hosted declaration reached extern emission"),
            },
        };
    }

    fn fnDefForHostedTemplate(self: *Builder, template: names.ProcTemplate, is_local: bool) Ast.FnDef {
        return switch (self.hostedEntry(template).binding) {
            .unavailable => .{ .checked_generated = template },
            .mapped => if (is_local)
                .{ .local_hosted = self.hostedFn(template) }
            else
                .{ .imported_hosted = self.hostedFn(template) },
        };
    }

    /// Whether an extern boundary may be emitted at `emitted_fn_ty`: the host
    /// ABI (design.md "Host Symbol ABI") admits the hosted declaration's own
    /// checked type, lowered here as `declared_fn_ty`, and nothing else.
    ///
    /// The comparison is the authoritative structural one, not a type digest. A
    /// digest encodes a cycle by the position it closes at, so a recursive
    /// nominal reached through differently shared nodes digests differently
    /// while describing one runtime type—and a hosted argument is exactly
    /// where that happens, since the declared lowering and the request build
    /// their graphs separately. test/fx/host_boxed_fn_boundary.roc passes a
    /// recursive nominal to a hosted function and covers that case.
    ///
    /// A hosted declaration written with type variables is a scheme rather than
    /// one type, and the host's single C signature covers every instantiation
    /// because each variable position is a pointer at runtime. For those, the
    /// declaration's variable slots accept whatever the request instantiated
    /// them to, while every position the declaration made concrete is still
    /// compared exactly.
    fn hostedExternMatchesDeclaredAbi(
        self: *Builder,
        declared_fn_ty: Type.TypeId,
        emitted_fn_ty: Type.TypeId,
        mode: Type.TypeMatchMode,
    ) Allocator.Error!bool {
        return try self.program.types.typeMatches(&self.program.names, declared_fn_ty, emitted_fn_ty, mode);
    }

    /// The match mode a hosted declaration's own checked type calls for.
    fn hostedDeclaredAbiMatchMode(
        self: *Builder,
        view: ModuleView,
        declared_checked_fn_ty: checked.CheckedTypeId,
    ) Allocator.Error!Type.TypeMatchMode {
        return if (try self.hostedDeclarationIsGeneric(view, declared_checked_fn_ty))
            .declared_variable_slots_match_any
        else
            .exact;
    }

    /// Whether a hosted declaration's checked type still contains type
    /// variables. A variable that carries a numeric or row default is not one:
    /// it lowers to the same concrete type for every use, so the declaration is
    /// concrete there.
    fn hostedDeclarationIsGeneric(
        self: *Builder,
        view: ModuleView,
        checked_ty: checked.CheckedTypeId,
    ) Allocator.Error!bool {
        var seen = collections.DenseMap(checked.CheckedTypeId, void).init(self.allocator);
        defer seen.deinit();
        var pending: std.ArrayListUnmanaged(checked.CheckedTypeId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, checked_ty);
        while (pending.pop()) |ty| {
            if ((try seen.getOrPut(ty)).found_existing) continue;
            const start = pending.items.len;
            switch (checkedPayload(view, ty)) {
                .flex, .rigid => |variable| {
                    if (variable.numeric_default_phase == null and variable.row_default == null) return true;
                },
                .pending, .err, .empty_record, .empty_tag_union => {},
                .alias => |alias| {
                    try pending.appendSlice(self.allocator, alias.args);
                    try pending.append(self.allocator, alias.backing);
                },
                // A nominal's runtime shape follows from its declaration and its
                // arguments, so the arguments carry every variable a use can fill.
                .nominal => |nominal| try pending.appendSlice(self.allocator, nominal.args),
                .record => |record| {
                    for (record.fields) |field| try pending.append(self.allocator, field.ty);
                    try pending.append(self.allocator, record.ext);
                },
                .tuple => |items| try pending.appendSlice(self.allocator, items),
                .tag_union => |tag_union| {
                    for (tag_union.tags) |tag| try pending.appendSlice(self.allocator, tag.argsSlice(view.types));
                    try pending.append(self.allocator, tag_union.ext);
                },
                .function => |fn_ty| {
                    try pending.appendSlice(self.allocator, fn_ty.args);
                    try pending.append(self.allocator, fn_ty.ret);
                },
            }
            std.mem.reverse(checked.CheckedTypeId, pending.items[start..]);
        }
        return false;
    }

    /// Stop the build unless this hosted specialization emits its extern at
    /// the declared host ABI type.
    ///
    /// The host was compiled against the declared signature. An extern emitted
    /// at any other type reads the host's return value at a layout the host
    /// never wrote—the app sees `Err` where the host returned `Ok`—and
    /// nothing downstream can tell that apart from a genuine `Err`. So this is
    /// a producer-side stop, in release builds as well as debug ones: whatever
    /// upstream stage widened, narrowed, or re-represented the request, its
    /// output never reaches codegen.
    fn requireHostedExternAtDeclaredAbi(
        self: *Builder,
        view: ModuleView,
        template: names.ProcTemplate,
        declared_checked_fn_ty: checked.CheckedTypeId,
        declared_fn_ty: Type.TypeId,
        emitted_fn_ty: Type.TypeId,
    ) Allocator.Error!void {
        const mode = try self.hostedDeclaredAbiMatchMode(view, declared_checked_fn_ty);
        if (try self.hostedExternMatchesDeclaredAbi(declared_fn_ty, emitted_fn_ty, mode)) return;
        var message_buf: [hosted_extern_abi_message_max]u8 = undefined;
        Common.compilerBug(hostedExternAbiViolationMessage(
            &message_buf,
            self.program.names.externalSymbolNameText(self.hostedFn(template).external_symbol_name),
            self.program.types.typeDigest(&self.program.names, declared_fn_ty),
            self.program.types.typeDigest(&self.program.names, emitted_fn_ty),
        ));
    }

    fn typeName(self: *Builder, view: ModuleView, id: names.TypeNameId) Allocator.Error!names.TypeNameId {
        return self.activeNameStore().internTypeName(view.names.typeNameText(id));
    }

    fn moduleIdentity(self: *Builder, view: ModuleView, id: names.ModuleIdentityId) Allocator.Error!names.ModuleIdentityId {
        return self.activeNameStore().internModuleIdentity(view.names.moduleIdentityBytes(id));
    }

    fn recordFieldName(self: *Builder, view: ModuleView, id: names.RecordFieldNameId) Allocator.Error!names.RecordFieldNameId {
        return self.activeNameStore().internRecordFieldLabel(view.names.recordFieldLabelText(id));
    }

    fn tagName(self: *Builder, view: ModuleView, id: names.TagNameId) Allocator.Error!names.TagNameId {
        return self.activeNameStore().internTagLabel(view.names.tagLabelText(id));
    }

    fn hostedTryAdapterCapability(
        self: *Builder,
        view: ModuleView,
        checked_capability: ?checked.HostedTryAdapterCapability,
    ) Allocator.Error!?HostedTryAdapterCapability {
        const capability = checked_capability orelse return null;
        // `try_error_type_arg_index` names the cell the widening relation opens
        // and the cell the adapter re-tags; `err_type_arg_index` is the same
        // index carried from the checker. Cross-check them once, here, so the
        // two cannot drift into opening one cell and re-tagging another.
        if (capability.err_type_arg_index != try_error_type_arg_index) {
            Common.compilerBug("checker-recorded Try error type-argument index disagreed with the widening relation's");
        }
        return .{
            .def = try self.typeDef(
                view,
                capability.nominal.module,
                capability.nominal.type_name,
                capability.nominal.source_decl,
            ),
            .ok_tag = try self.tagName(view, capability.ok_tag),
            .err_tag = try self.tagName(view, capability.err_tag),
            .ok_type_arg_index = capability.ok_type_arg_index,
            .err_type_arg_index = capability.err_type_arg_index,
        };
    }

    fn typeDef(
        self: *Builder,
        view: ModuleView,
        origin_module: names.ModuleIdentityId,
        type_name: names.TypeNameId,
        source_decl: ?u32,
    ) Allocator.Error!Type.TypeDef {
        return .{
            .module = try self.moduleIdentity(view, origin_module),
            .type_name = try self.typeName(view, type_name),
            .source_decl = source_decl,
        };
    }

    fn declaredModuleForNominal(_: *Builder, _: ModuleView, nominal: checked.CheckedNominalType) names.CheckedModuleDigest {
        return moduleDigestFromId(nominal.owner_module);
    }

    fn lowerRoot(self: *Builder, request: checked.RootRequest, source_module: checked.ModuleId) Allocator.Error!void {
        const source_view = self.moduleForId(source_module);
        const def = if (request.procedure_binding) |binding|
            try self.lowerProcedureBindingRoot(request, binding, source_view)
        else if (request.procedure_template) |template|
            try self.lowerTemplate(template, source_view, request.checked_type, request.root_evidence)
        else if (request.procedure_use) |procedure|
            try self.lowerProcedureUseRoot(request, procedure, source_module)
        else
            Common.invariant("root request reached Monotype without a checked procedure template or procedure source");
        try self.appendRuntimeSchemaRequestsForDef(def);
        try self.program.addRoot(.{ .def = def, .request = request, .owner = self.loweringModuleId(source_module) });
    }

    /// Procedure-use runs are the only isolated roots without an ordered
    /// coordinator dependency; every other root kind remains a serial barrier.
    fn lowerIsolatedRoots(self: *Builder, requests: []const checked.RootRequest, source_modules: []const checked.ModuleId) Allocator.Error!void {
        if (source_modules.len != 0 and source_modules.len != requests.len) {
            Common.invariant("root source module count differs from explicit request count");
        }
        if (self.comptime_value_reads) {
            for (requests, 0..) |request, i| {
                if (request.abi != .compile_time) continue;
                const root_id = request.compile_time_root orelse
                    Common.invariant("shared compile-time request lacked its checked root identity");
                const source_module = self.rootSourceModule(source_modules, i);
                const source_view = self.moduleForId(source_module);
                const template = request.procedure_template orelse
                    Common.invariant("shared compile-time root lacked its declared entry template");
                const def = try self.lowerTemplate(template, source_view, request.checked_type, request.root_evidence);
                const key = EntryRoot{ .module = source_module, .root = root_id };
                const entry = try self.declared_comptime_root_functions.getOrPut(key);
                const fn_id = self.defFnId(def);
                if (entry.found_existing and entry.value_ptr.* != fn_id) {
                    Common.invariant("checked compile-time root reserved different functions for one declared root");
                }
                entry.value_ptr.* = fn_id;
            }
        }
        const executor = self.post_check_executor orelse {
            for (requests, 0..) |request, i| try self.lowerRoot(request, self.rootSourceModule(source_modules, i));
            return;
        };
        if (executor.worker_count <= 1) {
            for (requests, 0..) |request, i| try self.lowerRoot(request, self.rootSourceModule(source_modules, i));
            return;
        }
        var index: usize = 0;
        while (index < requests.len) {
            if (requests[index].procedure_use == null) {
                try self.lowerRoot(requests[index], self.rootSourceModule(source_modules, index));
                index += 1;
                continue;
            }
            const start = index;
            while (index < requests.len and
                requests[index].procedure_use != null and
                index - start < executor.worker_count) : (index += 1)
            {}
            try self.lowerProcedureRootBatch(executor, requests[start..index], if (source_modules.len == 0) &.{} else source_modules[start..index]);
        }
    }

    fn captureSpecJobInputs(self: *Builder) Allocator.Error!WorkerInputs.Snapshot {
        if (self.shared_summaries == null) self.shared_summaries = SharedSummaries.init(self.allocator);
        const summaries = &self.shared_summaries.?;
        for (self.interface_summaries.entries.items[summaries.count..]) |entry| {
            try summaries.insert(entry.address, entry);
        }
        return self.worker_inputs.capture(self.allocator, self.program);
    }

    fn rootSourceModule(self: *Builder, source_modules: []const checked.ModuleId, index: usize) checked.ModuleId {
        return if (source_modules.len == 0) self.root_view.key else source_modules[index];
    }

    /// Run a frozen root batch to completion before committing its first root,
    /// so callbacks can never overlap coordinator mutation.
    fn lowerProcedureRootBatch(
        self: *Builder,
        executor: base.post_check_task_executor.Executor,
        requests: []const checked.RootRequest,
        source_modules: []const checked.ModuleId,
    ) Allocator.Error!void {
        const contexts = try self.allocator.alloc(ProcedureRootTaskContext, requests.len);
        defer self.allocator.free(contexts);
        const tasks = try self.allocator.alloc(base.post_check_task_executor.Task, requests.len);
        defer self.allocator.free(tasks);
        const completions = try self.allocator.alloc(base.post_check_task_executor.Completion, requests.len);
        defer self.allocator.free(completions);
        const snapshot = try self.captureSpecJobInputs();
        const inputs = SpecJobWorkerInputs{
            .run_id = self.spec_job_run_id,
            .modules = self.modules,
            .module_views = self.moduleViews(),
            .source_file_ids = self.sourceFileIds(),
            .lowering_module_ids = self.loweringModuleIds(),
            .snapshot = &snapshot,
            .proc_debug_names = self.proc_debug_names,
            .interface_summaries = &self.shared_summaries.?,
            .interface_summary_end = self.shared_summaries.?.count,
            .collect_counters = self.counters != null,
            .collect_diagnostics = self.diagnostics != null,
            .inline_expects = self.inline_expects,
            .static_data_literals = self.static_data_literals,
            .comptime_value_reads = self.comptime_value_reads,
            .literal_roots = self.literal_roots,
            .declared_comptime_root_functions = self.borrowed_comptime_root_functions orelse &self.declared_comptime_root_functions,
            .hosted_catalog = self.hosted_catalog,
            .current_loc = self.current_loc,
            .current_region = self.current_region,
            .timing_std_io = if (self.timing) |timing| timing.std_io else null,
        };
        for (requests, 0..) |request, task_id| {
            contexts[task_id] = .{
                .inputs = &inputs,
                .request = request,
                .source_module = self.rootSourceModule(source_modules, task_id),
            };
            tasks[task_id] = .{ .id = task_id, .context = &contexts[task_id], .run = runProcedureRootTask };
        }
        defer for (contexts) |*context| {
            if (context.shard) |*shard| shard.deinit();
        };
        if (self.timing) |timing| {
            timing.parallel.root_tasks_submitted +%= @intCast(requests.len);
            timing.parallel.task_waves +%= 1;
            timing.parallel.peak_worker_lanes_available = @max(
                timing.parallel.peak_worker_lanes_available,
                @as(u64, @intCast(executor.worker_count)),
            );
        }
        var run_error: ?Allocator.Error = null;
        {
            var wait_timing_scope = ProcedureTimingScope.begin(self.timing, .parallel_wait);
            defer wait_timing_scope.end();
            executor.run(tasks, completions) catch |err| {
                run_error = err;
            };
        }
        self.recordParallelWorkerWork(contexts);
        if (run_error) |err| return err;

        var commit_timing_scope = ParallelCoordinatorTimingScope.begin(self.timing);
        defer commit_timing_scope.end();
        for (completions) |completion| {
            if (completion.id >= contexts.len) Common.compilerBug("post-check executor returned an unknown root task");
            const context = &contexts[completion.id];
            if (context.completed) Common.compilerBug("post-check executor completed a root task more than once");
            if (completion.value != @as(?*anyopaque, @ptrCast(context))) {
                Common.compilerBug("post-check executor returned the wrong root task context");
            }
            context.completed = true;
            if (context.shard) |*shard| {
                if (@backingInt(shard.worker_id) != completion.worker_id) {
                    Common.compilerBug("post-check executor changed root worker ownership");
                }
            }
        }
        for (contexts) |*context| {
            if (!context.completed) Common.compilerBug("post-check executor omitted a root completion");
            if (context.failed) return error.OutOfMemory;
        }
        for (contexts) |*context| {
            const def = try self.commitCompletedProcedureRootShard(&context.shard.?);
            try self.appendRuntimeSchemaRequestsForDef(def);
            try self.program.addRoot(.{ .def = def, .request = context.request, .owner = self.loweringModuleId(context.source_module) });
            if (self.timing) |timing| timing.parallel.root_tasks_committed +%= 1;
            context.shard.?.deinit();
            context.shard = null;
        }
    }

    fn lowerLayoutRequest(self: *Builder, checked_ty: checked.CheckedTypeId) Allocator.Error!void {
        const ty = try self.lowerType(self.rootModuleView(), checked_ty);
        try self.program.addLayoutRequest(.{
            .checked_type = checked_ty,
            .ty = ty,
        });
        try self.appendRuntimeSchemaRequestsForType(ty);
    }

    fn lowerStaticDataRequest(self: *Builder, request: Common.StaticDataRequest) Allocator.Error!void {
        const type_view = self.rootModuleView();
        const ret_ty = try self.lowerType(type_view, request.checked_type);
        const body = body: {
            // Provided exports request the whole checked constant before its
            // evaluation completes. Their initializer aliases the declared
            // declared slot; it must not restore the still-pending ConstStore.
            if (request.node == null and self.comptime_value_reads) {
                const view = self.moduleForId(checked.constModuleId(request.const_locator));
                const root_id = switch (request.const_locator.owner) {
                    .top_level_binding => |owner| view.compile_time_roots.lookupIdByPattern(owner.pattern),
                    .hoisted_expr => |owner| if (view.hoisted_constants.lookupByExpr(owner.expr)) |entry| entry.root else null,
                };
                if (root_id) |root| {
                    if (self.comptimeValueReadDeclared(view, root)) {
                        const owners = self.borrowed_comptime_root_functions orelse &self.declared_comptime_root_functions;
                        const fn_id = owners.get(.{ .module = view.key, .root = root }).?;
                        const initializer = try self.program.addExpr(.{
                            .ty = ret_ty,
                            .data = .{ .call_proc = .{ .callee = Ast.localProcCallee(fn_id), .args = .empty() } },
                        });
                        break :body try self.program.addExpr(.{
                            .ty = ret_ty,
                            .data = .{ .comptime_value = .{
                                .root = try self.program.addComptimeValueRoot(.{ .module = view.key, .root = .{ .checked = root }, .const_locator = request.const_locator }),
                                .initializer = initializer,
                            } },
                        });
                    }
                }
            }
            const const_node = self.constNode(request.const_locator, request.node);
            break :body try self.restoreConstNodeAtTypeWithStaticRoot(const_node.module, type_view, const_node.id, ret_ty, request.const_locator);
        };
        const def = try self.program.addDef(.{
            .symbol = self.symbols.fresh(),
            .fn_def = null,
            .root_identity = self.staticDataRequestIdentity(type_view, request, ret_ty),
            .args = Ast.Span(Ast.TypedLocal).empty(),
            .body = .{ .roc = body },
            .ret = ret_ty,
        });
        try self.program.addLayoutRequest(.{
            .checked_type = request.checked_type,
            .ty = ret_ty,
            .def = def,
            .const_locator = request.const_locator,
        });
        try self.appendRuntimeSchemaRequestsForType(ret_ty);
    }

    fn appendRuntimeSchemaRequestsForDef(self: *Builder, def: Ast.DefId) Allocator.Error!void {
        const fn_ = self.program.getDef(def);
        const args = self.program.typedLocalSpan(fn_.args);
        for (0..GuardedList.borrowLen(args)) |index| {
            const arg = GuardedList.at(args, index);
            try self.appendRuntimeSchemaRequestsForType(arg.ty);
        }
        try self.appendRuntimeSchemaRequestsForType(fn_.ret);
    }

    fn appendRuntimeSchemaRequestsForType(self: *Builder, ty: Type.TypeId) Allocator.Error!void {
        var active = collections.DenseMap(Type.TypeId, void).init(self.allocator);
        defer active.deinit();
        try self.appendRuntimeSchemaRequestsForTypeInner(ty, &active);
    }

    /// Request a runtime schema for every named type reachable from `ty`
    /// that is backed by a record or tag union, in source order, from an
    /// explicit work list.
    fn appendRuntimeSchemaRequestsForTypeInner(
        self: *Builder,
        root: Type.TypeId,
        active: *collections.DenseMap(Type.TypeId, void),
    ) Allocator.Error!void {
        const Step = union(enum) { ty: Type.TypeId, request: Ast.RuntimeSchemaRequest };
        var pending: std.ArrayListUnmanaged(Step) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, .{ .ty = root });
        while (pending.pop()) |step| {
            const ty = switch (step) {
                .request => |request| {
                    try self.appendRuntimeSchemaRequest(request);
                    continue;
                },
                .ty => |ty| ty,
            };
            if (active.contains(ty)) continue;
            try active.put(ty, {});

            const start = pending.items.len;
            switch (self.program.types.get(ty)) {
                .named => |named| {
                    const args = self.program.types.span(named.args);
                    for (0..GuardedList.borrowLen(args)) |index| {
                        try pending.append(self.allocator, .{ .ty = GuardedList.at(args, index) });
                    }
                    if (named.backing) |backing| {
                        if (backing.use == .inspectable and self.runtimeSchemaBackedByRecordOrTagUnion(backing.ty)) {
                            try pending.append(self.allocator, .{ .request = .{ .def = named.def, .ty = ty } });
                        }
                        try pending.append(self.allocator, .{ .ty = backing.ty });
                    }
                },
                .record => |fields| {
                    const field_span = self.program.types.fieldSpan(fields);
                    for (0..GuardedList.borrowLen(field_span)) |index| {
                        try pending.append(self.allocator, .{ .ty = GuardedList.at(field_span, index).ty });
                    }
                },
                .tuple => |items| {
                    const item_span = self.program.types.span(items);
                    for (0..GuardedList.borrowLen(item_span)) |index| {
                        try pending.append(self.allocator, .{ .ty = GuardedList.at(item_span, index) });
                    }
                },
                .tag_union => |tags| {
                    const tag_span = self.program.types.tagSpan(tags);
                    for (0..GuardedList.borrowLen(tag_span)) |tag_index| {
                        const payload_span = self.program.types.span(GuardedList.at(tag_span, tag_index).payloads);
                        for (0..GuardedList.borrowLen(payload_span)) |payload_index| {
                            try pending.append(self.allocator, .{ .ty = GuardedList.at(payload_span, payload_index) });
                        }
                    }
                },
                .list,
                .box,
                => |elem| try pending.append(self.allocator, .{ .ty = elem }),
                .func => |func| {
                    const args = self.program.types.span(func.args);
                    for (0..GuardedList.borrowLen(args)) |index| {
                        try pending.append(self.allocator, .{ .ty = GuardedList.at(args, index) });
                    }
                    try pending.append(self.allocator, .{ .ty = func.ret });
                },
                .primitive,
                .erased,
                .zst,
                => {},
            }
            std.mem.reverse(Step, pending.items[start..]);
        }
    }

    fn runtimeSchemaBackedByRecordOrTagUnion(self: *Builder, ty: Type.TypeId) bool {
        var current = ty;
        while (true) switch (self.program.types.get(current)) {
            .record,
            .tag_union,
            => return true,
            .named => |named| {
                const backing = named.backing orelse return false;
                if (backing.use != .inspectable) return false;
                current = backing.ty;
            },
            .primitive, .tuple, .list, .box, .func, .erased, .zst => return false,
        };
    }

    fn appendRuntimeSchemaRequest(self: *Builder, request: Ast.RuntimeSchemaRequest) Allocator.Error!void {
        try appendRuntimeSchemaRequestToProgram(self.program, request);
    }

    fn lowerProcedureUseRoot(
        self: *Builder,
        request: checked.RootRequest,
        procedure: checked.ProcedureUseTemplate,
        source_module: checked.ModuleId,
    ) Allocator.Error!Ast.DefId {
        const worker = self.ensureSerialSpecJobWorker();
        var shard = try self.lowerProcedureUseRootToShard(
            worker,
            self.ensureSpecJobCommitDomain(),
            request,
            procedure,
            source_module,
        );
        defer shard.deinit();
        return self.commitCompletedProcedureRootShard(&shard);
    }

    /// Produce a root entirely in a worker epoch, sealing every graph-qualified
    /// cell before the lane retains its graph for the next task.
    fn lowerProcedureUseRootToShard(
        self: *Builder,
        worker: *SpecJobWorkerState,
        commit_domain: *SpecJobCommitDomain,
        request: checked.RootRequest,
        procedure: checked.ProcedureUseTemplate,
        source_module: checked.ModuleId,
    ) Allocator.Error!CompletedProcedureRootShard {
        if (self.symbols.active != .coordinator) {
            Common.compilerBug("procedure root shard entered with a worker-local symbol domain active");
        }
        self.symbols.worker_local = .{};
        self.symbols.active = .worker_local;
        defer self.symbols.active = .coordinator;
        const workspace = &worker.workspace;
        var digest_stats: Type.Store.DigestStats = .{};
        workspace.types.digest_stats = if (self.counters != null) &digest_stats else null;
        defer {
            workspace.types.digest_stats = null;
            self.addDigestStats(digest_stats);
        }
        const epoch = workspace.beginEpoch(self.program);
        errdefer workspace.finishEpoch(epoch);
        const program_types_before = self.program.types.epochBoundary();
        const program_names_before = self.program.names.epochBoundary();
        const program_loc_before = self.program.current_loc;
        const program_region_before = self.program.current_region;
        const shard_diagnostics: ?*SpecJobDiagnostics = if (self.diagnostics != null) blk: {
            const diagnostics = try self.allocator.create(SpecJobDiagnostics);
            diagnostics.* = .{};
            break :blk diagnostics;
        } else null;
        errdefer if (shard_diagnostics) |diagnostics| self.allocator.destroy(diagnostics);
        self.active_spec_job_diagnostics = shard_diagnostics;
        defer self.active_spec_job_diagnostics = null;
        const view = self.moduleForId(source_module);
        const callable_eval = self.callableEvalForProcedureUse(procedure);
        const template_ref = if (callable_eval) |use| blk: {
            const raw = @backingInt(use.template);
            if (raw >= use.view.callable_eval_templates.templates.len) {
                Common.invariant("callable eval procedure use referenced a missing checked template");
            }
            const template = use.view.callable_eval_templates.templates[raw];
            const wrapper = use.view.entry_wrappers.lookupByRoot(template.root) orelse
                Common.invariant("callable eval procedure use root had no checked entry wrapper");
            break :blk wrapper.template;
        } else self.templateRefForProcedureUse(procedure);
        var graph_setup_timing_scope = ProcedureTimingScope.begin(self.timing, .body_graph_setup);
        defer graph_setup_timing_scope.end();
        const graph = try self.acquireSpecJobGraph(worker);
        const saved_graph = self.active_graph;
        const saved_body_draft = self.active_body_draft;
        self.active_graph = graph;
        defer self.active_graph = saved_graph;
        var body_draft = BodyDraftStore.init(self.allocator);
        errdefer body_draft.deinit();
        body_draft.spec_job_workspace = workspace;
        body_draft.mutable_graph_names = &workspace.name_store;
        self.active_body_draft = &body_draft;
        defer self.active_body_draft = saved_body_draft;
        var ctx = try BodyContext.init(self.allocator, self, view, template_ref, graph, &body_draft);
        defer ctx.deinit();

        const root_node = try ctx.instNode(request.checked_type);
        const initial_fn = try graph.functionNodes(root_node);
        const args = try self.allocator.alloc(DraftTypedLocal, initial_fn.args.len);
        defer self.allocator.free(args);
        const arg_exprs = try self.allocator.alloc(DraftExprId, initial_fn.args.len);
        defer self.allocator.free(arg_exprs);

        for (initial_fn.args, 0..) |arg_node, index| {
            const arg_cell = DraftTypeCell.fromGraphNode(arg_node);
            const local = try ctx.addLocalWithBinderCell(self.symbols.fresh(), arg_cell, null);
            args[index] = .{ .local = local, .ty = arg_cell };
            arg_exprs[index] = try ctx.addExprWithTypeCell(arg_cell, .{ .local = local });
        }
        graph_setup_timing_scope.end();

        const draft = FinalBodyOutputGuard.begin(self);
        var body_timing_scope = ProcedureTimingScope.begin(self.timing, .body_lowering);
        defer body_timing_scope.end();
        const body, const ret_cell = if (callable_eval) |use| blk: {
            const callee = try ctx.lowerCallableEvalBindingValueAtNode(
                use.view,
                use.template,
                root_node,
                &.{},
            );
            const completed_fn = try graph.functionNodes(root_node);
            const completed_ret = DraftTypeCell.fromGraphNode(completed_fn.ret);
            break :blk .{
                try ctx.addExprWithTypeCell(completed_ret, .{
                    .call_value = .{
                        .callee = callee,
                        .args = try body_draft.addExprSpan(arg_exprs),
                    },
                }),
                completed_ret,
            };
        } else blk: {
            const callee, const completed_fn = dispatch: {
                var dispatch_timing_scope = ProcedureTimingScope.begin(self.timing, .dispatch_evidence);
                defer dispatch_timing_scope.end();
                const edge = if (request.root_evidence) |root_evidence|
                    try ctx.checkedProcedureEdgeAtRequest(template_ref, root_evidence, root_node, .body_lowering)
                else
                    EdgeEvidence{ .subst = &.{}, .vector = &.{} };
                const selected = try ctx.draftFnSlotForProcedureUseAtNode(
                    procedure,
                    request.checked_type,
                    procedure.source_fn_ty_template,
                    root_node,
                    edge,
                    false,
                );
                const callee_fn_node = try ctx.draftFnSlotTypeNode(selected, root_node);
                try relateFunctionRequestInterface(graph, root_node, callee_fn_node);
                break :dispatch .{ selected, try graph.functionNodes(root_node) };
            };
            const completed_ret = DraftTypeCell.fromGraphNode(completed_fn.ret);
            break :blk .{
                try ctx.addExprWithTypeCell(completed_ret, .{
                    .call_proc = .{
                        .callee = draftProcCalleeForSlot(callee),
                        .args = try body_draft.addExprSpan(arg_exprs),
                    },
                }),
                completed_ret,
            };
        };
        const root_def = try body_draft.reserveDef(.root);
        body_draft.setDef(root_def, .{
            .symbol = self.symbols.fresh(),
            .fn_def = null,
            .fn_id = null,
            .identity_seed = .{ .kind = "procedure-use-root", .extra = procedureUseRootIdentity(request, procedure, source_module) },
            .args = try body_draft.addTypedLocalSpan(args),
            .body = .{ .roc = body },
            .ret = ret_cell,
        });
        body_timing_scope.end();
        const draft_end = draft.end(self);
        try self.finalizeBodyDraftGraph(graph, &body_draft, draft, draft_end);
        const root_ty = seal: {
            var phase_b_sealer = GraphTypeFinals.init(graph);
            defer phase_b_sealer.deinit();
            try self.emitDraftDeferredStoredCodecRestores(&body_draft, graph, &phase_b_sealer);
            try self.emitDraftDeferredStructuralSerializations(&body_draft, graph, &phase_b_sealer);
            try self.emitDraftDeferredCallsiteIntrinsics(&body_draft, graph, &phase_b_sealer);
            try self.emitDraftDeferredStructuralEqs(&body_draft, graph, &phase_b_sealer);
            try self.emitDraftDeferredInspects(&body_draft, graph, &phase_b_sealer);
            try body_draft.finishOwnerRuns();
            var sealer = GraphTypeFinals.init(graph);
            defer sealer.deinit();
            try sealDraftCoordinatorIntents(graph, &body_draft, &sealer);
            const sealed_root_ty = try sealer.sealNode(root_node);
            try body_draft.sealTypeCellsInPlace(graph, &sealer);
            body_draft.discardGraphStateAfterSeal();
            body_draft.assertGraphStateDiscarded();
            break :seal sealed_root_ty;
        };
        body_draft.sealWorkerLocalSymbols(self.symbols.worker_local.next);
        if (self.spec_job_parallel_callback) {
            if (!std.meta.eql(program_types_before, self.program.types.epochBoundary()) or
                !std.meta.eql(program_names_before, self.program.names.epochBoundary()))
            {
                Common.compilerBug("parallel root lowering mutated coordinator stores");
            }
            if (!std.meta.eql(program_loc_before, self.program.current_loc) or
                !std.meta.eql(program_region_before, self.program.current_region))
            {
                Common.compilerBug("parallel root lowering mutated coordinator source scratch");
            }
        }
        const summaries = try self.allocator.dupe(InterfaceSummaryEntry, workspace.interface_summaries.entries.items[workspace.captured_interface_summaries..]);
        errdefer self.allocator.free(summaries);
        var store_epoch = try workspace.captureStoreEpoch(epoch);
        workspace.captured_interface_summaries = workspace.interface_summaries.entries.items.len;
        errdefer store_epoch.deinit();
        workspace.finishEpoch(epoch);
        return .{
            .worker_id = worker.worker_id,
            .commit_domain = commit_domain,
            .worker_local_symbol_count = body_draft.worker_local_symbol_count,
            .interface_summaries = summaries,
            .store_epoch = store_epoch,
            .body_draft = body_draft,
            .root_ty = root_ty,
            .root_def = root_def,
            .diagnostics = shard_diagnostics,
        };
    }

    fn lowerProcedureBindingRoot(
        self: *Builder,
        request: checked.RootRequest,
        binding_id: checked.TopLevelProcedureBindingId,
        view: ModuleView,
    ) Allocator.Error!Ast.DefId {
        const fn_ty = try self.lowerType(view, request.checked_type);
        const fn_data = self.functionShape(fn_ty, "procedure binding root had a non-function checked type");
        const arg_tys = self.program.types.span(fn_data.args);
        const args = try self.allocator.alloc(Ast.TypedLocal, arg_tys.len);
        defer self.allocator.free(args);
        const arg_exprs = try self.allocator.alloc(Ast.ExprId, arg_tys.len);
        defer self.allocator.free(arg_exprs);

        for (0..GuardedList.borrowLen(arg_tys)) |i| {
            const arg_ty = GuardedList.at(arg_tys, i);
            const local = try self.program.addLocal(self.symbols.fresh(), arg_ty);
            args[i] = .{ .local = local, .ty = arg_ty };
            arg_exprs[i] = try self.program.addExpr(.{ .ty = arg_ty, .data = .{ .local = local } });
        }

        const binding = view.top_level_procedure_bindings.get(binding_id);
        const body = switch (binding.body) {
            .direct_template => blk: {
                const source_fn_ty = schemeRoot(view, binding.source_scheme, "procedure binding source scheme was not output");
                const fn_template = self.fnDefForProcedureBindingBody(
                    view,
                    binding.body,
                    source_fn_ty,
                    view.types.rootKey(source_fn_ty),
                    fn_ty,
                );
                const callee = try self.lowerFnTemplateCallTarget(view, fn_template, &.{});
                break :blk try self.program.addExpr(.{
                    .ty = fn_data.ret,
                    .data = .{ .call_proc = .{
                        .callee = Ast.procCalleeForSlot(callee),
                        .args = try self.program.addExprSpan(arg_exprs),
                    } },
                });
            },
            .checked_error => try self.program.addExpr(.{
                .ty = fn_data.ret,
                .data = .{ .checked_error = try self.program.addStringLiteral("runtime error") },
            }),
            .callable_eval_template => blk: {
                const callee = try self.lowerProcedureBindingValue(view, binding, fn_ty);
                break :blk try self.program.addExpr(.{
                    .ty = fn_data.ret,
                    .data = .{ .call_value = .{
                        .callee = callee,
                        .args = try self.program.addExprSpan(arg_exprs),
                    } },
                });
            },
        };

        return try self.program.addDef(.{
            .symbol = self.symbols.fresh(),
            .fn_def = null,
            .root_identity = self.procedureBindingRootIdentity(view, binding_id, fn_ty),
            .args = try self.program.addTypedLocalSpan(args),
            .body = .{ .roc = body },
            .ret = fn_data.ret,
        });
    }

    /// Identity of a static-data request thunk: the checked constant it
    /// restores and the Monotype type it restores it at.
    fn staticDataRequestIdentity(self: *Builder, view: ModuleView, request: Common.StaticDataRequest, ret_ty: Type.TypeId) names.TypeDigest {
        var hasher = TypeDigestHasher.init();
        hasher.update("roc.monotype.static-data-request.v1");
        hasher.update(&view.key.bytes);
        hasher.update(&request.const_locator.artifact.bytes);
        switch (request.const_locator.owner) {
            .top_level_binding => |owner| {
                hasher.update("top-level-binding");
                hashU32(&hasher, @backingInt(owner.pattern));
            },
            .hoisted_expr => |owner| {
                hasher.update("hoisted-expr");
                hashU32(&hasher, @backingInt(owner.expr));
            },
        }
        hashU32(&hasher, @backingInt(request.const_locator.template));
        hasher.update(&request.const_locator.source_scheme.bytes);
        if (request.node) |node| {
            hasher.update("node");
            hashU32(&hasher, @backingInt(node));
        } else {
            hasher.update("root");
        }
        hasher.update(&view.types.rootKey(request.checked_type).bytes);
        hasher.update(&self.program.types.specializationDigest(&self.program.names, ret_ty).bytes);
        return .{ .bytes = hasher.finalResult() };
    }

    /// Identity of a procedure-binding root: the checked binding and the
    /// function type it is exposed at.
    fn procedureBindingRootIdentity(self: *Builder, view: ModuleView, binding_id: checked.TopLevelProcedureBindingId, fn_ty: Type.TypeId) names.TypeDigest {
        var hasher = TypeDigestHasher.init();
        hasher.update("roc.monotype.procedure-binding-root.v1");
        hasher.update(&view.key.bytes);
        hashU32(&hasher, @backingInt(binding_id));
        hasher.update(&self.program.types.specializationDigest(&self.program.names, fn_ty).bytes);
        return .{ .bytes = hasher.finalResult() };
    }

    fn lowerProcedureBindingValue(
        self: *Builder,
        view: ModuleView,
        binding: checked.TopLevelProcedureBinding,
        mono_fn_ty: Type.TypeId,
    ) Allocator.Error!Ast.ExprId {
        return switch (binding.body) {
            .direct_template => blk: {
                const source_fn_ty = schemeRoot(view, binding.source_scheme, "procedure binding source scheme was not output");
                const fn_template = self.fnDefForProcedureBindingBody(
                    view,
                    binding.body,
                    source_fn_ty,
                    view.types.rootKey(source_fn_ty),
                    mono_fn_ty,
                );
                const fn_id = try self.lowerFnTemplateDef(view, fn_template, &.{});
                break :blk try self.program.addExpr(.{
                    .ty = self.program.fnSource(fn_id).mono_fn_ty,
                    .data = .{ .fn_def = .{ .fn_id = fn_id } },
                });
            },
            .checked_error => Common.invariant("rejected binding reached Monotype callable consumption"),
            .callable_eval_template => |template_id| try self.lowerCallableEvalBindingValue(view, template_id, mono_fn_ty),
        };
    }

    fn lowerCallableEvalBindingValue(
        self: *Builder,
        view: ModuleView,
        template_id: checked.CallableEvalTemplateId,
        mono_fn_ty: Type.TypeId,
    ) Allocator.Error!Ast.ExprId {
        const raw = @backingInt(template_id);
        if (raw >= view.callable_eval_templates.templates.len) {
            Common.invariant("callable eval binding referenced a missing checked template");
        }
        const template = view.callable_eval_templates.templates[raw];
        const root = view.compile_time_roots.root(template.root);
        return switch (root.payload) {
            .fn_value => |fn_id| try self.restoreConstFnExpr(view, fn_id, mono_fn_ty, null),
            .const_node => |node| try self.restoreConstNodeAtType(view, view, node, mono_fn_ty),
            .pending => try self.lowerPendingCallableEvalBindingValue(view, template, root, mono_fn_ty),
            .discarded, .expect, .runtime => Common.invariant("callable eval binding root output a non-callable payload"),
        };
    }

    const CallableEvalUse = struct {
        view: ModuleView,
        template: checked.CallableEvalTemplateId,
    };

    /// The callable-eval binding behind a procedure use when that binding is
    /// an exact procedure alias, which calls forward through.
    fn forwardingCallableEvalForProcedureUse(self: *Builder, proc: checked.ProcedureUseTemplate) ?CallableEvalUse {
        const callable_eval = self.callableEvalForProcedureUse(proc) orelse return null;
        const template = callable_eval.view.callable_eval_templates.templates[@backingInt(callable_eval.template)];
        return if (template.forwarded_lookup != null) callable_eval else null;
    }

    fn callableEvalForProcedureUse(self: *Builder, proc: checked.ProcedureUseTemplate) ?CallableEvalUse {
        return switch (proc.binding) {
            .top_level => |top_level| blk: {
                const view = self.moduleForId(checked.topLevelProcedureModuleId(top_level));
                const binding = view.top_level_procedure_bindings.get(top_level.binding);
                break :blk switch (binding.body) {
                    .direct_template => null,
                    .checked_error => Common.invariant("rejected binding reached Monotype callable consumption"),
                    .callable_eval_template => |template| .{ .view = view, .template = template },
                };
            },
            .imported => |imported| blk: {
                const view = self.moduleForId(checked.importedProcedureModuleId(imported));
                for (view.exported_procedure_bindings.bindings) |binding| {
                    if (binding.binding.def != imported.def or binding.binding.pattern != imported.pattern) continue;
                    break :blk switch (binding.body) {
                        .direct_template => null,
                        .checked_error => Common.invariant("rejected binding reached Monotype callable consumption"),
                        .callable_eval_template => |template| .{ .view = view, .template = template },
                    };
                }
                Common.invariant("imported procedure binding was not exported by its checked module");
            },
            .hosted => null,
            .platform_required => |required| blk: {
                const view = self.moduleForId(checked.requiredProcedureModuleId(required));
                const binding = view.top_level_procedure_bindings.get(required.procedure_binding);
                break :blk switch (binding.body) {
                    .direct_template => null,
                    .checked_error => Common.invariant("rejected binding reached Monotype callable consumption"),
                    .callable_eval_template => |template| .{ .view = view, .template = template },
                };
            },
        };
    }

    fn lowerPendingCallableEvalBindingValue(
        self: *Builder,
        view: ModuleView,
        template: checked.CallableEvalTemplate,
        root: checked.CompileTimeRoot,
        mono_fn_ty: Type.TypeId,
    ) Allocator.Error!Ast.ExprId {
        const wrapper = view.entry_wrappers.lookupByRoot(template.root) orelse
            Common.invariant("callable eval template root had no checked entry wrapper");

        var graph_setup_timing_scope = ProcedureTimingScope.begin(self.timing, .body_graph_setup);
        defer graph_setup_timing_scope.end();
        const graph = try self.createGraph();
        defer graph.destroy();
        const saved_graph = self.active_graph;
        const saved_body_draft = self.active_body_draft;
        self.active_graph = graph;
        defer self.active_graph = saved_graph;
        var body_draft = BodyDraftStore.init(self.allocator);
        self.active_body_draft = &body_draft;
        defer self.active_body_draft = saved_body_draft;
        defer body_draft.deinit();
        var body_ctx = try BodyContext.init(self.allocator, self, view, wrapper.template, graph, &body_draft);
        defer body_ctx.deinit();
        graph_setup_timing_scope.end();

        const draft = FinalBodyOutputGuard.begin(self);
        var body_timing_scope = ProcedureTimingScope.begin(self.timing, .body_lowering);
        defer body_timing_scope.end();
        const lowered = try body_ctx.lowerPendingCallableEvalBindingValue(
            view,
            template,
            root,
            mono_fn_ty,
        );
        body_timing_scope.end();
        const draft_end = draft.end(self);
        const sealed = try self.sealActiveBodyDraft(graph, &body_draft, draft, draft_end, null, &.{}, null, null, null);
        defer sealed.deinit(self.allocator);
        var completion_timing_scope = ProcedureTimingScope.begin(self.timing, .completion);
        defer completion_timing_scope.end();
        return sealed.ids.expr(lowered);
    }

    fn lowerTemplate(
        self: *Builder,
        template_ref: names.ProcTemplate,
        source_ty_view: ModuleView,
        source_fn_ty: checked.CheckedTypeId,
        root_evidence: ?checked.CheckedEvidenceSpan,
    ) Allocator.Error!Ast.DefId {
        const fn_ty = try self.lowerContextFreeSpecializationType(
            source_ty_view,
            template_ref,
            source_fn_ty,
        );
        const view = self.moduleForDigest(names.procTemplateModuleDigest(template_ref));
        const fn_template = self.fnDefForTemplate(
            view,
            template_ref,
            source_fn_ty,
            source_ty_view.types.rootKey(source_fn_ty),
            fn_ty,
        );
        const evidence: []const SpecEvidence = if (root_evidence) |evidence_ref| blk: {
            var timing_scope = ProcedureTimingScope.begin(self.timing, .dispatch_evidence);
            defer timing_scope.end();
            break :blk (try self.materializeRootProcedureEvidence(fn_template, evidence_ref)).vector;
        } else &.{};
        // A root is requested at the template's own declared type, which no
        // relation ever widened—checked, not assumed.
        try self.requireRequestDidNotWidenResultRow(
            template_ref,
            fn_ty,
            "root template request widened the template's closed checked result row",
        );
        return try self.lowerTemplateWithMono(
            template_ref,
            view,
            source_fn_ty,
            source_ty_view.types.rootKey(source_fn_ty),
            fn_ty,
            evidence,
            null,
            .independent_roots,
            .count,
            null,
            null,
            .queued,
            null,
            false,
        );
    }

    /// Whether every type of a checked span is ground: no variable of any
    /// kind, error, or pending payload is reachable from it.
    fn checkedTypesGround(self: *Builder, view: ModuleView, tys: []const checked.CheckedTypeId) Allocator.Error!bool {
        if (tys.len == 0) return true;
        const key: CheckedSpanKey = .{ .view = @intFromPtr(view), .span = @intFromPtr(tys.ptr), .len = tys.len };
        if (self.checked_span_ground.get(key)) |ground| return ground;
        var pending = std.ArrayList(checked.CheckedTypeId).empty;
        defer pending.deinit(self.allocator);
        var seen = collections.DenseMap(checked.CheckedTypeId, void).init(self.allocator);
        defer seen.deinit();
        try pending.appendSlice(self.allocator, tys);
        const ground = walk: while (pending.pop()) |ty| {
            if ((try seen.getOrPut(ty)).found_existing) continue;
            switch (checkedPayload(view, ty)) {
                .pending, .err, .flex, .rigid => break :walk false,
                .empty_record, .empty_tag_union => {},
                .alias => |alias| {
                    try pending.append(self.allocator, alias.backing);
                    try pending.appendSlice(self.allocator, alias.args);
                },
                .record => |record| {
                    for (record.fields) |field| try pending.append(self.allocator, field.ty);
                    try pending.append(self.allocator, record.ext);
                },
                .tuple => |elems| try pending.appendSlice(self.allocator, elems),
                .nominal => |nominal| {
                    try pending.appendSlice(self.allocator, nominal.args);
                    try pending.appendSlice(self.allocator, nominal.padding_field_types);
                },
                .function => |function| {
                    try pending.appendSlice(self.allocator, function.args);
                    try pending.append(self.allocator, function.ret);
                },
                .tag_union => |tag_union| {
                    for (tag_union.tags) |tag| try pending.appendSlice(self.allocator, tag.argsSlice(view.types));
                    try pending.append(self.allocator, tag_union.ext);
                },
            }
        } else true;
        try self.checked_span_ground.put(key, ground);
        return ground;
    }

    /// Retain the exact dispatch vector selected for a specialization so a
    /// compile-time function value can restore that vector without resolving
    /// its requirements again.
    fn constFnEvidence(self: *Builder, evidence: EvidenceChain) Allocator.Error!StoredConstFnEvidence {
        var nodes = std.ArrayList(check.ConstStore.ConstFnEvidence).empty;
        defer nodes.deinit(self.allocator);
        var chain = std.ArrayList(*const EvidenceChain).empty;
        defer chain.deinit(self.allocator);
        var current: ?*const EvidenceChain = &evidence;
        while (current) |frame| : (current = frame.parent) {
            try chain.append(self.allocator, frame);
        }
        var frames = std.ArrayList(check.ConstStore.ConstFnEvidenceFrame).empty;
        defer frames.deinit(self.allocator);
        var index = chain.items.len;
        var parent: ?u32 = null;
        while (index > 0) {
            index -= 1;
            const frame = chain.items[index];
            const roots_start: u32 = @intCast(nodes.items.len);
            try self.appendConstFnEvidence(&nodes, frame.vector);
            const scope: check.ConstStore.ConstFnEvidenceScope = switch (frame.scope.lexical) {
                .root => .root,
                .generalized => |scope_id| .{ .generalized = @backingInt(scope_id) },
            };
            try frames.append(self.allocator, check.ConstStore.ConstFnEvidenceFrame.init(
                scope,
                parent,
                roots_start,
                @intCast(frame.vector.len),
            ));
            parent = @intCast(frames.items.len - 1);
        }
        // The same request's lowering converts one chain several times. A
        // repeated conversion equal to the last stored form for its innermost
        // vector is that stored form, with its digest already computed.
        const key: ConstEvidenceMemoKey = .{
            .vector = @intFromPtr(evidence.vector.ptr),
            .len = evidence.vector.len,
            .frames = frames.items.len,
        };
        if (self.const_evidence_memo.get(key)) |stored| {
            if (Ast.fnEvidenceEql(stored.nodes, stored.frames, stored.head, nodes.items, frames.items, parent)) return stored;
        }
        // Another request with equal evidence (uses checking replayed from
        // one source) already stored this conversion and its digest.
        const bucket = Ast.fnEvidenceBucket(nodes.items, frames.items, parent);
        if (self.const_evidence_by_content.get(bucket)) |stored| {
            if (Ast.fnEvidenceEql(stored.nodes, stored.frames, stored.head, nodes.items, frames.items, parent)) {
                try self.const_evidence_memo.put(key, stored);
                return stored;
            }
        }
        const stored = StoredConstFnEvidence.init(
            try self.evidence_arena.allocator().dupe(check.ConstStore.ConstFnEvidence, nodes.items),
            try self.evidence_arena.allocator().dupe(check.ConstStore.ConstFnEvidenceFrame, frames.items),
            parent,
        );
        try self.const_evidence_memo.put(key, stored);
        try self.const_evidence_by_content.put(bucket, stored);
        return stored;
    }

    /// Copy committed evidence out of the growable program lists so a lowered
    /// template can compare later requests against its exact topology.
    fn retainFnEvidence(self: *Builder, evidence: StoredConstFnEvidence) Allocator.Error!StoredConstFnEvidence {
        return .{
            .nodes = try self.evidence_arena.allocator().dupe(check.ConstStore.ConstFnEvidence, evidence.nodes),
            .frames = try self.evidence_arena.allocator().dupe(check.ConstStore.ConstFnEvidenceFrame, evidence.frames),
            .head = evidence.head,
            .digest = evidence.digest,
        };
    }

    /// A stored evidence vector whose entries are serializing; `pending`
    /// holds the entry whose nested vector or callable contracts are
    /// serializing above it.
    const ConstFnEvidenceFrame = struct {
        evidence: []const SpecEvidence,
        next: usize = 0,
        pending: ?struct { root_index: usize, stage: enum { nested, contracts }, nested_start: usize } = null,
    };

    /// Serialize an evidence tree in pre-order: each entry's node, its
    /// nested evidence, then its callable contracts. Nested evidence follows
    /// type nesting, so each nested vector is a frame rather than a native
    /// call.
    fn appendConstFnEvidence(
        self: *Builder,
        nodes: *std.ArrayList(check.ConstStore.ConstFnEvidence),
        evidence: []const SpecEvidence,
    ) Allocator.Error!void {
        var frames = std.ArrayList(ConstFnEvidenceFrame).empty;
        defer frames.deinit(self.allocator);
        try frames.append(self.allocator, .{ .evidence = evidence });
        while (true) {
            const frame = &frames.items[frames.items.len - 1];
            if (frame.next == frame.evidence.len) {
                const finished = frames.pop().?;
                if (frames.items.len == 0) return;
                const parent = &frames.items[frames.items.len - 1];
                const pending = parent.pending.?;
                parent.pending = null;
                const entry = parent.evidence[parent.next];
                switch (pending.stage) {
                    .nested => {
                        setConstFnTargetNode(nodes, pending.root_index, entry.target, .{ .resolved = .{
                            .count = @intCast(finished.evidence.len),
                            .subtree_len = @intCast(nodes.items.len - pending.nested_start),
                        } });
                        const contracts = evidenceCallableContracts(entry);
                        if (contracts.len != 0) {
                            parent.pending = .{ .root_index = pending.root_index, .stage = .contracts, .nested_start = nodes.items.len };
                            try frames.append(self.allocator, .{ .evidence = contracts });
                            continue;
                        }
                    },
                    .contracts => setConstFnCallableContractCount(nodes, pending.root_index, finished.evidence.len),
                }
                parent.next += 1;
                continue;
            }
            const entry = frame.evidence[frame.next];
            const root_index = nodes.items.len;
            switch (entry) {
                .target => |target| {
                    try nodes.append(self.allocator, undefined);
                    switch (target.nested) {
                        .synthesize => setConstFnTargetNode(nodes, root_index, target, .from_callable),
                        .resolved => |resolved| {
                            frame.pending = .{ .root_index = root_index, .stage = .nested, .nested_start = nodes.items.len };
                            try frames.append(self.allocator, .{ .evidence = resolved });
                            continue;
                        },
                    }
                },
                .structural => |structural| try nodes.append(self.allocator, .{ .structural = .{
                    .derivation = structural.derivation,
                    .checked = if (structural.checked) |checked_structural| .{
                        .view = .{ .bytes = checked_structural.view.key.bytes },
                        .dispatcher_key = checked_structural.view.types.rootKey(checked_structural.evidence.dispatcher_ty),
                        .dispatcher_ty = checked_structural.evidence.dispatcher_ty,
                        .callable_key = checked_structural.view.types.rootKey(checked_structural.evidence.callable_ty),
                        .callable_ty = checked_structural.evidence.callable_ty,
                        .generated_codec_derivation = checked_structural.evidence.generated_codec_derivation,
                        .generated_codec_identity = codecEvidenceIdentity(checked_structural),
                    } else null,
                } }),
                .from_callable => |use| {
                    try nodes.append(self.allocator, .{ .from_callable = .{
                        .independent_callable = use.independent_callable,
                    } });
                },
                .from_scheme => |index| try nodes.append(self.allocator, .{ .from_scheme = index }),
                .unreachable_value => try nodes.append(self.allocator, .unreachable_value),
                .checked_error => try nodes.append(self.allocator, .checked_error),
            }
            const contracts = evidenceCallableContracts(entry);
            if (contracts.len != 0) {
                frame.pending = .{ .root_index = root_index, .stage = .contracts, .nested_start = nodes.items.len };
                try frames.append(self.allocator, .{ .evidence = contracts });
                continue;
            }
            frame.next += 1;
        }
    }

    fn setConstFnCallableContractCount(nodes: *std.ArrayList(check.ConstStore.ConstFnEvidence), root_index: usize, contract_count: usize) void {
        switch (nodes.items[root_index]) {
            .target => |*target| target.callable_contracts = @intCast(contract_count),
            .structural => |*structural| structural.callable_contracts = @intCast(contract_count),
            .from_callable => |*use| use.callable_contracts = @intCast(contract_count),
            .from_scheme, .unreachable_value, .checked_error => unreachable,
        }
    }

    fn setConstFnTargetNode(
        nodes: *std.ArrayList(check.ConstStore.ConstFnEvidence),
        target_index: usize,
        target: *const SpecEvidenceTarget,
        nested: check.ConstStore.ConstFnNestedEvidence,
    ) void {
        nodes.items[target_index] = .{ .target = .{
            .view = .{ .bytes = target.view.key.bytes },
            .method = target.target,
            .method_callable_key = target.view.types.rootKey(target.target.callable_ty),
            .instantiation = if (target.instantiation) |instantiation| .{
                .view = .{ .bytes = instantiation.view.key.bytes },
                .callable_key = instantiation.view.types.rootKey(instantiation.callable_ty),
                .callable_ty = instantiation.callable_ty,
            } else null,
            .nested = nested,
        } };
    }

    fn completeRootTemplateEvidence(
        self: *Builder,
        view: ModuleView,
        template_ref: names.ProcTemplate,
        template: checked.CheckedProcedureTemplate,
        partial: EdgeEvidence,
    ) Allocator.Error!EdgeEvidence {
        return self.completeRootTemplateEvidenceForPurpose(
            view,
            template_ref,
            template,
            partial,
            .body_lowering,
        );
    }

    fn completeRootTemplateEvidenceForPurpose(
        self: *Builder,
        view: ModuleView,
        template_ref: names.ProcTemplate,
        template: checked.CheckedProcedureTemplate,
        partial: EdgeEvidence,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error!EdgeEvidence {
        var timing_scope = ProcedureTimingScope.begin(self.timing, .dispatch_evidence);
        defer timing_scope.end();

        const graph = try self.createGraph();
        defer graph.destroy();
        var draft = BodyDraftStore.init(self.allocator);
        defer draft.deinit();
        var ctx = try BodyContext.init(self.allocator, self, view, template_ref, graph, &draft);
        defer ctx.deinit();
        ctx.evidence = rootEvidence(template_ref, partial.vector);
        return try ctx.rootEdgeEvidenceForPurpose(view, template_ref, template, purpose);
    }

    fn lowerTemplateWithMono(
        self: *Builder,
        template_ref: names.ProcTemplate,
        method_scope: ModuleView,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        fn_ty: Type.TypeId,
        evidence: []const SpecEvidence,
        /// The request's substitution, or null for a root whose template is
        /// instantiated at its own scheme.
        subst: ?SealedSubstitution,
        signature_relation: Ast.SignatureRelation,
        request_accounting: TemplateRequestAccounting,
        precomputed_request_digest: ?names.TypeDigest,
        retained_topology: ?EvidenceChain,
        body_scheduling: TemplateBodyScheduling,
        codec_contract: ?SealedCodecContractContext,
        widened_result_row: bool,
    ) Allocator.Error!Ast.DefId {
        var lookup_timing_scope = ProcedureTimingScope.begin(self.timing, .lookup_reservation);
        defer lookup_timing_scope.end();

        if (request_accounting == .count) self.count("template_requests");
        const lower_fn_ty = fn_ty;
        const view = self.moduleForDigest(names.procTemplateModuleDigest(template_ref));
        const template = view.templates.get(template_ref.template);
        if (evidence.len > template.evidence_params.len) {
            Common.invariant("procedure specialization received more evidence than its checked requirements");
        }
        const spec_evidence = if (evidence.len == template.evidence_params.len)
            evidence
        else
            (try self.completeRootTemplateEvidence(view, template_ref, template, .{ .subst = &.{}, .vector = evidence })).vector;
        const source_topology: ?EvidenceChain = if (retained_topology) |topology|
            topology
        else
            rootEvidence(template_ref, spec_evidence);
        const identity_topology = source_topology orelse rootEvidence(template_ref, spec_evidence);
        const identity_evidence = try self.constFnEvidence(identity_topology);
        const evidence_digest = identity_evidence.digest;
        const stored_source_topology = if (source_topology != null) identity_evidence else null;
        const request_digest = precomputed_request_digest orelse self.specializationTypeDigest(fn_ty);
        const spec_identity = self.templateSpecIdentity(
            template_ref,
            method_scope.key,
            evidence_digest,
            self.codecContractIdentity(codec_contract),
            fn_ty,
            request_digest,
        );
        if (try self.spec_store.findLocal(spec_identity, specializationEvidenceView(identity_evidence))) |hit| {
            if (request_accounting == .count) self.count("template_hits");
            const existing = self.lowered_templates.get(hit.fn_id) orelse
                Common.invariant("Monotype specialization index found a local template missing from lowering state");
            if (!try specEvidenceVectorEql(self.allocator, existing.evidence, spec_evidence)) {
                Common.invariant("Monotype specialization hit disagreed on dispatch evidence");
            }
            // Two edges that reuse one specialization identity must agree about
            // whether it is a widening adapter. A disagreement would define the
            // callee at one row and call it at another, so it stops the build in
            // every mode (design.md "Result-Row Widening Adapter").
            if (existing.widened_result_row != widened_result_row) {
                Common.compilerBug("Monotype specialization cache hit disagreed on its result-row widening");
            }
            if (stored_source_topology) |requested| {
                const existing_topology = existing.topology orelse
                    Common.invariant("Monotype specialization hit had no explicit evidence topology");
                if (!storedConstFnEvidenceEql(existing_topology, requested)) {
                    Common.invariant("Monotype specialization hit disagreed on lexical evidence topology");
                }
            }
            switch (hit.status) {
                .ready,
                .lowering,
                => {
                    self.promoteFnSignatureRelation(hit.fn_id, signature_relation);
                    return existing.def;
                },
                .reserved => {
                    self.promoteFnSignatureRelation(hit.fn_id, signature_relation);
                    switch (body_scheduling) {
                        // A queued request reuses the reserved id; the body
                        // is already owned by the queue.
                        .queued => return existing.def,
                        // An immediate caller consumes the callee's solved
                        // representation, so it claims the queued body and
                        // lowers it now with the reservation's own winning
                        // seed. The queued job later observes the ready
                        // record and is skipped instead of re-lowered.
                        .immediate => {
                            const job = self.pendingSpecJobFor(hit.fn_id) orelse
                                Common.invariant("reserved Monotype specialization had no queued body to claim");
                            self.spec_store.markLowering(job.spec);
                            try self.completeTemplateReservation(
                                job.reservation,
                                job.fn_template,
                                job.template_ref,
                                self.moduleForId(job.method_scope),
                                job.source_fn_ty,
                                job.source_fn_key,
                                job.fn_ty,
                                job.evidence,
                                job.subst,
                                null,
                                job.signature_relation,
                                job.codec_contract,
                                job.widened_result_row,
                            );
                            return existing.def;
                        },
                    }
                },
            }
        } else {
            if (request_accounting == .count) self.count("template_misses");
        }

        var fn_template = self.fnDefForTemplate(view, template_ref, source_fn_ty, source_fn_key, lower_fn_ty);
        fn_template.evidence_digest = evidence_digest;
        // Only a closed request names a specialization the object cache can
        // hold: a function type in its arguments or result makes the body
        // depend on the program's lambda sets. The request's outer arrow does
        // not: procedure identity selects its source and captures explicitly,
        // independently of the callable set its value joins in the caller.
        // A hosted template has no procedure of its own to cache: callers
        // reach the host directly through its declared ABI.
        if (template.target != .hosted and !try self.monoFnTypeMentionsFunction(lower_fn_ty)) {
            const key = Ast.specIdentityKey(spec_identity);
            fn_template.spec_key = key;
            if (template.provided_low_level) |op| fn_template.procedure_keyed_by_layout = op.procedureKeyedByLayout();
            if (@import("builtin").link_libc and std.c.getenv("ROC_SPEC_CENSUS") != null) {
                const proc_base = view.names.procBase(template_ref.proc_base);
                const name: []const u8 = if (proc_base.export_name) |e| view.names.exportNameText(e) else "?";
                std.debug.print("CENSUS_KEY\t{s}\t{x}\tev={x}\tcodec={x}\treq={x}\tcallable={s}\n", .{ name, key.bytes[0..8], spec_identity.evidence_digest.bytes[0..6], spec_identity.codec_contract_digest.bytes[0..6], spec_identity.request_fn_ty_digest.bytes[0..6], @tagName(spec_identity.callable) });
            }
            if (self.spec_cache) |cache| {
                const relation = if (self.program.platform_requirement_filling) |filling| filling.relation else null;
                if (cache.lookup(key.bytes, relation)) |hit| {
                    fn_template.cached = hit;
                    self.count("spec_cache_hits");
                    if (pack_trace_available and packTraceEnabled()) std.debug.print("lookup monotype key={x} hit\n", .{key.bytes[0..8]});
                } else if (pack_trace_available and packTraceEnabled()) std.debug.print("lookup monotype key={x} miss\n", .{key.bytes[0..8]});
            }
        }
        if (stored_source_topology) |stored_evidence| {
            fn_template.const_evidence = try self.program.addConstFnEvidence(stored_evidence.nodes);
            fn_template.const_evidence_frames = try self.program.addConstFnEvidenceFrames(stored_evidence.frames);
            fn_template.const_evidence_frame_head = stored_evidence.head;
        }

        const ReservedSpec = struct { reservation: TemplateReservation, spec: Ast.SpecId };
        const reserved: ReservedSpec = blk: {
            // This reservation is appended directly to the durable Program even
            // when an enclosing shard is using the worker-local symbol domain.
            const symbol = self.symbols.freshCoordinator();
            try self.registerProcDebugNameForTemplate(symbol, view, template_ref);
            const fn_id = try self.program.addFn(fn_template);
            self.promoteFnSignatureRelation(fn_id, signature_relation);
            // The definition fills once its body lowers; a recursive request
            // that reuses this entry meanwhile reads the requested template,
            // which is the same specialization by construction.
            const def_id = try self.program.addDef(.{
                .symbol = symbol,
                .fn_def = fn_template,
                .fn_id = fn_id,
                .args = Ast.Span(Ast.TypedLocal).empty(),
                .body = .hosted,
                .ret = self.programFunctionShape(lower_fn_ty, "procedure template root type was not a function").ret,
            });
            const spec = try self.addTemplateSpecRecord(
                template_ref,
                method_scope.key,
                identity_evidence,
                lower_fn_ty,
                request_digest,
                self.codecContractIdentity(codec_contract),
                fn_id,
                switch (body_scheduling) {
                    .immediate => .lowering,
                    .queued => .reserved,
                },
            );
            try self.lowered_templates.put(fn_id, .{
                .def = def_id,
                .spec = spec,
                .evidence = spec_evidence,
                .topology = stored_source_topology,
                .widened_result_row = widened_result_row,
            });
            break :blk .{
                .reservation = .{
                    .def = def_id,
                    .fn_id = fn_id,
                    .symbol = symbol,
                },
                .spec = spec,
            };
        };
        const reservation = reserved.reservation;

        switch (body_scheduling) {
            .immediate => {},
            .queued => {
                if (retained_topology != null) {
                    Common.invariant("queued Monotype specialization request cannot carry a retained lexical topology");
                }
                const dispatch_index = self.next_spec_dispatch_index;
                try self.pending_spec_jobs.append(self.allocator, .{
                    .dispatch_index = dispatch_index,
                    .spec = reserved.spec,
                    .reservation = reservation,
                    .fn_template = fn_template,
                    .template_ref = template_ref,
                    .method_scope = method_scope.key,
                    .source_fn_ty = source_fn_ty,
                    .source_fn_key = source_fn_key,
                    .fn_ty = lower_fn_ty,
                    .evidence = spec_evidence,
                    .subst = subst,
                    .signature_relation = signature_relation,
                    .codec_contract = codec_contract,
                    .widened_result_row = widened_result_row,
                });
                self.next_spec_dispatch_index += 1;
                self.countCoordinatorBodyDiagnostic("spec_jobs_enqueued");
                self.recordPendingSpecJobPeak();
                return reservation.def;
            },
        }

        if (self.spec_job_parallel_callback) {
            Common.compilerBug("parallel specialization worker attempted coordinator-owned immediate completion");
        }
        const previous_symbol_domain = self.symbols.active;
        self.symbols.active = .coordinator;
        defer self.symbols.active = previous_symbol_domain;
        try self.completeTemplateReservation(
            reservation,
            fn_template,
            template_ref,
            method_scope,
            source_fn_ty,
            source_fn_key,
            lower_fn_ty,
            spec_evidence,
            subst,
            retained_topology,
            signature_relation,
            codec_contract,
            widened_result_row,
        );
        return reservation.def;
    }

    /// Lower the body (or hosted completion) for a specialization whose
    /// identity, ids, and seed are already reserved. Runs immediately for
    /// direct callers and from the scheduler's wave drain for queued symbolic
    /// requests.
    /// Whether a function type's arguments or result mention a function or
    /// erased callable anywhere, nominal backings included.
    fn monoFnTypeMentionsFunction(self: *Builder, fn_ty: Type.TypeId) Allocator.Error!bool {
        const types = self.program.types.view();
        switch (types.get(fn_ty)) {
            .func => |func| {
                for (types.span(func.args)) |arg| if (try self.monoTypeMentionsFunction(arg)) return true;
                return try self.monoTypeMentionsFunction(func.ret);
            },
            .primitive, .zst, .erased, .named, .record, .tuple, .tag_union, .list, .box => return try self.monoTypeMentionsFunction(fn_ty),
        }
    }

    /// Whether a `func` or `erased` type is reachable from `root`. Answers
    /// persist in `function_mentions` across requests, so a later scan stops
    /// at every type an earlier one answered instead of walking the same
    /// nested types again.
    fn monoTypeMentionsFunction(self: *Builder, root: Type.TypeId) Allocator.Error!bool {
        if (self.program.types.takeRollbackFloor()) |floor| {
            if (floor < self.function_mentions.items.len) self.function_mentions.shrinkRetainingCapacity(floor);
        }
        if (self.knownFunctionMention(root)) |known| return known;
        if (functionContent(self.program.types.view().get(root))) {
            try self.setFunctionMention(root, true);
            return true;
        }

        // A depth-first walk. A type whose walk finishes without finding a
        // function is function-free unless it reached a type still on the
        // walk's path (a cycle), whose answer is not known yet; such a type
        // is `open` and is answered only when the whole walk finishes.
        const Frame = struct {
            ty: Type.TypeId,
            /// This type's children are `children[start..end]`.
            start: usize,
            next: usize,
            end: usize,
            open: bool = false,
        };
        var frames = std.ArrayList(Frame).empty;
        defer frames.deinit(self.allocator);
        var children = std.ArrayList(Type.TypeId).empty;
        defer children.deinit(self.allocator);
        const on_path = &self.function_scan_path;
        on_path.clearRetainingCapacity();
        defer on_path.clearRetainingCapacity();
        var open_finished = std.ArrayList(Type.TypeId).empty;
        defer open_finished.deinit(self.allocator);

        try self.pushFunctionMentionFrame(Frame, &frames, &children, on_path, root);
        while (frames.items.len != 0) {
            const top = &frames.items[frames.items.len - 1];
            if (top.next < top.end) {
                const child = children.items[top.next];
                top.next += 1;
                const known = self.knownFunctionMention(child);
                const found = known orelse functionContent(self.program.types.view().get(child));
                if (found) {
                    try self.setFunctionMention(child, true);
                    for (frames.items) |frame| try self.setFunctionMention(frame.ty, true);
                    return true;
                }
                if (known != null) continue;
                // On the path, or finished open earlier in this walk.
                if (on_path.contains(child)) {
                    top.open = true;
                    continue;
                }
                try self.pushFunctionMentionFrame(Frame, &frames, &children, on_path, child);
                continue;
            }
            const finished = frames.pop().?;
            children.shrinkRetainingCapacity(finished.start);
            if (finished.open) {
                try open_finished.append(self.allocator, finished.ty);
                if (frames.items.len != 0) frames.items[frames.items.len - 1].open = true;
            } else {
                _ = on_path.remove(finished.ty);
                try self.setFunctionMention(finished.ty, false);
            }
        }
        // The walk from `root` found no function anywhere, so every type it
        // left open is function-free too.
        for (open_finished.items) |ty| try self.setFunctionMention(ty, false);
        return false;
    }

    const FunctionMention = enum(u8) { unknown, none, some };

    fn knownFunctionMention(self: *const Builder, ty: Type.TypeId) ?bool {
        const index = @backingInt(ty);
        if (index >= self.function_mentions.items.len) return null;
        return switch (self.function_mentions.items[index]) {
            .unknown => null,
            .none => false,
            .some => true,
        };
    }

    fn setFunctionMention(self: *Builder, ty: Type.TypeId, mentions: bool) Allocator.Error!void {
        const index = @backingInt(ty);
        if (index >= self.function_mentions.items.len) {
            try self.function_mentions.appendNTimes(self.allocator, .unknown, index + 1 - self.function_mentions.items.len);
        }
        self.function_mentions.items[index] = if (mentions) .some else .none;
    }

    fn functionContent(content: Type.Content) bool {
        return switch (content) {
            .erased, .func => true,
            .primitive, .zst, .named, .record, .tuple, .tag_union, .list, .box => false,
        };
    }

    fn pushFunctionMentionFrame(
        self: *Builder,
        comptime Frame: type,
        frames: *std.ArrayList(Frame),
        children: *std.ArrayList(Type.TypeId),
        on_path: *collections.DenseMap(Type.TypeId, void),
        ty: Type.TypeId,
    ) Allocator.Error!void {
        const types = self.program.types.view();
        try on_path.put(ty, {});
        const start = children.items.len;
        switch (types.get(ty)) {
            .primitive, .zst, .erased, .func => {},
            .named => |named| {
                try children.appendSlice(self.allocator, types.span(named.args));
                if (named.backing) |backing| try children.append(self.allocator, backing.ty);
            },
            .record => |span| for (types.fieldSpan(span)) |field| try children.append(self.allocator, field.ty),
            .tuple => |span| try children.appendSlice(self.allocator, types.span(span)),
            .tag_union => |span| for (types.tagSpan(span)) |tag| try children.appendSlice(self.allocator, types.span(tag.payloads)),
            .list, .box => |elem| try children.append(self.allocator, elem),
        }
        try frames.append(self.allocator, .{ .ty = ty, .start = start, .next = start, .end = children.items.len });
    }

    /// Everything a result-row widening adapter needs beyond the reservation
    /// itself: the declared interface the template is specialized at, and the
    /// `Try` capability when the adapted row sits inside a `Try` result.
    const ResultRowWideningAdapter = struct {
        declared_source_fn_ty: checked.CheckedTypeId,
        declared_source_fn_key: names.TypeDigest,
        source_fn_ty: Type.TypeId,
        capability: ?HostedTryAdapterCapability,
    };

    /// Plan the adapter for a specialization whose request relation DECLINED to
    /// unify the template's closed checked row with the requested one
    /// (design.md "Result-Row Widening Adapter"). `widened_result_row` is that
    /// relation's own answer, carried here from the specialization request; it
    /// is the single source of truth for whether an adapter is owed. Re-deriving
    /// the answer from the checked root instead would let the relation and the
    /// completion disagree—the relation declining with no adapter minted is a
    /// silent miscompile, and an adapter minted where the relation unified is a
    /// spurious narrow specialization behind a pointless re-tag.
    ///
    /// Everything below the gate is the adapter's construction, and every step
    /// of it must succeed: a recorded widening that cannot be built stops the
    /// build rather than falling back to a definition at the wrong row.
    ///
    /// The declared labels are read from `lowerType` of the checked root. That
    /// is sound only because `closedResultRowOrNull` refused every row whose
    /// tail is a rigid or an unsealed flex: `lowerCheckedTypeVariable` seals a
    /// rigid to the empty tag union, which would otherwise pass a parametric
    /// row off as a closed one. A rigid *payload* is harmless—every narrowed
    /// payload is taken from the request, never from the declared type—and
    /// `requireLoweredDeclaredRowLabels` checks the lowered label set against
    /// the checker's recorded row so a collapse cannot go unnoticed.
    fn resultRowWideningAdapterOrNull(
        self: *Builder,
        view: ModuleView,
        template: checked.CheckedProcedureTemplate,
        requested_fn_ty: Type.TypeId,
        widened_result_row: bool,
    ) Allocator.Error!?ResultRowWideningAdapter {
        if (!widened_result_row) return null;
        const declared_row = closedResultRowOrNull(view, template.checked_fn_root) orelse
            Common.compilerBug("result-row widening relation declined for a template with no closed checked result row");
        // Everything below is coordinator-program work: `requested_fn_ty` is a
        // program id, `sameMonoType` compares through `program.types`, and the
        // interned narrowed source type is handed to a program-domain
        // completion. A specialization workspace is a separate type domain
        // whose ids cross only through an explicit relocation, so lowering the
        // declared type there and comparing it here would read two unrelated
        // stores with one set of ids. This pre-step runs for every
        // specialization of every closed-result-row template, including ones
        // an immediate caller completes from inside a shard, so it pins the
        // destination rather than trusting the caller's.
        const coordinator_types = ProgramTypeDestination.begin(self);
        defer coordinator_types.end();
        const declared_source_fn_ty = template.checked_fn_root;
        const declared_mono_fn_ty = try self.lowerType(view, declared_source_fn_ty);
        if (try self.sameMonoType(declared_mono_fn_ty, requested_fn_ty)) {
            Common.compilerBug("result-row widening relation declined for a request at the declared type");
        }
        const capability = try self.hostedTryAdapterCapability(view, template.hosted_try_adapter);
        const try_capability: ?HostedTryAdapterCapability = if (declared_row.behind_try)
            capability orelse Common.compilerBug("closed Try result row had no checker-recorded Try capability")
        else
            null;
        try self.requireLoweredDeclaredRowLabels(view, declared_row, try_capability, declared_mono_fn_ty);
        const source_fn_ty = (try self.resultRowWideningAdapterSourceType(
            try_capability,
            declared_mono_fn_ty,
            requested_fn_ty,
        )) orelse Common.compilerBug("result-row widening relation declined for a request lowering cannot adapt");
        // The narrowed source carries exactly the declared labels, so the
        // recursive specialization below is a fixpoint of this pre-step and
        // cannot widen again.
        if (try self.resultRowWideningAdapterSourceType(
            try_capability,
            declared_mono_fn_ty,
            source_fn_ty,
        )) |_| {
            Common.compilerBug("result-row widening adapter source type widened the declared row again");
        }
        return .{
            .declared_source_fn_ty = declared_source_fn_ty,
            .declared_source_fn_key = view.types.rootKey(declared_source_fn_ty),
            .source_fn_ty = source_fn_ty,
            .capability = try_capability,
        };
    }

    /// Guard for the label source above: the lowered declared type must list
    /// exactly the labels the checker recorded for this row. A row tail that
    /// `lowerCheckedTypeVariable` sealed away shows up here as a disagreement.
    fn requireLoweredDeclaredRowLabels(
        self: *Builder,
        view: ModuleView,
        declared_row: ClosedResultRow,
        capability: ?HostedTryAdapterCapability,
        declared_mono_fn_ty: Type.TypeId,
    ) Allocator.Error!void {
        const declared_fn = self.functionShape(declared_mono_fn_ty, "declared template root type was not a function");
        const row_ty = if (capability) |try_capability|
            ((try self.hostedTryInfoOrNull(try_capability, declared_fn.ret)) orelse
                Common.compilerBug("closed Try result row did not lower to its checker-recorded Try nominal")).err_ty
        else
            declared_fn.ret;
        const lowered_tags = self.bareTagUnionTagsOrNull(row_ty) orelse
            Common.compilerBug("closed result row did not lower to a tag union");
        if (lowered_tags.len != checkedClosedRowLabelCount(view, declared_row.row)) {
            Common.compilerBug("lowered declared result row disagreed with the checker's recorded labels");
        }
    }

    /// Check a route that states `widened_result_row = false` with no relation
    /// behind the claim.
    ///
    /// `completeTemplateReservation` mints the adapter from the request
    /// relation's own recorded answer, but three routes reach it without ever
    /// running that relation and lower the body directly at the requested type
    /// (`lowerTemplate`'s root, `lowerFnTemplateCallTarget`, and
    /// `lowerRestoredConstFnTemplate`). Each states that its request is the
    /// binding's own declared type; if one were ever wrong the template would
    /// be defined at the wide row, which is exactly the miscompile the adapter
    /// exists to prevent. So the claim is checked against the types here
    /// instead of being taken on faith: if the adapter pre-step would have
    /// found a narrowed source type for this request, stop the build.
    fn requireRequestDidNotWidenResultRow(
        self: *Builder,
        template_ref: names.ProcTemplate,
        requested_fn_ty: Type.TypeId,
        comptime message: []const u8,
    ) Allocator.Error!void {
        const view = self.moduleForDigest(names.procTemplateModuleDigest(template_ref));
        const template = view.templates.get(template_ref.template);
        // Only a closed checked result row can be widened at all, and this
        // filter is a checked-type walk while everything below it lowers a
        // type; keep it first.
        const declared_row = closedResultRowOrNull(view, template.checked_fn_root) orelse return;
        // Same destination pin, and for the same reason, as the pre-step this
        // mirrors: `requested_fn_ty` is a program id.
        const coordinator_types = ProgramTypeDestination.begin(self);
        defer coordinator_types.end();
        const declared_mono_fn_ty = try self.lowerType(view, template.checked_fn_root);
        const try_capability: ?HostedTryAdapterCapability = if (declared_row.behind_try)
            (try self.hostedTryAdapterCapability(view, template.hosted_try_adapter)) orelse
                Common.compilerBug("closed Try result row had no checker-recorded Try capability")
        else
            null;
        // The same guard the pre-step applies before reading declared labels
        // out of the lowered type, and for the same reason: a row
        // `lowerCheckedTypeVariable` sealed to the empty tag union lists fewer
        // labels than the checker recorded, which would make an ordinary
        // request look wider than the declared row and report a lowering
        // collapse as a widening that never happened.
        try self.requireLoweredDeclaredRowLabels(view, declared_row, try_capability, declared_mono_fn_ty);
        if (try self.resultRowWideningAdapterSourceType(
            try_capability,
            declared_mono_fn_ty,
            requested_fn_ty,
        )) |_| {
            Common.compilerBug(message);
        }
    }

    /// Specialize the template at its declared row and define the reserved
    /// specialization as a generated adapter that calls it and re-tags the
    /// result into the requested row.
    fn completeResultRowWideningAdapter(
        self: *Builder,
        reservation: TemplateReservation,
        fn_template: Ast.FnTemplate,
        template_ref: names.ProcTemplate,
        method_scope: ModuleView,
        adapter: ResultRowWideningAdapter,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        lower_fn_ty: Type.TypeId,
        spec_evidence: []const SpecEvidence,
        signature_relation: Ast.SignatureRelation,
        codec_contract: ?SealedCodecContractContext,
    ) Allocator.Error!void {
        var completion_timing_scope = ProcedureTimingScope.begin(self.timing, .completion);
        defer completion_timing_scope.end();

        // The generated body is built from program ids throughout—the
        // reserved definition, its locals, and the re-tagging match all live
        // in the coordinator program—while the shape helpers it uses read
        // the active store. `resultRowWideningAdapterOrNull` pins its own
        // destination, but this step also requests the declared-row
        // specialization, so it cannot simply pin over an active shard.
        // Reaching here from one is a bug, and one whose only symptom would be
        // a wrong tag discriminant, so it stops the build in every mode.
        if (self.hasPrivateTypeDestination()) {
            Common.compilerBug("result-row widening adapter completed with a private type destination");
        }
        const fn_data = self.programFunctionShape(lower_fn_ty, "result-row widening adapter root type was not a function");
        const args = try self.typedLocalsForArgs(self.program.types.span(fn_data.args));
        const source_def = try self.lowerTemplateWithMono(
            template_ref,
            method_scope,
            adapter.declared_source_fn_ty,
            adapter.declared_source_fn_key,
            adapter.source_fn_ty,
            spec_evidence,
            null,
            signature_relation,
            .count,
            null,
            null,
            .immediate,
            codec_contract,
            // The adapter's own source is requested at the DECLARED row, the
            // fixpoint `resultRowWideningAdapterOrNull` asserts.
            false,
        );
        const adapter_template = Ast.FnTemplate{
            .fn_def = .{ .checked_generated = template_ref },
            .source_fn_ty = source_fn_ty,
            .source_fn_key = source_fn_key,
            .mono_fn_ty = lower_fn_ty,
            .evidence_digest = fn_template.evidence_digest,
            .const_evidence = fn_template.const_evidence,
            .const_evidence_frames = fn_template.const_evidence_frames,
            .const_evidence_frame_head = fn_template.const_evidence_frame_head,
        };
        const body = try self.resultRowWideningAdapterBody(
            adapter.capability,
            args,
            self.defFnId(source_def),
            adapter.source_fn_ty,
            lower_fn_ty,
        );
        self.program.setDef(reservation.def, .{
            .symbol = reservation.symbol,
            .fn_def = adapter_template,
            .fn_id = reservation.fn_id,
            .args = args,
            .body = .{ .roc = body },
            .ret = fn_data.ret,
        });
        self.program.setFnSource(reservation.fn_id, adapter_template);
        try self.markTemplateReady(reservation.fn_id, lower_fn_ty);
    }

    fn completeTemplateReservation(
        self: *Builder,
        reservation: TemplateReservation,
        fn_template: Ast.FnTemplate,
        template_ref: names.ProcTemplate,
        method_scope: ModuleView,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        lower_fn_ty: Type.TypeId,
        spec_evidence: []const SpecEvidence,
        subst: ?SealedSubstitution,
        retained_topology: ?EvidenceChain,
        signature_relation: Ast.SignatureRelation,
        codec_contract: ?SealedCodecContractContext,
        widened_result_row: bool,
    ) Allocator.Error!void {
        const view = self.moduleForDigest(names.procTemplateModuleDigest(template_ref));
        const template = view.templates.get(template_ref.template);

        if (fn_template.cached != null) {
            // The object cache holds this specialization's compiled
            // procedure. The definition keeps its declared shape and no body,
            // exactly like a hosted procedure, and downstream stages emit an
            // external reference the object writer resolves from the cache.
            const fn_data = self.programFunctionShape(lower_fn_ty, "cached procedure template root type was not a function");
            const args = try self.typedLocalsForArgs(self.program.types.span(fn_data.args));
            self.program.setDef(reservation.def, .{
                .symbol = reservation.symbol,
                .fn_def = fn_template,
                .fn_id = reservation.fn_id,
                .args = args,
                .body = .hosted,
                .ret = fn_data.ret,
            });
            self.program.setFnSource(reservation.fn_id, fn_template);
            try self.markTemplateReady(reservation.fn_id, lower_fn_ty);
            return;
        }

        // A template whose checked result row is closed may be requested at
        // a row that includes it (design.md "Result-Row Widening Adapter").
        // Such a request is served by specializing the template at its
        // declared row and generating an adapter at the requested row that
        // calls it and re-tags the result. Hosted templates are the instance
        // where the declared row is the host ABI: a use site widens the
        // (closed) hosted error row through `?`, and the adapter keeps the
        // extern boundary at its declared type instead of emitting a hosted
        // spec whose layout would not match the host ABI.
        if (try self.resultRowWideningAdapterOrNull(
            view,
            template,
            lower_fn_ty,
            widened_result_row,
        )) |adapter| {
            try self.completeResultRowWideningAdapter(
                reservation,
                fn_template,
                template_ref,
                method_scope,
                adapter,
                source_fn_ty,
                source_fn_key,
                lower_fn_ty,
                spec_evidence,
                signature_relation,
                codec_contract,
            );
            return;
        }

        switch (template.target) {
            .hosted => {
                var completion_timing_scope = ProcedureTimingScope.begin(self.timing, .completion);
                defer completion_timing_scope.end();

                // The host is compiled against the declared hosted signature,
                // so that exact type is the only one the extern boundary may
                // use. `requireHostedExternAtDeclaredAbi` holds that boundary
                // for every request the widening adapter above did not claim.
                const declared_source_fn_ty = template.checked_fn_root;
                const declared_source_fn_key = view.types.rootKey(declared_source_fn_ty);
                const declared_mono_fn_ty = try self.lowerType(view, declared_source_fn_ty);
                var hosted_fn_template = self.fnDefForTemplate(
                    view,
                    template_ref,
                    declared_source_fn_ty,
                    declared_source_fn_key,
                    lower_fn_ty,
                );
                hosted_fn_template.evidence_digest = fn_template.evidence_digest;
                hosted_fn_template.const_evidence = fn_template.const_evidence;
                hosted_fn_template.const_evidence_frames = fn_template.const_evidence_frames;
                hosted_fn_template.const_evidence_frame_head = fn_template.const_evidence_frame_head;
                const fn_data = self.programFunctionShape(lower_fn_ty, "hosted procedure template root type was not a function");
                const args = try self.typedLocalsForArgs(self.program.types.span(fn_data.args));
                if (self.hostedEntry(template_ref).binding == .unavailable) {
                    const body = try self.program.addExpr(.{
                        .ty = fn_data.ret,
                        .data = .{ .crash = try self.program.addStringLiteral("hosted declaration is absent from the platform hosted section") },
                    });
                    self.program.setDef(reservation.def, .{
                        .symbol = reservation.symbol,
                        .fn_def = hosted_fn_template,
                        .fn_id = reservation.fn_id,
                        .args = args,
                        .body = .{ .roc = body },
                        .ret = fn_data.ret,
                    });
                    self.program.setFnSource(reservation.fn_id, hosted_fn_template);
                    try self.markTemplateReady(reservation.fn_id, lower_fn_ty);
                    return;
                }
                try self.requireHostedExternAtDeclaredAbi(
                    view,
                    template_ref,
                    declared_source_fn_ty,
                    declared_mono_fn_ty,
                    lower_fn_ty,
                );
                self.program.setDef(reservation.def, .{
                    .symbol = reservation.symbol,
                    .fn_def = hosted_fn_template,
                    .fn_id = reservation.fn_id,
                    .args = args,
                    .body = .hosted,
                    .ret = fn_data.ret,
                });
                self.program.setFnSource(reservation.fn_id, hosted_fn_template);
                try self.markTemplateReady(reservation.fn_id, lower_fn_ty);
                return;
            },
            .roc,
            .intrinsic,
            .entry,
            .comptime_only,
            => {},
        }

        const graph = try self.createGraph();
        defer graph.destroy();
        var body_draft_storage = BodyDraftStore.init(self.allocator);
        defer body_draft_storage.deinit();
        const body_draft = &body_draft_storage;
        const draft = FinalBodyOutputGuard.begin(self);
        const pending = try self.lowerReservedTemplateBodyIntoDraft(
            graph,
            body_draft,
            reservation,
            fn_template,
            template_ref,
            view,
            method_scope,
            template,
            source_fn_key,
            lower_fn_ty,
            spec_evidence,
            subst,
            retained_topology,
            signature_relation,
            codec_contract,
        );
        const draft_end = draft.end(self);
        const sealed = try self.sealActiveBodyDraft(
            graph,
            body_draft,
            draft,
            draft_end,
            pending.root_node,
            &.{},
            null,
            null,
            null,
        );
        defer sealed.deinit(self.allocator);
        var completion_timing_scope = ProcedureTimingScope.begin(self.timing, .completion);
        defer completion_timing_scope.end();
        try self.finishReservedTemplateBody(pending, sealed.ids, sealed.root_ty.?);
    }

    /// The queued job whose reservation owns `fn_id`, or null when that body
    /// has already been claimed and completed. Claims are rare (bounded by
    /// iterator-inline occurrences), so a linear scan of the outstanding
    /// window is cheaper than an index.
    fn pendingSpecJobFor(self: *Builder, fn_id: Ast.FnId) ?PendingSpecJob {
        for (0..self.pending_spec_jobs.len) |index| {
            const job = self.pending_spec_jobs.get(index);
            if (job.reservation.fn_id == fn_id) return job;
        }
        return null;
    }

    /// Whether a queued specialization completes on the coordinator instead
    /// of in a body shard. A hosted template reaches the host directly, a
    /// template the object cache holds keeps its declared shape with no body,
    /// and a result-row widening adapter is a generated call plus a re-tag
    /// whose declared-row specialization is requested from the coordinator
    /// (design.md "Result-Row Widening Adapter"). None of the three has a
    /// graph/draft pair for a worker lane to hand back.
    fn specJobCompletesOnCoordinator(
        self: *Builder,
        view: ModuleView,
        template: checked.CheckedProcedureTemplate,
        job: PendingSpecJob,
    ) Allocator.Error!bool {
        if (job.fn_template.cached != null or template.target == .hosted) return true;
        return (try self.resultRowWideningAdapterOrNull(
            view,
            template,
            job.fn_ty,
            job.widened_result_row,
        )) != null;
    }

    /// Execute queued specialization bodies in dispatch order until the wave
    /// drains. Bodies executed here may enqueue further requests; those join
    /// the same FIFO and are reached by this same loop, in enqueue order.
    fn drainPendingSpecJobs(self: *Builder) Allocator.Error!void {
        const executor = self.post_check_executor orelse return self.drainPendingSpecJobsSerial();
        if (executor.worker_count <= 1) return self.drainPendingSpecJobsSerial();
        if (self.pending_spec_jobs.len == 0) {
            self.pending_spec_jobs.clearRetainingCapacity();
            self.requirePendingSpecJobsDrained();
            return;
        }

        const capacity = executor.worker_count *| parallel_spec_jobs_per_lane;
        const buffers = try self.ensureSpecJobTaskBuffers(capacity);
        const contexts = buffers.contexts;
        var session = executor.begin();
        defer session.end();
        var submitted: usize = 0;
        var accepted: usize = 0;
        var running: usize = 0;
        // Slots and snapshots outlive every accepted task even on OOM. Completed
        // shards own their epochs independently of the reusable worker workspace.
        defer {
            while (running > 0) : (running -= 1) {
                const completion = session.receive();
                self.receiveSpecJobCompletion(contexts, completion, accepted, submitted);
            }
            while (accepted < submitted) : (accepted += 1) {
                const context = &contexts[accepted % capacity];
                if (context.shard) |*shard| shard.deinit();
                context.shard = null;
            }
        }
        if (self.timing) |timing| {
            timing.parallel.task_waves +%= 1;
            timing.parallel.peak_worker_lanes_available = @max(timing.parallel.peak_worker_lanes_available, @as(u64, @intCast(executor.worker_count)));
        }
        while (self.pending_spec_jobs.len != 0 or accepted < submitted) {
            if (running < executor.worker_count and submitted - accepted < capacity and
                self.pending_spec_jobs.len != 0)
            {
                const job = self.pending_spec_jobs.get(0);
                if (job.dispatch_index != self.next_spec_accept_index + submitted - accepted) {
                    Common.compilerBug("Monotype streaming dispatch was not contiguous");
                }
                const view = self.moduleForDigest(names.procTemplateModuleDigest(job.template_ref));
                const template = view.templates.get(job.template_ref.template);
                if (self.spec_store.recordStatus(job.spec) == .ready or try self.specJobCompletesOnCoordinator(view, template, job)) {
                    // Coordinator-only entries still wait their exact acceptance
                    // turn, but need not wait for any later worker task.
                    _ = self.pending_spec_jobs.pop();
                    if (accepted == submitted) {
                        try self.executePendingSpecJob(job);
                        continue;
                    }
                    contexts[submitted % capacity] = .{
                        .inputs = undefined,
                        .snapshot = undefined,
                        .prepared = .{ .job = job, .view = view, .method_scope = self.moduleForId(job.method_scope), .template = template },
                        .completed = true,
                        .coordinator_only = true,
                    };
                    submitted += 1;
                    continue;
                } else {
                    const slot = submitted % capacity;
                    const context = &contexts[slot];
                    const snapshot = try self.captureSpecJobInputs();
                    context.* = .{
                        .snapshot = snapshot,
                        .inputs = .{
                            .run_id = self.spec_job_run_id,
                            .modules = self.modules,
                            .module_views = self.moduleViews(),
                            .source_file_ids = self.sourceFileIds(),
                            .lowering_module_ids = self.loweringModuleIds(),
                            .snapshot = &context.snapshot,
                            .proc_debug_names = self.proc_debug_names,
                            .interface_summaries = &self.shared_summaries.?,
                            .interface_summary_end = self.shared_summaries.?.count,
                            .collect_counters = self.counters != null,
                            .collect_diagnostics = self.diagnostics != null,
                            .inline_expects = self.inline_expects,
                            .static_data_literals = self.static_data_literals,
                            .comptime_value_reads = self.comptime_value_reads,
                            .literal_roots = self.literal_roots,
                            .declared_comptime_root_functions = self.borrowed_comptime_root_functions orelse &self.declared_comptime_root_functions,
                            .hosted_catalog = self.hosted_catalog,
                            .current_loc = self.current_loc,
                            .current_region = self.current_region,
                            .timing_std_io = if (self.timing) |timing| timing.std_io else null,
                        },
                        .prepared = .{ .job = job, .view = view, .method_scope = self.moduleForId(job.method_scope), .template = template },
                    };
                    try session.submit(.{ .id = slot, .context = context, .run = runSpecJobTask });
                    _ = self.pending_spec_jobs.pop();
                    submitted += 1;
                    running += 1;
                    if (self.timing) |timing| timing.parallel.specialization_tasks_submitted +%= 1;
                    continue;
                }
            }
            // Accept one deterministic entry, then give free lanes the newly
            // discovered work before accepting another buffered successor.
            if (accepted < submitted and contexts[accepted % capacity].completed) {
                const context = &contexts[accepted % capacity];
                var commit_scope = ParallelCoordinatorTimingScope.begin(self.timing);
                defer commit_scope.end();
                if (context.coordinator_only) {
                    context.coordinator_only = false;
                    try self.executePendingSpecJob(context.prepared.job);
                } else {
                    try self.acceptCompletedSpecJob(context);
                }
                accepted += 1;
                continue;
            }
            if (running == 0) Common.compilerBug("Monotype streaming drain made no progress");
            const completion = blk: {
                var wait_scope = ProcedureTimingScope.begin(self.timing, .parallel_wait);
                defer wait_scope.end();
                break :blk session.receive();
            };
            running -= 1;
            self.receiveSpecJobCompletion(contexts, completion, accepted, submitted);
        }
        self.pending_spec_jobs.clearRetainingCapacity();
        self.requirePendingSpecJobsDrained();
    }

    fn receiveSpecJobCompletion(self: *Builder, contexts: []SpecJobTaskContext, completion: base.post_check_task_executor.Completion, accepted: usize, submitted: usize) void {
        var scope = ParallelCoordinatorTimingScope.begin(self.timing);
        defer scope.end();
        if (completion.id >= contexts.len) Common.compilerBug("post-check executor returned an unknown specialization task");
        const offset = (completion.id + contexts.len - accepted % contexts.len) % contexts.len;
        if (offset >= submitted - accepted) Common.compilerBug("post-check executor completed an inactive specialization slot");
        const context = &contexts[completion.id];
        if (context.completed or completion.value != @as(?*anyopaque, @ptrCast(context))) {
            Common.compilerBug("post-check executor returned an invalid specialization completion");
        }
        context.completed = true;
        if (context.shard) |*shard| {
            if (@backingInt(shard.worker_id) != completion.worker_id) Common.compilerBug("post-check executor changed specialization worker ownership");
        }
        self.recordParallelWorkerWork(contexts[completion.id..][0..1]);
        self.recordRetainedSpecShardPeak(contexts, accepted, submitted);
    }

    fn acceptCompletedSpecJob(self: *Builder, context: *SpecJobTaskContext) Allocator.Error!void {
        if (context.failed) return error.OutOfMemory;
        switch (self.spec_store.recordStatus(context.prepared.job.spec)) {
            .ready => {
                // A preceding shard may have eagerly committed an iterator
                // producer's queued reservation. Accept the ready entry and
                // discard its independently lowered body. The worker's
                // cumulative type/name suffix must still be absorbed so
                // later epochs from that worker retain exact ids.
                if (context.shard) |*shard| {
                    const commit_domain = shard.commit_domain;
                    try commit_domain.absorb(&shard.store_epoch);
                    shard.store_epoch_absorbed = true;
                    var committed_types = CommittedGraphTypes.relocatedStore(
                        &commit_domain.types,
                        &commit_domain.name_store,
                        &self.program.types,
                        &self.program.names,
                        commit_domain.committedTypeRelocation(self.program),
                    );
                    try self.commitInterfaceSummaries(shard.interface_summaries, &committed_types);
                    shard.deinit();
                    if (self.timing) |timing| timing.parallel.specialization_tasks_discarded_ready +%= 1;
                }
                context.shard = null;
                try self.executePendingSpecJob(context.prepared.job);
                return;
            },
            .reserved => {},
            .lowering => Common.invariant("parallel Monotype specialization was already lowering at commit"),
        }
        self.countCoordinatorBodyDiagnostic("spec_jobs_executed");
        self.spec_store.markLowering(context.prepared.job.spec);
        const shard = &context.shard.?;
        try self.commitCompletedSpecJobShard(shard);
        if (self.timing) |timing| timing.parallel.specialization_tasks_committed +%= 1;
        shard.deinit();
        context.shard = null;
    }

    fn drainPendingSpecJobsSerial(self: *Builder) Allocator.Error!void {
        while (self.pending_spec_jobs.len != 0) {
            const job = self.pending_spec_jobs.get(0);
            _ = self.pending_spec_jobs.pop();
            try self.executePendingSpecJob(job);
        }
        self.pending_spec_jobs.clearRetainingCapacity();
        self.requirePendingSpecJobsDrained();
    }

    fn runSpecJobTask(
        opaque_context: *anyopaque,
        executor_worker: base.post_check_task_executor.Worker,
    ) ?*anyopaque {
        const context: *SpecJobTaskContext = @ptrCast(@alignCast(opaque_context));
        const task_started_ns = if (context.inputs.timing_std_io) |std_io| timingNowNs(std_io) else 0;
        defer if (context.inputs.timing_std_io) |std_io| {
            const finished_ns = timingNowNs(std_io);
            context.worker_work_ns = @intCast(@max(0, finished_ns - task_started_ns));
        };
        if (executor_worker.id >= std.math.maxInt(u32)) {
            Common.compilerBug("post-check executor returned an invalid specialization worker id");
        }
        const lane = Builder.ensureSpecJobLaneState(executor_worker, &context.inputs) catch {
            context.failed = true;
            return context;
        };
        const worker = &lane.worker;
        context.lane_task_started = true;
        context.first_task_on_lane = worker.tasks_started == 0;
        if (context.inputs.timing_std_io != null) worker.tasks_started +%= 1;
        worker.counters = .{};
        worker.diagnostics = .{};
        const builder = Builder.ensureSpecJobWorkerBuilder(worker, &context.inputs) catch {
            context.failed = true;
            return context;
        };
        if (builder.active_graph != null or builder.active_body_draft != null or
            builder.active_template_root != null or builder.active_spec_job_diagnostics != null)
        {
            Common.compilerBug("specialization executor reused a worker with active lowering state");
        }
        builder.current_loc = context.inputs.current_loc;
        builder.current_region = context.inputs.current_region;
        builder.spec_job_parallel_callback = true;
        defer builder.spec_job_parallel_callback = false;
        var shard = builder.lowerPendingSpecJobToShard(
            worker,
            &lane.commit_domain,
            context.prepared.job,
            context.prepared.view,
            context.prepared.method_scope,
            context.prepared.template,
        ) catch {
            context.failed = true;
            return context;
        };
        if (context.inputs.collect_counters) {
            shard.specialization_counter_delta = worker.counters;
        }
        context.shard = shard;
        return context;
    }

    fn runProcedureRootTask(
        opaque_context: *anyopaque,
        executor_worker: base.post_check_task_executor.Worker,
    ) ?*anyopaque {
        const context: *ProcedureRootTaskContext = @ptrCast(@alignCast(opaque_context));
        const task_started_ns = if (context.inputs.timing_std_io) |std_io| timingNowNs(std_io) else 0;
        defer if (context.inputs.timing_std_io) |std_io| {
            const finished_ns = timingNowNs(std_io);
            context.worker_work_ns = @intCast(@max(0, finished_ns - task_started_ns));
        };
        if (executor_worker.id >= std.math.maxInt(u32)) {
            Common.compilerBug("post-check executor returned an invalid root worker id");
        }
        const lane = Builder.ensureSpecJobLaneState(executor_worker, context.inputs) catch {
            context.failed = true;
            return context;
        };
        const worker = &lane.worker;
        context.lane_task_started = true;
        context.first_task_on_lane = worker.tasks_started == 0;
        if (context.inputs.timing_std_io != null) worker.tasks_started +%= 1;
        worker.counters = .{};
        worker.diagnostics = .{};
        const builder = Builder.ensureSpecJobWorkerBuilder(worker, context.inputs) catch {
            context.failed = true;
            return context;
        };
        builder.current_loc = context.inputs.current_loc;
        builder.current_region = context.inputs.current_region;
        builder.spec_job_parallel_callback = true;
        defer builder.spec_job_parallel_callback = false;
        var shard = builder.lowerProcedureUseRootToShard(
            worker,
            &lane.commit_domain,
            context.request,
            context.request.procedure_use orelse
                Common.compilerBug("procedure root task lost its procedure use"),
            context.source_module,
        ) catch {
            context.failed = true;
            return context;
        };
        if (context.inputs.collect_counters) shard.specialization_counter_delta = worker.counters;
        context.shard = shard;
        return context;
    }

    fn requirePendingSpecJobsDrained(self: *Builder) void {
        if (self.pending_spec_jobs.len != 0) {
            Common.compilerBug("Monotype specialization queue was not drained at a wave boundary");
        }
        if (self.next_spec_accept_index != self.next_spec_dispatch_index) {
            Common.compilerBug("Monotype specialization queue entries were not accepted through the wave boundary");
        }
    }

    fn executePendingSpecJob(self: *Builder, job: PendingSpecJob) Allocator.Error!void {
        if (self.active_graph != null) {
            Common.invariant("Monotype specialization job executed during an active body draft");
        }
        self.requireNextSpecAcceptance(job.dispatch_index);
        switch (self.spec_store.recordStatus(job.spec)) {
            // An immediate caller claimed and completed this reservation after
            // it was queued; the queued duplicate is skipped, not re-lowered.
            .ready => {
                self.countCoordinatorBodyDiagnostic("spec_jobs_skipped_ready");
                if (std.debug.runtime_safety) {
                    const existing = self.lowered_templates.get(job.reservation.fn_id) orelse
                        Common.invariant("completed Monotype specialization lost its lowering state");
                    std.debug.assert(try specEvidenceVectorEql(self.allocator, existing.evidence, job.evidence));
                }
                self.acceptSpecDispatch(job.dispatch_index);
                return;
            },
            .reserved => {},
            .lowering => Common.invariant("queued Monotype specialization was already lowering at dispatch"),
        }
        self.countCoordinatorBodyDiagnostic("spec_jobs_executed");
        self.spec_store.markLowering(job.spec);
        const view = self.moduleForDigest(names.procTemplateModuleDigest(job.template_ref));
        const template = view.templates.get(job.template_ref.template);
        // Hosted completion has no Roc graph/draft pair to transfer, and
        // neither does an object-cache completion or a result-row widening
        // adapter: the adapter is a generated call plus a re-tag, with the
        // declared-row specialization requested from the coordinator. All
        // three keep coordinator ownership while ordinary bodies establish
        // the shard handoff.
        if (try self.specJobCompletesOnCoordinator(view, template, job)) {
            try self.completeTemplateReservation(
                job.reservation,
                job.fn_template,
                job.template_ref,
                self.moduleForId(job.method_scope),
                job.source_fn_ty,
                job.source_fn_key,
                job.fn_ty,
                job.evidence,
                job.subst,
                null,
                job.signature_relation,
                job.codec_contract,
                job.widened_result_row,
            );
            self.acceptSpecDispatch(job.dispatch_index);
            return;
        }
        const worker = self.ensureSerialSpecJobWorker();
        var shard = try self.lowerPendingSpecJobToShard(
            worker,
            self.ensureSpecJobCommitDomain(),
            job,
            view,
            self.moduleForId(job.method_scope),
            template,
        );
        defer shard.deinit();
        try self.commitCompletedSpecJobShard(&shard);
    }

    fn requireNextSpecAcceptance(self: *Builder, dispatch_index: u64) void {
        if (dispatch_index != self.next_spec_accept_index) {
            Common.compilerBug("Monotype specialization queue entry reached the coordinator out of dispatch order");
        }
    }

    fn acceptSpecDispatch(self: *Builder, dispatch_index: u64) void {
        self.requireNextSpecAcceptance(dispatch_index);
        self.next_spec_accept_index += 1;
    }

    fn ensureSerialSpecJobWorker(self: *Builder) *SpecJobWorkerState {
        if (self.spec_job_worker == null) {
            self.spec_job_worker = SpecJobWorkerState.init(self.allocator, .serial);
        }
        return &self.spec_job_worker.?;
    }

    fn ensureSpecJobCommitDomain(self: *Builder) *SpecJobCommitDomain {
        if (self.spec_job_commit_domain == null) {
            self.spec_job_commit_domain = SpecJobCommitDomain.init(self.allocator);
        }
        return &self.spec_job_commit_domain.?;
    }

    fn recordParallelWorkerWork(self: *Builder, contexts: anytype) void {
        const timing = self.timing orelse return;
        for (contexts) |*context| {
            timing.parallel.worker_work_ns +%= context.worker_work_ns;
            context.worker_work_ns = 0;
            if (context.lane_task_started) {
                if (context.first_task_on_lane) {
                    timing.parallel.peak_worker_lanes_used +%= 1;
                } else {
                    timing.parallel.within_lowering_lane_reuse_tasks +%= 1;
                }
                context.lane_task_started = false;
            }
        }
    }

    fn recordPendingSpecJobPeak(self: *Builder) void {
        const executor = self.post_check_executor orelse return;
        if (executor.worker_count <= 1) return;
        const timing = self.timing orelse return;
        timing.parallel.peak_specialization_jobs_pending = @max(
            timing.parallel.peak_specialization_jobs_pending,
            @as(u64, @intCast(self.pending_spec_jobs.len)),
        );
    }

    fn recordRetainedSpecShardPeak(self: *Builder, contexts: []const SpecJobTaskContext, accepted: usize, submitted: usize) void {
        const timing = self.timing orelse return;
        var retained: u64 = 0;
        for (accepted..submitted) |index| {
            const context = &contexts[index % contexts.len];
            if (context.completed and context.shard != null) retained += 1;
        }
        timing.parallel.peak_specialization_shards_retained = @max(
            timing.parallel.peak_specialization_shards_retained,
            retained,
        );
    }

    fn ensureSpecJobTaskBuffers(self: *Builder, capacity: usize) Allocator.Error!*SpecJobTaskBuffers {
        const buffers = &self.spec_job_task_buffers;
        if (buffers.contexts.len == 0) {
            buffers.contexts = try self.allocator.alloc(SpecJobTaskContext, capacity);
        } else if (buffers.contexts.len != capacity) {
            Common.compilerBug("Monotype specialization task buffer capacity changed");
        }
        return buffers;
    }

    /// Lower one ordinary queued specialization into an owned workspace epoch
    /// and a graph-free sealed draft. The lane retains the resettable graph, but
    /// only ordered program appends happen after the result crosses the handoff.
    ///
    /// Deferred preparation executes against the worker's private Builder and
    /// workspace. Representation-sensitive iterator callees lower eagerly into
    /// this same draft, so callbacks never mutate coordinator state.
    fn lowerPendingSpecJobToShard(
        self: *Builder,
        worker: *SpecJobWorkerState,
        commit_domain: *SpecJobCommitDomain,
        job: PendingSpecJob,
        view: ModuleView,
        method_scope: ModuleView,
        template: checked.CheckedProcedureTemplate,
    ) Allocator.Error!CompletedSpecJobShard {
        switch (template.target) {
            .roc,
            .intrinsic,
            .entry,
            .comptime_only,
            => {},
            .hosted => Common.compilerBug("hosted specialization entered Roc body shard lowering"),
        }

        if (self.symbols.active != .coordinator) {
            Common.compilerBug("Monotype specialization shard entered with a worker-local symbol domain active");
        }
        self.symbols.worker_local = .{};
        self.symbols.active = .worker_local;
        defer self.symbols.active = .coordinator;

        const workspace = &worker.workspace;
        var digest_stats: Type.Store.DigestStats = .{};
        workspace.types.digest_stats = if (self.counters != null) &digest_stats else null;
        defer {
            workspace.types.digest_stats = null;
            self.addDigestStats(digest_stats);
        }
        const epoch = workspace.beginEpoch(self.program);
        errdefer workspace.finishEpoch(epoch);
        const program_types_before = self.program.types.epochBoundary();
        const program_names_before = self.program.names.epochBoundary();
        const program_loc_before = self.program.current_loc;
        const program_region_before = self.program.current_region;
        if (self.active_spec_job_diagnostics != null) {
            Common.compilerBug("Monotype specialization shard began with another shard diagnostic sink active");
        }
        const shard_diagnostics: ?*SpecJobDiagnostics = if (self.diagnostics != null) blk: {
            const diagnostics = try self.allocator.create(SpecJobDiagnostics);
            diagnostics.* = .{};
            break :blk diagnostics;
        } else null;
        errdefer if (shard_diagnostics) |diagnostics| self.allocator.destroy(diagnostics);
        self.active_spec_job_diagnostics = shard_diagnostics;
        defer self.active_spec_job_diagnostics = null;
        const graph = try self.acquireSpecJobGraph(worker);
        var body_draft = BodyDraftStore.init(self.allocator);
        errdefer body_draft.deinit();
        body_draft.spec_job_workspace = workspace;
        body_draft.mutable_graph_names = &workspace.name_store;
        const saved_graph = self.active_graph;
        const saved_body_draft = self.active_body_draft;
        self.active_graph = graph;
        self.active_body_draft = &body_draft;
        defer self.active_graph = saved_graph;
        defer self.active_body_draft = saved_body_draft;
        const final_guard = FinalBodyOutputGuard.begin(self);
        const pending = try self.lowerReservedTemplateBodyIntoDraft(
            graph,
            &body_draft,
            job.reservation,
            job.fn_template,
            job.template_ref,
            view,
            method_scope,
            template,
            job.source_fn_key,
            job.fn_ty,
            job.evidence,
            job.subst,
            null,
            job.signature_relation,
            job.codec_contract,
        );
        const final_end = final_guard.end(self);
        try self.finalizeBodyDraftGraph(graph, &body_draft, final_guard, final_end);
        const sealed_pending = try self.sealOrdinarySpecJobDraft(graph, &body_draft, pending);
        body_draft.sealWorkerLocalSymbols(self.symbols.worker_local.next);
        if (self.spec_job_parallel_callback) {
            const program_types_after = self.program.types.epochBoundary();
            if (!std.meta.eql(program_types_before, program_types_after)) {
                Common.compilerBug("parallel specialization lowering mutated the coordinator type store");
            }
            if (!std.meta.eql(program_names_before, self.program.names.epochBoundary())) {
                Common.compilerBug("parallel specialization lowering mutated the coordinator name store");
            }
            if (!std.meta.eql(program_loc_before, self.program.current_loc) or
                !std.meta.eql(program_region_before, self.program.current_region))
            {
                Common.compilerBug("parallel specialization lowering mutated coordinator source scratch");
            }
        }
        const summaries = try self.allocator.dupe(InterfaceSummaryEntry, workspace.interface_summaries.entries.items[workspace.captured_interface_summaries..]);
        errdefer self.allocator.free(summaries);
        var store_epoch = try workspace.captureStoreEpoch(epoch);
        workspace.captured_interface_summaries = workspace.interface_summaries.entries.items.len;
        errdefer store_epoch.deinit();
        self.countBodyDiagnostic("spec_job_shards_lowered");
        workspace.finishEpoch(epoch);
        return .{
            .worker_id = worker.worker_id,
            .commit_domain = commit_domain,
            .dispatch_index = job.dispatch_index,
            .worker_local_symbol_count = body_draft.worker_local_symbol_count,
            .interface_summaries = summaries,
            .store_epoch = store_epoch,
            .body_draft = body_draft,
            .pending = sealed_pending,
            .diagnostics = shard_diagnostics,
        };
    }

    /// Accept one frozen shard in logical dispatch order and reuse the existing
    /// exhaustive draft-to-program relocation commit.
    fn commitCompletedSpecJobShard(
        self: *Builder,
        shard: *CompletedSpecJobShard,
    ) Allocator.Error!void {
        self.requireNextSpecAcceptance(shard.dispatch_index);
        if (shard.diagnostics_committed) {
            Common.compilerBug("Monotype specialization shard diagnostics were committed more than once");
        }
        if (shard.store_epoch_absorbed) {
            Common.compilerBug("Monotype specialization shard store epoch was absorbed more than once");
        }
        if (self.active_spec_job_diagnostics != null) {
            Common.compilerBug("Monotype specialization shard committed with another shard diagnostic sink active");
        }
        self.active_spec_job_diagnostics = shard.diagnostics;
        defer self.active_spec_job_diagnostics = null;

        const commit_domain = shard.commit_domain;
        try commit_domain.absorb(&shard.store_epoch);
        shard.store_epoch_absorbed = true;
        const committed_type_relocation = commit_domain.committedTypeRelocation(
            self.program,
        );
        var committed_types = CommittedGraphTypes.relocatedStore(
            &commit_domain.types,
            &commit_domain.name_store,
            &self.program.types,
            &self.program.names,
            committed_type_relocation,
        );
        try self.commitInterfaceSummaries(shard.interface_summaries, &committed_types);
        if (shard.worker_local_symbol_count != shard.body_draft.worker_local_symbol_count) {
            Common.compilerBug("Monotype specialization shard symbol count disagreed with its sealed draft");
        }
        shard.body_draft.relocateWorkerLocalSymbols(&self.symbols.coordinator);
        shard.body_draft.assertGraphStateDiscarded();
        const sealed = try self.commitSealedBodyDraft(
            &shard.body_draft,
            shard.pending.root_ty,
            &committed_types,
            null,
        );
        defer sealed.deinit(self.allocator);
        var completion_timing_scope = ProcedureTimingScope.begin(self.timing, .completion);
        defer completion_timing_scope.end();
        try self.finishReservedTemplateBody(shard.pending, sealed.ids, sealed.root_ty.?);
        if (shard.diagnostics) |diagnostics| {
            const destination = self.diagnostics orelse
                Common.compilerBug("Monotype specialization shard lost its coordinator diagnostic sink");
            diagnostics.addTo(destination);
        }
        if (shard.specialization_counter_delta) |delta| {
            const destination = self.counters orelse
                Common.compilerBug("Monotype specialization shard lost its coordinator counter sink");
            addFlatCounters(SpecializationCounters, destination, delta);
        }
        shard.diagnostics_committed = true;
        self.countCoordinatorBodyDiagnostic("spec_job_shards_committed");
        self.acceptSpecDispatch(shard.dispatch_index);
    }

    /// Commit one root shard after its worker epoch joins the cumulative lane
    /// domain, recovering the wrapper def from the exhaustive draft commit.
    fn commitCompletedProcedureRootShard(
        self: *Builder,
        shard: *CompletedProcedureRootShard,
    ) Allocator.Error!Ast.DefId {
        if (shard.diagnostics_committed or shard.store_epoch_absorbed) {
            Common.compilerBug("procedure root shard was committed more than once");
        }
        const commit_domain = shard.commit_domain;
        try commit_domain.absorb(&shard.store_epoch);
        shard.store_epoch_absorbed = true;
        var committed_types = CommittedGraphTypes.relocatedStore(
            &commit_domain.types,
            &commit_domain.name_store,
            &self.program.types,
            &self.program.names,
            commit_domain.committedTypeRelocation(self.program),
        );
        try self.commitInterfaceSummaries(shard.interface_summaries, &committed_types);
        if (shard.worker_local_symbol_count != shard.body_draft.worker_local_symbol_count) {
            Common.compilerBug("procedure root shard symbol count disagreed with its sealed draft");
        }
        shard.body_draft.relocateWorkerLocalSymbols(&self.symbols.coordinator);
        shard.body_draft.assertGraphStateDiscarded();
        const sealed = try self.commitSealedBodyDraft(
            &shard.body_draft,
            shard.root_ty,
            &committed_types,
            shard.root_def,
        );
        defer sealed.deinit(self.allocator);
        const def = sealed.root_def orelse
            Common.invariant("procedure root shard did not commit its wrapper definition");
        if (shard.diagnostics) |diagnostics| diagnostics.addTo(self.diagnostics.?);
        if (shard.specialization_counter_delta) |delta| {
            addFlatCounters(SpecializationCounters, self.counters.?, delta);
        }
        shard.diagnostics_committed = true;
        return def;
    }

    fn lowerReservedTemplateBodyIntoDraft(
        self: *Builder,
        graph: *InstGraph,
        body_draft: *BodyDraftStore,
        reservation: TemplateReservation,
        fn_template: Ast.FnTemplate,
        template_ref: names.ProcTemplate,
        view: ModuleView,
        method_scope: ModuleView,
        template: checked.CheckedProcedureTemplate,
        source_fn_key: names.TypeDigest,
        lower_fn_ty: Type.TypeId,
        spec_evidence: []const SpecEvidence,
        subst: ?SealedSubstitution,
        retained_topology: ?EvidenceChain,
        signature_relation: Ast.SignatureRelation,
        codec_contract: ?SealedCodecContractContext,
    ) Allocator.Error!PendingTemplateBody {
        var graph_setup_timing_scope = ProcedureTimingScope.begin(self.timing, .body_graph_setup);
        defer graph_setup_timing_scope.end();
        const saved_graph = self.active_graph;
        const saved_body_draft = self.active_body_draft;
        const saved_template_root = self.active_template_root;
        self.active_graph = graph;
        self.active_body_draft = body_draft;
        defer self.active_graph = saved_graph;
        defer self.active_body_draft = saved_body_draft;
        defer self.active_template_root = saved_template_root;

        var body_ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self,
            view,
            method_scope,
            template_ref,
            graph,
            body_draft,
        );
        body_ctx.evidence = retained_topology orelse rootEvidence(template_ref, spec_evidence);
        defer body_ctx.deinit();
        if (subst) |sealed| {
            // The body instantiates the template under the request's
            // substitution: every quantified variable is its requester's cell.
            const live = try body_ctx.substitutionFromSealed(sealed);
            const schema = templateSchemaIn(view, &template);
            if (retained_topology == null) {
                body_ctx.evidence = rootEvidenceWithSubstitution(template_ref, schema, .{ .subst = live, .vector = spec_evidence });
            }
            try body_ctx.seedSubstitution(schema, live);
        } else if (retained_topology == null) {
            body_ctx.evidence = try body_ctx.rootEvidenceAtOwnScheme(template, spec_evidence);
        }

        const graph_fn_ty = try body_ctx.importProgramType(lower_fn_ty);

        const root_node = try body_ctx.relateCheckedFunctionToMono(template.checked_fn_root, graph_fn_ty);
        const draft_codec_contract: ?DraftCodecContractContext = if (codec_contract) |contract| .{
            .anchor = contract.anchor,
            .constructor_node = try body_ctx.activeNodeFromType(
                try body_ctx.importProgramType(contract.constructor_ty),
            ),
            .shape_node = try body_ctx.activeNodeFromType(try body_ctx.importProgramType(contract.shape_ty)),
        } else null;
        if (draft_codec_contract) |contract| {
            try body_ctx.instantiateCodecContractAtCall(
                contract.anchor,
                contract.constructor_node,
                contract.shape_node,
            );
        }
        self.active_template_root = .{
            .graph = graph,
            .family = DraftTemplateFamilyAddress.init(template_ref, method_scope.key, source_fn_key),
            .evidence = body_ctx.evidence.vector,
            .subst = body_ctx.evidence.subst,
            .request_fn_node = root_node,
            .initial_request_arg_classes = try graph.snapshotFunctionArgumentClasses(root_node),
            .codec_contract = draft_codec_contract,
            .fn_id = reservation.fn_id,
            .reserved_fn_ty = fn_template.mono_fn_ty,
            .signature_relation = signature_relation,
        };
        const root_owner = try body_draft.enterOwner(.{ .reserved_fn = reservation.fn_id });
        defer root_owner.leave();
        graph_setup_timing_scope.end();

        // The durable request remains an immutable snapshot. The body keeps
        // the related request node until the shared draft's single final seal
        // creates the solved function type.
        {
            var dispatch_timing_scope = ProcedureTimingScope.begin(self.timing, .dispatch_evidence);
            defer dispatch_timing_scope.end();
            try body_ctx.instantiateTemplateDispatchRelations(template, null);
        }
        body_ctx.owner_context_fn_key = source_fn_key;
        body_ctx.current_fn_key = source_fn_key;
        const lowered = try body_ctx.lowerTemplateBodyAtNode(template_ref, template, root_node);
        const final_signature_relation = self.active_template_root.?.signature_relation;
        const completed_root = blk: {
            var relations_timing_scope = ProcedureTimingScope.begin(self.timing, .body_graph_setup);
            defer relations_timing_scope.end();
            break :blk switch (final_signature_relation) {
                .exact_graph => root_node,
                .independent_roots => try body_ctx.completedFunctionNodeForLoweredRet(
                    root_node,
                    lowered.ret,
                    try body_ctx.exprCarriesFunctionDefinitionEvidence(lowered.body),
                ),
            };
        };
        return .{
            .reservation = reservation,
            .fn_template = fn_template,
            .signature_relation = final_signature_relation,
            .root_node = completed_root,
            .lowered = lowered,
        };
    }

    fn finishReservedTemplateBody(
        self: *Builder,
        pending: anytype,
        body_ids: FinalIdOffsets,
        final_fn_ty: Type.TypeId,
    ) Allocator.Error!void {
        // The definition records the body's solved view of the root type.
        // Call sites embed the requested type; a solved request determines
        // every interface slot, and root-class call sites adopt this recorded
        // template directly rather than recomputing an identity, so the two
        // views never race. (Interface digests are alias-opaque, so a
        // requested and a solved view that differ only by alias wrapping
        // would be distinct identities—acceptable because only the recorded
        // template is consulted.)
        var def_template = pending.fn_template;
        def_template.mono_fn_ty = switch (pending.signature_relation) {
            // An exact signature keeps the producer-authored request type. The
            // independently solved body may seal to an equal, distinct TypeId.
            .exact_graph => pending.fn_template.mono_fn_ty,
            .independent_roots => final_fn_ty,
        };
        self.program.setFnSource(pending.reservation.fn_id, def_template);
        const sealed_fn_data = self.programFunctionShape(final_fn_ty, "checked procedure template root type was not a function");
        self.program.setDef(pending.reservation.def, .{
            .symbol = pending.reservation.symbol,
            .fn_def = def_template,
            .fn_id = pending.reservation.fn_id,
            .args = body_ids.typedLocalSpan(pending.lowered.args),
            .body = .{ .roc = body_ids.expr(pending.lowered.body) },
            .ret = sealed_fn_data.ret,
        });
        try self.markTemplateReady(pending.reservation.fn_id, final_fn_ty);
    }

    fn lowerDraftTemplateFromContext(
        self: *Builder,
        source_ctx: *BodyContext,
        template_ref: names.ProcTemplate,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        raw_request_fn_node: NodeId,
        partial_edge: EdgeEvidence,
        request_edge: DraftRequestEdge,
        signature_relation: Ast.SignatureRelation,
        codec_contract_selection: CodecContractSelection,
    ) Allocator.Error!DraftFnSlot {
        self.count("template_requests");
        const request_fn_node = try source_ctx.graph.functionRequestRoot(raw_request_fn_node);
        const codec_contract: ?DraftCodecContractContext = switch (codec_contract_selection) {
            .inherit => source_ctx.activeCodecContractContext(),
            .independent => null,
            .anchored => |anchor| source_ctx.activeCodecContractContextForAnchor(anchor),
        };
        const view = self.moduleForDigest(names.procTemplateModuleDigest(template_ref));
        const template = view.templates.get(template_ref.template);
        if (partial_edge.vector.len > template.evidence_params.len) {
            Common.invariant("draft procedure specialization received more evidence than its checked requirements");
        }
        var edge = if (partial_edge.vector.len == template.evidence_params.len)
            partial_edge
        else
            try self.completeRootTemplateEvidence(view, template_ref, template, partial_edge);
        edge.vector = try source_ctx.resolveCallableEvidenceAtNode(
            view,
            template,
            edge.vector,
            request_fn_node,
            .body_lowering,
        );
        const evidence = edge.vector;
        const family = DraftTemplateFamilyAddress.init(template_ref, source_ctx.method_scope.key, source_fn_key);

        // The globally reserved root is the active ancestor of recursive calls
        // in its own specialization graph. A checked recursive reference to it
        // reuses that exact function instead of deferring a sibling body:
        // doing so keeps recursion within one Monotype instantiation context
        // and lets recursive representation evidence (notably forced-dynamic
        // iterator flow) reach the root before its single seal.
        if (self.active_template_root) |active_root| {
            if (active_root.graph == source_ctx.graph and
                active_root.family.sameRecursiveCallable(family) and
                (try specEvidenceVectorEql(self.allocator, active_root.evidence, evidence)) and
                draftCodecContractSpecializationEql(
                    active_root.codec_contract,
                    codec_contract,
                ))
            {
                const exact_interface = (try source_ctx.graph.sameFunctionInterface(
                    active_root.request_fn_node,
                    request_fn_node,
                ));
                const active_recursive_edge = source_ctx.draft.ownerDescendsFromReservedFn(
                    source_ctx.draft.current_owner,
                    active_root.fn_id,
                );
                const partial_recursive_allowed = active_recursive_edge and
                    request_edge == .recursive_reference and
                    substitutionsShareClasses(source_ctx.graph, active_root.subst, edge.subst);
                if (exact_interface or partial_recursive_allowed) {
                    if (active_recursive_edge) {
                        try source_ctx.graph.unifyRecursiveFunctionInterface(
                            active_root.request_fn_node,
                            active_root.initial_request_arg_classes,
                            request_fn_node,
                        );
                    } else {
                        try source_ctx.graph.unify(active_root.request_fn_node, request_fn_node);
                    }
                    if (!(try source_ctx.graph.sameFunctionInterface(active_root.request_fn_node, request_fn_node))) {
                        Common.invariant("recursive root request did not join its complete function interface");
                    }
                    self.promoteFnSignatureRelation(active_root.fn_id, signature_relation);
                    self.count("template_hits");
                    return .{ .local = .{ .final = active_root.fn_id } };
                }
            }
        }

        const stored_evidence = try self.constFnEvidence(rootEvidence(template_ref, evidence));
        const evidence_digest = stored_evidence.digest;
        const structural_lexical_dependent = template.target != .hosted and
            source_ctx.local_proc_contexts.count() != 0 and
            (try specEvidenceContainsStructural(self.allocator, evidence) or
                (codec_contract != null and source_ctx.activeCodecContractContainsLocalTarget()));
        const lexical_context_key: ?names.TypeDigest = if (structural_lexical_dependent)
            try source_ctx.codecLexicalContextKey()
        else
            null;
        const local_evidence_owner = try specEvidenceLocalOwner(self.allocator, source_ctx.draft, evidence);
        const local_context_dependent = local_evidence_owner != null or structural_lexical_dependent;
        const lexical_owner = local_evidence_owner orelse if (structural_lexical_dependent)
            source_ctx.draft.current_owner
        else
            null;

        // Draft specialization identity stays graph-native for the entire
        // relation-production phase. Even a currently resolved request can
        // still be joined by later body/evidence relations, so it must not be
        // promoted to a durable TypeId before the single final seal.
        var selection = DraftOpenCandidateSelection{};
        const resolved_request_ty: ?Type.TypeId = try source_ctx.specializationLookupTypeForNode(request_fn_node);
        // Closed requests—and requests whose only open cells have the explicit
        // required field-kind default—key on an immutable structural view, so
        // a repeat skips the graph-native recursive lookup below. The latter
        // view does not mutate the live request; a hit joins the live
        // interfaces below.
        const lookup_prefix = try source_ctx.draft.template_spec_lookup.internPrefix(family, evidence_digest.bytes);
        const resolved_lookup_address: ?DraftTemplateLookupAddress = if (resolved_request_ty) |request_fn_ty| .{
            .digest = .{
                .prefix = lookup_prefix,
                .kind = .closed,
                .digest = source_ctx.specializationTypeDigest(request_fn_ty).bytes,
            },
        } else null;
        if (resolved_lookup_address) |address| {
            if (source_ctx.draft.template_spec_lookup.get(address)) |candidate_iterator| {
                var candidates = candidate_iterator;
                while (candidates.next()) |raw_spec| {
                    const spec = &source_ctx.draft.template_specs.items[raw_spec];
                    if (!try specEvidenceVectorEql(self.allocator, spec.evidence, evidence)) continue;
                    if (!optionalTypeDigestEql(spec.lexical_context_key, lexical_context_key)) continue;
                    if (!draftTemplateSpecVisibleFrom(source_ctx.draft, spec, source_ctx.draft.current_owner)) continue;
                    if (!draftCodecContractSpecializationEql(spec.codec_contract, codec_contract)) continue;
                    const spec_fn_ty = (try source_ctx.specializationLookupTypeForNode(draftTemplateSpecLookupRequestNode(spec))) orelse continue;
                    if (!try source_ctx.typeStore().typeEql(source_ctx.nameStore(), spec_fn_ty, resolved_request_ty.?)) continue;
                    if (!selection.add(raw_spec, true)) unreachable;
                }
            }
        }
        if (selection.selected() == null) {
            const open_pairs = source_ctx.draft.template_spec_lookup.openPairs(lookup_prefix);
            // A fresh prefix has no registrations. Avoid even collecting its
            // interface: no open candidate can exist for this exact family.
            if (open_pairs.len != 0) {
                var seen_specs = std.AutoHashMap(u32, void).init(self.allocator);
                defer seen_specs.deinit();
                var interface_roots: std.ArrayList(NodeId) = .empty;
                defer interface_roots.deinit(self.allocator);
                var interface = try source_ctx.graph.functionInterfaceClassIterator(request_fn_node);
                defer interface.deinit();
                while (try interface.next()) |root| try interface_roots.append(self.allocator, root);
                var candidates = DraftTemplateSpecLookup.OpenIterator{
                    .pairs = open_pairs,
                    .graph = source_ctx.graph,
                    .interface_roots = interface_roots.items,
                };
                while (candidates.next()) |raw_spec| {
                    const seen = try seen_specs.getOrPut(raw_spec);
                    if (seen.found_existing) continue;
                    const spec = &source_ctx.draft.template_specs.items[raw_spec];
                    if (!try specEvidenceVectorEql(self.allocator, spec.evidence, evidence)) continue;
                    if (!optionalTypeDigestEql(spec.lexical_context_key, lexical_context_key)) continue;
                    if (!draftTemplateSpecVisibleFrom(source_ctx.draft, spec, source_ctx.draft.current_owner)) continue;
                    if (!draftCodecContractSpecializationEql(spec.codec_contract, codec_contract)) continue;
                    const exact_interface = (try source_ctx.graph.sameFunctionInterface(
                        draftTemplateSpecLookupRequestNode(spec),
                        request_fn_node,
                    ));
                    const active_recursive_edge = source_ctx.draft.ownerDescendsFromDraftFn(
                        source_ctx.draft.current_owner,
                        spec.fn_id,
                    );
                    const partial_recursive_allowed = active_recursive_edge and
                        request_edge == .recursive_reference and
                        substitutionsShareClasses(source_ctx.graph, spec.subst, edge.subst);
                    if (!draftOpenCandidateQualifies(
                        spec.state,
                        exact_interface,
                        active_recursive_edge,
                        partial_recursive_allowed,
                    )) continue;
                    if (!selection.add(raw_spec, exact_interface)) {
                        Common.invariant("draft template request matched more than one partial active recursive specialization");
                    }
                }
            }
            // Independently instantiated calls do not necessarily share graph
            // cells with the specialization currently being lowered. Once both
            // requests are closed or defaultable only by the declared required
            // field-kind rule, exact structural type equality proves that they
            // are the same specialization request. This scan retains graph-
            // interface identity for active recursive and partially overlapping
            // requests.
            if (resolved_request_ty) |request_fn_ty| {
                const template_candidates = source_ctx.draft.template_specs_by_template.get(template_ref);
                for (if (template_candidates) |list| list.items else &.{}) |raw_spec| {
                    const spec = &source_ctx.draft.template_specs.items[raw_spec];
                    // The checked source root selects the template body, but it is
                    // not part of a resolved specialization's identity. Recursive
                    // calls can reach the same template through a different checked
                    // root; exact interface, evidence, and lexical context prove
                    // that they refer to the same active specialization.
                    if (!try specEvidenceVectorEql(self.allocator, spec.evidence, evidence)) continue;
                    if (!optionalTypeDigestEql(spec.lexical_context_key, lexical_context_key)) continue;
                    if (!draftTemplateSpecVisibleFrom(source_ctx.draft, spec, source_ctx.draft.current_owner)) continue;
                    if (!draftCodecContractSpecializationEql(spec.codec_contract, codec_contract)) continue;
                    const spec_fn_ty = (try source_ctx.specializationLookupTypeForNode(draftTemplateSpecLookupRequestNode(spec))) orelse continue;
                    if (!try source_ctx.typeStore().typeEql(source_ctx.nameStore(), spec_fn_ty, request_fn_ty)) continue;
                    if (!selection.add(raw_spec, true)) unreachable;
                }
            }
        }
        if (selection.selected()) |raw_spec| {
            // A lowering specialization reached through an explicitly shared
            // interface class is a recursive edge. Fresh checked variables in
            // its new body instance are not joined until that edge is related,
            // so join the complete request before returning the in-progress
            // definition. Completed specializations reach here through exact
            // resolved identity, never through a partial interface overlap.
            const spec = &source_ctx.draft.template_specs.items[raw_spec];
            self.count("template_hits");
            const request_owner = source_ctx.draft.current_owner;
            const candidate_owner = source_ctx.draft.fns.items[@backingInt(spec.fn_id)].parent_owner;
            switch (request_owner) {
                .reserved_fn => |requesting_root| switch (candidate_owner) {
                    .reserved_fn => |candidate_root| _ = candidate_root != requesting_root,
                    .root, .draft_fn => {},
                },
                .root, .draft_fn => {},
            }
            const active_recursive_edge = spec.state == .lowering and
                source_ctx.draft.ownerDescendsFromDraftFn(source_ctx.draft.current_owner, spec.fn_id);
            if (active_recursive_edge) {
                try source_ctx.graph.unifyRecursiveFunctionInterface(
                    draftTemplateSpecLookupRequestNode(spec),
                    spec.initial_request_arg_classes,
                    request_fn_node,
                );
            } else {
                try source_ctx.graph.unify(draftTemplateSpecLookupRequestNode(spec), request_fn_node);
            }
            if (!(try source_ctx.graph.sameFunctionInterface(draftTemplateSpecLookupRequestNode(spec), request_fn_node))) {
                Common.invariant("recursive draft template request did not join its complete function interface");
            }
            if (signature_relation == .exact_graph) {
                source_ctx.draft.fns.items[@backingInt(spec.fn_id)].signature_relation = .exact_graph;
            }
            if (spec.state != .deferred and !runtimeDemandGuardFrameSetsEql(
                spec.runtime_demand_guard_frames,
                try source_ctx.runtimeDemandGuardFrameAddresses(),
            )) {
                try source_ctx.draft.template_spec_reuses.append(self.allocator, .{
                    .spec = raw_spec,
                    .prefix_proof = try source_ctx.currentRuntimeImpossibilityProof(null),
                });
            }
            // The closed address memoizes this hit only when the join left
            // the request's lookup type unchanged: `resolved_request_ty` is
            // the pre-join view, the selected specialization's is the
            // post-join one. A partial recursive join can leave that
            // interface with open cells the lookup view does not admit, in
            // which case the memo is simply skipped and later requests take
            // the open-interface and resolved scans.
            if (resolved_lookup_address) |address| {
                if (try source_ctx.specializationLookupTypeForNode(draftTemplateSpecLookupRequestNode(spec))) |active_spec_fn_ty| {
                    if (try source_ctx.typeStore().typeEql(
                        source_ctx.nameStore(),
                        active_spec_fn_ty,
                        resolved_request_ty.?,
                    )) {
                        try registerTemplateSpecLookup(source_ctx.draft, address, raw_spec);
                    }
                }
            }
            return .{ .local = .{ .draft = spec.fn_id } };
        }
        const is_local = moduleBytesEqual(view.key.bytes, names.procTemplateModuleDigest(template_ref).bytes);
        const fn_def: Ast.FnDef = switch (template.target) {
            .hosted => self.fnDefForHostedTemplate(template_ref, is_local),
            .roc, .intrinsic, .entry, .comptime_only => if (is_local)
                .{ .local_template = template_ref }
            else
                .{ .imported_template = template_ref },
        };
        const symbol = self.symbols.fresh();
        const fn_id = try source_ctx.draft.addFn(.{
            .source = .{
                .fn_def = fn_def,
                .source_fn_ty = source_fn_ty,
                .source_fn_key = source_fn_key,
                .mono_fn_ty = DraftTypeCell.fromGraphNode(request_fn_node),
                .evidence_digest = evidence_digest,
                .const_evidence = try source_ctx.draft.addConstFnEvidence(stored_evidence.nodes),
                .const_evidence_frames = try source_ctx.draft.addConstFnEvidenceFrames(stored_evidence.frames),
                .const_evidence_frame_head = stored_evidence.head,
            },
            .signature_relation = signature_relation,
        });
        self.count("template_misses");
        if (local_context_dependent and template.target == .hosted) {
            Common.invariant("hosted template specialization depended on a local procedure context");
        }
        if (local_context_dependent) {
            self.countBodyDiagnostic("caller_owned_template_bodies_lowered");
        } else {
            self.countBodyDiagnostic("deferred_template_requests");
        }
        const spec_index = source_ctx.draft.template_specs.items.len;
        const lexical = if (local_context_dependent)
            try source_ctx.captureCodecLexicalContext()
        else
            null;
        var lexical_needs_cleanup = lexical != null;
        errdefer if (lexical_needs_cleanup) {
            if (lexical) |captured| {
                self.allocator.free(captured.binders);
                self.allocator.free(captured.local_procs);
            }
        };
        const demand_boundary: u32 = @intCast(source_ctx.draft.runtime_value_demands.items.len);
        try source_ctx.draft.template_specs.append(self.allocator, .{
            .state = if (local_context_dependent) .lowering else .deferred,
            .template_ref = template_ref,
            .method_scope = source_ctx.method_scope.key,
            .source_fn_ty = source_fn_ty,
            .source_fn_key = source_fn_key,
            .symbol = symbol,
            .request_fn_node = request_fn_node,
            .initial_request_arg_classes = try source_ctx.graph.snapshotFunctionArgumentClasses(request_fn_node),
            .evidence = evidence,
            .subst = edge.subst,
            .runtime_demand_guard_frames = try source_ctx.runtimeDemandGuardFrameAddresses(),
            .demand_start = demand_boundary,
            .demand_end = demand_boundary,
            .demand_frame_floor = source_ctx.runtime_demand_guard_frames,
            .requires_local = local_context_dependent,
            .local_context_dependent = local_context_dependent,
            .lexical_owner = lexical_owner,
            .lexical = lexical,
            .lexical_context_key = lexical_context_key,
            .codec_contract = codec_contract,
            .fn_id = fn_id,
        });
        lexical_needs_cleanup = false;
        const template_bucket = try source_ctx.draft.template_specs_by_template.getOrPut(template_ref);
        if (!template_bucket.found_existing) template_bucket.value_ptr.* = .empty;
        try template_bucket.value_ptr.append(self.allocator, @intCast(spec_index));
        try source_ctx.draft.template_spec_by_fn.put(fn_id, @intCast(spec_index));
        try updateTemplateSpecInterfaceLookups(
            source_ctx.draft,
            self.allocator,
            source_ctx.graph,
            lookup_prefix,
            request_fn_node,
            @intCast(spec_index),
        );
        if (resolved_lookup_address) |address| {
            try registerTemplateSpecLookup(source_ctx.draft, address, @intCast(spec_index));
        }
        const owner_scope = try source_ctx.draft.enterOwner(.{ .draft_fn = fn_id });
        defer owner_scope.leave();
        try self.registerDraftProcDebugNameForTemplate(source_ctx.draft, symbol, view, template_ref);

        var body_ctx = try BodyContext.initWithMethodScope(self.allocator, self, view, source_ctx.method_scope, template_ref, source_ctx.graph, source_ctx.draft);
        body_ctx.evidence = rootEvidenceWithSubstitution(template_ref, templateSchemaIn(view, &template), edge);
        try body_ctx.seedSubstitution(body_ctx.evidence.schema.?, edge.subst);
        body_ctx.runtime_demand_guard_frames = source_ctx.runtime_demand_guard_frames;
        body_ctx.frozen_sealed_emission = source_ctx.frozen_sealed_emission;
        body_ctx.frozen_type_finals = source_ctx.frozen_type_finals;
        body_ctx.frozen_codec_calls = source_ctx.frozen_codec_calls;
        body_ctx.frozen_field_defaults = source_ctx.frozen_field_defaults;
        defer body_ctx.deinit();
        if (lexical) |captured| try body_ctx.restoreCodecLexicalContext(captured);
        const root_node = try body_ctx.instNode(template.checked_fn_root);
        // A request whose result row includes this template's closed checked
        // row keeps its extra labels: the rows are related component-wise and
        // the adapter is generated when the specialization completes
        // (design.md "Result-Row Widening Adapter"). Hosted templates take
        // their own capability-driven relation below, where the declared row
        // is the host ABI.
        //
        // A caller-owned (local-context-dependent) specialization has no such
        // completion: it lowers its body inline at `root_node` below and
        // registers the def at the declared interface, so no adapter would
        // ever be generated and the caller would call the narrow body through
        // its wide request. Declining here leaves the ordinary relation—and
        // its loud rejection of a widened closed row—in charge.
        const closed_row_widened = template.target != .hosted and
            try relateClosedResultRowRequestInterface(
                source_ctx.graph,
                view,
                template.checked_fn_root,
                root_node,
                request_fn_node,
                if (local_context_dependent) .no_adapter else .adapter_reachable,
            );
        var hosted_widened = false;
        if (closed_row_widened) {
            // Every component was related above; joining the two function
            // interfaces here would unify the rows this relation kept apart.
        } else if (!local_context_dependent and
            signature_relation == .independent_roots and
            template.target != .hosted)
        {
            const public_request = source_ctx.graph.requestSourceInterface(request_fn_node) orelse request_fn_node;
            try constrainDeferredTemplateTypeArguments(source_ctx.graph, root_node, public_request);
            try relateConstructionFunctionRequestInterface(source_ctx.graph, root_node, request_fn_node);
        } else {
            if (template.target == .hosted) {
                // Hosted Try Question Widening is the instance of the rule
                // where the declared row is the host ABI; the adapter keeps the
                // extern boundary at the declared type.
                hosted_widened = try relateHostedFunctionRequestInterface(
                    source_ctx.graph,
                    try self.hostedTryAdapterCapability(view, template.hosted_try_adapter),
                    root_node,
                    request_fn_node,
                );
            } else if (try source_ctx.graph.containsGeneratedPrivate(request_fn_node)) {
                if (source_ctx.graph.requestSourceInterface(request_fn_node)) |source_fn_node| {
                    try relateFunctionRequestInterface(source_ctx.graph, root_node, source_fn_node);
                }
                try relateFunctionRequestInterface(source_ctx.graph, root_node, request_fn_node);
            } else {
                try source_ctx.graph.unify(root_node, request_fn_node);
            }
        }
        // This is the one relation whose answer becomes the specialization's
        // own: completion mints the widening adapter exactly when this record
        // says the relation declined to unify the two rows, instead of deriving
        // a second answer from the checked root (design.md "Result-Row Widening
        // Adapter").
        const widened_result_row = closed_row_widened or hosted_widened;
        source_ctx.draft.template_specs.items[spec_index].widened_result_row = widened_result_row;
        if (!widened_result_row and
            !local_context_dependent and
            signature_relation != .independent_roots and
            template.target != .hosted)
        {
            try relateFunctionRequestInterface(source_ctx.graph, root_node, request_fn_node);
        }
        if (codec_contract) |contract| {
            try body_ctx.instantiateCodecContractAtCall(
                contract.anchor,
                contract.constructor_node,
                contract.shape_node,
            );
        }
        if (!local_context_dependent) {
            // A deferred body lowers in its own specialization, so only an
            // open interface needs the template's relations applied here. A
            // codec contract instantiated into this body above is part of
            // those relations' input, so they run in this body.
            if (!templateInterfaceIsClosed(view, &template) and templateHasInterfaceRelations(view, &template)) {
                if (codec_contract == null) {
                    if (try source_ctx.applyTemplateInterfaceRelations(
                        template_ref,
                        view,
                        template,
                        family,
                        stored_evidence,
                        edge,
                        request_fn_node,
                        &source_ctx.draft.interface_replay,
                    )) |expansion| try source_ctx.runInterfaceRelationFrames(.{ .callee = expansion });
                } else {
                    try body_ctx.instantiateTemplateDispatchRelations(template, null);
                    try body_ctx.applyCheckedTemplateInterfaceRelations(template, root_node);
                }
            }
            return .{ .local = .{ .draft = fn_id } };
        }
        try body_ctx.instantiateTemplateDispatchRelations(template, null);
        try body_ctx.applyCheckedTemplateInterfaceRelations(template, root_node);
        if (template.target == .hosted) {
            Common.invariant("hosted template specialization depended on a local procedure context");
        }
        body_ctx.owner_context_fn_key = source_fn_key;
        body_ctx.current_fn_key = source_fn_key;
        // A generated-private request is the exact runtime interface owned by
        // this specialization. The checked root remains the public interface
        // used to instantiate dispatch relations, but lowering the body
        // against it would discard the producer-supplied private backing from
        // parameters and returns.
        const body_fn_node = if (try source_ctx.graph.containsGeneratedPrivate(request_fn_node))
            request_fn_node
        else
            root_node;
        const lowered = try body_ctx.lowerTemplateBodyAtNode(template_ref, template, body_fn_node);
        const completed_fn_node = try body_ctx.completedFunctionNodeForLoweredRet(
            body_fn_node,
            lowered.ret,
            try body_ctx.exprCarriesFunctionDefinitionEvidence(lowered.body),
        );
        const completed_fn_ret = (try source_ctx.graph.functionNodes(completed_fn_node)).ret;
        const completed_ret_cell = DraftTypeCell.fromGraphNode(completed_fn_ret);

        var completed_template = source_ctx.draft.fns.items[@backingInt(fn_id)].source;
        completed_template.mono_fn_ty = DraftTypeCell.fromGraphNode(completed_fn_node);
        _ = try source_ctx.draft.addNestedDef(.{
            .symbol = symbol,
            .fn_def = completed_template,
            .fn_id = .{ .draft = fn_id },
            .args = lowered.args,
            .body = lowered.body,
            .ret = completed_ret_cell,
        });
        source_ctx.draft.fns.items[@backingInt(fn_id)].source = completed_template;
        source_ctx.draft.template_specs.items[spec_index].request_fn_node = completed_fn_node;
        try updateTemplateSpecInterfaceLookups(
            source_ctx.draft,
            self.allocator,
            source_ctx.graph,
            lookup_prefix,
            completed_fn_node,
            @intCast(spec_index),
        );
        source_ctx.draft.template_specs.items[spec_index].state = .lowered;
        source_ctx.draft.template_specs.items[spec_index].demand_end =
            @intCast(source_ctx.draft.runtime_value_demands.items.len);
        return .{ .local = .{ .draft = fn_id } };
    }

    /// Lower one already-registered context-free specialization into the
    /// caller's graph and body store when its iterator representation is needed
    /// before the ordinary deferred coordinator boundary.
    fn lowerDraftTemplateSpecBody(
        self: *Builder,
        source_ctx: *BodyContext,
        spec_index: usize,
        view: ModuleView,
        template: checked.CheckedProcedureTemplate,
    ) Allocator.Error!NodeId {
        if (spec_index >= source_ctx.draft.template_specs.items.len) {
            Common.invariant("draft template body index was outside the specialization table");
        }
        const spec = source_ctx.draft.template_specs.items[spec_index];
        if (spec.state != .lowering) {
            Common.invariant("draft template body lowering began outside the lowering state");
        }
        if (spec.local_context_dependent) {
            Common.invariant("context-free draft template lowering received lexical state");
        }
        if (template.target == .hosted) {
            Common.invariant("hosted template entered Roc draft body lowering");
        }

        const fn_id = spec.fn_id;
        const top_level_def = try source_ctx.draft.reserveDef(.{ .draft_fn = fn_id });
        source_ctx.draft.template_specs.items[spec_index].def_id = top_level_def;

        const owner_scope = try source_ctx.draft.enterOwner(.{ .draft_fn = fn_id });
        defer owner_scope.leave();
        try self.registerDraftProcDebugNameForTemplate(
            source_ctx.draft,
            spec.symbol,
            view,
            spec.template_ref,
        );

        var body_ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self,
            view,
            source_ctx.method_scope,
            spec.template_ref,
            source_ctx.graph,
            source_ctx.draft,
        );
        body_ctx.evidence = rootEvidenceWithSubstitution(
            spec.template_ref,
            templateSchemaIn(view, &template),
            .{ .vector = spec.evidence, .subst = spec.subst },
        );
        try body_ctx.seedSubstitution(body_ctx.evidence.schema.?, spec.subst);
        body_ctx.runtime_demand_guard_frames = source_ctx.runtime_demand_guard_frames;
        body_ctx.frozen_sealed_emission = source_ctx.frozen_sealed_emission;
        body_ctx.frozen_type_finals = source_ctx.frozen_type_finals;
        body_ctx.frozen_codec_calls = source_ctx.frozen_codec_calls;
        body_ctx.frozen_field_defaults = source_ctx.frozen_field_defaults;
        defer body_ctx.deinit();
        if (spec.lexical) |captured| try body_ctx.restoreCodecLexicalContext(captured);

        const root_node = try body_ctx.instNode(template.checked_fn_root);
        if (source_ctx.draft.fns.items[@backingInt(fn_id)].signature_relation == .independent_roots) {
            const public_request = source_ctx.graph.requestSourceInterface(spec.request_fn_node) orelse
                spec.request_fn_node;
            try constrainDeferredTemplateTypeArguments(source_ctx.graph, root_node, public_request);
            try relateConstructionFunctionRequestInterface(source_ctx.graph, root_node, spec.request_fn_node);
        } else if (try source_ctx.graph.containsGeneratedPrivate(spec.request_fn_node)) {
            if (source_ctx.graph.requestSourceInterface(spec.request_fn_node)) |source_fn_node| {
                try relateFunctionRequestInterface(source_ctx.graph, root_node, source_fn_node);
            }
            try relateFunctionRequestInterface(source_ctx.graph, root_node, spec.request_fn_node);
        } else {
            try source_ctx.graph.unify(root_node, spec.request_fn_node);
        }
        if (source_ctx.draft.fns.items[@backingInt(fn_id)].signature_relation != .independent_roots) {
            try relateFunctionRequestInterface(source_ctx.graph, root_node, spec.request_fn_node);
        }
        if (spec.codec_contract) |contract| {
            try body_ctx.instantiateCodecContractAtCall(
                contract.anchor,
                contract.constructor_node,
                contract.shape_node,
            );
        }
        try body_ctx.instantiateTemplateDispatchRelations(template, null);
        try body_ctx.applyCheckedTemplateInterfaceRelations(template, root_node);
        body_ctx.owner_context_fn_key = spec.source_fn_key;
        body_ctx.current_fn_key = spec.source_fn_key;

        // A generated-private request is the exact runtime interface owned by
        // this specialization. The checked root remains the public interface
        // used to instantiate dispatch relations, but lowering the body
        // against it would discard the producer-supplied private backing from
        // parameters and returns.
        const body_fn_node = if (try source_ctx.graph.containsGeneratedPrivate(spec.request_fn_node))
            spec.request_fn_node
        else
            root_node;
        const lowered = try body_ctx.lowerTemplateBodyAtNode(spec.template_ref, template, body_fn_node);
        const completed_fn_node = try body_ctx.completedFunctionNodeForLoweredRet(
            body_fn_node,
            lowered.ret,
            try body_ctx.exprCarriesFunctionDefinitionEvidence(lowered.body),
        );
        const completed_fn_ret = (try source_ctx.graph.functionNodes(completed_fn_node)).ret;
        const completed_ret_cell = DraftTypeCell.fromGraphNode(completed_fn_ret);

        var completed_template = source_ctx.draft.fns.items[@backingInt(fn_id)].source;
        completed_template.mono_fn_ty = DraftTypeCell.fromGraphNode(completed_fn_node);
        source_ctx.draft.setDef(top_level_def, .{
            .symbol = spec.symbol,
            .fn_def = completed_template,
            .fn_id = .{ .draft = fn_id },
            .args = lowered.args,
            .body = .{ .roc = lowered.body },
            .ret = completed_ret_cell,
        });
        source_ctx.draft.fns.items[@backingInt(fn_id)].source = completed_template;
        source_ctx.draft.template_specs.items[spec_index].request_fn_node = completed_fn_node;
        const lookup_prefix = try source_ctx.draft.template_spec_lookup.internPrefix(
            DraftTemplateFamilyAddress.init(
                spec.template_ref,
                spec.method_scope,
                spec.source_fn_key,
            ),
            completed_template.evidence_digest.bytes,
        );
        try updateTemplateSpecInterfaceLookups(
            source_ctx.draft,
            self.allocator,
            source_ctx.graph,
            lookup_prefix,
            completed_fn_node,
            @intCast(spec_index),
        );
        source_ctx.draft.template_specs.items[spec_index].state = .lowered;
        source_ctx.draft.template_specs.items[spec_index].demand_end =
            @intCast(source_ctx.draft.runtime_value_demands.items.len);
        return completed_fn_node;
    }

    fn markTemplateReady(self: *Builder, fn_id: Ast.FnId, fn_ty: Type.TypeId) Allocator.Error!void {
        const entry = self.lowered_templates.get(fn_id) orelse
            Common.invariant("lowered procedure template definition disappeared before completion");
        try self.spec_store.markReady(entry.spec, fn_ty, self.specializationTypeDigest(fn_ty));
    }

    fn typedLocalsForArgs(self: *Builder, arg_tys: anytype) Allocator.Error!Ast.Span(Ast.TypedLocal) {
        const args = try self.allocator.alloc(Ast.TypedLocal, GuardedList.borrowLen(arg_tys));
        defer self.allocator.free(args);
        for (0..GuardedList.borrowLen(arg_tys)) |index| {
            const arg_ty = GuardedList.at(arg_tys, index);
            args[index] = .{
                .local = try self.program.addLocal(self.symbols.fresh(), arg_ty),
                .ty = arg_ty,
            };
        }
        return try self.program.addTypedLocalSpan(args);
    }

    fn fnDefForTemplate(
        self: *Builder,
        view: ModuleView,
        template: names.ProcTemplate,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        mono_fn_ty: Type.TypeId,
    ) Ast.FnTemplate {
        const fn_def: Ast.FnDef = switch (view.templates.get(template.template).target) {
            .hosted => self.fnDefForHostedTemplate(template, moduleBytesEqual(view.key.bytes, names.procTemplateModuleDigest(template).bytes)),
            .roc,
            .intrinsic,
            .entry,
            .comptime_only,
            => if (moduleBytesEqual(view.key.bytes, names.procTemplateModuleDigest(template).bytes))
                .{ .local_template = template }
            else
                .{ .imported_template = template },
        };

        return .{
            .fn_def = fn_def,
            .source_fn_ty = source_fn_ty,
            .source_fn_key = source_fn_key,
            .mono_fn_ty = mono_fn_ty,
        };
    }

    fn addTemplateSpecRecord(
        self: *Builder,
        template_ref: names.ProcTemplate,
        method_scope: checked.ModuleId,
        evidence: StoredConstFnEvidence,
        request_fn_ty: Type.TypeId,
        request_fn_ty_digest: names.TypeDigest,
        codec_contract: ?Ast.CodecContractIdentity,
        fn_id: Ast.FnId,
        status: Ast.SpecStatus,
    ) Allocator.Error!Ast.SpecId {
        const evidence_digest = evidence.digest;
        return try self.addSpecRecord(
            self.templateSpecIdentity(
                template_ref,
                method_scope,
                evidence_digest,
                codec_contract,
                request_fn_ty,
                request_fn_ty_digest,
            ),
            evidence,
            null,
            fn_id,
            status,
        );
    }

    fn addNestedSpecRecord(
        self: *Builder,
        nested: Ast.NestedFn,
        method_scope: checked.ModuleId,
        evidence: StoredConstFnEvidence,
        program_span: ?specialize.ProgramEvidenceSpan,
        capture_abi_digest: names.TypeDigest,
        codec_contract: ?Ast.CodecContractIdentity,
        request_fn_ty: Type.TypeId,
        request_fn_ty_digest: names.TypeDigest,
        fn_id: Ast.FnId,
    ) Allocator.Error!Ast.SpecId {
        const evidence_digest = evidence.digest;
        return try self.addSpecRecord(
            self.nestedSpecIdentity(nested, method_scope, evidence_digest, capture_abi_digest, codec_contract, request_fn_ty, request_fn_ty_digest),
            evidence,
            program_span,
            fn_id,
            .lowering,
        );
    }

    fn addSpecRecord(
        self: *Builder,
        identity: Ast.SpecIdentity,
        evidence: StoredConstFnEvidence,
        program_span: ?specialize.ProgramEvidenceSpan,
        fn_id: Ast.FnId,
        status: Ast.SpecStatus,
    ) Allocator.Error!Ast.SpecId {
        var view = specializationEvidenceView(evidence);
        view.program_span = program_span;
        const reserved = try self.spec_store.reserve(identity, view, fn_id);
        if (!reserved.created) Common.invariant("Monotype specialization record already existed before lowering registered it");
        const spec = reserved.spec orelse Common.invariant("fresh Monotype specialization record resolved to an imported target");
        switch (status) {
            .reserved => {},
            .lowering => self.spec_store.markLowering(spec),
            .ready => Common.invariant("fresh Monotype specialization record cannot be created ready"),
        }
        return spec;
    }

    fn registerProcDebugNameForTemplate(
        self: *Builder,
        symbol: Common.Symbol,
        view: ModuleView,
        template: names.ProcTemplate,
    ) Allocator.Error!void {
        if (!self.proc_debug_names) return;
        const proc_base = view.names.procBase(template.proc_base);
        const export_name = proc_base.export_name orelse return;
        const name = try self.program.names.internExportName(view.names.exportNameText(export_name));
        try self.program.setProcDebugName(symbol, name);
    }

    fn registerDraftProcDebugNameForTemplate(
        self: *Builder,
        draft: *BodyDraftStore,
        symbol: Common.Symbol,
        view: ModuleView,
        template: names.ProcTemplate,
    ) Allocator.Error!void {
        if (!self.proc_debug_names) return;
        const proc_base = view.names.procBase(template.proc_base);
        const export_name = proc_base.export_name orelse return;
        const name = try self.activeNameStore().internExportName(view.names.exportNameText(export_name));
        try draft.proc_debug_names.append(self.allocator, .{ .symbol = symbol, .name = name });
    }

    fn fnDefForProcedureBindingBody(
        self: *Builder,
        view: ModuleView,
        body: checked.ProcedureBindingBody,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        mono_fn_ty: Type.TypeId,
    ) Ast.FnTemplate {
        return switch (body) {
            .direct_template => |direct| self.fnDefForCallableTemplate(view, direct.template, source_fn_ty, source_fn_key, mono_fn_ty),
            .checked_error => Common.invariant("rejected binding reached Monotype callable consumption"),
            .callable_eval_template => Common.invariant("callable eval template must be restored through ConstStore before Monotype lowering"),
        };
    }

    fn fnDefForCallableTemplate(
        self: *Builder,
        view: ModuleView,
        template: names.CallableProcTemplate,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        mono_fn_ty: Type.TypeId,
    ) Ast.FnTemplate {
        return switch (template) {
            .checked => |checked_template| self.fnDefForTemplate(view, checked_template, source_fn_ty, source_fn_key, mono_fn_ty),
            .lifted,
            .synthetic,
            => Common.invariant("checked procedure binding referenced a post-check function template"),
        };
    }

    /// Materialize a context-free Monotype request through the same explicit
    /// instantiation/freeze boundary as an ordinary requested specialization.
    /// A generalized checked field kind can therefore default for this one
    /// root without entering `type_cache` as a context-free required layout
    /// that would poison a later optional specialization.
    fn lowerContextFreeSpecializationType(
        self: *Builder,
        view: ModuleView,
        owner_template: names.ProcTemplate,
        checked_ty: checked.CheckedTypeId,
    ) Allocator.Error!Type.TypeId {
        const destination_types = self.activeTypeStore();
        const destination_names = self.activeNameStore();
        const workspace = if (self.active_body_draft) |draft| draft.spec_job_workspace else null;
        const graph = try self.createGraphForStores(destination_types, destination_names);
        defer graph.destroy();
        const saved_graph = self.active_graph;
        const saved_body_draft = self.active_body_draft;
        self.active_graph = graph;
        defer self.active_graph = saved_graph;
        var body_draft = BodyDraftStore.init(self.allocator);
        body_draft.spec_job_workspace = workspace;
        body_draft.mutable_graph_names = destination_names;
        self.active_body_draft = &body_draft;
        defer self.active_body_draft = saved_body_draft;
        defer body_draft.deinit();
        var ctx = try BodyContext.init(self.allocator, self, view, owner_template, graph, &body_draft);
        defer ctx.deinit();
        const node = try ctx.instNode(checked_ty);
        try graph.freezeRelations();
        return try graph.sealNode(node);
    }

    /// One step of lowering a checked type: a child type, or the part of a
    /// record field or tag that follows its lowered type.
    const TypeLowerOp = union(enum) {
        child: checked.CheckedTypeId,
        field: checked.CheckedRecordField,
        tag: checked.CheckedTag,
    };

    /// A checked type whose children are still lowering. Its ops occupy
    /// `ops[ops_start..]` and their results `results[results_start..]`.
    const TypeLowerFrame = struct {
        view: ModuleView,
        address: CheckedTypeAddress,
        checked_ty: checked.CheckedTypeId,
        payload: checked.CheckedTypePayload,
        /// Null for an alias, which shares its backing's type.
        slot: ?Type.Store.RecursiveSlot,
        ops_start: usize,
        next: usize,
        results_start: usize,
        fields_start: usize,
        tags_start: usize,
        /// A named frame's entry in `nominals`, present once its args and
        /// backing are built and its declared order is lowering.
        nominals_start: usize,
        declared_start: usize,
    };

    /// One declared field of a nominal's record backing, in declared order.
    const DeclaredOrderOp = union(enum) {
        named: struct { view: ModuleView, name: names.RecordFieldNameId },
        padding: struct { view: ModuleView, ty: checked.CheckedTypeId },
    };

    /// A named type whose declared order is lowering: its padding types lower
    /// as child frames, one at a time and in declared order.
    const NominalTypeLowering = struct {
        named: @FieldType(Type.Content, "named"),
        /// Null when the nominal has no declared order.
        ops: ?[]DeclaredOrderOp,
        next: usize = 0,
        awaiting_padding: bool = false,
    };

    const TypeLowerRun = struct {
        frames: std.ArrayListUnmanaged(TypeLowerFrame) = .empty,
        ops: std.ArrayListUnmanaged(TypeLowerOp) = .empty,
        results: std.ArrayListUnmanaged(Type.TypeId) = .empty,
        fields: std.ArrayListUnmanaged(Type.Field) = .empty,
        tags: std.ArrayListUnmanaged(Type.Tag) = .empty,
        nominals: std.ArrayListUnmanaged(NominalTypeLowering) = .empty,
        declared: std.ArrayListUnmanaged(Type.DeclaredField) = .empty,

        fn deinit(type_run: *TypeLowerRun, allocator: Allocator) void {
            for (type_run.nominals.items) |nominal| {
                if (nominal.ops) |ops| allocator.free(ops);
            }
            type_run.nominals.deinit(allocator);
            type_run.declared.deinit(allocator);
            type_run.tags.deinit(allocator);
            type_run.fields.deinit(allocator);
            type_run.results.deinit(allocator);
            type_run.ops.deinit(allocator);
            type_run.frames.deinit(allocator);
        }
    };

    /// Lower a checked type. Each composite type is an explicit frame whose
    /// children lower in order, so type depth never becomes native call depth.
    fn lowerType(self: *Builder, view: ModuleView, checked_ty: checked.CheckedTypeId) Allocator.Error!Type.TypeId {
        var type_run = TypeLowerRun{};
        defer type_run.deinit(self.allocator);
        errdefer for (type_run.frames.items) |frame| {
            if (frame.slot) |slot| {
                self.activeTypeStore().abortRecursive(slot);
                break;
            }
        };
        if (try self.enterLowerType(&type_run, view, checked_ty)) |ty| return ty;
        while (true) {
            const index = type_run.frames.items.len - 1;
            const frame = type_run.frames.items[index];
            if (frame.next < type_run.ops.items.len) {
                const op = type_run.ops.items[frame.next];
                type_run.frames.items[index].next += 1;
                switch (op) {
                    .child => |child| if (try self.enterLowerType(&type_run, frame.view, child)) |ty| {
                        try type_run.results.append(self.allocator, ty);
                    },
                    .field => |field| {
                        const value_ty = type_run.results.pop().?;
                        try type_run.fields.append(self.allocator, .{
                            .name = try self.recordFieldName(frame.view, field.name),
                            .ty = switch (field.kind.tag) {
                                .required, .defaulted => value_ty,
                                .optional => try self.optionalSlotType(value_ty),
                                .undetermined => Common.invariant("undetermined checked field kind reached direct record-row lowering"),
                                .err => Common.invariant("poisoned checked field kind reached direct record-row lowering"),
                            },
                            .value_ty = if (field.kind.tag == .optional) value_ty else null,
                            .default = try self.monoFieldDefault(frame.view, field),
                        });
                    },
                    .tag => |tag| {
                        const arg_count = tag.argsSlice(frame.view.types).len;
                        const payloads = type_run.results.items[type_run.results.items.len - arg_count ..];
                        const tag_name = try self.tagName(frame.view, tag.name);
                        const span = try self.activeTypeStore().addSpan(payloads);
                        type_run.results.shrinkRetainingCapacity(type_run.results.items.len - arg_count);
                        try type_run.tags.append(self.allocator, .{
                            .name = tag_name,
                            .checked_name = tag_name,
                            .payloads = span,
                        });
                    },
                }
                continue;
            }

            const ty = try self.finishLowerType(&type_run, frame) orelse continue;
            _ = type_run.frames.pop();
            type_run.ops.shrinkRetainingCapacity(frame.ops_start);
            type_run.results.shrinkRetainingCapacity(frame.results_start);
            type_run.fields.shrinkRetainingCapacity(frame.fields_start);
            type_run.tags.shrinkRetainingCapacity(frame.tags_start);
            for (type_run.nominals.items[frame.nominals_start..]) |nominal| {
                if (nominal.ops) |ops| self.allocator.free(ops);
            }
            type_run.nominals.shrinkRetainingCapacity(frame.nominals_start);
            type_run.declared.shrinkRetainingCapacity(frame.declared_start);
            if (type_run.frames.items.len == 0) return ty;
            try type_run.results.append(self.allocator, ty);
        }
    }

    /// The lowered type when it needs no new root; otherwise push the frame
    /// that lowers it.
    fn enterLowerType(self: *Builder, type_run: *TypeLowerRun, view: ModuleView, checked_ty: checked.CheckedTypeId) Allocator.Error!?Type.TypeId {
        const address = checkedTypeAddress(view, checked_ty);
        const cache = self.activeCheckedTypeCache();
        if (cache.get(address)) |cached| return cached;
        const raw = @backingInt(checked_ty);
        if (raw >= view.types.payloadCount()) Common.invariant("checked type id outside checked type store");

        const payload = view.types.payload(checked_ty);
        // Alias spelling belongs to checked data. Share the backing's runtime
        // identity, just as scoped instantiation does, before reserving any
        // type storage. Checking rules out alias-only cycles and phantom alias
        // arguments; recursive structure closes through the backing's memo.
        const slot: ?Type.Store.RecursiveSlot = if (payload == .alias) null else blk: {
            const reserved = try self.activeTypeStore().beginRecursive();
            try cache.put(address, reserved.ty);
            break :blk reserved;
        };
        const frame: TypeLowerFrame = .{
            .view = view,
            .address = address,
            .checked_ty = checked_ty,
            .payload = payload,
            .slot = slot,
            .ops_start = type_run.ops.items.len,
            .next = type_run.ops.items.len,
            .results_start = type_run.results.items.len,
            .fields_start = type_run.fields.items.len,
            .tags_start = type_run.tags.items.len,
            .nominals_start = type_run.nominals.items.len,
            .declared_start = type_run.declared.items.len,
        };
        try type_run.frames.append(self.allocator, frame);
        try self.appendLowerTypeOps(type_run, view, payload);
        return null;
    }

    fn appendLowerTypeOps(self: *Builder, type_run: *TypeLowerRun, view: ModuleView, payload: checked.CheckedTypePayload) Allocator.Error!void {
        const gpa = self.allocator;
        switch (payload) {
            .pending,
            .err,
            .flex,
            .rigid,
            .empty_record,
            .empty_tag_union,
            => {},
            .alias => |alias| try type_run.ops.append(gpa, .{ .child = alias.backing }),
            .record => |record| {
                var current_fields = record.fields;
                var current = record.ext;
                var seen = collections.DenseMap(checked.CheckedTypeId, void).init(gpa);
                defer seen.deinit();
                while (true) {
                    for (current_fields) |field| {
                        try type_run.ops.append(gpa, .{ .child = field.ty });
                        try type_run.ops.append(gpa, .{ .field = field });
                    }
                    current_fields = &.{};
                    if (seen.contains(current)) break;
                    try seen.put(current, {});
                    switch (checkedPayload(view, current)) {
                        .alias => |alias| current = alias.backing,
                        .empty_record => break,
                        .flex, .rigid => |variable| {
                            if (variable.row_default == .empty_record) break;
                            Common.invariant("open non-record checked row reached Monotype record lowering");
                        },
                        .record => |ext_record| {
                            current_fields = ext_record.fields;
                            current = ext_record.ext;
                        },
                        .pending, .err, .tuple, .nominal, .function, .tag_union, .empty_tag_union => Common.invariant("open or non-record checked row reached Monotype record lowering"),
                    }
                }
            },
            .tuple => |items| for (items) |item| try type_run.ops.append(gpa, .{ .child = item }),
            .tag_union => |tag_union| {
                var current_tags = tag_union.tags;
                var current = tag_union.ext;
                var seen = collections.DenseMap(checked.CheckedTypeId, void).init(gpa);
                defer seen.deinit();
                while (true) {
                    for (current_tags) |tag| {
                        for (tag.argsSlice(view.types)) |arg| try type_run.ops.append(gpa, .{ .child = arg });
                        try type_run.ops.append(gpa, .{ .tag = tag });
                    }
                    current_tags = &.{};
                    if (seen.contains(current)) break;
                    try seen.put(current, {});
                    switch (checkedPayload(view, current)) {
                        .alias => |alias| current = alias.backing,
                        .empty_tag_union => break,
                        .flex, .rigid => |variable| {
                            if (variable.row_default == .empty_tag_union) break;
                            Common.invariant("open non-tag checked row reached Monotype tag-union lowering");
                        },
                        .tag_union => |ext_union| {
                            current_tags = ext_union.tags;
                            current = ext_union.ext;
                        },
                        .pending, .err, .record, .tuple, .nominal, .function, .empty_record => Common.invariant("open or non-tag checked row reached Monotype tag-union lowering"),
                    }
                }
            },
            .function => |fn_ty| {
                for (fn_ty.args) |arg| try type_run.ops.append(gpa, .{ .child = arg });
                try type_run.ops.append(gpa, .{ .child = fn_ty.ret });
            },
            .nominal => |nominal| {
                switch (nominal.representation) {
                    .builtin => |builtin| switch (checked.builtinRuntimeEncoding(builtin)) {
                        .primitive => return,
                        .list, .box => {
                            if (nominal.args.len != 1) Common.invariant("checked List and Box nominals must have exactly one type argument");
                            return try type_run.ops.append(gpa, .{ .child = nominal.args[0] });
                        },
                        .bool_tag_union,
                        .try_nominal,
                        .iterator,
                        .parse_tag_union_spec,
                        .fields,
                        .field,
                        .dict,
                        .set,
                        .crypto_sha256_digest,
                        .crypto_sha256_hasher,
                        .crypto_blake3_digest,
                        .crypto_blake3_hasher,
                        => {},
                    },
                    .local_declaration, .imported_declaration, .local_box_payload_capability, .imported_box_payload_capability, .opaque_without_backing => {},
                }
                for (nominal.args) |arg| try type_run.ops.append(gpa, .{ .child = arg });
            },
        }
    }

    /// Build the frame's type from its lowered children, or null when a named
    /// type's padding type is lowering first as a child frame.
    fn finishLowerType(self: *Builder, type_run: *TypeLowerRun, frame: TypeLowerFrame) Allocator.Error!?Type.TypeId {
        if (type_run.nominals.items.len > frame.nominals_start) return try self.continueNominalLowering(type_run, frame);
        const results = type_run.results.items[frame.results_start..];
        const slot = frame.slot orelse {
            // An alias shares its backing's type.
            try self.activeCheckedTypeCache().put(frame.address, results[0]);
            return results[0];
        };
        const view = frame.view;
        const content: Type.Content = switch (frame.payload) {
            .pending => Common.invariant("pending checked type reached Monotype lowering"),
            .err => Common.invariant("erroneous checked type reached Monotype lowering"),
            .flex, .rigid => |variable| lowerCheckedTypeVariable(variable),
            .empty_record => .{ .record = .empty() },
            .empty_tag_union => .{ .tag_union = .empty() },
            .record => .{ .record = try self.activeTypeStore().addRecordFields(self.activeNameStore(), type_run.fields.items[frame.fields_start..]) },
            .tuple => .{ .tuple = try self.activeTypeStore().addSpan(results) },
            .tag_union => .{ .tag_union = try self.activeTypeStore().addTagVariants(self.activeNameStore(), type_run.tags.items[frame.tags_start..]) },
            .function => .{ .func = .{
                .args = try self.activeTypeStore().addSpan(results[0 .. results.len - 1]),
                .ret = results[results.len - 1],
            } },
            .alias => Common.invariant("transparent alias reserved a Monotype wrapper"),
            .nominal => |nominal| blk: {
                switch (nominal.representation) {
                    .builtin => |builtin| switch (checked.builtinRuntimeEncoding(builtin)) {
                        .primitive => |primitive| break :blk .{ .primitive = primitive },
                        .list => break :blk .{ .list = results[0] },
                        .box => break :blk .{ .box = results[0] },
                        .bool_tag_union,
                        .try_nominal,
                        .iterator,
                        .parse_tag_union_spec,
                        .fields,
                        .field,
                        .dict,
                        .set,
                        .crypto_sha256_digest,
                        .crypto_sha256_hasher,
                        .crypto_blake3_digest,
                        .crypto_blake3_hasher,
                        => {},
                    },
                    .local_declaration, .imported_declaration, .local_box_payload_capability, .imported_box_payload_capability, .opaque_without_backing => {},
                }

                const args = try self.allocator.dupe(Type.TypeId, results);
                defer self.allocator.free(args);
                const backing_use: Type.BackingUse = if (nominal.is_opaque) .runtime_layout_only else .inspectable;
                const def = try self.typeDef(view, nominal.origin_module, nominal.name, nominal.source_decl);
                self.noteBuiltinTryDef(nominal.builtin, self.activeNameStore(), def);
                const named: @FieldType(Type.Content, "named") = .{
                    .named_type = .{ .module = self.declaredModuleForNominal(view, nominal), .ty = frame.checked_ty },
                    .def = def,
                    .kind = if (nominal.is_opaque) .@"opaque" else .nominal,
                    .builtin_owner = builtinOwner(nominal.builtin),
                    .args = try self.activeTypeStore().addSpan(args),
                    .backing = switch (nominal.representation) {
                        .opaque_without_backing => null,
                        .builtin, .local_declaration, .imported_declaration, .local_box_payload_capability, .imported_box_payload_capability => .{
                            .ty = try self.lowerNominalBackingType(view, nominal, args),
                            .use = backing_use,
                        },
                    },
                };
                const ops = try self.declaredOrderOps(view, nominal);
                type_run.nominals.append(self.allocator, .{ .named = named, .ops = ops }) catch |err| {
                    if (ops) |owned| self.allocator.free(owned);
                    return err;
                };
                return try self.continueNominalLowering(type_run, frame);
            },
        };
        self.activeTypeStore().finishRecursive(slot, content);
        return slot.ty;
    }

    /// Lower the frame's declared order up to its next padding type that
    /// needs a child frame, then finish the named type.
    fn continueNominalLowering(self: *Builder, type_run: *TypeLowerRun, frame: TypeLowerFrame) Allocator.Error!?Type.TypeId {
        const index = frame.nominals_start;
        if (type_run.nominals.items[index].awaiting_padding) {
            type_run.nominals.items[index].awaiting_padding = false;
            try type_run.declared.append(self.allocator, .{ .padding = type_run.results.pop().? });
        }
        const nominal = type_run.nominals.items[index];
        if (nominal.ops) |ops| {
            var next = nominal.next;
            while (next < ops.len) : (next += 1) {
                switch (ops[next]) {
                    .named => |named| try type_run.declared.append(self.allocator, .{ .named = try self.recordFieldName(named.view, named.name) }),
                    .padding => |padding| {
                        type_run.nominals.items[index].next = next + 1;
                        if (try self.enterLowerType(type_run, padding.view, padding.ty)) |ty| {
                            try type_run.declared.append(self.allocator, .{ .padding = ty });
                            continue;
                        }
                        type_run.nominals.items[index].awaiting_padding = true;
                        return null;
                    },
                }
            }
        }
        var named = nominal.named;
        if (nominal.ops != null) {
            named.declared_order = try self.activeTypeStore().addDeclaredFields(type_run.declared.items[frame.declared_start..]);
        }
        const slot = frame.slot.?;
        self.activeTypeStore().finishRecursive(slot, .{ .named = named });
        return slot.ty;
    }

    fn lowerCheckedTypeVariable(variable: checked.CheckedTypeVariable) Type.Content {
        if (variable.numeric_default_phase) |phase| {
            const target = checked.literal_defaulting.defaultTargetForPhase(phase) orelse
                Common.invariant("checking-finalized numeric variable reached Monotype unresolved");
            return switch (target) {
                .dec => .{ .primitive = .dec },
                .str => .{ .primitive = .str },
            };
        }
        if (variable.row_default) |row_default| {
            return switch (row_default) {
                .empty_record => .{ .record = .empty() },
                .empty_tag_union => .{ .tag_union = .empty() },
            };
        }
        return .{ .tag_union = .empty() };
    }

    fn namedBackingType(self: *Builder, ty: Type.TypeId) ?Type.TypeId {
        return switch (self.activeTypeStore().get(ty)) {
            .named => |named| if (named.backing) |backing| backing.ty else null,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => null,
        };
    }

    const NominalConstructionLayer = struct {
        named: Type.TypeId,
        backing: Type.TypeId,
    };

    /// The nominal construction layer of `ty`: the nominal or opaque named
    /// type reached after unwrapping transparent alias layers, paired with
    /// its declared backing type. Constructor expressions and patterns
    /// (tags, records, tuples) created at such a type must be typed at the
    /// backing and wrapped in an explicit `.nominal` node per layer, so that
    /// "the value is `.nominal`-wrapped" holds exactly when the type is
    /// nominal, independent of whether the source construction was written
    /// qualified. Returns null when `ty` is structural, an alias of a
    /// structural type, or a named type whose backing is not present.
    fn nominalConstructionLayer(self: *Builder, ty: Type.TypeId) ?NominalConstructionLayer {
        return nominalConstructionLayerIn(NominalConstructionLayer, self.activeTypeStore(), ty);
    }

    fn shapeContent(self: *Builder, ty: Type.TypeId) Type.Content {
        return shapeContentFromStore(self.activeTypeStore(), ty);
    }

    fn shapeContentFromStore(type_store: *const Type.Store, ty: Type.TypeId) Type.Content {
        var current = ty;
        while (true) {
            switch (type_store.get(current)) {
                .named => |named| if (named.backing) |backing| {
                    current = backing.ty;
                    continue;
                } else {
                    return type_store.get(current);
                },
                .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return type_store.get(current),
            }
        }
    }

    fn functionShape(self: *Builder, ty: Type.TypeId, comptime message: []const u8) FunctionShape {
        return switch (self.shapeContent(ty)) {
            .func => |func| .{ .args = func.args, .ret = func.ret },
            .primitive, .named, .record, .tuple, .tag_union, .list, .box, .erased, .zst => Common.invariant(message),
        };
    }

    fn programFunctionShape(self: *Builder, ty: Type.TypeId, comptime message: []const u8) FunctionShape {
        return switch (shapeContentFromStore(&self.program.types, ty)) {
            .func => |func| .{ .args = func.args, .ret = func.ret },
            .primitive, .named, .record, .tuple, .tag_union, .list, .box, .erased, .zst => Common.invariant(message),
        };
    }

    fn tupleItemSpan(self: *Builder, ty: Type.TypeId) Type.Span {
        return switch (self.shapeContent(ty)) {
            .tuple => |items| items,
            .primitive, .named, .record, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("tuple pattern had a non-tuple checked type"),
        };
    }

    fn recordFieldsSpan(self: *Builder, ty: Type.TypeId) Type.Span {
        return switch (self.shapeContent(ty)) {
            .record => |fields| fields,
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("record pattern had a non-record checked type"),
        };
    }

    fn tagPayloadSpan(self: *Builder, ty: Type.TypeId, name: names.TagNameId) Type.Span {
        return switch (self.shapeContent(ty)) {
            .tag_union => |tags| {
                const tag_span = self.activeTypeStore().tagSpan(tags);
                for (0..GuardedList.borrowLen(tag_span)) |index| {
                    const tag = GuardedList.at(tag_span, index);
                    if (self.activeNameStore().tagLabelTextEql(tag.name, name)) return tag.payloads;
                }
                Common.invariant("tag pattern was absent from checked tag-union type");
            },
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => Common.invariant("tag pattern had a non-tag-union checked type"),
        };
    }

    fn lowerNominalBackingType(
        self: *Builder,
        view: ModuleView,
        nominal: checked.CheckedNominalType,
        mono_args: []const Type.TypeId,
    ) Allocator.Error!Type.TypeId {
        const destination_types = self.activeTypeStore();
        const destination_names = self.activeNameStore();
        const workspace = if (self.active_body_draft) |draft| draft.spec_job_workspace else null;
        const graph = try self.createGraphForStores(destination_types, destination_names);
        defer graph.destroy();
        const saved_graph = self.active_graph;
        const saved_body_draft = self.active_body_draft;
        self.active_graph = graph;
        defer self.active_graph = saved_graph;
        var body_draft = BodyDraftStore.init(self.allocator);
        body_draft.spec_job_workspace = workspace;
        body_draft.mutable_graph_names = destination_names;
        self.active_body_draft = &body_draft;
        defer self.active_body_draft = saved_body_draft;
        defer body_draft.deinit();
        var ctx = try BodyContext.init(self.allocator, self, view, .{
            .proc_base = undefined, // type-only context; type lowering does not read the owner template
            .template = undefined, // type-only context; type lowering does not read the owner template
        }, graph, &body_draft);
        defer ctx.deinit();
        if (nominal.args.len != mono_args.len) {
            Common.invariant("checked nominal type argument arity differed from monotype named argument arity");
        }
        for (nominal.args, mono_args) |checked_arg, mono_arg| {
            try ctx.constrainTypeToMono(checked_arg, mono_arg);
        }
        const source = ctx.nominalInstantiationSource(&nominal) orelse {
            Common.invariant("nominal backing type lowering could not resolve a declaration-backed nominal");
        };
        const arg_nodes = try graph.arena().alloc(NodeId, mono_args.len);
        for (mono_args, 0..) |mono_arg, index| {
            arg_nodes[index] = try graph.importMono(mono_arg);
        }
        const backing_node = try ctx.instNominalDeclarationBackingNode(source, arg_nodes);
        try graph.freezeRelations();
        const backing = try graph.sealNode(backing_node);
        return try self.structuralBackingForNominal(view, nominal, mono_args, backing);
    }

    fn structuralBackingForNominal(
        self: *Builder,
        view: ModuleView,
        nominal: checked.CheckedNominalType,
        mono_args: []const Type.TypeId,
        backing: Type.TypeId,
    ) Allocator.Error!Type.TypeId {
        const owner_def = try self.typeDef(view, nominal.origin_module, nominal.name, nominal.source_decl);
        var seen = collections.DenseMap(Type.TypeId, void).init(self.allocator);
        defer seen.deinit();
        var current = backing;
        const type_store = self.activeTypeStore();
        while (true) {
            if (seen.contains(current)) return current;
            try seen.put(current, {});
            switch (type_store.get(current)) {
                .named => |named| {
                    if (named.kind != .alias and (!sameTypeDef(named.def, owner_def) or !self.sameNominalArgs(named.args, mono_args))) {
                        return current;
                    }
                    const next = named.backing orelse return current;
                    current = next.ty;
                },
                .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return current,
            }
        }
    }

    fn sameNominalArgs(self: *Builder, actual_span: Type.Span, expected: []const Type.TypeId) bool {
        const type_store = self.activeTypeStore();
        const name_store = self.activeNameStore();
        const actual = type_store.span(actual_span);
        if (actual.len != expected.len) return false;
        for (expected, 0..) |expected_ty, index| {
            const actual_ty = GuardedList.at(actual, index);
            if (actual_ty == expected_ty) continue;
            const actual_digest = type_store.specializationDigest(name_store, actual_ty);
            const expected_digest = type_store.specializationDigest(name_store, expected_ty);
            if (!std.mem.eql(u8, actual_digest.bytes[0..], expected_digest.bytes[0..])) return false;
        }
        return true;
    }

    fn tupleItemTypes(self: *Builder, ty: Type.TypeId) Type.StoreSpanBorrow(Type.TypeId, "spans") {
        return self.activeTypeStore().span(self.tupleItemSpan(ty));
    }

    fn tagPayloadTypes(self: *Builder, ty: Type.TypeId, name: names.TagNameId) Type.StoreSpanBorrow(Type.TypeId, "spans") {
        return self.activeTypeStore().span(self.tagPayloadSpan(ty, name));
    }

    /// The closed structural tagged slot of an optional field:
    /// `[#Missing, #Present(payload)]`. Tag variants normalize to sorted label
    /// order, so `#Missing` is variant 0 (no payload) and `#Present` is
    /// variant 1—the discriminant contract every consumer (construction,
    /// `.?` runtime tests, layout, glue) shares.
    fn optionalSlotType(self: *Builder, payload_ty: Type.TypeId) Allocator.Error!Type.TypeId {
        const type_store = self.activeTypeStore();
        const name_store = self.activeNameStore();
        const missing = try name_store.internTagLabel(optional_slot_missing_tag);
        const present = try name_store.internTagLabel(optional_slot_present_tag);
        const tags = [_]Type.Store.TagInput{
            .{ .name = missing, .checked_name = missing, .payloads = &.{} },
            .{ .name = present, .checked_name = present, .payloads = &.{payload_ty} },
        };
        return try type_store.internTagUnion(name_store, &tags);
    }

    /// Translate a checked `??` identity into the Monotype name store.
    fn monoFieldDefault(self: *Builder, view: ModuleView, field: checked.CheckedRecordField) Allocator.Error!?Type.FieldDefault {
        const default = field.kind.defaultIdentity() orelse return null;
        const origin_module = default.origin() orelse Common.invariant("defaulted checked field carried no default origin module");
        return .{
            .module = try self.activeNameStore().internModuleIdentity(view.names.moduleIdentityBytes(origin_module)),
            .expr_node = default.expr_node,
        };
    }

    /// Stamp every function, definition, and nested definition from a checked template with
    /// whether its module's source calls it at exactly one site, wherever it
    /// was created: a fresh specialization or a restored function value. The
    /// two records of one function carry the same template.
    /// How the input's app fills its platform's requirements, if any module
    /// of the input has platform requirements bound to an app.
    fn platformRequirementFilling(self: *Builder) ?Common.PlatformRequirementFilling {
        var filling: ?Common.PlatformRequirementFilling = null;
        for (self.moduleViews()) |*view| {
            for (view.platform_required_bindings.bindings) |binding| {
                const this: Common.PlatformRequirementFilling = .{
                    .app_module = binding.app_value.artifact.bytes,
                    .relation = binding.relation.bytes,
                };
                if (filling) |existing| {
                    if (!std.meta.eql(existing, this)) Common.invariant("one lowering input had two platform/app requirement relations");
                } else {
                    filling = this;
                }
            }
        }
        return filling;
    }

    fn stampSingleSourceCalls(self: *Builder) void {
        for (0..self.program.fnCount()) |raw| {
            const id: Ast.FnId = @fromBackingInt(@intCast(@as(u32, @intCast(raw))));
            var source = self.program.getFn(id).source;
            if (self.singleSourceCall(source)) {
                source.single_source_call = true;
                self.program.setFnSource(id, source);
            }
        }
        for (0..self.program.defCount()) |raw| {
            const id: Ast.DefId = @fromBackingInt(@intCast(@as(u32, @intCast(raw))));
            var def = self.program.getDef(id);
            var fn_def = def.fn_def orelse continue;
            if (!self.singleSourceCall(fn_def)) continue;
            fn_def.single_source_call = true;
            def.fn_def = fn_def;
            self.program.setDef(id, def);
        }
        for (0..self.program.nestedDefCount()) |raw| {
            const id: Ast.NestedDefId = @fromBackingInt(@intCast(@as(u32, @intCast(raw))));
            var source = self.program.getNestedDef(id).fn_def;
            if (!self.singleSourceCall(source)) continue;
            source.single_source_call = true;
            self.program.setNestedDefSource(id, source);
        }
    }

    fn singleSourceCall(self: *Builder, template: Ast.FnTemplate) bool {
        const checked_template = switch (template.fn_def) {
            .local_template, .imported_template => |checked_template| checked_template,
            .nested, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => return false,
        };
        const view = self.moduleForDigest(names.procTemplateModuleDigest(checked_template));
        return view.templates.templateHasSingleSourceCall(checked_template.template);
    }

    fn moduleForDigest(self: *Builder, module_digest: names.CheckedModuleDigest) ModuleView {
        return self.moduleForKeyBytes(module_digest.bytes) orelse
            Common.invariant("procedure template referenced a checked module that is not in the lowering input");
    }

    /// Resolve a module by its checked key. The index is built once from the
    /// lowering input, which never changes for the builder's lifetime.
    fn moduleForKeyBytes(self: *Builder, key: [32]u8) ?ModuleView {
        if (self.module_index.count() == 0) self.buildModuleIndex();
        const slot = self.module_index.get(key) orelse return null;
        return switch (slot) {
            .root => self.rootModuleView(),
            .import => |index| self.importModuleView(index),
            .relation => |index| self.relationModuleView(index),
        };
    }

    fn rootModuleView(self: *Builder) ModuleView {
        return &self.moduleViews()[0];
    }

    fn importModuleView(self: *Builder, index: usize) ModuleView {
        return &self.moduleViews()[1 + index];
    }

    fn relationModuleView(self: *Builder, index: usize) ModuleView {
        return &self.moduleViews()[1 + self.modules.imports.len + index];
    }

    /// Every input module's view, built on first use.
    fn moduleViews(self: *Builder) []const ModuleViewData {
        if (self.borrowed_module_views) |views| return views;
        if (self.module_views.len != 0) return self.module_views;
        const view_count = 1 + self.modules.imports.len + self.modules.root.relation_modules.len;
        const views = self.allocator.alloc(ModuleViewData, view_count) catch
            Common.compilerBug("module view allocation failed");
        views[0] = moduleViewData(self.root_view);
        for (self.modules.imports, views[1..][0..self.modules.imports.len]) |imported, *view| view.* = moduleViewData(imported);
        for (self.modules.root.relation_modules, views[1 + self.modules.imports.len ..]) |relation, *view| view.* = moduleViewData(relation);
        self.module_views = views;
        return views;
    }

    fn buildModuleIndex(self: *Builder) void {
        // Lookups happen on the coordinator before any worker borrows the
        // builder, so the index is complete before it is shared.
        const view_count = 1 + self.modules.imports.len + self.modules.root.relation_modules.len;
        self.module_index.ensureTotalCapacity(@intCast(view_count)) catch
            Common.compilerBug("module index allocation failed");
        // Later entries never override earlier ones so the search order of the
        // lowering input (root, imports, relations) is preserved exactly.
        for (self.modules.root.relation_modules, 0..) |relation, index| {
            self.module_index.putAssumeCapacity(relation.key.bytes, .{ .relation = @intCast(index) });
        }
        for (self.modules.imports, 0..) |imported, index| {
            self.module_index.putAssumeCapacity(imported.key.bytes, .{ .import = @intCast(index) });
        }
        self.module_index.putAssumeCapacity(self.root_view.key.bytes, .root);
    }

    /// The module view whose content identity matches `origin_hash`, or null
    /// (used to resolve a defaulted field's declaring module—design.md
    /// "Defaulted Fields").
    fn moduleForIdentityHash(self: *Builder, origin_hash: *const [32]u8) ?ModuleView {
        const root = self.rootModuleView();
        if (moduleViewIdentityMatches(root, origin_hash)) return root;
        for (0..self.modules.imports.len) |index| {
            const view = self.importModuleView(index);
            if (moduleViewIdentityMatches(view, origin_hash)) return view;
        }
        for (0..self.modules.root.relation_modules.len) |index| {
            const view = self.relationModuleView(index);
            if (moduleViewIdentityMatches(view, origin_hash)) return view;
        }
        return null;
    }

    fn templateSpecIdentity(
        self: *Builder,
        template_ref: names.ProcTemplate,
        method_scope: checked.ModuleId,
        evidence_digest: Ast.EvidenceDigest,
        codec_contract: ?Ast.CodecContractIdentity,
        request_fn_ty: Type.TypeId,
        request_fn_ty_digest: names.TypeDigest,
    ) Ast.SpecIdentity {
        const view = self.moduleForDigest(names.procTemplateModuleDigest(template_ref));
        return .{
            .callable = .{ .proc_template = .{
                .module = moduleDigestFromId(view.code_generation_key orelse view.key),
                .proc_base = @backingInt(template_ref.proc_base),
                .template = @backingInt(template_ref.template),
            } },
            .method_scope = moduleDigestFromId(self.moduleForId(method_scope).code_generation_key orelse method_scope),
            .evidence_digest = evidence_digest,
            .codec_contract_digest = codecContractIdentityDigest(codec_contract),
            .codec_contract = codec_contract,
            .request_fn_ty_digest = request_fn_ty_digest,
            .request_fn_ty = request_fn_ty,
        };
    }

    fn nestedSpecIdentity(
        self: *Builder,
        nested: Ast.NestedFn,
        method_scope: checked.ModuleId,
        evidence_digest: Ast.EvidenceDigest,
        capture_abi_digest: names.TypeDigest,
        codec_contract: ?Ast.CodecContractIdentity,
        request_fn_ty: Type.TypeId,
        request_fn_ty_digest: names.TypeDigest,
    ) Ast.SpecIdentity {
        const view = self.moduleForDigest(names.procTemplateModuleDigest(nested.owner));
        var context_hasher = TypeDigestHasher.init();
        context_hasher.update("roc.monotype.nested_capture_abi");
        context_hasher.update(&nested.context_fn_key.bytes);
        context_hasher.update(&capture_abi_digest.bytes);
        return .{
            .callable = .{ .nested_site = .{
                .module = moduleDigestFromId(view.code_generation_key orelse view.key),
                .owner_proc_base = @backingInt(nested.owner.proc_base),
                .owner_template = @backingInt(nested.owner.template),
                .owner_fn_digest = .{ .bytes = context_hasher.finalResult() },
                .site = @backingInt(nested.site),
                .default_root_module = nested.default_root,
            } },
            .method_scope = moduleDigestFromId(self.moduleForId(method_scope).code_generation_key orelse method_scope),
            .evidence_digest = evidence_digest,
            .codec_contract_digest = codecContractIdentityDigest(codec_contract),
            .codec_contract = codec_contract,
            .request_fn_ty_digest = request_fn_ty_digest,
            .request_fn_ty = request_fn_ty,
        };
    }

    fn moduleForId(self: *Builder, module_id: checked.ModuleId) ModuleView {
        return self.moduleForKeyBytes(module_id.bytes) orelse
            Common.invariant("procedure binding referenced a checked module that is not in the lowering input");
    }

    const NominalDeclLookup = struct {
        view: ModuleView,
        declaration: checked.CheckedNominalDeclaration,
        /// Unnamed padding field types (declared order), in `view`'s store. For a
        /// box-payload capability this is the *instance's* substituted padding, so
        /// type-parameterized padding reserves its instantiated size; for a direct
        /// declaration it is the declaration's own padding types.
        padding_field_tys: []const checked.CheckedTypeId,
    };

    /// Resolves a nominal's checked declaration across every representation that
    /// has one, for reading declared field order. The box-payload representation
    /// is the common case for record nominals (assigned while the checked module
    /// data is built), so it must be handled, not just `*_declaration`.
    fn nominalDeclarationFor(self: *Builder, view: ModuleView, nominal: checked.CheckedNominalType) ?NominalDeclLookup {
        return switch (nominal.representation) {
            .local_declaration => |id| blk: {
                const decl = view.types.nominalDeclarationById(id);
                break :blk .{ .view = view, .declaration = decl, .padding_field_tys = decl.paddingFieldTypes(view.types) };
            },
            .imported_declaration => |imported| blk: {
                const sv = self.moduleForId(checked.importedNominalDeclarationModuleId(imported));
                const decl = sv.types.nominalDeclarationById(imported.declaration);
                break :blk .{ .view = sv, .declaration = decl, .padding_field_tys = decl.paddingFieldTypes(sv.types) };
            },
            .local_box_payload_capability => |cap| blk: {
                const capability = view.interface_capabilities.boxPayloadCapability(cap.capability);
                const decl = view.types.nominalDeclaration(capability.nominal) orelse break :blk null;
                break :blk .{ .view = view, .declaration = decl, .padding_field_tys = capability.paddingFieldTys(view.interface_capabilities) };
            },
            .imported_box_payload_capability => |cap| blk: {
                const sv = self.moduleForId(checked.importedBoxPayloadCapabilityModuleId(cap));
                const capability = sv.interface_capabilities.boxPayloadCapability(cap.capability);
                const decl = sv.types.nominalDeclaration(capability.nominal) orelse break :blk null;
                break :blk .{ .view = sv, .declaration = decl, .padding_field_tys = capability.paddingFieldTys(sv.interface_capabilities) };
            },
            .builtin => |builtin_nominal| blk: {
                const source_view = self.moduleForId(nominal.owner_module);
                const decl = source_view.types.builtinNominalDeclaration(builtin_nominal) orelse break :blk null;
                break :blk .{ .view = source_view, .declaration = decl, .padding_field_tys = decl.paddingFieldTypes(source_view.types) };
            },
            .opaque_without_backing => null,
        };
    }

    const NominalDeclarationSource = struct {
        view: ModuleView,
        declaration: checked.CheckedNominalDeclaration,
    };

    /// The declaration behind a user nominal, including one reached as a box
    /// payload. Builtin nominals are decided by their builtin kind instead.
    fn nominalDeclarationSource(self: *Builder, view: ModuleView, nominal: checked.CheckedNominalType) ?NominalDeclarationSource {
        return switch (nominal.representation) {
            .builtin, .opaque_without_backing => null,
            .local_declaration,
            .imported_declaration,
            .local_box_payload_capability,
            .imported_box_payload_capability,
            => blk: {
                const lookup = self.nominalDeclarationFor(view, nominal) orelse break :blk null;
                break :blk .{ .view = lookup.view, .declaration = lookup.declaration };
            },
        };
    }

    /// Whether each parameter of a nominal declaration occurs in its backing
    /// only as a value. A declaration still under analysis, as in mutually
    /// recursive nominals, reports null, which callers treat as not a value.
    fn nominalParameterValueMask(
        self: *Builder,
        view: ModuleView,
        declaration: checked.CheckedNominalDeclaration,
        key: NominalDeclarationKey,
    ) Allocator.Error!?[]const bool {
        const entry = try self.nominal_parameter_value_masks.getOrPut(self.allocator, key);
        if (entry.found_existing) return entry.value_ptr.*;
        entry.value_ptr.* = null;
        errdefer _ = self.nominal_parameter_value_masks.remove(key);
        // A recursive use of the declaration inside its own backing refers to
        // the parameters being decided. Start from every parameter being a
        // value and drop the ones the backing contradicts until nothing
        // changes: the greatest mask consistent with its own recursive uses.
        const formal_args = declaration.formalArgs(view.types);
        var assumed = try self.allocator.alloc(bool, formal_args.len);
        errdefer self.allocator.free(assumed);
        @memset(assumed, true);
        while (true) {
            const next = try valuePositionMask(self.allocator, self, view, declaration.backing, formal_args, .{ .key = key, .assumed = assumed });
            if (std.mem.eql(bool, next, assumed)) {
                self.allocator.free(next);
                break;
            }
            self.allocator.free(assumed);
            assumed = next;
        }
        self.nominal_parameter_value_masks.getPtr(key).?.* = assumed;
        return assumed;
    }

    /// The declared fields of a nominal/opaque record backing, from explicit
    /// checked metadata, or null when it has none. Boxy uses the lowered span
    /// for aggregate descriptor planning; LSS consumes it as layout order only
    /// when it contains padding. The lowered backing row remains lexicographic.
    fn declaredOrderOps(self: *Builder, view: ModuleView, nominal: checked.CheckedNominalType) Allocator.Error!?[]DeclaredOrderOp {
        if (nominal.declared_fields.len != 0) {
            return try self.checkedDeclaredOrderOps(view, nominal.declared_fields, view, nominal.padding_field_types);
        }
        const lookup = self.nominalDeclarationFor(view, nominal) orelse {
            if (!nominalHasDeclarationBacking(nominal)) return null;
            Common.invariant("declaration-backed nominal reached Monotype lowering without declaration data");
        };
        const declared_fields = lookup.declaration.declaredFields(lookup.view.types);
        if (declared_fields.len != 0) {
            return try self.checkedDeclaredOrderOps(
                lookup.view,
                declared_fields,
                lookup.view,
                lookup.padding_field_tys,
            );
        }
        const fields = lookup.declaration.declaredRecordFields(lookup.view.types);
        if (fields.len == 0) return null;
        // Unnamed fields are layout padding; their resolved checked types ride on
        // the declaration in declared order and are pulled sequentially as each
        // unnamed field is encountered while walking the declared field rows.
        // Padding types come from the lookup, which for an instantiated nominal
        // (box-payload capability) carries the *instance's* substituted padding
        // types—so a type-parameterized padding field (`_ : a`) reserves the
        // instantiated size, exactly like a named field of the same type.
        const padding_types = lookup.padding_field_tys;
        var padding_cursor: usize = 0;
        const ops = try self.allocator.alloc(DeclaredOrderOp, fields.len);
        for (fields, 0..) |field, i| {
            ops[i] = switch (field) {
                .named => |label| .{ .named = .{ .view = lookup.view, .name = label } },
                .padding => blk: {
                    if (padding_cursor >= padding_types.len) {
                        Common.invariant("nominal declaration had more unnamed fields than recorded padding types");
                    }
                    const checked_ty = padding_types[padding_cursor];
                    padding_cursor += 1;
                    break :blk .{ .padding = .{ .view = lookup.view, .ty = checked_ty } };
                },
            };
        }
        return ops;
    }

    fn checkedDeclaredOrderOps(
        self: *Builder,
        field_view: ModuleView,
        fields: []const checked.CheckedDeclaredField,
        padding_view: ModuleView,
        padding_types: []const checked.CheckedTypeId,
    ) Allocator.Error![]DeclaredOrderOp {
        const ops = try self.allocator.alloc(DeclaredOrderOp, fields.len);
        for (fields, 0..) |field, i| {
            ops[i] = switch (field) {
                .named => |name| .{ .named = .{ .view = field_view, .name = name } },
                .padding => |index| blk: {
                    const raw_index: usize = @intCast(index);
                    if (raw_index >= padding_types.len) {
                        Common.invariant("nominal declaration declared-order padding index was out of range");
                    }
                    break :blk .{ .padding = .{ .view = padding_view, .ty = padding_types[raw_index] } };
                },
            };
        }
        return ops;
    }

    /// Slot membership is the explicit compile-time request manifest, reserved
    /// before any root bodies are lowered. Type eligibility alone does not
    /// select a root: the checker omits procedure aliases and roots that depend
    /// on unbound platform requirements from that manifest.
    fn comptimeValueReadDeclared(self: *Builder, view: ModuleView, root_id: checked.ComptimeRootId) bool {
        if (!self.comptime_value_reads) return false;
        const declarations = self.borrowed_comptime_root_functions orelse &self.declared_comptime_root_functions;
        return declarations.contains(.{ .module = view.key, .root = root_id });
    }

    fn constNode(self: *Builder, const_locator: checked.ConstLocator, node: ?checked.ConstNodeId) ConstNode {
        const view = self.moduleForId(checked.constModuleId(const_locator));
        if (node) |id| return .{ .module = view, .id = id };
        const template = view.const_templates.get(const_locator);
        return switch (template.state) {
            .stored_const => |stored| .{ .module = view, .id = stored.node },
            .reserved,
            .eval_template,
            => Common.invariant("static data request const was not stored before Monotype lowering"),
            .unimplemented => Common.invariant("static data request reached a declaration with no implementation"),
        };
    }

    fn commitStaticDataValue(
        self: *Builder,
        const_locator: checked.ConstLocator,
        node: ?checked.ConstNodeId,
        checked_type: checked.CheckedTypeId,
        ty: Type.TypeId,
    ) Allocator.Error!Common.StaticDataId {
        const const_node = self.constNode(const_locator, node);
        const use = StaticDataUse{
            .module = const_node.module.key,
            .node = const_node.id,
            .checked_type = checked_type,
            .ty = ty,
        };
        if (self.static_data_ids.get(use)) |existing| return existing;

        for (self.static_data_uses.items, 0..) |existing, index| {
            if (!moduleBytesEqual(existing.module.bytes, use.module.bytes) or
                existing.node != use.node or
                existing.checked_type != use.checked_type)
            {
                continue;
            }
            if (!try self.program.types.typeEql(&self.program.names, existing.ty, use.ty)) continue;

            const id: Common.StaticDataId = @fromBackingInt(@intCast(@as(u32, @intCast(index))));
            try self.static_data_ids.put(use, id);
            return id;
        }

        try self.program.ensureStaticDataValueCapacity(1);
        try self.static_data_uses.ensureUnusedCapacity(self.allocator, 1);
        try self.static_data_ids.ensureUnusedCapacity(1);
        const id = self.program.addStaticDataValueAssumeCapacity(.{
            .const_locator = const_locator,
            .node = node,
            .checked_type = checked_type,
        });
        if (@backingInt(id) != self.static_data_uses.items.len) {
            Common.invariant("Monotype static-data use index diverged from program id");
        }
        self.static_data_uses.appendAssumeCapacity(use);
        self.static_data_ids.putAssumeCapacityNoClobber(use, id);
        return id;
    }

    const BareFnCandidate = enum {
        disallow,
        allow,
    };

    fn constNodeMayUseStaticDataCandidate(self: *Builder, view: ModuleView, node: checked.ConstNodeId, bare_fn: BareFnCandidate) bool {
        return self.constValueMayUseStaticDataCandidate(view, view.const_store.get(node), bare_fn);
    }

    /// Whether a ConstStore node and everything it contains has a stable
    /// static data representation, memoized per node and evaluated on
    /// explicit stacks.
    fn constNodeHasStableStaticDataRepresentation(
        self: *Builder,
        view: ModuleView,
        node: checked.ConstNodeId,
    ) Allocator.Error!bool {
        var eligibility = StaticDataEligibility{ .builder = self, .view = view };
        return try StaticDataEligibility.Eval.run(self.allocator, &eligibility, node);
    }

    const StaticDataEligibility = struct {
        builder: *Builder,
        view: ModuleView,

        const Eval = collections.AnyAll.Evaluation(checked.ConstNodeId, StaticDataEligibility);

        pub fn enter(self: *StaticDataEligibility, items: Eval.Items, node: checked.ConstNodeId) Allocator.Error!Eval.Expansion {
            const address = ConstNodeAddress{ .module = self.view.key, .node = node };
            if (self.builder.static_data_eligibility.get(address)) |stable| return .{ .value = stable };
            const leaf: ?bool = switch (self.view.const_store.get(node)) {
                .pending => Common.invariant("pending ConstStore node reached static data eligibility"),
                // Static data emits an erased callable as one allocation naming
                // its procedure through a relocation, so a capture-free function
                // value is fully decided by the ConstStore. A capture record is
                // not: its slots carry their own evidence, which this walk has no
                // ConstStore node to answer for.
                .fn_value => |fn_id| self.view.const_store.getFn(fn_id).captures.len == 0,
                .zst,
                .scalar,
                .str,
                .crash,
                .checked_error,
                => true,
                .box => |child| blk: {
                    try items.add(child);
                    break :blk null;
                },
                .list => |list| switch (list) {
                    .packed_bytes, .empty => true,
                    .nodes => |children| blk: {
                        for (children) |child| try items.add(child);
                        break :blk null;
                    },
                },
                .tuple,
                .record,
                => |children| blk: {
                    for (children) |child| try items.add(child);
                    break :blk null;
                },
                .tag => |tag| blk: {
                    for (tag.payloads) |child| try items.add(child);
                    break :blk null;
                },
                .nominal => |nominal| blk: {
                    try items.add(nominal.backing);
                    break :blk null;
                },
            };
            if (leaf) |stable| {
                try self.builder.static_data_eligibility.put(address, stable);
                return .{ .value = stable };
            }
            return .{ .group = .all };
        }

        pub fn exit(self: *StaticDataEligibility, node: checked.ConstNodeId, result: ?bool) Allocator.Error!void {
            const stable = result orelse return;
            try self.builder.static_data_eligibility.put(.{ .module = self.view.key, .node = node }, stable);
        }
    };

    fn constValueMayUseStaticDataCandidate(_: *Builder, view: ModuleView, value_in: checked.ConstValue, bare_fn_in: BareFnCandidate) bool {
        var value = value_in;
        var bare_fn = bare_fn_in;
        while (true) switch (value) {
            .pending => Common.invariant("pending ConstStore node reached static data selection"),
            .zst,
            .scalar,
            .crash,
            .checked_error,
            => return false,
            .str => |str| return constStringBackingLength(view, str) != 0,
            .fn_value => return bare_fn == .allow,
            .list => |list| return switch (list) {
                .nodes => |items| items.len != 0,
                .packed_bytes => |packed_list| packed_list.len != 0,
                // Rebuilt as the `with_capacity` it was evaluated with.
                .empty => false,
            },
            .box => return true,
            .tuple,
            .record,
            .tag,
            => return true,
            .nominal => |nominal| {
                value = view.const_store.get(nominal.backing);
                bare_fn = .allow;
            },
        };
    }

    fn lookupMethodTarget(
        self: *Builder,
        scope: ModuleView,
        owner: static_dispatch.MethodOwner,
        method_view: ModuleView,
        method: names.MethodNameId,
    ) Allocator.Error!?MethodLookupResult {
        return try self.lookupMethodTargetByName(scope, owner, method_view.names.methodNameText(method));
    }

    fn lookupMethodTargetByName(
        self: *Builder,
        scope: ModuleView,
        owner: static_dispatch.MethodOwner,
        method_name: []const u8,
    ) Allocator.Error!?MethodLookupResult {
        const method = try self.activeNameStore().internMethodName(method_name);
        const address = ScopedMethodDispatch.init(scope.key, owner, method);
        if (self.scoped_method_targets.get(address)) |resolution| {
            return switch (resolution) {
                .missing => null,
                .found => |found| found,
            };
        }

        const resolution: ScopedMethodResolution = if (self.findMethodTargetByName(scope, owner, method_name)) |found|
            .{ .found = found }
        else
            .missing;

        try self.scoped_method_targets.put(self.allocator, address, resolution);
        return switch (resolution) {
            .missing => null,
            .found => |found| found,
        };
    }

    /// The checked `to_inspect` override that inspection calls for `owner`,
    /// or null when inspection renders the owner's default form.
    fn lookupInspectOverride(
        self: *Builder,
        scope: ModuleView,
        owner: static_dispatch.MethodOwner,
    ) Allocator.Error!?MethodLookup {
        const method = try self.activeNameStore().internMethodName("to_inspect");
        const address = ScopedMethodDispatch.init(scope.key, owner, method);
        if (self.scoped_inspect_overrides.get(address)) |resolution| return resolution;

        const resolution = self.findInspectOverrideFromStore(scope, &self.program.names, owner);
        try self.scoped_inspect_overrides.put(self.allocator, address, resolution);
        return resolution;
    }

    /// Selects the view that declares `owner.to_inspect` exactly as method
    /// dispatch does; that declaration's checked eligibility is the answer.
    fn findInspectOverrideFromStore(
        self: *Builder,
        scope: ModuleView,
        owner_names: *const names.NameStore,
        owner: static_dispatch.MethodOwner,
    ) ?MethodLookup {
        if (inspectOverrideInViewFromStore(scope, owner_names, owner, true)) |decision| return decision.target;
        for (scope.method_lookup_scope) |module_id| {
            const candidate = self.moduleForId(module_id);
            if (inspectOverrideInViewFromStore(candidate, owner_names, owner, false)) |decision| return decision.target;
        }
        return null;
    }

    const InspectOverrideDecision = struct {
        target: ?MethodLookup,
    };

    fn inspectOverrideInViewFromStore(
        view: ModuleView,
        owner_names: *const names.NameStore,
        owner: static_dispatch.MethodOwner,
        allow_local_proc: bool,
    ) ?InspectOverrideDecision {
        const view_owner = static_dispatch.methodOwnerInImportedStore(owner_names, view.names, owner) orelse return null;
        const view_method = view.names.lookupMethodName("to_inspect") orelse return null;
        const key: static_dispatch.MethodKey = .{ .owner = view_owner, .method = view_method };
        switch (view.method_registry.lookup(key) orelse return null) {
            // The registry records no inspect override for a rejected
            // declaration, so inspection renders the default form below.
            .rejected => {},
            .target => |target| if (!allow_local_proc and target.kind == .local_proc) return null,
        }
        const override = view.method_registry.lookupInspectOverride(key) orelse return .{ .target = null };
        return .{ .target = .{ .view = view, .target = override.target } };
    }

    fn findMethodTargetByName(
        self: *Builder,
        scope: ModuleView,
        owner: static_dispatch.MethodOwner,
        method_name: []const u8,
    ) ?MethodLookupResult {
        return self.findMethodTargetByNameFromStore(
            scope,
            &self.program.names,
            owner,
            method_name,
        );
    }

    fn findMethodTargetByNameFromStore(
        self: *Builder,
        scope: ModuleView,
        owner_names: *const names.NameStore,
        owner: static_dispatch.MethodOwner,
        method_name: []const u8,
    ) ?MethodLookupResult {
        if (self.methodTargetInViewFromStore(scope, owner_names, owner, method_name, true)) |found| return found;
        for (scope.method_lookup_scope) |module_id| {
            const candidate = self.moduleForId(module_id);
            // Only the module declaring a function-body type registers its
            // methods, so a local procedure found here is that owner's exact
            // target; its declaration context comes from the evidence purpose.
            if (self.methodTargetInViewFromStore(candidate, owner_names, owner, method_name, true)) |found| return found;
        }
        return null;
    }

    fn methodTargetInViewFromStore(
        _: *Builder,
        view: ModuleView,
        owner_names: *const names.NameStore,
        owner: static_dispatch.MethodOwner,
        method_name: []const u8,
        allow_local_proc: bool,
    ) ?MethodLookupResult {
        const view_owner = static_dispatch.methodOwnerInImportedStore(owner_names, view.names, owner) orelse return null;
        const view_method = view.names.lookupMethodName(method_name) orelse return null;
        return switch (view.method_registry.lookup(.{ .owner = view_owner, .method = view_method }) orelse return null) {
            .rejected => .rejected,
            .target => |target| if (!allow_local_proc and target.kind == .local_proc)
                null
            else
                .{ .target = .{ .view = view, .target = target } },
        };
    }

    fn noteBuiltinTryDef(
        self: *Builder,
        builtin: ?checked.CheckedBuiltinNominal,
        name_store: *const names.NameStore,
        def: Type.TypeDef,
    ) void {
        if (builtin == null or builtin.? != .try_) return;
        if (self.builtin_try_def) |existing| {
            if (!sameTypeDefAcrossStores(
                existing.name_store,
                existing.def,
                name_store,
                def,
            )) {
                Common.invariant("checked modules disagreed on the builtin Try definition identity");
            }
        } else {
            self.builtin_try_def = .{ .name_store = name_store, .def = def };
        }
    }

    fn isBuiltinTryDef(
        self: *const Builder,
        name_store: *const names.NameStore,
        def: Type.TypeDef,
    ) bool {
        const expected = self.builtin_try_def orelse return false;
        return sameTypeDefAcrossStores(
            expected.name_store,
            expected.def,
            name_store,
            def,
        );
    }

    fn importModuleAlreadyScanned(self: *Builder, module_id: checked.ModuleId, import_index: usize) bool {
        if (moduleBytesEqual(module_id.bytes, self.root_view.key.bytes)) return true;
        for (self.modules.imports[0..import_index]) |imported| {
            if (moduleBytesEqual(module_id.bytes, imported.key.bytes)) return true;
        }
        return false;
    }

    fn relationModuleAlreadyScanned(self: *Builder, module_id: checked.ModuleId, relation_index: usize) bool {
        if (moduleBytesEqual(module_id.bytes, self.root_view.key.bytes)) return true;
        for (self.modules.imports) |imported| {
            if (moduleBytesEqual(module_id.bytes, imported.key.bytes)) return true;
        }
        for (self.modules.root.relation_modules[0..relation_index]) |relation| {
            if (moduleBytesEqual(module_id.bytes, relation.key.bytes)) return true;
        }
        return false;
    }

    fn templateRefForProcedureUse(
        self: *Builder,
        proc: checked.ProcedureUseTemplate,
    ) names.ProcTemplate {
        return switch (proc.binding) {
            .top_level => |top_level| blk: {
                const view = self.moduleForId(checked.topLevelProcedureModuleId(top_level));
                const binding = view.top_level_procedure_bindings.get(top_level.binding);
                break :blk switch (binding.body) {
                    .direct_template => |direct| switch (direct.template) {
                        .checked => |template| template,
                        .lifted => Common.invariant("lifted direct target reached Monotype procedure use"),
                        .synthetic => Common.invariant("synthetic direct target reached Monotype procedure use"),
                    },
                    .checked_error => Common.invariant("rejected binding reached Monotype callable consumption"),
                    .callable_eval_template => Common.invariant("callable-eval template reached Monotype procedure use"),
                };
            },
            .imported => |imported| blk: {
                const view = self.moduleForId(checked.importedProcedureModuleId(imported));
                for (view.exported_procedure_bindings.bindings) |binding| {
                    if (binding.binding.def == imported.def and binding.binding.pattern == imported.pattern) {
                        break :blk switch (binding.body) {
                            .direct_template => |direct| switch (direct.template) {
                                .checked => |template| template,
                                .lifted => Common.invariant("imported lifted target reached Monotype procedure use"),
                                .synthetic => Common.invariant("imported synthetic target reached Monotype procedure use"),
                            },
                            .checked_error => Common.invariant("rejected binding reached Monotype callable consumption"),
                            .callable_eval_template => Common.invariant("imported callable-eval template reached Monotype procedure use"),
                        };
                    }
                }
                Common.invariant("imported procedure binding was not exported by its checked module");
            },
            .hosted => |hosted| hosted.template,
            .platform_required => |required| blk: {
                const view = self.moduleForId(checked.requiredProcedureModuleId(required));
                const binding = view.top_level_procedure_bindings.get(required.procedure_binding);
                break :blk switch (binding.body) {
                    .direct_template => |direct| switch (direct.template) {
                        .checked => |template| template,
                        .lifted => Common.invariant("platform lifted target reached Monotype procedure use"),
                        .synthetic => Common.invariant("platform synthetic target reached Monotype procedure use"),
                    },
                    .checked_error => Common.invariant("rejected binding reached Monotype callable consumption"),
                    .callable_eval_template => Common.invariant("platform callable-eval template reached Monotype procedure use"),
                };
            },
        };
    }

    fn materializeRootProcedureEvidence(
        self: *Builder,
        fn_template: Ast.FnTemplate,
        evidence_span: checked.CheckedEvidenceSpan,
    ) Allocator.Error!EdgeEvidence {
        const template_ref = switch (fn_template.fn_def) {
            .local_template,
            .imported_template,
            .checked_generated,
            => |template| template,
            .local_hosted,
            .imported_hosted,
            => |hosted| hosted.template,
            .nested,
            .parser_runtime,
            .encoder_for_runtime,
            => Common.invariant("root procedure evidence referenced a non-checked procedure template"),
        };
        return try self.materializeCheckedProcedureEvidence(template_ref, evidence_span);
    }

    /// The evidence a producer-authored root edge supplies to a template: the
    /// template's own quantified variables, unpinned by any caller, with the
    /// root's recorded entries as contract provenance.
    fn materializeCheckedProcedureEvidence(
        self: *Builder,
        template_ref: names.ProcTemplate,
        evidence_span: checked.CheckedEvidenceSpan,
    ) Allocator.Error!EdgeEvidence {
        const view = self.moduleForId(evidence_span.checked_module);
        if (!moduleBytesEqual(view.key.bytes, names.procTemplateModuleDigest(template_ref).bytes)) {
            Common.invariant("root procedure evidence and procedure template belonged to different checked modules");
        }
        const start: usize = evidence_span.span.start;
        const len: usize = evidence_span.span.len;
        if (start > view.static_dispatch_plans.evidence_refs.len or
            len > view.static_dispatch_plans.evidence_refs.len - start)
        {
            Common.invariant("root procedure evidence range was outside its checked module");
        }

        const graph = try self.createGraph();
        defer graph.destroy();
        var draft = BodyDraftStore.init(self.allocator);
        defer draft.deinit();
        var ctx = try BodyContext.init(self.allocator, self, view, template_ref, graph, &draft);
        defer ctx.deinit();
        ctx.evidence = rootEvidence(template_ref, &.{});
        const template = view.templates.get(template_ref.template);
        const subst = try ctx.substitutionFromCheckedTypes(view, view.templates.templateSchemeVars(&template));
        return .{
            .subst = subst,
            .vector = try ctx.deriveEvidenceVector(
                templateSchemaIn(view, &template),
                subst,
                view,
                view.static_dispatch_plans.evidence_refs[start .. start + len],
                .body_lowering,
            ),
        };
    }

    /// Lower (or defer) a procedure template body and return the Monotype
    /// function id the call site should embed. Inside a specialization the
    /// request reserves an id and defers the body; outside one (root and
    /// wrapper paths, whose types come from the builder-global cache without
    /// body evidence), the body lowers now.
    fn lowerFnTemplateCallTarget(self: *Builder, method_scope: ModuleView, fn_template: Ast.FnTemplate, evidence: []const SpecEvidence) Allocator.Error!Ast.FnSlot {
        const template_ref = switch (fn_template.fn_def) {
            .local_template,
            .imported_template,
            .checked_generated,
            => |template| template,
            .parser_runtime,
            .encoder_for_runtime,
            => Common.invariant("generated serialization runtime function must be restored through ConstStore runtime restore"),
            .local_hosted,
            .imported_hosted,
            => |hosted| hosted.template,
            .nested => Common.invariant("nested function specialization must be lowered through nested function lowering"),
        };
        if (self.active_graph != null) {
            Common.invariant("final function-template lowering was called during an active body draft");
        }
        // Root and wrapper paths request the binding's own declared type; no
        // request relation ran, so no widening was recorded—checked here
        // rather than stated.
        //
        // `.checked_generated` is excluded because its `template_ref` is not
        // the template this type specializes: the widening adapter stores the
        // ADAPTED template there beside its deliberately WIDE `mono_fn_ty`
        // (the check would be guaranteed to fire), and a generated step lambda
        // stores merely the template it was generated inside (whose arity need
        // not even match). Neither states the claim this checks.
        if (fn_template.fn_def != .checked_generated) {
            try self.requireRequestDidNotWidenResultRow(
                template_ref,
                fn_template.mono_fn_ty,
                "function-template call target widened the template's closed checked result row",
            );
        }
        const def = try self.lowerTemplateWithMono(
            template_ref,
            method_scope,
            fn_template.source_fn_ty,
            fn_template.source_fn_key,
            fn_template.mono_fn_ty,
            evidence,
            null,
            .independent_roots,
            .count,
            null,
            null,
            .queued,
            null,
            false,
        );
        return .{ .local = self.defFnId(def) };
    }

    fn lowerFnTemplateDef(self: *Builder, method_scope: ModuleView, fn_template: Ast.FnTemplate, evidence: []const SpecEvidence) Allocator.Error!Ast.FnId {
        return localFnIdFromSlot(try self.lowerFnTemplateCallTarget(method_scope, fn_template, evidence));
    }

    fn lowerRestoredConstFnTemplate(
        self: *Builder,
        fn_template: Ast.FnTemplate,
        fn_value: check.ConstStore.ConstFn,
    ) Allocator.Error!Ast.FnId {
        switch (fn_template.fn_def) {
            .nested => {
                const fn_view = self.moduleForConstFnDef(fn_template.fn_def);
                const graph = try self.createGraph();
                defer graph.destroy();
                const saved_graph = self.active_graph;
                const saved_body_draft = self.active_body_draft;
                self.active_graph = graph;
                defer self.active_graph = saved_graph;
                var body_draft = BodyDraftStore.init(self.allocator);
                self.active_body_draft = &body_draft;
                defer self.active_body_draft = saved_body_draft;
                defer body_draft.deinit();
                var fn_ctx = try BodyContext.init(self.allocator, self, fn_view, templateForConstFnDef(fn_value.fn_def), graph, &body_draft);
                defer fn_ctx.deinit();
                // A default-root stored function restores in default
                // materialization mode: `fn_view` is the declaring module and
                // the site resolves against its `.default_root` owner.
                fn_ctx.in_default_expr = constFnDefIsDefaultRoot(fn_value.fn_def);
                fn_ctx.evidence = try fn_ctx.materializeConstFnEvidence(fn_value);
                try fn_ctx.replayStoredEvidenceRelations(fn_ctx.evidence);
                const draft = FinalBodyOutputGuard.begin(self);
                const request_fn_node = try graph.importMonoIndependent(fn_template.mono_fn_ty);
                const nested = switch (fn_template.fn_def) {
                    .nested => |value| value,
                    .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => unreachable,
                };
                fn_ctx.current_fn_key = nested.context_fn_key;
                const restored_local_proc_entries = try fn_ctx.enterRestoredLocalProcScope(nested, nested.context_fn_key);
                defer if (restored_local_proc_entries) |entries| fn_ctx.allocator.free(entries);
                const fn_target = try self.lowerDraftNestedFromContext(
                    &fn_ctx,
                    fn_ctx.draft.current_owner,
                    checkedLambdaExprIdForConstFn(fn_view, fn_template.fn_def),
                    nested,
                    fn_template.source_fn_ty,
                    fn_template.source_fn_key,
                    request_fn_node,
                    &.{},
                    fn_ctx.evidence,
                    null,
                    false,
                    .exact_graph,
                    .inherit,
                );
                const draft_fn = switch (fn_target) {
                    .draft => |id| id,
                    .final => Common.invariant("closed restored nested function resolved before draft commit"),
                };
                const draft_end = draft.end(self);
                const sealed = try self.sealActiveBodyDraft(graph, &body_draft, draft, draft_end, request_fn_node, &.{}, null, null, draft_fn);
                defer sealed.deinit(self.allocator);
                return sealed.root_fn orelse Common.invariant("closed restored nested function did not resolve its final id");
            },
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => {
                const fn_view = self.moduleForConstFnDef(fn_template.fn_def);
                const graph = try self.createGraph();
                defer graph.destroy();
                var body_draft = BodyDraftStore.init(self.allocator);
                defer body_draft.deinit();
                var fn_ctx = try BodyContext.init(self.allocator, self, fn_view, templateForConstFnDef(fn_value.fn_def), graph, &body_draft);
                defer fn_ctx.deinit();
                const retained = try fn_ctx.materializeConstFnEvidence(fn_value);
                const template_ref = switch (fn_template.fn_def) {
                    .local_template, .imported_template, .checked_generated => |template| template,
                    .local_hosted, .imported_hosted => |hosted| hosted.template,
                    .nested, .parser_runtime, .encoder_for_runtime => Common.invariant("non-nested restored function did not reference a procedure template"),
                };
                // A restored constant function reproduces a specialization that
                // was already reserved at this exact type; the identity hit
                // above carries its recorded answer. If the identity was not
                // registered locally this lowers the body at the requested
                // type, so the claim is checked rather than stated—`.checked_generated`
                // excluded for the reason given at the
                // call-target site above.
                if (fn_template.fn_def != .checked_generated) {
                    try self.requireRequestDidNotWidenResultRow(
                        template_ref,
                        fn_template.mono_fn_ty,
                        "restored constant function request widened the template's closed checked result row",
                    );
                }
                const def = try self.lowerTemplateWithMono(
                    template_ref,
                    fn_view,
                    fn_template.source_fn_ty,
                    fn_template.source_fn_key,
                    fn_template.mono_fn_ty,
                    retained.vector,
                    null,
                    .independent_roots,
                    .count,
                    null,
                    retained,
                    .immediate,
                    null,
                    false,
                );
                return self.defFnId(def);
            },
        }
    }

    fn defFnId(self: *Builder, def: Ast.DefId) Ast.FnId {
        return self.program.getDef(def).fn_id orelse
            Common.invariant("Monotype procedure template definition had no function id");
    }

    fn promoteFnSignatureRelation(
        self: *Builder,
        fn_id: Ast.FnId,
        requested: Ast.SignatureRelation,
    ) void {
        if (requested != .exact_graph) return;
        if (self.active_template_root) |*active_root| {
            if (active_root.fn_id == fn_id and self.hasPrivateTypeDestination()) {
                active_root.signature_relation = .exact_graph;
                return;
            }
        }
        var fn_ = self.program.getFn(fn_id);
        if (fn_.signature_relation == .exact_graph) return;
        fn_.signature_relation = .exact_graph;
        self.program.setFn(fn_id, fn_);
    }

    fn nestedFnForExpr(
        self: *Builder,
        view: ModuleView,
        owner: names.ProcTemplate,
        expr_id: checked.CheckedExprId,
        context_fn_key: names.TypeDigest,
        local_proc_context_digest: ?names.TypeDigest,
        in_default_expr: bool,
    ) Allocator.Error!Ast.NestedFn {
        const site = try self.nestedSiteForExpr(view, owner, expr_id, in_default_expr);
        return .{
            .owner = owner,
            .site = site,
            // A default-root site belongs to no template; the produced
            // reference carries the declaring module's content identity so a
            // stored function value built from it stays resolvable outside
            // materialization context (const-store restore).
            .default_root = switch (view.nested_proc_sites.sites[@backingInt(site)].owner) {
                .template => null,
                .default_root => .{ .bytes = view.module_identity.stable_hash },
            },
            .context_fn_key = context_fn_key,
            .local_proc_context_digest = local_proc_context_digest,
        };
    }

    /// The checked nested-procedure site `owner` lowers `expr_id` at.
    fn nestedSiteForExpr(
        self: *Builder,
        view: ModuleView,
        owner: names.ProcTemplate,
        expr_id: checked.CheckedExprId,
        in_default_expr: bool,
    ) Allocator.Error!names.NestedProcSiteId {
        const address = NestedSiteAddress.from(view.key, owner, expr_id);
        const site = if (self.nested_site_cache.get(address)) |cached|
            cached
        else blk: {
            for (view.nested_proc_sites.sites) |candidate| {
                if (candidate.checked_expr == null or candidate.checked_expr.? != expr_id) continue;
                // A default-root site (a lambda/closure inside a defaulted-field
                // expression) is matched only while materializing a default; it
                // has no owning template, so the requesting context's owner
                // does not participate. A template-owned site is matched only
                // by its own template.
                switch (candidate.owner) {
                    .template => |site_owner| {
                        if (in_default_expr) continue;
                        if (!names.procedureTemplateRefEql(site_owner, owner)) continue;
                    },
                    .default_root => if (!in_default_expr) continue,
                }
                try self.nested_site_cache.put(address, candidate.site);
                break :blk candidate.site;
            }
            Common.invariant("nested function expression reached Monotype without a checked nested function site");
        };
        if (@backingInt(site) >= view.nested_proc_sites.sites.len) {
            Common.invariant("nested function site id was outside the CheckedModule procedure-site table");
        }
        return site;
    }

    fn lowerDraftNestedFromContext(
        self: *Builder,
        source_ctx: *BodyContext,
        request_owner: DraftOwner,
        expr_id: checked.CheckedExprId,
        nested: Ast.NestedFn,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        raw_request_fn_node: NodeId,
        capture_entry_guards: []const NodeId,
        requested_evidence: EvidenceChain,
        owned_scope: ?checked.DispatchScopeId,
        recursive_reference: bool,
        signature_relation: Ast.SignatureRelation,
        codec_contract_selection: CodecContractSelection,
    ) Allocator.Error!DraftFnTarget {
        var draft = switch (try self.beginDraftNested(
            source_ctx,
            request_owner,
            expr_id,
            nested,
            source_fn_ty,
            source_fn_key,
            raw_request_fn_node,
            capture_entry_guards,
            requested_evidence,
            owned_scope,
            recursive_reference,
            signature_relation,
            codec_contract_selection,
        )) {
            .hit => |target| return target,
            .lowering => |lowering| lowering,
        };
        defer self.releaseDraftNested(&draft);
        const lowered = try draft.nested_ctx.lowerNestedFunctionAtNode(expr_id, draft.request_fn_node, draft.capture_entry_guards);
        return try self.finishDraftNested(source_ctx, &draft, lowered);
    }

    /// Release a nested function's lowering context and leave its owner.
    fn releaseDraftNested(self: *Builder, draft: *DraftNestedLowering) void {
        draft.nested_ctx.deinit();
        self.allocator.destroy(draft.nested_ctx);
        draft.owner_scope.leave();
    }

    fn beginDraftNested(
        self: *Builder,
        source_ctx: *BodyContext,
        request_owner: DraftOwner,
        expr_id: checked.CheckedExprId,
        nested: Ast.NestedFn,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        raw_request_fn_node: NodeId,
        capture_entry_guards: []const NodeId,
        requested_evidence: EvidenceChain,
        owned_scope: ?checked.DispatchScopeId,
        recursive_reference: bool,
        signature_relation: Ast.SignatureRelation,
        codec_contract_selection: CodecContractSelection,
    ) Allocator.Error!DraftNestedBegin {
        self.count("nested_requests");
        const request_fn_node = try source_ctx.graph.functionRequestRoot(raw_request_fn_node);
        const codec_contract: ?DraftCodecContractContext = switch (codec_contract_selection) {
            .inherit => source_ctx.activeCodecContractContext(),
            .independent => null,
            .anchored => |anchor| source_ctx.activeCodecContractContextForAnchor(anchor),
        };
        const family = DraftNestedFamilyAddress.init(nested, source_ctx.method_scope.key, source_fn_key);
        self.countBodyDiagnostic("nested_lookup_probes");
        const family_exists = source_ctx.draft.nested_spec_families.contains(family);
        const stored_evidence = try source_ctx.storedEvidence(requested_evidence);
        const evidence_digest = stored_evidence.digest;
        const draft_evidence = try source_ctx.draft.addStoredConstFnEvidence(stored_evidence);
        const resolved_request_ty: ?Type.TypeId = if (try source_ctx.graph.typeIsResolved(request_fn_node))
            try source_ctx.activeTypeFromNode(request_fn_node)
        else
            null;
        const lookup_prefix = try source_ctx.draft.nested_spec_lookup.internPrefix(family, evidence_digest.bytes);
        const resolved_lookup_address: ?DraftNestedLookupAddress = if (resolved_request_ty) |request_fn_ty| .{
            .digest = .{
                .prefix = lookup_prefix,
                .kind = .closed,
                .digest = source_ctx.specializationTypeDigest(request_fn_ty).bytes,
            },
        } else null;
        const open_request_shape: ?solve.OpenFunctionInterfaceShape = if (resolved_request_ty == null)
            try source_ctx.graph.openFunctionInterfaceShape(request_fn_node)
        else
            null;
        const open_shape_lookup_address: ?DraftNestedLookupAddress = if (open_request_shape) |shape| .{
            .digest = .{
                .prefix = lookup_prefix,
                .kind = .open_shape,
                .digest = shape.digest.bytes,
            },
        } else null;
        // Nested draft requests use the same graph-native identity discipline
        // as template requests; no resolved node becomes a durable cache key
        // before the graph freezes.
        var seen_specs = std.AutoHashMap(u32, void).init(self.allocator);
        defer seen_specs.deinit();
        var selection = DraftOpenCandidateSelection{};
        if (resolved_lookup_address) |address| {
            if (source_ctx.draft.nested_spec_lookup.get(address)) |candidate_iterator| {
                var candidates = candidate_iterator;
                while (candidates.next()) |raw_spec| {
                    self.countBodyDiagnostic("nested_lookup_probes");
                    const spec = &source_ctx.draft.nested_specs.items[raw_spec];
                    if (signature_relation == .exact_graph and
                        source_ctx.draft.fns.items[@backingInt(spec.fn_id)].signature_relation != .exact_graph)
                    {
                        continue;
                    }
                    if (!try evidenceChainEql(self.allocator, spec.evidence, requested_evidence)) continue;
                    if (!draftCodecContractSpecializationEql(spec.codec_contract, codec_contract)) continue;
                    if (!draftCaptureEntryGuardsMatch(source_ctx.graph, spec.capture_entry_guards, capture_entry_guards)) continue;
                    if (!std.meta.eql(spec.lexical_owner, source_ctx.draft.current_owner)) continue;
                    const spec_request = try draftNestedSpecRequestNode(source_ctx.draft, source_ctx.graph, spec);
                    if (!try source_ctx.graph.typeIsResolved(spec_request)) continue;
                    const spec_fn_ty = try source_ctx.activeTypeFromNode(spec_request);
                    if (!try source_ctx.typeStore().typeEql(source_ctx.nameStore(), spec_fn_ty, resolved_request_ty.?)) continue;
                    if (!selection.add(raw_spec, true)) unreachable;
                }
            }
        }
        if (family_exists and selection.selected() == null) {
            if (open_shape_lookup_address) |address| {
                if (source_ctx.draft.nested_spec_lookup.get(address)) |candidate_iterator| {
                    var candidates = candidate_iterator;
                    while (candidates.next()) |raw_spec| {
                        self.countBodyDiagnostic("nested_lookup_probes");
                        const spec = &source_ctx.draft.nested_specs.items[raw_spec];
                        if (spec.state != .lowered) continue;
                        if (spec.request_fn_ty != null) continue;
                        if (!try evidenceChainEql(self.allocator, spec.evidence, requested_evidence)) continue;
                        if (!draftCodecContractSpecializationEql(spec.codec_contract, codec_contract)) continue;
                        if (!draftCaptureEntryGuardsMatch(source_ctx.graph, spec.capture_entry_guards, capture_entry_guards)) continue;
                        if (!std.meta.eql(spec.lexical_owner, source_ctx.draft.current_owner)) continue;
                        if (signature_relation == .exact_graph and
                            source_ctx.draft.fns.items[@backingInt(spec.fn_id)].signature_relation != .exact_graph)
                        {
                            continue;
                        }
                        const spec_shape = spec.open_request_shape orelse continue;
                        if (!std.mem.eql(u8, spec_shape, open_request_shape.?.bytes)) continue;
                        if (!selection.add(raw_spec, true)) unreachable;
                    }
                }
            }
        }
        if (family_exists and selection.selected() == null) {
            var interface = try source_ctx.graph.functionInterfaceClassIterator(request_fn_node);
            defer interface.deinit();
            while (try interface.next()) |interface_class| {
                var aliases = source_ctx.graph.classMemberIterator(interface_class);
                while (aliases.next()) |member| {
                    self.countBodyDiagnostic("nested_lookup_probes");
                    const lookup_address = DraftNestedLookupAddress{
                        .open = .{
                            .prefix = lookup_prefix,
                            .node = member,
                        },
                    };
                    if (source_ctx.draft.nested_spec_lookup.get(lookup_address)) |candidate_iterator| {
                        var candidates = candidate_iterator;
                        while (candidates.next()) |raw_spec| {
                            self.countBodyDiagnostic("nested_lookup_probes");
                            const seen = try seen_specs.getOrPut(raw_spec);
                            if (seen.found_existing) continue;
                            const spec = &source_ctx.draft.nested_specs.items[raw_spec];
                            if (spec.request_fn_ty != null) continue;
                            if (!try evidenceChainEql(self.allocator, spec.evidence, requested_evidence)) continue;
                            if (!draftCodecContractSpecializationEql(spec.codec_contract, codec_contract)) continue;
                            if (!draftCaptureEntryGuardsMatch(source_ctx.graph, spec.capture_entry_guards, capture_entry_guards)) continue;
                            if (!std.meta.eql(spec.lexical_owner, source_ctx.draft.current_owner)) continue;
                            if (signature_relation == .exact_graph and
                                source_ctx.draft.fns.items[@backingInt(spec.fn_id)].signature_relation != .exact_graph)
                            {
                                continue;
                            }
                            const spec_fn_node = try draftNestedSpecRequestNode(source_ctx.draft, source_ctx.graph, spec);
                            const exact_interface = (try source_ctx.graph.sameFunctionInterface(spec_fn_node, request_fn_node));
                            const active_recursive_edge = source_ctx.draft.ownerDescendsFromDraftFn(
                                request_owner,
                                spec.fn_id,
                            );
                            if (!draftOpenCandidateQualifies(
                                spec.state,
                                exact_interface,
                                active_recursive_edge,
                                recursive_reference and substitutionsShareClasses(
                                    source_ctx.graph,
                                    spec.evidence.subst,
                                    requested_evidence.subst,
                                ),
                            )) continue;
                            if (!selection.add(raw_spec, exact_interface)) {
                                Common.invariant("draft nested request matched more than one partial active recursive specialization");
                            }
                        }
                    }
                }
            }
        }
        // A checked recursive reference whose fresh cells have not yet joined
        // any interface class above names the in-progress specialization of
        // the same site on its own ownership chain.
        if (family_exists and selection.selected() == null and recursive_reference) {
            for (source_ctx.draft.nested_specs.items, 0..) |*spec, raw_spec_usize| {
                if (spec.state != .lowering) continue;
                if (spec.request_fn_ty != null) continue;
                if (signature_relation == .exact_graph and
                    source_ctx.draft.fns.items[@backingInt(spec.fn_id)].signature_relation != .exact_graph)
                {
                    continue;
                }
                if (!std.meta.eql(DraftNestedFamilyAddress.init(spec.nested, spec.method_scope, spec.source_fn_key), family)) continue;
                if (!try evidenceChainEql(self.allocator, spec.evidence, requested_evidence)) continue;
                if (!substitutionsShareClasses(source_ctx.graph, spec.evidence.subst, requested_evidence.subst)) continue;
                if (!draftCaptureEntryGuardsMatch(source_ctx.graph, spec.capture_entry_guards, capture_entry_guards)) continue;
                if (!draftCodecContractSpecializationEql(spec.codec_contract, codec_contract)) continue;
                if (!source_ctx.draft.ownerDescendsFromDraftFn(request_owner, spec.fn_id)) continue;
                const raw_spec: u32 = @intCast(raw_spec_usize);
                if (!selection.add(raw_spec, false)) {
                    Common.invariant("checked recursive nested reference matched more than one in-progress specialization on its ownership chain");
                }
            }
        }
        if (selection.selected()) |raw_spec| {
            self.count("nested_hits");
            // As for template requests, a partially overlapping in-progress
            // nested request is an explicit recursive edge. Relate its fresh
            // checked cells before reusing the in-progress definition.
            const spec = &source_ctx.draft.nested_specs.items[raw_spec];
            const active_recursive_edge = spec.state == .lowering and
                source_ctx.draft.ownerDescendsFromDraftFn(request_owner, spec.fn_id);
            if (active_recursive_edge) {
                // A recursive edge into a function with no arguments carries
                // its recursive value flow through the result alone.
                const request = try source_ctx.graph.functionNodes(request_fn_node);
                if (request.args.len == 0) source_ctx.graph.markRecursiveValueSlot(request.ret);
                try source_ctx.graph.unifyRecursiveFunctionInterface(
                    spec.request_fn_node,
                    spec.initial_request_arg_classes,
                    request_fn_node,
                );
                if (!(try source_ctx.graph.sameFunctionInterface(spec.request_fn_node, request_fn_node))) {
                    Common.invariant("recursive draft nested request did not join its complete function interface");
                }
            } else {
                const spec_fn_node = try draftNestedSpecRequestNode(source_ctx.draft, source_ctx.graph, spec);
                try source_ctx.graph.unify(spec_fn_node, request_fn_node);
                if (!(try source_ctx.graph.sameFunctionInterface(spec_fn_node, request_fn_node))) {
                    Common.invariant("draft nested request did not join its complete function interface");
                }
            }
            if (signature_relation == .exact_graph) {
                source_ctx.draft.fns.items[@backingInt(spec.fn_id)].signature_relation = .exact_graph;
            }
            for (spec.capture_entry_guards, capture_entry_guards) |stored, requested| {
                if (!source_ctx.graph.sameClass(stored, requested)) {
                    Common.invariant("recursive draft nested request changed its ordered capture entry cells");
                }
            }
            if (!runtimeDemandGuardFrameSetsEql(
                spec.runtime_demand_guard_frames,
                try source_ctx.runtimeDemandGuardFrameAddresses(),
            )) {
                try source_ctx.draft.nested_spec_reuses.append(self.allocator, .{
                    .spec = raw_spec,
                    .prefix_proof = try source_ctx.currentRuntimeImpossibilityProof(null),
                });
            }
            return .{ .hit = .{ .draft = spec.fn_id } };
        }
        self.count("nested_misses");
        try source_ctx.draft.nested_spec_families.put(family, {});

        const fn_id = try source_ctx.draft.addFn(.{ .source = .{
            .fn_def = .{ .nested = nested },
            .source_fn_ty = source_fn_ty,
            .source_fn_key = source_fn_key,
            .mono_fn_ty = DraftTypeCell.fromGraphNode(request_fn_node),
            .evidence_digest = evidence_digest,
            .const_evidence = draft_evidence.nodes,
            .const_evidence_frames = draft_evidence.frames,
            .const_evidence_frame_head = stored_evidence.head,
        }, .signature_relation = signature_relation });
        const symbol = self.symbols.fresh();
        const spec_index = source_ctx.draft.nested_specs.items.len;
        try source_ctx.draft.nested_specs.append(self.allocator, .{
            .state = .lowering,
            .nested = nested,
            .method_scope = source_ctx.method_scope.key,
            .expr_id = expr_id,
            .source_fn_ty = source_fn_ty,
            .source_fn_key = source_fn_key,
            .request_fn_node = request_fn_node,
            .initial_request_arg_classes = try source_ctx.graph.snapshotFunctionArgumentClasses(request_fn_node),
            .request_fn_ty = null,
            .evidence = requested_evidence,
            .runtime_demand_guard_frames = try source_ctx.runtimeDemandGuardFrameAddresses(),
            .demand_start = @intCast(source_ctx.draft.runtime_value_demands.items.len),
            .demand_frame_floor = source_ctx.runtime_demand_guard_frames,
            .capture_entry_guards = try source_ctx.graph.arena().dupe(NodeId, capture_entry_guards),
            .codec_contract = codec_contract,
            .lexical_owner = source_ctx.draft.current_owner,
            .requires_local = try evidenceChainRequiresLocalContext(self.allocator, requested_evidence),
            .local_context_dependent = try evidenceChainRequiresLocalContext(self.allocator, requested_evidence),
            .symbol = symbol,
            .fn_id = fn_id,
            .open_request_shape = if (open_request_shape) |shape| shape.bytes else null,
        });
        var indexed_nodes = collections.DenseMap(NodeId, void).init(self.allocator);
        defer indexed_nodes.deinit();
        var spec_interface = try source_ctx.graph.functionInterfaceIterator(request_fn_node);
        while (spec_interface.next()) |interface_node| {
            const indexed = try indexed_nodes.getOrPut(interface_node);
            if (indexed.found_existing) continue;
            const lookup_address = DraftNestedLookupAddress{
                .open = .{
                    .prefix = lookup_prefix,
                    .node = interface_node,
                },
            };
            try source_ctx.draft.nested_spec_lookup.add(lookup_address, @intCast(spec_index));
        }
        if (open_shape_lookup_address) |address| {
            try registerNestedSpecLookup(source_ctx.draft, address, @intCast(spec_index));
        }
        // A closed request has an exact interface before its body completes.
        // Index it now so recursive calls with fresh instantiation cells can
        // reuse this body through structural equality of the live interface.
        if (resolved_lookup_address) |address| {
            try registerNestedSpecLookup(source_ctx.draft, address, @intCast(spec_index));
        }

        const owner_scope = try source_ctx.draft.enterOwner(.{ .draft_fn = fn_id });
        errdefer owner_scope.leave();

        const nested_ctx = try self.allocator.create(BodyContext);
        errdefer self.allocator.destroy(nested_ctx);
        nested_ctx.* = try source_ctx.nestedInstantiationContext(source_fn_key, requested_evidence, &.{});
        nested_ctx.in_deferred_body = true;
        errdefer nested_ctx.deinit();
        if (codec_contract) |contract| {
            try nested_ctx.instantiateCodecContractAtCall(
                contract.anchor,
                contract.constructor_node,
                contract.shape_node,
            );
        }
        // A request whose class already holds this function's pure instance
        // under the nested evidence is the nested body's instance itself:
        // instantiating the checked function afresh and relating it to the
        // request would add nothing to the request's class.
        const reuses_request = owned_scope == null and codec_contract == null and
            !try nested_ctx.graph.containsGeneratedPrivate(request_fn_node) and
            nested_ctx.holdsPureInstance(source_fn_ty, request_fn_node);
        const root_node = if (reuses_request) blk: {
            try nested_ctx.adoptPureInstance(source_fn_ty, request_fn_node);
            break :blk request_fn_node;
        } else try nested_ctx.instNode(source_fn_ty);
        if (owned_scope) |scope| {
            try nested_ctx.graph.unify(root_node, try nested_ctx.lowerExprTypeNode(expr_id));
            const raw_site = @backingInt(nested.site);
            if (raw_site >= nested_ctx.view.nested_proc_sites.sites.len) {
                Common.invariant("nested function referenced a site absent from the CheckedModule procedure-site table");
            }
            switch (nested_ctx.view.nested_proc_sites.sites[raw_site].owner) {
                .template => try nested_ctx.instantiateTemplateDispatchRelations(
                    nested_ctx.view.templates.get(nested_ctx.owner_template.template),
                    scope,
                ),
                // A default-root site has no owning template, and by the
                // parameter-constraint judgment (design.md "Defaulted
                // Fields") a default is checked at its concrete field type:
                // there is no enclosing scheme whose relations could apply.
                // The default's own dispatch relations flow through its
                // collected default-root evidence spans.
                .default_root => {},
            }
        }
        const request_contains_generated_private = try nested_ctx.graph.containsGeneratedPrivate(request_fn_node);
        if (request_contains_generated_private) {
            if (nested_ctx.graph.requestSourceInterface(request_fn_node)) |source_fn_node| {
                try relateFunctionRequestInterface(nested_ctx.graph, root_node, source_fn_node);
            }
        }
        try relateFunctionRequestInterface(nested_ctx.graph, root_node, request_fn_node);
        return .{ .lowering = .{
            .request_fn_node = request_fn_node,
            .capture_entry_guards = capture_entry_guards,
            .lookup_prefix = lookup_prefix,
            .fn_id = fn_id,
            .symbol = symbol,
            .spec_index = spec_index,
            .owner_scope = owner_scope,
            .nested_ctx = nested_ctx,
        } };
    }

    /// Finish a nested function whose body `beginDraftNested` prepared, once
    /// the body is lowered.
    fn finishDraftNested(
        self: *Builder,
        source_ctx: *BodyContext,
        draft: *DraftNestedLowering,
        lowered: LoweredTemplateBody,
    ) Allocator.Error!DraftFnTarget {
        const completed_fn_node = try draft.nested_ctx.completedFunctionNodeForLoweredRet(
            draft.request_fn_node,
            lowered.ret,
            try draft.nested_ctx.exprCarriesFunctionDefinitionEvidence(lowered.body),
        );
        const completed_fn_ret = (try draft.nested_ctx.graph.functionNodes(completed_fn_node)).ret;
        const completed_ret_cell = DraftTypeCell.fromGraphNode(completed_fn_ret);
        var nested_fn_template = source_ctx.draft.fns.items[@backingInt(draft.fn_id)].source;
        nested_fn_template.mono_fn_ty = DraftTypeCell.fromGraphNode(completed_fn_node);
        _ = try source_ctx.draft.addNestedDef(.{
            .symbol = draft.symbol,
            .fn_def = nested_fn_template,
            .fn_id = .{ .draft = draft.fn_id },
            .args = lowered.args,
            .body = lowered.body,
            .ret = completed_ret_cell,
        });
        source_ctx.draft.fns.items[@backingInt(draft.fn_id)].source = nested_fn_template;
        source_ctx.draft.nested_specs.items[draft.spec_index].request_fn_node = completed_fn_node;
        if (try source_ctx.graph.typeIsResolved(completed_fn_node)) {
            const completed_fn_ty = try source_ctx.activeTypeFromNode(completed_fn_node);
            source_ctx.draft.nested_specs.items[draft.spec_index].request_fn_ty = completed_fn_ty;
            try registerNestedSpecLookup(source_ctx.draft, .{
                .digest = .{
                    .prefix = draft.lookup_prefix,
                    .kind = .closed,
                    .digest = source_ctx.specializationTypeDigest(completed_fn_ty).bytes,
                },
            }, @intCast(draft.spec_index));
        }
        try registerNestedSpecInterfaceLookups(
            source_ctx.draft,
            self.allocator,
            source_ctx.graph,
            draft.lookup_prefix,
            completed_fn_node,
            @intCast(draft.spec_index),
        );
        source_ctx.draft.nested_specs.items[draft.spec_index].state = .lowered;
        source_ctx.draft.nested_specs.items[draft.spec_index].demand_end =
            @intCast(source_ctx.draft.runtime_value_demands.items.len);
        return .{ .draft = draft.fn_id };
    }

    fn markNestedFnReady(self: *Builder, fn_id: Ast.FnId, fn_ty: Type.TypeId) Allocator.Error!void {
        const spec = self.lowered_nested_by_fn.get(fn_id) orelse
            Common.invariant("lowered nested function disappeared before completion");
        try self.spec_store.markReady(spec, fn_ty, self.specializationTypeDigest(fn_ty));
    }

    const ActiveBodyDraftSeal = struct {
        ids: FinalIdOffsets,
        root_ty: ?Type.TypeId,
        root_tys: []Type.TypeId,
        extra_ty: ?Type.TypeId,
        root_def: ?Ast.DefId,
        root_fn: ?Ast.FnId,
        core_maps: *DraftCoreMaps,

        fn deinit(self: ActiveBodyDraftSeal, allocator: Allocator) void {
            allocator.free(self.root_tys);
            self.core_maps.deinit(allocator);
            allocator.destroy(self.core_maps);
        }
    };

    const DraftCommitMap = struct {
        ids: FinalIdOffsets,
        core_maps: ?*DraftCoreMaps,
        emit_fns: []bool,
        emit_defs: []bool,
        emit_nested_defs: []bool,
        static_data_ids: []Common.StaticDataId,

        fn deinit(self: DraftCommitMap, allocator: Allocator) void {
            if (self.core_maps) |maps| {
                maps.deinit(allocator);
                allocator.destroy(maps);
            }
            allocator.free(self.ids.fn_slots);
            allocator.free(self.ids.def_ids);
            allocator.free(self.emit_fns);
            allocator.free(self.emit_defs);
            allocator.free(self.emit_nested_defs);
            allocator.free(self.static_data_ids);
        }
    };

    const DraftCoreMaps = struct {
        values: [draft_core_kind_count][]u32,

        fn deinit(self: *DraftCoreMaps, allocator: Allocator) void {
            for (self.values) |map| allocator.free(map);
        }

        fn retained(self: *const DraftCoreMaps, kind: DraftCoreKind, index: usize) bool {
            return self.values[@backingInt(kind)][index] != std.math.maxInt(u32);
        }
    };

    fn draftCoreBases(self: *Builder) DraftCoreLengths {
        var bases: DraftCoreLengths = @splat(0);
        bases[@backingInt(DraftCoreKind.string_literals)] = @intCast(self.program.stringLiteralCount());
        bases[@backingInt(DraftCoreKind.comptime_sites)] = @intCast(self.program.comptimeSiteCount());
        bases[@backingInt(DraftCoreKind.expr_ids)] = @intCast(self.program.exprIdCount());
        bases[@backingInt(DraftCoreKind.pat_ids)] = @intCast(self.program.patIdCount());
        bases[@backingInt(DraftCoreKind.stmt_ids)] = @intCast(self.program.stmtIdCount());
        bases[@backingInt(DraftCoreKind.field_exprs)] = @intCast(self.program.fieldExprCount());
        bases[@backingInt(DraftCoreKind.fn_def_captures)] = @intCast(self.program.fnDefCaptureCount());
        bases[@backingInt(DraftCoreKind.record_destructs)] = @intCast(self.program.recordDestructCount());
        bases[@backingInt(DraftCoreKind.str_pattern_steps)] = @intCast(self.program.strPatternStepCount());
        bases[@backingInt(DraftCoreKind.branches)] = @intCast(self.program.branchCount());
        bases[@backingInt(DraftCoreKind.if_branches)] = @intCast(self.program.ifBranchCount());
        bases[@backingInt(DraftCoreKind.locals)] = @intCast(self.program.localCount());
        bases[@backingInt(DraftCoreKind.typed_locals)] = @intCast(self.program.typedLocalCount());
        bases[@backingInt(DraftCoreKind.pats)] = @intCast(self.program.patCount());
        bases[@backingInt(DraftCoreKind.exprs)] = @intCast(self.program.exprCount());
        bases[@backingInt(DraftCoreKind.stmts)] = @intCast(self.program.stmtCount());
        bases[@backingInt(DraftCoreKind.roots)] = @intCast(self.program.roots.len());
        bases[@backingInt(DraftCoreKind.layout_requests)] = @intCast(self.program.layoutRequestCount());
        bases[@backingInt(DraftCoreKind.runtime_schema_requests)] = @intCast(self.program.runtimeSchemaRequestCount());
        return bases;
    }

    fn buildDraftCoreMaps(
        self: *Builder,
        body_draft: *const BodyDraftStore,
        emit_fns: []const bool,
    ) Allocator.Error!*DraftCoreMaps {
        const maps = try self.allocator.create(DraftCoreMaps);
        errdefer self.allocator.destroy(maps);
        const lengths = body_draft.coreLengths();
        var initialized: usize = 0;
        errdefer for (maps.values[0..initialized]) |map| self.allocator.free(map);
        for (0..draft_core_kind_count) |raw_kind| {
            maps.values[raw_kind] = try self.allocator.alloc(u32, lengths[raw_kind]);
            @memset(maps.values[raw_kind], std.math.maxInt(u32));
            initialized += 1;
        }

        var next = self.draftCoreBases();
        for (body_draft.owner_runs.items) |owner_run| {
            if (!draftOwnerRetained(owner_run.owner, emit_fns)) continue;
            for (0..draft_core_kind_count) |raw_kind| {
                var index = owner_run.starts[raw_kind];
                while (index < owner_run.ends[raw_kind]) : (index += 1) {
                    maps.values[raw_kind][index] = next[raw_kind];
                    next[raw_kind] += 1;
                }
            }
        }
        return maps;
    }

    fn draftSpecIdentityEql(self: *Builder, left: Ast.SpecIdentity, right: Ast.SpecIdentity) Allocator.Error!bool {
        if (!std.meta.eql(left.callable, right.callable)) return false;
        if (!std.mem.eql(u8, left.method_scope.bytes[0..], right.method_scope.bytes[0..])) return false;
        if (!std.meta.eql(left.evidence_digest, right.evidence_digest)) return false;
        if (!std.mem.eql(u8, left.codec_contract_digest.bytes[0..], right.codec_contract_digest.bytes[0..])) return false;
        if ((left.codec_contract == null) != (right.codec_contract == null)) return false;
        if (left.codec_contract) |left_contract| {
            const right_contract = right.codec_contract.?;
            if (!std.meta.eql(left_contract.module, right_contract.module) or
                left_contract.derivation != right_contract.derivation or
                left_contract.kind != right_contract.kind or
                !std.meta.eql(left_contract.constructor_ty_digest, right_contract.constructor_ty_digest) or
                !std.meta.eql(left_contract.shape_ty_digest, right_contract.shape_ty_digest) or
                !try self.program.types.typeEql(&self.program.names, left_contract.shape_ty, right_contract.shape_ty) or
                !try self.program.types.typeEql(
                    &self.program.names,
                    left_contract.constructor_ty,
                    right_contract.constructor_ty,
                )) return false;
        }
        if (!std.mem.eql(u8, left.request_fn_ty_digest.bytes[0..], right.request_fn_ty_digest.bytes[0..])) return false;
        return try self.program.types.typeEql(&self.program.names, left.request_fn_ty, right.request_fn_ty);
    }

    /// Phase A for deferred expressions. Const bodies and equality-owned
    /// methods may produce graph relations or append more deferred work, so
    /// keep walking both dynamic queues until every equality plan is complete
    /// and another pass discovers no new owned call demand.
    fn prepareDraftDeferredExprs(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
    ) Allocator.Error!void {
        var const_index: usize = 0;
        while (true) {
            while (const_index < body_draft.deferred_const_uses.items.len) {
                const boundary_index = const_index;
                const_index += 1;
                try self.finalizeDraftConstUse(body_draft, graph, boundary_index);
            }

            var added_method_call = false;
            var equality_index: usize = 0;
            while (equality_index < body_draft.deferred_structural_eqs.items.len) : (equality_index += 1) {
                if (try self.prepareDraftStructuralEq(body_draft, graph, equality_index)) {
                    added_method_call = true;
                }
            }

            var added_inspect_method = false;
            var inspect_index: usize = 0;
            while (inspect_index < body_draft.deferred_inspects.items.len) : (inspect_index += 1) {
                const boundary = body_draft.deferred_inspects.items[inspect_index];
                if (try self.prepareDraftInspectMethods(body_draft, graph, boundary)) {
                    added_inspect_method = true;
                }
            }

            var added_codec_call = false;
            var codec_index: usize = 0;
            while (codec_index < body_draft.deferred_structural_serializations.items.len) : (codec_index += 1) {
                if (try self.prepareDraftStructuralSerialization(
                    body_draft,
                    graph,
                    body_draft.deferred_structural_serializations.items[codec_index],
                )) added_codec_call = true;
            }

            var restore_index: usize = 0;
            while (restore_index < body_draft.deferred_stored_codec_restores.items.len) : (restore_index += 1) {
                if (try self.prepareDraftStoredCodecRestore(
                    body_draft,
                    graph,
                    body_draft.deferred_stored_codec_restores.items[restore_index],
                )) added_codec_call = true;
            }

            var added_intrinsic_call = false;
            var intrinsic_index: usize = 0;
            while (intrinsic_index < body_draft.deferred_callsite_intrinsics.items.len) : (intrinsic_index += 1) {
                if (try self.prepareDraftCallsiteIntrinsic(
                    body_draft,
                    graph,
                    body_draft.deferred_callsite_intrinsics.items[intrinsic_index],
                )) added_intrinsic_call = true;
            }

            if (const_index < body_draft.deferred_const_uses.items.len) continue;
            if (!added_method_call and !added_inspect_method and !added_codec_call and !added_intrinsic_call) break;
        }
        try self.resolveDraftConstUseReservations(body_draft);

        for (body_draft.deferred_const_uses.items) |boundary| {
            if (body_draft.exprs.items[@backingInt(boundary.expr)].data == .pending_deferred) {
                Common.invariant("deferred const reservation was not filled before body sealing");
            }
        }
        for (body_draft.deferred_structural_eqs.items) |boundary| {
            if (!boundary.emission_plan_ready) {
                Common.invariant("deferred structural equality had no prepared emission plan");
            }
        }
        for (body_draft.deferred_structural_serializations.items) |boundary| {
            if (body_draft.exprs.items[@backingInt(boundary.expr)].data != .pending_deferred) {
                Common.invariant("deferred structural serialization reservation was filled before final graph sealing");
            }
        }
        for (body_draft.deferred_stored_codec_restores.items) |boundary| {
            if (body_draft.exprs.items[@backingInt(boundary.expr)].data != .pending_deferred) {
                Common.invariant("deferred stored codec restore reservation was filled before final graph sealing");
            }
        }
        for (body_draft.deferred_callsite_intrinsics.items) |boundary| {
            if (body_draft.exprs.items[@backingInt(boundary.expr)].data != .pending_deferred) {
                Common.invariant("deferred call-site intrinsic reservation was filled before final graph sealing");
            }
        }
    }

    /// A body context for the deferred boundary `boundary`: its module view,
    /// method scope, owner template, evidence, and enclosing function key.
    inline fn deferredBoundaryContext(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        boundary: anytype,
    ) Allocator.Error!BodyContext {
        var ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self,
            boundary.view,
            boundary.method_scope,
            boundary.owner_template,
            graph,
            body_draft,
        );
        ctx.evidence = boundary.evidence;
        ctx.current_fn_key = boundary.current_fn_key;
        return ctx;
    }

    fn finalizeDraftConstUse(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        boundary_index: usize,
    ) Allocator.Error!void {
        const boundary = body_draft.deferred_const_uses.items[boundary_index];
        if (boundary.restored_source != null) {
            Common.invariant("deferred const reservation was expanded more than once");
        }
        const owner_scope = try body_draft.enterOwner(boundary.owner);
        defer owner_scope.leave();

        const saved_loc = self.current_loc;
        defer self.current_loc = saved_loc;
        const saved_region = self.current_region;
        defer self.current_region = saved_region;
        self.current_loc = body_draft.expr_locs.items[@backingInt(boundary.expr)];
        self.current_region = body_draft.expr_regions.items[@backingInt(boundary.expr)];

        var ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self,
            boundary.view,
            boundary.method_scope,
            boundary.owner_template,
            graph,
            body_draft,
        );
        defer ctx.deinit();
        try ctx.inheritActiveConstBindingId(boundary.active_const_binding);
        ctx.evidence = boundary.context_evidence;
        ctx.current_fn_key = boundary.current_fn_key;
        try ctx.restoreCodecLexicalContext(boundary.lexical);

        const restored = switch (boundary.provenance) {
            .declared => try ctx.restoreConstUseAtNode(
                boundary.const_use,
                boundary.request_node,
                boundary.use_evidence,
            ),
            .hoisted => |entry| blk: {
                const previous_restore_evidence = ctx.restore_evidence;
                defer ctx.restore_evidence = previous_restore_evidence;
                ctx.restore_evidence = rootEvidence(ctx.owner_template, boundary.use_evidence);
                break :blk try ctx.restoredHoistedConstAtNode(entry, boundary.witness_node);
            },
        };
        const restored_expr = body_draft.exprs.items[@backingInt(restored)];
        const restored_node = try restored_expr.ty.toGraphNode(graph);
        try relateRequestComponent(graph, boundary.witness_node, restored_node);
        try relateRequestComponent(graph, boundary.request_node, boundary.witness_node);
        const restored_proof = body_draft.expr_impossibility_proofs.items[@backingInt(restored)];
        body_draft.impossibility_proofs.items[@backingInt(boundary.proof_reservation)] =
            if (restored_proof) |proof| .{ .forward = proof } else .never;
        body_draft.deferred_const_uses.items[boundary_index].restored_source = restored;
    }

    const DraftReservationState = enum { unseen, visiting, resolved };

    /// Const restoration can explicitly produce another deferred const use or
    /// a stable active-binding reservation. Record those exact dependencies,
    /// then resolve every one-edge chain in linear time. A recursive backedge
    /// is not a dependency edge here: materializing the active binding replaces
    /// its reservation with an explicit recursive let before this pass.
    /// Expression source metadata travels with the restored payload so hoisted
    /// diagnostics keep the original checked expression provenance rather than
    /// the const use site's location. The proof reservation is stable from the
    /// original producer and was filled during expansion.
    fn resolveDraftConstUseReservations(
        self: *Builder,
        body_draft: *BodyDraftStore,
    ) Allocator.Error!void {
        const expr_count = body_draft.exprs.items.len;
        const sources = try self.allocator.alloc(?DraftExprId, expr_count);
        defer self.allocator.free(sources);
        @memset(sources, null);

        const states = try self.allocator.alloc(DraftReservationState, expr_count);
        defer self.allocator.free(states);
        @memset(states, .unseen);

        const stack = try self.allocator.alloc(DraftExprId, expr_count);
        defer self.allocator.free(stack);

        for (body_draft.deferred_const_uses.items) |boundary| {
            const restored = boundary.restored_source orelse
                Common.invariant("deferred const reservation had no explicit restored source");
            const reservation_index = @backingInt(boundary.expr);
            if (body_draft.exprs.items[reservation_index].data != .pending_deferred) {
                Common.invariant("deferred const reservation was filled more than once");
            }
            if (body_draft.expr_impossibility_proofs.items[reservation_index] != boundary.proof_reservation) {
                Common.invariant("deferred const reservation lost its stable impossibility proof");
            }
            if (sources[reservation_index] != null) {
                Common.invariant("deferred const reservation had more than one dependency");
            }
            sources[reservation_index] = restored;
        }

        for (body_draft.active_const_bindings.items) |active| {
            const reservation_index = @backingInt(active.reservation);
            if (body_draft.exprs.items[reservation_index].data != .pending_deferred) continue;
            const restored = active.restored_source orelse
                Common.invariant("active const reservation had no explicit restored source");
            if (sources[reservation_index] != null) {
                Common.invariant("active const reservation had more than one dependency");
            }
            sources[reservation_index] = restored;
        }

        for (body_draft.deferred_const_uses.items) |boundary| {
            try resolveDraftReservationChain(body_draft, sources, states, stack, boundary.expr);
        }
        for (body_draft.active_const_bindings.items) |active| {
            try resolveDraftReservationChain(body_draft, sources, states, stack, active.reservation);
        }
    }

    fn resolveDraftReservationChain(
        body_draft: *BodyDraftStore,
        sources: []const ?DraftExprId,
        states: []DraftReservationState,
        stack: []DraftExprId,
        start: DraftExprId,
    ) Allocator.Error!void {
        var depth: usize = 0;
        var cursor = start;
        while (body_draft.exprs.items[@backingInt(cursor)].data == .pending_deferred) {
            const cursor_index = @backingInt(cursor);
            switch (states[cursor_index]) {
                .unseen => {
                    states[cursor_index] = .visiting;
                    stack[depth] = cursor;
                    depth += 1;
                    cursor = sources[cursor_index] orelse
                        Common.invariant("pending const reservation had no explicit dependency");
                },
                .visiting => Common.invariant("deferred const reservation dependencies formed a cycle"),
                .resolved => Common.invariant("resolved const reservation remained pending"),
            }
        }

        while (depth > 0) {
            depth -= 1;
            const reservation = stack[depth];
            const reservation_index = @backingInt(reservation);
            const restored = sources[reservation_index] orelse
                Common.invariant("pending const reservation lost its explicit dependency");
            const restored_index = @backingInt(restored);
            const restored_expr = body_draft.exprs.items[restored_index];
            if (restored_expr.data == .pending_deferred) {
                Common.invariant("deferred const dependency was not resolved before its consumer");
            }
            body_draft.exprs.items[reservation_index] = restored_expr;
            body_draft.expr_locs.items[reservation_index] = body_draft.expr_locs.items[restored_index];
            body_draft.expr_regions.items[reservation_index] = body_draft.expr_regions.items[restored_index];
            states[reservation_index] = .resolved;
        }
    }

    fn prepareDraftStructuralEq(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        boundary_index: usize,
    ) Allocator.Error!bool {
        const boundary = body_draft.deferred_structural_eqs.items[boundary_index];
        if (boundary.mode == .tag_discriminant) {
            body_draft.deferred_structural_eqs.items[boundary_index].emission_plan_ready = true;
            return false;
        }
        const owner_scope = try body_draft.enterOwner(boundary.owner);
        defer owner_scope.leave();

        const saved_loc = self.current_loc;
        defer self.current_loc = saved_loc;
        const saved_region = self.current_region;
        defer self.current_region = saved_region;
        self.current_loc = body_draft.expr_locs.items[@backingInt(boundary.expr)];
        self.current_region = body_draft.expr_regions.items[@backingInt(boundary.expr)];

        var ctx = try self.deferredBoundaryContext(body_draft, graph, boundary);
        defer ctx.deinit();
        try ctx.restoreCodecLexicalContext(boundary.lexical);

        var seen = collections.DenseMap(NodeId, void).init(self.allocator);
        defer seen.deinit();
        var added_method_call = false;
        try ctx.prepareStructuralEqNode(
            boundary_index,
            boundary.mode,
            boundary.operand_node,
            boundary.ret_ty,
            &seen,
            &added_method_call,
        );
        body_draft.deferred_structural_eqs.items[boundary_index].emission_plan_ready = true;
        return added_method_call;
    }

    fn prepareDraftInspectMethods(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        boundary: DraftDeferredInspect,
    ) Allocator.Error!bool {
        const owner_scope = try body_draft.enterOwner(boundary.owner);
        defer owner_scope.leave();

        var ctx = try self.deferredBoundaryContext(body_draft, graph, boundary);
        defer ctx.deinit();
        try ctx.restoreCodecLexicalContext(boundary.lexical);
        if (try ctx.deferredInspectHasProvenUninhabitedValueGuard(boundary)) return false;

        var seen = collections.DenseMap(NodeId, void).init(self.allocator);
        defer seen.deinit();
        return try ctx.prepareInspectMethodsAtNode(boundary.value_node, boundary.ret_ty, &seen);
    }

    fn prepareDraftStructuralSerialization(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        boundary: DraftDeferredStructuralSerialization,
    ) Allocator.Error!bool {
        const owner_scope = try body_draft.enterOwner(boundary.owner);
        defer owner_scope.leave();

        var ctx = try self.deferredBoundaryContext(body_draft, graph, boundary);
        defer ctx.deinit();
        ctx.active_codec_contract = try ctx.instantiateCodecContract(
            boundary.structural,
            boundary.callable_node,
            boundary.shape_node,
        );
        try ctx.restoreCodecLexicalContext(boundary.lexical);

        const kind: CodecKind = switch (boundary.plan.result_mode) {
            .parser_for => .parser,
            .encoder_for => .encoder,
            .value, .equality, .hash, .map, .map_effectful => Common.invariant("non-codec result mode reached deferred codec preparation"),
        };
        return try ctx.prepareStructuralCodecCallsAtNode(
            boundary.expr,
            kind,
            boundary.shape_node,
            boundary.callable_node,
        );
    }

    /// Relation production for a deferred stored codec restore. The restore
    /// prepared this boundary's calls once at deferral time; rerunning to
    /// fixpoint here matches the structural path, because preparing one nested
    /// codec call can expose another reachable shape.
    fn prepareDraftStoredCodecRestore(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        boundary: DraftDeferredStoredCodecRestore,
    ) Allocator.Error!bool {
        const owner_scope = try body_draft.enterOwner(boundary.owner);
        defer owner_scope.leave();

        var ctx = try self.deferredBoundaryContext(body_draft, graph, boundary);
        defer ctx.deinit();
        try ctx.inheritActiveConstBindingId(boundary.active_const_binding);
        try ctx.restoreCodecLexicalContext(boundary.lexical);
        try ctx.installRetainedCodecContract(boundary.codec_contract orelse
            Common.invariant("deferred stored codec restore had no enclosing codec contract"));

        // No `active_codec_contract` here, unlike `prepareDraftStructuralSerialization`:
        // a stored codec restore has no `SpecStructuralEvidence`—its
        // constructor came from the ConstStore, not from a structural dispatch
        // plan—so `checkedGeneratedCodecCallee` correctly finds no contract
        // and falls back to ordinary method-lookup resolution. The eager
        // restore this replaced set no contract either.
        return try ctx.prepareStructuralCodecCallsAtNode(
            boundary.expr,
            boundary.kind,
            boundary.shape_node,
            boundary.callable_node,
        );
    }

    /// Relation production for a deferred call-site intrinsic. Only
    /// `parse_tag_union` generates parser bodies whose format method calls
    /// and error-row tags must exist as graph relations before the freeze;
    /// the FieldNames/Field intrinsics only reshape already-related values.
    /// The intrinsic's callable is `(spec, options) -> Try({value, rest}, e)`;
    /// a synthetic `(encoding) -> (state) -> Try` constructor node over the
    /// options' own component cells lets the structural-parser preparation
    /// helpers run unchanged.
    fn prepareDraftCallsiteIntrinsic(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        boundary: DraftDeferredCallsiteIntrinsic,
    ) Allocator.Error!bool {
        if (boundary.intrinsic != .parse_tag_union) return false;
        const owner_scope = try body_draft.enterOwner(boundary.owner);
        defer owner_scope.leave();

        var ctx = try self.deferredBoundaryContext(body_draft, graph, boundary);
        defer ctx.deinit();
        try ctx.restoreCodecLexicalContext(boundary.lexical);
        try ctx.installRetainedCodecContract(boundary.codec_contract orelse
            Common.invariant("deferred parse-tag-union intrinsic had no enclosing codec contract"));

        const callable = try graph.functionNodes(boundary.callable_node);
        const constructor_node = try ctx.parseTagUnionSyntheticBoundary(callable, callable.ret);
        const result = try ctx.graphParserResultNodes(callable.ret);

        return try ctx.prepareParseTagUnionPayloadCodecCalls(
            boundary.expr,
            result.value,
            constructor_node,
        );
    }

    /// Phase B for deferred equality. The graph is frozen and `sealer` is the
    /// one final materializer shared with all subsequent body sealing.
    fn emitDraftDeferredStructuralEqs(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
    ) Allocator.Error!void {
        for (body_draft.deferred_structural_eqs.items, 0..) |boundary, boundary_index| {
            if (!boundary.emission_plan_ready) {
                Common.invariant("deferred structural equality had no prepared emission plan");
            }
            try self.emitDraftStructuralEq(body_draft, graph, sealer, boundary_index, boundary);
        }
        for (body_draft.deferred_structural_eqs.items) |boundary| {
            if (body_draft.exprs.items[@backingInt(boundary.expr)].data == .pending_deferred) {
                Common.invariant("deferred structural equality emission plan did not fill its reservation");
            }
        }
    }

    /// Structural parser and encoder generation depends on the dispatcher's
    /// complete closed shape. Checked row defaults remain live graph evidence
    /// until this phase, so generation consumes the same final snapshot used
    /// by every other draft type instead of forcing an eager callable view.
    fn emitDraftDeferredStructuralSerializations(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
    ) Allocator.Error!void {
        const runtime_demand_count = body_draft.runtime_value_demands.items.len;
        for (body_draft.deferred_structural_serializations.items) |boundary| {
            const owner_scope = try body_draft.enterOwner(boundary.owner);
            defer owner_scope.leave();

            const saved_loc = self.current_loc;
            defer self.current_loc = saved_loc;
            const saved_region = self.current_region;
            defer self.current_region = saved_region;
            self.current_loc = body_draft.expr_locs.items[@backingInt(boundary.expr)];
            self.current_region = body_draft.expr_regions.items[@backingInt(boundary.expr)];

            var ctx = try self.deferredBoundaryContext(body_draft, graph, boundary);
            defer ctx.deinit();
            try ctx.restoreCodecLexicalContext(boundary.lexical);
            ctx.frozen_sealed_emission = true;
            ctx.frozen_type_finals = sealer;

            var frozen_codec_calls = try ctx.sealedPreparedCodecCallsForBoundary(boundary.expr, sealer);
            defer frozen_codec_calls.deinit(self.allocator);
            ctx.frozen_codec_calls = &frozen_codec_calls;
            var frozen_field_defaults = try ctx.sealedPreparedFieldDefaultsForBoundary(boundary.expr, sealer);
            defer frozen_field_defaults.deinit(self.allocator);
            ctx.frozen_field_defaults = &frozen_field_defaults;

            const callable_ty = try sealer.sealNode(boundary.callable_node);
            const callable = ctx.functionShape(callable_ty, "deferred structural serialization callable was not a function");
            const shape_ty = try sealer.sealNode(boundary.shape_node);
            const pre_lowered = [_]BodyContext.PreLoweredOperand{.{ .index = 0, .expr = boundary.encoding }};
            const lowered = switch (boundary.plan.result_mode) {
                .parser_for => try ctx.lowerStructuralParser(boundary.plan, callable_ty, callable.ret, &ctx, &pre_lowered, shape_ty),
                .encoder_for => try ctx.lowerStructuralEncoderFor(boundary.plan, callable_ty, callable.ret, &ctx, &pre_lowered, shape_ty),
                .value, .equality, .hash, .map, .map_effectful => Common.invariant("non-serialization dispatch reached deferred structural serialization emission"),
            };
            var lowered_expr = body_draft.exprs.items[@backingInt(lowered)];
            const lowered_ty = try lowered_expr.ty.seal(graph, sealer);
            if (!try ctx.typeStore().typeEql(ctx.nameStore(), callable.ret, lowered_ty)) {
                Common.invariant("deferred structural serialization changed its sealed result type");
            }
            lowered_expr.ty = .{ .sealed = callable.ret };
            body_draft.exprs.items[@backingInt(boundary.expr)] = lowered_expr;
            body_draft.expr_impossibility_proofs.items[@backingInt(boundary.expr)] =
                body_draft.expr_impossibility_proofs.items[@backingInt(lowered)];
        }
        for (body_draft.deferred_structural_serializations.items) |boundary| {
            if (body_draft.exprs.items[@backingInt(boundary.expr)].data == .pending_deferred) {
                Common.invariant("deferred structural serialization did not fill its reservation");
            }
        }
        if (body_draft.runtime_value_demands.items.len != runtime_demand_count) {
            Common.invariant("sealed structural serialization emission produced a new checked runtime-value demand");
        }
    }

    /// Phase B for a stored codec constant. The restore instantiated its
    /// constructor against the request and prepared every generated
    /// format-method call while relations were still open; the body itself is
    /// generated here from the one final snapshot, so a protocol row or a
    /// field kind that only the freeze decides is already decided.
    fn emitDraftDeferredStoredCodecRestores(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
    ) Allocator.Error!void {
        const runtime_demand_count = body_draft.runtime_value_demands.items.len;
        for (body_draft.deferred_stored_codec_restores.items) |boundary| {
            const owner_scope = try body_draft.enterOwner(boundary.owner);
            defer owner_scope.leave();

            const saved_loc = self.current_loc;
            defer self.current_loc = saved_loc;
            const saved_region = self.current_region;
            defer self.current_region = saved_region;
            self.current_loc = body_draft.expr_locs.items[@backingInt(boundary.expr)];
            self.current_region = body_draft.expr_regions.items[@backingInt(boundary.expr)];

            var ctx = try self.deferredBoundaryContext(body_draft, graph, boundary);
            defer ctx.deinit();
            try ctx.inheritActiveConstBindingId(boundary.active_const_binding);
            try ctx.restoreCodecLexicalContext(boundary.lexical);
            try ctx.installRetainedCodecContract(boundary.codec_contract orelse
                Common.invariant("deferred stored codec restore had no enclosing codec contract"));
            ctx.frozen_sealed_emission = true;
            ctx.frozen_type_finals = sealer;

            var frozen_codec_calls = try ctx.sealedPreparedCodecCallsForBoundary(boundary.expr, sealer);
            defer frozen_codec_calls.deinit(self.allocator);
            ctx.frozen_codec_calls = &frozen_codec_calls;
            var frozen_field_defaults = try ctx.sealedPreparedFieldDefaultsForBoundary(boundary.expr, sealer);
            defer frozen_field_defaults.deinit(self.allocator);
            ctx.frozen_field_defaults = &frozen_field_defaults;

            const lowered = switch (boundary.kind) {
                .parser => try ctx.emitStoredParserRuntimeBody(boundary, sealer),
                .encoder => try ctx.emitStoredEncoderForRuntimeBody(boundary, sealer),
            };

            var lowered_expr = body_draft.exprs.items[@backingInt(lowered)];
            const reserved_ty = try body_draft.exprs.items[@backingInt(boundary.expr)].ty.seal(graph, sealer);
            // The emitter types its result at the request cell, which IS this
            // reservation's own cell, so comparing their seals would be
            // `sealNode(n) == sealNode(n)`. Guard the property that has
            // content instead: that the emitter returned an expression still
            // typed at the request node. (`toGraphNode` is not used here: on a
            // `.sealed` cell it calls `importMono`, which panics on a frozen
            // graph.)
            switch (lowered_expr.ty) {
                .graph_node => |node| if (!graph.sameClass(node, boundary.request_fn_node)) {
                    Common.invariant("deferred stored codec restore emitted a body outside its request cell");
                },
                .sealed => Common.invariant("deferred stored codec restore emitted a pre-sealed body"),
            }
            lowered_expr.ty = .{ .sealed = reserved_ty };
            body_draft.exprs.items[@backingInt(boundary.expr)] = lowered_expr;
            body_draft.expr_impossibility_proofs.items[@backingInt(boundary.expr)] =
                body_draft.expr_impossibility_proofs.items[@backingInt(lowered)];
        }
        for (body_draft.deferred_stored_codec_restores.items) |boundary| {
            if (body_draft.exprs.items[@backingInt(boundary.expr)].data == .pending_deferred) {
                Common.invariant("deferred stored codec restore did not fill its reservation");
            }
        }
        if (body_draft.runtime_value_demands.items.len != runtime_demand_count) {
            Common.invariant("sealed stored codec restore emission produced a new checked runtime-value demand");
        }
    }

    /// Deferred parse intrinsics consume the closed snapshot produced by
    /// final graph sealing: their callable request nodes carried live row
    /// defaults during body lowering, and only the sealer may decide the
    /// final rows those intrinsic bodies are generated over.
    fn emitDraftDeferredCallsiteIntrinsics(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
    ) Allocator.Error!void {
        for (body_draft.deferred_callsite_intrinsics.items) |boundary| {
            const owner_scope = try body_draft.enterOwner(boundary.owner);
            defer owner_scope.leave();

            const saved_loc = self.current_loc;
            defer self.current_loc = saved_loc;
            const saved_region = self.current_region;
            defer self.current_region = saved_region;
            self.current_loc = body_draft.expr_locs.items[@backingInt(boundary.expr)];
            self.current_region = body_draft.expr_regions.items[@backingInt(boundary.expr)];

            var ctx = try self.deferredBoundaryContext(body_draft, graph, boundary);
            defer ctx.deinit();
            try ctx.restoreCodecLexicalContext(boundary.lexical);
            ctx.frozen_sealed_emission = true;
            ctx.frozen_type_finals = sealer;

            var frozen_codec_calls = try ctx.sealedPreparedCodecCallsForBoundary(boundary.expr, sealer);
            defer frozen_codec_calls.deinit(self.allocator);
            ctx.frozen_codec_calls = &frozen_codec_calls;
            var frozen_field_defaults = try ctx.sealedPreparedFieldDefaultsForBoundary(boundary.expr, sealer);
            defer frozen_field_defaults.deinit(self.allocator);
            ctx.frozen_field_defaults = &frozen_field_defaults;

            const lowered = (try ctx.runLower(.{ .callsite_intrinsic = .{
                .intrinsic = boundary.intrinsic,
                .checked_expr_id = boundary.checked_expr_id,
                .source_fn_ty = boundary.source_fn_ty,
                .operands = boundary.operands,
                .callable_node = boundary.callable_node,
                .deferred_body = .{ .pre_lowered_args = boundary.pre_lowered_args },
            } })).exprValue();
            var lowered_expr = body_draft.exprs.items[@backingInt(lowered)];
            const reserved_cell = body_draft.exprs.items[@backingInt(boundary.expr)].ty;
            const reserved_ty = try reserved_cell.seal(graph, sealer);
            const lowered_ty = try lowered_expr.ty.seal(graph, sealer);
            if (!try ctx.typeStore().typeEql(ctx.nameStore(), reserved_ty, lowered_ty)) {
                Common.invariant("deferred call-site intrinsic changed its sealed result type");
            }
            lowered_expr.ty = .{ .sealed = reserved_ty };
            body_draft.exprs.items[@backingInt(boundary.expr)] = lowered_expr;
            body_draft.expr_impossibility_proofs.items[@backingInt(boundary.expr)] =
                body_draft.expr_impossibility_proofs.items[@backingInt(lowered)];
        }
        for (body_draft.deferred_callsite_intrinsics.items) |boundary| {
            if (body_draft.exprs.items[@backingInt(boundary.expr)].data == .pending_deferred) {
                Common.invariant("deferred call-site intrinsic did not fill its reservation");
            }
        }
    }

    /// Deferred inspect-only expressions consume the one closed snapshot
    /// produced by final graph sealing. They do not participate in relation
    /// production: the runtime value and result were already lowered, and the
    /// sealed value type only determines the generated renderer body.
    fn emitDraftDeferredInspects(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
    ) Allocator.Error!void {
        var prepared_methods = collections.DenseMap(Type.TypeId, DraftFnSlot).init(self.allocator);
        defer prepared_methods.deinit();
        for (body_draft.prepared_inspect_methods.items) |prepared| {
            const value_ty = try sealer.sealNode(prepared.value_node);
            const entry = try prepared_methods.getOrPut(value_ty);
            if (entry.found_existing) {
                if (!std.meta.eql(entry.value_ptr.*, prepared.callee)) {
                    Common.invariant("one sealed inspect type had multiple prepared method callees");
                }
            } else {
                entry.value_ptr.* = prepared.callee;
            }
        }
        var impossibility_evaluator = try FrozenRuntimeImpossibilityProofEvaluator.init(self.allocator, graph, body_draft);
        defer impossibility_evaluator.deinit(self.allocator);
        for (body_draft.deferred_inspects.items) |boundary| {
            const owner_scope = try body_draft.enterOwner(boundary.owner);
            defer owner_scope.leave();

            const saved_loc = self.current_loc;
            defer self.current_loc = saved_loc;
            const saved_region = self.current_region;
            defer self.current_region = saved_region;
            self.current_loc = body_draft.expr_locs.items[@backingInt(boundary.expr)];
            self.current_region = body_draft.expr_regions.items[@backingInt(boundary.expr)];

            var ctx = try self.deferredBoundaryContext(body_draft, graph, boundary);
            defer ctx.deinit();
            try ctx.restoreCodecLexicalContext(boundary.lexical);
            ctx.frozen_inspect_method_calls = &prepared_methods;

            const ret_ty = try sealer.sealType(boundary.ret_ty);
            const lowered = if (try graph.finalizesAsUninhabited(boundary.value_node) and
                try impossibility_evaluator.holds(boundary.impossibility_proof))
                try ctx.zeroBranchMatchAtTypeCell(boundary.value, .{ .sealed = ret_ty })
            else blk: {
                const value_ty = try sealer.sealNode(boundary.value_node);
                break :blk try ctx.inspectCall(boundary.value, value_ty, ret_ty);
            };
            var lowered_expr = body_draft.exprs.items[@backingInt(lowered)];
            lowered_expr.ty = .{ .sealed = ret_ty };
            body_draft.exprs.items[@backingInt(boundary.expr)] = lowered_expr;
        }
        for (body_draft.deferred_inspects.items) |boundary| {
            if (body_draft.exprs.items[@backingInt(boundary.expr)].data == .pending_deferred) {
                Common.invariant("deferred inspect emission did not fill its reservation");
            }
        }
    }

    fn emitDraftStructuralEq(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
        boundary_index: usize,
        boundary: DraftDeferredStructuralEq,
    ) Allocator.Error!void {
        const owner_scope = try body_draft.enterOwner(boundary.owner);
        defer owner_scope.leave();

        const saved_loc = self.current_loc;
        defer self.current_loc = saved_loc;
        const saved_region = self.current_region;
        defer self.current_region = saved_region;
        self.current_loc = body_draft.expr_locs.items[@backingInt(boundary.expr)];
        self.current_region = body_draft.expr_regions.items[@backingInt(boundary.expr)];

        var ctx = try self.deferredBoundaryContext(body_draft, graph, boundary);
        defer ctx.deinit();
        try ctx.restoreCodecLexicalContext(boundary.lexical);

        var method_calls = collections.DenseMap(Type.TypeId, DraftFnSlot).init(self.allocator);
        defer method_calls.deinit();
        for (body_draft.structural_eq_method_calls.items) |planned| {
            if (planned.boundary != boundary_index) continue;
            const component_ty = try sealer.sealNode(planned.node);
            const entry = try method_calls.getOrPut(component_ty);
            if (entry.found_existing) {
                if (!std.meta.eql(entry.value_ptr.*, planned.callee)) {
                    Common.invariant("deferred structural equality plan assigned two callees to one component type");
                }
            } else {
                entry.value_ptr.* = planned.callee;
            }
        }
        ctx.frozen_equality_method_calls = &method_calls;

        const operand_ty = try sealer.sealNode(boundary.operand_node);
        const ret_ty = try sealer.sealType(boundary.ret_ty);
        const lowered = switch (boundary.mode) {
            .equality => |eq| try ctx.lowerStructuralEqFromOperands(
                operand_ty,
                boundary.lhs,
                boundary.rhs,
                eq.negated,
                ret_ty,
            ),
            .tag_discriminant => |tag| try ctx.lowerEqualityAgainstTag(
                tag.value,
                operand_ty,
                tag.tag,
                tag.negated,
                ret_ty,
            ),
            .hash => try ctx.lowerHashExpr(
                operand_ty,
                boundary.lhs,
                boundary.rhs,
                ret_ty,
            ),
        };
        var lowered_expr = body_draft.exprs.items[@backingInt(lowered)];
        const lowered_ty = try lowered_expr.ty.seal(graph, sealer);
        if (!try ctx.typeStore().typeEql(ctx.nameStore(), ret_ty, lowered_ty)) {
            Common.invariant("deferred structural equality changed its sealed result type");
        }
        lowered_expr.ty = .{ .sealed = ret_ty };
        body_draft.exprs.items[@backingInt(boundary.expr)] = lowered_expr;
    }

    fn resolveDeferredTemplateSpecValueAtType(
        self: *Builder,
        body_draft: *BodyDraftStore,
        spec: anytype,
        draft_fn_ty: Type.TypeId,
        coordinator_fn_ty: Type.TypeId,
        coordinator_subst: SealedSubstitution,
        body_scheduling: TemplateBodyScheduling,
        codec_contract: ?SealedCodecContractContext,
    ) Allocator.Error!Ast.FnSlot {
        const draft_fn = &body_draft.fns.items[@backingInt(spec.fn_id)];
        draft_fn.source.mono_fn_ty = .{ .sealed = draft_fn_ty };
        const signature_relation = draft_fn.signature_relation;

        const requested_evidence = draftFnEvidence(body_draft, draft_fn.source);
        const request_digest = self.specializationTypeDigest(coordinator_fn_ty);
        const identity = self.templateSpecIdentity(
            spec.template_ref,
            spec.method_scope,
            draft_fn.source.evidence_digest,
            self.codecContractIdentity(codec_contract),
            coordinator_fn_ty,
            request_digest,
        );

        // `lowerTemplateWithMono` owns the validation and recursive state
        // handling for local specializations.
        const found_local = !spec.requires_local and
            try self.spec_store.find(identity, specializationEvidenceView(requested_evidence)) != null;

        if (found_local) {
            self.countBodyDiagnostic("deferred_template_reuses");
        } else {
            self.countBodyDiagnostic("deferred_template_bodies_lowered");
        }
        const resolved_slot: Ast.FnSlot = blk: {
            const def = try self.lowerTemplateWithMono(
                spec.template_ref,
                self.moduleForId(spec.method_scope),
                spec.source_fn_ty,
                spec.source_fn_key,
                coordinator_fn_ty,
                spec.evidence,
                coordinator_subst,
                signature_relation,
                .already_counted,
                request_digest,
                null,
                body_scheduling,
                codec_contract,
                spec.widened_result_row,
            );
            break :blk .{ .local = self.defFnId(def) };
        };
        return resolved_slot;
    }

    fn resolveSealedTemplateSpecAtType(
        self: *Builder,
        body_draft: *BodyDraftStore,
        spec_index: usize,
        draft_fn_ty: Type.TypeId,
        coordinator_fn_ty: Type.TypeId,
        coordinator_subst: SealedSubstitution,
        body_scheduling: TemplateBodyScheduling,
        codec_contract: ?SealedCodecContractContext,
    ) Allocator.Error!void {
        if (spec_index >= body_draft.sealed_template_specs.items.len) {
            Common.invariant("sealed template specialization index was outside the intent table");
        }
        const spec = body_draft.sealed_template_specs.items[spec_index];
        if (spec.state != .deferred) return;
        const resolved_slot = try self.resolveDeferredTemplateSpecValueAtType(
            body_draft,
            spec,
            draft_fn_ty,
            coordinator_fn_ty,
            coordinator_subst,
            body_scheduling,
            codec_contract,
        );
        body_draft.sealed_template_specs.items[spec_index].resolved_slot = resolved_slot;
        body_draft.sealed_template_specs.items[spec_index].state = .resolved;
    }

    /// Resolve context-free procedure requests that no representation-sensitive
    /// caller needed earlier. Their sealed callable interface is the complete
    /// specialization key. No callee body is reconstructed from, or lowered
    /// into, the caller's graph.
    fn resolveDeferredTemplateSpecs(
        self: *Builder,
        body_draft: *BodyDraftStore,
        committed_types: *CommittedGraphTypes,
    ) Allocator.Error!void {
        var spec_index: usize = 0;
        while (spec_index < body_draft.sealed_template_specs.items.len) : (spec_index += 1) {
            const state = body_draft.sealed_template_specs.items[spec_index].state;
            if (state != .deferred) continue;
            const spec = &body_draft.sealed_template_specs.items[spec_index];
            const draft_fn_ty = spec.request_fn_ty;
            const coordinator_fn_ty = try committed_types.commitType(draft_fn_ty);
            const coordinator_subst = try self.commitSealedSubstitution(committed_types, spec.subst);
            const codec_contract: ?SealedCodecContractContext = if (spec.codec_contract) |contract| .{
                .anchor = contract.anchor,
                .constructor_ty = try committed_types.commitType(
                    contract.constructor_ty,
                ),
                .shape_ty = try committed_types.commitType(contract.shape_ty),
            } else null;
            // Seal-time requests are symbolic: they reserve the callee's id
            // for call-site patching and queue the body for the wave drain.
            try self.resolveSealedTemplateSpecAtType(
                body_draft,
                spec_index,
                draft_fn_ty,
                coordinator_fn_ty,
                coordinator_subst,
                .queued,
                codec_contract,
            );
        }
    }

    /// Relocate a shard-sealed substitution into the coordinator's store,
    /// slot by slot, exactly as the request type is relocated.
    fn commitSealedSubstitution(
        self: *Builder,
        committed_types: *CommittedGraphTypes,
        subst: SealedSubstitution,
    ) Allocator.Error!SealedSubstitution {
        if (subst.len == 0) return &.{};
        const out = try self.evidence_arena.allocator().alloc(SealedSubstSlot, subst.len);
        for (subst, out) |slot, *committed| {
            committed.* = switch (slot) {
                .checked_error => .checked_error,
                .ty => |ty| .{ .ty = try committed_types.commitType(ty) },
            };
        }
        return out;
    }

    fn buildDraftCommitMap(
        self: *Builder,
        body_draft: *BodyDraftStore,
        committed_types: *CommittedGraphTypes,
        base_ids: FinalIdOffsets,
    ) Allocator.Error!DraftCommitMap {
        var ids = base_ids;
        const static_data_ids =
            try self.allocator.alloc(Common.StaticDataId, body_draft.static_data_requests.items.len);
        errdefer self.allocator.free(static_data_ids);
        // Static-data requests are result intents, not function-range members.
        // Absorb all of them even if identity merging later discards a duplicate
        // function body, preserving the prior eager assignment of durable ids.
        for (body_draft.static_data_requests.items, static_data_ids) |request, *id| {
            const coordinator_ty = try request.ty.sealCommitted(committed_types);
            id.* = try self.commitStaticDataValue(
                request.const_locator,
                request.node,
                request.checked_type,
                coordinator_ty,
            );
        }
        const fn_slots = try self.allocator.alloc(?Ast.FnSlot, body_draft.fns.items.len);
        errdefer self.allocator.free(fn_slots);
        @memset(fn_slots, null);
        const def_ids = try self.allocator.alloc(?Ast.DefId, body_draft.defs.items.len);
        errdefer self.allocator.free(def_ids);
        const emit_fns = try self.allocator.alloc(bool, body_draft.fns.items.len);
        errdefer self.allocator.free(emit_fns);
        const emit_defs = try self.allocator.alloc(bool, body_draft.defs.items.len);
        errdefer self.allocator.free(emit_defs);
        const emit_nested_defs = try self.allocator.alloc(bool, body_draft.nested_defs.items.len);
        errdefer self.allocator.free(emit_nested_defs);
        const identities = try self.allocator.alloc(?Ast.SpecIdentity, body_draft.fns.items.len);
        defer self.allocator.free(identities);
        @memset(identities, null);
        const solved_fn_tys = try self.allocator.alloc(Type.TypeId, body_draft.fns.items.len);
        defer self.allocator.free(solved_fn_tys);
        for (body_draft.sealed_template_specs.items) |*spec| {
            spec.committed_request_fn_ty = try committed_types.commitType(spec.request_fn_ty);
            spec.committed_codec_contract = if (spec.codec_contract) |contract|
                self.codecContractIdentity(.{
                    .anchor = contract.anchor,
                    .constructor_ty = try committed_types.commitType(
                        contract.constructor_ty,
                    ),
                    .shape_ty = try committed_types.commitType(contract.shape_ty),
                })
            else
                null;
        }
        for (body_draft.sealed_nested_specs.items) |*spec| {
            spec.sealed_codec_contract = if (spec.codec_contract) |contract|
                self.codecContractIdentity(.{
                    .anchor = contract.anchor,
                    .constructor_ty = try committed_types.commitType(
                        contract.constructor_ty,
                    ),
                    .shape_ty = try committed_types.commitType(contract.shape_ty),
                })
            else
                null;
        }

        // These sealed tables no longer change during commit. Index their
        // producer-authored function ids once rather than searching per body.
        var template_by_fn = collections.DenseMap(DraftFnId, *const SealedTemplateSpec).init(self.allocator);
        defer template_by_fn.deinit();
        for (body_draft.sealed_template_specs.items) |*spec| {
            self.countBodyDiagnostic("draft_commit_lookup_steps");
            try template_by_fn.put(spec.fn_id, spec);
        }
        var nested_by_fn = collections.DenseMap(DraftFnId, *const SealedNestedSpec).init(self.allocator);
        defer nested_by_fn.deinit();
        for (body_draft.sealed_nested_specs.items) |*spec| {
            self.countBodyDiagnostic("draft_commit_lookup_steps");
            try nested_by_fn.put(spec.fn_id, spec);
        }
        var prior_identities = std.AutoHashMap(specialize.SpecLookupAddress, u32).init(self.allocator);
        defer prior_identities.deinit();
        const previous_same_identity = try self.allocator.alloc(?u32, body_draft.fns.items.len);
        defer self.allocator.free(previous_same_identity);

        var next_fn: u32 = @intCast(self.program.fnCount());
        for (body_draft.fns.items, 0..) |fn_, raw_index| {
            const draft_id: DraftFnId = @fromBackingInt(@intCast(@as(u32, @intCast(raw_index))));
            self.countBodyDiagnostic("draft_commit_lookup_steps");
            const template_spec = template_by_fn.get(draft_id);
            if (template_spec) |spec| {
                if (spec.state == .resolved) {
                    fn_slots[raw_index] = spec.resolved_slot orelse
                        Common.invariant("resolved draft template demand had no specialization slot");
                    emit_fns[raw_index] = false;
                    continue;
                }
            }

            // Evidence does not participate in the specialization type digest.
            const sealed_template = try BodyDraftStore.sealFnTemplate(committed_types, fn_.source, 0, 0);
            const fn_ty = sealed_template.mono_fn_ty;
            solved_fn_tys[raw_index] = fn_ty;
            const requested_evidence = draftFnEvidence(body_draft, fn_.source);
            var identity: ?Ast.SpecIdentity = null;
            var allow_identity_merge = true;
            var lexical_owner: ?DraftOwner = null;
            if (template_spec) |spec| {
                if (!spec.local_context_dependent) {
                    const request_fn_ty = spec.committed_request_fn_ty orelse
                        Common.compilerBug("template specialization request type was not committed");
                    const request_digest = self.specializationTypeDigest(request_fn_ty);
                    identity = self.templateSpecIdentity(
                        spec.template_ref,
                        spec.method_scope,
                        sealed_template.evidence_digest,
                        spec.committed_codec_contract,
                        request_fn_ty,
                        request_digest,
                    );
                }
                lexical_owner = spec.lexical_owner;
                allow_identity_merge = !spec.requires_local;
            }
            if (identity == null) {
                if (nested_by_fn.get(draft_id)) |spec| {
                    if (!spec.local_context_dependent) {
                        const solved_digest = self.specializationTypeDigest(fn_ty);
                        identity = self.nestedSpecIdentity(
                            spec.nested,
                            spec.method_scope,
                            sealed_template.evidence_digest,
                            spec.capture_abi_digest,
                            spec.sealed_codec_contract,
                            fn_ty,
                            solved_digest,
                        );
                    }
                    lexical_owner = spec.lexical_owner;
                    allow_identity_merge = !spec.requires_local;
                }
            }
            identities[raw_index] = identity;

            if (lexical_owner) |owner| switch (owner) {
                .root, .reserved_fn => {},
                .draft_fn => |parent| {
                    const parent_raw = @backingInt(parent);
                    if (parent_raw >= raw_index) {
                        Common.invariant("nested draft function did not follow its explicit lexical owner");
                    }
                    if (!emit_fns[parent_raw]) {
                        emit_fns[raw_index] = false;
                        if (template_spec != null) {
                            self.countBodyDiagnostic("lowered_template_bodies_discarded");
                        } else {
                            self.countBodyDiagnostic("lowered_nested_bodies_discarded");
                        }
                        continue;
                    }
                },
            };

            if (identity) |wanted| {
                const address = specialize.SpecLookupAddress.fromIdentity(wanted);
                var candidate = if (allow_identity_merge) prior_identities.get(address) else null;
                while (candidate) |prior| : (candidate = previous_same_identity[prior]) {
                    self.countBodyDiagnostic("draft_commit_lookup_steps");
                    if (identities[prior]) |existing| {
                        if (try self.draftSpecIdentityEql(existing, wanted)) {
                            const prior_template = body_draft.fns.items[prior].source;
                            const prior_evidence = draftFnEvidence(body_draft, prior_template);
                            if (!storedConstFnEvidenceEql(prior_evidence, requested_evidence)) continue;
                            if (std.debug.runtime_safety and
                                !try self.program.types.typeEql(
                                    &self.program.names,
                                    solved_fn_tys[prior],
                                    fn_ty,
                                ))
                            {
                                Common.compilerBug("equal draft specialization identities produced different solved types");
                            }
                            if (fn_.signature_relation == .exact_graph) {
                                const prior_slot = fn_slots[prior] orelse
                                    Common.invariant("duplicate draft specialization had no retained function slot");
                                switch (prior_slot) {
                                    .local => |retained_fn| {
                                        if (@backingInt(retained_fn) >= self.program.fnCount()) {
                                            for (fn_slots[0..raw_index], emit_fns[0..raw_index], 0..) |candidate_slot, emits, candidate_index| {
                                                if (emits and std.meta.eql(candidate_slot, prior_slot)) {
                                                    body_draft.fns.items[candidate_index].signature_relation = .exact_graph;
                                                    break;
                                                }
                                            } else {
                                                Common.invariant("duplicate draft specialization lost its retained body");
                                            }
                                        } else {
                                            self.promoteFnSignatureRelation(retained_fn, .exact_graph);
                                        }
                                    },
                                }
                            }
                            fn_slots[raw_index] = fn_slots[prior];
                            emit_fns[raw_index] = false;
                            if (template_spec != null) {
                                self.countBodyDiagnostic("lowered_template_bodies_discarded");
                            } else {
                                self.countBodyDiagnostic("lowered_nested_bodies_discarded");
                            }
                            break;
                        }
                    }
                } else {
                    const committed: ?specialize.LookupResult = if (allow_identity_merge)
                        if (try self.spec_store.findLocal(wanted, specializationEvidenceView(requested_evidence))) |hit|
                            .{ .local = hit }
                        else
                            null
                    else
                        null;
                    if (committed) |hit| {
                        if (fn_.signature_relation == .exact_graph) {
                            self.promoteFnSignatureRelation(hit.local.fn_id, .exact_graph);
                        }
                        if (std.debug.runtime_safety and hit.local.status == .ready and
                            !try self.program.types.typeEql(
                                &self.program.names,
                                hit.local.solved_fn_ty,
                                fn_ty,
                            ))
                        {
                            Common.compilerBug("equal committed specialization identities produced different solved types");
                        }
                        const committed_evidence = programViewFnEvidence(self.program.view(), self.program.fnSource(hit.local.fn_id));
                        if (!storedConstFnEvidenceEql(committed_evidence, requested_evidence)) {
                            Common.invariant("committed specialization hit disagreed on dispatch evidence topology");
                        }
                        fn_slots[raw_index] = hit.target();
                        emit_fns[raw_index] = false;
                        if (template_spec != null) {
                            self.countBodyDiagnostic("lowered_template_bodies_discarded");
                        } else {
                            self.countBodyDiagnostic("lowered_nested_bodies_discarded");
                        }
                    } else {
                        fn_slots[raw_index] = .{ .local = @fromBackingInt(@intCast(next_fn)) };
                        next_fn += 1;
                        emit_fns[raw_index] = true;
                    }
                    if (allow_identity_merge) {
                        const entry = try prior_identities.getOrPut(address);
                        previous_same_identity[raw_index] = if (entry.found_existing) entry.value_ptr.* else null;
                        entry.value_ptr.* = @intCast(raw_index);
                    }
                }
            } else {
                fn_slots[raw_index] = .{ .local = @fromBackingInt(@intCast(next_fn)) };
                next_fn += 1;
                emit_fns[raw_index] = true;
            }
        }

        var next_def: u32 = @intCast(self.program.defCount());
        for (body_draft.defs.items, body_draft.def_owners.items, 0..) |_, owner, raw_index| {
            if (!draftOwnerRetained(owner, emit_fns)) {
                def_ids[raw_index] = null;
                emit_defs[raw_index] = false;
                continue;
            }
            def_ids[raw_index] = @fromBackingInt(@intCast(next_def));
            next_def += 1;
            emit_defs[raw_index] = true;
        }

        for (body_draft.nested_defs.items, 0..) |def, index| {
            emit_nested_defs[index] = switch (def.fn_id) {
                .final => true,
                .draft => |draft_fn| emit_fns[@backingInt(draft_fn)],
            };
        }
        const core_maps = try self.buildDraftCoreMaps(body_draft, emit_fns);
        errdefer {
            core_maps.deinit(self.allocator);
            self.allocator.destroy(core_maps);
        }
        ids.fn_slots = fn_slots;
        ids.def_ids = def_ids;
        ids.core_id_mode = .{ .remapped = core_maps };
        return .{
            .ids = ids,
            .core_maps = core_maps,
            .emit_fns = emit_fns,
            .emit_defs = emit_defs,
            .emit_nested_defs = emit_nested_defs,
            .static_data_ids = static_data_ids,
        };
    }

    fn sealActiveBodyDraft(
        self: *Builder,
        graph: *InstGraph,
        body_draft: *BodyDraftStore,
        final_guard: FinalBodyOutputGuard,
        final_end: FinalBodyOutputGuard.End,
        root_node: ?NodeId,
        root_nodes: []const NodeId,
        extra_ty: ?Type.TypeId,
        root_def: ?DraftDefId,
        root_fn: ?DraftFnId,
    ) Allocator.Error!ActiveBodyDraftSeal {
        try self.finalizeBodyDraftGraph(graph, body_draft, final_guard, final_end);
        return self.commitFinalizedBodyDraft(
            graph,
            body_draft,
            root_node,
            root_nodes,
            extra_ty,
            root_def,
            root_fn,
            null,
        );
    }

    /// Finish every relation-producing draft operation and freeze the graph
    /// before an owned specialization result can cross the coordinator handoff.
    ///
    /// Deferred preparation remains serialized because it can reenter lowering
    /// and mutate shared Builder state. Iterator identity calculation uses the
    /// graph-owned type and name stores.
    fn finalizeBodyDraftGraph(
        self: *Builder,
        graph: *InstGraph,
        body_draft: *BodyDraftStore,
        final_guard: FinalBodyOutputGuard,
        final_end: FinalBodyOutputGuard.End,
    ) Allocator.Error!void {
        var timing_scope = ProcedureTimingScope.begin(self.timing, .body_finalization);
        defer timing_scope.end();

        final_guard.assertNoFinalBodyOutput(final_end);
        if (body_draft.active_callable_eval_bindings.items.len != 0) {
            Common.invariant("unfinished callable eval binding reached Monotype body sealing");
        }
        const finalization_guard = FinalBodyOutputGuard.begin(self);
        try self.prepareDraftDeferredExprs(body_draft, graph);
        try graph.finalizeGeneratedIteratorRepresentations();
        try graph.finalizeGeneratedIteratorIdentities();
        try graph.freezeRelations();
        var impossibility_evaluator = try FrozenRuntimeImpossibilityProofEvaluator.init(self.allocator, graph, body_draft);
        defer impossibility_evaluator.deinit(self.allocator);
        for (body_draft.runtime_value_demands.items) |demand| {
            if (graph.finalizesAsClosedEmptyTagUnion(demand.node)) {
                if (try impossibility_evaluator.holds(demand.impossibility_proof)) continue;
                Common.invariant("runtime-value demand finalized as a closed empty tag-union type");
            }
        }
        try verifySpecReuseDemands(body_draft, graph, &impossibility_evaluator);
        finalization_guard.assertNoFinalBodyOutput(finalization_guard.end(self));
    }

    /// Convert graph-qualified specialization records into the only intent
    /// shapes accepted by coordinator commit.
    fn sealDraftCoordinatorIntents(
        graph: *InstGraph,
        body_draft: *BodyDraftStore,
        sealer: *GraphTypeFinals,
    ) Allocator.Error!void {
        if (body_draft.sealed_template_specs.items.len != 0 or
            body_draft.sealed_nested_specs.items.len != 0)
        {
            Common.compilerBug("Monotype body draft sealed coordinator intents twice");
        }

        try body_draft.sealed_template_specs.ensureTotalCapacity(
            body_draft.allocator,
            body_draft.template_specs.items.len,
        );
        for (body_draft.template_specs.items) |spec| {
            const request_ty = try sealer.sealNode(
                if (spec.eager_resolution) |eager|
                    eager.request_fn_node
                else
                    spec.lookup_request_fn_node orelse spec.request_fn_node,
            );
            if (spec.eager_resolution) |eager| {
                const eager_ty = try sealer.sealType(eager.fn_ty);
                const eager_request_ty = try sealer.sealNode(eager.request_fn_node);
                if (!try graph.types.typeEql(
                    graph.name_store,
                    eager_ty,
                    eager_request_ty,
                )) {
                    Common.invariant("eager procedure specialization request changed before final graph seal");
                }
            }
            body_draft.sealed_template_specs.appendAssumeCapacity(.{
                .state = spec.state,
                .template_ref = spec.template_ref,
                .method_scope = spec.method_scope,
                .source_fn_ty = spec.source_fn_ty,
                .source_fn_key = spec.source_fn_key,
                .request_fn_ty = request_ty,
                .evidence = spec.evidence,
                .codec_contract = if (spec.codec_contract) |contract| .{
                    .anchor = contract.anchor,
                    .constructor_ty = try sealer.sealNode(contract.constructor_node),
                    .shape_ty = try sealer.sealNode(contract.shape_node),
                } else null,
                .requires_local = spec.requires_local,
                .local_context_dependent = spec.local_context_dependent,
                .widened_result_row = spec.widened_result_row,
                .lexical_owner = spec.lexical_owner,
                .fn_id = spec.fn_id,
                .def_id = spec.def_id,
                .subst = try sealSubstitutionWithSealer(body_draft.allocator, sealer, spec.subst),
                .resolved_slot = spec.resolved_slot,
            });
        }
        try body_draft.sealed_nested_specs.ensureTotalCapacity(
            body_draft.allocator,
            body_draft.nested_specs.items.len,
        );
        for (body_draft.nested_specs.items) |spec| {
            body_draft.sealed_nested_specs.appendAssumeCapacity(.{
                .state = spec.state,
                .nested = spec.nested,
                .method_scope = spec.method_scope,
                .source_fn_key = spec.source_fn_key,
                .request_fn_ty = try sealer.sealNode(spec.request_fn_node),
                .capture_abi_digest = try graphCaptureAbiDigest(
                    graph,
                    sealer,
                    spec.capture_entry_guards,
                ),
                .codec_contract = if (spec.codec_contract) |contract| .{
                    .anchor = contract.anchor,
                    .constructor_ty = try sealer.sealNode(contract.constructor_node),
                    .shape_ty = try sealer.sealNode(contract.shape_node),
                } else null,
                .lexical_owner = spec.lexical_owner,
                .requires_local = spec.requires_local,
                .local_context_dependent = spec.local_context_dependent,
                .fn_id = spec.fn_id,
            });
        }
        for (body_draft.template_specs.items) |spec| {
            if (spec.lexical) |lexical| {
                body_draft.allocator.free(lexical.binders);
                body_draft.allocator.free(lexical.local_procs);
            }
        }
        body_draft.template_specs.deinit(body_draft.allocator);
        body_draft.template_specs = .empty;
        body_draft.nested_specs.deinit(body_draft.allocator);
        body_draft.nested_specs = .empty;
    }

    /// Consume every remaining frozen-graph query and convert the retained body
    /// into workspace-local type/name IDs. The returned completion and draft can
    /// outlive both the graph and subsequent workspace reallocations once their
    /// type/name suffix has been captured.
    fn sealOrdinarySpecJobDraft(
        self: *Builder,
        graph: *InstGraph,
        body_draft: *BodyDraftStore,
        pending: PendingTemplateBody,
    ) Allocator.Error!SealedPendingTemplateBody {
        var phase_b_sealer = GraphTypeFinals.init(graph);
        defer phase_b_sealer.deinit();

        try self.emitDraftDeferredStoredCodecRestores(body_draft, graph, &phase_b_sealer);
        try self.emitDraftDeferredStructuralSerializations(body_draft, graph, &phase_b_sealer);
        try self.emitDraftDeferredCallsiteIntrinsics(body_draft, graph, &phase_b_sealer);
        try self.emitDraftDeferredStructuralEqs(body_draft, graph, &phase_b_sealer);
        try self.emitDraftDeferredInspects(body_draft, graph, &phase_b_sealer);
        try body_draft.finishOwnerRuns();

        // Phase B may seal speculative intermediate nodes while it generates
        // retained body data. Use a fresh finalizer for the immutable handoff so
        // every retained node is read after those transactions have completed.
        var sealer = GraphTypeFinals.init(graph);
        defer sealer.deinit();

        try sealDraftCoordinatorIntents(graph, body_draft, &sealer);

        const root_ty = try sealer.sealNode(pending.root_node);
        const lowered_ret = try pending.lowered.ret.seal(graph, &sealer);
        try body_draft.sealTypeCellsInPlace(graph, &sealer);
        body_draft.discardGraphStateAfterSeal();
        body_draft.assertGraphStateDiscarded();

        return .{
            .reservation = pending.reservation,
            .fn_template = pending.fn_template,
            .signature_relation = pending.signature_relation,
            .root_ty = root_ty,
            .lowered = .{
                .args = pending.lowered.args,
                .body = pending.lowered.body,
                .ret = lowered_ret,
            },
        };
    }

    /// Seal one already-frozen graph into durable coordinator-owned ids and
    /// append its retained draft ranges to the final program.
    fn commitFinalizedBodyDraft(
        self: *Builder,
        graph: *InstGraph,
        body_draft: *BodyDraftStore,
        root_node: ?NodeId,
        root_nodes: []const NodeId,
        extra_ty: ?Type.TypeId,
        root_def: ?DraftDefId,
        root_fn: ?DraftFnId,
        committed_type_relocation: ?*Type.Store.TypeRelocation,
    ) Allocator.Error!ActiveBodyDraftSeal {
        var timing_scope = ProcedureTimingScope.begin(self.timing, .body_finalization);
        defer timing_scope.end();

        var sealer = GraphTypeFinals.init(graph);
        defer sealer.deinit();
        try self.emitDraftDeferredStoredCodecRestores(body_draft, graph, &sealer);
        try self.emitDraftDeferredStructuralSerializations(body_draft, graph, &sealer);
        try self.emitDraftDeferredCallsiteIntrinsics(body_draft, graph, &sealer);
        try self.emitDraftDeferredStructuralEqs(body_draft, graph, &sealer);
        try self.emitDraftDeferredInspects(body_draft, graph, &sealer);
        try sealDraftCoordinatorIntents(graph, body_draft, &sealer);
        var committed_types = if (committed_type_relocation) |relocation|
            CommittedGraphTypes.relocated(
                graph,
                &sealer,
                &self.program.types,
                &self.program.names,
                relocation,
            )
        else
            CommittedGraphTypes.shared(graph, &sealer);
        const sealed_root = if (root_node) |node| try committed_types.sealNode(node) else null;
        const sealed_roots = try self.allocator.alloc(Type.TypeId, root_nodes.len);
        errdefer self.allocator.free(sealed_roots);
        for (root_nodes, sealed_roots) |node, *ty| {
            ty.* = try committed_types.sealNode(node);
        }
        try body_draft.finishOwnerRuns();
        try self.resolveDeferredTemplateSpecs(body_draft, &committed_types);
        var commit_map = try self.buildDraftCommitMap(
            body_draft,
            &committed_types,
            BodyDraftStore.finalIdOffsets(self.program),
        );
        defer commit_map.deinit(self.allocator);
        const body_ids = commit_map.ids;
        const output_before = FinalBodyOutputCounts.fromProgram(self.program);
        try body_draft.sealCoreIntoProgramWithMap(
            self.program,
            &committed_types,
            commit_map.static_data_ids,
            body_ids,
            commit_map.emit_fns,
            commit_map.emit_defs,
            commit_map.emit_nested_defs,
        );
        self.final_body_output_allowance.addDelta(output_before, FinalBodyOutputCounts.fromProgram(self.program));
        const sealed_extra = if (extra_ty) |ty| blk: {
            break :blk try committed_types.sealType(ty);
        } else null;
        try self.markDraftNestedReady(body_draft, body_ids);
        try self.finalizeDraftTemplateSpecs(body_draft, body_ids);
        verifyDraftTemplateSpecsResolved(body_draft);
        try self.finalizeDraftNestedSpecs(body_draft, body_ids);
        var returned_ids = body_ids;
        returned_ids.fn_slots = &.{};
        returned_ids.def_ids = &.{};
        const retained_core_maps = commit_map.core_maps orelse
            Common.invariant("body draft commit map lost its core remapping before handoff");
        commit_map.core_maps = null;
        return .{
            .ids = returned_ids,
            .root_ty = sealed_root,
            .root_tys = sealed_roots,
            .extra_ty = sealed_extra,
            .root_def = if (root_def) |draft_def| body_ids.def(draft_def) else null,
            .root_fn = if (root_fn) |draft_fn| body_ids.fnSlot(draft_fn).local else null,
            .core_maps = retained_core_maps,
        };
    }

    /// Ordered coordinator suffix for a graph-free specialization result.
    /// Type/name IDs are read only from the copied immutable epoch domain;
    /// all final Ast IDs and specialization decisions remain coordinator-owned.
    fn commitSealedBodyDraft(
        self: *Builder,
        body_draft: *BodyDraftStore,
        root_ty: Type.TypeId,
        committed_types: *CommittedGraphTypes,
        root_def: ?DraftDefId,
    ) Allocator.Error!ActiveBodyDraftSeal {
        var timing_scope = ProcedureTimingScope.begin(self.timing, .body_finalization);
        defer timing_scope.end();

        const sealed_root = try committed_types.commitType(root_ty);
        const sealed_roots = try self.allocator.alloc(Type.TypeId, 0);
        errdefer self.allocator.free(sealed_roots);
        try self.resolveDeferredTemplateSpecs(body_draft, committed_types);
        var commit_map = try self.buildDraftCommitMap(
            body_draft,
            committed_types,
            BodyDraftStore.finalIdOffsets(self.program),
        );
        defer commit_map.deinit(self.allocator);
        const body_ids = commit_map.ids;
        const output_before = FinalBodyOutputCounts.fromProgram(self.program);
        try body_draft.sealCoreIntoProgramWithMap(
            self.program,
            committed_types,
            commit_map.static_data_ids,
            body_ids,
            commit_map.emit_fns,
            commit_map.emit_defs,
            commit_map.emit_nested_defs,
        );
        self.final_body_output_allowance.addDelta(output_before, FinalBodyOutputCounts.fromProgram(self.program));
        try self.markDraftNestedReady(body_draft, body_ids);
        try self.finalizeDraftTemplateSpecs(body_draft, body_ids);
        verifyDraftTemplateSpecsResolved(body_draft);
        try self.finalizeDraftNestedSpecs(body_draft, body_ids);
        var returned_ids = body_ids;
        returned_ids.fn_slots = &.{};
        returned_ids.def_ids = &.{};
        const retained_core_maps = commit_map.core_maps orelse
            Common.invariant("sealed body draft commit map lost its core remapping before handoff");
        commit_map.core_maps = null;
        return .{
            .ids = returned_ids,
            .root_ty = sealed_root,
            .root_tys = sealed_roots,
            .extra_ty = null,
            .root_def = if (root_def) |draft_def| body_ids.def(draft_def) else null,
            .root_fn = null,
            .core_maps = retained_core_maps,
        };
    }

    fn markDraftNestedReady(
        self: *Builder,
        body_draft: *const BodyDraftStore,
        ids: FinalIdOffsets,
    ) Allocator.Error!void {
        for (body_draft.nested_defs.items) |def| {
            switch (def.fn_id) {
                .draft => continue,
                .final => {},
            }
            const fn_id = ids.fnTarget(def.fn_id);
            const fn_template = self.program.getFn(fn_id).source;
            switch (fn_template.fn_def) {
                .nested => {},
                .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => Common.invariant("nested draft definition did not reference a nested function"),
            }
            try self.markNestedFnReady(fn_id, fn_template.mono_fn_ty);
        }
    }

    /// Finalize eagerly lowered context-free template bodies after their
    /// function and definition ranges have committed. Duplicate bodies already
    /// map to the winning slot, so only the first new local target creates a
    /// specialization record.
    fn finalizeDraftTemplateSpecs(
        self: *Builder,
        body_draft: *const BodyDraftStore,
        ids: FinalIdOffsets,
    ) Allocator.Error!void {
        for (body_draft.sealed_template_specs.items) |spec| {
            if (spec.state != .lowered or spec.local_context_dependent) continue;
            const draft_def = spec.def_id orelse
                Common.invariant("eager context-free template body had no top-level definition");
            if (!ids.hasFnSlot(spec.fn_id)) continue;

            const fn_id = switch (ids.fnSlot(spec.fn_id)) {
                .local => |local| local,
            };
            const fn_template = self.program.fnSource(fn_id);
            const solved_fn_ty = fn_template.mono_fn_ty;
            const request_fn_ty = spec.committed_request_fn_ty orelse
                Common.compilerBug("eager template request type was not committed");
            const request_digest = self.specializationTypeDigest(request_fn_ty);
            const evidence = programViewFnEvidence(self.program.view(), fn_template);
            const identity = self.templateSpecIdentity(
                spec.template_ref,
                spec.method_scope,
                fn_template.evidence_digest,
                spec.committed_codec_contract,
                request_fn_ty,
                request_digest,
            );
            if (try self.spec_store.findLocal(
                identity,
                specializationEvidenceView(evidence),
            )) |hit| {
                if (hit.fn_id != fn_id) {
                    // The commit map never merges a specialization that must
                    // stay local, so it keeps its own function beside an
                    // equal committed one.
                    if (!spec.requires_local) {
                        Common.invariant("eager template duplicate committed to a different winning function");
                    }
                    continue;
                }
                self.promoteFnSignatureRelation(
                    fn_id,
                    body_draft.fns.items[@backingInt(spec.fn_id)].signature_relation,
                );
                continue;
            }

            const spec_id = try self.addTemplateSpecRecord(
                spec.template_ref,
                spec.method_scope,
                evidence,
                request_fn_ty,
                request_digest,
                spec.committed_codec_contract,
                fn_id,
                .lowering,
            );
            try self.lowered_templates.put(fn_id, .{
                .def = ids.def(draft_def),
                .spec = spec_id,
                .evidence = spec.evidence,
                .topology = try self.retainFnEvidence(evidence),
            });
            try self.markTemplateReady(fn_id, solved_fn_ty);
        }
    }

    fn finalizeDraftNestedSpecs(
        self: *Builder,
        body_draft: *const BodyDraftStore,
        ids: FinalIdOffsets,
    ) Allocator.Error!void {
        for (body_draft.sealed_nested_specs.items) |spec| {
            if (spec.state != .lowered) {
                Common.invariant("draft nested specialization reached commit before its body lowered");
            }
            if (spec.local_context_dependent) continue;
            if (!ids.hasFnSlot(spec.fn_id)) continue;
            const fn_id = ids.fn_(spec.fn_id);
            const fn_ty = self.program.fnSource(fn_id).mono_fn_ty;
            const digest = self.specializationTypeDigest(fn_ty);
            const fn_template = self.program.fnSource(fn_id);
            const evidence = programViewFnEvidence(self.program.view(), fn_template);
            const program_span = programFnEvidenceSpan(fn_template);
            const capture_abi_digest = spec.capture_abi_digest;
            var view = specializationEvidenceView(evidence);
            view.program_span = program_span;
            if (try self.spec_store.findLocal(
                self.nestedSpecIdentity(spec.nested, spec.method_scope, fn_template.evidence_digest, capture_abi_digest, spec.sealed_codec_contract, fn_ty, digest),
                view,
            )) |_| continue;
            const spec_id = try self.addNestedSpecRecord(
                spec.nested,
                spec.method_scope,
                evidence,
                program_span,
                capture_abi_digest,
                spec.sealed_codec_contract,
                fn_ty,
                digest,
                fn_id,
            );
            try self.lowered_nested_by_fn.put(fn_id, spec_id);
            try self.markNestedFnReady(fn_id, fn_ty);
        }
    }

    fn verifyDraftTemplateSpecsResolved(body_draft: *const BodyDraftStore) void {
        for (body_draft.sealed_template_specs.items) |spec| {
            switch (spec.state) {
                .resolved => {},
                .lowered => {
                    if (spec.local_context_dependent and spec.def_id != null) {
                        Common.invariant("lexically dependent procedure body became a top-level definition");
                    }
                    if (!spec.local_context_dependent and spec.def_id == null) {
                        Common.invariant("eager context-free procedure body had no top-level definition");
                    }
                },
                .deferred => Common.invariant("deferred template specialization reached commit before resolution"),
                .lowering => Common.invariant("caller-owned template specialization reached commit before its body lowered"),
            }
        }
    }

    fn moduleForConstFnDef(self: *Builder, fn_def: anytype) ModuleView {
        return switch (fn_def) {
            // A default-root-qualified nested function's site lives in the
            // DECLARING module (resolved by content identity, like every
            // defaults-machinery lookup); a template-owned site lives in its
            // owner template's module.
            .nested => |nested| if (nested.default_root) |identity|
                self.moduleForIdentityHash(&identity.bytes) orelse
                    Common.invariant("stored default-root function's declaring module was not present in the lowering input")
            else
                self.moduleForDigest(names.procTemplateModuleDigest(nested.owner)),
            inline .parser_runtime, .encoder_for_runtime => |runtime| self.moduleForDigest(names.procTemplateModuleDigest(runtime.owner)),
            .local_template,
            .imported_template,
            .checked_generated,
            => |template| self.moduleForDigest(names.procTemplateModuleDigest(template)),
            .local_hosted,
            .imported_hosted,
            => |hosted| self.moduleForDigest(names.procTemplateModuleDigest(hostedTemplate(hosted))),
        };
    }

    fn constFnTemplateToMono(
        self: *Builder,
        fn_value: anytype,
        mono_fn_ty: Type.TypeId,
        retain_program_evidence: bool,
    ) Allocator.Error!Ast.FnTemplate {
        return .{
            .fn_def = try self.constFnDefToMono(fn_value.fn_def),
            .source_fn_ty = fn_value.source_fn_ty,
            .source_fn_key = fn_value.source_fn_key,
            .mono_fn_ty = mono_fn_ty,
            .const_evidence = if (retain_program_evidence) try self.program.addConstFnEvidence(fn_value.evidence) else .empty(),
            .const_evidence_frames = if (retain_program_evidence) try self.program.addConstFnEvidenceFrames(fn_value.evidence_frames) else .empty(),
            .const_evidence_frame_head = if (retain_program_evidence) fn_value.evidence_frame_head else null,
        };
    }

    fn restoredConstFnTemplateToMono(
        self: *Builder,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        fn_value: check.ConstStore.ConstFn,
        mono_fn_ty: Type.TypeId,
        retain_program_evidence: bool,
    ) Allocator.Error!Ast.FnTemplate {
        var template = try self.constFnTemplateToMono(fn_value, mono_fn_ty, retain_program_evidence);
        if (fn_value.captures.len == 0) return template;

        switch (template.fn_def) {
            .nested => |nested| {
                template.fn_def = .{ .nested = .{
                    .owner = nested.owner,
                    .site = nested.site,
                    .default_root = nested.default_root,
                    .context_fn_key = restoredConstFnContextKey(store_view.key, fn_id, fn_value.source_fn_key),
                    .local_proc_context_digest = nested.local_proc_context_digest,
                } };
            },
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => Common.invariant("capturing stored function had no nested function identity"),
        }
        return template;
    }

    fn constFnDefToMono(self: *Builder, fn_def: anytype) Allocator.Error!Ast.FnDef {
        return switch (fn_def) {
            .local_template => |template| .{ .local_template = template },
            .imported_template => |template| .{ .imported_template = template },
            .nested => |nested| .{ .nested = .{
                .owner = nested.owner,
                .site = nested.site,
                .default_root = nested.default_root,
                .context_fn_key = nested.context_fn_key,
                .local_proc_context_digest = nested.local_proc_context_digest,
            } },
            .local_hosted => |template| self.fnDefForHostedTemplate(template, true),
            .imported_hosted => |template| self.fnDefForHostedTemplate(template, false),
            .checked_generated => |template| .{ .checked_generated = template },
            .parser_runtime => |runtime| .{ .parser_runtime = .{
                .owner = runtime.owner,
                .expr = runtime.expr,
            } },
            .encoder_for_runtime => |runtime| .{ .encoder_for_runtime = .{
                .owner = runtime.owner,
                .expr = runtime.expr,
            } },
        };
    }

    const RestoredConstSourceCapture = struct {
        binder: checked.PatternBinderId,
        previous: ?DraftLocalId,
        previous_typed: ?DraftLocalId,
        local: DraftLocalId,
        ty: Type.TypeId,
        value: DraftExprId,
    };

    fn bindConstSourceCaptures(
        self: *Builder,
        fn_ctx: *BodyContext,
        store_view: ModuleView,
        fn_view: ModuleView,
        fn_value: check.ConstStore.ConstFn,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!std.ArrayList(RestoredConstSourceCapture) {
        var capture_count: usize = 0;
        for (fn_value.captures) |capture| {
            if (capture.id.isCanonical()) capture_count += 1;
        }

        var out = std.ArrayList(RestoredConstSourceCapture).empty;
        errdefer self.releaseConstSourceCaptures(fn_ctx, &out);
        try out.ensureTotalCapacity(self.allocator, capture_count);

        for (fn_value.captures) |capture| {
            if (!capture.id.isCanonical()) continue;
            const binder = capture.id.binder();
            const lowered_ty = try fn_ctx.lowerConstCaptureType(store_view, capture.ty);
            const local = try fn_ctx.addFreshLocalWithBinder(self.symbols.fresh(), lowered_ty, binder);
            try fn_ctx.bindLocalName(local, binder);
            const previous = fn_ctx.binders.get(binder);
            try fn_ctx.binders.put(binder, local);
            errdefer fn_ctx.restoreBinder(binder, previous);
            const previous_typed = try fn_ctx.putTypedBinder(binder, lowered_ty, local);
            out.appendAssumeCapacity(.{
                .binder = binder,
                .previous = previous,
                .previous_typed = previous_typed,
                .local = local,
                .ty = lowered_ty,
                .value = undefined,
            });
        }

        var out_index: usize = 0;
        for (fn_value.captures) |capture| {
            if (!capture.id.isCanonical()) continue;
            out.items[out_index].value = if (static_data_const_locator) |const_locator|
                try fn_ctx.restoredStaticDataCandidateNode(store_view, fn_view, capture.value, out.items[out_index].ty, const_locator, checkedBinderType(fn_view, capture.id.binder()), .allow)
            else
                try fn_ctx.restoreConstNodeAtType(store_view, fn_view, capture.value, out.items[out_index].ty);
            out_index += 1;
        }

        return out;
    }

    fn releaseConstSourceCaptures(
        self: *Builder,
        fn_ctx: *BodyContext,
        captures: *std.ArrayList(RestoredConstSourceCapture),
    ) void {
        fn_ctx.unbindConstCaptures(captures.items);
        captures.deinit(self.allocator);
    }

    fn wrapConstSourceCaptureLets(
        self: *Builder,
        fn_ctx: *BodyContext,
        captures: []const RestoredConstSourceCapture,
        expr: DraftExprId,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const order = try self.captureLetOrder(fn_ctx, captures);
        defer self.allocator.free(order);

        var result = expr;
        var index = order.len;
        while (index > 0) {
            index -= 1;
            const capture = captures[order[index]];
            result = try fn_ctx.wrapLet(capture.local, capture.ty, capture.value, result, ty);
        }
        return result;
    }

    fn wrapConstSourceCaptureLetsAtTypeCell(
        self: *Builder,
        fn_ctx: *BodyContext,
        captures: []const RestoredConstSourceCapture,
        expr: DraftExprId,
        ty: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        const order = try self.captureLetOrder(fn_ctx, captures);
        defer self.allocator.free(order);

        var result = expr;
        var index = order.len;
        while (index > 0) {
            index -= 1;
            const capture = captures[order[index]];
            result = try fn_ctx.wrapLetAtTypeCell(
                capture.local,
                try fn_ctx.draftTypeCell(capture.ty),
                capture.value,
                result,
                ty,
            );
        }
        return result;
    }

    fn captureLetOrder(self: *Builder, fn_ctx: *BodyContext, captures: anytype) Allocator.Error![]usize {
        const len = captures.len;
        const order = try self.allocator.alloc(usize, len);
        errdefer self.allocator.free(order);
        const visiting = try self.allocator.alloc(bool, len);
        defer self.allocator.free(visiting);
        const visited = try self.allocator.alloc(bool, len);
        defer self.allocator.free(visited);
        @memset(visiting, false);
        @memset(visited, false);

        var order_count: usize = 0;
        for (0..len) |index| {
            try self.appendCaptureLetOrder(fn_ctx, captures, index, visiting, visited, order, &order_count);
        }
        return order;
    }

    fn appendCaptureLetOrder(
        self: *Builder,
        fn_ctx: *BodyContext,
        captures: anytype,
        index: usize,
        visiting: []bool,
        visited: []bool,
        order: []usize,
        order_count: *usize,
    ) Allocator.Error!void {
        // Each frame is a capture whose dependencies are being ordered and
        // the next capture to test as one of them.
        const Frame = struct { index: usize, next_dep: usize };
        var frames = std.ArrayList(Frame).empty;
        defer frames.deinit(self.allocator);
        if (visited[index]) return;
        if (visiting[index]) {
            Common.invariant("ConstStore capture values formed a recursive value dependency");
        }
        visiting[index] = true;
        try frames.append(self.allocator, .{ .index = index, .next_dep = 0 });
        while (frames.items.len != 0) {
            const frame = &frames.items[frames.items.len - 1];
            if (frame.next_dep == captures.len) {
                const finished = frames.pop().?;
                visiting[finished.index] = false;
                visited[finished.index] = true;
                order[order_count.*] = finished.index;
                order_count.* += 1;
                continue;
            }
            const dep_index = frame.next_dep;
            frame.next_dep += 1;
            if (dep_index == frame.index) continue;
            if (!try fn_ctx.exprDependsOnFreeLocal(captures[frame.index].value, captures[dep_index].local)) continue;
            if (visited[dep_index]) continue;
            if (visiting[dep_index]) {
                Common.invariant("ConstStore capture values formed a recursive value dependency");
            }
            visiting[dep_index] = true;
            try frames.append(self.allocator, .{ .index = dep_index, .next_dep = 0 });
        }
    }

    fn restoreConstFnExpr(
        self: *Builder,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!Ast.ExprId {
        const raw = @backingInt(fn_id);
        if (raw >= store_view.const_store.fns.items.len) Common.invariant("ConstStore function id is out of range");
        const fn_value = store_view.const_store.getFn(@fromBackingInt(@intCast(raw)));
        if (fn_value.fn_def == .parser_runtime) {
            return try self.restoreConstParserRuntimeFnExpr(store_view, fn_id, fn_value, ty, static_data_const_locator);
        }
        if (fn_value.fn_def == .encoder_for_runtime) {
            return try self.restoreConstEncoderForRuntimeFnExpr(store_view, fn_id, fn_value, ty, static_data_const_locator);
        }
        if (fn_value.captures.len == 0) {
            const template = try self.restoredConstFnTemplateToMono(store_view, fn_id, fn_value, ty, true);
            const mono_fn_id = try self.lowerRestoredConstFnTemplate(template, fn_value);
            return try self.program.addExpr(.{
                .ty = self.program.fnSource(mono_fn_id).mono_fn_ty,
                .data = .{ .fn_def = .{ .fn_id = mono_fn_id } },
            });
        }

        const fn_view = self.moduleForConstFnDef(fn_value.fn_def);
        const graph = try self.createGraph();
        defer graph.destroy();
        const saved_graph = self.active_graph;
        const saved_body_draft = self.active_body_draft;
        self.active_graph = graph;
        defer self.active_graph = saved_graph;
        var body_draft = BodyDraftStore.init(self.allocator);
        self.active_body_draft = &body_draft;
        defer self.active_body_draft = saved_body_draft;
        defer body_draft.deinit();
        var fn_ctx = try BodyContext.init(self.allocator, self, fn_view, ownerTemplateForConstFnDef(fn_value.fn_def), graph, &body_draft);
        defer fn_ctx.deinit();
        fn_ctx.in_default_expr = constFnDefIsDefaultRoot(fn_value.fn_def);
        fn_ctx.evidence = try fn_ctx.materializeConstFnEvidence(fn_value);
        try fn_ctx.replayStoredEvidenceRelations(fn_ctx.evidence);
        fn_ctx.current_fn_key = switch (fn_value.fn_def) {
            .nested => |nested| nested.context_fn_key,
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => Common.invariant("capturing stored function had no nested function identity"),
        };
        try fn_ctx.constrainTypeToMono(fn_value.source_fn_ty, ty);
        const draft = FinalBodyOutputGuard.begin(self);

        const lambda_expr_id = checkedLambdaExprIdForConstFn(fn_view, fn_value.fn_def);
        const lambda_expr = fn_view.bodies.expr(lambda_expr_id);
        const captures = try self.allocator.alloc(struct {
            binder: checked.PatternBinderId,
            local: DraftLocalId,
            previous: ?DraftLocalId,
            previous_typed: ?DraftLocalId,
            ty: Type.TypeId,
            value: DraftExprId,
        }, fn_value.captures.len);
        defer self.allocator.free(captures);
        var initialized: usize = 0;
        defer fn_ctx.unbindConstCaptures(captures[0..initialized]);

        for (fn_value.captures, 0..) |capture, index| {
            const binder = constCaptureBinder(capture.id);
            const lowered_ty = try fn_ctx.lowerConstCaptureType(store_view, capture.ty);
            const capture_cell = try fn_ctx.draftTypeCell(lowered_ty);
            const local = try fn_ctx.addFreshLocalWithBinderCell(self.symbols.fresh(), capture_cell, binder);
            try fn_ctx.bindLocalName(local, binder);
            const previous = fn_ctx.binders.get(binder);
            try fn_ctx.binders.put(binder, local);
            errdefer fn_ctx.restoreBinder(binder, previous);
            const previous_typed = try fn_ctx.putTypedBinder(binder, lowered_ty, local);
            captures[index] = .{
                .binder = binder,
                .local = local,
                .previous = previous,
                .previous_typed = previous_typed,
                .ty = lowered_ty,
                .value = undefined,
            };
            initialized += 1;
        }
        for (fn_value.captures, 0..) |capture, index| {
            captures[index].value = if (static_data_const_locator) |const_locator|
                try fn_ctx.restoredStaticDataCandidateNode(store_view, fn_view, capture.value, captures[index].ty, const_locator, checkedBinderType(fn_view, constCaptureBinder(capture.id)), .allow)
            else
                try fn_ctx.restoreConstNodeAtType(store_view, fn_view, capture.value, captures[index].ty);
        }
        const template = try self.constFnTemplateToMono(fn_value, ty, true);
        const nested = switch (template.fn_def) {
            .nested => |nested| nested,
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => Common.invariant("capturing stored function had no nested function identity"),
        };
        const restored_local_proc_entries = try fn_ctx.enterRestoredLocalProcScope(nested, fn_ctx.current_fn_key);
        defer if (restored_local_proc_entries) |entries| fn_ctx.allocator.free(entries);

        const capture_values = try self.allocator.alloc(DraftFnDefCapture, captures.len);
        defer self.allocator.free(capture_values);
        const request_fn_node = try fn_ctx.activeNodeFromType(ty);
        const capture_entry_guards = try self.allocator.alloc(NodeId, captures.len);
        defer self.allocator.free(capture_entry_guards);
        for (captures, capture_entry_guards) |capture, *node|
            node.* = try fn_ctx.activeNodeFromType(capture.ty);
        if (lambda_expr.data != .lambda) Common.invariant("stored capturing function did not reference a checked lambda");
        const restored_fn = try self.lowerDraftNestedFromContext(
            &fn_ctx,
            fn_ctx.draft.current_owner,
            lambda_expr_id,
            nested,
            template.source_fn_ty,
            template.source_fn_key,
            request_fn_node,
            capture_entry_guards,
            fn_ctx.evidence,
            null,
            false,
            .exact_graph,
            .inherit,
        );

        for (captures, 0..) |capture, index| {
            capture_values[index] = .{ .id = fn_ctx.captureKey(capture.local), .value = capture.value };
        }

        const expr = try fn_ctx.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(request_fn_node),
            .{ .fn_def = .{
                .fn_id = restored_fn,
                .captures = try fn_ctx.addFnDefCaptureSpan(capture_values),
            } },
        );
        const draft_end = draft.end(self);
        const sealed = try self.sealActiveBodyDraft(graph, &body_draft, draft, draft_end, null, &.{}, null, null, null);
        defer sealed.deinit(self.allocator);
        return sealed.ids.expr(expr);
    }

    fn restoreConstParserRuntimeFnExpr(
        self: *Builder,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        fn_value: check.ConstStore.ConstFn,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!Ast.ExprId {
        const runtime = switch (fn_value.fn_def) {
            .parser_runtime => |runtime| runtime,
            .local_template, .imported_template, .nested, .local_hosted, .imported_hosted, .checked_generated, .encoder_for_runtime => Common.invariant("non-parser function reached parser runtime restore"),
        };
        const fn_view = self.moduleForDigest(names.procTemplateModuleDigest(runtime.owner));
        const graph = try self.createGraph();
        defer graph.destroy();
        const saved_graph = self.active_graph;
        const saved_body_draft = self.active_body_draft;
        self.active_graph = graph;
        defer self.active_graph = saved_graph;

        var body_draft = BodyDraftStore.init(self.allocator);
        self.active_body_draft = &body_draft;
        defer self.active_body_draft = saved_body_draft;
        defer body_draft.deinit();
        var fn_ctx = try BodyContext.init(self.allocator, self, fn_view, runtime.owner, graph, &body_draft);
        defer fn_ctx.deinit();
        fn_ctx.current_fn_key = restoredConstFnContextKey(store_view.key, fn_id, fn_value.source_fn_key);

        var source_captures = try self.bindConstSourceCaptures(&fn_ctx, store_view, fn_view, fn_value, static_data_const_locator);
        defer self.releaseConstSourceCaptures(&fn_ctx, &source_captures);

        const expr = fn_view.bodies.expr(runtime.expr);
        const plan = dispatchPlanForRuntimeExpr(fn_view, runtime.expr);
        try fn_ctx.restoreGeneratedRuntimeEvidence(fn_value, plan);
        const callable_plan = fn_ctx.requireStoredRuntimeCallableDispatchPlan(plan);
        const plan_args = callable_plan.operands;
        const callable_node = try fn_ctx.instantiateCallableDispatchPlanCallNodeFromCaller(callable_plan, &fn_ctx, expr.ty, ty);
        const callable_mono_ty = try fn_ctx.resolvedTypeViewForNode(callable_node);
        const fn_data = self.functionShape(callable_mono_ty, "stored parser constructor had a non-function type");
        const arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.activeTypeStore().span(fn_data.args));
        defer self.allocator.free(arg_tys);
        if (arg_tys.len != 1) Common.invariant("stored parser constructor had an unexpected arity");
        if (!fn_ctx.sameType(fn_data.ret, ty)) Common.invariant("stored parser constructor result type differed from restored function type");

        const runtime_fn = self.functionShape(ty, "stored parser runtime value had a non-function type");
        const runtime_arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.activeTypeStore().span(runtime_fn.args));
        defer self.allocator.free(runtime_arg_tys);
        if (runtime_arg_tys.len != 1) Common.invariant("stored parser runtime function had an unexpected arity");

        const draft = FinalBodyOutputGuard.begin(self);
        const shape_node = try fn_ctx.instNode(plan.dispatcher_ty);
        try fn_ctx.activateCodecContractForPlan(plan, callable_node, shape_node);
        const shape_ty = try fn_ctx.resolvedTypeViewForNode(shape_node);
        const state_local = try fn_ctx.addLocal(self.symbols.fresh(), runtime_arg_tys[0]);
        const state_expr = try fn_ctx.localExpr(state_local, runtime_arg_tys[0]);

        var encoding_let: ?struct {
            local: DraftLocalId,
            value: DraftExprId,
        } = null;
        const encoding_expr = if (constGeneratedCaptureNode(fn_value, parserEncodingCaptureId())) |node| blk: {
            const local = try fn_ctx.addLocal(self.symbols.fresh(), arg_tys[0]);
            fn_ctx.setLocalCaptureId(local, parserEncodingCaptureId());
            encoding_let = .{
                .local = local,
                .value = if (static_data_const_locator) |const_locator|
                    try fn_ctx.restoreConstNodeAtTypeWithStaticRoot(store_view, fn_view, node, arg_tys[0], const_locator)
                else
                    try fn_ctx.restoreConstNodeAtType(store_view, fn_view, node, arg_tys[0]),
            };
            break :blk try fn_ctx.localExpr(local, arg_tys[0]);
        } else try fn_ctx.lowerDispatchOperandAtType(plan_args[0], arg_tys[0]);

        const str_ty = try self.primitiveType(.str);
        var precomputed_plan = BodyContext.ParserPrecomputedPlan.init(self.allocator);
        defer precomputed_plan.deinit();
        try fn_ctx.buildParserRestoredPrecomputedPlan(&precomputed_plan, fn_value, store_view, fn_view, shape_ty, str_ty);

        const parsed = blk: {
            var capture_tys = std.ArrayList(Type.TypeId).empty;
            defer capture_tys.deinit(self.allocator);
            if (encoding_let != null) try capture_tys.append(self.allocator, arg_tys[0]);
            for (precomputed_plan.captures.items) |_| try capture_tys.append(self.allocator, str_ty);
            const demand_scope = try fn_ctx.enterCallableBodyDemandScope(&.{runtime_arg_tys[0]}, capture_tys.items);
            defer demand_scope.leave();
            break :blk try fn_ctx.lowerParseResultFromState(
                shape_ty,
                encoding_expr,
                arg_tys[0],
                state_expr,
                runtime_arg_tys[0],
                runtime_fn.ret,
                &precomputed_plan,
            );
        };
        const runtime_fn_id = try self.program.addFn(.{
            .fn_def = .{ .parser_runtime = .{
                .owner = runtime.owner,
                .expr = runtime.expr,
            } },
            .source_fn_ty = fn_value.source_fn_ty,
            .source_fn_key = fn_value.source_fn_key,
            .mono_fn_ty = ty,
            .evidence_digest = Ast.fnEvidenceDigest(&.{}, &.{}, null),
        });
        var parser_expr = try fn_ctx.addExpr(.{ .ty = ty, .data = .{ .lambda = .{
            .fn_id = draftFinalFn(runtime_fn_id),
            .args = try fn_ctx.addTypedLocalSpan(&.{
                .{ .local = state_local, .ty = runtime_arg_tys[0] },
            }),
            .body = parsed,
        } } });
        var capture_index = precomputed_plan.captures.items.len;
        while (capture_index > 0) {
            capture_index -= 1;
            const capture = precomputed_plan.captures.items[capture_index];
            parser_expr = try fn_ctx.wrapLet(capture.local, str_ty, capture.value, parser_expr, ty);
        }
        if (encoding_let) |let_| {
            parser_expr = try fn_ctx.wrapLet(let_.local, arg_tys[0], let_.value, parser_expr, ty);
        }
        parser_expr = try self.wrapConstSourceCaptureLets(&fn_ctx, source_captures.items, parser_expr, ty);

        const draft_end = draft.end(self);
        const sealed = try self.sealActiveBodyDraft(graph, &body_draft, draft, draft_end, null, &.{}, null, null, null);
        defer sealed.deinit(self.allocator);
        return sealed.ids.expr(parser_expr);
    }

    fn restoreConstEncoderForRuntimeFnExpr(
        self: *Builder,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        fn_value: check.ConstStore.ConstFn,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!Ast.ExprId {
        const runtime = switch (fn_value.fn_def) {
            .encoder_for_runtime => |runtime| runtime,
            .local_template, .imported_template, .nested, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime => Common.invariant("non-encoder_for function reached encoder_for runtime restore"),
        };
        const fn_view = self.moduleForDigest(names.procTemplateModuleDigest(runtime.owner));
        const graph = try self.createGraph();
        defer graph.destroy();
        const saved_graph = self.active_graph;
        const saved_body_draft = self.active_body_draft;
        self.active_graph = graph;
        defer self.active_graph = saved_graph;

        var body_draft = BodyDraftStore.init(self.allocator);
        self.active_body_draft = &body_draft;
        defer self.active_body_draft = saved_body_draft;
        defer body_draft.deinit();
        var fn_ctx = try BodyContext.init(self.allocator, self, fn_view, runtime.owner, graph, &body_draft);
        defer fn_ctx.deinit();
        fn_ctx.current_fn_key = restoredConstFnContextKey(store_view.key, fn_id, fn_value.source_fn_key);

        var source_captures = try self.bindConstSourceCaptures(&fn_ctx, store_view, fn_view, fn_value, static_data_const_locator);
        defer self.releaseConstSourceCaptures(&fn_ctx, &source_captures);

        const expr = fn_view.bodies.expr(runtime.expr);
        const plan = dispatchPlanForRuntimeExpr(fn_view, runtime.expr);
        try fn_ctx.restoreGeneratedRuntimeEvidence(fn_value, plan);
        const callable_plan = fn_ctx.requireStoredRuntimeCallableDispatchPlan(plan);
        const plan_args = callable_plan.operands;
        const callable_node = try fn_ctx.instantiateCallableDispatchPlanCallNodeFromCaller(callable_plan, &fn_ctx, expr.ty, ty);
        const callable_mono_ty = try fn_ctx.resolvedTypeViewForNode(callable_node);
        const fn_data = self.functionShape(callable_mono_ty, "stored encoder_for constructor had a non-function type");
        const arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.activeTypeStore().span(fn_data.args));
        defer self.allocator.free(arg_tys);
        if (arg_tys.len != 1) Common.invariant("stored encoder_for constructor had an unexpected arity");
        if (!fn_ctx.sameType(fn_data.ret, ty)) Common.invariant("stored encoder_for constructor result type differed from restored function type");

        const runtime_fn = self.functionShape(ty, "stored encoder_for runtime value had a non-function type");
        const runtime_arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.activeTypeStore().span(runtime_fn.args));
        defer self.allocator.free(runtime_arg_tys);
        if (runtime_arg_tys.len != 2) Common.invariant("stored encoder_for runtime function had an unexpected arity");

        const draft = FinalBodyOutputGuard.begin(self);
        const shape_node = try fn_ctx.instNode(plan.dispatcher_ty);
        try fn_ctx.activateCodecContractForPlan(plan, callable_node, shape_node);
        const shape_ty = try fn_ctx.resolvedTypeViewForNode(shape_node);
        const value_local = try fn_ctx.addLocal(self.symbols.fresh(), runtime_arg_tys[0]);
        const value_expr = try fn_ctx.localExpr(value_local, runtime_arg_tys[0]);
        const state_local = try fn_ctx.addLocal(self.symbols.fresh(), runtime_arg_tys[1]);
        const state_expr = try fn_ctx.localExpr(state_local, runtime_arg_tys[1]);

        var encoding_let: ?struct {
            local: DraftLocalId,
            value: DraftExprId,
        } = null;
        const encoding_expr = if (constGeneratedCaptureNode(fn_value, encoderForEncodingCaptureId())) |node| blk: {
            const local = try fn_ctx.addLocal(self.symbols.fresh(), arg_tys[0]);
            fn_ctx.setLocalCaptureId(local, encoderForEncodingCaptureId());
            encoding_let = .{
                .local = local,
                .value = if (static_data_const_locator) |const_locator|
                    try fn_ctx.restoreConstNodeAtTypeWithStaticRoot(store_view, fn_view, node, arg_tys[0], const_locator)
                else
                    try fn_ctx.restoreConstNodeAtType(store_view, fn_view, node, arg_tys[0]),
            };
            break :blk try fn_ctx.localExpr(local, arg_tys[0]);
        } else try fn_ctx.lowerDispatchOperandAtType(plan_args[0], arg_tys[0]);

        const str_ty = try self.primitiveType(.str);
        var precomputed_plan = BodyContext.ParserPrecomputedPlan.init(self.allocator);
        defer precomputed_plan.deinit();
        precomputed_plan.next_capture_id = encoderForFirstFieldCaptureId();
        try fn_ctx.buildEncodeRestoredPrecomputedPlan(&precomputed_plan, fn_value, store_view, fn_view, shape_ty, arg_tys[0], str_ty);

        const saved_encoder_source_fn_ty = fn_ctx.generated_encoder_source_fn_ty;
        const saved_encoder_source_expr = fn_ctx.generated_encoder_source_expr;
        const saved_encoder_lambda_index = fn_ctx.generated_encoder_lambda_index;
        fn_ctx.generated_encoder_source_fn_ty = fn_value.source_fn_ty;
        fn_ctx.generated_encoder_source_expr = runtime.expr;
        fn_ctx.generated_encoder_lambda_index = 0;
        defer {
            fn_ctx.generated_encoder_source_fn_ty = saved_encoder_source_fn_ty;
            fn_ctx.generated_encoder_source_expr = saved_encoder_source_expr;
            fn_ctx.generated_encoder_lambda_index = saved_encoder_lambda_index;
        }

        const encoded = blk: {
            var capture_tys = std.ArrayList(Type.TypeId).empty;
            defer capture_tys.deinit(self.allocator);
            if (encoding_let != null) try capture_tys.append(self.allocator, arg_tys[0]);
            for (precomputed_plan.captures.items) |_| try capture_tys.append(self.allocator, str_ty);
            const demand_scope = try fn_ctx.enterCallableBodyDemandScope(runtime_arg_tys, capture_tys.items);
            defer demand_scope.leave();
            break :blk try fn_ctx.lowerEncodeShapeToState(
                shape_ty,
                value_expr,
                encoding_expr,
                arg_tys[0],
                state_expr,
                runtime_arg_tys[1],
                runtime_fn.ret,
                &precomputed_plan,
            );
        };
        const runtime_fn_id = try self.program.addFn(.{
            .fn_def = .{ .encoder_for_runtime = .{
                .owner = runtime.owner,
                .expr = runtime.expr,
            } },
            .source_fn_ty = fn_value.source_fn_ty,
            .source_fn_key = fn_value.source_fn_key,
            .mono_fn_ty = ty,
            .evidence_digest = Ast.fnEvidenceDigest(&.{}, &.{}, null),
        });
        var encoder_expr = try fn_ctx.addExpr(.{ .ty = ty, .data = .{ .lambda = .{
            .fn_id = draftFinalFn(runtime_fn_id),
            .args = try fn_ctx.addTypedLocalSpan(&.{
                .{ .local = value_local, .ty = runtime_arg_tys[0] },
                .{ .local = state_local, .ty = runtime_arg_tys[1] },
            }),
            .body = encoded,
        } } });
        var capture_index = precomputed_plan.captures.items.len;
        while (capture_index > 0) {
            capture_index -= 1;
            const capture = precomputed_plan.captures.items[capture_index];
            encoder_expr = try fn_ctx.wrapLet(capture.local, str_ty, capture.value, encoder_expr, ty);
        }
        if (encoding_let) |let_| {
            encoder_expr = try fn_ctx.wrapLet(let_.local, arg_tys[0], let_.value, encoder_expr, ty);
        }
        encoder_expr = try self.wrapConstSourceCaptureLets(&fn_ctx, source_captures.items, encoder_expr, ty);

        const draft_end = draft.end(self);
        const sealed = try self.sealActiveBodyDraft(graph, &body_draft, draft, draft_end, null, &.{}, null, null, null);
        defer sealed.deinit(self.allocator);
        return sealed.ids.expr(encoder_expr);
    }

    fn restoreConstNodeAtType(
        self: *Builder,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        ty: Type.TypeId,
    ) Allocator.Error!Ast.ExprId {
        return try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, node, ty, null);
    }

    fn restoreConstNodeAtTypeWithStaticRoot(
        self: *Builder,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!Ast.ExprId {
        return try runConstRestore(self, store_view, type_view, node, ty, static_data_const_locator);
    }

    fn constExprAddress(store_view: ModuleView, type_view: ModuleView, node: checked.ConstNodeId, ty: Type.TypeId) ConstExprAddress {
        return .{
            .store_module_bytes = store_view.key.bytes,
            .type_module_bytes = type_view.key.bytes,
            .node = @backingInt(node),
            .mono_ty = @backingInt(ty),
        };
    }

    fn startConstRestore(
        self: *Builder,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!ConstRestoreStart(Ast.ExprId) {
        const address = constExprAddress(store_view, type_view, node, ty);
        if (static_data_const_locator == null) {
            if (self.const_expr_cache.get(address)) |existing| return .{ .done = existing };
        }

        const value = store_view.const_store.get(node);
        switch (value) {
            .fn_value => |fn_id| {
                const expr = try self.restoreConstFnExpr(store_view, fn_id, ty, static_data_const_locator);
                if (static_data_const_locator == null) try self.const_expr_cache.put(address, expr);
                return .{ .done = expr };
            },
            .tag, .record, .tuple => if (self.nominalConstructionLayer(ty)) |layer| {
                return .{ .layer = .{ .child = node, .backing = layer.backing, .named = layer.named } };
            },
            .nominal => |nominal| if (self.nominalConstructionLayer(ty)) |layer| {
                return .{ .layer = .{ .child = nominal.backing, .backing = layer.backing, .named = layer.named } };
            },
            .pending, .zst, .scalar, .str, .list, .box, .crash, .checked_error => {},
        }
        return .{ .value = value };
    }

    fn finishConstRestoreLayer(
        self: *Builder,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        ty: Type.TypeId,
        named: Type.TypeId,
        backing_expr: Ast.ExprId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!Ast.ExprId {
        const expr = try self.program.addExpr(.{ .ty = named, .data = .{ .nominal = backing_expr } });
        if (static_data_const_locator == null) try self.const_expr_cache.put(constExprAddress(store_view, type_view, node, ty), expr);
        return expr;
    }

    fn finishConstRestoreData(
        self: *Builder,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        ty: Type.TypeId,
        data: Ast.ExprData,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!Ast.ExprId {
        const expr = try self.program.addExpr(.{ .ty = ty, .data = data });
        if (static_data_const_locator == null) try self.const_expr_cache.put(constExprAddress(store_view, type_view, node, ty), expr);
        return expr;
    }

    fn constListElemType(self: *Builder, ty: Type.TypeId) Type.TypeId {
        return switch (self.shapeContent(ty)) {
            .list => |elem| elem,
            .primitive, .named, .record, .tuple, .tag_union, .box, .func, .erased, .zst => Common.invariant("ConstStore list restored with a non-list monotype"),
        };
    }

    fn constBoxPayloadType(self: *Builder, ty: Type.TypeId) Type.TypeId {
        return switch (self.shapeContent(ty)) {
            .box => |payload| payload,
            .primitive, .named, .record, .tuple, .tag_union, .list, .func, .erased, .zst => Common.invariant("ConstStore box restored with a non-box monotype"),
        };
    }

    fn constRecordFields(self: *Builder, ty: Type.TypeId) Type.StoreSpanBorrow(Type.Field, "fields") {
        return self.activeTypeStore().fieldSpan(self.recordFieldsSpan(ty));
    }

    fn primitiveType(self: *Builder, primitive: Type.Primitive) Allocator.Error!Type.TypeId {
        const type_store = self.activeTypeStore();
        const name_store = self.activeNameStore();
        const private_destination = self.hasPrivateTypeDestination();
        return switch (primitive) {
            .u64 => blk: {
                if (!private_destination) {
                    if (self.u64_ty) |ty| break :blk ty;
                }
                const ty = try type_store.internPrimitive(name_store, .u64);
                if (!private_destination and !type_store.hasSpeculativeConstruction()) self.u64_ty = ty;
                break :blk ty;
            },
            .bool => blk: {
                if (!private_destination) {
                    if (self.bool_ty) |ty| break :blk ty;
                }
                const ty = try type_store.internPrimitive(name_store, .bool);
                if (!private_destination and !type_store.hasSpeculativeConstruction()) self.bool_ty = ty;
                break :blk ty;
            },
            .str, .u8, .i8, .u16, .i16, .u32, .i32, .i64, .u128, .i128, .f32, .f64, .dec, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2 => try type_store.internPrimitive(name_store, primitive),
        };
    }

    /// Intern a function from children that have already been sealed. This is
    /// used during draft finalization, where the active graph remains present
    /// but the supplied TypeIds are durable rather than active snapshots.
    fn closedFunctionType(self: *Builder, arg_tys: []const Type.TypeId, ret_ty: Type.TypeId) Allocator.Error!Type.TypeId {
        return try self.activeTypeStore().internFunc(self.activeNameStore(), arg_tys, ret_ty);
    }

    fn localExpr(self: *Builder, local: Ast.LocalId, ty: Type.TypeId) Allocator.Error!Ast.ExprId {
        return try self.program.addExpr(.{ .ty = ty, .data = .{ .local = local } });
    }

    fn bindPat(self: *Builder, local: Ast.LocalId, ty: Type.TypeId) Allocator.Error!Ast.PatId {
        return try self.program.addPat(.{ .ty = ty, .data = .{ .bind = local } });
    }

    const HostedTryInfo = struct {
        ok_ty: Type.TypeId,
        err_ty: Type.TypeId,
        ok_tag: Type.Tag,
        err_tag: Type.Tag,
    };

    /// Reserved labels for the optional-slot encoding; see design.md "Field
    /// Kinds". Sorting fixes Missing at index 0 and Present at index 1.
    const optional_slot_missing_tag = "#Missing";
    const optional_slot_present_tag = "#Present";

    /// `Str.inspect`'s non-value marker for a missing optional field.
    const optional_field_missing_render = "<missing>";

    const OptionalSlotInfo = struct {
        payload_ty: Type.TypeId,
        missing_tag: Type.Tag,
        present_tag: Type.Tag,
    };

    /// The direct tag row of a Monotype: transparent alias layers are crossed,
    /// but a nominal (`Builtin.Try` included) is not a bare row, so its
    /// backing's labels are never mistaken for the result row.
    fn bareTagUnionTagsOrNull(self: *Builder, ty: Type.TypeId) ?Type.StoreSpanBorrow(Type.Tag, "tags") {
        var current = ty;
        while (true) {
            switch (self.activeTypeStore().get(current)) {
                .tag_union => |tags| return self.activeTypeStore().tagSpan(tags),
                .named => |named| {
                    if (named.kind != .alias) return null;
                    const backing = named.backing orelse return null;
                    current = backing.ty;
                },
                .primitive, .record, .tuple, .list, .box, .func, .erased, .zst => return null,
            }
        }
    }

    /// Return the exact source type the template is specialized at when a
    /// request widens its declared result-row label set. The source keeps every
    /// requested representation choice (arguments, `Ok` payload, and row
    /// payloads) but contains only the declared labels, so the generated Roc
    /// adapter performs one explicit row injection and no representation
    /// conversion. With a capability the adapted row is the result `Try`'s
    /// error argument—the hosted instance, where the declared row is the
    /// host ABI; without one it is the function's own result row.
    fn resultRowWideningAdapterSourceType(
        self: *Builder,
        capability: ?HostedTryAdapterCapability,
        declared_fn_ty: Type.TypeId,
        requested_fn_ty: Type.TypeId,
    ) Allocator.Error!?Type.TypeId {
        if (try self.sameMonoType(declared_fn_ty, requested_fn_ty)) return null;
        const declared = self.functionShape(declared_fn_ty, "result-row adapter declared type was not a function");
        const requested = self.functionShape(requested_fn_ty, "result-row adapter requested type was not a function");
        if (try self.sameMonoType(declared.ret, requested.ret)) return null;

        const requested_try: ?HostedTryInfo = if (capability) |try_capability|
            (try self.hostedTryInfoOrNull(try_capability, requested.ret)) orelse return null
        else
            null;
        const declared_row_ty = if (capability) |try_capability|
            ((try self.hostedTryInfoOrNull(try_capability, declared.ret)) orelse return null).err_ty
        else
            declared.ret;
        const requested_row_ty = if (requested_try) |info| info.err_ty else requested.ret;

        if (declared.args.len != requested.args.len) {
            Common.invariant("result-row widening request changed arity from the declared type");
        }

        const declared_tags = self.bareTagUnionTagsOrNull(declared_row_ty) orelse return null;
        const requested_tags = self.bareTagUnionTagsOrNull(requested_row_ty) orelse return null;
        if (requested_tags.len < declared_tags.len) {
            Common.invariant("result-row widening request removed a declared label");
        }
        const narrowed_tags = try self.allocator.alloc(Type.Tag, declared_tags.len);
        defer self.allocator.free(narrowed_tags);
        for (0..declared_tags.len) |index| {
            const declared_tag = GuardedList.at(declared_tags, index);
            const requested_tag = self.tagByNameOrNull(requested_row_ty, declared_tag.name) orelse
                Common.invariant("result-row widening request removed a declared label");
            const declared_payloads = self.program.types.span(declared_tag.payloads);
            const requested_payloads = self.program.types.span(requested_tag.payloads);
            if (declared_payloads.len != requested_payloads.len) {
                Common.invariant("result-row widening request changed a declared payload arity");
            }
            narrowed_tags[index] = requested_tag;
        }
        if (requested_tags.len == declared_tags.len) return null;

        const transaction = self.program.types.beginTransaction();
        errdefer transaction.abort(&self.program.types);
        const speculative_row_ty = try self.program.types.add(.{
            .tag_union = try self.program.types.addTagVariants(&self.program.names, narrowed_tags),
        });
        var transaction_result = try self.program.types.commitTransaction(
            &self.program.names,
            transaction,
            speculative_row_ty,
        );
        defer transaction_result.deinit();
        const narrowed_row_ty = transaction_result.root;
        const narrowed_ret_ty = if (capability) |try_capability|
            try self.hostedTryTypeLike(try_capability, requested.ret, requested_try.?.ok_ty, narrowed_row_ty)
        else
            narrowed_row_ty;
        return try self.program.types.internFuncFromSpan(&self.program.names, requested.args, narrowed_ret_ty);
    }

    /// Body of a generated result-row widening adapter: call the template at
    /// its declared row and re-tag the result into the requested row. With a
    /// capability the re-tag unwraps and re-wraps the result `Try`; without one
    /// the function's own result row is injected directly.
    fn resultRowWideningAdapterBody(
        self: *Builder,
        capability: ?HostedTryAdapterCapability,
        args: Ast.Span(Ast.TypedLocal),
        source_fn: Ast.FnId,
        source_fn_ty: Type.TypeId,
        target_fn_ty: Type.TypeId,
    ) Allocator.Error!Ast.ExprId {
        const source = self.functionShape(source_fn_ty, "result-row adapter source type was not a function");
        const target = self.functionShape(target_fn_ty, "result-row adapter target type was not a function");
        const source_args = self.program.types.span(source.args);
        const target_args = self.program.types.span(target.args);
        const adapter_args = self.program.typedLocalSpan(args);
        if (source_args.len != target_args.len or source_args.len != GuardedList.borrowLen(adapter_args)) {
            Common.invariant("result-row widening adapter arity differed from its function types");
        }

        const call_args = try self.allocator.alloc(Ast.ExprId, GuardedList.borrowLen(adapter_args));
        defer self.allocator.free(call_args);
        for (0..GuardedList.borrowLen(adapter_args)) |index| {
            const arg = GuardedList.at(adapter_args, index);
            const source_arg_ty = GuardedList.at(source_args, index);
            const target_arg_ty = GuardedList.at(target_args, index);
            if (!try self.sameMonoType(arg.ty, source_arg_ty) or !try self.sameMonoType(arg.ty, target_arg_ty)) {
                Common.invariant("result-row widening adapter argument type differed from source or target function type");
            }
            call_args[index] = try self.localExpr(arg.local, arg.ty);
        }

        const source_call = try self.program.addExpr(.{
            .ty = source.ret,
            .data = .{ .call_proc = .{
                .callee = Ast.localProcCallee(source_fn),
                .args = try self.program.addExprSpan(call_args),
            } },
        });
        if (capability) |try_capability| {
            return try self.hostedTryReturnInjectionExpr(try_capability, source_call, source.ret, target.ret);
        }
        if (!try self.errorRowIsIncludedIn(source.ret, target.ret)) {
            Common.invariant("result-row adapter source row was not included in target row");
        }
        return try self.tagRowInjectionExpr(source_call, source.ret, target.ret);
    }

    fn hostedTryReturnInjectionExpr(
        self: *Builder,
        capability: HostedTryAdapterCapability,
        source_expr: Ast.ExprId,
        source_try_ty: Type.TypeId,
        target_try_ty: Type.TypeId,
    ) Allocator.Error!Ast.ExprId {
        if (try self.sameMonoType(source_try_ty, target_try_ty)) return source_expr;

        const source_info = try self.hostedTryInfo(capability, source_try_ty);
        const target_info = try self.hostedTryInfo(capability, target_try_ty);
        if (!try self.sameMonoType(source_info.ok_ty, target_info.ok_ty)) {
            Common.invariant("Try adapter changed Ok type");
        }
        if (!try self.errorRowIsIncludedIn(source_info.err_ty, target_info.err_ty)) {
            Common.invariant("Try adapter error row was not included in target row");
        }

        const ok_local = try self.program.addLocal(self.symbols.fresh(), source_info.ok_ty);
        const ok_payload_pat = try self.bindPat(ok_local, source_info.ok_ty);
        const ok_pat = try self.program.addPat(.{ .ty = source_try_ty, .data = .{ .tag = .{
            .name = source_info.ok_tag.name,
            .payloads = try self.program.addPatSpan(&[_]Ast.PatId{ok_payload_pat}),
        } } });
        const ok_value = try self.localExpr(ok_local, source_info.ok_ty);
        const ok_body = try self.hostedTryOkExpr(capability, target_try_ty, ok_value);

        const err_local = try self.program.addLocal(self.symbols.fresh(), source_info.err_ty);
        const err_payload_pat = try self.bindPat(err_local, source_info.err_ty);
        const err_pat = try self.program.addPat(.{ .ty = source_try_ty, .data = .{ .tag = .{
            .name = source_info.err_tag.name,
            .payloads = try self.program.addPatSpan(&[_]Ast.PatId{err_payload_pat}),
        } } });
        const err_value = try self.localExpr(err_local, source_info.err_ty);
        const injected_err = try self.tagRowInjectionExpr(err_value, source_info.err_ty, target_info.err_ty);
        const err_body = try self.hostedTryErrExpr(capability, target_try_ty, injected_err);

        const branches = [_]Ast.Branch{
            .{ .pat = ok_pat, .body = ok_body },
            .{ .pat = err_pat, .body = err_body },
        };
        return try self.program.addExpr(.{ .ty = target_try_ty, .data = .{ .match_ = .{
            .scrutinee = source_expr,
            .branches = try self.program.addBranchSpan(&branches),
        } } });
    }

    /// Re-tag a value of a closed tag row into a row that includes it. Used
    /// for a `Try` result's error row and for a direct result row alike.
    fn tagRowInjectionExpr(
        self: *Builder,
        source_expr: Ast.ExprId,
        source_err_ty: Type.TypeId,
        target_err_ty: Type.TypeId,
    ) Allocator.Error!Ast.ExprId {
        if (try self.sameMonoType(source_err_ty, target_err_ty)) return source_expr;

        const source_tags = self.tagUnionTags(source_err_ty);
        if (source_tags.len == 0) {
            return try self.program.addExpr(.{ .ty = target_err_ty, .data = .{ .match_ = .{
                .scrutinee = source_expr,
                .branches = Ast.Span(Ast.Branch).empty(),
            } } });
        }

        const branches = try self.allocator.alloc(Ast.Branch, source_tags.len);
        defer self.allocator.free(branches);
        for (0..source_tags.len) |index| {
            const source_tag = GuardedList.at(source_tags, index);
            const source_payload_tys = self.program.types.span(source_tag.payloads);
            const target_tag = self.tagByName(target_err_ty, source_tag.name);
            const target_payload_tys = self.program.types.span(target_tag.payloads);
            if (source_payload_tys.len != target_payload_tys.len) {
                Common.invariant("Try adapter error tag payload arity differed in target row");
            }

            const payload_pats = try self.allocator.alloc(Ast.PatId, source_payload_tys.len);
            defer self.allocator.free(payload_pats);
            const payload_exprs = try self.allocator.alloc(Ast.ExprId, source_payload_tys.len);
            defer self.allocator.free(payload_exprs);
            for (0..source_payload_tys.len) |payload_index| {
                const source_payload_ty = GuardedList.at(source_payload_tys, payload_index);
                const target_payload_ty = GuardedList.at(target_payload_tys, payload_index);
                if (!try self.sameMonoType(source_payload_ty, target_payload_ty)) {
                    Common.invariant("Try adapter error tag payload type differed in target row");
                }
                const local = try self.program.addLocal(self.symbols.fresh(), source_payload_ty);
                payload_pats[payload_index] = try self.bindPat(local, source_payload_ty);
                payload_exprs[payload_index] = try self.localExpr(local, source_payload_ty);
            }

            const pat = try self.program.addPat(.{ .ty = source_err_ty, .data = .{ .tag = .{
                .name = source_tag.name,
                .payloads = try self.program.addPatSpan(payload_pats),
            } } });
            const body = try self.tagValueExpr(target_err_ty, target_tag, payload_exprs);
            branches[index] = .{ .pat = pat, .body = body };
        }

        return try self.program.addExpr(.{ .ty = target_err_ty, .data = .{ .match_ = .{
            .scrutinee = source_expr,
            .branches = try self.program.addBranchSpan(branches),
        } } });
    }

    fn hostedTryOkExpr(self: *Builder, capability: HostedTryAdapterCapability, try_ty: Type.TypeId, value_expr: Ast.ExprId) Allocator.Error!Ast.ExprId {
        const info = try self.hostedTryInfo(capability, try_ty);
        return try self.tagValueExpr(try_ty, info.ok_tag, &[_]Ast.ExprId{value_expr});
    }

    fn hostedTryErrExpr(self: *Builder, capability: HostedTryAdapterCapability, try_ty: Type.TypeId, err_expr: Ast.ExprId) Allocator.Error!Ast.ExprId {
        const info = try self.hostedTryInfo(capability, try_ty);
        return try self.tagValueExpr(try_ty, info.err_tag, &[_]Ast.ExprId{err_expr});
    }

    fn tagValueExpr(
        self: *Builder,
        ty: Type.TypeId,
        tag: Type.Tag,
        payloads: []const Ast.ExprId,
    ) Allocator.Error!Ast.ExprId {
        const backing_ty = self.nominalExprBackingType(ty) orelse ty;
        const tag_expr = try self.program.addExpr(.{
            .ty = backing_ty,
            .data = .{ .tag = .{
                .name = tag.name,
                .payloads = try self.program.addExprSpan(payloads),
            } },
        });
        if (self.nominalExprBackingType(ty) != null) {
            return try self.program.addExpr(.{ .ty = ty, .data = .{ .nominal = tag_expr } });
        }
        return tag_expr;
    }

    fn hostedTryInfo(self: *Builder, capability: HostedTryAdapterCapability, try_ty: Type.TypeId) Allocator.Error!HostedTryInfo {
        return (try self.hostedTryInfoOrNull(capability, try_ty)) orelse
            Common.invariant("hosted Try capability did not match its Monotype result");
    }

    /// The hosted `Try` nominal a Monotype names, crossing transparent alias
    /// layers on the way. The checked side already crosses them—`closedResultRowOrNull`
    /// resolves the result payload through aliases—so
    /// a template declared `Res : Try(Str, [NotFound])` carries a capability
    /// and a recorded row widening. Its lowered return is a `.alias` named node
    /// whose backing is the `Try` nominal, so matching only the outermost def
    /// would decline a widening the checker already committed to.
    ///
    /// Reads `self.program.types` rather than `activeTypeStore()`: the adapter
    /// pre-step pins the program store as the destination deliberately.
    fn hostedTryNamedOrNull(
        self: *Builder,
        capability: HostedTryAdapterCapability,
        try_ty: Type.TypeId,
    ) ?Type.NamedContent {
        var current = try_ty;
        // Bounded like the graph-side walk above, and for the same reason: a
        // backing cycle through two or more types hangs the compiler, which no
        // `unreachable` would report in a release build.
        var remaining = self.program.types.typeCount();
        while (remaining > 0) : (remaining -= 1) {
            const named = switch (self.program.types.get(current)) {
                .named => |named| named,
                .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return null,
            };
            if (sameTypeDef(named.def, capability.def)) return named;
            if (named.kind != .alias) return null;
            const backing = named.backing orelse return null;
            current = backing.ty;
        }
        Common.compilerBug("transparent alias backing chain was cyclic");
    }

    fn hostedTryInfoOrNull(self: *Builder, capability: HostedTryAdapterCapability, try_ty: Type.TypeId) Allocator.Error!?HostedTryInfo {
        const named = self.hostedTryNamedOrNull(capability, try_ty) orelse return null;
        if (capability.ok_type_arg_index >= self.program.types.span(named.args).len or
            capability.err_type_arg_index >= self.program.types.span(named.args).len)
        {
            Common.invariant("hosted Try capability referenced a missing Monotype type argument");
        }
        const backing_ty = named.backing orelse Common.invariant("hosted Try nominal had no backing");
        const ok_tag = self.tagByNameOrNull(backing_ty.ty, capability.ok_tag) orelse
            Common.invariant("hosted Try backing omitted its capability-recorded Ok tag");
        const err_tag = self.tagByNameOrNull(backing_ty.ty, capability.err_tag) orelse
            Common.invariant("hosted Try backing omitted its capability-recorded Err tag");
        const ok_payloads = self.program.types.span(ok_tag.payloads);
        const err_payloads = self.program.types.span(err_tag.payloads);
        if (ok_payloads.len != 1 or err_payloads.len != 1) {
            Common.invariant("hosted Try capability tags did not have one payload each");
        }
        const args = self.program.types.span(named.args);
        const ok_ty = GuardedList.at(args, capability.ok_type_arg_index);
        const err_ty = GuardedList.at(args, capability.err_type_arg_index);
        if (!try self.sameMonoType(ok_ty, GuardedList.at(ok_payloads, 0)) or
            !try self.sameMonoType(err_ty, GuardedList.at(err_payloads, 0)))
        {
            Common.invariant("hosted Try capability payload mapping disagreed with its nominal arguments");
        }
        return .{
            .ok_ty = ok_ty,
            .err_ty = err_ty,
            .ok_tag = ok_tag,
            .err_tag = err_tag,
        };
    }

    fn hostedTryTypeLike(
        self: *Builder,
        capability: HostedTryAdapterCapability,
        template_try_ty: Type.TypeId,
        ok_ty: Type.TypeId,
        err_ty: Type.TypeId,
    ) Allocator.Error!Type.TypeId {
        // Crosses alias layers like `hostedTryInfoOrNull`, so an alias-wrapped
        // template `Try` is recognized here too. The rebuilt type is the bare
        // `Try` nominal: this is the adapter's narrowed source row, which is a
        // different row from the one any crossed alias declares.
        const template = self.hostedTryNamedOrNull(capability, template_try_ty) orelse
            Common.invariant("hosted Try capability did not match the adapter template nominal");
        const template_backing = template.backing orelse
            Common.invariant("Try template type had no backing");
        const template_tags = switch (self.shapeContent(template_backing.ty)) {
            .tag_union => |span| self.program.types.tagSpan(span),
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => Common.invariant("Try template backing type was not a tag union"),
        };
        const transaction = self.program.types.beginTransaction();
        errdefer transaction.abort(&self.program.types);
        const tags = try self.allocator.alloc(Type.Tag, template_tags.len);
        defer self.allocator.free(tags);
        var found_ok = false;
        var found_err = false;
        for (0..template_tags.len) |index| {
            const tag = GuardedList.at(template_tags, index);
            const payload_ty = if (tag.name == capability.ok_tag) blk: {
                found_ok = true;
                break :blk ok_ty;
            } else if (tag.name == capability.err_tag) blk: {
                found_err = true;
                break :blk err_ty;
            } else Common.invariant("hosted Try backing contained a tag absent from its capability");
            tags[index] = .{
                .name = tag.name,
                .checked_name = tag.checked_name,
                .payloads = try self.program.types.addSpan(&.{payload_ty}),
            };
        }
        if (!found_ok or !found_err) {
            Common.invariant("Try backing type did not contain Ok and Err tags");
        }
        const backing_ty = try self.program.types.add(.{
            .tag_union = try self.program.types.addTagVariants(&self.program.names, tags),
        });
        const template_args = self.program.types.span(template.args);
        if (capability.ok_type_arg_index >= template_args.len or capability.err_type_arg_index >= template_args.len) {
            Common.invariant("hosted Try capability referenced a missing template type argument");
        }
        const args = try GuardedList.dupe(self.allocator, Type.TypeId, template_args);
        defer self.allocator.free(args);
        args[capability.ok_type_arg_index] = ok_ty;
        args[capability.err_type_arg_index] = err_ty;
        const speculative = try self.program.types.add(.{ .named = .{
            .named_type = template.named_type,
            .def = template.def,
            .kind = template.kind,
            .builtin_owner = template.builtin_owner,
            .args = try self.program.types.addSpan(args),
            .backing = .{
                .ty = backing_ty,
                .use = template_backing.use,
                .authority = template_backing.authority,
            },
            .declared_order = template.declared_order,
        } });
        var result = try self.program.types.commitTransaction(
            &self.program.names,
            transaction,
            speculative,
        );
        defer result.deinit();
        return result.root;
    }

    fn errorRowIsIncludedIn(self: *Builder, source_err_ty: Type.TypeId, target_err_ty: Type.TypeId) Allocator.Error!bool {
        if (try self.sameMonoType(source_err_ty, target_err_ty)) return true;
        const source_tags = self.tagUnionTags(source_err_ty);
        for (0..source_tags.len) |index| {
            const source_tag = GuardedList.at(source_tags, index);
            const target_tag = self.tagByNameOrNull(target_err_ty, source_tag.name) orelse return false;
            const source_payloads = self.program.types.span(source_tag.payloads);
            const target_payloads = self.program.types.span(target_tag.payloads);
            if (source_payloads.len != target_payloads.len) return false;
            for (0..source_payloads.len) |payload_index| {
                const source_payload = GuardedList.at(source_payloads, payload_index);
                const target_payload = GuardedList.at(target_payloads, payload_index);
                if (!try self.sameMonoType(source_payload, target_payload)) return false;
            }
        }
        return true;
    }

    fn tagByName(self: *Builder, ty: Type.TypeId, name: names.TagNameId) Type.Tag {
        return self.tagByNameOrNull(ty, name) orelse Common.invariant("tag operation referenced tag absent from Monotype type");
    }

    fn tagByNameOrNull(self: *Builder, ty: Type.TypeId, name: names.TagNameId) ?Type.Tag {
        const tags = self.tagUnionTags(ty);
        for (0..tags.len) |index| {
            const tag = GuardedList.at(tags, index);
            if (tag.name == name) return tag;
        }
        return null;
    }

    fn tagUnionTags(self: *Builder, ty: Type.TypeId) Type.StoreSpanBorrow(Type.Tag, "tags") {
        return switch (self.shapeContent(ty)) {
            .tag_union => |tags| self.program.types.tagSpan(tags),
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => Common.invariant("tag operation expected tag-union type"),
        };
    }

    fn nominalExprBackingType(self: *Builder, ty: Type.TypeId) ?Type.TypeId {
        return switch (self.program.types.get(ty)) {
            .named => |named| if (named.kind != .alias) blk: {
                const backing = named.backing orelse break :blk null;
                break :blk backing.ty;
            } else null,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => null,
        };
    }

    /// Whether two Monotypes describe the same type. This is the structural
    /// `typeEql` relation rather than a stored-identity digest comparison:
    /// checking may present one unified type both alias-wrapped and unwrapped
    /// (a nominal's type argument can keep an alias name that the backing
    /// row's payload resolved away), and a digest keeps aliases opaque, so
    /// digest equality would report such equal types as different.
    fn sameMonoType(self: *Builder, a: Type.TypeId, b: Type.TypeId) Allocator.Error!bool {
        if (a == b) return true;
        return try self.program.types.typeEql(&self.program.names, a, b);
    }
};

fn optionalFieldSlotForType(
    types_: *Type.Store,
    name_store: *const names.NameStore,
    slot_ty: Type.TypeId,
) ?Builder.OptionalSlotInfo {
    const tags = switch (types_.get(slot_ty)) {
        .tag_union => |span_| types_.tagSpan(span_),
        .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => return null,
    };
    if (tags.len != 2) return null;
    // Tag normalization gives #Missing index 0 and #Present index 1.
    const missing_tag = GuardedList.at(tags, 0);
    const present_tag = GuardedList.at(tags, 1);
    if (!std.mem.eql(u8, name_store.tagLabelText(missing_tag.name), Builder.optional_slot_missing_tag)) return null;
    if (!std.mem.eql(u8, name_store.tagLabelText(present_tag.name), Builder.optional_slot_present_tag)) return null;
    if (types_.span(missing_tag.payloads).len != 0) return null;
    const present_payloads = types_.span(present_tag.payloads);
    if (present_payloads.len != 1) return null;
    return .{
        .payload_ty = GuardedList.at(present_payloads, 0),
        .missing_tag = missing_tag,
        .present_tag = present_tag,
    };
}

const LoweredTemplateBody = struct {
    args: DraftSpan(DraftTypedLocal),
    body: DraftExprId,
    ret: DraftTypeCell,
};

const SealedLoweredTemplateBody = struct {
    args: DraftSpan(DraftTypedLocal),
    body: DraftExprId,
    ret: Type.TypeId,
};

const DraftTypeCell = union(enum) {
    graph_node: NodeId,
    sealed: Type.TypeId,

    fn fromGraphNode(node: NodeId) DraftTypeCell {
        return .{ .graph_node = node };
    }

    fn fromActiveType(graph: ?*InstGraph, ty: Type.TypeId) Allocator.Error!DraftTypeCell {
        if (graph) |active_graph| {
            if (active_graph.activeSnapshotNode(ty)) |node| {
                return .{ .graph_node = node };
            }
        }
        return DraftTypeCell.fromSealed(ty);
    }

    fn fromSealed(ty: Type.TypeId) DraftTypeCell {
        return .{ .sealed = ty };
    }

    fn seal(self: DraftTypeCell, graph: *InstGraph, sealer: *GraphTypeFinals) Allocator.Error!Type.TypeId {
        return switch (self) {
            .graph_node => |node| blk: {
                const sealed = try sealer.sealNode(node);
                try graph.assertTypeHasNoActiveSnapshots(sealed);
                break :blk sealed;
            },
            .sealed => |ty| ty,
        };
    }

    /// Replace this graph-qualified cell with its immutable graph-store type so
    /// a retained draft can outlive the graph's mutable relation state.
    fn sealInPlace(self: *DraftTypeCell, graph: *InstGraph, sealer: *GraphTypeFinals) Allocator.Error!void {
        const sealed = try self.*.seal(graph, sealer);
        self.* = .{ .sealed = sealed };
    }

    /// Graph-free check for retained draft state after graph sealing.
    fn assertSealed(self: DraftTypeCell) void {
        switch (self) {
            .sealed => {},
            .graph_node => Common.invariant("graph-qualified type cell remained in a sealed body draft"),
        }
    }

    fn sealCommitted(
        self: DraftTypeCell,
        committed_types: *CommittedGraphTypes,
    ) Allocator.Error!Type.TypeId {
        return switch (self) {
            .graph_node => |node| try committed_types.sealNode(node),
            .sealed => |ty| try committed_types.sealType(ty),
        };
    }

    fn toGraphNode(self: DraftTypeCell, graph: *InstGraph) Allocator.Error!NodeId {
        return switch (self) {
            .graph_node => |graph_node| graph_node,
            .sealed => |ty| try graph.importMono(ty),
        };
    }

    fn sealedHasActiveSnapshots(self: DraftTypeCell, graph: *InstGraph) Allocator.Error!bool {
        return switch (self) {
            .graph_node => false,
            .sealed => |ty| try graph.typeHasActiveSnapshots(ty),
        };
    }
};

const DraftExprId = enum(u32) { _ };
const DraftPatId = enum(u32) { _ };
const DraftStmtId = enum(u32) { _ };
const DraftLocalId = enum(u32) { _ };
const DraftFnId = enum(u32) { _ };
const DraftDefId = enum(u32) { _ };
const DraftNestedDefId = enum(u32) { _ };
const DraftComptimeSiteId = enum(u32) { _ };
const DraftStringLiteralId = enum(u32) { _ };
const DraftStaticDataId = enum(u32) { _ };

/// Qualified by the owning BodyDraftStore, never by a worker Program.
const DraftComptimeValueRootId = enum(u32) { _ };

/// A literal root this draft registers: its definition, the literal it
/// converts, and the compile-time value descriptor its read uses. The
/// descriptor names the root by its position in the draft's list until the
/// commit gives the root its program id.
const DraftLiteralRoot = struct {
    def: DraftDefId,
    module: checked.ModuleId,
    site: Common.LiteralRejectionSite,
    read: DraftComptimeValueRootId,
};

fn DraftSpan(comptime _: type) type {
    return extern struct {
        start: u32,
        len: u32,

        fn empty() @This() {
            return .{ .start = 0, .len = 0 };
        }
    };
}

const DraftFnTemplate = struct {
    fn_def: Ast.FnDef,
    source_fn_ty: checked.CheckedTypeId,
    source_fn_key: names.TypeDigest,
    mono_fn_ty: DraftTypeCell,
    evidence_digest: Ast.EvidenceDigest = .{},
    const_evidence: DraftSpan(check.ConstStore.ConstFnEvidence) = DraftSpan(check.ConstStore.ConstFnEvidence).empty(),
    const_evidence_frames: DraftSpan(check.ConstStore.ConstFnEvidenceFrame) = DraftSpan(check.ConstStore.ConstFnEvidenceFrame).empty(),
    const_evidence_frame_head: ?u32 = null,
};

const DraftFn = struct {
    source: DraftFnTemplate,
    signature_relation: Ast.SignatureRelation = .independent_roots,
    parent_owner: DraftOwner = .root,
};

const DraftLocal = struct {
    id: DraftLocalId,
    symbol: Common.Symbol,
    ty: DraftTypeCell,
    binder: ?checked.PatternBinderId = null,
    capture_id: ?checked.CaptureId = null,
    checked_capture_id: ?checked.CaptureId = null,
};

const DraftTypedLocal = struct {
    local: DraftLocalId,
    ty: DraftTypeCell,
};

const BodyTypedLocal = struct {
    local: DraftLocalId,
    ty: Type.TypeId,
};

const DraftFieldExpr = struct {
    name: names.RecordFieldNameId,
    value: DraftExprId,
};

const DraftRecordUpdate = struct {
    base: DraftExprId,
    fields: DraftSpan(DraftFieldExpr),
};

const DraftTagExpr = struct {
    name: names.TagNameId,
    payloads: DraftSpan(DraftExprId),
};

const DraftFnTarget = union(enum(u8)) {
    draft: DraftFnId,
    final: Ast.FnId,
};

/// A nested function whose specialization lookup missed: its new
/// specialization, the ownership scope its body lowers under, and the
/// context lowering it.
const DraftNestedLowering = struct {
    request_fn_node: NodeId,
    capture_entry_guards: []const NodeId,
    lookup_prefix: DraftNestedSpecLookup.PrefixId,
    fn_id: DraftFnId,
    symbol: Common.Symbol,
    spec_index: usize,
    owner_scope: BodyDraftStore.OwnerScope,
    nested_ctx: *BodyContext,
};

const DraftNestedBegin = union(enum) {
    hit: DraftFnTarget,
    lowering: DraftNestedLowering,
};

const DraftDefTarget = union(enum(u8)) {
    draft: DraftDefId,
    final: Ast.DefId,
};

const DraftLambdaExpr = struct {
    fn_id: DraftFnTarget,
    args: DraftSpan(DraftTypedLocal),
    body: DraftExprId,
};

const DraftCallValue = struct {
    callee: DraftExprId,
    args: DraftSpan(DraftExprId),
};

const DraftFnSlot = union(enum(u8)) {
    local: DraftFnTarget,
};

const ClosedDirectDraftSpecialization = struct {
    slot: DraftFnSlot,
    draft_spec: ?u32,
};

/// The callee specialization selected for one direct-call request interface,
/// with the request node the selection completed.
const CompletedDirectCallee = struct {
    callee: DraftFnSlot,
    fn_node: NodeId,
};

/// The graph request one direct call expression instantiated in one scope.
/// A body asks
/// for a direct call's result type from several places (structural-equality
/// operand sealing, argument evidence for an enclosing call, argument
/// preparation) before it lowers the call itself, and every one of those
/// reads the same checked expression against the same checked argument
/// cells, so they share one request interface, one argument preparation,
/// and one callee selection instead of instantiating the callee's checked
/// type again for each read.
const RelatedConstructor = struct {
    expr: checked.CheckedExprId,
    node: NodeId,
};

const DirectCallRequest = struct {
    fn_node: NodeId,
    /// Every argument has been related to its slot of `fn_node`. Relation
    /// only unifies, so relating the same arguments to the same slots again
    /// adds nothing; nested calls rely on this to relate each argument
    /// chain once rather than once per enclosing call.
    args_related: bool = false,
    args_prepared: bool = false,
    completed: ?CompletedDirectCallee = null,
};

const DraftProcCallee = union(enum(u8)) {
    func: DraftFnSlot,
    lifted: Ast.LiftedFnId,
};

const DraftCallProc = struct {
    callee: DraftProcCallee,
    args: DraftSpan(DraftExprId),
    iterator_procedure: ?static_dispatch.IteratorProcedureId = null,
    captures: DraftSpan(DraftExprId) = DraftSpan(DraftExprId).empty(),
    is_cold: bool = false,
};

const DraftFnDefCapture = struct {
    id: checked.CaptureId,
    value: DraftExprId,
};

const DraftMonotypeFunctionValue = struct {
    fn_id: DraftFnTarget,
    captures: DraftSpan(DraftFnDefCapture) = DraftSpan(DraftFnDefCapture).empty(),
};

fn draftFinalFn(id: Ast.FnId) DraftFnTarget {
    return .{ .final = id };
}

