const DraftSpecState = enum {
    /// The caller owns only this specialization's live request interface. Its
    /// body is lowered later in the procedure's own instantiation graph.
    deferred,
    /// A specialization body is currently being lowered in the active graph.
    /// This is used for lexical-context-dependent procedures and nested functions.
    lowering,
    /// A caller-owned specialization body finished lowering into this draft.
    lowered,
    /// A deferred request was resolved through the global specialization
    /// store after its request interface sealed.
    resolved,
};

fn runtimeDemandGuardFrameSetsEql(
    left: []const RuntimeDemandGuardFrameAddress,
    right: []const RuntimeDemandGuardFrameAddress,
) bool {
    for (left) |left_frame| {
        for (right) |right_frame| {
            if (std.meta.eql(left_frame, right_frame)) break;
        } else return false;
    }
    for (right) |right_frame| {
        for (left) |left_frame| {
            if (std.meta.eql(left_frame, right_frame)) break;
        } else return false;
    }
    return true;
}

fn draftOpenCandidateQualifies(
    state: DraftSpecState,
    exact_interface: bool,
    active_recursive_edge: bool,
    partial_recursive_allowed: bool,
) bool {
    return exact_interface or (state == .lowering and active_recursive_edge and partial_recursive_allowed);
}

fn draftCaptureEntryGuardsMatch(
    graph: *InstGraph,
    stored_guards: []const NodeId,
    requested_guards: []const NodeId,
) bool {
    if (stored_guards.len != requested_guards.len) return false;
    for (stored_guards, requested_guards) |stored, requested| {
        if (!graph.sameClass(stored, requested)) return false;
    }
    return true;
}

fn registerTemplateSpecLookup(
    draft: *BodyDraftStore,
    address: DraftTemplateLookupAddress,
    raw_spec: u32,
) Allocator.Error!void {
    try draft.template_spec_lookup.add(address, raw_spec);
}

fn updateTemplateSpecInterfaceLookups(
    draft: *BodyDraftStore,
    allocator: Allocator,
    graph: *InstGraph,
    lookup_prefix: DraftTemplateSpecLookup.PrefixId,
    request_fn_node: NodeId,
    raw_spec: u32,
) Allocator.Error!void {
    var indexed_nodes = collections.DenseMap(NodeId, void).init(allocator);
    defer indexed_nodes.deinit();
    var spec_interface = try graph.functionInterfaceIterator(request_fn_node);
    while (spec_interface.next()) |interface_node| {
        const indexed = try indexed_nodes.getOrPut(interface_node);
        if (indexed.found_existing) continue;
        const address = DraftTemplateLookupAddress{
            .open = .{
                .prefix = lookup_prefix,
                .node = interface_node,
            },
        };
        try registerTemplateSpecLookup(draft, address, raw_spec);
    }
}

fn draftNestedSpecRequestNode(
    draft: *BodyDraftStore,
    graph: *InstGraph,
    spec: *const DraftNestedSpec,
) Allocator.Error!NodeId {
    return switch (spec.state) {
        .lowered => try draft.fns.items[@backingInt(spec.fn_id)].source.mono_fn_ty.toGraphNode(graph),
        .deferred, .lowering, .resolved => spec.request_fn_node,
    };
}

fn registerNestedSpecLookup(
    draft: *BodyDraftStore,
    address: DraftNestedLookupAddress,
    raw_spec: u32,
) Allocator.Error!void {
    try draft.nested_spec_lookup.add(address, raw_spec);
}

fn registerNestedSpecInterfaceLookups(
    draft: *BodyDraftStore,
    allocator: Allocator,
    graph: *InstGraph,
    lookup_prefix: DraftNestedSpecLookup.PrefixId,
    request_fn_node: NodeId,
    raw_spec: u32,
) Allocator.Error!void {
    var indexed_nodes = collections.DenseMap(NodeId, void).init(allocator);
    defer indexed_nodes.deinit();
    var spec_interface = try graph.functionInterfaceIterator(request_fn_node);
    while (spec_interface.next()) |interface_node| {
        const indexed = try indexed_nodes.getOrPut(interface_node);
        if (indexed.found_existing) continue;
        try registerNestedSpecLookup(draft, .{
            .open = .{
                .prefix = lookup_prefix,
                .node = interface_node,
            },
        }, raw_spec);
    }
}

/// Re-verify a reused specialization's runtime-value demands under each
/// reusing guard context. The creating context is checked demand-by-demand at
/// seal; a reuse from a different context must independently exempt every
/// demand that finalized as a closed empty tag union, with the reusing
/// context's proof standing in for the creation context's inherited frames.
fn verifySpecReuseDemands(
    body_draft: *const BodyDraftStore,
    graph: *InstGraph,
    evaluator: *FrozenRuntimeImpossibilityProofEvaluator,
) Allocator.Error!void {
    for (body_draft.template_spec_reuses.items) |reuse| {
        const spec = body_draft.template_specs.items[reuse.spec];
        try verifyReusedDemandRange(body_draft, graph, evaluator, reuse, spec.demand_start, spec.demand_end, spec.demand_frame_floor);
    }
    for (body_draft.nested_spec_reuses.items) |reuse| {
        const spec = body_draft.nested_specs.items[reuse.spec];
        try verifyReusedDemandRange(body_draft, graph, evaluator, reuse, spec.demand_start, spec.demand_end, spec.demand_frame_floor);
    }
}

fn verifyReusedDemandRange(
    body_draft: *const BodyDraftStore,
    graph: *InstGraph,
    evaluator: *FrozenRuntimeImpossibilityProofEvaluator,
    reuse: DraftSpecReuse,
    start: u32,
    end: u32,
    frame_floor: RuntimeDemandGuardFrameStack,
) Allocator.Error!void {
    if (start > end or end > body_draft.runtime_value_demands.items.len) {
        Common.invariant("reused specialization demand range was out of bounds");
    }
    demand_loop: for (body_draft.runtime_value_demands.items[start..end]) |demand| {
        if (!graph.finalizesAsClosedEmptyTagUnion(demand.node)) continue;
        // The creation context's certification covers the one emitted body:
        // statement-position guard frames are not monotonic across call sites
        // in one block, so a reusing context can legitimately lack a frame
        // (e.g. a call lowered before the DraftStmt whose result proves later
        // DraftStmt nodes unreachable) without the demand needing runtime code.
        if (try evaluator.holds(demand.impossibility_proof)) continue;
        if (try evaluator.holds(reuse.prefix_proof)) continue;
        if (try evaluator.holds(demand.local_proof)) continue;
        if (demand.frames.depth < frame_floor.depth) {
            Common.invariant("reused specialization demand lost its inherited guard frame prefix");
        }
        var demand_frames = demand.frames;
        while (demand_frames.depth > frame_floor.depth) {
            const frame_id = demand_frames.head orelse
                Common.invariant("non-empty runtime-demand guard stack had no head frame");
            const frame = runtimeDemandGuardFrame(body_draft, frame_id);
            if (try evaluator.holds(frame.proof)) continue :demand_loop;
            demand_frames = .{ .head = frame.parent, .depth = demand_frames.depth - 1 };
        }
        if (demand_frames.head != frame_floor.head) {
            Common.invariant("reused specialization demand did not inherit its recorded guard frame prefix");
        }
        Common.invariant("runtime-value demand finalized as a closed empty tag-union type under a reusing guard context");
    }
}

/// Active graph relations can make independently created draft requests share
/// one complete function interface. Exact matches therefore converge on the
/// earliest recorded specialization, matching final draft commit order. A
/// partial match is an active recursive edge and must remain unique.
const DraftOpenCandidateSelection = struct {
    exact: ?u32 = null,
    partial: ?u32 = null,

    fn add(self: *DraftOpenCandidateSelection, raw_spec: u32, exact_interface: bool) bool {
        if (exact_interface) {
            if (self.exact == null or raw_spec < self.exact.?) self.exact = raw_spec;
            return true;
        }
        if (self.partial) |existing| {
            if (existing != raw_spec) return false;
        } else {
            self.partial = raw_spec;
        }
        return true;
    }

    fn selected(self: DraftOpenCandidateSelection) ?u32 {
        return self.exact orelse self.partial;
    }
};

const DraftTemplateFamilyAddress = struct {
    module: [32]u8,
    proc_base: u32,
    template: u32,
    method_scope: [32]u8,
    source_fn_key: [32]u8,

    fn init(template_ref: names.ProcTemplate, method_scope: checked.ModuleId, source_fn_key: names.TypeDigest) DraftTemplateFamilyAddress {
        return .{
            .module = names.procTemplateModuleDigest(template_ref).bytes,
            .proc_base = @backingInt(template_ref.proc_base),
            .template = @backingInt(template_ref.template),
            .method_scope = method_scope.bytes,
            .source_fn_key = source_fn_key.bytes,
        };
    }

    /// Recursive references may instantiate the same checked procedure
    /// template through a different checked root. Declaration and method scope
    /// identify the active body; the complete live function interface decides
    /// whether the reference belongs to that specialization.
    fn sameRecursiveCallable(self: DraftTemplateFamilyAddress, other: DraftTemplateFamilyAddress) bool {
        return std.mem.eql(u8, self.module[0..], other.module[0..]) and
            self.proc_base == other.proc_base and
            self.template == other.template and
            std.mem.eql(u8, self.method_scope[0..], other.method_scope[0..]);
    }
};

/// One globally reserved procedure specialization while its body is lowering
/// in the specialization's own instantiation graph. Recursive references use
/// this live root rather than creating a deferred sibling specialization.
const ActiveTemplateRoot = struct {
    graph: *InstGraph,
    family: DraftTemplateFamilyAddress,
    evidence: []const SpecEvidence,
    subst: SpecSubstitution,
    request_fn_node: NodeId,
    initial_request_arg_classes: []const ArgumentClassSnapshot,
    codec_contract: ?DraftCodecContractContext,
    fn_id: Ast.FnId,
    /// Immutable reservation signature supplied by the job. Workers never
    /// read the coordinator's mutable function row for recursive references.
    reserved_fn_ty: Type.TypeId,
    signature_relation: Ast.SignatureRelation,
};

const DraftNestedFamilyAddress = struct {
    module: [32]u8,
    owner_proc_base: u32,
    owner_template: u32,
    owner_fn_key: [32]u8,
    site: u32,
    /// Explicitly tagged default-root qualifier: the site id is relative to
    /// the declaring module's site table, so a default-root site's family
    /// carries that module's content identity (zeros under `false`).
    default_root: bool,
    default_root_module: [32]u8,
    method_scope: [32]u8,
    source_fn_key: [32]u8,

    fn init(nested: Ast.NestedFn, method_scope: checked.ModuleId, source_fn_key: names.TypeDigest) DraftNestedFamilyAddress {
        return .{
            .module = names.procTemplateModuleDigest(nested.owner).bytes,
            .owner_proc_base = @backingInt(nested.owner.proc_base),
            .owner_template = @backingInt(nested.owner.template),
            .owner_fn_key = nested.context_fn_key.bytes,
            .site = @backingInt(nested.site),
            .default_root = nested.default_root != null,
            .default_root_module = if (nested.default_root) |identity| identity.bytes else @splat(0),
            .method_scope = method_scope.bytes,
            .source_fn_key = source_fn_key.bytes,
        };
    }
};

const DraftTemplateSpecLookup = DraftSpecLookup(DraftTemplateFamilyAddress);
const DraftNestedSpecLookup = DraftSpecLookup(DraftNestedFamilyAddress);
const DraftTemplateLookupAddress = DraftTemplateSpecLookup.Address;
const DraftNestedLookupAddress = DraftNestedSpecLookup.Address;

/// Intern the exact family/evidence prefix once per request, rather than
/// hashing and storing it again for every permanent interface node. Prefix IDs
/// are append-only and local to this index; reentrant lowering may grow the
/// tables without invalidating an outer request's ID. Exact candidate checks
/// remain authoritative after this index selects a bucket.
fn DraftSpecLookup(comptime Family: type) type {
    return struct {
        const Self = @This();
        const Prefix = struct {
            family: Family,
            evidence_digest: [32]u8,
        };
        const PrefixId = enum(u32) { _ };
        const OpenPair = struct { node: NodeId, spec: u32 };
        const OpenIterator = struct {
            pairs: []const OpenPair,
            graph: *InstGraph,
            interface_roots: []const NodeId,

            fn next(self: *OpenIterator) ?u32 {
                while (self.pairs.len != 0) {
                    const pair = self.pairs[0];
                    self.pairs = self.pairs[1..];
                    for (self.interface_roots) |root| {
                        if (self.graph.sameClass(pair.node, root)) return pair.spec;
                    }
                }
                return null;
            }
        };
        const OpenAddress = struct {
            prefix: PrefixId,
            node: NodeId,
        };
        const DigestAddress = struct {
            prefix: PrefixId,
            kind: enum { closed, open_shape },
            digest: [32]u8,
        };
        const Address = union(enum) {
            open: OpenAddress,
            digest: DigestAddress,
        };
        const OverflowId = enum(u32) { none = std.math.maxInt(u32), _ };
        const Candidates = struct {
            first: u32,
            overflow: OverflowId = .none,
        };
        const Iterator = struct {
            first: ?u32,
            rest: []const u32,

            fn next(self: *Iterator) ?u32 {
                if (self.first) |first| {
                    self.first = null;
                    return first;
                }
                if (self.rest.len == 0) return null;
                const next_candidate = self.rest[0];
                self.rest = self.rest[1..];
                return next_candidate;
            }
        };
        const Entry = struct {
            value_ptr: *Candidates,
            found_existing: bool,
        };

        allocator: Allocator,
        prefixes: std.array_hash_map.Auto(Prefix, std.ArrayList(OpenPair)),
        open_requests: std.AutoHashMap(OpenAddress, Candidates),
        digest_requests: std.AutoHashMap(DigestAddress, Candidates),
        /// Only buckets with multiple candidates own an overflow list. Its
        /// stable slot survives growth of both request indexes and this table.
        overflow_lists: std.ArrayList(std.ArrayList(u32)),

        fn init(allocator: Allocator) Self {
            return .{
                .allocator = allocator,
                .prefixes = .empty,
                .open_requests = std.AutoHashMap(OpenAddress, Candidates).init(allocator),
                .digest_requests = std.AutoHashMap(DigestAddress, Candidates).init(allocator),
                .overflow_lists = .empty,
            };
        }

        fn deinit(self: *Self) void {
            self.open_requests.deinit();
            self.digest_requests.deinit();
            for (self.overflow_lists.items) |*list| list.deinit(self.allocator);
            self.overflow_lists.deinit(self.allocator);
            for (self.prefixes.values()) |*pairs| pairs.deinit(self.allocator);
            self.prefixes.deinit(self.allocator);
        }

        fn isEmpty(self: *const Self) bool {
            return self.prefixes.count() == 0 and self.open_requests.count() == 0 and self.digest_requests.count() == 0 and self.overflow_lists.items.len == 0;
        }

        fn get(self: *const Self, address: Address) ?Iterator {
            const candidates = switch (address) {
                .open => |key| self.open_requests.get(key),
                .digest => |key| self.digest_requests.get(key),
            } orelse return null;
            return .{
                .first = candidates.first,
                .rest = if (candidates.overflow == .none) &.{} else self.overflow_lists.items[@backingInt(candidates.overflow)].items,
            };
        }

        fn getOrPut(self: *Self, address: Address) Allocator.Error!Entry {
            return switch (address) {
                inline .open, .digest => |key, tag| blk: {
                    const map = &@field(self, @tagName(tag) ++ "_requests");
                    const entry = try map.getOrPut(key);
                    break :blk .{ .value_ptr = entry.value_ptr, .found_existing = entry.found_existing };
                },
            };
        }

        fn add(self: *Self, address: Address, raw_spec: u32) Allocator.Error!void {
            // Reserve before updating either index so allocation failure cannot
            // leave a registered candidate absent from the prefix inventory.
            const pairs: ?*std.ArrayList(OpenPair) = switch (address) {
                .open => |key| &self.prefixes.values()[@backingInt(key.prefix)],
                .digest => null,
            };
            if (pairs) |list| try list.ensureUnusedCapacity(self.allocator, 1);
            const entry = try self.getOrPut(address);
            if (!entry.found_existing) {
                entry.value_ptr.* = .{ .first = raw_spec };
                if (pairs) |list| list.appendAssumeCapacity(.{ .node = address.open.node, .spec = raw_spec });
                return;
            }
            if (entry.value_ptr.first == raw_spec) return;
            if (entry.value_ptr.overflow != .none) {
                const list = &self.overflow_lists.items[@backingInt(entry.value_ptr.overflow)];
                for (list.items) |existing| if (existing == raw_spec) return;
                try list.append(self.allocator, raw_spec);
            } else {
                if (self.overflow_lists.items.len == @backingInt(OverflowId.none)) return error.OutOfMemory;
                var list: std.ArrayList(u32) = .empty;
                errdefer list.deinit(self.allocator);
                try list.append(self.allocator, raw_spec);
                const overflow: OverflowId = @fromBackingInt(@intCast(self.overflow_lists.items.len));
                try self.overflow_lists.append(self.allocator, list);
                entry.value_ptr.overflow = overflow;
            }
            if (pairs) |list| list.appendAssumeCapacity(.{ .node = address.open.node, .spec = raw_spec });
        }

        fn internPrefix(self: *Self, family: Family, evidence_digest: [32]u8) Allocator.Error!PrefixId {
            const entry = try self.prefixes.getOrPut(self.allocator, .{
                .family = family,
                .evidence_digest = evidence_digest,
            });
            if (!entry.found_existing) entry.value_ptr.* = .empty;
            return @fromBackingInt(@intCast(entry.index));
        }

        fn openPairs(self: *const Self, prefix: PrefixId) []const OpenPair {
            return self.prefixes.values()[@backingInt(prefix)].items;
        }
    };
}

const EagerTemplateResolution = struct {
    request_fn_node: NodeId,
    fn_ty: Type.TypeId,
};

const DraftTemplateSpec = struct {
    state: DraftSpecState,
    template_ref: names.ProcTemplate,
    /// Checked module whose ordered registry scope governs generated method
    /// dispatch embedded in this specialization's body.
    method_scope: checked.ModuleId,
    source_fn_ty: checked.CheckedTypeId,
    source_fn_key: names.TypeDigest,
    /// Worker-local symbol retained when a deferred request must eagerly lower
    /// into this draft to reveal its iterator result representation.
    symbol: Common.Symbol,
    request_fn_node: NodeId,
    /// Stable public request retained only when eager iterator completion
    /// replaces `request_fn_node` with its producer-completed private callable.
    /// Other completed specs keep their existing representation-sensitive
    /// matching rules.
    lookup_request_fn_node: ?NodeId = null,
    initial_request_arg_classes: []const ArgumentClassSnapshot,
    evidence: []const SpecEvidence,
    /// The substitution the request applied to the template's scheme.
    subst: SpecSubstitution,
    runtime_demand_guard_frames: []const RuntimeDemandGuardFrameAddress,
    /// Runtime-value demands recorded while this specialization's body (and
    /// any explicitly lexical-context-dependent procedure bodies it owns)
    /// lowered, re-verified at seal for every reusing guard context.
    demand_start: u32 = 0,
    demand_end: u32 = 0,
    /// Guard frames inherited from the requesting context at body start; a
    /// demand's ancestors below this snapshot belong to the reused-away
    /// context.
    demand_frame_floor: RuntimeDemandGuardFrameStack = .{},
    requires_local: bool = false,
    local_context_dependent: bool = false,
    /// Whether this request's relation declined to unify the template's closed
    /// checked result row with the requested one. Recorded by the relation
    /// and consumed by `completeTemplateReservation`, which mints the widening
    /// adapter exactly when it is set (design.md "Result-Row Widening Adapter").
    widened_result_row: bool = false,
    lexical_owner: ?DraftOwner = null,
    lexical: ?DraftCodecLexicalContext = null,
    lexical_context_key: ?names.TypeDigest = null,
    codec_contract: ?DraftCodecContractContext = null,
    fn_id: DraftFnId,
    /// Top-level body definition for an eagerly lowered context-free template.
    /// Lexically dependent procedures remain in `nested_defs` instead.
    def_id: ?DraftDefId = null,
    resolved_slot: ?Ast.FnSlot = null,
    /// Mid-lowering iterator-result completion may resolve a body before the
    /// graph's final seal. Commit re-seals this retained request and proves the
    /// specialization key did not move afterward.
    eager_resolution: ?EagerTemplateResolution = null,
};

/// Coordinator intent retained after the request graph is destroyed.
///
/// The request type is workspace-local and belongs to the shard's immutable
/// store epoch. Graph argument classes and eager-resolution nodes have
/// already been validated and are deliberately absent.
const SealedTemplateSpec = struct {
    state: DraftSpecState,
    template_ref: names.ProcTemplate,
    method_scope: checked.ModuleId,
    source_fn_ty: checked.CheckedTypeId,
    source_fn_key: names.TypeDigest,
    request_fn_ty: Type.TypeId,
    evidence: []const SpecEvidence,
    /// The request's substitution sealed in the shard's store epoch.
    subst: SealedSubstitution,
    codec_contract: ?SealedCodecContractContext,
    requires_local: bool,
    local_context_dependent: bool,
    /// The request relation's recorded answer, carried to completion.
    widened_result_row: bool,
    lexical_owner: ?DraftOwner,
    fn_id: DraftFnId,
    def_id: ?DraftDefId,
    resolved_slot: ?Ast.FnSlot,
    committed_request_fn_ty: ?Type.TypeId = null,
    committed_codec_contract: ?Ast.CodecContractIdentity = null,
};

/// Seal a draft request's substitution with the graph sealer that seals its
/// request type.
fn sealSubstitutionWithSealer(allocator: Allocator, sealer: anytype, subst: SpecSubstitution) Allocator.Error!SealedSubstitution {
    if (subst.len == 0) return &.{};
    const out = try allocator.alloc(SealedSubstSlot, subst.len);
    errdefer allocator.free(out);
    for (subst, out) |slot, *sealed| {
        sealed.* = switch (slot) {
            .checked_error => .checked_error,
            .node => |node| .{ .ty = try sealer.sealNode(node) },
        };
    }
    return out;
}

fn draftTemplateSpecLookupRequestNode(spec: *const DraftTemplateSpec) NodeId {
    return spec.lookup_request_fn_node orelse spec.request_fn_node;
}

const DraftConstUseProvenance = union(enum) {
    declared,
    hoisted: checked.HoistedConstEntry,
};

const DraftDeferredConstUse = struct {
    view: ModuleView,
    /// Checked module whose ordered registry scope governs generated method
    /// dispatch inside the deferred emission, captured at deferral time.
    method_scope: ModuleView,
    owner_template: names.ProcTemplate,
    owner: DraftOwner,
    expr: DraftExprId,
    /// Checked-public request interface owned by the use site.
    request_node: NodeId,
    /// Exact producer-owned runtime representation stored with the const.
    witness_node: NodeId,
    const_use: checked.ConstUseTemplate,
    /// Explicit checker-owned origin for selecting the restoration path.
    provenance: DraftConstUseProvenance,
    context_evidence: EvidenceChain,
    use_evidence: []const SpecEvidence,
    current_fn_key: names.TypeDigest,
    /// Durable ancestry of constant expansions active at the use site. The
    /// deferred expansion must restore this chain so a delayed recursive edge
    /// resolves to its already-reserved local.
    active_const_binding: ?ActiveConstBindingId,
    lexical: DraftCodecLexicalContext,
    /// Stable proof node stored with the reservation expression. Parents
    /// may reference it before const restoration expands this boundary.
    proof_reservation: RuntimeImpossibilityProofId,
    /// Explicit expression produced by expansion. Reservation data is copied
    /// only after the complete deferred-const dependency graph is known.
    restored_source: ?DraftExprId = null,
};

/// A pending compile-time callable root currently being expanded into the
/// active body draft. The reserved local is the forward value used by a
/// recursive edge; after the expansion completes it is bound by an explicit
/// recursive let around the produced callable value.
const ActiveCallableEvalBinding = struct {
    module: checked.ModuleId,
    root: checked.ComptimeRootId,
    request_node: NodeId,
    local: DraftLocalId,
    used: bool = false,
};

const ActiveConstNodeRepresentation = union(enum) {
    sealed: Type.TypeId,
    graph: NodeId,
};

const ActiveConstNodeAddress = struct {
    module: [32]u8,
    node: checked.ConstNodeId,
    sealed_representation: bool,
};

const MaterializedConstNodeAddress = struct {
    active: ActiveConstNodeAddress,
    owner: DraftOwner,
    static_data_const_locator: ?checked.ConstLocator,
};

fn activeConstNodeAddress(
    store_view: ModuleView,
    node: checked.ConstNodeId,
    representation: ActiveConstNodeRepresentation,
) ActiveConstNodeAddress {
    return .{
        .module = store_view.key.bytes,
        .node = node,
        .sealed_representation = switch (representation) {
            .sealed => true,
            .graph => false,
        },
    };
}

/// A ConstStore node currently being materialized. ConstStore graphs may
/// contain exact back-edges through function captures, so descendants reuse
/// this reserved local instead of recursively expanding the node again.
const ActiveConstNodeBinding = struct {
    module: checked.ModuleId,
    node: checked.ConstNodeId,
    representation: ActiveConstNodeRepresentation,
    previous_same_address: ?u32,
    owner: DraftOwner,
    cell: DraftTypeCell,
    local: ?DraftLocalId = null,
    used: bool = false,
};

const MaterializedConstNode = struct {
    representation: ActiveConstNodeRepresentation,
    expr: DraftExprId,
    previous_same_address: ?u32,
};

/// One deferred structural derivation over an operand whose graph node may
/// still carry live row defaults; the eq and hash flavors share this record
/// and the prepare/emit pipeline. For equality, `lhs`/`rhs` are the two
/// compared operands; for hash they are the hashed value and the running
/// hasher (whose type is `ret_ty`).
const DraftDeferredStructuralEq = struct {
    view: ModuleView,
    method_scope: ModuleView,
    owner_template: names.ProcTemplate,
    owner: DraftOwner,
    expr: DraftExprId,
    operand_node: NodeId,
    ret_ty: Type.TypeId,
    lhs: DraftExprId,
    rhs: DraftExprId,
    mode: DraftStructuralDerivationMode,
    evidence: EvidenceChain,
    current_fn_key: names.TypeDigest,
    lexical: DraftCodecLexicalContext,
    emission_plan_ready: bool = false,
};

const DraftStructuralDerivationMode = union(enum) {
    equality: struct { negated: bool },
    tag_discriminant: struct {
        value: DraftExprId,
        tag: names.TagNameId,
        negated: bool,
    },
    hash,
};

const DraftDeferredStructuralSerialization = struct {
    view: ModuleView,
    method_scope: ModuleView,
    owner_template: names.ProcTemplate,
    owner: DraftOwner,
    expr: DraftExprId,
    plan: static_dispatch.StaticDispatchCallPlan,
    callable_node: NodeId,
    shape_node: NodeId,
    structural: SpecStructuralEvidence,
    encoding: DraftExprId,
    evidence: EvidenceChain,
    current_fn_key: names.TypeDigest,
    lexical: DraftCodecLexicalContext,
};

/// One call-site intrinsic whose callable request still carried unresolved
/// component cells at body-lowering time (e.g. a `FieldName(shape)` whose
/// shape row stays widenable until final sealing). The reservation keeps the
/// callable's result node live; emission lowers the intrinsic body under the
/// frozen final-type sealer.
const CheckedIntrinsicOperands = union(enum) {
    direct_call: []const checked.CheckedExprId,
    dispatch: []const static_dispatch.StaticDispatchOperand,
};

const DraftDeferredCallsiteIntrinsic = struct {
    view: ModuleView,
    method_scope: ModuleView,
    owner_template: names.ProcTemplate,
    owner: DraftOwner,
    expr: DraftExprId,
    intrinsic: checked.IntrinsicId,
    checked_expr_id: checked.CheckedExprId,
    source_fn_ty: checked.CheckedTypeId,
    operands: CheckedIntrinsicOperands,
    pre_lowered_args: ?DraftSpan(DraftExprId),
    callable_node: NodeId,
    evidence: EvidenceChain,
    current_fn_key: names.TypeDigest,
    lexical: DraftCodecLexicalContext,
    codec_contract: ?RetainedCodecContract,
};

/// The generated `#encoding` capture's let, when the stored constant carries
/// one. An optional pair rather than a sentinel `DraftExprId`, because
/// expression 0 is a real expression and a sentinel that aliases a live id is
/// indistinguishable from a present value.
const DraftStoredCodecEncodingLet = struct {
    local: DraftLocalId,
    value: DraftExprId,
};

/// One stored codec constant (`parser_runtime` / `encoder_for_runtime`)
/// restored at a use site. The constructor is instantiated against the
/// request and its generated format-method calls are prepared while the
/// graph still accepts relations; the generated body itself is emitted after
/// the freeze, from sealed types only, exactly like every other derived
/// codec body (design.md, the Phase-A/Phase-B boundary).
///
/// Both restore shapes prove at deferral time that the constructor's result
/// cell IS the request cell (`graph.sameClass`), so Phase B needs no durable
/// copy of the caller's request type. A cross-phase `Type.TypeId` could only
/// be a pre-freeze view of a node the freeze may still decide, and comparing
/// one to a sealed type is not a comparison this boundary can make.
const DraftDeferredStoredCodecRestore = struct {
    view: ModuleView,
    method_scope: ModuleView,
    owner_template: names.ProcTemplate,
    owner: DraftOwner,
    expr: DraftExprId,
    kind: CodecKind,
    store_view: ModuleView,
    fn_value: check.ConstStore.ConstFn,
    request_fn_node: NodeId,
    callable_node: NodeId,
    encoding_node: NodeId,
    shape_node: NodeId,
    encoding_expr: DraftExprId,
    encoding_let: ?DraftStoredCodecEncodingLet,
    source_captures: []const Builder.RestoredConstSourceCapture,
    active_const_binding: ?ActiveConstBindingId,
    evidence: EvidenceChain,
    current_fn_key: names.TypeDigest,
    lexical: DraftCodecLexicalContext,
    /// The generated codec contract active when the restore was deferred;
    /// Phase-B emission runs in a fresh context and reinstalls it before it
    /// prepares the generated body's structural codec calls.
    codec_contract: ?RetainedCodecContract = null,
};

const DraftCodecLocalProcContext = struct {
    declaration: DraftLocalProcAddress,
    context: DraftLocalProcContextId,
};

const DraftCodecLexicalContext = struct {
    view: [32]u8,
    binders: []const LexicalBinderEntry,
    local_procs: []const DraftCodecLocalProcContext,
};

const CodecKind = enum {
    parser,
    encoder,
};

/// Whether a callee needs the enclosing generated-codec contract to lower
/// intrinsics such as `ParseTagUnionSpec.parse`. Ordinary calls inherit their
/// lexical contract; format methods using ordinary values and writer arguments
/// specialize only by their own interface and evidence.
const CodecContractSelection = union(enum) {
    inherit,
    independent,
    anchored: CheckedCodecContractAnchor,
};

/// Durable checker-owned grounding for a codec method body. The selected call
/// links that procedure's checked callable type to the complete generated-codec
/// contract that justified calling it.
const CheckedCodecContractAnchor = struct {
    view: ModuleView,
    derivation: static_dispatch.GeneratedCodecDerivationId,
    call_index: u32,
    kind: CodecKind,
};

/// Graph-local specialization context for a procedure body reached from a
/// generated codec call. The constructor and public shape carry the complete
/// producer-authored contract component bindings, including components that
/// the grounding format call's own type does not mention. The public shape
/// retains its nominal boundary when the constructor uses the body shape.
const DraftCodecContractContext = struct {
    anchor: CheckedCodecContractAnchor,
    constructor_node: NodeId,
    shape_node: NodeId,
};

/// Durable form of `DraftCodecContractContext` used after the requesting
/// graph's single sealing boundary and by queued specialization jobs.
const SealedCodecContractContext = struct {
    anchor: CheckedCodecContractAnchor,
    constructor_ty: Type.TypeId,
    shape_ty: Type.TypeId,
};

const CodecContractBoundary = struct {
    callable_node: NodeId,
    shape_node: NodeId,
};

const InstantiatedGeneratedCodecCall = struct {
    view: ModuleView,
    call_index: u32,
    checked: static_dispatch.GeneratedCodecCall,
    dispatcher_node: NodeId,
    callable_node: NodeId,
    subject_node: ?NodeId,
    resolution: union(enum) {
        callable: static_dispatch.EvidenceNodeId,
        structural: static_dispatch.GeneratedCodecDerivationId,
    },
    debug_consumed: if (@import("builtin").mode == .debug) bool else void = if (@import("builtin").mode == .debug) false else {},
};

/// One unique checker-authored generated-call role. Repeated source
/// occurrences with the same exact subject share this direct slot.
const CodecMethodCallSlot = struct {
    method: names.MethodNameId,
    method_role: u32,
    subject_node: ?NodeId,
    call_index: u32,
};

const ActiveCodecContract = struct {
    view: ModuleView,
    derivation: static_dispatch.GeneratedCodecDerivationId,
    kind: CodecKind,
    evidence: EvidenceChain,
    calls_start: usize,
    calls_len: usize,
    method_call_slots: []CodecMethodCallSlot,
    grounding_call_index: ?u32,
    constructor_node: NodeId,
    shape_node: NodeId,
};

/// Graph-native snapshot of an already-instantiated checker contract. Deferred
/// intrinsic preparation runs in a fresh BodyContext but must consume the same
/// call identities and type nodes selected at the enclosing codec boundary.
const RetainedCodecContract = struct {
    view: ModuleView,
    derivation: static_dispatch.GeneratedCodecDerivationId,
    kind: CodecKind,
    evidence: EvidenceChain,
    calls: []const InstantiatedGeneratedCodecCall,
    method_call_slots: []const CodecMethodCallSlot,
    grounding_call_index: ?u32,
    constructor_node: NodeId,
    shape_node: NodeId,

    fn deinit(self: RetainedCodecContract, allocator: Allocator) void {
        allocator.free(self.calls);
        allocator.free(self.method_call_slots);
    }
};

const CodecContractExpansion = struct {
    view: [32]u8,
    derivation: static_dispatch.GeneratedCodecDerivationId,
    shape_node: NodeId,
};

const CodecCallPurpose = enum {
    format,
    custom,
};

const PreparedCodecCallId = enum(u32) { _ };

/// One exact codec request prepared while the specialization graph still
/// accepts relations. The callable node owns every checked/private component;
/// ordinary procedure targets use the same deferred specialization slot as
/// every other call in the compiler.
const DraftPreparedCodecCall = struct {
    boundary_expr: DraftExprId,
    kind: CodecKind,
    purpose: CodecCallPurpose = .format,
    /// Checker-authored method identity, retained as immutable text so sealed
    /// emission never has to consult a method registry to rediscover it.
    method_name: []const u8,
    /// Exact checker-authored role selected while the graph relation that
    /// witnesses its subject is still available.
    method_role: u32,
    subject_bearing: bool,
    contract_view: [32]u8,
    contract_derivation: static_dispatch.GeneratedCodecDerivationId,
    shape_node: NodeId,
    lookup: MethodLookup,
    callable_node: NodeId,
    callee: DraftFnSlot,
};

const FrozenPreparedCodecCall = struct {
    kind: CodecKind,
    purpose: CodecCallPurpose,
    method_name: []const u8,
    method_role: u32,
    subject_bearing: bool,
    contract_view: [32]u8,
    contract_derivation: static_dispatch.GeneratedCodecDerivationId,
    shape_ty: Type.TypeId,
    lookup: MethodLookup,
    callable_ty: Type.TypeId,
    callee: DraftFnSlot,
};

const CustomCodecCallAddress = struct {
    kind: CodecKind,
    shape_ty: Type.TypeId,
};

/// Exact Phase-B address installed from the checker role Phase A selected.
/// A subject-free role is reusable for every shape and therefore carries no
/// shape identity. A subject-bearing role carries the full Monotype digest of
/// Phase A's related shape. The Wyhash below only selects a bucket; `eql`
/// compares the method name and the whole digest, so a Wyhash collision costs
/// a probe. The digest comparison itself is trusted as shape identity, which
/// is sound because `TypeDigest` is cryptographic SHA-256 (see
/// `base.TypeDigestHasher`).
const FormatCodecCallAddress = struct {
    kind: CodecKind,
    method_name: []const u8,
    shape_digest: ?names.TypeDigest,
};

const FormatCodecCallAddressContext = struct {
    pub fn hash(_: @This(), address: FormatCodecCallAddress) u64 {
        var hasher = std.hash.Wyhash.init(0);
        std.hash.autoHash(&hasher, address.kind);
        hasher.update(address.method_name);
        std.hash.autoHash(&hasher, address.shape_digest != null);
        if (address.shape_digest) |shape_digest| {
            hasher.update(&shape_digest.bytes);
        }
        return hasher.final();
    }

    pub fn eql(_: @This(), left: FormatCodecCallAddress, right: FormatCodecCallAddress) bool {
        return left.kind == right.kind and
            std.mem.eql(u8, left.method_name, right.method_name) and
            optionalTypeDigestEql(left.shape_digest, right.shape_digest);
    }
};

const FormatCodecCallMap = std.HashMap(
    FormatCodecCallAddress,
    std.ArrayList(PreparedCodecCallId),
    FormatCodecCallAddressContext,
    std.hash_map.default_max_load_percentage,
);

const FrozenPreparedCodecCalls = struct {
    calls: []FrozenPreparedCodecCall,
    format_call_ids: FormatCodecCallMap,
    custom_call_ids: std.AutoHashMap(CustomCodecCallAddress, PreparedCodecCallId),

    fn init(
        allocator: Allocator,
        type_store: *Type.Store,
        name_store: *const names.NameStore,
        calls: []FrozenPreparedCodecCall,
    ) Allocator.Error!FrozenPreparedCodecCalls {
        errdefer allocator.free(calls);
        var format_call_ids = FormatCodecCallMap.init(allocator);
        errdefer {
            var buckets = format_call_ids.valueIterator();
            while (buckets.next()) |bucket| bucket.deinit(allocator);
            format_call_ids.deinit();
        }
        var custom_call_ids = std.AutoHashMap(CustomCodecCallAddress, PreparedCodecCallId).init(allocator);
        errdefer custom_call_ids.deinit();

        for (calls, 0..) |call, index| {
            if (index > std.math.maxInt(u32)) Common.invariant("prepared codec call index exceeded its identity range");
            switch (call.purpose) {
                .format => {
                    const address = FormatCodecCallAddress{
                        .kind = call.kind,
                        .method_name = call.method_name,
                        .shape_digest = if (call.subject_bearing)
                            type_store.typeDigest(name_store, call.shape_ty)
                        else
                            null,
                    };
                    const entry = try format_call_ids.getOrPut(address);
                    if (!entry.found_existing) entry.value_ptr.* = .empty;
                    var equivalent = false;
                    for (entry.value_ptr.items) |previous_id| {
                        const previous = calls[@backingInt(previous_id)];
                        const same_shape = if (call.subject_bearing)
                            try type_store.typeEql(name_store, previous.shape_ty, call.shape_ty)
                        else
                            !previous.subject_bearing;
                        if (!same_shape) continue;
                        const same_role = moduleBytesEqual(previous.contract_view, call.contract_view) and
                            previous.contract_derivation == call.contract_derivation and
                            previous.method_role == call.method_role;
                        const same_target = methodLookupIdentityEql(previous.lookup, call.lookup) and
                            try type_store.typeEql(name_store, previous.callable_ty, call.callable_ty) and
                            std.meta.eql(previous.callee, call.callee);
                        if (!same_target) {
                            if (same_role) {
                                Common.invariant("one checker codec method role prepared multiple call targets");
                            } else {
                                Common.invariant("frozen codec call address conflated distinct checker method-role targets");
                            }
                        }
                        equivalent = true;
                        break;
                    }
                    if (!equivalent) try entry.value_ptr.append(allocator, @fromBackingInt(@intCast(index)));
                },
                .custom => {
                    const entry = try custom_call_ids.getOrPut(.{ .kind = call.kind, .shape_ty = call.shape_ty });
                    if (entry.found_existing) Common.invariant("frozen codec plan had multiple custom calls for one shape");
                    entry.value_ptr.* = @fromBackingInt(@intCast(index));
                },
            }
        }

        return .{
            .calls = calls,
            .format_call_ids = format_call_ids,
            .custom_call_ids = custom_call_ids,
        };
    }

    fn deinit(self: *FrozenPreparedCodecCalls, allocator: Allocator) void {
        var buckets = self.format_call_ids.valueIterator();
        while (buckets.next()) |bucket| bucket.deinit(allocator);
        self.format_call_ids.deinit();
        self.custom_call_ids.deinit();
        allocator.free(self.calls);
    }

    fn formatCall(
        self: *const FrozenPreparedCodecCalls,
        type_store: *Type.Store,
        name_store: *const names.NameStore,
        kind: CodecKind,
        method_name: []const u8,
        shape_ty: ?Type.TypeId,
    ) Allocator.Error!?*const FrozenPreparedCodecCall {
        const ids = self.format_call_ids.get(.{
            .kind = kind,
            .method_name = method_name,
            .shape_digest = if (shape_ty) |shape| type_store.typeDigest(name_store, shape) else null,
        }) orelse return null;
        var found: ?*const FrozenPreparedCodecCall = null;
        for (ids.items) |id| {
            const index = @backingInt(id);
            if (index >= self.calls.len) Common.invariant("prepared codec call identity was outside its frozen plan");
            const call = &self.calls[index];
            if (shape_ty) |shape| {
                if (!call.subject_bearing or !try type_store.typeEql(name_store, call.shape_ty, shape)) continue;
            } else if (call.subject_bearing) {
                continue;
            }
            if (found != null) Common.invariant("frozen codec digest bucket contained multiple exact format-call matches");
            found = call;
        }
        return found;
    }

    fn customCall(
        self: *const FrozenPreparedCodecCalls,
        kind: CodecKind,
        shape_ty: Type.TypeId,
    ) ?*const FrozenPreparedCodecCall {
        const id = self.custom_call_ids.get(.{ .kind = kind, .shape_ty = shape_ty }) orelse return null;
        const index = @backingInt(id);
        if (index >= self.calls.len) Common.invariant("prepared codec call identity was outside its frozen plan");
        return &self.calls[index];
    }
};

/// One `??` field-default value pre-lowered while the specialization graph
/// still accepted relations (design.md "Defaulted Fields"): the default is a
/// checked expression, and checked-expression lowering is relation
/// production, so it must happen in Phase A. Phase-B parser emission consumes
/// the finished draft expression and may not lower another checked default.
const DraftPreparedFieldDefault = struct {
    boundary_expr: DraftExprId,
    default: Type.FieldDefault,
    field_node: NodeId,
    value: DraftExprId,
};

const FrozenPreparedFieldDefault = struct {
    default: Type.FieldDefault,
    field_ty: Type.TypeId,
    value: DraftExprId,
    consumed: bool = false,
};

/// Frozen Phase-B lookup from a sealed defaulted-field demand to its
/// pre-lowered value expression. Each prepared value is one draft expression
/// tree, so each entry satisfies exactly one generated consumption.
const FrozenPreparedFieldDefaults = struct {
    entries: []FrozenPreparedFieldDefault,

    fn take(
        self: *FrozenPreparedFieldDefaults,
        default: Type.FieldDefault,
        field_ty: Type.TypeId,
    ) ?DraftExprId {
        for (self.entries) |*entry| {
            if (entry.consumed) continue;
            if (!std.meta.eql(entry.default, default)) continue;
            if (entry.field_ty != field_ty) continue;
            entry.consumed = true;
            return entry.value;
        }
        return null;
    }

    fn deinit(self: *FrozenPreparedFieldDefaults, allocator: Allocator) void {
        allocator.free(self.entries);
    }
};

const DraftDeferredInspect = struct {
    view: ModuleView,
    method_scope: ModuleView,
    owner_template: names.ProcTemplate,
    owner: DraftOwner,
    expr: DraftExprId,
    value: DraftExprId,
    value_node: NodeId,
    ret_ty: Type.TypeId,
    evidence: EvidenceChain,
    current_fn_key: names.TypeDigest,
    lexical: DraftCodecLexicalContext,
    /// Exact pass-local proof that the inspect body cannot be reached.
    impossibility_proof: ?RuntimeImpossibilityProofId,
};

const DraftPreparedInspectMethod = struct {
    value_node: NodeId,
    callee: DraftFnSlot,
};

const RuntimeImpossibilityProofId = enum(u32) { _ };

const RuntimeImpossibilityProof = union(enum) {
    node: NodeId,
    never,
    always,
    pending,
    forward: RuntimeImpossibilityProofId,
    any: DraftSpan(RuntimeImpossibilityProofId),
    all: DraftSpan(RuntimeImpossibilityProofId),
};

const DraftRuntimeValueDemand = struct {
    node: NodeId,
    /// Exemption proof under the demand's creation context: the full guard
    /// frame stack (inherited and body-internal) plus the local parts.
    impossibility_proof: ?RuntimeImpossibilityProofId,
    /// The exact guard frame stack at record time. A specialization reused
    /// from a different guard context re-verifies its demands at seal against
    /// the reusing context, substituting that context for the persistent stack
    /// below the owning specialization's inherited-frame floor.
    frames: RuntimeDemandGuardFrameStack,
    /// Context-independent exemption parts: function entry guards and the
    /// expression's own proof.
    local_proof: ?RuntimeImpossibilityProofId,
};

const RuntimeDemandGuardFrameKind = enum {
    match_branch,
    pattern_success,
    iterator_one,
    statement_success,
};

const RuntimeDemandGuardFrameAddress = struct {
    module: [32]u8,
    owner_module: [32]u8,
    owner_proc_base: u32,
    owner_template: u32,
    pattern: u32,
    kind: RuntimeDemandGuardFrameKind,
};

const RuntimeDemandGuardFrameId = enum(u32) { _ };

/// An immutable snapshot of the active runtime-demand guards. Every push adds
/// one parent-linked node to `BodyDraftStore.runtime_demand_guard_frames`, so
/// saving, restoring, and inheriting a stack is a fixed-size value copy.
const RuntimeDemandGuardFrameStack = struct {
    head: ?RuntimeDemandGuardFrameId = null,
    depth: u32 = 0,
};

const RuntimeDemandGuardFrame = struct {
    parent: ?RuntimeDemandGuardFrameId,
    address: RuntimeDemandGuardFrameAddress,
    proof: RuntimeImpossibilityProofId,
};

fn runtimeDemandGuardFrame(
    draft: *const BodyDraftStore,
    id: RuntimeDemandGuardFrameId,
) *const RuntimeDemandGuardFrame {
    const index = @backingInt(id);
    if (index >= draft.runtime_demand_guard_frames.items.len) {
        Common.invariant("runtime-demand guard frame ID was outside the draft frame store");
    }
    return &draft.runtime_demand_guard_frames.items[index];
}

fn runtimeDemandGuardFrameStackContains(
    draft: *const BodyDraftStore,
    stack: RuntimeDemandGuardFrameStack,
    address: RuntimeDemandGuardFrameAddress,
) bool {
    var current = stack.head;
    while (current) |id| {
        const frame = runtimeDemandGuardFrame(draft, id);
        if (std.meta.eql(frame.address, address)) return true;
        current = frame.parent;
    }
    return false;
}

fn pushRuntimeDemandGuardFrame(
    draft: *BodyDraftStore,
    existing: RuntimeDemandGuardFrameStack,
    address: RuntimeDemandGuardFrameAddress,
    proof: RuntimeImpossibilityProofId,
) Allocator.Error!RuntimeDemandGuardFrameStack {
    const id: RuntimeDemandGuardFrameId = @fromBackingInt(@intCast(draft.runtime_demand_guard_frames.items.len));
    try draft.runtime_demand_guard_frames.append(draft.allocator, .{
        .parent = existing.head,
        .address = address,
        .proof = proof,
    });
    return .{ .head = id, .depth = existing.depth + 1 };
}

fn addRuntimeDemandGuardFrame(
    draft: *BodyDraftStore,
    existing: RuntimeDemandGuardFrameStack,
    address: RuntimeDemandGuardFrameAddress,
    proof: RuntimeImpossibilityProofId,
) Allocator.Error!RuntimeDemandGuardFrameStack {
    if (runtimeDemandGuardFrameStackContains(draft, existing, address)) return existing;
    return try pushRuntimeDemandGuardFrame(draft, existing, address, proof);
}

const FrozenRuntimeImpossibilityProofEvaluator = struct {
    allocator: Allocator,
    graph: *InstGraph,
    draft: *const BodyDraftStore,
    memo: []?bool,
    active: []bool,

    fn init(
        allocator: Allocator,
        graph: *InstGraph,
        draft: *const BodyDraftStore,
    ) Allocator.Error!FrozenRuntimeImpossibilityProofEvaluator {
        const memo = try allocator.alloc(?bool, draft.impossibility_proofs.items.len);
        errdefer allocator.free(memo);
        @memset(memo, null);
        const active = try allocator.alloc(bool, draft.impossibility_proofs.items.len);
        @memset(active, false);
        return .{ .allocator = allocator, .graph = graph, .draft = draft, .memo = memo, .active = active };
    }

    fn deinit(self: *FrozenRuntimeImpossibilityProofEvaluator, allocator: Allocator) void {
        allocator.free(self.active);
        allocator.free(self.memo);
    }

    fn proofSpan(self: *const FrozenRuntimeImpossibilityProofEvaluator, span: DraftSpan(RuntimeImpossibilityProofId)) []const RuntimeImpossibilityProofId {
        if (span.start > self.draft.impossibility_proof_ids.items.len or
            span.len > self.draft.impossibility_proof_ids.items.len - span.start)
        {
            Common.invariant("runtime impossibility proof span was outside the frozen draft proof store");
        }
        return self.draft.impossibility_proof_ids.items[span.start..][0..span.len];
    }

    fn holds(self: *FrozenRuntimeImpossibilityProofEvaluator, maybe_proof: ?RuntimeImpossibilityProofId) Allocator.Error!bool {
        return if (maybe_proof) |proof| try self.holdsInner(proof) else false;
    }

    /// Evaluate a proof graph node, memoizing every node it decides; the
    /// any/all structure is evaluated on explicit stacks.
    fn holdsInner(self: *FrozenRuntimeImpossibilityProofEvaluator, proof_id: RuntimeImpossibilityProofId) Allocator.Error!bool {
        return try Eval.run(self.allocator, self, proof_id);
    }

    const Eval = collections.AnyAll.Evaluation(RuntimeImpossibilityProofId, FrozenRuntimeImpossibilityProofEvaluator);

    pub fn enter(self: *FrozenRuntimeImpossibilityProofEvaluator, items: Eval.Items, proof_id: RuntimeImpossibilityProofId) Allocator.Error!Eval.Expansion {
        const index = @backingInt(proof_id);
        if (index >= self.draft.impossibility_proofs.items.len) {
            Common.invariant("runtime impossibility proof referenced a missing proof node");
        }
        if (self.memo[index]) |result| return .{ .value = result };
        if (self.active[index]) Common.invariant("runtime impossibility proof graph contained a cycle");
        const expansion: Eval.Expansion = switch (self.draft.impossibility_proofs.items[index]) {
            .node => |node| .{ .value = try self.graph.finalizesAsUninhabited(node) },
            .never => .{ .value = false },
            .always => .{ .value = true },
            .pending => Common.invariant("runtime impossibility proof reservation was not filled before graph sealing"),
            .forward => |child| blk: {
                try items.add(child);
                break :blk .{ .group = .all };
            },
            .any => |span| blk: {
                for (self.proofSpan(span)) |child| try items.add(child);
                break :blk .{ .group = .any };
            },
            .all => |span| blk: {
                for (self.proofSpan(span)) |child| try items.add(child);
                break :blk .{ .group = .all };
            },
        };
        switch (expansion) {
            .value => |result| self.memo[index] = result,
            .group => self.active[index] = true,
        }
        return expansion;
    }

    pub fn exit(self: *FrozenRuntimeImpossibilityProofEvaluator, proof_id: RuntimeImpossibilityProofId, result: ?bool) Allocator.Error!void {
        const index = @backingInt(proof_id);
        self.active[index] = false;
        if (result) |decided| self.memo[index] = decided;
    }
};

const DraftStructuralEqMethodCall = struct {
    boundary: u32,
    node: NodeId,
    callee: DraftFnSlot,
};

const DraftNestedSpec = struct {
    state: DraftSpecState,
    nested: Ast.NestedFn,
    /// Checked module whose ordered registry scope governs generated method
    /// dispatch embedded in this specialization's body.
    method_scope: checked.ModuleId,
    expr_id: checked.CheckedExprId,
    source_fn_ty: checked.CheckedTypeId,
    source_fn_key: names.TypeDigest,
    request_fn_node: NodeId,
    initial_request_arg_classes: []const ArgumentClassSnapshot,
    request_fn_ty: ?Type.TypeId,
    evidence: EvidenceChain,
    runtime_demand_guard_frames: []const RuntimeDemandGuardFrameAddress,
    demand_start: u32 = 0,
    demand_end: u32 = 0,
    demand_frame_floor: RuntimeDemandGuardFrameStack = .{},
    capture_entry_guards: []const NodeId,
    codec_contract: ?DraftCodecContractContext = null,
    lexical_owner: DraftOwner,
    requires_local: bool,
    local_context_dependent: bool,
    symbol: Common.Symbol,
    fn_id: DraftFnId,
    /// Exact alpha-normalized shape of the unresolved request before this nested
    /// body contributed its relations. This graph-local snapshot is the collision
    /// authority and never becomes durable specialization identity.
