};

/// Coordinator intent for one fully graph-sealed nested specialization.
const SealedNestedSpec = struct {
    state: DraftSpecState,
    nested: Ast.NestedFn,
    method_scope: checked.ModuleId,
    source_fn_key: names.TypeDigest,
    request_fn_ty: Type.TypeId,
    capture_abi_digest: names.TypeDigest,
    codec_contract: ?SealedCodecContractContext,
    sealed_codec_contract: ?Ast.CodecContractIdentity = null,
    lexical_owner: DraftOwner,
    requires_local: bool,
    local_context_dependent: bool,
    fn_id: DraftFnId,
};

fn assertCoordinatorIntentGraphFree(comptime T: type) void {
    inline for (@typeInfo(T).@"struct".field_names) |field_name| {
        if (@FieldType(T, field_name) == NodeId or
            @FieldType(T, field_name) == InstGraph or
            @FieldType(T, field_name) == GraphTypeFinals or
            @FieldType(T, field_name) == Type.Store.TypeRelocation or
            @FieldType(T, field_name) == ArgumentClassSnapshot)
        {
            @compileError(@typeName(T) ++ "." ++ field_name ++ " retains graph-qualified state");
        }
        if (@typeInfo(@FieldType(T, field_name)) == .pointer) {
            const child = @typeInfo(@FieldType(T, field_name)).pointer.child;
            if (child == NodeId or
                child == InstGraph or
                child == GraphTypeFinals or
                child == Type.Store.TypeRelocation or
                child == ArgumentClassSnapshot)
            {
                @compileError(@typeName(T) ++ "." ++ field_name ++ " retains graph-qualified storage");
            }
        }
    }
}

comptime {
    assertCoordinatorIntentGraphFree(SealedTemplateSpec);
    assertCoordinatorIntentGraphFree(SealedNestedSpec);
}

/// One reuse of a completed (or actively lowering) draft specialization from a
/// guard context that differs from the one it was created under. At seal, the
/// specialization's recorded demands are re-verified with `prefix_proof`
/// standing in for the creation context's inherited guard frames.
const DraftSpecReuse = struct {
    spec: u32,
    prefix_proof: ?RuntimeImpossibilityProofId,
};

