    static_data_requests: std.ArrayList(DraftStaticDataRequest),
    static_data_request_ids: std.AutoHashMap(DraftStaticDataRequestAddress, DraftStaticDataId),
    /// Drafts outlive worker builders and seal into a different Program.
    /// Keep exact descriptors append-only until ordered commit; abandoned
    /// speculative expressions cannot invalidate ids held by surviving ones.
    comptime_value_roots: std.ArrayList(Common.ComptimeValueRoot),
    literal_roots: std.ArrayList(DraftLiteralRoot),
    /// These memoized TypeIds belong to this draft's graph, so their lifetime
    /// cannot exceed the body that owns that graph. Type-store entries are
    /// immutable snapshots: later graph refinement allocates a new TypeId
    /// rather than changing the meaning of an existing cache key.
    parse_result_ok_types: std.AutoHashMap(GeneratedParseResultOkTypeAddress, Type.TypeId),
    generated_try_types: std.AutoHashMap(GeneratedTryTypeAddress, Type.TypeId),
    /// Ordinary queued drafts borrow the Builder-owned persistent workspace.
    /// Other private-graph tests and paths retain draft-owned relocation below.
    spec_job_workspace: ?*SpecJobWorkspace,
    /// Mutable capability for a graph-owned name store when it differs from the
    /// program store. `InstGraph` deliberately retains only a read capability.
    mutable_graph_names: ?*names.NameStore,
    /// Retains imported `TypeId` mappings while this body lowers into its
    /// graph-owned store.
    program_type_relocation: ?Type.Store.TypeRelocation,
    /// Interface-replay memo shared by every template request lowered into
    /// this draft's graph. Active entries own live input cells and completed
    /// entries own immutable constraints; both are discarded with the graph.
    interface_replay: InterfaceReplayState,

    fn init(allocator: Allocator) BodyDraftStore {
        return .{
            .allocator = allocator,
            .interface_replay = InterfaceReplayState.init(allocator),
            .symbol_domain = .coordinator,
            .worker_local_symbol_count = 0,
            .fns = .empty,
            .const_fn_evidence = .empty,
            .const_fn_evidence_frames = .empty,
            .defs = .empty,
            .def_owners = .empty,
            .nested_defs = .empty,
            .template_specs = .empty,
            .sealed_template_specs = .empty,
            .template_specs_by_template = std.AutoHashMap(names.ProcTemplate, std.ArrayList(u32)).init(allocator),
            .template_spec_by_fn = collections.DenseMap(DraftFnId, u32).init(allocator),
            .template_spec_lookup = DraftTemplateSpecLookup.init(allocator),
            .closed_direct_specializations = std.AutoHashMap(ClosedDirectCallIdentity, ClosedDirectDraftSpecialization).init(allocator),
            .active_callable_eval_bindings = .empty,
            .active_const_node_bindings = .empty,
            .active_const_node_binding_indices = std.AutoHashMap(ActiveConstNodeAddress, u32).init(allocator),
            .materialized_const_nodes = .empty,
            .materialized_const_node_indices = std.AutoHashMap(MaterializedConstNodeAddress, u32).init(allocator),
            .active_const_bindings = .empty,
            .deferred_const_uses = .empty,
            .deferred_structural_eqs = .empty,
            .deferred_structural_serializations = .empty,
            .deferred_stored_codec_restores = .empty,
            .deferred_callsite_intrinsics = .empty,
            .prepared_codec_calls = .empty,
            .prepared_field_defaults = .empty,
            .local_proc_contexts = .empty,
            .deferred_inspects = .empty,
            .prepared_inspect_methods = .empty,
            .structural_eq_method_calls = .empty,
            .runtime_value_demands = .empty,
            .runtime_demand_guard_frames = .empty,
            .template_spec_reuses = .empty,
            .nested_spec_reuses = .empty,
            .impossibility_proofs = .empty,
            .impossibility_proof_ids = .empty,
            .expr_impossibility_proofs = .empty,
            .pat_impossibility_proofs = .empty,
            .stmt_impossibility_proofs = .empty,
            .nested_specs = .empty,
            .sealed_nested_specs = .empty,
            .nested_spec_lookup = DraftNestedSpecLookup.init(allocator),
            .nested_spec_families = std.AutoHashMap(DraftNestedFamilyAddress, void).init(allocator),
            .exprs = .empty,
            .pats = .empty,
            .stmts = .empty,
            .locals = .empty,
            .expr_ids = .empty,
            .pat_ids = .empty,
            .typed_locals = .empty,
            .stmt_ids = .empty,
            .field_exprs = .empty,
            .field_access_segments = .empty,
            .fn_def_captures = .empty,
            .record_destructs = .empty,
            .str_pattern_steps = .empty,
            .declared_fields = .empty,
            .branches = .empty,
            .if_branches = .empty,
            .string_literals = .empty,
            .string_bytes = .empty,
            .checked_string_literals = std.AutoHashMap(CheckedStringLiteralAddress, DraftStringLiteralId).init(allocator),
            .proc_debug_names = .empty,
            .roots = .empty,
            .layout_requests = .empty,
            .runtime_schema_requests = .empty,
            .comptime_sites = .empty,
            .branch_regions = .empty,
            .local_names = .empty,
            .source_text_bytes = .empty,
            .expr_locs = .empty,
            .expr_regions = .empty,
            .stmt_locs = .empty,
            .stmt_regions = .empty,
            .current_owner = .root,
            .owner_starts = @splat(0),
            .owner_runs = .empty,
            .static_data_candidate_exprs = std.AutoHashMap(StaticDataCandidateAddress, DraftExprId).init(allocator),
            .static_data_requests = .empty,
            .static_data_request_ids = std.AutoHashMap(DraftStaticDataRequestAddress, DraftStaticDataId).init(allocator),
            .comptime_value_roots = .empty,
            .literal_roots = .empty,
            .parse_result_ok_types = std.AutoHashMap(GeneratedParseResultOkTypeAddress, Type.TypeId).init(allocator),
            .generated_try_types = std.AutoHashMap(GeneratedTryTypeAddress, Type.TypeId).init(allocator),
            .spec_job_workspace = null,
            .mutable_graph_names = null,
            .program_type_relocation = null,
        };
    }

    fn sealWorkerLocalSymbols(self: *BodyDraftStore, count: u32) void {
        if (self.symbol_domain != .coordinator or self.worker_local_symbol_count != 0) {
            Common.compilerBug("Monotype body draft symbol domain was sealed more than once");
        }
        self.symbol_domain = .worker_local;
        self.worker_local_symbol_count = count;
    }

    fn relocateWorkerLocalSymbol(self: *const BodyDraftStore, symbol: *Common.Symbol, symbol_base: u32) void {
        const local: u32 = @backingInt(symbol.*);
        if (local >= self.worker_local_symbol_count) {
            Common.compilerBug("Monotype body draft retained a symbol outside its worker-local domain");
        }
        const relocated = std.math.add(u32, symbol_base, local) catch
            Common.compilerBug("Monotype worker-local symbol relocation overflow");
        symbol.* = @fromBackingInt(@intCast(relocated));
    }

    /// Exhaustive symbol-bearing storage owned by a body draft. Symbols inside
    /// `DraftFnTemplate.fn_def`, roots, and sealed specialization IDs are
    /// coordinator reservations and deliberately do not belong to this domain.
    fn relocateWorkerLocalSymbols(self: *BodyDraftStore, coordinator: *Common.SymbolGen) void {
        if (self.symbol_domain != .worker_local) {
            Common.compilerBug("Monotype body draft did not carry a worker-local symbol domain");
        }
        const symbol_base = coordinator.next;
        coordinator.next = std.math.add(u32, symbol_base, self.worker_local_symbol_count) catch
            Common.compilerBug("Monotype worker-local symbol reservation overflow");

        for (self.locals.items) |*local| self.relocateWorkerLocalSymbol(&local.symbol, symbol_base);
        for (self.defs.items) |*def| self.relocateWorkerLocalSymbol(&def.symbol, symbol_base);
        for (self.nested_defs.items) |*def| self.relocateWorkerLocalSymbol(&def.symbol, symbol_base);
        for (self.proc_debug_names.items) |*debug_name| {
            self.relocateWorkerLocalSymbol(&debug_name.symbol, symbol_base);
        }
        for (self.nested_specs.items) |*spec| self.relocateWorkerLocalSymbol(&spec.symbol, symbol_base);

        self.symbol_domain = .coordinator;
        self.worker_local_symbol_count = 0;
    }

    fn mutableGraphNameStore(
        self: *BodyDraftStore,
        graph: *InstGraph,
        program: *Ast.Program,
    ) *names.NameStore {
        if (graph.name_store == &program.names) return &program.names;
        const graph_names = self.mutable_graph_names orelse
            Common.invariant("private Monotype body did not retain its mutable graph NameStore");
        if (graph_names != graph.name_store) {
            Common.compilerBug("Monotype body retained a mutable NameStore for an unrelated graph");
        }
        return graph_names;
    }

    fn ensureProgramTypeRelocation(
        self: *BodyDraftStore,
        graph: *InstGraph,
        program: *Ast.Program,
    ) *Type.Store.TypeRelocation {
        if (graph.types == &program.types) {
            Common.invariant("shared-store body requested a program-to-graph type relocation");
        }
        if (self.spec_job_workspace) |workspace| {
            if (graph.types != &workspace.types or graph.name_store != &workspace.name_store) {
                Common.compilerBug("Monotype specialization draft imported through an unrelated workspace");
            }
            return workspace.programTypeRelocation(program);
        }
        if (self.program_type_relocation == null) {
            const graph_names = self.mutableGraphNameStore(graph, program);
            self.program_type_relocation = Type.Store.TypeRelocation.init(
                self.allocator,
                &program.types,
                &program.names,
                graph.types,
                graph_names,
            );
        }
        return &self.program_type_relocation.?;
    }

    /// Free the lexical contexts, source captures, and codec contracts the
    /// deferred boundaries own, and the local procedure context entries.
    fn freeDeferredBoundaryPayloads(self: *BodyDraftStore) void {
        for (self.deferred_const_uses.items) |boundary| {
            self.allocator.free(boundary.lexical.binders);
            self.allocator.free(boundary.lexical.local_procs);
        }
        for (self.deferred_structural_eqs.items) |boundary| {
            self.allocator.free(boundary.lexical.binders);
            self.allocator.free(boundary.lexical.local_procs);
        }
        for (self.deferred_structural_serializations.items) |boundary| {
            self.allocator.free(boundary.lexical.binders);
            self.allocator.free(boundary.lexical.local_procs);
        }
        for (self.deferred_callsite_intrinsics.items) |boundary| {
            self.allocator.free(boundary.lexical.binders);
            self.allocator.free(boundary.lexical.local_procs);
            if (boundary.codec_contract) |contract| {
                contract.deinit(self.allocator);
            }
        }
        for (self.deferred_inspects.items) |boundary| {
            self.allocator.free(boundary.lexical.binders);
            self.allocator.free(boundary.lexical.local_procs);
        }
        for (self.deferred_stored_codec_restores.items) |boundary| {
            self.allocator.free(boundary.lexical.binders);
            self.allocator.free(boundary.lexical.local_procs);
            self.allocator.free(boundary.source_captures);
            if (boundary.codec_contract) |contract| contract.deinit(self.allocator);
        }
        for (self.local_proc_contexts.items) |context| self.allocator.free(context.entries);
    }

    fn deinit(self: *BodyDraftStore) void {
        self.interface_replay.deinit(self.allocator);
        for (self.template_specs.items) |*spec| {
            if (spec.lexical) |lexical| {
                self.allocator.free(lexical.binders);
                self.allocator.free(lexical.local_procs);
            }
        }
        self.freeDeferredBoundaryPayloads();
        self.local_proc_contexts.deinit(self.allocator);
        self.template_spec_lookup.deinit();
        self.closed_direct_specializations.deinit();
        var template_lists = self.template_specs_by_template.valueIterator();
        while (template_lists.next()) |list| list.deinit(self.allocator);
        self.template_specs_by_template.deinit();
        self.template_spec_by_fn.deinit();
        self.nested_spec_lookup.deinit();
        self.nested_spec_families.deinit();
        self.owner_runs.deinit(self.allocator);
        self.stmt_impossibility_proofs.deinit(self.allocator);
        self.pat_impossibility_proofs.deinit(self.allocator);
        self.expr_impossibility_proofs.deinit(self.allocator);
        self.impossibility_proof_ids.deinit(self.allocator);
        self.impossibility_proofs.deinit(self.allocator);
        if (self.program_type_relocation) |*relocation| relocation.deinit();
        self.generated_try_types.deinit();
        self.parse_result_ok_types.deinit();
        self.static_data_request_ids.deinit();
        self.static_data_requests.deinit(self.allocator);
        self.comptime_value_roots.deinit(self.allocator);
        self.literal_roots.deinit(self.allocator);
        self.static_data_candidate_exprs.deinit();
        self.stmt_regions.deinit(self.allocator);
        self.stmt_locs.deinit(self.allocator);
        self.expr_regions.deinit(self.allocator);
        self.expr_locs.deinit(self.allocator);
        self.source_text_bytes.deinit(self.allocator);
        self.local_names.deinit(self.allocator);
        self.branch_regions.deinit(self.allocator);
        self.comptime_sites.deinit(self.allocator);
        self.runtime_schema_requests.deinit(self.allocator);
        self.layout_requests.deinit(self.allocator);
        self.roots.deinit(self.allocator);
        self.proc_debug_names.deinit(self.allocator);
        self.runtime_value_demands.deinit(self.allocator);
        self.runtime_demand_guard_frames.deinit(self.allocator);
        self.template_spec_reuses.deinit(self.allocator);
        self.nested_spec_reuses.deinit(self.allocator);
        self.structural_eq_method_calls.deinit(self.allocator);
        self.prepared_inspect_methods.deinit(self.allocator);
        self.deferred_inspects.deinit(self.allocator);
        self.deferred_structural_serializations.deinit(self.allocator);
        self.deferred_stored_codec_restores.deinit(self.allocator);
        self.deferred_callsite_intrinsics.deinit(self.allocator);
        self.prepared_codec_calls.deinit(self.allocator);
        self.prepared_field_defaults.deinit(self.allocator);
        self.deferred_structural_eqs.deinit(self.allocator);
        self.deferred_const_uses.deinit(self.allocator);
        self.active_callable_eval_bindings.deinit(self.allocator);
        self.active_const_node_bindings.deinit(self.allocator);
        self.active_const_node_binding_indices.deinit();
        self.materialized_const_nodes.deinit(self.allocator);
        self.materialized_const_node_indices.deinit();
        self.active_const_bindings.deinit(self.allocator);
        self.checked_string_literals.deinit();
        self.string_bytes.deinit(self.allocator);
        self.string_literals.deinit(self.allocator);
        self.if_branches.deinit(self.allocator);
        self.branches.deinit(self.allocator);
        self.declared_fields.deinit(self.allocator);
        self.str_pattern_steps.deinit(self.allocator);
        self.record_destructs.deinit(self.allocator);
        self.fn_def_captures.deinit(self.allocator);
        self.field_access_segments.deinit(self.allocator);
        self.field_exprs.deinit(self.allocator);
        self.stmt_ids.deinit(self.allocator);
        self.typed_locals.deinit(self.allocator);
        self.pat_ids.deinit(self.allocator);
        self.expr_ids.deinit(self.allocator);
        self.locals.deinit(self.allocator);
        self.stmts.deinit(self.allocator);
        self.pats.deinit(self.allocator);
        self.exprs.deinit(self.allocator);
        self.nested_defs.deinit(self.allocator);
        self.template_specs.deinit(self.allocator);
        for (self.sealed_template_specs.items) |spec| self.allocator.free(spec.subst);
        self.sealed_template_specs.deinit(self.allocator);
        self.nested_specs.deinit(self.allocator);
        self.sealed_nested_specs.deinit(self.allocator);
        self.def_owners.deinit(self.allocator);
        self.defs.deinit(self.allocator);
        self.const_fn_evidence_frames.deinit(self.allocator);
        self.const_fn_evidence.deinit(self.allocator);
        self.stored_evidence_spans.deinit(self.allocator);
        self.fns.deinit(self.allocator);
    }

    const OwnerScope = struct {
        draft: *BodyDraftStore,
        previous: DraftOwner,

        fn leave(self: OwnerScope) void {
            // `enterOwner` reserved this scope's run slot, so the switch back
            // cannot need to grow `owner_runs`.
            self.draft.pending_owner_leaves -= 1;
            self.draft.switchOwner(self.previous) catch |err| switch (err) {
                error.OutOfMemory => Common.invariant("restoring body draft owner could not record its completed ownership run"),
            };
        }
    };

    fn enterOwner(self: *BodyDraftStore, owner: DraftOwner) Allocator.Error!OwnerScope {
        const previous = self.current_owner;
        self.pending_owner_leaves += 1;
        errdefer self.pending_owner_leaves -= 1;
        // Reserve this scope's exit slot now, even when the owner is already
        // current and no run gets recorded here.
        try self.owner_runs.ensureUnusedCapacity(self.allocator, self.pending_owner_leaves + 1);
        try self.switchOwner(owner);
        return .{ .draft = self, .previous = previous };
    }

    fn switchOwner(self: *BodyDraftStore, owner: DraftOwner) Allocator.Error!void {
        if (std.meta.eql(self.current_owner, owner)) return;
        try self.closeOwnerRun();
        self.current_owner = owner;
        self.owner_starts = self.coreLengths();
    }

    fn finishOwnerRuns(self: *BodyDraftStore) Allocator.Error!void {
        try self.closeOwnerRun();
        self.owner_starts = self.coreLengths();
    }

    fn closeOwnerRun(self: *BodyDraftStore) Allocator.Error!void {
        const ends = self.coreLengths();
        if (std.mem.eql(u32, self.owner_starts[0..], ends[0..])) return;
        // Keep one spare slot per entered owner scope beyond this run.
        try self.owner_runs.ensureUnusedCapacity(self.allocator, 1 + self.pending_owner_leaves);
        self.owner_runs.appendAssumeCapacity(.{
            .owner = self.current_owner,
            .starts = self.owner_starts,
            .ends = ends,
        });
    }

    fn coreLengths(self: *const BodyDraftStore) DraftCoreLengths {
        var lengths: DraftCoreLengths = undefined;
        lengths[@backingInt(DraftCoreKind.string_literals)] = @intCast(self.string_literals.items.len);
        lengths[@backingInt(DraftCoreKind.comptime_sites)] = @intCast(self.comptime_sites.items.len);
        lengths[@backingInt(DraftCoreKind.branch_regions)] = @intCast(self.branch_regions.items.len);
        lengths[@backingInt(DraftCoreKind.expr_ids)] = @intCast(self.expr_ids.items.len);
        lengths[@backingInt(DraftCoreKind.pat_ids)] = @intCast(self.pat_ids.items.len);
        lengths[@backingInt(DraftCoreKind.stmt_ids)] = @intCast(self.stmt_ids.items.len);
        lengths[@backingInt(DraftCoreKind.field_exprs)] = @intCast(self.field_exprs.items.len);
        lengths[@backingInt(DraftCoreKind.fn_def_captures)] = @intCast(self.fn_def_captures.items.len);
        lengths[@backingInt(DraftCoreKind.record_destructs)] = @intCast(self.record_destructs.items.len);
        lengths[@backingInt(DraftCoreKind.str_pattern_steps)] = @intCast(self.str_pattern_steps.items.len);
        lengths[@backingInt(DraftCoreKind.branches)] = @intCast(self.branches.items.len);
        lengths[@backingInt(DraftCoreKind.if_branches)] = @intCast(self.if_branches.items.len);
        lengths[@backingInt(DraftCoreKind.locals)] = @intCast(self.locals.items.len);
        lengths[@backingInt(DraftCoreKind.typed_locals)] = @intCast(self.typed_locals.items.len);
        lengths[@backingInt(DraftCoreKind.pats)] = @intCast(self.pats.items.len);
        lengths[@backingInt(DraftCoreKind.exprs)] = @intCast(self.exprs.items.len);
        lengths[@backingInt(DraftCoreKind.stmts)] = @intCast(self.stmts.items.len);
        lengths[@backingInt(DraftCoreKind.proc_debug_names)] = @intCast(self.proc_debug_names.items.len);
        lengths[@backingInt(DraftCoreKind.roots)] = @intCast(self.roots.items.len);
        lengths[@backingInt(DraftCoreKind.layout_requests)] = @intCast(self.layout_requests.items.len);
        lengths[@backingInt(DraftCoreKind.runtime_schema_requests)] = @intCast(self.runtime_schema_requests.items.len);
        return lengths;
    }

    fn ownerForCore(self: *const BodyDraftStore, kind: DraftCoreKind, index: usize) DraftOwner {
        const raw_kind = @backingInt(kind);
        for (self.owner_runs.items) |owner_run| {
            if (index >= owner_run.starts[raw_kind] and index < owner_run.ends[raw_kind]) return owner_run.owner;
        }
        Common.invariant("body draft core item had no explicit owner");
    }

    fn currentOwnerOwnsCore(self: *const BodyDraftStore, kind: DraftCoreKind, index: usize) bool {
        const raw_kind = @backingInt(kind);
        if (index >= self.owner_starts[raw_kind]) return true;
        return std.meta.eql(self.ownerForCore(kind, index), self.current_owner);
    }

    /// Register a literal root whose definition is `def`, returning the
    /// descriptor its read uses.
    fn addLiteralRoot(
        self: *BodyDraftStore,
        def: DraftDefId,
        module: checked.ModuleId,
        site: Common.LiteralRejectionSite,
    ) Allocator.Error!DraftComptimeValueRootId {
        const position: Common.LiteralRootId = @fromBackingInt(@intCast(@as(u32, @intCast(self.literal_roots.items.len))));
        const read = try self.addComptimeValueRoot(.{ .module = module, .root = .{ .literal = position }, .const_locator = null });
        try self.literal_roots.append(self.allocator, .{ .def = def, .module = module, .site = site, .read = read });
        return read;
    }

    fn addComptimeValueRoot(self: *BodyDraftStore, root: Common.ComptimeValueRoot) Allocator.Error!DraftComptimeValueRootId {
        const id: DraftComptimeValueRootId = @fromBackingInt(@intCast(@as(u32, @intCast(self.comptime_value_roots.items.len))));
        try self.comptime_value_roots.append(self.allocator, root);
        return id;
    }

    fn commitComptimeValueRoot(
        self: *const BodyDraftStore,
        program: *Ast.Program,
        roots: *collections.DenseMap(DraftComptimeValueRootId, Common.ComptimeValueRootId),
        root: DraftComptimeValueRootId,
    ) Allocator.Error!Common.ComptimeValueRootId {
        if (roots.get(root)) |id| return id;
        const descriptor = self.comptime_value_roots.items[@backingInt(root)];
        switch (descriptor.root) {
            .checked => {},
            // Committing the draft's literal roots commits their reads first.
            .literal => Common.invariant("literal root read was retained without its literal root"),
        }
        const id = try program.addComptimeValueRoot(descriptor);
        try roots.put(root, id);
        return id;
    }

    fn addExpr(self: *BodyDraftStore, expr: DraftExpr) Allocator.Error!DraftExprId {
        const id: DraftExprId = @fromBackingInt(@intCast(@as(u32, @intCast(self.exprs.items.len))));
        try self.exprs.append(self.allocator, expr);
        try self.expr_impossibility_proofs.append(self.allocator, null);
        try self.expr_locs.append(self.allocator, base.SourceLoc.none);
        try self.expr_regions.append(self.allocator, base.Region.zero());
        return id;
    }

    fn addExprWithSource(
        self: *BodyDraftStore,
        expr: DraftExpr,
        loc: base.SourceLoc,
        region: base.Region,
    ) Allocator.Error!DraftExprId {
        const id = try self.addExpr(expr);
        self.expr_locs.items[@backingInt(id)] = loc;
        self.expr_regions.items[@backingInt(id)] = region;
        return id;
    }

    fn addFn(self: *BodyDraftStore, fn_: DraftFn) Allocator.Error!DraftFnId {
        const id: DraftFnId = @fromBackingInt(@intCast(@as(u32, @intCast(self.fns.items.len))));
        var stored = fn_;
        stored.parent_owner = self.current_owner;
        try self.fns.append(self.allocator, stored);
        return id;
    }

    /// Return whether `owner` is currently lowering inside `ancestor`'s body.
    /// Draft function parents are recorded at creation, so a partial interface
    /// match can only be classified as recursion through an explicit active
    /// ownership path rather than inferred from shared type-graph cells.
    fn ownerDescendsFromDraftFn(self: *const BodyDraftStore, owner: DraftOwner, ancestor: DraftFnId) bool {
        var cursor = owner;
        var remaining = self.fns.items.len + 1;
        while (remaining > 0) : (remaining -= 1) {
            switch (cursor) {
                .root, .reserved_fn => return false,
                .draft_fn => |fn_id| {
                    if (fn_id == ancestor) return true;
                    const raw = @backingInt(fn_id);
                    if (raw >= self.fns.items.len) {
                        Common.invariant("draft owner ancestry referenced an unknown function");
                    }
                    cursor = self.fns.items[raw].parent_owner;
                },
            }
        }
        Common.invariant("draft function ownership ancestry contained a cycle");
    }

    /// Return whether `owner` is lowering inside a globally reserved root.
    /// Draft children retain their parent owner, so mutually recursive paths
    /// through local procedures remain explicit rather than being inferred
    /// from coincidentally shared graph cells.
    fn ownerDescendsFromReservedFn(self: *const BodyDraftStore, owner: DraftOwner, ancestor: Ast.FnId) bool {
        var cursor = owner;
        var remaining = self.fns.items.len + 1;
        while (remaining > 0) : (remaining -= 1) {
            switch (cursor) {
                .root => return false,
                .reserved_fn => |fn_id| return fn_id == ancestor,
                .draft_fn => |fn_id| {
                    const raw = @backingInt(fn_id);
                    if (raw >= self.fns.items.len) {
                        Common.invariant("draft owner ancestry referenced an unknown function");
                    }
                    cursor = self.fns.items[raw].parent_owner;
                },
            }
        }
        Common.invariant("draft function ownership ancestry contained a cycle");
    }

    fn reserveDef(self: *BodyDraftStore, owner: DraftOwner) Allocator.Error!DraftDefId {
        const id: DraftDefId = @fromBackingInt(@intCast(@as(u32, @intCast(self.defs.items.len))));
        try self.defs.append(self.allocator, undefined);
        errdefer _ = self.defs.pop();
        try self.def_owners.append(self.allocator, owner);
        return id;
    }

    fn setDef(self: *BodyDraftStore, id: DraftDefId, def: DraftDef) void {
        const owner = self.def_owners.items[@backingInt(id)];
        if (def.fn_id) |fn_id| switch (fn_id) {
            .draft => |draft_fn| if (!std.meta.eql(owner, DraftOwner{ .draft_fn = draft_fn })) {
                Common.invariant("draft definition target disagreed with its explicit owner");
            },
            .final => |final_fn| if (!std.meta.eql(owner, DraftOwner{ .reserved_fn = final_fn })) {
                Common.invariant("final definition target disagreed with its explicit owner");
            },
        };
        self.defs.items[@backingInt(id)] = def;
    }

    fn addNestedDef(self: *BodyDraftStore, def: DraftNestedDef) Allocator.Error!DraftNestedDefId {
        const id: DraftNestedDefId = @fromBackingInt(@intCast(@as(u32, @intCast(self.nested_defs.items.len))));
        try self.nested_defs.append(self.allocator, def);
        return id;
    }

    fn addPat(self: *BodyDraftStore, pat: DraftPat) Allocator.Error!DraftPatId {
        const id: DraftPatId = @fromBackingInt(@intCast(@as(u32, @intCast(self.pats.items.len))));
        try self.pats.append(self.allocator, pat);
        try self.pat_impossibility_proofs.append(self.allocator, null);
        return id;
    }

    fn addStmt(self: *BodyDraftStore, stmt: DraftStmt) Allocator.Error!DraftStmtId {
        const id: DraftStmtId = @fromBackingInt(@intCast(@as(u32, @intCast(self.stmts.items.len))));
        try self.stmts.append(self.allocator, stmt);
        try self.stmt_impossibility_proofs.append(self.allocator, null);
        try self.stmt_locs.append(self.allocator, base.SourceLoc.none);
        try self.stmt_regions.append(self.allocator, base.Region.zero());
        return id;
    }

    fn addStmtWithSource(
        self: *BodyDraftStore,
        stmt: DraftStmt,
        loc: base.SourceLoc,
        region: base.Region,
    ) Allocator.Error!DraftStmtId {
        const id = try self.addStmt(stmt);
        self.stmt_locs.items[@backingInt(id)] = loc;
        self.stmt_regions.items[@backingInt(id)] = region;
        return id;
    }

    fn addLocal(
        self: *BodyDraftStore,
        symbol: Common.Symbol,
        ty: DraftTypeCell,
        binder: ?checked.PatternBinderId,
        inherited_capture_id: ?checked.CaptureId,
    ) Allocator.Error!DraftLocalId {
        const id: DraftLocalId = @fromBackingInt(@intCast(@as(u32, @intCast(self.locals.items.len))));
        const checked_capture_id = if (binder) |b| checked.CaptureId.fromBinder(b) else null;
        const capture_id = if (binder != null) blk: {
            if (inherited_capture_id) |inherited| break :blk inherited;
            const index = @backingInt(id);
            if (index > checked.CaptureId.max_generated_index) {
                Common.invariant("Monotype body had too many locals for provisional capture identity");
            }
            break :blk checked.CaptureId.generatedLift(index);
        } else null;
        try self.locals.append(self.allocator, .{
            .id = id,
            .symbol = symbol,
            .ty = ty,
            .binder = binder,
            .capture_id = capture_id,
            .checked_capture_id = checked_capture_id,
        });
        try self.local_names.append(self.allocator, .empty());
        return id;
    }

    /// A local holding a reassignable binder's value at a closure's
    /// declaration, which the closure captures in place of the binder. It is
    /// not a version of the binder, so it carries no binder and its own
    /// generated capture identity: a later reassignment rebinds the binder
    /// and leaves the snapshot as it was.
    fn addCaptureSnapshotLocal(
        self: *BodyDraftStore,
        symbol: Common.Symbol,
        ty: DraftTypeCell,
    ) Allocator.Error!DraftLocalId {
        const id = try self.addLocal(symbol, ty, null, null);
        const index = @backingInt(id);
        if (index > checked.CaptureId.max_generated_index) {
            Common.invariant("Monotype body had too many locals for provisional capture identity");
        }
        self.locals.items[index].capture_id = checked.CaptureId.generatedLift(index);
        return id;
    }

    fn addExprSpan(self: *BodyDraftStore, ids: []const DraftExprId) Allocator.Error!DraftSpan(DraftExprId) {
        const start: u32 = @intCast(self.expr_ids.items.len);
        try self.expr_ids.appendSlice(self.allocator, ids);
        return .{ .start = start, .len = @intCast(ids.len) };
    }

    /// Spans holding `stored`, which must be a `Builder.constFnEvidence`
    /// result: its arena storage is never freed or reused while this draft
    /// lives, so that storage's identity names its contents.
    fn addStoredConstFnEvidence(self: *BodyDraftStore, stored: StoredConstFnEvidence) Allocator.Error!DraftEvidenceSpans {
        const key: StoredEvidenceStorage = .{
            .nodes_ptr = @intFromPtr(stored.nodes.ptr),
            .nodes_len = stored.nodes.len,
            .frames_ptr = @intFromPtr(stored.frames.ptr),
            .frames_len = stored.frames.len,
        };
        const entry = try self.stored_evidence_spans.getOrPut(self.allocator, key);
        if (!entry.found_existing) {
            errdefer _ = self.stored_evidence_spans.remove(key);
            entry.value_ptr.* = .{
                .nodes = try self.addConstFnEvidence(stored.nodes),
                .frames = try self.addConstFnEvidenceFrames(stored.frames),
            };
        }
        return entry.value_ptr.*;
    }

    fn addConstFnEvidence(self: *BodyDraftStore, values: []const check.ConstStore.ConstFnEvidence) Allocator.Error!DraftSpan(check.ConstStore.ConstFnEvidence) {
        const start: u32 = @intCast(self.const_fn_evidence.items.len);
        try self.const_fn_evidence.appendSlice(self.allocator, values);
        return .{ .start = start, .len = @intCast(values.len) };
    }

    fn addConstFnEvidenceFrames(self: *BodyDraftStore, values: []const check.ConstStore.ConstFnEvidenceFrame) Allocator.Error!DraftSpan(check.ConstStore.ConstFnEvidenceFrame) {
        const start: u32 = @intCast(self.const_fn_evidence_frames.items.len);
        try self.const_fn_evidence_frames.appendSlice(self.allocator, values);
        return .{ .start = start, .len = @intCast(values.len) };
    }

    fn constFnEvidence(self: *const BodyDraftStore, span: DraftSpan(check.ConstStore.ConstFnEvidence)) []const check.ConstStore.ConstFnEvidence {
        return self.const_fn_evidence.items[span.start..][0..span.len];
    }

    fn constFnEvidenceFrames(self: *const BodyDraftStore, span: DraftSpan(check.ConstStore.ConstFnEvidenceFrame)) []const check.ConstStore.ConstFnEvidenceFrame {
        return self.const_fn_evidence_frames.items[span.start..][0..span.len];
    }

    const ReservedExprSpan = struct {
        span: DraftSpan(DraftExprId),
    };

    /// Reserve the final flat-pool range so callers can lower directly into
    /// its destination instead of allocating a temporary slice and copying it.
    fn reserveExprSpan(self: *BodyDraftStore, len: usize) Allocator.Error!ReservedExprSpan {
        const start: u32 = @intCast(self.expr_ids.items.len);
        _ = try self.expr_ids.addManyAsSlice(self.allocator, len);
        return .{
            .span = .{ .start = start, .len = @intCast(len) },
        };
    }

    fn setReservedExprSpanItem(
        self: *BodyDraftStore,
        reserved: ReservedExprSpan,
        index: usize,
        expr: DraftExprId,
    ) void {
        if (index >= reserved.span.len) Common.invariant("reserved expression span write was out of bounds");
        self.expr_ids.items[reserved.span.start + index] = expr;
    }

