    fn addStringBytes(self: *BodyDraftStore, bytes: []const u8) Allocator.Error!DraftSpan(u8) {
        const start: u32 = @intCast(self.string_bytes.items.len);
        try self.string_bytes.appendSlice(self.allocator, bytes);
        return .{ .start = start, .len = @intCast(bytes.len) };
    }

    fn addStringLiteral(self: *BodyDraftStore, text: []const u8) Allocator.Error!DraftStringLiteralId {
        return try self.addStringView(text, 0, @intCast(text.len));
    }

    fn addCheckedStringLiteral(
        self: *BodyDraftStore,
        checked_module_bytes: [32]u8,
        literal: checked.CheckedStringLiteralId,
        text: []const u8,
    ) Allocator.Error!DraftStringLiteralId {
        const address: CheckedStringLiteralAddress = .{
            .module_bytes = checked_module_bytes,
            .literal = literal,
            .owner = self.current_owner,
        };
        if (self.checked_string_literals.get(address)) |existing| return existing;
        const lowered = try self.addStringLiteral(text);
        try self.checked_string_literals.put(address, lowered);
        return lowered;
    }

    fn addStringView(self: *BodyDraftStore, backing: []const u8, offset: u32, len: u32) Allocator.Error!DraftStringLiteralId {
        const offset_usize: usize = offset;
        const len_usize: usize = len;
        if (offset_usize > backing.len or len_usize > backing.len - offset_usize) {
            Common.invariant("body draft string literal view exceeded backing bytes");
        }
        const id: DraftStringLiteralId = @fromBackingInt(@intCast(@as(u32, @intCast(self.string_literals.items.len))));
        const backing_span = try self.addStringBytes(backing);
        try self.string_literals.append(self.allocator, .{
            .backing = backing_span,
            .offset = offset,
            .len = len,
        });
        return id;
    }

    fn addBranchRegionSpan(self: *BodyDraftStore, regions: []const base.Region) Allocator.Error!DraftSpan(base.Region) {
        const start: u32 = @intCast(self.branch_regions.items.len);
        try self.branch_regions.appendSlice(self.allocator, regions);
        return .{ .start = start, .len = @intCast(regions.len) };
    }

    fn addComptimeSite(
        self: *BodyDraftStore,
        kind: Ast.ComptimeSiteKind,
        owner: Common.LoweringModuleId,
        region: base.Region,
        checked_site: ?checked.CheckedExhaustivenessSiteId,
        branch_regions: []const base.Region,
    ) Allocator.Error!DraftComptimeSiteId {
        const id: DraftComptimeSiteId = @fromBackingInt(@intCast(@as(u32, @intCast(self.comptime_sites.items.len))));
        const branch_region_span = try self.addBranchRegionSpan(branch_regions);
        try self.comptime_sites.append(self.allocator, .{
            .kind = kind,
            .owner = owner,
            .region = region,
            .checked_site = checked_site,
            .branch_regions = branch_region_span,
        });
        return id;
    }

    fn addSourceText(self: *BodyDraftStore, text: []const u8) Allocator.Error!DraftSpan(u8) {
        const start: u32 = @intCast(self.source_text_bytes.items.len);
        try self.source_text_bytes.appendSlice(self.allocator, text);
        return .{ .start = start, .len = @intCast(text.len) };
    }

    fn setLocalName(self: *BodyDraftStore, id: DraftLocalId, name: []const u8) Allocator.Error!void {
        if (name.len == 0) return;
        self.local_names.items[@backingInt(id)] = try self.addSourceText(name);
    }

    fn setLocalCaptureId(self: *BodyDraftStore, id: DraftLocalId, capture_id: u32) void {
        const checked_id = checked.CaptureId.generatedCheck(capture_id);
        self.locals.items[@backingInt(id)].capture_id = checked_id;
        self.locals.items[@backingInt(id)].checked_capture_id = checked_id;
    }

    fn setLocalType(self: *BodyDraftStore, id: DraftLocalId, ty: DraftTypeCell) void {
        self.locals.items[@backingInt(id)].ty = ty;
        for (self.typed_locals.items) |*typed_local| {
            if (typed_local.local == id) {
                typed_local.ty = ty;
            }
        }
    }

    /// Seal every type cell retained by this body into the graph's immutable
    /// workspace store. This must run only after lowering has finished: the
    /// discarded maps below are graph-qualified lowering memoization.
    fn sealTypeCellsInPlace(self: *BodyDraftStore, graph: *InstGraph, sealer: *GraphTypeFinals) Allocator.Error!void {
        for (self.fns.items) |*fn_| {
            try fn_.source.mono_fn_ty.sealInPlace(graph, sealer);
        }
        for (self.defs.items) |*def| {
            if (def.fn_def) |*template| try template.mono_fn_ty.sealInPlace(graph, sealer);
            try def.ret.sealInPlace(graph, sealer);
        }
        for (self.nested_defs.items) |*def| {
            try def.fn_def.mono_fn_ty.sealInPlace(graph, sealer);
            try def.ret.sealInPlace(graph, sealer);
        }
        for (self.locals.items) |*local| {
            try local.ty.sealInPlace(graph, sealer);
        }
        for (self.typed_locals.items) |*local| {
            try local.ty.sealInPlace(graph, sealer);
        }
        for (self.exprs.items) |*expr| {
            try expr.ty.sealInPlace(graph, sealer);
            if (expr.data == .return_) {
                var sealed_ret = expr.data.return_;
                try sealed_ret.target.sealInPlace(graph, sealer);
                expr.data = .{ .return_ = sealed_ret };
            }
        }
        for (self.pats.items) |*pat| {
            try pat.ty.sealInPlace(graph, sealer);
        }
        for (self.stmts.items) |*stmt| {
            if (stmt.* == .return_) {
                var sealed_ret = stmt.return_;
                try sealed_ret.target.sealInPlace(graph, sealer);
                stmt.* = .{ .return_ = sealed_ret };
            }
        }
        for (self.declared_fields.items) |*field| {
            switch (field.*) {
                .padding => |padding| {
                    var sealed_padding = padding;
                    try sealed_padding.sealInPlace(graph, sealer);
                    field.* = .{ .padding = sealed_padding };
                },
                .named => {},
            }
        }
        for (self.layout_requests.items) |*request| {
            try request.ty.sealInPlace(graph, sealer);
        }
        for (self.runtime_schema_requests.items) |*request| {
            try request.ty.sealInPlace(graph, sealer);
        }
        for (self.static_data_requests.items) |*request| {
            try request.ty.sealInPlace(graph, sealer);
        }
        for (self.active_const_node_bindings.items) |*binding| {
            try binding.cell.sealInPlace(graph, sealer);
        }

        // Request IDs key on a graph-qualified type cell and are only used
        // while lowering deduplicates requests. Reset the map rather than
        // retaining stale hash keys after their requests have sealed.
        self.static_data_request_ids.deinit();
        self.static_data_request_ids = std.AutoHashMap(DraftStaticDataRequestAddress, DraftStaticDataId).init(self.allocator);

        // These caches are only consulted while a graph accepts relations.
        // Their TypeIds belong to that graph store, so retaining them after
        // sealing would make a graph-free draft accidentally graph-dependent.
        self.static_data_candidate_exprs.deinit();
        self.static_data_candidate_exprs = std.AutoHashMap(StaticDataCandidateAddress, DraftExprId).init(self.allocator);
        self.parse_result_ok_types.deinit();
        self.parse_result_ok_types = std.AutoHashMap(GeneratedParseResultOkTypeAddress, Type.TypeId).init(self.allocator);
        self.generated_try_types.deinit();
        self.generated_try_types = std.AutoHashMap(GeneratedTryTypeAddress, Type.TypeId).init(self.allocator);
    }

    /// Verify that retained body data no longer contains a graph node in a
    /// type-cell position. Graph-node queues are deliberately excluded because
    /// Builder still consumes them before it can release the graph.
    fn assertTypeCellsSealed(self: *const BodyDraftStore) void {
        for (self.fns.items) |fn_| fn_.source.mono_fn_ty.assertSealed();
        for (self.defs.items) |def| {
            if (def.fn_def) |template| template.mono_fn_ty.assertSealed();
            def.ret.assertSealed();
        }
        for (self.nested_defs.items) |def| {
            def.fn_def.mono_fn_ty.assertSealed();
            def.ret.assertSealed();
        }
        for (self.locals.items) |local| local.ty.assertSealed();
        for (self.typed_locals.items) |local| local.ty.assertSealed();
        for (self.exprs.items) |expr| {
            expr.ty.assertSealed();
            if (expr.data == .return_) expr.data.return_.target.assertSealed();
        }
        for (self.pats.items) |pat| pat.ty.assertSealed();
        for (self.stmts.items) |stmt| {
            if (stmt == .return_) stmt.return_.target.assertSealed();
        }
        for (self.declared_fields.items) |field| {
            switch (field) {
                .padding => |padding| padding.assertSealed(),
                .named => {},
            }
        }
        for (self.layout_requests.items) |request| request.ty.assertSealed();
        for (self.runtime_schema_requests.items) |request| request.ty.assertSealed();
        for (self.static_data_requests.items) |request| request.ty.assertSealed();
        for (self.active_const_node_bindings.items) |binding| binding.cell.assertSealed();
    }

    /// Drop lowering-only graph identities after their final frozen-graph
    /// consumers have run. Retained core data and coordinator intents remain;
    /// no slice in those intents may continue to borrow the graph arena.
    fn discardGraphStateAfterSeal(self: *BodyDraftStore) void {
        self.interface_replay.deinit(self.allocator);
        self.interface_replay = InterfaceReplayState.init(self.allocator);
        self.freeDeferredBoundaryPayloads();
        self.deferred_const_uses.deinit(self.allocator);
        self.deferred_const_uses = .empty;
        self.deferred_structural_eqs.deinit(self.allocator);
        self.deferred_structural_eqs = .empty;
        self.deferred_structural_serializations.deinit(self.allocator);
        self.deferred_structural_serializations = .empty;
        self.deferred_stored_codec_restores.deinit(self.allocator);
        self.deferred_stored_codec_restores = .empty;
        self.deferred_callsite_intrinsics.deinit(self.allocator);
        self.deferred_callsite_intrinsics = .empty;
        self.deferred_inspects.deinit(self.allocator);
        self.deferred_inspects = .empty;
        self.local_proc_contexts.deinit(self.allocator);
        self.local_proc_contexts = .empty;
        self.prepared_codec_calls.deinit(self.allocator);
        self.prepared_codec_calls = .empty;
        self.prepared_inspect_methods.deinit(self.allocator);
        self.prepared_inspect_methods = .empty;
        self.structural_eq_method_calls.deinit(self.allocator);
        self.structural_eq_method_calls = .empty;

        self.active_callable_eval_bindings.deinit(self.allocator);
        self.active_callable_eval_bindings = .empty;
        self.active_const_node_bindings.deinit(self.allocator);
        self.active_const_node_bindings = .empty;
        self.active_const_node_binding_indices.deinit();
        self.active_const_node_binding_indices = std.AutoHashMap(ActiveConstNodeAddress, u32).init(self.allocator);
        self.materialized_const_nodes.deinit(self.allocator);
        self.materialized_const_nodes = .empty;
        self.materialized_const_node_indices.deinit();
        self.materialized_const_node_indices = std.AutoHashMap(MaterializedConstNodeAddress, u32).init(self.allocator);
        self.active_const_bindings.deinit(self.allocator);
        self.active_const_bindings = .empty;

        self.runtime_value_demands.deinit(self.allocator);
        self.runtime_value_demands = .empty;
        self.runtime_demand_guard_frames.deinit(self.allocator);
        self.runtime_demand_guard_frames = .empty;
        self.template_spec_reuses.deinit(self.allocator);
        self.template_spec_reuses = .empty;
        self.nested_spec_reuses.deinit(self.allocator);
        self.nested_spec_reuses = .empty;
        self.impossibility_proofs.deinit(self.allocator);
        self.impossibility_proofs = .empty;
        self.impossibility_proof_ids.deinit(self.allocator);
        self.impossibility_proof_ids = .empty;
        self.expr_impossibility_proofs.deinit(self.allocator);
        self.expr_impossibility_proofs = .empty;
        self.pat_impossibility_proofs.deinit(self.allocator);
        self.pat_impossibility_proofs = .empty;
        self.stmt_impossibility_proofs.deinit(self.allocator);
        self.stmt_impossibility_proofs = .empty;

        self.template_spec_lookup.deinit();
        self.template_spec_lookup = DraftTemplateSpecLookup.init(self.allocator);
        self.nested_spec_lookup.deinit();
        self.nested_spec_families.deinit();
        self.nested_spec_lookup = DraftNestedSpecLookup.init(self.allocator);
        self.nested_spec_families = std.AutoHashMap(DraftNestedFamilyAddress, void).init(self.allocator);
        var template_lists = self.template_specs_by_template.valueIterator();
        while (template_lists.next()) |list| list.deinit(self.allocator);
        self.template_specs_by_template.deinit();
        self.template_spec_by_fn.deinit();
        self.template_specs_by_template = std.AutoHashMap(names.ProcTemplate, std.ArrayList(u32)).init(self.allocator);
        self.template_spec_by_fn = collections.DenseMap(DraftFnId, u32).init(self.allocator);
        self.closed_direct_specializations.deinit();
        self.closed_direct_specializations = std.AutoHashMap(
            ClosedDirectCallIdentity,
            ClosedDirectDraftSpecialization,
        ).init(self.allocator);

        self.spec_job_workspace = null;
        self.mutable_graph_names = null;
        if (self.program_type_relocation != null) {
            Common.compilerBug("ordinary specialization draft retained a graph-qualified relocation");
        }
    }

    fn assertGraphStateDiscarded(self: *const BodyDraftStore) void {
        self.assertTypeCellsSealed();
        if (self.deferred_const_uses.items.len != 0 or
            self.deferred_structural_eqs.items.len != 0 or
            self.deferred_structural_serializations.items.len != 0 or
            self.deferred_stored_codec_restores.items.len != 0 or
            self.deferred_callsite_intrinsics.items.len != 0 or
            self.deferred_inspects.items.len != 0 or
            self.prepared_codec_calls.items.len != 0 or
            self.prepared_inspect_methods.items.len != 0 or
            self.structural_eq_method_calls.items.len != 0 or
            self.runtime_value_demands.items.len != 0 or
            self.impossibility_proofs.items.len != 0 or
            !self.template_spec_lookup.isEmpty() or
            !self.nested_spec_lookup.isEmpty() or
            self.nested_spec_families.count() != 0 or
            self.template_specs.items.len != 0 or
            self.template_specs_by_template.count() != 0 or
            self.nested_specs.items.len != 0 or
            self.spec_job_workspace != null or
            self.mutable_graph_names != null or
            self.program_type_relocation != null)
        {
            Common.invariant("graph-qualified state remained in a sealed specialization result");
        }
    }

    fn finalIdOffsets(program: *const Ast.Program) FinalIdOffsets {
        return .{
            .fn_start = @intCast(program.fnCount()),
            .def_start = @intCast(program.defCount()),
            .nested_def_start = @intCast(program.nestedDefCount()),
            .expr_start = @intCast(program.exprCount()),
            .pat_start = @intCast(program.patCount()),
            .stmt_start = @intCast(program.stmtCount()),
            .local_start = @intCast(program.localCount()),
            .string_literal_start = @intCast(program.stringLiteralCount()),
            .comptime_site_start = @intCast(program.comptimeSiteCount()),
            .expr_ids_start = @intCast(program.exprIdCount()),
            .pat_ids_start = @intCast(program.patIdCount()),
            .typed_locals_start = @intCast(program.typedLocalCount()),
            .stmt_ids_start = @intCast(program.stmtIdCount()),
            .field_expr_start = @intCast(program.fieldExprCount()),
            .field_access_segment_start = @intCast(program.fieldAccessSegmentCount()),
            .fn_def_capture_start = @intCast(program.fnDefCaptureCount()),
            .record_destruct_start = @intCast(program.recordDestructCount()),
            .str_pattern_step_start = @intCast(program.strPatternStepCount()),
            .branch_start = @intCast(program.branchCount()),
            .if_branch_start = @intCast(program.ifBranchCount()),
            .core_id_mode = .identity,
        };
    }

    fn sealCoreIntoProgram(
        self: *const BodyDraftStore,
        program: *Ast.Program,
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
    ) Allocator.Error!void {
        var committed_types = CommittedGraphTypes.shared(graph, sealer);
        return try self.sealCoreIntoProgramWithMap(
            program,
            &committed_types,
            &.{},
            BodyDraftStore.finalIdOffsets(program),
            null,
            null,
            null,
        );
    }

    fn sealCoreIntoProgramWithMap(
        self: *const BodyDraftStore,
        program: *Ast.Program,
        committed_types: *CommittedGraphTypes,
        static_data_ids: []const Common.StaticDataId,
        draft_ids: FinalIdOffsets,
        emit_fns: ?[]const bool,
        emit_defs: ?[]const bool,
        emit_nested_defs: ?[]const bool,
    ) Allocator.Error!void {
        var shared_literal_root_defs = collections.DenseMap(DraftDefId, Ast.DefId).init(program.allocator);
        defer shared_literal_root_defs.deinit();
        var ids = draft_ids;
        ids.shared_literal_root_defs = &shared_literal_root_defs;
        const evidence_span = try program.addConstFnEvidence(self.const_fn_evidence.items);
        const evidence_frames_span = try program.addConstFnEvidenceFrames(self.const_fn_evidence_frames.items);

        // The map belongs to this import, not the worker lane: independent
        // shards may use the same local ordinal for different checked roots.
        var comptime_roots = collections.DenseMap(DraftComptimeValueRootId, Common.ComptimeValueRootId).init(program.allocator);
        defer comptime_roots.deinit();

        for (self.string_literals.items, 0..) |literal, index| {
            if (!ids.retained(.string_literals, index)) continue;
            const id = if (literal.const_blob) |blob|
                try program.addConstBlobView(blob.module_bytes, blob.data, blob.bytes, literal.offset, literal.len)
            else
                try program.addStringView(self.stringBytes(literal.backing), literal.offset, literal.len);
            if (@backingInt(id) != ids.core(.string_literals, @intCast(index), ids.string_literal_start)) {
                Common.invariant("Monotype body draft string literal id did not append contiguously");
            }
        }

        for (self.comptime_sites.items, 0..) |site, index| {
            if (!ids.retained(.comptime_sites, index)) continue;
            const id = try program.addComptimeSite(site.kind, site.owner, site.region, site.checked_site, self.branchRegions(site.branch_regions));
            if (@backingInt(id) != ids.core(.comptime_sites, @intCast(index), ids.comptime_site_start)) {
                Common.invariant("Monotype body draft compile-time site id did not append contiguously");
            }
        }

        try program.expr_ids.ensureUnusedCapacity(program.allocator, self.expr_ids.items.len);
        for (self.expr_ids.items, 0..) |id, index| if (ids.retained(.expr_ids, index)) program.expr_ids.appendAssumeCapacity(ids.expr(id));

        try program.pat_ids.ensureUnusedCapacity(program.allocator, self.pat_ids.items.len);
        for (self.pat_ids.items, 0..) |id, index| if (ids.retained(.pat_ids, index)) program.pat_ids.appendAssumeCapacity(ids.pat(id));

        try program.stmt_ids.ensureUnusedCapacity(program.allocator, self.stmt_ids.items.len);
        for (self.stmt_ids.items, 0..) |id, index| if (ids.retained(.stmt_ids, index)) program.stmt_ids.appendAssumeCapacity(ids.stmt(id));

        try program.field_exprs.ensureUnusedCapacity(program.allocator, self.field_exprs.items.len);
        for (self.field_exprs.items, 0..) |field, index| {
            if (!ids.retained(.field_exprs, index)) continue;
            program.field_exprs.appendAssumeCapacity(.{
                .name = try committed_types.commitRecordFieldName(field.name),
                .value = ids.expr(field.value),
            });
        }

        try program.field_access_segments.ensureUnusedCapacity(program.allocator, self.field_access_segments.items.len);
        for (self.field_access_segments.items) |segment| {
            program.field_access_segments.appendAssumeCapacity(.{
                .field = try committed_types.commitRecordFieldName(segment.field),
            });
        }

        try program.record_destructs.ensureUnusedCapacity(program.allocator, self.record_destructs.items.len);
        for (self.record_destructs.items, 0..) |field, index| {
            if (!ids.retained(.record_destructs, index)) continue;
            program.record_destructs.appendAssumeCapacity(.{
                .name = try committed_types.commitRecordFieldName(field.name),
                .pattern = ids.pat(field.pattern),
            });
        }

        try program.str_pattern_steps.ensureUnusedCapacity(program.allocator, self.str_pattern_steps.items.len);
        for (self.str_pattern_steps.items, 0..) |step, index| {
            if (!ids.retained(.str_pattern_steps, index)) continue;
            program.str_pattern_steps.appendAssumeCapacity(.{
                .capture = if (step.capture) |capture| ids.pat(capture) else null,
                .delimiter = ids.stringLiteral(step.delimiter),
            });
        }

        try program.branches.ensureUnusedCapacity(program.allocator, self.branches.items.len);
        for (self.branches.items, 0..) |branch, index| {
            if (!ids.retained(.branches, index)) continue;
            program.branches.appendAssumeCapacity(.{
                .pat = ids.pat(branch.pat),
                .bindings = ids.stmtSpan(branch.bindings),
                .guard = if (branch.guard) |guard| ids.expr(guard) else null,
                .body = ids.expr(branch.body),
            });
        }

        try program.if_branches.ensureUnusedCapacity(program.allocator, self.if_branches.items.len);
        for (self.if_branches.items, 0..) |branch, index| {
            if (!ids.retained(.if_branches, index)) continue;
            program.if_branches.appendAssumeCapacity(.{
                .cond = ids.expr(branch.cond),
                .body = ids.expr(branch.body),
            });
        }

        try program.locals.ensureUnusedCapacity(program.allocator, self.locals.items.len);
        try program.local_names.ensureUnusedCapacity(program.allocator, self.locals.items.len);
        // This commit is one Monotype materialization. Checked capture
        // identities identify aliases within it, while separate commits get
        // separate durable ids even when they instantiate the same binder.
        var durable_capture_ids = collections.DenseMap(checked.CaptureId, checked.CaptureId).init(program.allocator);
        defer durable_capture_ids.deinit();
        for (self.locals.items, 0..) |local, index| {
            if (!ids.retained(.locals, index)) continue;
            const expected = ids.local(@fromBackingInt(@intCast(@as(u32, @intCast(index)))));
            const sealed_ty = try local.ty.sealCommitted(committed_types);
            const durable_capture_id = if (local.capture_id) |provisional| blk: {
                const final_index = @backingInt(expected);
                if (final_index > checked.CaptureId.max_generated_index) {
                    Common.invariant("Monotype program had too many locals for durable capture identity");
                }
                const entry = try durable_capture_ids.getOrPut(provisional);
                if (!entry.found_existing) entry.value_ptr.* = checked.CaptureId.generatedLift(final_index);
                break :blk entry.value_ptr.*;
            } else null;
            program.locals.appendAssumeCapacity(.{
                .id = expected,
                .symbol = local.symbol,
                .ty = sealed_ty,
                .binder = local.binder,
                .capture_id = durable_capture_id,
                .checked_capture_id = local.checked_capture_id,
            });
            const local_name = self.sourceText(self.local_names.items[index]);
            program.local_names.appendAssumeCapacity(if (local_name.len == 0) "" else try program.allocator.dupe(u8, local_name));
        }

        try program.fn_def_captures.ensureUnusedCapacity(program.allocator, self.fn_def_captures.items.len);
        for (self.fn_def_captures.items, 0..) |capture, index| {
            if (!ids.retained(.fn_def_captures, index)) continue;
            const id = if (capture.id.isLiftGenerated())
                durable_capture_ids.get(capture.id) orelse
                    Common.invariant("retained function capture names a missing target identity")
            else
                capture.id;
            program.fn_def_captures.appendAssumeCapacity(.{
                .id = id,
                .value = ids.expr(capture.value),
            });
        }

        try program.typed_locals.ensureUnusedCapacity(program.allocator, self.typed_locals.items.len);
        for (self.typed_locals.items, 0..) |typed, index| {
            if (!ids.retained(.typed_locals, index)) continue;
            program.typed_locals.appendAssumeCapacity(.{
                .local = ids.local(typed.local),
                .ty = try typed.ty.sealCommitted(committed_types),
            });
        }

        try program.pats.ensureUnusedCapacity(program.allocator, self.pats.items.len);
        for (self.pats.items, 0..) |pat, index| {
            if (!ids.retained(.pats, index)) continue;
            program.pats.appendAssumeCapacity(.{
                .ty = try pat.ty.sealCommitted(committed_types),
                .data = try BodyDraftStore.sealCorePatData(committed_types, ids, pat.data),
            });
        }

        // A literal root commits with its definition, which commits exactly
        // when the function owning it does; its read then names the root by
        // its program id. The same literal at the same type is one literal
        // root however many specializations convert it: its definition's
        // content identity names the conversion, so a later one reads the
        // first one's root, and its read's representation evidence calls the
        // first one's definition, whose callables the root's value holds.
        for (self.literal_roots.items) |root| {
            if (emit_defs) |emit| if (!emit[@backingInt(root.def)]) continue;
            const def = self.defs.items[@backingInt(root.def)];
            const seed = def.identity_seed orelse Common.invariant("literal root definition had no identity seed");
            const identity = try sealedDefIdentity(program, committed_types, seed, ids.typedLocalSpan(def.args), try def.ret.sealCommitted(committed_types));
            const entry = try program.literal_root_by_identity.getOrPut(program.allocator, identity);
            if (entry.found_existing) {
                try shared_literal_root_defs.put(root.def, program.literal_roots.get(@backingInt(entry.value_ptr.*)).def);
            } else {
                entry.value_ptr.* = try program.addLiteralRoot(.{ .def = ids.def(root.def), .module = root.module, .site = root.site });
            }
            var descriptor = self.comptime_value_roots.items[@backingInt(root.read)];
            descriptor.root = .{ .literal = entry.value_ptr.* };
            try comptime_roots.put(root.read, try program.addComptimeValueRoot(descriptor));
        }

        var retained_expr_count: usize = 0;
        for (self.exprs.items, 0..) |_, index| {
            if (ids.retained(.exprs, index)) retained_expr_count += 1;
        }
        const nominal_backing_expr_start: u32 = @intCast(program.exprCount() + retained_expr_count);
        var nominal_backing_exprs = std.ArrayList(PendingSealedExpr).empty;
        defer nominal_backing_exprs.deinit(program.allocator);

        try program.exprs.ensureUnusedCapacity(program.allocator, retained_expr_count);
        try program.expr_locs.ensureUnusedCapacity(program.allocator, retained_expr_count);
        try program.expr_regions.ensureUnusedCapacity(program.allocator, retained_expr_count);
        for (self.exprs.items, 0..) |expr, index| {
            if (!ids.retained(.exprs, index)) continue;
            const sealed_ty = try expr.ty.sealCommitted(committed_types);
            const sealed_data = try self.sealCoreExprData(
                program,
                ids,
                committed_types,
                static_data_ids,
                &comptime_roots,
                expr.data,
            );
            const loc = ids.sourceLoc(self.expr_locs.items[index]);
            const region = self.expr_regions.items[index];
            const sealed_expr = try BodyDraftStore.sealConstructorExprWithNominalBackings(
                program,
                &nominal_backing_exprs,
                nominal_backing_expr_start,
                sealed_ty,
                sealed_data,
                loc,
                region,
            );
            program.exprs.appendAssumeCapacity(.{
                .ty = sealed_expr.ty,
                .data = sealed_expr.data,
            });
            program.expr_locs.appendAssumeCapacity(loc);
            program.expr_regions.appendAssumeCapacity(region);
        }
        for (nominal_backing_exprs.items) |pending| {
            try program.exprs.append(program.allocator, pending.expr);
            try program.expr_locs.append(program.allocator, pending.loc);
            try program.expr_regions.append(program.allocator, pending.region);
        }

        try program.stmts.ensureUnusedCapacity(program.allocator, self.stmts.items.len);
        try program.stmt_locs.ensureUnusedCapacity(program.allocator, self.stmts.items.len);
        try program.stmt_regions.ensureUnusedCapacity(program.allocator, self.stmts.items.len);
        for (self.stmts.items, 0..) |stmt, index| {
            if (!ids.retained(.stmts, index)) continue;
            program.stmts.appendAssumeCapacity(try BodyDraftStore.sealCoreStmt(ids, committed_types, stmt));
            program.stmt_locs.appendAssumeCapacity(ids.sourceLoc(self.stmt_locs.items[index]));
            program.stmt_regions.appendAssumeCapacity(self.stmt_regions.items[index]);
        }

        try program.fns.ensureUnusedCapacity(program.allocator, self.fns.items.len);
        for (self.fns.items, 0..) |fn_, index| {
            if (emit_fns) |emit| if (!emit[index]) continue;
            program.fns.appendAssumeCapacity(.{
                .source = try BodyDraftStore.sealFnTemplate(committed_types, fn_.source, evidence_span.start, evidence_frames_span.start),
                .signature_relation = fn_.signature_relation,
            });
        }

        try program.defs.ensureUnusedCapacity(program.allocator, self.defs.items.len);
        for (self.defs.items, 0..) |def, index| {
            if (emit_defs) |emit| if (!emit[index]) continue;
            const sealed_fn_def = if (def.fn_def) |template| try BodyDraftStore.sealFnTemplate(committed_types, template, evidence_span.start, evidence_frames_span.start) else null;
            const sealed_fn_id = if (def.fn_id) |fn_id| ids.fnTarget(fn_id) else null;
            if (sealed_fn_def) |template| {
                if (sealed_fn_id) |fn_id| {
                    program.setFnSource(fn_id, template);
                }
            }
            const sealed_args = ids.typedLocalSpan(def.args);
            const sealed_ret = try def.ret.sealCommitted(committed_types);
            const root_identity: ?names.TypeDigest = if (def.identity_seed) |seed|
                try sealedDefIdentity(program, committed_types, seed, sealed_args, sealed_ret)
            else
                null;
            program.defs.appendAssumeCapacity(.{
                .symbol = def.symbol,
                .fn_def = sealed_fn_def,
                .fn_id = sealed_fn_id,
                .root_identity = root_identity,
                .args = sealed_args,
                .body = ids.fnBody(def.body),
                .ret = sealed_ret,
            });
        }

        try program.nested_defs.ensureUnusedCapacity(program.allocator, self.nested_defs.items.len);
        for (self.nested_defs.items, 0..) |def, index| {
            if (emit_nested_defs) |emit| if (!emit[index]) continue;
            const sealed_fn_def = try BodyDraftStore.sealFnTemplate(committed_types, def.fn_def, evidence_span.start, evidence_frames_span.start);
            const sealed_fn_id = ids.fnTarget(def.fn_id);
            program.setFnSource(sealed_fn_id, sealed_fn_def);
            program.nested_defs.appendAssumeCapacity(.{
                .symbol = def.symbol,
                .fn_def = sealed_fn_def,
                .fn_id = sealed_fn_id,
                .args = ids.typedLocalSpan(def.args),
                .body = ids.expr(def.body),
                .ret = try def.ret.sealCommitted(committed_types),
            });
        }

        for (self.proc_debug_names.items, 0..) |debug_name, index| {
            if (!ids.retained(.proc_debug_names, index)) continue;
            try program.setProcDebugName(debug_name.symbol, try committed_types.commitExportName(debug_name.name));
        }

        try program.roots.ensureUnusedCapacity(program.allocator, self.roots.items.len);
        for (self.roots.items, 0..) |root, index| {
            if (!ids.retained(.roots, index)) continue;
            program.roots.appendAssumeCapacity(.{
                .def = ids.def(root.def),
                .request = root.request,
                .owner = root.owner,
            });
        }

        try program.layout_requests.ensureUnusedCapacity(program.allocator, self.layout_requests.items.len);
        for (self.layout_requests.items, 0..) |request, index| {
            if (!ids.retained(.layout_requests, index)) continue;
            program.layout_requests.appendAssumeCapacity(.{
                .checked_type = request.checked_type,
                .ty = try request.ty.sealCommitted(committed_types),
                .def = if (request.def) |def_id| ids.def(def_id) else null,
                .const_locator = request.const_locator,
            });
        }

        try program.runtime_schema_requests.ensureUnusedCapacity(program.allocator, self.runtime_schema_requests.items.len);
        for (self.runtime_schema_requests.items, 0..) |request, index| {
            if (!ids.retained(.runtime_schema_requests, index)) continue;
            try appendRuntimeSchemaRequestToProgram(program, .{
                .def = try committed_types.commitTypeDef(request.def),
                .ty = try request.ty.sealCommitted(committed_types),
            });
        }
    }

    fn sourceText(self: *const BodyDraftStore, span: DraftSpan(u8)) []const u8 {
        if (span.start > self.source_text_bytes.items.len or span.len > self.source_text_bytes.items.len - span.start) {
            Common.invariant("Monotype body draft source text span was out of bounds");
        }
        return self.source_text_bytes.items[span.start..][0..span.len];
    }

    fn stringBytes(self: *const BodyDraftStore, span: DraftSpan(u8)) []const u8 {
        if (span.start > self.string_bytes.items.len or span.len > self.string_bytes.items.len - span.start) {
            Common.invariant("Monotype body draft string byte span was out of bounds");
        }
        return self.string_bytes.items[span.start..][0..span.len];
    }

    fn branchRegions(self: *const BodyDraftStore, span: DraftSpan(base.Region)) []const base.Region {
        if (span.start > self.branch_regions.items.len or span.len > self.branch_regions.items.len - span.start) {
            Common.invariant("Monotype body draft branch-region span was out of bounds");
        }
        return self.branch_regions.items[span.start..][0..span.len];
    }

    fn sealFnTemplate(
        committed_types: *CommittedGraphTypes,
        template: DraftFnTemplate,
        evidence_start: u32,
        evidence_frames_start: u32,
    ) Allocator.Error!Ast.FnTemplate {
        return .{
            .fn_def = template.fn_def,
            .source_fn_ty = template.source_fn_ty,
            .source_fn_key = template.source_fn_key,
            .mono_fn_ty = try template.mono_fn_ty.sealCommitted(committed_types),
            .evidence_digest = template.evidence_digest,
            .const_evidence = .{ .start = evidence_start + template.const_evidence.start, .len = template.const_evidence.len },
            .const_evidence_frames = .{ .start = evidence_frames_start + template.const_evidence_frames.start, .len = template.const_evidence_frames.len },
            .const_evidence_frame_head = template.const_evidence_frame_head,
        };
    }

    fn sealCorePatData(
        committed_types: *CommittedGraphTypes,
        ids: FinalIdOffsets,
        data: DraftPatData,
    ) Allocator.Error!Ast.PatData {
        return switch (data) {
            .bind => |local| .{ .bind = ids.local(local) },
            .wildcard => .wildcard,
            .as => |as| .{ .as = .{
                .pattern = ids.pat(as.pattern),
                .local = ids.local(as.local),
            } },
            .record => |span| .{ .record = ids.recordDestructSpan(span) },
            .tuple => |span| .{ .tuple = ids.patSpan(span) },
            .list => |list| .{ .list = .{
                .patterns = ids.patSpan(list.patterns),
                .rest = if (list.rest) |rest| .{
                    .index = rest.index,
                    .pattern = if (rest.pattern) |pattern| ids.pat(pattern) else null,
                } else null,
            } },
            .tag => |tag| .{ .tag = .{
                .name = try committed_types.commitTagName(tag.name),
                .payloads = ids.patSpan(tag.payloads),
            } },
            .nominal => |pat| .{ .nominal = ids.pat(pat) },
            .int_lit => |value| .{ .int_lit = value },
            .dec_lit => |value| .{ .dec_lit = value },
            .frac_f32_lit => |value| .{ .frac_f32_lit = value },
            .frac_f64_lit => |value| .{ .frac_f64_lit = value },
            .str_lit => |literal| .{ .str_lit = ids.stringLiteral(literal) },
            .str_pattern => |pattern| .{ .str_pattern = .{
                .prefix = ids.stringLiteral(pattern.prefix),
                .steps = ids.strPatternStepSpan(pattern.steps),
                .end = pattern.end,
            } },
        };
    }

    fn sealCoreReturn(ids: FinalIdOffsets, committed_types: *CommittedGraphTypes, ret: DraftReturn) Allocator.Error!Ast.Return {
        return .{
            .value = ids.expr(ret.value),
            .target = try ret.target.sealCommitted(committed_types),
        };
    }

    fn sealedNominalConstructionLayer(program: *const Ast.Program, ty: Type.TypeId) ?SealedNominalConstructionLayer {
        return nominalConstructionLayerIn(SealedNominalConstructionLayer, &program.types, ty);
    }

    fn sealConstructorExprWithNominalBackings(
        program: *Ast.Program,
        pending: *std.ArrayList(PendingSealedExpr),
        pending_start: u32,
        ty: Type.TypeId,
        data: Ast.ExprData,
        loc: base.SourceLoc,
        region: base.Region,
    ) Allocator.Error!Ast.Expr {
        return switch (data) {
            .tag, .record, .tuple => try BodyDraftStore.sealConstructorExprWithNominalBackingsInner(
                program,
                pending,
                pending_start,
                ty,
                data,
                loc,
                region,
            ),
            .local,
            .unit,
            .@"unreachable",
            .int_lit,
            .frac_f32_lit,
            .frac_f64_lit,
            .dec_lit,
            .str_lit,
            .bytes_lit,
            .static_data_candidate,
            .comptime_value,
            .typed_boundary,
            .list,
            .record_update,
            .nominal,
            .let_,
            .lambda,
            .def_ref,
            .fn_def,
            .fn_ref,
            .call_value,
            .call_proc,
            .low_level,
            .field_access,
            .tuple_access,
            .structural_eq,
            .structural_hash,
            .match_,
            .if_,
            .uninitialized,
            .uninitialized_payload,
            .if_initialized_payload,
            .try_sequence,
            .try_record_sequence,
            .block,
            .loop_,
            .break_,
            .continue_,
            .join_point,
            .jump,
            .return_,
            .crash,
            .checked_error,
            .comptime_branch_taken,
            .comptime_exhaustiveness_failed,
            .dbg,
            .expect_err,
            .literal_rejected,
            .expect,
            => .{ .ty = ty, .data = data },
        };
    }

    fn sealConstructorExprWithNominalBackingsInner(
        program: *Ast.Program,
        pending: *std.ArrayList(PendingSealedExpr),
        pending_start: u32,
        ty: Type.TypeId,
        data: Ast.ExprData,
        loc: base.SourceLoc,
        region: base.Region,
    ) Allocator.Error!Ast.Expr {
        const layer = BodyDraftStore.sealedNominalConstructionLayer(program, ty) orelse
            return .{ .ty = ty, .data = data };
        const backing_expr = try BodyDraftStore.sealConstructorExprWithNominalBackingsInner(
            program,
            pending,
            pending_start,
            layer.backing,
            data,
            loc,
            region,
        );
        const backing_id: Ast.ExprId = @fromBackingInt(@intCast(pending_start + @as(u32, @intCast(pending.items.len))));
        try pending.append(program.allocator, .{
            .expr = backing_expr,
            .loc = loc,
            .region = region,
        });
        return .{ .ty = layer.named, .data = .{ .nominal = backing_id } };
    }

    fn sealCallCaptureOperandSpan(
        self: *const BodyDraftStore,
        program: *Ast.Program,
        ids: FinalIdOffsets,
        span: DraftSpan(DraftExprId),
    ) Allocator.Error!Ast.Span(Ast.CaptureOperand) {
        if (span.len == 0) return Ast.Span(Ast.CaptureOperand).empty();
        if (span.start > self.expr_ids.items.len or span.len > self.expr_ids.items.len - span.start) {
            Common.invariant("Monotype body draft call capture span was out of bounds");
        }

        const operands = try program.allocator.alloc(Ast.CaptureOperand, span.len);
        defer program.allocator.free(operands);

        for (self.expr_ids.items[span.start..][0..span.len], operands) |draft_value, *operand| {
            const raw_expr = @backingInt(draft_value);
            if (raw_expr >= self.exprs.items.len) {
                Common.invariant("Monotype direct-call capture referenced an unknown expression");
            }
            const draft_local = switch (self.exprs.items[raw_expr].data) {
                .local => |local| local,
                .unit,
                .pending_deferred,
                .@"unreachable",
                .int_lit,
                .frac_f32_lit,
                .frac_f64_lit,
                .dec_lit,
                .str_lit,
                .bytes_lit,
                .static_data_candidate,
                .comptime_value,
                .list,
                .tuple,
                .record,
                .record_update,
                .tag,
                .nominal,
                .let_,
                .lambda,
                .def_ref,
                .fn_def,
                .fn_ref,
                .call_value,
                .call_proc,
                .low_level,
                .field_access,
                .tuple_access,
                .structural_eq,
                .structural_hash,
                .match_,
                .if_,
                .uninitialized,
                .uninitialized_payload,
                .if_initialized_payload,
                .try_sequence,
                .try_record_sequence,
                .block,
                .loop_,
                .break_,
                .continue_,
                .join_point,
                .jump,
                .return_,
                .crash,
                .checked_error,
                .comptime_branch_taken,
                .comptime_exhaustiveness_failed,
                .dbg,
                .expect_err,
                .literal_rejected,
                .expect,
                => Common.invariant("Monotype direct-call capture operand was not a local expression"),
            };
            const local = program.getLocal(ids.local(draft_local));
            const id = local.checked_capture_id orelse local.capture_id orelse
                Common.invariant("Monotype direct-call capture local had no capture identity");
            operand.* = .{
                .id = id,
                .value = ids.expr(draft_value),
            };
        }

        return try program.addCaptureOperandSpan(operands);
    }

    fn sealCoreExprData(
        self: *const BodyDraftStore,
        program: *Ast.Program,
        ids: FinalIdOffsets,
        committed_types: *CommittedGraphTypes,
        static_data_ids: []const Common.StaticDataId,
        comptime_roots: *collections.DenseMap(DraftComptimeValueRootId, Common.ComptimeValueRootId),
        data: DraftExprData,
    ) Allocator.Error!Ast.ExprData {
        return switch (data) {
            .local => |local| .{ .local = ids.local(local) },
            .unit => .unit,
            .int_lit => |value| .{ .int_lit = value },
            .frac_f32_lit => |value| .{ .frac_f32_lit = value },
            .frac_f64_lit => |value| .{ .frac_f64_lit = value },
            .dec_lit => |value| .{ .dec_lit = value },
            .str_lit => |literal| .{ .str_lit = ids.stringLiteral(literal) },
            .bytes_lit => |literal| .{ .bytes_lit = .{
                .literal = ids.stringLiteral(literal.literal),
                .len = literal.len,
                .element = literal.element,
                .product_width = literal.product_width,
            } },
            .comptime_value => |value| .{ .comptime_value = .{
                .root = try self.commitComptimeValueRoot(program, comptime_roots, value.root),
                .initializer = ids.expr(value.initializer),
            } },
            .static_data_candidate => |candidate| blk: {
                const index = @backingInt(candidate.static_data);
                if (index >= static_data_ids.len) {
                    Common.invariant("Monotype body draft static-data request was not committed");
                }
                break :blk .{ .static_data_candidate = .{
                    .static_data = static_data_ids[index],
                    .storage = candidate.storage,
                    .runtime_expr = ids.expr(candidate.runtime_expr),
                } };
            },
            .list => |span| .{ .list = ids.exprSpan(span) },
            .tuple => |span| .{ .tuple = ids.exprSpan(span) },
            .record => |span| .{ .record = ids.fieldExprSpan(span) },
            .record_update => |update| .{ .record_update = .{
                .base = ids.expr(update.base),
                .fields = ids.fieldExprSpan(update.fields),
            } },
            .tag => |tag| .{ .tag = .{
                .name = try committed_types.commitTagName(tag.name),
                .payloads = ids.exprSpan(tag.payloads),
            } },
            .nominal => |expr| .{ .nominal = ids.expr(expr) },
            .let_ => |let_| .{ .let_ = .{
                .bind = ids.pat(let_.bind),
                .value = ids.expr(let_.value),
                .rest = ids.expr(let_.rest),
                .comptime_site = if (let_.comptime_site) |site| ids.comptimeSite(site) else null,
            } },
            .lambda => |lambda| .{ .lambda = .{
                .fn_id = ids.fnTarget(lambda.fn_id),
                .args = ids.typedLocalSpan(lambda.args),
                .body = ids.expr(lambda.body),
            } },
            .def_ref => |def| .{ .def_ref = ids.defTarget(def) },
            .fn_def => |fn_def| .{ .fn_def = .{
                .fn_id = ids.fnTarget(fn_def.fn_id),
                .captures = ids.fnDefCaptureSpan(fn_def.captures),
            } },
            .fn_ref => |fn_ref| .{ .fn_ref = fn_ref },
            .call_value => |call| .{ .call_value = .{
                .callee = ids.expr(call.callee),
                .args = ids.exprSpan(call.args),
            } },
            .call_proc => |call| .{ .call_proc = .{
                .callee = ids.procCallee(call.callee),
                .args = ids.exprSpan(call.args),
                .iterator_procedure = call.iterator_procedure,
                .captures = try self.sealCallCaptureOperandSpan(program, ids, call.captures),
                .is_cold = call.is_cold,
            } },
            .low_level => |call| .{ .low_level = .{
                .op = call.op,
                .args = ids.exprSpan(call.args),
            } },
            .field_access => |access| .{ .field_access = .{
                .receiver = ids.expr(access.receiver),
                .segments = ids.fieldAccessSegmentSpan(access.segments),
            } },
            .tuple_access => |access| .{ .tuple_access = .{
                .tuple = ids.expr(access.tuple),
                .elem_index = access.elem_index,
            } },
            .structural_eq => |eq| .{ .structural_eq = .{
                .lhs = ids.expr(eq.lhs),
                .rhs = ids.expr(eq.rhs),
                .negated = eq.negated,
            } },
            .structural_hash => |hash| .{ .structural_hash = .{
                .value = ids.expr(hash.value),
                .hasher = ids.expr(hash.hasher),
            } },
            .match_ => |match_| .{ .match_ = .{
                .scrutinee = ids.expr(match_.scrutinee),
                .branches = ids.branchSpan(match_.branches),
                .comptime_site = if (match_.comptime_site) |site| ids.comptimeSite(site) else null,
            } },
            .if_ => |if_| .{ .if_ = .{
                .branches = ids.ifBranchSpan(if_.branches),
                .final_else = ids.expr(if_.final_else),
            } },
            .pending_deferred => Common.invariant("pending deferred expression reached Monotype body sealing"),
            .@"unreachable" => .@"unreachable",
            .uninitialized => .uninitialized,
            .uninitialized_payload => |payload| .{ .uninitialized_payload = .{
                .condition = ids.local(payload.condition),
                .mask = payload.mask,
            } },
            .if_initialized_payload => |payload| .{ .if_initialized_payload = .{
                .cond = ids.expr(payload.cond),
                .cond_mask = payload.cond_mask,
                .payload = ids.local(payload.payload),
                .uninitialized_is_cold = payload.uninitialized_is_cold,
                .initialized = ids.expr(payload.initialized),
                .uninitialized = ids.expr(payload.uninitialized),
            } },
            .try_sequence => |try_| .{ .try_sequence = .{
                .try_expr = ids.expr(try_.try_expr),
                .ok_local = ids.local(try_.ok_local),
                .err_is_cold = try_.err_is_cold,
                .err_target = if (try_.err_target) |target| @fromBackingInt(@intCast(@backingInt(ids.expr(target)))) else null,
                .ok_body = ids.expr(try_.ok_body),
            } },
            .try_record_sequence => |try_| .{ .try_record_sequence = .{
                .try_expr = ids.expr(try_.try_expr),
                .value_local = ids.local(try_.value_local),
                .value_field = try committed_types.commitRecordFieldName(try_.value_field),
                .rest_local = ids.local(try_.rest_local),
                .rest_field = try committed_types.commitRecordFieldName(try_.rest_field),
                .err_is_cold = try_.err_is_cold,
                .err_target = if (try_.err_target) |target| @fromBackingInt(@intCast(@backingInt(ids.expr(target)))) else null,
                .ok_body = ids.expr(try_.ok_body),
            } },
            .block => |block| .{ .block = .{
                .statements = self.stmtSpan(ids, block.statements),
                .final_expr = ids.expr(block.final_expr),
            } },
            .loop_ => |loop| .{ .loop_ = .{
                .params = ids.typedLocalSpan(loop.params),
                .initial_values = ids.exprSpan(loop.initial_values),
                .body = ids.expr(loop.body),
            } },
            .break_ => |break_| .{ .break_ = if (break_) |expr| ids.expr(expr) else null },
            .continue_ => |continue_| .{ .continue_ = .{
                .values = ids.exprSpan(continue_.values),
            } },
            .join_point => |join_point| .{ .join_point = .{
                .id = @fromBackingInt(@intCast(@backingInt(ids.expr(join_point.id)))),
                .params = ids.typedLocalSpan(join_point.params),
                .retained = ids.typedLocalSpan(join_point.retained),
                .body = ids.expr(join_point.body),
                .remainder = ids.expr(join_point.remainder),
            } },
            .jump => |jump| .{ .jump = .{
                .target = @fromBackingInt(@intCast(@backingInt(ids.expr(jump.target)))),
                .args = ids.exprSpan(jump.args),
                .loop_params = ids.typedLocalSpan(jump.loop_params),
                .loop_values = ids.exprSpan(jump.loop_values),
            } },
            .return_ => |ret| .{ .return_ = try BodyDraftStore.sealCoreReturn(ids, committed_types, ret) },
            .crash => |literal| .{ .crash = ids.stringLiteral(literal) },
            .checked_error => |literal| .{ .checked_error = ids.stringLiteral(literal) },
            .comptime_branch_taken => |taken| .{ .comptime_branch_taken = .{
                .site = ids.comptimeSite(taken.site),
                .branch_index = taken.branch_index,
                .body = ids.expr(taken.body),
            } },
            .comptime_exhaustiveness_failed => |site| .{ .comptime_exhaustiveness_failed = ids.comptimeSite(site) },
            .dbg => |expr| .{ .dbg = ids.expr(expr) },
            .expect_err => |expect_err| .{ .expect_err = .{
                .msg = ids.expr(expect_err.msg),
                .region = expect_err.region,
            } },
            .expect => |expr| .{ .expect = ids.expr(expr) },
            .literal_rejected => |rejected| .{ .literal_rejected = .{
                .msg = ids.expr(rejected.msg),
                .site = rejected.site,
            } },
        };
    }

    fn sealCoreStmt(ids: FinalIdOffsets, committed_types: *CommittedGraphTypes, stmt: DraftStmt) Allocator.Error!Ast.Stmt {
        return switch (stmt) {
            .uninitialized => |pat| .{ .uninitialized = ids.pat(pat) },
            .let_ => |let_| .{ .let_ = .{
                .pat = ids.pat(let_.pat),
                .value = ids.expr(let_.value),
                .recursive = let_.recursive,
                .comptime_site = if (let_.comptime_site) |site| ids.comptimeSite(site) else null,
            } },
            .expr => |expr| .{ .expr = ids.expr(expr) },
            .expect => |expr| .{ .expect = ids.expr(expr) },
            .dbg => |expr| .{ .dbg = ids.expr(expr) },
            .return_ => |ret| .{ .return_ = try BodyDraftStore.sealCoreReturn(ids, committed_types, ret) },
            .crash => |literal| .{ .crash = ids.stringLiteral(literal) },
            .checked_error => |literal| .{ .checked_error = ids.stringLiteral(literal) },
        };
    }

    fn stmtSpan(_: *const BodyDraftStore, ids: FinalIdOffsets, span: DraftSpan(DraftStmtId)) Ast.Span(Ast.StmtId) {
        return ids.stmtSpan(span);
    }
};

test "ordered worker-local symbol relocation reserves distinct deterministic domains" {
    const allocator = std.testing.allocator;
    var first = BodyDraftStore.init(allocator);
    defer first.deinit();
    var second = BodyDraftStore.init(allocator);
    defer second.deinit();

    var first_symbols: Common.SymbolGen = .{};
    var second_symbols: Common.SymbolGen = .{};
    try first.locals.append(allocator, .{
        .id = @fromBackingInt(@intCast(@as(u32, @intCast(first.locals.items.len)))),
        .symbol = first_symbols.fresh(),
        .ty = undefined,
    });
    try second.locals.append(allocator, .{
        .id = @fromBackingInt(@intCast(@as(u32, @intCast(second.locals.items.len)))),
        .symbol = second_symbols.fresh(),
        .ty = undefined,
    });
    first.sealWorkerLocalSymbols(1);
    second.sealWorkerLocalSymbols(1);

    var coordinator = Common.SymbolGen{ .next = 41 };
    first.relocateWorkerLocalSymbols(&coordinator);
    second.relocateWorkerLocalSymbols(&coordinator);

    try std.testing.expectEqual(@as(u32, 41), @backingInt(first.locals.items[0].symbol));
    try std.testing.expectEqual(@as(u32, 42), @backingInt(second.locals.items[0].symbol));
    try std.testing.expectEqual(@as(u32, 43), coordinator.next);
    try std.testing.expectEqual(SymbolDomain.coordinator, first.symbol_domain);
    try std.testing.expectEqual(SymbolDomain.coordinator, second.symbol_domain);
}

const FinalIdOffsets = struct {
    const CoreIdMode = union(enum) {
        identity,
        remapped: *const Builder.DraftCoreMaps,
    };

    fn_start: u32,
    def_start: u32,
    nested_def_start: u32,
    expr_start: u32,
    pat_start: u32,
    stmt_start: u32,
    local_start: u32,
    string_literal_start: u32,
    comptime_site_start: u32,
    expr_ids_start: u32,
    pat_ids_start: u32,
    typed_locals_start: u32,
    stmt_ids_start: u32,
    field_expr_start: u32,
    field_access_segment_start: u32,
    fn_def_capture_start: u32,
    record_destruct_start: u32,
    str_pattern_step_start: u32,
    branch_start: u32,
    if_branch_start: u32,
    fn_slots: []const ?Ast.FnSlot = &.{},
    def_ids: []const ?Ast.DefId = &.{},
    /// Literal root definitions this draft converts at a type an earlier
    /// commit already owns a root for, mapped to that root's definition.
    shared_literal_root_defs: ?*const collections.DenseMap(DraftDefId, Ast.DefId) = null,
    core_id_mode: CoreIdMode,

    fn core(self: FinalIdOffsets, kind: DraftCoreKind, raw: u32, identity_start: u32) u32 {
        return switch (self.core_id_mode) {
            .identity => identity_start + raw,
            .remapped => |maps| blk: {
                const mapped = maps.values[@backingInt(kind)][raw];
                if (mapped == std.math.maxInt(u32)) {
                    Common.invariant("retained body draft content referenced suppressed owned content");
                }
                break :blk mapped;
            },
        };
    }

    fn retained(self: FinalIdOffsets, kind: DraftCoreKind, index: usize) bool {
        return switch (self.core_id_mode) {
            .identity => true,
            .remapped => |maps| maps.retained(kind, index),
        };
    }

    fn coreSpanStart(self: FinalIdOffsets, kind: DraftCoreKind, start: u32, len: u32, identity_start: u32) u32 {
        if (len == 0) return 0;
        const mapped_start = self.core(kind, start, identity_start);
        var offset: u32 = 1;
        while (offset < len) : (offset += 1) {
            if (self.core(kind, start + offset, identity_start) != mapped_start + offset) {
                Common.invariant("retained body draft span was not one contiguous ownership range");
            }
        }
        return mapped_start;
    }

    fn fn_(self: FinalIdOffsets, id: DraftFnId) Ast.FnId {
        if (self.fn_slots.len != 0) return switch (self.fn_slots[@backingInt(id)] orelse
            Common.invariant("unreachable draft function required a final function id")) {
            .local => |fn_id| fn_id,
        };
        return @fromBackingInt(@intCast(self.fn_start + @backingInt(id)));
    }

    fn fnSlot(self: FinalIdOffsets, id: DraftFnId) Ast.FnSlot {
        if (self.fn_slots.len != 0) return self.fn_slots[@backingInt(id)] orelse
            Common.invariant("unreachable draft function required a final function slot");
        return .{ .local = @fromBackingInt(@intCast(self.fn_start + @backingInt(id))) };
    }

    fn hasFnSlot(self: FinalIdOffsets, id: DraftFnId) bool {
        return self.fn_slots.len == 0 or self.fn_slots[@backingInt(id)] != null;
    }

    fn fnTarget(self: FinalIdOffsets, id: DraftFnTarget) Ast.FnId {
        return switch (id) {
            .draft => |draft| self.fn_(draft),
            .final => |final| final,
        };
    }

    fn def(self: FinalIdOffsets, id: DraftDefId) Ast.DefId {
        if (self.shared_literal_root_defs) |shared| if (shared.get(id)) |root_def| return root_def;
        if (self.def_ids.len != 0) return self.def_ids[@backingInt(id)] orelse
            Common.invariant("draft definition required a local id after its function converged to an imported specialization");
        return @fromBackingInt(@intCast(self.def_start + @backingInt(id)));
    }

    fn defTarget(self: FinalIdOffsets, id: DraftDefTarget) Ast.DefId {
        return switch (id) {
            .draft => |draft| self.def(draft),
            .final => |final| final,
        };
    }

    fn expr(self: FinalIdOffsets, id: DraftExprId) Ast.ExprId {
        return @fromBackingInt(@intCast(self.core(.exprs, @backingInt(id), self.expr_start)));
    }

    fn pat(self: FinalIdOffsets, id: DraftPatId) Ast.PatId {
        return @fromBackingInt(@intCast(self.core(.pats, @backingInt(id), self.pat_start)));
    }

    fn stmt(self: FinalIdOffsets, id: DraftStmtId) Ast.StmtId {
        return @fromBackingInt(@intCast(self.core(.stmts, @backingInt(id), self.stmt_start)));
    }

    fn local(self: FinalIdOffsets, id: DraftLocalId) Ast.LocalId {
        return @fromBackingInt(@intCast(self.core(.locals, @backingInt(id), self.local_start)));
    }

    fn stringLiteral(self: FinalIdOffsets, id: DraftStringLiteralId) Ast.StringLiteralId {
        return @fromBackingInt(@intCast(self.core(.string_literals, @backingInt(id), self.string_literal_start)));
    }

    fn comptimeSite(self: FinalIdOffsets, id: DraftComptimeSiteId) Ast.ComptimeSiteId {
        return @fromBackingInt(@intCast(self.core(.comptime_sites, @backingInt(id), self.comptime_site_start)));
    }

    fn exprSpan(self: FinalIdOffsets, span: DraftSpan(DraftExprId)) Ast.Span(Ast.ExprId) {
        return .{ .start = self.coreSpanStart(.expr_ids, span.start, span.len, self.expr_ids_start), .len = span.len };
    }

    fn patSpan(self: FinalIdOffsets, span: DraftSpan(DraftPatId)) Ast.Span(Ast.PatId) {
        return .{ .start = self.coreSpanStart(.pat_ids, span.start, span.len, self.pat_ids_start), .len = span.len };
    }

    fn typedLocalSpan(self: FinalIdOffsets, span: DraftSpan(DraftTypedLocal)) Ast.Span(Ast.TypedLocal) {
        return .{ .start = self.coreSpanStart(.typed_locals, span.start, span.len, self.typed_locals_start), .len = span.len };
    }

    fn stmtSpan(self: FinalIdOffsets, span: DraftSpan(DraftStmtId)) Ast.Span(Ast.StmtId) {
        return .{ .start = self.coreSpanStart(.stmt_ids, span.start, span.len, self.stmt_ids_start), .len = span.len };
    }

    fn fieldExprSpan(self: FinalIdOffsets, span: DraftSpan(DraftFieldExpr)) Ast.Span(Ast.FieldExpr) {
        return .{ .start = self.coreSpanStart(.field_exprs, span.start, span.len, self.field_expr_start), .len = span.len };
    }

    fn fieldAccessSegmentSpan(
        self: FinalIdOffsets,
        span: DraftSpan(DraftFieldAccessSegment),
    ) Ast.Span(Ast.FieldAccessSegment) {
        return .{ .start = self.field_access_segment_start + span.start, .len = span.len };
    }

    fn fnDefCaptureSpan(self: FinalIdOffsets, span: DraftSpan(DraftFnDefCapture)) Ast.Span(Ast.FnDefCapture) {
        return .{ .start = self.coreSpanStart(.fn_def_captures, span.start, span.len, self.fn_def_capture_start), .len = span.len };
    }

    fn recordDestructSpan(self: FinalIdOffsets, span: DraftSpan(DraftRecordDestruct)) Ast.Span(Ast.RecordDestruct) {
        return .{ .start = self.coreSpanStart(.record_destructs, span.start, span.len, self.record_destruct_start), .len = span.len };
    }

    fn strPatternStepSpan(self: FinalIdOffsets, span: DraftSpan(DraftStrPatternStep)) Ast.Span(Ast.StrPatternStep) {
        return .{ .start = self.coreSpanStart(.str_pattern_steps, span.start, span.len, self.str_pattern_step_start), .len = span.len };
    }

    fn branchSpan(self: FinalIdOffsets, span: DraftSpan(DraftBranch)) Ast.Span(Ast.Branch) {
        return .{ .start = self.coreSpanStart(.branches, span.start, span.len, self.branch_start), .len = span.len };
    }

    fn ifBranchSpan(self: FinalIdOffsets, span: DraftSpan(DraftIfBranch)) Ast.Span(Ast.IfBranch) {
        return .{ .start = self.coreSpanStart(.if_branches, span.start, span.len, self.if_branch_start), .len = span.len };
    }

    fn fnBody(self: FinalIdOffsets, body: DraftFnBody) Ast.FnBody {
        return switch (body) {
            .roc => |body_expr| .{ .roc = self.expr(body_expr) },
            .hosted => .hosted,
        };
    }

    fn procCallee(self: FinalIdOffsets, callee: DraftProcCallee) Ast.ProcCallee {
        return switch (callee) {
            .func => |slot| .{ .func = switch (slot) {
                .local => |fn_id| switch (fn_id) {
                    .draft => |draft| self.fnSlot(draft),
                    .final => |final| .{ .local = final },
                },
            } },
            .lifted => |lifted| .{ .lifted = lifted },
        };
    }

    /// Source locations already carry final program file ids (the program's
    /// source-file table is seeded before any body is lowered), so sealing
    /// leaves them unchanged.
    fn sourceLoc(_: FinalIdOffsets, loc: base.SourceLoc) base.SourceLoc {
        return loc;
    }
};

const FinalBodyOutputGuard = struct {
    start: FinalBodyOutputCounts,
    allowance_start: FinalBodyOutputCounts,

    const End = struct {
        counts: FinalBodyOutputCounts,
        allowance: FinalBodyOutputCounts,
    };

    fn begin(builder: *Builder) FinalBodyOutputGuard {
        return .{
            .start = FinalBodyOutputCounts.fromProgram(builder.program),
            .allowance_start = builder.final_body_output_allowance,
        };
    }

    fn end(_: FinalBodyOutputGuard, builder: *Builder) End {
        return .{
            .counts = FinalBodyOutputCounts.fromProgram(builder.program),
            .allowance = builder.final_body_output_allowance,
        };
    }

    fn assertNoFinalBodyOutput(self: FinalBodyOutputGuard, end_: End) void {
        if (end_.counts.exprs - self.start.exprs != end_.allowance.exprs - self.allowance_start.exprs) {
            Common.invariant("active Monotype lowering wrote final expressions instead of BodyDraftStore expressions");
        }
        if (end_.counts.pats - self.start.pats != end_.allowance.pats - self.allowance_start.pats) {
            Common.invariant("active Monotype lowering wrote final patterns instead of BodyDraftStore patterns");
        }
        if (end_.counts.locals - self.start.locals != end_.allowance.locals - self.allowance_start.locals) {
            Common.invariant("active Monotype lowering wrote final locals instead of BodyDraftStore locals");
        }
        if (end_.counts.typed_locals - self.start.typed_locals != end_.allowance.typed_locals - self.allowance_start.typed_locals) {
            Common.invariant("active Monotype lowering wrote final typed locals instead of BodyDraftStore typed locals");
        }
        if (end_.counts.layout_requests - self.start.layout_requests != end_.allowance.layout_requests - self.allowance_start.layout_requests) {
            Common.invariant("active Monotype lowering wrote final layout requests instead of BodyDraftStore layout requests");
        }
        if (end_.counts.runtime_schema_requests - self.start.runtime_schema_requests != end_.allowance.runtime_schema_requests - self.allowance_start.runtime_schema_requests) {
            Common.invariant("active Monotype lowering wrote final runtime schema requests instead of BodyDraftStore runtime schema requests");
        }
    }
};

fn appendRuntimeImpossibilityProof(
    draft: *BodyDraftStore,
    allocator: Allocator,
    proof: RuntimeImpossibilityProof,
) Allocator.Error!RuntimeImpossibilityProofId {
    const id: RuntimeImpossibilityProofId = @fromBackingInt(@intCast(@as(u32, @intCast(draft.impossibility_proofs.items.len))));
    try draft.impossibility_proofs.append(allocator, proof);
    return id;
}

fn anyRuntimeImpossibilityProof(
    draft: *BodyDraftStore,
    allocator: Allocator,
    candidates: []const ?RuntimeImpossibilityProofId,
) Allocator.Error!?RuntimeImpossibilityProofId {
    var active_count: usize = 0;
    var sole: RuntimeImpossibilityProofId = undefined;
    for (candidates) |candidate| if (candidate) |id| switch (draft.impossibility_proofs.items[@backingInt(id)]) {
        // `any(false, x) == x`. False proofs are represented canonically as
        // null outside the proof store, so never retain an explicit `.never`
        // leaf in a composite proof.
        .never => {},
        // `any(true, x) == true`; the remaining operands cannot affect the
        // result.
        .always => return id,
        .node, .pending, .forward, .any, .all => {
            sole = id;
            active_count += 1;
        },
    };
    return switch (active_count) {
        0 => null,
        1 => sole,
        else => blk: {
            const start: u32 = @intCast(draft.impossibility_proof_ids.items.len);
            const ids = try draft.impossibility_proof_ids.addManyAsSlice(allocator, active_count);
            var index: usize = 0;
            for (candidates) |candidate| if (candidate) |id| switch (draft.impossibility_proofs.items[@backingInt(id)]) {
                .never => {},
                .always => unreachable,
                .node, .pending, .forward, .any, .all => {
                    ids[index] = id;
                    index += 1;
                },
            };
            break :blk try appendRuntimeImpossibilityProof(draft, allocator, .{
                .any = .{ .start = start, .len = @intCast(active_count) },
            });
        },
    };
}

fn allRuntimeImpossibilityProof(
    draft: *BodyDraftStore,
    allocator: Allocator,
    candidates: []const ?RuntimeImpossibilityProofId,
) Allocator.Error!?RuntimeImpossibilityProofId {
    var active_count: usize = 0;
    var sole: RuntimeImpossibilityProofId = undefined;
    for (candidates) |candidate| {
        const id = candidate orelse return null;
        switch (draft.impossibility_proofs.items[@backingInt(id)]) {
            // `all(false, x) == false`, represented canonically as null.
            .never => return null,
            // `all(true, x) == x`.
            .always => {},
            .node, .pending, .forward, .any, .all => {
                sole = id;
                active_count += 1;
            },
        }
    }
    return switch (active_count) {
        0 => try appendRuntimeImpossibilityProof(draft, allocator, .always),
        1 => sole,
        else => blk: {
            const start: u32 = @intCast(draft.impossibility_proof_ids.items.len);
            const ids = try draft.impossibility_proof_ids.addManyAsSlice(allocator, active_count);
            var index: usize = 0;
            for (candidates) |candidate| {
                const id = candidate orelse unreachable;
                switch (draft.impossibility_proofs.items[@backingInt(id)]) {
                    .never => unreachable,
                    .always => {},
                    .node, .pending, .forward, .any, .all => {
                        ids[index] = id;
                        index += 1;
                    },
                }
            }
            break :blk try appendRuntimeImpossibilityProof(draft, allocator, .{
                .all = .{ .start = start, .len = @intCast(active_count) },
            });
        },
    };
}

