const InterfaceReplayStatus = enum { expanding, expanded, ready };

const InterfaceReplayAddress = struct {
    kind: enum { procedure, method_signature, method_contract, local_method_contract, evidence_contracts } = .procedure,
    family: DraftTemplateFamilyAddress,
    evidence_digest: [32]u8,
    /// Bucket selector over the request's exact identity bytes, which remain
    /// the collision authority.
    input_digest: [32]u8,
};

fn interfaceRequestBucket(bytes: []const u8) [32]u8 {
    var bucket = @as([32]u8, @splat(0));
    std.mem.writeInt(u64, bucket[0..8], std.hash.Wyhash.hash(0, bytes), .little);
    return bucket;
}

/// Immutable input identity and parameterized output constraints. Only settled
/// leaves refer to the owner's type store; all open cells use local indices.
const InterfaceSummaryEntry = struct {
    address: InterfaceReplayAddress,
    evidence: StoredConstFnEvidence,
    request: InterfaceConstraints.Identity,
    summary: InterfaceSummary,
};

/// A completed expansion's contribution to its request roots. An expansion
/// whose captured roots equal its captured input added no constraint, so
/// replaying it relates nothing and instantiates nothing.
const InterfaceSummary = union(enum) {
    unchanged,
    constraints: InterfaceConstraints,

    fn copy(self: InterfaceSummary, allocator: Allocator, context: anytype) Allocator.Error!InterfaceSummary {
        return switch (self) {
            .unchanged => .unchanged,
            .constraints => |constraints| .{ .constraints = try constraints.copy(allocator, context) },
        };
    }

    /// Whether two expansions of the request whose input was `input`
    /// constrain its interface identically. An unchanged summary stands for
    /// that input itself.
    fn equivalent(self: InterfaceSummary, other: InterfaceSummary, input: InterfaceConstraints, graph: *InstGraph, allocator: Allocator) Allocator.Error!bool {
        const left = switch (self) {
            .unchanged => input,
            .constraints => |constraints| constraints,
        };
        const right = switch (other) {
            .unchanged => input,
            .constraints => |constraints| constraints,
        };
        return std.mem.eql(u8, try left.equivalenceIdentityInto(graph, allocator), try right.equivalenceIdentityInto(graph, allocator));
    }
};

const InterfaceSummaryCopy = struct {
    pub fn mapScalar(_: InterfaceSummaryCopy, comptime T: type, value: T) Allocator.Error!T {
        return value;
    }
};

/// Names and settled leaves cross the same explicit domain boundary as the
/// owning worker's completed body, without sealing any unresolved cells.
const InterfaceSummaryRelocation = struct {
    source_names: *const names.NameStore,
    destination_names: *names.NameStore,
    committed: ?*CommittedGraphTypes = null,
    importing: ?*BodyContext = null,
    sealer: ?*GraphTypeFinals = null,

    pub fn mapScalar(self: InterfaceSummaryRelocation, comptime T: type, value: T) Allocator.Error!T {
        if (T == Type.TypeId) {
            if (self.sealer) |sealer| return sealer.sealType(value);
            if (self.committed) |committed| return committed.commitType(value);
            return self.importing.?.importProgramType(value);
        }
        if (self.source_names == self.destination_names) return value;
        if (T == names.ModuleIdentityId) return self.destination_names.internModuleIdentity(self.source_names.moduleIdentityBytes(value));
        if (T == names.TypeNameId) return self.destination_names.internTypeName(self.source_names.typeNameText(value));
        if (T == names.RecordFieldNameId) return self.destination_names.internRecordFieldLabel(self.source_names.recordFieldLabelText(value));
        if (T == names.TagNameId) return self.destination_names.internTagLabel(self.source_names.tagLabelText(value));
        return value;
    }
};

const InterfaceSummaryCache = struct {
    allocator: Allocator,
    evidence_arena: std.heap.ArenaAllocator,
    entries: std.ArrayList(InterfaceSummaryEntry) = .empty,
    buckets: std.AutoHashMap(InterfaceReplayAddress, std.ArrayList(u32)),

    fn init(allocator: Allocator) InterfaceSummaryCache {
        return .{
            .allocator = allocator,
            .evidence_arena = std.heap.ArenaAllocator.init(allocator),
            .buckets = std.AutoHashMap(InterfaceReplayAddress, std.ArrayList(u32)).init(allocator),
        };
    }

    fn deinit(self: *InterfaceSummaryCache) void {
        var buckets = self.buckets.valueIterator();
        while (buckets.next()) |bucket| bucket.deinit(self.allocator);
        self.buckets.deinit();
        self.entries.deinit(self.allocator);
        self.evidence_arena.deinit();
    }

    fn insert(self: *InterfaceSummaryCache, types_: *Type.Store, name_store: *const names.NameStore, entry: InterfaceSummaryEntry) Allocator.Error!InterfaceSummary {
        const bucket = try self.buckets.getOrPut(entry.address);
        if (!bucket.found_existing) bucket.value_ptr.* = .empty;
        for (bucket.value_ptr.items) |index| {
            const existing = self.entries.items[index];
            if (storedConstFnEvidenceEql(existing.evidence, entry.evidence) and
                try existing.request.eql(entry.request, types_, name_store)) return existing.summary;
        }
        try bucket.value_ptr.ensureUnusedCapacity(self.allocator, 1);
        try self.entries.ensureUnusedCapacity(self.allocator, 1);
        var owned = entry;
        const arena = self.evidence_arena.allocator();
        owned.evidence = .{
            .nodes = try arena.dupe(check.ConstStore.ConstFnEvidence, entry.evidence.nodes),
            .frames = try arena.dupe(check.ConstStore.ConstFnEvidenceFrame, entry.evidence.frames),
            .head = entry.evidence.head,
            .digest = entry.evidence.digest,
        };
        owned.request = try entry.request.copy(arena, InterfaceSummaryCopy{});
        owned.summary = try entry.summary.copy(arena, InterfaceSummaryCopy{});
        bucket.value_ptr.appendAssumeCapacity(@intCast(self.entries.items.len));
        self.entries.appendAssumeCapacity(owned);
        return owned.summary;
    }
};

const InterfaceReplayEntry = struct {
    address: InterfaceReplayAddress,
    evidence: StoredConstFnEvidence,
    /// `request.bytes[0..input_len]` identifies the captured input interface;
    /// the remaining bytes mark the checked-error substitution slots.
    request: InterfaceConstraints.Identity,
    input_len: usize,
    /// The classes the request's parametric holes stood for.
    hole_classes: []const ?NodeId,
    /// This expansion's instantiated cell for each parametric hole slot.
    hole_cells: []const NodeId,
    roots: []const NodeId,
    summary: ?InterfaceSummary = null,
    verify_summary: ?InterfaceSummary = null,
    /// The request's input, kept while `verify_summary` awaits comparison.
    verify_input: ?InterfaceConstraints = null,
    status: InterfaceReplayStatus = .expanding,
    lowlink: usize,
};

const InterfaceReplayState = struct {
    use_finished_summaries: bool = true,
    entries: std.ArrayList(InterfaceReplayEntry),
    buckets: std.AutoHashMap(InterfaceReplayAddress, std.ArrayList(u32)),
    stack: std.ArrayList(usize) = .empty,
    current: ?usize = null,

    fn init(allocator: Allocator) InterfaceReplayState {
        return .{
            .entries = .empty,
            .buckets = std.AutoHashMap(InterfaceReplayAddress, std.ArrayList(u32)).init(allocator),
        };
    }

    fn deinit(self: *InterfaceReplayState, allocator: Allocator) void {
        self.entries.deinit(allocator);
        self.stack.deinit(allocator);
        var buckets = self.buckets.valueIterator();
        while (buckets.next()) |bucket| bucket.deinit(allocator);
        self.buckets.deinit();
    }
};

const InstantiationScopeId = enum(u64) { _ };

const InstantiatedFieldKind = struct {
    id: FieldKindId,
    slot: NodeId,
    value: NodeId,
};

/// A checked root reserves graph identity only when construction re-enters it.
const InstantiatingNode = union(enum) {
    node: NodeId,
    building: ?NodeId,

    fn get(self: *InstantiatingNode, graph: *InstGraph) Allocator.Error!NodeId {
        return switch (self.*) {
            .node => |node| node,
            .building => |reserved| reserved orelse blk: {
                const node = try graph.newNode(.{ .unresolved = InstVariable.placeholder() });
                self.* = .{ .building = node };
                break :blk node;
            },
        };
    }

    fn finish(self: *InstantiatingNode, graph: *InstGraph, built: NodeId) Allocator.Error!NodeId {
        const node = if (self.building) |placeholder| blk: {
            try graph.unify(placeholder, built);
            break :blk placeholder;
        } else built;
        self.* = .{ .node = node };
        return node;
    }
};

/// Completed instantiations can be inherited by branch contexts. Construction
/// placeholders belong only to the exact instantiation scope that created them.
const InstantiatingNodeMap = struct {
    const Completed = collections.VersionedDenseMap(checked.CheckedTypeId, NodeId);
    completed: Completed,
    building: collections.DenseMap(checked.CheckedTypeId, ?NodeId),

    fn init(allocator: Allocator) InstantiatingNodeMap {
        return .{
            .completed = Completed.init(allocator),
            .building = collections.DenseMap(checked.CheckedTypeId, ?NodeId).init(allocator),
        };
    }

    fn deinit(self: *InstantiatingNodeMap) void {
        self.building.deinit();
        self.completed.deinit();
    }

    fn forkCompleted(self: *const InstantiatingNodeMap) InstantiatingNodeMap {
        return .{
            .completed = self.completed.fork(),
            .building = collections.DenseMap(checked.CheckedTypeId, ?NodeId).init(self.completed.allocator),
        };
    }

    fn get(self: *const InstantiatingNodeMap, key: checked.CheckedTypeId) ?InstantiatingNode {
        if (self.building.get(key)) |reserved| return .{ .building = reserved };
        return .{ .node = self.completed.get(key) orelse return null };
    }

    fn contains(self: *const InstantiatingNodeMap, key: checked.CheckedTypeId) bool {
        return self.get(key) != null;
    }

    fn put(self: *InstantiatingNodeMap, key: checked.CheckedTypeId, value: InstantiatingNode) Allocator.Error!void {
        switch (value) {
            .building => |reserved| {
                std.debug.assert(!self.completed.contains(key));
                try self.building.put(key, reserved);
            },
            .node => |node| {
                try self.completed.putPermanent(key, node);
                _ = self.building.remove(key);
            },
        }
    }

    fn remove(self: *InstantiatingNodeMap, key: checked.CheckedTypeId) bool {
        std.debug.assert(!self.completed.contains(key));
        return self.building.remove(key);
    }

    const ValueIterator = struct {
        completed: Completed.Iterator,
        building: collections.DenseMap(checked.CheckedTypeId, ?NodeId).ValueIterator,
        value: InstantiatingNode = undefined,

        fn next(self: *ValueIterator) ?*const InstantiatingNode {
            if (self.completed.next()) |entry| {
                self.value = .{ .node = entry.value_ptr.* };
            } else if (self.building.next()) |entry| {
                self.value = .{ .building = entry.* };
            } else return null;
            return &self.value;
        }
    };

    fn valueIterator(self: *InstantiatingNodeMap) ValueIterator {
        return .{ .completed = self.completed.iterator(), .building = self.building.valueIterator() };
    }
};

/// The complete mutable state for one checked-type instantiation scope. Body
/// lowering state remains on `BodyContext`; operations that only need a fresh
/// type instantiation can swap this small state without constructing another
/// body context.
/// How an instantiation context instantiates a closed checked type.
const ClosedTypeInstantiation = union(enum) {
    /// Its whole structure, like every other checked type.
    structure,
    /// An unread leaf of the Monotype it denotes, shared by every closed type
    /// of that Monotype the context instantiates through this leaf scope. A
    /// codec contract or structural-evidence context relates a whole checked
    /// codec shape at every boundary; only the parts of it something reads
    /// are ever built.
    leaves: solve.LeafScopeId,
    /// Learning the Monotypes closed types denote. A closed type whose
    /// Monotype is already known is a leaf in this scope; any other builds
    /// its structure and is recorded in `measured`.
    measuring: solve.LeafScopeId,
};

const TypeInstantiationContext = struct {
    allocator: Allocator,
    id: InstantiationScopeId,
    module_bytes: [32]u8,
    node_map: InstantiatingNodeMap,
    field_kind_map: collections.DenseMap(checked.CheckedTypeId, InstantiatedFieldKind),
    /// A direct call's request belongs to the same instantiation as its checked
    /// argument cells. Default materializations must not reuse a caller's or
    /// another materialization's request, even for the same checked expression.
    direct_call_requests: collections.DenseMap(checked.CheckedExprId, DirectCallRequest),
    /// Result-type reads belong to this checked-type instantiation. Imported
    /// defaults and other instantiations use independent expression-read maps.
    expr_type_reads: collections.DenseMap(checked.CheckedExprId, NodeId),
    /// Innermost-last stack of nominal-instance instantiation scopes; see
    /// instNominalBackingNode.
    decl_scopes: std.ArrayList(*InstantiatingNodeMap) = .empty,
    field_kind_decl_scopes: std.ArrayList(*collections.DenseMap(checked.CheckedTypeId, InstantiatedFieldKind)) = .empty,
    /// Nodes this scope instantiated as pure instances under its evidence
    /// (see `BodyContext.recordPureInstance`).
    pure_nodes: collections.DenseMap(NodeId, void),
    closed_types: ClosedTypeInstantiation = .structure,
    /// Closed checked types a `.measuring` context built, each with its node,
    /// in the order their builds finished.
    measured: std.ArrayList(solve.ClosedTypeBuild) = .empty,

    fn init(
        allocator: Allocator,
        id: InstantiationScopeId,
        module_bytes: [32]u8,
    ) TypeInstantiationContext {
        return .{
            .allocator = allocator,
            .id = id,
            .module_bytes = module_bytes,
            .node_map = InstantiatingNodeMap.init(allocator),
            .field_kind_map = collections.DenseMap(checked.CheckedTypeId, InstantiatedFieldKind).init(allocator),
            .direct_call_requests = collections.DenseMap(checked.CheckedExprId, DirectCallRequest).init(allocator),
            .expr_type_reads = collections.DenseMap(checked.CheckedExprId, NodeId).init(allocator),
            .pure_nodes = collections.DenseMap(NodeId, void).init(allocator),
        };
    }

    fn deinit(self: *TypeInstantiationContext) void {
        self.pure_nodes.deinit();
        self.measured.deinit(self.allocator);
        self.decl_scopes.deinit(self.allocator);
        self.field_kind_decl_scopes.deinit(self.allocator);
        self.node_map.deinit();
        self.field_kind_map.deinit();
        self.direct_call_requests.deinit();
        self.expr_type_reads.deinit();
    }
};

const ParserErrorRowKey = struct {
    source: Type.TypeId,
    target: Type.TypeId,
};

const BodyContext = struct {
    allocator: Allocator,
    builder: *Builder,
    /// Checked module whose ordered registry scope governs generated method
    /// dispatch in this specialization. This can differ from `view` when an
    /// imported template is specialized for a caller's concrete types.
    method_scope: ModuleView,
    view: ModuleView,
    /// Source-file identity for `view`, resolved once when this body context is
    /// created instead of through the draft hash table for every source node.
    source_file_id: ?u32,
    owner_template: names.ProcTemplate,
    owner_context_fn_key: names.TypeDigest,
    current_fn_key: names.TypeDigest,
    comptime_exhaustiveness_context: ExhaustivenessContext.Context,
    generated_encoder_source_fn_ty: ?checked.CheckedTypeId,
    generated_encoder_source_expr: ?checked.CheckedExprId,
    generated_encoder_lambda_index: u64,
    binders: BinderMap,
    typed_binders: TypedBinders,
    local_proc_contexts: LocalProcContexts,
    restored_local_proc_scope: ?RestoredLocalProcScope = null,
    /// The binder relations every nested context created from this one
    /// starts from (see `nestedRelationBase`).
    nested_relation_base: ?*NestedRelationBase = null,
    /// True while this context lowers a defaulted-field expression (design.md
    /// "Defaulted Fields"). Checking records nested-function sites for
    /// default expressions under the `.default_root` owner (they belong to no
    /// procedure template), so site resolution must know it is inside a
    /// default's inlined materialization rather than the consuming template's
    /// own body. Set and restored by `defaultedFieldValueAtCell`; inherited by
    /// child contexts created within the materialization.
    in_default_expr: bool = false,
    /// This specialization's type solver, shared by every instantiation
    /// context created while lowering the same specialization.
    graph: *InstGraph,
    /// Reusable recursion-path scratch for exact graph inhabitation walks.
    /// Node IDs are dense, and each walk unsets on exit, so this replaces a
    /// fresh visitation hash table per query.
    inhabitation_visiting: std.bit_set.DynamicBitSetUnmanaged,
    /// Each node being expanded by the running uninhabitedness scan, with the
    /// scan's count of unsettled encounters when it was entered.
    inhabitation_entered: std.AutoHashMapUnmanaged(NodeId, usize) = .empty,
    /// Uninhabitedness of graph roots whose whole reachable structure was
    /// settled when scanned, per backing access. Nothing can change such an
    /// answer.
    settled_node_uninhabited: [2]std.AutoHashMapUnmanaged(NodeId, bool) = .{ .empty, .empty },
    /// The stacks the uninhabitedness scans run on, kept between scans.
    node_uninhabited_scratch: NodeUninhabitedScan.Evaluation.Scratch = .{},
    pattern_uninhabited_scratch: PatternUninhabitedScan.Evaluation.Scratch = .{},
    /// Draft body output owned by this specialization graph.
    draft: *BodyDraftStore,
    /// Checked-type cache and declaration-scope stack for this exact
    /// instantiation identity. Separate contexts give every checked graph a
    /// fresh relation-production identity.
    instantiation: TypeInstantiationContext,
    loop_contexts: std.ArrayList(LoopContext),
    /// Literal sub-patterns on non-builtin number types collected while
    /// lowering a match branch's pattern; each becomes an equality condition
    /// on the branch comparing the bound value against the literal's
    /// `from_numeral`-converted constant.
    pattern_literal_guards: std.ArrayList(PatternLiteralGuard),
    /// Pending user-binder preludes from translated optional-field destructs
    /// (see `OptionalDestructBind`), drained by the same owners that drain
    /// `pattern_literal_guards`.
    optional_destruct_binds: std.ArrayList(OptionalDestructBind) = .empty,
    /// Frozen-at-creation reachability topology attached to runtime demands
    /// emitted while lowering one match branch. The root plus explicit
    /// constructor payload/element cells prove when that branch cannot run.
    runtime_demand_guard_frames: RuntimeDemandGuardFrameStack = .{},
    /// Exact argument nodes of the function body currently being lowered.
    /// If any argument finalizes as uninhabited, the body is unreachable.
    /// This callee-owned proof is separate from call-chain frame identity.
    function_entry_demand_guards: []const NodeId = &.{},
    /// A nested body's instantiation answers each enclosing quantified
    /// variable from its lexical evidence frames when it first reaches the
    /// variable (see `enclosingVariableNode`). Other contexts own their
    /// variables' cells.
    resolves_enclosing_variables: bool = false,
    /// Set on a `NestedRelationBase`'s context: every variable node its
    /// instantiation creates or resolves is recorded here, so each nested
    /// context forked from it can join its own answer for the variable.
    relation_variables: ?*std.ArrayList(InstantiatedVariable) = null,
    /// The quantified variables of a generalized scope this context is
    /// constructing: they stay fresh until the construction request
    /// determines them.
    constructing_scheme_vars: []const checked.CheckedTypeId = &.{},
    propagate_constructor_value_evidence: bool = false,
    /// One shared request interface per direct call expression of this body;
    /// see `DirectCallRequest`.
    direct_call_requests: std.AutoHashMapUnmanaged(checked.CheckedExprId, DirectCallRequest) = .empty,
    /// Constructor expressions already related to a request node, keyed by
    /// the node's class root at the time. A constructor's relation only
    /// unifies its children with the node's component slots, so relating it
    /// to the same class again adds nothing; lowering a nested constructor
    /// relates each level once instead of once per enclosing level.
    related_constructors: std.AutoHashMapUnmanaged(RelatedConstructor, void) = .empty,
    /// Exact return cell owned by the active checked lambda specialization.
    /// Source `return` expressions must consume this cell rather than create a
    /// new instantiation of the lambda's checked return type.
    current_return_target: ?ActiveReturnTarget = null,
    /// Match lowering can pre-register binder locals with graph type cells so
    /// branch bodies contribute constraints before the scrutinee is sealed.
    /// The subsequent pattern pass must attach those exact locals to the
    /// emitted patterns instead of allocating replacements.
    reuse_pre_registered_pattern_binders: bool = false,
    /// `patternNeedsExplicitBinding` answers, memoized per pattern: pattern
    /// lowering asks it at every level of a pattern tree.
    explicit_binding_memo: std.AutoHashMapUnmanaged(checked.CheckedPatternId, bool) = .empty,
    /// Match branches have their own complete pattern engine. Other callers
    /// must route recursive materialization through the shell/plan lowering.
    allow_recursive_pattern_lowering_for_match: bool = false,
    /// Structural equality types currently being expanded in this context.
    /// Seeing the same type again is a real recursive edge, which lowers to a
    /// reserved generated equality helper instead of recursively expanding AST.
    equality_expansion_stack: collections.DenseMap(Type.TypeId, void),
    /// Structural hash types currently being expanded in this context.
    /// Seeing the same type again is a real recursive edge, which lowers to a
    /// reserved generated hash helper instead of recursively expanding AST.
    hash_expansion_stack: collections.DenseMap(Type.TypeId, void),
    /// Types on the current path of a structural codec support check. A
    /// recursive nominal reaches its own type again inside its backing; that
    /// occurrence is the recursive reference, so the check answers for it
    /// from the rest of the cycle rather than walking the backing again.
    codec_support_path: collections.DenseMap(Type.TypeId, void),
    /// Frame stacks of finished instantiation runs, reused by later runs so
    /// a deep type does not regrow a stack for every instantiation.
    spare_inst_frames: std.ArrayListUnmanaged(std.ArrayList(InstFrame)) = .empty,
    inspect_defs: std.AutoHashMap(GeneratedHelperDefAddress, DraftGeneratedHelperDefEntry),
    equality_defs: std.AutoHashMap(GeneratedHelperDefAddress, DraftGeneratedHelperDefEntry),
    hash_defs: std.AutoHashMap(GeneratedHelperDefAddress, DraftGeneratedHelperDefEntry),
    encoder_defs: std.AutoHashMap(GeneratedEncoderDefAddress, DraftGeneratedHelperDefEntry),
    parser_defs: std.AutoHashMap(GeneratedParserDefAddress, DraftGeneratedHelperDefEntry),
    /// Frozen Phase-B lookup from each sealed equality component with an exact
    /// method to the procedure slot reserved while relations were still being
    /// produced.
    frozen_equality_method_calls: ?*const collections.DenseMap(Type.TypeId, DraftFnSlot) = null,
    /// Frozen Phase-B lookup from a sealed inspected nominal type to the
    /// attached `to_inspect` slot reserved while relations were still open.
    frozen_inspect_method_calls: ?*const collections.DenseMap(Type.TypeId, DraftFnSlot) = null,
    /// Exact custom parser/encoder callees prepared before the graph froze.
    /// Phase-B structural serialization may consume these sealed requests but
    /// may not instantiate or lower another checked callable.
    frozen_codec_calls: ?*const FrozenPreparedCodecCalls = null,
    /// Exact `??` field-default values pre-lowered before the graph froze.
    /// Phase-B structural parser emission consumes these finished draft
    /// expressions; it may not lower another checked default expression.
    frozen_field_defaults: ?*FrozenPreparedFieldDefaults = null,
    /// Exact checker-authored contract for the structural codec currently
    /// being prepared. Every checked type in the contract is instantiated
    /// once at the boundary; individual call preparation only selects from
    /// these graph-native identities.
    instantiated_codec_calls: std.ArrayList(InstantiatedGeneratedCodecCall) = .empty,
    /// Sealed rows are immutable. Retain each source-to-target tag mapping once
    /// per emission context; no solved-graph cache survives a solver mutation.
    parser_error_rows: std.AutoHashMapUnmanaged(ParserErrorRowKey, []const u32) = .empty,
    active_codec_contract: ?ActiveCodecContract = null,
    codec_contract_expansion_stack: std.ArrayList(CodecContractExpansion) = .empty,
    /// Final structural serialization emission consumes only durable types and
    /// exact prepared call identities instead of reconstructing checked requests.
    frozen_sealed_emission: bool = false,
    /// The one finalizer that owns Phase-B materialization for this frozen
    /// graph. Checked defaults are applied here, never by an eager consumer.
    frozen_type_finals: ?*GraphTypeFinals = null,
    /// Source region to use while inlining a compile-time const eval template.
    /// The template body can be lowered from a lookup site, but diagnostics
    /// must point at the original const root.
    source_region_override: ?base.Region = null,
    /// The specific compile-time entry root currently being lowered. Hoisted
    /// constants only count as "own" roots for this exact entry, not for every
    /// specialization of the same procedure template. Module-qualified because
    /// the root id travels through template requests into other modules'
    /// body contexts, where the same integer names an unrelated root.
    current_entry_root: ?EntryRoot = null,
    /// Whether this context lowers a lambda body nested inside the current
    /// entry root. Such a body runs only when the lambda is called, after the
    /// root's value exists, so a constant of the root's own scrutinee (a
    /// sibling name bound by the same top-level destructure) is an ordinary
    /// constant use there, restored recursively like a top-level constant.
    in_deferred_body: bool = false,
    /// An expression statement whose expression is a guarded hoisted root. Its
    /// value is discarded, so the root has nothing to restore there; the
    /// statement lowers its original expression, keeping its failure in place.
    in_place_statement_expr: ?checked.CheckedExprId = null,
    /// Generated local for the top-level constant root currently being
    /// restored. Recursive references to that exact checked const identity
    /// consume this local so the restored value becomes an explicit recursive
    /// binding instead of an unbounded chain of deferred const expansions.
    active_const_binding: ?ActiveConstBindingId = null,
    /// Evidence for the current callable's dispatch requirements (innermost
    /// vector plus lexical parents for nested local functions). Body contexts
    /// created for the same specialization (dispatch call contexts, nested
    /// non-generalized closures) share the owning specialization's chain.
    evidence: EvidenceChain,
    /// While restoring a constant's stored value at a use site, the evidence
    /// vector that use supplied for the constant's own requirements. Closures
    /// restored from the constant lower their bodies against this chain
    /// (their plans' `constraint(k)` refs index the constant's scheme).
    restore_evidence: EvidenceChain,
    /// The stored form of the last chain this body converted, which is
    /// almost always `evidence` itself: every nested procedure and body-local
    /// function created under the same chain shares one conversion instead
    /// of rebuilding and rehashing the whole chain per procedure.
    stored_evidence_cache: ?StoredEvidenceCacheEntry = null,
    /// Exact dispatch sites whose constraint evidence resolves to a checked
    /// error or unreachable value in this specialization. Monotype emits a
    /// runtime crash instead of returning a value from each such dispatch.
    /// CheckedModule dependency propagation turns these dispatch crash bits into
    /// the complete expression and statement divergence columns consumed below.
    specialization_dispatch_crashes: ?[]bool = null,
    owns_specialization_dispatch_crashes: bool = false,
    specialization_dispatch_divergence: ?checked.DispatchDivergence = null,
    borrowed_specialization_dispatch_divergence: ?*const checked.DispatchDivergence = null,
    /// While recursively restoring a stored constant, the concrete type of the
    /// whole restored value. Nested stored closures use this to instantiate the
    /// owner callable's return when synthesizing the constant scheme's evidence.
    const PatternLiteralGuard = union(enum) {
        /// The checker-produced comparison, including conversion and exact
        /// equality dispatch, reads the bound pattern value.
        condition: checked.CheckedExprId,
        /// This literal is unrepresentable at the specialized builtin type.
        never,
    };

    /// A user binder deferred while an optional destructure is translated
    /// from checked Try space into runtime slot space.
    const OptionalDestructBind = struct {
        /// The user binder's local (registered at the Try / error node).
        binder_local: DraftLocalId,
        value: union(enum) {
            /// Materialize the bound slot as a one-segment `.?` result.
            slot_to_try: struct {
                slot_local: DraftLocalId,
                slot_node: NodeId,
                try_node: NodeId,
            },
            /// Bind the constant error represented by the payload-less Missing slot.
            missing_err: struct {
                err_node: NodeId,
            },
        },
    };

    const ParserPrecomputedRecord = struct {
        renamed_field_locals: []DraftLocalId,
        renamed_field_values: []DraftExprId,
        renamed_field_lengths: ?[]u32,
        renamed_field_texts: ?[][]const u8,
    };

    const ParserPrecomputedCapture = struct {
        local: DraftLocalId,
        value: DraftExprId,
    };

    const ParserPrecomputedPlan = struct {
        allocator: Allocator,
        records: std.AutoHashMap(names.TypeDigest, ParserPrecomputedRecord),
        captures: std.ArrayList(ParserPrecomputedCapture),
        next_capture_id: usize,

        fn init(allocator: Allocator) ParserPrecomputedPlan {
            return .{
                .allocator = allocator,
                .records = std.AutoHashMap(names.TypeDigest, ParserPrecomputedRecord).init(allocator),
                .captures = .empty,
                .next_capture_id = 1,
            };
        }

        fn deinit(self: *ParserPrecomputedPlan) void {
            var records = self.records.valueIterator();
            while (records.next()) |record| {
                self.allocator.free(record.renamed_field_locals);
                self.allocator.free(record.renamed_field_values);
                if (record.renamed_field_lengths) |lengths| self.allocator.free(lengths);
                if (record.renamed_field_texts) |texts| self.allocator.free(texts);
            }
            self.records.deinit();
            self.captures.deinit(self.allocator);
        }
    };

    const SerializationPlanKind = enum { parser, encoder };

    const SerializationHelperPlan = struct {
        plan: ParserPrecomputedPlan,
        args: []BodyTypedLocal,

        fn deinit(self: *SerializationHelperPlan, allocator: Allocator) void {
            allocator.free(self.args);
            self.plan.deinit();
        }
    };

    const SerializationPlanInputs = struct {
        locals: std.ArrayList(DraftLocalId) = .empty,
        record_keys: std.AutoHashMap(names.TypeDigest, void),
        seen_types: collections.DenseMap(Type.TypeId, void),
        seen_locals: collections.DenseMap(DraftLocalId, void),

        fn init(allocator: Allocator) SerializationPlanInputs {
            return .{
                .record_keys = std.AutoHashMap(names.TypeDigest, void).init(allocator),
                .seen_types = collections.DenseMap(Type.TypeId, void).init(allocator),
                .seen_locals = collections.DenseMap(DraftLocalId, void).init(allocator),
            };
        }

        fn deinit(self: *SerializationPlanInputs, allocator: Allocator) void {
            self.seen_locals.deinit();
            self.seen_types.deinit();
            self.record_keys.deinit();
            self.locals.deinit(allocator);
        }
    };

    /// The graph owns every TypeId inspected while lowering this body.
    fn typeStore(self: *const BodyContext) *Type.Store {
        return self.graph.types;
    }

    /// Every name id read while lowering belongs to the graph's paired
    /// name store, independently of the coordinator program's name domain.
    fn nameStore(self: *const BodyContext) *const names.NameStore {
        return self.graph.name_store;
    }

    /// Body-local generated labels are interned into the mutable owner paired
    /// with the graph. `InstGraph` deliberately retains only a read capability.
    fn nameStoreMut(self: *BodyContext) *names.NameStore {
        return self.draft.mutableGraphNameStore(self.graph, self.builder.program);
    }

    /// Import a checked record label into the graph-owned name domain.
    fn recordFieldName(self: *BodyContext, view: ModuleView, id: names.RecordFieldNameId) Allocator.Error!names.RecordFieldNameId {
        return self.nameStoreMut().internRecordFieldLabel(view.names.recordFieldLabelText(id));
    }

    /// Import a checked tag label into the graph-owned name domain.
    fn tagName(self: *BodyContext, view: ModuleView, id: names.TagNameId) Allocator.Error!names.TagNameId {
        return self.nameStoreMut().internTagLabel(view.names.tagLabelText(id));
    }

    /// Import one checked nominal identity into the graph-owned name domain.
    fn typeDef(
        self: *BodyContext,
        view: ModuleView,
        origin_module: names.ModuleIdentityId,
        type_name: names.TypeNameId,
        source_decl: ?u32,
    ) Allocator.Error!Type.TypeDef {
        return .{
            .module = try self.nameStoreMut().internModuleIdentity(
                view.names.moduleIdentityBytes(origin_module),
            ),
            .type_name = try self.nameStoreMut().internTypeName(
                view.names.typeNameText(type_name),
            ),
            .source_decl = source_decl,
        };
    }

    /// Method owners derived from graph types remain qualified by the graph's
    /// name store. Private owners bypass the coordinator cache because its raw
    /// name-id keys belong exclusively to the program name domain.
    fn lookupMethodTargetByName(
        self: *BodyContext,
        owner: static_dispatch.MethodOwner,
        method_name: []const u8,
    ) Allocator.Error!?MethodLookupResult {
        if (self.nameStore() == &self.builder.program.names) {
            return self.builder.lookupMethodTargetByName(
                self.method_scope,
                owner,
                method_name,
            );
        }
        return self.builder.findMethodTargetByNameFromStore(
            self.method_scope,
            self.nameStore(),
            owner,
            method_name,
        );
    }

    /// Method owners derived from graph types remain qualified by the graph's
    /// name store, exactly as in `lookupMethodTargetByName`.
    fn lookupInspectOverride(
        self: *BodyContext,
        owner: static_dispatch.MethodOwner,
    ) Allocator.Error!?MethodLookup {
        if (self.nameStore() == &self.builder.program.names) {
            return try self.builder.lookupInspectOverride(self.method_scope, owner);
        }
        return self.builder.findInspectOverrideFromStore(self.method_scope, self.nameStore(), owner);
    }

    fn lookupMethodTarget(
        self: *BodyContext,
        owner: static_dispatch.MethodOwner,
        method_view: ModuleView,
        method: names.MethodNameId,
    ) Allocator.Error!?MethodLookupResult {
        return self.lookupMethodTargetByName(
            owner,
            method_view.names.methodNameText(method),
        );
    }

    fn namedBackingType(self: *const BodyContext, ty: Type.TypeId) ?Type.TypeId {
        return switch (self.typeStore().get(ty)) {
            .named => |named| if (named.backing) |backing| backing.ty else null,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => null,
        };
    }

    fn nominalConstructionLayer(self: *const BodyContext, ty: Type.TypeId) ?Builder.NominalConstructionLayer {
        return nominalConstructionLayerIn(Builder.NominalConstructionLayer, self.typeStore(), ty);
    }

    fn shapeContent(self: *const BodyContext, ty: Type.TypeId) Type.Content {
        var current = ty;
        while (true) {
            switch (self.typeStore().get(current)) {
                .named => |named| if (named.backing) |backing| {
                    current = backing.ty;
                    continue;
                } else {
                    return self.typeStore().get(current);
                },
                .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return self.typeStore().get(current),
            }
        }
    }

    fn functionShape(self: *const BodyContext, ty: Type.TypeId, comptime message: []const u8) FunctionShape {
        return switch (self.shapeContent(ty)) {
            .func => |func| .{ .args = func.args, .ret = func.ret },
            .primitive, .named, .record, .tuple, .tag_union, .list, .box, .erased, .zst => Common.invariant(message),
        };
    }

    fn recordFieldsSpan(self: *const BodyContext, ty: Type.TypeId) Type.Span {
        return switch (self.shapeContent(ty)) {
            .record => |fields| fields,
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("record pattern had a non-record checked type"),
        };
    }

    fn tupleItemTypes(self: *const BodyContext, ty: Type.TypeId) Type.StoreSpanBorrow(Type.TypeId, "spans") {
        return self.typeStore().span(switch (self.shapeContent(ty)) {
            .tuple => |items| items,
            .primitive, .named, .record, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("tuple pattern had a non-tuple checked type"),
        });
    }

    fn tagPayloadTypes(self: *const BodyContext, ty: Type.TypeId, name: names.TagNameId) Type.StoreSpanBorrow(Type.TypeId, "spans") {
        const tags = switch (self.shapeContent(ty)) {
            .tag_union => |tags| self.typeStore().tagSpan(tags),
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => Common.invariant("tag pattern had a non-tag-union checked type"),
        };
        for (0..GuardedList.borrowLen(tags)) |index| {
            const tag = GuardedList.at(tags, index);
            if (self.nameStore().tagLabelTextEql(tag.name, name)) return self.typeStore().span(tag.payloads);
        }
        Common.invariant("tag pattern was absent from checked tag-union type");
    }

    fn optionalFieldSlot(self: *const BodyContext, slot_ty: Type.TypeId) ?Builder.OptionalSlotInfo {
        return optionalFieldSlotForType(self.typeStore(), self.nameStore(), slot_ty);
    }

    fn specializationTypeDigest(self: *BodyContext, ty: Type.TypeId) names.TypeDigest {
        return self.builder.specializationTypeDigestIn(self.typeStore(), self.nameStore(), ty);
    }

    fn recordField(self: *const BodyContext, ty: Type.TypeId, name: names.RecordFieldNameId) Type.Field {
        return sortedRecordField(self.typeStore().fieldSpan(self.recordFieldsSpan(ty)), self.nameStore(), name);
    }

    fn tagUnionTags(self: *const BodyContext, ty: Type.TypeId) Type.StoreSpanBorrow(Type.Tag, "tags") {
        return switch (self.shapeContent(ty)) {
            .tag_union => |tags| self.typeStore().tagSpan(tags),
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => Common.invariant("tag operation expected tag-union type"),
        };
    }

    fn tagByNameOrNull(self: *const BodyContext, ty: Type.TypeId, name: names.TagNameId) ?Type.Tag {
        const tags = self.tagUnionTags(ty);
        for (0..GuardedList.borrowLen(tags)) |index| {
            const tag = GuardedList.at(tags, index);
            if (tag.name == name) return tag;
        }
        return null;
    }

    fn tagByName(self: *const BodyContext, ty: Type.TypeId, name: names.TagNameId) Type.Tag {
        return self.tagByNameOrNull(ty, name) orelse Common.invariant("tag operation referenced tag absent from Monotype type");
    }

    fn nominalExprBackingType(self: *const BodyContext, ty: Type.TypeId) ?Type.TypeId {
        return switch (self.typeStore().get(ty)) {
            .named => |named| if (named.kind != .alias) blk: {
                const backing = named.backing orelse break :blk null;
                break :blk backing.ty;
            } else null,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => null,
        };
    }

    fn optionalSlotInfo(self: *BodyContext, slot_ty: Type.TypeId) Allocator.Error!Builder.OptionalSlotInfo {
        const missing_name = try self.nameStoreMut().internTagLabel(Builder.optional_slot_missing_tag);
        const present_name = try self.nameStoreMut().internTagLabel(Builder.optional_slot_present_tag);
        const missing_tag = self.tagByNameOrNull(slot_ty, missing_name) orelse
            Common.invariant("optional field slot type had no Missing tag");
        const present_tag = self.tagByNameOrNull(slot_ty, present_name) orelse
            Common.invariant("optional field slot type had no Present tag");
        if (self.typeStore().span(missing_tag.payloads).len != 0) {
            Common.invariant("optional field slot Missing tag unexpectedly had payloads");
        }
        const present_payloads = self.typeStore().span(present_tag.payloads);
        if (present_payloads.len != 1) {
            Common.invariant("optional field slot Present tag must carry exactly one payload");
        }
        return .{
            .payload_ty = GuardedList.at(present_payloads, 0),
            .missing_tag = missing_tag,
            .present_tag = present_tag,
        };
    }

    /// Primitive construction already targets this body's active type domain.
    fn primitiveType(self: *BodyContext, primitive: Type.Primitive) Allocator.Error!Type.TypeId {
        const active_ty = try self.builder.primitiveType(primitive);
        if (self.typeStore() == self.builder.activeTypeStore()) return active_ty;
        return try self.importProgramType(active_ty);
    }

    /// Crossing from checked types into global program type production is centralized here.
    fn lowerType(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!Type.TypeId {
        return self.lowerTypeFromView(self.view, checked_ty);
    }

    fn lowerTypeFromView(
        self: *BodyContext,
        view: ModuleView,
        checked_ty: checked.CheckedTypeId,
    ) Allocator.Error!Type.TypeId {
        const active_ty = try self.builder.lowerType(view, checked_ty);
        if (self.typeStore() == self.builder.activeTypeStore()) return active_ty;
        return try self.importProgramType(active_ty);
    }

    /// Import one coordinator-owned type closure into this body's graph domain.
    /// Shared-store graphs retain the identity mapping without allocating.
    fn importProgramType(self: *BodyContext, program_ty: Type.TypeId) Allocator.Error!Type.TypeId {
        const program_types = &self.builder.program.types;
        const graph_types = self.typeStore();
        if (graph_types == program_types) return program_ty;
        const relocation = self.draft.ensureProgramTypeRelocation(
            self.graph,
            self.builder.program,
        );
        if (relocation.get(program_types, program_ty)) |mapped| return mapped;
        var imported = try graph_types.importTypes(
            self.draft.mutableGraphNameStore(self.graph, self.builder.program),
            program_types,
            &self.builder.program.names,
            relocation,
            &.{program_ty},
        );
        defer imported.deinit();
        return imported.roots[0];
    }

    /// Record a graph-qualified static-data intent without allocating a durable
    /// program id. Ordered commit seals the type and performs global interning.
    fn draftStaticDataRequest(
        self: *BodyContext,
        const_locator: checked.ConstLocator,
        node: ?checked.ConstNodeId,
        checked_type: checked.CheckedTypeId,
        ty: DraftTypeCell,
    ) Allocator.Error!DraftStaticDataId {
        const const_node = self.builder.constNode(const_locator, node);
        const address: DraftStaticDataRequestAddress = .{
            .module = const_node.module.key,
            .node = const_node.id,
            .checked_type = checked_type,
            .ty = ty,
        };
        if (self.draft.static_data_request_ids.get(address)) |existing| return existing;

        try self.draft.static_data_requests.ensureUnusedCapacity(self.allocator, 1);
        const entry = try self.draft.static_data_request_ids.getOrPut(address);
        if (entry.found_existing) return entry.value_ptr.*;
        errdefer _ = self.draft.static_data_request_ids.remove(address);
        const id: DraftStaticDataId =
            @fromBackingInt(@intCast(@as(u32, @intCast(self.draft.static_data_requests.items.len))));
        self.draft.static_data_requests.appendAssumeCapacity(.{
            .const_locator = const_locator,
            .node = node,
            .module = const_node.module.key,
            .const_node = const_node.id,
            .checked_type = checked_type,
            .ty = ty,
        });
        entry.value_ptr.* = id;
        return id;
    }

    /// Crossing from a committed function signature into the active graph is
    /// centralized here so a private graph can import it at this boundary.
    fn programFnSourceTypeNode(self: *BodyContext, final_fn: Ast.FnId) Allocator.Error!NodeId {
        const source_ty = if (self.builder.spec_job_parallel_callback) blk: {
            const root = self.builder.active_template_root orelse
                Common.invariant("worker final function reference had no reserved root");
            if (root.fn_id != final_fn) {
                Common.invariant("worker final function reference escaped its reserved root");
            }
            break :blk root.reserved_fn_ty;
        } else self.builder.program.fnSource(final_fn).mono_fn_ty;
        const ty = try self.importProgramType(source_ty);
        return self.activeNodeFromType(ty);
    }

    /// The store this scope emits restored const expressions into.
    fn constEmit(self: *BodyContext) *BodyContext {
        return self;
    }

    /// Const restoration must intern names in the body-owned destination.
    fn constNameStore(self: *BodyContext) *names.NameStore {
        return self.nameStoreMut();
    }

    /// This scope's expression-data type for restored const values.
    const ConstExprData = BodyExprData;
    const ConstExprId = DraftExprId;
    const ConstExprSpan = DraftSpan(DraftExprId);
    const ConstFieldExpr = DraftFieldExpr;
    const ConstFieldExprSpan = DraftSpan(DraftFieldExpr);

    /// This scope's mapping from a stored scalar to expression data.
    fn constScalarData(_: *BodyContext, scalar: checked.ConstScalar) ConstExprData {
        return restoreScalar(BodyExprData, scalar);
    }

    /// An empty compile-time list restores as the `with_capacity` it was
    /// evaluated with, so the first append at runtime goes in place; one
    /// evaluated with no capacity is the empty literal.
    fn constEmptyListData(self: *BodyContext, capacity: u64) Allocator.Error!ConstExprData {
        if (capacity == 0) return .{ .list = try self.addExprSpan(&[0]DraftExprId{}) };
        const requested = try self.addExpr(.{ .ty = try self.primitiveType(.u64), .data = restoreScalar(BodyExprData, .{ .u64 = capacity }) });
        return .{ .low_level = .{ .op = .list_with_capacity, .args = try self.addExprSpan(&.{requested}) } };
    }

    fn parserPlanKey(self: *BodyContext, shape_ty: Type.TypeId) names.TypeDigest {
        var hasher = TypeDigestHasher.init();
        hasher.update("roc.parser_precomputed_record");
        const fields = self.recordFieldsForShape(shape_ty);
        var count = std.mem.nativeToLittle(u32, @intCast(GuardedList.borrowLen(fields)));
        hasher.update(std.mem.asBytes(&count));
        for (0..GuardedList.borrowLen(fields)) |index| {
            const field = GuardedList.at(fields, index);
            const label = self.nameStore().recordFieldLabelText(field.name);
            var label_len = std.mem.nativeToLittle(u32, @intCast(label.len));
            hasher.update(std.mem.asBytes(&label_len));
            hasher.update(label);
        }
        return .{ .bytes = hasher.finalResult() };
    }

    fn parserPlanContains(self: *BodyContext, plan: *const ParserPrecomputedPlan, shape_ty: Type.TypeId) bool {
        return plan.records.contains(self.parserPlanKey(shape_ty));
    }

    fn parserPlanGet(self: *BodyContext, plan: *const ParserPrecomputedPlan, shape_ty: Type.TypeId) ?ParserPrecomputedRecord {
        return plan.records.get(self.parserPlanKey(shape_ty));
    }

    fn parserPlanPut(
        self: *BodyContext,
        plan: *ParserPrecomputedPlan,
        shape_ty: Type.TypeId,
        record: ParserPrecomputedRecord,
    ) Allocator.Error!void {
        try plan.records.put(self.parserPlanKey(shape_ty), record);
    }

    fn collectSerializationPlanInputs(
        self: *BodyContext,
        kind: SerializationPlanKind,
        shape_ty: Type.TypeId,
        plan: *const ParserPrecomputedPlan,
        inputs: *SerializationPlanInputs,
    ) Allocator.Error!void {
        // Every shape reachable from `shape_ty`, in source order, from an
        // explicit work list.
        var pending: std.ArrayListUnmanaged(Type.TypeId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, shape_ty);
        while (pending.pop()) |next| {
            const start = pending.items.len;
            try self.collectSerializationPlanInputsStep(kind, next, plan, inputs, &pending);
            std.mem.reverse(Type.TypeId, pending.items[start..]);
        }
    }

    /// Record one shape's plan inputs; the shapes it contains go on `pending`.
    fn collectSerializationPlanInputsStep(
        self: *BodyContext,
        kind: SerializationPlanKind,
        shape_ty: Type.TypeId,
        plan: *const ParserPrecomputedPlan,
        inputs: *SerializationPlanInputs,
        pending: *std.ArrayListUnmanaged(Type.TypeId),
    ) Allocator.Error!void {
        if (inputs.seen_types.contains(shape_ty)) return;
        try inputs.seen_types.put(shape_ty, {});

        switch (kind) {
            .parser => {
                if (self.tryNullInfo(shape_ty)) |info| {
                    return try pending.append(self.allocator, info.ok_payload_ty);
                }
                if (try self.missingTryInfo(shape_ty)) |info| {
                    return try pending.append(self.allocator, info.ok_ty);
                }
                if (self.optionalFieldSlot(shape_ty)) |slot| {
                    return try pending.append(self.allocator, slot.payload_ty);
                }
                if (self.frozenCustomCodecCallForShape(.parser, shape_ty) != null or self.scalarCodecMethodName(shape_ty, "parse_") != null) return;
            },
            .encoder => {
                if (self.tryNullInfo(shape_ty)) |info| {
                    return try pending.append(self.allocator, info.ok_payload_ty);
                }
                if (self.frozenCustomCodecCallForShape(.encoder, shape_ty) != null or self.scalarCodecMethodName(shape_ty, "encode_") != null) return;
            },
        }
        if (self.setPayloadType(shape_ty)) |payload_ty| {
            return try pending.append(self.allocator, payload_ty);
        }
        if (self.dictEntryShape(shape_ty)) |dict| {
            var dict_buf: [2]Type.TypeId = undefined;
            for (self.dictCodecShapes(dict, &dict_buf)) |dict_shape| {
                try pending.append(self.allocator, dict_shape);
            }
            return;
        }

        switch (self.shapeContent(shape_ty)) {
            .list => |elem_ty| try pending.append(self.allocator, elem_ty),
            .box => |payload_ty| try pending.append(self.allocator, payload_ty),
            .tuple => |span| {
                const item_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(span));
                defer self.allocator.free(item_tys);
                for (item_tys) |item_ty| {
                    try pending.append(self.allocator, item_ty);
                }
            },
            .record, .zst => {
                const key = self.parserPlanKey(shape_ty);
                const record = plan.records.get(key) orelse
                    Common.invariant("structural serialization helper was missing precomputed record fields");
                try inputs.record_keys.put(key, {});
                for (record.renamed_field_locals) |local| {
                    if (inputs.seen_locals.contains(local)) continue;
                    try inputs.seen_locals.put(local, {});
                    try inputs.locals.append(self.allocator, local);
                }

                const fields = try self.dupeRecordFieldsForShape(shape_ty);
                defer self.allocator.free(fields);
                for (fields) |field| {
                    const child_ty = switch (kind) {
                        .parser => field.ty,
                        .encoder => try self.encodeRecordFieldPayloadType(field.ty),
                    };
                    try pending.append(self.allocator, child_ty);
                }
            },
            .tag_union => |span| {
                const tags = try GuardedList.dupe(self.allocator, Type.Tag, self.typeStore().tagSpan(span));
                defer self.allocator.free(tags);
                for (tags) |tag| {
                    const payload_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(tag.payloads));
                    defer self.allocator.free(payload_tys);
                    for (payload_tys) |payload_ty| {
                        try pending.append(self.allocator, payload_ty);
                    }
                }
            },
            .primitive, .named, .func, .erased => {},
        }
    }

    fn serializationPlanInputs(
        self: *BodyContext,
        kind: SerializationPlanKind,
        shape_ty: Type.TypeId,
        plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!SerializationPlanInputs {
        var inputs = SerializationPlanInputs.init(self.allocator);
        errdefer inputs.deinit(self.allocator);
        if (plan) |precomputed| {
            try self.collectSerializationPlanInputs(kind, shape_ty, precomputed, &inputs);
        }
        return inputs;
    }

    fn cloneSerializationHelperPlan(
        self: *BodyContext,
        source: *const ParserPrecomputedPlan,
        inputs: *const SerializationPlanInputs,
        str_ty: Type.TypeId,
    ) Allocator.Error!SerializationHelperPlan {
        var helper = SerializationHelperPlan{
            .plan = ParserPrecomputedPlan.init(self.allocator),
            .args = try self.allocator.alloc(BodyTypedLocal, inputs.locals.items.len),
        };
        errdefer helper.deinit(self.allocator);
        helper.plan.next_capture_id = source.next_capture_id;

        var local_map = collections.DenseMap(DraftLocalId, DraftLocalId).init(self.allocator);
        defer local_map.deinit();
        var expr_map = collections.DenseMap(DraftLocalId, DraftExprId).init(self.allocator);
        defer expr_map.deinit();
        for (inputs.locals.items, 0..) |source_local, index| {
            const helper_local = try self.addLocal(self.builder.symbols.fresh(), str_ty);
            const helper_expr = try self.localExpr(helper_local, str_ty);
            try local_map.put(source_local, helper_local);
            try expr_map.put(source_local, helper_expr);
            helper.args[index] = .{ .local = helper_local, .ty = str_ty };
            try helper.plan.captures.append(self.allocator, .{
                .local = helper_local,
                .value = helper_expr,
            });
        }

        var key_iter = inputs.record_keys.keyIterator();
        while (key_iter.next()) |key| {
            const source_record = source.records.get(key.*) orelse
                Common.invariant("structural serialization helper record key was absent from source plan");
            const locals = try self.allocator.alloc(DraftLocalId, source_record.renamed_field_locals.len);
            const values = try self.allocator.alloc(DraftExprId, source_record.renamed_field_locals.len);
            var inserted = false;
            errdefer if (!inserted) {
                self.allocator.free(locals);
                self.allocator.free(values);
            };
            for (source_record.renamed_field_locals, 0..) |source_local, index| {
                const helper_local = local_map.get(source_local) orelse
                    Common.invariant("structural serialization helper record local was absent from input map");
                locals[index] = helper_local;
                values[index] = expr_map.get(source_local) orelse
                    Common.invariant("structural serialization helper record expression was absent from input map");
            }
            const lengths = if (source_record.renamed_field_lengths) |source_lengths|
                try self.allocator.dupe(u32, source_lengths)
            else
                null;
            errdefer if (!inserted) if (lengths) |owned| self.allocator.free(owned);
            const texts = if (source_record.renamed_field_texts) |source_texts|
                try self.allocator.dupe([]const u8, source_texts)
            else
                null;
            errdefer if (!inserted) if (texts) |owned| self.allocator.free(owned);
            try helper.plan.records.put(key.*, .{
                .renamed_field_locals = locals,
                .renamed_field_values = values,
                .renamed_field_lengths = lengths,
                .renamed_field_texts = texts,
            });
            inserted = true;
        }
        return helper;
    }

    const MaterializedArg = struct {
        pattern: checked.CheckedPatternId,
        value: DraftExprId,
        ty: DraftTypeCell,
    };

    const PendingMaterializedPattern = struct {
        pattern: checked.CheckedPatternId,
        local: DraftLocalId,
        cell: DraftTypeCell,
    };

    const PendingMatchRecordRestBinding = struct {
        source_local: DraftLocalId,
        source_node: NodeId,
        rest_local: DraftLocalId,
        rest_node: NodeId,
        rest_cell: DraftTypeCell,
        before_guard: bool,
    };

    const MatchPatternLowering = struct {
        guard: ?DraftExprId,
        body: DraftExprId,
        record_rests: *std.ArrayList(PendingMatchRecordRestBinding),
    };

    const LoweredMatchRecordRestBindings = struct {
        guard_bindings: DraftSpan(DraftStmtId),
        body: DraftExprId,
    };

    const PatternSuccessGuard = struct {
        root_pattern: checked.CheckedPatternId,
        root_node: NodeId,
    };

    const PatternNodeVisit = struct {
        pattern: checked.CheckedPatternId,
        node: NodeId,
    };

    const ParseRecordSlots = struct {
        presence_locals: []const DraftLocalId,
        presence_tys: []const Type.TypeId,
        payload_locals: []const DraftLocalId,
        payload_tys: []const Type.TypeId,

        fn fieldCount(self: ParseRecordSlots) usize {
            return self.payload_locals.len;
        }
    };

    /// Producer-authored control-flow for one derived record parser. All three
    /// format field-event modes route to these same field continuations, so
    /// field parsing and loop-state transition code each exist once.
    const ParseRecordContinuations = struct {
        error_join: DraftExprId,
        entry_end_join: DraftExprId,
        skip_join: DraftExprId,
        field_joins: []const DraftExprId,
    };

    /// Loop-carried control locals for a derived record parser. `done` is set
    /// when the format reports the end of the record so the next iteration
    /// finishes at the loop head, which keeps the record-construction code at
    /// exactly one site. `counted`/`remaining` drive Counted mode, where the
    /// format declared the entry count up front and the driver never calls
    /// `parse_record_after_field`.
    const RecordLoopCtl = struct {
        done_local: DraftLocalId,
        counted_local: DraftLocalId,
        remaining_local: DraftLocalId,
        bool_ty: Type.TypeId,
        u64_ty: Type.TypeId,
    };

    /// Loop-carried control locals for a derived list parser. In Counted mode
    /// the format declared the element count up front, so the driver reads
    /// exactly `remaining` more elements and never calls `parse_list_next` or
    /// `parse_list_after_item`.
    /// How a dict entry ends: `uncounted` asks the format whether more entries
    /// follow, `counted` re-enters the loop with one fewer entry left.
    const DictEntryEndMode = enum { counted, uncounted };

    const ListLoopCtl = struct {
        counted_local: DraftLocalId,
        remaining_local: DraftLocalId,
        bool_ty: Type.TypeId,
        u64_ty: Type.TypeId,
    };

    /// Loop params before the payload slots: cursor, done, counted, remaining.
    const record_loop_slot_offset = 4;

    const BindingContinuation = union(enum) {
        expr: DraftExprId,
        materialized_args: struct {
            args: []const MaterializedArg,
            index: usize,
            lambda: checked.CheckedExprId,
            body: checked.CheckedExprId,
        },
        iterator_body: struct {
            body: checked.CheckedExprId,
            result_cell: DraftTypeCell,
            rest_expr: DraftExprId,
            carries: []const LoopCarry,
        },
    };

    const CurrentLocal = struct {
        binder: checked.PatternBinderId,
        local: DraftLocalId,
    };

    fn typedBinder(self: *BodyContext, binder: checked.PatternBinderId, ty: Type.TypeId) TypedBinder {
        return .{
            .binder = binder,
            .type_digest = self.typeStore().typeDigest(self.nameStore(), ty),
        };
    }

    fn putTypedBinder(
        self: *BodyContext,
        binder: checked.PatternBinderId,
        ty: Type.TypeId,
        local: DraftLocalId,
    ) Allocator.Error!?DraftLocalId {
        const key = self.typedBinder(binder, ty);
        const previous = self.typed_binders.get(key);
        try self.typed_binders.put(key, local);
        return previous;
    }

    /// Put `binder` back to the local it named before a scoped rebinding, or
    /// unbind it when it named none.
    fn restoreBinder(self: *BodyContext, binder: checked.PatternBinderId, previous: ?DraftLocalId) void {
        if (previous) |local| {
            self.binders.restore(binder, local);
        } else {
            _ = self.binders.remove(binder);
        }
    }

    /// Undo the binder and typed-binder bindings of restored constant
    /// captures, most recent first. Each capture carries the `binder` it
    /// bound, the `ty` it was bound at, and what both bindings named before
    /// (`previous`, `previous_typed`).
    fn unbindConstCaptures(self: *BodyContext, captures: anytype) void {
        var index = captures.len;
        while (index > 0) {
            index -= 1;
            self.restoreTypedBinder(captures[index].binder, captures[index].ty, captures[index].previous_typed);
            self.restoreBinder(captures[index].binder, captures[index].previous);
        }
    }

    fn restoreTypedBinder(
        self: *BodyContext,
        binder: checked.PatternBinderId,
        ty: Type.TypeId,
        previous: ?DraftLocalId,
    ) void {
        const key = self.typedBinder(binder, ty);
        if (previous) |local| {
            self.typed_binders.restore(key, local);
        } else {
            _ = self.typed_binders.remove(key);
        }
    }

    fn init(
        allocator: Allocator,
        builder: *Builder,
        view: ModuleView,
        owner_template: names.ProcTemplate,
        graph: *InstGraph,
        draft: *BodyDraftStore,
    ) Allocator.Error!BodyContext {
        return try initWithMethodScope(allocator, builder, view, view, owner_template, graph, draft);
    }

    fn initWithMethodScope(
        allocator: Allocator,
        builder: *Builder,
        view: ModuleView,
        method_scope: ModuleView,
        owner_template: names.ProcTemplate,
        graph: *InstGraph,
        draft: *BodyDraftStore,
    ) Allocator.Error!BodyContext {
        var ctx = try initBodyState(allocator, builder, view, owner_template, graph, draft);
        errdefer ctx.deinit();
        ctx.method_scope = method_scope;
        ctx.source_file_id = builder.sourceFileId(view);
        return ctx;
    }

    /// Construct the operational state for a body-lowering context. Dense
    /// binder state remains lazy, and fresh type-only work uses
    /// `TypeInstantiationContext` directly.
    fn initBodyState(
        allocator: Allocator,
        builder: *Builder,
        view: ModuleView,
        owner_template: names.ProcTemplate,
        graph: *InstGraph,
        draft: *BodyDraftStore,
    ) Allocator.Error!BodyContext {
        builder.countBodyDiagnostic("body_contexts_created");
        return .{
            .allocator = allocator,
            .builder = builder,
            .method_scope = view,
            .view = view,
            .source_file_id = null,
            .owner_template = owner_template,
            .owner_context_fn_key = .{},
            .current_fn_key = .{},
            .comptime_exhaustiveness_context = .{},
            .generated_encoder_source_fn_ty = null,
            .generated_encoder_source_expr = null,
            .generated_encoder_lambda_index = 0,
            .binders = try BinderMap.init(allocator, view.bodies.patternBinderCount()),
            .typed_binders = TypedBinders.init(allocator),
            .local_proc_contexts = LocalProcContexts.init(allocator),
            .graph = graph,
            .inhabitation_visiting = .{},
            .draft = draft,
            .evidence = rootEvidence(owner_template, &.{}),
            .restore_evidence = rootEvidence(owner_template, &.{}),
            .instantiation = TypeInstantiationContext.init(allocator, builder.allocateInstantiationScope(), view.key.bytes),
            .loop_contexts = .empty,
            .pattern_literal_guards = .empty,
            .equality_expansion_stack = collections.DenseMap(Type.TypeId, void).init(allocator),
            .codec_support_path = collections.DenseMap(Type.TypeId, void).init(allocator),
            .hash_expansion_stack = collections.DenseMap(Type.TypeId, void).init(allocator),
            .inspect_defs = std.AutoHashMap(GeneratedHelperDefAddress, DraftGeneratedHelperDefEntry).init(allocator),
            .equality_defs = std.AutoHashMap(GeneratedHelperDefAddress, DraftGeneratedHelperDefEntry).init(allocator),
            .hash_defs = std.AutoHashMap(GeneratedHelperDefAddress, DraftGeneratedHelperDefEntry).init(allocator),
            .encoder_defs = std.AutoHashMap(GeneratedEncoderDefAddress, DraftGeneratedHelperDefEntry).init(allocator),
            .parser_defs = std.AutoHashMap(GeneratedParserDefAddress, DraftGeneratedHelperDefEntry).init(allocator),
            .frozen_equality_method_calls = null,
            .frozen_codec_calls = null,
            .instantiated_codec_calls = .empty,
            .codec_contract_expansion_stack = .empty,
        };
    }

    fn deinit(self: *BodyContext) void {
        self.destroyNestedRelationBase();
        self.explicit_binding_memo.deinit(self.allocator);
        var error_rows = self.parser_error_rows.valueIterator();
        while (error_rows.next()) |row| self.allocator.free(row.*);
        self.parser_error_rows.deinit(self.allocator);
        if (self.specialization_dispatch_divergence) |*divergence| divergence.deinit(self.allocator);
        if (self.owns_specialization_dispatch_crashes) {
            self.allocator.free(self.specialization_dispatch_crashes.?);
        }
        self.parser_defs.deinit();
        self.encoder_defs.deinit();
        self.hash_defs.deinit();
        self.equality_defs.deinit();
        self.inspect_defs.deinit();
        self.hash_expansion_stack.deinit();
        self.equality_expansion_stack.deinit();
        self.codec_support_path.deinit();
        self.deinitSpareInstFrames();
        self.codec_contract_expansion_stack.deinit(self.allocator);
        self.instantiated_codec_calls.deinit(self.allocator);
        self.direct_call_requests.deinit(self.allocator);
        self.related_constructors.deinit(self.allocator);
        self.pattern_literal_guards.deinit(self.allocator);
        self.optional_destruct_binds.deinit(self.allocator);
        self.loop_contexts.deinit(self.allocator);
        self.inhabitation_visiting.deinit(self.allocator);
        self.inhabitation_entered.deinit(self.allocator);
        for (&self.settled_node_uninhabited) |*settled| settled.deinit(self.allocator);
        self.node_uninhabited_scratch.deinit(self.allocator);
        self.pattern_uninhabited_scratch.deinit(self.allocator);
        self.instantiation.deinit();
        self.local_proc_contexts.deinit();
        self.typed_binders.deinit();
        self.binders.deinit();
    }

    fn draftTypeCell(self: *BodyContext, ty: Type.TypeId) Allocator.Error!DraftTypeCell {
        return try DraftTypeCell.fromActiveType(self.graph, ty);
    }

    fn activeTypeFromNode(self: *BodyContext, node: NodeId) Allocator.Error!Type.TypeId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        return try self.graph.activeTypeViewForNode(node);
    }

    /// The immutable type a specialization request or a recorded
    /// specialization keys on: the active type of a resolved interface, the
    /// required-defaulted view of an interface whose only open cells are
    /// undetermined field kinds, and nothing for an interface still carrying
    /// other open evidence. Every draft-specialization lookup and memo reads
    /// both sides of a comparison through this one policy.
    fn specializationLookupTypeForNode(self: *BodyContext, node: NodeId) Allocator.Error!?Type.TypeId {
        if (try self.graph.typeIsResolved(node)) return try self.activeTypeFromNode(node);
        if (try self.graph.typeIsSpecializationDefaultable(node)) return try self.graph.specializationTypeViewForNode(node);
        return null;
    }

    fn activeTypeFromCell(self: *BodyContext, cell: DraftTypeCell) Allocator.Error!Type.TypeId {
        return switch (cell) {
            .graph_node => |node| try self.activeTypeFromNode(node),
            .sealed => |ty| ty,
        };
    }

    fn addImpossibilityProof(
        self: *BodyContext,
        proof: RuntimeImpossibilityProof,
    ) Allocator.Error!RuntimeImpossibilityProofId {
        return try appendRuntimeImpossibilityProof(self.draft, self.allocator, proof);
    }

    fn impossibilityProofSpan(
        self: *BodyContext,
        span: DraftSpan(RuntimeImpossibilityProofId),
    ) []const RuntimeImpossibilityProofId {
        if (span.start > self.draft.impossibility_proof_ids.items.len or
            span.len > self.draft.impossibility_proof_ids.items.len - span.start)
        {
            Common.invariant("runtime impossibility proof span was outside the draft proof store");
        }
        return self.draft.impossibility_proof_ids.items[span.start..][0..span.len];
    }

    /// A `.node` proof leaf, or null when the node provably can never finalize
    /// as uninhabited—such a proof could never hold, so omitting it keeps
    /// proofs and demand-guard frames down to the guards that can actually
    /// exempt something.
    fn maybeNodeImpossibilityProof(self: *BodyContext, node: NodeId) Allocator.Error!?RuntimeImpossibilityProofId {
        if (!try self.graph.mayFinalizeAsUninhabited(node)) return null;
        return try self.addImpossibilityProof(.{ .node = node });
    }

    fn alwaysImpossibilityProof(self: *BodyContext) Allocator.Error!RuntimeImpossibilityProofId {
        return try self.addImpossibilityProof(.always);
    }

    fn anyImpossibilityProof(
        self: *BodyContext,
        candidates: []const ?RuntimeImpossibilityProofId,
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
        defer timing_scope.end();
        return try anyRuntimeImpossibilityProof(self.draft, self.allocator, candidates);
    }

    fn allImpossibilityProof(
        self: *BodyContext,
        candidates: []const ?RuntimeImpossibilityProofId,
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        return try allRuntimeImpossibilityProof(self.draft, self.allocator, candidates);
    }

    fn maybeNodesImpossibilityProof(
        self: *BodyContext,
        nodes: []const NodeId,
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        var combined: ?RuntimeImpossibilityProofId = null;
        for (nodes) |node| {
            combined = try self.anyImpossibilityProof(&.{ combined, try self.maybeNodeImpossibilityProof(node) });
        }
        return combined;
    }

    fn currentRuntimeImpossibilityProof(
        self: *BodyContext,
        expression_proof: ?RuntimeImpossibilityProofId,
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        var combined: ?RuntimeImpossibilityProofId = null;
        if (self.function_entry_demand_guards.len != 0) {
            combined = try self.maybeNodesImpossibilityProof(self.function_entry_demand_guards);
        }
        var frame_id = self.runtime_demand_guard_frames.head;
        while (frame_id) |id| {
            const frame = runtimeDemandGuardFrame(self.draft, id);
            combined = try self.anyImpossibilityProof(&.{ combined, frame.proof });
            frame_id = frame.parent;
        }
        return try self.anyImpossibilityProof(&.{ combined, expression_proof });
    }

    fn exprImpossibilityProof(self: *BodyContext, expr: DraftExprId) ?RuntimeImpossibilityProofId {
        return self.draft.expr_impossibility_proofs.items[@backingInt(expr)];
    }

    fn stmtImpossibilityProof(self: *BodyContext, stmt: DraftStmtId) ?RuntimeImpossibilityProofId {
        return self.draft.stmt_impossibility_proofs.items[@backingInt(stmt)];
    }

    fn anyExprSpanImpossibilityProof(
        self: *BodyContext,
        span: DraftSpan(DraftExprId),
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        var combined: ?RuntimeImpossibilityProofId = null;
        for (self.exprSpan(span)) |expr| {
            combined = try self.anyImpossibilityProof(&.{ combined, self.exprImpossibilityProof(expr) });
        }
        return combined;
    }

    fn anyStmtSpanImpossibilityProof(
        self: *BodyContext,
        stmts: []const DraftStmtId,
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        var active_count: usize = 0;
        var sole: RuntimeImpossibilityProofId = undefined;
        for (stmts) |stmt| if (self.stmtImpossibilityProof(stmt)) |id| switch (self.draft.impossibility_proofs.items[@backingInt(id)]) {
            .never => {},
            .always => return id,
            .node, .pending, .forward, .any, .all => {
                sole = id;
                active_count += 1;
            },
        };
        return switch (active_count) {
            0 => null,
            1 => sole,
            else => blk: {
                const start: u32 = @intCast(self.draft.impossibility_proof_ids.items.len);
                const ids = try self.draft.impossibility_proof_ids.addManyAsSlice(self.allocator, active_count);
                var index: usize = 0;
                for (stmts) |stmt| if (self.stmtImpossibilityProof(stmt)) |id| switch (self.draft.impossibility_proofs.items[@backingInt(id)]) {
                    .never => {},
                    .always => unreachable,
                    .node, .pending, .forward, .any, .all => {
                        ids[index] = id;
                        index += 1;
                    },
                };
                break :blk try self.addImpossibilityProof(.{
                    .any = .{ .start = start, .len = @intCast(active_count) },
                });
            },
        };
    }

    fn patternSuccessImpossibilityProof(
        self: *BodyContext,
        pat: DraftPatId,
    ) ?RuntimeImpossibilityProofId {
        return self.draft.pat_impossibility_proofs.items[@backingInt(pat)];
    }

    /// Build a proof leaf without importing a sealed type back into the
    /// specialization graph. Phase-B deferred emission may create expressions
    /// after relation production is frozen, so sealed cells must use their
    /// immutable Monotype inhabitation result directly.
    fn cellImpossibilityProof(
        self: *BodyContext,
        cell: DraftTypeCell,
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        return switch (cell) {
            .graph_node => |node| try self.maybeNodeImpossibilityProof(node),
            .sealed => |ty| if (try self.typeIsProvenUninhabited(ty))
                try self.alwaysImpossibilityProof()
            else
                null,
        };
    }

    fn patDataImpossibilityProof(
        self: *BodyContext,
        ty: DraftTypeCell,
        data: DraftPatData,
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
        defer timing_scope.end();
        var proofs = std.ArrayList(?RuntimeImpossibilityProofId).empty;
        defer proofs.deinit(self.allocator);
        try proofs.append(self.allocator, try self.cellImpossibilityProof(ty));
        switch (data) {
            .as => |as| try proofs.append(self.allocator, self.patternSuccessImpossibilityProof(as.pattern)),
            .record => |span| for (self.recordDestructSpan(span)) |field|
                try proofs.append(self.allocator, self.patternSuccessImpossibilityProof(field.pattern)),
            .tuple => |span| for (self.patSpan(span)) |child|
                try proofs.append(self.allocator, self.patternSuccessImpossibilityProof(child)),
            .list => |list| {
                for (self.patSpan(list.patterns)) |child|
                    try proofs.append(self.allocator, self.patternSuccessImpossibilityProof(child));
                if (list.rest) |rest| if (rest.pattern) |child|
                    try proofs.append(self.allocator, self.patternSuccessImpossibilityProof(child));
            },
            .tag => |tag| for (self.patSpan(tag.payloads)) |child|
                try proofs.append(self.allocator, self.patternSuccessImpossibilityProof(child)),
            .nominal => |child| try proofs.append(self.allocator, self.patternSuccessImpossibilityProof(child)),
            .str_pattern => |str_pattern| for (self.strPatternStepSpan(str_pattern.steps)) |step|
                if (step.capture) |child| try proofs.append(self.allocator, self.patternSuccessImpossibilityProof(child)),
            .bind, .wildcard, .int_lit, .dec_lit, .frac_f32_lit, .frac_f64_lit, .str_lit => {},
        }
        return try self.anyImpossibilityProof(proofs.items);
    }

    fn exprDataImpossibilityProof(
        self: *BodyContext,
        ty: DraftTypeCell,
        data: DraftExprData,
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
        defer timing_scope.end();
        return switch (data) {
            .local,
            .unit,
            .pending_deferred,
            .int_lit,
            .frac_f32_lit,
            .frac_f64_lit,
            .dec_lit,
            .str_lit,
            .bytes_lit,
            .lambda,
            .def_ref,
            .fn_ref,
            .uninitialized,
            .uninitialized_payload,
            => null,
            .static_data_candidate => |candidate| self.exprImpossibilityProof(candidate.runtime_expr),
            .comptime_value => |candidate| self.exprImpossibilityProof(candidate.initializer),
            .@"unreachable",
            .break_,
            .continue_,
            .jump,
            .return_,
            .crash,
            .checked_error,
            .comptime_exhaustiveness_failed,
            => try self.alwaysImpossibilityProof(),
            .list, .tuple => |span| try self.anyExprSpanImpossibilityProof(span),
            .record => |span| blk: {
                var proofs = std.ArrayList(?RuntimeImpossibilityProofId).empty;
                defer proofs.deinit(self.allocator);
                for (self.fieldExprSpan(span)) |field|
                    try proofs.append(self.allocator, self.exprImpossibilityProof(field.value));
                break :blk try self.anyImpossibilityProof(proofs.items);
            },
            .record_update => |update| blk: {
                var proofs = std.ArrayList(?RuntimeImpossibilityProofId).empty;
                defer proofs.deinit(self.allocator);
                try proofs.append(self.allocator, self.exprImpossibilityProof(update.base));
                for (self.fieldExprSpan(update.fields)) |field|
                    try proofs.append(self.allocator, self.exprImpossibilityProof(field.value));
                break :blk try self.anyImpossibilityProof(proofs.items);
            },
            .tag => |tag| try self.anyExprSpanImpossibilityProof(tag.payloads),
            .nominal => |backing| self.exprImpossibilityProof(backing),
            .fn_def => |fn_def| blk: {
                var proofs = std.ArrayList(?RuntimeImpossibilityProofId).empty;
                defer proofs.deinit(self.allocator);
                for (self.fnDefCaptureSpan(fn_def.captures)) |capture|
                    try proofs.append(self.allocator, self.exprImpossibilityProof(capture.value));
                break :blk try self.anyImpossibilityProof(proofs.items);
            },
            .let_ => |let_| try self.anyImpossibilityProof(&.{
                self.exprImpossibilityProof(let_.value),
                self.patternSuccessImpossibilityProof(let_.bind),
                self.exprImpossibilityProof(let_.rest),
            }),
            .call_value => |call| try self.anyImpossibilityProof(&.{
                try self.cellImpossibilityProof(ty),
                self.exprImpossibilityProof(call.callee),
                try self.anyExprSpanImpossibilityProof(call.args),
            }),
            .call_proc => |call| try self.anyImpossibilityProof(&.{
                try self.cellImpossibilityProof(ty),
                try self.anyExprSpanImpossibilityProof(call.args),
                try self.anyExprSpanImpossibilityProof(call.captures),
            }),
            .low_level => |call| try self.anyImpossibilityProof(&.{
                try self.cellImpossibilityProof(ty),
                try self.anyExprSpanImpossibilityProof(call.args),
            }),
            .field_access => |field| try self.anyImpossibilityProof(&.{
                try self.cellImpossibilityProof(ty),
                self.exprImpossibilityProof(field.receiver),
            }),
            .tuple_access => |tuple| try self.anyImpossibilityProof(&.{
                try self.cellImpossibilityProof(ty),
                self.exprImpossibilityProof(tuple.tuple),
            }),
            .structural_eq => |eq| try self.anyImpossibilityProof(&.{
                self.exprImpossibilityProof(eq.lhs),
                self.exprImpossibilityProof(eq.rhs),
            }),
            .structural_hash => |hash| try self.anyImpossibilityProof(&.{
                self.exprImpossibilityProof(hash.value),
                self.exprImpossibilityProof(hash.hasher),
            }),
            .match_ => |match_| blk: {
                var alternatives = std.ArrayList(?RuntimeImpossibilityProofId).empty;
                defer alternatives.deinit(self.allocator);
                for (self.branchSpan(match_.branches)) |branch| {
                    try alternatives.append(self.allocator, try self.anyImpossibilityProof(&.{
                        self.patternSuccessImpossibilityProof(branch.pat),
                        try self.anyStmtSpanImpossibilityProof(self.stmtSpan(branch.bindings)),
                        if (branch.guard) |guard| self.exprImpossibilityProof(guard) else null,
                        self.exprImpossibilityProof(branch.body),
                    }));
                }
                break :blk try self.anyImpossibilityProof(&.{
                    self.exprImpossibilityProof(match_.scrutinee),
                    try self.allImpossibilityProof(alternatives.items),
                });
            },
            .if_ => |if_| blk: {
                var remaining = self.exprImpossibilityProof(if_.final_else);
                const branches = self.ifBranchSpan(if_.branches);
                var index = branches.len;
                while (index > 0) {
                    index -= 1;
                    remaining = try self.anyImpossibilityProof(&.{
                        self.exprImpossibilityProof(branches[index].cond),
                        try self.allImpossibilityProof(&.{
                            self.exprImpossibilityProof(branches[index].body),
                            remaining,
                        }),
                    });
                }
                break :blk remaining;
            },
            .if_initialized_payload => |switch_| try self.anyImpossibilityProof(&.{
                self.exprImpossibilityProof(switch_.cond),
                try self.allImpossibilityProof(&.{
                    self.exprImpossibilityProof(switch_.initialized),
                    self.exprImpossibilityProof(switch_.uninitialized),
                }),
            }),
            inline .try_sequence, .try_record_sequence => |try_| self.exprImpossibilityProof(try_.try_expr),
            .block => |block| blk: {
                var proofs = std.ArrayList(?RuntimeImpossibilityProofId).empty;
                defer proofs.deinit(self.allocator);
                for (self.stmtSpan(block.statements)) |stmt|
                    try proofs.append(self.allocator, self.stmtImpossibilityProof(stmt));
                try proofs.append(self.allocator, self.exprImpossibilityProof(block.final_expr));
                break :blk try self.anyImpossibilityProof(proofs.items);
            },
            .loop_ => |loop_| try self.anyExprSpanImpossibilityProof(loop_.initial_values),
            // A join may be entered through its remainder or any lexically
            // nested jump. The generated control-flow producer owns that
            // reachability; this local proof builder does not approximate it.
            .join_point => null,
            .comptime_branch_taken => |branch| self.exprImpossibilityProof(branch.body),
            .dbg => |child| self.exprImpossibilityProof(child),
            .expect_err => |expect_err| self.exprImpossibilityProof(expect_err.msg),
            .literal_rejected => |rejected| self.exprImpossibilityProof(rejected.msg),
            .expect => |child| if (self.builder.inline_expects == .shared) null else self.exprImpossibilityProof(child),
        };
    }

    fn stmtDataImpossibilityProof(
        self: *BodyContext,
        stmt: DraftStmt,
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
        defer timing_scope.end();
        return switch (stmt) {
            .uninitialized => null,
            .let_ => |let_| try self.anyImpossibilityProof(&.{
                self.exprImpossibilityProof(let_.value),
                self.patternSuccessImpossibilityProof(let_.pat),
            }),
            .expr, .dbg => |expr| self.exprImpossibilityProof(expr),
            .expect => |expr| if (self.builder.inline_expects == .shared) null else self.exprImpossibilityProof(expr),
            .return_, .crash, .checked_error => try self.alwaysImpossibilityProof(),
        };
    }

    fn addExpr(self: *BodyContext, expr: BodyExpr) Allocator.Error!DraftExprId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .draft_ir);
        defer timing_scope.end();
        const id = try self.draft.addExprWithSource(
            .{ .ty = try self.draftTypeCell(expr.ty), .data = expr.data },
            self.builder.current_loc,
            self.builder.current_region,
        );
        self.draft.expr_impossibility_proofs.items[@backingInt(id)] = try self.exprDataImpossibilityProof(
            self.draft.exprs.items[@backingInt(id)].ty,
            expr.data,
        );
        return id;
    }

    fn addFieldAccessExpr(
        self: *BodyContext,
        receiver: DraftExprId,
        field: names.RecordFieldNameId,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const segments = try self.draft.addFieldAccessSegmentSpan(&.{.{ .field = field }});
        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .field_access = .{
                .receiver = receiver,
                .segments = segments,
            } },
        });
    }

    fn addExprWithTypeCell(self: *BodyContext, ty: DraftTypeCell, data: BodyExprData) Allocator.Error!DraftExprId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .draft_ir);
        defer timing_scope.end();
        const id = try self.draft.addExprWithSource(
            .{ .ty = ty, .data = data },
            self.builder.current_loc,
            self.builder.current_region,
        );
        self.draft.expr_impossibility_proofs.items[@backingInt(id)] = try self.exprDataImpossibilityProof(ty, data);
        return id;
    }

    /// Add a structural constructor expression (tag, record, or tuple),
    /// typing it at the nominal construction backing and wrapping it in one
    /// explicit `.nominal` node per nominal layer of `ty`. This keeps
    /// nominal construction explicit in the IR even when the checked
    /// expression was an unqualified constructor promoted to a nominal type
    /// during unification.
    fn addConstructorExpr(self: *BodyContext, ty: Type.TypeId, data: BodyExprData) Allocator.Error!DraftExprId {
        var layers: std.ArrayListUnmanaged(Type.TypeId) = .empty;
        defer layers.deinit(self.allocator);
        var current = ty;
        while (self.nominalConstructionLayer(current)) |layer| {
            try layers.append(self.allocator, layer.named);
            current = layer.backing;
        }
        var expr = try self.addExpr(.{ .ty = current, .data = data });
        while (layers.pop()) |named| {
            expr = try self.addExpr(.{ .ty = named, .data = .{ .nominal = expr } });
        }
        return expr;
    }

    fn addConstructorExprAtNode(self: *BodyContext, node: NodeId, data: BodyExprData) Allocator.Error!DraftExprId {
        var layers: std.ArrayListUnmanaged(NodeId) = .empty;
        defer layers.deinit(self.allocator);
        var current = node;
        while (true) {
            const representation_node = (try self.constructorRepresentationNode(current));
            switch ((try self.graph.content(representation_node))) {
                .named => {
                    const named = (try self.graph.namedNodes(representation_node));
                    if (named.kind == .alias) Common.invariant("constructor representation retained a transparent alias node");
                    const backing = named.backing orelse
                        Common.invariant("named constructor graph node had no explicit backing");
                    try layers.append(self.allocator, representation_node);
                    current = backing.node;
                },
                .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => break,
            }
        }
        var expr = try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(current), data);
        while (layers.pop()) |representation_node| {
            expr = try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(representation_node), .{ .nominal = expr });
        }
        return expr;
    }

    /// Follow only producer-authored transparent alias edges to the runtime
    /// representation node used by constructor and pattern topology. A
    /// nominal or opaque node remains as an explicit construction layer;
    /// an alias never creates a `.nominal` expression or pattern.
    fn constructorRepresentationNode(self: *BodyContext, node: NodeId) Allocator.Error!NodeId {
        var current = node;
        while ((try self.graph.content(current)) == .named) {
            const named = (try self.graph.namedNodes(current));
            if (named.kind != .alias) return current;
            const backing = named.backing orelse
                Common.invariant("transparent alias graph node had no explicit backing");
            if (backing.node == current) Common.invariant("transparent alias backing did not advance");
            current = backing.node;
        }
        return current;
    }

    /// Materialize a local at its requested graph node. The request relation
    /// either joins the local and request representations, relates a
    /// generated-private local to a distinct public interface, or leaves an
    /// exact chain of producer-authored nominal backing edges between them.
    /// Preserve the producer-owned local at an opaque interface boundary;
    /// otherwise record every requested nominal layer explicitly in Monotype
    /// IR.
    fn lowerLocalAtRequestedNode(
        self: *BodyContext,
        local: DraftLocalId,
        source_cell: DraftTypeCell,
        expected_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const source_node = try source_cell.toGraphNode(self.graph);
        const source_root_private = (try isGeneratedPrivateRootNode(self.graph, source_node));
        const expected_root_private = (try isGeneratedPrivateRootNode(self.graph, expected_node));
        const preserves_distinct_interface = if (source_root_private or expected_root_private)
            source_root_private != expected_root_private
        else
            try self.graph.containsGeneratedPrivate(source_node) !=
                try self.graph.containsGeneratedPrivate(expected_node);
        try relateRequestComponent(self.graph, source_node, expected_node);
        if (preserves_distinct_interface) {
            return try self.addExprWithTypeCell(source_cell, .{ .local = local });
        }
        const source_representation_node = (try self.constructorRepresentationNode(source_node));

        var layers = std.ArrayList(NodeId).empty;
        defer layers.deinit(self.allocator);

        var current = expected_node;
        while (true) {
            current = (try self.constructorRepresentationNode(current));
            if (self.graph.sameClass(source_representation_node, current)) break;
            if ((try self.graph.content(current)) != .named) {
                Common.invariant("related local and request had no exact nominal backing path");
            }
            for (layers.items) |layer| {
                if (self.graph.sameClass(layer, current)) {
                    Common.invariant("nominal local request backing path contained a cycle");
                }
            }
            try layers.append(self.allocator, current);
            const named = (try self.graph.namedNodes(current));
            if (named.kind == .alias) Common.invariant("constructor representation retained a transparent alias node");
            current = (named.backing orelse
                Common.invariant("named expression graph node had no explicit backing")).node;
        }

        var expr = try self.addExprWithTypeCell(source_cell, .{ .local = local });
        var index = layers.items.len;
        while (index > 0) {
            index -= 1;
            expr = try self.addExprWithTypeCell(
                DraftTypeCell.fromGraphNode(layers.items[index]),
                .{ .nominal = expr },
            );
        }
        return expr;
    }

    /// Wrap an exact structural value witness in its nominal constructor
    /// layers. Transparent aliases stay out of the runtime IR but remain part
    /// of the witness type, matching `addConstructorExprAtNode`, whose
    /// non-named arm types a structural expression at its original (possibly
    /// alias-wrapped) node.
    /// Wrap `node`'s named layers, nominal and then alias, around
    /// `structural_node`, innermost last.
    fn constructorWitnessWithStructuralNode(
        self: *BodyContext,
        node: NodeId,
        structural_node: NodeId,
    ) Allocator.Error!NodeId {
        const Layer = struct { raw: InstNode, backing: InstBacking };
        var layers: std.ArrayListUnmanaged(Layer) = .empty;
        defer layers.deinit(self.allocator);
        var current = node;
        while (true) {
            const representation_node = (try self.constructorRepresentationNode(current));
            const raw = (try self.graph.content(representation_node));
            if (raw != .named) break;
            const named = (try self.graph.namedNodes(representation_node));
            if (named.kind == .alias) Common.invariant("constructor witness retained a transparent alias node");
            const backing = named.backing orelse
                Common.invariant("named constructor witness had no explicit backing");
            try layers.append(self.allocator, .{ .raw = raw, .backing = backing });
            current = backing.node;
        }
        var witness_node = try self.constructorWitnessAliasLayers(current, structural_node);
        while (layers.pop()) |layer| {
            var witness = layer.raw.named.*;
            witness.backing = .{
                .node = witness_node,
                .use = layer.backing.use,
                .authority = layer.backing.authority,
            };
            witness_node = try self.graph.newNode(try self.graph.namedContent(witness));
        }
        return witness_node;
    }

    /// Wrap the structural value witness in `node`'s transparent alias
    /// layers. Witness and no-witness branches of the same constructor must
    /// seal to the same Monotype, and the no-witness branch types the
    /// expression at the original alias-wrapped node.
    fn constructorWitnessAliasLayers(
        self: *BodyContext,
        node: NodeId,
        structural_node: NodeId,
    ) Allocator.Error!NodeId {
        const Layer = struct { raw: InstNode, backing: InstBacking };
        var layers: std.ArrayListUnmanaged(Layer) = .empty;
        defer layers.deinit(self.allocator);
        var current = node;
        while (true) {
            const raw = (try self.graph.content(current));
            if (raw != .named) break;
            const named = (try self.graph.namedNodes(current));
            if (named.kind != .alias) break;
            const backing = named.backing orelse
                Common.invariant("transparent alias graph node had no explicit backing");
            try layers.append(self.allocator, .{ .raw = raw, .backing = backing });
            current = backing.node;
        }
        var witness_node = structural_node;
        while (layers.pop()) |layer| {
            var witness = layer.raw.named.*;
            witness.backing = .{
                .node = witness_node,
                .use = layer.backing.use,
                .authority = layer.backing.authority,
            };
            witness_node = try self.graph.newNode(try self.graph.namedContent(witness));
        }
        return witness_node;
    }

    /// Pattern counterpart to `addConstructorExpr`, used by compiler-generated
    /// exhaustive matches whose constructor pattern has no checked source node.
    fn addConstructorPat(self: *BodyContext, ty: Type.TypeId, data: BodyPatData) Allocator.Error!DraftPatId {
        var layers: std.ArrayListUnmanaged(Type.TypeId) = .empty;
        defer layers.deinit(self.allocator);
        var current = ty;
        while (self.nominalConstructionLayer(current)) |layer| {
            try layers.append(self.allocator, layer.named);
            current = layer.backing;
        }
        var pat = try self.addPat(.{ .ty = current, .data = data });
        while (layers.pop()) |named| {
            pat = try self.addPat(.{ .ty = named, .data = .{ .nominal = pat } });
        }
        return pat;
    }

    fn addPat(self: *BodyContext, pat: BodyPat) Allocator.Error!DraftPatId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .draft_ir);
        defer timing_scope.end();
        const ty = try self.draftTypeCell(pat.ty);
        const id = try self.draft.addPat(.{ .ty = ty, .data = pat.data });
        self.draft.pat_impossibility_proofs.items[@backingInt(id)] = try self.patDataImpossibilityProof(ty, pat.data);
        return id;
    }

    fn addPatWithTypeCell(self: *BodyContext, ty: DraftTypeCell, data: BodyPatData) Allocator.Error!DraftPatId {
        if (std.debug.runtime_safety and data == .nominal) {
            switch (ty) {
                .graph_node => |node| if ((try self.graph.content(node)) == .named and (try self.graph.namedNodes(node)).kind == .alias) {
                    Common.invariant("Monotype graph lowering emitted a nominal pattern at an alias type");
                },
                .sealed => {},
            }
        }
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .draft_ir);
        defer timing_scope.end();
        const id = try self.draft.addPat(.{ .ty = ty, .data = data });
        self.draft.pat_impossibility_proofs.items[@backingInt(id)] = try self.patDataImpossibilityProof(ty, data);
        return id;
    }

    fn addLocal(self: *BodyContext, symbol: Common.Symbol, ty: Type.TypeId) Allocator.Error!DraftLocalId {
        if (@backingInt(ty) >= self.typeStore().epochBoundary().types) {
            Common.invariant("body context added a local with a type from another store");
        }
        return try self.addLocalWithBinder(symbol, ty, null);
    }

    fn addLocalWithBinder(
        self: *BodyContext,
        symbol: Common.Symbol,
        ty: Type.TypeId,
        binder: ?checked.PatternBinderId,
    ) Allocator.Error!DraftLocalId {
        return try self.addLocalWithBinderCell(symbol, try self.draftTypeCell(ty), binder);
    }

    fn addLocalWithBinderCell(
        self: *BodyContext,
        symbol: Common.Symbol,
        ty: DraftTypeCell,
        binder: ?checked.PatternBinderId,
    ) Allocator.Error!DraftLocalId {
        switch (ty) {
            .sealed => |sealed| if (@backingInt(sealed) >= self.typeStore().epochBoundary().types) {
                Common.invariant("body context added a local cell with a type from another store");
            },
            .graph_node => {},
        }
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .draft_ir);
        defer timing_scope.end();
        const inherited_capture_id = if (binder) |source_binder| blk: {
            const existing = self.binders.get(source_binder) orelse break :blk null;
            break :blk self.draft.locals.items[@backingInt(existing)].capture_id;
        } else null;
        return try self.draft.addLocal(symbol, ty, binder, inherited_capture_id);
    }

    /// Materialize a new runtime binding from checked capture provenance even
    /// when another instantiation of that checked binder is temporarily in
    /// scope. This is the one-to-many boundary; ordinary local versions use
    /// `addLocalWithBinderCell` and inherit the current binding's identity.
    fn addFreshLocalWithBinder(
        self: *BodyContext,
        symbol: Common.Symbol,
        ty: Type.TypeId,
        binder: checked.PatternBinderId,
    ) Allocator.Error!DraftLocalId {
        return try self.addFreshLocalWithBinderCell(symbol, try self.draftTypeCell(ty), binder);
    }

    fn addFreshLocalWithBinderCell(
        self: *BodyContext,
        symbol: Common.Symbol,
        ty: DraftTypeCell,
        binder: checked.PatternBinderId,
    ) Allocator.Error!DraftLocalId {
        switch (ty) {
            .sealed => |sealed| if (@backingInt(sealed) >= self.typeStore().epochBoundary().types) {
                Common.invariant("body context added a fresh local cell with a type from another store");
            },
            .graph_node => {},
        }
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .draft_ir);
        defer timing_scope.end();
        return try self.draft.addLocal(symbol, ty, binder, null);
    }

    /// The stored form of `chain`, reusing the last conversion when `chain`
    /// reads the same frames.
    fn storedEvidence(self: *BodyContext, chain: EvidenceChain) Allocator.Error!StoredConstFnEvidence {
        const source = StoredEvidenceSource.of(chain);
        if (self.stored_evidence_cache) |cached| {
            if (std.meta.eql(cached.source, source)) return cached.stored;
        }
        const stored = try self.builder.constFnEvidence(chain);
        self.stored_evidence_cache = .{ .source = source, .stored = stored };
        return stored;
    }

    fn addFn(self: *BodyContext, source: Ast.FnTemplate) Allocator.Error!DraftFnId {
        if (source.const_evidence.len != 0 or source.const_evidence_frames.len != 0 or source.const_evidence_frame_head != null) {
            Common.invariant("body-local function source carried evidence outside its lexical lowering context");
        }
        const stored_evidence = try self.storedEvidence(self.evidence);
        const evidence_digest = stored_evidence.digest;
        const draft_evidence = try self.draft.addStoredConstFnEvidence(stored_evidence);
        return try self.draft.addFn(.{
            .source = .{
                .fn_def = source.fn_def,
                .source_fn_ty = source.source_fn_ty,
                .source_fn_key = source.source_fn_key,
                .mono_fn_ty = try self.draftTypeCell(source.mono_fn_ty),
                .const_evidence = draft_evidence.nodes,
                .const_evidence_frames = draft_evidence.frames,
                .const_evidence_frame_head = stored_evidence.head,
                .evidence_digest = evidence_digest,
            },
        });
    }

    fn addExprSpan(self: *BodyContext, ids: []const DraftExprId) Allocator.Error!DraftSpan(DraftExprId) {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .draft_ir);
        defer timing_scope.end();
        return try self.draft.addExprSpan(ids);
    }

    fn reserveExprSpan(self: *BodyContext, len: usize) Allocator.Error!BodyDraftStore.ReservedExprSpan {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .draft_ir);
        defer timing_scope.end();
        return try self.draft.reserveExprSpan(len);
    }

    fn addPatSpan(self: *BodyContext, ids: []const DraftPatId) Allocator.Error!DraftSpan(DraftPatId) {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .draft_ir);
        defer timing_scope.end();
        return try self.draft.addPatSpan(ids);
    }

    fn addTypedLocalSpan(self: *BodyContext, values: []const BodyTypedLocal) Allocator.Error!DraftSpan(DraftTypedLocal) {
        const draft_values = try self.allocator.alloc(DraftTypedLocal, values.len);
        defer self.allocator.free(draft_values);
        for (values, 0..) |value, index| {
            draft_values[index] = .{
                .local = value.local,
                .ty = try self.draftTypeCell(value.ty),
            };
        }
        return try self.draft.addTypedLocalSpan(draft_values);
    }

    fn addStmt(self: *BodyContext, stmt: DraftStmt) Allocator.Error!DraftStmtId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .draft_ir);
        defer timing_scope.end();
        const id = try self.draft.addStmtWithSource(stmt, self.builder.current_loc, self.builder.current_region);
        self.draft.stmt_impossibility_proofs.items[@backingInt(id)] = try self.stmtDataImpossibilityProof(stmt);
        return id;
    }

    fn addStmtSpan(self: *BodyContext, ids: []const DraftStmtId) Allocator.Error!DraftSpan(DraftStmtId) {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .draft_ir);
        defer timing_scope.end();
        return try self.draft.addStmtSpan(ids);
