    fn addStringLiteral(self: *BodyContext, text: []const u8) Allocator.Error!DraftStringLiteralId {
        return try self.draft.addStringLiteral(text);
    }

    fn addConstBlobView(self: *BodyContext, module_bytes: [32]u8, data: check.ConstStore.ConstBlobDataId, bytes: []const u8, offset: u32, len: u32) Allocator.Error!DraftStringLiteralId {
        const id: DraftStringLiteralId = @fromBackingInt(@intCast(@as(u32, @intCast(self.draft.string_literals.items.len))));
        try self.draft.string_literals.append(self.allocator, .{ .backing = .empty(), .const_blob = .{ .module_bytes = module_bytes, .data = data, .bytes = bytes }, .offset = offset, .len = len });
        return id;
    }

    fn addStringView(
        self: *BodyContext,
        backing: []const u8,
        offset: u32,
        len: u32,
    ) Allocator.Error!DraftStringLiteralId {
        return try self.draft.addStringView(backing, offset, len);
    }

    fn exprLoc(self: *BodyContext, id: DraftExprId) base.SourceLoc {
        return self.draft.expr_locs.items[@backingInt(id)];
    }

    fn exprRegion(self: *BodyContext, id: DraftExprId) base.Region {
        return self.draft.expr_regions.items[@backingInt(id)];
    }

    /// Frozen Phase-B emission reads a draft expression's type through the one
    /// final sealer, exactly as `localType` does: a graph-node cell has no
    /// active view once relation production has ended.
    fn exprType(self: *BodyContext, id: DraftExprId) Allocator.Error!Type.TypeId {
        const cell = self.draft.exprs.items[@backingInt(id)].ty;
        if (self.frozen_sealed_emission) {
            const finals = self.frozen_type_finals orelse
                Common.invariant("frozen Monotype emission had no graph type finalizer");
            return try cell.seal(self.graph, finals);
        }
        return try self.activeTypeFromCell(cell);
    }

    fn exprTypeCell(self: *BodyContext, id: DraftExprId) DraftTypeCell {
        return self.draft.exprs.items[@backingInt(id)].ty;
    }

    fn patData(self: *BodyContext, id: DraftPatId) DraftPatData {
        return self.draft.pats.items[@backingInt(id)].data;
    }

    fn localType(self: *BodyContext, id: DraftLocalId) Allocator.Error!Type.TypeId {
        const cell = self.draft.locals.items[@backingInt(id)].ty;
        if (self.frozen_sealed_emission) {
            const finals = self.frozen_type_finals orelse
                Common.invariant("frozen Monotype emission had no graph type finalizer");
            return try cell.seal(self.graph, finals);
        }
        return try self.activeTypeFromCell(cell);
    }

    fn localTypeCell(self: *BodyContext, id: DraftLocalId) DraftTypeCell {
        return self.draft.locals.items[@backingInt(id)].ty;
    }

    fn setLocalCaptureId(self: *BodyContext, id: DraftLocalId, capture_id: u32) void {
        self.draft.setLocalCaptureId(id, capture_id);
    }

    fn setLocalType(self: *BodyContext, id: DraftLocalId, ty: Type.TypeId) Allocator.Error!void {
        if (@backingInt(ty) >= self.typeStore().epochBoundary().types) {
            Common.invariant("body context updated a local with a type from another store");
        }
        self.draft.setLocalType(id, try self.draftTypeCell(ty));
    }

    fn bindLocalName(self: *BodyContext, local: DraftLocalId, binder: checked.PatternBinderId) Allocator.Error!void {
        return try self.bindLocalNameFromView(self.view, local, binder);
    }

    fn bindLocalNameFromView(
        self: *BodyContext,
        source_view: ModuleView,
        local: DraftLocalId,
        binder: checked.PatternBinderId,
    ) Allocator.Error!void {
        const entry = source_view.bodies.patternBinder(binder);
        const pattern = source_view.bodies.pattern(entry.pattern);
        if (pattern.data != .assign) return;
        const source = source_view.module_env.common.source;
        const start = pattern.source_region.start.offset;
        const end = pattern.source_region.end.offset;
        if (start >= end or end > source.len) return;
        try self.draft.setLocalName(local, source[start..end]);
    }

    fn localExpr(self: *BodyContext, local: DraftLocalId, ty: Type.TypeId) Allocator.Error!DraftExprId {
        return try self.addExpr(.{ .ty = ty, .data = .{ .local = local } });
    }

    fn bindPat(self: *BodyContext, local: DraftLocalId, ty: Type.TypeId) Allocator.Error!DraftPatId {
        return try self.addPat(.{ .ty = ty, .data = .{ .bind = local } });
    }

    fn intLiteralExpr(self: *BodyContext, value: u64, ty: Type.TypeId) Allocator.Error!DraftExprId {
        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .int_lit = unsignedIntLiteral(value) },
        });
    }

    fn lowLevelExpr(
        self: *BodyContext,
        op: can.CIR.Expr.LowLevel,
        args: []const DraftExprId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.addExpr(.{
            .ty = ret_ty,
            .data = .{ .low_level = .{
                .op = op,
                .args = try self.addExprSpan(args),
            } },
        });
    }

    fn concatExpr(self: *BodyContext, left: DraftExprId, right: DraftExprId, str_ty: Type.TypeId) Allocator.Error!DraftExprId {
        return try self.lowLevelExpr(.str_concat, &.{ left, right }, str_ty);
    }

    fn ifExpr(
        self: *BodyContext,
        cond: DraftExprId,
        then_expr: DraftExprId,
        else_expr: DraftExprId,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const branches = [_]DraftIfBranch{.{ .cond = cond, .body = then_expr }};
        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .if_ = .{
                .branches = try self.addIfBranchSpan(&branches),
                .final_else = else_expr,
            } },
        });
    }

    fn stringExpr(self: *BodyContext, text: []const u8, str_ty: Type.TypeId) Allocator.Error!DraftExprId {
        return try self.addExpr(.{
            .ty = str_ty,
            .data = .{ .str_lit = try self.addStringLiteral(text) },
        });
    }

    /// One pending piece of `Str.inspect` expansion. Each piece allocates its
    /// expressions, locals, patterns, and helper definitions in the order a
    /// direct walk would, waiting on a frame for each component it renders.
    const InspectTask = union(enum) {
        /// A call to the helper that renders a value of this type.
        call: struct { value: DraftExprId, value_ty: Type.TypeId },
        /// The helper that renders a value of this type.
        def: struct { value_ty: Type.TypeId, def_id: DraftDefId = undefined, arg_local: DraftLocalId = undefined },
        body: struct { value: DraftExprId, value_ty: Type.TypeId, shape_ty: Type.TypeId },
        box: struct { value: DraftExprId, elem_ty: Type.TypeId, out: DraftExprId = undefined },
        field_slot: struct { value: DraftExprId, slot_ty: Type.TypeId, present_pat: DraftPatId = undefined, slot: Builder.OptionalSlotInfo = undefined },
        record: struct { value: DraftExprId, fields: []Type.Field, index: usize = 0, out: DraftExprId = undefined },
        tuple: struct { value: DraftExprId, items: []Type.TypeId, index: usize = 0, out: DraftExprId = undefined },
        tag_union: struct {
            value: DraftExprId,
            value_ty: Type.TypeId,
            tags: []Type.Tag,
            index: usize = 0,
            branches: std.ArrayList(DraftBranch) = .empty,
            pending_pat: DraftPatId = undefined,
            payload_tys: []Type.TypeId = &.{},
            payload_exprs: []DraftExprId = &.{},
        },
        tag_body: struct {
            name: names.TagNameId,
            payload_exprs: []const DraftExprId,
            payload_tys: []const Type.TypeId,
            index: usize = 0,
            out: DraftExprId = undefined,
        },
        list: struct {
            value: DraftExprId,
            elem_ty: Type.TypeId,
            u64_ty: Type.TypeId = undefined,
            len_pat: DraftPatId = undefined,
            len_value: DraftExprId = undefined,
            index_local: DraftLocalId = undefined,
            out_local: DraftLocalId = undefined,
            done_cond: DraftExprId = undefined,
            finish: DraftExprId = undefined,
        },
        list_step: struct {
            value: DraftExprId,
            elem_ty: Type.TypeId,
            index_local: DraftLocalId,
            out_local: DraftLocalId,
            u64_ty: Type.TypeId = undefined,
            index_expr: DraftExprId = undefined,
            out_expr: DraftExprId = undefined,
            sep: DraftExprId = undefined,
        },
    };

    const InspectFrame = struct {
        task: InspectTask,
        started: bool = false,
    };

    const InspectResult = union(enum) {
        expr: DraftExprId,
        def: DraftDefId,
    };

    const InspectStep = union(enum) {
        /// Expand a component; the frame resumes with its result.
        child: InspectTask,
        /// This frame's result is the component's result.
        tail: InspectTask,
        done: InspectResult,
    };

    fn releaseInspectFrame(self: *BodyContext, frame: *InspectFrame) void {
        switch (frame.task) {
            .record => |*record| self.allocator.free(record.fields),
            .tuple => |*tuple| self.allocator.free(tuple.items),
            .tag_union => |*tag_union| {
                self.allocator.free(tag_union.tags);
                tag_union.branches.deinit(self.allocator);
                self.allocator.free(tag_union.payload_tys);
                self.allocator.free(tag_union.payload_exprs);
            },
            .call, .def, .body, .box, .field_slot, .tag_body, .list, .list_step => {},
        }
    }

    fn inspectCall(self: *BodyContext, value: DraftExprId, value_ty: Type.TypeId, str_ty: Type.TypeId) Allocator.Error!DraftExprId {
        var frames = std.ArrayList(InspectFrame).empty;
        defer {
            for (frames.items) |*frame| self.releaseInspectFrame(frame);
            frames.deinit(self.allocator);
        }
        try frames.append(self.allocator, .{ .task = .{ .call = .{ .value = value, .value_ty = value_ty } } });
        var input: ?InspectResult = null;
        while (true) {
            const frame = &frames.items[frames.items.len - 1];
            const step = try self.stepInspect(frame, str_ty, input);
            input = null;
            switch (step) {
                .child => |task| try frames.append(self.allocator, .{ .task = task }),
                .tail => |task| {
                    self.releaseInspectFrame(frame);
                    frame.* = .{ .task = task };
                },
                .done => |result| {
                    var finished = frames.pop().?;
                    self.releaseInspectFrame(&finished);
                    if (frames.items.len == 0) return result.expr;
                    input = result;
                },
            }
        }
    }

    fn stepInspect(self: *BodyContext, frame: *InspectFrame, str_ty: Type.TypeId, input: ?InspectResult) Allocator.Error!InspectStep {
        const started = frame.started;
        frame.started = true;
        switch (frame.task) {
            .call => |call| {
                if (!started) {
                    if (try self.typeIsProvenUninhabited(call.value_ty)) {
                        return .{ .done = .{ .expr = try self.uninhabitedInspect(call.value, str_ty) } };
                    }
                    return .{ .child = .{ .def = .{ .value_ty = call.value_ty } } };
                }
                const callee = try self.addExprWithTypeCell(
                    .{ .sealed = try self.functionType(&.{call.value_ty}, str_ty) },
                    .{ .def_ref = .{ .draft = input.?.def } },
                );
                const args = [_]DraftExprId{call.value};
                return .{ .done = .{ .expr = try self.addExpr(.{
                    .ty = str_ty,
                    .data = .{ .call_value = .{
                        .callee = callee,
                        .args = try self.addExprSpan(&args),
                    } },
                }) } };
            },
            .def => |*def| {
                if (!started) {
                    const address = GeneratedHelperDefAddress{
                        .value_ty = @backingInt(def.value_ty),
                        .result_ty = @backingInt(str_ty),
                    };
                    if (self.inspect_defs.get(address)) |entry| return .{ .done = .{ .def = entry.id() } };

                    def.def_id = try self.draft.reserveDef(self.draft.current_owner);
                    try self.inspect_defs.put(address, .{ .reserved = def.def_id });

                    def.arg_local = try self.addLocal(self.builder.symbols.fresh(), def.value_ty);
                    const arg_expr = try self.localExpr(def.arg_local, def.value_ty);
                    return .{ .child = .{ .body = .{ .value = arg_expr, .value_ty = def.value_ty, .shape_ty = def.value_ty } } };
                }
                const args = try self.addTypedLocalSpan(&.{.{ .local = def.arg_local, .ty = def.value_ty }});
                self.draft.setDef(def.def_id, .{
                    .symbol = self.builder.symbols.fresh(),
                    .fn_def = null,
                    .identity_seed = .{ .kind = "inspect-helper", .cells = .{ DraftTypeCell.fromSealed(def.value_ty), DraftTypeCell.fromSealed(str_ty), null, null } },
                    .args = args,
                    .body = .{ .roc = input.?.expr },
                    .ret = try self.draftTypeCell(str_ty),
                });
                try self.inspect_defs.put(.{
                    .value_ty = @backingInt(def.value_ty),
                    .result_ty = @backingInt(str_ty),
                }, .{ .ready = def.def_id });
                return .{ .done = .{ .def = def.def_id } };
            },
            .body => |body| return try self.stepInspectBody(body.value, body.value_ty, body.shape_ty, str_ty),
            .box => |*box| {
                if (!started) {
                    const unboxed = try self.lowLevelExpr(.box_unbox, &.{box.value}, box.elem_ty);
                    box.out = try self.stringExpr("Box(", str_ty);
                    return .{ .child = .{ .call = .{ .value = unboxed, .value_ty = box.elem_ty } } };
                }
                const out = try self.concatExpr(box.out, input.?.expr, str_ty);
                return .{ .done = .{ .expr = try self.concatExpr(out, try self.stringExpr(")", str_ty), str_ty) } };
            },
            .field_slot => |*field_slot| {
                // An inline (required/defaulted) slot renders as the value
                // itself. An optional field's tagged slot never leaks its
                // Missing/Present encoding: a present slot renders its
                // payload exactly as a required field's value would, and a
                // missing slot renders the literal `<missing>` marker. Twin
                // of `Builder.inspectFieldSlot` for draft-body inspect
                // expansion.
                if (!started) {
                    field_slot.slot = self.optionalFieldSlot(field_slot.slot_ty) orelse
                        return .{ .tail = .{ .call = .{ .value = field_slot.value, .value_ty = field_slot.slot_ty } } };
                    const slot = field_slot.slot;
                    const payload_local = try self.addLocal(self.builder.symbols.fresh(), slot.payload_ty);
                    const payload_pat = try self.bindPat(payload_local, slot.payload_ty);
                    field_slot.present_pat = try self.addPat(.{ .ty = field_slot.slot_ty, .data = .{ .tag = .{
                        .name = slot.present_tag.name,
                        .payloads = try self.addPatSpan(&[_]DraftPatId{payload_pat}),
                    } } });
                    return .{ .child = .{ .call = .{
                        .value = try self.localExpr(payload_local, slot.payload_ty),
                        .value_ty = slot.payload_ty,
                    } } };
                }
                const missing_pat = try self.addPat(.{ .ty = field_slot.slot_ty, .data = .{ .tag = .{
                    .name = field_slot.slot.missing_tag.name,
                    .payloads = .empty(),
                } } });
                const missing_body = try self.stringExpr(Builder.optional_field_missing_render, str_ty);

                const branches = [_]DraftBranch{
                    .{ .pat = field_slot.present_pat, .body = input.?.expr },
                    .{ .pat = missing_pat, .body = missing_body },
                };
                return .{ .done = .{ .expr = try self.addExpr(.{ .ty = str_ty, .data = .{ .match_ = .{
                    .scrutinee = field_slot.value,
                    .branches = try self.addBranchSpan(&branches),
                } } }) } };
            },
            .record => |*record| {
                if (!started) {
                    record.out = try self.stringExpr("{ ", str_ty);
                } else {
                    record.out = try self.concatExpr(record.out, input.?.expr, str_ty);
                }
                if (record.index == record.fields.len) {
                    return .{ .done = .{ .expr = try self.concatExpr(record.out, try self.stringExpr(" }", str_ty), str_ty) } };
                }
                const field = record.fields[record.index];
                if (record.index != 0) record.out = try self.concatExpr(record.out, try self.stringExpr(", ", str_ty), str_ty);
                record.index += 1;
                record.out = try self.concatExpr(record.out, try self.stringExpr(self.nameStore().recordFieldLabelText(field.name), str_ty), str_ty);
                record.out = try self.concatExpr(record.out, try self.stringExpr(": ", str_ty), str_ty);
                const field_value = try self.addFieldAccessExpr(record.value, field.name, field.ty);
                return .{ .child = .{ .field_slot = .{ .value = field_value, .slot_ty = field.ty } } };
            },
            .tuple => |*tuple| {
                if (!started) {
                    tuple.out = try self.stringExpr("(", str_ty);
                } else {
                    tuple.out = try self.concatExpr(tuple.out, input.?.expr, str_ty);
                }
                if (tuple.index == tuple.items.len) {
                    return .{ .done = .{ .expr = try self.concatExpr(tuple.out, try self.stringExpr(")", str_ty), str_ty) } };
                }
                const i = tuple.index;
                tuple.index += 1;
                const item_ty = tuple.items[i];
                if (i != 0) tuple.out = try self.concatExpr(tuple.out, try self.stringExpr(", ", str_ty), str_ty);
                const item = try self.addExpr(.{
                    .ty = item_ty,
                    .data = .{ .tuple_access = .{ .tuple = tuple.value, .elem_index = @intCast(i) } },
                });
                return .{ .child = .{ .call = .{ .value = item, .value_ty = item_ty } } };
            },
            .tag_union => |*tag_union| {
                if (started) {
                    try tag_union.branches.append(self.allocator, .{ .pat = tag_union.pending_pat, .body = input.?.expr });
                    self.allocator.free(tag_union.payload_tys);
                    tag_union.payload_tys = &.{};
                    self.allocator.free(tag_union.payload_exprs);
                    tag_union.payload_exprs = &.{};
                }
                while (tag_union.index < tag_union.tags.len) {
                    const tag = tag_union.tags[tag_union.index];
                    tag_union.index += 1;
                    const payload_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(tag.payloads));
                    var tag_is_uninhabited = false;
                    for (payload_tys) |payload_ty| {
                        if (self.typeIsProvenUninhabited(payload_ty) catch |err| {
                            self.allocator.free(payload_tys);
                            return err;
                        }) {
                            tag_is_uninhabited = true;
                            break;
                        }
                    }
                    if (tag_is_uninhabited) {
                        self.allocator.free(payload_tys);
                        continue;
                    }
                    tag_union.payload_tys = payload_tys;
                    const payload_pats = try self.allocator.alloc(DraftPatId, payload_tys.len);
                    defer self.allocator.free(payload_pats);
                    tag_union.payload_exprs = try self.allocator.alloc(DraftExprId, payload_tys.len);

                    for (payload_tys, 0..) |payload_ty, payload_i| {
                        const local = try self.addLocal(self.builder.symbols.fresh(), payload_ty);
                        payload_pats[payload_i] = try self.addPat(.{ .ty = payload_ty, .data = .{ .bind = local } });
                        tag_union.payload_exprs[payload_i] = try self.localExpr(local, payload_ty);
                    }

                    tag_union.pending_pat = try self.addPat(.{
                        .ty = tag_union.value_ty,
                        .data = .{ .tag = .{
                            .name = tag.name,
                            .payloads = try self.addPatSpan(payload_pats),
                        } },
                    });
                    return .{ .child = .{ .tag_body = .{
                        .name = tag.name,
                        .payload_exprs = tag_union.payload_exprs,
                        .payload_tys = tag_union.payload_tys,
                    } } };
                }
                if (tag_union.branches.items.len == 0) return .{ .done = .{ .expr = try self.uninhabitedInspect(tag_union.value, str_ty) } };

                return .{ .done = .{ .expr = try self.addExpr(.{
                    .ty = str_ty,
                    .data = .{ .match_ = .{
                        .scrutinee = tag_union.value,
                        .branches = try self.addBranchSpan(tag_union.branches.items),
                    } },
                }) } };
            },
            .tag_body => |*tag_body| {
                if (!started) {
                    tag_body.out = try self.stringExpr(self.nameStore().tagLabelText(tag_body.name), str_ty);
                    if (tag_body.payload_exprs.len == 0) return .{ .done = .{ .expr = tag_body.out } };
                    tag_body.out = try self.concatExpr(tag_body.out, try self.stringExpr("(", str_ty), str_ty);
                } else {
                    tag_body.out = try self.concatExpr(tag_body.out, input.?.expr, str_ty);
                }
                if (tag_body.index == tag_body.payload_exprs.len) {
                    return .{ .done = .{ .expr = try self.concatExpr(tag_body.out, try self.stringExpr(")", str_ty), str_ty) } };
                }
                const i = tag_body.index;
                tag_body.index += 1;
                if (i != 0) tag_body.out = try self.concatExpr(tag_body.out, try self.stringExpr(", ", str_ty), str_ty);
                return .{ .child = .{ .call = .{ .value = tag_body.payload_exprs[i], .value_ty = tag_body.payload_tys[i] } } };
            },
            .list => |*list| {
                if (!started) {
                    if (try self.typeIsProvenUninhabited(list.elem_ty)) return .{ .done = .{ .expr = try self.stringExpr("[]", str_ty) } };
                    list.u64_ty = try self.primitiveType(.u64);
                    const bool_ty = try self.primitiveType(.bool);

                    const len_local = try self.addLocal(self.builder.symbols.fresh(), list.u64_ty);
                    list.len_pat = try self.bindPat(len_local, list.u64_ty);
                    list.len_value = try self.lowLevelExpr(.list_len, &.{list.value}, list.u64_ty);
                    const len_expr = try self.localExpr(len_local, list.u64_ty);

                    list.index_local = try self.addLocal(self.builder.symbols.fresh(), list.u64_ty);
                    list.out_local = try self.addLocal(self.builder.symbols.fresh(), str_ty);
                    const index_expr = try self.localExpr(list.index_local, list.u64_ty);
                    const out_expr = try self.localExpr(list.out_local, str_ty);

                    list.done_cond = try self.lowLevelExpr(.num_is_eq, &.{ index_expr, len_expr }, bool_ty);
                    list.finish = try self.addExpr(.{
                        .ty = str_ty,
                        .data = .{ .break_ = try self.concatExpr(out_expr, try self.stringExpr("]", str_ty), str_ty) },
                    });
                    return .{ .child = .{ .list_step = .{
                        .value = list.value,
                        .elem_ty = list.elem_ty,
                        .index_local = list.index_local,
                        .out_local = list.out_local,
                    } } };
                }
                const body = try self.ifExpr(list.done_cond, list.finish, input.?.expr, str_ty);

                const params = [_]BodyTypedLocal{
                    .{ .local = list.index_local, .ty = list.u64_ty },
                    .{ .local = list.out_local, .ty = str_ty },
                };
                const initial_values = [_]DraftExprId{
                    try self.intLiteralExpr(0, list.u64_ty),
                    try self.stringExpr("[", str_ty),
                };
                const loop = try self.addExpr(.{
                    .ty = str_ty,
                    .data = .{ .loop_ = .{
                        .params = try self.addTypedLocalSpan(&params),
                        .initial_values = try self.addExprSpan(&initial_values),
                        .body = body,
                    } },
                });
                return .{ .done = .{ .expr = try self.addExpr(.{
                    .ty = str_ty,
                    .data = .{ .let_ = .{
                        .bind = list.len_pat,
                        .value = list.len_value,
                        .rest = loop,
                    } },
                }) } };
            },
            .list_step => |*step| {
                if (!started) {
                    step.u64_ty = try self.primitiveType(.u64);
                    const bool_ty = try self.primitiveType(.bool);
                    step.index_expr = try self.localExpr(step.index_local, step.u64_ty);
                    step.out_expr = try self.localExpr(step.out_local, str_ty);

                    const first_cond = try self.lowLevelExpr(.num_is_eq, &.{ step.index_expr, try self.intLiteralExpr(0, step.u64_ty) }, bool_ty);
                    step.sep = try self.ifExpr(first_cond, try self.stringExpr("", str_ty), try self.stringExpr(", ", str_ty), str_ty);
                    const elem = try self.lowLevelExpr(.list_get_unsafe, &.{ step.value, step.index_expr }, step.elem_ty);
                    return .{ .child = .{ .call = .{ .value = elem, .value_ty = step.elem_ty } } };
                }
                const with_sep = try self.concatExpr(step.out_expr, step.sep, str_ty);
                const next_out = try self.concatExpr(with_sep, input.?.expr, str_ty);
                const next_index = try self.lowLevelExpr(.num_plus, &.{ step.index_expr, try self.intLiteralExpr(1, step.u64_ty) }, step.u64_ty);
                return .{ .done = .{ .expr = try self.addExpr(.{
                    .ty = str_ty,
                    .data = .{ .continue_ = .{ .values = try self.addExprSpan(&.{ next_index, next_out }) } },
                }) } };
            },
        }
    }

    /// Render a value by the shape of `shape_ty`, which is `value_ty` or an
    /// inspectable backing reached through it.
    fn stepInspectBody(
        self: *BodyContext,
        value: DraftExprId,
        value_ty: Type.TypeId,
        shape_ty: Type.TypeId,
        str_ty: Type.TypeId,
    ) Allocator.Error!InspectStep {
        return switch (self.typeStore().get(shape_ty)) {
            .primitive => |primitive| .{ .done = .{ .expr = switch (Common.primitiveInspectLowering(primitive)) {
                .low_level => |op| try self.lowLevelExpr(op, &.{value}, str_ty),
                .builtin_method => try self.inspectPrimitiveMethod(value, value_ty, shape_ty, str_ty),
                .bool_tag_union => Common.invariant("Bool must lower as an ordinary tag union before Str.inspect"),
            } } },
            .named => |named| blk: {
                if (named.builtin_owner) |owner| {
                    switch (owner) {
                        .list => {
                            const args = self.typeStore().span(named.args);
                            if (args.len != 1) Common.invariant("List type reached Monotype inspect lowering without one type argument");
                            break :blk .{ .tail = .{ .list = .{ .value = value, .elem_ty = GuardedList.at(args, 0) } } };
                        },
                        .box, .dict, .set, .fields, .field, .bool, .str, .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, .parse_tag_union_spec, .crypto_sha256_digest, .crypto_sha256_hasher, .crypto_blake3_digest, .crypto_blake3_hasher, .iter, .stream => {},
                    }
                }
                if (try self.toInspectCall(value, value_ty, str_ty)) |method_call| break :blk .{ .done = .{ .expr = method_call } };
                const backing = named.backing orelse Common.invariant("Str.inspect reached opaque named type without checked inspect authority");
                if (backing.use != .inspectable) {
                    break :blk .{ .done = .{ .expr = try self.stringExpr("<opaque>", str_ty) } };
                }
                break :blk .{ .tail = .{ .body = .{ .value = value, .value_ty = value_ty, .shape_ty = backing.ty } } };
            },
            .record => |fields| blk: {
                const field_span = self.typeStore().fieldSpan(fields);
                if (field_span.len == 0) break :blk .{ .done = .{ .expr = try self.stringExpr("{}", str_ty) } };
                break :blk .{ .tail = .{ .record = .{ .value = value, .fields = try GuardedList.dupe(self.allocator, Type.Field, field_span) } } };
            },
            .tuple => |items| blk: {
                const item_span = self.typeStore().span(items);
                if (item_span.len == 0) break :blk .{ .done = .{ .expr = try self.stringExpr("()", str_ty) } };
                break :blk .{ .tail = .{ .tuple = .{ .value = value, .items = try GuardedList.dupe(self.allocator, Type.TypeId, item_span) } } };
            },
            .tag_union => |tags| blk: {
                const tag_span = self.typeStore().tagSpan(tags);
                if (tag_span.len == 0) break :blk .{ .done = .{ .expr = try self.uninhabitedInspect(value, str_ty) } };
                break :blk .{ .tail = .{ .tag_union = .{ .value = value, .value_ty = value_ty, .tags = try GuardedList.dupe(self.allocator, Type.Tag, tag_span) } } };
            },
            .list => |elem_ty| .{ .tail = .{ .list = .{ .value = value, .elem_ty = elem_ty } } },
            .func, .erased => .{ .done = .{ .expr = try self.stringExpr("<function>", str_ty) } },
            .zst => .{ .done = .{ .expr = try self.stringExpr("{}", str_ty) } },
            .box => |elem_ty| .{ .tail = .{ .box = .{ .value = value, .elem_ty = elem_ty } } },
        };
    }

    fn uninhabitedInspect(self: *BodyContext, value: DraftExprId, str_ty: Type.TypeId) Allocator.Error!DraftExprId {
        return try self.addExpr(.{
            .ty = str_ty,
            .data = .{ .match_ = .{
                .scrutinee = value,
                .branches = try self.addBranchSpan(&.{}),
            } },
        });
    }

    fn inspectPrimitiveMethod(
        self: *BodyContext,
        value: DraftExprId,
        value_ty: Type.TypeId,
        shape_ty: Type.TypeId,
        str_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        if (value_ty == shape_ty) {
            return (try self.toInspectCall(value, shape_ty, str_ty)) orelse
                Common.invariant("primitive inspect had no checked to_inspect method");
        }

        // Structural inspection may have traversed inspectable nominal backing
        // edges. A method call needs the backing value at its own type, with
        // each nominal layer explicitly destructured in the IR.
        const backing_local = try self.addLocal(self.builder.symbols.fresh(), shape_ty);
        const backing_value = try self.localExpr(backing_local, shape_ty);
        const body = (try self.toInspectCall(backing_value, shape_ty, str_ty)) orelse
            Common.invariant("primitive inspect backing had no checked to_inspect method");
        const pat = try self.addConstructorPat(value_ty, .{ .bind = backing_local });
        return try self.addExpr(.{ .ty = str_ty, .data = .{ .match_ = .{
            .scrutinee = value,
            .branches = try self.addBranchSpan(&.{.{ .pat = pat, .body = body }}),
        } } });
    }

    fn toInspectCall(self: *BodyContext, value: DraftExprId, value_ty: Type.TypeId, str_ty: Type.TypeId) Allocator.Error!?DraftExprId {
        const owner = methodOwnerFromType(self.typeStore(), value_ty) orelse return null;
        const lookup = try self.withLocalProcContext((try self.lookupInspectOverride(owner)) orelse return null);
        const callee = if (self.frozen_inspect_method_calls) |prepared|
            prepared.get(value_ty) orelse
                Common.invariant("deferred inspect method was not reserved before relation freeze")
        else blk: {
            const callable_mono_ty = try self.methodTargetMonoTypeFromArgs(lookup, &.{value_ty}, str_ty);
            break :blk try self.methodTargetCalleeWithMono(lookup, callable_mono_ty);
        };

        const args = [_]DraftExprId{value};
        return try self.addExpr(.{ .ty = str_ty, .data = .{ .call_proc = .{
            .callee = draftProcCalleeForSlot(callee),
            .args = try self.addExprSpan(&args),
            .captures = try self.methodTargetCaptureSpan(lookup),
        } } });
    }

    /// Prepare the inspect method of every inspectable node reachable from
    /// `root`, in the order a direct walk reaches them. Whether any was newly
    /// prepared is the answer.
    fn prepareInspectMethodsAtNode(
        self: *BodyContext,
        root: NodeId,
        str_ty: Type.TypeId,
        seen: *collections.DenseMap(NodeId, void),
    ) Allocator.Error!bool {
        var pending = std.ArrayList(NodeId).empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, root);
        var added = false;
        while (pending.pop()) |node| {
            const entry = try seen.getOrPut(node);
            if (entry.found_existing) continue;

            // Components are pushed last-first so the first is visited next.
            const mark = pending.items.len;
            switch ((try self.graph.content(node))) {
                .primitive => |primitive| switch (Common.primitiveInspectLowering(primitive)) {
                    .builtin_method => added = (try self.prepareToInspectMethodAtNode(
                        node,
                        str_ty,
                        .{ .builtin = checked.builtinOwnerForPrimitive(primitive) },
                    ) orelse Common.invariant("primitive inspect had no checked to_inspect method")) or added,
                    .low_level, .bool_tag_union => {},
                },
                .named => |named| {
                    if (named.builtin_owner == .list) {
                        if (named.args.len != 1) Common.invariant("List inspect graph node did not have one type argument");
                        try pending.append(self.allocator, named.args[0]);
                        continue;
                    }
                    if ((try self.methodOwnerFromNode(node))) |owner| {
                        if (try self.prepareToInspectMethodAtNode(node, str_ty, owner)) |prepared| {
                            added = prepared or added;
                            continue;
                        }
                    }
                    const backing = named.backing orelse continue;
                    if (backing.use != .inspectable) continue;
                    try pending.append(self.allocator, backing.node);
                },
                .list, .box => |child| try pending.append(self.allocator, child),
                .tuple => |items| try pending.appendSlice(self.allocator, items),
                .record => |record| for (record.fields) |field| try pending.append(self.allocator, field.ty),
                .tag_union => |tag_union| for (tag_union.tags) |tag| try pending.appendSlice(self.allocator, tag.payloads),
                .redirect, .leaf => unreachable,
                .unresolved,
                .func,
                .empty_tag_union,
                .empty_record,
                .erased,
                .zst,
                => {},
            }
            std.mem.reverse(NodeId, pending.items[mark..]);
        }
        return added;
    }

    /// Null means the owner has no inspect override; false means it was already
    /// prepared. Both immediate and deferred inspection use the checked target.
    fn prepareToInspectMethodAtNode(
        self: *BodyContext,
        node: NodeId,
        str_ty: Type.TypeId,
        owner: static_dispatch.MethodOwner,
    ) Allocator.Error!?bool {
        const raw_lookup = (try self.lookupInspectOverride(owner)) orelse return null;
        const lookup = try self.withLocalProcContext(raw_lookup);
        for (self.draft.prepared_inspect_methods.items) |prepared| {
            if (self.graph.sameClass(prepared.value_node, node)) return false;
        }
        const ret_node = try self.graph.importMono(str_ty);
        const request_node = try self.graphFunctionNode(&.{node}, ret_node);
        const callee = try self.methodTargetCalleeAtNode(lookup, request_node, null);
        try self.draft.prepared_inspect_methods.append(self.allocator, .{
            .value_node = node,
            .callee = callee,
        });
        return true;
    }

    fn childContext(self: *BodyContext, current_fn_key: names.TypeDigest) Allocator.Error!BodyContext {
        var child = try self.childContextWithTypeCells(current_fn_key, true);
        child.current_return_target = self.current_return_target;
        return child;
    }

    fn inheritFrozenEmissionContext(self: *BodyContext, parent: *const BodyContext) void {
        self.frozen_sealed_emission = parent.frozen_sealed_emission;
        self.frozen_type_finals = parent.frozen_type_finals;
        self.frozen_codec_calls = parent.frozen_codec_calls;
        self.frozen_field_defaults = parent.frozen_field_defaults;
    }

    fn inheritActiveCodecContract(self: *BodyContext, parent: *const BodyContext) Allocator.Error!void {
        const active = parent.active_codec_contract orelse return;
        const calls = parent.activeCodecCalls();
        try self.instantiated_codec_calls.appendSlice(self.allocator, calls);
        self.active_codec_contract = .{
            .view = active.view,
            .derivation = active.derivation,
            .kind = active.kind,
            .evidence = active.evidence,
            .calls_start = 0,
            .calls_len = calls.len,
            .method_call_slots = try self.graph.arena().dupe(CodecMethodCallSlot, active.method_call_slots),
            .grounding_call_index = active.grounding_call_index,
            .constructor_node = active.constructor_node,
            .shape_node = active.shape_node,
        };
    }

    const CallableBodyDemandScope = struct {
        ctx: *BodyContext,
        previous_frames: RuntimeDemandGuardFrameStack,
        previous_entry_guards: []const NodeId,

        fn leave(self: CallableBodyDemandScope) void {
            self.ctx.runtime_demand_guard_frames = self.previous_frames;
            self.ctx.function_entry_demand_guards = self.previous_entry_guards;
        }
    };

    /// Generated callable bodies are callee-local runtime regions. They never
    /// inherit the enclosing statement/branch frames; their entry proof is
    /// exactly their ordered runtime arguments plus explicit captures.
    fn enterCallableBodyDemandScope(
        self: *BodyContext,
        argument_tys: []const Type.TypeId,
        capture_tys: []const Type.TypeId,
    ) Allocator.Error!CallableBodyDemandScope {
        const scope = CallableBodyDemandScope{
            .ctx = self,
            .previous_frames = self.runtime_demand_guard_frames,
            .previous_entry_guards = self.function_entry_demand_guards,
        };
        if (self.frozen_sealed_emission) return self.enterSealedCallableBodyScope(scope);
        const entry_guards = try self.graph.arena().alloc(NodeId, argument_tys.len + capture_tys.len);
        for (argument_tys, entry_guards[0..argument_tys.len]) |ty, *node|
            node.* = try self.activeNodeFromType(ty);
        for (capture_tys, entry_guards[argument_tys.len..]) |ty, *node|
            node.* = try self.activeNodeFromType(ty);
        self.runtime_demand_guard_frames = .{};
        self.function_entry_demand_guards = entry_guards;
        return scope;
    }

    fn enterSealedCallableBodyScope(
        self: *BodyContext,
        scope: CallableBodyDemandScope,
    ) CallableBodyDemandScope {
        self.runtime_demand_guard_frames = .{};
        self.function_entry_demand_guards = &.{};
        return scope;
    }

    fn nestedInstantiationContext(
        self: *BodyContext,
        current_fn_key: names.TypeDigest,
        evidence: EvidenceChain,
        constructing_scheme_vars: []const checked.CheckedTypeId,
    ) Allocator.Error!BodyContext {
        var child = try self.childContextWithTypeCells(current_fn_key, false);
        errdefer child.deinit();
        // The child starts from this context's binder relations, related
        // once for every nested context rather than once by each.
        const relation_base = try self.nestedRelationBase();
        child.instantiation.node_map.deinit();
        child.instantiation.node_map = relation_base.ctx.instantiation.node_map.forkCompleted();
        var kinds = relation_base.ctx.instantiation.field_kind_map.iterator();
        while (kinds.next()) |entry| try child.instantiation.field_kind_map.put(entry.key_ptr.*, entry.value_ptr.*);
        child.evidence = switch (evidence.origin) {
            .specialization => evidence,
            .stored_function => try child.instantiateStoredEvidence(evidence),
        };
        child.function_entry_demand_guards = &.{};
        child.resolves_enclosing_variables = true;
        child.constructing_scheme_vars = constructing_scheme_vars;
        // A variable the base relations instantiated holds the base's node,
        // which the child's evidence may answer differently; the child's
        // answer joins its class, exactly as relating the binders in the
        // child would have joined them.
        for (relation_base.variables.items) |instantiated| {
            if (try child.enclosingVariableNode(instantiated.checked_ty)) |bound| try child.graph.unify(instantiated.node, bound);
        }
        return child;
    }

    /// Every binder in this context's environment related to its local, in a
    /// context of its own that no nested site's bindings have touched yet.
    /// Relating a binder there gives each variable of its type a node in the
    /// class of the local's, exactly what relating it in each nested context
    /// gave; a nested context forks these relations, binds its site's
    /// variables over them, and relates each bound node to the one it
    /// replaces. The relations follow the environment: a new binder is
    /// related on the next request, and one rebound or removed since starts
    /// them over.
    fn nestedRelationBase(self: *BodyContext) Allocator.Error!*NestedRelationBase {
        const entries = try self.binders.sortedEntries(self.allocator);
        defer self.allocator.free(entries);
        if (self.nested_relation_base) |existing| {
            var current: usize = 0;
            var stale = false;
            for (entries) |entry| {
                const local = existing.related.get(entry.binder) orelse continue;
                if (local != entry.local) {
                    stale = true;
                    break;
                }
                current += 1;
            }
            if (!stale and current == existing.related.count()) {
                for (entries) |entry| {
                    if (existing.related.contains(entry.binder)) continue;
                    try existing.relate(entry);
                }
                return existing;
            }
            self.destroyNestedRelationBase();
        }
        const relation_base = try self.allocator.create(NestedRelationBase);
        errdefer self.allocator.destroy(relation_base);
        relation_base.* = .{
            .ctx = try self.childContextWithTypeCells(self.current_fn_key, false),
            .related = collections.DenseMap(checked.PatternBinderId, DraftLocalId).init(self.allocator),
        };
        self.nested_relation_base = relation_base;
        relation_base.ctx.relation_variables = &relation_base.variables;
        for (entries) |entry| try relation_base.relate(entry);
        return relation_base;
    }

    fn destroyNestedRelationBase(self: *BodyContext) void {
        const relation_base = self.nested_relation_base orelse return;
        self.nested_relation_base = null;
        relation_base.ctx.deinit();
        relation_base.related.deinit();
        relation_base.variables.deinit(self.allocator);
        self.allocator.destroy(relation_base);
    }

    /// The cell a nested body's instantiation gives a quantified variable of
    /// an enclosing scope: the substitution of the innermost lexical evidence
    /// frame whose scheme quantifies it. Null leaves the variable fresh: it
    /// belongs to no enclosing scheme, its slot is a checked error, or it is
    /// quantified by the generalized scope under construction.
    fn enclosingVariableNode(self: *BodyContext, variable: checked.CheckedTypeId) Allocator.Error!?NodeId {
        for (self.constructing_scheme_vars) |scheme_var| {
            if (scheme_var == variable) return null;
        }
        return try self.evidenceBinding(variable);
    }

    /// The substitution the innermost frame of this context's evidence chain
    /// whose scheme quantifies `variable` gives it.
    fn evidenceBinding(self: *BodyContext, variable: checked.CheckedTypeId) Allocator.Error!?NodeId {
        var chain: ?*const EvidenceChain = &self.evidence;
        while (chain) |frame| : (chain = frame.parent) {
            const schema = frame.schema orelse continue;
            if (!moduleBytesEqual(schema.view.key.bytes, self.view.key.bytes)) continue;
            const slot = (try self.builder.schemeVarSlot(schema.scheme_vars, variable)) orelse continue;
            if (slot >= frame.subst.len) Common.invariant("evidence frame substitution omitted a quantified variable of its scheme");
            return switch (frame.subst[slot]) {
                .node => |node| node,
                .checked_error => null,
            };
        }
        return null;
    }

    fn childContextWithTypeCells(
        self: *BodyContext,
        current_fn_key: names.TypeDigest,
        copy_type_cells: bool,
    ) Allocator.Error!BodyContext {
        var child = try BodyContext.initWithMethodScope(self.allocator, self.builder, self.view, self.method_scope, self.owner_template, self.graph, self.draft);
        child.evidence = self.evidence;
        errdefer child.deinit();
        child.owner_context_fn_key = self.owner_context_fn_key;
        child.current_fn_key = current_fn_key;
        child.comptime_exhaustiveness_context = self.comptime_exhaustiveness_context;
        child.generated_encoder_source_fn_ty = self.generated_encoder_source_fn_ty;
        child.generated_encoder_source_expr = self.generated_encoder_source_expr;
        child.generated_encoder_lambda_index = self.generated_encoder_lambda_index;
        child.inheritFrozenEmissionContext(self);
        try child.inheritActiveCodecContract(self);
        child.source_region_override = self.source_region_override;
        child.current_entry_root = self.current_entry_root;
        child.in_deferred_body = self.in_deferred_body;
        child.active_const_binding = self.active_const_binding;
        child.runtime_demand_guard_frames = self.runtime_demand_guard_frames;
        child.function_entry_demand_guards = self.function_entry_demand_guards;
        child.propagate_constructor_value_evidence = self.propagate_constructor_value_evidence;
        child.restored_local_proc_scope = self.restored_local_proc_scope;
        child.in_default_expr = self.in_default_expr;
        child.specialization_dispatch_crashes = self.specialization_dispatch_crashes;
        child.owns_specialization_dispatch_crashes = false;
        child.borrowed_specialization_dispatch_divergence = self.specializationDispatchDivergence();

        child.binders.deinit();
        child.binders = self.binders.fork();
        child.typed_binders.deinit();
        child.typed_binders = self.typed_binders.fork();
        child.local_proc_contexts.deinit();
        child.local_proc_contexts = self.local_proc_contexts.fork();

        if (copy_type_cells) {
            child.instantiation.node_map.deinit();
            child.instantiation.node_map = self.instantiation.node_map.forkCompleted();
        }

        try child.loop_contexts.appendSlice(child.allocator, self.loop_contexts.items);

        return child;
    }

    fn enterRestoredLocalProcScope(
        self: *BodyContext,
        nested: Ast.NestedFn,
        base_key: names.TypeDigest,
    ) Allocator.Error!?[]LexicalBinderEntry {
        const digest = nested.local_proc_context_digest orelse {
            self.restored_local_proc_scope = null;
            return null;
        };
        const entries = try self.captureLexicalBinderEntries();
        self.restored_local_proc_scope = .{
            .source_context_digest = digest,
            .base_key = base_key,
            .entries = entries,
        };
        return entries;
    }

    fn cloneLocalProcContext(self: *BodyContext, context: LocalProcContext) Allocator.Error!LocalProcContext {
        return .{
            .declaration = context.declaration,
            .lexical_owner = context.lexical_owner,
            .owner_template = context.owner_template,
            .base_key = context.base_key,
            .restored_specialization_key = context.restored_specialization_key,
            .entries = try self.allocator.dupe(LexicalBinderEntry, context.entries),
            .evidence = context.evidence,
        };
    }

    fn captureCodecLexicalContext(self: *BodyContext) Allocator.Error!DraftCodecLexicalContext {
        const binders = try self.captureLexicalBinderEntries();
        errdefer self.allocator.free(binders);
        const local_procs = try self.allocator.alloc(DraftCodecLocalProcContext, self.local_proc_contexts.count());
        errdefer self.allocator.free(local_procs);
        var initialized: usize = 0;
        var iter = self.local_proc_contexts.iterator();
        while (iter.next()) |entry| {
            local_procs[initialized] = .{
                .declaration = entry.key_ptr.*,
                .context = entry.value_ptr.*,
            };
            initialized += 1;
        }
        sortCodecLocalProcContexts(local_procs);
        return .{ .view = self.view.key.bytes, .binders = binders, .local_procs = local_procs };
    }

    fn codecLexicalContextKey(self: *BodyContext) Allocator.Error!names.TypeDigest {
        const lexical = try self.captureCodecLexicalContext();
        defer self.allocator.free(lexical.binders);
        defer self.allocator.free(lexical.local_procs);

        const binder_key = lexicalContextKeyFromEntries(self.current_fn_key, lexical.binders);
        var hasher = TypeDigestHasher.init();
        hasher.update("roc.monotype.codec_lexical_context");
        hasher.update(&lexical.view);
        hasher.update(&binder_key.bytes);
        for (lexical.local_procs) |proc| {
            hasher.update(&proc.declaration.module);
            hashU32(&hasher, @backingInt(proc.declaration.binder));
            hashU32(&hasher, @backingInt(proc.declaration.expr));
            hashU32(&hasher, @backingInt(proc.context));
        }
        return .{ .bytes = hasher.finalResult() };
    }

    fn sortCodecLocalProcContexts(contexts: []DraftCodecLocalProcContext) void {
        const SortContext = struct {
            pub fn lessThan(_: void, left: DraftCodecLocalProcContext, right: DraftCodecLocalProcContext) bool {
                const module_order = std.mem.order(u8, &left.declaration.module, &right.declaration.module);
                if (module_order != .eq) return module_order == .lt;
                if (left.declaration.binder != right.declaration.binder) {
                    return @backingInt(left.declaration.binder) < @backingInt(right.declaration.binder);
                }
                if (left.declaration.expr != right.declaration.expr) {
                    return @backingInt(left.declaration.expr) < @backingInt(right.declaration.expr);
                }
                return @backingInt(left.context) < @backingInt(right.context);
            }
        };
        std.mem.sort(DraftCodecLocalProcContext, contexts, {}, SortContext.lessThan);
    }

    fn restoreCodecLexicalContext(
        self: *BodyContext,
        lexical: DraftCodecLexicalContext,
    ) Allocator.Error!void {
        if (moduleBytesEqual(lexical.view, self.view.key.bytes)) {
            for (lexical.binders) |entry| switch (entry.kind) {
                0 => try self.binders.put(@fromBackingInt(@intCast(entry.binder)), @fromBackingInt(@intCast(entry.local))),
                1 => try self.typed_binders.put(.{
                    .binder = @fromBackingInt(@intCast(entry.binder)),
                    .type_digest = entry.type_digest,
                }, @fromBackingInt(@intCast(entry.local))),
                else => Common.invariant("deferred lexical context had an unknown binder kind"),
            };
        }
        for (lexical.local_procs) |proc| {
            try self.local_proc_contexts.putPermanent(proc.declaration, proc.context);
        }
    }

    fn captureLocalProcContext(
        self: *BodyContext,
        declaration: DraftLocalProcDeclaration,
    ) Allocator.Error!LocalProcContext {
        return .{
            .declaration = declaration,
            .lexical_owner = self.draft.current_owner,
            .owner_template = self.owner_template,
            .base_key = self.current_fn_key,
            .restored_specialization_key = null,
            .entries = try self.captureLexicalBinderEntries(),
            .evidence = self.evidence,
        };
    }

    fn releaseLocalProcContext(self: *BodyContext, context: LocalProcContext) void {
        self.allocator.free(context.entries);
    }

    fn localProcUseContextKey(self: *BodyContext, context: LocalProcContext) names.TypeDigest {
        if (context.restored_specialization_key) |key| return key;

        // The draft locals establish that every declaration-context binder is
        // available here, but their allocation ids are not callable identity.
        for (context.entries) |entry| {
            switch (entry.kind) {
                0 => {
                    const binder: checked.PatternBinderId = @fromBackingInt(@intCast(entry.binder));
                    _ = self.binders.get(binder) orelse
                        Common.invariant("local procedure use was missing a declaration-context binder");
                },
                1 => {
                    const key = TypedBinder{
                        .binder = @fromBackingInt(@intCast(entry.binder)),
                        .type_digest = entry.type_digest,
                    };
                    _ = self.typed_binders.get(key) orelse
                        Common.invariant("local procedure use was missing a declaration-context typed binder");
                },
                else => Common.invariant("local procedure context had an unknown binder entry kind"),
            }
        }

        return lexicalContextKeyFromEntries(context.base_key, context.entries);
    }

    /// Digest the exact source declaration contexts visible at a nested
    /// callable boundary. ConstStore retains this producer-authored identity
    /// so restoration never infers lexical provenance from a finished type or
    /// from whichever binders happen to be live at the use site.
    fn localProcContextsDigest(self: *BodyContext) Allocator.Error!?names.TypeDigest {
        if (self.restored_local_proc_scope) |restored| return restored.source_context_digest;
        if (self.local_proc_contexts.count() == 0) return null;

        const addresses = try self.allocator.alloc(DraftLocalProcAddress, self.local_proc_contexts.count());
        defer self.allocator.free(addresses);
        var index: usize = 0;
        var iter = self.local_proc_contexts.keyIterator();
        while (iter.next()) |address| : (index += 1) addresses[index] = address.*;
        std.mem.sort(DraftLocalProcAddress, addresses, {}, struct {
            fn lessThan(_: void, left: DraftLocalProcAddress, right: DraftLocalProcAddress) bool {
                const module_order = std.mem.order(u8, &left.module, &right.module);
                if (module_order != .eq) return module_order == .lt;
                if (left.binder != right.binder) return @backingInt(left.binder) < @backingInt(right.binder);
                return @backingInt(left.expr) < @backingInt(right.expr);
            }
        }.lessThan);

        var hasher = TypeDigestHasher.init();
        hasher.update("roc.monotype.local_proc_contexts.v4");
        for (addresses) |address| {
            const context_id = self.local_proc_contexts.get(address) orelse
                Common.invariant("local procedure context disappeared while its digest was produced");
            const context = self.validateLocalProcContext(context_id, address.module, address.binder, address.expr, null);
            hasher.update(&address.module);
            hashU32(&hasher, @backingInt(address.binder));
            hashU32(&hasher, @backingInt(address.expr));
            if (context.declaration.context_anchor) |anchor| {
                hasher.update(&.{1});
                hashU32(&hasher, @backingInt(anchor));
            } else hasher.update(&.{0});
            hasher.update(&names.procTemplateModuleDigest(context.owner_template).bytes);
            hashU32(&hasher, @backingInt(context.owner_template.proc_base));
            hashU32(&hasher, @backingInt(context.owner_template.template));
            hasher.update(&context.base_key.bytes);
            if (context.restored_specialization_key) |key| {
                hasher.update(&.{1});
                hasher.update(&key.bytes);
            } else hasher.update(&.{0});
            for (context.entries) |entry| {
                hasher.update(&.{entry.kind});
                hashU32(&hasher, entry.binder);
                hasher.update(&entry.type_digest.bytes);
            }
        }
        return .{ .bytes = hasher.finalResult() };
    }

    const InstalledLocalProcContext = struct {
        ctx: *BodyContext,
        binders: []checked.PatternBinderId,
        binder_count: usize,
        /// Binders whose declaration-context local replaced the requesting
        /// body's local, with the local to restore.
        replaced: []ReplacedBinder,
        replaced_count: usize,
        typed_binders: []TypedBinder,
        typed_binder_count: usize,

        const ReplacedBinder = struct { binder: checked.PatternBinderId, local: DraftLocalId };

        fn deinit(self: *InstalledLocalProcContext) void {
            for (self.binders[0..self.binder_count]) |binder| {
                if (!self.ctx.binders.remove(binder)) {
                    Common.invariant("installed local procedure binder disappeared before context restoration");
                }
            }
            for (self.replaced[0..self.replaced_count]) |replaced| {
                self.ctx.binders.put(replaced.binder, replaced.local) catch
                    Common.invariant("restoring a replaced local procedure binder needed new capacity");
            }
            self.ctx.allocator.free(self.replaced);
            for (self.typed_binders[0..self.typed_binder_count]) |binder| {
                if (!self.ctx.typed_binders.remove(binder)) {
                    Common.invariant("installed typed local procedure binder disappeared before context restoration");
                }
            }
            self.ctx.allocator.free(self.typed_binders);
            self.ctx.allocator.free(self.binders);
        }
    };

    fn installLocalProcContext(
        self: *BodyContext,
        context: LocalProcContext,
    ) Allocator.Error!InstalledLocalProcContext {
        const binders = try self.allocator.alloc(checked.PatternBinderId, context.entries.len);
        const typed_binders = self.allocator.alloc(TypedBinder, context.entries.len) catch |err| {
            self.allocator.free(binders);
            return err;
        };
        const replaced = self.allocator.alloc(InstalledLocalProcContext.ReplacedBinder, context.entries.len) catch |err| {
            self.allocator.free(typed_binders);
            self.allocator.free(binders);
            return err;
        };
        var installed = InstalledLocalProcContext{
            .ctx = self,
            .binders = binders,
            .binder_count = 0,
            .replaced = replaced,
            .replaced_count = 0,
            .typed_binders = typed_binders,
            .typed_binder_count = 0,
        };
        errdefer installed.deinit();

        for (context.entries) |entry| {
            const local: DraftLocalId = @fromBackingInt(@intCast(entry.local));
            if (@backingInt(local) >= self.draft.locals.items.len) {
                Common.invariant("local procedure declaration context named a local outside its body draft");
            }
            switch (entry.kind) {
                0 => {
                    const binder: checked.PatternBinderId = @fromBackingInt(entry.binder);
                    if (self.binders.get(binder)) |requesting| {
                        // A captured reassignable binder's value is its
                        // snapshot at the declaration
                        // (`snapshotReassignableCaptures`), which the
                        // requesting body's current local no longer holds.
                        if (requesting != local and self.localProcSnapshotsBinder(context.declaration.expr, binder)) {
                            try self.binders.put(binder, local);
                            installed.replaced[installed.replaced_count] = .{ .binder = binder, .local = requesting };
                            installed.replaced_count += 1;
                        }
                        continue;
                    }
                    try self.binders.put(binder, local);
                    installed.binders[installed.binder_count] = binder;
                    installed.binder_count += 1;
                },
                1 => {
                    const binder = TypedBinder{
                        .binder = @fromBackingInt(@intCast(entry.binder)),
                        .type_digest = entry.type_digest,
                    };
                    if (self.typed_binders.contains(binder)) continue;
                    try self.typed_binders.put(binder, local);
                    installed.typed_binders[installed.typed_binder_count] = binder;
                    installed.typed_binder_count += 1;
                },
                else => Common.invariant("local procedure context had an unknown binder entry kind"),
            }
        }
        return installed;
    }

    fn captureLexicalBinderEntries(self: *BodyContext) Allocator.Error![]LexicalBinderEntry {
        const count = self.binders.count() + self.typed_binders.count();
        if (count == 0) return try self.allocator.alloc(LexicalBinderEntry, 0);

        const entries = try self.allocator.alloc(LexicalBinderEntry, count);

        var index: usize = 0;
        var iter = self.binders.iterator();
        while (iter.next()) |entry| {
            entries[index] = .{
                .kind = 0,
                .binder = @backingInt(entry.binder),
                .local = @backingInt(entry.local),
                .type_digest = .{ .bytes = @as([32]u8, @splat(0)) },
            };
            index += 1;
        }
        var typed_iter = self.typed_binders.iterator();
        while (typed_iter.next()) |entry| {
            entries[index] = .{
                .kind = 1,
                .binder = @backingInt(entry.key_ptr.binder),
                .local = @backingInt(entry.value_ptr.*),
                .type_digest = entry.key_ptr.type_digest,
            };
            index += 1;
        }

        sortLexicalBinderEntries(entries);
        return entries;
    }

    fn lexicalContextKeyFromEntries(base_key: names.TypeDigest, entries: []const LexicalBinderEntry) names.TypeDigest {
        if (entries.len == 0) return base_key;
        var hasher = TypeDigestHasher.init();
        hasher.update("roc.monotype.lexical_context.v3");
        hasher.update(&base_key.bytes);
        // `local` installs the checked binder in the active body draft. Its
        // allocation id changes across restoration and is not checked identity.
        for (entries) |entry| {
            hasher.update(&.{entry.kind});
            hashU32(&hasher, entry.binder);
            hasher.update(&entry.type_digest.bytes);
        }
        return .{ .bytes = hasher.finalResult() };
    }

    fn sortLexicalBinderEntries(entries: []LexicalBinderEntry) void {
        const SortContext = struct {
            pub fn lessThan(_: void, a: LexicalBinderEntry, b: LexicalBinderEntry) bool {
                if (a.kind != b.kind) return a.kind < b.kind;
                if (a.binder != b.binder) return a.binder < b.binder;
                const digest_order = std.mem.order(u8, &a.type_digest.bytes, &b.type_digest.bytes);
                if (digest_order != .eq) return digest_order == .lt;
                return a.local < b.local;
            }
        };
        std.mem.sort(LexicalBinderEntry, entries, {}, SortContext.lessThan);
    }

    fn localProcContextEql(allocator: Allocator, left: LocalProcContext, right: LocalProcContext) Allocator.Error!bool {
        if (!std.meta.eql(left.lexical_owner, right.lexical_owner)) return false;
        if (!names.procedureTemplateRefEql(left.owner_template, right.owner_template)) return false;
        if (!std.mem.eql(u8, left.base_key.bytes[0..], right.base_key.bytes[0..])) return false;
        if (!std.meta.eql(left.restored_specialization_key, right.restored_specialization_key)) return false;
        if (!try evidenceChainEql(allocator, left.evidence, right.evidence)) return false;
        if (left.entries.len != right.entries.len) return false;
        for (left.entries, right.entries) |a, b| {
            if (a.kind != b.kind or a.binder != b.binder or a.local != b.local) return false;
            if (!std.mem.eql(u8, a.type_digest.bytes[0..], b.type_digest.bytes[0..])) return false;
        }
        return true;
    }

    fn exprSpan(self: *BodyContext, span: DraftSpan(DraftExprId)) []const DraftExprId {
        if (span.start > self.draft.expr_ids.items.len or span.len > self.draft.expr_ids.items.len - span.start) {
            Common.invariant("Monotype body draft expr span was out of bounds");
        }
        return self.draft.expr_ids.items[span.start..][0..span.len];
    }

    fn patSpan(self: *BodyContext, span: DraftSpan(DraftPatId)) []const DraftPatId {
        if (span.start > self.draft.pat_ids.items.len or span.len > self.draft.pat_ids.items.len - span.start) {
            Common.invariant("Monotype body draft pattern span was out of bounds");
        }
        return self.draft.pat_ids.items[span.start..][0..span.len];
    }

    fn typedLocalSpan(self: *BodyContext, span: DraftSpan(DraftTypedLocal)) []const DraftTypedLocal {
        if (span.start > self.draft.typed_locals.items.len or span.len > self.draft.typed_locals.items.len - span.start) {
            Common.invariant("Monotype body draft typed-local span was out of bounds");
        }
        return self.draft.typed_locals.items[span.start..][0..span.len];
    }

    fn stmtSpan(self: *BodyContext, span: DraftSpan(DraftStmtId)) []const DraftStmtId {
        if (span.start > self.draft.stmt_ids.items.len or span.len > self.draft.stmt_ids.items.len - span.start) {
            Common.invariant("Monotype body draft statement span was out of bounds");
        }
        return self.draft.stmt_ids.items[span.start..][0..span.len];
    }

    fn fieldExprSpan(self: *BodyContext, span: DraftSpan(DraftFieldExpr)) []const DraftFieldExpr {
        if (span.start > self.draft.field_exprs.items.len or span.len > self.draft.field_exprs.items.len - span.start) {
            Common.invariant("Monotype body draft field-expression span was out of bounds");
        }
        return self.draft.field_exprs.items[span.start..][0..span.len];
    }

    /// Whether a function definition is among the values `expr_id` can
    /// evaluate to, searched from an explicit work list.
    fn exprCarriesFunctionDefinitionEvidence(self: *BodyContext, root: DraftExprId) Allocator.Error!bool {
        var pending: std.ArrayListUnmanaged(DraftExprId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, root);
        while (pending.pop()) |expr_id| {
            const start = pending.items.len;
            switch (self.draft.exprs.items[@backingInt(expr_id)].data) {
                .fn_def => return true,
                .list, .tuple => |items| try pending.appendSlice(self.allocator, self.exprSpan(items)),
                .record => |fields| for (self.fieldExprSpan(fields)) |field| try pending.append(self.allocator, field.value),
                .tag => |tag| try pending.appendSlice(self.allocator, self.exprSpan(tag.payloads)),
                .nominal => |backing| try pending.append(self.allocator, backing),
                .let_ => |let_| {
                    try pending.append(self.allocator, let_.value);
                    try pending.append(self.allocator, let_.rest);
                },
                .join_point => |join_point| {
                    try pending.append(self.allocator, join_point.body);
                    try pending.append(self.allocator, join_point.remainder);
                },
                .jump => |jump| {
                    try pending.appendSlice(self.allocator, self.exprSpan(jump.loop_values));
                    try pending.appendSlice(self.allocator, self.exprSpan(jump.args));
                },
                .local,
                .unit,
                .pending_deferred,
                .@"unreachable",
                .int_lit,
                .frac_f32_lit,
                .frac_f64_lit,
                .dec_lit,
                .str_lit,
                .bytes_lit,
                .static_data_candidate,
                .comptime_value,
                .record_update,
                .lambda,
                .def_ref,
                .fn_ref,
                .call_value,
                .call_proc,
                .low_level,
                .field_access,
                .tuple_access,
                .structural_eq,
                .structural_hash,
                .match_,
                .if_,
                .uninitialized,
                .uninitialized_payload,
                .if_initialized_payload,
                .try_sequence,
                .try_record_sequence,
                .block,
                .loop_,
                .break_,
                .continue_,
                .return_,
                .crash,
                .checked_error,
                .comptime_branch_taken,
                .comptime_exhaustiveness_failed,
                .dbg,
                .expect_err,
                .literal_rejected,
                .expect,
                => {},
            }
            std.mem.reverse(DraftExprId, pending.items[start..]);
        }
        return false;
    }

    fn fnDefCaptureSpan(self: *BodyContext, span: DraftSpan(DraftFnDefCapture)) []const DraftFnDefCapture {
        if (span.start > self.draft.fn_def_captures.items.len or span.len > self.draft.fn_def_captures.items.len - span.start) {
            Common.invariant("Monotype body draft fn-def capture span was out of bounds");
        }
        return self.draft.fn_def_captures.items[span.start..][0..span.len];
    }

    fn recordDestructSpan(self: *BodyContext, span: DraftSpan(DraftRecordDestruct)) []const DraftRecordDestruct {
        if (span.start > self.draft.record_destructs.items.len or span.len > self.draft.record_destructs.items.len - span.start) {
            Common.invariant("Monotype body draft record-destruct span was out of bounds");
        }
        return self.draft.record_destructs.items[span.start..][0..span.len];
    }

    fn branchSpan(self: *BodyContext, span: DraftSpan(DraftBranch)) []const DraftBranch {
        if (span.start > self.draft.branches.items.len or span.len > self.draft.branches.items.len - span.start) {
            Common.invariant("Monotype body draft branch span was out of bounds");
        }
        return self.draft.branches.items[span.start..][0..span.len];
    }

    fn ifBranchSpan(self: *BodyContext, span: DraftSpan(DraftIfBranch)) []const DraftIfBranch {
        if (span.start > self.draft.if_branches.items.len or span.len > self.draft.if_branches.items.len - span.start) {
            Common.invariant("Monotype body draft if-branch span was out of bounds");
        }
        return self.draft.if_branches.items[span.start..][0..span.len];
    }

    fn strPatternStepSpan(self: *BodyContext, span: DraftSpan(DraftStrPatternStep)) []const DraftStrPatternStep {
        if (span.start > self.draft.str_pattern_steps.items.len or span.len > self.draft.str_pattern_steps.items.len - span.start) {
            Common.invariant("Monotype body draft string-pattern-step span was out of bounds");
        }
        return self.draft.str_pattern_steps.items[span.start..][0..span.len];
    }

    /// Whether `expr` reads `target` where it is not rebound. Subexpressions
    /// are searched from an explicit continuation stack; binder scopes open
    /// and close as steps of that stack.
    fn exprDependsOnFreeLocal(
        self: *BodyContext,
        expr: DraftExprId,
        target: DraftLocalId,
    ) Allocator.Error!bool {
        var search = DraftFreeLocalSearch{ .ctx = self, .target = target, .bound = collections.DenseMap(DraftLocalId, void).init(self.allocator) };
        defer search.deinit();
        return try search.run(expr);
    }

    const DraftFreeLocalSearch = struct {
        ctx: *BodyContext,
        target: DraftLocalId,
        bound: collections.DenseMap(DraftLocalId, void),
        /// Every local bound so far, in binding order; a scope closes by
        /// unbinding back to its mark.
        bound_log: std.ArrayListUnmanaged(DraftLocalId) = .empty,
        pending: std.ArrayListUnmanaged(Step) = .empty,

        const Step = union(enum) {
            expr: DraftExprId,
            stmt: DraftStmtId,
            local: DraftLocalId,
            bind_pat: DraftPatId,
            bind_typed: DraftSpan(DraftTypedLocal),
            bind_local: DraftLocalId,
            /// Unbind every local bound since this mark.
            unbind: usize,
        };

        fn deinit(search: *DraftFreeLocalSearch) void {
            search.pending.deinit(search.ctx.allocator);
            search.bound_log.deinit(search.ctx.allocator);
            search.bound.deinit();
        }

        fn run(search: *DraftFreeLocalSearch, root: DraftExprId) Allocator.Error!bool {
            const gpa = search.ctx.allocator;
            try search.pending.append(gpa, .{ .expr = root });
            while (search.pending.pop()) |step| {
                const start = search.pending.items.len;
                switch (step) {
                    .expr => |expr_id| if (try search.expandExpr(expr_id)) return true,
                    .stmt => |stmt_id| try search.expandStmt(stmt_id),
                    .local => |local| if (try search.ctx.localDependsOnTarget(local, search.target, &search.bound)) return true,
                    .bind_pat => |pat| try search.bindPat(pat),
                    .bind_typed => |span| for (search.ctx.typedLocalSpan(span)) |local| try search.bind(local.local),
                    .bind_local => |local| try search.bind(local),
                    .unbind => |mark| while (search.bound_log.items.len > mark) {
                        _ = search.bound.remove(search.bound_log.pop().?);
                    },
                }
                std.mem.reverse(Step, search.pending.items[start..]);
            }
            return false;
        }

        fn bind(search: *DraftFreeLocalSearch, local: DraftLocalId) Allocator.Error!void {
            try search.bound.put(local, {});
            try search.bound_log.append(search.ctx.allocator, local);
        }

        fn push(search: *DraftFreeLocalSearch, step: Step) Allocator.Error!void {
            try search.pending.append(search.ctx.allocator, step);
        }

        fn pushExprs(search: *DraftFreeLocalSearch, exprs: []const DraftExprId) Allocator.Error!void {
            for (exprs) |expr| try search.push(.{ .expr = expr });
        }

        /// Bind every local a pattern introduces: an `as` local after its
        /// subpattern's.
        fn bindPat(search: *DraftFreeLocalSearch, root: DraftPatId) Allocator.Error!void {
            const ctx = search.ctx;
            const Visit = union(enum) { pat: DraftPatId, local: DraftLocalId };
            var visits: std.ArrayListUnmanaged(Visit) = .empty;
            defer visits.deinit(ctx.allocator);
            try visits.append(ctx.allocator, .{ .pat = root });
            while (visits.pop()) |visit| {
                const pat_id = switch (visit) {
                    .local => |local| {
                        try search.bind(local);
                        continue;
                    },
                    .pat => |pat_id| pat_id,
                };
                const start = visits.items.len;
                switch (ctx.draft.pats.items[@backingInt(pat_id)].data) {
                    .bind => |local| try search.bind(local),
                    .wildcard,
                    .int_lit,
                    .dec_lit,
                    .frac_f32_lit,
                    .frac_f64_lit,
                    .str_lit,
                    => {},
                    .as => |as| {
                        try visits.append(ctx.allocator, .{ .pat = as.pattern });
                        try visits.append(ctx.allocator, .{ .local = as.local });
                    },
                    .record => |fields| for (ctx.recordDestructSpan(fields)) |field| try visits.append(ctx.allocator, .{ .pat = field.pattern }),
                    .tuple => |items| for (ctx.patSpan(items)) |child| try visits.append(ctx.allocator, .{ .pat = child }),
                    .list => |list| {
                        for (ctx.patSpan(list.patterns)) |child| try visits.append(ctx.allocator, .{ .pat = child });
                        if (list.rest) |rest| if (rest.pattern) |rest_pat| try visits.append(ctx.allocator, .{ .pat = rest_pat });
                    },
                    .tag => |tag| for (ctx.patSpan(tag.payloads)) |payload| try visits.append(ctx.allocator, .{ .pat = payload }),
                    .nominal => |backing| try visits.append(ctx.allocator, .{ .pat = backing }),
                    .str_pattern => |str| for (ctx.strPatternStepSpan(str.steps)) |str_step| {
                        if (str_step.capture) |capture| try visits.append(ctx.allocator, .{ .pat = capture });
                    },
                }
                std.mem.reverse(Visit, visits.items[start..]);
            }
        }

        fn expandStmt(search: *DraftFreeLocalSearch, stmt_id: DraftStmtId) Allocator.Error!void {
            switch (search.ctx.draft.stmts.items[@backingInt(stmt_id)]) {
                .uninitialized => |pat| try search.push(.{ .bind_pat = pat }),
                .let_ => |let_| if (let_.recursive) {
                    try search.push(.{ .bind_pat = let_.pat });
                    try search.push(.{ .expr = let_.value });
                } else {
                    try search.push(.{ .expr = let_.value });
                    try search.push(.{ .bind_pat = let_.pat });
                },
                .expr,
                .expect,
                .dbg,
                => |expr| try search.push(.{ .expr = expr }),
                .return_ => |ret| try search.push(.{ .expr = ret.value }),
                .crash, .checked_error => {},
            }
        }

        /// Queue the steps an expression's search takes; true when the
        /// expression itself reads the target.
        fn expandExpr(search: *DraftFreeLocalSearch, expr_id: DraftExprId) Allocator.Error!bool {
            const ctx = search.ctx;
            const mark = search.bound_log.items.len;
            switch (ctx.draft.exprs.items[@backingInt(expr_id)].data) {
                .pending_deferred => Common.invariant("pending deferred expression reached draft free-local analysis"),
                .local => |local| return try ctx.localDependsOnTarget(local, search.target, &search.bound),
                .@"unreachable",
                .unit,
                .int_lit,
                .frac_f32_lit,
                .frac_f64_lit,
                .dec_lit,
                .str_lit,
                .bytes_lit,
                .uninitialized,
                .crash,
                .checked_error,
                .comptime_exhaustiveness_failed,
                .def_ref,
                .fn_ref,
                => {},
                .uninitialized_payload => |payload| return try ctx.localDependsOnTarget(payload.condition, search.target, &search.bound),
                .list,
                .tuple,
                => |items| try search.pushExprs(ctx.exprSpan(items)),
                .record => |fields| for (ctx.fieldExprSpan(fields)) |field| try search.push(.{ .expr = field.value }),
                .record_update => |update| {
                    try search.push(.{ .expr = update.base });
                    for (ctx.fieldExprSpan(update.fields)) |field| try search.push(.{ .expr = field.value });
                },
                .tag => |tag| try search.pushExprs(ctx.exprSpan(tag.payloads)),
                .static_data_candidate => |candidate| try search.push(.{ .expr = candidate.runtime_expr }),
                .comptime_value => |candidate| try search.push(.{ .expr = candidate.initializer }),
                .nominal,
                .dbg,
                .expect,
                => |child| try search.push(.{ .expr = child }),
                .return_ => |ret| try search.push(.{ .expr = ret.value }),
                .expect_err => |expect_err| try search.push(.{ .expr = expect_err.msg }),
                .literal_rejected => |rejected| try search.push(.{ .expr = rejected.msg }),
                .comptime_branch_taken => |taken| try search.push(.{ .expr = taken.body }),
                .let_ => |let_| {
                    try search.push(.{ .expr = let_.value });
                    try search.push(.{ .bind_pat = let_.bind });
                    try search.push(.{ .expr = let_.rest });
                    try search.push(.{ .unbind = mark });
                },
                .lambda => |lambda| {
                    try search.push(.{ .bind_typed = lambda.args });
                    try search.push(.{ .expr = lambda.body });
                    try search.push(.{ .unbind = mark });
                },
                .fn_def => |fn_def| for (ctx.fnDefCaptureSpan(fn_def.captures)) |capture| try search.push(.{ .expr = capture.value }),
                .call_value => |call| {
                    try search.push(.{ .expr = call.callee });
                    try search.pushExprs(ctx.exprSpan(call.args));
                },
                .call_proc => |call| {
                    try search.pushExprs(ctx.exprSpan(call.args));
                    try search.pushExprs(ctx.exprSpan(call.captures));
                },
                .low_level => |call| try search.pushExprs(ctx.exprSpan(call.args)),
                .field_access => |field| try search.push(.{ .expr = field.receiver }),
                .tuple_access => |access| try search.push(.{ .expr = access.tuple }),
                .structural_eq => |eq| {
                    try search.push(.{ .expr = eq.lhs });
                    try search.push(.{ .expr = eq.rhs });
                },
                .structural_hash => |hash| {
                    try search.push(.{ .expr = hash.value });
                    try search.push(.{ .expr = hash.hasher });
                },
                .match_ => |match| {
                    try search.push(.{ .expr = match.scrutinee });
                    for (ctx.branchSpan(match.branches)) |branch| {
                        try search.push(.{ .bind_pat = branch.pat });
                        for (ctx.stmtSpan(branch.bindings)) |stmt| try search.push(.{ .stmt = stmt });
                        if (branch.guard) |guard| try search.push(.{ .expr = guard });
                        try search.push(.{ .expr = branch.body });
                        try search.push(.{ .unbind = mark });
                    }
                },
                .if_ => |if_| {
                    for (ctx.ifBranchSpan(if_.branches)) |branch| {
                        try search.push(.{ .expr = branch.cond });
                        try search.push(.{ .expr = branch.body });
                    }
                    try search.push(.{ .expr = if_.final_else });
                },
                .if_initialized_payload => |payload| {
                    try search.push(.{ .expr = payload.cond });
                    try search.push(.{ .local = payload.payload });
                    try search.push(.{ .expr = payload.initialized });
                    try search.push(.{ .expr = payload.uninitialized });
                },
                .try_sequence => |sequence| {
                    try search.push(.{ .expr = sequence.try_expr });
                    try search.push(.{ .bind_local = sequence.ok_local });
                    try search.push(.{ .expr = sequence.ok_body });
                    try search.push(.{ .unbind = mark });
                },
                .try_record_sequence => |sequence| {
                    try search.push(.{ .expr = sequence.try_expr });
                    try search.push(.{ .bind_local = sequence.value_local });
                    try search.push(.{ .bind_local = sequence.rest_local });
                    try search.push(.{ .expr = sequence.ok_body });
                    try search.push(.{ .unbind = mark });
                },
                .block => |block| {
                    for (ctx.stmtSpan(block.statements)) |stmt| try search.push(.{ .stmt = stmt });
                    try search.push(.{ .expr = block.final_expr });
                    try search.push(.{ .unbind = mark });
                },
                .loop_ => |loop| {
                    try search.pushExprs(ctx.exprSpan(loop.initial_values));
                    try search.push(.{ .bind_typed = loop.params });
                    try search.push(.{ .expr = loop.body });
                    try search.push(.{ .unbind = mark });
                },
                .break_ => |maybe| if (maybe) |value| try search.push(.{ .expr = value }),
                .continue_ => |continue_| try search.pushExprs(ctx.exprSpan(continue_.values)),
                .join_point => |join_point| {
                    for (ctx.typedLocalSpan(join_point.retained)) |retained| try search.push(.{ .local = retained.local });
                    try search.push(.{ .bind_typed = join_point.params });
                    try search.push(.{ .expr = join_point.body });
                    try search.push(.{ .unbind = mark });
                    try search.push(.{ .expr = join_point.remainder });
                },
                .jump => |jump| {
                    try search.pushExprs(ctx.exprSpan(jump.loop_values));
                    try search.pushExprs(ctx.exprSpan(jump.args));
                },
            }
            return false;
        }
    };

    fn localDependsOnTarget(
        self: *BodyContext,
        local: DraftLocalId,
        target: DraftLocalId,
        bound: *collections.DenseMap(DraftLocalId, void),
    ) Allocator.Error!bool {
        if (!try self.sameLocalIdentity(local, target)) return false;
        return !try self.boundContainsLocalIdentity(bound, local);
    }

    fn boundContainsLocalIdentity(
        self: *BodyContext,
        bound: *collections.DenseMap(DraftLocalId, void),
        local: DraftLocalId,
    ) Allocator.Error!bool {
        if (bound.contains(local)) return true;
        var iter = bound.keyIterator();
        while (iter.next()) |active| {
            if (try self.sameLocalIdentity(active.*, local)) return true;
        }
        return false;
    }

    fn sameLocalIdentity(self: *BodyContext, lhs: DraftLocalId, rhs: DraftLocalId) Allocator.Error!bool {
        if (lhs == rhs) return true;
        const lhs_data = self.draft.locals.items[@backingInt(lhs)];
        const rhs_data = self.draft.locals.items[@backingInt(rhs)];
        if (lhs_data.binder == null or rhs_data.binder == null or lhs_data.binder.? != rhs_data.binder.?) {
            return false;
        }
        const lhs_node = try lhs_data.ty.toGraphNode(self.graph);
        const rhs_node = try rhs_data.ty.toGraphNode(self.graph);
        return self.graph.sameClass(lhs_node, rhs_node);
    }

    /// Constrain a checked type to a Monotype: instantiate the checked type
    /// into the graph and unify with the (linked or imported) Monotype node.
    fn constrainTypeToMono(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        mono_ty: Type.TypeId,
    ) Allocator.Error!void {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        try self.graph.unify(try self.instNode(checked_ty), try self.graph.importMono(mono_ty));
    }

    fn requireClosedCheckedType(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        mono_ty: Type.TypeId,
    ) Allocator.Error!void {
        if (!try self.checkedTypeSealsWithoutSpecialization(checked_ty)) {
            Common.invariant("sealed Monotype cell was paired with a checked type that needs a specialization input");
        }
        const lowered = try self.lowerType(checked_ty);
        if (!self.sameType(lowered, mono_ty)) {
            Common.invariant("sealed Monotype cell differed from its closed checked type");
        }
    }

    fn constrainTypeToCell(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        cell: DraftTypeCell,
    ) Allocator.Error!void {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        try self.graph.unify(try self.instNode(checked_ty), try cell.toGraphNode(self.graph));
    }

    /// Relate a checked public interface to an exact producer-owned value
    /// representation without allowing that private representation to replace
    /// the checked type node shared by other source occurrences. A binding's
    /// draft cell retains the private node directly; the fresh checked node is
    /// only its source-level interface proof.
    fn constrainCheckedInterfaceToCell(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        cell: DraftTypeCell,
    ) Allocator.Error!void {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        const value_node = try cell.toGraphNode(self.graph);
        if (try self.graph.containsGeneratedPrivate(value_node)) {
            try self.graph.relateOpaqueInterface(try self.freshInstNode(checked_ty), value_node);
        } else {
            try self.constrainTypeToCell(checked_ty, cell);
        }
    }

    /// Constrain two checked types from (possibly different) instantiation
    /// contexts of the same specialization to denote one type.
    fn constrainCheckedTypeRelations(
        self: *BodyContext,
        left_ty: checked.CheckedTypeId,
        right_ctx: *BodyContext,
        right_ty: checked.CheckedTypeId,
    ) Allocator.Error!void {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        if (self.graph != right_ctx.graph) {
            Common.invariant("checked type relation crossed specialization graphs");
        }
        try self.graph.unify(try self.instNode(left_ty), try right_ctx.instNode(right_ty));
    }

    fn monoAliasBacking(types: *const Type.Store, mono_ty: Type.TypeId) ?Type.TypeId {
        return switch (types.get(mono_ty)) {
            .named => |named| if (named.kind == .alias) blk: {
                const backing = named.backing orelse break :blk null;
                break :blk backing.ty;
            } else null,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => null,
        };
    }

    fn constrainKnownType(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        mono_ty: Type.TypeId,
    ) Allocator.Error!void {
        // The graph cross-check can only run while relations are producing.
        // Only a context explicitly marked as sealed-emission skips it: the
        // frozen-graph boundary emitters (deferred structural serialization
        // and callsite intrinsics, e.g. a generated parser body
        // materializing a field default per specialization—design.md
        // "Defaulted Fields") lower sealed expressions whose produced type
        // every call site verifies with its `sameType` invariant. Any other
        // frozen-phase caller is a bug and fails loudly inside
        // `constrainTypeToMono` (the graph's relation-production
        // requirement) instead of silently losing the cross-check.
        if (self.frozen_sealed_emission) return;
        try self.constrainTypeToMono(checked_ty, mono_ty);
    }

    fn scopedCheckedType(self: *BodyContext, checked_ty: checked.CheckedTypeId) checked.CheckedTypeId {
        if (!moduleBytesEqual(self.instantiation.module_bytes, self.view.key.bytes)) {
            Common.invariant("checked type lookup used an instantiation context owned by another module");
        }
        return checked_ty;
    }

    fn lowerTypeNode(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!NodeId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        return try self.instNode(checked_ty);
    }

    /// Whether a checked type reaches the error type. Checked types are
    /// immutable, so answers are memoized per module for the compilation:
    /// every type a scan without an error visited is error-free too.
    fn checkedTypeContainsError(self: *BodyContext, root: checked.CheckedTypeId) Allocator.Error!bool {
        const memo = &self.builder.checked_type_contains_error;
        if (memo.get(checkedTypeAddress(self.view, root))) |known| return known;
        var visited = collections.DenseMap(checked.CheckedTypeId, void).init(self.allocator);
        defer visited.deinit();
        var visited_order: std.ArrayList(checked.CheckedTypeId) = .empty;
        defer visited_order.deinit(self.allocator);
        var pending: std.ArrayList(checked.CheckedTypeId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, root);
        while (pending.pop()) |checked_ty| {
            if (visited.contains(checked_ty)) continue;
            if (memo.get(checkedTypeAddress(self.view, checked_ty))) |known| {
                if (!known) continue;
                try memo.put(self.builder.allocator, checkedTypeAddress(self.view, root), true);
                return true;
            }
            try visited.put(checked_ty, {});
            try visited_order.append(self.allocator, checked_ty);
            switch (checkedPayload(self.view, checked_ty)) {
                .pending => Common.invariant("pending checked type reached Monotype error scan"),
                .err => {
                    try memo.put(self.builder.allocator, checkedTypeAddress(self.view, root), true);
                    return true;
                },
                .flex, .rigid, .empty_record, .empty_tag_union => {},
                .alias => |alias| {
                    try pending.append(self.allocator, alias.backing);
                    try pending.appendSlice(self.allocator, alias.args);
                },
                .record => |record| {
                    for (record.fields) |field| try pending.append(self.allocator, field.ty);
                    try pending.append(self.allocator, record.ext);
                },
                .tuple => |items| try pending.appendSlice(self.allocator, items),
                .nominal => |nominal| {
                    try pending.appendSlice(self.allocator, nominal.args);
                    try pending.appendSlice(self.allocator, nominal.padding_field_types);
                },
                .function => |function| {
                    try pending.appendSlice(self.allocator, function.args);
                    try pending.append(self.allocator, function.ret);
                },
                .tag_union => |tag_union| {
                    for (tag_union.tags) |tag| try pending.appendSlice(self.allocator, tag.argsSlice(self.view.types));
                    try pending.append(self.allocator, tag_union.ext);
                },
            }
        }
        for (visited_order.items) |checked_ty| {
            try memo.put(self.builder.allocator, checkedTypeAddress(self.view, checked_ty), false);
        }
        return false;
    }

    /// Whether a checked type is built only from functions, tuples, empty
    /// rows, primitives, and variables. No representation evidence can attach
    /// to any part of such a type: generated-private representations belong
    /// to nominal types, and a variable's cell is its binding's. Answers are
    /// memoized per module for the compilation, like `checkedTypeContainsError`.
    fn checkedTypeRepresentationFixed(self: *BodyContext, root: checked.CheckedTypeId) Allocator.Error!bool {
        const memo = &self.builder.checked_type_representation_fixed;
        if (memo.get(checkedTypeAddress(self.view, root))) |known| return known;
        var visited = collections.DenseMap(checked.CheckedTypeId, void).init(self.allocator);
        defer visited.deinit();
        var visited_order: std.ArrayList(checked.CheckedTypeId) = .empty;
        defer visited_order.deinit(self.allocator);
        var pending: std.ArrayList(checked.CheckedTypeId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, root);
        while (pending.pop()) |checked_ty| {
            if (visited.contains(checked_ty)) continue;
            if (memo.get(checkedTypeAddress(self.view, checked_ty))) |known| {
                if (known) continue;
                try memo.put(self.builder.allocator, checkedTypeAddress(self.view, root), false);
                return false;
            }
            try visited.put(checked_ty, {});
            try visited_order.append(self.allocator, checked_ty);
            const fixed = switch (checkedPayload(self.view, checked_ty)) {
                .flex, .rigid, .empty_record, .empty_tag_union => true,
                .tuple => |items| blk: {
                    try pending.appendSlice(self.allocator, items);
                    break :blk true;
                },
                .function => |function| blk: {
                    try pending.appendSlice(self.allocator, function.args);
                    try pending.append(self.allocator, function.ret);
                    break :blk true;
                },
                .nominal => |nominal| switch (nominal.representation) {
                    .builtin => |builtin| checked.builtinRuntimeEncoding(builtin) == .primitive,
                    .local_declaration, .imported_declaration, .local_box_payload_capability, .imported_box_payload_capability, .opaque_without_backing => false,
                },
                .alias, .record, .tag_union, .pending, .err => false,
            };
            if (!fixed) {
                try memo.put(self.builder.allocator, checkedTypeAddress(self.view, root), false);
                return false;
            }
        }
        for (visited_order.items) |checked_ty| {
            try memo.put(self.builder.allocator, checkedTypeAddress(self.view, checked_ty), true);
        }
        return true;
    }

    fn activeNodeFromType(self: *BodyContext, ty: Type.TypeId) Allocator.Error!NodeId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        if (self.graph.activeSnapshotNode(ty)) |node| return node;
        return try self.graph.importMono(ty);
    }

    fn lowerTypeCell(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!DraftTypeCell {
        return DraftTypeCell.fromGraphNode(try self.lowerTypeNode(checked_ty));
    }

    fn resolvedTypeViewForNode(self: *BodyContext, node: NodeId) Allocator.Error!Type.TypeId {
        if (!try self.graph.typeIsResolved(node)) {
            Common.invariant("resolved Monotype view requested for an unresolved instantiation node");
        }
        return try self.activeTypeFromNode(node);
    }

    fn currentPhaseTypeForNode(self: *BodyContext, node: NodeId) Allocator.Error!Type.TypeId {
        if (self.frozen_sealed_emission) {
            const finals = self.frozen_type_finals orelse
                Common.invariant("frozen Monotype emission had no graph type finalizer");
            return try finals.sealNode(node);
        }
        return try self.resolvedTypeViewForNode(node);
    }

    fn lowerTypeView(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!Type.TypeId {
        return try self.activeTypeFromCell(try self.lowerTypeCell(checked_ty));
    }

    fn graphFunctionNode(
        self: *BodyContext,
        args: []const NodeId,
        ret: NodeId,
    ) Allocator.Error!NodeId {
        const stored_args = try self.graph.arena().alloc(NodeId, args.len);
        @memcpy(stored_args, args);
        return try self.graph.newNode(.{ .func = .{
            .args = stored_args,
            .ret = ret,
        } });
    }

    fn graphFunctionNodeFromMono(
        self: *BodyContext,
        arg_tys: []const Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!NodeId {
        const args = try self.graph.arena().alloc(NodeId, arg_tys.len);
        for (arg_tys, 0..) |arg_ty, index| {
            args[index] = try self.graph.importMono(arg_ty);
        }
        return try self.graphFunctionNode(args, try self.graph.importMono(ret_ty));
    }

    fn graphFunctionTypeCellFromMono(
        self: *BodyContext,
        arg_tys: []const Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftTypeCell {
        return DraftTypeCell.fromGraphNode(try self.graphFunctionNodeFromMono(arg_tys, ret_ty));
    }

    fn hashFnTypeCell(self: *BodyContext, value_ty: Type.TypeId, hasher_ty: Type.TypeId) Allocator.Error!DraftTypeCell {
        const args = [_]Type.TypeId{ value_ty, hasher_ty };
        return try self.graphFunctionTypeCellFromMono(&args, hasher_ty);
    }

    /// Instantiate a checked type into this specialization's graph, caching by
    /// checked identity so every occurrence of the same checked root resolves
    /// to the same node within this instantiation context.
    fn instNode(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!NodeId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        var task = InstNodeTask{ .checked_ty = checked_ty };
        if (try self.probeInstNode(&task)) |existing| return existing;
        return (try self.runInst(.{ .node = task })).get(.node);
    }

    fn instNominalDeclarationBackingNode(
        self: *BodyContext,
        source: NominalInstantiationSource,
        args: []NodeId,
    ) Allocator.Error!NodeId {
        return (try self.runInst(.{ .decl_backing = try self.boxInstTask(InstDeclBackingTask, .{ .source = source, .args = args }) })).get(.node);
    }

    // Instantiation //
    //
    // A checked type instantiates its component types from inside its own
    // instantiation. Each such computation suspends as an `InstFrame` on one
    // heap-backed stack while a component instantiates, so type nesting never
    // becomes native call depth. Frames issue components in the order a
    // direct recursive instantiation visited them, so graph nodes, names, and
    // scopes are created in the same order.

    const InstTask = union(enum) {
        node: InstNodeTask,
        slice: InstSliceTask,
        fields: InstFieldsTask,
        tags: InstTagsTask,
        /// Boxed, like `decl_backing` and `declared_order`: the three are far
        /// larger than every other task, and pooled frame stacks hold one
        /// frame per nesting level.
        nominal: *InstNominalTask,
        declared_order: *InstDeclaredOrderTask,
        decl_backing: *InstDeclBackingTask,
    };

    const InstResult = union(enum) {
        node: NodeId,
        nodes: []NodeId,
        fields: []InstField,
        tags: []InstTag,
        declared_order: []const InstDeclaredField,

        fn get(self: InstResult, comptime tag: std.meta.Tag(InstResult)) @FieldType(InstResult, @tagName(tag)) {
            if (std.meta.activeTag(self) != tag) Common.invariant("Monotype instantiation frame received the wrong result kind");
            return @field(self, @tagName(tag));
        }
    };

    const InstFrame = struct {
        cursor: u8 = 0,
        index: usize = 0,
        task: InstTask,
    };

    const InstStep = union(enum) {
        call: InstTask,
        ret: InstResult,
    };

    fn deinitSpareInstFrames(self: *BodyContext) void {
        for (self.spare_inst_frames.items) |*frames| frames.deinit(self.allocator);
        self.spare_inst_frames.deinit(self.allocator);
    }

    fn runInst(self: *BodyContext, root: InstTask) Allocator.Error!InstResult {
        // Reserve the slot this run's stack returns to before taking one.
        try self.spare_inst_frames.ensureUnusedCapacity(self.allocator, 1);
        var frames: std.ArrayList(InstFrame) = self.spare_inst_frames.pop() orelse .empty;
        defer {
            frames.clearRetainingCapacity();
            self.spare_inst_frames.appendAssumeCapacity(frames);
        }
        errdefer {
            // Scopes nest, so the innermost frame releases first.
            var index = frames.items.len;
            while (index > 0) {
                index -= 1;
                self.releaseInstFrame(&frames.items[index]);
                self.destroyInstTaskBox(frames.items[index].task);
            }
        }
        frames.append(self.allocator, .{ .task = root }) catch |err| {
            self.destroyInstTaskBox(root);
            return err;
        };
        var input: ?InstResult = null;
        while (true) {
            const frame = &frames.items[frames.items.len - 1];
            switch (try self.stepInst(frame, input)) {
                .call => |called| {
                    const pushed = frames.addOne(self.allocator) catch |err| {
                        self.destroyInstTaskBox(called);
                        return err;
                    };
                    // A frame is written in place, one variant's worth.
                    pushed.cursor = 0;
                    pushed.index = 0;
                    writeActiveVariant(InstTask, &pushed.task, called);
                    input = null;
                    // Most checked types are already instantiated in their
                    // scope; such a request answers without keeping a frame.
                    if (pushed.task == .node) {
                        const probed = self.probeInstNode(&pushed.task.node) catch |err| {
                            frames.items.len -= 1;
                            return err;
                        };
                        if (probed) |existing| {
                            frames.items.len -= 1;
                            input = .{ .node = existing };
                        }
                    }
                },
                .ret => |result| {
                    self.destroyInstTaskBox(frames.items[frames.items.len - 1].task);
                    frames.items.len -= 1;
                    if (frames.items.len == 0) return result;
                    input = result;
                },
            }
        }
    }

    inline fn boxInstTask(self: *BodyContext, comptime T: type, task: T) Allocator.Error!*T {
        const boxed = try self.allocator.create(T);
        boxed.* = task;
        return boxed;
    }

    fn destroyInstTaskBox(self: *BodyContext, task: InstTask) void {
        switch (task) {
            inline .nominal, .declared_order, .decl_backing => |boxed| self.allocator.destroy(boxed),
            .node, .slice, .fields, .tags => {},
        }
    }

    /// Undo what an unfinished frame installed.
    fn releaseInstFrame(self: *BodyContext, frame: *InstFrame) void {
        switch (frame.task) {
            .node => |*task| if (task.reserved) {
                const removed = self.scopedNodeMap(task.scoped_ty).remove(task.scoped_ty);
                std.debug.assert(removed);
            },
            inline .decl_backing, .declared_order => |task| self.leaveDeclBackingScopes(task),
            .slice, .fields, .tags, .nominal => {},
        }
    }

    fn stepInst(self: *BodyContext, frame: *InstFrame, input: ?InstResult) Allocator.Error!InstStep {
        return switch (frame.task) {
            .node => |*task| self.stepInstNode(frame, task, input),
            .slice => |*task| self.stepInstSlice(frame, task, input),
            .fields => |*task| self.stepInstFields(frame, task, input),
            .tags => |*task| self.stepInstTags(frame, task, input),
            .nominal => |task| self.stepInstNominal(frame, task, input),
            .declared_order => |task| self.stepInstDeclaredOrder(frame, task, input),
            .decl_backing => |task| self.stepInstDeclBacking(frame, task, input),
        };
    }

    fn instNodeStep(checked_ty: checked.CheckedTypeId) InstStep {
        return .{ .call = .{ .node = .{ .checked_ty = checked_ty } } };
    }

    fn instSliceStep(checked_tys: []const checked.CheckedTypeId) InstStep {
        return .{ .call = .{ .slice = .{ .checked_tys = checked_tys } } };
    }

    const InstNodeTask = struct {
        checked_ty: checked.CheckedTypeId,
        scoped_ty: checked.CheckedTypeId = undefined,
        /// Whether `probeInstNode` already looked this type up and missed.
        probed: bool = false,
        /// Whether this frame registered `scoped_ty` as building.
        reserved: bool = false,
        /// A component instantiated before the last one.
        first: InstResult = undefined,
        /// What the frame instantiates next once its pending component
        /// returns, recorded when its payload was decoded.
        next: Next = .none,

        const Next = union(enum) {
            none,
            alias: struct { args: []const checked.CheckedTypeId, backing: checked.CheckedTypeId },
            record_ext: checked.CheckedTypeId,
            tuple,
            function_ret: checked.CheckedTypeId,
            tag_union_ext: checked.CheckedTypeId,
            nominal,
        };
    };

    /// The node `task`'s checked type already has in its scope; null, with
    /// the task marked probed, when it must be instantiated.
    fn probeInstNode(self: *BodyContext, task: *InstNodeTask) Allocator.Error!?NodeId {
        self.builder.countBodyDiagnostic("checked_node_requests");
        task.scoped_ty = self.scopedCheckedType(task.checked_ty);
        if (try self.scopedNode(task.scoped_ty)) |existing| {
            self.builder.countBodyDiagnostic("checked_node_cache_hits");
            return existing;
        }
        if (try self.closedTypeLeaf(task.scoped_ty)) |leaf| return leaf;
        task.probed = true;
        return null;
    }

    /// The leaf a closed checked type instantiates to in a leaf-instantiating
    /// context, recorded as its node there; null when the type builds its
    /// structure instead.
    fn closedTypeLeaf(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!?NodeId {
        const scope, const mono = switch (self.instantiation.closed_types) {
            .structure => return null,
            .leaves => |scope| blk: {
                if (!self.checkedTypeIsClosed(checked_ty)) return null;
                break :blk .{ scope, try self.closedCheckedMono(checked_ty) };
            },
            .measuring => |scope| blk: {
                if (!self.checkedTypeIsClosed(checked_ty)) return null;
                break :blk .{ scope, self.graph.closedCheckedMono(self.view.key.bytes, checked_ty) orelse return null };
            },
        };
        const node = try self.graph.checkedLeaf(scope, mono);
        try self.instantiation.node_map.put(checked_ty, .{ .node = node });
        return node;
    }

    /// The Monotype a closed checked type of this context's module denotes.
    /// One that is not known yet is measured: instantiated in a fresh
    /// measuring context, where every closed type whose Monotype is known
    /// stays a leaf, and sealed together with every closed type the build
    /// reached.
    fn closedCheckedMono(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!Type.TypeId {
        if (self.graph.closedCheckedMono(self.view.key.bytes, checked_ty)) |known| return known;
        const previous = self.instantiation;
        self.instantiation = TypeInstantiationContext.init(self.allocator, self.builder.allocateInstantiationScope(), self.view.key.bytes);
        defer {
            self.instantiation.deinit();
            self.instantiation = previous;
        }
        self.instantiation.closed_types = .{ .measuring = try self.graph.newLeafScope() };
        _ = try self.instNode(checked_ty);
        try self.graph.recordClosedCheckedMonos(self.view.key.bytes, self.instantiation.measured.items);
        return self.graph.closedCheckedMono(self.view.key.bytes, checked_ty) orelse
            Common.invariant("measuring a closed checked type did not record its Monotype");
    }

    fn stepInstNode(self: *BodyContext, frame: *InstFrame, task: *InstNodeTask, input: ?InstResult) Allocator.Error!InstStep {
        if (frame.cursor == 0) {
            if (!task.probed) {
                if (try self.probeInstNode(task)) |existing| return .{ .ret = .{ .node = existing } };
            }
            self.builder.countBodyDiagnostic("checked_node_cache_misses");
            try self.scopedNodeMap(task.scoped_ty).put(task.scoped_ty, .{ .building = null });
            task.reserved = true;
            frame.cursor = 1;
        }
        const built: NodeId = built: {
            // A resumed frame continues from what its first step recorded,
            // so a checked payload is decoded once per instantiation.
            if (input) |result| switch (task.next) {
                .none => Common.invariant("Monotype instantiation frame resumed without a pending component"),
                .alias => |alias| {
                    frame.index += 1;
                    if (frame.index < alias.args.len) return instNodeStep(alias.args[frame.index]);
                    if (frame.index == alias.args.len) return instNodeStep(alias.backing);
                    break :built result.get(.node);
                },
                .record_ext => |ext| {
                    if (frame.cursor == 1) {
                        task.first = result;
                        frame.cursor = 2;
                        return instNodeStep(ext);
                    }
                    break :built try self.graph.newNode(.{ .record = .{
                        .fields = task.first.get(.fields),
                        .ext = result.get(.node),
                    } });
                },
                .tuple => break :built try self.graph.newNode(.{ .tuple = result.get(.nodes) }),
                .function_ret => |ret| {
                    if (frame.cursor == 1) {
                        task.first = result;
                        frame.cursor = 2;
                        return instNodeStep(ret);
                    }
                    break :built try self.graph.newNode(.{ .func = .{
                        .args = task.first.get(.nodes),
                        .ret = result.get(.node),
                    } });
                },
                .tag_union_ext => |ext| {
                    if (frame.cursor == 1) {
                        task.first = result;
                        frame.cursor = 2;
                        return instNodeStep(ext);
                    }
                    break :built try self.graph.newNode(.{ .tag_union = .{
                        .tags = task.first.get(.tags),
                        .ext = result.get(.node),
                    } });
                },
                .nominal => break :built result.get(.node),
            };
            switch (checkedPayload(self.view, task.checked_ty)) {
                .pending => Common.invariant("pending checked type reached Monotype instantiation"),
                .err => Common.invariant("erroneous checked type reached Monotype instantiation"),
                .flex, .rigid => |variable| {
                    const variable_node = resolved: {
                        if (self.resolves_enclosing_variables) {
                            if (try self.enclosingVariableNode(task.checked_ty)) |bound| break :resolved bound;
                        }
                        break :resolved try self.graph.newNode(.{ .unresolved = InstVariable.checkedVariable(
                            variable.numeric_default_phase,
                            variable.row_default,
                        ) });
                    };
                    if (self.relation_variables) |variables| {
                        try variables.append(self.allocator, .{ .checked_ty = task.checked_ty, .node = variable_node });
                    }
                    break :built variable_node;
                },
                .empty_record => break :built try self.graph.newNode(.empty_record),
                .empty_tag_union => break :built try self.graph.newNode(.empty_tag_union),
                // Aliases are checked views, not value identities. Instantiate
                // their parameter cells in this scope, then use the explicit
                // backing cell, just as alias-transparent unification does.
                .alias => |alias| {
                    task.next = .{ .alias = .{ .args = alias.args, .backing = alias.backing } };
                    if (alias.args.len != 0) return instNodeStep(alias.args[0]);
                    return instNodeStep(alias.backing);
                },
                .record => |record| {
                    task.next = .{ .record_ext = record.ext };
                    return .{ .call = .{ .fields = .{ .fields = record.fields } } };
                },
                .tuple => |items| {
                    task.next = .tuple;
                    return instSliceStep(items);
                },
                .function => |function| {
                    task.next = .{ .function_ret = function.ret };
                    return instSliceStep(function.args);
                },
                .tag_union => |tag_union| {
                    task.next = .{ .tag_union_ext = tag_union.ext };
                    return .{ .call = .{ .tags = .{ .tags = tag_union.tags } } };
                },
                .nominal => |nominal| {
                    task.next = .nominal;
                    return .{ .call = .{ .nominal = try self.boxInstTask(InstNominalTask, .{ .checked_ty = task.checked_ty, .nominal = nominal }) } };
                },
            }
        };
        const map = self.scopedNodeMap(task.scoped_ty);
        var entry = map.get(task.scoped_ty).?;
        const node = try entry.finish(self.graph, built);
        try map.put(task.scoped_ty, entry);
        task.reserved = false;
        if (self.instantiation.decl_scopes.items.len == 0 and try self.instantiatedNodeIsPure(task.scoped_ty)) {
            try self.recordPureInstance(task.scoped_ty, node);
        }
        switch (self.instantiation.closed_types) {
            .structure, .leaves => {},
            .measuring => if (self.checkedTypeIsClosed(task.scoped_ty)) {
                try self.instantiation.measured.append(self.allocator, .{ .checked_ty = task.scoped_ty, .node = node });
            },
        }
        return .{ .ret = .{ .node = node } };
    }

    // Pure instances //
    //
    // An instance of a checked type is pure under this context's evidence
    // when every variable it reaches is the substitution the evidence gives
    // that variable and every other part is a function, tuple, empty row, or
    // primitive. Such an instance has no cell of its own that a later
    // relation could refine: its variables are the evidence's shared cells,
    // and no representation evidence can attach to the rest. Two pure
    // instances of one checked type under one evidence are therefore the
    // same type wherever they occur, so a fresh pure instance related to a
    // class that already holds one adds nothing to that class.

    fn instantiatedNodeIsPure(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!bool {
        return switch (checkedPayload(self.view, checked_ty)) {
            .function => |function| {
                for (function.args) |arg| {
                    if (!try self.instantiatedChildIsPure(arg)) return false;
                }
                return try self.instantiatedChildIsPure(function.ret);
            },
            .tuple => |items| {
                for (items) |item| {
                    if (!try self.instantiatedChildIsPure(item)) return false;
                }
                return true;
            },
            .empty_record, .empty_tag_union => true,
            .nominal => |nominal| switch (nominal.representation) {
                .builtin => |builtin| checked.builtinRuntimeEncoding(builtin) == .primitive,
                .local_declaration, .imported_declaration, .local_box_payload_capability, .imported_box_payload_capability, .opaque_without_backing => false,
            },
            // A variable is pure exactly when it is its evidence binding,
            // which `instantiatedChildIsPure` reads directly.
            .flex, .rigid, .alias, .record, .tag_union, .pending, .err => false,
        };
    }

    fn instantiatedChildIsPure(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!bool {
        const node = (try self.scopedNode(checked_ty)) orelse return false;
        return switch (checkedPayload(self.view, checked_ty)) {
            .flex, .rigid => {
                const bound = (try self.evidenceBinding(checked_ty)) orelse return false;
                return self.graph.sameClass(bound, node);
            },
            .function, .tuple, .empty_record, .empty_tag_union, .nominal, .alias, .record, .tag_union, .pending, .err => self.instantiation.pure_nodes.contains(node),
        };
    }

    /// An evidence chain's substitutions and schemes are immutable, live as
    /// long as the graph, and its parents are shared frames, so the head
    /// frame's scheme, substitution, and parent name every binding the chain
    /// gives.
    fn pureInstanceKey(self: *const BodyContext, checked_ty: checked.CheckedTypeId) solve.PureInstanceKey {
        return .{
            .module_bytes = self.view.key.bytes,
            .checked_ty = @backingInt(checked_ty),
            .scheme_vars_ptr = if (self.evidence.schema) |schema| @intFromPtr(schema.scheme_vars.ptr) else 0,
            .subst_ptr = @intFromPtr(self.evidence.subst.ptr),
            .subst_len = self.evidence.subst.len,
            .parent = if (self.evidence.parent) |parent| @intFromPtr(parent) else 0,
        };
    }

    fn recordPureInstance(self: *BodyContext, checked_ty: checked.CheckedTypeId, node: NodeId) Allocator.Error!void {
        try self.instantiation.pure_nodes.put(node, {});
        try self.graph.recordPureInstance(self.pureInstanceKey(checked_ty), node);
    }

    /// Whether `node`'s class already holds a pure instance of `checked_ty`
    /// under this context's evidence. Instantiating the type afresh and
    /// relating it to `node` would then add nothing, so this context can use
    /// `node` as its instance.
    fn holdsPureInstance(self: *BodyContext, checked_ty: checked.CheckedTypeId, node: NodeId) bool {
        const instance = self.graph.pureInstance(self.pureInstanceKey(checked_ty)) orelse return false;
        return self.graph.sameClass(instance, node);
    }

    /// Use `node`, whose class holds a pure instance of `checked_ty` under
    /// this context's evidence, as this context's instance of that type.
    fn adoptPureInstance(self: *BodyContext, checked_ty: checked.CheckedTypeId, node: NodeId) Allocator.Error!void {
        try self.putScopedNode(self.scopedCheckedType(checked_ty), node);
        try self.instantiation.pure_nodes.put(node, {});
    }

    const InstSliceTask = struct {
        checked_tys: []const checked.CheckedTypeId,
        out: []NodeId = &.{},
    };

    fn stepInstSlice(self: *BodyContext, frame: *InstFrame, task: *InstSliceTask, input: ?InstResult) Allocator.Error!InstStep {
        if (frame.cursor == 0) {
            task.out = try self.graph.arena().alloc(NodeId, task.checked_tys.len);
            frame.cursor = 1;
        } else {
            task.out[frame.index] = input.?.get(.node);
            frame.index += 1;
        }
        if (frame.index < task.checked_tys.len) return instNodeStep(task.checked_tys[frame.index]);
        return .{ .ret = .{ .nodes = task.out } };
    }

    const InstFieldsTask = struct {
        fields: []const checked.CheckedRecordField,
        out: []InstField = &.{},
    };

    fn stepInstFields(self: *BodyContext, frame: *InstFrame, task: *InstFieldsTask, input: ?InstResult) Allocator.Error!InstStep {
        if (frame.cursor == 0) {
            task.out = try self.graph.arena().alloc(InstField, task.fields.len);
            frame.cursor = 1;
        } else {
            task.out[frame.index] = try self.instField(task.fields[frame.index], input.?.get(.node));
            frame.index += 1;
        }
        if (frame.index < task.fields.len) return instNodeStep(task.fields[frame.index].ty);
        return .{ .ret = .{ .fields = task.out } };
    }

    fn instField(self: *BodyContext, field: checked.CheckedRecordField, value_node: NodeId) Allocator.Error!InstField {
        const name = try self.recordFieldName(self.view, field.name);
        const default = try self.builder.monoFieldDefault(self.view, field);
        return switch (field.kind.tag) {
            .required => .{ .name = name, .ty = value_node, .kind = .required, .default = null },
            .defaulted => .{
                .name = name,
                .ty = value_node,
                .kind = .{ .defaulted = default orelse Common.invariant("defaulted checked field carried no default identity") },
                .default = default,
            },
            .optional => .{
                .name = name,
                .ty = try self.optionalSlotNode(value_node),
                .value_ty = value_node,
                .kind = .optional,
                .default = null,
            },
            .undetermined => blk: {
                const checked_kind = self.scopedCheckedType(field.kind.undeterminedVariable() orelse
                    Common.invariant("undetermined checked field kind carried no presence variable"));
                if (self.scopedFieldKind(checked_kind)) |existing| {
                    try self.graph.unify(existing.value, value_node);
                    break :blk .{
                        .name = name,
                        .ty = existing.slot,
                        .value_ty = existing.value,
                        .kind = .{ .undetermined = existing.id },
                        .default = null,
                    };
                }
                const slot_node = try self.graph.newNode(.{ .unresolved = InstVariable.placeholder() });
                const kind = try self.graph.newUndeterminedFieldKind();
                self.graph.registerUndeterminedFieldKindCells(kind, slot_node, value_node);
                const instantiated = InstantiatedFieldKind{
                    .id = kind,
                    .slot = slot_node,
                    .value = value_node,
                };
                try self.putScopedFieldKind(checked_kind, instantiated);
                break :blk .{
                    .name = name,
                    .ty = instantiated.slot,
                    .value_ty = instantiated.value,
                    .kind = .{ .undetermined = instantiated.id },
                    .default = null,
                };
            },
            .err => Common.invariant("poisoned checked field kind reached Monotype instantiation"),
        };
    }

    const InstTagsTask = struct {
        tags: []const checked.CheckedTag,
        out: []InstTag = &.{},
    };

    fn stepInstTags(self: *BodyContext, frame: *InstFrame, task: *InstTagsTask, input: ?InstResult) Allocator.Error!InstStep {
        if (frame.cursor == 0) {
            task.out = try self.graph.arena().alloc(InstTag, task.tags.len);
            frame.cursor = 1;
        } else {
            task.out[frame.index].payloads = input.?.get(.nodes);
            frame.index += 1;
        }
        if (frame.index < task.tags.len) {
            const tag = task.tags[frame.index];
            task.out[frame.index] = .{
                .name = try self.tagName(self.view, tag.name),
                .checked_name = try self.tagName(self.view, tag.name),
                .payloads = undefined,
            };
            return instSliceStep(tag.argsSlice(self.view.types));
        }
        return .{ .ret = .{ .tags = task.out } };
    }

    const InstNominalTask = struct {
        checked_ty: checked.CheckedTypeId,
        nominal: checked.CheckedNominalType,
        args: []NodeId = &.{},
        backing: ?InstBacking = null,
        def: Type.TypeDef = undefined,
        named_type: Type.NamedType = undefined,
    };

    /// Cursor states of a nominal instantiation.
    const InstNominalCursor = struct {
        const start = 0;
        const builtin_elem = 1;
        const args = 2;
        const backing = 3;
        const declared_order = 4;
    };

    fn stepInstNominal(self: *BodyContext, frame: *InstFrame, task: *InstNominalTask, input: ?InstResult) Allocator.Error!InstStep {
        const nominal = &task.nominal;
        switch (frame.cursor) {
            InstNominalCursor.start => {
                switch (nominal.representation) {
                    .builtin => |builtin| switch (checked.builtinRuntimeEncoding(builtin)) {
                        .primitive => |primitive| return .{ .ret = .{ .node = try self.graph.newNode(.{ .primitive = primitive }) } },
                        .bool_tag_union => {},
                        .list => {
                            if (nominal.args.len != 1) Common.invariant("checked List nominal must have exactly one type argument");
                            frame.cursor = InstNominalCursor.builtin_elem;
                            return instNodeStep(nominal.args[0]);
                        },
                        .box => {
                            if (nominal.args.len != 1) Common.invariant("checked Box nominal must have exactly one type argument");
                            frame.cursor = InstNominalCursor.builtin_elem;
                            return instNodeStep(nominal.args[0]);
                        },
                        .try_nominal,
                        .iterator,
                        .parse_tag_union_spec,
                        .fields,
                        .field,
                        .dict,
                        .set,
                        .crypto_sha256_digest,
                        .crypto_sha256_hasher,
                        .crypto_blake3_digest,
                        .crypto_blake3_hasher,
                        => {},
                    },
                    .local_declaration, .imported_declaration, .local_box_payload_capability, .imported_box_payload_capability, .opaque_without_backing => {},
                }
                frame.cursor = InstNominalCursor.args;
                return instSliceStep(nominal.args);
            },
            InstNominalCursor.builtin_elem => {
                const elem = input.?.get(.node);
                return .{ .ret = .{ .node = try self.graph.newNode(switch (checked.builtinRuntimeEncoding(nominal.representation.builtin)) {
                    .list => .{ .list = elem },
                    .box => .{ .box = elem },
                    .primitive, .bool_tag_union, .try_nominal, .iterator, .parse_tag_union_spec, .fields, .field, .dict, .set, .crypto_sha256_digest, .crypto_sha256_hasher, .crypto_blake3_digest, .crypto_blake3_hasher => Common.invariant("builtin nominal element resumed for a builtin without one"),
                }) } };
            },
            InstNominalCursor.args => {
                task.args = input.?.get(.nodes);
                switch (nominal.representation) {
                    .opaque_without_backing => {},
                    .builtin, .local_declaration, .imported_declaration, .local_box_payload_capability, .imported_box_payload_capability => {
                        const source = self.nominalInstantiationSource(nominal) orelse
                            Common.invariant("nominal backing instantiation could not resolve a declaration-backed nominal");
                        frame.cursor = InstNominalCursor.backing;
                        return .{ .call = .{ .decl_backing = try self.boxInstTask(InstDeclBackingTask, .{ .source = source, .args = task.args }) } };
                    },
                }
                return self.instNominalDeclaredOrder(frame, task);
            },
            InstNominalCursor.backing => {
                task.backing = .{
                    .node = input.?.get(.node),
                    .use = if (nominal.is_opaque) .runtime_layout_only else .inspectable,
                };
                return self.instNominalDeclaredOrder(frame, task);
            },
            InstNominalCursor.declared_order => return .{ .ret = .{ .node = try self.graph.newNode(try self.graph.namedContent(.{
                .named_type = task.named_type,
                .def = task.def,
                .kind = if (nominal.is_opaque) .@"opaque" else .nominal,
                .builtin_owner = builtinOwner(nominal.builtin),
                .args = task.args,
                .backing = task.backing,
                .declared_order = input.?.get(.declared_order),
            })) } },
            InstNominalCursor.declared_order + 1...std.math.maxInt(u8) => unreachable,
        }
    }

    fn instNominalDeclaredOrder(self: *BodyContext, frame: *InstFrame, task: *InstNominalTask) Allocator.Error!InstStep {
        const nominal = task.nominal;
        task.def = try self.typeDef(self.view, nominal.origin_module, nominal.name, nominal.source_decl);
        self.builder.noteBuiltinTryDef(nominal.builtin, self.nameStore(), task.def);
        task.named_type = .{ .module = self.builder.declaredModuleForNominal(self.view, nominal), .ty = task.checked_ty };
        frame.cursor = InstNominalCursor.declared_order;
        return .{ .call = .{ .declared_order = try self.boxInstTask(InstDeclaredOrderTask, .{ .nominal = nominal, .args = task.args }) } };
    }

    /// A nominal instance's declared field order. Its padding types
    /// instantiate in the declaring view, with the declaration's formals bound
    /// to this instance's argument nodes, exactly as its backing instantiates.
    const InstDeclaredOrderTask = struct {
        nominal: checked.CheckedNominalType,
        args: []NodeId,
        lookup: Builder.NominalDeclLookup = undefined,
        /// The view and instantiation context the declaring module replaced.
        outer: ?struct { view: ModuleView, instantiation: TypeInstantiationContext } = null,
        scope: ?*InstantiatingNodeMap = null,
        field_kind_scope: ?*collections.DenseMap(checked.CheckedTypeId, InstantiatedFieldKind) = null,
        scope_pushed: bool = false,
        field_kind_scope_pushed: bool = false,
    };

    fn stepInstDeclaredOrder(self: *BodyContext, frame: *InstFrame, task: *InstDeclaredOrderTask, input: ?InstResult) Allocator.Error!InstStep {
        if (frame.cursor == 0) {
            task.lookup = self.builder.nominalDeclarationFor(self.view, task.nominal) orelse {
                if (!nominalHasDeclarationBacking(task.nominal)) return .{ .ret = .{ .declared_order = &.{} } };
                Common.invariant("declaration-backed nominal reached Monotype instantiation without declaration data");
            };
            const fields = task.lookup.declaration.declaredRecordFields(task.lookup.view.types);
            if (fields.len == 0) return .{ .ret = .{ .declared_order = &.{} } };
            if (task.lookup.padding_field_tys.len == 0) return .{ .ret = .{ .declared_order = try self.instDeclaredOrderEntries(task, &.{}) } };
            frame.cursor = 1;
            try self.enterDeclScopes(task, task.lookup.view, task.lookup.declaration, task.args);
            return instSliceStep(task.lookup.padding_field_tys);
        }
        const padding_nodes = input.?.get(.nodes);
        self.leaveDeclBackingScopes(task);
        return .{ .ret = .{ .declared_order = try self.instDeclaredOrderEntries(task, padding_nodes) } };
    }

    fn instDeclaredOrderEntries(self: *BodyContext, task: *InstDeclaredOrderTask, padding_nodes: []const NodeId) Allocator.Error![]InstDeclaredField {
        const fields = task.lookup.declaration.declaredRecordFields(task.lookup.view.types);
        const entries = try self.graph.arena().alloc(InstDeclaredField, fields.len);
        var padding_cursor: usize = 0;
        for (fields, entries) |field, *entry| {
            switch (field) {
                .named => |label| entry.* = .{ .named = try self.recordFieldName(task.lookup.view, label) },
                .padding => {
                    if (padding_cursor >= padding_nodes.len) {
                        Common.invariant("nominal declaration had more unnamed fields than recorded padding types");
                    }
                    entry.* = .{ .padding = padding_nodes[padding_cursor] };
                    padding_cursor += 1;
                },
            }
        }
        return entries;
    }

    /// Instantiate a nominal instance's backing. A declaration-backed nominal's
    /// formals and backing share one set of checked roots across every instance
    /// of the nominal, so the backing instantiates inside a fresh scope seeded
    /// with this instance's argument nodes: two instances of the same nominal at
    /// different arguments stay independent.
    ///
    /// Termination: the checker's `validateNominalDeclArgumentGrowth` rejects
    /// any declaration group whose formal-flow graph carries a growing edge
    /// inside a cycle, and any recursive mention argument holding a variable
    /// that is no formal of the mentioning declaration. What remains keeps
    /// the reachable argument tuples finite here: a formal argument resolves
    /// in the innermost scope to this instance's own argument cell, so the
    /// recursive lookup hits the placeholder registered below before the
    /// backing expands; a closed argument memoizes once per instantiation
    /// context, so nested expansions present the same cell; and a
    /// formal-wrapping argument only occurs on acyclic flow edges, so the
    /// fresh cells it mints never feed back into their own declaration.
    const InstDeclBackingTask = struct {
        source: NominalInstantiationSource,
        args: []NodeId,
        placeholder: NodeId = undefined,
        /// The view and instantiation context the backing's module replaced.
        outer: ?struct { view: ModuleView, instantiation: TypeInstantiationContext } = null,
        scope: ?*InstantiatingNodeMap = null,
        field_kind_scope: ?*collections.DenseMap(checked.CheckedTypeId, InstantiatedFieldKind) = null,
        scope_pushed: bool = false,
        field_kind_scope_pushed: bool = false,
    };

    fn stepInstDeclBacking(self: *BodyContext, frame: *InstFrame, task: *InstDeclBackingTask, input: ?InstResult) Allocator.Error!InstStep {
        const source = task.source;
        if (frame.cursor == 1) {
            self.leaveDeclBackingScopes(task);
            try self.graph.unify(task.placeholder, input.?.get(.node));
            return .{ .ret = .{ .node = task.placeholder } };
        }
        const declaration_id: u32 = @backingInt(source.declaration.id);
        if (self.graph.nominalBackingNode(source.view.key.bytes, declaration_id, task.args)) |cached| {
            self.builder.count("nominal_backing_reuses");
            return .{ .ret = .{ .node = cached } };
        }
        self.builder.count("nominal_backing_instantiations");

        task.placeholder = try self.graph.newNode(.{ .unresolved = InstVariable.placeholder() });
        try self.graph.putNominalBackingNode(source.view.key.bytes, declaration_id, task.args, task.placeholder);

        frame.cursor = 1;
        try self.enterDeclScopes(task, source.view, source.declaration, task.args);
        return instNodeStep(source.declaration.backing);
    }

    /// Enter `view` (when it is not the current one) and push declaration
    /// scopes binding `declaration`'s formals to `args`, recording on `task`
    /// what `leaveDeclBackingScopes` undoes.
    fn enterDeclScopes(
        self: *BodyContext,
        task: anytype,
        view: ModuleView,
        declaration: checked.CheckedNominalDeclaration,
        args: []const NodeId,
    ) Allocator.Error!void {
        if (!moduleBytesEqual(view.key.bytes, self.view.key.bytes)) {
            task.outer = .{ .view = self.view, .instantiation = self.instantiation };
            self.view = view;
            self.instantiation = TypeInstantiationContext.init(self.allocator, self.builder.allocateInstantiationScope(), view.key.bytes);
        }

        const formal_args = declaration.formalArgs(self.view.types);
        if (formal_args.len != args.len) {
            Common.invariant("checked nominal declaration arity differed from nominal type use");
        }
        const scope = try self.allocator.create(InstantiatingNodeMap);
        scope.* = InstantiatingNodeMap.init(self.allocator);
        task.scope = scope;
        const field_kind_scope = try self.allocator.create(collections.DenseMap(checked.CheckedTypeId, InstantiatedFieldKind));
        field_kind_scope.* = collections.DenseMap(checked.CheckedTypeId, InstantiatedFieldKind).init(self.allocator);
        task.field_kind_scope = field_kind_scope;
        for (formal_args, args) |formal, arg| {
            try scope.put(self.scopedCheckedType(formal), .{ .node = arg });
        }
        try self.instantiation.decl_scopes.append(self.allocator, scope);
        task.scope_pushed = true;
        try self.instantiation.field_kind_decl_scopes.append(self.allocator, field_kind_scope);
        task.field_kind_scope_pushed = true;
    }

    /// Pop and free the declaration scopes `task` pushed, then restore the
    /// view and instantiation context it replaced.
    fn leaveDeclBackingScopes(self: *BodyContext, task: anytype) void {
        if (task.field_kind_scope_pushed) {
            _ = self.instantiation.field_kind_decl_scopes.pop();
            task.field_kind_scope_pushed = false;
        }
        if (task.scope_pushed) {
            _ = self.instantiation.decl_scopes.pop();
            task.scope_pushed = false;
        }
        if (task.field_kind_scope) |field_kind_scope| {
            field_kind_scope.deinit();
            self.allocator.destroy(field_kind_scope);
            task.field_kind_scope = null;
        }
        if (task.scope) |scope| {
            scope.deinit();
            self.allocator.destroy(scope);
            task.scope = null;
        }
        if (task.outer) |outer| {
            self.instantiation.deinit();
            self.instantiation = outer.instantiation;
            self.view = outer.view;
            task.outer = null;
        }
    }

    fn freshInstNode(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!NodeId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        self.builder.countBodyDiagnostic("fresh_checked_node_requests");
        const previous = self.instantiation;
        self.instantiation = TypeInstantiationContext.init(self.allocator, self.builder.allocateInstantiationScope(), self.view.key.bytes);
        defer {
            self.instantiation.deinit();
            self.instantiation = previous;
        }
        return try self.instNode(checked_ty);
    }

    /// Resolve a checked type's memoized instantiation node. A closed checked
    /// type (no identity variables anywhere, field kinds included) means the
    /// same thing under every declaration scope, so it memoizes at the
    /// instantiation-context level; an open type's meaning depends on the
    /// innermost declaration scope's formal bindings, so it memoizes there
    /// and only there. An outer declaration scope must never answer an open
    /// lookup: the same open checked type mentioned at two nesting levels of
    /// a recursive declaration expansion binds the formals differently, and
    /// an outer answer would collapse those distinct types into one node.
    fn scopedNodeMap(self: *BodyContext, checked_ty: checked.CheckedTypeId) *InstantiatingNodeMap {
        const scopes = self.instantiation.decl_scopes.items;
        if (scopes.len == 0 or self.checkedTypeIsClosed(checked_ty)) {
            return &self.instantiation.node_map;
        }
        return scopes[scopes.len - 1];
    }

    fn scopedNode(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!?NodeId {
        const map = self.scopedNodeMap(checked_ty);
        var entry = map.get(checked_ty) orelse return null;
        if (entry == .node) return entry.node;
        const node = try entry.get(self.graph);
        try map.put(checked_ty, entry);
        return node;
    }

    fn putScopedNode(self: *BodyContext, checked_ty: checked.CheckedTypeId, node: NodeId) Allocator.Error!void {
        try self.scopedNodeMap(checked_ty).put(checked_ty, .{ .node = node });
        // A leaf read later reaches a closed component through its leaf
        // scope, so the scope names the same node for it.
        switch (self.instantiation.closed_types) {
            .structure, .measuring => {},
            .leaves => |scope| if (self.checkedTypeIsClosed(checked_ty)) {
                try self.graph.bindCheckedLeaf(scope, try self.closedCheckedMono(checked_ty), node);
            },
        }
    }

    /// Field-kind memoization scopes exactly like `scopedNode`. A kind cell
    /// is looked up by its undetermined variable's checked type, and a
    /// variable is always open, so inside a declaration expansion this
    /// resolves in the innermost scope; the closed branch exists only to
    /// keep the routing rule identical to `scopedNode`'s.
    fn scopedFieldKind(self: *BodyContext, checked_ty: checked.CheckedTypeId) ?InstantiatedFieldKind {
        const scopes = self.instantiation.field_kind_decl_scopes.items;
        if (scopes.len == 0 or self.checkedTypeIsClosed(checked_ty)) {
            return self.instantiation.field_kind_map.get(checked_ty);
        }
        return scopes[scopes.len - 1].get(checked_ty);
    }

    fn putScopedFieldKind(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        field_kind: InstantiatedFieldKind,
    ) Allocator.Error!void {
        const scopes = self.instantiation.field_kind_decl_scopes.items;
        if (scopes.len == 0 or self.checkedTypeIsClosed(checked_ty)) {
            try self.instantiation.field_kind_map.put(checked_ty, field_kind);
            return;
        }
        try scopes[scopes.len - 1].put(checked_ty, field_kind);
    }

    /// The instantiation-graph node of an optional field's tagged slot: the
    /// closed structural union `[#Missing, #Present(value)]`, matching
    /// `Builder.optionalSlotType` exactly so graph-solved and directly-lowered
    /// occurrences of one checked row seal to the same Monotype.
    fn optionalSlotNode(self: *BodyContext, value_node: NodeId) Allocator.Error!NodeId {
        const missing = try self.nameStoreMut().internTagLabel(Builder.optional_slot_missing_tag);
        const present = try self.nameStoreMut().internTagLabel(Builder.optional_slot_present_tag);
        const tags = try self.graph.arena().alloc(InstTag, 2);
        tags[0] = .{
            .name = missing,
            .checked_name = missing,
            .payloads = try self.graph.arena().alloc(NodeId, 0),
        };
        const present_payloads = try self.graph.arena().alloc(NodeId, 1);
        present_payloads[0] = value_node;
        tags[1] = .{
            .name = present,
            .checked_name = present,
            .payloads = present_payloads,
        };
        return try self.graph.newNode(.{ .tag_union = .{
            .tags = tags,
            .ext = try self.graph.newNode(.empty_tag_union),
        } });
    }

    const NominalInstantiationSource = struct {
        view: ModuleView,
        declaration: checked.CheckedNominalDeclaration,
    };

    fn nominalInstantiationSource(
        self: *BodyContext,
        nominal: *const checked.CheckedNominalType,
    ) ?NominalInstantiationSource {
        return switch (nominal.representation) {
            .local_declaration => |id| .{
                .view = self.view,
                .declaration = self.view.types.nominalDeclarationById(id),
            },
            .local_box_payload_capability => blk: {
                const lookup = self.builder.nominalDeclarationFor(self.view, nominal.*) orelse
                    Common.invariant("local box-payload nominal had no declaration source");
                break :blk .{
                    .view = lookup.view,
                    .declaration = lookup.declaration,
                };
            },
            .imported_declaration => |imported| blk: {
                const source_view = self.builder.moduleForId(checked.importedNominalDeclarationModuleId(imported));
                break :blk .{
                    .view = source_view,
                    .declaration = source_view.types.nominalDeclarationById(imported.declaration),
                };
            },
            .imported_box_payload_capability => blk: {
                const lookup = self.builder.nominalDeclarationFor(self.view, nominal.*) orelse
                    Common.invariant("imported box-payload nominal had no declaration source");
                break :blk .{
                    .view = lookup.view,
                    .declaration = lookup.declaration,
                };
            },
            .builtin => blk: {
                const lookup = self.builder.nominalDeclarationFor(self.view, nominal.*) orelse break :blk null;
                break :blk .{
                    .view = lookup.view,
                    .declaration = lookup.declaration,
                };
            },
            .opaque_without_backing => null,
        };
    }

    fn lowerTemplateBodyAtNode(
        self: *BodyContext,
        template_ref: names.ProcTemplate,
        template: checked.CheckedProcedureTemplate,
        fn_node: NodeId,
    ) Allocator.Error!LoweredTemplateBody {
        var timing_scope = ProcedureTimingScope.begin(self.builder.timing, .body_lowering);
        defer timing_scope.end();

        if (!names.procedureTemplateRefEql(self.owner_template, template_ref)) {
            Common.invariant("Monotype body context owner did not match lowered checked template");
        }
        const fn_nodes = try self.graph.functionNodes(fn_node);
        const saved_function_entry_demand_guards = self.function_entry_demand_guards;
        defer self.function_entry_demand_guards = saved_function_entry_demand_guards;
        self.function_entry_demand_guards = fn_nodes.args;
        const ret_cell = DraftTypeCell.fromGraphNode(fn_nodes.ret);
        return switch (template.body) {
            .checked_body => |body_id| blk: {
                const body = self.view.bodies.body(body_id);
                const root = self.view.bodies.expr(body.root_expr);
                break :blk switch (root.data) {
                    .lambda => |lambda| try self.lowerLambdaTemplateAtNode(body.root_expr, lambda, fn_node),
                    .closure => |closure| closure_blk: {
                        if (closure.captures.len != 0) {
                            Common.invariant("checked procedure template root closure had captures");
                        }
                        const lambda_expr = self.view.bodies.expr(closure.lambda);
                        if (lambda_expr.data != .lambda) Common.invariant("checked procedure template root closure did not point at a lambda");
                        break :closure_blk try self.lowerLambdaTemplateAtNode(closure.lambda, lambda_expr.data.lambda, fn_node);
                    },
                    .hosted_lambda => Common.invariant("hosted lambda template must lower through hosted metadata, not source lambda body"),
                    .pending,
                    .numeral,
                    .str_from_quote,
                    .str_segment,
                    .str,
                    .bytes_literal,
                    .lookup_local,
                    .lookup_external,
                    .lookup_required,
                    .list,
                    .empty_list,
                    .tuple,
                    .match_,
                    .if_,
                    .call,
                    .record,
                    .empty_record,
                    .block,
                    .tag,
                    .nominal,
                    .zero_argument_tag,
                    .binop,
                    .unary_minus,
                    .unary_not,
                    .field_access,
                    .dispatch_call,
                    .interpolation,
                    .structural_eq,
                    .structural_hash,
                    .method_eq,
                    .type_dispatch_call,
                    .tuple_access,
                    .runtime_error,
                    .crash,
                    .dbg,
                    .expect_err,
                    .expect,
                    .ellipsis,
                    .anno_only,
                    .break_,
                    .return_,
                    .for_,
                    .run_low_level,
                    => .{
                        .args = .empty(),
                        .body = try self.lowerExprAtTypeCell(body.root_expr, ret_cell),
                        .ret = ret_cell,
                    },
                };
            },
            .unimplemented => |declaration| return try self.lowerUnimplementedTemplateAtNode(declaration, fn_nodes, ret_cell),
            .entry_wrapper => |wrapper_id| return try self.lowerEntryWrapperAtCell(wrapper_id, ret_cell),
            .intrinsic_wrapper => |wrapper_id| {
                const wrapper = self.view.intrinsic_wrappers.get(wrapper_id);
                return switch (wrapper.intrinsic) {
                    .str_inspect => try self.lowerStrInspectIntrinsicAtNode(fn_nodes, ret_cell),
                    .structural_eq => Common.invariant("structural equality intrinsic wrapper must lower through checked dispatch plans"),
                    .parse_tag_union,
                    .field_names_rename_fields,
                    .field_names_shortest_name,
                    .field_names_longest_name,
                    .field_names_iter,
                    .field_names_for_size,
                    .field_name,
                    => Common.invariant("encoding intrinsic wrapper must lower through a checked direct call"),
                };
            },
        };
    }

    fn applyCheckedTemplateInterfaceRelations(
        self: *BodyContext,
        template: checked.CheckedProcedureTemplate,
        root_node: NodeId,
    ) Allocator.Error!void {
        var active_local_scopes = collections.DenseMap(checked.DispatchScopeId, NodeId).init(self.allocator);
        defer active_local_scopes.deinit();
        const root = try self.allocator.create(InterfaceScopeFrame);
        root.* = .{
            .ctx = self,
            .owns_ctx = false,
            .template = template,
            .scope_id = null,
            .scope_root_node = root_node,
            .active_local_scopes = &active_local_scopes,
            .replay_state = &self.draft.interface_replay,
        };
        try self.runInterfaceRelations(root);
    }

    const InterfacePendingDependency = struct {
        target: checked.ResolvedValueId,
        source_fn_ty: checked.CheckedTypeId,
        request_fn_node: NodeId,
    };

    /// The relations of one checked dispatch scope, applied in order. A
    /// generalized local scope's relations apply as a child frame in its own
    /// context; each direct callee's interface expands as a child frame after
    /// every relation of this scope is applied.
    const InterfaceScopeFrame = struct {
        ctx: *BodyContext,
        /// Whether `ctx` is this frame's own heap-allocated local context.
        owns_ctx: bool,
        template: checked.CheckedProcedureTemplate,
        scope_id: ?checked.DispatchScopeId,
        scope_root_node: NodeId,
        active_local_scopes: *collections.DenseMap(checked.DispatchScopeId, NodeId),
        replay_state: *InterfaceReplayState,
        pending: std.ArrayList(InterfacePendingDependency) = .empty,
        next_relation: usize = 0,
        next_dependency: usize = 0,
        /// The local scope this frame made active, inactive again when it
        /// finishes.
        leave_scope: ?checked.DispatchScopeId = null,
    };

    const InterfaceRelationFrame = union(enum) {
        scope: *InterfaceScopeFrame,
        callee: *DirectCalleeExpansion,
    };

    /// Checked specialization relations reach callees' relations through
    /// call chains and nested local scopes, so each scope and each callee
    /// expansion is an explicit frame.
    fn runInterfaceRelations(self: *BodyContext, root: *InterfaceScopeFrame) Allocator.Error!void {
        try self.runInterfaceRelationFrames(.{ .scope = root });
    }

    fn runInterfaceRelationFrames(self: *BodyContext, root: InterfaceRelationFrame) Allocator.Error!void {
        var frames = std.ArrayList(InterfaceRelationFrame).empty;
        defer {
            var index = frames.items.len;
            while (index > 0) {
                index -= 1;
                switch (frames.items[index]) {
                    .scope => |frame| self.releaseInterfaceScopeFrame(frame),
                    .callee => |expansion| expansion.destroy(),
                }
            }
            frames.deinit(self.allocator);
        }
        frames.append(self.allocator, root) catch |err| {
            switch (root) {
                .scope => |frame| self.releaseInterfaceScopeFrame(frame),
                .callee => |expansion| expansion.destroy(),
            }
            return err;
        };
        while (frames.items.len != 0) {
            switch (frames.items[frames.items.len - 1]) {
                .scope => |frame| {
                    if (try self.stepInterfaceScope(frame)) |child| {
                        frames.append(self.allocator, child) catch |err| {
                            switch (child) {
                                .scope => |child_frame| self.releaseInterfaceScopeFrame(child_frame),
                                .callee => |expansion| expansion.destroy(),
                            }
                            return err;
                        };
                        continue;
                    }
                    _ = frames.pop();
                    self.releaseInterfaceScopeFrame(frame);
                },
                .callee => |expansion| {
                    if (try expansion.beginScope()) |child| {
                        try frames.append(self.allocator, .{ .scope = child });
                        continue;
                    }
                    _ = frames.pop();
                    try expansion.finish();
                },
            }
        }
    }

    fn releaseInterfaceScopeFrame(self: *BodyContext, frame: *InterfaceScopeFrame) void {
        frame.pending.deinit(self.allocator);
        if (frame.leave_scope) |scope| _ = frame.active_local_scopes.remove(scope);
        if (frame.owns_ctx) {
            frame.ctx.deinit();
            self.allocator.destroy(frame.ctx);
        }
        self.allocator.destroy(frame);
    }

    /// Apply the scope's next relations up to the next child frame, or null
    /// once every relation and callee interface is applied.
    fn stepInterfaceScope(_: *BodyContext, frame: *InterfaceScopeFrame) Allocator.Error!?InterfaceRelationFrame {
        const self = frame.ctx;
        const scope_id = frame.scope_id;
        const scope_root_node = frame.scope_root_node;
        const relations = self.view.templates.specializationRelations(&frame.template);
        while (frame.next_relation < relations.len) {
            const relation = relations[frame.next_relation];
            frame.next_relation += 1;
            if (!dispatchRefBelongsToScope(relation.scope, scope_id)) continue;
            switch (relation.data) {
                .type_equality => |equality| try relateRequestComponent(
                    self.graph,
                    try self.instNode(equality.left),
                    try self.instNode(equality.right),
                ),
                .procedure => |procedure| {
                    const fn_node = try self.instNode(procedure.fn_ty);
                    if (procedure.owns_scope) {
                        try relateFunctionRequestInterface(self.graph, fn_node, scope_root_node);
                    }
                    const function = try self.graph.functionNodes(fn_node);
                    try relateRequestComponent(
                        self.graph,
                        function.ret,
                        try self.instNode(procedure.body_ret_ty),
                    );
                },
                .call => |call| {
                    const source_fn_ty = if (call.direct_target) |target|
                        self.directCallInstantiationSourceFnType(target, call.callable_ty)
                    else
                        call.callable_ty;
                    const fn_node = try self.instNode(source_fn_ty);
                    try relateRequestComponent(self.graph, fn_node, try self.instNode(call.callee_ty));
                    const function = try self.graph.functionNodes(fn_node);
                    const arg_tys = self.view.templates.specializationRelationTypes(call.args);
                    if (function.args.len != arg_tys.len) {
                        Common.invariant("checked specialization call relation changed arity");
                    }
                    for (function.args, arg_tys) |arg_node, arg_ty| {
                        try relateRequestComponent(self.graph, arg_node, try self.instNode(arg_ty));
                    }
                    try relateRequestComponent(self.graph, function.ret, try self.instNode(call.ret_ty));
                    if (call.direct_target) |target| {
                        try frame.pending.append(self.allocator, .{
                            .target = target,
                            .source_fn_ty = source_fn_ty,
                            .request_fn_node = fn_node,
                        });
                    }
                },
                .local_proc_use => |ref_id| {
                    const record = self.view.resolved_refs.records[@backingInt(ref_id)];
                    const local = switch (record.ref) {
                        .local_proc => |local| local,
                        .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_const, .platform_required_proc, .promoted_top_level_proc => Common.invariant("checked local specialization relation targeted a non-local procedure"),
                    };
                    const local_scope = local.dispatch_scope orelse
                        Common.invariant("generalized local specialization relation had no checked scope");
                    const request_node = try self.instNode(record.checked_ty);
                    if (frame.active_local_scopes.get(local_scope)) |active_root| {
                        try relateFunctionRequestInterface(self.graph, active_root, request_node);
                        continue;
                    }
                    const local_ctx = try self.allocator.create(BodyContext);
                    local_ctx.* = BodyContext.initWithMethodScope(
                        self.allocator,
                        self.builder,
                        self.view,
                        self.method_scope,
                        self.owner_template,
                        self.graph,
                        self.draft,
                    ) catch |err| {
                        self.allocator.destroy(local_ctx);
                        return err;
                    };
                    const child = self.allocator.create(InterfaceScopeFrame) catch |err| {
                        local_ctx.deinit();
                        self.allocator.destroy(local_ctx);
                        return err;
                    };
                    child.* = .{
                        .ctx = local_ctx,
                        .owns_ctx = true,
                        .template = frame.template,
                        .scope_id = local_scope,
                        .scope_root_node = undefined,
                        .active_local_scopes = frame.active_local_scopes,
                        .replay_state = frame.replay_state,
                    };
                    errdefer self.releaseInterfaceScopeFrame(child);
                    local_ctx.owner_context_fn_key = self.owner_context_fn_key;
                    local_ctx.current_fn_key = self.current_fn_key;
                    const use_evidence = try self.evidenceForUseSiteForPurposeAtNode(
                        record.expr,
                        .specialization_interface,
                        request_node,
                    );
                    local_ctx.evidence = try enterEvidenceScope(
                        self.builder,
                        self.evidence,
                        local_scope,
                        local.expr,
                        use_evidence,
                    );
                    // The scope's relations mention checked variables quantified
                    // by enclosing frames as well as by the scope itself, and
                    // some are reachable only through constraints rather than
                    // through the scope's callable shape. Bind them the way
                    // lowering the local's use does before any relation
                    // instantiates them.
                    if (local.is_alias) {
                        try local_ctx.seedSubstitution(local_ctx.evidence.schema.?, use_evidence.subst);
                    } else {
                        local_ctx.resolves_enclosing_variables = true;
                    }
                    const local_root_node = try local_ctx.checkedTemplateInterfaceScopeRootNode(local_scope);
                    try relateFunctionRequestInterface(self.graph, local_root_node, request_node);
                    try frame.active_local_scopes.put(local_scope, local_root_node);
                    child.leave_scope = local_scope;
                    child.scope_root_node = local_root_node;

                    try local_ctx.instantiateTemplateDispatchRelations(frame.template, local_scope);
                    return .{ .scope = child };
                },
            }
        }

        while (frame.next_dependency < frame.pending.items.len) {
            const pending = frame.pending.items[frame.next_dependency];
            frame.next_dependency += 1;
            if (try self.beginDirectCalleeInterface(
                pending.target,
                pending.source_fn_ty,
                pending.request_fn_node,
                frame.replay_state,
            )) |expansion| return .{ .callee = expansion };
        }
        return null;
    }

    fn checkedTemplateInterfaceScopeRootNode(
        self: *BodyContext,
        scope_id: checked.DispatchScopeId,
    ) Allocator.Error!NodeId {
        const raw_scope = @backingInt(scope_id);
        if (raw_scope >= self.view.templates.dispatch_scopes.len) {
            Common.invariant("checked specialization relation named an unknown local scope");
        }
        const scheme_root = self.view.templates.dispatch_scopes[raw_scope].scheme_root;
        return try self.instNode(scheme_root);
    }

    const InterfaceSummaryCacheBinding = struct {
        cache: *InterfaceSummaryCache,
        types_are_durable: bool,
    };

    fn interfaceSummaryCache(self: *BodyContext) InterfaceSummaryCacheBinding {
        if (self.typeStore() == &self.builder.program.types) {
            return .{ .cache = &self.builder.interface_summaries, .types_are_durable = true };
        }
        const workspace = self.draft.spec_job_workspace orelse
            Common.compilerBug("interface summary graph has no owning workspace");
        std.debug.assert(self.typeStore() == &workspace.types);
        return .{ .cache = &workspace.interface_summaries, .types_are_durable = false };
    }

    fn findInterfaceSummary(self: *BodyContext, address: InterfaceReplayAddress, evidence: StoredConstFnEvidence, request: InterfaceConstraints.Identity) Allocator.Error!?InterfaceSummary {
        const local = self.interfaceSummaryCache().cache;
        if (local.buckets.get(address)) |candidates| for (candidates.items) |index| {
            const entry = local.entries.items[index];
            if (storedConstFnEvidenceEql(entry.evidence, evidence) and try entry.request.eql(request, self.typeStore(), self.nameStore())) return entry.summary;
        };
        if (self.builder.coordinator_interface_summaries) |published| {
            var candidates = published.get(address, self.builder.coordinator_interface_summary_end);
            while (candidates.next()) |entry| {
                if (!storedConstFnEvidenceEql(entry.evidence, evidence) or !std.mem.eql(u8, entry.request.bytes, request.bytes)) continue;
                if (try self.importInterfaceSummary(entry, request)) |summary| return summary;
            }
            return null;
        }
        const coordinator = &self.builder.interface_summaries;
        if (coordinator == local) return null;
        if (coordinator.buckets.get(address)) |candidates| for (candidates.items) |index| {
            const entry = coordinator.entries.items[index];
            if (!storedConstFnEvidenceEql(entry.evidence, evidence) or !std.mem.eql(u8, entry.request.bytes, request.bytes)) continue;
            if (try self.importInterfaceSummary(entry, request)) |summary| return summary;
        };
        return null;
    }

    fn importInterfaceSummary(self: *BodyContext, entry: InterfaceSummaryEntry, request: InterfaceConstraints.Identity) Allocator.Error!?InterfaceSummary {
        const relocation = InterfaceSummaryRelocation{
            .source_names = &self.builder.program.names,
            .destination_names = self.nameStoreMut(),
            .importing = self,
        };
        var scratch = std.heap.ArenaAllocator.init(self.allocator);
        defer scratch.deinit();
        const imported_request = try entry.request.copy(scratch.allocator(), relocation);
        if (!try imported_request.eql(request, self.typeStore(), self.nameStore())) return null;
        const summary = try entry.summary.copy(scratch.allocator(), relocation);
        return try self.insertInterfaceSummary(.{ .address = entry.address, .evidence = entry.evidence, .request = imported_request, .summary = summary });
    }

    fn insertInterfaceSummary(self: *BodyContext, entry: InterfaceSummaryEntry) Allocator.Error!InterfaceSummary {
        const binding = self.interfaceSummaryCache();
        if (binding.types_are_durable) {
            // Coordinator leaves already belong to permanent program storage.
            return try binding.cache.insert(self.typeStore(), self.nameStore(), entry);
        }
        // Retain only settled leaves; open cells remain explicit constraints.
        var sealer = GraphTypeFinals.initRetainedTypeView(self.graph);
        defer sealer.deinit();
        const relocation = InterfaceSummaryRelocation{
            .source_names = self.nameStore(),
            .destination_names = self.nameStoreMut(),
            .sealer = &sealer,
        };
        var scratch = std.heap.ArenaAllocator.init(self.allocator);
        defer scratch.deinit();
        return try binding.cache.insert(self.typeStore(), self.nameStore(), .{
            .address = entry.address,
            .evidence = entry.evidence,
            .request = try entry.request.copy(scratch.allocator(), relocation),
            .summary = try entry.summary.copy(scratch.allocator(), relocation),
        });
    }

    fn parametricRequestHoles(
        self: *BodyContext,
        allocator: Allocator,
        template_ref: names.ProcTemplate,
        view: ModuleView,
        template: *const checked.CheckedProcedureTemplate,
        subst: SpecSubstitution,
    ) Allocator.Error!ParametricHoles {
        if (subst.len == 0) return .{};
        const cached = try self.builder.parametric_scheme_vars.getOrPut(self.builder.allocator, template_ref);
        if (!cached.found_existing) {
            cached.value_ptr.* = parametricSchemeVarMask(self.builder.allocator, self.builder, view, template) catch |err| {
                _ = self.builder.parametric_scheme_vars.remove(template_ref);
                return err;
            };
        }
        const mask = cached.value_ptr.*;
        if (mask.len != subst.len) Common.invariant("parametric request substitution differed from its scheme's quantified variables");
        var count: usize = 0;
        for (mask, subst) |is_parametric, slot| {
            if (is_parametric and slot == .node) count += 1;
        }
        if (count == 0) return .{};
        const nodes = try allocator.alloc(NodeId, count);
        const root_indices = try allocator.alloc(u32, count);
        var next: usize = 0;
        // Request roots are the function request followed by each node slot.
        var root_index: u32 = 1;
        for (mask, subst) |is_parametric, slot| {
            switch (slot) {
                .node => |node| {
                    if (is_parametric) {
                        nodes[next] = node;
                        root_indices[next] = root_index;
                        next += 1;
                    }
                    root_index += 1;
                },
                .checked_error => {},
            }
        }
        return .{ .nodes = nodes, .root_indices = root_indices };
    }

    /// An unfinished expansion is joined only by the instantiation it expands:
    /// each hole slot names the class the expansion's request supplied or
    /// the expansion's own hole cell. Inside mutually recursive expansions a
    /// slot can instead name another unfinished expansion's hole cell, which
    /// stands for the class that expansion's request supplied; the slot is
    /// followed through those cells to what it stands for.
    fn joinsUnfinishedExpansion(
        self: *BodyContext,
        replay_state: *const InterfaceReplayState,
        entry: InterfaceReplayEntry,
        holes: []const NodeId,
        hole_classes: []const ?NodeId,
    ) bool {
        if (entry.hole_classes.len != hole_classes.len) return false;
        for (entry.hole_classes, entry.hole_cells, holes, hole_classes) |expanded_class, expanded_cell, hole, hole_class| {
            const expanded = expanded_class orelse {
                if (hole_class != null) return false;
                continue;
            };
            var current = hole;
            var steps: usize = 0;
            while (!self.graph.sameClass(current, expanded) and !self.graph.sameClass(current, expanded_cell)) {
                if (steps == replay_state.stack.items.len) return false;
                current = self.unfinishedHoleCellClass(replay_state, current) orelse return false;
                steps += 1;
            }
        }
        return true;
    }

    /// The class an unfinished expansion's hole cell stands for, when `node`
    /// is such a cell.
    fn unfinishedHoleCellClass(self: *BodyContext, replay_state: *const InterfaceReplayState, node: NodeId) ?NodeId {
        for (replay_state.stack.items) |index| {
            const unfinished = replay_state.entries.items[index];
            for (unfinished.hole_cells, unfinished.hole_classes) |cell, class| {
                const stands_for = class orelse continue;
                if (self.graph.sameClass(node, cell)) return stands_for;
            }
        }
        return null;
    }

    fn relateInterfaceRoots(self: *BodyContext, produced: []const NodeId, requested: []const NodeId) Allocator.Error!void {
        std.debug.assert(produced.len == requested.len);
        try relateFunctionRequestInterface(self.graph, produced[0], requested[0]);
        for (produced[1..], requested[1..]) |left, right| try relateRequestComponent(self.graph, left, right);
    }

    /// Relate a direct callee's interface to its request: from a replayed or
    /// cached summary, or by starting an expansion of the callee's checked
    /// relations, returned for the caller to run as a frame.
    fn beginDirectCalleeInterface(
        self: *BodyContext,
        target: checked.ResolvedValueId,
        source_fn_ty: checked.CheckedTypeId,
        request_fn_node: NodeId,
        replay_state: *InterfaceReplayState,
    ) Allocator.Error!?*DirectCalleeExpansion {
        self.builder.count("interface_relation_requests");
        const record = self.view.resolved_refs.records[@backingInt(target)];
        const procedure, const root_evidence = switch (record.ref) {
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .promoted_top_level_proc,
            => |procedure| .{ procedure, @as(?checked.CheckedEvidenceSpan, null) },
            .platform_required_proc => |required| .{ required.procedure, required.root_evidence },
            .local_proc => return null,
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .selected_hoisted_const,
            .top_level_const,
            .imported_const,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            => Common.invariant("checked specialization call relation targeted a non-procedure"),
        };
        // A call through an exact procedure alias forwards when it is drafted,
        // and that forwarded specialization applies its own relations.
        if (self.builder.forwardingCallableEvalForProcedureUse(procedure) != null) return null;
        const template_ref = self.builder.templateRefForProcedureUse(procedure);
        const callee_view = self.builder.moduleForDigest(names.procTemplateModuleDigest(template_ref));
        const template = callee_view.templates.get(template_ref.template);
        const partial_edge = try self.evidenceForProcedureUseAtNode(procedure, record.expr, root_evidence, request_fn_node, .interface_summary_input);
        var edge = if (partial_edge.vector.len == template.evidence_params.len)
            partial_edge
        else
            try self.builder.completeRootTemplateEvidenceForPurpose(
                callee_view,
                template_ref,
                template,
                partial_edge,
                .interface_summary_input,
            );
        edge.vector = try self.resolveCallableEvidenceAtNode(
            callee_view,
            template,
            edge.vector,
            request_fn_node,
            .interface_summary_input,
        );
        return try self.applyTemplateInterfaceRelations(
            template_ref,
            callee_view,
            template,
            DraftTemplateFamilyAddress.init(template_ref, self.method_scope.key, self.view.types.rootKey(source_fn_ty)),
            try self.builder.constFnEvidence(rootEvidence(template_ref, edge.vector)),
            edge,
            request_fn_node,
            replay_state,
        );
    }

    /// Relate `request_fn_node` and the substitution's cells to everything a
    /// specialization of `template` at `edge` implies about its interface:
    /// its checked root, its evidence contracts, and, for an open interface,
    /// its dispatch and callee relations. A completed expansion is summarized
    /// by its request's identity, so an equal request replays the summary
    /// instead of expanding again. An expansion is returned for the caller to
    /// run as a frame.
    fn applyTemplateInterfaceRelations(
        self: *BodyContext,
        template_ref: names.ProcTemplate,
        callee_view: ModuleView,
        template: checked.CheckedProcedureTemplate,
        family: DraftTemplateFamilyAddress,
        stored_evidence: StoredConstFnEvidence,
        request_edge: EdgeEvidence,
        request_fn_node: NodeId,
        replay_state: *InterfaceReplayState,
    ) Allocator.Error!?*DirectCalleeExpansion {
        var edge = request_edge;
        const evidence_digest = stored_evidence.digest;
        const expansion = try self.allocator.create(DirectCalleeExpansion);
        expansion.* = .{
            .caller = self,
            .replay_state = replay_state,
            .input_arena = self.graph.acquireArena(),
        };
        var expanding = false;
        defer if (!expanding) expansion.destroy();
        const request_roots = &expansion.request_roots;
        try request_roots.append(self.allocator, request_fn_node);
        for (edge.subst) |slot| if (slot == .node) {
            try request_roots.append(self.allocator, slot.node);
        };
        const input_arena = &expansion.input_arena;
        const holes = try self.parametricRequestHoles(input_arena.allocator(), template_ref, callee_view, &template, edge.subst);
        const hole_classes = try input_arena.allocator().alloc(?NodeId, holes.nodes.len);
        const input = try InterfaceConstraints.captureWithHoles(self.graph, input_arena.allocator(), request_roots.items, holes.nodes, hole_classes);
        for (hole_classes) |hole_class| if (hole_class != null) {
            self.builder.count("interface_parametric_requests");
            break;
        };
        const shape = try input.identityInto(self.graph, input_arena.allocator());
        const request_bytes = try input_arena.allocator().alloc(u8, shape.bytes.len + edge.subst.len);
        @memcpy(request_bytes[0..shape.bytes.len], shape.bytes);
        for (edge.subst, request_bytes[shape.bytes.len..]) |slot, *byte| byte.* = if (slot == .checked_error) 1 else 0;
        const request: InterfaceConstraints.Identity = .{ .bytes = request_bytes, .leaves = shape.leaves };
        const address = InterfaceReplayAddress{
            .family = family,
            .evidence_digest = evidence_digest.bytes,
            .input_digest = interfaceRequestBucket(request.bytes),
        };

        var cached: ?InterfaceSummary = null;
        if (replay_state.buckets.get(address)) |candidates| for (candidates.items) |raw_entry| {
            const entry = replay_state.entries.items[raw_entry];
            if (!storedConstFnEvidenceEql(entry.evidence, stored_evidence) or !try entry.request.eql(request, self.typeStore(), self.nameStore())) continue;
            // An unfinished expansion is joined only by the exact request it
            // expands; parametric holes generalize completed summaries.
            if (entry.status != .ready and !self.joinsUnfinishedExpansion(replay_state, entry, holes.nodes, hole_classes)) continue;
            self.builder.count("interface_replay_hits");
            switch (entry.status) {
                .expanding, .expanded => {
                    if (replay_state.current) |current| {
                        replay_state.entries.items[current].lowlink = @min(replay_state.entries.items[current].lowlink, raw_entry);
                    }
                    try self.relateInterfaceRoots(entry.roots, request_roots.items);
                    return null;
                },
                .ready => {
                    if (!replay_state.use_finished_summaries) continue;
                    cached = entry.summary orelse continue;
                    break;
                },
            }
        };
        if (cached == null and replay_state.use_finished_summaries) cached = try self.findInterfaceSummary(address, stored_evidence, request);
        var verify_summary: ?InterfaceSummary = null;
        const saved_use_summaries = replay_state.use_finished_summaries;
        expansion.saved_use_summaries = saved_use_summaries;
        expansion.restores_use_summaries = true;
        if (cached) |summary| {
            self.builder.count("interface_summary_hits");
            if (std.debug.runtime_safety and self.builder.diagnostics != null and self.builder.interface_summary_checks < 16) {
                self.builder.interface_summary_checks += 1;
                self.builder.count("interface_summary_verifications");
                verify_summary = summary;
                replay_state.use_finished_summaries = false;
            } else switch (summary) {
                .unchanged => {
                    self.builder.count("interface_summary_unchanged_hits");
                    return null;
                },
                .constraints => |constraints| {
                    try self.relateInterfaceRoots(try constraints.instantiate(self.graph), request_roots.items);
                    return null;
                },
            }
        }
        self.builder.count("interface_summary_expansions");
        // Expand on independent input cells. No unrelated caller refinement can
        // become a cached callee constraint while its dependencies are replayed.
        const roots = try input.instantiate(self.graph);
        const detached_subst = try self.graph.arena().dupe(SubstSlot, edge.subst);
        var slot_index: usize = 1;
        for (detached_subst) |*slot| if (slot.* == .node) {
            slot.* = .{ .node = roots[slot_index] };
            slot_index += 1;
        };
        edge.subst = detached_subst;
        const replay_index = replay_state.entries.items.len;
        try replay_state.entries.append(self.allocator, .{
            .address = address,
            .evidence = stored_evidence,
            .request = try request.copy(self.graph.arena(), InterfaceSummaryCopy{}),
            .input_len = shape.bytes.len,
            .hole_classes = try self.graph.arena().dupe(?NodeId, hole_classes),
            .hole_cells = hole_cells: {
                const cells = try self.graph.arena().alloc(NodeId, holes.root_indices.len);
                for (holes.root_indices, cells) |root_index, *cell| cell.* = roots[root_index];
                break :hole_cells cells;
            },
            .roots = roots,
            .lowlink = replay_index,
            .verify_summary = verify_summary,
            .verify_input = if (verify_summary != null) try input.copy(self.graph.arena(), InterfaceSummaryCopy{}) else null,
        });
        try replay_state.stack.append(self.allocator, replay_index);
        const parent = replay_state.current;
        replay_state.current = replay_index;
        expansion.parent = parent;
        expansion.restores_current = true;
        const bucket = try replay_state.buckets.getOrPut(address);
        if (!bucket.found_existing) bucket.value_ptr.* = .empty;
        try bucket.value_ptr.append(self.allocator, @intCast(replay_index));

        expansion.callee_ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self.builder,
            callee_view,
            self.method_scope,
            template_ref,
            self.graph,
            self.draft,
        );
        expansion.callee_ctx_live = true;
        const callee_ctx = &expansion.callee_ctx;
        callee_ctx.owner_context_fn_key = self.owner_context_fn_key;
        callee_ctx.current_fn_key = self.current_fn_key;
        callee_ctx.evidence = rootEvidenceWithSubstitution(template_ref, templateSchemaIn(callee_view, &template), edge);
        try callee_ctx.seedSubstitution(callee_ctx.evidence.schema.?, edge.subst);
        const root_node = try callee_ctx.instNode(template.checked_fn_root);
        if (template.target == .hosted) {
            // The replayed summary shapes the request; the specialization this
            // request later reaches records the widening for completion.
            _ = try relateHostedFunctionRequestInterface(
                self.graph,
                try self.builder.hostedTryAdapterCapability(callee_view, template.hosted_try_adapter),
                root_node,
                roots[0],
            );
        } else if (!try relateClosedResultRowRequestInterface(
            self.graph,
            callee_view,
            template.checked_fn_root,
            root_node,
            roots[0],
            // A `.local_proc` target returned above, so this request is always
            // served by a procedure template specialization.
            .adapter_reachable,
        )) {
            try relateConstructionFunctionRequestInterface(self.graph, root_node, roots[0]);
        }
        try callee_ctx.relateMaterializedEvidenceConstraints(callee_ctx, callee_ctx.evidence.schema.?, edge.vector);
        if (templateInterfaceIsClosed(callee_view, &template)) {
            // A closed interface is complete once the request is related to
            // its checked root; its relation table never enters this graph.
            self.builder.count("interface_closed_expansions");
        } else {
            try callee_ctx.instantiateTemplateDispatchRelations(template, null);
            expansion.open_scope = .{ .template = template, .root_node = root_node };
        }
        expansion.replay_index = replay_index;
        expansion.hole_classes = hole_classes;
        expansion.roots = roots;
        expanding = true;
        return expansion;
    }

    /// A callee interface expansion: its replay entry is on the replay stack
    /// and `replay_state.current` names it until it finishes.
    const DirectCalleeExpansion = struct {
        caller: *BodyContext,
        replay_state: *InterfaceReplayState,
        input_arena: std.heap.ArenaAllocator,
        request_roots: std.ArrayList(NodeId) = .empty,
        callee_ctx: BodyContext = undefined,
        callee_ctx_live: bool = false,
        /// The callee's open checked relations, applied as a child scope
        /// frame before the expansion finishes.
        open_scope: ?struct { template: checked.CheckedProcedureTemplate, root_node: NodeId } = null,
        active_local_scopes: ?collections.DenseMap(checked.DispatchScopeId, NodeId) = null,
        saved_use_summaries: bool = undefined,
        restores_use_summaries: bool = false,
        parent: ?usize = null,
        restores_current: bool = false,
        replay_index: usize = undefined,
        hole_classes: []const ?NodeId = &.{},
        roots: []const NodeId = &.{},

        /// The child frame applying the callee's open relations, once.
        fn beginScope(expansion: *DirectCalleeExpansion) Allocator.Error!?*InterfaceScopeFrame {
            const scope = expansion.open_scope orelse return null;
            expansion.open_scope = null;
            const allocator = expansion.caller.allocator;
            expansion.active_local_scopes = collections.DenseMap(checked.DispatchScopeId, NodeId).init(allocator);
            const frame = try allocator.create(InterfaceScopeFrame);
            frame.* = .{
                .ctx = &expansion.callee_ctx,
                .owns_ctx = false,
                .template = scope.template,
                .scope_id = null,
                .scope_root_node = scope.root_node,
                .active_local_scopes = &expansion.active_local_scopes.?,
                .replay_state = expansion.replay_state,
            };
            return frame;
        }

        fn destroy(expansion: *DirectCalleeExpansion) void {
            const allocator = expansion.caller.allocator;
            if (expansion.active_local_scopes) |*scopes| scopes.deinit();
            if (expansion.callee_ctx_live) expansion.callee_ctx.deinit();
            if (expansion.restores_current) expansion.replay_state.current = expansion.parent;
            if (expansion.restores_use_summaries) expansion.replay_state.use_finished_summaries = expansion.saved_use_summaries;
            expansion.caller.graph.releaseArena(expansion.input_arena);
            expansion.request_roots.deinit(allocator);
            allocator.destroy(expansion);
        }

        /// Relate the expansion back to its request and, when it closes a
        /// recursive component, store each member's interface summary.
        fn finish(expansion: *DirectCalleeExpansion) Allocator.Error!void {
            defer expansion.destroy();
            const self = expansion.caller;
            const replay_state = expansion.replay_state;
            const replay_index = expansion.replay_index;
            const hole_classes = expansion.hole_classes;
            const roots = expansion.roots;
            const request_roots = &expansion.request_roots;
            const parent = expansion.parent;
            const saved_use_summaries = expansion.saved_use_summaries;
            // A component of one request is complete before it relates back to
            // that request. A parametric request's summary is therefore taken
            // from its expansion alone, so relating back cannot fill its holes.
            const single_request_component = replay_state.entries.items[replay_index].lowlink == replay_index and
                replay_state.stack.items[replay_state.stack.items.len - 1] == replay_index;
            const parametric_request = for (hole_classes) |hole_class| {
                if (hole_class != null) break true;
            } else false;
            var component_scratch = std.heap.ArenaAllocator.init(self.allocator);
            defer component_scratch.deinit();
            const single_request_constraints: ?InterfaceConstraints = if (single_request_component and parametric_request)
                try InterfaceConstraints.capture(self.graph, component_scratch.allocator(), roots)
            else
                null;
            try self.relateInterfaceRoots(roots, request_roots.items);
            replay_state.entries.items[replay_index].status = .expanded;
            const lowlink = replay_state.entries.items[replay_index].lowlink;
            if (parent) |parent_index| {
                replay_state.entries.items[parent_index].lowlink = @min(replay_state.entries.items[parent_index].lowlink, lowlink);
            }
            if (lowlink == replay_index) {
                // All members of this recursive component have contributed their
                // constraints. Store each interface only after this fixed point.
                while (replay_state.stack.pop()) |index| {
                    const entry = &replay_state.entries.items[index];
                    var scratch = std.heap.ArenaAllocator.init(self.allocator);
                    defer scratch.deinit();
                    // Members of a larger component are captured after relating
                    // back to each other's requests, so their interfaces hold the
                    // settled types their holes stood for; only exact requests
                    // may reuse them.
                    const parametric = for (entry.hole_classes) |hole_class| {
                        if (hole_class != null) break true;
                    } else false;
                    if (parametric and !single_request_component) {
                        entry.status = .ready;
                        if (index == replay_index) break;
                        continue;
                    }
                    const constraints = single_request_constraints orelse try InterfaceConstraints.capture(self.graph, scratch.allocator(), entry.roots);
                    const entry_input: InterfaceConstraints.Identity = .{ .bytes = entry.request.bytes[0..entry.input_len], .leaves = entry.request.leaves };
                    const summary: InterfaceSummary = if (try (try constraints.identityInto(self.graph, scratch.allocator())).eql(entry_input, self.typeStore(), self.nameStore()))
                        .unchanged
                    else
                        .{ .constraints = constraints };
                    entry.status = .ready;
                    if (entry.verify_summary) |expected| {
                        if (!try expected.equivalent(summary, entry.verify_input.?, self.graph, scratch.allocator())) {
                            Common.compilerBug("cached interface constraints disagreed with fresh checked relation expansion");
                        }
                    }
                    // Completed replay entries borrow the durable cache's immutable
                    // storage; only uncached verification expansions remain graph-local.
                    entry.summary = if (saved_use_summaries) try self.insertInterfaceSummary(.{
                        .address = entry.address,
                        .evidence = entry.evidence,
                        .request = entry.request,
                        .summary = summary,
                    }) else try summary.copy(self.graph.arena(), InterfaceSummaryCopy{});
                    if (index == replay_index) break;
                }
            }
        }
    };

    fn lowerEntryWrapperAtCell(
        self: *BodyContext,
        wrapper_id: anytype,
        ret_cell: DraftTypeCell,
    ) Allocator.Error!LoweredTemplateBody {
        const wrapper = self.view.entry_wrappers.get(wrapper_id);
        const root = self.view.compile_time_roots.root(wrapper.root);
        const saved_entry_root = self.current_entry_root;
        defer self.current_entry_root = saved_entry_root;
        self.current_entry_root = .{ .module = self.view.key, .root = wrapper.root };
        const saved_source_region_override = self.source_region_override;
        defer self.source_region_override = saved_source_region_override;
        self.source_region_override = switch (root.kind) {
            .constant,
            .hoisted_constant,
            .hoisted_validation,
            .callable_binding,
            .expect,
            .numeral_conversion,
            .quote_conversion,
            .repl_expr,
            => saved_source_region_override,
        };
        const body = if (root.literalConversionKind() != null)
            try self.lowerLiteralConversionRootBody(wrapper.body_expr, ret_cell)
        else switch (root.kind) {
            .constant,
            .hoisted_constant,
            .hoisted_validation,
            .expect,
            .repl_expr,
            => try self.lowerComptimeRootExprAtCell(wrapper.body_expr, ret_cell),
            .callable_binding => blk: {
                // The canonical evaluator owns its recursive closure binding.
                // Reads inside its construction must refer to this binding,
                // before the completed value can be published to a root slot.
                const local = try self.reserveCallableEvalBinding(self.view, wrapper.root, try ret_cell.toGraphNode(self.graph));
                const lowered = try self.lowerComptimeRootExprAtCell(wrapper.body_expr, ret_cell);
                break :blk try self.finishCallableEvalBinding(self.view, wrapper.root, ret_cell, local, lowered);
            },
            .numeral_conversion,
            .quote_conversion,
            => Common.invariant("literal-conversion root bypassed literal-conversion lowering"),
        };
        const declared_ret_node = try ret_cell.toGraphNode(self.graph);
        const body_ret_cell = self.exprTypeCell(body);
        const body_ret_node = try body_ret_cell.toGraphNode(self.graph);
        const produced_ret_cell = if (self.graph.sameClass(declared_ret_node, body_ret_node))
            ret_cell
        else if (try self.resultCompletesRequest(declared_ret_node, body_ret_node) or
            try self.graph.containsGeneratedPrivate(body_ret_node) or
            try self.exprCarriesFunctionDefinitionEvidence(body))
            body_ret_cell
        else blk: {
            try relateRequestComponent(self.graph, declared_ret_node, body_ret_node);
            break :blk ret_cell;
        };
        self.draft.exprs.items[@backingInt(body)].ty = produced_ret_cell;
        return .{ .args = .empty(), .body = body, .ret = produced_ret_cell };
    }

    fn instantiateTemplateDispatchRelations(
        self: *BodyContext,
        template: checked.CheckedProcedureTemplate,
        scope_id: ?checked.DispatchScopeId,
    ) Allocator.Error!void {
        const span = template.dispatch_relations;
        const refs = self.view.static_dispatch_plans.dispatch_relation_refs[span.start .. span.start + span.len];
        const scopes = self.view.templates.dispatch_ref_scopes[span.start .. span.start + span.len];
        const kinds = self.view.templates.dispatch_relation_kinds[span.start .. span.start + span.len];
        if (refs.len != scopes.len or refs.len != kinds.len) Common.invariant("checked template dispatch refs and relation metadata differed in length");

        // Resolve every plan in this scope before instantiating any of its type
        // relations. A rejected inner dispatch makes every enclosing expression
        // that evaluates it divergent, so relation replay must consume the
        // complete specialization-specific divergence column, not only the
        // entries discovered earlier in source order.
        var added_crash = false;
        for (refs, scopes) |plan_id, dispatch_scope| {
            if (!dispatchRefBelongsToScope(dispatch_scope, scope_id)) continue;
            const plan = self.view.static_dispatch_plans.plans[@backingInt(plan_id)];
            switch (self.dispatchRuntimePlan(plan)) {
                .callable => {},
                .crash => {
                    added_crash = (try self.recordSpecializationDispatchCrash(plan.expr)) or added_crash;
                },
            }
        }
        if (added_crash) try self.refreshSpecializationDispatchDivergence();

        for (refs, scopes, kinds) |plan_id, dispatch_scope, relation_kind| {
            if (!dispatchRefBelongsToScope(dispatch_scope, scope_id)) continue;
            const plan = self.view.static_dispatch_plans.plans[@backingInt(plan_id)];
            if (self.checkedExprDivergesInLoweredRuntime(plan.expr)) continue;
            if (relation_kind == .conversion) continue;
            const callable_plan = switch (self.dispatchRuntimePlan(plan)) {
                .callable => |value| value,
                .crash => Common.invariant("non-divergent dispatch relation resolved to a crash"),
            };
            const expr = self.view.bodies.expr(plan.expr);
            // An interpolation's conversion returns the `Try` of the
            // assembler whose result is the interpolation's value.
            const ret_ty = if (expr.data == .interpolation) self.literalConversionTryType(plan_id) else expr.ty;
            self.builder.count("template_dispatch_relation_replays");
            _ = try self.callableDispatchResultTypeNodeInPhase(
                ret_ty,
                callable_plan,
                null,
                .template_relation_replay,
            );
        }
    }

    fn dispatchRefBelongsToScope(
        dispatch_scope: checked.DispatchScope,
        scope_id: ?checked.DispatchScopeId,
    ) bool {
        return if (scope_id) |wanted_scope|
            switch (dispatch_scope) {
                .root => false,
                .generalized => |id| id == wanted_scope,
            }
        else switch (dispatch_scope) {
            .root => true,
            .generalized => false,
        };
    }

    fn recordSpecializationDispatchCrash(
        self: *BodyContext,
        expr: checked.CheckedExprId,
    ) Allocator.Error!bool {
        if (!self.owns_specialization_dispatch_crashes) {
            const previous = self.specialization_dispatch_crashes orelse &.{};
            const crashes = try self.allocator.alloc(bool, self.view.bodies.exprCount());
            @memset(crashes, false);
            if (previous.len != 0) {
                if (previous.len != crashes.len) {
                    Common.invariant("specialization dispatch crash array length differed from checked body expression count");
                }
                @memcpy(crashes, previous);
            }
            self.specialization_dispatch_crashes = crashes;
            self.owns_specialization_dispatch_crashes = true;
        }
        const crashes = self.specialization_dispatch_crashes.?;
        const raw = @backingInt(expr);
        if (raw >= crashes.len) Common.invariant("specialization dispatch crash referenced a missing checked expression");
        if (crashes[raw]) return false;
        crashes[raw] = true;
        return true;
    }

    fn refreshSpecializationDispatchDivergence(self: *BodyContext) Allocator.Error!void {
        if (self.specialization_dispatch_divergence) |*divergence| divergence.deinit(self.allocator);
        self.specialization_dispatch_divergence = try checked.dispatchDivergenceForEvidence(
            self.allocator,
            self.view.bodies,
            self.view.static_dispatch_plans,
            self.specialization_dispatch_crashes.?,
        );
        self.borrowed_specialization_dispatch_divergence = null;
    }

    fn specializationDispatchDivergence(self: *const BodyContext) ?*const checked.DispatchDivergence {
        if (self.specialization_dispatch_divergence) |*divergence| return divergence;
        return self.borrowed_specialization_dispatch_divergence;
    }

    /// Replay the dispatch relations of every scope in the chain, from the
    /// outermost scope in.
    fn replayStoredEvidenceRelations(self: *BodyContext, chain: EvidenceChain) Allocator.Error!void {
        if (!names.procedureTemplateRefEql(chain.scope.owner, self.owner_template)) {
            Common.invariant("stored function evidence belonged to a different checked template");
        }
        // A default-root nested function instantiates no owner-template
        // dispatch relations (design.md "Defaulted Fields"): the default has
        // no enclosing scheme, so its relations flow entirely through the
        // default evidence spans. The chain owner above is the template that
        // RECORDED the materialization, while `self.view` is the declaring
        // module—its template table does not contain that owner.
        if (self.in_default_expr) return;
        var scopes = std.ArrayList(EvidenceScope).empty;
        defer scopes.deinit(self.allocator);
        var frame = chain;
        while (true) {
            if (!names.procedureTemplateRefEql(frame.scope.owner, self.owner_template)) {
                Common.invariant("stored function evidence belonged to a different checked template");
            }
            try scopes.append(self.allocator, frame.scope);
            frame = (frame.parent orelse break).*;
        }
        const template = self.view.templates.get(self.owner_template.template);
        var index = scopes.items.len;
        while (index > 0) {
            index -= 1;
            switch (scopes.items[index].lexical) {
                .root => try self.instantiateTemplateDispatchRelations(template, null),
                .generalized => |scope| try self.instantiateTemplateDispatchRelations(template, scope),
            }
        }
    }

    fn lowerStrInspectIntrinsicAtNode(
        self: *BodyContext,
        fn_nodes: FunctionNodes,
        ret_cell: DraftTypeCell,
    ) Allocator.Error!LoweredTemplateBody {
        if (fn_nodes.args.len != 1) Common.invariant("Str.inspect intrinsic requires exactly one argument");

        const arg_node = fn_nodes.args[0];
        const arg_cell = DraftTypeCell.fromGraphNode(arg_node);
        const arg_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), arg_cell, null);
        const local_expr = try self.addExprWithTypeCell(arg_cell, .{ .local = arg_local });
        const ret_ty = try self.activeTypeFromCell(ret_cell);
        const body = switch ((try self.graph.content(arg_node))) {
            // Rendering a function never inspects its nested signature. Keep
            // that signature graph-native so unresolved child cells survive
            // until the owning draft is sealed once.
            .func, .erased => try self.stringExpr("<function>", ret_ty),
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .zst => if (try self.graph.typeIsResolved(arg_node))
                try self.inspectCall(local_expr, try self.activeTypeFromNode(arg_node), ret_ty)
            else
                try self.deferInspectAtNode(local_expr, arg_node, ret_ty),
        };
        return .{
            .args = try self.draft.addTypedLocalSpan(&.{.{ .local = arg_local, .ty = arg_cell }}),
            .body = body,
            .ret = ret_cell,
        };
    }

    fn deferInspectAtNode(
        self: *BodyContext,
        value: DraftExprId,
        value_node: NodeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const expr = try self.addExprWithTypeCell(.{ .sealed = ret_ty }, .pending_deferred);
        const lexical = try self.captureCodecLexicalContext();
        errdefer {
            self.allocator.free(lexical.binders);
            self.allocator.free(lexical.local_procs);
        }
        try self.draft.deferred_inspects.append(self.allocator, .{
            .view = self.view,
            .method_scope = self.method_scope,
            .owner_template = self.owner_template,
            .owner = self.draft.current_owner,
            .expr = expr,
            .value = value,
            .value_node = value_node,
            .ret_ty = ret_ty,
            .evidence = self.evidence,
            .current_fn_key = self.current_fn_key,
            .lexical = lexical,
            .impossibility_proof = try self.currentRuntimeImpossibilityProof(null),
        });
        return expr;
    }

    const RequestCompletion = enum {
        unchanged,
        completed,
        mismatch,
    };

    const RequestCompletionPair = struct {
        request: NodeId,
        produced: NodeId,
    };

    /// Completion revisits many siblings while keeping only the current path.
    /// Tombstone deletion makes that workload saturate a probing hash table;
    /// dense-map deletion repairs its index instead, without memoizing the
    /// provisional answers used to cut recursive cycles.
    const RequestCompletionPath = struct {
        const Map = std.array_hash_map.Auto(RequestCompletionPair, void);

        map: Map = .empty,
        allocator: Allocator,

        fn init(allocator: Allocator) RequestCompletionPath {
            return .{ .allocator = allocator };
        }

        fn deinit(self: *RequestCompletionPath) void {
            self.map.deinit(self.allocator);
        }

        fn enter(self: *RequestCompletionPath, pair: RequestCompletionPair) Allocator.Error!bool {
            return !(try self.map.getOrPut(self.allocator, pair)).found_existing;
        }

        fn leave(self: *RequestCompletionPath, pair: RequestCompletionPair) void {
            const removed = self.map.swapRemove(pair);
            std.debug.assert(removed);
        }
    };

    const ProducedValuePair = struct {
        request: NodeId,
        produced: NodeId,
    };

    /// Request-completion relations of the pairs one produced-value walk
    /// enters. A pair's relation is a fact about its whole subtree, so a walk
    /// that asks it of every container on a path would otherwise re-walk each
    /// subtree once per enclosing container. Relations are recorded while the
    /// first query walks the subtree and hold while the graph's
    /// `structure_epoch` is unchanged; a relation decided by assuming a pair
    /// still on the walked path is not recorded, since it holds only under
    /// that assumption.
    const CompletionMemo = struct {
        epoch: u32,
        relations: std.AutoHashMap(RequestCompletionPair, RequestCompletion),

        fn init(allocator: Allocator) CompletionMemo {
            return .{ .epoch = 0, .relations = std.AutoHashMap(RequestCompletionPair, RequestCompletion).init(allocator) };
        }

        fn deinit(self: *CompletionMemo) void {
            self.relations.deinit();
        }
    };

    const ProducedValueRowKind = enum {
        record,
        tag_union,
    };

    fn resultCompletesRequest(
        self: *BodyContext,
        request_ret_node: NodeId,
        produced_ret_node: NodeId,
    ) Allocator.Error!bool {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        var visiting = RequestCompletionPath.init(self.allocator);
        defer visiting.deinit();
        return (try self.requestCompletionRelation(request_ret_node, produced_ret_node, &visiting, null)) == .completed;
    }

    /// `resultCompletesRequest` for a pair a produced-value walk enters,
    /// answered from the walk's memo while the graph is unchanged.
    fn producedPairCompletesRequest(
        self: *BodyContext,
        checked_root: NodeId,
        produced_root: NodeId,
        memo: *CompletionMemo,
    ) Allocator.Error!bool {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        const pair = RequestCompletionPair{ .request = self.graph.rootNode(checked_root), .produced = self.graph.rootNode(produced_root) };
        if (memo.epoch != self.graph.structure_epoch) {
            memo.relations.clearRetainingCapacity();
            memo.epoch = self.graph.structure_epoch;
        } else if (memo.relations.get(pair)) |relation| {
            return relation == .completed;
        }
        var visiting = RequestCompletionPath.init(self.allocator);
        defer visiting.deinit();
        return (try self.requestCompletionRelation(checked_root, produced_root, &visiting, memo)) == .completed;
    }

    fn relateCheckedNodeToProducedValue(
        self: *BodyContext,
        checked_node: NodeId,
        produced_node: NodeId,
    ) Allocator.Error!NodeId {
        var visiting = std.AutoHashMap(ProducedValuePair, void).init(self.allocator);
        defer visiting.deinit();
        var completions = CompletionMemo.init(self.allocator);
        defer completions.deinit();
        return try self.relateCheckedNodeToProducedValueInner(checked_node, produced_node, &visiting, &completions);
    }

    /// One step of relating a matching container's children: a child pair
    /// to relate, or a label check that must hold before the next child.
    const ProducedValueOp = union(enum) {
        child: struct { checked: NodeId, produced: NodeId },
        field_name: struct { checked: names.RecordFieldNameId, produced: names.RecordFieldNameId },
        tag: struct { checked_name: names.TagNameId, produced_name: names.TagNameId, checked_len: usize, produced_len: usize },
    };

    /// A matching container whose children are still relating.
    const ProducedValueFrame = struct {
        checked_node: NodeId,
        produced_node: NodeId,
        /// The produced container as it was matched, before its children
        /// related.
        produced_content: InstNode,
        pair: ProducedValuePair,
        ops_start: usize,
        next: usize,
        results_start: usize,
    };

    /// Relate a checked node to the value actually produced, returning the
    /// witness node the value is typed at. Matching containers relate their
    /// children as explicit frames, so type depth never becomes native call
    /// depth; a pair already on the current path relates to the produced
    /// node by assumption.
    fn relateCheckedNodeToProducedValueInner(
        self: *BodyContext,
        root_checked: NodeId,
        root_produced: NodeId,
        visiting: *std.AutoHashMap(ProducedValuePair, void),
        completions: *CompletionMemo,
    ) Allocator.Error!NodeId {
        var frames: std.ArrayListUnmanaged(ProducedValueFrame) = .empty;
        defer frames.deinit(self.allocator);
        var ops: std.ArrayListUnmanaged(ProducedValueOp) = .empty;
        defer ops.deinit(self.allocator);
        var results: std.ArrayListUnmanaged(NodeId) = .empty;
        defer results.deinit(self.allocator);
        errdefer for (frames.items) |frame| {
            _ = visiting.remove(frame.pair);
        };

        var delivered: ?NodeId = try self.enterProducedValue(root_checked, root_produced, visiting, completions, &frames, &ops, &results);
        while (true) {
            if (delivered) |node| {
                if (frames.items.len == 0) return node;
                try results.append(self.allocator, node);
                delivered = null;
            }
            const frame = frames.items[frames.items.len - 1];
            var failed = false;
            if (frame.next < ops.items.len) {
                const op = ops.items[frame.next];
                frames.items[frames.items.len - 1].next += 1;
                switch (op) {
                    .child => |child| {
                        delivered = try self.enterProducedValue(child.checked, child.produced, visiting, completions, &frames, &ops, &results);
                        continue;
                    },
                    .field_name => |field| failed = field.checked != field.produced,
                    .tag => |tag| failed = tag.checked_name != tag.produced_name or tag.checked_len != tag.produced_len,
                }
                if (!failed) continue;
            }

            _ = frames.pop();
            const witness = if (failed) null else try self.buildProducedValueWitness(frame, results.items[frame.results_start..]);
            ops.shrinkRetainingCapacity(frame.ops_start);
            results.shrinkRetainingCapacity(frame.results_start);
            const checked_root = self.graph.rootNode(frame.checked_node);
            const produced_root = self.graph.rootNode(frame.produced_node);
            delivered = witness orelse try self.relateUnmatchedProducedValue(frame.checked_node, frame.produced_node, checked_root, produced_root);
            _ = visiting.remove(frame.pair);
        }
    }

    /// The witness a pair relates to at once, or null after pushing the frame
    /// that relates a matching container's children.
    fn enterProducedValue(
        self: *BodyContext,
        checked_node: NodeId,
        produced_node: NodeId,
        visiting: *std.AutoHashMap(ProducedValuePair, void),
        completions: *CompletionMemo,
        frames: *std.ArrayListUnmanaged(ProducedValueFrame),
        ops: *std.ArrayListUnmanaged(ProducedValueOp),
        results: *std.ArrayListUnmanaged(NodeId),
    ) Allocator.Error!?NodeId {
        const gpa = self.allocator;
        const checked_root = self.graph.rootNode(checked_node);
        const produced_root = self.graph.rootNode(produced_node);
        if (checked_root == produced_root) return checked_node;

        const pair = ProducedValuePair{ .request = checked_root, .produced = produced_root };
        const entry = try visiting.getOrPut(pair);
        if (entry.found_existing) return produced_node;
        var pushed = false;
        defer if (!pushed) {
            _ = visiting.remove(pair);
        };

        if (try self.producedRuntimeValueIsProvenUninhabited(produced_root)) return produced_node;
        const checked_private_root = (try isGeneratedPrivateRootNode(self.graph, checked_root));
        const produced_private_root = (try isGeneratedPrivateRootNode(self.graph, produced_root));
        if (checked_private_root or produced_private_root) {
            // The structural witness records the representation of the value
            // that was actually produced. Generated-private roots are explicit
            // evidence but intentionally cannot join an ordinary public graph
            // class; the directed relation still validates the pair's shared
            // public interface so neither side's expectation is dropped.
            try relateRequestComponent(self.graph, checked_root, produced_root);
            // The private side is the runtime representation, matching the
            // selection every other site makes (field access, control-flow
            // result selection, and the containment branch below). Typing the
            // value at a public node against a private request is the state
            // `includeControlFlowResult` reports as fatal, so the checked side
            // is selected only when it is the private one.
            if (produced_private_root or try self.graph.containsGeneratedPrivate(produced_root)) {
                return produced_node;
            }
            return checked_node;
        }
        if (try self.producedPairCompletesRequest(checked_root, produced_root, completions)) return produced_node;

        const ops_start = ops.items.len;
        const matched: bool = matched: {
            const checked_content = (try self.graph.content(checked_root));
            const produced_content = (try self.graph.content(produced_root));
            switch (checked_content) {
                .named => |checked_named| switch (produced_content) {
                    .named => |produced_named| {
                        if (!sameNamedValueDefinition(checked_named, produced_named)) break :matched false;
                        const checked_backing = checked_named.backing orelse break :matched false;
                        const produced_backing = produced_named.backing orelse break :matched false;
                        try ops.append(gpa, .{ .child = .{ .checked = checked_backing.node, .produced = produced_backing.node } });
                        break :matched true;
                    },
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => break :matched false,
                },
                .list => |checked_elem| switch (produced_content) {
                    .list => |produced_elem| {
                        try ops.append(gpa, .{ .child = .{ .checked = checked_elem, .produced = produced_elem } });
                        break :matched true;
                    },
                    .redirect, .leaf, .unresolved, .primitive, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => break :matched false,
                },
                .box => |checked_elem| switch (produced_content) {
                    .box => |produced_elem| {
                        try ops.append(gpa, .{ .child = .{ .checked = checked_elem, .produced = produced_elem } });
                        break :matched true;
                    },
                    .redirect, .leaf, .unresolved, .primitive, .list, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => break :matched false,
                },
                .tuple => |checked_items| switch (produced_content) {
                    .tuple => |produced_items| {
                        if (checked_items.len != produced_items.len) break :matched false;
                        for (checked_items, produced_items) |checked_item, produced_item| {
                            try ops.append(gpa, .{ .child = .{ .checked = checked_item, .produced = produced_item } });
                        }
                        break :matched true;
                    },
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => break :matched false,
                },
                .func => |checked_fn| switch (produced_content) {
                    .func => |produced_fn| {
                        if (checked_fn.args.len != produced_fn.args.len) break :matched false;
                        return checked_node;
                    },
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => break :matched false,
                },
                .record => |checked_row| switch (produced_content) {
                    .record => |produced_row| {
                        if (checked_row.fields.len != produced_row.fields.len) break :matched false;
                        if (!(try self.rowExtsAreValueCompatible(checked_row.ext, produced_row.ext, .record))) break :matched false;
                        for (checked_row.fields, produced_row.fields) |checked_field, produced_field| {
                            try ops.append(gpa, .{ .field_name = .{ .checked = checked_field.name, .produced = produced_field.name } });
                            try ops.append(gpa, .{ .child = .{ .checked = checked_field.ty, .produced = produced_field.ty } });
                        }
                        break :matched true;
                    },
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .empty_tag_union, .empty_record, .named, .erased, .zst => break :matched false,
                },
                .tag_union => |checked_row| switch (produced_content) {
                    .tag_union => |produced_row| {
                        if (checked_row.tags.len != produced_row.tags.len) break :matched false;
                        if (!(try self.rowExtsAreValueCompatible(checked_row.ext, produced_row.ext, .tag_union))) break :matched false;
                        for (checked_row.tags, produced_row.tags) |checked_tag, produced_tag| {
                            try ops.append(gpa, .{ .tag = .{
                                .checked_name = checked_tag.name,
                                .produced_name = produced_tag.name,
                                .checked_len = checked_tag.payloads.len,
                                .produced_len = produced_tag.payloads.len,
                            } });
                            if (checked_tag.payloads.len != produced_tag.payloads.len) break;
                            for (checked_tag.payloads, produced_tag.payloads) |checked_payload, produced_payload| {
                                try ops.append(gpa, .{ .child = .{ .checked = checked_payload, .produced = produced_payload } });
                            }
                        }
                        break :matched true;
                    },
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => break :matched false,
                },
                .redirect, .leaf, .unresolved, .primitive, .empty_tag_union, .empty_record, .erased, .zst => break :matched false,
            }
        };
        if (!matched) {
            ops.shrinkRetainingCapacity(ops_start);
            return try self.relateUnmatchedProducedValue(checked_node, produced_node, checked_root, produced_root);
        }
        try frames.append(gpa, .{
            .checked_node = checked_node,
            .produced_node = produced_node,
            .produced_content = (try self.graph.content(produced_root)),
            .pair = pair,
            .ops_start = ops_start,
            .next = ops_start,
            .results_start = results.items.len,
        });
        pushed = true;
        return null;
    }

    /// A pair whose containers do not match relates through their shared
    /// interface when either side is generated-private, and unifies otherwise.
    fn relateUnmatchedProducedValue(
        self: *BodyContext,
        checked_node: NodeId,
        produced_node: NodeId,
        checked_root: NodeId,
        produced_root: NodeId,
    ) Allocator.Error!NodeId {
        const checked_private = try self.graph.containsGeneratedPrivate(checked_root);
        const produced_private = try self.graph.containsGeneratedPrivate(produced_root);
        if (checked_private or produced_private) {
            try relateRequestComponent(self.graph, checked_root, produced_root);
            return if (produced_private) produced_node else checked_node;
        }
        try self.graph.unify(checked_root, produced_root);
        return checked_node;
    }

    /// Build a matched container's witness from its children's; the
    /// produced node itself when no child's witness differs.
    fn buildProducedValueWitness(self: *BodyContext, frame: ProducedValueFrame, children: []const NodeId) Allocator.Error!NodeId {
        const produced_node = frame.produced_node;
        switch (frame.produced_content) {
            .named => |produced_named| {
                const produced_backing = produced_named.backing.?;
                const backing = children[0];
                if (self.graph.sameClass(backing, produced_backing.node)) return produced_node;
                var witness = produced_named.*;
                witness.backing = .{
                    .node = backing,
                    .use = produced_backing.use,
                    .authority = produced_backing.authority,
                };
                return try self.graph.newNode(try self.graph.namedContent(witness));
            },
            .list => |produced_elem| {
                if (self.graph.sameClass(children[0], produced_elem)) return produced_node;
                return try self.graph.newNode(.{ .list = children[0] });
            },
            .box => |produced_elem| {
                if (self.graph.sameClass(children[0], produced_elem)) return produced_node;
                return try self.graph.newNode(.{ .box = children[0] });
            },
            .tuple => |produced_items| {
                var changed = false;
                for (children, produced_items) |item, produced_item| {
                    changed = changed or !self.graph.sameClass(item, produced_item);
                }
                if (!changed) return produced_node;
                return try self.graph.newNode(.{ .tuple = try self.graph.arena().dupe(NodeId, children) });
            },
            .record => |produced_row| {
                const fields = try self.graph.arena().alloc(InstField, produced_row.fields.len);
                var changed = false;
                for (produced_row.fields, children, fields) |produced_field, ty, *out| {
                    out.* = .{
                        .name = produced_field.name,
                        .ty = ty,
                        .value_ty = produced_field.value_ty,
                        .kind = produced_field.kind,
                        .default = produced_field.default,
                    };
                    changed = changed or !self.graph.sameClass(ty, produced_field.ty);
                }
                if (!changed) return produced_node;
                return try self.graph.newNode(.{ .record = .{
                    .fields = fields,
                    .ext = self.graph.rootNode(produced_row.ext),
                } });
            },
            .tag_union => |produced_row| {
                const tags = try self.graph.arena().alloc(InstTag, produced_row.tags.len);
                var changed = false;
                var offset: usize = 0;
                for (produced_row.tags, tags) |produced_tag, *out| {
                    const payloads = try self.graph.arena().dupe(NodeId, children[offset..][0..produced_tag.payloads.len]);
                    offset += produced_tag.payloads.len;
                    for (payloads, produced_tag.payloads) |payload, produced_payload| {
                        changed = changed or !self.graph.sameClass(payload, produced_payload);
                    }
                    out.* = .{
                        .name = produced_tag.name,
                        .checked_name = produced_tag.checked_name,
                        .payloads = payloads,
                    };
                }
                if (!changed) return produced_node;
                return try self.graph.newNode(.{ .tag_union = .{
                    .tags = tags,
                    .ext = self.graph.rootNode(produced_row.ext),
                } });
            },
            .redirect, .leaf, .unresolved, .primitive, .func, .empty_tag_union, .empty_record, .erased, .zst => unreachable,
        }
    }

    fn producedValueHasExplicitRepresentationEvidence(
        self: *BodyContext,
        checked_node: NodeId,
        produced_node: NodeId,
    ) Allocator.Error!bool {
        var evidence = ProducedValueEvidence{
            .ctx = self,
            .visiting = std.AutoHashMap(ProducedValuePair, void).init(self.allocator),
        };
        defer evidence.visiting.deinit();
        return try ProducedValueEvidence.Eval.run(self.allocator, &evidence, .{ .request = checked_node, .produced = produced_node });
    }

    /// Whether a produced value carries representation evidence its checked
    /// node lacks: every differing child of a matching container must carry
    /// it, and at least one must differ. Evaluated on explicit stacks; a pair
    /// already on the current path carries none.
    const ProducedValueEvidence = struct {
        ctx: *BodyContext,
        visiting: std.AutoHashMap(ProducedValuePair, void),

        const Eval = collections.AnyAll.Evaluation(ProducedValuePair, ProducedValueEvidence);

        pub fn enter(self: *ProducedValueEvidence, items: Eval.Items, pair: ProducedValuePair) Allocator.Error!Eval.Expansion {
            const graph = self.ctx.graph;
            const checked_root = graph.rootNode(pair.request);
            const produced_root = graph.rootNode(pair.produced);
            if (checked_root == produced_root) return .{ .value = false };
            if (try graph.containsGeneratedPrivate(checked_root)) return .{ .value = true };
            if (try graph.containsGeneratedPrivate(produced_root)) return .{ .value = true };
            if (try self.ctx.resultCompletesRequest(checked_root, produced_root)) return .{ .value = true };

            const root_pair = ProducedValuePair{ .request = checked_root, .produced = produced_root };
            if (self.visiting.contains(root_pair)) return .{ .value = false };

            var children: usize = 0;
            const checked_content = (try graph.content(checked_root));
            const produced_content = (try graph.content(produced_root));
            switch (checked_content) {
                .named => |checked_named| switch (produced_content) {
                    .named => |produced_named| {
                        if (!sameNamedValueDefinition(checked_named, produced_named)) return .{ .value = false };
                        const checked_backing = checked_named.backing orelse return .{ .value = false };
                        const produced_backing = produced_named.backing orelse return .{ .value = false };
                        try items.add(.{ .request = checked_backing.node, .produced = produced_backing.node });
                        children += 1;
                    },
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return .{ .value = false },
                },
                .func => |checked_fn| switch (produced_content) {
                    .func => |produced_fn| return .{ .value = checked_fn.args.len == produced_fn.args.len },
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return .{ .value = false },
                },
                .list => |checked_elem| switch (produced_content) {
                    .list => |produced_elem| {
                        try items.add(.{ .request = checked_elem, .produced = produced_elem });
                        children += 1;
                    },
                    .redirect, .leaf, .unresolved, .primitive, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return .{ .value = false },
                },
                .box => |checked_elem| switch (produced_content) {
                    .box => |produced_elem| {
                        try items.add(.{ .request = checked_elem, .produced = produced_elem });
                        children += 1;
                    },
                    .redirect, .leaf, .unresolved, .primitive, .list, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return .{ .value = false },
                },
                .tuple => |checked_items| switch (produced_content) {
                    .tuple => |produced_items| {
                        if (checked_items.len != produced_items.len) return .{ .value = false };
                        for (checked_items, produced_items) |checked_item, produced_item| {
                            if (graph.sameClass(checked_item, produced_item)) continue;
                            try items.add(.{ .request = checked_item, .produced = produced_item });
                            children += 1;
                        }
                    },
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return .{ .value = false },
                },
                .record => |checked_row| switch (produced_content) {
                    .record => |produced_row| {
                        if (checked_row.fields.len != produced_row.fields.len) return .{ .value = false };
                        if (!(try self.ctx.rowExtsAreValueCompatible(checked_row.ext, produced_row.ext, .record))) return .{ .value = false };
                        for (checked_row.fields, produced_row.fields) |checked_field, produced_field| {
                            if (checked_field.name != produced_field.name) return .{ .value = false };
                            if (graph.sameClass(checked_field.ty, produced_field.ty)) continue;
                            try items.add(.{ .request = checked_field.ty, .produced = produced_field.ty });
                            children += 1;
                        }
                    },
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .empty_tag_union, .empty_record, .named, .erased, .zst => return .{ .value = false },
                },
                .tag_union => |checked_row| switch (produced_content) {
                    .tag_union => |produced_row| {
                        if (checked_row.tags.len != produced_row.tags.len) return .{ .value = false };
                        if (!(try self.ctx.rowExtsAreValueCompatible(checked_row.ext, produced_row.ext, .tag_union))) return .{ .value = false };
                        for (checked_row.tags, produced_row.tags) |checked_tag, produced_tag| {
                            if (checked_tag.name != produced_tag.name or checked_tag.payloads.len != produced_tag.payloads.len) {
                                return .{ .value = false };
                            }
                            for (checked_tag.payloads, produced_tag.payloads) |checked_payload, produced_payload| {
                                if (graph.sameClass(checked_payload, produced_payload)) continue;
                                try items.add(.{ .request = checked_payload, .produced = produced_payload });
                                children += 1;
                            }
                        }
                    },
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return .{ .value = false },
                },
                .redirect, .leaf, .unresolved, .primitive, .empty_tag_union, .empty_record, .erased, .zst => return .{ .value = false },
            }
            if (children == 0) return .{ .value = false };
            try self.visiting.put(root_pair, {});
            return .{ .group = .all };
        }

        pub fn exit(self: *ProducedValueEvidence, pair: ProducedValuePair, _: ?bool) Allocator.Error!void {
            _ = self.visiting.remove(.{
                .request = self.ctx.graph.rootNode(pair.request),
                .produced = self.ctx.graph.rootNode(pair.produced),
            });
        }
    };

    fn rowExtsAreValueCompatible(self: *BodyContext, checked_ext: NodeId, produced_ext: NodeId, kind: ProducedValueRowKind) Allocator.Error!bool {
        const checked_root = self.graph.rootNode(checked_ext);
        const produced_root = self.graph.rootNode(produced_ext);
        if (checked_root == produced_root) return true;
        return switch ((try self.graph.content(checked_root))) {
            .empty_record => kind == .record and (try self.graph.content(produced_root)) == .empty_record,
            .empty_tag_union => kind == .tag_union and (try self.graph.content(produced_root)) == .empty_tag_union,
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .named, .erased, .zst => false,
        };
    }

    /// How one child relation combines into its parent's.
    const RequestCompletionOp = struct {
        request: NodeId,
        produced: NodeId,
        combine: enum {
            /// Completed or unchanged children accumulate; a mismatch decides.
            fold,
            /// A row extension must be unchanged.
            unchanged_extension,
            /// A public named backing completes the wrapper unless it mismatches.
            backing,
        },
    };

    /// Whether a produced value's graph completes a request's. Composite
    /// relations are explicit frames over their child relations, so type
    /// depth never becomes native call depth; a pair already on the current
    /// path is unchanged by assumption. With `memo`, every relation decided
    /// without such an assumption is recorded for its pair.
    fn requestCompletionRelation(
        self: *BodyContext,
        request_node: NodeId,
        produced_node: NodeId,
        visiting: *RequestCompletionPath,
        memo: ?*CompletionMemo,
    ) Allocator.Error!RequestCompletion {
        const Frame = struct {
            pair: RequestCompletionPair,
            ops_start: usize,
            next: usize,
            relation: RequestCompletion,
            /// Whether a relation below this frame assumed a pair on the path.
            assumed: bool = false,
        };
        var frames: std.ArrayListUnmanaged(Frame) = .empty;
        defer frames.deinit(self.allocator);
        var ops: std.ArrayListUnmanaged(RequestCompletionOp) = .empty;
        defer ops.deinit(self.allocator);
        errdefer for (frames.items) |frame| {
            visiting.leave(frame.pair);
        };

        var delivered: RequestCompletion = undefined;
        var has_delivery = false;
        var assumed = false;
        if (try self.enterRequestCompletion(request_node, produced_node, visiting, &ops, &assumed)) |relation| {
            if (memo) |m| try m.relations.put(.{ .request = self.graph.rootNode(request_node), .produced = self.graph.rootNode(produced_node) }, relation);
            return relation;
        }
        try frames.append(self.allocator, .{
            .pair = .{ .request = self.graph.rootNode(request_node), .produced = self.graph.rootNode(produced_node) },
            .ops_start = 0,
            .next = 0,
            .relation = .unchanged,
        });
        while (true) {
            const frame = &frames.items[frames.items.len - 1];
            var finished: ?RequestCompletion = null;
            if (has_delivery) {
                has_delivery = false;
                const op = ops.items[frame.next - 1];
                switch (op.combine) {
                    .fold => switch (delivered) {
                        .unchanged => {},
                        .completed => frame.relation = .completed,
                        .mismatch => finished = .mismatch,
                    },
                    .unchanged_extension => if (delivered != .unchanged) {
                        finished = .mismatch;
                    },
                    .backing => frame.relation = switch (delivered) {
                        .unchanged, .completed => .completed,
                        .mismatch => .mismatch,
                    },
                }
            }
            if (finished == null) {
                if (frame.next < ops.items.len) {
                    const op = ops.items[frame.next];
                    frame.next += 1;
                    const ops_start = ops.items.len;
                    assumed = false;
                    if (try self.enterRequestCompletion(op.request, op.produced, visiting, &ops, &assumed)) |relation| {
                        if (assumed) {
                            for (frames.items) |*open| open.assumed = true;
                        } else if (memo) |m| {
                            try m.relations.put(.{ .request = self.graph.rootNode(op.request), .produced = self.graph.rootNode(op.produced) }, relation);
                        }
                        delivered = relation;
                        has_delivery = true;
                    } else {
                        try frames.append(self.allocator, .{
                            .pair = .{ .request = self.graph.rootNode(op.request), .produced = self.graph.rootNode(op.produced) },
                            .ops_start = ops_start,
                            .next = ops_start,
                            .relation = .unchanged,
                        });
                    }
                    continue;
                }
                finished = frame.relation;
            }

            const done = frames.pop().?;
            visiting.leave(done.pair);
            ops.shrinkRetainingCapacity(done.ops_start);
            if (memo) |m| if (!done.assumed) try m.relations.put(done.pair, finished.?);
            if (frames.items.len == 0) return finished.?;
            delivered = finished.?;
            has_delivery = true;
        }
    }

    /// A pair's relation when it is decided at once; otherwise mark it on the
    /// current path, list its child relations, and return null.
    fn enterRequestCompletion(
        self: *BodyContext,
        request_node: NodeId,
        produced_node: NodeId,
        visiting: *RequestCompletionPath,
        ops: *std.ArrayListUnmanaged(RequestCompletionOp),
        assumed: *bool,
    ) Allocator.Error!?RequestCompletion {
        const gpa = self.allocator;
        const request_root = self.graph.rootNode(request_node);
        const produced_root = self.graph.rootNode(produced_node);
        if (request_root == produced_root) return .unchanged;
        if (try self.nodeIsProvenUninhabited(request_root) and
            !try self.nodeIsProvenUninhabited(produced_root))
        {
            return .completed;
        }

        const pair = RequestCompletionPair{ .request = request_root, .produced = produced_root };
        if (!try visiting.enter(pair)) {
            assumed.* = true;
            return .unchanged;
        }
        errdefer visiting.leave(pair);
        const start = ops.items.len;
        const relation: ?RequestCompletion = relation: {
            if ((try self.checkedPublicInspectableBacking(produced_root))) |backing| {
                try ops.append(gpa, .{ .request = request_root, .produced = backing.node, .combine = .backing });
                break :relation null;
            }
            if ((try self.checkedPublicInspectableBacking(request_root))) |backing| {
                try ops.append(gpa, .{ .request = backing.node, .produced = produced_root, .combine = .backing });
                break :relation null;
            }
            break :relation switch ((try self.graph.content(request_root))) {
                .primitive => |request_primitive| switch ((try self.graph.content(produced_root))) {
                    .primitive => |produced_primitive| if (request_primitive == produced_primitive) .unchanged else .mismatch,
                    .redirect, .leaf, .unresolved, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => .mismatch,
                },
                .list => |request_elem| switch ((try self.graph.content(produced_root))) {
                    .list => |produced_elem| blk: {
                        try ops.append(gpa, .{ .request = request_elem, .produced = produced_elem, .combine = .fold });
                        break :blk null;
                    },
                    .redirect, .leaf, .unresolved, .primitive, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => .mismatch,
                },
                .box => |request_elem| switch ((try self.graph.content(produced_root))) {
                    .box => |produced_elem| blk: {
                        try ops.append(gpa, .{ .request = request_elem, .produced = produced_elem, .combine = .fold });
                        break :blk null;
                    },
                    .redirect, .leaf, .unresolved, .primitive, .list, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => .mismatch,
                },
                .tuple => |request_items| switch ((try self.graph.content(produced_root))) {
                    .tuple => |produced_items| blk: {
                        if (request_items.len != produced_items.len) break :blk .mismatch;
                        for (request_items, produced_items) |request_item, produced_item| {
                            try ops.append(gpa, .{ .request = request_item, .produced = produced_item, .combine = .fold });
                        }
                        break :blk null;
                    },
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => .mismatch,
                },
                .func => |request_fn| switch ((try self.graph.content(produced_root))) {
                    .func => |produced_fn| blk: {
                        if (request_fn.args.len != produced_fn.args.len) break :blk .mismatch;
                        for (request_fn.args, produced_fn.args) |request_arg, produced_arg| {
                            if (!self.graph.sameClass(request_arg, produced_arg)) break :blk .mismatch;
                        }
                        try ops.append(gpa, .{ .request = request_fn.ret, .produced = produced_fn.ret, .combine = .fold });
                        break :blk null;
                    },
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => .mismatch,
                },
                .tag_union => |request_row| switch ((try self.graph.content(produced_root))) {
                    .tag_union => |produced_row| blk: {
                        try ops.append(gpa, .{ .request = request_row.ext, .produced = produced_row.ext, .combine = .unchanged_extension });
                        if (request_row.tags.len != produced_row.tags.len) break :blk .mismatch;
                        for (request_row.tags, produced_row.tags) |request_tag, produced_tag| {
                            if (request_tag.name != produced_tag.name) break :blk .mismatch;
                            if (request_tag.payloads.len != produced_tag.payloads.len) break :blk .mismatch;
                            for (request_tag.payloads, produced_tag.payloads) |request_payload, produced_payload| {
                                try ops.append(gpa, .{ .request = request_payload, .produced = produced_payload, .combine = .fold });
                            }
                        }
                        break :blk null;
                    },
                    .empty_tag_union, .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_record, .named, .erased, .zst => .mismatch,
                },
                .record => |request_row| switch ((try self.graph.content(produced_root))) {
                    .record => |produced_row| blk: {
                        try ops.append(gpa, .{ .request = request_row.ext, .produced = produced_row.ext, .combine = .unchanged_extension });
                        if (request_row.fields.len != produced_row.fields.len) break :blk .mismatch;
                        for (request_row.fields, produced_row.fields) |request_field, produced_field| {
                            if (request_field.name != produced_field.name) break :blk .mismatch;
                            try ops.append(gpa, .{ .request = request_field.ty, .produced = produced_field.ty, .combine = .fold });
                        }
                        break :blk null;
                    },
                    .empty_record, .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .empty_tag_union, .named, .erased, .zst => .mismatch,
                },
                .empty_tag_union => switch ((try self.graph.content(produced_root))) {
                    .empty_tag_union => .unchanged,
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_record, .named, .erased, .zst => .mismatch,
                },
                .empty_record => switch ((try self.graph.content(produced_root))) {
                    .empty_record => .unchanged,
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .named, .erased, .zst => .mismatch,
                },
                .erased => |request_digest| switch ((try self.graph.content(produced_root))) {
                    .erased => |produced_digest| if (std.mem.eql(u8, request_digest.bytes[0..], produced_digest.bytes[0..])) .unchanged else .mismatch,
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .zst => .mismatch,
                },
                .zst => switch ((try self.graph.content(produced_root))) {
                    .zst => .unchanged,
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased => .mismatch,
                },
                .named,
                .unresolved,
                .redirect,
                .leaf,
                => .mismatch,
            };
        };
        if (relation) |decided| {
            ops.shrinkRetainingCapacity(start);
            visiting.leave(pair);
            return decided;
        }
        return null;
    }

    fn checkedPublicInspectableBacking(self: *BodyContext, node: NodeId) Allocator.Error!?InstBacking {
        const named = switch ((try self.graph.content(node))) {
            .named => |named| named,
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return null,
        };
        const backing = named.backing orelse return null;
        if (backing.authority != .checked_public or backing.use != .inspectable) return null;
        return backing;
    }

    fn completedFunctionNodeForLoweredRet(
        self: *BodyContext,
        fn_node: NodeId,
        lowered_ret: DraftTypeCell,
        has_explicit_value_witness: bool,
    ) Allocator.Error!NodeId {
        const function = try self.graph.functionNodes(fn_node);
        const lowered_ret_node = try lowered_ret.toGraphNode(self.graph);
        if (self.graph.sameClass(function.ret, lowered_ret_node)) return fn_node;
        const completes_request = try self.resultCompletesRequest(function.ret, lowered_ret_node);
        const contains_generated_private = try self.graph.containsGeneratedPrivate(lowered_ret_node);
        if (!completes_request and !contains_generated_private and !has_explicit_value_witness) {
            try relateRequestComponent(self.graph, function.ret, lowered_ret_node);
            return fn_node;
        }
        const completed_fn = try self.graphFunctionNode(function.args, lowered_ret_node);
        if (try self.graph.containsGeneratedPrivate(completed_fn) and
            self.graph.requestSourceInterface(completed_fn) == null)
        {
            const source_interface = self.graph.requestSourceInterface(fn_node) orelse fn_node;
            try self.graph.registerRequestSourceInterface(completed_fn, source_interface);
        }
        return completed_fn;
    }

    /// Lower a procedure whose declaration carries a type annotation and no
    /// implementation. The procedure keeps its declared arity so every call
    /// site still links and still evaluates its arguments, and reaching the
    /// body crashes.
    fn lowerUnimplementedTemplateAtNode(
        self: *BodyContext,
        declaration: checked.UnimplementedDeclaration,
        fn_nodes: FunctionNodes,
        ret_cell: DraftTypeCell,
    ) Allocator.Error!LoweredTemplateBody {
        const saved_loc = self.builder.current_loc;
        defer self.builder.current_loc = saved_loc;
        const saved_region = self.builder.current_region;
        defer self.builder.current_region = saved_region;
        self.builder.current_loc = try self.sourceLocFor(declaration.region);
        self.builder.current_region = declaration.region;

        const args = try self.allocator.alloc(DraftTypedLocal, fn_nodes.args.len);
        defer self.allocator.free(args);
        for (fn_nodes.args, 0..) |arg_node, index| {
            const cell = DraftTypeCell.fromGraphNode(arg_node);
            args[index] = .{
                .local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), cell, null),
                .ty = cell,
            };
        }
        return .{
            .args = try self.draft.addTypedLocalSpan(args),
            .body = try self.runtimeCrashExprAtCell(ret_cell, Common.unimplemented_declaration_crash),
            .ret = ret_cell,
        };
    }

    /// A lambda's function lowering in progress, from its arguments to its
    /// body. It holds every piece of context state the lowering moves, to
    /// restore once the body is finished.
    const LambdaLowering = struct {
        /// Saved by a nested function's lowering: the enclosing entry guards.
        nested_entry_guards: ?[]const NodeId = null,
        /// Saved by a nested lambda's lowering: the binders its arguments shadow.
        saved_binders: ?std.ArrayList(BinderRestore) = null,
        saved_propagation: bool,
        lambda_id: checked.CheckedExprId,
        checked_body: checked.CheckedExprId,
        ret_cell: DraftTypeCell,
        saved_return_target: ?ActiveReturnTarget,
        saved_loc: base.SourceLoc,
        saved_region: base.Region,
        exhaustiveness_scope: ExhaustivenessContext.Scope,
        args: []DraftTypedLocal = &.{},
        arg_lets: std.ArrayList(LambdaArgLet) = .empty,
        arg_literal_guards: std.ArrayList(PatternLiteralGuard) = .empty,
        materialized_args: std.ArrayList(MaterializedArg) = .empty,
        declared_ret_node: NodeId = undefined,
        body_ret_cell: DraftTypeCell = undefined,
        /// How the body lowers: all at once (an uninhabited argument, or
        /// materialized argument bindings), or as a child at `cell`.
        body: union(enum) {
            immediate_result: LoweredLambdaArgs,
            /// Materialized argument bindings around the body.
            materialized: MaterializeRequest,
            child: struct { cell: DraftTypeCell, return_boundary: bool },
        } = undefined,
        restored: bool = false,
    };

    fn lowerLambdaTemplateAtNode(
        self: *BodyContext,
        lambda_id: checked.CheckedExprId,
        lambda: @FieldType(checked.CheckedExprData, "lambda"),
        fn_node: NodeId,
    ) Allocator.Error!LoweredTemplateBody {
        var lowering = try self.beginLambdaLowering(lambda_id, lambda, fn_node);
        defer self.restoreLambdaLowering(&lowering);
        return try self.finishLambdaLowering(&lowering, try self.lowerLambdaLoweringBody(&lowering));
    }

    fn lowerNestedFunctionAtNode(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        fn_node: NodeId,
        capture_entry_guards: []const NodeId,
    ) Allocator.Error!LoweredTemplateBody {
        var lowering = try self.beginNestedLambdaLowering(expr_id, fn_node, capture_entry_guards);
        defer self.restoreLambdaLowering(&lowering);
        return try self.finishLambdaLowering(&lowering, try self.lowerLambdaLoweringBody(&lowering));
    }

    /// Lower a lambda body that lowers as a child, directly.
    fn lowerLambdaLoweringBody(self: *BodyContext, lowering: *const LambdaLowering) Allocator.Error!?DraftExprId {
        return switch (lowering.body) {
            .immediate_result => null,
            .materialized => |request| try self.runMaterialize(request),
            .child => |child| try self.lowerExprAtTypeCell(lowering.checked_body, child.cell),
        };
    }

    /// Enter a nested function's lambda: its entry guards and the binders its
    /// arguments shadow, then the lambda itself.
    fn beginNestedLambdaLowering(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        fn_node: NodeId,
        capture_entry_guards: []const NodeId,
    ) Allocator.Error!LambdaLowering {
        const fn_nodes = try self.graph.functionNodes(fn_node);
        const saved_function_entry_demand_guards = self.function_entry_demand_guards;
        const entry_guards = try self.graph.arena().alloc(NodeId, fn_nodes.args.len + capture_entry_guards.len);
        @memcpy(entry_guards[0..fn_nodes.args.len], fn_nodes.args);
        @memcpy(entry_guards[fn_nodes.args.len..], capture_entry_guards);
        self.function_entry_demand_guards = entry_guards;
        errdefer self.function_entry_demand_guards = saved_function_entry_demand_guards;
        const expr = self.view.bodies.expr(expr_id);
        const lambda_id, const lambda = switch (expr.data) {
            .lambda => |lambda| .{ expr_id, lambda },
            .closure => |closure| blk: {
                const lambda_expr = self.view.bodies.expr(closure.lambda);
                if (lambda_expr.data != .lambda) Common.invariant("checked closure did not point at a lambda expression");
                break :blk .{ closure.lambda, lambda_expr.data.lambda };
            },
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("local procedure site did not point at a lambda or closure"),
        };

        var saved = std.ArrayList(BinderRestore).empty;
        errdefer saved.deinit(self.allocator);
        for (lambda.args) |pattern_id| try self.savePatternBinders(pattern_id, &saved);
        errdefer self.restoreBinders(saved.items);
        var lowering = try self.beginLambdaLowering(lambda_id, lambda, fn_node);
        lowering.nested_entry_guards = saved_function_entry_demand_guards;
        lowering.saved_binders = saved;
        return lowering;
    }

    /// Enter a lambda at its function node and lower its arguments, deciding
    /// how its body lowers.
    fn beginLambdaLowering(
        self: *BodyContext,
        lambda_id: checked.CheckedExprId,
        lambda: @FieldType(checked.CheckedExprData, "lambda"),
        fn_node: NodeId,
    ) Allocator.Error!LambdaLowering {
        const fn_nodes = try self.graph.functionNodes(fn_node);
        if (fn_nodes.args.len != lambda.args.len) Common.invariant("lambda template arity differs from concrete function type");

        const saved_propagation = self.propagate_constructor_value_evidence;
        self.propagate_constructor_value_evidence = saved_propagation or
            self.graph.requestPropagatesConstructorEvidence(fn_node);
        errdefer self.propagate_constructor_value_evidence = saved_propagation;

        const checked_args = lambda.args;
        const arg_nodes = fn_nodes.args;
        const checked_body = lambda.body;
        const ret_cell = DraftTypeCell.fromGraphNode(fn_nodes.ret);
        if (arg_nodes.len != checked_args.len) Common.invariant("lambda arity differs from concrete function type");
        var lowering = LambdaLowering{
            .saved_propagation = saved_propagation,
            .lambda_id = lambda_id,
            .checked_body = checked_body,
            .ret_cell = ret_cell,
            .saved_return_target = self.current_return_target,
            .saved_loc = self.builder.current_loc,
            .saved_region = self.builder.current_region,
            .exhaustiveness_scope = undefined,
        };
        self.current_return_target = .{ .lambda = lambda_id, .cell = ret_cell };
        errdefer self.current_return_target = lowering.saved_return_target;
        errdefer self.builder.current_loc = lowering.saved_loc;
        errdefer self.builder.current_region = lowering.saved_region;
        const body_expr = self.view.bodies.expr(checked_body);
        const body_region = self.sourceRegionForExpr(body_expr);
        self.builder.current_loc = try self.sourceLocFor(body_region);
        self.builder.current_region = body_region;

        lowering.exhaustiveness_scope = self.comptime_exhaustiveness_context.resetForRuntimeFunction();
        errdefer lowering.exhaustiveness_scope.leave();

        for (arg_nodes, 0..) |arg_node, uninhabited_index| {
            if (!try self.nodeIsProvenUninhabited(arg_node)) continue;
            const args = try self.allocator.alloc(DraftTypedLocal, checked_args.len);
            defer self.allocator.free(args);
            for (arg_nodes, 0..) |node, index| {
                const cell = DraftTypeCell.fromGraphNode(node);
                args[index] = .{ .local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), cell, null), .ty = cell };
            }
            const arg_cell = DraftTypeCell.fromGraphNode(arg_node);
            const scrutinee = try self.addExprWithTypeCell(arg_cell, .{ .local = args[uninhabited_index].local });
            const body = try self.addExprWithTypeCell(ret_cell, .{ .match_ = .{
                .scrutinee = scrutinee,
                .branches = try self.addBranchSpan(&.{}),
            } });
            lowering.body = .{ .immediate_result = .{
                .args = try self.draft.addTypedLocalSpan(args),
                .body = body,
                .ret = ret_cell,
            } };
            return lowering;
        }

        lowering.args = try self.allocator.alloc(DraftTypedLocal, checked_args.len);
        errdefer self.freeLambdaLoweringArgs(&lowering);
        const args = lowering.args;

        for (checked_args, arg_nodes, 0..) |pattern_id, arg_node, i| {
            const arg_cell = DraftTypeCell.fromGraphNode(arg_node);
            try relateRequestComponent(
                self.graph,
                try self.instNode(self.view.bodies.pattern(pattern_id).ty),
                arg_node,
            );
            if (self.patternIsShapeFree(pattern_id)) {
                const pat = try self.lowerShapeFreePatternAtCell(pattern_id, arg_cell);
                switch (self.patData(pat)) {
                    .bind => |local| args[i] = .{ .local = local, .ty = arg_cell },
                    .wildcard, .as, .record, .tuple, .list, .tag, .nominal, .int_lit, .dec_lit, .frac_f32_lit, .frac_f64_lit, .str_lit, .str_pattern => {
                        const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), arg_cell, null);
                        args[i] = .{ .local = local, .ty = arg_cell };
                        const value = try self.addExprWithTypeCell(arg_cell, .{ .local = local });
                        try lowering.arg_lets.append(self.allocator, .{ .pat = pat, .value = value });
                    },
                }
                continue;
            }
            if (try self.patternNeedsExplicitBinding(pattern_id)) {
                const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), arg_cell, null);
                args[i] = .{ .local = local, .ty = arg_cell };
                const value = try self.addExprWithTypeCell(arg_cell, .{ .local = local });
                try lowering.materialized_args.append(self.allocator, .{
                    .pattern = pattern_id,
                    .value = value,
                    .ty = arg_cell,
                });
                continue;
            }

            const guards_start = self.pattern_literal_guards.items.len;
            const pat = try self.lowerPatternAtNode(pattern_id, arg_node);
            const literal_guards = try self.drainPatternLiteralGuards(guards_start);
            defer self.allocator.free(literal_guards);
            try lowering.arg_literal_guards.appendSlice(self.allocator, literal_guards);
            switch (self.patData(pat)) {
                .bind => |local| args[i] = .{ .local = local, .ty = arg_cell },
                .wildcard, .as, .record, .tuple, .list, .tag, .nominal, .int_lit, .dec_lit, .frac_f32_lit, .frac_f64_lit, .str_lit, .str_pattern => {
                    const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), arg_cell, null);
                    args[i] = .{ .local = local, .ty = arg_cell };
                    const value = try self.addExprWithTypeCell(arg_cell, .{ .local = local });
                    try lowering.arg_lets.append(self.allocator, .{ .pat = pat, .value = value });
                },
            }
        }

        lowering.declared_ret_node = try ret_cell.toGraphNode(self.graph);
        // A runtime error body produces no value, and its checked type can
        // contain the error it was retired for, so it takes the declared
        // result's cell like any other consumer's representation.
        lowering.body_ret_cell = if (self.view.bodies.expr(checked_body).data != .runtime_error and
            try self.nodeIsProvenUninhabited(lowering.declared_ret_node))
            DraftTypeCell.fromGraphNode(try self.lowerTypeNode(self.view.bodies.expr(checked_body).ty))
        else
            ret_cell;
        const body_ret_cell = lowering.body_ret_cell;
        self.current_return_target = .{ .lambda = lambda_id, .cell = body_ret_cell };
        if (lowering.materialized_args.items.len != 0) {
            lowering.body = .{ .materialized = try self.materializedArgsRequest(
                lowering.materialized_args.items,
                0,
                lambda_id,
                checked_body,
                body_ret_cell,
            ) };
            return lowering;
        }
        // A body whose checked type is not the
        // function's checked result is a composed `?` result (design.md "Try
        // Return-Row Composition"), lowered at its own type's cell and
        // returned across the function's return boundary.
        if (self.checkedExprDivergesInLoweredRuntime(checked_body)) {
            lowering.body = .{ .child = .{ .cell = body_ret_cell, .return_boundary = false } };
            return lowering;
        }
        const body_ty = self.view.bodies.expr(checked_body).ty;
        const fn_ret_ty = self.checkedFunctionType(self.view.bodies.expr(lambda_id).ty).ret;
        if (resolvedPayload(self.view, body_ty).root == resolvedPayload(self.view, fn_ret_ty).root) {
            lowering.body = .{ .child = .{ .cell = body_ret_cell, .return_boundary = false } };
            return lowering;
        }
        lowering.body = .{ .child = .{
            .cell = DraftTypeCell.fromGraphNode(try self.lowerTypeNode(body_ty)),
            .return_boundary = true,
        } };
        return lowering;
    }

    fn freeLambdaLoweringArgs(self: *BodyContext, lowering: *LambdaLowering) void {
        self.allocator.free(lowering.args);
        lowering.args = &.{};
        lowering.arg_lets.deinit(self.allocator);
        lowering.arg_literal_guards.deinit(self.allocator);
        lowering.materialized_args.deinit(self.allocator);
    }

    /// Finish a lambda's lowering once its body has lowered: apply argument
    /// literal guards and pattern bindings, and settle the produced result.
    fn finishLambdaLowering(self: *BodyContext, lowering: *LambdaLowering, child_body: ?DraftExprId) Allocator.Error!LoweredTemplateBody {
        const body_ret_cell = lowering.body_ret_cell;
        var body = switch (lowering.body) {
            .immediate_result => |result| return .{
                .args = result.args,
                .body = result.body,
                .ret = result.ret,
            },
            .materialized => child_body.?,
            .child => |child| if (child.return_boundary)
                try self.addExprWithTypeCell(body_ret_cell, .{ .return_ = .{ .value = child_body.?, .target = body_ret_cell } })
            else
                child_body.?,
        };
        if (lowering.arg_literal_guards.items.len != 0) {
            const guarded_cell = self.exprTypeCell(body);
            const miss = try self.addExprWithTypeCell(
                guarded_cell,
                .{ .crash = try self.addStringLiteral("pattern match failed") },
            );
            body = try self.applyPatternLiteralGuardsAtCell(
                lowering.arg_literal_guards.items,
                body,
                miss,
                guarded_cell,
            );
        }
        const body_loc = self.exprLoc(body);
        const body_region_after_lowering = self.exprRegion(body);
        const saved_body_loc = self.builder.current_loc;
        defer self.builder.current_loc = saved_body_loc;
        const saved_body_region = self.builder.current_region;
        defer self.builder.current_region = saved_body_region;
        self.builder.current_loc = body_loc;
        self.builder.current_region = body_region_after_lowering;
        var remaining = lowering.arg_lets.items.len;
        while (remaining > 0) {
            remaining -= 1;
            const arg_let = lowering.arg_lets.items[remaining];
            body = try self.addExprWithTypeCell(self.exprTypeCell(body), .{ .let_ = .{
                .bind = arg_let.pat,
                .value = arg_let.value,
                .rest = body,
            } });
        }

        const declared_ret_node = lowering.declared_ret_node;
        const ret_cell = lowering.ret_cell;
        const body_ret_node = try self.exprTypeCell(body).toGraphNode(self.graph);
        const produced_ret_cell = if (self.graph.sameClass(declared_ret_node, body_ret_node))
            ret_cell
        else if (try self.resultCompletesRequest(declared_ret_node, body_ret_node) or
            try self.graph.containsGeneratedPrivate(body_ret_node))
            DraftTypeCell.fromGraphNode(body_ret_node)
        else blk: {
            try relateRequestComponent(self.graph, declared_ret_node, body_ret_node);
            break :blk ret_cell;
        };
        self.draft.exprs.items[@backingInt(body)].ty = produced_ret_cell;

        return .{
            .args = try self.draft.addTypedLocalSpan(lowering.args),
            .body = body,
            .ret = produced_ret_cell,
        };
    }

    /// Restore every piece of context state a lambda's lowering moved,
    /// innermost first.
    fn restoreLambdaLowering(self: *BodyContext, lowering: *LambdaLowering) void {
        if (lowering.restored) return;
        lowering.restored = true;
        self.freeLambdaLoweringArgs(lowering);
        lowering.exhaustiveness_scope.leave();
        self.builder.current_region = lowering.saved_region;
        self.builder.current_loc = lowering.saved_loc;
        self.current_return_target = lowering.saved_return_target;
        self.propagate_constructor_value_evidence = lowering.saved_propagation;
        if (lowering.saved_binders) |*saved| {
            self.restoreBinders(saved.items);
            saved.deinit(self.allocator);
            lowering.saved_binders = null;
        }
        if (lowering.nested_entry_guards) |guards| {
            self.function_entry_demand_guards = guards;
            lowering.nested_entry_guards = null;
        }
    }

    /// An evidence computation run by the lowering loop: each nested lambda
    /// or closure it drafts lowers its body as a child task, so an argument
    /// lambda's body never nests a lowering run inside its call's evidence.
    const HostedEvidenceTask = struct {
        root: EvidenceTask,
        started: bool = false,
        frames: std.ArrayList(EvidenceFrame) = .empty,
    };

    fn hostedEvidenceTask(self: *BodyContext, root: EvidenceTask) Allocator.Error!LowerTask {
        return .{ .hosted_evidence = try self.boxLowerTask(HostedEvidenceTask, .{ .root = root }) };
    }

    fn stepHostedEvidence(self: *BodyContext, task: *HostedEvidenceTask) Allocator.Error!LowerStep {
        if (!task.started) {
            task.started = true;
            try task.frames.append(self.allocator, .{ .ctx = self, .task = task.root });
        }
        return switch (try self.driveEvidence(&task.frames)) {
            .done => |result| .{ .ret = .{ .evidence = result } },
            .draft_nested => |request| requestLowerTask(request.ctx, .{ .nested_fn = try request.ctx.boxLowerTask(NestedFnTask, .{
                .expr_id = request.expr,
                .request_fn_node = request.request_fn_node,
                .purpose = .draft,
            }) }),
        };
    }

    /// Lambda and closure operands, each drafted at its slot as a child task
    /// in order. Then the frame becomes `then`, whose result is this task's
    /// result, or with no `then` it answers nothing.
    const DraftCallablesTask = struct {
        /// Owned.
        drafts: []DraftNestedCallable,
        index: usize = 0,
        then: ?union(enum) {
            prepared_operands: PreparedOperandsTask,
            uninhabited_dispatch: UninhabitedArgumentTask,
        } = null,
    };

    /// Draft the listed callables, then run `then`. Takes ownership of
    /// `drafts`.
    fn draftCallablesThen(self: *BodyContext, drafts: []DraftNestedCallable, then: @FieldType(DraftCallablesTask, "then")) LowerStep {
        if (drafts.len == 0) {
            self.allocator.free(drafts);
            if (then) |task| return requestLowerTask(self, switch (task) {
                .prepared_operands => |prepared| .{ .prepared_operands = prepared },
                .uninhabited_dispatch => |uninhabited| .{ .uninhabited_dispatch = uninhabited },
            });
        }
        return requestLowerTask(self, .{ .draft_callables = .{ .drafts = drafts, .then = then } });
    }

    fn stepDraftCallables(self: *BodyContext, frame: *LowerFrame, task: *DraftCallablesTask) Allocator.Error!LowerStep {
        if (task.index < task.drafts.len) {
            const draft = task.drafts[task.index];
            task.index += 1;
            return requestLowerTask(draft.ctx, .{ .nested_fn = try draft.ctx.boxLowerTask(NestedFnTask, .{
                .expr_id = draft.expr,
                .request_fn_node = draft.request_fn_node,
                .purpose = .draft,
            }) });
        }
        const then = task.then;
        self.allocator.free(task.drafts);
        task.drafts = &.{};
        const next = then orelse return .{ .ret = .{ .evidence = .none } };
        frame.cursor = 0;
        frame.task = switch (next) {
            .prepared_operands => |prepared| .{ .prepared_operands = prepared },
            .uninhabited_dispatch => |uninhabited| .{ .uninhabited_dispatch = uninhabited },
        };
        return try self.stepLower(frame, null);
    }

    /// A lambda or closure whose nested function body lowers as a child task,
    /// so nested functions never nest native lowering calls.
    const NestedFnTask = struct {
        expr_id: checked.CheckedExprId,
        request_fn_node: NodeId,
        closure: ?@FieldType(checked.CheckedExprData, "closure") = null,
        /// A value lowers the function expression; a draft only makes its
        /// specialization exist at the request node.
        purpose: enum { value, draft } = .value,
        stage: enum { start, body } = .start,
        capture_span: DraftSpan(DraftFnDefCapture) = undefined,
        draft: ?DraftNestedLowering = null,
        lambda: ?LambdaLowering = null,
    };

    fn releaseNestedFnTask(self: *BodyContext, task: *NestedFnTask) void {
        if (task.lambda) |*lambda| {
            task.draft.?.nested_ctx.restoreLambdaLowering(lambda);
            task.lambda = null;
        }
        if (task.draft) |*draft| {
            self.builder.releaseDraftNested(draft);
            task.draft = null;
        }
    }

    fn stepNestedFn(self: *BodyContext, task: *NestedFnTask, input: ?LowerResult) Allocator.Error!LowerStep {
        const child_body: ?DraftExprId = switch (task.stage) {
            .start => blk: {
                const expr_id = task.expr_id;
                const request_fn_node = task.request_fn_node;
                var capture_nodes: []NodeId = &.{};
                const source_fn_ty = switch (task.purpose) {
                    .draft => switch (self.view.bodies.expr(expr_id).data) {
                        .lambda => ty: {
                            self.builder.countBodyDiagnostic("nested_lambdas_prepared");
                            break :ty self.view.bodies.expr(expr_id).ty;
                        },
                        .closure => |closure| ty: {
                            self.builder.countBodyDiagnostic("nested_closures_prepared");
                            capture_nodes = try self.closureCaptureEntryNodes(closure);
                            const lambda = self.view.bodies.expr(closure.lambda);
                            if (lambda.data != .lambda) Common.invariant("checked closure did not point at a lambda expression");
                            break :ty lambda.ty;
                        },
                        .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("nested callable draft named a non-callable expression"),
                    },
                    .value => if (task.closure) |closure| ty: {
                        task.capture_span = try self.lowerClosureCaptureExprSpan(closure.captures);
                        capture_nodes = try self.graph.arena().alloc(NodeId, task.capture_span.len);
                        for (self.fnDefCaptureSpan(task.capture_span), capture_nodes) |capture, *node| {
                            node.* = try self.exprTypeCell(capture.value).toGraphNode(self.graph);
                        }
                        const lambda = self.view.bodies.expr(closure.lambda);
                        if (lambda.data != .lambda) Common.invariant("checked closure did not point at a lambda expression");
                        break :ty lambda.ty;
                    } else self.view.bodies.expr(expr_id).ty,
                };
                const nested = try self.builder.nestedFnForExpr(
                    self.view,
                    self.owner_template,
                    expr_id,
                    self.current_fn_key,
                    try self.localProcContextsDigest(),
                    self.in_default_expr,
                );
                const nested_evidence = try self.evidenceForNestedSiteAtNode(nested, expr_id, request_fn_node);
                switch (try self.builder.beginDraftNested(
                    self,
                    self.draft.current_owner,
                    expr_id,
                    nested,
                    source_fn_ty,
                    self.view.types.rootKey(source_fn_ty),
                    request_fn_node,
                    capture_nodes,
                    nested_evidence.chain,
                    nested_evidence.owned_scope,
                    false,
                    .exact_graph,
                    .inherit,
                )) {
                    .hit => |target| return self.finishNestedFnValue(task, target),
                    .lowering => |lowering| task.draft = lowering,
                }
                const draft = &task.draft.?;
                task.lambda = try draft.nested_ctx.beginNestedLambdaLowering(expr_id, draft.request_fn_node, draft.capture_entry_guards);
                switch (task.lambda.?.body) {
                    .immediate_result => break :blk null,
                    .materialized => |request| {
                        task.stage = .body;
                        return requestLowerTask(draft.nested_ctx, .{ .materialize = .{ .root = request } });
                    },
                    .child => |child| {
                        task.stage = .body;
                        return requestLowerChild(draft.nested_ctx, task.lambda.?.checked_body, child.cell);
                    },
                }
            },
            .body => input.?.exprValue(),
        };
        const draft = &task.draft.?;
        const lowered = try draft.nested_ctx.finishLambdaLowering(&task.lambda.?, child_body);
        draft.nested_ctx.restoreLambdaLowering(&task.lambda.?);
        task.lambda = null;
        const target = try self.builder.finishDraftNested(self, draft, lowered);
        self.builder.releaseDraftNested(draft);
        task.draft = null;
        return self.finishNestedFnValue(task, target);
    }

    fn finishNestedFnValue(self: *BodyContext, task: *NestedFnTask, fn_id: DraftFnTarget) Allocator.Error!LowerStep {
        switch (task.purpose) {
            .value => {},
            .draft => return .{ .ret = .{ .evidence = .none } },
        }
        const fn_node = try self.draftFnSlotTypeNode(.{ .local = fn_id }, task.request_fn_node);
        return loweredExprStep(try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(fn_node),
            .{ .fn_def = if (task.closure != null) .{
                .fn_id = fn_id,
                .captures = task.capture_span,
            } else .{ .fn_id = fn_id } },
        ));
    }

    // Expression evidence //
    //
    // An expression's type node, call-result evidence, produced-value
    // evidence, and request relations each depend on the same evidence of its
    // operands. They are evaluated by one explicit kernel: every computation
    // that needs an operand's evidence suspends as an `EvidenceFrame` on a
    // heap-backed stack and resumes with the operand's result, so expression
    // nesting depth never becomes native call depth. Each frame runs on the
    // exact body context the direct computation used, and every graph relation
    // happens in the same order.

    const CheckedCall = @FieldType(checked.CheckedExprData, "call");
    const CheckedFieldAccess = @FieldType(checked.CheckedExprData, "field_access");

    const EvidenceResult = union(enum) {
        none,
        node: NodeId,
        maybe_node: ?NodeId,

        fn nodeValue(self: EvidenceResult) NodeId {
            return switch (self) {
                .node => |node| node,
                .none, .maybe_node => unreachable,
            };
        }

        fn maybeNodeValue(self: EvidenceResult) ?NodeId {
            return switch (self) {
                .maybe_node, .node => |node| node,
                .none => unreachable,
            };
        }
    };

    const EvidenceTask = union(enum) {
        /// `lowerExprTypeNode`
        type_node: struct { expr: checked.CheckedExprId, timing: BodyWorkTimingScope = .{} },
        /// `exprCallResultEvidenceNode`
        call_evidence: struct { expr: checked.CheckedExprId, expected_ty: ?Type.TypeId },
        /// `exprCallArgumentEvidenceNode`
        argument_evidence: struct { expr: checked.CheckedExprId, argument_node: NodeId = undefined },
        /// `exprProducedValueEvidenceNode`
        produced_value: ProducedValueTask,
        /// `dispatchResultTypeNodeInPhase`, including its callable relation.
        dispatch_result: DispatchResultTask,
        /// `callableDispatchResultTypeNodeInPhase`
        callable_dispatch_result: DispatchResultTask,
        /// An interpolation's value: the result of the assembler its
        /// conversion's dispatch returns.
        interpolation_result: InterpolationResultTask,
        /// `callResultTypeNode`
        call_result: CallResultTask,
        /// `directCallRequestNode`
        direct_call_request: DirectCallTask,
        /// `directCallTypeNode`
        direct_call_type: DirectCallTask,
        /// `instantiateCallNodeFromCallerAtNode`, run on the callee context.
        instantiate_call: InstantiateCallTask,
        /// `instantiateCallableDispatchPlanCallNodeFromCallerAtNode`, run on the callee context.
        instantiate_dispatch: InstantiateDispatchTask,
        /// `fieldAccessTypeNode`
        field_access: struct { checked_ty: checked.CheckedTypeId, access: CheckedFieldAccess, expected_ty: ?Type.TypeId },
        /// `tupleAccessTypeNode`
        tuple_access: struct { checked_ty: checked.CheckedTypeId, tuple: checked.CheckedExprId, elem_index: usize, expected_ty: ?Type.TypeId },
        /// `directCallCompletedResultNode`
        completed_result: CompletedResultTask,
        /// A direct call's arguments related to its request node.
        prepare_direct_args: PrepareArgsTask,
        /// Expressions related to their request nodes.
        prepare_span: PrepareArgsTask,
        /// `relateExprAtNode`
        relate: RelateTask,
    };

    const ProducedValueTask = struct {
        expr: checked.CheckedExprId,
        request_node: NodeId,
        index: usize = 0,
        requires_distinct_witness: bool = false,
        /// Child nodes, or record fields, being filled for a constructor.
        child_nodes: []const NodeId = &.{},
        produced_nodes: []NodeId = &.{},
        produced_fields: []InstField = &.{},
        /// A record constructor's supplied values and unset labels.
        record_labels: ?RecordExprLabels = null,
        base_node: ?NodeId = null,
        /// The base's fields, indexed on the first field the update leaves
        /// to it.
        base_construction: ?ConstructionFields = null,
        produced_element: ?NodeId = null,
        current_child_node: NodeId = undefined,
        name: names.TagNameId = undefined,
    };

    const DispatchResultTask = struct {
        checked_ret_ty: checked.CheckedTypeId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        callable_plan: CallableDispatchPlan = undefined,
        expected_ret_node: ?NodeId,
        phase: DispatchInstantiationPhase,
        call_ctx: ?*BodyContext = null,
    };

    const InterpolationResultTask = struct {
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        expected_ret_node: ?NodeId,
    };

    const CallResultTask = struct {
        expr: checked.CheckedExprId,
        checked_ret_ty: checked.CheckedTypeId,
        call: CheckedCall,
        expected_ret_ty: ?Type.TypeId,
        call_ctx: ?*BodyContext = null,
        source_fn_ty: checked.CheckedTypeId = undefined,
    };

    const DirectCallTask = struct {
        expr: checked.CheckedExprId,
        target: checked.ResolvedValueId,
        call: CheckedCall,
        checked_ret_ty: checked.CheckedTypeId,
        source_fn_ty: checked.CheckedTypeId,
        expected_ret_node: ?NodeId,
        call_ctx: ?*BodyContext = null,
    };

    const InstantiateCallTask = struct {
        source_fn_ty: checked.CheckedTypeId,
        caller: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        checked_args: []const checked.CheckedExprId,
        expected_ret_node: ?NodeId,
        hosted_try_capability: ?HostedTryAdapterCapability,
        capture_constructor_argument_evidence: bool,
        /// The callee is a value of the caller's: an indirect call.
        callee_value: bool = false,
        fn_node: NodeId = undefined,
        formal_nodes: []const NodeId = &.{},
        ret_node: NodeId = undefined,
        request_args: []NodeId = &.{},
        index: usize = 0,
    };

    const InstantiateDispatchTask = struct {
        callable_plan: CallableDispatchPlan,
        caller: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        expected_ret_node: ?NodeId,
        phase: DispatchInstantiationPhase,
        fn_node: NodeId = undefined,
        formal_nodes: []const NodeId = &.{},
        ret_node: NodeId = undefined,
        request_args: []NodeId = &.{},
        index: usize = 0,
    };

    const CompletedResultTask = struct {
        expr: checked.CheckedExprId,
        target: checked.ResolvedValueId,
        call: CheckedCall,
        source_fn_ty: checked.CheckedTypeId,
        fn_node: NodeId,
    };

    const PrepareArgsTask = struct {
        expr: checked.CheckedExprId = undefined,
        fn_node: NodeId = undefined,
        checked_exprs: []const checked.CheckedExprId,
        nodes: []const NodeId,
        index: usize = 0,
    };

    const RelateTask = struct {
        expr: checked.CheckedExprId,
        expected_node: NodeId,
        timing: BodyWorkTimingScope = .{},
        index: usize = 0,
        /// Per-child nodes for a constructor or call argument span.
        child_nodes: []const NodeId = &.{},
        fn_node: NodeId = undefined,
        call_ctx: ?*BodyContext = null,
        name: names.TagNameId = undefined,
        /// A record constructor's runtime fields by name.
        construction: ?ConstructionFields = null,
    };

    const EvidenceFrame = struct {
        ctx: *BodyContext,
        cursor: u8 = 0,
        task: EvidenceTask,
    };

    const EvidenceStep = union(enum) {
        call: struct { ctx: *BodyContext, task: EvidenceTask },
        ret: EvidenceResult,
        /// Draft a nested lambda or closure at its request node; the frame
        /// resumes once it is drafted.
        draft_nested: DraftNestedCallable,
    };

    /// A lambda or closure argument drafted at its request node before the
    /// evidence that needs it continues.
    const DraftNestedCallable = struct {
        ctx: *BodyContext,
        expr: checked.CheckedExprId,
        request_fn_node: NodeId,
    };

    const EvidenceProgress = union(enum) {
        done: EvidenceResult,
        draft_nested: DraftNestedCallable,
    };

    fn evidenceCall(ctx: *BodyContext, task: EvidenceTask) EvidenceStep {
        return .{ .call = .{ .ctx = ctx, .task = task } };
    }

    /// Run an evidence computation to completion on an explicit frame stack,
    /// drafting each nested callable it needs in place.
    fn runEvidence(self: *BodyContext, root: EvidenceTask) Allocator.Error!EvidenceResult {
        var frames: std.ArrayList(EvidenceFrame) = .empty;
        defer frames.deinit(self.allocator);
        errdefer releaseEvidenceFrames(&frames);
        try frames.append(self.allocator, .{ .ctx = self, .task = root });
        while (true) switch (try self.driveEvidence(&frames)) {
            .done => |result| return result,
            .draft_nested => |request| try request.ctx.ensureNestedCallableAtNode(request.expr, request.request_fn_node),
        };
    }

    /// Step an evidence computation until it finishes or asks for a nested
    /// callable to be drafted. The frame that asked resumes on the next call.
    fn driveEvidence(self: *BodyContext, frames: *std.ArrayList(EvidenceFrame)) Allocator.Error!EvidenceProgress {
        var input: ?EvidenceResult = null;
        while (true) {
            const frame = &frames.items[frames.items.len - 1];
            const step = try frame.ctx.stepEvidence(frame, input);
            switch (step) {
                .call => {
                    const next = frames.addOne(self.allocator) catch |err| {
                        var unstarted: EvidenceFrame = .{ .ctx = step.call.ctx, .task = step.call.task };
                        unstarted.ctx.releaseEvidenceFrame(&unstarted);
                        return err;
                    };
                    next.* = .{ .ctx = step.call.ctx, .task = step.call.task };
                    input = null;
                },
                .ret => {
                    const finished = &frames.items[frames.items.len - 1];
                    finished.ctx.releaseEvidenceFrame(finished);
                    frames.items.len -= 1;
                    if (frames.items.len == 0) return .{ .done = step.ret };
                    input = step.ret;
                },
                .draft_nested => return .{ .draft_nested = step.draft_nested },
            }
        }
    }

    fn releaseEvidenceFrames(frames: *std.ArrayList(EvidenceFrame)) void {
        while (frames.pop()) |frame| {
            var owned = frame;
            owned.ctx.releaseEvidenceFrame(&owned);
        }
    }

    /// Release what a frame still owns: its timing scope, its callee context,
    /// and its scratch spans. Idempotent, so a frame that already released
    /// them on its normal path is unaffected.
    fn releaseEvidenceFrame(self: *BodyContext, frame: *EvidenceFrame) void {
        switch (frame.task) {
            .type_node => |*task| task.timing.end(),
            .relate => |*task| {
                if (task.call_ctx) |call_ctx| self.destroyCallContext(call_ctx);
                task.call_ctx = null;
                if (task.construction) |*construction| construction.deinit(self.allocator);
                task.construction = null;
                task.timing.end();
            },
            .dispatch_result, .callable_dispatch_result => |*task| {
                if (task.call_ctx) |call_ctx| self.destroyCallContext(call_ctx);
                task.call_ctx = null;
            },
            .call_result => |*task| {
                if (task.call_ctx) |call_ctx| self.destroyCallContext(call_ctx);
                task.call_ctx = null;
            },
            .direct_call_type, .direct_call_request => |*task| {
                if (task.call_ctx) |call_ctx| self.destroyCallContext(call_ctx);
                task.call_ctx = null;
            },
            .produced_value => |*task| {
                self.allocator.free(task.produced_nodes);
                task.produced_nodes = &.{};
                self.allocator.free(task.produced_fields);
                task.produced_fields = &.{};
                if (task.record_labels) |*labels| labels.deinit(self.allocator);
                task.record_labels = null;
                if (task.base_construction) |*base_fields| base_fields.deinit(self.allocator);
                task.base_construction = null;
            },
            .call_evidence,
            .argument_evidence,
            .instantiate_call,
            .instantiate_dispatch,
            .field_access,
            .tuple_access,
            .completed_result,
            .prepare_direct_args,
            .prepare_span,
            .interpolation_result,
            => {},
        }
    }

    /// A context for instantiating a callee's checked type in the caller's
    /// graph, owned by the computation that creates it.
    fn createCallContext(self: *BodyContext) Allocator.Error!*BodyContext {
        const call_ctx = try self.allocator.create(BodyContext);
        errdefer self.allocator.destroy(call_ctx);
        call_ctx.* = try BodyContext.initWithMethodScope(self.allocator, self.builder, self.view, self.method_scope, self.owner_template, self.graph, self.draft);
        call_ctx.evidence = self.evidence;
        call_ctx.owner_context_fn_key = self.owner_context_fn_key;
        call_ctx.current_fn_key = self.current_fn_key;
        call_ctx.source_region_override = self.source_region_override;
        call_ctx.current_entry_root = self.current_entry_root;
        call_ctx.in_deferred_body = self.in_deferred_body;
        return call_ctx;
    }

    fn destroyCallContext(self: *BodyContext, call_ctx: *BodyContext) void {
        call_ctx.deinit();
        self.allocator.destroy(call_ctx);
    }

    fn stepEvidence(self: *BodyContext, frame: *EvidenceFrame, input: ?EvidenceResult) Allocator.Error!EvidenceStep {
        switch (frame.task) {
            .type_node => |*task| return self.stepTypeNode(frame, task, input),
            .call_evidence => |*task| return self.stepCallEvidence(frame, task.expr, task.expected_ty, input),
            .argument_evidence => |*task| return self.stepArgumentEvidence(frame, task, input),
            .produced_value => |*task| return self.stepProducedValue(frame, task, input),
            .dispatch_result => |*task| return self.stepDispatchResult(frame, task, input, true),
            .callable_dispatch_result => |*task| return self.stepDispatchResult(frame, task, input, false),
            .interpolation_result => |*task| return self.stepInterpolationResult(frame, task, input),
            .call_result => |*task| return self.stepCallResult(frame, task, input),
            .direct_call_request => |*task| return self.stepDirectCallRequest(frame, task, input),
            .direct_call_type => |*task| return self.stepDirectCallType(frame, task, input),
            .instantiate_call => |*task| return self.stepInstantiateCall(frame, task, input),
            .instantiate_dispatch => |*task| return self.stepInstantiateDispatch(frame, task, input),
            .field_access => |task| return self.stepFieldAccess(frame, task.checked_ty, task.access, task.expected_ty, input),
            .tuple_access => |task| return self.stepTupleAccess(frame, task.checked_ty, task.tuple, task.elem_index, task.expected_ty, input),
            .completed_result => |task| return self.stepCompletedResult(frame, task),
            .prepare_direct_args => |*task| return self.stepPrepareArgs(frame, task, true),
            .prepare_span => |*task| return self.stepPrepareArgs(frame, task, false),
            .relate => |*task| return self.stepRelate(frame, task, input),
        }
    }

    /// An expression's result type is read once per checked-type instantiation and
    /// shared by every later result-type read carrying no expected cell, as a
    /// direct call's request interface is. A result carrying generated-private
    /// evidence depends on the read and is never shared.
    fn sharedExprTypeRead(self: *BodyContext, expr_id: checked.CheckedExprId) Allocator.Error!?NodeId {
        const node = self.instantiation.expr_type_reads.get(expr_id) orelse return null;
        if (try self.graph.containsGeneratedPrivate(node)) return null;
        return node;
    }

    fn recordExprTypeRead(self: *BodyContext, expr_id: checked.CheckedExprId, node: NodeId) Allocator.Error!void {
        if (try self.graph.containsGeneratedPrivate(node)) return;
        try self.instantiation.expr_type_reads.put(expr_id, node);
    }

    fn isDispatchExpr(expr: checked.CheckedExpr) bool {
        return switch (expr.data) {
            .dispatch_call, .interpolation, .type_dispatch_call, .method_eq => true,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .structural_eq, .structural_hash, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => false,
        };
    }

    fn finishTypeNodeLeaf(self: *BodyContext, task: anytype, node: NodeId) Allocator.Error!EvidenceStep {
        try self.recordExprTypeRead(task.expr, node);
        task.timing.end();
        return .{ .ret = .{ .node = node } };
    }

    fn stepTypeNode(self: *BodyContext, frame: *EvidenceFrame, task: anytype, input: ?EvidenceResult) Allocator.Error!EvidenceStep {
        if (frame.cursor == 1) {
            try self.recordExprTypeRead(task.expr, input.?.nodeValue());
            task.timing.end();
            return .{ .ret = input.? };
        }
        task.timing = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        frame.cursor = 1;
        const expr_id = task.expr;
        const expr = self.view.bodies.expr(expr_id);
        if (try self.sharedExprTypeRead(expr_id)) |node| {
            task.timing.end();
            return .{ .ret = .{ .node = node } };
        }
        const next: EvidenceTask = switch (expr.data) {
            .call => |call| .{ .call_result = .{ .expr = expr_id, .checked_ret_ty = expr.ty, .call = call, .expected_ret_ty = null } },
            .dispatch_call => |plan| .{ .dispatch_result = .{ .checked_ret_ty = expr.ty, .maybe_plan = plan, .expected_ret_node = null, .phase = .expression_lowering } },
            .interpolation => |interpolation| .{ .interpolation_result = .{ .maybe_plan = interpolation.plan, .expected_ret_node = null } },
            .type_dispatch_call, .method_eq => |plan| .{ .dispatch_result = .{ .checked_ret_ty = expr.ty, .maybe_plan = plan, .expected_ret_node = null, .phase = .expression_lowering } },
            .field_access => |field| .{ .field_access = .{ .checked_ty = expr.ty, .access = field, .expected_ty = null } },
            .tuple_access => |access| .{ .tuple_access = .{ .checked_ty = expr.ty, .tuple = access.tuple, .elem_index = access.elem_index, .expected_ty = null } },
            .lookup_local => |lookup| return try self.finishTypeNodeLeaf(task, try self.lookupExprTypeNode(expr.ty, lookup.resolved)),
            .lookup_external, .lookup_required => |resolved| return try self.finishTypeNodeLeaf(task, try self.lookupExprTypeNode(expr.ty, resolved)),
            .lambda => |lambda| return try self.finishTypeNodeLeaf(task, try self.lambdaFunctionNode(expr.ty, lambda)),
            .closure => |closure| return try self.finishTypeNodeLeaf(task, try self.closureFunctionNode(closure)),
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .list, .empty_list, .tuple, .match_, .if_, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .structural_eq, .structural_hash, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => return try self.finishTypeNodeLeaf(task, try self.lowerTypeNode(expr.ty)),
        };
        return evidenceCall(self, next);
    }

    fn stepCallEvidence(
        self: *BodyContext,
        frame: *EvidenceFrame,
        checked_arg: checked.CheckedExprId,
        expected_ty: ?Type.TypeId,
        input: ?EvidenceResult,
    ) Allocator.Error!EvidenceStep {
        const expr = self.view.bodies.expr(checked_arg);
        switch (frame.cursor) {
            0 => {},
            // A direct call's shared request interface.
            1 => {
                const call = expr.data.call;
                const target = call.direct_target.?;
                const fn_node = input.?.nodeValue();
                const fn_nodes = try self.graph.functionNodes(fn_node);
                if (try self.graph.containsGeneratedPrivate(fn_nodes.ret)) return .{ .ret = .{ .maybe_node = fn_nodes.ret } };
                frame.cursor = 2;
                return evidenceCall(self, .{ .completed_result = .{
                    .expr = checked_arg,
                    .target = target,
                    .call = call,
                    .source_fn_ty = self.directCallInstantiationSourceFnType(target, call.source_fn_ty_payload),
                    .fn_node = fn_node,
                } });
            },
            // A shared null-expected dispatch result read.
            4 => {
                const node = input.?.nodeValue();
                try self.recordExprTypeRead(checked_arg, node);
                return .{ .ret = .{ .maybe_node = node } };
            },
            else => return .{ .ret = .{ .maybe_node = input.?.maybeNodeValue() } },
        }
        if (self.checkedExprDivergesInLoweredRuntime(checked_arg)) return .{ .ret = .{ .maybe_node = null } };
        if (expected_ty == null and isDispatchExpr(expr)) {
            if (try self.sharedExprTypeRead(checked_arg)) |node| return .{ .ret = .{ .maybe_node = node } };
        }
        const expected_node: ?NodeId = if (expected_ty) |expected| try self.activeNodeFromType(expected) else null;
        switch (expr.data) {
            .call => |call| {
                if (call.direct_target) |target| {
                    frame.cursor = 1;
                    return evidenceCall(self, .{ .direct_call_request = .{
                        .expr = checked_arg,
                        .target = target,
                        .call = call,
                        .checked_ret_ty = expr.ty,
                        .source_fn_ty = self.directCallInstantiationSourceFnType(target, call.source_fn_ty_payload),
                        .expected_ret_node = expected_node,
                    } });
                }
                frame.cursor = 2;
                return evidenceCall(self, .{ .call_result = .{ .expr = checked_arg, .checked_ret_ty = expr.ty, .call = call, .expected_ret_ty = expected_ty } });
            },
            .dispatch_call => |plan| {
                frame.cursor = if (expected_ty == null) 4 else 2;
                return evidenceCall(self, .{ .dispatch_result = .{ .checked_ret_ty = expr.ty, .maybe_plan = plan, .expected_ret_node = expected_node, .phase = .expression_lowering } });
            },
            .interpolation => |interpolation| {
                frame.cursor = if (expected_ty == null) 4 else 2;
                return evidenceCall(self, .{ .interpolation_result = .{ .maybe_plan = interpolation.plan, .expected_ret_node = expected_node } });
            },
            .type_dispatch_call => |plan| {
                frame.cursor = if (expected_ty == null) 4 else 2;
                return evidenceCall(self, .{ .dispatch_result = .{ .checked_ret_ty = expr.ty, .maybe_plan = plan, .expected_ret_node = expected_node, .phase = .expression_lowering } });
            },
            .method_eq => |plan| {
                frame.cursor = if (expected_ty == null) 4 else 2;
                return evidenceCall(self, .{ .dispatch_result = .{ .checked_ret_ty = expr.ty, .maybe_plan = plan, .expected_ret_node = expected_node, .phase = .expression_lowering } });
            },
            .field_access => |field| {
                frame.cursor = 2;
                return evidenceCall(self, .{ .field_access = .{ .checked_ty = expr.ty, .access = field, .expected_ty = expected_ty } });
            },
            .tuple_access => |access| {
                frame.cursor = 2;
                return evidenceCall(self, .{ .tuple_access = .{ .checked_ty = expr.ty, .tuple = access.tuple, .elem_index = access.elem_index, .expected_ty = expected_ty } });
            },
            .lookup_local => |lookup| return .{ .ret = .{ .maybe_node = try self.lookupCallArgumentEvidenceNode(expr.ty, lookup.resolved, expected_ty) } },
            .lookup_external, .lookup_required => |resolved| return .{ .ret = .{ .maybe_node = try self.lookupCallArgumentEvidenceNode(expr.ty, resolved, expected_ty) } },
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .list, .empty_list, .tuple, .match_, .if_, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .structural_eq, .structural_hash, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
        }
        if (expected_ty) |ty| {
            try self.constrainTypeToMono(expr.ty, ty);
            return .{ .ret = .{ .maybe_node = try self.activeNodeFromType(ty) } };
        }
        return .{ .ret = .{ .maybe_node = null } };
    }

    fn stepArgumentEvidence(self: *BodyContext, frame: *EvidenceFrame, task: anytype, input: ?EvidenceResult) Allocator.Error!EvidenceStep {
        switch (frame.cursor) {
            0 => {
                frame.cursor = 1;
                return evidenceCall(self, .{ .call_evidence = .{ .expr = task.expr, .expected_ty = null } });
            },
            1 => {
                if (input.?.maybeNodeValue()) |produced| {
                    return .{ .ret = .{ .maybe_node = if (try self.graph.containsGeneratedPrivate(produced)) produced else null } };
                }
                const expr = self.view.bodies.expr(task.expr);
                switch (expr.data) {
                    .tuple, .record, .tag, .nominal, .list => {},
                    .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .empty_list, .match_, .if_, .empty_record, .block, .zero_argument_tag, .call, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => return .{ .ret = .{ .maybe_node = null } },
                }
                task.argument_node = try self.freshInstNode(expr.ty);
                frame.cursor = 2;
                return evidenceCall(self, .{ .produced_value = .{ .expr = task.expr, .request_node = task.argument_node } });
            },
            else => {
                const produced = input.?.maybeNodeValue() orelse return .{ .ret = .{ .maybe_node = null } };
                return .{ .ret = .{ .maybe_node = if (try self.graph.containsGeneratedPrivate(produced)) produced else null } };
            },
        }
    }

    /// Produced-value evidence: a direct producer or lookup supplies its own
    /// evidence; a constructor propagates each child's evidence into its exact
    /// positional slot and creates a distinct container witness when needed.
    fn stepProducedValue(self: *BodyContext, frame: *EvidenceFrame, task: *ProducedValueTask, input: ?EvidenceResult) Allocator.Error!EvidenceStep {
        const request_node = task.request_node;
        const expr = self.view.bodies.expr(task.expr);
        switch (frame.cursor) {
            0 => {
                frame.cursor = 1;
                return evidenceCall(self, .{ .call_evidence = .{ .expr = task.expr, .expected_ty = null } });
            },
            1 => {
                if (input.?.maybeNodeValue()) |produced| {
                    return .{ .ret = .{ .maybe_node = try self.relateCheckedNodeToProducedValue(request_node, produced) } };
                }
                frame.cursor = 2;
                switch (expr.data) {
                    .tuple => |items| {
                        const item_nodes = try self.graph.tupleItemNodes(request_node);
                        if (items.len != item_nodes.len) Common.invariant("tuple value evidence arity differed from its graph type");
                        task.child_nodes = item_nodes;
                        task.produced_nodes = try self.allocator.alloc(NodeId, items.len);
                    },
                    .tag => |tag| {
                        task.name = try self.tagName(self.view, tag.name);
                        task.produced_nodes = try self.allocator.alloc(NodeId, tag.args.len);
                    },
                    .record => |record| {
                        task.record_labels = try self.recordExprLabels(record);
                        const target_fields = (try self.graph.recordConstructionNodes(request_node)).fields;
                        task.produced_fields = try self.allocator.dupe(InstField, target_fields);
                        if (record.ext) |base_expr| {
                            // The base evidence is requested before any field.
                            frame.cursor = 3;
                            return evidenceCall(self, .{ .produced_value = .{
                                .expr = base_expr,
                                .request_node = try self.freshInstNode(self.view.bodies.expr(base_expr).ty),
                            } });
                        }
                    },
                    .list => task.current_child_node = try self.graph.listElementNode(request_node),
                    .nominal => |nominal| {
                        const representation_node = (try self.constructorRepresentationNode(request_node));
                        const named = switch ((try self.graph.content(representation_node))) {
                            .named => |value| value,
                            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => Common.invariant("nominal value evidence had no nominal graph representation"),
                        };
                        const backing = named.backing orelse
                            Common.invariant("nominal value evidence graph node had no backing");
                        task.current_child_node = backing.node;
                        return evidenceCall(self, .{ .produced_value = .{ .expr = nominal.backing_expr, .request_node = backing.node } });
                    },
                    .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .empty_list, .match_, .if_, .empty_record, .block, .zero_argument_tag, .call, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => return .{ .ret = .{ .maybe_node = null } },
                }
                return try self.nextProducedValueChild(task, expr);
            },
            // A record update's base evidence.
            3 => {
                task.base_node = input.?.maybeNodeValue();
                frame.cursor = 2;
                return try self.nextProducedValueChild(task, expr);
            },
            else => {
                // A child's produced evidence.
                const child_node = task.current_child_node;
                const produced = input.?.maybeNodeValue() orelse child_node;
                switch (expr.data) {
                    .tuple => {
                        const witness = try self.constructorChildWitness(
                            child_node,
                            produced,
                            "tuple value evidence child differed without explicit representation evidence",
                        );
                        task.produced_nodes[task.index] = witness.slot;
                        if (witness.requires_witness) task.requires_distinct_witness = true;
                    },
                    .tag => {
                        const witness = try self.constructorChildWitness(
                            child_node,
                            produced,
                            "tag value evidence child differed without explicit representation evidence",
                        );
                        task.produced_nodes[task.index] = witness.slot;
                        if (witness.requires_witness) task.requires_distinct_witness = true;
                    },
                    .record => {
                        const field = task.produced_fields[task.index];
                        const produced_value = input.?.maybeNodeValue() orelse task.current_child_node;
                        const produced_slot = switch (try self.graph.recordConstructionFieldKindOf(field)) {
                            .required, .defaulted => produced_value,
                            .optional => optional: {
                                const present = try self.nameStoreMut().internTagLabel(Builder.optional_slot_present_tag);
                                const present_node = try self.graph.tagValueNodeWithPayloads(field.ty, present, &.{produced_value});
                                break :optional try self.constructorWitnessWithStructuralNode(field.ty, present_node);
                            },
                        };
                        const witness = try self.constructorChildWitness(
                            field.ty,
                            produced_slot,
                            "record value evidence child differed without explicit representation evidence",
                        );
                        task.produced_fields[task.index].ty = witness.slot;
                        if (witness.requires_witness) task.requires_distinct_witness = true;
                    },
                    .list => {
                        if (task.produced_element) |selected| {
                            try selectRequestRepresentation(self.graph, selected, produced);
                        } else {
                            const witness = try self.constructorChildWitness(
                                child_node,
                                produced,
                                "list value evidence child differed without explicit representation evidence",
                            );
                            if (witness.requires_witness) task.produced_element = witness.slot;
                        }
                    },
                    .nominal => {
                        const produced_backing = input.?.maybeNodeValue() orelse return .{ .ret = .{ .maybe_node = null } };
                        const representation_node = (try self.constructorRepresentationNode(request_node));
                        const backing_witness = try self.constructorChildWitness(
                            child_node,
                            produced_backing,
                            "nominal value evidence child differed without explicit representation evidence",
                        );
                        if (!backing_witness.requires_witness) return .{ .ret = .{ .maybe_node = null } };
                        const witness = try self.graph.namedValueNodeWithBacking(representation_node, backing_witness.slot);
                        return .{ .ret = .{ .maybe_node = try self.relateCheckedNodeToProducedValue(representation_node, witness) } };
                    },
                    .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .empty_list, .match_, .if_, .empty_record, .block, .zero_argument_tag, .call, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => unreachable,
                }
                task.index += 1;
                return try self.nextProducedValueChild(task, expr);
            },
        }
    }

    /// Request the next constructor child's produced evidence, or finish the
    /// constructor's witness once every child has contributed.
    fn nextProducedValueChild(self: *BodyContext, task: *ProducedValueTask, expr: checked.CheckedExpr) Allocator.Error!EvidenceStep {
        const request_node = task.request_node;
        switch (expr.data) {
            .tuple => |items| {
                if (task.index < items.len) {
                    task.current_child_node = task.child_nodes[task.index];
                    return evidenceCall(self, .{ .produced_value = .{ .expr = items[task.index], .request_node = task.current_child_node } });
                }
                if (!task.requires_distinct_witness) return .{ .ret = .{ .maybe_node = null } };
                const structural_node = try self.graph.newNode(.{
                    .tuple = try self.graph.arena().dupe(NodeId, task.produced_nodes),
                });
                const witness = try self.constructorWitnessWithStructuralNode(request_node, structural_node);
                return .{ .ret = .{ .maybe_node = try self.relateCheckedNodeToProducedValue(request_node, witness) } };
            },
            .tag => |tag| {
                if (task.index < tag.args.len) {
                    task.current_child_node = try self.graph.tagConstructionPayloadNode(request_node, task.name, task.index);
                    return evidenceCall(self, .{ .produced_value = .{ .expr = tag.args[task.index], .request_node = task.current_child_node } });
                }
                if (!task.requires_distinct_witness) return .{ .ret = .{ .maybe_node = null } };
                const structural_node = try self.graph.tagValueNodeWithPayloads(request_node, task.name, task.produced_nodes);
                const witness = try self.constructorWitnessWithStructuralNode(request_node, structural_node);
                return .{ .ret = .{ .maybe_node = try self.relateCheckedNodeToProducedValue(request_node, witness) } };
            },
            .record => {
                while (task.index < task.produced_fields.len) : (task.index += 1) {
                    const field = task.produced_fields[task.index];
                    const labels = &task.record_labels.?;
                    const field_value = labels.values.get(field.name) orelse {
                        const base_witness = task.base_node orelse continue;
                        if (labels.unsets.contains(field.name)) continue;
                        if (task.base_construction == null) task.base_construction = try self.constructionFields(base_witness);
                        const produced_slot = self.graph.rootNode(task.base_construction.?.get(field.name).ty);
                        const witness = try self.constructorChildWitness(
                            field.ty,
                            produced_slot,
                            "record update evidence field differed without explicit representation evidence",
                        );
                        task.produced_fields[task.index].ty = witness.slot;
                        if (witness.requires_witness) task.requires_distinct_witness = true;
                        continue;
                    };
                    task.current_child_node = self.graph.rootNode(field.value_ty orelse field.ty);
                    return evidenceCall(self, .{ .produced_value = .{ .expr = field_value, .request_node = task.current_child_node } });
                }
                if (!task.requires_distinct_witness) return .{ .ret = .{ .maybe_node = null } };
                const structural_node = try self.graph.newNode(.{ .record = .{
                    .fields = try self.graph.arena().dupe(InstField, task.produced_fields),
                    .ext = try self.graph.newNode(.empty_record),
                } });
                const witness = try self.constructorWitnessWithStructuralNode(request_node, structural_node);
                return .{ .ret = .{ .maybe_node = try self.relateCheckedNodeToProducedValue(request_node, witness) } };
            },
            .list => |items| {
                if (task.index < items.len) {
                    return evidenceCall(self, .{ .produced_value = .{ .expr = items[task.index], .request_node = task.current_child_node } });
                }
                const element_witness = task.produced_element orelse return .{ .ret = .{ .maybe_node = null } };
                const structural_node = try self.graph.newNode(.{ .list = element_witness });
                const witness = try self.constructorWitnessWithStructuralNode(request_node, structural_node);
                return .{ .ret = .{ .maybe_node = try self.relateCheckedNodeToProducedValue(request_node, witness) } };
            },
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .empty_list, .match_, .if_, .empty_record, .block, .zero_argument_tag, .call, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level, .nominal => unreachable,
        }
    }

    /// `dispatchResultTypeNodeInPhase` (starting at the plan) or
    /// `callableDispatchResultTypeNodeInPhase` (starting at an already
    /// selected callable plan).
    fn stepDispatchResult(self: *BodyContext, frame: *EvidenceFrame, task: *DispatchResultTask, input: ?EvidenceResult, from_plan: bool) Allocator.Error!EvidenceStep {
        if (frame.cursor == 1) {
            var callable_node = input.?.nodeValue();
            const call_ctx = task.call_ctx.?;
            const callable_plan = task.callable_plan;
            const plan = callable_plan.plan;
            const plan_args = callable_plan.operands;
            const resolution = self.evidenceResolution(plan) orelse
                Common.invariant("runtime method result had no CheckedCallResolution evidence");
            switch (resolution) {
                .target => |lookup| {
                    const relation_lookup = lookup;
                    const target_node = try self.methodTargetNodeFromPlan(relation_lookup, call_ctx, plan.callable_ty);
                    try self.relateDispatchTargetRequestInterface(relation_lookup, target_node, callable_node);
                    if (try self.generatedIteratorMethodRequestNode(
                        relation_lookup,
                        target_node,
                        callable_node,
                        plan_args,
                    )) |private_node| {
                        callable_node = private_node;
                    }
                    if (task.phase == .expression_lowering) {
                        callable_node = try self.lowerAndCompleteIteratorMethodResultAtNode(
                            relation_lookup,
                            callable_node,
                            plan,
                            self.dispatchUsesDirectGraphCallee(plan),
                        );
                    }
                },
                .structural => {},
            }
            self.destroyCallContext(call_ctx);
            task.call_ctx = null;
            return .{ .ret = .{ .node = switch ((try self.graph.content(callable_node))) {
                .func => |function| function.ret,
                .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => Common.invariant("checked dispatch plan had a non-function graph node"),
            } } };
        }

        if (from_plan) {
            const plan_id = task.maybe_plan orelse Common.invariant("checked dispatch expression reached Monotype without a dispatch plan");
            const plan = self.view.static_dispatch_plans.plans[@backingInt(plan_id)];
            if (try self.closedDirectGraphFreeResultNode(task.checked_ret_ty, plan, task.expected_ret_node)) |ret_node| {
                return .{ .ret = .{ .node = ret_node } };
            }
            task.callable_plan = switch (self.dispatchRuntimePlan(plan)) {
                .callable => |callable_plan| callable_plan,
                .crash => return .{ .ret = .{ .node = task.expected_ret_node orelse
                    Common.invariant("rejected dispatch reached result type lookup without a contextual result cell") } },
            };
        }
        const call_ctx = try self.createCallContext();
        task.call_ctx = call_ctx;
        frame.cursor = 1;
        return evidenceCall(call_ctx, .{ .instantiate_dispatch = .{
            .callable_plan = task.callable_plan,
            .caller = self,
            .checked_ret_ty = task.checked_ret_ty,
            .expected_ret_node = task.expected_ret_node,
            .phase = task.phase,
        } });
    }

    /// An interpolation's conversion returns `Try(assembler, err)`; the
    /// interpolation's own value is the assembler's result.
    fn stepInterpolationResult(self: *BodyContext, frame: *EvidenceFrame, task: *InterpolationResultTask, input: ?EvidenceResult) Allocator.Error!EvidenceStep {
        if (frame.cursor == 1) {
            const assembler_node = (try self.graphTryPayloads(input.?.nodeValue())).ok;
            return .{ .ret = .{ .node = (try self.graph.functionNodes(assembler_node)).ret } };
        }
        const try_ty = self.literalConversionTryType(task.maybe_plan);
        const expected_try_node: ?NodeId = if (task.expected_ret_node) |expected| blk: {
            const try_node = try self.instNode(try_ty);
            const assembler_node = (try self.graphTryPayloads(try_node)).ok;
            try relateRequestComponent(self.graph, (try self.graph.functionNodes(assembler_node)).ret, expected);
            break :blk try_node;
        } else null;
        frame.cursor = 1;
        return evidenceCall(self, .{ .dispatch_result = .{ .checked_ret_ty = try_ty, .maybe_plan = task.maybe_plan, .expected_ret_node = expected_try_node, .phase = .expression_lowering } });
    }

    fn stepCallResult(self: *BodyContext, frame: *EvidenceFrame, task: *CallResultTask, input: ?EvidenceResult) Allocator.Error!EvidenceStep {
        const call = task.call;
        switch (frame.cursor) {
            0 => {},
            // An indirect call's instantiated callee.
            1 => {
                const fn_node = input.?.nodeValue();
                self.destroyCallContext(task.call_ctx.?);
                task.call_ctx = null;
                return .{ .ret = .{ .node = switch ((try self.graph.content(fn_node))) {
                    .func => |function| function.ret,
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => Common.invariant("checked indirect call instantiated a non-function graph node"),
                } } };
            },
            // A direct call's request interface.
            2 => {
                frame.cursor = 3;
                return evidenceCall(self, .{ .completed_result = .{
                    .expr = task.expr,
                    .target = call.direct_target.?,
                    .call = call,
                    .source_fn_ty = task.source_fn_ty,
                    .fn_node = input.?.nodeValue(),
                } });
            },
            else => return .{ .ret = input.? },
        }

        const expected_ret_ty = task.expected_ret_ty;
        const checked_ret_ty = task.checked_ret_ty;
        if (call.direct_target == null) {
            if (try self.indirectCalleeMonoType(call.func, call.args, expected_ret_ty)) |fn_ty| {
                const ret_ty = self.functionReturnType(fn_ty);
                if (expected_ret_ty) |expected| {
                    if (!self.sameType(expected, ret_ty)) {
                        Common.invariant("checked indirect call result type differed from its expected Monotype type");
                    }
                    try self.constrainTypeToMono(checked_ret_ty, expected);
                    return .{ .ret = .{ .node = try self.activeNodeFromType(expected) } };
                }
                try self.constrainTypeToMono(checked_ret_ty, ret_ty);
                return .{ .ret = .{ .node = try self.activeNodeFromType(ret_ty) } };
            }

            const call_ctx = try self.createCallContext();
            task.call_ctx = call_ctx;
            frame.cursor = 1;
            return evidenceCall(call_ctx, .{ .instantiate_call = .{
                .source_fn_ty = call.source_fn_ty_payload,
                .caller = self,
                .checked_ret_ty = checked_ret_ty,
                .checked_args = call.args,
                .expected_ret_node = if (expected_ret_ty) |expected| try self.activeNodeFromType(expected) else null,
                .hosted_try_capability = null,
                .capture_constructor_argument_evidence = false,
            } });
        }

        const target = call.direct_target.?;
        task.source_fn_ty = self.directCallInstantiationSourceFnType(target, call.source_fn_ty_payload);
        frame.cursor = 2;
        return evidenceCall(self, .{ .direct_call_request = .{
            .expr = task.expr,
            .target = target,
            .call = call,
            .checked_ret_ty = checked_ret_ty,
            .source_fn_ty = task.source_fn_ty,
            .expected_ret_node = if (expected_ret_ty) |expected| try self.activeNodeFromType(expected) else null,
        } });
    }

    /// The request interface of a direct call expression, instantiated once
    /// per body and shared by every later read of the same expression (see
    /// `directCallRequestNode`).
    fn stepDirectCallRequest(self: *BodyContext, frame: *EvidenceFrame, task: *DirectCallTask, input: ?EvidenceResult) Allocator.Error!EvidenceStep {
        switch (frame.cursor) {
            0 => {},
            1 => return .{ .ret = input.? },
            else => {
                const fn_node = input.?.nodeValue();
                try self.instantiation.direct_call_requests.put(task.expr, .{ .fn_node = fn_node });
                return .{ .ret = .{ .node = fn_node } };
            },
        }
        const type_task = EvidenceTask{ .direct_call_type = .{
            .expr = task.expr,
            .target = task.target,
            .call = task.call,
            .checked_ret_ty = task.checked_ret_ty,
            .source_fn_ty = task.source_fn_ty,
            .expected_ret_node = task.expected_ret_node,
        } };
        if (!try self.directCallRequestIsShareable(task.target, task.expected_ret_node)) {
            frame.cursor = 1;
            return evidenceCall(self, type_task);
        }
        if (self.instantiation.direct_call_requests.get(task.expr)) |request| {
            self.builder.countBodyDiagnostic("direct_call_request_reuses");
            if (task.expected_ret_node) |expected| {
                const fn_nodes = try self.graph.functionNodes(request.fn_node);
                _ = try checkedMonoRequestNode(self.graph, fn_nodes.ret, expected, .exact);
            }
            return .{ .ret = .{ .node = request.fn_node } };
        }
        frame.cursor = 2;
        return evidenceCall(self, type_task);
    }

    fn stepDirectCallType(self: *BodyContext, frame: *EvidenceFrame, task: *DirectCallTask, input: ?EvidenceResult) Allocator.Error!EvidenceStep {
        const call = task.call;
        if (frame.cursor == 1) {
            var fn_node = input.?.nodeValue();
            if (self.iteratorProcedureForResolvedTarget(call.direct_target.?)) |procedure| {
                const public_fn_node = self.graph.requestSourceInterface(fn_node) orelse fn_node;
                if (try self.generatedIteratorFunctionNode(procedure, public_fn_node, fn_node, call.args)) |private_fn_node| {
                    try self.graph.registerRequestSourceInterface(private_fn_node, public_fn_node);
                    try relateFunctionRequestInterface(self.graph, public_fn_node, private_fn_node);
                    fn_node = private_fn_node;
                }
            }
            self.destroyCallContext(task.call_ctx.?);
            task.call_ctx = null;
            return .{ .ret = .{ .node = fn_node } };
        }
        if (call.direct_target == null) {
            Common.invariant("direct checked call instantiation received an indirect call");
        }
        const call_ctx = try self.createCallContext();
        task.call_ctx = call_ctx;
        frame.cursor = 1;
        return evidenceCall(call_ctx, .{ .instantiate_call = .{
            .source_fn_ty = task.source_fn_ty,
            .caller = self,
            .checked_ret_ty = task.checked_ret_ty,
            .checked_args = call.args,
            .expected_ret_node = task.expected_ret_node,
            .hosted_try_capability = try self.hostedTryCapabilityForResolvedTarget(call.direct_target.?),
            .capture_constructor_argument_evidence = try self.iteratorCallNeedsConstructorArgumentEvidence(
                self.iteratorProcedureForResolvedTarget(call.direct_target.?),
                call.args,
            ),
        } });
    }

    /// Instantiate a callee's checked function type from the caller's
    /// argument evidence. Runs on the callee context; each argument's
    /// evidence is computed on the caller.
    fn stepInstantiateCall(self: *BodyContext, frame: *EvidenceFrame, task: *InstantiateCallTask, input: ?EvidenceResult) Allocator.Error!EvidenceStep {
        const caller = task.caller;
        if (frame.cursor == 0) {
            const function = self.checkedFunctionType(task.source_fn_ty);
            if (function.args.len != task.checked_args.len) {
                Common.invariant("checked direct call arity differs from its function type");
            }
            task.fn_node = (try self.calleeValueInstance(task)) orelse try self.instNode(task.source_fn_ty);
            const fn_graph = switch ((try self.graph.content(task.fn_node))) {
                .func => |func| func,
                .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => Common.invariant("checked direct call had a non-function instantiation node"),
            };
            if (fn_graph.args.len != task.checked_args.len) {
                Common.invariant("checked direct call graph arity differed from its argument span");
            }
            task.formal_nodes = fn_graph.args;
            task.ret_node = fn_graph.ret;
            task.request_args = try self.graph.arena().alloc(NodeId, function.args.len);
            frame.cursor = 1;
        } else {
            // An argument's evidence.
            const index = task.index;
            const formal_node = task.formal_nodes[index];
            const checked_arg = task.checked_args[index];
            const arg_ty = caller.view.bodies.expr(checked_arg).ty;
            if (input.?.maybeNodeValue()) |evidence| {
                if (try self.graph.containsGeneratedPrivate(evidence)) {
                    const public_node = try caller.freshInstNode(arg_ty);
                    try self.graph.relateOpaqueInterface(public_node, evidence);
                    try relateRequestComponent(self.graph, formal_node, public_node);
                    task.request_args[index] = evidence;
                } else {
                    const request = try self.unifyFormalWithCallerArgNode(caller, formal_node, arg_ty);
                    try relateRequestComponent(self.graph, formal_node, evidence);
                    task.request_args[index] = request;
                }
            } else {
                task.request_args[index] = try self.unifyFormalWithCallerArgNode(caller, formal_node, arg_ty);
            }
            task.index += 1;
        }

        if (task.index < task.checked_args.len) {
            const checked_arg = task.checked_args[task.index];
            return evidenceCall(caller, if (task.capture_constructor_argument_evidence or caller.propagate_constructor_value_evidence)
                .{ .argument_evidence = .{ .expr = checked_arg } }
            else
                .{ .call_evidence = .{ .expr = checked_arg, .expected_ty = null } });
        }

        const fn_node = task.fn_node;
        const request_args = task.request_args;
        const checked_ret_ty = task.checked_ret_ty;
        if (task.expected_ret_node) |expected| {
            if (task.hosted_try_capability) |capability| {
                if (try self.hostedTryWidenedRequestNode(capability, fn_node, request_args, expected)) |request_fn| {
                    return .{ .ret = .{ .node = request_fn } };
                }
            }
            // An explicit request owns the call's exact result evidence. Keep
            // the checked result as a fresh public interface: its cached cell
            // may already contain private evidence from another occurrence.
            const public_ret = try caller.freshInstNode(checked_ret_ty);
            try relateRequestComponent(self.graph, task.ret_node, public_ret);
        } else {
            const caller_ret = try caller.instNode(checked_ret_ty);
            if (task.hosted_try_capability) |capability| {
                if (try self.hostedTryWidenedRequestNode(capability, fn_node, request_args, caller_ret)) |request_fn| {
                    return .{ .ret = .{ .node = request_fn } };
                }
            }
            if (try self.graph.containsGeneratedPrivate(caller_ret)) {
                // A prior occurrence may already have refined this cached cell
                // to a private producer representation. Preserve its public
                // interface without letting that representation select this
                // call's producer before the call itself has done so.
                const public_ret = try caller.freshInstNode(checked_ret_ty);
                try self.graph.relateOpaqueInterface(public_ret, caller_ret);
                try relateRequestComponent(self.graph, task.ret_node, public_ret);
            } else {
                try relateRequestComponent(self.graph, task.ret_node, caller_ret);
            }
        }
        var request_ret = task.ret_node;
        if (task.expected_ret_node) |expected| {
            request_ret = if (try self.graph.containsGeneratedPrivate(expected))
                expected
            else
                try checkedMonoRequestNode(self.graph, task.ret_node, expected, .exact);
        }
        return .{ .ret = .{ .node = try functionRequestNode(self.graph, fn_node, request_args, request_ret) } };
    }

    /// An indirect call's callee is a value of the caller, so its function
    /// type is the caller's instance of that checked type, which the callee's
    /// lowering relates to the request. When no representation evidence can
    /// attach to the type and none is present, every relation the call makes
    /// is plain unification, so a fresh instance would join the caller's
    /// entirely; the call uses the caller's instance directly. An explicit
    /// result request keeps the fresh instance that owns its exact result.
    fn calleeValueInstance(self: *BodyContext, task: *InstantiateCallTask) Allocator.Error!?NodeId {
        if (!task.callee_value or task.expected_ret_node != null or task.hosted_try_capability != null) return null;
        if (!try self.checkedTypeRepresentationFixed(task.source_fn_ty)) return null;
        const node = try task.caller.instNode(task.source_fn_ty);
        if (try self.graph.containsGeneratedPrivate(node)) return null;
        try self.putScopedNode(self.scopedCheckedType(task.source_fn_ty), node);
        return node;
    }

    /// Instantiate a dispatch plan's callable from the caller's operand
    /// evidence. Runs on the callee context; each operand's type node is
    /// computed on the caller.
    fn stepInstantiateDispatch(self: *BodyContext, frame: *EvidenceFrame, task: *InstantiateDispatchTask, input: ?EvidenceResult) Allocator.Error!EvidenceStep {
        const caller = task.caller;
        const plan = task.callable_plan.plan;
        const operands = task.callable_plan.operands;
        if (frame.cursor == 0) {
            const source_fn_ty = plan.callable_ty;
            const function = self.checkedFunctionType(source_fn_ty);
            if (function.args.len != operands.len) {
                Common.invariant("checked dispatch plan arity differs from its function type");
            }
            task.fn_node = try self.instNode(source_fn_ty);
            const fn_graph = switch ((try self.graph.content(task.fn_node))) {
                .func => |func| func,
                .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => Common.invariant("checked dispatch plan had a non-function instantiation node"),
            };
            if (fn_graph.args.len != operands.len) {
                Common.invariant("checked dispatch plan graph arity differed from its operand span");
            }
            task.formal_nodes = fn_graph.args;
            task.ret_node = fn_graph.ret;
            switch (plan.dispatcher) {
                .arg => |index| {
                    if (index >= fn_graph.args.len) Common.invariant("dispatch plan dispatcher argument index was outside the callable graph");
                    const dispatcher_node = try caller.instNode(plan.dispatcher_ty);
                    try relateRequestComponent(self.graph, fn_graph.args[index], dispatcher_node);
                },
                .type_only => {},
            }
            task.request_args = try self.graph.arena().alloc(NodeId, function.args.len);
            frame.cursor = 1;
        } else {
            // An operand's type node.
            const formal_node = task.formal_nodes[task.index];
            const checked_arg = operands[task.index].checked_expr;
            const arg_ty = caller.view.bodies.expr(checked_arg).ty;
            const evidence_node = input.?.nodeValue();
            if (try self.graph.containsGeneratedPrivate(evidence_node)) {
                const public_node = try caller.freshInstNode(arg_ty);
                try self.graph.relateOpaqueInterface(public_node, evidence_node);
                try relateRequestComponent(self.graph, formal_node, public_node);
                task.request_args[task.index] = evidence_node;
            } else {
                const public_node = try caller.instNode(arg_ty);
                try relateRequestComponent(self.graph, formal_node, public_node);
                try relateRequestComponent(self.graph, formal_node, evidence_node);
            }
            task.index += 1;
        }

        while (task.index < operands.len) : (task.index += 1) {
            const formal_node = task.formal_nodes[task.index];
            task.request_args[task.index] = formal_node;
            switch (operands[task.index]) {
                .checked_expr => |checked_arg| {
                    if (task.phase == .expression_lowering) {
                        return evidenceCall(caller, .{ .type_node = .{ .expr = checked_arg } });
                    }
                    const arg_ty = caller.view.bodies.expr(checked_arg).ty;
                    try relateRequestComponent(self.graph, formal_node, try caller.instNode(arg_ty));
                },
                .generated_interpolation_segments,
                .generated_numeral,
                .generated_quote,
                => {},
            }
        }

        var request_ret = task.ret_node;
        const checked_ret_ty = task.checked_ret_ty;
        if (task.expected_ret_node) |expected| {
            try relateRequestComponent(self.graph, task.ret_node, try caller.freshInstNode(checked_ret_ty));
            request_ret = if (try self.graph.containsGeneratedPrivate(expected))
                expected
            else
                try checkedMonoRequestNode(self.graph, task.ret_node, expected, .exact);
        } else {
            const caller_ret = try caller.instNode(checked_ret_ty);
            if (try self.graph.containsGeneratedPrivate(caller_ret)) {
                const public_ret = try caller.freshInstNode(checked_ret_ty);
                try self.graph.relateOpaqueInterface(public_ret, caller_ret);
                try relateRequestComponent(self.graph, task.ret_node, public_ret);
            } else {
                try relateRequestComponent(self.graph, task.ret_node, caller_ret);
            }
        }
        return .{ .ret = .{ .node = try functionRequestNode(self.graph, task.fn_node, task.request_args, request_ret) } };
    }

    fn stepFieldAccess(
        self: *BodyContext,
        frame: *EvidenceFrame,
        checked_ty: checked.CheckedTypeId,
        access: CheckedFieldAccess,
        expected_ty: ?Type.TypeId,
        input: ?EvidenceResult,
    ) Allocator.Error!EvidenceStep {
        if (frame.cursor == 0) {
            if (access.segments.len == 0) Common.invariant("checked field access path had no segments");
            frame.cursor = 1;
            return evidenceCall(self, .{ .type_node = .{ .expr = access.receiver } });
        }
        var saw_optional = false;
        var field_node = input.?.nodeValue();
        for (access.segments, 0..) |segment, index| {
            const is_last = index + 1 == access.segments.len;
            const mono_field_name = try self.recordFieldName(self.view, segment.field_name);
            switch (segment.mode) {
                // A required segment's slot IS the field's value: the chain
                // continues from the receiver-derived slot node so a
                // producer-authored (generated-private) representation—e.g.
                // a stored iterator witness—survives the access. The
                // segment's checked success type relates to the slot only as
                // its public interface, never by direct unification; the
                // final segment's relation is the trailing whole-expression
                // constraint below.
                .required => {
                    const slot_node = try self.graph.requiredRecordFieldNode(field_node, mono_field_name);
                    if (!is_last) {
                        try self.constrainCheckedInterfaceToCell(
                            segment.success_ty,
                            DraftTypeCell.fromGraphNode(slot_node),
                        );
                    }
                    field_node = slot_node;
                },
                // A `.?` segment's slot is the tagged representation of the
                // value; the chain continues from the Present payload.
                .optional => {
                    saw_optional = true;
                    const field = try self.graph.optionalRecordFieldNodes(field_node, mono_field_name);
                    const value_node = try self.instNode(segment.success_ty);
                    try self.graph.unify(field.value, value_node);
                    try self.graph.unify(field.slot, try self.optionalSlotNode(value_node));
                    field_node = field.value;
                },
            }
        }
        if (saw_optional) {
            // The chain's observable type is the checked expression's own
            // `Try(τ, [MissingField])` from the checking output; constrain
            // its Ok argument with the receiver-refined final value node
            // (instNode caches by checked identity, so this reaches the Try
            // node's arg).
            try self.graph.unify(field_node, try self.instNode(self.checkedTryOkArg(checked_ty)));
            field_node = try self.instNode(checked_ty);
        }
        try self.constrainCheckedInterfaceToCell(
            checked_ty,
            DraftTypeCell.fromGraphNode(field_node),
        );
        if (expected_ty) |expected| {
            try relateRequestComponent(self.graph, try self.graph.importMono(expected), field_node);
        }
        return .{ .ret = .{ .node = field_node } };
    }

    fn stepTupleAccess(
        self: *BodyContext,
        frame: *EvidenceFrame,
        checked_ty: checked.CheckedTypeId,
        tuple: checked.CheckedExprId,
        elem_index: usize,
        expected_ty: ?Type.TypeId,
        input: ?EvidenceResult,
    ) Allocator.Error!EvidenceStep {
        if (frame.cursor == 0) {
            frame.cursor = 1;
            return evidenceCall(self, .{ .type_node = .{ .expr = tuple } });
        }
        const tuple_node = input.?.nodeValue();
        const item_nodes = try self.graph.tupleItemNodes(tuple_node);
        if (elem_index >= item_nodes.len) Common.invariant("tuple access index was outside its graph tuple type");
        const item_node = item_nodes[elem_index];
        try self.constrainCheckedInterfaceToCell(
            checked_ty,
            DraftTypeCell.fromGraphNode(item_node),
        );
        if (expected_ty) |expected| {
            try relateRequestComponent(self.graph, try self.graph.importMono(expected), item_node);
        }
        return .{ .ret = .{ .node = item_node } };
    }

    /// The result cell of a direct call is the selected specialization's
    /// result (see `directCallCompletedResultNode`).
    fn stepCompletedResult(self: *BodyContext, frame: *EvidenceFrame, task: CompletedResultTask) Allocator.Error!EvidenceStep {
        const checked_expr = task.expr;
        const target = task.target;
        const call = task.call;
        const fn_node = task.fn_node;
        if (frame.cursor == 0) {
            if (self.instantiation.direct_call_requests.get(checked_expr)) |request| {
                if (request.fn_node == fn_node) {
                    if (request.completed) |completed| return .{ .ret = .{ .node = (try self.graph.functionNodes(completed.fn_node)).ret } };
                }
            }
            if (self.callsiteIntrinsicForResolvedTarget(target)) |intrinsic| {
                const callable_node = try self.callsiteIntrinsicRequestNode(intrinsic, fn_node);
                return .{ .ret = .{ .node = (try self.graph.functionNodes(callable_node)).ret } };
            }
            const fn_nodes = try self.graph.functionNodes(fn_node);
            if (self.checkedExprDivergesInLoweredRuntime(call.func)) return .{ .ret = .{ .node = fn_nodes.ret } };
            for (call.args) |arg| {
                if (self.checkedExprDivergesInLoweredRuntime(arg)) return .{ .ret = .{ .node = fn_nodes.ret } };
            }
            frame.cursor = 1;
            return evidenceCall(self, .{ .prepare_direct_args = .{
                .expr = checked_expr,
                .fn_node = fn_node,
                .checked_exprs = call.args,
                .nodes = fn_nodes.args,
            } });
        }
        const fn_nodes = try self.graph.functionNodes(fn_node);
        for (fn_nodes.args) |arg_node| {
            if (try self.nodeIsProvenUninhabited(arg_node)) return .{ .ret = .{ .node = fn_nodes.ret } };
        }
        if (self.iteratorProcedureForResolvedTarget(target)) |procedure| {
            if (procedure == .next and fn_nodes.args.len == 1 and (try self.isGeneratedIteratorEvidenceNode(fn_nodes.args[0]))) {
                return .{ .ret = .{ .node = fn_nodes.ret } };
            }
        }
        if (self.resolvedTargetIsStrInspect(target)) return .{ .ret = .{ .node = fn_nodes.ret } };
        const completed = try self.completedDirectCalleeAtNode(checked_expr, target, task.source_fn_ty, fn_node);
        return .{ .ret = .{ .node = (try self.graph.functionNodes(completed.fn_node)).ret } };
    }

    /// Relate each checked argument to its request node, then prepare nested
    /// callables. A direct call prepares its shared request's arguments once.
    fn stepPrepareArgs(self: *BodyContext, frame: *EvidenceFrame, task: *PrepareArgsTask, direct_call: bool) Allocator.Error!EvidenceStep {
        if (frame.cursor == 0) {
            if (direct_call) {
                if (self.instantiation.direct_call_requests.get(task.expr)) |request| {
                    if (request.fn_node == task.fn_node and request.args_prepared) return .{ .ret = .none };
                }
            }
            if (task.checked_exprs.len != task.nodes.len) Common.invariant("checked call argument count differed from graph function arity");
            self.builder.countBodyDiagnostic("argument_spans_prepared");
            self.builder.countBodyDiagnosticBy("arguments_prepared", task.checked_exprs.len);
            frame.cursor = 1;
            if (direct_call and self.directCallArgsRelated(task.expr, task.fn_node)) task.index = task.checked_exprs.len;
        } else if (frame.cursor == 1) {
            task.index += 1;
        }
        if (frame.cursor == 1) {
            if (task.index < task.checked_exprs.len) {
                return evidenceCall(self, .{ .relate = .{ .expr = task.checked_exprs[task.index], .expected_node = task.nodes[task.index] } });
            }
            frame.cursor = 2;
            task.index = 0;
        }
        while (task.index < task.checked_exprs.len) {
            const expr = task.checked_exprs[task.index];
            const request_fn_node = task.nodes[task.index];
            task.index += 1;
            if (self.isNestedCallableExpr(expr)) return .{ .draft_nested = .{ .ctx = self, .expr = expr, .request_fn_node = request_fn_node } };
        }
        if (direct_call) {
            if (self.instantiation.direct_call_requests.getPtr(task.expr)) |request| {
                if (request.fn_node == task.fn_node) {
                    request.args_related = true;
                    request.args_prepared = true;
                }
            }
        }
        return .{ .ret = .none };
    }

    fn directCallArgsRelated(self: *const BodyContext, checked_expr: checked.CheckedExprId, fn_node: NodeId) bool {
        const request = self.instantiation.direct_call_requests.get(checked_expr) orelse return false;
        return request.fn_node == fn_node and request.args_related;
    }

    /// Relate a checked expression's value to a request node.
    fn stepRelate(self: *BodyContext, frame: *EvidenceFrame, task: *RelateTask, input: ?EvidenceResult) Allocator.Error!EvidenceStep {
        const checked_expr = task.expr;
        const expected_node = task.expected_node;
        const expr = self.view.bodies.expr(checked_expr);
        if (frame.cursor == 0) {
            task.timing = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
            self.builder.countBodyDiagnostic("expr_relation_requests");
            // Divergent expressions never return a value to relate to the
            // request. In particular, checking may replace a failed callee
            // with `runtime_error`, which emits a crash, while its unused call
            // type contains `.err`.
            if (self.checkedExprDivergesInLoweredRuntime(checked_expr)) return self.finishRelate(task);
            switch (expr.data) {
                .tag, .nominal, .tuple, .list, .record => {
                    const key = RelatedConstructor{ .expr = checked_expr, .node = self.graph.rootNode(expected_node) };
                    if ((try self.related_constructors.getOrPut(self.allocator, key)).found_existing) return self.finishRelate(task);
                },
                .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .empty_list, .match_, .if_, .call, .empty_record, .block, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
            }
            frame.cursor = 1;
            switch (expr.data) {
                .lookup_local => |lookup| try self.relateLookupExprAtNode(checked_expr, lookup.resolved, expected_node),
                .lookup_external, .lookup_required => |resolved| try self.relateLookupExprAtNode(checked_expr, resolved, expected_node),
                .call => |call| return try self.beginRelateCall(frame, task, expr.ty, call),
                .dispatch_call => |plan| return evidenceCall(self, .{ .dispatch_result = .{ .checked_ret_ty = expr.ty, .maybe_plan = plan, .expected_ret_node = expected_node, .phase = .expression_lowering } }),
                .interpolation => |interpolation| return evidenceCall(self, .{ .interpolation_result = .{ .maybe_plan = interpolation.plan, .expected_ret_node = expected_node } }),
                .type_dispatch_call, .method_eq => |plan| return evidenceCall(self, .{ .dispatch_result = .{ .checked_ret_ty = expr.ty, .maybe_plan = plan, .expected_ret_node = expected_node, .phase = .expression_lowering } }),
                .field_access => |field| return evidenceCall(self, .{ .field_access = .{ .checked_ty = expr.ty, .access = field, .expected_ty = null } }),
                .tag => |tag| {
                    task.name = try self.tagName(self.view, tag.name);
                    return try self.nextRelateChild(task, expr);
                },
                .zero_argument_tag => _ = try self.graph.tagRowNodes(expected_node),
                .nominal => |nominal| {
                    const representation_node = (try self.constructorRepresentationNode(expected_node));
                    if ((try self.graph.content(representation_node)) != .named) {
                        Common.invariant("nominal constructor had no nominal graph representation");
                    }
                    const named = (try self.graph.namedNodes(representation_node));
                    const backing_node = (named.backing orelse
                        Common.invariant("nominal constructor graph node had no backing")).node;
                    task.index = 1;
                    return evidenceCall(self, .{ .relate = .{ .expr = nominal.backing_expr, .expected_node = backing_node } });
                },
                .tuple => |items| {
                    const item_nodes = try self.graph.tupleItemNodes(expected_node);
                    if (items.len != item_nodes.len) Common.invariant("tuple constructor arity differed from its graph type");
                    task.child_nodes = item_nodes;
                    return try self.nextRelateChild(task, expr);
                },
                .list => {
                    task.fn_node = try self.graph.listElementNode(expected_node);
                    return try self.nextRelateChild(task, expr);
                },
                .empty_list => _ = try self.graph.listElementNode(expected_node),
                .empty_record => _ = try self.graph.recordConstructionNodes(expected_node),
                .record => {
                    task.construction = try self.constructionFields(expected_node);
                    return try self.nextRelateChild(task, expr);
                },
                // These forms propagate the exact result cell while their own
                // lowering establishes branch-local binders and statement
                // state. Relating their shared checked result node here would
                // collapse distinct generated-private representations across
                // branches.
                .block, .match_, .if_, .runtime_error => {},
                .lambda, .closure => _ = try self.graph.functionNodes(expected_node),
                .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .binop, .unary_minus, .unary_not, .structural_eq, .structural_hash, .tuple_access, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => return evidenceCall(self, .{ .type_node = .{ .expr = checked_expr } }),
            }
            return self.finishRelate(task);
        }

        switch (expr.data) {
            .dispatch_call, .interpolation, .type_dispatch_call, .method_eq, .field_access => {
                try relateRequestComponent(self.graph, input.?.nodeValue(), expected_node);
                return self.finishRelate(task);
            },
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .binop, .unary_minus, .unary_not, .structural_eq, .structural_hash, .tuple_access, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {
                try self.graph.unify(expected_node, input.?.nodeValue());
                return self.finishRelate(task);
            },
            .call => |call| return try self.resumeRelateCall(frame, task, call, input),
            .tag, .tuple, .list, .record => {
                task.index += 1;
                return try self.nextRelateChild(task, expr);
            },
            .nominal => return self.finishRelate(task),
            .lookup_local, .lookup_external, .lookup_required, .zero_argument_tag, .empty_list, .empty_record, .block, .match_, .if_, .runtime_error, .lambda, .closure => unreachable,
        }
    }

    fn finishRelate(_: *BodyContext, task: *RelateTask) EvidenceStep {
        task.timing.end();
        return .{ .ret = .none };
    }

    /// Relate the next constructor child to its slot of the request.
    fn nextRelateChild(self: *BodyContext, task: *RelateTask, expr: checked.CheckedExpr) Allocator.Error!EvidenceStep {
        const expected_node = task.expected_node;
        switch (expr.data) {
            .tag => |tag| {
                if (task.index < tag.args.len) {
                    return evidenceCall(self, .{ .relate = .{
                        .expr = tag.args[task.index],
                        .expected_node = try self.graph.tagConstructionPayloadNode(expected_node, task.name, task.index),
                    } });
                }
            },
            .tuple => |items| {
                if (task.index < items.len) {
                    return evidenceCall(self, .{ .relate = .{ .expr = items[task.index], .expected_node = task.child_nodes[task.index] } });
                }
            },
            .list => |items| {
                if (task.index < items.len) {
                    return evidenceCall(self, .{ .relate = .{ .expr = items[task.index], .expected_node = task.fn_node } });
                }
            },
            .record => |record| {
                if (task.index < record.fields.len) {
                    const field = record.fields[task.index];
                    const construction_field = task.construction.?.get(try self.recordFieldName(self.view, field.label));
                    return evidenceCall(self, .{ .relate = .{
                        .expr = field.value,
                        .expected_node = self.graph.rootNode(construction_field.value_ty orelse construction_field.ty),
                    } });
                }
            },
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .empty_list, .match_, .if_, .empty_record, .block, .zero_argument_tag, .call, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level, .nominal => unreachable,
        }
        return self.finishRelate(task);
    }

    /// A shareable direct call relates its shared
    /// request; any other call instantiates its callee on a call context.
    fn beginRelateCall(self: *BodyContext, frame: *EvidenceFrame, task: *RelateTask, checked_ret_ty: checked.CheckedTypeId, call: CheckedCall) Allocator.Error!EvidenceStep {
        if (call.direct_target) |target| {
            if (try self.directCallRequestIsShareable(target, null)) {
                frame.cursor = 2;
                return evidenceCall(self, .{ .direct_call_request = .{
                    .expr = task.expr,
                    .target = target,
                    .call = call,
                    .checked_ret_ty = checked_ret_ty,
                    .source_fn_ty = self.directCallInstantiationSourceFnType(target, call.source_fn_ty_payload),
                    .expected_ret_node = null,
                } });
            }
        }
        const call_ctx = try self.createCallContext();
        task.call_ctx = call_ctx;

        const source_fn_ty = if (call.direct_target) |target|
            self.directCallInstantiationSourceFnType(target, call.source_fn_ty_payload)
        else
            call.source_fn_ty_payload;
        const hosted_try_capability = if (call.direct_target) |target|
            try self.hostedTryCapabilityForResolvedTarget(target)
        else
            null;
        frame.cursor = 3;
        return evidenceCall(call_ctx, .{ .instantiate_call = .{
            .source_fn_ty = source_fn_ty,
            .caller = self,
            .checked_ret_ty = checked_ret_ty,
            .checked_args = call.args,
            .expected_ret_node = if (hosted_try_capability != null) task.expected_node else null,
            .hosted_try_capability = hosted_try_capability,
            .capture_constructor_argument_evidence = if (call.direct_target) |target|
                try self.iteratorCallNeedsConstructorArgumentEvidence(
                    self.iteratorProcedureForResolvedTarget(target),
                    call.args,
                )
            else
                false,
        } });
    }

    /// Continue relating a call: after its request node, relate each
    /// argument to its request slot, then an indirect call's callee.
    fn resumeRelateCall(self: *BodyContext, frame: *EvidenceFrame, task: *RelateTask, call: CheckedCall, input: ?EvidenceResult) Allocator.Error!EvidenceStep {
        switch (frame.cursor) {
            // The call's request node.
            2, 3 => {
                task.fn_node = input.?.nodeValue();
                const fn_nodes = try self.graph.functionNodes(task.fn_node);
                try relateRequestComponent(self.graph, fn_nodes.ret, task.expected_node);
                task.child_nodes = fn_nodes.args;
                task.index = 0;
                frame.cursor += 2;
                // A shared request's arguments relate to its slots once.
                if (frame.cursor == 4 and self.directCallArgsRelated(task.expr, task.fn_node)) task.index = call.args.len;
            },
            // An argument relation.
            4, 5 => task.index += 1,
            // The indirect callee relation.
            else => {
                if (task.call_ctx) |call_ctx| self.destroyCallContext(call_ctx);
                task.call_ctx = null;
                return self.finishRelate(task);
            },
        }
        if (task.index < call.args.len) {
            return evidenceCall(self, .{ .relate = .{ .expr = call.args[task.index], .expected_node = task.child_nodes[task.index] } });
        }
        if (frame.cursor == 4) {
            if (self.instantiation.direct_call_requests.getPtr(task.expr)) |request| {
                if (request.fn_node == task.fn_node) request.args_related = true;
            }
        }
        if (frame.cursor == 5 and call.direct_target == null) {
            frame.cursor = 6;
            return evidenceCall(self, .{ .relate = .{ .expr = call.func, .expected_node = task.fn_node } });
        }
        if (task.call_ctx) |call_ctx| self.destroyCallContext(call_ctx);
        task.call_ctx = null;
        return self.finishRelate(task);
    }

    fn lowerExprTypeNode(self: *BodyContext, expr_id: checked.CheckedExprId) Allocator.Error!NodeId {
        return (try self.runEvidence(.{ .type_node = .{ .expr = expr_id } })).nodeValue();
    }

    fn lowerExprType(self: *BodyContext, expr_id: checked.CheckedExprId) Allocator.Error!Type.TypeId {
        const expr = self.view.bodies.expr(expr_id);
        return switch (expr.data) {
            // A checked runtime error emits a crash and never returns a value,
            // so an unconstrained occurrence uses unit while contextual lowering
            // supplies the exact expected type through lowerExprAtType.
            .runtime_error => try self.unitType(),
            .call => |call| (try self.callResultMonoType(expr_id, expr.ty, call, null)) orelse try self.lowerTypeView(expr.ty),
            .dispatch_call => |plan| (try self.dispatchResultMonoType(expr.ty, plan, null)) orelse try self.lowerTypeView(expr.ty),
            .interpolation => |interpolation| try self.activeTypeFromNode(try self.interpolationResultTypeNode(interpolation.plan, null)),
            .type_dispatch_call, .method_eq => |plan| (try self.dispatchResultMonoType(expr.ty, plan, null)) orelse try self.lowerTypeView(expr.ty),
            .lookup_local => |lookup| try self.lookupExprMonoType(expr.ty, lookup.resolved),
            .lookup_external, .lookup_required => |resolved| try self.lookupExprMonoType(expr.ty, resolved),
            .lambda => |lambda| try self.lambdaFunctionType(expr.ty, lambda),
            .closure => |closure| try self.closureFunctionType(closure),
            .field_access => |field| try self.activeTypeFromNode(try self.fieldAccessTypeNode(expr.ty, field, null)),
            .tuple_access => |access| try self.activeTypeFromNode(try self.tupleAccessTypeNode(expr.ty, access.tuple, access.elem_index, null)),
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .list, .empty_list, .tuple, .match_, .if_, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .structural_eq, .structural_hash, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => try self.lowerTypeView(expr.ty),
        };
    }

    /// Resolve a checked node's source region to a `SourceLoc` in this body's
    /// module.
    fn sourceLocFor(self: *BodyContext, region: base.Region) Allocator.Error!base.SourceLoc {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .source_mapping);
        defer timing_scope.end();
        if (region.isEmpty()) return base.SourceLoc.none;
        const line_starts = self.view.module_env.common.getLineStartsAll();
        if (line_starts.len == 0) return base.SourceLoc.none;
        const offset = region.start.offset;
        const line = base.RegionInfo.lineIdx(line_starts, offset);
        const column = base.RegionInfo.columnIdx(line_starts, line, offset) catch
            Common.invariant("checked node region resolved to an invalid line/column position");
        return .{
            .file = self.source_file_id orelse
                Common.invariant("expression-capable body context had no source-file identity"),
            .line = line + 1,
            .column = column + 1,
        };
    }

    fn sourceRegionForExpr(self: *const BodyContext, expr: checked.CheckedExpr) base.Region {
        return self.source_region_override orelse expr.source_region;
    }

    const DivergentExprContext = union(enum) {
        uncontextual,
        mono_type: Type.TypeId,
        type_cell: DraftTypeCell,
    };

    /// Lower a producer-marked divergent expression before any value
    /// representation or type relation is requested for it. The continuation's
    /// context is the result cell for a value that can never materialize.
    fn divergentExprInContextStep(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        context: DivergentExprContext,
    ) Allocator.Error!?LowerStep {
        if (!self.checkedExprDivergesInLoweredRuntime(expr_id)) return null;

        return switch (context) {
            .uncontextual => blk: {
                const expr = self.view.bodies.expr(expr_id);
                // A runtime error produces no value, and its checked type can
                // contain the error it was retired for. Every other divergent
                // expression retains its checked result variable as an
                // unobservable continuation cell; asking for expression value
                // evidence here would instantiate a rejected dispatch.
                if (expr.data == .runtime_error or self.view.types.payload(expr.ty) == .err) {
                    break :blk divergentStep(self, expr_id, .{ .at_type = try self.unitType() });
                }
                break :blk divergentStep(self, expr_id, .{ .at_cell = DraftTypeCell.fromGraphNode(try self.instNode(expr.ty)) });
            },
            .mono_type => |ty| divergentStep(self, expr_id, .{ .at_type = ty }),
            .type_cell => |cell| divergentStep(self, expr_id, .{ .at_cell = cell }),
        };
    }
    // Expression lowering //
    //
    // Lowering a checked expression lowers its child expressions first, from
    // inside the parent's own lowering. Every lowering computation that lowers
    // a child expression of the same body suspends as a `LowerFrame` on one
    // heap-backed stack and resumes with the child's result, so expression
    // nesting depth never becomes native call depth. Each frame runs on the
    // exact body context the direct computation used, and every draft
    // expression, graph relation, and builder location change happens in the
    // same order. Lowering another body (a nested procedure, a template, a
    // literal conversion root) starts that body's own lowering run.

    const LowerResult = union(enum) {
        expr: DraftExprId,
        maybe_expr: ?DraftExprId,
        call: LoweredCall,
        maybe_call: ?LoweredCall,
        span: DraftSpan(DraftExprId),
        closed_operands: ClosedDispatchOperands,
        statement: LoweredStatement,
        data: BodyExprData,
        /// A hosted evidence computation's result.
        evidence: EvidenceResult,

        fn exprValue(self: LowerResult) DraftExprId {
            return switch (self) {
                .expr => |expr| expr,
                .maybe_expr, .call, .maybe_call, .span, .closed_operands, .statement, .data, .evidence => unreachable,
            };
        }

        fn maybeExprValue(self: LowerResult) ?DraftExprId {
            return switch (self) {
                .maybe_expr => |expr| expr,
                .expr, .call, .maybe_call, .span, .closed_operands, .statement, .data, .evidence => unreachable,
            };
        }

        fn callValue(self: LowerResult) LoweredCall {
            return switch (self) {
                .call => |call| call,
                .expr, .maybe_expr, .maybe_call, .span, .closed_operands, .statement, .data, .evidence => unreachable,
            };
        }

        fn maybeCallValue(self: LowerResult) ?LoweredCall {
            return switch (self) {
                .maybe_call => |call| call,
                .expr, .maybe_expr, .call, .span, .closed_operands, .statement, .data, .evidence => unreachable,
            };
        }

        fn spanValue(self: LowerResult) DraftSpan(DraftExprId) {
            return switch (self) {
                .span => |span| span,
                .expr, .maybe_expr, .call, .maybe_call, .closed_operands, .statement, .data, .evidence => unreachable,
            };
        }

        fn closedOperandsValue(self: LowerResult) ClosedDispatchOperands {
            return switch (self) {
                .closed_operands => |operands| operands,
                .expr, .maybe_expr, .call, .maybe_call, .span, .statement, .data, .evidence => unreachable,
            };
        }

        fn statementValue(self: LowerResult) LoweredStatement {
            return switch (self) {
                .statement => |statement| statement,
                .expr, .maybe_expr, .call, .maybe_call, .span, .closed_operands, .data, .evidence => unreachable,
            };
        }

        fn dataValue(self: LowerResult) BodyExprData {
            return switch (self) {
                .data => |data| data,
                .expr, .maybe_expr, .call, .maybe_call, .span, .closed_operands, .statement, .evidence => unreachable,
            };
        }
    };

    /// The builder's current source location, saved by a lowering frame that
    /// moves it to its own expression and restored when that frame finishes.
    const SavedSourceLocation = struct {
        loc: base.SourceLoc,
        region: base.Region,
    };

    const LowerTask = union(enum) {
        /// `lowerExprAtTypeCellWithKnownDivergence`
        at_type_cell: struct {
            expr: checked.CheckedExprId,
            cell: DraftTypeCell,
            demand: LoweringDemand,
            diverges: bool,
            saved: ?SavedSourceLocation = null,
        },
        /// `lowerExprAtTypeCellInner`
        cell_inner: struct {
            expr: checked.CheckedExprId,
            cell: DraftTypeCell,
            expected_node: NodeId,
            tuple_node: NodeId = undefined,
        },
        /// `lowerExprAtTypeWithDemandInner`
        type_inner: struct { expr: checked.CheckedExprId, ty: Type.TypeId },
        /// `lowerExpr`
        expr: struct { expr: checked.CheckedExprId },
        /// `lowerExprInner`
        expr_inner: struct { expr: checked.CheckedExprId, saved: ?SavedSourceLocation = null },
        /// An expression lowered at a sealed type.
        with_type: WithTypeTask,
        /// `lowerRecordExpr` at a sealed record type.
        record_at_type: RecordAtTypeTask,
        /// `lowerDispatchExprAtType`
        dispatch: DispatchLowerTask,
        /// `lowerClosedDirectLowLevelDispatch`
        closed_low_level: struct {
            plan: static_dispatch.StaticDispatchCallPlan,
            op: can.CIR.Expr.LowLevel,
            expected_ret_cell: DraftTypeCell,
        },
        /// `lowerClosedDirectProcedureDispatch`
        closed_procedure: ClosedProcedureTask,
        /// `lowerClosedDispatchOperandsAtTypes`
        closed_operands_at_types: ClosedOperandsAtTypesTask,
        /// `lowerClosedDispatchOperandsAtNode`
        closed_operands_at_node: struct {
            operands: []const static_dispatch.StaticDispatchOperand,
            callable_node: NodeId,
            expected_ret_cell: DraftTypeCell,
            arg_nodes: []const NodeId = &.{},
        },
        /// Dispatch operands not already lowered, each at its prepared node.
        prepared_operands: PreparedOperandsTask,
        /// `lowerDispatchOperandAtType`
        operand_at_type: struct { operand: static_dispatch.StaticDispatchOperand, ty: Type.TypeId },
        /// `lowerDispatchWithUninhabitedArgument`
        uninhabited_dispatch: UninhabitedArgumentTask,
        /// `lowerDirectCallWithUninhabitedArgument`
        uninhabited_call: UninhabitedArgumentTask,
        /// `lowerExprSpan`
        span: SpanTask,
        /// Expressions each lowered at its prepared node.
        prepared_span: SpanTask,
        /// `lowerExprSpanAtTypes`
        span_at_types: SpanTask,
        /// `lowerListExpr`
        list_span: SpanTask,
        /// `lowerCallAtExpectedNode`
        call: CallLowerTask,
        /// `lowerCallExprAtNode`
        call_expr_at_node: struct { expr: checked.CheckedExprId, expected_node: NodeId, producer_request: ?NodeId = null },
        /// `lowerCallExpr`
        call_expr: struct { expr: checked.CheckedExprId, checked_ret_ty: checked.CheckedTypeId, call: CheckedCall },
        constructor: ConstructorTask,
        /// A block.
        /// Stored by pointer, like `loop`.
        block: *BlockTask,
        /// An `if`.
        if_task: IfTask,
        /// A `match`.
        match_task: MatchTask,
        /// `lowerLambdaExprAtNode` and `lowerClosureAtNode`
        /// Stored by pointer, like `loop`: frames copy their task, and these
        /// two are far larger than every other task.
        nested_fn: *NestedFnTask,
        /// An evidence computation whose nested-callable drafts lower as
        /// child tasks.
        /// Stored by pointer, like `loop`.
        hosted_evidence: *HostedEvidenceTask,
        /// Lambda and closure operands drafted at their slots, each as a
        /// child task.
        draft_callables: DraftCallablesTask,
        /// A control-flow branch body lowered for its output.
        branch_body: BranchBodyTask,
        /// A branch value composed into the enclosing branch state.
        value_then_state: ValueThenStateTask,
        /// An expression lowered as a statement whose value is discarded.
        discarded: DiscardedTask,
        /// A block statement.
        statement: StatementTask,
        /// A `return`'s value.
        return_value: ReturnTask,
        /// A value lowered for diagnostic rendering.
        inspected: InspectedTask,
        /// A divergent expression lowered for its effect.
        divergent: DivergentTask,
        /// A divergent expression's operands, each for its effect.
        operand_sequence: OperandSequenceTask,
        /// A loop statement.
        loop: *LoopTask,
        /// An iterator method call. Boxed: its method lookup is far larger
        /// than every other task.
        iterator_dispatch: *IteratorDispatchTask,
        /// A pattern binding before its continuation.
        materialize: MaterializeTask,
        /// A field access whose receiver lowers as a child.
        field_access: FieldAccessTask,
        /// A string's segments concatenated in order.
        str: StrTask,
        /// A structural equality or hash whose operands lower as children.
        direct_structural: DirectStructuralTask,
        /// A function value rendered by `Str.inspect` after it is evaluated.
        inspect_only: InspectOnlyTask,
        /// A generalized callable alias's aliased callable.
        scheme_alias: SchemeAliasTask,
        /// A call-site intrinsic's arguments, then its generated body.
        callsite_intrinsic: CallsiteIntrinsicTask,
        /// An interpolation: its compile-time conversion, then its assembler
        /// called with the parts' values.
        interpolation: InterpolationLowerTask,
    };

    const InterpolationLowerTask = struct {
        expr: checked.CheckedExprId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        value_node: NodeId,
        try_node: NodeId = undefined,
        assembler_node: NodeId = undefined,
        assembler: DraftExprId = undefined,
        values_ty: Type.TypeId = undefined,
    };

    /// A call-site intrinsic whose arguments lower as child tasks, in
    /// argument order, before its generated body.
    const CallsiteIntrinsicTask = struct {
        intrinsic: checked.IntrinsicId,
        checked_expr_id: checked.CheckedExprId,
        source_fn_ty: checked.CheckedTypeId,
        operands: CheckedIntrinsicOperands,
        /// The callable request node: at a call site, the initial node the
        /// intrinsic's result source refines when the task starts.
        callable_node: NodeId,
        expected_ret_ty: ?Type.TypeId = null,
        /// A deferred intrinsic emitted once the body's graph is sealed,
        /// with the arguments its call site lowered, if any.
        deferred_body: ?struct { pre_lowered_args: ?DraftSpan(DraftExprId) } = null,
        stage: enum { start, deferred_prepared, deferred_args, args } = .start,
        /// The checked arguments. Owned.
        args: []checked.CheckedExprId = &.{},
        arg_tys: [checked.IntrinsicId.max_callsite_arity]Type.TypeId = undefined,
        ret_ty: Type.TypeId = undefined,
        lowered_args: [checked.IntrinsicId.max_callsite_arity]DraftExprId = undefined,
        index: usize = 0,
    };

    /// A checked callable alias is a scheme-use edge, not a new function or
    /// runtime local. Its aliased callable lowers as a child in a fresh
    /// type-only scope holding the alias's exact substitution; runtime binder
    /// and declaration-context tables remain shared with the enclosing body.
    const SchemeAliasTask = struct {
        alias: checked.LocalProcedureBinding,
        use_expr: checked.CheckedExprId,
        expected_node: NodeId,
        /// The enclosing scope's instantiation and evidence, restored once
        /// the aliased callable is lowered. Boxed: an instantiation context
        /// is far larger than every task.
        saved: ?*SchemeAliasSavedScope = null,
    };

    const SchemeAliasSavedScope = struct {
        instantiation: TypeInstantiationContext,
        evidence: EvidenceChain,
    };

    /// A function value `Str.inspect` renders without consuming: the source
    /// expression still runs as a child, and its value is discarded.
    const InspectOnlyTask = struct {
        arg: checked.CheckedExprId,
        str_ty: Type.TypeId,
    };

    /// A structural equality or hash expression whose operands lower as
    /// child tasks.
    const DirectStructuralTask = struct {
        expr: checked.CheckedExprId,
        /// The context type the result is lowered at, checked against the
        /// result, or the checked result type lowered when the task starts.
        ret: union(enum) { context: Type.TypeId, checked: checked.CheckedTypeId },
        stage: enum { start, discriminant, lhs, rhs, hash_value, hash_hasher } = .start,
        ret_ty: Type.TypeId = undefined,
        /// The sealed operand type, or null when the operands are lowered
        /// at the deferred operand node.
        operand_ty: ?Type.TypeId = null,
        operand_node: NodeId = undefined,
        lhs: DraftExprId = undefined,
    };

    /// A string whose segments lower as child tasks, concatenated in order.
    const StrTask = struct {
        segments: []const checked.CheckedExprId,
        /// The cell the string's expression is built at; without one the
        /// task produces the string's expression data.
        cell: ?DraftTypeCell = null,
        index: usize = 0,
        out: DraftExprId = undefined,
    };

    /// A field access whose receiver lowers as a child task, so nested
    /// receivers never nest native lowering calls.
    const FieldAccessTask = struct {
        expr: checked.CheckedExprId,
        /// The node the access is lowered at, or, for an optional chain at a
        /// sealed type, its `Try` type.
        target: union(enum) { node: NodeId, try_ty: Type.TypeId },
        started: bool = false,
        optional: bool = false,
        receiver_node: NodeId = undefined,
        receiver_ty: Type.TypeId = undefined,
        result_node: NodeId = undefined,
        segments_start: u32 = 0,
    };

    /// A block whose statements and final expression lower as child tasks,
    /// so nested blocks never nest native lowering calls.
    const BlockTask = struct {
        statements: []const checked.CheckedStatementId,
        final_expr: checked.CheckedExprId,
        /// The cell the block's own expression is built at.
        result_cell: DraftTypeCell,
        /// What the block produces after its statements.
        tail: BlockTail = .value,
        /// Lowering at a sealed type rather than at a cell:
        /// the block's final expression and value use the type directly.
        typed: ?Type.TypeId = null,
        /// Produce a typed block's expression data rather than its expression.
        as_data: bool = false,
        result_node: NodeId = undefined,
        stage: enum { start, statements, statement, uninhabited_statement, expanded, recursive_direct, final_expr, discarded_final, finished } = .start,
        saved_guard_frames: RuntimeDemandGuardFrameStack = undefined,
        lowered: LoweredStatements = .{ .items = &.{}, .len = 0, .termination = .none },
        index: usize = 0,
        /// The statement whose value is lowering as a child.
        statement: checked.CheckedStatementId = undefined,
        statement_start: usize = 0,
        statement_diverges: bool = false,
        statement_saved: ?SavedSourceLocation = null,
        /// A pattern statement expanded into several block statements.
        expanded: ExpandedPatternStatement = undefined,
        /// The binders an expanded stateful pattern statement reassigns. Owned.
        expanded_merge_binders: []MergeBinder = &.{},
        recursive_binders: []checked.PatternBinderId = &.{},
        recursive_locals: []DraftLocalId = &.{},
        recursive_direct_pat: DraftPatId = undefined,
        recursive_direct_cell: DraftTypeCell = undefined,
        /// The cell of the zero-branch match consuming a proven-uninhabited
        /// final value's scrutinee.
        final_wrap: ?DraftTypeCell = null,
    };

    /// What a block produces after its statements.
    const BlockTail = union(enum) {
        /// Its final expression's value.
        value,
        /// Its final expression as a discarded statement, then the loop's
        /// continue edge: carrying the iterator's rest when there is one.
        loop_continue: struct { rest_expr: ?DraftExprId, carries: []const LoopCarry },
        /// Its final expression as a discarded statement, then the state of
        /// the binders it reassigns.
        state_only: @FieldType(BranchOutput, "state_only"),
        /// Its final expression's value paired with the state of the
        /// binders it reassigns.
        state_result: struct { state: @FieldType(BranchOutput, "state_result"), result_node: NodeId },
    };

    /// A pattern statement that binds several block statements rather than
    /// one: a statement-position `if`/`match`/`for` that also reassigns
    /// surrounding binders, or a record destructure with an explicit rest or
    /// an optional field.
    const ExpandedPatternStatement = union(enum) {
        stateful: struct {
            pattern: checked.CheckedPatternId,
            value_cell: DraftTypeCell,
            state_cell: DraftTypeCell,
        },
        record: struct {
            pattern: checked.CheckedPatternId,
            destructs: []const checked.CheckedRecordDestruct,
            value_node: NodeId,
            value_cell: DraftTypeCell,
        },
    };

    /// An `if` whose conditions and branch bodies lower as child tasks, so
    /// nested conditionals never nest native lowering calls.
    const IfTask = struct {
        expr_id: checked.CheckedExprId,
        if_: @FieldType(checked.CheckedExprData, "if_"),
        result_cell: DraftTypeCell,
        /// What each branch produces; null lowers the `if` as a value,
        /// merging any state it reassigns. A value output selects one
        /// runtime representation from every branch unless `select` is false.
        output: ?BranchOutput = null,
        select: bool = true,
        stage: enum { start, cond, body, else_body } = .start,
        comptime_site: ?DraftComptimeSiteId = null,
        selection: ControlFlowResultSelection = undefined,
        branches: []DraftIfBranch = &.{},
        index: usize = 0,
        /// The context the branch body in progress lowers in.
        branch_ctx: ?*BodyContext = null,
        /// The reassigned binders a value `if` merges. Owned.
        merge_binders: []MergeBinder = &.{},
        /// The state tuple cell unwrapped into the value once the `if` is built.
        unwrap_state: ?DraftTypeCell = null,
    };

    fn releaseIfTask(self: *BodyContext, task: *IfTask) void {
        if (task.branch_ctx) |branch_ctx| {
            branch_ctx.deinit();
            self.allocator.destroy(branch_ctx);
            task.branch_ctx = null;
        }
        self.allocator.free(task.branches);
        task.branches = &.{};
        self.allocator.free(task.merge_binders);
        task.merge_binders = &.{};
    }

    fn createBranchContext(self: *BodyContext) Allocator.Error!*BodyContext {
        const branch_ctx = try self.allocator.create(BodyContext);
        errdefer self.allocator.destroy(branch_ctx);
        branch_ctx.* = try self.childContext(self.current_fn_key);
        return branch_ctx;
    }

    fn destroyBranchContext(self: *BodyContext, slot: *?*BodyContext) void {
        const branch_ctx = slot.* orelse return;
        branch_ctx.deinit();
        self.allocator.destroy(branch_ctx);
        slot.* = null;
    }

    /// Lower a branch body in `branch_ctx` for its output, as a child task.
    fn branchBodyStep(branch_ctx: *BodyContext, body: checked.CheckedExprId, output: BranchOutput) LowerStep {
        return requestLowerTask(branch_ctx, .{ .branch_body = .{ .body = body, .output = output } });
    }

    /// The output a control-flow branch lowers for: the shared selected
    /// representation of a selecting value output, else the output itself.
    fn controlFlowBranchOutput(output: BranchOutput, select: bool, selection: ControlFlowResultSelection) BranchOutput {
        return if (select) .{ .value = selection.selected } else output;
    }

    /// Decide how a control-flow expression lowered as a value produces it:
    /// directly with a selected representation, or, when it reassigns
    /// surrounding binders, as a state tuple unwrapped into the value.
    fn beginControlFlowValueOutput(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        result_cell: DraftTypeCell,
        merge_binders: *[]MergeBinder,
        select: *bool,
        unwrap_state: *?DraftTypeCell,
    ) Allocator.Error!BranchOutput {
        merge_binders.* = try self.stateMergeBinders(expr_id);
        if (merge_binders.len == 0) return .{ .value = result_cell };
        const state_cell = try self.stateResultTypeCell(merge_binders.*, result_cell);
        select.* = false;
        unwrap_state.* = state_cell;
        return .{ .state_result = .{
            .result_cell = result_cell,
            .state_cell = state_cell,
            .merge_binders = merge_binders.*,
        } };
    }

    fn stepIf(self: *BodyContext, task: *IfTask, input: ?LowerResult) Allocator.Error!LowerStep {
        const if_ = task.if_;
        switch (task.stage) {
            .start => {
                task.comptime_site = try self.ifComptimeSite(task.expr_id, if_);
                if (task.output == null) {
                    task.output = try self.beginControlFlowValueOutput(
                        task.expr_id,
                        task.result_cell,
                        &task.merge_binders,
                        &task.select,
                        &task.unwrap_state,
                    );
                }
                if (task.select) {
                    task.selection = .{
                        .declared = task.result_cell,
                        .selected = task.result_cell,
                    };
                    // Conditions do not bind names visible in branch bodies, so all result
                    // producers can contribute their representation evidence up front.
                    // Branch emission below then consumes one settled request.
                    for (if_.branches) |branch| {
                        try self.prepareControlFlowResultSelection(&task.selection, branch.body);
                    }
                    try self.prepareControlFlowResultSelection(&task.selection, if_.final_else);
                }
                task.branches = try self.allocator.alloc(DraftIfBranch, if_.branches.len);
            },
            .cond => {
                task.branches[task.index].cond = input.?.exprValue();
                task.branch_ctx = try self.createBranchContext();
                task.stage = .body;
                return branchBodyStep(
                    task.branch_ctx.?,
                    if_.branches[task.index].body,
                    controlFlowBranchOutput(task.output.?, task.select, task.selection),
                );
            },
            .body => try self.finishIfBranch(task, input.?.exprValue()),
            .else_body => return self.finishIf(task, input.?.exprValue()),
        }

        if (task.index < if_.branches.len) {
            task.stage = .cond;
            return requestLowerTask(self, .{ .expr = .{ .expr = if_.branches[task.index].cond } });
        }
        task.branch_ctx = try self.createBranchContext();
        task.stage = .else_body;
        return branchBodyStep(
            task.branch_ctx.?,
            if_.final_else,
            controlFlowBranchOutput(task.output.?, task.select, task.selection),
        );
    }

    fn finishIfBranch(self: *BodyContext, task: *IfTask, body: DraftExprId) Allocator.Error!void {
        const branch_ctx = task.branch_ctx.?;
        task.branches[task.index].body = try branch_ctx.wrapComptimeBranch(task.comptime_site, task.index, body);
        if (task.select) try self.includeControlFlowResult(&task.selection, task.branches[task.index].body);
        self.destroyBranchContext(&task.branch_ctx);
        task.index += 1;
    }

    fn finishIf(self: *BodyContext, task: *IfTask, else_body: DraftExprId) Allocator.Error!LowerStep {
        const final_else = try task.branch_ctx.?.wrapComptimeBranch(task.comptime_site, task.if_.branches.len, else_body);
        if (task.select) {
            try self.includeControlFlowResult(&task.selection, final_else);
            for (task.branches) |branch| {
                if (self.exprImpossibilityProof(branch.body) == null) {
                    self.draft.exprs.items[@backingInt(branch.body)].ty = task.selection.selected;
                }
            }
            if (self.exprImpossibilityProof(final_else) == null) {
                self.draft.exprs.items[@backingInt(final_else)].ty = task.selection.selected;
            }
        }
        const data: BodyExprData = .{ .if_ = .{
            .branches = try self.addIfBranchSpan(task.branches),
            .final_else = final_else,
        } };
        self.destroyBranchContext(&task.branch_ctx);
        if (task.select) {
            return loweredExprStep(try self.addExprWithTypeCell(
                try self.finishControlFlowResultSelection(task.selection),
                data,
            ));
        }
        return self.finishControlFlowOutput(task.output.?, task.unwrap_state, task.result_cell, task.merge_binders, data);
    }

    /// Build a non-selecting control-flow expression at its output's cell,
    /// unwrapping a value `if`/`match`'s state tuple into its value.
    fn finishControlFlowOutput(
        self: *BodyContext,
        output: BranchOutput,
        unwrap_state: ?DraftTypeCell,
        result_cell: DraftTypeCell,
        merge_binders: []const MergeBinder,
        data: BodyExprData,
    ) Allocator.Error!LowerStep {
        const expr = try self.addExprWithTypeCell(self.branchOutputCell(output), data);
        const state_cell = unwrap_state orelse return loweredExprStep(expr);
        return loweredExprStep(try self.unwrapStateResultAtTypeCells(expr, state_cell, result_cell, merge_binders));
    }

    /// A `match` whose guards, branch bodies, and scrutinee lower as child
    /// tasks, so nested matches never nest native lowering calls.
    const MatchTask = struct {
        expr_id: checked.CheckedExprId,
        match: @FieldType(checked.CheckedExprData, "match_"),
        result_cell: DraftTypeCell,
        /// What each branch produces; null lowers the `match` as a value,
        /// merging any state it reassigns. A value output selects one
        /// runtime representation from every branch unless `select` is false.
        output: ?BranchOutput = null,
        select: bool = true,
        stage: enum { start, guard, body, scrutinee, divergent } = .start,
        comptime_site: ?DraftComptimeSiteId = null,
        selection: ControlFlowResultSelection = undefined,
        scrutinee_node: NodeId = undefined,
        branches: []DraftBranch = &.{},
        pending: std.ArrayListUnmanaged(MatchPendingBranch) = .empty,
        index: usize = 0,
        /// The reassigned binders a value `match` merges. Owned.
        merge_binders: []MergeBinder = &.{},
        /// The state tuple cell unwrapped into the value once the `match` is built.
        unwrap_state: ?DraftTypeCell = null,
    };

    const MatchPendingBranch = struct {
        ctx: *BodyContext,
        pattern: checked.CheckedMatchBranchPattern,
        checked_guard: ?checked.CheckedExprId,
        checked_body: checked.CheckedExprId,
        source_index: usize,
        user_guard: ?DraftExprId = null,
        body: DraftExprId = undefined,
    };

    fn releaseMatchTask(self: *BodyContext, task: *MatchTask) void {
        for (task.pending.items) |entry| {
            entry.ctx.deinit();
            self.allocator.destroy(entry.ctx);
        }
        task.pending.deinit(self.allocator);
        task.pending = .empty;
        self.allocator.free(task.branches);
        task.branches = &.{};
        self.allocator.free(task.merge_binders);
        task.merge_binders = &.{};
    }

    fn stepMatch(self: *BodyContext, task: *MatchTask, input: ?LowerResult) Allocator.Error!LowerStep {
        const match = task.match;
        switch (task.stage) {
            .start => {
                // A divergent scrutinee never produces a value for a branch to
                // inspect: no pattern is observed at runtime, and the match is
                // exactly its scrutinee's divergence. Checking relates no branch
                // pattern to a scrutinee that always crashes, so those patterns
                // need not even agree with each other and must not be
                // instantiated here.
                if (try self.divergentExprInContextStep(match.cond, .{ .type_cell = task.result_cell })) |step| {
                    task.stage = .divergent;
                    return step;
                }
                task.comptime_site = try self.matchComptimeSite(task.expr_id, match);
                if (task.output == null) {
                    task.output = try self.beginControlFlowValueOutput(
                        task.expr_id,
                        task.result_cell,
                        &task.merge_binders,
                        &task.select,
                        &task.unwrap_state,
                    );
                }
                if (task.select) {
                    task.selection = .{
                        .declared = task.result_cell,
