                return requestLowerTask(self, .{ .loop = try self.boxLowerTask(LoopTask, .{ .kind = .{ .condition = .{ .loop = loop, .condition = .checked } } }) });
            },
            .infinite_loop, .breakable_loop => |loop| {
                task.stage = .loop;
