            },
            .break_ => return self.finishStatement(task, .{ .expr = try self.breakCurrentLoopExpr() }, .none),
            .return_ => |ret| {
                task.stage = .return_value;
                return requestLowerTask(self, .{ .return_value = .{ .expr = ret.expr, .lambda = ret.lambda, .context = .return_expr } });
