    }

    /// A divergent expression evaluates its operands in source order, each
    /// for its effect, up to the operand whose evaluation diverges; a
    /// dispatch that cannot run (`DispatchCrashReason`) evaluates all of its
    /// operands and then crashes. Every operand before the divergence point
    /// is observable, so none is skipped. Only the operands up to and
    /// including the first divergent one are listed: nothing after it runs.
    const OperandSequenceTask = struct {
        /// The operand expressions in evaluation order. Owned.
        operands: []const checked.CheckedExprId,
        ty: Type.TypeId,
        tail: OperandSequenceTail,
        index: usize = 0,
        stmts: std.ArrayList(DraftStmtId) = .empty,
    };

    const OperandSequenceTail = union(enum) {
        /// The last operand diverges.
        diverges,
        /// The dispatch crashes once every operand has evaluated.
        dispatch_crash: DispatchCrashReason,
        /// A retired expression crashes with the checked runtime error once
        /// every operand it still evaluates has evaluated.
        runtime_error,
    };

    fn releaseOperandSequenceTask(self: *BodyContext, task: *OperandSequenceTask) void {
        self.allocator.free(task.operands);
        task.operands = &.{};
        task.stmts.deinit(self.allocator);
        task.stmts = .empty;
    }

    /// The operands of a divergent expression whose evaluation diverges at
    /// one of them: every operand up to and including the first divergent
    /// one, in evaluation order.
    fn divergentOperandsStep(self: *BodyContext, operands: []const checked.CheckedExprId, ty: Type.TypeId) Allocator.Error!LowerStep {
        const len = for (operands, 0..) |operand, index| {
            if (self.checkedExprDivergesInLoweredRuntime(operand)) break index + 1;
        } else Common.invariant("checked expression was marked divergent but no divergent operand was found");
        return requestLowerTask(self, .{ .operand_sequence = .{
            .operands = try self.allocator.dupe(checked.CheckedExprId, operands[0..len]),
            .ty = ty,
            .tail = .diverges,
        } });
    }

    /// The source expressions a dispatch's operands evaluate, in evaluation
    /// order. An interpolation's generated segments operand
    /// evaluates the interpolation's segments and values; a generated numeral or quote
    /// operand is literal source text with nothing to evaluate. Owned.
    fn dispatchOperandExprs(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
    ) Allocator.Error![]const checked.CheckedExprId {
        var exprs: std.ArrayList(checked.CheckedExprId) = .empty;
        errdefer exprs.deinit(self.allocator);
        for (plan.argsSlice(self.view.static_dispatch_plans)) |operand| switch (operand) {
            .checked_expr => |expr| try exprs.append(self.allocator, expr),
            .generated_interpolation_segments => |expr| {
                const interpolation = switch (self.view.bodies.expr(expr).data) {
                    .interpolation => |value| value,
                    .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("dispatch interpolation segments referenced a non-interpolation expression"),
                };
                try appendInterpolationOperands(self.allocator, &exprs, interpolation);
            },
            .generated_numeral, .generated_quote => {},
        };
        return try exprs.toOwnedSlice(self.allocator);
    }

    fn appendInterpolationOperands(
        allocator: Allocator,
        exprs: *std.ArrayList(checked.CheckedExprId),
        interpolation: checked.CheckedInterpolation,
    ) Allocator.Error!void {
        try exprs.append(allocator, interpolation.segments[0]);
        for (interpolation.values, interpolation.segments[1..]) |value, segment| {
            try exprs.append(allocator, value);
            try exprs.append(allocator, segment);
        }
    }

    fn stepOperandSequence(self: *BodyContext, task: *OperandSequenceTask, input: ?LowerResult) Allocator.Error!LowerStep {
        if (input) |result| {
            const lowered = result.statementValue();
            if (lowered.stmt) |stmt| try task.stmts.append(self.allocator, stmt);
            switch (lowered.termination) {
                .none => {},
                .checked_control_transfer => return try self.finishOperandSequence(task, try self.unreachableAfterTerminatingStatementExpr(task.ty)),
                .uninhabited => |scrutinee| return try self.finishOperandSequence(task, try self.zeroBranchMatch(scrutinee, task.ty)),
            }
        }
        if (task.index < task.operands.len) {
            const operand = task.operands[task.index];
            task.index += 1;
            return requestLowerTask(self, .{ .discarded = .{ .expr = operand } });
        }
        return switch (task.tail) {
            .diverges => Common.invariant("divergent operand sequence ended without diverging"),
            .dispatch_crash => |reason| try self.finishOperandSequence(task, try self.addExpr(.{
                .ty = task.ty,
                .data = try self.dispatchCrashData(reason),
            })),
            .runtime_error => try self.finishOperandSequence(task, try self.addExpr(.{
                .ty = task.ty,
                .data = .{ .checked_error = try self.addStringLiteral("runtime error") },
            })),
        };
    }

    fn finishOperandSequence(self: *BodyContext, task: *OperandSequenceTask, final_expr: DraftExprId) Allocator.Error!LowerStep {
        return .{ .ret = .{ .data = .{ .block = .{
            .statements = try self.addStmtSpan(task.stmts.items),
            .final_expr = final_expr,
        } } } };
    }

    fn divergentEffectStep(self: *BodyContext, child: checked.CheckedExprId, ty: Type.TypeId) LowerStep {
        return divergentStep(self, child, .{ .effect_data = ty });
    }

    fn divergentDataStep(self: *BodyContext, task: *DivergentTask, checked_expr: checked.CheckedExpr, ty: Type.TypeId) Allocator.Error!LowerStep {
        const expr_id = task.expr;
        const data: BodyExprData = switch (checked_expr.data) {
            .crash => |msg| .{ .crash = try self.lowerStringLiteral(msg) },
            .runtime_error => |runtime_error| if (runtime_error.evaluated.len != 0)
                // A retired expression evaluates the operands it still
                // evaluates, each for its effects, then crashes.
                return requestLowerTask(self, .{ .operand_sequence = .{
                    .operands = try self.allocator.dupe(checked.CheckedExprId, runtime_error.evaluated),
                    .ty = ty,
                    .tail = .runtime_error,
                } })
            else
                .{ .checked_error = try self.addStringLiteral("runtime error") },
            .ellipsis => .{ .crash = try self.addStringLiteral("not implemented") },
            .break_ => try self.breakCurrentLoopExprData(),
            .return_ => |ret| return requestLowerTask(self, .{ .return_value = .{ .expr = ret.expr, .lambda = ret.lambda, .context = ret.context } }),
            .expect_err => |expect_err| {
                task.finish = .{ .expect_err = checked_expr.source_region };
                return requestLowerTask(self, .{ .inspected = .{ .expr = expect_err.expr, .expect_err_snippet = expect_err.snippet } });
            },
            .str, .list, .tuple => |items| return try self.divergentOperandsStep(items, ty),
            .block => |block| return requestLowerTask(self, .{ .block = try self.boxLowerTask(BlockTask, .{
                .statements = block.statements,
                .final_expr = block.final_expr,
                .result_cell = .{ .sealed = ty },
                .typed = ty,
                .as_data = true,
            }) }),
            .match_ => |match| {
                task.finish = .expr_as_data;
                return requestLowerTask(self, .{ .match_task = .{ .expr_id = expr_id, .match = match, .result_cell = .{ .sealed = ty } } });
            },
            .if_ => |if_| {
                task.finish = .expr_as_data;
                return requestLowerTask(self, .{ .if_task = .{ .expr_id = expr_id, .if_ = if_, .result_cell = .{ .sealed = ty } } });
            },
            .call => |call| {
                var operands: std.ArrayList(checked.CheckedExprId) = .empty;
                defer operands.deinit(self.allocator);
                try operands.append(self.allocator, call.func);
                try operands.appendSlice(self.allocator, call.args);
                return try self.divergentOperandsStep(operands.items, ty);
            },
            .record => |record| {
                var operands: std.ArrayList(checked.CheckedExprId) = .empty;
                defer operands.deinit(self.allocator);
                if (record.ext) |ext| try operands.append(self.allocator, ext);
                for (record.fields) |field| try operands.append(self.allocator, field.value);
                return try self.divergentOperandsStep(operands.items, ty);
            },
            .tag => |tag| return try self.divergentOperandsStep(tag.args, ty),
            .nominal => |nominal| return self.divergentEffectStep(nominal.backing_expr, ty),
            .binop => |binop| return try self.divergentOperandsStep(&.{ binop.lhs, binop.rhs }, ty),
            .unary_minus,
            .unary_not,
            .dbg,
            => |child| return self.divergentEffectStep(child, ty),
            .expect => |child| if (self.builder.inline_expects == .run)
                return self.divergentEffectStep(child, ty)
            else
                Common.invariant("omitted checked expect reached divergent runtime lowering"),
            .field_access => |field| return self.divergentEffectStep(field.receiver, ty),
            .structural_eq => |eq| return try self.divergentOperandsStep(&.{ eq.lhs, eq.rhs }, ty),
            .structural_hash => |hash| return try self.divergentOperandsStep(&.{ hash.value, hash.hasher }, ty),
            .tuple_access => |access| return self.divergentEffectStep(access.tuple, ty),
            .for_ => |for_| return self.divergentEffectStep(for_.expr, ty),
            .run_low_level => |low_level| {
                for (low_level.args) |arg| {
                    if (self.checkedExprDivergesInLoweredRuntime(arg)) return try self.divergentOperandsStep(low_level.args, ty);
                }
                if (low_level.op != .crash) {
                    Common.invariant("checked low-level expression was marked divergent but no divergent argument was found");
                }
                task.finish = .{ .low_level = low_level.op };
                return requestLowerTask(self, .{ .span = .{ .exprs = low_level.args } });
            },
            .dispatch_call => |plan| return try self.divergentDispatchStep(plan, ty),
            .interpolation => |interpolation| {
                var operands: std.ArrayList(checked.CheckedExprId) = .empty;
                defer operands.deinit(self.allocator);
                try appendInterpolationOperands(self.allocator, &operands, interpolation);
                return try self.divergentOperandsStep(operands.items, ty);
            },
            .method_eq, .type_dispatch_call => |plan| return try self.divergentDispatchStep(plan, ty),
            .numeral => |numeral| return try self.divergentDispatchStep(numeral.plan, ty),
            .str_from_quote => |quote| return try self.divergentDispatchStep(quote.plan, ty),
            .pending,
            .str_segment,
            .bytes_literal,
            .lookup_local,
            .lookup_external,
            .lookup_required,
            .empty_list,
            .empty_record,
            .zero_argument_tag,
            .closure,
            .lambda,
            .anno_only,
            .hosted_lambda,
            => Common.invariant("non-divergent checked expression reached divergent lowering"),
        };
        return .{ .ret = .{ .data = data } };
    }

    fn divergentDispatchStep(
        self: *BodyContext,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        ty: Type.TypeId,
    ) Allocator.Error!LowerStep {
        const plan_id = maybe_plan orelse Common.invariant("divergent checked dispatch expression did not contain its checked plan");
        const plan = self.view.static_dispatch_plans.plans[@backingInt(plan_id)];
        const operands = try self.dispatchOperandExprs(plan);
        defer self.allocator.free(operands);
        return switch (self.dispatchRuntimePlan(plan)) {
            .callable => try self.divergentOperandsStep(operands, ty),
            .crash => |reason| requestLowerTask(self, .{ .operand_sequence = .{
                .operands = try self.allocator.dupe(checked.CheckedExprId, operands),
                .ty = ty,
                .tail = .{ .dispatch_crash = reason },
            } }),
        };
    }

    /// A `for` loop's checked fields, shared by its statement and expression
    /// forms.
    const CheckedForLoop = struct {
        pattern: checked.CheckedPatternId,
        expr: checked.CheckedExprId,
        body: checked.CheckedExprId,
        plan: ?static_dispatch.IteratorForPlanId,
        mutations: ?checked.LoopMutationPlanId,
    };

    fn checkedForLoop(for_: anytype) CheckedForLoop {
        return .{
            .pattern = for_.pattern,
            .expr = for_.expr,
            .body = for_.body,
            .plan = for_.plan,
            .mutations = for_.mutations,
        };
    }

    /// A loop statement whose iterator dispatches, condition, and body lower
    /// as child tasks, so nested loops never nest native lowering calls. Both
    /// source loop forms bind their exit state in the enclosing
    /// continuation; the task produces that binding statement.
    const LoopTask = struct {
        kind: union(enum) {
            for_: CheckedForLoop,
            condition: struct { loop: checked.CheckedConditionLoop, condition: WhileCondition },
        },
        stage: union(enum) { start, crashing_iter: DispatchCrashReason, initial_iterator, step_expr, one_body, cond, body } = .start,
        carries: []LoopCarry = &.{},
        loop_cell: DraftTypeCell = undefined,
        /// The binder mappings the loop parameters replace.
        saved: std.ArrayList(BinderRestore) = .empty,
        binders_replaced: bool = false,
        loop_context_pushed: bool = false,
        plan: static_dispatch.IteratorForPlan = undefined,
        iterator_cell: DraftTypeCell = undefined,
        iterator_param: DraftTypedLocal = undefined,
        initial_iterator: DraftExprId = undefined,
        step: IterStepShape = undefined,
        step_expr: DraftExprId = undefined,
        done_body: DraftExprId = undefined,
        branches: [3]DraftBranch = undefined,
        /// The binder mappings the `One` branch's pattern and carries replace.
        one_saved: std.ArrayList(BinderRestore) = .empty,
        one_scope_entered: bool = false,
        one_guard_frames: RuntimeDemandGuardFrameStack = undefined,
        one_tag_pat: DraftPatId = undefined,
        cond: DraftExprId = undefined,
        break_body: DraftExprId = undefined,
    };

    fn releaseLoopTask(self: *BodyContext, task: *LoopTask) void {
        self.leaveIteratorOneScope(task);
        task.one_saved.deinit(self.allocator);
        task.one_saved = .empty;
        self.leaveLoopScope(task);
        task.saved.deinit(self.allocator);
        task.saved = .empty;
        self.allocator.free(task.carries);
        task.carries = &.{};
    }

    /// Map each carried binder to its loop parameter and make the loop the
    /// current `break` target.
    fn enterLoopScope(self: *BodyContext, task: *LoopTask) Allocator.Error!void {
        for (task.carries) |carry| {
            try self.saveBinder(carry.binder, &task.saved);
            try self.binders.put(carry.binder, carry.param_local);
        }
        task.binders_replaced = true;
        try self.pushLoopContext(task.loop_cell, task.carries);
        task.loop_context_pushed = true;
    }

    fn leaveLoopScope(self: *BodyContext, task: *LoopTask) void {
        if (task.loop_context_pushed) {
            self.popLoopContext();
            task.loop_context_pushed = false;
        }
        if (task.binders_replaced) {
            self.restoreBinders(task.saved.items);
            task.binders_replaced = false;
        }
    }

    fn leaveIteratorOneScope(self: *BodyContext, task: *LoopTask) void {
        if (!task.one_scope_entered) return;
        self.runtime_demand_guard_frames = task.one_guard_frames;
        self.restoreBinders(task.one_saved.items);
        task.one_scope_entered = false;
    }

    fn stepLoop(self: *BodyContext, task: *LoopTask, input: ?LowerResult) Allocator.Error!LowerStep {
        switch (task.stage) {
            .start => {
                const mutations = switch (task.kind) {
                    .for_ => |for_| for_.mutations,
                    .condition => |condition| condition.loop.mutations,
                };
                task.carries = try self.prepareLoopCarries(mutations);
                task.loop_cell = try self.loopStateTypeCell(try self.unitType(), task.carries);
                switch (task.kind) {
                    .for_ => |for_| {
                        const plan_id = for_.plan orelse Common.invariant("checked iterator for reached Monotype without an iterator dispatch plan");
                        task.plan = self.view.static_dispatch_plans.iterator_for_plans[@backingInt(plan_id)];
                        // An `iter` call that cannot run evaluates the
                        // iterable it receives and then crashes; a `next`
                        // call that cannot run crashes once `iter` has
                        // produced the iterator it receives
                        // (`initial_iterator`).
                        if (self.dispatchCrashReason(task.plan.iter.resolution)) |reason| {
                            task.stage = .{ .crashing_iter = reason };
                            return requestLowerTask(self, .{ .discarded = .{ .expr = task.plan.iterable } });
                        }
                        task.stage = .initial_iterator;
                        return self.iteratorDispatchStep(.{
                            .plan = task.plan.iter,
                            .loop_iterator = null,
                            .expected_ret_ty = null,
                        });
                    },
                    .condition => |condition| {
                        try self.enterLoopScope(task);
                        // Checked entry edges observe the loop parameters at the start of an
                        // iteration. Lower both the condition and its false-edge result before
                        // the body, whose branch merges replace binder mappings with post-body
                        // locals used only by the continuation edge.
                        switch (condition.condition) {
                            .checked => {
                                task.stage = .cond;
                                return requestLowerTask(self, .{ .expr = .{ .expr = condition.loop.cond } });
                            },
                            .always_true => return try self.beginConditionLoopBody(task),
                        }
                    },
                }
            },
            .crashing_iter => |reason| {
                const lowered = input.?.statementValue();
                var statement_buf: [1]DraftStmtId = undefined;
                const statements: []const DraftStmtId = if (lowered.stmt) |stmt| blk: {
                    statement_buf[0] = stmt;
                    break :blk statement_buf[0..1];
                } else &.{};
                const final_expr = switch (lowered.termination) {
                    .none => try self.addExprWithTypeCell(task.loop_cell, try self.dispatchCrashData(reason)),
                    .checked_control_transfer => try self.addExprWithTypeCell(task.loop_cell, .@"unreachable"),
                    .uninhabited => |scrutinee| try self.zeroBranchMatchAtTypeCell(scrutinee, task.loop_cell),
                };
                return self.finishLoop(task, .{ .block = .{
                    .statements = try self.addStmtSpan(statements),
                    .final_expr = final_expr,
                } });
            },
            .initial_iterator => {
                const plan = task.plan;
                if (self.dispatchCrashReason(plan.next.resolution)) |reason| {
                    const iterator_stmt = try self.addStmt(.{ .expr = input.?.exprValue() });
                    return self.finishLoop(task, .{ .block = .{
                        .statements = try self.addStmtSpan(&.{iterator_stmt}),
                        .final_expr = try self.addExprWithTypeCell(task.loop_cell, try self.dispatchCrashData(reason)),
                    } });
                }
                task.initial_iterator = input.?.exprValue();
                task.iterator_cell = self.exprTypeCell(task.initial_iterator);
                try self.constrainCheckedInterfaceToCell(plan.iterator_ty, task.iterator_cell);
                task.step = try self.iteratorStepShape(plan, task.iterator_cell);
                try self.constrainCheckedInterfaceToCell(plan.iterator_ty, DraftTypeCell.fromGraphNode(task.step.one_rest.node));
                try self.constrainCheckedInterfaceToCell(plan.iterator_ty, DraftTypeCell.fromGraphNode(task.step.skip_rest.node));
                try self.constrainCheckedInterfaceToCell(plan.item_ty, DraftTypeCell.fromGraphNode(task.step.one_item.node));
                const iterator_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), task.iterator_cell, null);
                task.iterator_param = .{ .local = iterator_local, .ty = task.iterator_cell };
                try self.enterLoopScope(task);
                task.stage = .step_expr;
                return self.iteratorDispatchStep(.{
                    .plan = plan.next,
                    .loop_iterator = task.iterator_param,
                    .expected_ret_ty = DraftTypeCell.fromGraphNode(task.step.step_node),
                });
            },
            .step_expr => {
                task.step_expr = input.?.exprValue();
                try self.constrainCheckedInterfaceToCell(task.plan.step_ty, self.exprTypeCell(task.step_expr));
                task.done_body = if (task.carries.len == 0)
                    try self.addExprWithTypeCell(task.loop_cell, .{ .break_ = null })
                else
                    try self.addExprWithTypeCell(task.loop_cell, .{ .break_ = try self.loopStateExpr(task.loop_cell, task.carries) });
                task.branches[0] = .{
                    .pat = try self.iteratorDonePattern(task.step),
                    .body = task.done_body,
                };
                if (try self.nodeIsProvenUninhabited(task.step.one_item.node)) {
                    task.branches[1] = try self.uninhabitedIteratorOneBranch(task.step, task.done_body);
                    return self.finishIteratorLoop(task);
                }
                return self.beginIteratorOneBranch(task);
            },
            .one_body => {
                task.branches[1] = .{ .pat = task.one_tag_pat, .body = input.?.exprValue() };
                self.leaveIteratorOneScope(task);
                return self.finishIteratorLoop(task);
            },
            .cond => {
                task.cond = input.?.exprValue();
                task.break_body = try self.breakCurrentLoopExpr();
                return try self.beginConditionLoopBody(task);
            },
            .body => return self.finishConditionLoop(task, input.?.exprValue()),
        }
    }

    /// A loop body lowered as statements whose final expression is
    /// discarded, then the loop's continue edge.
    fn loopBodyStep(self: *BodyContext, body: checked.CheckedExprId, result_cell: DraftTypeCell, rest_expr: ?DraftExprId, carries: []const LoopCarry) Allocator.Error!LowerStep {
        return requestLowerTask(self, .{ .block = try self.boxDiscardingBlockTask(body, result_cell, .{ .loop_continue = .{
            .rest_expr = rest_expr,
            .carries = carries,
        } }) });
    }

    fn beginIteratorOneBranch(self: *BodyContext, task: *LoopTask) Allocator.Error!LowerStep {
        const for_ = task.kind.for_;
        const step = task.step;
        try self.savePatternBinders(for_.pattern, &task.one_saved);
        for (task.carries) |carry| try self.saveBinder(carry.binder, &task.one_saved);
        task.one_guard_frames = self.runtime_demand_guard_frames;
        task.one_scope_entered = true;

        const item_cell = DraftTypeCell.fromGraphNode(step.one_item.node);
        try self.constrainCheckedInterfaceToCell(self.view.bodies.pattern(for_.pattern).ty, item_cell);
        self.runtime_demand_guard_frames = try self.withIteratorOneRuntimeDemandGuardFrame(for_.pattern, step);

        const rest_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), task.iterator_cell, null);
        const item_local: ?DraftLocalId = if (try self.patternNeedsExplicitBinding(for_.pattern))
            try self.addLocalWithBinderCell(self.builder.symbols.fresh(), item_cell, null)
        else
            null;
        const record_pat = try self.iteratorOnePayloadPattern(for_.pattern, step, task.iterator_cell, rest_local, item_local);
        task.one_tag_pat = try self.addPatWithTypeCell(DraftTypeCell.fromGraphNode(step.step_node), .{ .tag = .{
            .name = try self.tagName(self.view, step.one_tag),
            .payloads = try self.addPatSpan(&[_]DraftPatId{record_pat}),
        } });

        const rest_expr = try self.addExprWithTypeCell(task.iterator_cell, .{ .local = rest_local });
        task.stage = .one_body;
        const local = item_local orelse return try self.loopBodyStep(for_.body, task.loop_cell, rest_expr, task.carries);
        const item_expr = try self.addExprWithTypeCell(item_cell, .{ .local = local });
        const miss = try self.addExprWithTypeCell(task.loop_cell, .{ .crash = try self.addStringLiteral("pattern match failed") });
        return requestLowerTask(self, .{ .materialize = .{ .root = .{
            .pattern = for_.pattern,
            .value = item_expr,
            .value_cell = item_cell,
            .result_cell = task.loop_cell,
            .continuation = .{ .iterator_body = .{
                .body = for_.body,
                .result_cell = task.loop_cell,
                .rest_expr = rest_expr,
                .carries = task.carries,
            } },
            .miss = miss,
            .success_guard = null,
            .mode = .then_root,
        } } });
    }

    fn finishIteratorLoop(self: *BodyContext, task: *LoopTask) Allocator.Error!LowerStep {
        const carries = task.carries;
        task.branches[2] = try self.iteratorSkipBranch(task.loop_cell, task.step, task.iterator_cell, carries);

        const match_expr = try self.addExprWithTypeCell(task.loop_cell, .{ .match_ = .{
            .scrutinee = task.step_expr,
            .branches = try self.addBranchSpan(&task.branches),
        } });

        const params = try self.allocator.alloc(DraftTypedLocal, 1 + carries.len);
        defer self.allocator.free(params);
        params[0] = task.iterator_param;
        for (carries, 0..) |carry, i| params[i + 1] = .{ .local = carry.param_local, .ty = carry.ty };

        const initial_values = try self.allocator.alloc(DraftExprId, 1 + carries.len);
        defer self.allocator.free(initial_values);
        initial_values[0] = task.initial_iterator;
        for (carries, 0..) |carry, i| {
            initial_values[i + 1] = try self.addExprWithTypeCell(carry.ty, .{ .local = carry.initial_local });
        }

        return self.finishLoop(task, .{ .loop_ = .{
            .params = try self.draft.addTypedLocalSpan(params),
            .initial_values = try self.addExprSpan(initial_values),
            .body = match_expr,
        } });
    }

    fn beginConditionLoopBody(self: *BodyContext, task: *LoopTask) Allocator.Error!LowerStep {
        task.stage = .body;
        return try self.loopBodyStep(task.kind.condition.loop.body, task.loop_cell, null, task.carries);
    }

    fn finishConditionLoop(self: *BodyContext, task: *LoopTask, continue_body: DraftExprId) Allocator.Error!LowerStep {
        const carries = task.carries;
        const body = switch (task.kind.condition.condition) {
            .always_true => continue_body,
            .checked => blk: {
                const branches = [_]DraftIfBranch{.{ .cond = task.cond, .body = continue_body }};
                break :blk try self.addExprWithTypeCell(task.loop_cell, .{ .if_ = .{
                    .branches = try self.addIfBranchSpan(&branches),
                    .final_else = task.break_body,
                } });
            },
        };

        const params = try self.allocator.alloc(DraftTypedLocal, carries.len);
        defer self.allocator.free(params);
        for (carries, 0..) |carry, i| params[i] = .{ .local = carry.param_local, .ty = carry.ty };

        const initial_values = try self.allocator.alloc(DraftExprId, carries.len);
        defer self.allocator.free(initial_values);
        for (carries, 0..) |carry, i| {
            initial_values[i] = try self.addExprWithTypeCell(carry.ty, .{ .local = carry.initial_local });
        }

        return self.finishLoop(task, .{ .loop_ = .{
            .params = try self.draft.addTypedLocalSpan(params),
            .initial_values = try self.addExprSpan(initial_values),
            .body = body,
        } });
    }

    /// Build the loop expression once its scope is left, and the statement
    /// binding its exit state.
    fn finishLoop(self: *BodyContext, task: *LoopTask, data: BodyExprData) Allocator.Error!LowerStep {
        self.leaveLoopScope(task);
        const expr = try self.addExprWithTypeCell(task.loop_cell, data);
        const stmt = try self.loopExitStatement(expr, task.carries, task.loop_cell);
        return statementStep(.{ .stmt = try self.addStmt(stmt), .termination = .none });
    }

    /// An iterator method call whose operands lower
    /// as child tasks.
    const IteratorDispatchTask = struct {
        plan: static_dispatch.IteratorDispatchCall,
        loop_iterator: ?DraftTypedLocal,
        expected_ret_ty: ?DraftTypeCell,
        call_ctx: ?*BodyContext = null,
        /// The generated `Iter.iter`/`Iter.next` path's procedure and
        /// dispatcher node.
        generated: ?struct { procedure: checked.IteratorProcedureId, dispatcher_node: NodeId } = null,
        lookup: MethodLookup = undefined,
        callee: DraftFnSlot = undefined,
        ret_node: NodeId = undefined,
        arg_nodes: []const NodeId = &.{},
        /// Each lowered operand. Owned.
        args: []DraftExprId = &.{},
        index: usize = 0,
    };

    fn iteratorDispatchStep(self: *BodyContext, task: IteratorDispatchTask) Allocator.Error!LowerStep {
        const boxed = try self.allocator.create(IteratorDispatchTask);
        boxed.* = task;
        return requestLowerTask(self, .{ .iterator_dispatch = boxed });
    }

    fn releaseIteratorDispatchTask(self: *BodyContext, task: *IteratorDispatchTask) void {
        if (task.call_ctx) |call_ctx| self.destroyCallContext(call_ctx);
        task.call_ctx = null;
        self.allocator.free(task.args);
        task.args = &.{};
    }

    fn stepIteratorDispatch(self: *BodyContext, frame: *LowerFrame, task: *IteratorDispatchTask, input: ?LowerResult) Allocator.Error!LowerStep {
        const plan = task.plan;
        const plan_args = plan.argsSlice(self.view.static_dispatch_plans);
        if (frame.cursor != 0) {
            if (task.generated) |generated| return self.finishGeneratedIteratorDispatch(task, generated.procedure, generated.dispatcher_node, input.?.exprValue());
            task.args[task.index] = input.?.exprValue();
            task.index += 1;
            return self.nextIteratorDispatchOperand(task, plan_args);
        }
        frame.cursor = 1;
        if (plan.dispatcher_arg_index >= plan_args.len) Common.invariant("iterator dispatch plan dispatcher argument index was outside the argument span");

        const lookup = try self.withLocalProcContext(self.iteratorMethodLookup(plan));
        task.lookup = lookup;
        task.call_ctx = try self.createCallContext();
        const call_ctx = task.call_ctx.?;

        var callable_node = try call_ctx.instantiateIteratorPlanCallNodeFromCaller(plan.callable_ty, self, plan_args, task.loop_iterator, task.expected_ret_ty);
        const initial_plan_fn = try self.graph.functionNodes(callable_node);
        // Instantiating the caller-authored request completes any procedure
        // operands that return iterator evidence. Only then is the producer's
        // representation available for the generated Iter.iter/Iter.next path.
        if (self.iteratorProcedureForMethodTarget(lookup.target)) |procedure| {
            const dispatcher_node = initial_plan_fn.args[plan.dispatcher_arg_index];
            if ((procedure == .identity or procedure == .next) and (try self.isGeneratedIteratorEvidenceNode(dispatcher_node))) {
                try self.constrainCheckedInterfaceToCell(plan.dispatcher_ty, DraftTypeCell.fromGraphNode(dispatcher_node));
                task.generated = .{ .procedure = procedure, .dispatcher_node = dispatcher_node };
                switch (try self.iteratorOperandStep(plan_args[plan.dispatcher_arg_index], task.loop_iterator, dispatcher_node)) {
                    .now => |iterator| return self.finishGeneratedIteratorDispatch(task, procedure, dispatcher_node, iterator),
                    .child => |step| return step,
                }
            }
        }
        const target_node = try self.methodTargetNodeFromPlan(lookup, call_ctx, plan.callable_ty);
        try self.relateDispatchTargetRequestInterface(lookup, target_node, callable_node);
        if (try self.generatedIteratorPlanRequestNode(
            lookup,
            target_node,
            callable_node,
            plan_args,
        )) |private_node| {
            callable_node = private_node;
        }
        // The generated request owns the operand slots used to lower this
        // call. Completing the callee may replace the callable result, but it
        // must not move these request-authored operands.
        const plan_fn = try self.graph.functionNodes(callable_node);
        task.callee = try self.methodTargetCalleeAtNodeWithEvidence(
            lookup,
            callable_node,
            self.iteratorTargetEvidenceSource(plan),
        );
        const completed_callable_node = try self.draftFnSlotTypeNode(task.callee, callable_node);
        if (task.expected_ret_ty) |expected| {
            if (!self.graph.sameClass(plan_fn.ret, try expected.toGraphNode(self.graph))) {
                Common.invariant("checked iterator dispatch plan return type differed from iterator-for expected type");
            }
        }

        const dispatcher_node = plan_fn.args[plan.dispatcher_arg_index];
        try call_ctx.constrainCheckedInterfaceToCell(plan.dispatcher_ty, DraftTypeCell.fromGraphNode(dispatcher_node));
        const actual_dispatcher_node = try self.iteratorOperandNode(plan_args[plan.dispatcher_arg_index], task.loop_iterator);
        try relateRequestComponent(self.graph, dispatcher_node, actual_dispatcher_node);
        // A producer-authored request intentionally remains in a different
        // class from its checked-public operand. The directed relation above
        // validates their complete public interface; ordinary operands still
        // require the single checked class.
        if (!self.graph.sameClass(dispatcher_node, actual_dispatcher_node) and
            !try self.graph.containsGeneratedPrivate(dispatcher_node) and
            !try self.graph.containsGeneratedPrivate(actual_dispatcher_node))
        {
            Common.invariant("iterator dispatch plan dispatcher operand differed from the checked dispatcher type");
        }
        const fn_nodes = try self.graph.functionNodes(completed_callable_node);
        if (fn_nodes.args.len != plan_args.len) {
            Common.invariant("completed iterator dispatch target changed its argument arity");
        }
        if (task.expected_ret_ty) |expected| {
            const expected_node = try expected.toGraphNode(self.graph);
            // Completion may replace the public return with a producer-minted
            // private representation that is directionally related to the
            // request instead of sharing its class, so a generated-private
            // side is exempt exactly like the dispatcher operand check above.
            if (!self.graph.sameClass(fn_nodes.ret, expected_node) and
                !try self.graph.containsGeneratedPrivate(fn_nodes.ret) and
                !try self.graph.containsGeneratedPrivate(expected_node))
            {
                Common.invariant("checked iterator dispatch target return type differed from iterator-for expected type");
            }
        }
        task.ret_node = fn_nodes.ret;
        task.arg_nodes = plan_fn.args;
        task.args = try self.allocator.alloc(DraftExprId, plan_args.len);
        return self.nextIteratorDispatchOperand(task, plan_args);
    }

    fn nextIteratorDispatchOperand(
        self: *BodyContext,
        task: *IteratorDispatchTask,
        plan_args: []const static_dispatch.IteratorDispatchOperand,
    ) Allocator.Error!LowerStep {
        while (task.index < plan_args.len) {
            switch (try self.iteratorOperandStep(plan_args[task.index], task.loop_iterator, task.arg_nodes[task.index])) {
                .now => |arg| {
                    task.args[task.index] = arg;
                    task.index += 1;
                },
                .child => |step| return step,
            }
        }
        const lowered = try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(task.ret_node),
            .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(task.callee),
                .args = try self.addExprSpan(task.args),
                .iterator_procedure = self.iteratorProcedureForMethodTarget(task.lookup.target),
                .captures = try self.methodTargetCaptureSpan(task.lookup),
            } },
        );
        self.releaseIteratorDispatchTask(task);
        return loweredExprStep(lowered);
    }

    fn finishGeneratedIteratorDispatch(
        self: *BodyContext,
        task: *IteratorDispatchTask,
        procedure: checked.IteratorProcedureId,
        dispatcher_node: NodeId,
        iterator: DraftExprId,
    ) Allocator.Error!LowerStep {
        const lowered = switch (procedure) {
            .identity => blk: {
                if (task.expected_ret_ty) |expected| {
                    try relateRequestComponent(self.graph, dispatcher_node, try expected.toGraphNode(self.graph));
                }
                break :blk iterator;
            },
            .next => blk: {
                const step_ret_node = try self.generatedIteratorStepReturnNode(dispatcher_node);
                if (task.expected_ret_ty) |expected| {
                    try relateRequestComponent(self.graph, step_ret_node, try expected.toGraphNode(self.graph));
                }
                break :blk try self.addExprWithTypeCell(
                    DraftTypeCell.fromGraphNode(step_ret_node),
                    try self.lowerGeneratedIteratorNextData(iterator, dispatcher_node),
                );
            },
            .custom, .single, .list_iter, .list_iter_rev, .str_iter_utf8, .map, .keep_if, .drop_if, .take_first, .drop_first, .concat, .append, .with_index, .step_by, .from_iter, .range_iter, .numeric_range_iter, .numeric_to, .numeric_until, .from_step, .range_done => unreachable,
        };
        self.releaseIteratorDispatchTask(task);
        return loweredExprStep(lowered);
    }

    /// Lower one iterator dispatch operand at its instantiated argument node:
    /// the loop's iterator local at once, a checked expression as a child.
    fn iteratorOperandStep(
        self: *BodyContext,
        operand: static_dispatch.IteratorDispatchOperand,
        loop_iterator: ?DraftTypedLocal,
        node: NodeId,
    ) Allocator.Error!union(enum) { now: DraftExprId, child: LowerStep } {
        return switch (operand) {
            .checked_expr => |expr| .{ .child = requestLowerChild(self, expr, DraftTypeCell.fromGraphNode(node)) },
            .loop_iterator_state => blk: {
                const iterator = loop_iterator orelse Common.invariant("iterator .next dispatch reached Monotype without a loop iterator local");
                const iterator_node = try iterator.ty.toGraphNode(self.graph);
                try self.graph.unify(iterator_node, node);
                if (!self.graph.sameClass(iterator_node, node)) Common.invariant("iterator .next operand type differed from instantiated callable argument type");
                break :blk .{ .now = try self.addExprWithTypeCell(iterator.ty, .{ .local = iterator.local }) };
            },
        };
    }

    const WithTypeTask = struct {
        expr: checked.CheckedExprId,
        ty: Type.TypeId,
        saved: ?SavedSourceLocation = null,
        field_access_start: u32 = 0,
        receiver_ty: Type.TypeId = undefined,
        tag_name: names.TagNameId = undefined,
        nominal_named: Type.TypeId = undefined,
        /// A nominal's proven-uninhabited backing type, whose scrutinee is
        /// lowering as a child.
        uninhabited_backing: ?Type.TypeId = null,
    };

    const DispatchLowerTask = struct {
        /// The result type a structural equality or hash computed before its
        /// operands lower.
        structural_ret_ty: Type.TypeId = undefined,
        checked_ret_ty: checked.CheckedTypeId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        expected_ret_cell: DraftTypeCell,
        timing: BodyWorkTimingScope = .{},
        call_ctx: ?*BodyContext = null,
        direct_parametric_low_level: ?can.CIR.Expr.LowLevel = null,
        direct_graph_call: bool = false,
        plan_args: []const static_dispatch.StaticDispatchOperand = &.{},
        callable_node: NodeId = undefined,
        callable_args: []const NodeId = &.{},
        callable_ret: NodeId = undefined,
        pre_lowered: std.ArrayList(PreLoweredOperand) = .empty,
        index: usize = 0,
        /// The next operand to draft if it is a lambda or closure.
        draft_index: usize = 0,
    };

    const ClosedProcedureTask = struct {
        checked_ret_ty: checked.CheckedTypeId,
        plan: static_dispatch.StaticDispatchCallPlan,
        evidence_id: static_dispatch.EvidenceNodeId,
        procedure: static_dispatch.ProcedureMethodTarget,
        expected_ret_cell: DraftTypeCell,
        callable_node: NodeId = undefined,
    };

    const ClosedOperandsAtTypesTask = struct {
        operands: []const static_dispatch.StaticDispatchOperand,
        /// Owned copy of the sealed argument types.
        stable_types: []const Type.TypeId,
        ret_cell: DraftTypeCell,
        uninhabited_index: ?usize = null,
        prior: []DraftExprId = &.{},
        reserved: BodyDraftStore.ReservedExprSpan = undefined,
        reserving: bool = false,
        index: usize = 0,
    };

    const PreparedOperandsTask = struct {
        operands: []const static_dispatch.StaticDispatchOperand,
        nodes: []const NodeId,
        pre_lowered: []const PreLoweredOperand,
        reserved: BodyDraftStore.ReservedExprSpan = undefined,
        reserving: bool = false,
        index: usize = 0,
    };

    const UninhabitedArgumentTask = struct {
        /// Dispatch operands, or checked call arguments as operands.
        operands: []const static_dispatch.StaticDispatchOperand = &.{},
        checked_args: []const checked.CheckedExprId = &.{},
        arg_nodes: []const NodeId,
        ret_cell: DraftTypeCell,
        uninhabited_index: usize = 0,
        prior: []DraftExprId = &.{},
        index: usize = 0,
        /// The uninhabited argument's scrutinee is lowering as a child.
        scrutinee_requested: bool = false,
    };

    const SpanTask = struct {
        exprs: []const checked.CheckedExprId,
        nodes: []const NodeId = &.{},
        types: []const Type.TypeId = &.{},
        owns_types: bool = false,
        list_ty: Type.TypeId = undefined,
        elem_ty: Type.TypeId = undefined,
        reserved: BodyDraftStore.ReservedExprSpan = undefined,
        /// The reserved span is still being filled; an unwinding frame
        /// returns its slots.
        reserving: bool = false,
        index: usize = 0,
        /// The proven-uninhabited type of the element whose scrutinee is
        /// lowering as a child.
        uninhabited_ty: ?Type.TypeId = null,
    };

    const CallLowerTask = struct {
        expr: checked.CheckedExprId,
        checked_ret_ty: checked.CheckedTypeId,
        call: CheckedCall,
        expected_ret_node: ?NodeId,
        expected_ret_ty: ?Type.TypeId,
        timing: BodyWorkTimingScope = .{},
        call_ctx: ?*BodyContext = null,
        fn_node: NodeId = undefined,
        fn_nodes: FunctionNodes = undefined,
        callee_ret: NodeId = undefined,
        callee: DraftFnSlot = undefined,
        iterator_procedure: ?checked.IteratorProcedureId = null,
        fn_ty: Type.TypeId = undefined,
        callee_expr: DraftExprId = undefined,
        /// The result cell a divergent operand's effect lowers at.
        divergent_ret_cell: DraftTypeCell = undefined,
    };

    const LowerFrame = struct {
        ctx: *BodyContext,
        cursor: u8 = 0,
        task: LowerTask,
    };

    const LowerStep = union(enum) {
        call: struct { ctx: *BodyContext, task: LowerTask },
        ret: LowerResult,
    };

    /// `task` stored by `ctx`'s allocator, for a `LowerTask` variant that
    /// holds it by pointer; finishing or releasing its frame frees it.
    fn boxLowerTask(ctx: *BodyContext, comptime T: type, task: T) Allocator.Error!*T {
        const boxed = try ctx.allocator.create(T);
        boxed.* = task;
        return boxed;
    }

    fn requestLowerTask(ctx: *BodyContext, task: LowerTask) LowerStep {
        return .{ .call = .{ .ctx = ctx, .task = task } };
    }

    /// Run a lowering computation to completion on an explicit frame stack.
    fn runLower(self: *BodyContext, root: LowerTask) Allocator.Error!LowerResult {
        var frames: std.ArrayList(LowerFrame) = .empty;
        defer frames.deinit(self.allocator);
        errdefer {
            while (frames.pop()) |frame| {
                var owned = frame;
                owned.ctx.releaseLowerFrame(&owned);
            }
        }
        try frames.append(self.allocator, .{ .ctx = self, .task = root });
        var input: ?LowerResult = null;
        while (true) {
            const frame = &frames.items[frames.items.len - 1];
            const step = try frame.ctx.stepLower(frame, input);
            switch (step) {
                .call => {
                    const next = frames.addOne(self.allocator) catch |err| {
                        var unstarted: LowerFrame = .{ .ctx = step.call.ctx, .task = step.call.task };
                        unstarted.ctx.releaseLowerFrame(&unstarted);
                        return err;
                    };
                    next.* = .{ .ctx = step.call.ctx, .task = step.call.task };
                    input = null;
                },
                .ret => {
                    const finished = &frames.items[frames.items.len - 1];
                    finished.ctx.releaseLowerFrame(finished);
                    frames.items.len -= 1;
                    if (frames.items.len == 0) return step.ret;
                    input = step.ret;
                },
            }
        }
    }

    fn saveSourceLocation(self: *BodyContext, expr: checked.CheckedExpr) Allocator.Error!SavedSourceLocation {
        const saved: SavedSourceLocation = .{
            .loc = self.builder.current_loc,
            .region = self.builder.current_region,
        };
        const region = self.sourceRegionForExpr(expr);
        self.builder.current_loc = try self.sourceLocFor(region);
        self.builder.current_region = region;
        return saved;
    }

    fn restoreSourceLocation(self: *BodyContext, saved: *?SavedSourceLocation) void {
        const location = saved.* orelse return;
        self.builder.current_loc = location.loc;
        self.builder.current_region = location.region;
        saved.* = null;
    }

    /// Release what a frame still owns. Idempotent, so a frame that already
    /// released its state on its normal path is unaffected.
    const CheckedRecordConstruction = @FieldType(checked.CheckedExprData, "record");

    /// A constructor lowered at its graph node: every child is related to its
    /// slot first, then each lowers at its slot, then the constructor is
    /// built at the node or, when a child requires one, at an exact value
    /// witness.
    const ConstructorTask = struct {
        kind: union(enum) {
            tag: @FieldType(@FieldType(checked.CheckedExprData, "tag"), "name"),
            /// The backing expression.
            nominal: checked.CheckedExprId,
            tuple,
            list,
            record: struct { expr: checked.CheckedExprId, record: CheckedRecordConstruction },
        },
        /// The constructor's graph node; for a nominal, its representation node.
        node: NodeId,
        /// A tag's, tuple's, or list's checked children. A nominal's backing
        /// and a record's extension base and fields live in `kind`.
        children: []const checked.CheckedExprId,
        name: names.TagNameId = undefined,
        /// Each child's slot node. Owned.
        slots: []NodeId = &.{},
        /// Each lowered child. Owned.
        lowered: []DraftExprId = &.{},
        /// Each lowered child's witness slot; for a list, each child's node.
        /// Owned.
        produced: []NodeId = &.{},
        index: usize = 0,
        requires_distinct_witness: bool = false,
        /// A list's selected element witness and the child that chose it.
        produced_element: ?NodeId = null,
        selected_index: usize = 0,
        /// The slot cell of a proven-uninhabited child, whose lowered
        /// scrutinee a zero-branch match consumes.
        uninhabited_slot: ?DraftTypeCell = null,
    };

    fn releaseConstructorTask(self: *BodyContext, task: *ConstructorTask) void {
        self.allocator.free(task.slots);
        task.slots = &.{};
        self.allocator.free(task.lowered);
        task.lowered = &.{};
        self.allocator.free(task.produced);
        task.produced = &.{};
    }

    fn constructorStep(ctx: *BodyContext, task: ConstructorTask) LowerStep {
        return requestLowerTask(ctx, .{ .constructor = task });
    }

    fn recordConstructorStep(
        ctx: *BodyContext,
        checked_expr: checked.CheckedExprId,
        record: CheckedRecordConstruction,
        record_node: NodeId,
    ) LowerStep {
        return constructorStep(ctx, .{
            .kind = .{ .record = .{ .expr = checked_expr, .record = record } },
            .node = record_node,
            .children = &.{},
        });
    }

    fn stepConstructor(self: *BodyContext, frame: *LowerFrame, task: *ConstructorTask, input: ?LowerResult) Allocator.Error!LowerStep {
        if (frame.cursor == 0) {
            if (task.kind == .list) {
                const element_node = try self.graph.listElementNode(task.node);
                const element_content = try self.graph.content(try self.constructorRepresentationNode(element_node));
                if (element_content == .primitive) {
                    if (try self.lowerPackedNumeralList(task.children, element_content.primitive)) |data| {
                        return loweredExprStep(try self.addConstructorExprAtNode(task.node, data));
                    }
                }
            }
            const drafts = try self.beginConstructor(task);
            if (drafts.len != 0) {
                frame.cursor = constructor_drafts_cursor;
                return self.draftCallablesThen(drafts, null);
            }
            self.allocator.free(drafts);
            frame.cursor = 1;
        } else if (frame.cursor == constructor_drafts_cursor) {
            frame.cursor = 1;
        } else {
            task.lowered[task.index] = if (task.uninhabited_slot) |cell|
                try self.zeroBranchMatchAtTypeCell(input.?.exprValue(), cell)
            else
                input.?.exprValue();
            task.uninhabited_slot = null;
            try self.constructorChildLowered(task);
        }
        if (task.index < task.slots.len) {
            const slot = task.slots[task.index];
            const child = self.constructorChild(task, task.index);
            const slot_cell = DraftTypeCell.fromGraphNode(slot);
            if (try self.nodeIsProvenUninhabited(slot)) {
                task.uninhabited_slot = slot_cell;
                return uninhabitedScrutineeStep(self, child, slot_cell);
            }
            return requestLowerChild(self, child, slot_cell);
        }
        const lowered = try self.finishConstructor(task);
        self.releaseConstructorTask(task);
        return loweredExprStep(lowered);
    }

    /// The constructor task's cursor while its lambda children are drafted.
    const constructor_drafts_cursor: u8 = 2;

    fn constructorChild(_: *BodyContext, task: *const ConstructorTask, index: usize) checked.CheckedExprId {
        return switch (task.kind) {
            .record => |record| if (record.record.ext) |ext|
                if (index == 0) ext else record.record.fields[index - 1].value
            else
                record.record.fields[index].value,
            .nominal => |backing| backing,
            .tag, .tuple, .list => task.children[index],
        };
    }

    /// Compute every child's slot, relate each child to its slot, and
    /// allocate the child results. Returns the lambda and closure children
    /// to draft at their slots, owned.
    fn beginConstructor(self: *BodyContext, task: *ConstructorTask) Allocator.Error![]DraftNestedCallable {
        const child_count = switch (task.kind) {
            .record => |record| record.record.fields.len + @as(usize, if (record.record.ext != null) 1 else 0),
            .nominal => 1,
            .tag, .tuple, .list => task.children.len,
        };
        task.slots = try self.allocator.alloc(NodeId, child_count);
        switch (task.kind) {
            .tag => |tag_name| {
                task.name = try self.tagName(self.view, tag_name);
                for (task.slots, 0..) |*slot, index| {
                    slot.* = try self.graph.tagConstructionPayloadNode(task.node, task.name, index);
                }
            },
            .nominal => {
                const representation_node = task.node;
                if ((try self.graph.content(representation_node)) != .named) {
                    Common.invariant("nominal constructor had no nominal graph representation");
                }
                const named = (try self.graph.namedNodes(representation_node));
                task.slots[0] = (named.backing orelse
                    Common.invariant("nominal constructor graph node had no backing")).node;
            },
            .tuple => {
                const item_nodes = try self.graph.tupleItemNodes(task.node);
                if (task.children.len != item_nodes.len) Common.invariant("tuple constructor arity differed from its graph type");
                @memcpy(task.slots, item_nodes);
            },
            .list => @memset(task.slots, try self.graph.listElementNode(task.node)),
            .record => |record| {
                var slot_index: usize = 0;
                if (record.record.ext) |ext| {
                    task.slots[slot_index] = try self.instNode(self.view.bodies.expr(ext).ty);
                    slot_index += 1;
                }
                var construction = try self.constructionFields(task.node);
                defer construction.deinit(self.allocator);
                for (record.record.fields) |field| {
                    const construction_field = construction.get(try self.recordFieldName(self.view, field.label));
                    task.slots[slot_index] = self.graph.rootNode(construction_field.value_ty orelse construction_field.ty);
                    slot_index += 1;
                }
            },
        }
        const children = try self.allocator.alloc(checked.CheckedExprId, child_count);
        defer self.allocator.free(children);
        for (children, 0..) |*child, index| child.* = self.constructorChild(task, index);
        const drafts = try self.relateConstructorChildrenAtNodes(children, task.slots);
        errdefer self.allocator.free(drafts);
        task.lowered = try self.allocator.alloc(DraftExprId, child_count);
        task.produced = try self.allocator.alloc(NodeId, child_count);
        return drafts;
    }

    /// Record what the child at `task.index` contributes to the
    /// constructor's value witness, then move to the next child.
    fn constructorChildLowered(self: *BodyContext, task: *ConstructorTask) Allocator.Error!void {
        const index = task.index;
        task.index += 1;
        const slot = task.slots[index];
        const child_node = try self.exprTypeCell(task.lowered[index]).toGraphNode(self.graph);
        const witness = switch (task.kind) {
            .record => return,
            .list => {
                task.produced[index] = child_node;
                if (task.produced_element) |selected| {
                    // A list has exactly one element representation, so every
                    // later child joins the selected witness—including a child
                    // whose class already matches the checked element slot, which
                    // otherwise would silently diverge from the selection.
                    try selectRequestRepresentation(self.graph, selected, child_node);
                } else {
                    const witness = try self.constructorChildWitness(
                        slot,
                        child_node,
                        "list graph constructor child differed without explicit representation evidence",
                    );
                    if (witness.requires_witness) {
                        task.produced_element = witness.slot;
                        task.selected_index = index;
                    }
                }
                return;
            },
            .tag => try self.constructorChildWitness(
                slot,
                child_node,
                "tag graph constructor child differed without explicit representation evidence",
            ),
            .tuple => try self.constructorChildWitness(
                slot,
                child_node,
                "tuple graph constructor child differed without explicit representation evidence",
            ),
            .nominal => try self.constructorChildWitness(
                slot,
                child_node,
                "nominal graph constructor child differed without explicit representation evidence",
            ),
        };
        task.produced[index] = witness.slot;
        if (witness.requires_witness) task.requires_distinct_witness = true;
    }

    fn finishConstructor(self: *BodyContext, task: *ConstructorTask) Allocator.Error!DraftExprId {
        switch (task.kind) {
            .tag => {
                const tag_node = task.node;
                const produced_node = if (task.requires_distinct_witness) blk: {
                    const structural_node = try self.graph.tagValueNodeWithPayloads(tag_node, task.name, task.produced);
                    const witness = try self.constructorWitnessWithStructuralNode(tag_node, structural_node);
                    break :blk try self.relateCheckedNodeToProducedValue(tag_node, witness);
                } else tag_node;
                return try self.addConstructorExprAtNode(produced_node, .{ .tag = .{
                    .name = task.name,
                    .payloads = try self.addExprSpan(task.lowered),
                } });
            },
            .nominal => {
                const representation_node = task.node;
                const produced_node = if (task.requires_distinct_witness) blk: {
                    const witness_node = try self.graph.namedValueNodeWithBacking(representation_node, task.produced[0]);
                    break :blk try self.relateCheckedNodeToProducedValue(representation_node, witness_node);
                } else representation_node;
                return try self.addExprWithTypeCell(
                    DraftTypeCell.fromGraphNode(produced_node),
                    .{ .nominal = task.lowered[0] },
                );
            },
            .tuple => {
                const tuple_node = task.node;
                const produced_node = if (task.requires_distinct_witness) blk: {
                    const structural_node = try self.graph.newNode(.{
                        .tuple = try self.graph.arena().dupe(NodeId, task.produced),
                    });
                    const witness = try self.constructorWitnessWithStructuralNode(tuple_node, structural_node);
                    break :blk try self.relateCheckedNodeToProducedValue(tuple_node, witness);
                } else tuple_node;
                return try self.addConstructorExprAtNode(produced_node, .{ .tuple = try self.addExprSpan(task.lowered) });
            },
            .list => {
                const list_node = task.node;
                const produced_node = if (task.produced_element) |element_witness| blk: {
                    // Elements lowered before the selection were only checked against
                    // the public element slot, so they join the selection here; every
                    // element is stored at one representation regardless of which
                    // element chose it.
                    for (task.produced[0..task.selected_index]) |child_node| {
                        try selectRequestRepresentation(self.graph, element_witness, child_node);
                    }
                    const structural_node = try self.graph.newNode(.{ .list = element_witness });
                    const witness = try self.constructorWitnessWithStructuralNode(list_node, structural_node);
                    // Every element is stored at the list's single element
                    // representation, so each element expression carries the selected
                    // witness cell rather than the checked-public slot it was
                    // requested at.
                    const element_cell = DraftTypeCell.fromGraphNode(element_witness);
                    for (task.lowered) |element| {
                        self.draft.exprs.items[@backingInt(element)].ty = element_cell;
                    }
                    break :blk try self.relateCheckedNodeToProducedValue(list_node, witness);
                } else list_node;
                return try self.addExprWithTypeCell(
                    DraftTypeCell.fromGraphNode(produced_node),
                    .{ .list = try self.addExprSpan(task.lowered) },
                );
            },
            .record => |record| {
                const children = try self.allocator.alloc(PreLoweredChild, task.lowered.len);
                defer self.allocator.free(children);
                for (children, task.lowered, 0..) |*child, lowered, index| {
                    child.* = .{ .checked_expr = self.constructorChild(task, index), .expr = lowered };
                }
                return try self.lowerRecordExprAtNode(record.expr, record.record, task.node, children);
            },
        }
    }

    fn releaseLowerFrame(self: *BodyContext, frame: *LowerFrame) void {
        switch (frame.task) {
            inline .at_type_cell, .expr_inner, .with_type => |*task| self.restoreSourceLocation(&task.saved),
            .record_at_type => |*task| task.deinit(self.allocator),
            .dispatch => |*task| {
                task.pre_lowered.deinit(self.allocator);
                task.pre_lowered = .empty;
                if (task.call_ctx) |call_ctx| self.destroyCallContext(call_ctx);
                task.call_ctx = null;
                task.timing.end();
            },
            .call => |*task| {
                if (task.call_ctx) |call_ctx| self.destroyCallContext(call_ctx);
                task.call_ctx = null;
                task.timing.end();
            },
            .closed_operands_at_types => |*task| {
                if (task.reserving) self.draft.expr_ids.shrinkRetainingCapacity(task.reserved.span.start);
                task.reserving = false;
                self.allocator.free(task.stable_types);
                task.stable_types = &.{};
                self.allocator.free(task.prior);
                task.prior = &.{};
            },
            .uninhabited_dispatch, .uninhabited_call => |*task| {
                self.allocator.free(task.prior);
                task.prior = &.{};
            },
            .span, .prepared_span, .span_at_types, .list_span => |*task| self.releaseSpanTask(task),
            .constructor => |*task| self.releaseConstructorTask(task),
            .block => |task| {
                self.releaseBlockTask(task);
                self.allocator.destroy(task);
            },
            .if_task => |*task| self.releaseIfTask(task),
            .match_task => |*task| self.releaseMatchTask(task),
            .nested_fn => |task| {
                self.releaseNestedFnTask(task);
                self.allocator.destroy(task);
            },
            .hosted_evidence => |task| {
                releaseEvidenceFrames(&task.frames);
                task.frames.deinit(self.allocator);
                self.allocator.destroy(task);
            },
            .draft_callables => |*task| {
                self.allocator.free(task.drafts);
                task.drafts = &.{};
            },
            .value_then_state => |*task| self.releaseValueThenStateTask(task),
            .discarded => |*task| self.releaseDiscardedTask(task),
            .operand_sequence => |*task| self.releaseOperandSequenceTask(task),
            .statement => |*task| self.releaseStatementTask(task),
            .loop => |task| {
                self.releaseLoopTask(task);
                self.allocator.destroy(task);
            },
            .iterator_dispatch => |task| {
                self.releaseIteratorDispatchTask(task);
                self.allocator.destroy(task);
            },
            .materialize => |*task| self.releaseMaterializeTask(task),
            .branch_body, .return_value, .inspected, .divergent, .field_access, .str, .direct_structural, .inspect_only => {},
            .scheme_alias => |*task| self.restoreSchemeAliasScope(task),
            .callsite_intrinsic => |*task| {
                self.allocator.free(task.args);
                task.args = &.{};
            },
            .prepared_operands => |*task| {
                if (task.reserving) self.draft.expr_ids.shrinkRetainingCapacity(task.reserved.span.start);
                task.reserving = false;
            },
            .cell_inner,
            .type_inner,
            .expr,
            .closed_low_level,
            .closed_procedure,
            .closed_operands_at_node,
            .operand_at_type,
            .call_expr_at_node,
            .call_expr,
            .interpolation,
            => {},
        }
    }

    fn stepLower(self: *BodyContext, frame: *LowerFrame, input: ?LowerResult) Allocator.Error!LowerStep {
        switch (frame.task) {
            .at_type_cell => |*task| return self.stepAtTypeCell(frame, task, input),
            .cell_inner => |*task| return self.stepCellInner(frame, task, input),
            .type_inner => |*task| return self.stepTypeInner(frame, task, input),
            .expr => |*task| return self.stepLowerExpr(frame, task, input),
            .expr_inner => |*task| return self.stepExprInner(frame, task, input),
            .with_type => |*task| return self.stepWithType(frame, task, input),
            .record_at_type => |*task| return self.stepRecordAtType(task, input),
            .dispatch => |*task| return self.stepDispatchLower(frame, task, input),
            .closed_low_level => |*task| return self.stepClosedLowLevel(frame, task, input),
            .closed_procedure => |*task| return self.stepClosedProcedure(frame, task, input),
            .closed_operands_at_types => |*task| return self.stepClosedOperandsAtTypes(frame, task, input),
            .closed_operands_at_node => |*task| return self.stepClosedOperandsAtNode(frame, task, input),
            .prepared_operands => |*task| return self.stepPreparedOperands(frame, task, input),
            .operand_at_type => |*task| return self.stepOperandAtType(frame, task, input),
            .uninhabited_dispatch => |*task| return self.stepUninhabitedDispatch(frame, task, input),
            .uninhabited_call => |*task| return self.stepUninhabitedCall(frame, task, input),
            .span => |*task| return self.stepSpan(frame, task, input, .typed_by_expr),
            .prepared_span => |*task| return self.stepSpan(frame, task, input, .at_nodes),
            .span_at_types => |*task| return self.stepSpan(frame, task, input, .at_types),
            .list_span => |*task| return self.stepSpan(frame, task, input, .list_elements),
            .call => |*task| return self.stepCallLower(frame, task, input),
            .call_expr_at_node => |*task| return self.stepCallExprAtNode(frame, task, input),
            .call_expr => |*task| return self.stepCallExpr(frame, task, input),
            .constructor => |*task| return self.stepConstructor(frame, task, input),
            .block => |task| return self.stepBlock(task, input),
            .if_task => |*task| return self.stepIf(task, input),
            .match_task => |*task| return self.stepMatch(task, input),
            .nested_fn => |task| return self.stepNestedFn(task, input),
            .hosted_evidence => |task| return self.stepHostedEvidence(task),
            .draft_callables => |*task| return self.stepDraftCallables(frame, task),
            .branch_body => |*task| return self.stepBranchBody(frame, task, input),
            .value_then_state => |*task| return self.stepValueThenState(task, input),
            .discarded => |*task| return self.stepDiscarded(task, input),
            .statement => |*task| return self.stepStatement(task, input),
            .return_value => |*task| return self.stepReturn(frame, task, input),
            .inspected => |*task| return self.stepInspected(frame, task, input),
            .divergent => |*task| return self.stepDivergent(frame, task, input),
            .operand_sequence => |*task| return self.stepOperandSequence(task, input),
            .loop => |task| return self.stepLoop(task, input),
            .iterator_dispatch => |task| return self.stepIteratorDispatch(frame, task, input),
            .materialize => |*task| return self.stepMaterialize(task, input),
            .field_access => |*task| return self.stepFieldAccessLower(task, input),
            .str => |*task| return self.stepStr(task, input),
            .direct_structural => |*task| return self.stepDirectStructural(task, input),
            .inspect_only => |*task| return self.stepInspectOnly(task, input),
            .scheme_alias => |*task| return self.stepSchemeAlias(task, input),
            .callsite_intrinsic => |*task| return self.stepCallsiteIntrinsic(task, input),
            .interpolation => |*task| return self.stepInterpolationLower(frame, task, input),
        }
    }

    /// An interpolation's conversion receives its literal segments and returns
    /// `Try(assembler, [InvalidInterpolation(Str)])`. Like any specialized
    /// literal conversion it runs at compile time: its `Ok` payload, the
    /// assembler, is a literal root's value, and its `Err` is the literal's
    /// rejection. The interpolation's value is the assembler called with the
    /// parts' values.
    fn stepInterpolationLower(self: *BodyContext, frame: *LowerFrame, task: *InterpolationLowerTask, input: ?LowerResult) Allocator.Error!LowerStep {
        switch (frame.cursor) {
            0 => {
                const try_ty = self.literalConversionTryType(task.maybe_plan);
                task.try_node = try self.instNode(try_ty);
                task.assembler_node = (try self.graphTryPayloads(task.try_node)).ok;
                const assembler_fn = try self.graph.functionNodes(task.assembler_node);
                if (assembler_fn.args.len != 1) Common.invariant("interpolation assembler did not take exactly the values list");
                try relateRequestComponent(self.graph, assembler_fn.ret, task.value_node);
                // Every interpolated value is an item of the assembler's
                // values list, so the item type is the values' type. The
                // selected `from_interpolation` determines the item only when
                // its own signature fixes it.
                const item_node = switch (try self.graph.content(assembler_fn.args[0])) {
                    .list => |elem| elem,
                    .redirect, .leaf, .unresolved, .primitive, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => Common.invariant("interpolation assembler did not take a values list"),
                };
                const interpolation = switch (self.view.bodies.expr(task.expr).data) {
                    .interpolation => |value| value,
                    .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("interpolation lowering referenced a non-interpolation expression"),
                };
                for (interpolation.values) |value| {
                    try relateRequestComponent(self.graph, item_node, try self.lowerExprTypeNode(value));
                }
                frame.cursor = 1;
                return requestLowerTask(self, .{ .dispatch = .{
                    .checked_ret_ty = try_ty,
                    .maybe_plan = task.maybe_plan,
                    .expected_ret_cell = DraftTypeCell.fromGraphNode(task.try_node),
                } });
            },
            1 => {
                const site = self.literalRejectionSite(task.expr);
                const assembler = try self.unwrapLiteralConversionAtNode(input.?.exprValue(), task.try_node, task.assembler_node, site);
                task.assembler = if (self.builder.literal_roots)
                    try self.literalRootRead(task.expr, site, assembler, task.assembler_node)
                else
                    assembler;
                const interpolation = switch (self.view.bodies.expr(task.expr).data) {
                    .interpolation => |value| value,
                    .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("interpolation lowering referenced a non-interpolation expression"),
                };
                task.values_ty = try self.activeTypeFromNode((try self.graph.functionNodes(task.assembler_node)).args[0]);
                frame.cursor = 2;
                return requestLowerTask(self, .{ .list_span = .{ .exprs = interpolation.values, .list_ty = task.values_ty } });
            },
            else => {
                const values = try self.addExpr(.{ .ty = task.values_ty, .data = .{ .list = input.?.spanValue() } });
                return loweredExprStep(try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(task.value_node), .{ .call_value = .{
                    .callee = task.assembler,
                    .args = try self.addExprSpan(&.{values}),
                } }));
            },
        }
    }

    fn requestLowerChild(ctx: *BodyContext, expr: checked.CheckedExprId, cell: DraftTypeCell) LowerStep {
        return requestLowerTask(ctx, .{ .at_type_cell = .{
            .expr = expr,
            .cell = cell,
            .demand = .runtime_value,
            .diverges = ctx.checkedExprDivergesInLoweredRuntime(expr),
        } });
    }

    fn stepAtTypeCell(self: *BodyContext, frame: *LowerFrame, task: anytype, input: ?LowerResult) Allocator.Error!LowerStep {
        const checked_expr = task.expr;
        const expr = self.view.bodies.expr(checked_expr);
        if (frame.cursor == 1) {
            const lowered = input.?.exprValue();
            const result = switch (task.cell) {
                .sealed => try self.requireLoweredExprAtCell(expr, task.cell, task.demand, lowered),
                .graph_node => |expected_node| try self.requireLoweredExpr(expr, expected_node, task.demand, lowered),
            };
            self.restoreSourceLocation(&task.saved);
            return .{ .ret = .{ .expr = result } };
        }
        task.saved = try self.saveSourceLocation(expr);
        frame.cursor = 1;
        return switch (task.cell) {
            .sealed => |ty| if (task.diverges)
                divergentStep(self, checked_expr, .{ .at_cell = task.cell })
            else
                requestLowerTask(self, .{ .type_inner = .{ .expr = checked_expr, .ty = ty } }),
            .graph_node => |expected_node| if (task.diverges)
                divergentStep(self, checked_expr, .{ .at_cell = task.cell })
            else
                requestLowerTask(self, .{ .cell_inner = .{ .expr = checked_expr, .cell = task.cell, .expected_node = expected_node } }),
        };
    }

    fn stepLowerExpr(self: *BodyContext, frame: *LowerFrame, task: anytype, input: ?LowerResult) Allocator.Error!LowerStep {
        if (frame.cursor == 0) {
            frame.cursor = 1;
            return requestLowerTask(self, .{ .expr_inner = .{ .expr = task.expr } });
        }
        const lowered = input.?.exprValue();
        return .{ .ret = .{ .expr = try self.requireLoweredExpr(
            self.view.bodies.expr(task.expr),
            try self.exprTypeCell(lowered).toGraphNode(self.graph),
            .runtime_value,
            lowered,
        ) } };
    }

    fn loweredExprStep(expr: DraftExprId) LowerStep {
        return .{ .ret = .{ .expr = expr } };
    }

    fn stepCellInner(self: *BodyContext, frame: *LowerFrame, task: anytype, input: ?LowerResult) Allocator.Error!LowerStep {
        const checked_expr = task.expr;
        const cell = task.cell;
        const expected_node = task.expected_node;
        const expr = self.view.bodies.expr(checked_expr);
        switch (frame.cursor) {
            0 => {},
            // A tuple access's tuple.
            2 => {
                const access = expr.data.tuple_access;
                const item_node = (try self.graph.tupleItemNodes(task.tuple_node))[access.elem_index];
                const result_cell = DraftTypeCell.fromGraphNode(
                    if (try self.graph.containsGeneratedPrivate(item_node)) item_node else expected_node,
                );
                return loweredExprStep(try self.addExprWithTypeCell(result_cell, .{ .tuple_access = .{
                    .tuple = input.?.exprValue(),
                    .elem_index = access.elem_index,
                } }));
            },
            // A low-level operation's arguments.
            3 => return loweredExprStep(try self.addExprWithTypeCell(cell, .{ .low_level = .{
                .op = expr.data.run_low_level.op,
                .args = input.?.spanValue(),
            } })),
            // The expression lowered without a contextual node.
            4 => {
                const lowered = input.?.exprValue();
                try relateRequestComponent(
                    self.graph,
                    expected_node,
                    try self.exprTypeCell(lowered).toGraphNode(self.graph),
                );
                self.draft.exprs.items[@backingInt(lowered)].ty = cell;
                return loweredExprStep(lowered);
            },
            // A dispatch or call lowered at this node.
            else => return .{ .ret = input.? },
        }
        switch (cell) {
            .sealed => Common.invariant("sealed expression reached graph-cell lowering"),
            .graph_node => {},
        }
        if (try self.restoredHoistedExprAtNode(checked_expr, expected_node)) |restored| {
            return loweredExprStep(restored);
        }
        frame.cursor = 5;
        switch (expr.data) {
            .lookup_local => |lookup| return try self.lookupExprAtNodeStep(checked_expr, lookup.resolved, expected_node),
            .lookup_external, .lookup_required => |resolved| return try self.lookupExprAtNodeStep(checked_expr, resolved, expected_node),
            .lambda => return requestLowerTask(self, .{ .nested_fn = try self.boxLowerTask(NestedFnTask, .{ .expr_id = checked_expr, .request_fn_node = expected_node }) }),
            .closure => |closure| return requestLowerTask(self, .{ .nested_fn = try self.boxLowerTask(NestedFnTask, .{ .expr_id = checked_expr, .request_fn_node = expected_node, .closure = closure }) }),
            .field_access => return requestLowerTask(self, .{ .field_access = .{ .expr = checked_expr, .target = .{ .node = expected_node } } }),
            .tag => |tag| return constructorStep(self, .{ .kind = .{ .tag = tag.name }, .node = expected_node, .children = tag.args }),
            .zero_argument_tag => |tag| return loweredExprStep(try self.addConstructorExprAtNode(expected_node, .{ .tag = .{
                .name = try self.tagName(self.view, tag.name),
                .payloads = .empty(),
            } })),
            .nominal => |nominal| return constructorStep(self, .{
                .kind = .{ .nominal = nominal.backing_expr },
                .node = (try self.constructorRepresentationNode(expected_node)),
                .children = &.{},
            }),
            .tuple => |items| return constructorStep(self, .{ .kind = .tuple, .node = expected_node, .children = items }),
            .list => |items| return constructorStep(self, .{ .kind = .list, .node = expected_node, .children = items }),
            .empty_list => return loweredExprStep(try self.addExprWithTypeCell(
                DraftTypeCell.fromGraphNode(expected_node),
                .{ .list = .empty() },
            )),
            // `{}` is a record construction that omits every field: lower it
            // through the record path so the demanded row's DEFAULTED fields
            // materialize their defaults into the inline slots (design.md
            // "Defaulted Fields").
            .empty_record => return recordConstructorStep(self, checked_expr, .{
                .fields = &.{},
                .unsets = &.{},
                .ext = null,
            }, expected_node),
            .record => |record| return recordConstructorStep(self, checked_expr, record, expected_node),
            .call => return requestLowerTask(self, .{ .call_expr_at_node = .{ .expr = checked_expr, .expected_node = expected_node } }),
            .numeral => |numeral| if (numeral.conversion_root) |root_id| {
                return loweredExprStep(try self.lowerLiteralConversionAtNode(checked_expr, root_id, expected_node));
            },
            .str_from_quote => |quote| if (quote.conversion_root) |root_id| {
                return loweredExprStep(try self.lowerLiteralConversionAtNode(checked_expr, root_id, expected_node));
            },
            .dispatch_call => |plan| {
                try self.selectExprRepresentationAtNode(checked_expr, expected_node);
                return requestLowerTask(self, .{ .dispatch = .{ .checked_ret_ty = expr.ty, .maybe_plan = plan, .expected_ret_cell = cell } });
            },
            .interpolation => |interpolation| {
                try self.selectExprRepresentationAtNode(checked_expr, expected_node);
                return requestLowerTask(self, .{ .interpolation = .{ .expr = checked_expr, .maybe_plan = interpolation.plan, .value_node = expected_node } });
            },
            .type_dispatch_call => |plan| {
                try self.selectExprRepresentationAtNode(checked_expr, expected_node);
                return requestLowerTask(self, .{ .dispatch = .{ .checked_ret_ty = expr.ty, .maybe_plan = plan, .expected_ret_cell = cell } });
            },
            .method_eq => |plan| {
                try self.selectExprRepresentationAtNode(checked_expr, expected_node);
                return requestLowerTask(self, .{ .dispatch = .{ .checked_ret_ty = expr.ty, .maybe_plan = plan, .expected_ret_cell = cell } });
            },
            .block => |block| return requestLowerTask(self, .{ .block = try self.boxLowerTask(BlockTask, .{
                .statements = block.statements,
                .final_expr = block.final_expr,
                .result_cell = cell,
            }) }),
            .match_ => |match| return requestLowerTask(self, .{ .match_task = .{ .expr_id = checked_expr, .match = match, .result_cell = cell } }),
            .if_ => |if_| return requestLowerTask(self, .{ .if_task = .{ .expr_id = checked_expr, .if_ = if_, .result_cell = cell } }),
            .runtime_error => |runtime_error| {
                if (runtime_error.evaluated.len != 0) return divergentStep(self, checked_expr, .{ .at_cell = cell });
                return loweredExprStep(try self.addExprWithTypeCell(cell, .{ .checked_error = try self.addStringLiteral("runtime error") }));
            },
            .anno_only => Common.invariant("non-runtime checked expression reached Monotype lowering"),
            .pending, .str_segment, .str, .bytes_literal, .binop, .unary_minus, .unary_not, .structural_eq, .structural_hash, .tuple_access, .crash, .dbg, .expect_err, .expect, .ellipsis, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
        }
        switch (expr.data) {
            .tuple_access => |access| {
                if (try self.checkedTypeContainsError(expr.ty)) {
                    return loweredExprStep(try self.addExprWithTypeCell(cell, .{ .checked_error = try self.addStringLiteral("runtime error") }));
                }
                if (try self.checkedTypeContainsError(self.view.bodies.expr(access.tuple).ty)) {
                    return loweredExprStep(try self.addExprWithTypeCell(cell, .{ .checked_error = try self.addStringLiteral("runtime error") }));
                }
            },
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
        }
        try relateRequestComponent(
            self.graph,
            expected_node,
            try self.lowerExprTypeNode(checked_expr),
        );
        switch (expr.data) {
            .tuple_access => |access| {
                const tuple_node = try self.lowerExprTypeNode(access.tuple);
                const item_nodes = try self.graph.tupleItemNodes(tuple_node);
                if (access.elem_index >= item_nodes.len) Common.invariant("tuple access index was outside its graph tuple type");
                const item_node = item_nodes[access.elem_index];
                try relateRequestComponent(self.graph, expected_node, item_node);
                task.tuple_node = tuple_node;
                frame.cursor = 2;
                return requestLowerChild(self, access.tuple, DraftTypeCell.fromGraphNode(tuple_node));
            },
            .run_low_level => |low_level| {
                frame.cursor = 3;
                return requestLowerTask(self, .{ .span = .{ .exprs = low_level.args } });
            },
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda => {},
        }
        frame.cursor = 4;
        return requestLowerTask(self, .{ .expr_inner = .{ .expr = checked_expr } });
    }

    fn stepTypeInner(self: *BodyContext, frame: *LowerFrame, task: anytype, input: ?LowerResult) Allocator.Error!LowerStep {
        const checked_expr = task.expr;
        const ty = task.ty;
        const expr = self.view.bodies.expr(checked_expr);
        switch (frame.cursor) {
            0 => {},
            // A call lowered at the context type.
            2 => {
                const lowered = input.?.callValue();
                if (!self.sameType(ty, try self.activeTypeFromCell(lowered.ret_ty))) {
                    Common.invariant("checked call expression lowered at a type different from its context type");
                }
                const ret_node = try lowered.ret_ty.toGraphNode(self.graph);
                const expected_node = try self.activeNodeFromType(ty);
                const completes_request = try self.resultCompletesRequest(expected_node, ret_node);
                const contains_generated_private = try self.graph.containsGeneratedPrivate(ret_node);
                const result_cell: DraftTypeCell = if (completes_request)
                    lowered.ret_ty
                else if (contains_generated_private) blk: {
                    try relateRequestComponent(self.graph, expected_node, ret_node);
                    break :blk lowered.ret_ty;
                } else DraftTypeCell.fromGraphNode(try self.relateCheckedNodeToProducedValue(expected_node, ret_node));
                return loweredExprStep(try self.addExprWithTypeCell(result_cell, lowered.data));
            },
            // A dispatch lowered at the context type.
            3 => return .{ .ret = input.? },
            // An expression lowered with the context type.
            else => {
                const lowered = input.?.exprValue();
                if (!self.sameType(ty, try self.exprType(lowered))) {
                    switch (expr.data) {
                        .lambda, .closure => Common.invariant("checked function expression lowered at a type different from its context type"),
                        .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("checked expression lowered at a type different from its call operand type"),
                    }
                }
                return loweredExprStep(lowered);
            },
        }
        switch (expr.data) {
            .call => |call| if (try self.inspectOnlyCallStep(
                expr.ty,
                call,
                ty,
                self.inspectCallDemand(call),
            )) |step| {
                frame.cursor = 3;
                return step;
            },
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
        }
        if (try self.restoredHoistedExprAtType(checked_expr, ty)) |restored| return loweredExprStep(restored);
        switch (expr.data) {
            .runtime_error => |runtime_error| {
                frame.cursor = 3;
                if (runtime_error.evaluated.len != 0) return divergentStep(self, checked_expr, .{ .at_type = ty });
                return requestLowerTask(self, .{ .with_type = .{ .expr = checked_expr, .ty = ty } });
            },
            .call => |call| {
                if (try self.callsiteIntrinsicCallTask(checked_expr, expr.ty, call, try self.activeNodeFromType(ty), ty)) |intrinsic| {
                    frame.cursor = 3;
                    return requestLowerTask(self, intrinsic);
                }
                try self.constrainKnownType(expr.ty, ty);
                frame.cursor = 2;
