                var prefix_ty = receiver_ty;
                for (field.segments) |segment| {
                    const field_name = try self.recordFieldName(self.view, segment.field_name);
                    prefix_ty = self.recordFieldType(prefix_ty, field_name);
                    self.draft.field_access_segments.appendAssumeCapacity(.{ .field = field_name });
                }
                if (@import("builtin").mode == .debug and !self.sameType(ty, prefix_ty)) {
                    Common.invariant("Monotype field access path type differed from its final receiver field type");
                }
                task.field_access_start = start;
                return requestLowerChild(self, field.receiver, .{ .sealed = receiver_ty });
            },
            .tuple_access => |access| {
                // The receiver stays attached to the specialization graph
                // through its tuple node: a receiver such as a `match` may
                // still carry an open row that only the whole program settles,
                // so it has no standalone Monotype to lower at yet.
                const tuple_node = try self.lowerExprTypeNode(access.tuple);
                const item_nodes = try self.graph.tupleItemNodes(tuple_node);
                if (access.elem_index >= item_nodes.len) Common.invariant("tuple access index was outside its graph tuple type");
                try relateRequestComponent(self.graph, try self.graph.importMono(ty), item_nodes[access.elem_index]);
                return requestLowerChild(self, access.tuple, DraftTypeCell.fromGraphNode(tuple_node));
            },
            .match_ => |match| return requestLowerTask(self, .{ .match_task = .{ .expr_id = expr_id, .match = match, .result_cell = .{ .sealed = ty } } }),
            .if_ => |if_| return requestLowerTask(self, .{ .if_task = .{ .expr_id = expr_id, .if_ = if_, .result_cell = .{ .sealed = ty } } }),
            .block => |block| return requestLowerTask(self, .{ .block = try self.boxLowerTask(BlockTask, .{
                .statements = block.statements,
                .final_expr = block.final_expr,
                .result_cell = .{ .sealed = ty },
                .typed = ty,
            }) }),
            .binop,
            .unary_minus,
            .unary_not,
            => Common.invariant("desugared operator expression reached Monotype without checked dispatch or low-level form"),
            .ellipsis => .{ .crash = try self.addStringLiteral("not implemented") },
            .crash => |msg| .{ .crash = try self.lowerStringLiteral(msg) },
            .dbg => |child| return requestLowerTask(self, .{ .inspected = .{ .expr = child } }),
            .expect_err => |expect_err| return requestLowerTask(self, .{ .inspected = .{
                .expr = expect_err.expr,
                .expect_err_snippet = expect_err.snippet,
            } }),
            .expect => |child| if (self.builder.inline_expects == .omit)
                .unit
            else
                return requestLowerTask(self, .{ .expr = .{ .expr = child } }),
            .break_ => try self.breakCurrentLoopExprData(),
            .return_ => |ret| return requestLowerTask(self, .{ .return_value = .{ .expr = ret.expr, .lambda = ret.lambda, .context = ret.context } }),
            .for_ => |for_| return requestLowerTask(self, .{ .loop = try self.boxLowerTask(LoopTask, .{ .kind = .{ .for_ = checkedForLoop(for_) } }) }),
            .hosted_lambda => Common.invariant("hosted lambda expression reached ordinary Monotype expression lowering"),
            .run_low_level => |low_level| return requestLowerTask(self, .{ .span = .{ .exprs = low_level.args } }),
        };
        return try self.withTypeData(task, data);
    }

    fn dispatchLowerDone(self: *BodyContext, task: *DispatchLowerTask, lowered: DraftExprId) LowerStep {
        task.pre_lowered.deinit(self.allocator);
        task.pre_lowered = .empty;
        if (task.call_ctx) |call_ctx| self.destroyCallContext(call_ctx);
        task.call_ctx = null;
        task.timing.end();
        return loweredExprStep(lowered);
    }

    fn stepDispatchLower(self: *BodyContext, frame: *LowerFrame, task: *DispatchLowerTask, input: ?LowerResult) Allocator.Error!LowerStep {
        const expected_ret_cell = task.expected_ret_cell;
        const checked_ret_ty = task.checked_ret_ty;
        const plan_id = task.maybe_plan orelse Common.invariant("checked dispatch expression reached Monotype without a dispatch plan");
        const plan = self.view.static_dispatch_plans.plans[@backingInt(plan_id)];
        switch (frame.cursor) {
            0 => {},
            dispatch_drafts_cursor => return try self.nextDispatchDraft(frame, task),
            // The uninhabited-argument check.
            1 => {
                if (input.?.maybeExprValue()) |uninhabited| return self.dispatchLowerDone(task, uninhabited);
                task.index = 0;
                return try self.nextDispatchOperand(frame, task, plan);
            },
            // An operand lowered at its callable slot.
            2 => {
                try task.pre_lowered.append(self.allocator, .{ .index = task.index, .expr = input.?.exprValue() });
                task.index += 1;
                return try self.nextDispatchOperand(frame, task, plan);
            },
            // A parametric low-level call's operands.
            3 => {
                const plan_ret_node = task.callable_ret;
                const call_ret_cell = if (try self.graph.containsGeneratedPrivate(plan_ret_node))
                    DraftTypeCell.fromGraphNode(plan_ret_node)
                else
                    expected_ret_cell;
                const call_expr = try self.addExprWithTypeCell(call_ret_cell, .{ .low_level = .{
                    .op = task.direct_parametric_low_level.?,
                    .args = input.?.spanValue(),
                } });
                // Result modes consume the graph-backed call type directly
                // because the return node may still be an unresolved open row
                // here.
                return self.dispatchLowerDone(task, try self.applyDispatchResultMode(plan.result_mode, call_expr));
            },
            // A resolved method call's remaining operands.
            5, 6 => {
                const lookup = switch (self.evidenceResolution(plan) orelse
                    Common.invariant("CheckedStaticDispatchCallPlan had no MethodTarget or StructuralDerivation")) {
                    .target => |lookup| lookup,
                    .structural => Common.invariant("resolved dispatch operands reached a structural derivation"),
                };
                const call_data = if (frame.cursor == 6)
                    try self.resolvedDirectDispatchCallData(plan, lookup, task.callable_node, input.?.spanValue())
                else
                    try self.resolvedDispatchCallData(plan, lookup, task.callable_node, input.?.spanValue());
                const plan_ret_node = task.callable_ret;
                const call_ret_cell = if (try self.graph.containsGeneratedPrivate(plan_ret_node))
                    DraftTypeCell.fromGraphNode(plan_ret_node)
                else
                    expected_ret_cell;
                const call_expr = try self.addExprWithTypeCell(
                    call_ret_cell,
                    call_data,
                );
                return self.dispatchLowerDone(task, try self.applyDispatchResultMode(plan.result_mode, call_expr));
            },
            // A structural equality's operands.
            7 => return self.dispatchLowerDone(task, try self.finishStructuralEqualityAtNode(plan, task.callable_node, task.structural_ret_ty, input.?.spanValue())),
            // A structural hash's operands.
            8 => return self.dispatchLowerDone(task, try self.finishStructuralHashAtNode(task.callable_node, task.structural_ret_ty, input.?.spanValue())),
            // A closed direct call lowered by its own frame.
            else => return self.dispatchLowerDone(task, input.?.exprValue()),
        }

        task.timing = BodyWorkTimingScope.begin(self.builder.timing, .call_dispatch);
        self.builder.countBodyDiagnostic("dispatch_expressions");
        task.direct_graph_call = self.dispatchUsesDirectGraphCallee(plan);
        switch (plan.resolution) {
            .direct_closed => |direct| {
                const node = self.view.static_dispatch_plans.evidenceNode(direct.evidence);
                switch (node.target.kind) {
                    .procedure => |procedure| switch (procedure.runtime_target) {
                        .low_level => |op| {
                            frame.cursor = 4;
                            return requestLowerTask(self, .{ .closed_low_level = .{
                                .plan = plan,
                                .op = op,
                                .expected_ret_cell = expected_ret_cell,
                            } });
                        },
                        .procedure => {
                            frame.cursor = 4;
                            return requestLowerTask(self, .{ .closed_procedure = .{
                                .checked_ret_ty = checked_ret_ty,
                                .plan = plan,
                                .evidence_id = direct.evidence,
                                .procedure = procedure,
                                .expected_ret_cell = expected_ret_cell,
                            } });
                        },
                        .intrinsic, .graph_participating => {},
                    },
                    .local_proc, .structural => {},
                }
            },
            .direct_parametric => |direct| {
                const node = self.view.static_dispatch_plans.evidenceNode(direct.evidence);
                switch (node.target.kind) {
                    .procedure => |procedure| switch (procedure.runtime_target) {
                        .low_level => |op| task.direct_parametric_low_level = op,
                        .procedure, .intrinsic, .graph_participating => {},
                    },
                    .local_proc, .structural => {},
                }
            },
            .direct_pending => Common.invariant("unfinalized direct call reached Monotype"),
            .evidence_dependent, .structural, .@"unreachable", .checked_error => {},
        }
        const callable_plan = switch (self.dispatchRuntimePlan(plan)) {
            .callable => |value| value,
            .crash => |reason| return self.dispatchLowerDone(task, try self.addExprWithTypeCell(expected_ret_cell, try self.dispatchCrashData(reason))),
        };
        const plan_args = callable_plan.operands;
        task.plan_args = plan_args;
        const expected_ret_ty: ?Type.TypeId = switch (expected_ret_cell) {
            .sealed => |ty| ty,
            .graph_node => null,
        };
        const expected_ret_node = try expected_ret_cell.toGraphNode(self.graph);

        const call_ctx = try self.createCallContext();
        task.call_ctx = call_ctx;

        var callable_node = try call_ctx.instantiateCallableDispatchPlanCallNodeFromCallerAtNode(
            callable_plan,
            self,
            checked_ret_ty,
            expected_ret_node,
            .expression_lowering,
        );
        const resolution = self.evidenceResolution(plan) orelse
            Common.invariant("runtime method call had no CheckedCallResolution evidence");
        switch (resolution) {
            .target => |initial_lookup| {
                const relation_lookup = initial_lookup;
                if (task.direct_parametric_low_level == null and !task.direct_graph_call) {
                    const target_node = try self.methodTargetNodeFromPlan(relation_lookup, call_ctx, plan.callable_ty);
                    try self.relateDispatchTargetRequestInterface(relation_lookup, target_node, callable_node);
                    if (try self.generatedIteratorMethodRequestNode(
                        relation_lookup,
                        target_node,
                        callable_node,
                        plan_args,
                    )) |private_node| {
                        callable_node = private_node;
                    }
                }
                callable_node = try self.lowerAndCompleteIteratorMethodResultAtNode(
                    relation_lookup,
                    callable_node,
                    plan,
                    task.direct_graph_call,
                );
            },
            .structural => {},
        }
        const callsite_intrinsic = switch (resolution) {
            .target => |lookup| self.callsiteIntrinsicForMethodTarget(lookup.target),
            .structural => null,
        };
        if (callsite_intrinsic) |intrinsic| {
            if (plan.result_mode != .value) {
                Common.invariant("call-site intrinsic dispatch had a non-value result mode");
            }
            frame.cursor = 4;
            return requestLowerTask(self, .{ .callsite_intrinsic = .{
                .intrinsic = intrinsic,
                .checked_expr_id = plan.expr,
                .source_fn_ty = plan.callable_ty,
                .operands = .{ .dispatch = plan_args },
                .callable_node = callable_node,
                .expected_ret_ty = expected_ret_ty,
            } });
        }
        const callable_graph = switch ((try self.graph.content(callable_node))) {
            .func => |function| function,
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => Common.invariant("checked dispatch plan had a non-function graph node"),
        };
        task.callable_node = callable_node;
        task.callable_args = callable_graph.args;
        task.callable_ret = callable_graph.ret;
        for (plan_args, 0..) |operand, index| switch (operand) {
            .checked_expr => |expr| {
                try self.relateExprAtNode(expr, callable_graph.args[index]);
            },
            .generated_interpolation_segments,
            .generated_numeral,
            .generated_quote,
            => {},
        };
        frame.cursor = dispatch_drafts_cursor;
        return try self.nextDispatchDraft(frame, task);
    }

    /// Draft the dispatch's next lambda or closure operand at its callable
    /// slot, then check the operands for an uninhabited argument.
    fn nextDispatchDraft(self: *BodyContext, frame: *LowerFrame, task: *DispatchLowerTask) Allocator.Error!LowerStep {
        while (task.draft_index < task.plan_args.len) {
            const index = task.draft_index;
            task.draft_index += 1;
            switch (task.plan_args[index]) {
                .checked_expr => |expr| if (self.isNestedCallableExpr(expr)) {
                    return requestLowerTask(self, .{ .nested_fn = try self.boxLowerTask(NestedFnTask, .{
                        .expr_id = expr,
                        .request_fn_node = task.callable_args[index],
                        .purpose = .draft,
                    }) });
                },
                .generated_interpolation_segments,
                .generated_numeral,
                .generated_quote,
                => {},
            }
        }
        frame.cursor = 1;
        return requestLowerTask(self, .{ .uninhabited_dispatch = .{
            .operands = task.plan_args,
            .arg_nodes = task.callable_args,
            .ret_cell = task.expected_ret_cell,
        } });
    }

    /// The dispatch task's cursor while its lambda operands are drafted.
    const dispatch_drafts_cursor: u8 = 0xf0;

    /// Lower the dispatch's next checked operand at its callable slot, or
    /// finish the dispatch once every checked operand is lowered.
    fn nextDispatchOperand(self: *BodyContext, frame: *LowerFrame, task: *DispatchLowerTask, plan: static_dispatch.StaticDispatchCallPlan) Allocator.Error!LowerStep {
        while (task.index < task.plan_args.len) : (task.index += 1) {
            switch (task.plan_args[task.index]) {
                .checked_expr => |expr| {
                    frame.cursor = 2;
                    return requestLowerChild(self, expr, DraftTypeCell.fromGraphNode(task.callable_args[task.index]));
                },
                .generated_interpolation_segments,
                .generated_numeral,
                .generated_quote,
                => {},
            }
        }

        const checked_ret_ty = task.checked_ret_ty;
        const callable_node = task.callable_node;
        const call_ctx = task.call_ctx.?;
        const plan_args = task.plan_args;
        const pre_lowered = task.pre_lowered.items;
        const plan_ret_node = task.callable_ret;
        // `dispatchTarget` raises the "dispatch plan had no method owner"
        // invariant when the receiver never grounded to a concrete owner and
        // the result mode is not a structural dispatch. That is only
        // reachable inside a bare polymorphic function value never called at
        // a concrete type—e.g. evaluating `run` itself for
        // `run : a -> a where [a.go : a -> a]`. Checking classified such
        // dispatches (`unreachable_dispatch`, or a `checked_error` for
        // reported missing methods); both emit an ordinary Roc runtime crash
        // and never return a dispatch result. A genuinely reachable ownerless
        // dispatch was rejected at check time.
        switch (self.evidenceResolution(plan) orelse
            Common.invariant("CheckedStaticDispatchCallPlan had no MethodTarget or StructuralDerivation")) {
            .target => {},
            .structural => |structural| return self.dispatchLowerDone(task, switch (structural.derivation) {
                .equality => {
                    task.structural_ret_ty = try self.beginStructuralEqualityAtNode(plan, callable_node);
                    frame.cursor = 7;
                    return try self.dispatchOperandsAtCallableStep(plan, callable_node, pre_lowered);
                },
                .hash => {
                    task.structural_ret_ty = try self.beginStructuralHashAtNode(plan, callable_node);
                    frame.cursor = 8;
                    return try self.dispatchOperandsAtCallableStep(plan, callable_node, pre_lowered);
                },
                .parser, .encoder => try self.deferStructuralSerializationAtNode(
                    plan,
                    structural,
                    callable_node,
                    try call_ctx.instNode(plan.dispatcher_ty),
                    pre_lowered,
                ),
                .map => |map_plan| blk: {
                    const callable_mono_ty = try call_ctx.resolvedTypeViewForNode(callable_node);
                    const plan_ret_ty = self.functionShape(callable_mono_ty, "checked structural map plan had a non-function type").ret;
                    break :blk try self.lowerStructuralMap("map", plan, map_plan, callable_mono_ty, plan_ret_ty, self, pre_lowered);
                },
                .map_effectful => |map_plan| blk: {
                    const callable_mono_ty = try call_ctx.resolvedTypeViewForNode(callable_node);
                    const plan_ret_ty = self.functionShape(callable_mono_ty, "checked structural map! plan had a non-function type").ret;
                    break :blk try self.lowerStructuralMap("map!", plan, map_plan, callable_mono_ty, plan_ret_ty, self, pre_lowered);
                },
            }),
        }
        const checked_result_node = if (try self.graph.containsGeneratedPrivate(plan_ret_node))
            try self.freshInstNode(checked_ret_ty)
        else
            try self.lowerTypeNode(checked_ret_ty);
        _ = try checkedMonoRequestNode(self.graph, checked_result_node, plan_ret_node, .exact);
        if (task.direct_parametric_low_level != null) {
            const drafts = try self.relateDispatchOperandsAtNodes(plan_args, task.callable_args, pre_lowered);
            frame.cursor = 3;
            return self.draftCallablesThen(drafts, .{ .prepared_operands = .{
                .operands = plan_args,
                .nodes = task.callable_args,
                .pre_lowered = pre_lowered,
            } });
        }
        frame.cursor = if (task.direct_graph_call) 6 else 5;
        return try self.dispatchOperandsAtCallableStep(plan, callable_node, pre_lowered);
    }

    /// Lower a dispatch's operands not already lowered at the callable's
    /// argument nodes, as a child.
    fn dispatchOperandsAtCallableStep(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
        callable_node: NodeId,
        pre_lowered: []const PreLoweredOperand,
    ) Allocator.Error!LowerStep {
        const fn_nodes = try self.graph.functionNodes(callable_node);
        const operands = plan.argsSlice(self.view.static_dispatch_plans);
        const drafts = try self.relateDispatchOperandsAtNodes(operands, fn_nodes.args, pre_lowered);
        return self.draftCallablesThen(drafts, .{ .prepared_operands = .{
            .operands = operands,
            .nodes = fn_nodes.args,
            .pre_lowered = pre_lowered,
        } });
    }

    fn stepClosedLowLevel(self: *BodyContext, frame: *LowerFrame, task: anytype, input: ?LowerResult) Allocator.Error!LowerStep {
        const plan = task.plan;
        const expected_ret_cell = task.expected_ret_cell;
        if (frame.cursor == 1) {
            const lowered = switch (input.?.closedOperandsValue()) {
                .args => |args| args,
                .uninhabited => |expr| return loweredExprStep(expr),
            };
            const call = try self.addExprWithTypeCell(expected_ret_cell, .{ .low_level = .{
                .op = task.op,
                .args = lowered,
            } });
            return loweredExprStep(try self.applyDispatchResultMode(plan.result_mode, call));
        }
        const callable_ty = blk: {
            var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
            defer timing_scope.end();
            break :blk try self.lowerType(plan.callable_ty);
        };
        const function = self.functionShape(callable_ty, "checked closed direct low-level call had a non-function type");
        const operands = plan.argsSlice(self.view.static_dispatch_plans);
        if (operands.len != self.typeStore().span(function.args).len) {
            Common.invariant("checked closed direct low-level call argument arity differed from its callable type");
        }

        switch (expected_ret_cell) {
            .sealed => |expected| if (!self.sameType(expected, function.ret)) {
                Common.invariant("checked closed direct low-level call result differed from its expected type");
            },
            .graph_node => |expected| try relateRequestComponent(
                self.graph,
                expected,
                try self.activeNodeFromType(function.ret),
            ),
        }

        const arg_types = self.typeStore().span(function.args);
        if (operands.len != GuardedList.borrowLen(arg_types)) {
            Common.invariant("closed dispatch argument arity differed from its sealed callable type");
        }
        frame.cursor = 1;
        return requestLowerTask(self, .{ .closed_operands_at_types = .{
            .operands = operands,
            .stable_types = try GuardedList.dupe(self.allocator, Type.TypeId, arg_types),
            .ret_cell = expected_ret_cell,
        } });
    }

    /// `lowerClosedDispatchOperandsAtTypes`: lower each operand at its sealed
    /// type, or, when an operand's type is proven uninhabited, lower the
    /// operands before it and then the uninhabited operand as a scrutinee.
    fn stepClosedOperandsAtTypes(self: *BodyContext, frame: *LowerFrame, task: *ClosedOperandsAtTypesTask, input: ?LowerResult) Allocator.Error!LowerStep {
        const operands = task.operands;
        const stable_types = task.stable_types;
        switch (frame.cursor) {
            0 => {
                for (stable_types, 0..) |arg_ty, uninhabited_index| {
                    if (!try self.typeIsProvenUninhabited(arg_ty)) continue;
                    switch (operands[uninhabited_index]) {
                        .checked_expr => {},
                        .generated_interpolation_segments,
                        .generated_numeral,
                        .generated_quote,
                        => Common.invariant("compiler-generated dispatch operand had an uninhabited sealed type"),
                    }
                    task.uninhabited_index = uninhabited_index;
                    task.prior = try self.allocator.alloc(DraftExprId, uninhabited_index);
                    break;
                }
                if (task.uninhabited_index == null) {
                    task.reserved = try self.reserveExprSpan(operands.len);
                    task.reserving = true;
                }
                frame.cursor = 1;
            },
            2 => return self.finishClosedOperandsAtUninhabited(task, input.?.exprValue()),
            else => {
                const lowered = input.?.exprValue();
                if (task.uninhabited_index != null) {
                    task.prior[task.index] = lowered;
                } else {
                    self.draft.setReservedExprSpanItem(task.reserved, task.index, lowered);
                }
                task.index += 1;
            },
        }

        const limit = task.uninhabited_index orelse operands.len;
        if (task.index < limit) {
            return requestLowerTask(self, .{ .operand_at_type = .{ .operand = operands[task.index], .ty = stable_types[task.index] } });
        }

        task.reserving = false;
        const uninhabited_index = task.uninhabited_index orelse {
            self.releaseClosedOperandsAtTypes(task);
            return .{ .ret = .{ .closed_operands = .{ .args = task.reserved.span } } };
        };
        frame.cursor = 2;
        return uninhabitedScrutineeStep(self, operands[uninhabited_index].checked_expr, .{ .sealed = stable_types[uninhabited_index] });
    }

    fn releaseClosedOperandsAtTypes(self: *BodyContext, task: *ClosedOperandsAtTypesTask) void {
        self.allocator.free(task.stable_types);
        task.stable_types = &.{};
        self.allocator.free(task.prior);
        task.prior = &.{};
    }

    /// Bind the operands before a proven-uninhabited one, then match on its
    /// lowered scrutinee with no branches.
    fn finishClosedOperandsAtUninhabited(self: *BodyContext, task: *ClosedOperandsAtTypesTask, scrutinee: DraftExprId) Allocator.Error!LowerStep {
        defer self.releaseClosedOperandsAtTypes(task);
        const stable_types = task.stable_types;
        const uninhabited_index = task.uninhabited_index.?;
        const ret_cell = task.ret_cell;
        var result = try self.zeroBranchMatchAtTypeCell(scrutinee, ret_cell);
        var index = uninhabited_index;
        while (index > 0) {
            index -= 1;
            result = try self.addExprWithTypeCell(ret_cell, .{ .let_ = .{
                .bind = try self.addPatWithTypeCell(.{ .sealed = stable_types[index] }, .wildcard),
                .value = task.prior[index],
                .rest = result,
            } });
        }
        return .{ .ret = .{ .closed_operands = .{ .uninhabited = result } } };
    }

    fn stepClosedProcedure(self: *BodyContext, frame: *LowerFrame, task: *ClosedProcedureTask, input: ?LowerResult) Allocator.Error!LowerStep {
        const checked_ret_ty = task.checked_ret_ty;
        const plan = task.plan;
        const expected_ret_cell = task.expected_ret_cell;
        const operands = plan.argsSlice(self.view.static_dispatch_plans);
        if (frame.cursor == 0) {
            const callable_ty = blk: {
                var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
                defer timing_scope.end();
                break :blk try self.lowerType(plan.callable_ty);
            };
            const function = self.functionShape(callable_ty, "checked closed direct procedure call had a non-function type");
            if (operands.len != self.typeStore().span(function.args).len) {
                Common.invariant("checked closed direct procedure call argument arity differed from its callable type");
            }
            try self.constrainTypeToMono(checked_ret_ty, function.ret);
            switch (expected_ret_cell) {
                .sealed => |expected| if (!self.sameType(expected, function.ret)) {
                    Common.invariant("checked closed direct procedure call result differed from its expected type");
                },
                .graph_node => |expected| try relateRequestComponent(
                    self.graph,
                    expected,
                    try self.activeNodeFromType(function.ret),
                ),
            }

            task.callable_node = try self.activeNodeFromType(callable_ty);
            frame.cursor = 1;
            return requestLowerTask(self, .{ .closed_operands_at_node = .{
                .operands = operands,
                .callable_node = task.callable_node,
                .expected_ret_cell = expected_ret_cell,
            } });
        }
        const callable_node = task.callable_node;
        const lowered = switch (input.?.closedOperandsValue()) {
            .args => |args| args,
            .uninhabited => |expr| return loweredExprStep(expr),
        };
        const evidence_id = task.evidence_id;
        const procedure = task.procedure;
        const evidence_node = self.view.static_dispatch_plans.evidenceNode(evidence_id);
        const lookup = self.methodLookupForResolvedTarget(evidence_node.target);
        const direct_key = ClosedDirectCallIdentity{
            .callable = checkedTypeAddress(self.view, plan.callable_ty),
            .evidence = evidence_id,
            .method_scope = self.method_scope.key,
        };
        const slot = if (self.draft.closed_direct_specializations.get(direct_key)) |existing| blk: {
            if (existing.draft_spec) |raw_spec| {
                if (raw_spec >= self.draft.template_specs.items.len) {
                    Common.invariant("closed direct call cache referenced a missing draft specialization");
                }
                const spec = &self.draft.template_specs.items[raw_spec];
                if (spec.state != .deferred and !runtimeDemandGuardFrameSetsEql(
                    spec.runtime_demand_guard_frames,
                    try self.runtimeDemandGuardFrameAddresses(),
                )) {
                    try self.draft.template_spec_reuses.append(self.allocator, .{
                        .spec = raw_spec,
                        .prefix_proof = try self.currentRuntimeImpossibilityProof(null),
                    });
                }
            }
            break :blk existing.slot;
        } else blk: {
            const subst = (try self.directDispatchTargetSubstitution(plan, lookup, callable_node)) orelse
                Common.invariant("closed direct procedure call had no checked substitution");
            const template = lookup.view.templates.get(procedure.template.template);
            if (subst.len != template.scheme_vars.len) {
                Common.invariant("closed direct procedure call substitution length differed from its scheme");
            }
            const edge: EdgeEvidence = .{
                .subst = subst,
                .vector = try self.deriveEvidenceVector(
                    templateSchemaIn(lookup.view, &template),
                    subst,
                    self.view,
                    if (self.dispatchTargetContract(plan)) |c| c.entries else null,
                    .body_lowering,
                ),
            };
            const source_fn_ty = lookup.target.callable_ty;
            const created = try self.builder.lowerDraftTemplateFromContext(
                self,
                procedure.template,
                source_fn_ty,
                lookup.view.types.rootKey(source_fn_ty),
                callable_node,
                edge,
                .instantiation,
                .independent_roots,
                .inherit,
            );
            const draft_spec: ?u32 = switch (created.local) {
                .draft => |draft_fn| self.draft.template_spec_by_fn.get(draft_fn) orelse
                    Common.invariant("closed direct call created a draft function without a specialization record"),
                .final => null,
            };
            try self.draft.closed_direct_specializations.put(direct_key, .{
                .slot = created,
                .draft_spec = draft_spec,
            });
            break :blk created;
        };
        const completed_callable_node = try self.draftFnSlotTypeNode(slot, callable_node);
        const completed_function = try self.graph.functionNodes(completed_callable_node);
        if (completed_function.args.len != operands.len) {
            Common.invariant("completed closed direct procedure call changed its argument arity");
        }
        const completed_ret_is_private = try self.graph.containsGeneratedPrivate(completed_function.ret);
        if (completed_ret_is_private) {
            try relateRequestComponent(
                self.graph,
                try expected_ret_cell.toGraphNode(self.graph),
                completed_function.ret,
            );
        }
        const call_ret_cell = if (completed_ret_is_private)
            DraftTypeCell.fromGraphNode(completed_function.ret)
        else
            expected_ret_cell;
        const call = try self.addExprWithTypeCell(call_ret_cell, .{ .call_proc = .{
            .callee = draftProcCalleeForSlot(slot),
            .args = lowered,
            .iterator_procedure = procedure.runtime_target.iteratorProcedure(),
            .captures = try self.methodTargetCaptureSpan(lookup),
        } });
        return loweredExprStep(try self.applyDispatchResultMode(plan.result_mode, call));
    }

    fn stepClosedOperandsAtNode(self: *BodyContext, frame: *LowerFrame, task: anytype, input: ?LowerResult) Allocator.Error!LowerStep {
        switch (frame.cursor) {
            0 => {
                const function = blk: {
                    var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
                    defer timing_scope.end();
                    break :blk try self.graph.functionNodes(task.callable_node);
                };
                if (task.operands.len != function.args.len) {
                    Common.invariant("closed dispatch argument arity differed from its callable type");
                }
                task.arg_nodes = function.args;
                const drafts = try self.relateDispatchOperandsAtNodes(task.operands, function.args, &.{});
                frame.cursor = 1;
                return self.draftCallablesThen(drafts, .{ .uninhabited_dispatch = .{
                    .operands = task.operands,
                    .arg_nodes = function.args,
                    .ret_cell = task.expected_ret_cell,
                } });
            },
            1 => {
                if (input.?.maybeExprValue()) |uninhabited| {
                    return .{ .ret = .{ .closed_operands = .{ .uninhabited = uninhabited } } };
                }
                frame.cursor = 2;
                return requestLowerTask(self, .{ .prepared_operands = .{
                    .operands = task.operands,
                    .nodes = task.arg_nodes,
                    .pre_lowered = &.{},
                } });
            },
            else => return .{ .ret = .{ .closed_operands = .{ .args = input.?.spanValue() } } },
        }
    }

    /// Lower each dispatch operand not already
    /// lowered at its slot node.
    fn stepPreparedOperands(self: *BodyContext, frame: *LowerFrame, task: *PreparedOperandsTask, input: ?LowerResult) Allocator.Error!LowerStep {
        const operands = task.operands;
        const nodes = task.nodes;
        if (frame.cursor == 0) {
            if (operands.len != nodes.len) Common.invariant("dispatch argument arity differs from function graph node");
            task.reserved = try self.reserveExprSpan(operands.len);
            task.reserving = true;
            frame.cursor = 1;
        } else {
            const lowered = input.?.exprValue();
            self.draft.setReservedExprSpanItem(task.reserved, task.index, lowered);
            try relateRequestComponent(
                self.graph,
                nodes[task.index],
                try self.exprTypeCell(lowered).toGraphNode(self.graph),
            );
            task.index += 1;
        }
        while (task.index < operands.len) : (task.index += 1) {
            if (self.preLoweredOperandAt(task.pre_lowered, task.index)) |pre| {
                self.draft.setReservedExprSpanItem(task.reserved, task.index, pre);
                continue;
            }
            const operand = operands[task.index];
            const node = nodes[task.index];
            return switch (operand) {
                .checked_expr => |expr| requestLowerChild(self, expr, DraftTypeCell.fromGraphNode(node)),
                .generated_interpolation_segments,
                .generated_numeral,
                .generated_quote,
                => requestLowerTask(self, .{ .operand_at_type = .{ .operand = operand, .ty = try self.activeTypeFromNode(node) } }),
            };
        }
        task.reserving = false;
        return .{ .ret = .{ .span = task.reserved.span } };
    }

    fn stepOperandAtType(self: *BodyContext, frame: *LowerFrame, task: anytype, input: ?LowerResult) Allocator.Error!LowerStep {
        if (frame.cursor == 1) return .{ .ret = input.? };
        return switch (task.operand) {
            .checked_expr => |expr| blk: {
                frame.cursor = 1;
                break :blk requestLowerChild(self, expr, .{ .sealed = task.ty });
            },
            .generated_interpolation_segments => |expr| loweredExprStep(try self.lowerInterpolationSegments(expr, task.ty)),
            .generated_numeral => |literal| loweredExprStep(try self.lowerNumeralValue(literal, task.ty)),
            .generated_quote => |literal| loweredExprStep(try self.lowerQuoteValue(literal, task.ty)),
        };
    }

    /// `lowerDispatchWithUninhabitedArgument`: when an operand's slot is
    /// proven uninhabited, lower the operands before it, then that operand as
    /// the scrutinee of a zero-branch match.
    fn stepUninhabitedDispatch(self: *BodyContext, frame: *LowerFrame, task: *UninhabitedArgumentTask, input: ?LowerResult) Allocator.Error!LowerStep {
        const arg_nodes = task.arg_nodes;
        const operands = task.operands;
        if (frame.cursor == 0) {
            if (operands.len != arg_nodes.len) {
                Common.invariant("dispatch argument arity differed while lowering an uninhabited invocation");
            }
            const uninhabited_index = for (arg_nodes, 0..) |arg_node, index| {
                if (try self.nodeIsProvenUninhabited(arg_node)) break index;
            } else return .{ .ret = .{ .maybe_expr = null } };
            switch (operands[uninhabited_index]) {
                .checked_expr => {},
                .generated_interpolation_segments,
                .generated_numeral,
                .generated_quote,
                => Common.invariant("compiler-generated dispatch operand had an uninhabited type"),
            }
            task.uninhabited_index = uninhabited_index;
            task.prior = try self.allocator.alloc(DraftExprId, uninhabited_index);
            frame.cursor = 1;
        } else if (!task.scrutinee_requested) {
            task.prior[task.index] = input.?.exprValue();
            task.index += 1;
        }

        if (task.index < task.uninhabited_index) {
            const prior_node = arg_nodes[task.index];
            return switch (operands[task.index]) {
                .checked_expr => |expr| requestLowerChild(self, expr, DraftTypeCell.fromGraphNode(prior_node)),
                .generated_interpolation_segments,
                .generated_numeral,
                .generated_quote,
                => requestLowerTask(self, .{ .operand_at_type = .{ .operand = operands[task.index], .ty = try self.activeTypeFromNode(prior_node) } }),
            };
        }

        if (!task.scrutinee_requested) {
            task.scrutinee_requested = true;
            const arg_cell = DraftTypeCell.fromGraphNode(arg_nodes[task.uninhabited_index]);
            return uninhabitedScrutineeStep(self, operands[task.uninhabited_index].checked_expr, arg_cell);
        }
        defer {
            self.allocator.free(task.prior);
            task.prior = &.{};
        }
        const uninhabited_index = task.uninhabited_index;
        const scrutinee = input.?.exprValue();
        const ret_cell = task.ret_cell;
        var result = try self.zeroBranchMatchAtTypeCell(scrutinee, ret_cell);
        var index = uninhabited_index;
        while (index > 0) {
            index -= 1;
            const prior_cell = DraftTypeCell.fromGraphNode(arg_nodes[index]);
            result = try self.addExprWithTypeCell(ret_cell, .{ .let_ = .{
                .bind = try self.addPatWithTypeCell(prior_cell, .wildcard),
                .value = task.prior[index],
                .rest = result,
            } });
        }
        return .{ .ret = .{ .maybe_expr = result } };
    }

    /// `lowerDirectCallWithUninhabitedArgument`: when an argument's slot is
    /// proven uninhabited, lower the arguments before it through their graph
    /// cells, then that argument as the scrutinee of a zero-branch match.
    fn stepUninhabitedCall(self: *BodyContext, frame: *LowerFrame, task: *UninhabitedArgumentTask, input: ?LowerResult) Allocator.Error!LowerStep {
        const arg_nodes = task.arg_nodes;
        if (frame.cursor == 0) {
            const uninhabited_index = for (arg_nodes, 0..) |arg_node, index| {
                if (try self.nodeIsProvenUninhabited(arg_node)) break index;
            } else return .{ .ret = .{ .maybe_call = null } };
            task.uninhabited_index = uninhabited_index;
            task.prior = try self.allocator.alloc(DraftExprId, uninhabited_index);
            frame.cursor = 1;
        } else if (!task.scrutinee_requested) {
            task.prior[task.index] = input.?.exprValue();
            task.index += 1;
        }

        if (task.index < task.uninhabited_index) {
            return requestLowerChild(self, task.checked_args[task.index], DraftTypeCell.fromGraphNode(arg_nodes[task.index]));
        }

        if (!task.scrutinee_requested) {
            task.scrutinee_requested = true;
            const uninhabited_cell = DraftTypeCell.fromGraphNode(arg_nodes[task.uninhabited_index]);
            return uninhabitedScrutineeStep(self, task.checked_args[task.uninhabited_index], uninhabited_cell);
        }
        defer {
            self.allocator.free(task.prior);
            task.prior = &.{};
        }
        const uninhabited_index = task.uninhabited_index;
        const scrutinee = input.?.exprValue();
        const ret_cell = task.ret_cell;
        var result = try self.addExprWithTypeCell(ret_cell, .{ .match_ = .{
            .scrutinee = scrutinee,
            .branches = try self.addBranchSpan(&.{}),
            .comptime_site = null,
        } });
        var index = uninhabited_index;
        while (index > 0) {
            index -= 1;
            const arg_cell = DraftTypeCell.fromGraphNode(arg_nodes[index]);
            result = try self.addExprWithTypeCell(ret_cell, .{ .let_ = .{
                .bind = try self.addPatWithTypeCell(arg_cell, .wildcard),
                .value = task.prior[index],
                .rest = result,
            } });
        }
        return .{ .ret = .{ .maybe_call = .{
            .ret_ty = ret_cell,
            .data = try self.exprIdAsDivergentData(result),
        } } };
    }

    const SpanMode = enum {
        /// `lowerExprSpan`: each child at its own expression type node.
        typed_by_expr,
        /// Each child at its prepared node.
        at_nodes,
        /// `lowerExprSpanAtTypes`: each child at its sealed type.
        at_types,
        /// `lowerListExpr`: each element at the list's element type.
        list_elements,
    };

    /// A span task lowering each child at its sealed type, owning a stable
    /// copy of those types.
    fn spanAtTypesTask(self: *BodyContext, exprs: []const checked.CheckedExprId, tys: anytype) Allocator.Error!LowerTask {
        if (exprs.len != GuardedList.borrowLen(tys)) Common.invariant("call argument arity differs from concrete function type");
        return .{ .span_at_types = .{
            .exprs = exprs,
            .types = try GuardedList.dupe(self.allocator, Type.TypeId, tys),
            .owns_types = true,
        } };
    }

    fn stepSpan(self: *BodyContext, frame: *LowerFrame, task: *SpanTask, input: ?LowerResult, mode: SpanMode) Allocator.Error!LowerStep {
        const exprs = task.exprs;
        if (frame.cursor == 0) {
            switch (mode) {
                .typed_by_expr, .at_types => {},
                .at_nodes => if (exprs.len != task.nodes.len) Common.invariant("checked call argument count differed from graph function arity"),
                .list_elements => task.elem_ty = switch (self.shapeContent(task.list_ty)) {
                    .list => |elem| elem,
                    .primitive, .named, .record, .tuple, .tag_union, .box, .func, .erased, .zst => Common.invariant("list expression had a non-list monotype"),
                },
            }
            task.reserved = try self.reserveExprSpan(exprs.len);
            task.reserving = true;
            frame.cursor = 1;
        } else {
            const lowered = if (task.uninhabited_ty) |ty|
                try self.zeroBranchMatch(input.?.exprValue(), ty)
            else
                input.?.exprValue();
            task.uninhabited_ty = null;
            self.draft.setReservedExprSpanItem(task.reserved, task.index, lowered);
            task.index += 1;
        }
        if (task.index < exprs.len) {
            const child = exprs[task.index];
            const ty = switch (mode) {
                .typed_by_expr => return requestLowerChild(self, child, DraftTypeCell.fromGraphNode(try self.lowerExprTypeNode(child))),
                .at_nodes => return requestLowerChild(self, child, DraftTypeCell.fromGraphNode(task.nodes[task.index])),
                .at_types => task.types[task.index],
                .list_elements => task.elem_ty,
            };
            if (!try self.typeIsProvenUninhabited(ty)) return requestLowerChild(self, child, .{ .sealed = ty });
            task.uninhabited_ty = ty;
            return uninhabitedScrutineeStep(self, child, .{ .sealed = ty });
        }
        task.reserving = false;
        self.releaseSpanTask(task);
        return .{ .ret = .{ .span = task.reserved.span } };
    }

    fn releaseSpanTask(self: *BodyContext, task: *SpanTask) void {
        if (task.reserving) {
            self.draft.expr_ids.shrinkRetainingCapacity(task.reserved.span.start);
            task.reserving = false;
        }
        if (task.owns_types) {
            self.allocator.free(task.types);
            task.types = &.{};
            task.owns_types = false;
        }
    }

    fn callLowerDone(self: *BodyContext, task: *CallLowerTask, lowered: LoweredCall) LowerStep {
        if (task.call_ctx) |call_ctx| self.destroyCallContext(call_ctx);
        task.call_ctx = null;
        task.timing.end();
        return .{ .ret = .{ .call = lowered } };
    }

    /// The call task's cursor while a divergent operand's effect lowers.
    const divergent_call_cursor: u8 = 0xff;
    /// The generated iterator whose `next` a direct call reads.
    const iterator_next_cursor: u8 = 0xfe;
    /// A direct call's arguments are related to its request and every lambda
    /// argument is drafted.
    const direct_args_prepared_cursor: u8 = 0xfd;
    /// An indirect call's arguments are related to its instantiated callee.
    const indirect_args_prepared_cursor: u8 = 0xfc;

    /// `lowerCallAtExpectedNode`
    fn stepCallLower(self: *BodyContext, frame: *LowerFrame, task: *CallLowerTask, input: ?LowerResult) Allocator.Error!LowerStep {
        const checked_expr = task.expr;
        const checked_ret_ty = task.checked_ret_ty;
        const call = task.call;
        switch (frame.cursor) {
            divergent_call_cursor => return self.callLowerDone(task, .{
                .ret_ty = task.divergent_ret_cell,
                .data = try self.exprIdAsDivergentData(input.?.exprValue()),
            }),
            iterator_next_cursor => {
                const iterator_node = task.fn_nodes.args[0];
                return self.callLowerDone(task, .{
                    .ret_ty = DraftTypeCell.fromGraphNode(task.fn_nodes.ret),
                    .data = try self.lowerGeneratedIteratorNextData(input.?.exprValue(), iterator_node),
                });
            },
            0 => {
                const expected_ret_node = task.expected_ret_node;
                const expected_ret_ty = task.expected_ret_ty;
                task.timing = BodyWorkTimingScope.begin(self.builder.timing, .call_dispatch);
                self.builder.countBodyDiagnostic("call_expressions");
                if (self.divergentCallOperand(call)) |operand| {
                    task.divergent_ret_cell = if (expected_ret_node) |expected|
                        DraftTypeCell.fromGraphNode(expected)
                    else
                        try self.lowerTypeCell(checked_ret_ty);
                    try self.constrainCheckedInterfaceToCell(checked_ret_ty, task.divergent_ret_cell);
                    frame.cursor = divergent_call_cursor;
                    return divergentStep(self, operand, .{ .at_cell = task.divergent_ret_cell });
                }

                if (call.direct_target) |target| {
                    const source_fn_ty = self.directCallInstantiationSourceFnType(target, call.source_fn_ty_payload);
                    task.iterator_procedure = self.iteratorProcedureForResolvedTarget(target);
                    const fn_node = try self.directCallRequestNode(
                        checked_expr,
                        target,
                        call,
                        checked_ret_ty,
                        source_fn_ty,
                        expected_ret_node,
                    );
                    const fn_nodes = try self.graph.functionNodes(fn_node);
                    task.fn_node = fn_node;
                    task.fn_nodes = fn_nodes;
                    frame.cursor = direct_args_prepared_cursor;
                    return requestLowerTask(self, try self.hostedEvidenceTask(.{ .prepare_direct_args = .{
                        .expr = checked_expr,
                        .fn_node = fn_node,
                        .checked_exprs = call.args,
                        .nodes = fn_nodes.args,
                    } }));
                }

                if (try self.indirectCalleeMonoType(call.func, call.args, expected_ret_ty)) |fn_ty| {
                    const fn_data = self.functionShape(fn_ty, "checked call function type was not a function");
                    try self.constrainTypeToMono(checked_ret_ty, fn_data.ret);
                    if (expected_ret_ty) |expected| {
                        if (!self.sameType(expected, fn_data.ret)) {
                            Common.invariant("checked indirect call result type differed from its expected Monotype type");
                        }
                    }
                    task.fn_ty = fn_ty;
                    frame.cursor = 4;
                    return requestLowerChild(self, call.func, .{ .sealed = fn_ty });
                }

                const call_ctx = try self.createCallContext();
                task.call_ctx = call_ctx;
                const fn_node = try call_ctx.instantiateCallNodeFromCallerAtNode(
                    call.source_fn_ty_payload,
                    self,
                    checked_ret_ty,
                    call.args,
                    expected_ret_node,
                    null,
                    false,
                );
                const fn_nodes = try self.graph.functionNodes(fn_node);
                task.fn_node = fn_node;
                task.fn_nodes = fn_nodes;
                frame.cursor = indirect_args_prepared_cursor;
                return requestLowerTask(self, try self.hostedEvidenceTask(.{ .prepare_span = .{
                    .checked_exprs = call.args,
                    .nodes = fn_nodes.args,
                } }));
            },
            direct_args_prepared_cursor => {
                frame.cursor = 1;
                return requestLowerTask(self, .{ .uninhabited_call = .{
                    .checked_args = call.args,
                    .arg_nodes = task.fn_nodes.args,
                    .ret_cell = DraftTypeCell.fromGraphNode(task.fn_nodes.ret),
                } });
            },
            indirect_args_prepared_cursor => {
                frame.cursor = 6;
                return requestLowerChild(self, call.func, DraftTypeCell.fromGraphNode(task.fn_node));
            },
            // A direct call's uninhabited-argument check.
            1 => {
                if (input.?.maybeCallValue()) |lowered| return self.callLowerDone(task, lowered);
                const target = call.direct_target.?;
                const fn_nodes = task.fn_nodes;
                if (task.iterator_procedure) |procedure| {
                    if ((try self.generatedIteratorNextOperand(procedure, call.args, fn_nodes))) |iterator| {
                        frame.cursor = iterator_next_cursor;
                        return requestLowerChild(self, iterator, DraftTypeCell.fromGraphNode(fn_nodes.args[0]));
                    }
                }
                const source_fn_ty = self.directCallInstantiationSourceFnType(target, call.source_fn_ty_payload);
                if (self.resolvedTargetIsStrInspect(target)) {
                    frame.cursor = 2;
                    return requestLowerTask(self, .{ .prepared_span = .{ .exprs = call.args, .nodes = fn_nodes.args } });
                }
                const completed = try self.completedDirectCalleeAtNode(checked_expr, target, source_fn_ty, task.fn_node);
                const callee_fn_nodes = try self.graph.functionNodes(completed.fn_node);
                if (callee_fn_nodes.args.len != fn_nodes.args.len) {
                    Common.invariant("completed direct-call specialization changed argument arity");
                }
                task.callee = completed.callee;
                task.callee_ret = callee_fn_nodes.ret;
                frame.cursor = 3;
                return requestLowerTask(self, .{ .prepared_span = .{ .exprs = call.args, .nodes = fn_nodes.args } });
            },
            // `Str.inspect`'s argument.
            2 => {
                const args = input.?.spanValue();
                const target = call.direct_target.?;
                const source_fn_ty = self.directCallInstantiationSourceFnType(target, call.source_fn_ty_payload);
                const source_fn_key = self.view.types.rootKey(source_fn_ty);
                if (args.len != 1) Common.invariant("Str.inspect call did not have exactly one lowered argument");
                const callee = try self.fnTemplateForDirectCallAtNode(target, source_fn_ty, source_fn_key, task.fn_node);
                const captures = try self.directCallCaptureSpan(target);
                return self.callLowerDone(task, .{
                    .ret_ty = DraftTypeCell.fromGraphNode(task.fn_nodes.ret),
                    .data = .{ .call_proc = .{
                        .callee = .{ .func = callee },
                        .args = args,
                        .iterator_procedure = task.iterator_procedure,
                        .captures = captures,
                    } },
                });
            },
            // A completed direct call's arguments.
            3 => {
                const lowered_args = input.?.spanValue();
                const captures = try self.directCallCaptureSpan(call.direct_target.?);
                return self.callLowerDone(task, .{
                    .ret_ty = DraftTypeCell.fromGraphNode(task.callee_ret),
                    .data = .{ .call_proc = .{
                        .callee = .{ .func = task.callee },
                        .args = lowered_args,
                        .iterator_procedure = task.iterator_procedure,
                        .captures = captures,
                    } },
                });
            },
            // A sealed indirect callee, then its arguments.
            4 => {
                task.callee_expr = input.?.exprValue();
                const fn_data = self.functionShape(task.fn_ty, "checked call function type was not a function");
                frame.cursor = 5;
                return requestLowerTask(self, try self.spanAtTypesTask(call.args, self.typeStore().span(fn_data.args)));
            },
            5 => {
                const fn_data = self.functionShape(task.fn_ty, "checked call function type was not a function");
                return self.callLowerDone(task, .{
                    .ret_ty = .{ .sealed = fn_data.ret },
                    .data = .{ .call_value = .{
                        .callee = task.callee_expr,
                        .args = input.?.spanValue(),
                    } },
                });
            },
            // A graph-instantiated indirect callee, then its arguments.
            6 => {
                task.callee_expr = input.?.exprValue();
                frame.cursor = 7;
                return requestLowerTask(self, .{ .prepared_span = .{ .exprs = call.args, .nodes = task.fn_nodes.args } });
            },
            else => return self.callLowerDone(task, .{
                .ret_ty = DraftTypeCell.fromGraphNode(task.fn_nodes.ret),
                .data = .{ .call_value = .{
                    .callee = task.callee_expr,
                    .args = input.?.spanValue(),
                } },
            }),
        }
    }

    /// `lowerCallExprAtNode`
    fn stepCallExprAtNode(self: *BodyContext, frame: *LowerFrame, task: anytype, input: ?LowerResult) Allocator.Error!LowerStep {
        const checked_expr = task.expr;
        const expected_node = task.expected_node;
        const expr = self.view.bodies.expr(checked_expr);
        const call = switch (expr.data) {
            .call => |call| call,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("call-at-node lowering received a non-call expression"),
        };
        switch (frame.cursor) {
            0 => {},
            1 => {
                const call_data = input.?.callValue();
                return loweredExprStep(try self.finishCallExprAtNode(expected_node, try self.addExprWithTypeCell(call_data.ret_ty, call_data.data)));
            },
            // A function value rendered after its evaluation.
            else => return loweredExprStep(try self.finishCallExprAtNode(expected_node, input.?.exprValue())),
        }
        const producer_request = if ((try isGeneratedPrivateRootNode(self.graph, expected_node))) expected_node else null;
        if (try self.inspectOnlyCallStep(
            expr.ty,
            call,
            try self.primitiveType(.str),
            self.inspectCallDemand(call),
        )) |step| switch (step) {
            .ret => |result| return loweredExprStep(try self.finishCallExprAtNode(expected_node, result.exprValue())),
            .call => {
                frame.cursor = 2;
                return step;
            },
        };
        if (try self.restoredHoistedExprAtNode(checked_expr, expected_node)) |restored| {
            return loweredExprStep(try self.finishCallExprAtNode(expected_node, restored));
        }
        if (try self.callsiteIntrinsicCallTask(checked_expr, expr.ty, call, producer_request, null)) |intrinsic| {
            frame.cursor = 2;
            return requestLowerTask(self, intrinsic);
        }
        // Preserve the expected result as an active graph relation. It may
        // contain unresolved payload cells here, so materializing it as a
        // Monotype TypeId would emit an incomplete output.
        frame.cursor = 1;
        return requestLowerTask(self, .{ .call = .{
            .expr = checked_expr,
            .checked_ret_ty = expr.ty,
            .call = call,
            .expected_ret_node = producer_request,
            .expected_ret_ty = null,
        } });
    }

    fn finishCallExprAtNode(self: *BodyContext, expected_node: NodeId, lowered: DraftExprId) Allocator.Error!DraftExprId {
        const lowered_node = try self.exprTypeCell(lowered).toGraphNode(self.graph);
        const completes_request = try self.resultCompletesRequest(expected_node, lowered_node);
        const contains_generated_private = try self.graph.containsGeneratedPrivate(lowered_node);
        const result_node = if (completes_request)
            lowered_node
        else if (contains_generated_private) blk: {
            try relateRequestComponent(
                self.graph,
                expected_node,
                lowered_node,
            );
            break :blk lowered_node;
        } else try self.relateCheckedNodeToProducedValue(expected_node, lowered_node);
        self.draft.exprs.items[@backingInt(lowered)].ty = DraftTypeCell.fromGraphNode(
            result_node,
        );
        return lowered;
    }

    /// `lowerCallExpr`
    fn stepCallExpr(self: *BodyContext, frame: *LowerFrame, task: anytype, input: ?LowerResult) Allocator.Error!LowerStep {
        const checked_expr_id = task.expr;
        const checked_ret_ty = task.checked_ret_ty;
        if (frame.cursor == 0) {
            if (try self.callsiteIntrinsicCallTask(checked_expr_id, checked_ret_ty, task.call, null, null)) |intrinsic| {
                frame.cursor = 2;
                return requestLowerTask(self, intrinsic);
            }
            frame.cursor = 1;
            return requestLowerTask(self, .{ .call = .{
                .expr = checked_expr_id,
                .checked_ret_ty = checked_ret_ty,
                .call = task.call,
                .expected_ret_node = null,
                .expected_ret_ty = null,
            } });
        }
        // A call-site intrinsic lowered by its own frame.
        if (frame.cursor == 2) return .{ .ret = input.? };
        const lowered = input.?.callValue();
        const ret_node = try lowered.ret_ty.toGraphNode(self.graph);
        const checked_ret_node = try self.lowerExprTypeNode(checked_expr_id);
        var result_request_node = checked_ret_node;
        if (!self.graph.sameClass(ret_node, checked_ret_node)) {
            const public_ret = if (try self.graph.containsGeneratedPrivate(checked_ret_node))
                try self.freshInstNode(checked_ret_ty)
            else
                checked_ret_node;
            result_request_node = public_ret;
            if (!try self.resultCompletesRequest(public_ret, ret_node) or
                try self.graph.containsGeneratedPrivate(ret_node))
            {
                if (try self.graph.containsGeneratedPrivate(ret_node))
                    try relateRequestComponent(self.graph, public_ret, ret_node)
                else
                    _ = try self.relateCheckedNodeToProducedValue(public_ret, ret_node);
            }
        }
        return loweredExprStep(try self.addExprWithTypeCell(
            try self.producedResultCell(result_request_node, lowered.ret_ty),
            lowered.data,
        ));
    }

    fn lowerExpr(self: *BodyContext, expr_id: checked.CheckedExprId) Allocator.Error!DraftExprId {
        return (try self.runLower(.{ .expr = .{ .expr = expr_id } })).exprValue();
    }

    fn lowerComptimeRootExprAtCell(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        const exhaustiveness_scope = self.comptime_exhaustiveness_context.enterCompileTimeRoot();
        defer exhaustiveness_scope.leave();
        return try self.lowerExprAtTypeCell(expr_id, cell);
    }

    fn shouldRecordComptimeSite(self: *const BodyContext, kind: ExhaustivenessContext.SiteKind) bool {
        return self.comptime_exhaustiveness_context.shouldRecordSite(kind);
    }

    fn loweringOwnHoistedConstRoot(self: *BodyContext, entry: checked.HoistedConstEntry) bool {
        if (self.in_deferred_body) return false;
        if (self.current_entry_root) |entry_root| {
            return moduleBytesEqual(entry_root.module.bytes, self.view.key.bytes) and entry.root == entry_root.root;
        }
        return false;
    }

    fn restoredHoistedConstAtType(
        self: *BodyContext,
        entry: checked.HoistedConstEntry,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const template = self.view.const_templates.get(entry.const_ref);
        const source_region = self.hoistedConstSourceRegion(entry);
        return switch (template.state) {
            .stored_const => |stored| blk: {
                const stored_ty = try self.storedConstRootMonoType(self.view, stored, entry.checked_type);
                if (!self.sameType(ty, stored_ty)) {
                    Common.invariant("stored hoisted const representation differed from its expected Monotype type");
                }
                const saved_loc = self.builder.current_loc;
                defer self.builder.current_loc = saved_loc;
                const saved_region = self.builder.current_region;
                defer self.builder.current_region = saved_region;
                self.builder.current_loc = try self.sourceLocFor(source_region);
                self.builder.current_region = source_region;
                break :blk try self.restoredStaticDataCandidateNode(
                    self.view,
                    self.view,
                    stored.node,
                    stored_ty,
                    entry.const_ref,
                    entry.checked_type,
                    .disallow,
                );
            },
            .eval_template => |eval| blk: {
                try self.constrainTypeToMono(entry.checked_type, ty);
                break :blk try self.lowerConstEvalTemplateUse(self.view, eval, entry.const_ref, ty, source_region, .{ .module = self.view.key, .root = entry.root });
            },
            .reserved => Common.invariant("reserved hoisted const template reached Monotype"),
            .unimplemented => Common.invariant("declaration with no implementation reached hoisted const restoration"),
        };
    }

    fn restoredHoistedConstAtNode(
        self: *BodyContext,
        entry: checked.HoistedConstEntry,
        request_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const template = self.view.const_templates.get(entry.const_ref);
        const source_region = self.hoistedConstSourceRegion(entry);
        return switch (template.state) {
            .stored_const => |stored| blk: {
                const stored_node = try self.storedConstRootTypeNode(self.view, stored, entry.checked_type);
                try relateRequestComponent(self.graph, request_node, stored_node);
                const saved_loc = self.builder.current_loc;
                defer self.builder.current_loc = saved_loc;
                const saved_region = self.builder.current_region;
                defer self.builder.current_region = saved_region;
                self.builder.current_loc = try self.sourceLocFor(source_region);
                self.builder.current_region = source_region;
                break :blk try self.restoredStaticDataCandidateNodeAtNode(
                    self.view,
                    self.view,
                    stored.node,
                    stored_node,
                    entry.const_ref,
                    entry.checked_type,
                    .disallow,
                );
            },
            .eval_template => |eval| blk: {
                try self.graph.unify(try self.instNode(entry.checked_type), request_node);
                break :blk try self.lowerConstEvalTemplateUseAtNode(
                    self.view,
                    eval,
                    entry.const_ref,
                    request_node,
                    source_region,
                    .{ .module = self.view.key, .root = entry.root },
                );
            },
            .reserved => Common.invariant("reserved hoisted const template reached Monotype"),
            .unimplemented => Common.invariant("declaration with no implementation reached hoisted const restoration"),
        };
    }

    fn hoistedConstSourceRegion(self: *const BodyContext, entry: checked.HoistedConstEntry) base.Region {
        if (entry.pattern) |pattern| {
            return self.view.bodies.pattern(pattern).source_region;
        }
        return self.view.bodies.expr(entry.expr).source_region;
    }

    fn restoredHoistedExprAtType(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        ty: Type.TypeId,
    ) Allocator.Error!?DraftExprId {
        const entry = self.restoredHoistedConstEntry(expr_id) orelse return null;
        return try self.restoredHoistedConstAtType(entry, ty);
    }

    fn restoredHoistedExprAtNode(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        request_node: NodeId,
    ) Allocator.Error!?DraftExprId {
        const entry = self.restoredHoistedConstEntry(expr_id) orelse return null;
        return try self.restoredHoistedConstAtNode(entry, request_node);
    }

    /// The hoisted const an expression lowers by restoring, rather than by
    /// lowering its own checked body.
    fn restoredHoistedConstEntry(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
    ) ?checked.HoistedConstEntry {
        const entry = self.view.hoisted_constants.lookupByExpr(expr_id) orelse return null;
        if (self.loweringOwnHoistedConstRoot(entry)) return null;
        if (hoistedConstRunsAtRuntime(self.view, entry)) return null;
        // A guarded binding root's declaration stays in the runtime body with
        // its original right-hand side; the binder's uses read that local.
        if (entry.pattern != null and self.view.compile_time_roots.root(entry.root).guarded) return null;
        if (self.in_place_statement_expr != null and self.in_place_statement_expr.? == expr_id) return null;
        return entry;
    }

    /// A guarded hoisted root whose compile-time evaluation failed has no
    /// stored value. Its original expression and declaration lower in place.
    fn hoistedConstRunsAtRuntime(view: ModuleView, entry: checked.HoistedConstEntry) bool {
        return view.compile_time_roots.root(entry.root).payload == .runtime;
    }

    fn selectedHoistedConstEntry(
        self: *BodyContext,
        selected: checked.SelectedHoistedConstUse,
    ) checked.HoistedConstEntry {
        const const_ref = selected.const_use.const_ref;
        const module_id = checked.constModuleId(const_ref);
        if (!moduleBytesEqual(module_id.bytes, self.view.key.bytes)) {
            Common.invariant("selected hoisted local const ref referenced a different checked module");
        }
        const hoisted = switch (const_ref.owner) {
            .hoisted_expr => |owner| owner,
            .top_level_binding => Common.invariant("selected hoisted local const ref did not reference a hoisted const"),
        };
        if (hoisted.module_idx != self.view.module_identity.module_idx) {
            Common.invariant("selected hoisted local const ref had mismatched module index");
        }
        return self.view.hoisted_constants.lookupByExpr(hoisted.expr) orelse
            Common.invariant("selected hoisted local const ref had no hoisted const table entry");
    }

    fn selectedHoistedConstMonoType(
        self: *BodyContext,
        selected: checked.SelectedHoistedConstUse,
        checked_ty: checked.CheckedTypeId,
    ) Allocator.Error!?Type.TypeId {
        const entry = self.selectedHoistedConstEntry(selected);
        if (self.loweringOwnHoistedConstRoot(entry)) return null;
        const template = self.view.const_templates.get(entry.const_ref);
        const hoisted_ty = switch (template.state) {
            .stored_const => |stored| try self.storedConstRootMonoType(self.view, stored, entry.checked_type),
            // Dispatch requires one concrete specialization type for this
            // selected const use. A generalized field whose presence has no
            // other evidence takes the declared required default in an
            // immutable view; the relation below then applies that exact
            // choice to the live const-use graph before any body emits.
            .eval_template => try self.graph.specializationTypeViewForNode(
                try self.instNode(entry.checked_type),
            ),
            .reserved => Common.invariant("reserved hoisted const template reached Monotype type selection"),
            .unimplemented => Common.invariant("declaration with no implementation reached hoisted const type selection"),
        };
        try relateCheckedNodeToMono(
            self.graph,
            try self.instNode(checked_ty),
            try self.graph.importMono(hoisted_ty),
        );
        return hoisted_ty;
    }

    fn restoreSelectedHoistedConstAtType(
        self: *BodyContext,
        selected: checked.SelectedHoistedConstUse,
        ty: Type.TypeId,
    ) Allocator.Error!?DraftExprId {
        const entry = self.selectedHoistedConstEntry(selected);
        if (self.loweringOwnHoistedConstRoot(entry)) return null;
        return try self.restoredHoistedConstAtType(entry, ty);
    }

    fn requireLoweredExpr(
        self: *BodyContext,
        expr: checked.CheckedExpr,
        node: NodeId,
        demand: LoweringDemand,
        lowered: DraftExprId,
    ) Allocator.Error!DraftExprId {
        if (demand != .runtime_value) return lowered;
        switch (expr.data) {
            .runtime_error, .crash, .ellipsis => return lowered,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .dbg, .expect_err, .expect, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
        }
        const expr_proof = self.exprImpossibilityProof(lowered);
        const entry_guard_proof = if (self.function_entry_demand_guards.len != 0)
            try self.maybeNodesImpossibilityProof(self.function_entry_demand_guards)
        else
            null;
        try self.draft.runtime_value_demands.append(self.allocator, .{
            .node = node,
            .impossibility_proof = try self.currentRuntimeImpossibilityProof(expr_proof),
            .frames = self.runtime_demand_guard_frames,
            .local_proof = try self.anyImpossibilityProof(&.{ entry_guard_proof, expr_proof }),
        });
        return lowered;
    }

    fn requireLoweredExprAtCell(
        self: *BodyContext,
        expr: checked.CheckedExpr,
        cell: DraftTypeCell,
        demand: LoweringDemand,
        lowered: DraftExprId,
    ) Allocator.Error!DraftExprId {
        if (demand != .runtime_value) return lowered;
        return switch (cell) {
            // A sealed inhabited type cannot later become an impossible
            // runtime demand, so it needs neither an InstGraph node nor a
            // deferred reachability record.
            .sealed => |ty| if (!try self.typeIsProvenUninhabited(ty))
                lowered
            else
                try self.requireLoweredExpr(expr, try self.activeNodeFromType(ty), demand, lowered),
            .graph_node => |node| try self.requireLoweredExpr(expr, node, demand, lowered),
        };
    }

    fn nodeIsProvenUninhabited(self: *BodyContext, node: NodeId) Allocator.Error!bool {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
        defer timing_scope.end();
        return self.nodeIsProvenUninhabitedInner(node, .inspectable_only);
    }

    fn producedRuntimeValueIsProvenUninhabited(self: *BodyContext, node: NodeId) Allocator.Error!bool {
        return self.nodeIsProvenUninhabitedInner(node, .runtime_layout);
    }

    fn deferredInspectHasProvenUninhabitedValueGuard(
        self: *BodyContext,
        boundary: DraftDeferredInspect,
    ) Allocator.Error!bool {
        if (!try self.nodeIsProvenUninhabited(boundary.value_node)) return false;
        return try self.activeImpossibilityProofHolds(boundary.impossibility_proof);
    }

    fn activeImpossibilityProofHolds(
        self: *BodyContext,
        maybe_proof: ?RuntimeImpossibilityProofId,
    ) Allocator.Error!bool {
        const proof = maybe_proof orelse return false;
        const memo = try self.allocator.alloc(?bool, self.draft.impossibility_proofs.items.len);
        defer self.allocator.free(memo);
        @memset(memo, null);
        const active = try self.allocator.alloc(bool, self.draft.impossibility_proofs.items.len);
        defer self.allocator.free(active);
        @memset(active, false);
        var scan = ImpossibilityProofScan{ .body = self, .memo = memo, .active = active };
        return try ImpossibilityProofScan.Evaluation.run(self.allocator, &scan, proof);
    }

    const UninhabitedBackingAccess = enum {
        inspectable_only,
        runtime_layout,
    };

    fn nodeIsProvenUninhabitedInner(
        self: *BodyContext,
        node: NodeId,
        backing_access: UninhabitedBackingAccess,
    ) Allocator.Error!bool {
        self.inhabitation_entered.clearRetainingCapacity();
        var scan = NodeUninhabitedScan{ .body = self, .backing_access = backing_access };
        return try NodeUninhabitedScan.Evaluation.runWith(self.allocator, &self.node_uninhabited_scratch, &scan, node);
    }

    fn typeIsProvenUninhabited(self: *BodyContext, ty: Type.TypeId) Allocator.Error!bool {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
        defer timing_scope.end();
        return try self.typeIsProvenUninhabitedWith(ty, .inspectable_only);
    }

    /// A durable TypeId is already a closed snapshot. Inspecting its
    /// inhabitation must not import it back into the active graph; deferred
    /// inspect generation runs after relation production is frozen.
    fn typeIsProvenUninhabitedWith(self: *BodyContext, ty: Type.TypeId, backing_access: UninhabitedBackingAccess) Allocator.Error!bool {
        return try self.graph.typeProvenUninhabited(ty, switch (backing_access) {
            .inspectable_only => .inspectable_only,
            .runtime_layout => .runtime_layout,
        });
    }

    fn checkedPatternIsProvenUninhabited(self: *BodyContext, pattern_id: checked.CheckedPatternId) Allocator.Error!bool {
        var scan = PatternUninhabitedScan{ .body = self };
        return try PatternUninhabitedScan.Evaluation.runWith(self.allocator, &self.pattern_uninhabited_scratch, &scan, pattern_id);
    }

    fn stepStr(self: *BodyContext, task: *StrTask, input: ?LowerResult) Allocator.Error!LowerStep {
        const str_ty = try self.primitiveType(.str);
        if (input) |lowered| {
            task.out = if (task.index == 0)
                lowered.exprValue()
            else
                try self.concatExpr(task.out, lowered.exprValue(), str_ty);
            task.index += 1;
        } else if (task.segments.len == 0) {
            return try self.finishStr(task, try self.stringExpr("", str_ty));
        }
        if (task.index < task.segments.len) {
            return requestLowerChild(self, task.segments[task.index], .{ .sealed = str_ty });
        }
        return try self.finishStr(task, task.out);
    }

    fn finishStr(self: *BodyContext, task: *const StrTask, value: DraftExprId) Allocator.Error!LowerStep {
        const data: BodyExprData = .{ .nominal = value };
        const cell = task.cell orelse return .{ .ret = .{ .data = data } };
        return loweredExprStep(try self.addExprWithTypeCell(cell, data));
    }

    fn lowerStringLiteral(self: *BodyContext, id: checked.CheckedStringLiteralId) Allocator.Error!DraftStringLiteralId {
        const index = @backingInt(id);
        if (index >= self.view.bodies.stringLiteralCount()) {
            Common.invariant("checked string literal id outside checked body string store");
        }
        return try self.draft.addCheckedStringLiteral(
            self.view.key.bytes,
            id,
            self.view.bodies.stringLiteral(@fromBackingInt(@intCast(index))),
        );
    }

    fn producedResultCell(
        self: *BodyContext,
        request_node: NodeId,
        produced_cell: DraftTypeCell,
    ) Allocator.Error!DraftTypeCell {
        const produced_node = try produced_cell.toGraphNode(self.graph);
        return if (try self.resultCompletesRequest(request_node, produced_node) or
            try self.graph.containsGeneratedPrivate(produced_node))
            produced_cell
        else
            DraftTypeCell.fromGraphNode(try self.relateCheckedNodeToProducedValue(request_node, produced_node));
    }

    fn checkedFunctionType(self: *BodyContext, checked_fn_ty: checked.CheckedTypeId) checked.CheckedFunctionType {
        return switch (resolvedPayload(self.view, checked_fn_ty).payload) {
            .function => |function| function,
            .pending, .err, .flex, .rigid, .alias, .record, .tuple, .nominal, .empty_record, .tag_union, .empty_tag_union => Common.invariant("checked call function type was not a function"),
        };
    }

    fn functionReturnType(self: *BodyContext, fn_ty: Type.TypeId) Type.TypeId {
        return self.functionShape(fn_ty, "checked call function type was not a function").ret;
    }

    /// The task lowering a direct call to a call-site intrinsic, or null
    /// when the call's target is not one.
    fn callsiteIntrinsicCallTask(
        self: *BodyContext,
        checked_expr_id: checked.CheckedExprId,
        checked_ret_ty: checked.CheckedTypeId,
        call: anytype,
        expected_ret_node: ?NodeId,
        expected_ret_ty: ?Type.TypeId,
    ) Allocator.Error!?LowerTask {
        const target = call.direct_target orelse return null;
        const intrinsic = self.callsiteIntrinsicForResolvedTarget(target) orelse return null;
        const source_fn_ty = self.directCallInstantiationSourceFnType(target, call.source_fn_ty_payload);
        return .{ .callsite_intrinsic = .{
            .intrinsic = intrinsic,
            .checked_expr_id = checked_expr_id,
            .source_fn_ty = source_fn_ty,
            .operands = .{ .direct_call = call.args },
            .callable_node = try self.directCallTypeNode(checked_ret_ty, call, source_fn_ty, expected_ret_node),
            .expected_ret_ty = expected_ret_ty,
        } };
    }

    /// Return checked expression operands for a call-site intrinsic without
    /// allocating. Method dispatch is valid here only when every operand is a
    /// source expression; compiler-generated dispatch operands have their own
    /// explicit lowering protocols.
    fn checkedCallsiteIntrinsicArgs(
        _: *BodyContext,
        intrinsic: checked.IntrinsicId,
        operands: CheckedIntrinsicOperands,
        storage: *[checked.IntrinsicId.max_callsite_arity]checked.CheckedExprId,
    ) []const checked.CheckedExprId {
        const expected_arity: usize = intrinsic.callsiteArity() orelse
            Common.invariant("non-call-site intrinsic reached call-site lowering");
        const actual_arity = switch (operands) {
            inline .direct_call, .dispatch => |args| args.len,
        };
        if (actual_arity != expected_arity) {
            Common.invariant("checked call-site intrinsic had an unexpected arity");
        }
        return switch (operands) {
            .direct_call => |args| args,
            .dispatch => |args| blk: {
                for (args, storage.*[0..expected_arity]) |operand, *checked_arg| {
                    checked_arg.* = switch (operand) {
                        .checked_expr => |expr| expr,
                        .generated_interpolation_segments,
                        .generated_numeral,
                        .generated_quote,
                        => Common.invariant("call-site intrinsic had a compiler-generated dispatch operand"),
                    };
                }
                break :blk storage.*[0..expected_arity];
            },
        };
    }

    /// Apply the checked intrinsic's result source to its callable request.
    /// Result queries and call-site lowering share these exact graph relations;
    /// the intrinsic wrapper never supplies an ordinary procedure body.
    fn callsiteIntrinsicRequestNode(
        self: *BodyContext,
        intrinsic: checked.IntrinsicId,
        callable_node: NodeId,
    ) Allocator.Error!NodeId {
        const callable = try self.graph.functionNodes(callable_node);
        return switch (intrinsic.requestResultSource()) {
            .declared_return => callable_node,
            .argument => |index| blk: {
                if (index >= callable.args.len) Common.invariant("checked intrinsic result argument was outside its callable request");
                const request_ret = try checkedMonoRequestNode(self.graph, callable.ret, callable.args[index], .exact);
                break :blk try functionRequestNode(self.graph, callable_node, callable.args, request_ret);
            },
        };
    }

    /// Lower every syntax form for a call-site intrinsic through one exact
    /// monomorphic body generator. The checked callable request owns the
    /// specialization cells; neither source syntax nor the intrinsic wrapper
    /// is a later type authority.
    fn stepCallsiteIntrinsic(self: *BodyContext, task: *CallsiteIntrinsicTask, input: ?LowerResult) Allocator.Error!LowerStep {
        switch (task.stage) {
            .start => {
                var checked_arg_storage: [checked.IntrinsicId.max_callsite_arity]checked.CheckedExprId = undefined;
                task.args = try self.allocator.dupe(checked.CheckedExprId, self.checkedCallsiteIntrinsicArgs(task.intrinsic, task.operands, &checked_arg_storage));
                if (task.deferred_body) |deferred| {
                    if (deferred.pre_lowered_args) |span| {
                        const lowered = self.exprSpan(span);
                        if (lowered.len != task.args.len) Common.invariant("ParseTagUnionSpec.parse pre-lowered argument arity differed from its checked call");
                        try self.beginCallsiteIntrinsicBody(task);
                        @memcpy(task.lowered_args[0..lowered.len], lowered);
                        return try self.finishCallsiteIntrinsic(task);
                    }
                    try self.beginCallsiteIntrinsicBody(task);
                    return try self.nextCallsiteIntrinsicArg(task);
                }
                task.callable_node = try self.callsiteIntrinsicRequestNode(task.intrinsic, task.callable_node);
                const callable = try self.graph.functionNodes(task.callable_node);
                if (callable.args.len != task.args.len) {
                    Common.invariant("checked call-site intrinsic request had an unexpected arity");
                }

                if (!self.frozen_sealed_emission) {
                    var unresolved = !try self.graph.typeIsResolved(callable.ret);
                    if (!unresolved) for (callable.args) |arg_node| {
                        if (!try self.graph.typeIsResolved(arg_node)) {
                            unresolved = true;
                            break;
                        }
                    };
                    if (task.intrinsic == .parse_tag_union) {
                        // Structural tag-union parsing always generates a codec
                        // body, so it follows the same prepare/freeze/emit
                        // boundary whether or not this particular request
                        // happens to be resolved yet.
                        task.stage = .deferred_prepared;
                        return requestLowerTask(self, try self.hostedEvidenceTask(.{ .prepare_span = .{
                            .checked_exprs = task.args,
                            .nodes = callable.args,
                        } }));
                    }
                    // Other intrinsics defer only while their request still
                    // owns live row defaults such as an open
                    // `FieldName(shape)` row.
                    if (unresolved) return loweredExprStep(try self.deferCallsiteIntrinsic(task, null));
                }
                try self.beginCallsiteIntrinsicBody(task);
                return try self.nextCallsiteIntrinsicArg(task);
            },
            .deferred_prepared => {
                task.stage = .deferred_args;
                const callable = try self.graph.functionNodes(task.callable_node);
                return requestLowerTask(self, .{ .prepared_span = .{ .exprs = task.args, .nodes = callable.args } });
            },
            .deferred_args => return loweredExprStep(try self.deferCallsiteIntrinsic(task, input.?.spanValue())),
            .args => {
                task.lowered_args[task.index] = input.?.exprValue();
                task.index += 1;
                return try self.nextCallsiteIntrinsicArg(task);
            },
        }
    }

    /// Reserve a call-site intrinsic's expression, emitted once its body's
    /// graph is sealed.
    fn deferCallsiteIntrinsic(
        self: *BodyContext,
        task: *CallsiteIntrinsicTask,
        pre_lowered_args: ?DraftSpan(DraftExprId),
    ) Allocator.Error!DraftExprId {
        const callable = try self.graph.functionNodes(task.callable_node);
        const expr = try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(callable.ret), .pending_deferred);
        const lexical = try self.captureCodecLexicalContext();
        var lexical_needs_cleanup = true;
        errdefer if (lexical_needs_cleanup) {
            self.allocator.free(lexical.binders);
            self.allocator.free(lexical.local_procs);
        };
        const codec_contract = if (task.intrinsic == .parse_tag_union)
            try self.retainActiveCodecContract()
        else
            null;
        var codec_contract_needs_cleanup = true;
        errdefer if (codec_contract_needs_cleanup) {
            if (codec_contract) |contract| {
                contract.deinit(self.allocator);
            }
        };
        try self.draft.deferred_callsite_intrinsics.append(self.allocator, .{
            .view = self.view,
            .method_scope = self.method_scope,
            .owner_template = self.owner_template,
            .owner = self.draft.current_owner,
            .expr = expr,
            .intrinsic = task.intrinsic,
            .checked_expr_id = task.checked_expr_id,
            .source_fn_ty = task.source_fn_ty,
            .operands = task.operands,
            .pre_lowered_args = pre_lowered_args,
            .callable_node = task.callable_node,
            .evidence = self.evidence,
            .current_fn_key = self.current_fn_key,
            .lexical = lexical,
            .codec_contract = codec_contract,
        });
        lexical_needs_cleanup = false;
        codec_contract_needs_cleanup = false;
        self.allocator.free(task.args);
        task.args = &.{};
        return expr;
    }

    /// Materialize the intrinsic's argument and result types from the exact
    /// checked callable request nodes. Under frozen emission the
    /// current-phase view seals each node to its final type; during ordinary
    /// body lowering every node is already resolved.
    fn beginCallsiteIntrinsicBody(self: *BodyContext, task: *CallsiteIntrinsicTask) Allocator.Error!void {
        const callable = try self.graph.functionNodes(task.callable_node);
        if (task.args.len > checked.IntrinsicId.max_callsite_arity or callable.args.len != task.args.len) {
            Common.invariant("call-site intrinsic body had an unexpected arity");
        }
        for (callable.args, task.arg_tys[0..task.args.len]) |arg_node, *arg_ty| {
            arg_ty.* = try self.currentPhaseTypeForNode(arg_node);
        }
        task.ret_ty = try self.currentPhaseTypeForNode(callable.ret);
        if (task.expected_ret_ty) |expected| {
            if (!self.sameType(expected, task.ret_ty)) Common.invariant("checked call-site intrinsic lowered at a type different from its context type");
        }
        task.index = 0;
        task.stage = .args;
    }

    /// Lower the intrinsic's next argument, as a child when it is not a
    /// callable reference; the body follows the last argument.
    fn nextCallsiteIntrinsicArg(self: *BodyContext, task: *CallsiteIntrinsicTask) Allocator.Error!LowerStep {
        while (task.index < task.args.len) {
            switch (try self.callsiteIntrinsicArgStep(task.args[task.index], task.arg_tys[task.index])) {
                .ret => |lowered| {
                    task.lowered_args[task.index] = lowered.exprValue();
                    task.index += 1;
                },
                .call => |child| return .{ .call = child },
            }
        }
        return try self.finishCallsiteIntrinsic(task);
    }

    fn finishCallsiteIntrinsic(self: *BodyContext, task: *CallsiteIntrinsicTask) Allocator.Error!LowerStep {
        const args = task.args;
        const arg_tys = task.arg_tys[0..args.len];
        const lowered_args = task.lowered_args[0..args.len];
        const ret_ty = task.ret_ty;
        const lowered = switch (task.intrinsic) {
            .parse_tag_union => try self.lowerParseTagUnionDecode(args, arg_tys, ret_ty, lowered_args),
            .field_names_rename_fields => try self.lowerFieldNamesRenameFieldNames(args, arg_tys, ret_ty, lowered_args),
            .field_names_shortest_name => try self.lowerFieldNamesNameBound(args, arg_tys, ret_ty, .shortest, lowered_args),
            .field_names_longest_name => try self.lowerFieldNamesNameBound(args, arg_tys, ret_ty, .longest, lowered_args),
            .field_names_iter => try self.lowerFieldNamesIter(task.checked_expr_id, task.source_fn_ty, args, arg_tys, ret_ty, .all, lowered_args),
            .field_names_for_size => try self.lowerFieldNamesIter(task.checked_expr_id, task.source_fn_ty, args, arg_tys, ret_ty, .for_size, lowered_args),
            .field_name => try self.lowerFieldName(args, arg_tys, ret_ty, lowered_args),
            .str_inspect, .structural_eq => unreachable,
        };
        if (task.deferred_body == null) {
            const callable = try self.graph.functionNodes(task.callable_node);
            if (try self.graph.containsGeneratedPrivate(callable.ret)) {
                self.draft.exprs.items[@backingInt(lowered)].ty = DraftTypeCell.fromGraphNode(callable.ret);
            }
        }
        self.allocator.free(task.args);
        task.args = &.{};
        return loweredExprStep(lowered);
    }

    /// Synthetic `(encoding) -> (state) -> Try` constructor node over a
    /// `ParseTagUnionSpec.parse` request's own component cells, letting the
    /// structural-parser relation helpers treat the intrinsic like a derived
    /// `parser_for` boundary.
    fn parseTagUnionSyntheticBoundary(self: *BodyContext, callable: FunctionNodes, callable_ret: NodeId) Allocator.Error!NodeId {
        if (callable.args.len != 2) Common.invariant("ParseTagUnionSpec.parse request did not have spec and options arguments");
        const options_node = callable.args[1];
        const encoding_node = try self.graph.recordFieldNode(options_node, try self.nameStoreMut().internRecordFieldLabel("encoding"));
        const state_node = try self.graph.recordFieldNode(options_node, try self.nameStoreMut().internRecordFieldLabel("state"));
        const runtime_node = try self.graphFunctionNode(&.{state_node}, callable_ret);
        return try self.graphFunctionNode(&.{encoding_node}, runtime_node);
    }

    fn callsiteIntrinsicArgStep(
        self: *BodyContext,
        checked_arg: checked.CheckedExprId,
        ty: Type.TypeId,
    ) Allocator.Error!LowerStep {
        const expr = self.view.bodies.expr(checked_arg);
        const maybe_ref: ?checked.ResolvedValueId = switch (expr.data) {
            .lookup_local => |lookup| lookup.resolved,
            .lookup_external, .lookup_required => |ref_id| ref_id,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => null,
        };
        if (maybe_ref) |ref_id| {
            if (try self.currentLocalForResolvedValue(ref_id)) |local_id| {
                const local_ty = try self.localType(local_id);
                if (!self.sameType(ty, local_ty)) {
                    Common.invariant("checked call-site intrinsic local argument type differed from its concrete local type");
                }
                return loweredExprStep(try self.addExpr(.{ .ty = local_ty, .data = .{ .local = local_id } }));
            }

            const record = self.view.resolved_refs.records[@backingInt(ref_id)];
            switch (record.ref) {
                .local_proc => |local| {
                    const request_fn_node = try self.activeNodeFromType(ty);
                    if (local.is_alias) return requestLowerTask(self, .{ .scheme_alias = .{
                        .alias = local,
                        .use_expr = record.expr,
                        .expected_node = request_fn_node,
                    } });
                    const context_id = try self.localProcContextId(self.view, local.binder, local.expr);
                    const fn_id = try self.lowerDraftLocalProcAtNode(
                        local,
                        self.view,
                        context_id,
                        expr.ty,
                        self.view.types.rootKey(expr.ty),
                        request_fn_node,
                        try self.evidenceForUseSiteAtNode(record.expr, request_fn_node),
                        record.recursive_reference,
                        .inherit,
                    );
                    const fn_node = try self.draftFnSlotTypeNode(.{ .local = fn_id }, request_fn_node);
                    return loweredExprStep(try self.addExprWithTypeCell(
                        DraftTypeCell.fromGraphNode(fn_node),
                        .{ .fn_def = .{ .fn_id = fn_id, .captures = try self.localProcFnDefCaptureSpan(
                            context_id,
                            self.view.key.bytes,
                            local.binder,
                            local.expr,
                            null,
                        ) } },
                    ));
                },
                .top_level_proc,
                .imported_proc,
                .hosted_proc,
                .promoted_top_level_proc,
                => |proc| return loweredExprStep(try self.lowerProcedureUseValueAtNode(proc, try self.activeNodeFromType(ty), record.expr, null, record.recursive_reference)),
                .platform_required_proc => |proc| return loweredExprStep(try self.lowerProcedureUseValueAtNode(proc.procedure, try self.activeNodeFromType(ty), record.expr, proc.root_evidence, record.recursive_reference)),
                .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .platform_required_declaration, .platform_required_checked_error, .platform_required_const => {},
            }
        }
        return requestLowerChild(self, checked_arg, .{ .sealed = ty });
    }

    fn lowerPendingCallableEvalBindingValue(
        self: *BodyContext,
        view: ModuleView,
        template: checked.CallableEvalTemplate,
        root: checked.CompileTimeRoot,
        mono_fn_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const wrapper = view.entry_wrappers.lookupByRoot(template.root) orelse
            Common.invariant("callable eval template root had no checked entry wrapper");

        const wrapper_fn_ty = try self.functionType(&.{}, mono_fn_ty);
        const wrapper_template = self.builder.fnDefForTemplate(
            view,
            wrapper.template,
            wrapper.checked_fn_root,
            view.types.rootKey(wrapper.checked_fn_root),
            wrapper_fn_ty,
        );

        var body_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, view, self.method_scope, wrapper.template, self.graph, self.draft);
        defer body_ctx.deinit();
        const entry_template = view.templates.get(wrapper.template.template);
        const schema = templateSchemaIn(view, &entry_template);
        const subst = try body_ctx.substitutionFromCheckedTypes(view, schema.scheme_vars);
        body_ctx.evidence = rootEvidenceWithSubstitution(wrapper.template, schema, .{
            .subst = subst,
            .vector = self.restore_evidence.vector,
        });
        try body_ctx.seedSubstitution(schema, subst);
        body_ctx.frozen_sealed_emission = self.frozen_sealed_emission;
        body_ctx.frozen_type_finals = self.frozen_type_finals;
        body_ctx.frozen_codec_calls = self.frozen_codec_calls;
        body_ctx.frozen_field_defaults = self.frozen_field_defaults;
        const root_fn_key = Ast.fnTemplateDigest(wrapper_template, self.typeStore(), self.nameStore());
        body_ctx.owner_context_fn_key = root_fn_key;
        body_ctx.current_fn_key = root_fn_key;
        try body_ctx.constrainTypeToMono(wrapper.checked_fn_root, wrapper_fn_ty);
        try body_ctx.constrainTypeToMono(template.checked_fn_root, mono_fn_ty);
        try body_ctx.constrainKnownType(root.checked_type, mono_fn_ty);

        return try body_ctx.lowerPendingCallableEvalRoot(
            view,
            template.root,
            wrapper.body_expr,
            try body_ctx.activeNodeFromType(mono_fn_ty),
        );
    }

    fn lowerCallableEvalBindingValueAtNode(
        self: *BodyContext,
        view: ModuleView,
        template_id: checked.CallableEvalTemplateId,
        request_fn_node: NodeId,
        evidence: []const SpecEvidence,
    ) Allocator.Error!DraftExprId {
        const previous_restore_evidence = self.restore_evidence;
        self.restore_evidence = rootEvidence(self.owner_template, evidence);
        defer self.restore_evidence = previous_restore_evidence;

        const raw = @backingInt(template_id);
        if (raw >= view.callable_eval_templates.templates.len) {
            Common.invariant("callable eval binding referenced a missing checked template");
        }
        const template = view.callable_eval_templates.templates[raw];
        const root = view.compile_time_roots.root(template.root);
        return switch (root.payload) {
            .fn_value => |fn_id| try self.restoreConstFnAtNode(view, fn_id, request_fn_node),
            .const_node => |node| try self.restoreConstNodeAtNode(view, view, node, request_fn_node),
            .pending => try self.lowerPendingCallableEvalBindingValueAtNode(view, template, root, request_fn_node),
            .discarded, .expect, .runtime => Common.invariant("callable eval binding root output a non-callable payload"),
        };
    }

    fn lowerPendingCallableEvalBindingValueAtNode(
        self: *BodyContext,
        view: ModuleView,
        template: checked.CallableEvalTemplate,
        root: checked.CompileTimeRoot,
        request_fn_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const wrapper = view.entry_wrappers.lookupByRoot(template.root) orelse
            Common.invariant("callable eval template root had no checked entry wrapper");

        var body_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, view, self.method_scope, wrapper.template, self.graph, self.draft);
        defer body_ctx.deinit();
        const entry_template = view.templates.get(wrapper.template.template);
        const schema = templateSchemaIn(view, &entry_template);
        const subst = try body_ctx.substitutionFromCheckedTypes(view, schema.scheme_vars);
        body_ctx.evidence = rootEvidenceWithSubstitution(wrapper.template, schema, .{
            .subst = subst,
            .vector = self.restore_evidence.vector,
        });
        try body_ctx.seedSubstitution(schema, subst);
        body_ctx.frozen_sealed_emission = self.frozen_sealed_emission;
        body_ctx.frozen_type_finals = self.frozen_type_finals;
        body_ctx.frozen_codec_calls = self.frozen_codec_calls;
        body_ctx.frozen_field_defaults = self.frozen_field_defaults;
        const root_fn_key = view.types.rootKey(wrapper.checked_fn_root);
        body_ctx.owner_context_fn_key = root_fn_key;
        body_ctx.current_fn_key = root_fn_key;

        const wrapper_fn_node = try body_ctx.graphFunctionNode(&.{}, request_fn_node);
        try self.graph.unify(try body_ctx.instNode(wrapper.checked_fn_root), wrapper_fn_node);
        try self.graph.unify(try body_ctx.instNode(template.checked_fn_root), request_fn_node);
        try self.graph.unify(try body_ctx.instNode(root.checked_type), request_fn_node);

        return try body_ctx.lowerPendingCallableEvalRoot(
            view,
            template.root,
            wrapper.body_expr,
            request_fn_node,
        );
    }

    /// The checker permits root slots only for context-free concrete values.
    /// This direct reference transports the declared root's return relation to
    /// Lambda Solved. It is evidence for a slot read, never an evaluator call.
    fn declaredComptimeValueRead(
        self: *BodyContext,
        view: ModuleView,
        root_id: checked.ComptimeRootId,
        cell: DraftTypeCell,
        const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const owners = self.builder.borrowed_comptime_root_functions orelse &self.builder.declared_comptime_root_functions;
        const fn_id = owners.get(.{ .module = view.key, .root = root_id }) orelse
            Common.invariant("shared root read lacked a declared root function");
        const initializer = try self.addExprWithTypeCell(cell, .{ .call_proc = .{
            .callee = .{ .func = .{ .local = .{ .final = fn_id } } },
            .args = .empty(),
        } });
        return try self.addExprWithTypeCell(cell, .{ .comptime_value = .{
            .root = try self.draft.addComptimeValueRoot(.{ .module = view.key, .root = .{ .checked = root_id }, .const_locator = const_locator }),
            .initializer = initializer,
        } });
    }

    fn lowerPendingCallableEvalRoot(
        self: *BodyContext,
        view: ModuleView,
        root_id: checked.ComptimeRootId,
        body_expr: checked.CheckedExprId,
        request_fn_node: NodeId,
    ) Allocator.Error!DraftExprId {
        if (try self.activeCallableEvalBindingExpr(view, root_id, request_fn_node)) |active| return active;

        const request_cell = DraftTypeCell.fromGraphNode(request_fn_node);
        if (self.builder.comptimeValueReadDeclared(view, root_id)) {
            return self.declaredComptimeValueRead(view, root_id, request_cell, null);
        }
        const local = try self.reserveCallableEvalBinding(view, root_id, request_fn_node);
        const lowered = try self.lowerComptimeRootExprAtCell(body_expr, request_cell);
        return try self.finishCallableEvalBinding(view, root_id, request_cell, local, lowered);
    }

    fn activeCallableEvalBindingExpr(
        self: *BodyContext,
        view: ModuleView,
        root_id: checked.ComptimeRootId,
        request_fn_node: NodeId,
    ) Allocator.Error!?DraftExprId {
        var index = self.draft.active_callable_eval_bindings.items.len;
        while (index > 0) {
            index -= 1;
            const active = self.draft.active_callable_eval_bindings.items[index];
            if (!moduleBytesEqual(active.module.bytes, view.key.bytes) or active.root != root_id) continue;

            try relateRequestComponent(self.graph, active.request_node, request_fn_node);
            self.draft.active_callable_eval_bindings.items[index].used = true;
            return try self.addExprWithTypeCell(
                DraftTypeCell.fromGraphNode(request_fn_node),
                .{ .local = active.local },
            );
        }

        return null;
    }

    fn reserveCallableEvalBinding(
        self: *BodyContext,
        view: ModuleView,
        root_id: checked.ComptimeRootId,
        request_fn_node: NodeId,
    ) Allocator.Error!DraftLocalId {
        const root = view.compile_time_roots.root(root_id);
        const pattern = root.pattern orelse Common.invariant("callable eval binding omitted its checked pattern");
        const binder = switch (view.bodies.pattern(pattern).data) {
            .assign => |binder| binder,
            .pending, .as, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => Common.invariant("callable eval binding pattern was not a binder"),
        };
        const local = try self.addLocalWithBinderCell(
            self.builder.symbols.fresh(),
            DraftTypeCell.fromGraphNode(request_fn_node),
            binder,
        );
        try self.draft.active_callable_eval_bindings.append(self.allocator, .{
            .module = view.key,
            .root = root_id,
            .request_node = request_fn_node,
            .local = local,
        });
        return local;
    }

    fn finishCallableEvalBinding(
        self: *BodyContext,
        view: ModuleView,
        root_id: checked.ComptimeRootId,
        request_cell: DraftTypeCell,
        local: DraftLocalId,
        lowered: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const active = self.draft.active_callable_eval_bindings.pop().?;
        if (!moduleBytesEqual(active.module.bytes, view.key.bytes) or active.root != root_id or active.local != local) {
            Common.invariant("callable eval binding reservation changed before completion");
        }
        if (!active.used) return lowered;
        return try self.wrapRecursiveConstLocalAtTypeCell(local, request_cell, lowered);
    }

    fn activeConstNodeBindingExpr(
        self: *BodyContext,
        store_view: ModuleView,
        node: checked.ConstNodeId,
        representation: ActiveConstNodeRepresentation,
        request_cell: DraftTypeCell,
    ) Allocator.Error!?DraftExprId {
        const address = activeConstNodeAddress(store_view, node, representation);
        var cursor = self.draft.active_const_node_binding_indices.get(address);
        while (cursor) |index| {
            if (index >= self.draft.active_const_node_bindings.items.len) {
                Common.invariant("active ConstStore node index was outside its binding stack");
            }
            const active = self.draft.active_const_node_bindings.items[index];
            if (!try self.constNodeRepresentationsEql(active.representation, representation)) {
                cursor = active.previous_same_address;
                continue;
            }

            try relateRequestComponent(
                self.graph,
                try active.cell.toGraphNode(self.graph),
                try request_cell.toGraphNode(self.graph),
            );
            const local = active.local orelse blk: {
                const owner_scope = try self.draft.enterOwner(active.owner);
                defer owner_scope.leave();
                const reserved = try self.addLocalWithBinderCell(
                    self.builder.symbols.fresh(),
                    active.cell,
                    null,
                );
                self.draft.active_const_node_bindings.items[index].local = reserved;
                break :blk reserved;
            };
            self.draft.active_const_node_bindings.items[index].used = true;
            return try self.addExprWithTypeCell(request_cell, .{ .local = local });
        }

        return null;
    }

    fn materializedConstNodeExpr(
        self: *BodyContext,
        store_view: ModuleView,
        node: checked.ConstNodeId,
        representation: ActiveConstNodeRepresentation,
        request_cell: DraftTypeCell,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!?DraftExprId {
        const address = MaterializedConstNodeAddress{
            .active = activeConstNodeAddress(store_view, node, representation),
            .owner = self.draft.current_owner,
            .static_data_const_locator = static_data_const_locator,
        };
        var cursor = self.draft.materialized_const_node_indices.get(address);
        while (cursor) |index| {
            if (index >= self.draft.materialized_const_nodes.items.len) {
                Common.invariant("materialized ConstStore node index was outside its entry list");
            }
            const existing = self.draft.materialized_const_nodes.items[index];
            if (!try self.constNodeRepresentationsEql(existing.representation, representation)) {
                cursor = existing.previous_same_address;
                continue;
            }
            // Two SEALED cells need no graph relation: representation
            // equality above already matched the finished monotypes, so
            // relating them is a no-op—and sealed emission (a derived
            // parser def restoring an archived constant) may not grow the
            // graph at all. A disagreement here is an upstream invariant,
            // not a case.
            const reuse_relation: ?struct { existing: Type.TypeId, requested: Type.TypeId } = switch (self.exprTypeCell(existing.expr)) {
                .sealed => |existing_ty| switch (request_cell) {
                    .sealed => |request_ty| .{ .existing = existing_ty, .requested = request_ty },
                    .graph_node => null,
                },
                .graph_node => null,
            };
            if (reuse_relation) |sealed_pair| {
                if (sealed_pair.existing != sealed_pair.requested and
                    !try self.typeStore().typeEql(
                        self.nameStore(),
                        sealed_pair.existing,
                        sealed_pair.requested,
                    ))
                {
                    Common.invariant("materialized ConstStore reuse cell disagreed with its sealed request type");
                }
            } else {
                try relateRequestComponent(
                    self.graph,
                    try self.exprTypeCell(existing.expr).toGraphNode(self.graph),
                    try request_cell.toGraphNode(self.graph),
                );
            }
            return existing.expr;
        }
        return null;
    }

    /// Whether a constant restored here can only name what it builds.
    ///
    /// A node reached while an enclosing ConstStore node is still being built
    /// restores to a read of that node's binding local, and static data is
    /// emitted by a standalone initializer procedure with no such local in
    /// scope. A node's own binding is not in this stack by the time its
    /// candidate is decided, so only genuinely enclosing ones are counted.
    fn constRestorationIsClosed(self: *BodyContext) bool {
        return self.draft.active_const_node_bindings.items.len == 0;
    }

    fn constNodeRepresentationsEql(
        self: *BodyContext,
        left: ActiveConstNodeRepresentation,
        right: ActiveConstNodeRepresentation,
    ) Allocator.Error!bool {
        return switch (left) {
            .sealed => |left_ty| switch (right) {
                .sealed => |right_ty| left_ty == right_ty or
                    try self.typeStore().typeEql(
                        self.nameStore(),
                        left_ty,
                        right_ty,
                    ),
                .graph => false,
            },
            .graph => switch (right) {
                .sealed => false,
                .graph => true,
            },
        };
    }

    fn reserveConstNodeBinding(
        self: *BodyContext,
        store_view: ModuleView,
        node: checked.ConstNodeId,
        representation: ActiveConstNodeRepresentation,
        cell: DraftTypeCell,
    ) Allocator.Error!void {
        const index = self.draft.active_const_node_bindings.items.len;
        const address = activeConstNodeAddress(store_view, node, representation);
        const previous_same_address = self.draft.active_const_node_binding_indices.get(address);
        try self.draft.active_const_node_bindings.append(self.allocator, .{
            .module = store_view.key,
            .node = node,
            .representation = representation,
            .previous_same_address = previous_same_address,
            .owner = self.draft.current_owner,
            .cell = cell,
        });
        try self.draft.active_const_node_binding_indices.put(address, @intCast(index));
    }

    fn finishConstNodeBinding(
        self: *BodyContext,
        store_view: ModuleView,
        node: checked.ConstNodeId,
        representation: ActiveConstNodeRepresentation,
        cell: DraftTypeCell,
        lowered: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const index = self.draft.active_const_node_bindings.items.len - 1;
        const active = self.draft.active_const_node_bindings.pop().?;
        if (!moduleBytesEqual(active.module.bytes, store_view.key.bytes) or
            active.node != node or
            !std.meta.eql(active.representation, representation))
        {
            Common.invariant("ConstStore node reservation changed before materialization completed");
        }
        const address = activeConstNodeAddress(store_view, node, representation);
        const current = self.draft.active_const_node_binding_indices.getPtr(address) orelse
            Common.invariant("completed ConstStore node had no active reservation index");
        if (current.* != index) {
            Common.invariant("completed ConstStore node was not its address bucket head");
        }
        if (active.previous_same_address) |previous| {
            current.* = previous;
        } else if (!self.draft.active_const_node_binding_indices.remove(address)) {
            Common.invariant("completed ConstStore node address could not be removed");
        }
        if (!active.used) return lowered;

        const owner_scope = try self.draft.enterOwner(active.owner);
        defer owner_scope.leave();
        return try self.wrapRecursiveConstLocalAtTypeCell(
            active.local orelse Common.invariant("used ConstStore node reservation had no local"),
            cell,
            lowered,
        );
    }

    fn cacheMaterializedConstNode(
        self: *BodyContext,
        store_view: ModuleView,
        node: checked.ConstNodeId,
        representation: ActiveConstNodeRepresentation,
        expr: DraftExprId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!void {
        const address = MaterializedConstNodeAddress{
            .active = activeConstNodeAddress(store_view, node, representation),
            .owner = self.draft.current_owner,
            .static_data_const_locator = static_data_const_locator,
        };
        const index = self.draft.materialized_const_nodes.items.len;
        try self.draft.materialized_const_nodes.append(self.allocator, .{
            .representation = representation,
            .expr = expr,
            .previous_same_address = self.draft.materialized_const_node_indices.get(address),
        });
        try self.draft.materialized_const_node_indices.put(address, @intCast(index));
    }

    /// A `Str.inspect` of a function value: its rendering, or the task
    /// evaluating the function expression before rendering it. Null when
    /// the call is not an inspect-only rendering of a function.
    fn inspectOnlyCallStep(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        call: anytype,
        str_ty: Type.TypeId,
        demand: LoweringDemand,
    ) Allocator.Error!?LowerStep {
        if (demand != .inspect_only) return null;
        if (call.args.len != 1) Common.invariant("Str.inspect call did not have exactly one argument");

        const value_expr = self.view.bodies.expr(call.args[0]);
        switch (resolvedPayload(self.view, value_expr.ty).payload) {
            .function => {},
            .pending, .err, .flex, .rigid, .alias, .record, .tuple, .nominal, .empty_record, .tag_union, .empty_tag_union => return null,
        }

        try self.constrainTypeToMono(checked_ret_ty, str_ty);
        if (self.view.bodies.exprEvaluationMayBeElidedForInspect(call.args[0])) {
            return loweredExprStep(try self.stringExpr("<function>", str_ty));
        }
        return requestLowerTask(self, .{ .inspect_only = .{ .arg = call.args[0], .str_ty = str_ty } });
    }

    /// Function rendering does not consume the function value, but the
    /// source expression must still run: it lowers normally, the produced
    /// callable is discarded, and the representation is the result.
    fn stepInspectOnly(self: *BodyContext, task: *InspectOnlyTask, input: ?LowerResult) Allocator.Error!LowerStep {
        const evaluated = if (input) |lowered| lowered.exprValue() else return requestLowerTask(self, .{ .expr = .{ .expr = task.arg } });
        const evaluation = try self.addStmt(.{ .expr = evaluated });
        return loweredExprStep(try self.addExpr(.{ .ty = task.str_ty, .data = .{ .block = .{
            .statements = try self.addStmtSpan(&.{evaluation}),
            .final_expr = try self.stringExpr("<function>", task.str_ty),
        } } }));
    }

    fn inspectCallDemand(self: *BodyContext, call: anytype) LoweringDemand {
        const target = call.direct_target orelse return .runtime_value;
        return if (self.resolvedTargetIsStrInspect(target)) .inspect_only else .runtime_value;
    }

    fn resolvedTargetIsStrInspect(self: *BodyContext, target: checked.ResolvedValueId) bool {
        return switch (self.finalDirectTarget(target).record.ref) {
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .promoted_top_level_proc,
            => |proc| proc.intrinsic == .str_inspect,
            .platform_required_proc => |proc| proc.procedure.intrinsic == .str_inspect,
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .selected_hoisted_const, .top_level_const, .imported_const, .platform_required_declaration, .platform_required_checked_error, .platform_required_const => false,
        };
    }

    fn iteratorProcedureForResolvedTarget(
        self: *BodyContext,
        target: checked.ResolvedValueId,
    ) ?checked.IteratorProcedureId {
        return switch (self.finalDirectTarget(target).record.ref) {
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .promoted_top_level_proc,
            => |proc| proc.iterator_procedure,
            .platform_required_proc => |proc| proc.procedure.iterator_procedure,
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .selected_hoisted_const, .top_level_const, .imported_const, .platform_required_declaration, .platform_required_checked_error, .platform_required_const => null,
        };
    }

    fn iteratorCallNeedsConstructorArgumentEvidence(
        self: *BodyContext,
        procedure: ?checked.IteratorProcedureId,
        args: []const checked.CheckedExprId,
    ) Allocator.Error!bool {
        if (procedure != .custom) return false;
        if (args.len != 3) Common.invariant("custom iterator call did not have three arguments");
        return try self.graph.containsIteratorInterface(try self.instNode(self.view.bodies.expr(args[0]).ty));
    }

    fn iteratorProcedureForMethodTarget(
        _: *BodyContext,
        target: static_dispatch.MethodTarget,
    ) ?checked.IteratorProcedureId {
        return switch (target.kind) {
            .procedure => |procedure| procedure.runtime_target.iteratorProcedure(),
            .local_proc, .structural => null,
        };
    }

    fn callsiteIntrinsicForMethodTarget(
        _: *BodyContext,
        target: static_dispatch.MethodTarget,
    ) ?checked.IntrinsicId {
        return switch (target.kind) {
            .procedure => |procedure| switch (procedure.runtime_target) {
                .intrinsic => |intrinsic| if (intrinsic.callsiteArity() != null)
                    intrinsic
                else
                    Common.invariant("non-call-site intrinsic had a call-site method runtime target"),
                .procedure, .low_level, .graph_participating => null,
            },
            .local_proc, .structural => null,
        };
    }

    fn callsiteIntrinsicForResolvedTarget(self: *BodyContext, target: checked.ResolvedValueId) ?checked.IntrinsicId {
        const intrinsic = switch (self.finalDirectTarget(target).record.ref) {
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .promoted_top_level_proc,
            => |proc| proc.intrinsic,
            .platform_required_proc => |proc| proc.procedure.intrinsic,
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .selected_hoisted_const, .top_level_const, .imported_const, .platform_required_declaration, .platform_required_checked_error, .platform_required_const => null,
        } orelse return null;
        return if (intrinsic.callsiteArity() != null) intrinsic else null;
    }

    fn lowerFieldNamesRenameFieldNames(
        self: *BodyContext,
        args: []const checked.CheckedExprId,
        arg_tys: []const Type.TypeId,
        ret_ty: Type.TypeId,
        lowered_args: []const DraftExprId,
    ) Allocator.Error!DraftExprId {
        if (args.len != 2 or arg_tys.len != 2) Common.invariant("FieldNames.rename_fields reached Monotype with an unexpected arity");
        if (!self.sameType(arg_tys[0], ret_ty)) Common.invariant("FieldNames.rename_fields result type differed from its field set argument");

        const fields_value = lowered_args[0];
        const rename_value = lowered_args[1];
        if (self.generatedFieldNamesBackingValueFieldNames(arg_tys[0])) |backing_fields| {
            const stable_backing_fields = try GuardedList.dupe(self.allocator, Type.Field, backing_fields);
            defer self.allocator.free(stable_backing_fields);
            const fields_local = try self.addLocal(self.builder.symbols.fresh(), ret_ty);
            const rename_local = try self.addLocal(self.builder.symbols.fresh(), arg_tys[1]);
            var body = try self.lowerGeneratedFieldNamesRenameFieldNames(
                stable_backing_fields,
                ret_ty,
                fields_local,
                rename_local,
                arg_tys[1],
            );
            body = try self.wrapLet(rename_local, arg_tys[1], rename_value, body, ret_ty);
            return try self.wrapLet(fields_local, ret_ty, fields_value, body, ret_ty);
        }

        const fields_local = try self.addLocal(self.builder.symbols.fresh(), ret_ty);
        var body = try self.localExpr(fields_local, ret_ty);
        body = try self.wrapWildcardLet(arg_tys[1], rename_value, body, ret_ty);
        return try self.wrapLet(fields_local, ret_ty, fields_value, body, ret_ty);
    }

    fn lowerGeneratedFieldNamesRenameFieldNames(
        self: *BodyContext,
        backing_fields: []const Type.Field,
        fields_ty: Type.TypeId,
        fields_local: DraftLocalId,
        rename_local: DraftLocalId,
        rename_fn_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const fields_backing_ty = self.namedBackingType(fields_ty) orelse
            Common.invariant("generated FieldNames value expected a named backing type");
        const backing_local = try self.addLocal(self.builder.symbols.fresh(), fields_backing_ty);
        const body = try self.lowerGeneratedFieldNamesRenameBackingRecord(
            backing_fields,
            fields_ty,
            fields_backing_ty,
            backing_local,
            rename_local,
            rename_fn_ty,
        );
        const field_pat = try self.addPat(.{
            .ty = fields_ty,
            .data = .{ .nominal = try self.bindPat(backing_local, fields_backing_ty) },
        });
        const branch = DraftBranch{ .pat = field_pat, .body = body };
        return try self.addExpr(.{ .ty = fields_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(fields_local, fields_ty),
            .branches = try self.addBranchSpan(&[_]DraftBranch{branch}),
        } } });
    }

    fn lowerGeneratedFieldNamesRenameBackingRecord(
        self: *BodyContext,
        backing_fields: []const Type.Field,
        fields_ty: Type.TypeId,
        fields_backing_ty: Type.TypeId,
        backing_local: DraftLocalId,
        rename_local: DraftLocalId,
        rename_fn_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const info = self.generatedFieldNamesBackingInfoFromBacking(fields_backing_ty) orelse
            Common.invariant("generated FieldNames value expected a generated backing type");
        const item_fields = try GuardedList.dupe(self.allocator, Type.Field, info.item_fields);
        defer self.allocator.free(item_fields);
        if (backing_fields.len != item_fields.len) Common.invariant("generated FieldNames rename arity differed from item count");
        const str_ty = try self.primitiveType(.str);
        const lowered_items = try self.allocator.alloc(DraftFieldExpr, item_fields.len);
        defer self.allocator.free(lowered_items);
        const item_locals = try self.allocator.alloc(DraftLocalId, item_fields.len);
        defer self.allocator.free(item_locals);
        const item_exprs = try self.allocator.alloc(DraftExprId, item_fields.len);
        defer self.allocator.free(item_exprs);
        const renamed_name_locals = try self.allocator.alloc(DraftLocalId, item_fields.len);
        defer self.allocator.free(renamed_name_locals);
        const renamed_name_exprs = try self.allocator.alloc(DraftExprId, item_fields.len);
        defer self.allocator.free(renamed_name_exprs);
        const renamed_length_locals = try self.allocator.alloc(DraftLocalId, item_fields.len);
        defer self.allocator.free(renamed_length_locals);
        const u64_ty = try self.primitiveType(.u64);

        const items_expr = try self.addFieldAccessExpr(
            try self.localExpr(backing_local, fields_backing_ty),
            info.items_field.name,
            info.items_field.ty,
        );
        const items_local = try self.addLocal(self.builder.symbols.fresh(), info.items_field.ty);

        for (item_fields, 0..) |field, index| {
            const field_ty = field.ty;
            item_exprs[index] = try self.addFieldAccessExpr(
                try self.localExpr(items_local, info.items_field.ty),
                field.name,
                field_ty,
            );
            item_locals[index] = try self.addLocal(self.builder.symbols.fresh(), field_ty);
            const current_name = try self.fieldNameFromLocal(item_locals[index], field_ty, str_ty);
            renamed_name_exprs[index] = try self.addExpr(.{
                .ty = str_ty,
                .data = .{ .call_value = .{
                    .callee = try self.localExpr(rename_local, rename_fn_ty),
                    .args = try self.addExprSpan(&[_]DraftExprId{current_name}),
                } },
            });
            renamed_name_locals[index] = try self.addLocal(self.builder.symbols.fresh(), str_ty);
            renamed_length_locals[index] = try self.addLocal(self.builder.symbols.fresh(), u64_ty);
            const renamed_handle = try self.lowerRecordFieldHandleWithName(
                field_ty,
                try self.localExpr(renamed_name_locals[index], str_ty),
                try self.localExpr(renamed_length_locals[index], u64_ty),
                index,
            );
            lowered_items[index] = .{
                .name = field.name,
                .value = renamed_handle,
            };
        }

        const items_record_expr = try self.addExpr(.{
            .ty = info.items_field.ty,
            .data = .{ .record = try self.addFieldExprSpan(lowered_items) },
        });
        const bound_exprs = try self.fieldNameBoundExprsFromLocals(renamed_length_locals, null, info.shortest_field.ty);
        const shortest_expr = bound_exprs[0];
        const longest_expr = bound_exprs[1];
        const backing_type_fields = try GuardedList.dupe(self.allocator, Type.Field, self.typeStore().fieldSpan(self.recordFieldsSpan(fields_backing_ty)));
        defer self.allocator.free(backing_type_fields);
        const backing_values = try self.allocator.alloc(DraftFieldExpr, backing_type_fields.len);
        defer self.allocator.free(backing_values);
        for (backing_type_fields, 0..) |field, index| {
            const label = self.nameStore().recordFieldLabelText(field.name);
            backing_values[index] = .{
                .name = field.name,
                .value = if (Ident.textEql(label, "items"))
                    items_record_expr
                else if (Ident.textEql(label, "shortest_name"))
                    shortest_expr
                else if (Ident.textEql(label, "longest_name"))
                    longest_expr
                else
                    Common.invariant("generated FieldNames backing contained an unexpected field"),
            };
        }
        const backing_expr = try self.addExpr(.{
            .ty = fields_backing_ty,
            .data = .{ .record = try self.addFieldExprSpan(backing_values) },
        });
        const renamed_fields = try self.addExpr(.{
            .ty = fields_ty,
            .data = .{ .nominal = backing_expr },
        });
        var body = renamed_fields;
        var index = item_fields.len;
        while (index > 0) {
            index -= 1;
            body = try self.wrapLet(
                renamed_length_locals[index],
                u64_ty,
                try self.lowLevelExpr(
                    .str_count_utf8_bytes,
                    &.{try self.localExpr(renamed_name_locals[index], str_ty)},
                    u64_ty,
                ),
                body,
                fields_ty,
            );
            body = try self.wrapLet(
                renamed_name_locals[index],
                str_ty,
                renamed_name_exprs[index],
                body,
                fields_ty,
            );
            body = try self.wrapLet(
                item_locals[index],
                item_fields[index].ty,
                item_exprs[index],
                body,
                fields_ty,
            );
        }
        return try self.wrapLet(items_local, info.items_field.ty, items_expr, body, fields_ty);
    }

    fn lowerFieldNamesNameBound(
        self: *BodyContext,
        args: []const checked.CheckedExprId,
        arg_tys: []const Type.TypeId,
        ret_ty: Type.TypeId,
        bound: FieldNameBound,
        lowered_args: []const DraftExprId,
    ) Allocator.Error!DraftExprId {
        if (args.len != 1 or arg_tys.len != 1) Common.invariant("FieldNames name bound reached Monotype with an unexpected arity");
        if (!self.typeHasBuiltinOwner(ret_ty, .u64)) Common.invariant("FieldNames name bound result was not U64");

        const shape_ty = self.fieldsShapeType(arg_tys[0]);
        const fields = try GuardedList.dupe(self.allocator, Type.Field, self.recordFieldsForShape(shape_ty));
        defer self.allocator.free(fields);
        const fields_value = lowered_args[0];
        if (self.generatedFieldNamesBackingInfo(arg_tys[0])) |info| {
            const fields_local = try self.addLocal(self.builder.symbols.fresh(), arg_tys[0]);
            const body = try self.lowerGeneratedFieldNamesNameBound(
                info,
                arg_tys[0],
                fields_local,
                ret_ty,
                bound,
            );
            return try self.wrapLet(fields_local, arg_tys[0], fields_value, body, ret_ty);
        }

        var value: u64 = 0;
        if (fields.len > 0) {
            value = @intCast(self.nameStore().recordFieldLabelText(fields[0].name).len);
            for (fields[1..]) |field| {
                const len: u64 = @intCast(self.nameStore().recordFieldLabelText(field.name).len);
                value = switch (bound) {
                    .shortest => @min(value, len),
                    .longest => @max(value, len),
                };
            }
        }

        const bound_expr = try self.intLiteralExpr(value, ret_ty);
        return try self.wrapWildcardLet(arg_tys[0], fields_value, bound_expr, ret_ty);
    }

    fn lowerGeneratedFieldNamesNameBound(
        self: *BodyContext,
        info: GeneratedFieldNamesBackingInfo,
        fields_ty: Type.TypeId,
        fields_local: DraftLocalId,
        ret_ty: Type.TypeId,
        bound: FieldNameBound,
    ) Allocator.Error!DraftExprId {
        const fields_backing_ty = self.namedBackingType(fields_ty) orelse
            Common.invariant("generated FieldNames value expected a named backing type");
        const backing_local = try self.addLocal(self.builder.symbols.fresh(), fields_backing_ty);
        const bound_field = switch (bound) {
            .shortest => info.shortest_field,
            .longest => info.longest_field,
        };
        if (!self.sameType(bound_field.ty, ret_ty)) Common.invariant("generated FieldNames bound metadata type differed from result type");
        const bound_expr = try self.addFieldAccessExpr(
            try self.localExpr(backing_local, fields_backing_ty),
            bound_field.name,
            ret_ty,
        );
        const field_pat = try self.addPat(.{
            .ty = fields_ty,
            .data = .{ .nominal = try self.bindPat(backing_local, fields_backing_ty) },
        });
        const branch = DraftBranch{ .pat = field_pat, .body = bound_expr };
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(fields_local, fields_ty),
            .branches = try self.addBranchSpan(&[_]DraftBranch{branch}),
        } } });
    }

    fn lowerFieldName(
        self: *BodyContext,
        args: []const checked.CheckedExprId,
        arg_tys: []const Type.TypeId,
        ret_ty: Type.TypeId,
        lowered_args: []const DraftExprId,
    ) Allocator.Error!DraftExprId {
        if (args.len != 1 or arg_tys.len != 1) Common.invariant("Field.name reached Monotype with an unexpected arity");
        if (!self.typeHasBuiltinOwner(ret_ty, .str)) Common.invariant("Field.name result was not Str");

        const field_ty = arg_tys[0];
        const backing_ty = self.namedBackingType(field_ty) orelse
            Common.invariant("Field.name argument had no backing type");
        const name_field = self.recordFieldByText(backing_ty, "name");
        if (!self.sameType(name_field.ty, ret_ty)) Common.invariant("Field.name backing name field differed from Str");

        const field_value = lowered_args[0];
        const field_local = try self.addLocal(self.builder.symbols.fresh(), field_ty);
        const backing_local = try self.addLocal(self.builder.symbols.fresh(), backing_ty);
        const name_expr = try self.addFieldAccessExpr(
            try self.localExpr(backing_local, backing_ty),
            name_field.name,
            ret_ty,
        );
        const field_pat = try self.addPat(.{
            .ty = field_ty,
            .data = .{ .nominal = try self.bindPat(backing_local, backing_ty) },
        });
        const branch = DraftBranch{ .pat = field_pat, .body = name_expr };
        const matched = try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(field_local, field_ty),
            .branches = try self.addBranchSpan(&[_]DraftBranch{branch}),
        } } });
        return try self.wrapLet(field_local, field_ty, field_value, matched, ret_ty);
    }

    fn lowerFieldNamesValue(
        self: *BodyContext,
        fields_ty: Type.TypeId,
        fields_backing_ty: Type.TypeId,
        field_handle_ty: Type.TypeId,
        renamed_field_locals: []const DraftLocalId,
        renamed_field_lengths: ?[]const u32,
    ) Allocator.Error!DraftExprId {
        const info = self.generatedFieldNamesBackingInfoFromBacking(fields_backing_ty) orelse
            Common.invariant("generated FieldNames backing did not have the expected shape");
        const item_fields = try GuardedList.dupe(self.allocator, Type.Field, info.item_fields);
        defer self.allocator.free(item_fields);
        if (item_fields.len != renamed_field_locals.len) Common.invariant("generated FieldNames backing arity differed from renamed field count");
        if (renamed_field_lengths) |lengths| {
            if (lengths.len != renamed_field_locals.len) Common.invariant("generated FieldNames backing length arity differed from renamed field count");
        }

        const str_ty = try self.primitiveType(.str);
        const u64_ty = try self.primitiveType(.u64);
        const item_values = try self.allocator.alloc(DraftFieldExpr, item_fields.len);
        defer self.allocator.free(item_values);
        // Each name's byte length, counted once when the lengths are not
        // known statically; the handles and the name bounds all read it.
        const length_locals = try self.allocator.alloc(DraftLocalId, item_fields.len);
        defer self.allocator.free(length_locals);
        if (renamed_field_lengths == null) {
            for (length_locals) |*length_local| length_local.* = try self.addLocal(self.builder.symbols.fresh(), u64_ty);
        }

        for (item_fields, 0..) |field, index| {
            const name_expr = try self.localExpr(renamed_field_locals[index], str_ty);
            const name_len_expr = if (renamed_field_lengths) |lengths|
                try self.intLiteralExpr(lengths[index], u64_ty)
            else
                try self.localExpr(length_locals[index], u64_ty);
            item_values[index] = .{
                .name = field.name,
                .value = try self.lowerRecordFieldHandleWithName(field_handle_ty, name_expr, name_len_expr, index),
            };
        }

        const items_expr = try self.addExpr(.{
            .ty = info.items_field.ty,
            .data = .{ .record = try self.addFieldExprSpan(item_values) },
        });
        const bound_exprs = try self.fieldNameBoundExprsFromLocals(
            length_locals,
            renamed_field_lengths,
            info.shortest_field.ty,
        );
        const shortest_expr = bound_exprs[0];
        const longest_expr = bound_exprs[1];
        const backing_type_fields = self.typeStore().fieldSpan(self.recordFieldsSpan(fields_backing_ty));
        const backing_values = try self.allocator.alloc(DraftFieldExpr, backing_type_fields.len);
        defer self.allocator.free(backing_values);
        for (0..GuardedList.borrowLen(backing_type_fields)) |index| {
            const field = GuardedList.at(backing_type_fields, index);
            const label = self.nameStore().recordFieldLabelText(field.name);
            backing_values[index] = .{
                .name = field.name,
                .value = if (Ident.textEql(label, "items"))
                    items_expr
                else if (Ident.textEql(label, "shortest_name"))
                    shortest_expr
                else if (Ident.textEql(label, "longest_name"))
                    longest_expr
                else
                    Common.invariant("generated FieldNames backing contained an unexpected field"),
            };
        }

        const backing_expr = try self.addExpr(.{
            .ty = fields_backing_ty,
            .data = .{ .record = try self.addFieldExprSpan(backing_values) },
        });
        var body = try self.addExpr(.{
            .ty = fields_ty,
            .data = .{ .nominal = backing_expr },
        });
        if (renamed_field_lengths == null) {
            var index = length_locals.len;
            while (index > 0) {
                index -= 1;
                body = try self.wrapLet(
                    length_locals[index],
                    u64_ty,
                    try self.lowLevelExpr(
                        .str_count_utf8_bytes,
                        &.{try self.localExpr(renamed_field_locals[index], str_ty)},
                        u64_ty,
                    ),
                    body,
                    fields_ty,
                );
            }
        }
        return body;
    }

    /// The shortest and longest field name lengths: literals when the
    /// lengths are known statically, otherwise read from `length_locals`,
    /// which hold each renamed name's byte length.
    fn fieldNameBoundExprsFromLocals(
        self: *BodyContext,
        length_locals: []const DraftLocalId,
        renamed_field_lengths: ?[]const u32,
        u64_ty: Type.TypeId,
    ) Allocator.Error!struct { DraftExprId, DraftExprId } {
        if (renamed_field_lengths) |lengths| {
            if (lengths.len != length_locals.len) Common.invariant("renamed field length arity differed from locals");
            var shortest: u64 = 0;
            var longest: u64 = 0;
            if (lengths.len > 0) {
                shortest = lengths[0];
                longest = lengths[0];
                for (lengths[1..]) |len| {
                    shortest = @min(shortest, len);
                    longest = @max(longest, len);
                }
            }
            return .{
                try self.intLiteralExpr(shortest, u64_ty),
                try self.intLiteralExpr(longest, u64_ty),
            };
        }

        if (length_locals.len == 0) {
            const zero = try self.intLiteralExpr(0, u64_ty);
            return .{ zero, zero };
        }

        return .{
            try self.fieldNameBoundExprFromLocals(length_locals, u64_ty, .shortest),
            try self.fieldNameBoundExprFromLocals(length_locals, u64_ty, .longest),
        };
    }

    fn fieldNameBoundExprFromLocals(
        self: *BodyContext,
        length_locals: []const DraftLocalId,
        u64_ty: Type.TypeId,
        bound: FieldNameBound,
    ) Allocator.Error!DraftExprId {
        if (length_locals.len == 0) return try self.intLiteralExpr(0, u64_ty);

        var body = try self.localExpr(length_locals[0], u64_ty);
        for (length_locals[1..]) |candidate_local| {
            const current_local = try self.addLocal(self.builder.symbols.fresh(), u64_ty);
            const cond = try self.lowLevelExpr(switch (bound) {
                .shortest => .num_is_lt,
                .longest => .num_is_gt,
            }, &.{
                try self.localExpr(candidate_local, u64_ty),
                try self.localExpr(current_local, u64_ty),
            }, try self.primitiveType(.bool));
            const selected = try self.ifExpr(
                cond,
                try self.localExpr(candidate_local, u64_ty),
                try self.localExpr(current_local, u64_ty),
                u64_ty,
            );
            body = try self.wrapLet(current_local, u64_ty, body, selected, u64_ty);
        }
        return body;
    }

    fn fieldHandleIndexExpr(
        self: *BodyContext,
        field_local: DraftLocalId,
        field_ty: Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        if (!self.typeHasBuiltinOwner(ret_ty, .u64)) Common.invariant("Field index result was not U64");
        const backing_ty = self.namedBackingType(field_ty) orelse
            Common.invariant("Field index argument had no backing type");
        const index_field = self.recordFieldByText(backing_ty, "index");
        if (!self.sameType(index_field.ty, ret_ty)) Common.invariant("Field backing index field differed from U64");

        const backing_local = try self.addLocal(self.builder.symbols.fresh(), backing_ty);
        const index_expr = try self.addFieldAccessExpr(
            try self.localExpr(backing_local, backing_ty),
            index_field.name,
            ret_ty,
        );
        const field_pat = try self.addPat(.{
            .ty = field_ty,
            .data = .{ .nominal = try self.bindPat(backing_local, backing_ty) },
        });
        const branch = DraftBranch{ .pat = field_pat, .body = index_expr };
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(field_local, field_ty),
            .branches = try self.addBranchSpan(&[_]DraftBranch{branch}),
        } } });
    }

    fn fieldNameLenFromLocal(
        self: *BodyContext,
        field_local: DraftLocalId,
        field_ty: Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        if (!self.typeHasBuiltinOwner(ret_ty, .u64)) Common.invariant("Field name length result was not U64");
        const backing_ty = self.namedBackingType(field_ty) orelse
            Common.invariant("Field name length argument had no backing type");
        const name_len_field = self.recordFieldByText(backing_ty, "name_len");
        if (!self.sameType(name_len_field.ty, ret_ty)) Common.invariant("Field backing name_len field differed from U64");

        const backing_local = try self.addLocal(self.builder.symbols.fresh(), backing_ty);
        const name_len_expr = try self.addFieldAccessExpr(
            try self.localExpr(backing_local, backing_ty),
            name_len_field.name,
            ret_ty,
        );
        const field_pat = try self.addPat(.{
            .ty = field_ty,
            .data = .{ .nominal = try self.bindPat(backing_local, backing_ty) },
        });
        const branch = DraftBranch{ .pat = field_pat, .body = name_len_expr };
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(field_local, field_ty),
            .branches = try self.addBranchSpan(&[_]DraftBranch{branch}),
        } } });
    }

    fn lowerFieldNamesIter(
        self: *BodyContext,
        checked_expr_id: checked.CheckedExprId,
        checked_source_ty: checked.CheckedTypeId,
        args: []const checked.CheckedExprId,
        arg_tys: []const Type.TypeId,
        ret_ty: Type.TypeId,
        mode: FieldNamesIterMode,
        lowered_args: []const DraftExprId,
    ) Allocator.Error!DraftExprId {
        const expected_arity: usize = switch (mode) {
            .all => 1,
            .for_size => 2,
        };
        if (args.len != expected_arity or arg_tys.len != expected_arity) Common.invariant("FieldNames iterator reached Monotype with an unexpected arity");

        const shape_ty = self.fieldsShapeType(arg_tys[0]);
        const fields = try GuardedList.dupe(self.allocator, Type.Field, self.recordFieldsForShape(shape_ty));
        defer self.allocator.free(fields);
        const backing_ty = self.namedBackingType(ret_ty) orelse
            Common.invariant("FieldNames iterator result was not an Iter nominal type");
        const topology = try self.iteratorRepresentationNames(.iter);
        const len_field = self.recordFieldByName(backing_ty, topology.len_field);
        const step_field = self.recordFieldByName(backing_ty, topology.step_field);
        const step_fn_ty = step_field.ty;
        const step_shape = self.functionShape(step_fn_ty, "FieldNames iterator step field was not a function");
        if (self.typeStore().span(step_shape.args).len != 0) {
            Common.invariant("FieldNames iterator step function was not zero-argument");
        }
        const field_handle_ty = self.iterItemType(ret_ty);

        const fields_value = lowered_args[0];
        const fields_local = try self.addLocal(self.builder.symbols.fresh(), arg_tys[0]);
        const size_local: ?DraftLocalId = if (mode == .for_size) blk: {
            if (!self.typeHasBuiltinOwner(arg_tys[1], .u64)) Common.invariant("FieldNames.for_size size argument was not U64");
            break :blk try self.addLocal(self.builder.symbols.fresh(), arg_tys[1]);
        } else null;

        var iter_expr = if (self.generatedFieldNamesBackingFieldNames(arg_tys[0], field_handle_ty, fields.len)) |backing_fields| blk: {
            break :blk try self.lowerFieldNamesValueIter(
                backing_fields,
                arg_tys[0],
                fields_local,
                field_handle_ty,
                ret_ty,
                backing_ty,
                len_field.ty,
                step_fn_ty,
                step_shape.ret,
                size_local,
                arg_tys,
                checked_source_ty,
                checked_expr_id,
            );
        } else if (mode == .all) blk: {
            break :blk try self.lowerFieldNamesStaticIterFromIndex(
                fields,
                0,
                field_handle_ty,
                ret_ty,
                backing_ty,
                len_field.ty,
                step_fn_ty,
                step_shape.ret,
                checked_source_ty,
                checked_expr_id,
            );
        } else blk: {
            break :blk try self.lowerFieldNamesForSizeIter(
                fields,
                field_handle_ty,
                ret_ty,
                backing_ty,
                len_field.ty,
                step_fn_ty,
                step_shape.ret,
                size_local.?,
                arg_tys[1],
                checked_source_ty,
                checked_expr_id,
            );
        };
        if (mode == .for_size) {
            const size_value = lowered_args[1];
            iter_expr = try self.wrapLet(size_local.?, arg_tys[1], size_value, iter_expr, ret_ty);
        }
        return try self.wrapLet(fields_local, arg_tys[0], fields_value, iter_expr, ret_ty);
    }

    const GeneratedFieldNamesBackingInfo = struct {
        items_field: Type.Field,
        shortest_field: Type.Field,
        longest_field: Type.Field,
        item_fields: TypeFieldSpanBorrow,
    };

    fn generatedFieldNamesBackingInfo(
        self: *BodyContext,
        fields_ty: Type.TypeId,
    ) ?GeneratedFieldNamesBackingInfo {
        if (!self.typeHasBuiltinOwner(fields_ty, .fields)) return null;
        const backing_ty = self.namedBackingType(fields_ty) orelse return null;
        return self.generatedFieldNamesBackingInfoFromBacking(backing_ty);
    }

    fn generatedFieldNamesBackingInfoFromBacking(
        self: *BodyContext,
        backing_ty: Type.TypeId,
    ) ?GeneratedFieldNamesBackingInfo {
        const items_field = self.recordFieldByTextOptional(backing_ty, "items") orelse return null;
        const shortest_field = self.recordFieldByTextOptional(backing_ty, "shortest_name") orelse return null;
        const longest_field = self.recordFieldByTextOptional(backing_ty, "longest_name") orelse return null;
        if (!self.typeHasBuiltinOwner(shortest_field.ty, .u64)) return null;
        if (!self.typeHasBuiltinOwner(longest_field.ty, .u64)) return null;
        const item_fields = switch (self.shapeContent(items_field.ty)) {
            .record => |span| self.typeStore().fieldSpan(span),
            .zst => self.typeStore().fieldSpan(.empty()),
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased => return null,
        };
        return .{
            .items_field = items_field,
            .shortest_field = shortest_field,
            .longest_field = longest_field,
            .item_fields = item_fields,
        };
    }

    fn generatedFieldNamesBackingFieldNames(
        self: *BodyContext,
        fields_ty: Type.TypeId,
        field_handle_ty: Type.TypeId,
        expected_count: usize,
    ) ?TypeFieldSpanBorrow {
        const info = self.generatedFieldNamesBackingInfo(fields_ty) orelse return null;
        if (info.item_fields.len != expected_count) return null;
        for (0..GuardedList.borrowLen(info.item_fields)) |index| {
            const field = GuardedList.at(info.item_fields, index);
            if (!self.sameFieldHandleType(field.ty, field_handle_ty)) return null;
        }
        return info.item_fields;
    }

    /// Whether two field-handle types name the same instantiation. The stored
    /// metadata's items carry the compiler-generated backing while a consumer
    /// specialized through the checked interface sees the checked-public
    /// backing of the same nominal; both back onto the identical declared
    /// record, so the pairing is one runtime type.
    fn sameFieldHandleType(self: *BodyContext, left_ty: Type.TypeId, right_ty: Type.TypeId) bool {
        if (self.sameType(left_ty, right_ty)) return true;
        const left = switch (self.typeStore().get(left_ty)) {
            .named => |named| named,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return false,
        };
        const right = switch (self.typeStore().get(right_ty)) {
            .named => |named| named,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return false,
        };
        if (!sameTypeDef(left.def, right.def)) return false;
        const left_args = self.typeStore().span(left.args);
        const right_args = self.typeStore().span(right.args);
        if (GuardedList.borrowLen(left_args) != GuardedList.borrowLen(right_args)) return false;
        for (0..GuardedList.borrowLen(left_args)) |index| {
            if (!self.sameType(GuardedList.at(left_args, index), GuardedList.at(right_args, index))) return false;
        }
        const left_backing = left.backing orelse return false;
        const right_backing = right.backing orelse return false;
        return self.sameType(left_backing.ty, right_backing.ty) and
            (left_backing.authority == .generated_private) != (right_backing.authority == .generated_private);
    }

    fn generatedFieldNamesBackingValueFieldNames(
        self: *BodyContext,
        fields_ty: Type.TypeId,
    ) ?TypeFieldSpanBorrow {
        const info = self.generatedFieldNamesBackingInfo(fields_ty) orelse return null;
        for (0..GuardedList.borrowLen(info.item_fields)) |index| {
            const field = GuardedList.at(info.item_fields, index);
            if (!self.typeHasBuiltinOwner(field.ty, .field)) return null;
        }
        return info.item_fields;
    }

    const GeneratedParseTagUnionSpecBackingInfo = struct {
        record_fields: TypeFieldSpanBorrow,
    };

    fn generatedParseTagUnionSpecBackingInfo(
        self: *BodyContext,
        spec_ty: Type.TypeId,
    ) ?GeneratedParseTagUnionSpecBackingInfo {
        if (!self.typeHasBuiltinOwner(spec_ty, .parse_tag_union_spec)) return null;
        const backing_ty = self.namedBackingType(spec_ty) orelse return null;
        const record_fields = switch (self.shapeContent(backing_ty)) {
            .record => |span| self.typeStore().fieldSpan(span),
            .zst => self.typeStore().fieldSpan(.empty()),
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased => return null,
        };
        if (record_fields.len == 0) return null;
        return .{ .record_fields = record_fields };
    }

    fn isGeneratedIteratorEvidenceNode(self: *BodyContext, node: NodeId) Allocator.Error!bool {
        return switch ((try self.graph.content(node))) {
            .named => |named| switch (named.def.iterator_representation) {
                .minted, .forced_dynamic => if (named.builtin_owner) |owner|
                    static_dispatch.isIteratorOwner(owner)
                else
                    false,
                .none => false,
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => false,
        };
    }

    fn isForcedDynamicIteratorNode(self: *BodyContext, node: NodeId) Allocator.Error!bool {
        return switch ((try self.graph.content(node))) {
            .named => |named| named.def.iterator_representation == .forced_dynamic,
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => false,
        };
    }

    /// Build an exact iterator procedure request entirely in the active
    /// instantiation graph. No durable Monotype TypeId is created until the
    /// graph has received all evidence and is sealed.
    fn generatedIteratorFunctionNode(
        self: *BodyContext,
        procedure: checked.IteratorProcedureId,
        public_fn_node: NodeId,
        request_fn_node: NodeId,
        checked_args: []const checked.CheckedExprId,
    ) Allocator.Error!?NodeId {
        const public_fn = try self.graph.functionNodes(public_fn_node);
        const request_fn = try self.graph.functionNodes(request_fn_node);
        if (public_fn.args.len != request_fn.args.len) {
            Common.invariant("iterator public/request function arity differed");
        }
        const expected_ret = if ((try self.isGeneratedIteratorEvidenceNode(request_fn.ret))) request_fn.ret else null;

        if (expected_ret) |expected| switch (procedure) {
            .from_step => return try self.generatedIteratorConstructorFunctionNode(expected),
            .range_done => return try self.graphFunctionNode(request_fn.args, expected),
            .identity, .next, .custom, .single, .list_iter, .list_iter_rev, .str_iter_utf8, .map, .keep_if, .drop_if, .take_first, .drop_first, .concat, .append, .with_index, .step_by, .from_iter, .range_iter, .numeric_range_iter, .numeric_to, .numeric_until => {},
        };

        switch (procedure) {
            .identity => {
                if (checked_args.len != 1 or request_fn.args.len != 1) {
                    Common.invariant("Iter.iter reached Monotype with an unexpected arity");
                }
                if ((try self.isGeneratedIteratorEvidenceNode(request_fn.args[0]))) {
                    return try self.graphFunctionNode(&.{request_fn.args[0]}, request_fn.args[0]);
                }
            },
            .next => {
                if (checked_args.len != 1 or request_fn.args.len != 1) {
                    Common.invariant("iterator next reached Monotype with an unexpected arity");
                }
                if ((try self.isGeneratedIteratorEvidenceNode(request_fn.args[0]))) {
                    return try self.graphFunctionNode(
                        &.{request_fn.args[0]},
                        try self.generatedIteratorStepReturnNode(request_fn.args[0]),
                    );
                }
            },
            .custom => {
                if (checked_args.len != 3 or request_fn.args.len != 3) {
                    Common.invariant("custom iterator source reached Monotype with an unexpected arity");
                }
                if ((try self.expectedGeneratedIteratorProducerNode(expected_ret, mintedProducerKind(procedure)))) |expected| {
                    if ((try self.isForcedDynamicIteratorNode(expected))) {
                        return try self.graphFunctionNode(request_fn.args, expected);
                    }
                    const components = (try self.generatedIteratorComponentNodes(expected, 2));
                    return try self.graphFunctionNode(&.{ components[0], request_fn.args[1], components[1] }, expected);
                }
                const state_is_private = try self.graph.containsGeneratedPrivate(request_fn.args[0]);
                const advance_node = if (state_is_private)
                    try self.iterCustomAdvanceRequestNode(checked_args[2], request_fn.args[0])
                else
                    request_fn.args[2];
                return try self.graphFunctionNode(
                    &.{ request_fn.args[0], request_fn.args[1], advance_node },
                    try self.generatedIteratorNode(
                        mintedProducerKind(procedure),
                        public_fn.ret,
                        &.{ request_fn.args[0], advance_node },
                        try self.callableArgumentEvidenceDigest(checked_args[2]),
                    ),
                );
            },
            // Both list-backed conversions mint over the same component and
            // item; only the producer kind differs, and that comes from the
            // registry.
            .list_iter, .list_iter_rev => {
                if (checked_args.len != 1 or request_fn.args.len != 1) {
                    Common.invariant("list-backed iterator conversion reached Monotype with an unexpected arity");
                }
                if (try self.generatedIteratorExpectedProducerFunctionNode(mintedProducerKind(procedure), request_fn.args, expected_ret)) |expected_fn| return expected_fn;
                return try self.graphFunctionNode(
                    request_fn.args,
                    try self.generatedIteratorNodeWithItem(
                        mintedProducerKind(procedure),
                        public_fn.ret,
                        &.{request_fn.args[0]},
                        null,
                        try self.graph.listElementNode(request_fn.args[0]),
                    ),
                );
            },
            .str_iter_utf8 => {
                if (checked_args.len != 1 or request_fn.args.len != 1) {
                    Common.invariant("Str.iter_utf8 reached Monotype with an unexpected arity");
                }
                if (try self.generatedIteratorExpectedProducerFunctionNode(mintedProducerKind(procedure), request_fn.args, expected_ret)) |expected_fn| return expected_fn;
                return try self.graphFunctionNode(
                    request_fn.args,
                    try self.generatedIteratorNode(mintedProducerKind(procedure), public_fn.ret, &.{request_fn.args[0]}, null),
                );
            },
            .single => {
                if (checked_args.len != 1 or request_fn.args.len != 1) {
                    Common.invariant("Iter.single reached Monotype with an unexpected arity");
                }
                if (try self.generatedIteratorExpectedProducerFunctionNode(mintedProducerKind(procedure), request_fn.args, expected_ret)) |expected_fn| return expected_fn;
                return try self.graphFunctionNode(
                    request_fn.args,
                    try self.generatedIteratorNodeWithItem(
                        mintedProducerKind(procedure),
                        public_fn.ret,
                        &.{request_fn.args[0]},
                        null,
                        request_fn.args[0],
                    ),
                );
            },
            .numeric_until, .numeric_to => {
                if (try self.generatedIteratorExpectedProducerFunctionNode(mintedProducerKind(procedure), request_fn.args, expected_ret)) |expected_fn| return expected_fn;
                return try self.graphFunctionNode(
                    request_fn.args,
                    try self.generatedIteratorNode(mintedProducerKind(procedure), public_fn.ret, &.{}, null),
                );
            },
            .map, .keep_if, .drop_if => return try self.generatedIteratorAdapterFunctionNode(mintedProducerKind(procedure), public_fn.ret, request_fn.args, checked_args, expected_ret, 1),
            .take_first, .drop_first, .append, .with_index, .step_by, .from_iter => return try self.generatedIteratorAdapterFunctionNode(mintedProducerKind(procedure), public_fn.ret, request_fn.args, checked_args, expected_ret, null),
            .concat => {
                if (checked_args.len != 2 or request_fn.args.len != 2) {
                    Common.invariant("Iter.concat reached Monotype with an unexpected arity");
                }
                if (try self.generatedIteratorExpectedProducerFunctionNode(mintedProducerKind(procedure), request_fn.args, expected_ret)) |expected_fn| return expected_fn;
                if ((try self.isGeneratedIteratorEvidenceNode(request_fn.args[0])) or
                    (try self.isGeneratedIteratorEvidenceNode(request_fn.args[1])))
                {
                    return try self.graphFunctionNode(
                        request_fn.args,
                        try self.generatedIteratorNode(mintedProducerKind(procedure), public_fn.ret, request_fn.args, null),
                    );
                }
            },
            .range_iter, .numeric_range_iter, .from_step, .range_done => {},
        }
        return null;
    }

    /// Build the transition request of `Iter.custom` or `Stream.custom` with
    /// its checked state role bound to the seed's exact representation. The
    /// transition's argument and successful next-state result share that
    /// checked identity, so a fresh instantiation propagates the
    /// representation through both positions without mutating a finished seed
    /// Monotype or reconstructing a type path.
    fn iterCustomAdvanceRequestNode(
        self: *BodyContext,
        checked_advance: checked.CheckedExprId,
        state_node: NodeId,
    ) Allocator.Error!NodeId {
        const checked_fn_ty = self.view.bodies.expr(checked_advance).ty;
        const checked_fn = self.checkedFunctionType(checked_fn_ty);
        if (checked_fn.args.len != 1) {
            Common.invariant("custom iterator advance callable did not have exactly one state argument");
        }
        var checked_try_ty = checked_fn.ret;
        const checked_try = while (true) switch (checkedPayload(self.view, checked_try_ty)) {
            .alias => |alias| checked_try_ty = alias.backing,
            .nominal => |nominal| break nominal,
            .pending, .err, .flex, .rigid, .record, .tuple, .function, .tag_union, .empty_record, .empty_tag_union => Common.invariant("custom iterator advance callable did not return Try"),
        };
        const checked_try_builtin = switch (checked_try.representation) {
            .builtin => |builtin| builtin,
            .local_declaration, .imported_declaration, .local_box_payload_capability, .imported_box_payload_capability, .opaque_without_backing => Common.invariant("custom iterator advance callable returned a non-builtin Try"),
        };
        if (checked.builtinRuntimeEncoding(checked_try_builtin) != .try_nominal or checked_try.args.len != 2) {
            Common.invariant("custom iterator advance callable did not return the builtin Try type");
        }
        var checked_ok = checked_try.args[0];
        const checked_ok_items = while (true) switch (checkedPayload(self.view, checked_ok)) {
            .alias => |alias| checked_ok = alias.backing,
            .tuple => |items| break items,
            .pending, .err, .flex, .rigid, .record, .nominal, .function, .tag_union, .empty_record, .empty_tag_union => Common.invariant("custom iterator advance success value was not an item-state tuple"),
        };
        if (checked_ok_items.len != 2) {
            Common.invariant("custom iterator advance success tuple did not have item and state elements");
        }
        const checked_next_state = checked_ok_items[1];

        const previous = self.instantiation;
        self.instantiation = TypeInstantiationContext.init(
            self.allocator,
            self.builder.allocateInstantiationScope(),
            self.view.key.bytes,
        );
        defer {
            self.instantiation.deinit();
            self.instantiation = previous;
        }

        try self.putScopedNode(self.scopedCheckedType(checked_fn.args[0]), state_node);
        try self.putScopedNode(self.scopedCheckedType(checked_next_state), state_node);
        const advance_node = try self.instNode(checked_fn_ty);
        const advance_fn = try self.graph.functionNodes(advance_node);
        if (advance_fn.args.len != 1 or !self.graph.sameClass(advance_fn.args[0], state_node)) {
            Common.invariant("custom iterator advance request lost its exact state argument");
        }
        self.graph.registerConstructorEvidenceRequest(advance_node);
        return advance_node;
    }

    /// The registry-declared minted kind for a producing iterator procedure.
    fn mintedProducerKind(procedure: checked.IteratorProcedureId) Type.IteratorKind {
        return procedure.iteratorKind() orelse
            Common.invariant("iterator procedure minted no producer kind");
    }

    fn generatedIteratorAdapterFunctionNode(
        self: *BodyContext,
        kind: Type.IteratorKind,
        public_ret: NodeId,
        args: []const NodeId,
        checked_args: []const checked.CheckedExprId,
        expected_ret: ?NodeId,
        callable_index: ?usize,
    ) Allocator.Error!?NodeId {
        // The adapted iterator is always the first argument; the remaining
        // arguments are the operation's own inputs.
        if (checked_args.len != args.len or args.len == 0 or args.len > 2) {
            Common.invariant("iterator adapter reached Monotype with an unexpected arity");
        }
        if (try self.generatedIteratorExpectedProducerFunctionNode(kind, args, expected_ret)) |expected_fn| return expected_fn;
        if (!(try self.isGeneratedIteratorEvidenceNode(args[0]))) return null;
        const callable_evidence = if (callable_index) |index|
            try self.callableArgumentEvidenceDigest(checked_args[index])
        else
            null;
        return try self.graphFunctionNode(
            args,
            try self.generatedIteratorNode(kind, public_ret, args, callable_evidence),
        );
    }

    fn expectedGeneratedIteratorProducerNode(
        self: *BodyContext,
        expected_ret: ?NodeId,
        kind: Type.IteratorKind,
    ) Allocator.Error!?NodeId {
        const expected = expected_ret orelse return null;
        if (!(try self.isGeneratedIteratorEvidenceNode(expected))) return null;
        if ((try self.isForcedDynamicIteratorNode(expected))) return expected;
        const named = (try self.graph.content(expected)).named;
        return if (named.def.iterator_kind == kind) expected else null;
    }

    fn generatedIteratorExpectedProducerFunctionNode(
        self: *BodyContext,
        kind: Type.IteratorKind,
        args: []const NodeId,
        expected_ret: ?NodeId,
    ) Allocator.Error!?NodeId {
        const expected = (try self.expectedGeneratedIteratorProducerNode(expected_ret, kind)) orelse return null;
        if ((try self.isForcedDynamicIteratorNode(expected))) return try self.graphFunctionNode(args, expected);
        // A source without nominal components (ranges) initializes the
        // generated step state from its construction inputs. Its producer
        // therefore keeps the checked request arguments while returning the
        // exact private iterator.
        if (kind.componentTopology()) |topology| {
            if (topology == .source_without_components) {
                return try self.graphFunctionNode(args, expected);
            }
        }
        return try self.graphFunctionNode((try self.generatedIteratorComponentNodes(expected, args.len)), expected);
    }

    fn generatedIteratorComponentNodes(
        self: *BodyContext,
        iterator: NodeId,
        expected_components: usize,
    ) Allocator.Error![]const NodeId {
        const named = switch ((try self.graph.content(iterator))) {
            .named => |named| named,
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => Common.invariant("generated iterator component nodes requested for a non-named type"),
        };
        if (named.args.len != expected_components + 1) {
            Common.invariant("generated iterator producer did not contain its component count");
        }
        return named.args[1..];
    }

    const IteratorRepresentationNames = Type.IteratorTopology;

    fn iteratorRepresentationNames(self: *BodyContext, owner: static_dispatch.IteratorOwner) Allocator.Error!IteratorRepresentationNames {
        const topologies = self.view.static_dispatch_plans.iterator_topologies;
        if (topologies.len != std.enums.values(static_dispatch.IteratorOwner).len) {
            Common.invariant("checked module omitted an iterator representation topology");
        }
        const topology = topologies[@backingInt(owner)];
        return .{
            .len_field = try self.recordFieldName(self.view, topology.len_field),
            .step_field = try self.recordFieldName(self.view, topology.step_field),
            .known_tag = try self.tagName(self.view, topology.known_tag),
            .unknown_tag = try self.tagName(self.view, topology.unknown_tag),
            .done_tag = try self.tagName(self.view, topology.done_tag),
            .one_tag = try self.tagName(self.view, topology.one_tag),
            .skip_tag = try self.tagName(self.view, topology.skip_tag),
            .item_field = try self.recordFieldName(self.view, topology.item_field),
            .rest_field = try self.recordFieldName(self.view, topology.rest_field),
        };
    }

    /// The public iterator type a generated or public iterator node belongs to.
    fn iteratorOwnerOfNamed(builtin_owner: ?static_dispatch.BuiltinOwner) static_dispatch.IteratorOwner {
        const owner = builtin_owner orelse
            Common.invariant("iterator representation requested for a type without builtin identity");
        return static_dispatch.iteratorOwner(owner) orelse
            Common.invariant("iterator representation requested for a non-iterator builtin type");
    }

    fn generatedIteratorConstructorFunctionNode(self: *BodyContext, iterator: NodeId) Allocator.Error!NodeId {
        const named = (try self.graph.content(iterator)).named;
        const backing = named.backing orelse
            Common.invariant("generated iterator constructor requested a type without backing");
        const topology = try self.iteratorRepresentationNames(iteratorOwnerOfNamed(named.builtin_owner));
        return try self.graphFunctionNode(&.{
            try self.graph.recordFieldNode(backing.node, topology.len_field),
            try self.graph.recordFieldNode(backing.node, topology.step_field),
        }, iterator);
    }

    fn generatedIteratorStepReturnNode(self: *BodyContext, iterator: NodeId) Allocator.Error!NodeId {
        const named = (try self.graph.content(iterator)).named;
        const backing = named.backing orelse
            Common.invariant("generated iterator next requested a type without backing");
        const topology = try self.iteratorRepresentationNames(iteratorOwnerOfNamed(named.builtin_owner));
        const step = try self.graph.functionNodes(try self.graph.recordFieldNode(backing.node, topology.step_field));
        return step.ret;
    }

    fn generatedIteratorNode(
        self: *BodyContext,
        kind: Type.IteratorKind,
        public_iterator: NodeId,
        components: []const NodeId,
        callable_evidence: ?names.TypeDigest,
    ) Allocator.Error!NodeId {
        const public_named = switch ((try self.graph.content(public_iterator))) {
            .named => |named| named,
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => Common.invariant("generated iterator requested a non-named public type"),
        };
        if (public_named.args.len == 0) {
            Common.invariant("generated iterator requested a public type without an item argument");
        }
        return self.generatedIteratorNodeWithItem(
            kind,
            public_iterator,
            components,
            callable_evidence,
            public_named.args[0],
        );
    }

    fn generatedIteratorNodeWithItem(
        self: *BodyContext,
        kind: Type.IteratorKind,
        public_iterator: NodeId,
        components: []const NodeId,
        callable_evidence: ?names.TypeDigest,
        item_node: NodeId,
    ) Allocator.Error!NodeId {
        const public_named = switch ((try self.graph.content(public_iterator))) {
            .named => |named| named,
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => Common.invariant("generated iterator requested a non-named public type"),
        };
        const owner = public_named.builtin_owner orelse
            Common.invariant("generated iterator requested an Iter type without producer-owned builtin identity");
        if (!static_dispatch.isIteratorOwner(owner) or public_named.args.len == 0) {
            Common.invariant("generated iterator requested a non-public Iter source type");
        }
        const public_source: solve.InstIteratorPublicSource = if (public_named.generated_iterator) |generated|
            generated.public_source
        else blk: {
            if (public_named.def.iterator_representation != .none or public_named.args.len != 1) {
                Common.invariant("generated iterator source lacked its producer-owned public contract");
            }
            const public_backing = public_named.backing orelse
                Common.invariant("generated iterator requested a public Iter without backing");
            if (public_backing.authority != .checked_public) {
                Common.invariant("generated iterator public source had private backing authority");
            }
            break :blk .{
                .named_type = public_named.named_type,
                .def = public_named.def,
                .kind = public_named.kind,
                .builtin_owner = owner,
                .backing = public_backing,
                .declared_order = public_named.declared_order,
            };
        };
        const mint_depth = (try self.generatedIteratorMintDepth(kind, components)) orelse
            return try self.forcedDynamicIteratorNode(public_iterator, item_node, public_source);
        if ((try self.graph.findGeneratedIterator(public_iterator, kind, components, callable_evidence))) |existing| {
            return existing;
        }

        const Context = struct {
            body: *BodyContext,
            public_source: solve.InstIteratorPublicSource,
            item_node: NodeId,
            components: []const NodeId,
            callable_evidence: ?names.TypeDigest,
            kind: Type.IteratorKind,
            mint_depth: u8,

            fn fill(ctx: @This(), self_node: NodeId) Allocator.Error!InstNode {
                const args = try ctx.body.graph.arena().alloc(NodeId, ctx.components.len + 1);
                args[0] = ctx.item_node;
                @memcpy(args[1..], ctx.components);
                var def = ctx.public_source.def;
                def.generated = null;
                def.iterator_representation = .minted;
                def.iterator_kind = ctx.kind;
                def.iterator_depth = ctx.mint_depth;
                const topology = try ctx.body.iteratorRepresentationNames(iteratorOwnerOfNamed(ctx.public_source.builtin_owner));
                def.iterator_topology = topology;
                return try ctx.body.graph.namedContent(.{
                    .named_type = ctx.public_source.named_type,
                    .def = def,
                    .kind = ctx.public_source.kind,
                    .builtin_owner = ctx.public_source.builtin_owner,
                    .args = args,
                    .backing = .{
                        .node = try ctx.body.generatedIteratorBackingNode(
                            topology,
                            ctx.public_source.backing.node,
                            self_node,
                            ctx.item_node,
                        ),
                        .use = ctx.public_source.backing.use,
                        .authority = .generated_private,
                    },
                    .generated_iterator = try ctx.body.graph.generatedIterator(.{
                        .callable_evidence = ctx.callable_evidence,
                        .public_source = ctx.public_source,
                    }),
                    .declared_order = ctx.public_source.declared_order,
                });
            }
        };
        return try self.graph.addRecursiveNode(Context{
            .body = self,
            .public_source = public_source,
            .item_node = item_node,
            .components = try self.graph.arena().dupe(NodeId, components),
            .callable_evidence = callable_evidence,
            .kind = kind,
            .mint_depth = mint_depth,
        }, Context.fill);
    }

    const max_minted_iterator_chain_depth: u8 = 16;

    fn generatedIteratorMintDepth(
        self: *BodyContext,
        kind: Type.IteratorKind,
        components: []const NodeId,
    ) Allocator.Error!?u8 {
        if (kind == .forced_dynamic) return null;
        const topology = kind.componentTopology() orelse
            Common.invariant("generated iterator mint requested without a producer kind");
        switch (topology) {
            .source_without_components, .source_with_components => return 1,
            .adapter => {},
        }

        var component_depth: u8 = 0;
        for (components) |component| {
            const named = switch ((try self.graph.content(component))) {
                .named => |named| named,
                .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => continue,
            };
            switch (named.def.iterator_representation) {
                .forced_dynamic => return null,
                .minted => {
                    if (named.def.iterator_depth == 0) {
                        Common.invariant("generated iterator component had no producer-assigned depth");
                    }
                    component_depth = @max(component_depth, named.def.iterator_depth);
                },
                .none => {},
            }
        }
        if (component_depth == 0) {
            Common.invariant("generated iterator adapter had no exact iterator component");
        }
        if (component_depth >= max_minted_iterator_chain_depth) return null;
        return component_depth + 1;
    }

    fn forcedDynamicIteratorNode(
        self: *BodyContext,
        public_iterator: NodeId,
        item_node: NodeId,
        public_source: solve.InstIteratorPublicSource,
    ) Allocator.Error!NodeId {
        if ((try self.graph.findGeneratedIterator(public_iterator, .forced_dynamic, &.{}, null))) |existing| {
            return existing;
        }
        const Context = struct {
            body: *BodyContext,
            item_node: NodeId,
            public_source: solve.InstIteratorPublicSource,

            fn fill(ctx: @This(), self_node: NodeId) Allocator.Error!InstNode {
                const args = try ctx.body.graph.arena().alloc(NodeId, 1);
                args[0] = ctx.item_node;
                var def = ctx.public_source.def;
                def.generated = null;
                def.iterator_representation = .forced_dynamic;
                def.iterator_kind = .forced_dynamic;
                def.iterator_depth = 0;
                const topology = try ctx.body.iteratorRepresentationNames(iteratorOwnerOfNamed(ctx.public_source.builtin_owner));
                def.iterator_topology = topology;
                return try ctx.body.graph.namedContent(.{
                    .named_type = ctx.public_source.named_type,
                    .def = def,
                    .kind = ctx.public_source.kind,
                    .builtin_owner = ctx.public_source.builtin_owner,
                    .args = args,
                    .backing = .{
                        .node = try ctx.body.generatedIteratorBackingNode(
                            topology,
                            ctx.public_source.backing.node,
                            self_node,
                            ctx.item_node,
                        ),
                        .use = ctx.public_source.backing.use,
                        .authority = .generated_private,
                    },
                    .generated_iterator = try ctx.body.graph.generatedIterator(.{
                        .callable_evidence = null,
                        .public_source = ctx.public_source,
                    }),
                    .declared_order = ctx.public_source.declared_order,
                });
            }
        };
        return try self.graph.addRecursiveNode(Context{
            .body = self,
            .item_node = item_node,
            .public_source = public_source,
        }, Context.fill);
    }

    fn generatedIteratorBackingNode(
        self: *BodyContext,
        topology: IteratorRepresentationNames,
        public_backing: NodeId,
        self_node: NodeId,
        item_node: NodeId,
    ) Allocator.Error!NodeId {
        const public_fields = (try self.graph.recordNodes(public_backing)).fields;
        const fields = try self.graph.arena().alloc(InstField, public_fields.len);
        for (public_fields, fields) |field, *out| {
            out.* = .{
                .name = field.name,
                .ty = if (field.name == topology.step_field)
                    try self.generatedIteratorStepFunctionNode(topology, field.ty, self_node, item_node)
                else
                    field.ty,
                .value_ty = field.value_ty,
                .kind = field.kind,
                .default = field.default,
            };
        }
        return try self.graph.newNode(.{ .record = .{
            .fields = fields,
            .ext = try self.graph.newNode(.empty_record),
        } });
    }

    fn generatedIteratorStepFunctionNode(
        self: *BodyContext,
        topology: IteratorRepresentationNames,
        public_step: NodeId,
        self_node: NodeId,
        item_node: NodeId,
    ) Allocator.Error!NodeId {
        const step = try self.graph.functionNodes(public_step);
        return try self.graphFunctionNode(
            step.args,
            try self.generatedIteratorStepResultNode(topology, step.ret, self_node, item_node),
        );
    }

    fn generatedIteratorStepResultNode(
        self: *BodyContext,
        topology: IteratorRepresentationNames,
        public_result: NodeId,
        self_node: NodeId,
        item_node: NodeId,
    ) Allocator.Error!NodeId {
        const public_tags = (try self.graph.tagRowNodes(public_result)).tags;
        const tags = try self.graph.arena().alloc(InstTag, public_tags.len);
        for (public_tags, tags) |tag, *out| {
            const payloads = try self.graph.arena().alloc(NodeId, tag.payloads.len);
            for (tag.payloads, payloads) |payload, *payload_out| {
                payload_out.* = try self.generatedIteratorStepPayloadNode(topology, tag.name, payload, self_node, item_node);
            }
            out.* = .{
                .name = tag.name,
                .checked_name = tag.checked_name,
                .payloads = payloads,
            };
        }
        return try self.graph.newNode(.{ .tag_union = .{
            .tags = tags,
            .ext = try self.graph.newNode(.empty_tag_union),
        } });
    }

    fn generatedIteratorStepPayloadNode(
        self: *BodyContext,
        topology: IteratorRepresentationNames,
        tag_name: names.TagNameId,
        public_payload: NodeId,
        self_node: NodeId,
        item_node: NodeId,
    ) Allocator.Error!NodeId {
        if (tag_name != topology.one_tag and tag_name != topology.skip_tag) return public_payload;
        const public_fields = (try self.graph.recordNodes(public_payload)).fields;
        const fields = try self.graph.arena().alloc(InstField, public_fields.len);
        for (public_fields, fields) |field, *out| {
            out.* = .{
                .name = field.name,
                .ty = if (field.name == topology.rest_field)
                    self_node
                else if (field.name == topology.item_field)
                    item_node
                else
                    field.ty,
                .value_ty = field.value_ty,
                .kind = field.kind,
                .default = field.default,
            };
        }
        return try self.graph.newNode(.{ .record = .{
            .fields = fields,
            .ext = try self.graph.newNode(.empty_record),
        } });
    }

    fn callableArgumentEvidenceDigest(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
    ) Allocator.Error!?names.TypeDigest {
        const expr = self.view.bodies.expr(expr_id);
        return switch (expr.data) {
            .closure => |closure| try self.closureArgumentEvidenceDigest(expr_id, closure),
            .lambda => |lambda| self.lambdaArgumentEvidenceDigest(expr_id, lambda.args.len),
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => null,
        };
    }

    fn lambdaArgumentEvidenceDigest(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        arg_count: usize,
    ) names.TypeDigest {
        var hasher = TypeDigestHasher.init();
        hasher.update("roc.generated_iterator.callable.lambda");
        hasher.update(self.view.key.bytes[0..]);
        hashU32(&hasher, @backingInt(expr_id));
        hashU32(&hasher, @intCast(arg_count));
        hashU32(&hasher, 0);
        return .{ .bytes = hasher.finalResult() };
    }

    fn closureArgumentEvidenceDigest(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        closure: anytype,
    ) Allocator.Error!names.TypeDigest {
        var hasher = TypeDigestHasher.init();
        hasher.update("roc.generated_iterator.callable.closure");
        hasher.update(self.view.key.bytes[0..]);
        hashU32(&hasher, @backingInt(expr_id));
        hashU32(&hasher, @backingInt(closure.lambda));
        hashU32(&hasher, @intCast(closure.captures.len));
        for (closure.captures) |capture| {
            hashU32(&hasher, @backingInt(capture.capture_id));
            hashU32(&hasher, capture.scope_depth);
            const binder = checkedCaptureBinder(self.view, capture.pattern);
            const checked_type_key = self.view.types.rootKey(checkedBinderType(self.view, binder));
            hasher.update(&checked_type_key.bytes);
        }
        return .{ .bytes = hasher.finalResult() };
    }

    fn relateCheckedTypeToMono(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        mono_ty: Type.TypeId,
    ) Allocator.Error!void {
        const checked_node = try self.instNode(checked_ty);
        const mono_node = try self.graph.importMono(mono_ty);
        try relateCheckedNodeToMono(self.graph, checked_node, mono_node);
    }

    fn relateCheckedFunctionToMono(
        self: *BodyContext,
        checked_fn_ty: checked.CheckedTypeId,
        mono_fn_ty: Type.TypeId,
    ) Allocator.Error!NodeId {
        const checked_node = try self.instNode(checked_fn_ty);
        const request_node = try self.graph.importMonoIndependent(mono_fn_ty);
        const related = try checkedMonoRequestNode(self.graph, checked_node, request_node, .construction);
        return related;
    }

    fn lowerFieldNamesValueIter(
        self: *BodyContext,
        backing_fields: anytype,
        fields_ty: Type.TypeId,
        fields_local: DraftLocalId,
        field_handle_ty: Type.TypeId,
        iter_ty: Type.TypeId,
        iter_backing_ty: Type.TypeId,
        len_ty: Type.TypeId,
        step_fn_ty: Type.TypeId,
        step_ret_ty: Type.TypeId,
        size_local: ?DraftLocalId,
        arg_tys: []const Type.TypeId,
        checked_source_ty: checked.CheckedTypeId,
        source_expr_id: checked.CheckedExprId,
    ) Allocator.Error!DraftExprId {
        const fields_backing_ty = self.namedBackingType(fields_ty) orelse
            Common.invariant("generated FieldNames value expected a named backing type");
        const info = self.generatedFieldNamesBackingInfoFromBacking(fields_backing_ty) orelse
            Common.invariant("generated FieldNames value expected a generated backing type");
        const item_fields = try GuardedList.dupe(self.allocator, Type.Field, info.item_fields);
        defer self.allocator.free(item_fields);
        if (GuardedList.borrowLen(backing_fields) != item_fields.len) Common.invariant("generated FieldNames iterator arity differed from item count");
        const backing_local = try self.addLocal(self.builder.symbols.fresh(), fields_backing_ty);
        const items_expr = try self.addFieldAccessExpr(
            try self.localExpr(backing_local, fields_backing_ty),
            info.items_field.name,
            info.items_field.ty,
        );
        const items_local = try self.addLocal(self.builder.symbols.fresh(), info.items_field.ty);
        const body = try self.lowerFieldNamesValueIterFromIndex(
            item_fields,
            info.items_field.ty,
            items_local,
            0,
            field_handle_ty,
            iter_ty,
            iter_backing_ty,
            len_ty,
            step_fn_ty,
            step_ret_ty,
            size_local,
            arg_tys,
            checked_source_ty,
            source_expr_id,
        );
        const body_with_items = try self.wrapLet(items_local, info.items_field.ty, items_expr, body, iter_ty);
        const field_pat = try self.addPat(.{
            .ty = fields_ty,
            .data = .{ .nominal = try self.bindPat(backing_local, fields_backing_ty) },
        });
        const branch = DraftBranch{ .pat = field_pat, .body = body_with_items };
        return try self.addExpr(.{ .ty = iter_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(fields_local, fields_ty),
            .branches = try self.addBranchSpan(&[_]DraftBranch{branch}),
        } } });
    }

    /// The iterator over `backing_fields[start..]`: each level's length is
    /// lowered on the way in, and each level's step, which continues with the
    /// next level's iterator, on the way out.
    fn lowerFieldNamesValueIterFromIndex(
        self: *BodyContext,
        backing_fields: []const Type.Field,
        items_ty: Type.TypeId,
        items_local: DraftLocalId,
        start: usize,
        field_handle_ty: Type.TypeId,
        iter_ty: Type.TypeId,
        iter_backing_ty: Type.TypeId,
        len_ty: Type.TypeId,
        step_fn_ty: Type.TypeId,
        step_ret_ty: Type.TypeId,
        size_local: ?DraftLocalId,
        arg_tys: []const Type.TypeId,
        checked_source_ty: checked.CheckedTypeId,
        source_expr_id: checked.CheckedExprId,
    ) Allocator.Error!DraftExprId {
        const mode: FieldNamesIterMode = if (size_local == null) .all else .for_size;
        var lens: std.ArrayListUnmanaged(DraftExprId) = .empty;
        defer lens.deinit(self.allocator);
        var index = start;
        while (true) : (index += 1) {
            try lens.append(self.allocator, try self.lowerFieldNamesIterLen(backing_fields.len - index, len_ty, mode));
            if (index == backing_fields.len) break;
        }
        const done_step = try self.lowerFieldNamesDoneStep(checked_source_ty, source_expr_id, backing_fields.len, mode, step_fn_ty, step_ret_ty);
        var rest_expr = try self.lowerGeneratedIterRecord(iter_ty, iter_backing_ty, lens.items[lens.items.len - 1], done_step);

        index = backing_fields.len;
        while (index > start) {
            index -= 1;
            const item_expr = try self.addFieldAccessExpr(
                try self.localExpr(items_local, items_ty),
                backing_fields[index].name,
                field_handle_ty,
            );
            const step_expr = if (size_local) |local|
                try self.lowerFieldNamesSizeFilteredStep(
                    checked_source_ty,
                    source_expr_id,
                    index,
                    item_expr,
                    rest_expr,
                    step_fn_ty,
                    step_ret_ty,
                    local,
                    arg_tys[1],
                )
            else
                try self.lowerFieldNamesOneStep(
                    checked_source_ty,
                    source_expr_id,
                    index,
                    item_expr,
                    rest_expr,
                    step_fn_ty,
                    step_ret_ty,
                );
            rest_expr = try self.lowerGeneratedIterRecord(iter_ty, iter_backing_ty, lens.items[index - start], step_expr);
        }
        return rest_expr;
    }

    /// The iterator over `fields[start..]`, built as
    /// `lowerFieldNamesValueIterFromIndex` builds its own.
    fn lowerFieldNamesStaticIterFromIndex(
        self: *BodyContext,
        fields: []const Type.Field,
        start: usize,
        field_handle_ty: Type.TypeId,
        iter_ty: Type.TypeId,
        backing_ty: Type.TypeId,
        len_ty: Type.TypeId,
        step_fn_ty: Type.TypeId,
        step_ret_ty: Type.TypeId,
        checked_source_ty: checked.CheckedTypeId,
        source_expr_id: checked.CheckedExprId,
    ) Allocator.Error!DraftExprId {
        var lens: std.ArrayListUnmanaged(DraftExprId) = .empty;
        defer lens.deinit(self.allocator);
        var index = start;
        while (true) : (index += 1) {
            try lens.append(self.allocator, try self.lowerFieldNamesIterLen(fields.len - index, len_ty, .all));
            if (index == fields.len) break;
        }
        const done_step = try self.lowerFieldNamesDoneStep(checked_source_ty, source_expr_id, fields.len, .all, step_fn_ty, step_ret_ty);
        var rest_expr = try self.lowerGeneratedIterRecord(iter_ty, backing_ty, lens.items[lens.items.len - 1], done_step);

        index = fields.len;
        while (index > start) {
            index -= 1;
            const item_expr = try self.lowerRecordFieldHandle(field_handle_ty, fields[index], index);
            const step_expr = try self.lowerFieldNamesOneStep(
                checked_source_ty,
                source_expr_id,
                index,
                item_expr,
                rest_expr,
                step_fn_ty,
                step_ret_ty,
            );
            rest_expr = try self.lowerGeneratedIterRecord(iter_ty, backing_ty, lens.items[index - start], step_expr);
        }
        return rest_expr;
    }

    fn lowerFieldNamesForSizeIter(
        self: *BodyContext,
        fields: []const Type.Field,
        field_handle_ty: Type.TypeId,
        iter_ty: Type.TypeId,
        backing_ty: Type.TypeId,
        len_ty: Type.TypeId,
        step_fn_ty: Type.TypeId,
        step_ret_ty: Type.TypeId,
        size_local: DraftLocalId,
        size_ty: Type.TypeId,
        checked_source_ty: checked.CheckedTypeId,
        source_expr_id: checked.CheckedExprId,
    ) Allocator.Error!DraftExprId {
        var body = try self.lowerFieldNamesStaticIterForLen(
            fields,
            field_handle_ty,
            iter_ty,
            backing_ty,
            len_ty,
            step_fn_ty,
            step_ret_ty,
            checked_source_ty,
            source_expr_id,
            null,
        );

        var seen = std.ArrayList(usize).empty;
        defer seen.deinit(self.allocator);
        for (fields) |field| {
            const len = self.nameStore().recordFieldLabelText(field.name).len;
            var already_seen = false;
            for (seen.items) |seen_len| {
                if (seen_len == len) {
                    already_seen = true;
                    break;
                }
            }
            if (already_seen) continue;
            try seen.append(self.allocator, len);

            const bucket = try self.lowerFieldNamesStaticIterForLen(
                fields,
                field_handle_ty,
                iter_ty,
                backing_ty,
                len_ty,
                step_fn_ty,
                step_ret_ty,
                checked_source_ty,
                source_expr_id,
                len,
            );
            const size_expr = try self.localExpr(size_local, size_ty);
            const len_expr = try self.intLiteralExpr(@intCast(len), size_ty);
            const cond = try self.lowLevelExpr(.num_is_eq, &.{ size_expr, len_expr }, try self.primitiveType(.bool));
            body = try self.ifExpr(cond, bucket, body, iter_ty);
        }
        return body;
    }

    fn lowerFieldNamesStaticIterForLen(
        self: *BodyContext,
        fields: []const Type.Field,
        field_handle_ty: Type.TypeId,
        iter_ty: Type.TypeId,
        backing_ty: Type.TypeId,
        len_ty: Type.TypeId,
        step_fn_ty: Type.TypeId,
        step_ret_ty: Type.TypeId,
        checked_source_ty: checked.CheckedTypeId,
        source_expr_id: checked.CheckedExprId,
        target_len: ?usize,
    ) Allocator.Error!DraftExprId {
        return try self.lowerFieldNamesStaticFilteredIterFromIndex(
            fields,
            0,
            target_len,
            field_handle_ty,
            iter_ty,
            backing_ty,
            len_ty,
            step_fn_ty,
            step_ret_ty,
            checked_source_ty,
            source_expr_id,
        );
    }

    /// The iterator over the fields from `start_index` whose names have
    /// `target_len` bytes, built as `lowerFieldNamesValueIterFromIndex`
    /// builds its own.
    fn lowerFieldNamesStaticFilteredIterFromIndex(
        self: *BodyContext,
        fields: []const Type.Field,
        start_index: usize,
        target_len: ?usize,
        field_handle_ty: Type.TypeId,
        iter_ty: Type.TypeId,
        backing_ty: Type.TypeId,
        len_ty: Type.TypeId,
        step_fn_ty: Type.TypeId,
        step_ret_ty: Type.TypeId,
        checked_source_ty: checked.CheckedTypeId,
        source_expr_id: checked.CheckedExprId,
    ) Allocator.Error!DraftExprId {
        const Level = struct { index: usize, len: DraftExprId };
        var levels: std.ArrayListUnmanaged(Level) = .empty;
        defer levels.deinit(self.allocator);
        var remaining = self.countFieldNamesForLenFrom(fields, start_index, target_len);
        var scan = start_index;
        const done_start = while (true) {
            const len_expr = try self.lowerFieldNamesIterLen(remaining, len_ty, .all);
            const index = self.nextFieldIndexForLen(fields, scan, target_len) orelse {
                try levels.append(self.allocator, .{ .index = scan, .len = len_expr });
                break scan;
            };
            try levels.append(self.allocator, .{ .index = index, .len = len_expr });
            remaining -= 1;
            scan = index + 1;
        };
        const done_level = levels.pop().?;
        const done_step = try self.lowerFieldNamesDoneStep(checked_source_ty, source_expr_id, done_start, .all, step_fn_ty, step_ret_ty);
        var rest_expr = try self.lowerGeneratedIterRecord(iter_ty, backing_ty, done_level.len, done_step);

        while (levels.pop()) |level| {
            const item_expr = try self.lowerRecordFieldHandle(field_handle_ty, fields[level.index], level.index);
            const step_expr = try self.lowerFieldNamesOneStep(
                checked_source_ty,
                source_expr_id,
                level.index,
                item_expr,
                rest_expr,
                step_fn_ty,
                step_ret_ty,
            );
            rest_expr = try self.lowerGeneratedIterRecord(iter_ty, backing_ty, level.len, step_expr);
        }
        return rest_expr;
    }

    fn nextFieldIndexForLen(
        self: *BodyContext,
        fields: []const Type.Field,
        start_index: usize,
        target_len: ?usize,
    ) ?usize {
        var index = start_index;
        while (index < fields.len) : (index += 1) {
            if (target_len) |len| {
                if (self.nameStore().recordFieldLabelText(fields[index].name).len != len) continue;
            }
            return index;
        }
        return null;
    }

    fn countFieldNamesForLenFrom(
        self: *BodyContext,
        fields: []const Type.Field,
        start_index: usize,
        target_len: ?usize,
    ) usize {
        var count: usize = 0;
        for (fields[start_index..]) |field| {
            if (target_len) |len| {
                if (self.nameStore().recordFieldLabelText(field.name).len != len) continue;
            }
            count += 1;
        }
        return count;
    }

    fn lowerFieldNamesIterLen(
        self: *BodyContext,
        remaining: usize,
        ty: Type.TypeId,
        mode: FieldNamesIterMode,
    ) Allocator.Error!DraftExprId {
        const topology = try self.iteratorRepresentationNames(.iter);
        return switch (mode) {
            .all => try self.lowerGeneratedIterLenIfKnown(remaining, ty),
            .for_size => blk: {
                const unknown_tag = self.monoTagByName(ty, topology.unknown_tag);
                break :blk try self.addExpr(.{ .ty = ty, .data = .{ .tag = .{
                    .name = unknown_tag.name,
                    .payloads = .empty(),
                } } });
            },
        };
    }

    fn lowerFieldNamesDoneStep(
        self: *BodyContext,
        checked_source_ty: checked.CheckedTypeId,
        source_expr_id: checked.CheckedExprId,
        index: usize,
        mode: FieldNamesIterMode,
        step_fn_ty: Type.TypeId,
        step_ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const demand_scope = try self.enterCallableBodyDemandScope(&.{}, &.{});
        defer demand_scope.leave();
        const topology = try self.iteratorRepresentationNames(.iter);
        const done_tag = self.monoTagByName(step_ret_ty, topology.done_tag);
        const body = try self.addExpr(.{ .ty = step_ret_ty, .data = .{ .tag = .{
            .name = done_tag.name,
            .payloads = .empty(),
        } } });
        return try self.lowerFieldNamesStepLambda(checked_source_ty, source_expr_id, index, mode, step_fn_ty, body);
    }

    fn lowerFieldNamesOneStep(
        self: *BodyContext,
        checked_source_ty: checked.CheckedTypeId,
        source_expr_id: checked.CheckedExprId,
        index: usize,
        item_expr: DraftExprId,
        rest_expr: DraftExprId,
        step_fn_ty: Type.TypeId,
        step_ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const item_ty = try self.exprType(item_expr);
        const rest_ty = try self.exprType(rest_expr);
        const demand_scope = try self.enterCallableBodyDemandScope(&.{}, &.{ item_ty, rest_ty });
        defer demand_scope.leave();
        const topology = try self.iteratorRepresentationNames(.iter);
        const one_tag = self.monoTagByName(step_ret_ty, topology.one_tag);
        const one_payloads = self.typeStore().span(one_tag.payloads);
        if (one_payloads.len != 1) Common.invariant("Iter step One tag did not have one record payload");
        const one_payload = try self.lowerGeneratedIterOnePayload(GuardedList.at(one_payloads, 0), item_expr, rest_expr);
        const one_body = try self.addExpr(.{ .ty = step_ret_ty, .data = .{ .tag = .{
            .name = one_tag.name,
            .payloads = try self.addExprSpan(&[_]DraftExprId{one_payload}),
        } } });

        return try self.lowerFieldNamesStepLambda(checked_source_ty, source_expr_id, index, .all, step_fn_ty, one_body);
    }

    fn lowerFieldNamesSizeFilteredStep(
        self: *BodyContext,
        checked_source_ty: checked.CheckedTypeId,
        source_expr_id: checked.CheckedExprId,
        index: usize,
        item_expr: DraftExprId,
        rest_expr: DraftExprId,
        step_fn_ty: Type.TypeId,
        step_ret_ty: Type.TypeId,
        size_local: DraftLocalId,
        size_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const field_handle_ty = try self.exprType(item_expr);
        const rest_ty = try self.exprType(rest_expr);
        const demand_scope = try self.enterCallableBodyDemandScope(&.{}, &.{ field_handle_ty, rest_ty, size_ty });
        defer demand_scope.leave();
        const item_local = try self.addLocal(self.builder.symbols.fresh(), field_handle_ty);
        const item_local_expr = try self.localExpr(item_local, field_handle_ty);
        const topology = try self.iteratorRepresentationNames(.iter);

        const one_tag = self.monoTagByName(step_ret_ty, topology.one_tag);
        const one_payloads = self.typeStore().span(one_tag.payloads);
        if (one_payloads.len != 1) Common.invariant("Iter step One tag did not have one record payload");
        const one_payload = try self.lowerGeneratedIterOnePayload(GuardedList.at(one_payloads, 0), item_local_expr, rest_expr);
        const one_body = try self.addExpr(.{ .ty = step_ret_ty, .data = .{ .tag = .{
            .name = one_tag.name,
            .payloads = try self.addExprSpan(&[_]DraftExprId{one_payload}),
        } } });

        const skip_tag = self.monoTagByName(step_ret_ty, topology.skip_tag);
        const skip_payloads = self.typeStore().span(skip_tag.payloads);
        if (skip_payloads.len != 1) Common.invariant("Iter step Skip tag did not have one record payload");
        const skip_payload = try self.lowerGeneratedIterSkipPayload(GuardedList.at(skip_payloads, 0), rest_expr);
        const skip_body = try self.addExpr(.{ .ty = step_ret_ty, .data = .{ .tag = .{
            .name = skip_tag.name,
            .payloads = try self.addExprSpan(&[_]DraftExprId{skip_payload}),
        } } });

        const len_expr = try self.fieldNameLenFromLocal(item_local, field_handle_ty, size_ty);
        const cond = try self.lowLevelExpr(.num_is_eq, &.{
            len_expr,
            try self.localExpr(size_local, size_ty),
        }, try self.primitiveType(.bool));
        const body = try self.wrapLet(
            item_local,
            field_handle_ty,
            item_expr,
            try self.ifExpr(cond, one_body, skip_body, step_ret_ty),
            step_ret_ty,
        );
        return try self.lowerFieldNamesStepLambda(checked_source_ty, source_expr_id, index, .for_size, step_fn_ty, body);
    }

    fn lowerGeneratedIterRecord(
        self: *BodyContext,
        iter_ty: Type.TypeId,
        backing_ty: Type.TypeId,
        len_expr: DraftExprId,
        step_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const fields = self.typeStore().fieldSpan(self.recordFieldsSpan(backing_ty));
        const lowered = try self.allocator.alloc(DraftFieldExpr, fields.len);
        defer self.allocator.free(lowered);
        const topology = try self.iteratorRepresentationNames(.iter);

        for (0..GuardedList.borrowLen(fields)) |i| {
            const field = GuardedList.at(fields, i);
            lowered[i] = .{
                .name = field.name,
                .value = if (field.name == topology.len_field)
                    len_expr
                else if (field.name == topology.step_field)
                    step_expr
                else
                    Common.invariant("Iter backing record contained an unexpected field"),
            };
        }

        const record_expr = try self.addExpr(.{
            .ty = backing_ty,
            .data = .{ .record = try self.addFieldExprSpan(lowered) },
        });
        return try self.addExpr(.{
            .ty = iter_ty,
            .data = .{ .nominal = record_expr },
        });
    }

    fn lowerGeneratedIterLenIfKnown(
        self: *BodyContext,
        remaining: usize,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const topology = try self.iteratorRepresentationNames(.iter);
        const known_tag = self.monoTagByName(ty, topology.known_tag);
        const payloads = self.typeStore().span(known_tag.payloads);
        if (payloads.len != 1) Common.invariant("Iter.len_if_known Known tag did not have one payload");
        const count = try self.intLiteralExpr(@intCast(remaining), GuardedList.at(payloads, 0));
        return try self.addExpr(.{ .ty = ty, .data = .{ .tag = .{
            .name = known_tag.name,
            .payloads = try self.addExprSpan(&[_]DraftExprId{count}),
        } } });
    }

    fn lowerGeneratedIterOnePayload(
        self: *BodyContext,
        ty: Type.TypeId,
        item_expr: DraftExprId,
        rest_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const fields = self.typeStore().fieldSpan(self.recordFieldsSpan(ty));
        const lowered = try self.allocator.alloc(DraftFieldExpr, fields.len);
        defer self.allocator.free(lowered);
        const topology = try self.iteratorRepresentationNames(.iter);

        for (0..GuardedList.borrowLen(fields)) |i| {
            const field = GuardedList.at(fields, i);
            lowered[i] = .{
                .name = field.name,
                .value = if (field.name == topology.item_field)
                    item_expr
                else if (field.name == topology.rest_field)
                    rest_expr
                else
                    Common.invariant("Iter step One payload contained an unexpected field"),
            };
        }

        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .record = try self.addFieldExprSpan(lowered) },
        });
    }

    fn lowerGeneratedIterSkipPayload(
        self: *BodyContext,
        ty: Type.TypeId,
        rest_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const fields = self.typeStore().fieldSpan(self.recordFieldsSpan(ty));
        const lowered = try self.allocator.alloc(DraftFieldExpr, fields.len);
        defer self.allocator.free(lowered);
        const topology = try self.iteratorRepresentationNames(.iter);

        for (0..GuardedList.borrowLen(fields)) |i| {
            const field = GuardedList.at(fields, i);
            lowered[i] = .{
                .name = field.name,
                .value = if (field.name == topology.rest_field)
                    rest_expr
                else
                    Common.invariant("Iter step Skip payload contained an unexpected field"),
            };
        }

        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .record = try self.addFieldExprSpan(lowered) },
        });
    }

    fn fieldNameFromLocal(
        self: *BodyContext,
        field_local: DraftLocalId,
        field_ty: Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const backing_ty = self.namedBackingType(field_ty) orelse
            Common.invariant("Field.name argument had no backing type");
        const name_field = self.recordFieldByText(backing_ty, "name");
        if (!self.sameType(name_field.ty, ret_ty)) Common.invariant("Field.name backing name field differed from Str");

        const backing_local = try self.addLocal(self.builder.symbols.fresh(), backing_ty);
        const name_expr = try self.addFieldAccessExpr(
            try self.localExpr(backing_local, backing_ty),
            name_field.name,
            ret_ty,
        );
        const field_pat = try self.addPat(.{
            .ty = field_ty,
            .data = .{ .nominal = try self.bindPat(backing_local, backing_ty) },
        });
        const branch = DraftBranch{ .pat = field_pat, .body = name_expr };
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(field_local, field_ty),
            .branches = try self.addBranchSpan(&[_]DraftBranch{branch}),
        } } });
    }

    fn lowerFieldNamesStepLambda(
        self: *BodyContext,
        checked_source_ty: checked.CheckedTypeId,
        source_expr_id: checked.CheckedExprId,
        index: usize,
        mode: FieldNamesIterMode,
        step_fn_ty: Type.TypeId,
        body: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const fn_id = try self.addFn(.{
            .fn_def = .{ .checked_generated = self.owner_template },
            .source_fn_ty = checked_source_ty,
            .source_fn_key = generatedFieldNamesIterStepKey(self.current_fn_key, source_expr_id, index, mode),
            .mono_fn_ty = step_fn_ty,
        });
        return try self.addExpr(.{ .ty = step_fn_ty, .data = .{ .lambda = .{
            .fn_id = .{ .draft = fn_id },
            .args = try self.addTypedLocalSpan(&.{}),
            .body = body,
        } } });
    }

    fn lowerRecordFieldHandle(
        self: *BodyContext,
        field_handle_ty: Type.TypeId,
        record_field: Type.Field,
        index: usize,
    ) Allocator.Error!DraftExprId {
        const str_ty = try self.primitiveType(.str);
        const field_text = self.nameStore().recordFieldLabelText(record_field.name);
        return try self.lowerRecordFieldHandleWithName(
            field_handle_ty,
            try self.stringExpr(field_text, str_ty),
            try self.intLiteralExpr(@intCast(field_text.len), try self.primitiveType(.u64)),
            index,
        );
    }

    fn lowerRecordFieldHandleWithName(
        self: *BodyContext,
        field_handle_ty: Type.TypeId,
        name_expr: DraftExprId,
        name_len_expr: DraftExprId,
        index: usize,
    ) Allocator.Error!DraftExprId {
        const backing_ty = self.namedBackingType(field_handle_ty) orelse
            Common.invariant("generated Field handle expected a named backing type");
        const fields = self.typeStore().fieldSpan(self.recordFieldsSpan(backing_ty));
        const lowered = try self.allocator.alloc(DraftFieldExpr, fields.len);
        defer self.allocator.free(lowered);

        var saw_name = false;
        var saw_index = false;
        var saw_name_len = false;
        for (0..GuardedList.borrowLen(fields)) |i| {
            const field = GuardedList.at(fields, i);
            const label = self.nameStore().recordFieldLabelText(field.name);
            lowered[i] = .{
                .name = field.name,
                .value = if (Ident.textEql(label, "name")) blk: {
                    saw_name = true;
                    if (!self.typeHasBuiltinOwner(field.ty, .str)) Common.invariant("Field backing name was not Str");
                    break :blk name_expr;
                } else if (Ident.textEql(label, "index")) blk: {
                    saw_index = true;
                    if (!self.typeHasBuiltinOwner(field.ty, .u64)) Common.invariant("Field backing index was not U64");
                    break :blk try self.intLiteralExpr(@intCast(index), field.ty);
                } else if (Ident.textEql(label, "name_len")) blk: {
                    saw_name_len = true;
                    if (!self.typeHasBuiltinOwner(field.ty, .u64)) Common.invariant("Field backing name_len was not U64");
                    break :blk name_len_expr;
                } else {
                    Common.invariant("Field backing record contained an unexpected field");
                },
            };
        }
        if (!saw_name or !saw_index or !saw_name_len) Common.invariant("Field backing record did not contain name, index, and name_len");

        const backing_expr = try self.addExpr(.{
            .ty = backing_ty,
            .data = .{ .record = try self.addFieldExprSpan(lowered) },
        });
        return try self.addExpr(.{
            .ty = field_handle_ty,
            .data = .{ .nominal = backing_expr },
        });
    }

    fn fieldsShapeType(self: *BodyContext, fields_ty: Type.TypeId) Type.TypeId {
        if (!self.typeHasBuiltinOwner(fields_ty, .fields)) Common.invariant("expected FieldNames(_shape) type");
        return switch (self.typeStore().get(fields_ty)) {
            .named => |named| blk: {
                const args = self.typeStore().span(named.args);
                if (args.len != 1) Common.invariant("FieldNames nominal did not have one type argument");
                break :blk GuardedList.at(args, 0);
            },
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("FieldNames value was not a named type"),
        };
    }

    fn recordFieldsForShape(self: *BodyContext, shape_ty: Type.TypeId) TypeFieldSpanBorrow {
        return switch (self.shapeContent(shape_ty)) {
            .record => |span| self.typeStore().fieldSpan(span),
            .zst => self.typeStore().fieldSpan(.empty()),
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased => Common.invariant("FieldNames metadata requested for a non-record shape"),
        };
    }

    fn dupeRecordFieldsForShape(self: *BodyContext, shape_ty: Type.TypeId) Allocator.Error![]Type.Field {
        return try GuardedList.dupe(self.allocator, Type.Field, self.recordFieldsForShape(shape_ty));
    }

    fn parserRecordFieldRank(
        self: *BodyContext,
        fields: []const Type.Field,
        field_index: usize,
    ) usize {
        if (field_index >= fields.len) Common.invariant("parser field capture requested for a missing record field");
        const target = self.nameStore().recordFieldLabelText(fields[field_index].name);
        var rank: usize = 0;
        for (fields, 0..) |field, index| {
            if (index == field_index) continue;
            const name = self.nameStore().recordFieldLabelText(field.name);
            if (std.mem.order(u8, name, target) == .lt) rank += 1;
        }
        return rank;
    }

    fn parserFieldCaptureIdForRecordField(
        self: *BodyContext,
        fields: []const Type.Field,
        field_index: usize,
        base_capture_id: usize,
    ) u32 {
        const capture_id = base_capture_id + self.parserRecordFieldRank(fields, field_index);
        if (capture_id > std.math.maxInt(u32)) Common.invariant("parser generated too many field captures");
        return @intCast(capture_id);
    }

    fn appendParserPrecomputedCaptures(
        self: *BodyContext,
        plan: *ParserPrecomputedPlan,
        fields: []const Type.Field,
        renamed_field_locals: []const DraftLocalId,
        renamed_field_values: []const DraftExprId,
    ) Allocator.Error!void {
        if (fields.len != renamed_field_locals.len or fields.len != renamed_field_values.len) {
            Common.invariant("parser precomputed capture arity differed from record field count");
        }

        var rank: usize = 0;
        while (rank < fields.len) : (rank += 1) {
            for (fields, 0..) |_, index| {
                if (self.parserRecordFieldRank(fields, index) != rank) continue;
                try plan.captures.append(self.allocator, .{
                    .local = renamed_field_locals[index],
                    .value = renamed_field_values[index],
                });
                break;
            } else {
                Common.invariant("parser record field rank was missing from field set");
            }
        }
    }

    fn buildParserConstructionPrecomputedPlan(
        self: *BodyContext,
        plan: *ParserPrecomputedPlan,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        str_ty: Type.TypeId,
    ) Allocator.Error!void {
        // Record plan entries intentionally share renamed fields by field-name
        // set. Track concrete types separately so that sharing cannot truncate
        // traversal of a distinct record shape's children.
        var seen_types = collections.DenseMap(Type.TypeId, void).init(self.allocator);
        defer seen_types.deinit();

        try self.buildParserConstructionPrecomputedPlanVisit(
            plan,
            &seen_types,
            shape_ty,
            encoding_expr,
            encoding_ty,
            str_ty,
        );
    }

    /// A pending type of a codec shape walk. A `field_payload` is a record
    /// field's type, whose encoded payload type is read when the walk
    /// reaches it.
    const CodecShapeStep = union(enum) {
        ty: Type.TypeId,
        field_payload: Type.TypeId,
    };

    /// Push `shape_ty`'s component types so they pop in source order.
    fn pushCodecShapeComponents(
        self: *BodyContext,
        pending: *std.ArrayList(CodecShapeStep),
        shape_ty: Type.TypeId,
        comptime record_field: std.meta.Tag(CodecShapeStep),
    ) Allocator.Error!void {
        const start = pending.items.len;
        switch (self.shapeContent(shape_ty)) {
            .list => |elem_ty| try pending.append(self.allocator, .{ .ty = elem_ty }),
            .box => |payload_ty| try pending.append(self.allocator, .{ .ty = payload_ty }),
            .tuple => |span| {
                const item_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(span));
                defer self.allocator.free(item_tys);
                for (item_tys) |elem_ty| try pending.append(self.allocator, .{ .ty = elem_ty });
            },
            .record, .zst => {
                const fields = try self.dupeRecordFieldsForShape(shape_ty);
                defer self.allocator.free(fields);
                for (fields) |field| try pending.append(self.allocator, @unionInit(CodecShapeStep, @tagName(record_field), field.ty));
            },
            .tag_union => |span| {
                const tags = try GuardedList.dupe(self.allocator, Type.Tag, self.typeStore().tagSpan(span));
                defer self.allocator.free(tags);
                for (tags) |tag| {
                    const payload_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(tag.payloads));
                    defer self.allocator.free(payload_tys);
                    for (payload_tys) |payload_ty| try pending.append(self.allocator, .{ .ty = payload_ty });
                }
            },
            .primitive, .named, .func, .erased => {},
        }
        std.mem.reverse(CodecShapeStep, pending.items[start..]);
    }

    /// Push a dict's codec shapes so they pop in order.
    fn pushDictCodecShapes(self: *BodyContext, pending: *std.ArrayList(CodecShapeStep), dict: DictEntryShape) Allocator.Error!void {
        var dict_buf: [2]Type.TypeId = undefined;
        const dict_shapes = self.dictCodecShapes(dict, &dict_buf);
        var index = dict_shapes.len;
        while (index > 0) {
            index -= 1;
            try pending.append(self.allocator, .{ .ty = dict_shapes[index] });
        }
    }

    fn buildParserConstructionPrecomputedPlanVisit(
        self: *BodyContext,
        plan: *ParserPrecomputedPlan,
        seen_types: *collections.DenseMap(Type.TypeId, void),
        root_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        str_ty: Type.TypeId,
    ) Allocator.Error!void {
        var pending = std.ArrayList(CodecShapeStep).empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, .{ .ty = root_ty });
        while (pending.pop()) |step| {
            const shape_ty = step.ty;
            if (seen_types.contains(shape_ty)) continue;
            try seen_types.put(shape_ty, {});

            if (self.tryNullInfo(shape_ty)) |info| {
                try pending.append(self.allocator, .{ .ty = info.ok_payload_ty });
                continue;
            }
            if (try self.missingTryInfo(shape_ty)) |info| {
                try pending.append(self.allocator, .{ .ty = info.ok_ty });
                continue;
            }
            if (self.optionalFieldSlot(shape_ty)) |slot| {
                try pending.append(self.allocator, .{ .ty = slot.payload_ty });
                continue;
            }
            if (self.frozenCustomCodecCallForShape(.parser, shape_ty) != null) continue;
            if (self.scalarCodecMethodName(shape_ty, "parse_") != null) continue;
            if (self.setPayloadType(shape_ty)) |payload_ty| {
                try pending.append(self.allocator, .{ .ty = payload_ty });
                continue;
            }
            if (self.dictEntryShape(shape_ty)) |dict| {
                try self.pushDictCodecShapes(&pending, dict);
                continue;
            }
            switch (self.shapeContent(shape_ty)) {
                .record, .zst => try self.buildConstructionRecordPrecomputedPlan(.parser, plan, shape_ty, encoding_expr, encoding_ty, str_ty),
                .list, .box, .tuple, .tag_union, .primitive, .named, .func, .erased => {},
            }
            try self.pushCodecShapeComponents(&pending, shape_ty, .ty);
        }
    }

    fn buildEncodeConstructionPrecomputedPlan(
        self: *BodyContext,
        plan: *ParserPrecomputedPlan,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        str_ty: Type.TypeId,
    ) Allocator.Error!void {
        // A recursive nominal reaches its own shape again inside its backing;
        // that shape's plan entries are already being recorded.
        var seen_types = collections.DenseMap(Type.TypeId, void).init(self.allocator);
        defer seen_types.deinit();
        try self.buildEncodeConstructionPrecomputedPlanVisit(plan, &seen_types, shape_ty, encoding_expr, encoding_ty, str_ty);
    }

    fn buildEncodeConstructionPrecomputedPlanVisit(
        self: *BodyContext,
        plan: *ParserPrecomputedPlan,
        seen_types: *collections.DenseMap(Type.TypeId, void),
        root_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        str_ty: Type.TypeId,
    ) Allocator.Error!void {
        var pending = std.ArrayList(CodecShapeStep).empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, .{ .ty = root_ty });
        while (pending.pop()) |step| {
            const shape_ty = switch (step) {
                .ty => |ty| ty,
                .field_payload => |field_ty| try self.encodeRecordFieldPayloadType(field_ty),
            };
            if (seen_types.contains(shape_ty)) continue;
            try seen_types.put(shape_ty, {});

            if (self.tryNullInfo(shape_ty)) |info| {
                try pending.append(self.allocator, .{ .ty = info.ok_payload_ty });
                continue;
            }
            if (self.frozenCustomCodecCallForShape(.encoder, shape_ty) != null) continue;
            if (self.scalarCodecMethodName(shape_ty, "encode_") != null) continue;
            if (self.setPayloadType(shape_ty)) |payload_ty| {
                try pending.append(self.allocator, .{ .ty = payload_ty });
                continue;
            }
            if (self.dictEntryShape(shape_ty)) |dict| {
                try self.pushDictCodecShapes(&pending, dict);
                continue;
            }
            switch (self.shapeContent(shape_ty)) {
                .record, .zst => try self.buildConstructionRecordPrecomputedPlan(.encoder, plan, shape_ty, encoding_expr, encoding_ty, str_ty),
                .list, .box, .tuple, .tag_union, .primitive, .named, .func, .erased => {},
            }
            try self.pushCodecShapeComponents(&pending, shape_ty, .field_payload);
        }
    }

    fn buildEncodeRestoredPrecomputedPlan(
        self: *BodyContext,
        plan: *ParserPrecomputedPlan,
        fn_value: check.ConstStore.ConstFn,
        store_view: ModuleView,
        fn_view: ModuleView,
        shape_ty: Type.TypeId,
        encoding_ty: Type.TypeId,
        str_ty: Type.TypeId,
    ) Allocator.Error!void {
        // A recursive nominal reaches its own shape again inside its backing;
        // that shape's plan entries are already being recorded.
        var seen_types = collections.DenseMap(Type.TypeId, void).init(self.allocator);
        defer seen_types.deinit();
        try self.buildEncodeRestoredPrecomputedPlanVisit(plan, &seen_types, fn_value, store_view, fn_view, shape_ty, encoding_ty, str_ty);
    }

    fn buildEncodeRestoredPrecomputedPlanVisit(
        self: *BodyContext,
        plan: *ParserPrecomputedPlan,
        seen_types: *collections.DenseMap(Type.TypeId, void),
        fn_value: check.ConstStore.ConstFn,
        store_view: ModuleView,
        fn_view: ModuleView,
        shape_ty: Type.TypeId,
        encoding_ty: Type.TypeId,
        str_ty: Type.TypeId,
    ) Allocator.Error!void {
        if (seen_types.contains(shape_ty)) return;
        try seen_types.put(shape_ty, {});

        if (self.tryNullInfo(shape_ty)) |info| {
            return try self.buildEncodeRestoredPrecomputedPlanVisit(plan, seen_types, fn_value, store_view, fn_view, info.ok_payload_ty, encoding_ty, str_ty);
        }
        if (self.frozenCustomCodecCallForShape(.encoder, shape_ty) != null) return;
        if (self.scalarCodecMethodName(shape_ty, "encode_") != null) return;
        if (self.setPayloadType(shape_ty)) |payload_ty| {
            return try self.buildEncodeRestoredPrecomputedPlanVisit(plan, seen_types, fn_value, store_view, fn_view, payload_ty, encoding_ty, str_ty);
        }
        if (self.dictEntryShape(shape_ty)) |dict| {
            var dict_buf: [2]Type.TypeId = undefined;
            for (self.dictCodecShapes(dict, &dict_buf)) |dict_shape| {
                try self.buildEncodeRestoredPrecomputedPlanVisit(plan, seen_types, fn_value, store_view, fn_view, dict_shape, encoding_ty, str_ty);
            }
            return;
        }

        switch (self.shapeContent(shape_ty)) {
            .list => |elem_ty| try self.buildEncodeRestoredPrecomputedPlanVisit(plan, seen_types, fn_value, store_view, fn_view, elem_ty, encoding_ty, str_ty),
            .box => |payload_ty| try self.buildEncodeRestoredPrecomputedPlanVisit(plan, seen_types, fn_value, store_view, fn_view, payload_ty, encoding_ty, str_ty),
            .tuple => |span| {
                const item_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(span));
                defer self.allocator.free(item_tys);
                for (item_tys) |elem_ty| {
                    try self.buildEncodeRestoredPrecomputedPlanVisit(plan, seen_types, fn_value, store_view, fn_view, elem_ty, encoding_ty, str_ty);
                }
            },
            .record, .zst => {
                try self.buildEncodeRestoredRecordPrecomputedPlan(plan, fn_value, store_view, fn_view, shape_ty, str_ty);
                const fields = try self.dupeRecordFieldsForShape(shape_ty);
                defer self.allocator.free(fields);
                for (fields) |field| {
                    try self.buildEncodeRestoredPrecomputedPlanVisit(plan, seen_types, fn_value, store_view, fn_view, try self.encodeRecordFieldPayloadType(field.ty), encoding_ty, str_ty);
                }
            },
            .tag_union => |span| {
                const tags = try GuardedList.dupe(self.allocator, Type.Tag, self.typeStore().tagSpan(span));
                defer self.allocator.free(tags);
                for (tags) |tag| {
                    const payload_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(tag.payloads));
                    defer self.allocator.free(payload_tys);
                    for (payload_tys) |payload_ty| {
                        try self.buildEncodeRestoredPrecomputedPlanVisit(plan, seen_types, fn_value, store_view, fn_view, payload_ty, encoding_ty, str_ty);
                    }
                }
            },
            .primitive, .named, .func, .erased => {},
        }
    }

    fn buildEncodeRestoredRecordPrecomputedPlan(
        self: *BodyContext,
        plan: *ParserPrecomputedPlan,
        fn_value: check.ConstStore.ConstFn,
        store_view: ModuleView,
        fn_view: ModuleView,
        shape_ty: Type.TypeId,
        str_ty: Type.TypeId,
    ) Allocator.Error!void {
        if (self.parserPlanContains(plan, shape_ty)) return;

        const fields = try self.dupeRecordFieldsForShape(shape_ty);
        defer self.allocator.free(fields);
        const locals = try self.allocator.alloc(DraftLocalId, fields.len);
        const values = try self.allocator.alloc(DraftExprId, fields.len);
        var inserted = false;
        errdefer if (!inserted) {
            self.allocator.free(locals);
            self.allocator.free(values);
        };

        const base_capture_id = plan.next_capture_id;
        plan.next_capture_id += fields.len;
        if (plan.next_capture_id > std.math.maxInt(u32)) Common.invariant("encoder_for generated too many captures");

        for (fields, 0..) |_, index| {
            const capture_id = self.parserFieldCaptureIdForRecordField(fields, index, base_capture_id);
            const node = constGeneratedCaptureNode(fn_value, capture_id) orelse
                Common.invariant("stored encoder_for runtime function was missing a renamed field capture");
            locals[index] = try self.addLocal(self.builder.symbols.fresh(), str_ty);
            self.setLocalCaptureId(locals[index], capture_id);
            values[index] = try self.restoreConstNodeAtType(store_view, fn_view, node, str_ty);
        }

        try self.parserPlanPut(plan, shape_ty, .{
            .renamed_field_locals = locals,
            .renamed_field_values = values,
            .renamed_field_lengths = null,
            .renamed_field_texts = null,
        });
        inserted = true;

        try self.appendParserPrecomputedCaptures(plan, fields, locals, values);
    }

    fn buildConstructionRecordPrecomputedPlan(
        self: *BodyContext,
        comptime kind: CodecKind,
        plan: *ParserPrecomputedPlan,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        str_ty: Type.TypeId,
    ) Allocator.Error!void {
        if (self.parserPlanContains(plan, shape_ty)) return;

        const fields = try self.dupeRecordFieldsForShape(shape_ty);
        defer self.allocator.free(fields);
        const locals = try self.allocator.alloc(DraftLocalId, fields.len);
        const values = try self.allocator.alloc(DraftExprId, fields.len);
        var inserted = false;
        errdefer if (!inserted) {
            self.allocator.free(locals);
            self.allocator.free(values);
        };

        const base_capture_id = plan.next_capture_id;
        plan.next_capture_id += fields.len;
        if (plan.next_capture_id > std.math.maxInt(u32)) Common.invariant(switch (kind) {
            .parser => "parser generated too many captures",
            .encoder => "encoder_for generated too many captures",
        });

        for (fields, 0..) |field, index| {
            locals[index] = try self.addLocal(self.builder.symbols.fresh(), str_ty);
            self.setLocalCaptureId(
                locals[index],
                self.parserFieldCaptureIdForRecordField(fields, index, base_capture_id),
            );
            values[index] = try self.renamedRecordFieldNameExpr(kind, encoding_expr, encoding_ty, field, str_ty);
        }

        try self.parserPlanPut(plan, shape_ty, .{
            .renamed_field_locals = locals,
            .renamed_field_values = values,
            .renamed_field_lengths = null,
            .renamed_field_texts = null,
        });
        inserted = true;

        try self.appendParserPrecomputedCaptures(plan, fields, locals, values);
    }

    fn buildParserRestoredPrecomputedPlan(
        self: *BodyContext,
        plan: *ParserPrecomputedPlan,
        fn_value: check.ConstStore.ConstFn,
        store_view: ModuleView,
        fn_view: ModuleView,
        shape_ty: Type.TypeId,
        str_ty: Type.TypeId,
    ) Allocator.Error!void {
        // Restoration must walk concrete types independently from the shared
        // field-name entries for the same reason as construction above.
        var seen_types = collections.DenseMap(Type.TypeId, void).init(self.allocator);
        defer seen_types.deinit();

        try self.buildParserRestoredPrecomputedPlanVisit(
            plan,
            &seen_types,
            fn_value,
            store_view,
            fn_view,
            shape_ty,
            str_ty,
        );
    }

    fn buildParserRestoredPrecomputedPlanVisit(
        self: *BodyContext,
        plan: *ParserPrecomputedPlan,
        seen_types: *collections.DenseMap(Type.TypeId, void),
        fn_value: check.ConstStore.ConstFn,
        store_view: ModuleView,
        fn_view: ModuleView,
        shape_ty: Type.TypeId,
        str_ty: Type.TypeId,
    ) Allocator.Error!void {
        if (seen_types.contains(shape_ty)) return;
        try seen_types.put(shape_ty, {});

        if (self.tryNullInfo(shape_ty)) |info| {
            return try self.buildParserRestoredPrecomputedPlanVisit(plan, seen_types, fn_value, store_view, fn_view, info.ok_payload_ty, str_ty);
        }
        if (self.frozenCustomCodecCallForShape(.parser, shape_ty) != null) return;
        if (self.scalarCodecMethodName(shape_ty, "parse_") != null) return;
        if (self.setPayloadType(shape_ty)) |payload_ty| {
            return try self.buildParserRestoredPrecomputedPlanVisit(plan, seen_types, fn_value, store_view, fn_view, payload_ty, str_ty);
        }
        if (self.dictEntryShape(shape_ty)) |dict| {
            var dict_buf: [2]Type.TypeId = undefined;
            for (self.dictCodecShapes(dict, &dict_buf)) |dict_shape| {
                try self.buildParserRestoredPrecomputedPlanVisit(plan, seen_types, fn_value, store_view, fn_view, dict_shape, str_ty);
            }
            return;
        }

        switch (self.shapeContent(shape_ty)) {
            .list => |elem_ty| try self.buildParserRestoredPrecomputedPlanVisit(plan, seen_types, fn_value, store_view, fn_view, elem_ty, str_ty),
            .box => |payload_ty| try self.buildParserRestoredPrecomputedPlanVisit(plan, seen_types, fn_value, store_view, fn_view, payload_ty, str_ty),
            .tuple => |span| {
                const item_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(span));
                defer self.allocator.free(item_tys);
                for (item_tys) |elem_ty| {
                    try self.buildParserRestoredPrecomputedPlanVisit(plan, seen_types, fn_value, store_view, fn_view, elem_ty, str_ty);
                }
            },
            .record, .zst => {
                try self.buildParserRestoredRecordPrecomputedPlan(plan, fn_value, store_view, fn_view, shape_ty, str_ty);
                const fields = try self.dupeRecordFieldsForShape(shape_ty);
                defer self.allocator.free(fields);
                for (fields) |field| {
                    try self.buildParserRestoredPrecomputedPlanVisit(plan, seen_types, fn_value, store_view, fn_view, field.ty, str_ty);
                }
            },
            .tag_union => |span| {
                const tags = try GuardedList.dupe(self.allocator, Type.Tag, self.typeStore().tagSpan(span));
                defer self.allocator.free(tags);
                for (tags) |tag| {
                    const payload_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(tag.payloads));
                    defer self.allocator.free(payload_tys);
                    for (payload_tys) |payload_ty| {
                        try self.buildParserRestoredPrecomputedPlanVisit(plan, seen_types, fn_value, store_view, fn_view, payload_ty, str_ty);
                    }
                }
            },
            .primitive, .named, .func, .erased => {},
        }
    }

    fn parserPrecomputedRecordShapesForTagUnion(
        self: *BodyContext,
        plan: ?*const ParserPrecomputedPlan,
        union_ty: Type.TypeId,
    ) Allocator.Error![]Type.TypeId {
        var shapes = std.ArrayList(Type.TypeId).empty;
        errdefer shapes.deinit(self.allocator);
        var seen = collections.DenseMap(Type.TypeId, void).init(self.allocator);
        defer seen.deinit();

        try self.appendParserPrecomputedRecordShapes(plan, &shapes, &seen, union_ty);
        return try shapes.toOwnedSlice(self.allocator);
    }

    fn appendParserPrecomputedRecordShapes(
        self: *BodyContext,
        plan: ?*const ParserPrecomputedPlan,
        shapes: *std.ArrayList(Type.TypeId),
        seen: *collections.DenseMap(Type.TypeId, void),
        root_ty: Type.TypeId,
    ) Allocator.Error!void {
        var pending = std.ArrayList(CodecShapeStep).empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, .{ .ty = root_ty });
        while (pending.pop()) |step| {
            const shape_ty = step.ty;
            if (self.tryNullInfo(shape_ty)) |info| {
                try pending.append(self.allocator, .{ .ty = info.ok_payload_ty });
                continue;
            }
            if (self.frozenCustomCodecCallForShape(.parser, shape_ty) != null) continue;
            if (self.scalarCodecMethodName(shape_ty, "parse_") != null) continue;
            if (self.setPayloadType(shape_ty)) |payload_ty| {
                try pending.append(self.allocator, .{ .ty = payload_ty });
                continue;
            }
            if (self.dictEntryShape(shape_ty)) |dict| {
                try self.pushDictCodecShapes(&pending, dict);
                continue;
            }

            if (seen.contains(shape_ty)) continue;
            try seen.put(shape_ty, {});

            switch (self.shapeContent(shape_ty)) {
                .record, .zst => if (plan == null or self.parserPlanContains(plan.?, shape_ty)) {
                    try shapes.append(self.allocator, shape_ty);
                },
                .list, .box, .tuple, .tag_union, .primitive, .named, .func, .erased => {},
            }
            try self.pushCodecShapeComponents(&pending, shape_ty, .ty);
        }
    }

    fn generatedParseTagUnionSpecBackingRecordFieldName(
        self: *BodyContext,
        index: usize,
    ) Allocator.Error!names.RecordFieldNameId {
        const label = try std.fmt.allocPrint(self.allocator, "record_{d:0>20}", .{index});
        defer self.allocator.free(label);
        return try self.nameStoreMut().internRecordFieldLabel(label);
    }

    fn generatedParseTagUnionSpecBackingFieldName(
        self: *BodyContext,
        index: usize,
    ) Allocator.Error!names.RecordFieldNameId {
        const label = try std.fmt.allocPrint(self.allocator, "field_{d:0>20}", .{index});
        defer self.allocator.free(label);
        return try self.nameStoreMut().internRecordFieldLabel(label);
    }

    fn lowerParseTagUnionSpecValue(
        self: *BodyContext,
        spec_ty: Type.TypeId,
        spec_backing_ty: Type.TypeId,
        record_shapes: []const Type.TypeId,
        plan: *const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const str_ty = try self.primitiveType(.str);
        const backing_fields = try GuardedList.dupe(self.allocator, Type.Field, self.typeStore().fieldSpan(self.recordFieldsSpan(spec_backing_ty)));
        defer self.allocator.free(backing_fields);
        if (backing_fields.len != record_shapes.len) Common.invariant("generated tag-union spec backing arity differed from record shape count");

        const outer_values = try self.allocator.alloc(DraftFieldExpr, record_shapes.len);
        defer self.allocator.free(outer_values);

        for (record_shapes, backing_fields, 0..) |record_shape, backing_field, record_index| {
            const precomputed = self.parserPlanGet(plan, record_shape) orelse
                Common.invariant("generated tag-union spec requested missing parser precomputed record");
            const inner_fields = try GuardedList.dupe(self.allocator, Type.Field, self.typeStore().fieldSpan(self.recordFieldsSpan(backing_field.ty)));
            defer self.allocator.free(inner_fields);
            if (inner_fields.len != precomputed.renamed_field_locals.len) {
                Common.invariant("generated tag-union spec record arity differed from precomputed record");
            }

            const inner_values = try self.allocator.alloc(DraftFieldExpr, inner_fields.len);
            defer self.allocator.free(inner_values);
            for (inner_fields, precomputed.renamed_field_locals, 0..) |inner_field, renamed_local, field_index| {
                inner_values[field_index] = .{
                    .name = inner_field.name,
                    .value = try self.localExpr(renamed_local, str_ty),
                };
            }

            outer_values[record_index] = .{
                .name = backing_field.name,
                .value = try self.addExpr(.{
                    .ty = backing_field.ty,
                    .data = .{ .record = try self.addFieldExprSpan(inner_values) },
                }),
            };
        }

        const backing_expr = try self.addExpr(.{
            .ty = spec_backing_ty,
            .data = .{ .record = try self.addFieldExprSpan(outer_values) },
        });
        return try self.addExpr(.{
            .ty = spec_ty,
            .data = .{ .nominal = backing_expr },
        });
    }

    fn buildParserPrecomputedPlanFromTagUnionSpec(
        self: *BodyContext,
        plan: *ParserPrecomputedPlan,
        spec_backing_local: DraftLocalId,
        spec_backing_ty: Type.TypeId,
        union_ty: Type.TypeId,
    ) Allocator.Error!void {
        const record_shapes = try self.parserPrecomputedRecordShapesForTagUnion(null, union_ty);
        defer self.allocator.free(record_shapes);

        const backing_fields = try GuardedList.dupe(self.allocator, Type.Field, self.typeStore().fieldSpan(self.recordFieldsSpan(spec_backing_ty)));
        defer self.allocator.free(backing_fields);
        if (backing_fields.len != record_shapes.len) {
            Common.invariant("generated tag-union spec backing arity differed from payload record shape count");
        }

        const str_ty = try self.primitiveType(.str);
        for (record_shapes, backing_fields) |record_shape, backing_field| {
            if (self.parserPlanContains(plan, record_shape)) continue;

            const record_fields = try self.dupeRecordFieldsForShape(record_shape);
            defer self.allocator.free(record_fields);
            const backing_record_fields = try GuardedList.dupe(self.allocator, Type.Field, self.typeStore().fieldSpan(self.recordFieldsSpan(backing_field.ty)));
            defer self.allocator.free(backing_record_fields);
            if (backing_record_fields.len != record_fields.len) {
                Common.invariant("generated tag-union spec record arity differed from payload record arity");
            }

            const locals = try self.allocator.alloc(DraftLocalId, record_fields.len);
            const values = try self.allocator.alloc(DraftExprId, record_fields.len);
            var inserted = false;
            errdefer if (!inserted) {
                self.allocator.free(locals);
                self.allocator.free(values);
            };

            const record_expr = try self.addFieldAccessExpr(
                try self.localExpr(spec_backing_local, spec_backing_ty),
                backing_field.name,
                backing_field.ty,
            );

            for (backing_record_fields, 0..) |field, index| {
                if (!self.sameType(field.ty, str_ty)) {
                    Common.invariant("generated tag-union spec field name value was not Str");
                }
                locals[index] = try self.addLocal(self.builder.symbols.fresh(), str_ty);
                values[index] = try self.addFieldAccessExpr(record_expr, field.name, str_ty);
            }

            try self.parserPlanPut(plan, record_shape, .{
                .renamed_field_locals = locals,
                .renamed_field_values = values,
                .renamed_field_lengths = null,
                .renamed_field_texts = null,
            });
            inserted = true;

            try self.appendParserPrecomputedCaptures(plan, record_fields, locals, values);
        }
    }

    fn buildParserRestoredRecordPrecomputedPlan(
        self: *BodyContext,
        plan: *ParserPrecomputedPlan,
        fn_value: check.ConstStore.ConstFn,
        store_view: ModuleView,
        fn_view: ModuleView,
        shape_ty: Type.TypeId,
        str_ty: Type.TypeId,
    ) Allocator.Error!void {
        if (self.parserPlanContains(plan, shape_ty)) return;

        const fields = try self.dupeRecordFieldsForShape(shape_ty);
        defer self.allocator.free(fields);
        const locals = try self.allocator.alloc(DraftLocalId, fields.len);
        const values = try self.allocator.alloc(DraftExprId, fields.len);
        const lengths = try self.allocator.alloc(u32, fields.len);
        const texts = try self.allocator.alloc([]const u8, fields.len);
        var inserted = false;
        errdefer if (!inserted) {
            self.allocator.free(locals);
            self.allocator.free(values);
            self.allocator.free(lengths);
            self.allocator.free(texts);
        };

        const base_capture_id = plan.next_capture_id;
        plan.next_capture_id += fields.len;
        if (plan.next_capture_id > std.math.maxInt(u32)) Common.invariant("parser generated too many captures");

        for (fields, 0..) |_, index| {
            const capture_id = self.parserFieldCaptureIdForRecordField(fields, index, base_capture_id);
            const node = constGeneratedCaptureNode(fn_value, capture_id) orelse
                Common.invariant("stored parser runtime function was missing a renamed field capture");
            locals[index] = try self.addLocal(self.builder.symbols.fresh(), str_ty);
            self.setLocalCaptureId(locals[index], capture_id);
            values[index] = try self.restoreConstNodeAtType(store_view, fn_view, node, str_ty);
            lengths[index] = constStrNodeByteLen(store_view, node);
            texts[index] = constStrNodeBytes(store_view, node);
        }

        try self.parserPlanPut(plan, shape_ty, .{
            .renamed_field_locals = locals,
            .renamed_field_values = values,
            .renamed_field_lengths = lengths,
            .renamed_field_texts = texts,
        });
        inserted = true;

        try self.appendParserPrecomputedCaptures(plan, fields, locals, values);
    }

    fn lowerParseShapeFromState(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        // A nominal opaque with a scalar backing and no custom parser (e.g. `Username := Str`)
        // parses its backing scalar, then rewraps the value in the nominal.
        if (self.nominalExprBackingType(shape_ty)) |backing_ty| {
            if (self.scalarCodecMethodName(backing_ty, "parse_") != null) {
                return try self.lowerParseNominalScalarFromState(shape_ty, backing_ty, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan);
            }
        }
        const selected = self.parseShapeSelection(shape_ty);
        if (Ident.textEql(selected.tag_text, "Record")) {
            const precomputed = if (precomputed_plan) |plan| self.parserPlanGet(plan, shape_ty) else null;
            return try self.lowerParseRecordFromState(
                shape_ty,
                encoding_expr,
                encoding_ty,
                state_expr,
                state_ty,
                ret_ty,
                precomputed_plan,
                if (precomputed) |record| record.renamed_field_locals else null,
                if (precomputed) |record| record.renamed_field_lengths else null,
                if (precomputed) |record| record.renamed_field_texts else null,
            );
        }

        const method_name: []const u8 =
            if (Ident.textEql(selected.tag_text, "TagUnion"))
                "parse_tag_union"
            else
                selected.tag_text;

        const prepared = try self.frozenFormatCodecCallForShape(.parser, method_name, shape_ty);
        const parse_lookup = prepared.lookup;
        const parse_mono_ty = prepared.callable_ty;
        const parse_fn = self.functionShape(parse_mono_ty, "parser target method was not a function");
        const parse_arg_tys = self.typeStore().span(parse_fn.args);
        if (!Ident.textEql(selected.tag_text, "TagUnion")) {
            if (parse_arg_tys.len != 2) Common.invariant("parser target scalar method had an unexpected arity");
            if (!self.sameType(GuardedList.at(parse_arg_tys, 0), encoding_ty)) Common.invariant("parser target encoding type differed from input encoding type");
            if (!self.sameType(GuardedList.at(parse_arg_tys, 1), state_ty)) Common.invariant("parser target state type differed from input state type");

            const parse_args = [_]DraftExprId{ encoding_expr, state_expr };
            const result = try self.addExpr(.{
                .ty = parse_fn.ret,
                .data = .{ .call_proc = .{
                    .callee = draftProcCalleeForSlot(prepared.callee),
                    .args = try self.addExprSpan(&parse_args),
                    .captures = try self.methodTargetCaptureSpan(parse_lookup),
                } },
            });
            return try self.injectTryErrorRow(result, parse_fn.ret, ret_ty);
        }
        if (parse_arg_tys.len != 3) Common.invariant("parser target tag-union method had an unexpected arity");
        if (!self.sameType(GuardedList.at(parse_arg_tys, 0), encoding_ty)) Common.invariant("parser target tag-union encoding type differed from input encoding type");
        if (!self.sameType(GuardedList.at(parse_arg_tys, 2), state_ty)) Common.invariant("parser target tag-union state type differed from input state type");

        const record_shapes = if (precomputed_plan) |plan|
            try self.parserPrecomputedRecordShapesForTagUnion(plan, shape_ty)
        else
            &.{};
        defer if (precomputed_plan != null) self.allocator.free(record_shapes);

        const callable_mono_ty = parse_mono_ty;
        const callable_fn = self.functionShape(callable_mono_ty, "parser target tag-union method was not a function");
        const callable_arg_tys = self.typeStore().span(callable_fn.args);
        if (callable_arg_tys.len != 3) Common.invariant("parser target tag-union method had an unexpected arity");
        const spec_ty = GuardedList.at(callable_arg_tys, 1);
        if (!self.sameType(GuardedList.at(callable_arg_tys, 0), encoding_ty)) Common.invariant("parser target tag-union encoding type differed from generated input encoding type");
        if (!self.sameType(GuardedList.at(callable_arg_tys, 1), spec_ty)) Common.invariant("parser target tag-union spec type differed from generated spec type");
        if (!self.sameType(GuardedList.at(callable_arg_tys, 2), state_ty)) Common.invariant("parser target tag-union state type differed from generated input state type");

        const final_spec_expr = blk: {
            const plan = precomputed_plan orelse Common.invariant("generated tag-union spec requested without a precomputed plan");
            const spec_backing_ty = self.namedBackingType(spec_ty) orelse
                Common.invariant("generated tag-union spec had no backing type");
            break :blk try self.lowerParseTagUnionSpecValue(spec_ty, spec_backing_ty, record_shapes, plan);
        };
        const result = try self.addExpr(.{
            .ty = callable_fn.ret,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(prepared.callee),
                .args = try self.addExprSpan(&[_]DraftExprId{ encoding_expr, final_spec_expr, state_expr }),
                .captures = try self.methodTargetCaptureSpan(parse_lookup),
            } },
        });
        if (self.nominalConstructionLayer(shape_ty) != null) {
            const source_info = self.tryInfo(callable_fn.ret);
            const value_name = try self.nameStoreMut().internRecordFieldLabel("value");
            const rest_name = try self.nameStoreMut().internRecordFieldLabel("rest");
            const source_value_ty = self.recordFieldType(source_info.ok_ty, value_name);
            if (!self.sameType(self.recordFieldType(source_info.ok_ty, rest_name), state_ty)) {
                Common.invariant("tag-union parser result changed the state type");
            }
            const value_local = try self.addLocal(self.builder.symbols.fresh(), source_value_ty);
            const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
            const value = try self.wrapParsedTagUnionValue(
                try self.localExpr(value_local, source_value_ty),
                source_value_ty,
                shape_ty,
            );
            const ok_body = try self.parseResultOk(ret_ty, value, try self.localExpr(rest_local, state_ty), state_ty);
            return try self.sequenceTryRecord(result, callable_fn.ret, value_local, value_name, rest_local, rest_name, ok_body, ret_ty);
        }
        return try self.injectTryErrorRow(result, callable_fn.ret, ret_ty);
    }

    /// A format method may return the structural tag union backing the
    /// checked nominal shape. Construct each declared nominal layer explicitly.
    fn wrapParsedTagUnionValue(
        self: *BodyContext,
        value: DraftExprId,
        source_ty: Type.TypeId,
        target_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        // Nominal layers can nest through a chain of declarations, so they
        // are collected before wrapping from the innermost out.
        var named_tys = std.ArrayList(Type.TypeId).empty;
        defer named_tys.deinit(self.allocator);
        var current = target_ty;
        while (!self.sameType(source_ty, current)) {
            const layer = self.nominalConstructionLayer(current) orelse
                Common.invariant("tag-union parser value differed from its checked nominal backing");
            try named_tys.append(self.allocator, layer.named);
            current = layer.backing;
        }
        var wrapped = value;
        var index = named_tys.items.len;
        while (index > 0) {
            index -= 1;
            wrapped = try self.addExpr(.{ .ty = named_tys.items[index], .data = .{ .nominal = wrapped } });
        }
        return wrapped;
    }

    fn lowerParseNominalScalarFromState(
        self: *BodyContext,
        nominal_ty: Type.TypeId,
        backing_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const backing_parse_ok_ty = try self.parseResultOkType(backing_ty, state_ty);
        const backing_parse_ret_ty = try self.tryTypeLike(ret_ty, backing_parse_ok_ty, ret_info.err_ty);
        const backing_parse = try self.lowerParseShapeHelperCall(
            backing_ty,
            encoding_expr,
            encoding_ty,
            state_expr,
            state_ty,
            backing_parse_ret_ty,
            precomputed_plan,
        );

        const value_name = try self.nameStoreMut().internRecordFieldLabel("value");
        const rest_name = try self.nameStoreMut().internRecordFieldLabel("rest");
        const backing_local = try self.addLocal(self.builder.symbols.fresh(), backing_ty);
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const nominal_value = try self.addExpr(.{
            .ty = nominal_ty,
            .data = .{ .nominal = try self.localExpr(backing_local, backing_ty) },
        });
        const ok_body = try self.parseResultOk(ret_ty, nominal_value, try self.localExpr(rest_local, state_ty), state_ty);
        return try self.sequenceTryRecord(backing_parse, backing_parse_ret_ty, backing_local, value_name, rest_local, rest_name, ok_body, ret_ty);
    }

    fn lowerParseRecordFromState(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
        precomputed_renamed_field_locals: ?[]const DraftLocalId,
        precomputed_renamed_field_lengths: ?[]const u32,
        precomputed_renamed_field_texts: ?[][]const u8,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const parse_ok_ty = try self.parseResultOkType(shape_ty, state_ty);
        if (!self.sameType(ret_info.ok_ty, parse_ok_ty)) Common.invariant("record parser return Ok type differed from generated parse result");

        const record_fields = try GuardedList.dupe(self.allocator, Type.Field, switch (self.shapeContent(shape_ty)) {
            .record => |span| self.typeStore().fieldSpan(span),
            .zst => self.typeStore().fieldSpan(.empty()),
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased => Common.invariant("record parser requested for a non-record shape"),
        });
        defer self.allocator.free(record_fields);

        const u64_ty = try self.primitiveType(.u64);
        const presence_word_count = recordPresenceWordCount(record_fields.len);
        const presence_locals = try self.allocator.alloc(DraftLocalId, presence_word_count);
        defer self.allocator.free(presence_locals);
        const presence_tys = try self.allocator.alloc(Type.TypeId, presence_word_count);
        defer self.allocator.free(presence_tys);
        const initial_presence_values = try self.allocator.alloc(DraftExprId, presence_word_count);
        defer self.allocator.free(initial_presence_values);
        for (presence_locals, 0..) |*local, index| {
            local.* = try self.addLocal(self.builder.symbols.fresh(), u64_ty);
            presence_tys[index] = u64_ty;
            initial_presence_values[index] = try self.intLiteralExpr(0, u64_ty);
        }

        const payload_locals = try self.allocator.alloc(DraftLocalId, record_fields.len);
        defer self.allocator.free(payload_locals);
        const payload_tys = try self.allocator.alloc(Type.TypeId, record_fields.len);
        defer self.allocator.free(payload_tys);
        const initial_payload_values = try self.allocator.alloc(DraftExprId, record_fields.len);
        defer self.allocator.free(initial_payload_values);
        for (record_fields, 0..) |field, index| {
            payload_tys[index] = field.ty;
            payload_locals[index] = try self.addLocal(self.builder.symbols.fresh(), field.ty);
            initial_payload_values[index] = try self.uninitializedPayloadExpr(
                field.ty,
                presence_locals[recordPresenceWordIndex(index)],
                recordPresenceMask(index),
            );
        }
        const record_slots = ParseRecordSlots{
            .presence_locals = presence_locals,
            .presence_tys = presence_tys,
            .payload_locals = payload_locals,
            .payload_tys = payload_tys,
        };

        const prepared = try self.frozenFormatCodecCallForShape(.parser, "parse_record_field", shape_ty);
        const parse_lookup = prepared.lookup;
        const callable_mono_ty = prepared.callable_ty;
        const parse_fn = self.functionShape(callable_mono_ty, "parse_record_field target method was not a function");
        const parse_arg_tys = self.typeStore().span(parse_fn.args);
        if (parse_arg_tys.len != 3) Common.invariant("parse_record_field target method had an unexpected arity");
        if (!self.sameType(GuardedList.at(parse_arg_tys, 0), encoding_ty)) Common.invariant("parse_record_field encoding type differed from input encoding type");
        if (!self.sameType(GuardedList.at(parse_arg_tys, 2), state_ty)) Common.invariant("parse_record_field state type differed from input state type");
        const fields_ty = GuardedList.at(parse_arg_tys, 1);
        const step_try_ty = parse_fn.ret;
        const step_try_info = self.tryInfo(step_try_ty);
        const event_ty = step_try_info.ok_ty;
        const field_handle_ty = try self.recordEventFieldHandleTemplate(event_ty);
        const fields_backing_ty = self.namedBackingType(fields_ty) orelse
            Common.invariant("prepared parse_record_field field set had no backing type");

        const str_ty = try self.primitiveType(.str);
        var owned_renamed_field_locals: ?[]DraftLocalId = null;
        defer if (owned_renamed_field_locals) |locals| self.allocator.free(locals);
        var owned_renamed_field_values: ?[]DraftExprId = null;
        defer if (owned_renamed_field_values) |values| self.allocator.free(values);

        const renamed_field_locals = if (precomputed_renamed_field_locals) |locals| blk: {
            if (locals.len != record_fields.len) Common.invariant("precomputed renamed field arity differed from record field count");
            break :blk locals;
        } else blk: {
            const locals = try self.allocator.alloc(DraftLocalId, record_fields.len);
            const values = try self.allocator.alloc(DraftExprId, record_fields.len);
            owned_renamed_field_locals = locals;
            owned_renamed_field_values = values;

            for (record_fields, 0..) |field, index| {
                locals[index] = try self.addLocal(self.builder.symbols.fresh(), str_ty);
                values[index] = try self.renamedRecordFieldNameExpr(.parser, encoding_expr, encoding_ty, field, str_ty);
            }

            break :blk locals;
        };
        const renamed_field_lengths = if (precomputed_renamed_field_lengths) |lengths| blk: {
            if (lengths.len != record_fields.len) Common.invariant("precomputed renamed field length arity differed from record field count");
            break :blk lengths;
        } else null;
        const renamed_field_texts = if (precomputed_renamed_field_texts) |texts| blk: {
            if (texts.len != record_fields.len) Common.invariant("precomputed renamed field text arity differed from record field count");
            break :blk texts;
        } else null;

        const cursor_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const bool_ty = try self.primitiveType(.bool);
        const ctl = RecordLoopCtl{
            .done_local = try self.addLocal(self.builder.symbols.fresh(), bool_ty),
            .counted_local = try self.addLocal(self.builder.symbols.fresh(), bool_ty),
            .remaining_local = try self.addLocal(self.builder.symbols.fresh(), u64_ty),
            .bool_ty = bool_ty,
            .u64_ty = u64_ty,
        };

        const error_join = try self.reserveGeneratedJoinPoint(ret_ty);
        const entry_end_join = try self.reserveGeneratedJoinPoint(ret_ty);
        const entry_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const skip_join = try self.reserveGeneratedJoinPoint(ret_ty);
        const skip_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const field_joins = try self.allocator.alloc(DraftExprId, record_fields.len);
        defer self.allocator.free(field_joins);
        const field_state_locals = try self.allocator.alloc(DraftLocalId, record_fields.len);
        defer self.allocator.free(field_state_locals);
        for (field_joins, field_state_locals) |*join, *local| {
            join.* = try self.reserveGeneratedJoinPoint(ret_ty);
            local.* = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        }
        const continuations = ParseRecordContinuations{
            .error_join = error_join,
            .entry_end_join = entry_end_join,
            .skip_join = skip_join,
            .field_joins = field_joins,
        };

        const fields_expr = try self.lowerFieldNamesValue(fields_ty, fields_backing_ty, field_handle_ty, renamed_field_locals, renamed_field_lengths);
        const fields_local = try self.addLocal(self.builder.symbols.fresh(), fields_ty);
        const parser_retained = try self.allocator.alloc(
            BodyTypedLocal,
            1 + renamed_field_locals.len + record_slots.payload_locals.len,
        );
        defer self.allocator.free(parser_retained);
        var retained_index: usize = 0;
        parser_retained[retained_index] = .{ .local = fields_local, .ty = fields_ty };
        retained_index += 1;
        for (renamed_field_locals) |local| {
            parser_retained[retained_index] = .{ .local = local, .ty = str_ty };
            retained_index += 1;
        }
        for (record_slots.payload_locals, record_slots.payload_tys) |local, ty| {
            parser_retained[retained_index] = .{ .local = local, .ty = ty };
            retained_index += 1;
        }
        if (retained_index != parser_retained.len) Common.invariant("record parser retained local count differed");

        const step_expr = try self.addExpr(.{
            .ty = step_try_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(prepared.callee),
                .args = try self.addExprSpan(&[_]DraftExprId{
                    encoding_expr,
                    try self.localExpr(fields_local, fields_ty),
                    try self.localExpr(cursor_local, state_ty),
                }),
                .captures = try self.methodTargetCaptureSpan(parse_lookup),
            } },
        });

        const event_local = try self.addLocal(self.builder.symbols.fresh(), event_ty);
        const event_body = try self.lowerParseRecordEvent(
            state_ty,
            ret_ty,
            record_slots,
            ctl,
            continuations,
            renamed_field_locals,
            renamed_field_lengths,
            renamed_field_texts,
            event_local,
            event_ty,
        );
        const step_body = try self.sequenceTryTo(step_expr, step_try_ty, event_local, event_body, ret_ty, error_join);

        const remaining_is_zero = try self.lowLevelExpr(.num_is_eq, &.{
            try self.localExpr(ctl.remaining_local, u64_ty),
            try self.intLiteralExpr(0, u64_ty),
        }, bool_ty);
        const counted_finished = try self.ifExpr(
            try self.localExpr(ctl.counted_local, bool_ty),
            remaining_is_zero,
            try self.boolLiteral(false, bool_ty),
            bool_ty,
        );
        const finish_cond = try self.ifExpr(
            try self.localExpr(ctl.done_local, bool_ty),
            try self.boolLiteral(true, bool_ty),
            counted_finished,
            bool_ty,
        );
        const finish_body = try self.lowerParseRecordFinish(
            shape_ty,
            state_ty,
            ret_ty,
            record_slots,
            renamed_field_locals,
            try self.localExpr(cursor_local, state_ty),
            error_join,
        );
        var loop_body = try self.ifExpr(finish_cond, finish_body, step_body, ret_ty);

        var field_index = record_fields.len;
        while (field_index > 0) {
            field_index -= 1;
            const field_body = try self.lowerParseMatchedRecordFieldNext(
                record_fields[field_index],
                field_index,
                encoding_expr,
                encoding_ty,
                state_ty,
                record_slots,
                precomputed_plan,
                field_state_locals[field_index],
                ret_ty,
                entry_end_join,
                error_join,
            );
            try self.completeGeneratedJoinPoint(
                field_joins[field_index],
                &.{.{ .local = field_state_locals[field_index], .ty = state_ty }},
                &.{},
                field_body,
                loop_body,
            );
            loop_body = field_joins[field_index];
        }

        const skip_body = try self.lowerSkipRecordFieldNext(
            encoding_expr,
            encoding_ty,
            state_ty,
            ret_ty,
            skip_state_local,
            entry_end_join,
            error_join,
        );
        try self.completeGeneratedJoinPoint(
            skip_join,
            &.{.{ .local = skip_state_local, .ty = state_ty }},
            &.{},
            skip_body,
            loop_body,
        );
        loop_body = skip_join;

        const entry_end_body = try self.lowerParseRecordEntryEnd(
            shape_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            ret_ty,
            entry_state_local,
            record_slots,
            ctl,
            error_join,
        );
        try self.completeGeneratedJoinPoint(
            entry_end_join,
            &.{.{ .local = entry_state_local, .ty = state_ty }},
            parser_retained,
            entry_end_body,
            loop_body,
        );
        loop_body = entry_end_join;

        const error_local = try self.addLocal(self.builder.symbols.fresh(), ret_info.err_ty);
        const error_body = try self.tryErr(ret_ty, try self.localExpr(error_local, ret_info.err_ty));
        try self.completeGeneratedJoinPoint(
            error_join,
            &.{.{ .local = error_local, .ty = ret_info.err_ty }},
            parser_retained,
            error_body,
            loop_body,
        );
        loop_body = error_join;

        const params = try self.allocator.alloc(BodyTypedLocal, record_loop_slot_offset + record_slots.payload_locals.len + record_slots.presence_locals.len);
        defer self.allocator.free(params);
        params[0] = .{ .local = cursor_local, .ty = state_ty };
        params[1] = .{ .local = ctl.done_local, .ty = bool_ty };
        params[2] = .{ .local = ctl.counted_local, .ty = bool_ty };
        params[3] = .{ .local = ctl.remaining_local, .ty = u64_ty };
        // Payloads must be carried before presence words. LIR lowers continue
        // arguments into ordered `set_local` statements; ARC inserts cleanup of
        // the old payload immediately before the payload write, and that cleanup
        // must test the old presence bit, not the just-updated one.
        const payload_param_offset = record_loop_slot_offset;
        for (record_slots.payload_locals, record_slots.payload_tys, 0..) |local, ty, index| {
            params[payload_param_offset + index] = .{ .local = local, .ty = ty };
        }
        const presence_param_offset = payload_param_offset + record_slots.payload_locals.len;
        for (record_slots.presence_locals, record_slots.presence_tys, 0..) |local, ty, index| {
            params[presence_param_offset + index] = .{ .local = local, .ty = ty };
        }

        const start_event_ty = try self.parseCountedStartEventType(state_ty);
        const start_try_ty = try self.tryTypeLike(ret_ty, start_event_ty, ret_info.err_ty);
        const start_try = try self.lowerParseFormatMethod(
            "parse_record_start",
            &.{ encoding_expr, state_expr },
            &.{ encoding_ty, state_ty },
            shape_ty,
            start_try_ty,
        );
        const start_event_local = try self.addLocal(self.builder.symbols.fresh(), start_event_ty);

        const start_init = try self.lowerParseCountedStartInit(start_event_local, start_event_ty, state_ty, bool_ty, u64_ty, "record parse Counted start event");
        const init_ty = start_init.ty;
        const init_expr = start_init.expr;
        const init_local = start_init.local;

        const initial_values = try self.allocator.alloc(DraftExprId, record_loop_slot_offset + initial_payload_values.len + initial_presence_values.len);
        defer self.allocator.free(initial_values);
        initial_values[0] = try self.recordPayloadFieldAccess(init_local, init_ty, "cursor");
        initial_values[1] = try self.boolLiteral(false, bool_ty);
        initial_values[2] = try self.recordPayloadFieldAccess(init_local, init_ty, "counted");
        initial_values[3] = try self.recordPayloadFieldAccess(init_local, init_ty, "remaining");
        @memcpy(initial_values[record_loop_slot_offset .. record_loop_slot_offset + initial_payload_values.len], initial_payload_values);
        @memcpy(initial_values[record_loop_slot_offset + initial_payload_values.len ..], initial_presence_values);
        var loop_expr = try self.addExpr(.{ .ty = ret_ty, .data = .{ .loop_ = .{
            .params = try self.addTypedLocalSpan(params),
            .initial_values = try self.addExprSpan(initial_values),
            .body = loop_body,
        } } });
        loop_expr = try self.wrapLet(init_local, init_ty, init_expr, loop_expr, ret_ty);
        loop_expr = try self.sequenceTry(start_try, start_try_ty, start_event_local, loop_expr, ret_ty);
        loop_expr = try self.wrapLet(fields_local, fields_ty, fields_expr, loop_expr, ret_ty);
        if (owned_renamed_field_values) |renamed_field_values| {
            var index = renamed_field_locals.len;
            while (index > 0) {
                index -= 1;
                loop_expr = try self.wrapLet(renamed_field_locals[index], str_ty, renamed_field_values[index], loop_expr, ret_ty);
            }
        }
        return loop_expr;
    }

    fn lowerParseRecordEvent(
        self: *BodyContext,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        record_slots: ParseRecordSlots,
        ctl: RecordLoopCtl,
        continuations: ParseRecordContinuations,
        renamed_field_locals: []const DraftLocalId,
        renamed_field_lengths: ?[]const u32,
        renamed_field_texts: ?[]const []const u8,
        event_local: DraftLocalId,
        event_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const continue_tag = self.monoTagByText(event_ty, "Continue");
        const done_tag = self.monoTagByText(event_ty, "Done");
        const field_tag = self.monoTagByText(event_ty, "Field");
        const try_field_tag = self.monoTagByText(event_ty, "TryField");
        const try_field_caseless_tag = self.monoTagByText(event_ty, "TryFieldCaseless");
        const field_payload_ty = self.singleTagPayloadType(field_tag, "record parse Field event");
        const try_field_payload_ty = self.singleTagPayloadType(try_field_tag, "record parse TryField event");
        const try_field_caseless_payload_ty = self.singleTagPayloadType(try_field_caseless_tag, "record parse TryFieldCaseless event");

        const continue_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const continue_state_pat = try self.bindPat(continue_state_local, state_ty);
        const continue_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = continue_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{continue_state_pat}),
        } } });
        const continue_body = try self.lowerParseRecordContinueEvent(
            state_ty,
            ret_ty,
            record_slots,
            ctl,
            continue_state_local,
        );

        const done_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const done_state_pat = try self.bindPat(done_state_local, state_ty);
        const done_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = done_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{done_state_pat}),
        } } });
        const done_body = try self.lowerParseRecordDoneEvent(
            state_ty,
            ret_ty,
            record_slots,
            ctl,
            done_state_local,
        );

        const field_payload_local = try self.addLocal(self.builder.symbols.fresh(), field_payload_ty);
        const field_payload_pat = try self.bindPat(field_payload_local, field_payload_ty);
        const field_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = field_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{field_payload_pat}),
        } } });
        const field_body = try self.lowerParseRecordDirectFieldEvent(
            state_ty,
            ret_ty,
            continuations,
            field_payload_local,
            field_payload_ty,
        );

        const try_field_payload_local = try self.addLocal(self.builder.symbols.fresh(), try_field_payload_ty);
        const try_field_payload_pat = try self.bindPat(try_field_payload_local, try_field_payload_ty);
        const try_field_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = try_field_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{try_field_payload_pat}),
        } } });
        const try_field_body = try self.lowerParseRecordNamedFieldEvent(
            state_ty,
            ret_ty,
            continuations,
            renamed_field_locals,
            renamed_field_lengths,
            renamed_field_texts,
            try_field_payload_local,
            try_field_payload_ty,
            .exact,
        );

        const try_field_caseless_payload_local = try self.addLocal(self.builder.symbols.fresh(), try_field_caseless_payload_ty);
        const try_field_caseless_payload_pat = try self.bindPat(try_field_caseless_payload_local, try_field_caseless_payload_ty);
        const try_field_caseless_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = try_field_caseless_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{try_field_caseless_payload_pat}),
        } } });
        const try_field_caseless_body = try self.lowerParseRecordNamedFieldEvent(
            state_ty,
            ret_ty,
            continuations,
            renamed_field_locals,
            renamed_field_lengths,
            renamed_field_texts,
            try_field_caseless_payload_local,
            try_field_caseless_payload_ty,
            .caseless,
        );

        const branches = [_]DraftBranch{
            .{ .pat = continue_pat, .body = continue_body },
            .{ .pat = done_pat, .body = done_body },
            .{ .pat = field_pat, .body = field_body },
            .{ .pat = try_field_pat, .body = try_field_body },
            .{ .pat = try_field_caseless_pat, .body = try_field_caseless_body },
        };
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(event_local, event_ty),
            .branches = try self.addBranchSpan(&branches),
        } } });
    }

    fn lowerParseRecordNamedDispatchBody(
        self: *BodyContext,
        key_local: DraftLocalId,
        key_ty: Type.TypeId,
        renamed_field_locals: []const DraftLocalId,
        renamed_field_lengths: ?[]const u32,
        renamed_field_texts: ?[]const []const u8,
        matched_bodies: []const DraftExprId,
        unknown_body: DraftExprId,
        mode: RecordFieldMatchMode,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        if (renamed_field_locals.len != matched_bodies.len) Common.invariant("record parser dispatch arity did not match renamed fields");
        if (renamed_field_lengths) |lengths| {
            if (lengths.len != renamed_field_locals.len) Common.invariant("record parser dispatch length arity did not match renamed fields");
            return try self.lowerParseRecordLengthBucketedDispatchBody(
                key_local,
                key_ty,
                renamed_field_locals,
                lengths,
                renamed_field_texts,
                matched_bodies,
                unknown_body,
                mode,
                ret_ty,
            );
        }
        var body = unknown_body;
        var index = matched_bodies.len;
        while (index > 0) {
            index -= 1;
            const renamed_field_expr = try self.localExpr(renamed_field_locals[index], key_ty);
            const cond = try self.recordFieldNameMatch(
                key_local,
                key_ty,
                renamed_field_expr,
                if (renamed_field_texts) |texts| texts[index] else null,
                mode,
            );
            body = try self.ifExpr(cond, matched_bodies[index], body, ret_ty);
        }
        return body;
    }

    fn lowerParseRecordLengthBucketedDispatchBody(
        self: *BodyContext,
        key_local: DraftLocalId,
        key_ty: Type.TypeId,
        renamed_field_locals: []const DraftLocalId,
        renamed_field_lengths: []const u32,
        renamed_field_texts: ?[]const []const u8,
        matched_bodies: []const DraftExprId,
        unknown_body: DraftExprId,
        mode: RecordFieldMatchMode,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const u64_ty = try self.primitiveType(.u64);
        const bool_ty = try self.primitiveType(.bool);
        const key_len_local = try self.addLocal(self.builder.symbols.fresh(), u64_ty);

        var body = unknown_body;
        var index = matched_bodies.len;
        while (index > 0) {
            index -= 1;
            const length = renamed_field_lengths[index];
            if (fieldLengthAlreadyHandled(renamed_field_lengths, index, length)) continue;
            const static_lane: ?StaticFieldLane = if ((mode == .exact or mode == .caseless) and length <= 24)
                if (renamed_field_texts) |texts| selectStaticFieldLane(renamed_field_lengths, texts, length) else null
            else
                null;

            var group_body = unknown_body;
            var field_index = matched_bodies.len;
            while (field_index > 0) {
                field_index -= 1;
                if (renamed_field_lengths[field_index] != length) continue;

                const renamed_field_expr = try self.localExpr(renamed_field_locals[field_index], key_ty);
                if (static_lane) |lane| {
                    const texts = renamed_field_texts orelse Common.invariant("static field lane requested without field text");
                    const field_text = texts[field_index];
                    const probe = switch (mode) {
                        .direct => Common.invariant("direct field handles do not use string matching"),
                        .exact => try self.recordFieldNameStaticSmallWordMatch(false, key_local, key_ty, field_text, lane.offset, lane.active_len),
                        .caseless => try self.recordFieldNameStaticSmallWordMatch(true, key_local, key_ty, field_text, lane.offset, lane.active_len),
                    };
                    const matched_or_next = if (lane.offset == 0 and lane.active_len == length)
                        matched_bodies[field_index]
                    else blk: {
                        const full_cond = switch (mode) {
                            .direct => Common.invariant("direct field handles do not use string matching"),
                            .exact => try self.recordFieldNameStaticSmallExactMatch(key_local, key_ty, field_text),
                            .caseless => try self.recordFieldNameStaticSmallCaselessMatch(key_local, key_ty, field_text),
                        };
                        break :blk try self.ifExpr(full_cond, matched_bodies[field_index], group_body, ret_ty);
                    };
                    group_body = try self.ifExpr(probe, matched_or_next, group_body, ret_ty);
                } else {
                    const cond = try self.recordFieldNameMatch(
                        key_local,
                        key_ty,
                        renamed_field_expr,
                        if (renamed_field_texts) |texts| texts[field_index] else null,
                        mode,
                    );
                    group_body = try self.ifExpr(cond, matched_bodies[field_index], group_body, ret_ty);
                }
            }

            const key_len_expr = try self.localExpr(key_len_local, u64_ty);
            const length_expr = try self.intLiteralExpr(length, u64_ty);
            const length_matches = try self.lowLevelExpr(.num_is_eq, &.{ key_len_expr, length_expr }, bool_ty);
            body = try self.ifExpr(length_matches, group_body, body, ret_ty);
        }

        const key_expr = try self.localExpr(key_local, key_ty);
        const key_len_expr = try self.lowLevelExpr(.str_count_utf8_bytes, &.{key_expr}, u64_ty);
        return try self.wrapLet(key_len_local, u64_ty, key_len_expr, body, ret_ty);
    }

    fn continueRecordLoop(
        self: *BodyContext,
        ret_ty: Type.TypeId,
        cursor_expr: DraftExprId,
        done_expr: DraftExprId,
        remaining_expr: DraftExprId,
        record_slots: ParseRecordSlots,
        ctl: RecordLoopCtl,
    ) Allocator.Error!DraftExprId {
        const values = try self.allocator.alloc(DraftExprId, record_loop_slot_offset + record_slots.payload_locals.len + record_slots.presence_locals.len);
        defer self.allocator.free(values);
        values[0] = cursor_expr;
        values[1] = done_expr;
        values[2] = try self.localExpr(ctl.counted_local, ctl.bool_ty);
        values[3] = remaining_expr;
        // Keep this order in sync with `lowerParseRecordFromState`: ARC cleanup
        // of the old slot must see the old presence word before the new value is
        // marked present.
        const payload_offset = record_loop_slot_offset;
        for (record_slots.payload_locals, record_slots.payload_tys, 0..) |local, ty, index| {
            values[payload_offset + index] = try self.localExpr(local, ty);
        }
        const presence_offset = payload_offset + record_slots.payload_locals.len;
        for (record_slots.presence_locals, record_slots.presence_tys, 0..) |local, ty, index| {
            values[presence_offset + index] = try self.localExpr(local, ty);
        }
        return try self.continueWith(.{ .sealed = ret_ty }, values);
    }

    /// After a record entry (matched field, skipped field) has been consumed:
    /// in Counted mode decrement `remaining` and re-enter the loop directly;
    /// otherwise ask `parse_record_after_field` whether more entries follow.
    fn lowerParseRecordEntryEnd(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        entry_state_local: DraftLocalId,
        record_slots: ParseRecordSlots,
        ctl: RecordLoopCtl,
        error_join: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const false_expr = try self.boolLiteral(false, ctl.bool_ty);
        const remaining_minus_one = try self.lowLevelExpr(.num_int_sub_wrap, &.{
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            try self.intLiteralExpr(1, ctl.u64_ty),
        }, ctl.u64_ty);
        const counted_body = try self.continueRecordLoop(
            ret_ty,
            try self.localExpr(entry_state_local, state_ty),
            false_expr,
            remaining_minus_one,
            record_slots,
            ctl,
        );

        const after_event_ty = try self.parseArrayEventType(state_ty, "Continue", "Done");
        const after_try_ty = try self.tryTypeLike(ret_ty, after_event_ty, ret_info.err_ty);
        const after_try = try self.lowerParseFormatMethod(
            "parse_record_after_field",
            &.{ encoding_expr, try self.localExpr(entry_state_local, state_ty) },
            &.{ encoding_ty, state_ty },
            shape_ty,
            after_try_ty,
        );
        const after_event_local = try self.addLocal(self.builder.symbols.fresh(), after_event_ty);
        const remaining_expr = try self.localExpr(ctl.remaining_local, ctl.u64_ty);

        const continue_tag = self.monoTagByText(after_event_ty, "Continue");
        const continue_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const continue_state_pat = try self.bindPat(continue_state_local, state_ty);
        const continue_pat = try self.addPat(.{ .ty = after_event_ty, .data = .{ .tag = .{
            .name = continue_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{continue_state_pat}),
        } } });
        const continue_body = try self.continueRecordLoop(
            ret_ty,
            try self.localExpr(continue_state_local, state_ty),
            try self.boolLiteral(false, ctl.bool_ty),
            remaining_expr,
            record_slots,
            ctl,
        );

        const done_tag = self.monoTagByText(after_event_ty, "Done");
        const done_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const done_state_pat = try self.bindPat(done_state_local, state_ty);
        const done_pat = try self.addPat(.{ .ty = after_event_ty, .data = .{ .tag = .{
            .name = done_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{done_state_pat}),
        } } });
        const done_body = try self.continueRecordLoop(
            ret_ty,
            try self.localExpr(done_state_local, state_ty),
            try self.boolLiteral(true, ctl.bool_ty),
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            record_slots,
            ctl,
        );

        const branches = [_]DraftBranch{
            .{ .pat = continue_pat, .body = continue_body },
            .{ .pat = done_pat, .body = done_body },
        };
        const after_match = try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(after_event_local, after_event_ty),
            .branches = try self.addBranchSpan(&branches),
        } } });
        const uncounted_body = try self.sequenceTryTo(after_try, after_try_ty, after_event_local, after_match, ret_ty, error_join);

        return try self.ifExpr(
            try self.localExpr(ctl.counted_local, ctl.bool_ty),
            counted_body,
            uncounted_body,
            ret_ty,
        );
    }

    fn lowerParseRecordNamedFieldEvent(
        self: *BodyContext,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        continuations: ParseRecordContinuations,
        renamed_field_locals: []const DraftLocalId,
        renamed_field_lengths: ?[]const u32,
        renamed_field_texts: ?[]const []const u8,
        payload_local: DraftLocalId,
        payload_ty: Type.TypeId,
        mode: RecordFieldMatchMode,
    ) Allocator.Error!DraftExprId {
        const str_ty = try self.primitiveType(.str);
        const key_expr = try self.recordPayloadFieldAccess(payload_local, payload_ty, "name");
        if (!self.sameType(try self.exprType(key_expr), str_ty)) {
            Common.invariant("record named-field event key was not Str");
        }
        const rest_expr = try self.recordPayloadFieldAccess(payload_local, payload_ty, "rest");
        const key_local = try self.addLocal(self.builder.symbols.fresh(), str_ty);
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const body = try self.lowerRecordNamedFieldDispatchBody(
            key_local,
            str_ty,
            rest_local,
            state_ty,
            ret_ty,
            continuations,
            renamed_field_locals,
            renamed_field_lengths,
            renamed_field_texts,
            mode,
        );
        return try self.wrapLet(key_local, str_ty, key_expr, try self.wrapLet(rest_local, state_ty, rest_expr, body, ret_ty), ret_ty);
    }

    /// A `Continue` event means the format consumed a whole entry itself and
    /// the cursor is already at the next entry boundary, so the loop re-enters
    /// without calling `parse_record_after_field`.
    fn lowerParseRecordContinueEvent(
        self: *BodyContext,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        record_slots: ParseRecordSlots,
        ctl: RecordLoopCtl,
        continue_state_local: DraftLocalId,
    ) Allocator.Error!DraftExprId {
        const cursor_expr = try self.localExpr(continue_state_local, state_ty);
        const false_expr = try self.boolLiteral(false, ctl.bool_ty);
        const remaining_minus_one = try self.lowLevelExpr(.num_int_sub_wrap, &.{
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            try self.intLiteralExpr(1, ctl.u64_ty),
        }, ctl.u64_ty);
        const counted_body = try self.continueRecordLoop(ret_ty, cursor_expr, false_expr, remaining_minus_one, record_slots, ctl);
        const uncounted_body = try self.continueRecordLoop(
            ret_ty,
            cursor_expr,
            try self.boolLiteral(false, ctl.bool_ty),
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            record_slots,
            ctl,
        );
        return try self.ifExpr(
            try self.localExpr(ctl.counted_local, ctl.bool_ty),
            counted_body,
            uncounted_body,
            ret_ty,
        );
    }

    fn lowerParseRecordDoneEvent(
        self: *BodyContext,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        record_slots: ParseRecordSlots,
        ctl: RecordLoopCtl,
        done_state_local: DraftLocalId,
    ) Allocator.Error!DraftExprId {
        return try self.continueRecordLoop(
            ret_ty,
            try self.localExpr(done_state_local, state_ty),
            try self.boolLiteral(true, ctl.bool_ty),
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            record_slots,
            ctl,
        );
    }

    /// The single record-construction site: runs at the loop head once `done`
    /// is set or a counted record has consumed all its entries.
    fn lowerParseRecordFinish(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        record_slots: ParseRecordSlots,
        renamed_field_locals: []const DraftLocalId,
        rest_expr: DraftExprId,
        error_join: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const record_try_ty = try self.tryTypeLike(ret_ty, shape_ty, ret_info.err_ty);
        const record_expr = try self.finishGeneratedRecordSlots(
            record_slots,
            shape_ty,
            record_try_ty,
            renamed_field_locals,
            error_join,
        );
        const record_local = try self.addLocal(self.builder.symbols.fresh(), shape_ty);
        const ok_body = try self.parseResultOk(
            ret_ty,
            try self.localExpr(record_local, shape_ty),
            rest_expr,
            state_ty,
        );
        return try self.sequenceTryTo(record_expr, record_try_ty, record_local, ok_body, ret_ty, error_join);
    }

    fn lowerParseRecordDirectFieldEvent(
        self: *BodyContext,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        continuations: ParseRecordContinuations,
        field_payload_local: DraftLocalId,
        field_payload_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const rest_expr = try self.recordPayloadFieldAccess(field_payload_local, field_payload_ty, "rest");
        const field_expr = try self.recordPayloadFieldAccess(field_payload_local, field_payload_ty, "field");
        const field_ty = try self.exprType(field_expr);
        const field_local = try self.addLocal(self.builder.symbols.fresh(), field_ty);
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const body = try self.lowerRecordDirectFieldDispatchBody(
            field_local,
            field_ty,
            rest_local,
            state_ty,
            ret_ty,
            continuations,
        );
        return try self.wrapLet(field_local, field_ty, field_expr, try self.wrapLet(rest_local, state_ty, rest_expr, body, ret_ty), ret_ty);
    }

    fn lowerRecordDirectFieldDispatchBody(
        self: *BodyContext,
        field_local: DraftLocalId,
        field_ty: Type.TypeId,
        rest_local: DraftLocalId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        continuations: ParseRecordContinuations,
    ) Allocator.Error!DraftExprId {
        if (continuations.field_joins.len == 0) return try self.jumpToGeneratedJoin(
            continuations.skip_join,
            &.{try self.localExpr(rest_local, state_ty)},
            &.{},
            &.{},
            ret_ty,
        );

        const u64_ty = try self.primitiveType(.u64);
        const index_local = try self.addLocal(self.builder.symbols.fresh(), u64_ty);
        var body = try self.jumpToGeneratedJoin(
            continuations.field_joins[continuations.field_joins.len - 1],
            &.{try self.localExpr(rest_local, state_ty)},
            &.{},
            &.{},
            ret_ty,
        );
        var index = continuations.field_joins.len - 1;
        while (index > 0) {
            index -= 1;
            const matched = try self.jumpToGeneratedJoin(
                continuations.field_joins[index],
                &.{try self.localExpr(rest_local, state_ty)},
                &.{},
                &.{},
                ret_ty,
            );
            const index_expr = try self.localExpr(index_local, u64_ty);
            const literal_expr = try self.intLiteralExpr(@intCast(index), u64_ty);
            const cond = try self.lowLevelExpr(.num_is_eq, &.{ index_expr, literal_expr }, try self.primitiveType(.bool));
            body = try self.ifExpr(cond, matched, body, ret_ty);
        }

        const handle_index = try self.fieldHandleIndexExpr(field_local, field_ty, u64_ty);
        return try self.wrapLet(index_local, u64_ty, handle_index, body, ret_ty);
    }

    fn lowerRecordNamedFieldDispatchBody(
        self: *BodyContext,
        key_local: DraftLocalId,
        key_ty: Type.TypeId,
        rest_local: DraftLocalId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        continuations: ParseRecordContinuations,
        renamed_field_locals: []const DraftLocalId,
        renamed_field_lengths: ?[]const u32,
        renamed_field_texts: ?[]const []const u8,
        mode: RecordFieldMatchMode,
    ) Allocator.Error!DraftExprId {
        if (continuations.field_joins.len != renamed_field_locals.len) Common.invariant("record named field dispatch renamed field arity differed from field count");
        if (renamed_field_lengths) |lengths| {
            if (continuations.field_joins.len != lengths.len) Common.invariant("record named field dispatch renamed length arity differed from field count");
        }
        if (renamed_field_texts) |texts| {
            if (continuations.field_joins.len != texts.len) Common.invariant("record named field dispatch renamed text arity differed from field count");
        }

        const matched_bodies = try self.allocator.alloc(DraftExprId, continuations.field_joins.len);
        defer self.allocator.free(matched_bodies);
        for (continuations.field_joins, 0..) |target, index| {
            matched_bodies[index] = try self.jumpToGeneratedJoin(
                target,
                &.{try self.localExpr(rest_local, state_ty)},
                &.{},
                &.{},
                ret_ty,
            );
        }

        const unknown_body = try self.jumpToGeneratedJoin(
            continuations.skip_join,
            &.{try self.localExpr(rest_local, state_ty)},
            &.{},
            &.{},
            ret_ty,
        );

        return try self.lowerParseRecordNamedDispatchBody(
            key_local,
            key_ty,
            renamed_field_locals,
            renamed_field_lengths,
            renamed_field_texts,
            matched_bodies,
            unknown_body,
            mode,
            ret_ty,
        );
    }

    fn lowerSkipRecordFieldNext(
        self: *BodyContext,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        rest_local: DraftLocalId,
        entry_end_join: DraftExprId,
        error_join: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const skip_try_ty = try self.tryTypeLike(ret_ty, state_ty, ret_info.err_ty);
        const prepared = try self.frozenFormatCodecCall(.parser, "skip_record_field");
        const lookup = prepared.lookup;
        const callable_mono_ty = prepared.callable_ty;
        const skip_fn = self.functionShape(callable_mono_ty, "skip_record_field target method was not a function");
        const arg_tys = self.typeStore().span(skip_fn.args);
        if (arg_tys.len != 2) Common.invariant("skip_record_field target method had an unexpected arity");
        if (!self.sameType(GuardedList.at(arg_tys, 0), encoding_ty)) Common.invariant("skip_record_field encoding type differed from record encoding type");
        if (!self.sameType(GuardedList.at(arg_tys, 1), state_ty)) Common.invariant("skip_record_field state type differed from record state type");

        const skip_expr = try self.addExpr(.{
            .ty = skip_fn.ret,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(prepared.callee),
                .args = try self.addExprSpan(&[_]DraftExprId{ encoding_expr, try self.localExpr(rest_local, state_ty) }),
                .captures = try self.methodTargetCaptureSpan(lookup),
            } },
        });
        const skipped_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const ok_body = try self.jumpToGeneratedJoin(
            entry_end_join,
            &.{try self.localExpr(skipped_local, state_ty)},
            &.{},
            &.{},
            ret_ty,
        );
        return try self.sequenceTryTo(skip_expr, skip_try_ty, skipped_local, ok_body, ret_ty, error_join);
    }

    fn lowerParseMatchedRecordFieldNext(
        self: *BodyContext,
        field: Type.Field,
        field_index: usize,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        record_slots: ParseRecordSlots,
        precomputed_plan: ?*const ParserPrecomputedPlan,
        rest_local: DraftLocalId,
        ret_ty: Type.TypeId,
        entry_end_join: DraftExprId,
        error_join: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const maybe_missing_try = try self.missingTryInfo(field.ty);
        const maybe_slot = self.optionalFieldSlot(field.ty);
        const field_parse_ty = if (maybe_missing_try) |info|
            info.ok_ty
        else if (maybe_slot) |slot|
            slot.payload_ty
        else
            field.ty;
        const parse_ok_ty = try self.parseResultOkType(field_parse_ty, state_ty);
        const parse_ret_ty = try self.tryTypeLike(ret_ty, parse_ok_ty, ret_info.err_ty);
        const parse_expr = try self.lowerParseShapeHelperCall(
            field_parse_ty,
            encoding_expr,
            encoding_ty,
            try self.localExpr(rest_local, state_ty),
            state_ty,
            parse_ret_ty,
            precomputed_plan,
        );
        const value_name = try self.nameStoreMut().internRecordFieldLabel("value");
        const rest_name = try self.nameStoreMut().internRecordFieldLabel("rest");
        const parsed_value_local = try self.addLocal(self.builder.symbols.fresh(), field_parse_ty);
        const field_value = if (maybe_missing_try != null)
            try self.tryOk(field.ty, try self.localExpr(parsed_value_local, field_parse_ty))
        else if (maybe_slot) |slot|
            // A matched `?:` field parses at the slot's Present payload type
            // and wraps in the `#Present` tag (design.md "Field Kinds").
            try self.optionalSlotPresentExpr(field.ty, slot, try self.localExpr(parsed_value_local, field_parse_ty))
        else
            try self.localExpr(parsed_value_local, field_parse_ty);
        const field_value_local = try self.addLocal(self.builder.symbols.fresh(), field.ty);
        const parsed_rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const presence_word = recordPresenceWordIndex(field_index);
        const loop_params = [_]BodyTypedLocal{
            .{ .local = record_slots.payload_locals[field_index], .ty = record_slots.payload_tys[field_index] },
            .{ .local = record_slots.presence_locals[presence_word], .ty = record_slots.presence_tys[presence_word] },
        };
        // Payload replacement must precede marking the slot initialized. ARC
        // cleanup of a duplicate field therefore tests the previous presence
        // bit and never decrefs an uninitialized payload.
        const loop_values = [_]DraftExprId{
            try self.localExpr(field_value_local, field.ty),
            try self.recordPresenceWithBit(
                record_slots.presence_locals[presence_word],
                record_slots.presence_tys[presence_word],
                recordPresenceMask(field_index),
            ),
        };
        const ok_body = try self.jumpToGeneratedJoin(
            entry_end_join,
            &.{try self.localExpr(parsed_rest_local, state_ty)},
            &loop_params,
            &loop_values,
            ret_ty,
        );
        const with_field_value = try self.wrapLet(field_value_local, field.ty, field_value, ok_body, ret_ty);
        return try self.sequenceTryRecordTo(
            parse_expr,
            parse_ret_ty,
            parsed_value_local,
            value_name,
            parsed_rest_local,
            rest_name,
            with_field_value,
            ret_ty,
            error_join,
        );
    }

    fn lowerParseShapeHelperCall(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const def_id = try self.parseShapeDefForType(
            shape_ty,
            encoding_ty,
            state_ty,
            ret_ty,
            precomputed_plan,
        );
        var plan_inputs = try self.serializationPlanInputs(.parser, shape_ty, precomputed_plan);
        defer plan_inputs.deinit(self.allocator);
        const str_ty = try self.primitiveType(.str);
        const arg_tys = try self.allocator.alloc(Type.TypeId, 2 + plan_inputs.locals.items.len);
        defer self.allocator.free(arg_tys);
        const args = try self.allocator.alloc(DraftExprId, arg_tys.len);
        defer self.allocator.free(args);
        arg_tys[0] = state_ty;
        arg_tys[1] = encoding_ty;
        args[0] = state_expr;
        args[1] = encoding_expr;
        for (plan_inputs.locals.items, 0..) |local, index| {
            arg_tys[2 + index] = str_ty;
            args[2 + index] = try self.localExpr(local, str_ty);
        }
        const fn_ty = try self.functionType(arg_tys, ret_ty);
        const callee = try self.addExpr(.{
            .ty = fn_ty,
            .data = .{ .def_ref = .{ .draft = def_id } },
        });
        return try self.addExpr(.{
            .ty = ret_ty,
            .data = .{ .call_value = .{
                .callee = callee,
                .args = try self.addExprSpan(args),
            } },
        });
    }

    fn parseShapeDefForType(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftDefId {
        const address = GeneratedParserDefAddress{
            .value_ty = @backingInt(shape_ty),
            .encoding_ty = @backingInt(encoding_ty),
            .state_ty = @backingInt(state_ty),
            .result = self.typeStore().typeDigestCached(self.nameStore(), ret_ty, null),
        };
        if (self.parser_defs.get(address)) |entry| return entry.id();

        const def_id = try self.draft.reserveDef(self.draft.current_owner);
        try self.parser_defs.put(address, .{ .reserved = def_id });

        var plan_inputs = try self.serializationPlanInputs(.parser, shape_ty, precomputed_plan);
        defer plan_inputs.deinit(self.allocator);
        const str_ty = try self.primitiveType(.str);
        var helper_plan: ?SerializationHelperPlan = if (precomputed_plan) |plan|
            try self.cloneSerializationHelperPlan(plan, &plan_inputs, str_ty)
        else
            null;
        defer if (helper_plan) |*plan| plan.deinit(self.allocator);

        const state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const encoding_local = try self.addLocal(self.builder.symbols.fresh(), encoding_ty);
        const body = try self.lowerParseResultFromState(
            shape_ty,
            try self.localExpr(encoding_local, encoding_ty),
            encoding_ty,
            try self.localExpr(state_local, state_ty),
            state_ty,
            ret_ty,
            if (helper_plan) |*plan| &plan.plan else null,
        );
        const args = try self.allocator.alloc(BodyTypedLocal, 2 + plan_inputs.locals.items.len);
        defer self.allocator.free(args);
        args[0] = .{ .local = state_local, .ty = state_ty };
        args[1] = .{ .local = encoding_local, .ty = encoding_ty };
        if (helper_plan) |*plan| {
            @memcpy(args[2..], plan.args);
        } else if (plan_inputs.locals.items.len != 0) {
            Common.invariant("structural parser helper had plan inputs without a precomputed plan");
        }
        self.draft.setDef(def_id, .{
            .symbol = self.builder.symbols.fresh(),
            .fn_def = null,
            .fn_id = null,
            .identity_seed = .{ .kind = "parse-shape-helper", .cells = .{ DraftTypeCell.fromSealed(shape_ty), DraftTypeCell.fromSealed(encoding_ty), DraftTypeCell.fromSealed(state_ty), DraftTypeCell.fromSealed(ret_ty) } },
            .args = try self.addTypedLocalSpan(args),
            .body = .{ .roc = body },
            .ret = try self.draftTypeCell(ret_ty),
        });
        try self.parser_defs.put(address, .{ .ready = def_id });
        return def_id;
    }

    fn lowerParseResultFromState(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        if (self.tryNullInfo(shape_ty)) |info| {
            return try self.lowerParseNullTryFromState(info, shape_ty, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan);
        }
        if (self.dictEntryShape(shape_ty)) |dict| {
            return try self.lowerParseDictFromState(dict.key_ty, dict.value_ty, shape_ty, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan);
        }
        if (self.setPayloadType(shape_ty)) |payload_ty| {
            return try self.lowerParseSetFromState(payload_ty, shape_ty, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan);
        }
        // The checked nominal codec owns this value, regardless of its backing shape.
        if (self.frozenCustomCodecCallForShape(.parser, shape_ty)) |prepared| {
            return try self.lowerCustomParserFromState(
                prepared.*,
                shape_ty,
                encoding_expr,
                encoding_ty,
                state_expr,
                state_ty,
                ret_ty,
            );
        }
        switch (self.shapeContent(shape_ty)) {
            .list => |elem_ty| return try self.lowerParseListFromState(elem_ty, shape_ty, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan),
            .tuple => |items| {
                const item_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(items));
                defer self.allocator.free(item_tys);
                return try self.lowerParseTupleFromState(item_tys, shape_ty, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan);
            },
            .box => |payload_ty| return try self.lowerParseBoxFromState(payload_ty, shape_ty, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan),
            .primitive, .named, .record, .tag_union, .func, .erased, .zst => {},
        }
        return try self.lowerParseShapeFromState(shape_ty, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan);
    }

    /// A tuple's arity is static, so the format is told the element count and
    /// never decides when the sequence ends: no per-element event union, and
    /// arity mismatches are reported by the format itself, where it can say
    /// what it actually found.
    fn lowerParseTupleFromState(
        self: *BodyContext,
        item_tys: []const Type.TypeId,
        tuple_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const u64_ty = try self.primitiveType(.u64);
        const len_expr = try self.intLiteralExpr(@intCast(item_tys.len), u64_ty);
        const state_try_ty = try self.tryTypeLike(ret_ty, state_ty, ret_info.err_ty);

        const item_locals = try self.allocator.alloc(DraftLocalId, item_tys.len);
        defer self.allocator.free(item_locals);
        for (item_tys, 0..) |item_ty, index| {
            item_locals[index] = try self.addLocal(self.builder.symbols.fresh(), item_ty);
        }

        const start_try = try self.lowerParseFormatMethod(
            "parse_tuple_start",
            &.{ encoding_expr, state_expr, len_expr },
            &.{ encoding_ty, state_ty, u64_ty },
            tuple_ty,
            state_try_ty,
        );
        const cursor_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const body = try self.lowerParseTupleElement(
            item_tys,
            tuple_ty,
            encoding_expr,
            encoding_ty,
            cursor_local,
            state_ty,
            ret_ty,
            item_locals,
            0,
            precomputed_plan,
        );
        return try self.sequenceTry(start_try, state_try_ty, cursor_local, body, ret_ty);
    }

    fn lowerParseTupleElement(
        self: *BodyContext,
        item_tys: []const Type.TypeId,
        tuple_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        cursor_local: DraftLocalId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        item_locals: []const DraftLocalId,
        item_index: usize,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const u64_ty = try self.primitiveType(.u64);
        const len_expr = try self.intLiteralExpr(@intCast(item_tys.len), u64_ty);
        const state_try_ty = try self.tryTypeLike(ret_ty, state_ty, ret_info.err_ty);

        if (item_index == item_tys.len) {
            const end_try = try self.lowerParseFormatMethod(
                "parse_tuple_end",
                &.{ encoding_expr, try self.localExpr(cursor_local, state_ty), len_expr },
                &.{ encoding_ty, state_ty, u64_ty },
                tuple_ty,
                state_try_ty,
            );
            const end_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
            const done_body = try self.lowerParseTupleDone(
                item_tys,
                tuple_ty,
                item_locals,
                try self.localExpr(end_local, state_ty),
                state_ty,
                ret_ty,
            );
            return try self.sequenceTry(end_try, state_try_ty, end_local, done_body, ret_ty);
        }

        const element_body = try self.lowerParseTupleElementAfterSeparator(
            item_tys,
            tuple_ty,
            encoding_expr,
            encoding_ty,
            cursor_local,
            state_ty,
            ret_ty,
            item_locals,
            item_index,
            precomputed_plan,
        );

        // Every element after the first is preceded by a separator the format
        // consumes, told which element is coming and how many there are.
        if (item_index == 0) return element_body;

        const index_expr = try self.intLiteralExpr(@intCast(item_index), u64_ty);
        const next_try = try self.lowerParseFormatMethod(
            "parse_tuple_next",
            &.{ encoding_expr, try self.localExpr(cursor_local, state_ty), index_expr, len_expr },
            &.{ encoding_ty, state_ty, u64_ty, u64_ty },
            tuple_ty,
            state_try_ty,
        );
        const separated_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const separated_body = try self.lowerParseTupleElementAfterSeparator(
            item_tys,
            tuple_ty,
            encoding_expr,
            encoding_ty,
            separated_local,
            state_ty,
            ret_ty,
            item_locals,
            item_index,
            precomputed_plan,
        );
        return try self.sequenceTry(next_try, state_try_ty, separated_local, separated_body, ret_ty);
    }

    /// The element read itself, with the cursor already past the separator.
    fn lowerParseTupleElementAfterSeparator(
        self: *BodyContext,
        item_tys: []const Type.TypeId,
        tuple_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        cursor_local: DraftLocalId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        item_locals: []const DraftLocalId,
        item_index: usize,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const item_ty = item_tys[item_index];
        const parse_ok_ty = try self.parseResultOkType(item_ty, state_ty);
        const parse_ret_ty = try self.tryTypeLike(ret_ty, parse_ok_ty, ret_info.err_ty);
        const value_name = try self.nameStoreMut().internRecordFieldLabel("value");
        const rest_name = try self.nameStoreMut().internRecordFieldLabel("rest");
        const parsed_rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);

        const rest_body = try self.lowerParseTupleElement(
            item_tys,
            tuple_ty,
            encoding_expr,
            encoding_ty,
            parsed_rest_local,
            state_ty,
            ret_ty,
            item_locals,
            item_index + 1,
            precomputed_plan,
        );
        const parse_expr = try self.lowerParseShapeHelperCall(
            item_ty,
            encoding_expr,
            encoding_ty,
            try self.localExpr(cursor_local, state_ty),
            state_ty,
            parse_ret_ty,
            precomputed_plan,
        );
        return try self.sequenceTryRecord(
            parse_expr,
            parse_ret_ty,
            item_locals[item_index],
            value_name,
            parsed_rest_local,
            rest_name,
            rest_body,
            ret_ty,
        );
    }

    fn lowerParseTupleDone(
        self: *BodyContext,
        item_tys: []const Type.TypeId,
        tuple_ty: Type.TypeId,
        item_locals: []const DraftLocalId,
        rest_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        if (item_tys.len != item_locals.len) Common.invariant("tuple parser local count differed from tuple type arity");
        const items = try self.allocator.alloc(DraftExprId, item_tys.len);
        defer self.allocator.free(items);
        for (item_tys, item_locals, 0..) |item_ty, item_local, index| {
            items[index] = try self.localExpr(item_local, item_ty);
        }
        const tuple_expr = try self.addExpr(.{
            .ty = tuple_ty,
            .data = .{ .tuple = try self.addExprSpan(items) },
        });
        return try self.parseResultOk(ret_ty, tuple_expr, rest_expr, state_ty);
    }

    const ParseCountedStartInit = struct {
        ty: Type.TypeId,
        expr: DraftExprId,
        local: DraftLocalId,
    };

    /// The `{ counted, cursor, remaining }` record a counted parse loop starts
    /// from, selected by matching the format's `Counted`/`Uncounted` start
    /// event, plus a fresh local to bind it to.
    fn lowerParseCountedStartInit(
        self: *BodyContext,
        start_event_local: DraftLocalId,
        start_event_ty: Type.TypeId,
        state_ty: Type.TypeId,
        bool_ty: Type.TypeId,
        u64_ty: Type.TypeId,
        comptime context: []const u8,
    ) Allocator.Error!ParseCountedStartInit {
        const init_counted_name = try self.nameStoreMut().internRecordFieldLabel("counted");
        const init_cursor_name = try self.nameStoreMut().internRecordFieldLabel("cursor");
        const init_remaining_name = try self.nameStoreMut().internRecordFieldLabel("remaining");
        const init_field_tys = [_]Type.Field{
            .{ .name = init_counted_name, .ty = bool_ty, .default = null },
            .{ .name = init_cursor_name, .ty = state_ty, .default = null },
            .{ .name = init_remaining_name, .ty = u64_ty, .default = null },
        };
        const init_ty = try self.recordType(&init_field_tys);

        const counted_tag = self.monoTagByText(start_event_ty, "Counted");
        const counted_payload_ty = self.singleTagPayloadType(counted_tag, context);
        const counted_payload_local = try self.addLocal(self.builder.symbols.fresh(), counted_payload_ty);
        const counted_payload_pat = try self.bindPat(counted_payload_local, counted_payload_ty);
        const counted_pat = try self.addPat(.{ .ty = start_event_ty, .data = .{ .tag = .{
            .name = counted_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{counted_payload_pat}),
        } } });
        const counted_init_fields = [_]DraftFieldExpr{
            .{ .name = init_counted_name, .value = try self.boolLiteral(true, bool_ty) },
            .{ .name = init_cursor_name, .value = try self.recordPayloadFieldAccess(counted_payload_local, counted_payload_ty, "rest") },
            .{ .name = init_remaining_name, .value = try self.recordPayloadFieldAccess(counted_payload_local, counted_payload_ty, "len") },
        };
        const counted_init = try self.addExpr(.{
            .ty = init_ty,
            .data = .{ .record = try self.addFieldExprSpan(&counted_init_fields) },
        });

        const uncounted_tag = self.monoTagByText(start_event_ty, "Uncounted");
        const uncounted_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const uncounted_state_pat = try self.bindPat(uncounted_state_local, state_ty);
        const uncounted_pat = try self.addPat(.{ .ty = start_event_ty, .data = .{ .tag = .{
            .name = uncounted_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{uncounted_state_pat}),
        } } });
        const uncounted_init_fields = [_]DraftFieldExpr{
            .{ .name = init_counted_name, .value = try self.boolLiteral(false, bool_ty) },
            .{ .name = init_cursor_name, .value = try self.localExpr(uncounted_state_local, state_ty) },
            .{ .name = init_remaining_name, .value = try self.intLiteralExpr(0, u64_ty) },
        };
        const uncounted_init = try self.addExpr(.{
            .ty = init_ty,
            .data = .{ .record = try self.addFieldExprSpan(&uncounted_init_fields) },
        });

        const init_branches = [_]DraftBranch{
            .{ .pat = counted_pat, .body = counted_init },
            .{ .pat = uncounted_pat, .body = uncounted_init },
        };
        const init_expr = try self.addExpr(.{ .ty = init_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(start_event_local, start_event_ty),
            .branches = try self.addBranchSpan(&init_branches),
        } } });
        const init_local = try self.addLocal(self.builder.symbols.fresh(), init_ty);
        return .{ .ty = init_ty, .expr = init_expr, .local = init_local };
    }

    /// A format that knows its element count up front returns `Counted`, and
    /// the driver then reads exactly that many elements with no further format
    /// calls and preallocates the list. Otherwise the element loop asks the
    /// format after every element whether more follow.
    fn lowerParseListFromState(
        self: *BodyContext,
        elem_ty: Type.TypeId,
        list_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const u64_ty = try self.primitiveType(.u64);
        const bool_ty = try self.primitiveType(.bool);
        const start_event_ty = try self.parseCountedStartEventType(state_ty);
        const start_try_ty = try self.tryTypeLike(ret_ty, start_event_ty, ret_info.err_ty);
        const start_try = try self.lowerParseFormatMethod(
            "parse_list_start",
            &.{ encoding_expr, state_expr },
            &.{ encoding_ty, state_ty },
            list_ty,
            start_try_ty,
        );
        const start_event_local = try self.addLocal(self.builder.symbols.fresh(), start_event_ty);

        const cursor_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const list_local = try self.addLocal(self.builder.symbols.fresh(), list_ty);
        const ctl = ListLoopCtl{
            .counted_local = try self.addLocal(self.builder.symbols.fresh(), bool_ty),
            .remaining_local = try self.addLocal(self.builder.symbols.fresh(), u64_ty),
            .bool_ty = bool_ty,
            .u64_ty = u64_ty,
        };
        const loop_body = try self.lowerParseListLoopBody(
            elem_ty,
            list_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            cursor_local,
            list_local,
            ctl,
            ret_ty,
            precomputed_plan,
        );
        const loop_params = [_]BodyTypedLocal{
            .{ .local = cursor_local, .ty = state_ty },
            .{ .local = list_local, .ty = list_ty },
            .{ .local = ctl.counted_local, .ty = bool_ty },
            .{ .local = ctl.remaining_local, .ty = u64_ty },
        };

        const start_init = try self.lowerParseCountedStartInit(start_event_local, start_event_ty, state_ty, bool_ty, u64_ty, "list parse Counted start event");
        const init_ty = start_init.ty;
        const init_expr = start_init.expr;
        const init_local = start_init.local;

        const remaining_expr = try self.recordPayloadFieldAccess(init_local, init_ty, "remaining");
        const initial_values = [_]DraftExprId{
            try self.recordPayloadFieldAccess(init_local, init_ty, "cursor"),
            try self.lowLevelExpr(.list_with_capacity, &.{remaining_expr}, list_ty),
            try self.recordPayloadFieldAccess(init_local, init_ty, "counted"),
            try self.recordPayloadFieldAccess(init_local, init_ty, "remaining"),
        };
        var loop_expr = try self.addExpr(.{ .ty = ret_ty, .data = .{ .loop_ = .{
            .params = try self.addTypedLocalSpan(&loop_params),
            .initial_values = try self.addExprSpan(&initial_values),
            .body = loop_body,
        } } });
        loop_expr = try self.wrapLet(init_local, init_ty, init_expr, loop_expr, ret_ty);
        return try self.sequenceTry(start_try, start_try_ty, start_event_local, loop_expr, ret_ty);
    }

    fn lowerParseSetFromState(
        self: *BodyContext,
        elem_ty: Type.TypeId,
        set_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const list_ty = try self.listType(elem_ty);
        const list_parse_ok_ty = try self.parseResultOkType(list_ty, state_ty);
        const list_parse_ret_ty = try self.tryTypeLike(ret_ty, list_parse_ok_ty, ret_info.err_ty);
        const list_parse = try self.lowerParseListFromState(
            elem_ty,
            list_ty,
            encoding_expr,
            encoding_ty,
            state_expr,
            state_ty,
            list_parse_ret_ty,
            precomputed_plan,
        );

        const value_name = try self.nameStoreMut().internRecordFieldLabel("value");
        const rest_name = try self.nameStoreMut().internRecordFieldLabel("rest");
        const list_local = try self.addLocal(self.builder.symbols.fresh(), list_ty);
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const set_value = try self.lowerSetFromList(set_ty, list_ty, try self.localExpr(list_local, list_ty));
        const ok_body = try self.parseResultOk(ret_ty, set_value, try self.localExpr(rest_local, state_ty), state_ty);
        return try self.sequenceTryRecord(list_parse, list_parse_ret_ty, list_local, value_name, rest_local, rest_name, ok_body, ret_ty);
    }

    /// A dict's entries are parsed the same way a list's elements are, with a
    /// key read before each value: `Counted` lets a length-prefixed format
    /// declare the entry count up front, and the key goes through the key
    /// type's own parser rather than being routed through a string.
    fn lowerParseDictFromState(
        self: *BodyContext,
        key_ty: Type.TypeId,
        value_ty: Type.TypeId,
        dict_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const u64_ty = try self.primitiveType(.u64);
        const bool_ty = try self.primitiveType(.bool);
        const start_event_ty = try self.parseCountedStartEventType(state_ty);
        const start_try_ty = try self.tryTypeLike(ret_ty, start_event_ty, ret_info.err_ty);
        const start_try = try self.lowerParseFormatMethod(
            "parse_dict_start",
            &.{ encoding_expr, state_expr },
            &.{ encoding_ty, state_ty },
            dict_ty,
            start_try_ty,
        );
        const start_event_local = try self.addLocal(self.builder.symbols.fresh(), start_event_ty);

        const cursor_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const dict_local = try self.addLocal(self.builder.symbols.fresh(), dict_ty);
        const ctl = ListLoopCtl{
            .counted_local = try self.addLocal(self.builder.symbols.fresh(), bool_ty),
            .remaining_local = try self.addLocal(self.builder.symbols.fresh(), u64_ty),
            .bool_ty = bool_ty,
            .u64_ty = u64_ty,
        };
        const loop_body = try self.lowerParseDictLoopBody(
            key_ty,
            value_ty,
            dict_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            cursor_local,
            dict_local,
            ctl,
            ret_ty,
            precomputed_plan,
        );
        const loop_params = [_]BodyTypedLocal{
            .{ .local = cursor_local, .ty = state_ty },
            .{ .local = dict_local, .ty = dict_ty },
            .{ .local = ctl.counted_local, .ty = bool_ty },
            .{ .local = ctl.remaining_local, .ty = u64_ty },
        };

        const start_init = try self.lowerParseCountedStartInit(start_event_local, start_event_ty, state_ty, bool_ty, u64_ty, "dict parse Counted start event");
        const init_ty = start_init.ty;
        const init_expr = start_init.expr;
        const init_local = start_init.local;

        const initial_values = [_]DraftExprId{
            try self.recordPayloadFieldAccess(init_local, init_ty, "cursor"),
            try self.lowerDictWithCapacity(dict_ty, try self.recordPayloadFieldAccess(init_local, init_ty, "remaining"), u64_ty),
            try self.recordPayloadFieldAccess(init_local, init_ty, "counted"),
            try self.recordPayloadFieldAccess(init_local, init_ty, "remaining"),
        };
        var loop_expr = try self.addExpr(.{ .ty = ret_ty, .data = .{ .loop_ = .{
            .params = try self.addTypedLocalSpan(&loop_params),
            .initial_values = try self.addExprSpan(&initial_values),
            .body = loop_body,
        } } });
        loop_expr = try self.wrapLet(init_local, init_ty, init_expr, loop_expr, ret_ty);
        return try self.sequenceTry(start_try, start_try_ty, start_event_local, loop_expr, ret_ty);
    }

    fn lowerParseDictLoopBody(
        self: *BodyContext,
        key_ty: Type.TypeId,
        value_ty: Type.TypeId,
        dict_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        cursor_local: DraftLocalId,
        dict_local: DraftLocalId,
        ctl: ListLoopCtl,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const event_ty = try self.parseArrayEventType(state_ty, "Entry", "Done");
        const event_try_ty = try self.tryTypeLike(ret_ty, event_ty, ret_info.err_ty);
        const next_try = try self.lowerParseFormatMethod(
            "parse_dict_next",
            &.{ encoding_expr, try self.localExpr(cursor_local, state_ty) },
            &.{ encoding_ty, state_ty },
            dict_ty,
            event_try_ty,
        );
        const event_local = try self.addLocal(self.builder.symbols.fresh(), event_ty);
        const event_body = try self.lowerParseDictNextEvent(
            key_ty,
            value_ty,
            dict_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            event_local,
            event_ty,
            dict_local,
            ctl,
            ret_ty,
            precomputed_plan,
        );
        const uncounted_body = try self.sequenceTry(next_try, event_try_ty, event_local, event_body, ret_ty);

        const done_value = try self.parseResultOk(
            ret_ty,
            try self.localExpr(dict_local, dict_ty),
            try self.localExpr(cursor_local, state_ty),
            state_ty,
        );
        const counted_done = try self.addExpr(.{ .ty = ret_ty, .data = .{ .break_ = done_value } });
        const remaining_minus_one = try self.lowLevelExpr(.num_int_sub_wrap, &.{
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            try self.intLiteralExpr(1, ctl.u64_ty),
        }, ctl.u64_ty);
        const counted_entry = try self.lowerParseDictEntry(
            key_ty,
            value_ty,
            dict_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            cursor_local,
            dict_local,
            ctl,
            remaining_minus_one,
            .counted,
            ret_ty,
            precomputed_plan,
        );
        const remaining_is_zero = try self.lowLevelExpr(.num_is_eq, &.{
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            try self.intLiteralExpr(0, ctl.u64_ty),
        }, ctl.bool_ty);
        const counted_body = try self.ifExpr(remaining_is_zero, counted_done, counted_entry, ret_ty);

        return try self.ifExpr(
            try self.localExpr(ctl.counted_local, ctl.bool_ty),
            counted_body,
            uncounted_body,
            ret_ty,
        );
    }

    fn lowerParseDictNextEvent(
        self: *BodyContext,
        key_ty: Type.TypeId,
        value_ty: Type.TypeId,
        dict_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        event_local: DraftLocalId,
        event_ty: Type.TypeId,
        dict_local: DraftLocalId,
        ctl: ListLoopCtl,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const entry_tag = self.monoTagByText(event_ty, "Entry");
        const entry_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const entry_state_pat = try self.bindPat(entry_state_local, state_ty);
        const entry_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = entry_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{entry_state_pat}),
        } } });
        const entry_body = try self.lowerParseDictEntry(
            key_ty,
            value_ty,
            dict_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            entry_state_local,
            dict_local,
            ctl,
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            .uncounted,
            ret_ty,
            precomputed_plan,
        );

        const done_tag = self.monoTagByText(event_ty, "Done");
        const done_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const done_state_pat = try self.bindPat(done_state_local, state_ty);
        const done_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = done_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{done_state_pat}),
        } } });
        const done_value = try self.parseResultOk(
            ret_ty,
            try self.localExpr(dict_local, dict_ty),
            try self.localExpr(done_state_local, state_ty),
            state_ty,
        );
        const done_body = try self.addExpr(.{ .ty = ret_ty, .data = .{ .break_ = done_value } });

        const branches = [_]DraftBranch{
            .{ .pat = entry_pat, .body = entry_body },
            .{ .pat = done_pat, .body = done_body },
        };
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(event_local, event_ty),
            .branches = try self.addBranchSpan(&branches),
        } } });
    }

    /// One key-value entry. In Uncounted mode the format decides after each
    /// entry whether more follow; Counted mode instead re-enters the loop with
    /// one fewer entry left.
    fn lowerParseDictEntry(
        self: *BodyContext,
        key_ty: Type.TypeId,
        value_ty: Type.TypeId,
        dict_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        entry_state_local: DraftLocalId,
        dict_local: DraftLocalId,
        ctl: ListLoopCtl,
        remaining_expr: DraftExprId,
        entry_end_mode: DictEntryEndMode,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const value_name = try self.nameStoreMut().internRecordFieldLabel("value");
        const rest_name = try self.nameStoreMut().internRecordFieldLabel("rest");

        const key_parse_ok_ty = try self.parseResultOkType(key_ty, state_ty);
        const key_parse_ret_ty = try self.tryTypeLike(ret_ty, key_parse_ok_ty, ret_info.err_ty);
        const key_parse = try self.lowerParseDictKey(
            key_ty,
            encoding_expr,
            encoding_ty,
            try self.localExpr(entry_state_local, state_ty),
            state_ty,
            key_parse_ret_ty,
            precomputed_plan,
        );
        const key_local = try self.addLocal(self.builder.symbols.fresh(), key_ty);
        const after_key_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);

        const separator_try_ty = try self.tryTypeLike(ret_ty, state_ty, ret_info.err_ty);
        const separator_try = try self.lowerParseFormatMethod(
            "parse_dict_after_key",
            &.{ encoding_expr, try self.localExpr(after_key_local, state_ty) },
            &.{ encoding_ty, state_ty },
            dict_ty,
            separator_try_ty,
        );
        const value_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);

        const value_parse_ok_ty = try self.parseResultOkType(value_ty, state_ty);
        const value_parse_ret_ty = try self.tryTypeLike(ret_ty, value_parse_ok_ty, ret_info.err_ty);
        const value_parse = try self.lowerParseShapeHelperCall(
            value_ty,
            encoding_expr,
            encoding_ty,
            try self.localExpr(value_state_local, state_ty),
            state_ty,
            value_parse_ret_ty,
            precomputed_plan,
        );
        const value_local = try self.addLocal(self.builder.symbols.fresh(), value_ty);
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const inserted = try self.lowerDictInsert(
            dict_ty,
            key_ty,
            value_ty,
            try self.localExpr(dict_local, dict_ty),
            try self.localExpr(key_local, key_ty),
            try self.localExpr(value_local, value_ty),
        );
        const inserted_local = try self.addLocal(self.builder.symbols.fresh(), dict_ty);

        const entry_end = switch (entry_end_mode) {
            .uncounted => blk: {
                const after_event_ty = try self.parseArrayEventType(state_ty, "Continue", "Done");
                const after_try_ty = try self.tryTypeLike(ret_ty, after_event_ty, ret_info.err_ty);
                const after_try = try self.lowerParseFormatMethod(
                    "parse_dict_after_entry",
                    &.{ encoding_expr, try self.localExpr(rest_local, state_ty) },
                    &.{ encoding_ty, state_ty },
                    dict_ty,
                    after_try_ty,
                );
                const after_event_local = try self.addLocal(self.builder.symbols.fresh(), after_event_ty);

                const continue_tag = self.monoTagByText(after_event_ty, "Continue");
                const continue_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
                const continue_state_pat = try self.bindPat(continue_state_local, state_ty);
                const continue_pat = try self.addPat(.{ .ty = after_event_ty, .data = .{ .tag = .{
                    .name = continue_tag.name,
                    .payloads = try self.addPatSpan(&[_]DraftPatId{continue_state_pat}),
                } } });
                const continue_body = try self.addExpr(.{ .ty = ret_ty, .data = .{ .continue_ = .{
                    .values = try self.addExprSpan(&[_]DraftExprId{
                        try self.localExpr(continue_state_local, state_ty),
                        try self.localExpr(inserted_local, dict_ty),
                        try self.localExpr(ctl.counted_local, ctl.bool_ty),
                        remaining_expr,
                    }),
                } } });

                const after_done_tag = self.monoTagByText(after_event_ty, "Done");
                const after_done_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
                const after_done_state_pat = try self.bindPat(after_done_state_local, state_ty);
                const after_done_pat = try self.addPat(.{ .ty = after_event_ty, .data = .{ .tag = .{
                    .name = after_done_tag.name,
                    .payloads = try self.addPatSpan(&[_]DraftPatId{after_done_state_pat}),
                } } });
                const after_done_value = try self.parseResultOk(
                    ret_ty,
                    try self.localExpr(inserted_local, dict_ty),
                    try self.localExpr(after_done_state_local, state_ty),
                    state_ty,
                );
                const after_done_body = try self.addExpr(.{ .ty = ret_ty, .data = .{ .break_ = after_done_value } });

                const after_branches = [_]DraftBranch{
                    .{ .pat = continue_pat, .body = continue_body },
                    .{ .pat = after_done_pat, .body = after_done_body },
                };
                const after_match = try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
                    .scrutinee = try self.localExpr(after_event_local, after_event_ty),
                    .branches = try self.addBranchSpan(&after_branches),
                } } });
                break :blk try self.sequenceTry(after_try, after_try_ty, after_event_local, after_match, ret_ty);
            },
            .counted => try self.addExpr(.{ .ty = ret_ty, .data = .{ .continue_ = .{
                .values = try self.addExprSpan(&[_]DraftExprId{
                    try self.localExpr(rest_local, state_ty),
                    try self.localExpr(inserted_local, dict_ty),
                    try self.localExpr(ctl.counted_local, ctl.bool_ty),
                    remaining_expr,
                }),
            } } }),
        };

        const with_inserted = try self.wrapLet(inserted_local, dict_ty, inserted, entry_end, ret_ty);
        const value_body = try self.sequenceTryRecord(value_parse, value_parse_ret_ty, value_local, value_name, rest_local, rest_name, with_inserted, ret_ty);
        const separator_body = try self.sequenceTry(separator_try, separator_try_ty, value_state_local, value_body, ret_ty);
        return try self.sequenceTryRecord(key_parse, key_parse_ret_ty, key_local, value_name, after_key_local, rest_name, separator_body, ret_ty);
    }

    fn lowerParseDictKey(
        self: *BodyContext,
        key_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        if (self.scalarCodecMethodName(key_ty, "parse_key_")) |method_name| {
            return try self.lowerParseFormatMethod(
                method_name,
                &.{ encoding_expr, state_expr },
                &.{ encoding_ty, state_ty },
                key_ty,
                ret_ty,
            );
        }
        if (self.dictKeyUnitTags(key_ty)) |tags_span| {
            return try self.lowerParseUnitTagDictKey(tags_span, key_ty, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty);
        }

        // A key the format cannot render as a key string is read by the key's
        // own parser, after `parse_key_start` opens the key position.
        const ret_info = self.tryInfo(ret_ty);
        const start_try_ty = try self.tryTypeLike(ret_ty, state_ty, ret_info.err_ty);
        const start_try = try self.lowerParseFormatMethod(
            "parse_key_start",
            &.{ encoding_expr, state_expr },
            &.{ encoding_ty, state_ty },
            key_ty,
            start_try_ty,
        );
        const opened_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const key_parse = try self.lowerParseShapeHelperCall(
            key_ty,
            encoding_expr,
            encoding_ty,
            try self.localExpr(opened_local, state_ty),
            state_ty,
            ret_ty,
            precomputed_plan,
        );
        return try self.sequenceTry(start_try, start_try_ty, opened_local, key_parse, ret_ty);
    }

    /// An enum key arrives as text, and an unmatched name is the one dict
    /// failure the driver detects rather than the format, so it builds the
    /// error through `invalid_value`.
    fn lowerParseUnitTagDictKey(
        self: *BodyContext,
        tags_span: Type.Span,
        key_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const str_ty = try self.primitiveType(.str);
        const key_parse_ok_ty = try self.parseResultOkType(str_ty, state_ty);
        const key_parse_ret_ty = try self.tryTypeLike(ret_ty, key_parse_ok_ty, ret_info.err_ty);
        const key_parse = try self.lowerParseFormatMethod(
            "parse_key_str",
            &.{ encoding_expr, state_expr },
            &.{ encoding_ty, state_ty },
            str_ty,
            key_parse_ret_ty,
        );
        const key_local = try self.addLocal(self.builder.symbols.fresh(), str_ty);
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);

        var body = try self.tryErr(ret_ty, try self.invalidValueError(
            encoding_expr,
            try self.localExpr(rest_local, state_ty),
            encoding_ty,
            state_ty,
            ret_info.err_ty,
        ));
        const tags = self.typeStore().tagSpan(tags_span);
        var index = tags.len;
        while (index > 0) {
            index -= 1;
            const tag = GuardedList.at(tags, index);
            const tag_text = self.nameStore().tagLabelText(tag.name);
            const tag_name_expr = try self.stringExpr(tag_text, str_ty);
            const key_expr = try self.localExpr(key_local, str_ty);
            const cond = try self.lowLevelExpr(.str_is_eq, &.{ key_expr, tag_name_expr }, try self.primitiveType(.bool));
            const value = try self.tagUnionValueWithoutPayload(key_ty, tag_text);
            const matched = try self.parseResultOk(ret_ty, value, try self.localExpr(rest_local, state_ty), state_ty);
            body = try self.ifExpr(cond, matched, body, ret_ty);
        }

        const value_name = try self.nameStoreMut().internRecordFieldLabel("value");
        const rest_name = try self.nameStoreMut().internRecordFieldLabel("rest");
        return try self.sequenceTryRecord(key_parse, key_parse_ret_ty, key_local, value_name, rest_local, rest_name, body, ret_ty);
    }

    fn lowerParseListLoopBody(
        self: *BodyContext,
        elem_ty: Type.TypeId,
        list_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        cursor_local: DraftLocalId,
        list_local: DraftLocalId,
        ctl: ListLoopCtl,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const next_event_ty = try self.parseArrayEventType(state_ty, "Item", "Done");
        const next_try_ty = try self.tryTypeLike(ret_ty, next_event_ty, ret_info.err_ty);
        const next_try = try self.lowerParseFormatMethod(
            "parse_list_next",
            &.{ encoding_expr, try self.localExpr(cursor_local, state_ty) },
            &.{ encoding_ty, state_ty },
            list_ty,
            next_try_ty,
        );
        const event_local = try self.addLocal(self.builder.symbols.fresh(), next_event_ty);
        const event_body = try self.lowerParseListNextEvent(
            elem_ty,
            list_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            event_local,
            next_event_ty,
            list_local,
            ctl,
            ret_ty,
            precomputed_plan,
        );
        const uncounted_body = try self.sequenceTry(next_try, next_try_ty, event_local, event_body, ret_ty);

        const counted_body = try self.lowerParseListCountedStep(
            elem_ty,
            list_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            cursor_local,
            list_local,
            ctl,
            ret_ty,
            precomputed_plan,
        );
        return try self.ifExpr(
            try self.localExpr(ctl.counted_local, ctl.bool_ty),
            counted_body,
            uncounted_body,
            ret_ty,
        );
    }

    /// Counted mode: stop once the declared count is exhausted, otherwise read
    /// one more element back-to-back with no intervening format call.
    fn lowerParseListCountedStep(
        self: *BodyContext,
        elem_ty: Type.TypeId,
        list_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        cursor_local: DraftLocalId,
        list_local: DraftLocalId,
        ctl: ListLoopCtl,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const done_value = try self.parseResultOk(
            ret_ty,
            try self.localExpr(list_local, list_ty),
            try self.localExpr(cursor_local, state_ty),
            state_ty,
        );
        const done_body = try self.addExpr(.{ .ty = ret_ty, .data = .{ .break_ = done_value } });

        const elem_parse_ok_ty = try self.parseResultOkType(elem_ty, state_ty);
        const elem_parse_ret_ty = try self.tryTypeLike(ret_ty, elem_parse_ok_ty, ret_info.err_ty);
        const elem_parse = try self.lowerParseShapeHelperCall(
            elem_ty,
            encoding_expr,
            encoding_ty,
            try self.localExpr(cursor_local, state_ty),
            state_ty,
            elem_parse_ret_ty,
            precomputed_plan,
        );
        const value_name = try self.nameStoreMut().internRecordFieldLabel("value");
        const rest_name = try self.nameStoreMut().internRecordFieldLabel("rest");
        const elem_local = try self.addLocal(self.builder.symbols.fresh(), elem_ty);
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const appended = try self.appendListElement(
            try self.localExpr(list_local, list_ty),
            try self.localExpr(elem_local, elem_ty),
            list_ty,
        );
        const remaining_minus_one = try self.lowLevelExpr(.num_int_sub_wrap, &.{
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            try self.intLiteralExpr(1, ctl.u64_ty),
        }, ctl.u64_ty);
        const continue_body = try self.addExpr(.{ .ty = ret_ty, .data = .{ .continue_ = .{
            .values = try self.addExprSpan(&[_]DraftExprId{
                try self.localExpr(rest_local, state_ty),
                appended,
                try self.localExpr(ctl.counted_local, ctl.bool_ty),
                remaining_minus_one,
            }),
        } } });
        const element_body = try self.sequenceTryRecord(elem_parse, elem_parse_ret_ty, elem_local, value_name, rest_local, rest_name, continue_body, ret_ty);

        const remaining_is_zero = try self.lowLevelExpr(.num_is_eq, &.{
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            try self.intLiteralExpr(0, ctl.u64_ty),
        }, ctl.bool_ty);
        return try self.ifExpr(remaining_is_zero, done_body, element_body, ret_ty);
    }

    fn lowerParseListNextEvent(
        self: *BodyContext,
        elem_ty: Type.TypeId,
        list_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        event_local: DraftLocalId,
        event_ty: Type.TypeId,
        list_local: DraftLocalId,
        ctl: ListLoopCtl,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const item_tag = self.monoTagByText(event_ty, "Item");
        const element_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const element_state_pat = try self.bindPat(element_state_local, state_ty);
        const element_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = item_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{element_state_pat}),
        } } });
        const element_body = try self.lowerParseListElement(
            elem_ty,
            list_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            element_state_local,
            list_local,
            ctl,
            ret_ty,
            precomputed_plan,
        );

        const done_tag = self.monoTagByText(event_ty, "Done");
        const done_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const done_state_pat = try self.bindPat(done_state_local, state_ty);
        const done_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = done_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{done_state_pat}),
        } } });
        const done_value = try self.parseResultOk(
            ret_ty,
            try self.localExpr(list_local, list_ty),
            try self.localExpr(done_state_local, state_ty),
            state_ty,
        );
        const done_body = try self.addExpr(.{ .ty = ret_ty, .data = .{ .break_ = done_value } });

        const branches = [_]DraftBranch{
            .{ .pat = element_pat, .body = element_body },
            .{ .pat = done_pat, .body = done_body },
        };
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(event_local, event_ty),
            .branches = try self.addBranchSpan(&branches),
        } } });
    }

    fn lowerParseListElement(
        self: *BodyContext,
        elem_ty: Type.TypeId,
        list_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        element_state_local: DraftLocalId,
        list_local: DraftLocalId,
        ctl: ListLoopCtl,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const elem_parse_ok_ty = try self.parseResultOkType(elem_ty, state_ty);
        const elem_parse_ret_ty = try self.tryTypeLike(ret_ty, elem_parse_ok_ty, ret_info.err_ty);
        const elem_parse = try self.lowerParseShapeHelperCall(
            elem_ty,
            encoding_expr,
            encoding_ty,
            try self.localExpr(element_state_local, state_ty),
            state_ty,
            elem_parse_ret_ty,
            precomputed_plan,
        );
        const elem_local = try self.addLocal(self.builder.symbols.fresh(), elem_ty);
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const value_name = try self.nameStoreMut().internRecordFieldLabel("value");
        const rest_name = try self.nameStoreMut().internRecordFieldLabel("rest");

        const after_event_ty = try self.parseArrayEventType(state_ty, "Continue", "Done");
        const after_try_ty = try self.tryTypeLike(ret_ty, after_event_ty, ret_info.err_ty);
        const after_try = try self.lowerParseFormatMethod(
            "parse_list_after_item",
            &.{ encoding_expr, try self.localExpr(rest_local, state_ty) },
            &.{ encoding_ty, state_ty },
            list_ty,
            after_try_ty,
        );
        const after_event_local = try self.addLocal(self.builder.symbols.fresh(), after_event_ty);
        const after_body = try self.lowerParseListAfterItemEvent(
            elem_ty,
            list_ty,
            state_ty,
            elem_local,
            list_local,
            after_event_local,
            after_event_ty,
            ctl,
            ret_ty,
        );
        const sequenced_after = try self.sequenceTry(after_try, after_try_ty, after_event_local, after_body, ret_ty);
        return try self.sequenceTryRecord(elem_parse, elem_parse_ret_ty, elem_local, value_name, rest_local, rest_name, sequenced_after, ret_ty);
    }

    fn lowerParseListAfterItemEvent(
        self: *BodyContext,
        elem_ty: Type.TypeId,
        list_ty: Type.TypeId,
        state_ty: Type.TypeId,
        elem_local: DraftLocalId,
        list_local: DraftLocalId,
        event_local: DraftLocalId,
        event_ty: Type.TypeId,
        ctl: ListLoopCtl,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const continue_tag = self.monoTagByText(event_ty, "Continue");
        const continue_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const continue_state_pat = try self.bindPat(continue_state_local, state_ty);
        const continue_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = continue_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{continue_state_pat}),
        } } });
        const continue_appended = try self.appendListElement(
            try self.localExpr(list_local, list_ty),
            try self.localExpr(elem_local, elem_ty),
            list_ty,
        );
        const continue_body = try self.addExpr(.{ .ty = ret_ty, .data = .{ .continue_ = .{
            .values = try self.addExprSpan(&[_]DraftExprId{
                try self.localExpr(continue_state_local, state_ty),
                continue_appended,
                try self.localExpr(ctl.counted_local, ctl.bool_ty),
                try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            }),
        } } });

        const done_tag = self.monoTagByText(event_ty, "Done");
        const done_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const done_state_pat = try self.bindPat(done_state_local, state_ty);
        const done_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = done_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{done_state_pat}),
        } } });
        const done_appended = try self.appendListElement(
            try self.localExpr(list_local, list_ty),
            try self.localExpr(elem_local, elem_ty),
            list_ty,
        );
        const done_value = try self.parseResultOk(ret_ty, done_appended, try self.localExpr(done_state_local, state_ty), state_ty);
        const done_body = try self.addExpr(.{ .ty = ret_ty, .data = .{ .break_ = done_value } });

        const branches = [_]DraftBranch{
            .{ .pat = continue_pat, .body = continue_body },
            .{ .pat = done_pat, .body = done_body },
        };
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(event_local, event_ty),
            .branches = try self.addBranchSpan(&branches),
        } } });
    }

    fn lowerParseBoxFromState(
        self: *BodyContext,
        payload_ty: Type.TypeId,
        box_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const payload_parse_ok_ty = try self.parseResultOkType(payload_ty, state_ty);
        const payload_parse_ret_ty = try self.tryTypeLike(ret_ty, payload_parse_ok_ty, ret_info.err_ty);
        const payload_parse = try self.lowerParseShapeHelperCall(
            payload_ty,
            encoding_expr,
            encoding_ty,
            state_expr,
            state_ty,
            payload_parse_ret_ty,
            precomputed_plan,
        );

        const payload_local = try self.addLocal(self.builder.symbols.fresh(), payload_ty);
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const value_name = try self.nameStoreMut().internRecordFieldLabel("value");
        const rest_name = try self.nameStoreMut().internRecordFieldLabel("rest");
        const boxed_value = try self.lowLevelExpr(.box_box, &.{try self.localExpr(payload_local, payload_ty)}, box_ty);
        const ok_body = try self.parseResultOk(ret_ty, boxed_value, try self.localExpr(rest_local, state_ty), state_ty);
        return try self.sequenceTryRecord(payload_parse, payload_parse_ret_ty, payload_local, value_name, rest_local, rest_name, ok_body, ret_ty);
    }

    fn lowerParseNullTryFromState(
        self: *BodyContext,
        info: TryNullInfo,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const prepared = try self.frozenFormatCodecCall(.parser, "parse_null");
        const parse_null_lookup = prepared.lookup;
        const parse_null_mono_ty = prepared.callable_ty;
        const parse_null_fn = self.functionShape(parse_null_mono_ty, "parse_null target method was not a function");
        const parse_null_arg_tys = self.typeStore().span(parse_null_fn.args);
        if (parse_null_arg_tys.len != 2) Common.invariant("parse_null target method had an unexpected arity");
        if (!self.sameType(GuardedList.at(parse_null_arg_tys, 0), encoding_ty)) Common.invariant("parse_null encoding type differed from input encoding type");
        if (!self.sameType(GuardedList.at(parse_null_arg_tys, 1), state_ty)) Common.invariant("parse_null state type differed from input state type");
        const null_try_ty = parse_null_fn.ret;

        const parse_null_expr = try self.addExpr(.{
            .ty = null_try_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(prepared.callee),
                .args = try self.addExprSpan(&[_]DraftExprId{ encoding_expr, state_expr }),
                .captures = try self.methodTargetCaptureSpan(parse_null_lookup),
            } },
        });

        const null_try_info = self.tryInfo(null_try_ty);
        const null_rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const null_rest_pat = try self.bindPat(null_rest_local, state_ty);
        const null_ok_backing_pat = try self.addPat(.{ .ty = null_try_info.backing_ty, .data = .{ .tag = .{
            .name = null_try_info.ok_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{null_rest_pat}),
        } } });
        const null_ok_pat = try self.addPat(.{ .ty = null_try_ty, .data = .{ .nominal = null_ok_backing_pat } });
        const null_marker = try self.tagUnionValueWithoutPayload(info.err_ty, "Null");
        const null_value = try self.tryErr(shape_ty, null_marker);
        const null_ok_body = try self.parseResultOk(ret_ty, null_value, try self.localExpr(null_rest_local, state_ty), state_ty);

        const child_parse_ok_ty = try self.parseResultOkType(info.ok_payload_ty, state_ty);
        const child_parse_ty = try self.tryTypeLike(ret_ty, child_parse_ok_ty, ret_info.err_ty);
        const child_parse = try self.lowerParseShapeHelperCall(
            info.ok_payload_ty,
            encoding_expr,
            encoding_ty,
            state_expr,
            state_ty,
            child_parse_ty,
            precomputed_plan,
        );
        const value_name = try self.nameStoreMut().internRecordFieldLabel("value");
        const rest_name = try self.nameStoreMut().internRecordFieldLabel("rest");
        const parsed_value_local = try self.addLocal(self.builder.symbols.fresh(), info.ok_payload_ty);
        const parsed_rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const present_value = try self.tryOk(shape_ty, try self.localExpr(parsed_value_local, info.ok_payload_ty));
        const child_ok_body = try self.parseResultOk(ret_ty, present_value, try self.localExpr(parsed_rest_local, state_ty), state_ty);
        const child_body = try self.sequenceTryRecord(child_parse, child_parse_ty, parsed_value_local, value_name, parsed_rest_local, rest_name, child_ok_body, ret_ty);

        const null_err_payload_pat = try self.addPat(.{ .ty = null_try_info.err_ty, .data = .wildcard });
        const null_err_backing_pat = try self.addPat(.{ .ty = null_try_info.backing_ty, .data = .{ .tag = .{
            .name = null_try_info.err_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{null_err_payload_pat}),
        } } });
        const null_err_pat = try self.addPat(.{ .ty = null_try_ty, .data = .{ .nominal = null_err_backing_pat } });

        const branches = [_]DraftBranch{
            .{ .pat = null_ok_pat, .body = null_ok_body },
            .{ .pat = null_err_pat, .body = child_body },
        };
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = parse_null_expr,
            .branches = try self.addBranchSpan(&branches),
        } } });
    }

    fn lowerCustomParserFromState(
        self: *BodyContext,
        prepared: FrozenPreparedCodecCall,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const callable_mono_ty = prepared.callable_ty;
        const parse_fn = self.functionShape(callable_mono_ty, "custom parser target was not a function");
        const parse_arg_tys = self.typeStore().span(parse_fn.args);
        if (parse_arg_tys.len != 1) Common.invariant("custom parser target had an unexpected arity");
        if (!self.sameType(GuardedList.at(parse_arg_tys, 0), encoding_ty)) Common.invariant("custom parser encoding type differed from input encoding type");
        const runtime_fn_ty = parse_fn.ret;
        const runtime_fn = self.functionShape(runtime_fn_ty, "custom parser runtime target was not a function");
        const runtime_arg_tys = self.typeStore().span(runtime_fn.args);
        if (runtime_arg_tys.len != 1 or !self.sameType(GuardedList.at(runtime_arg_tys, 0), state_ty)) {
            Common.invariant("custom parser runtime argument differed from parser state type");
        }
        const source_ret_ty = runtime_fn.ret;

        const source_ret_info = self.tryInfo(source_ret_ty);
        const target_ret_info = self.tryInfo(ret_ty);
        if (!self.sameType(source_ret_info.ok_ty, target_ret_info.ok_ty)) {
            Common.invariant("custom parser result Ok type differed from derived parser result Ok type");
        }
        const parse_ok_fields = switch (self.shapeContent(source_ret_info.ok_ty)) {
            .record => |span| self.typeStore().fieldSpan(span),
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("custom parser result Ok type was not a parse result record"),
        };
        var found_value = false;
        for (0..GuardedList.borrowLen(parse_ok_fields)) |index| {
            const field = GuardedList.at(parse_ok_fields, index);
            const field_text = self.nameStore().recordFieldLabelText(field.name);
            if (Ident.textEql(field_text, "value")) {
                found_value = true;
                if (!self.sameType(field.ty, shape_ty)) Common.invariant("custom parser value type differed from parsed shape");
            }
        }
        if (!found_value) Common.invariant("custom parser result was missing value field");

        const parser_expr = try self.addExpr(.{
            .ty = runtime_fn_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(prepared.callee),
                .args = try self.addExprSpan(&[_]DraftExprId{encoding_expr}),
                .captures = try self.methodTargetCaptureSpan(prepared.lookup),
            } },
        });
        const source_result = try self.addExpr(.{
            .ty = source_ret_ty,
            .data = .{ .call_value = .{
                .callee = parser_expr,
                .args = try self.addExprSpan(&[_]DraftExprId{state_expr}),
            } },
        });
        return try self.injectTryErrorRow(source_result, source_ret_ty, ret_ty);
    }

    fn injectTryErrorRow(
        self: *BodyContext,
        source_expr: DraftExprId,
        source_try_ty: Type.TypeId,
        target_try_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        if (self.sameType(source_try_ty, target_try_ty)) return source_expr;
        const source_info = self.tryInfo(source_try_ty);
        const target_info = self.tryInfo(target_try_ty);
        if (!self.sameType(source_info.ok_ty, target_info.ok_ty)) {
            Common.invariant("parser Try error-row injection changed the Ok type");
        }
        const ok_local = try self.addLocal(self.builder.symbols.fresh(), source_info.ok_ty);
        return try self.sequenceTryTo(
            source_expr,
            source_try_ty,
            ok_local,
            try self.tryOk(target_try_ty, try self.localExpr(ok_local, source_info.ok_ty)),
            target_try_ty,
            null,
        );
    }

    /// Specialization's immutable tag rows are sorted by label. One linear
    /// merge commits their correspondence, which emission reuses directly.
    fn parserErrorRowMapping(self: *BodyContext, source: Type.TypeId, target: Type.TypeId) Allocator.Error![]const u32 {
        const key = ParserErrorRowKey{ .source = source, .target = target };
        if (self.parser_error_rows.get(key)) |mapping| return mapping;
        const source_tags = self.tagUnionTags(source);
        const target_tags = self.tagUnionTags(target);
        const mapping = try self.allocator.alloc(u32, source_tags.len);
        errdefer self.allocator.free(mapping);
        var target_index: usize = 0;
        for (mapping, 0..) |*entry, source_index| {
            const source_tag = GuardedList.at(source_tags, source_index);
            while (target_index < target_tags.len and self.nameStore().tagLabelTextLessThan(GuardedList.at(target_tags, target_index).name, source_tag.name)) : (target_index += 1) {}
            if (target_index == target_tags.len) Common.invariant("parser error row was not included in target");
            const target_tag = GuardedList.at(target_tags, target_index);
            if (source_tag.name != target_tag.name) Common.invariant("parser error row was not included in target");
            const source_payloads = self.typeStore().span(source_tag.payloads);
            const target_payloads = self.typeStore().span(target_tag.payloads);
            if (source_payloads.len != target_payloads.len) Common.invariant("parser error injection changed payload arity");
            for (0..source_payloads.len) |i| {
                if (!self.sameType(GuardedList.at(source_payloads, i), GuardedList.at(target_payloads, i))) Common.invariant("parser error injection changed payload type");
            }
            entry.* = @intCast(target_index);
        }
        try self.parser_error_rows.put(self.allocator, key, mapping);
        return mapping;
    }

    fn injectErrorRow(
        self: *BodyContext,
        source_expr: DraftExprId,
        source_err_ty: Type.TypeId,
        target_err_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        if (self.sameType(source_err_ty, target_err_ty)) return source_expr;

        const mapping = try self.parserErrorRowMapping(source_err_ty, target_err_ty);
        const source_tags = self.tagUnionTags(source_err_ty);
        const target_tags = self.tagUnionTags(target_err_ty);
        if (source_tags.len == 0) Common.invariant("cannot inject an empty parser error row into a different row");
        const branches = try self.allocator.alloc(DraftBranch, source_tags.len);
        defer self.allocator.free(branches);

        for (0..source_tags.len) |tag_index| {
            const source_tag = GuardedList.at(source_tags, tag_index);
            const target_tag = GuardedList.at(target_tags, mapping[tag_index]);
            const source_payload_tys = self.typeStore().span(source_tag.payloads);

            const payload_pats = try self.allocator.alloc(DraftPatId, source_payload_tys.len);
            defer self.allocator.free(payload_pats);
            const payload_exprs = try self.allocator.alloc(DraftExprId, source_payload_tys.len);
            defer self.allocator.free(payload_exprs);
            for (0..source_payload_tys.len) |payload_index| {
                const source_payload_ty = GuardedList.at(source_payload_tys, payload_index);
                const local = try self.addLocal(self.builder.symbols.fresh(), source_payload_ty);
                payload_pats[payload_index] = try self.bindPat(local, source_payload_ty);
                payload_exprs[payload_index] = try self.localExpr(local, source_payload_ty);
            }

            const pat = try self.addPat(.{ .ty = source_err_ty, .data = .{ .tag = .{
                .name = source_tag.name,
                .payloads = try self.addPatSpan(payload_pats),
            } } });
            branches[tag_index] = .{
                .pat = pat,
                .body = try self.tagUnionValue(target_err_ty, target_tag, payload_exprs),
            };
        }

        return try self.addExpr(.{ .ty = target_err_ty, .data = .{ .match_ = .{
            .scrutinee = source_expr,
            .branches = try self.addBranchSpan(branches),
        } } });
    }

    fn parseResultOkType(
        self: *BodyContext,
        value_ty: Type.TypeId,
        rest_ty: Type.TypeId,
    ) Allocator.Error!Type.TypeId {
        const address = GeneratedParseResultOkTypeAddress{
            .value_ty = @backingInt(value_ty),
            .rest_ty = @backingInt(rest_ty),
        };
        if (self.draft.parse_result_ok_types.get(address)) |ty| return ty;

        const rest_name = try self.nameStoreMut().internRecordFieldLabel("rest");
        const value_name = try self.nameStoreMut().internRecordFieldLabel("value");
        const fields = [_]Type.Field{
            .{ .name = rest_name, .ty = rest_ty, .default = null },
            .{ .name = value_name, .ty = value_ty, .default = null },
        };
        const ty = try self.recordType(&fields);
        try self.draft.parse_result_ok_types.put(address, ty);
        return ty;
    }

    fn parseResultOk(
        self: *BodyContext,
        try_ty: Type.TypeId,
        value_expr: DraftExprId,
        rest_expr: DraftExprId,
        rest_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const try_info = self.tryInfo(try_ty);
        const value_ty = try self.exprType(value_expr);
        const rest_name = try self.nameStoreMut().internRecordFieldLabel("rest");
        const value_name = try self.nameStoreMut().internRecordFieldLabel("value");
        const fields = [_]DraftFieldExpr{
            .{ .name = rest_name, .value = rest_expr },
            .{ .name = value_name, .value = value_expr },
        };
        const record_expr = try self.addExpr(.{
            .ty = try_info.ok_ty,
            .data = .{ .record = try self.addFieldExprSpan(&fields) },
        });
        const parse_ok_ty = try self.parseResultOkType(value_ty, rest_ty);
        if (!self.sameType(try_info.ok_ty, parse_ok_ty)) Common.invariant("parse result Ok type differed from generated parse result record");
        return try self.tryOk(try_ty, record_expr);
    }

    fn uninitializedPayloadExpr(self: *BodyContext, ty: Type.TypeId, condition_local: DraftLocalId, condition_mask: u64) Allocator.Error!DraftExprId {
        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .uninitialized_payload = .{ .condition = condition_local, .mask = condition_mask } },
        });
    }

    fn recordPresenceWithBit(
        self: *BodyContext,
        presence_local: DraftLocalId,
        presence_ty: Type.TypeId,
        mask: u64,
    ) Allocator.Error!DraftExprId {
        const current = try self.localExpr(presence_local, presence_ty);
        const bit = try self.intLiteralExpr(mask, presence_ty);
        return try self.lowLevelExpr(.num_bitwise_or, &.{ current, bit }, presence_ty);
    }

    /// The event a variable-length container's `parse_*_start` returns: either
    /// the format declared the entry count up front (`Counted`) or the driver
    /// must ask after every entry whether more follow (`Uncounted`).
    /// `freshParseCountedStartEventVar` in check/Check.zig builds the same row.
    fn parseCountedStartEventType(
        self: *BodyContext,
        state_ty: Type.TypeId,
    ) Allocator.Error!Type.TypeId {
        const len_name = try self.nameStoreMut().internRecordFieldLabel("len");
        const rest_name = try self.nameStoreMut().internRecordFieldLabel("rest");
        const u64_ty = try self.primitiveType(.u64);

        const counted_fields = [_]Type.Field{
            .{ .name = len_name, .ty = u64_ty, .default = null },
            .{ .name = rest_name, .ty = state_ty, .default = null },
        };
        const counted_payload_ty = try self.recordType(&counted_fields);

        const counted_name = try self.nameStoreMut().internTagLabel("Counted");
        const uncounted_name = try self.nameStoreMut().internTagLabel("Uncounted");
        const tags = [_]Type.Store.TagInput{
            .{
                .name = counted_name,
                .checked_name = counted_name,
                .payloads = &.{counted_payload_ty},
            },
            .{
                .name = uncounted_name,
                .checked_name = uncounted_name,
                .payloads = &.{state_ty},
            },
        };
        return try self.tagUnionType(&tags);
    }

    fn parseArrayEventType(
        self: *BodyContext,
        state_ty: Type.TypeId,
        comptime first_tag_text: []const u8,
        comptime second_tag_text: []const u8,
    ) Allocator.Error!Type.TypeId {
        const first_name = try self.nameStoreMut().internTagLabel(first_tag_text);
        const second_name = try self.nameStoreMut().internTagLabel(second_tag_text);
        const tags = [_]Type.Store.TagInput{
            .{
                .name = first_name,
                .checked_name = first_name,
                .payloads = &.{state_ty},
            },
            .{
                .name = second_name,
                .checked_name = second_name,
                .payloads = &.{state_ty},
            },
        };
        return try self.tagUnionType(&tags);
    }

    fn appendListElement(
        self: *BodyContext,
        list_expr: DraftExprId,
        elem_expr: DraftExprId,
        list_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const u64_ty = try self.primitiveType(.u64);
        const reserved = try self.lowLevelExpr(.list_reserve_for_append, &.{ list_expr, try self.intLiteralExpr(1, u64_ty) }, list_ty);
        return try self.lowLevelExpr(.list_append_unsafe, &.{ reserved, elem_expr }, list_ty);
    }

    fn recordEventFieldHandleTemplate(self: *BodyContext, event_ty: Type.TypeId) Allocator.Error!Type.TypeId {
        const field_tag = self.monoTagByText(event_ty, "Field");
        const payload_ty = self.singleTagPayloadType(field_tag, "record parse Field event");
        const field_name = try self.nameStoreMut().internRecordFieldLabel("field");
        return self.recordFieldType(payload_ty, field_name);
    }

    fn singleTagPayloadType(self: *BodyContext, tag: Type.Tag, comptime context: []const u8) Type.TypeId {
        const payloads = self.typeStore().span(tag.payloads);
        if (payloads.len != 1) Common.invariant(context ++ " had an unexpected payload count");
        return GuardedList.at(payloads, 0);
    }

    fn recordPayloadFieldAccess(
        self: *BodyContext,
        payload_local: DraftLocalId,
        payload_ty: Type.TypeId,
        comptime field_text: []const u8,
    ) Allocator.Error!DraftExprId {
        const field_name = try self.nameStoreMut().internRecordFieldLabel(field_text);
        const field_ty = self.recordFieldType(payload_ty, field_name);
        return try self.addFieldAccessExpr(
            try self.localExpr(payload_local, payload_ty),
            field_name,
            field_ty,
        );
    }

    fn finishGeneratedRecordSlots(
        self: *BodyContext,
        record_slots: ParseRecordSlots,
        record_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        renamed_field_locals: []const DraftLocalId,
        error_join: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        if (!self.sameType(ret_info.ok_ty, record_ty)) Common.invariant("record finish Try Ok type differed from record type");

        const record_fields = try GuardedList.dupe(self.allocator, Type.Field, switch (self.shapeContent(record_ty)) {
            .record => |span| self.typeStore().fieldSpan(span),
            .zst => self.typeStore().fieldSpan(.empty()),
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased => Common.invariant("record finish Ok type was not a record"),
        });
        defer self.allocator.free(record_fields);
        if (record_fields.len != record_slots.fieldCount()) Common.invariant("record parse state arity did not match finish record field count");
        if (record_fields.len != renamed_field_locals.len) Common.invariant("record parse renamed field arity did not match finish record field count");

        const out_fields = try self.allocator.alloc(DraftFieldExpr, record_fields.len);
        defer self.allocator.free(out_fields);
        const field_locals = try self.allocator.alloc(DraftLocalId, record_fields.len);
        defer self.allocator.free(field_locals);
        for (record_fields, 0..) |field, index| {
            field_locals[index] = try self.addLocal(self.builder.symbols.fresh(), field.ty);
            out_fields[index] = .{
                .name = field.name,
                .value = try self.localExpr(field_locals[index], field.ty),
            };
        }

        const record_expr = try self.addExpr(.{
            .ty = ret_info.ok_ty,
            .data = .{ .record = try self.addFieldExprSpan(out_fields) },
        });
        var body = try self.tryOk(ret_ty, record_expr);
        var field_index = record_fields.len;
        while (field_index > 0) {
            field_index -= 1;
            const maybe_default = self.parserFieldDefaultFor(record_ty, record_fields[field_index].name);
            const field_can_be_missing = (try self.missingTryInfo(record_fields[field_index].ty)) != null or
                self.optionalFieldSlot(record_fields[field_index].ty) != null or
                maybe_default != null;
            body = if (maybe_default) |default|
                try self.finishDefaultedRecordFieldFromPresencePayload(
                    body,
                    ret_ty,
                    record_slots,
                    record_fields[field_index],
                    field_index,
                    field_locals[field_index],
                    default,
                )
            else if (field_can_be_missing)
                try self.finishOptionalRecordFieldFromPresencePayload(
                    body,
                    ret_ty,
                    record_slots,
                    record_fields[field_index],
                    field_index,
                    field_locals[field_index],
                )
            else
                try self.wrapLet(
                    field_locals[field_index],
                    record_fields[field_index].ty,
                    try self.localExpr(record_slots.payload_locals[field_index], record_slots.payload_tys[field_index]),
                    body,
                    ret_ty,
                );
        }

        // Validate every required presence bit before consuming any payload.
        // Consequently every failure edge reaches the shared error body with
        // the same ownership environment, and ARC emits its O(N) cleanup once.
        field_index = record_fields.len;
        while (field_index > 0) {
            field_index -= 1;
            const field = record_fields[field_index];
            const field_can_be_missing = (try self.missingTryInfo(field.ty)) != null or
                self.optionalFieldSlot(field.ty) != null or
                self.parserFieldDefaultFor(record_ty, field.name) != null;
            if (field_can_be_missing) continue;

            const renamed_field_ty = try self.localType(renamed_field_locals[field_index]);
            const missing_error = try self.missingRequiredFieldError(
                try self.localExpr(renamed_field_locals[field_index], renamed_field_ty),
                ret_info.err_ty,
            );
            const missing_body = try self.jumpToGeneratedJoin(
                error_join,
                &.{missing_error},
                &.{},
                &.{},
                ret_ty,
            );
            const presence_word = recordPresenceWordIndex(field_index);
            body = try self.addExpr(.{ .ty = ret_ty, .data = .{ .if_initialized_payload = .{
                .cond = try self.localExpr(record_slots.presence_locals[presence_word], record_slots.presence_tys[presence_word]),
                .cond_mask = recordPresenceMask(field_index),
                .payload = record_slots.payload_locals[field_index],
                .uninitialized_is_cold = true,
                .initialized = body,
                .uninitialized = missing_body,
            } } });
        }
        return body;
    }

    const ParseShapeSelection = struct {
        tag_text: []const u8,
    };

    fn parseShapeSelection(self: *BodyContext, shape_ty: Type.TypeId) ParseShapeSelection {
        if (self.scalarCodecMethodName(shape_ty, "parse_")) |method_name| return .{ .tag_text = method_name };
        return switch (self.shapeContent(shape_ty)) {
            .record, .zst => .{ .tag_text = "Record" },
            .tag_union => .{ .tag_text = "TagUnion" },
            .primitive, .named, .tuple, .list, .box, .func, .erased => Common.invariant("parser shape was not supported"),
        };
    }

    fn lowerParseTagUnionDecode(
        self: *BodyContext,
        args: []const checked.CheckedExprId,
        arg_tys: []const Type.TypeId,
        ret_ty: Type.TypeId,
        lowered_args: []const DraftExprId,
    ) Allocator.Error!DraftExprId {
        if (args.len != 2 or arg_tys.len != 2) Common.invariant("ParseTagUnionSpec.parse reached Monotype with an unexpected arity");
        const ret_info = self.tryInfo(ret_ty);

        const value_name = try self.nameStoreMut().internRecordFieldLabel("value");
        const value_ty = self.recordFieldType(ret_info.ok_ty, value_name);
        const tag_span = switch (self.shapeContent(value_ty)) {
            .tag_union => |span| span,
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => Common.invariant("ParseTagUnionSpec.parse value type was not a tag union"),
        };
        const spec_ty = arg_tys[0];
        const spec_value = lowered_args[0];
        const options_value = lowered_args[1];
        const options_ty = arg_tys[1];
        const key_ty = self.recordFieldType(options_ty, try self.nameStoreMut().internRecordFieldLabel("tag"));
        const encoding_ty = self.recordFieldType(options_ty, try self.nameStoreMut().internRecordFieldLabel("encoding"));
        const state_ty = self.recordFieldType(options_ty, try self.nameStoreMut().internRecordFieldLabel("state"));
        const start_payloads_ty = self.recordFieldType(options_ty, try self.nameStoreMut().internRecordFieldLabel("start_payloads"));
        const next_payload_ty = self.recordFieldType(options_ty, try self.nameStoreMut().internRecordFieldLabel("next_payload"));
        const finish_payloads_ty = self.recordFieldType(options_ty, try self.nameStoreMut().internRecordFieldLabel("finish_payloads"));
        const missing_ty = self.recordFieldType(options_ty, try self.nameStoreMut().internRecordFieldLabel("missing"));

        const options_local = try self.addLocal(self.builder.symbols.fresh(), options_ty);
        const key_value = try self.recordPayloadFieldAccess(options_local, options_ty, "tag");
        const encoding_value = try self.recordPayloadFieldAccess(options_local, options_ty, "encoding");
        const slot_value = try self.recordPayloadFieldAccess(options_local, options_ty, "state");
        const start_payloads_value = try self.recordPayloadFieldAccess(options_local, options_ty, "start_payloads");
        const next_payload_value = try self.recordPayloadFieldAccess(options_local, options_ty, "next_payload");
        const finish_payloads_value = try self.recordPayloadFieldAccess(options_local, options_ty, "finish_payloads");
        const missing_value = try self.recordPayloadFieldAccess(options_local, options_ty, "missing");

        const key_local = try self.addLocal(self.builder.symbols.fresh(), key_ty);
        const encoding_local = try self.addLocal(self.builder.symbols.fresh(), encoding_ty);
        const slot_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const start_payloads_local = try self.addLocal(self.builder.symbols.fresh(), start_payloads_ty);
        const next_payload_local = try self.addLocal(self.builder.symbols.fresh(), next_payload_ty);
        const finish_payloads_local = try self.addLocal(self.builder.symbols.fresh(), finish_payloads_ty);
        const missing_local = try self.addLocal(self.builder.symbols.fresh(), missing_ty);
        const tags = try GuardedList.dupe(self.allocator, Type.Tag, self.typeStore().tagSpan(tag_span));
        defer self.allocator.free(tags);

        var precomputed_plan = ParserPrecomputedPlan.init(self.allocator);
        defer precomputed_plan.deinit();
        const maybe_spec_backing_ty = if (self.generatedParseTagUnionSpecBackingInfo(spec_ty) != null)
            self.namedBackingType(spec_ty) orelse Common.invariant("generated tag-union spec had no backing type")
        else
            null;
        const spec_local = if (maybe_spec_backing_ty != null)
            try self.addLocal(self.builder.symbols.fresh(), spec_ty)
        else
            null;
        const spec_backing_local = if (maybe_spec_backing_ty) |spec_backing_ty| blk: {
            const local = try self.addLocal(self.builder.symbols.fresh(), spec_backing_ty);
            try self.buildParserPrecomputedPlanFromTagUnionSpec(&precomputed_plan, local, spec_backing_ty, value_ty);
            break :blk local;
        } else null;

        var body = try self.unknownDecodedTagErr(ret_ty, missing_local, missing_ty);
        var index = tags.len;
        while (index > 0) {
            index -= 1;
            const tag_expr = try self.decodedTagUnionValue(
                tags[index],
                value_ty,
                ret_ty,
                encoding_local,
                encoding_ty,
                slot_local,
                state_ty,
                start_payloads_local,
                start_payloads_ty,
                next_payload_local,
                next_payload_ty,
                finish_payloads_local,
                finish_payloads_ty,
                // A spec with no record shapes precomputes nothing, which is an
                // empty plan: nested tag-union payloads still build their own
                // specs from it.
                &precomputed_plan,
            );
            const cond = try self.parseTagExactMatch(key_local, key_ty, tags[index]);
            body = try self.ifExpr(cond, tag_expr, body, ret_ty);
        }

        body = try self.wrapLet(missing_local, missing_ty, missing_value, body, ret_ty);
        body = try self.wrapLet(finish_payloads_local, finish_payloads_ty, finish_payloads_value, body, ret_ty);
        body = try self.wrapLet(next_payload_local, next_payload_ty, next_payload_value, body, ret_ty);
        body = try self.wrapLet(start_payloads_local, start_payloads_ty, start_payloads_value, body, ret_ty);
        body = try self.wrapLet(slot_local, state_ty, slot_value, body, ret_ty);
        body = try self.wrapLet(encoding_local, encoding_ty, encoding_value, body, ret_ty);
        body = try self.wrapLet(key_local, key_ty, key_value, body, ret_ty);
        body = try self.wrapLet(options_local, options_ty, options_value, body, ret_ty);
        if (maybe_spec_backing_ty) |spec_backing_ty| {
            var capture_index = precomputed_plan.captures.items.len;
            while (capture_index > 0) {
                capture_index -= 1;
                const capture = precomputed_plan.captures.items[capture_index];
                body = try self.wrapLet(capture.local, try self.primitiveType(.str), capture.value, body, ret_ty);
            }
            const backing_local = spec_backing_local orelse Common.invariant("generated tag-union spec backing local was missing");
            const spec_pat = try self.addPat(.{
                .ty = spec_ty,
                .data = .{ .nominal = try self.bindPat(backing_local, spec_backing_ty) },
            });
            const branch = DraftBranch{ .pat = spec_pat, .body = body };
            const matched = try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
                .scrutinee = try self.localExpr(spec_local orelse Common.invariant("generated tag-union spec local was missing"), spec_ty),
                .branches = try self.addBranchSpan(&[_]DraftBranch{branch}),
            } } });
            return try self.wrapLet(spec_local orelse Common.invariant("generated tag-union spec local was missing"), spec_ty, spec_value, matched, ret_ty);
        }
        return try self.wrapWildcardLet(arg_tys[0], spec_value, body, ret_ty);
    }

    fn decodedTagUnionValue(
        self: *BodyContext,
        tag: Type.Tag,
        union_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        encoding_local: DraftLocalId,
        encoding_ty: Type.TypeId,
        slot_local: DraftLocalId,
        slot_ty: Type.TypeId,
        start_payloads_local: DraftLocalId,
        start_payloads_ty: Type.TypeId,
        next_payload_local: DraftLocalId,
        next_payload_ty: Type.TypeId,
        finish_payloads_local: DraftLocalId,
        finish_payloads_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const payload_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(tag.payloads));
        defer self.allocator.free(payload_tys);
        const payload_locals = try self.allocator.alloc(DraftLocalId, payload_tys.len);
        defer self.allocator.free(payload_locals);
        for (payload_tys, 0..) |payload_ty, index| {
            payload_locals[index] = try self.addLocal(self.builder.symbols.fresh(), payload_ty);
        }
        const boundary_try_ty = try self.tryTypeLike(ret_ty, slot_ty, ret_info.err_ty);
        const u64_ty = try self.primitiveType(.u64);
        const count_expr = try self.intLiteralExpr(@intCast(payload_tys.len), u64_ty);
        self.assertTagPayloadBoundaryType(start_payloads_ty, &.{ slot_ty, u64_ty }, boundary_try_ty);
        self.assertTagPayloadBoundaryType(next_payload_ty, &.{ slot_ty, u64_ty, u64_ty }, boundary_try_ty);
        self.assertTagPayloadBoundaryType(finish_payloads_ty, &.{ slot_ty, u64_ty }, boundary_try_ty);

        const started_try = try self.addExpr(.{
            .ty = boundary_try_ty,
            .data = .{ .call_value = .{
                .callee = try self.localExpr(start_payloads_local, start_payloads_ty),
                .args = try self.addExprSpan(&[_]DraftExprId{
                    try self.localExpr(slot_local, slot_ty),
                    count_expr,
                }),
            } },
        });
        const started_local = try self.addLocal(self.builder.symbols.fresh(), slot_ty);
        const body = try self.decodedTagPayloadsFromState(
            tag,
            union_ty,
            ret_ty,
            encoding_local,
            encoding_ty,
            try self.localExpr(started_local, slot_ty),
            slot_ty,
            payload_tys,
            payload_locals,
            0,
            next_payload_local,
            next_payload_ty,
            finish_payloads_local,
            finish_payloads_ty,
            count_expr,
            boundary_try_ty,
            precomputed_plan,
        );
        return try self.sequenceTry(started_try, boundary_try_ty, started_local, body, ret_ty);
    }

    fn assertTagPayloadBoundaryType(
        self: *BodyContext,
        fn_ty: Type.TypeId,
        expected_args: []const Type.TypeId,
        expected_ret: Type.TypeId,
    ) void {
        const fn_shape = self.functionShape(fn_ty, "tag payload boundary was not a function");
        const args = self.typeStore().span(fn_shape.args);
        if (args.len != expected_args.len) Common.invariant("tag payload boundary had an unexpected arity");
        for (expected_args, 0..) |expected, index| {
            if (!self.sameType(GuardedList.at(args, index), expected)) Common.invariant("tag payload boundary argument type differed from expected type");
        }
        if (!self.sameType(fn_shape.ret, expected_ret)) Common.invariant("tag payload boundary return type differed from expected type");
    }

    fn decodedTagPayloadsFromState(
        self: *BodyContext,
        tag: Type.Tag,
        union_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        encoding_local: DraftLocalId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        payload_tys: []const Type.TypeId,
        payload_locals: []const DraftLocalId,
        payload_index: usize,
        next_payload_local: DraftLocalId,
        next_payload_ty: Type.TypeId,
        finish_payloads_local: DraftLocalId,
        finish_payloads_ty: Type.TypeId,
        count_expr: DraftExprId,
        boundary_try_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        if (payload_index == payload_tys.len) {
            const payloads = try self.allocator.alloc(DraftExprId, payload_tys.len);
            defer self.allocator.free(payloads);
            for (payload_tys, 0..) |payload_ty, index| {
                payloads[index] = try self.localExpr(payload_locals[index], payload_ty);
            }
            const tag_expr = try self.tagUnionValue(union_ty, tag, payloads);
            const finished_try = try self.addExpr(.{
                .ty = boundary_try_ty,
                .data = .{ .call_value = .{
                    .callee = try self.localExpr(finish_payloads_local, finish_payloads_ty),
                    .args = try self.addExprSpan(&[_]DraftExprId{ state_expr, count_expr }),
                } },
            });
            const finished_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
            const finished = try self.parseResultOk(ret_ty, tag_expr, try self.localExpr(finished_local, state_ty), state_ty);
            return try self.sequenceTry(finished_try, boundary_try_ty, finished_local, finished, ret_ty);
        }

        const ret_info = self.tryInfo(ret_ty);
        const payload_ty = payload_tys[payload_index];
        const payload_ok_ty = try self.parseResultOkType(payload_ty, state_ty);
        const payload_try_ty = try self.tryTypeLike(ret_ty, payload_ok_ty, ret_info.err_ty);
        const payload_try = try self.lowerParseShapeHelperCall(
            payload_ty,
            try self.localExpr(encoding_local, encoding_ty),
            encoding_ty,
            state_expr,
            state_ty,
            payload_try_ty,
            precomputed_plan,
        );
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const rest_expr = try self.localExpr(rest_local, state_ty);
        const next_body = if (payload_index + 1 < payload_tys.len) blk: {
            const u64_ty = try self.primitiveType(.u64);
            const next_try = try self.addExpr(.{
                .ty = boundary_try_ty,
                .data = .{ .call_value = .{
                    .callee = try self.localExpr(next_payload_local, next_payload_ty),
                    .args = try self.addExprSpan(&[_]DraftExprId{
                        rest_expr,
                        try self.intLiteralExpr(@intCast(payload_index + 1), u64_ty),
                        count_expr,
                    }),
                } },
            });
            const next_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
            const body = try self.decodedTagPayloadsFromState(
                tag,
                union_ty,
                ret_ty,
                encoding_local,
                encoding_ty,
                try self.localExpr(next_local, state_ty),
                state_ty,
                payload_tys,
                payload_locals,
                payload_index + 1,
                next_payload_local,
                next_payload_ty,
                finish_payloads_local,
                finish_payloads_ty,
                count_expr,
                boundary_try_ty,
                precomputed_plan,
            );
            break :blk try self.sequenceTry(next_try, boundary_try_ty, next_local, body, ret_ty);
        } else try self.decodedTagPayloadsFromState(
            tag,
            union_ty,
            ret_ty,
            encoding_local,
            encoding_ty,
            rest_expr,
            state_ty,
            payload_tys,
            payload_locals,
            payload_index + 1,
            next_payload_local,
            next_payload_ty,
            finish_payloads_local,
            finish_payloads_ty,
            count_expr,
            boundary_try_ty,
            precomputed_plan,
        );
        const value_name = try self.nameStoreMut().internRecordFieldLabel("value");
        const rest_name = try self.nameStoreMut().internRecordFieldLabel("rest");
        return try self.sequenceTryRecord(
            payload_try,
            payload_try_ty,
            payload_locals[payload_index],
            value_name,
            rest_local,
            rest_name,
            next_body,
            ret_ty,
        );
    }

    fn tagUnionValue(
        self: *BodyContext,
        ret_ty: Type.TypeId,
        tag: Type.Tag,
        payloads: []const DraftExprId,
    ) Allocator.Error!DraftExprId {
        const backing_ty = self.namedBackingType(ret_ty);
        const tag_ty = backing_ty orelse ret_ty;
        const backing_expr = try self.addExpr(.{
            .ty = tag_ty,
            .data = .{ .tag = .{
                .name = tag.name,
                .payloads = try self.addExprSpan(payloads),
            } },
        });
        if (backing_ty == null) return backing_expr;
        return try self.addExpr(.{
            .ty = ret_ty,
            .data = .{ .nominal = backing_expr },
        });
    }

    fn unknownDecodedTagErr(
        self: *BodyContext,
        ret_ty: Type.TypeId,
        missing_local: DraftLocalId,
        missing_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.tryErr(ret_ty, try self.localExpr(missing_local, missing_ty));
    }

    fn parseTagExactMatch(
        self: *BodyContext,
        key_local: DraftLocalId,
        key_ty: Type.TypeId,
        tag: Type.Tag,
    ) Allocator.Error!DraftExprId {
        if (!self.typeHasBuiltinOwner(key_ty, .str)) Common.invariant("ParseTagUnionSpec.parse key was not Str");
        const tag_text = self.nameStore().tagLabelText(tag.name);
        const tag_expr = try self.stringExpr(tag_text, key_ty);
        const key_expr = try self.localExpr(key_local, key_ty);
        return try self.lowLevelExpr(.str_is_eq, &.{ key_expr, tag_expr }, try self.primitiveType(.bool));
    }

    fn recordFieldNameExactMatch(
        self: *BodyContext,
        key_local: DraftLocalId,
        key_ty: Type.TypeId,
        field_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const key_expr = try self.localExpr(key_local, key_ty);
        return try self.lowLevelExpr(.str_is_eq, &.{ key_expr, field_expr }, try self.primitiveType(.bool));
    }

    fn recordFieldNameStaticSmallExactMatch(
        self: *BodyContext,
        key_local: DraftLocalId,
        key_ty: Type.TypeId,
        field_text: []const u8,
    ) Allocator.Error!DraftExprId {
        if (field_text.len > 24) Common.invariant("static small field match requested for a long field name");

        var words = [3]u64{ 0, 0, 0 };
        for (field_text, 0..) |byte, index| {
            words[index / @sizeOf(u64)] |= @as(u64, byte) << @intCast((index % @sizeOf(u64)) * 8);
        }

        const u64_ty = try self.primitiveType(.u64);
        const key_expr = try self.localExpr(key_local, key_ty);
        const args = [_]DraftExprId{
            key_expr,
            try self.intLiteralExpr(@intCast(field_text.len), u64_ty),
            try self.intLiteralExpr(words[0], u64_ty),
            try self.intLiteralExpr(words[1], u64_ty),
            try self.intLiteralExpr(words[2], u64_ty),
        };
        return try self.lowLevelExpr(.str_is_eq_static_small, &args, try self.primitiveType(.bool));
    }

    fn recordFieldNameStaticSmallWordMatch(
        self: *BodyContext,
        comptime caseless: bool,
        key_local: DraftLocalId,
        key_ty: Type.TypeId,
        field_text: []const u8,
        offset: u32,
        active_len: u32,
    ) Allocator.Error!DraftExprId {
        if (field_text.len > 24) Common.invariant(if (caseless) "static small caseless field lane requested for a long field name" else "static small field lane requested for a long field name");
        const word = staticFieldLaneWord(field_text, offset, active_len);

        const u64_ty = try self.primitiveType(.u64);
        const key_expr = try self.localExpr(key_local, key_ty);
        const args = [_]DraftExprId{
            key_expr,
            try self.intLiteralExpr(offset, u64_ty),
            try self.intLiteralExpr(active_len, u64_ty),
            try self.intLiteralExpr(word, u64_ty),
        };
        return try self.lowLevelExpr(if (caseless) .str_static_small_word_caseless_eq else .str_static_small_word_eq, &args, try self.primitiveType(.bool));
    }

    fn recordFieldNameStaticSmallCaselessMatch(
        self: *BodyContext,
        key_local: DraftLocalId,
        key_ty: Type.TypeId,
        field_text: []const u8,
    ) Allocator.Error!DraftExprId {
        if (field_text.len > 24) Common.invariant("static small caseless field match requested for a long field name");

        const bool_ty = try self.primitiveType(.bool);
        var body = try self.boolLiteral(true, bool_ty);
        var offset: u32 = @intCast(((field_text.len + 7) / 8) * 8);
        while (offset > 0) {
            offset -= 8;
            const remaining: u32 = @intCast(field_text.len - offset);
            const active_len: u32 = @min(remaining, 8);
            const cond = try self.recordFieldNameStaticSmallWordMatch(true, key_local, key_ty, field_text, offset, active_len);
            body = try self.ifExpr(cond, body, try self.boolLiteral(false, bool_ty), bool_ty);
        }

        const u64_ty = try self.primitiveType(.u64);
        const key_expr = try self.localExpr(key_local, key_ty);
        const key_len_expr = try self.lowLevelExpr(.str_count_utf8_bytes, &.{key_expr}, u64_ty);
        const length_expr = try self.intLiteralExpr(@intCast(field_text.len), u64_ty);
        const length_matches = try self.lowLevelExpr(.num_is_eq, &.{ key_len_expr, length_expr }, bool_ty);
        return try self.ifExpr(length_matches, body, try self.boolLiteral(false, bool_ty), bool_ty);
    }

    fn renamedRecordFieldNameExpr(
        self: *BodyContext,
        kind: CodecKind,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        field: Type.Field,
        str_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const field_text = self.nameStore().recordFieldLabelText(field.name);
        const field_expr = try self.stringExpr(field_text, str_ty);
        const prepared = try self.frozenFormatCodecCall(kind, "rename_field");
        const lookup = prepared.lookup;
        const callable_mono_ty = prepared.callable_ty;
        const rename_fn = self.functionShape(callable_mono_ty, "rename_field target method was not a function");
        const arg_tys = self.typeStore().span(rename_fn.args);
        if (arg_tys.len != 2) Common.invariant("rename_field target method had an unexpected arity");
        if (!self.sameType(GuardedList.at(arg_tys, 0), encoding_ty)) Common.invariant("rename_field encoding argument differed from parser encoding type");
        if (!self.sameType(GuardedList.at(arg_tys, 1), str_ty)) Common.invariant("rename_field name argument differed from Str");
        if (!self.sameType(rename_fn.ret, str_ty)) Common.invariant("rename_field return type differed from Str");
        return try self.addExpr(.{
            .ty = str_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(prepared.callee),
                .args = try self.addExprSpan(&[_]DraftExprId{ encoding_expr, field_expr }),
