        // mirroring `lookupExprTypeNode`'s const arms.
        const const_use: ?checked.ConstUseTemplate = switch (record.ref) {
            .top_level_const, .imported_const => |const_use| const_use,
            .platform_required_const => |required| required.const_use,
            .selected_hoisted_const, .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_proc, .promoted_top_level_proc => null,
        };
        if (const_use) |use| {
            const node = try self.constUseTypeNode(checked_ty, use);
            if (try self.graph.containsGeneratedPrivate(node)) return node;
        }
        return if (try self.lookupCallArgumentMonoType(checked_ty, maybe_ref, expected_ty)) |ty|
            try self.activeNodeFromType(ty)
        else
            null;
    }

    fn lookupCallArgumentMonoType(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        maybe_ref: ?checked.ResolvedValueId,
        expected_ty: ?Type.TypeId,
    ) Allocator.Error!?Type.TypeId {
        const ref_id = maybe_ref orelse Common.invariant("checked lookup reached Monotype without resolved value ref");
        const record = self.view.resolved_refs.records[@backingInt(ref_id)];
        switch (record.ref) {
            .selected_hoisted_const => |selected| {
                // A selected hoisted constant's binder has a local only while
                // its own root is lowered or while a recursive restore of the
                // constant is active; every other use consumes the
                // checker-selected ConstStore entry directly.
                if (self.binders.get(selected.local.binder) == null) {
                    if (try self.selectedHoistedConstMonoType(selected, checked_ty)) |ty| return ty;
                }
            },
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .top_level_const, .imported_const, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_const, .platform_required_proc, .promoted_top_level_proc => {},
        }
        if ((try self.currentLocalForResolvedValue(ref_id)) != null) {
            return try self.localCallArgumentEvidenceType(checked_ty, ref_id, expected_ty);
        }
        return switch (record.ref) {
            .top_level_const,
            .imported_const,
            .platform_required_const,
            .local_proc,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_proc,
            .promoted_top_level_proc,
            => null,
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .platform_required_declaration, .platform_required_checked_error => try self.lookupExprMonoType(checked_ty, ref_id),
        };
    }

    fn localCallArgumentEvidenceType(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        ref_id: checked.ResolvedValueId,
        expected_ty: ?Type.TypeId,
    ) Allocator.Error!?Type.TypeId {
        const node = (try self.localCallArgumentEvidenceNode(checked_ty, ref_id, expected_ty)) orelse
            return expected_ty;
        return try self.activeTypeFromNode(node);
    }

    /// Constrain a local call argument's cell and return its evidence node
    /// when the local carries generated-private content; otherwise the
    /// caller's expected type (if any) is the evidence.
    fn localCallArgumentEvidenceNode(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        ref_id: checked.ResolvedValueId,
        expected_ty: ?Type.TypeId,
    ) Allocator.Error!?NodeId {
        const local_id = (try self.currentLocalForResolvedValue(ref_id)) orelse
            Common.invariant("local call argument evidence requested without a current local");
        const cell = self.localTypeCell(local_id);
        const node = switch (cell) {
            .graph_node => |graph_node| graph_node,
            .sealed => |ty| try self.activeNodeFromType(ty),
        };
        try self.constrainCheckedInterfaceToCell(checked_ty, cell);
        if (expected_ty) |expected| try self.graph.unify(node, try self.graph.importMono(expected));
        return if (try self.graph.containsGeneratedPrivate(node)) node else null;
    }

    fn lookupExprTypeNode(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        maybe_ref: ?checked.ResolvedValueId,
    ) Allocator.Error!NodeId {
        const ref_id = maybe_ref orelse
            Common.invariant("checked lookup reached Monotype without a resolved value ref");
        if (self.currentLocalBindingForResolvedValue(ref_id)) |binding| {
            const local_id = binding.local;
            const node = switch (self.localTypeCell(local_id)) {
                .graph_node => |graph_node| graph_node,
                .sealed => |ty| try self.activeNodeFromType(ty),
            };
            try self.constrainCheckedInterfaceToCell(checked_ty, self.localTypeCell(local_id));
            return node;
        }
        const record = self.view.resolved_refs.records[@backingInt(ref_id)];
        switch (record.ref) {
            .selected_hoisted_const => |selected| return try self.constUseTypeNode(checked_ty, selected.const_use),
            .top_level_const, .imported_const => |const_use| return try self.constUseTypeNode(checked_ty, const_use),
            .platform_required_const => |required| return try self.constUseTypeNode(checked_ty, required.const_use),
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_proc, .promoted_top_level_proc => {},
        }
        return try self.lowerTypeNode(checked_ty);
    }

    fn lookupExprMonoType(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        maybe_ref: ?checked.ResolvedValueId,
    ) Allocator.Error!Type.TypeId {
        const ref_id = maybe_ref orelse Common.invariant("checked lookup reached Monotype without resolved value ref");
        const record = self.view.resolved_refs.records[@backingInt(ref_id)];
        switch (record.ref) {
            .local_value,
            .pattern_binder,
            => {},
            .selected_hoisted_const => |selected| {
                // A local for the binder is consumed instead of the constant
                // (see `lookupCallArgumentMonoType`).
                if (self.binders.get(selected.local.binder) == null) {
                    if (try self.selectedHoistedConstMonoType(selected, checked_ty)) |ty| return ty;
                }
            },
            .local_param,
            .local_mutable_version,
            .local_proc,
            .top_level_const,
            .imported_const,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            .platform_required_proc,
            .promoted_top_level_proc,
            => {},
        }
        if (try self.currentLocalForResolvedValue(ref_id)) |local_id| {
            const local_ty = try self.localType(local_id);
            try self.relateCheckedTypeToMono(checked_ty, local_ty);
            return local_ty;
        }
        return switch (record.ref) {
            .top_level_const, .imported_const => |const_use| try self.constUseMonoType(const_use),
            .platform_required_const => |required| try self.constUseMonoType(required.const_use),
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .selected_hoisted_const,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_proc,
            .promoted_top_level_proc,
            => try self.lowerTypeView(checked_ty),
        };
    }

    fn fieldAccessTypeNode(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        access: anytype,
        expected_ty: ?Type.TypeId,
    ) Allocator.Error!NodeId {
        return (try self.runEvidence(.{ .field_access = .{ .checked_ty = checked_ty, .access = access, .expected_ty = expected_ty } })).nodeValue();
    }

    fn tupleAccessTypeNode(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        tuple: checked.CheckedExprId,
        elem_index: usize,
        expected_ty: ?Type.TypeId,
    ) Allocator.Error!NodeId {
        return (try self.runEvidence(.{ .tuple_access = .{ .checked_ty = checked_ty, .tuple = tuple, .elem_index = elem_index, .expected_ty = expected_ty } })).nodeValue();
    }

    /// The Ok type argument of a checked nominal `Try` type (behind
    /// transparent aliases)—the type the checker gave an optional access
    /// chain's successful value.
    fn checkedTryOkArg(self: *BodyContext, checked_try_ty: checked.CheckedTypeId) checked.CheckedTypeId {
        var current = checked_try_ty;
        while (true) {
            switch (checkedPayload(self.view, current)) {
                .alias => |alias| current = alias.backing,
                .nominal => |nominal| {
                    if (nominal.args.len != 2) {
                        Common.invariant("optional access chain's checked Try type did not carry two type arguments");
                    }
                    return nominal.args[0];
                },
                .pending, .err, .flex, .rigid, .record, .tuple, .function, .empty_record, .tag_union, .empty_tag_union => Common.invariant("optional access chain's checked type was not a nominal Try"),
            }
        }
    }

    fn callResultMonoType(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        checked_ret_ty: checked.CheckedTypeId,
        call: anytype,
        expected_ret_ty: ?Type.TypeId,
    ) Allocator.Error!?Type.TypeId {
        const ret_node = try self.callResultTypeNode(checked_expr, checked_ret_ty, call, expected_ret_ty);
        if (expected_ret_ty) |expected| return expected;
        return try self.activeTypeFromNode(ret_node);
    }

    fn callResultTypeNode(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        checked_ret_ty: checked.CheckedTypeId,
        call: anytype,
        expected_ret_ty: ?Type.TypeId,
    ) Allocator.Error!NodeId {
        return (try self.runEvidence(.{ .call_result = .{ .expr = checked_expr, .checked_ret_ty = checked_ret_ty, .call = call, .expected_ret_ty = expected_ret_ty } })).nodeValue();
    }

    /// The request interface of a direct call expression, instantiated once
    /// per instantiation scope and shared by later reads of that expression (see
    /// `DirectCallRequest`). A later read that carries an expected result
    /// cell relates it to the shared request exactly as a fresh
    /// instantiation would. Requests whose interface depends on the read
    /// itself are never shared: an iterator procedure's request may be
    /// replaced by a generated private interface chosen from the argument
    /// evidence, a hosted `Try` request may be widened by the expected
    /// result's error labels, and an expected cell carrying generated-private
    /// evidence becomes the request's own result.
    fn directCallRequestNode(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        target: checked.ResolvedValueId,
        call: anytype,
        checked_ret_ty: checked.CheckedTypeId,
        source_fn_ty: checked.CheckedTypeId,
        expected_ret_node: ?NodeId,
    ) Allocator.Error!NodeId {
        return (try self.runEvidence(.{ .direct_call_request = .{ .expr = checked_expr, .target = target, .call = call, .checked_ret_ty = checked_ret_ty, .source_fn_ty = source_fn_ty, .expected_ret_node = expected_ret_node } })).nodeValue();
    }

    fn directCallRequestIsShareable(
        self: *BodyContext,
        target: checked.ResolvedValueId,
        expected_ret_node: ?NodeId,
    ) Allocator.Error!bool {
        if (self.iteratorProcedureForResolvedTarget(target) != null) return false;
        if (try self.hostedTryCapabilityForResolvedTarget(target) != null) return false;
        if (expected_ret_node) |expected| {
            if (try self.graph.containsGeneratedPrivate(expected)) return false;
        }
        return true;
    }

    /// Select and draft the callee specialization of a direct call's request
    /// interface, once per shared request.
    fn completedDirectCalleeAtNode(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        target: checked.ResolvedValueId,
        source_fn_ty: checked.CheckedTypeId,
        fn_node: NodeId,
    ) Allocator.Error!CompletedDirectCallee {
        if (self.instantiation.direct_call_requests.get(checked_expr)) |request| {
            if (request.fn_node == fn_node) {
                if (request.completed) |completed| return completed;
            }
        }
        const callee = try self.fnTemplateForDirectCallAtNode(
            target,
            source_fn_ty,
            self.view.types.rootKey(source_fn_ty),
            fn_node,
        );
        const completed = CompletedDirectCallee{
            .callee = callee,
            .fn_node = try self.draftFnSlotTypeNode(callee, fn_node),
        };
        if (self.instantiation.direct_call_requests.getPtr(checked_expr)) |request| {
            if (request.fn_node == fn_node) request.completed = completed;
        }
        return completed;
    }

    fn directCallTypeNode(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        call: anytype,
        source_fn_ty: checked.CheckedTypeId,
        expected_ret_node: ?NodeId,
    ) Allocator.Error!NodeId {
        return (try self.runEvidence(.{ .direct_call_type = .{ .expr = undefined, .target = call.direct_target orelse Common.invariant("direct checked call instantiation received an indirect call"), .call = call, .checked_ret_ty = checked_ret_ty, .source_fn_ty = source_fn_ty, .expected_ret_node = expected_ret_node } })).nodeValue();
    }

    fn fnTemplateForDirectCallAtNode(
        self: *BodyContext,
        target: checked.ResolvedValueId,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        request_fn_node: NodeId,
    ) Allocator.Error!DraftFnSlot {
        const raw = @backingInt(target);
        if (raw >= self.view.resolved_refs.records.len) {
            Common.invariant("checked direct call target is outside resolved value table");
        }
        const record = self.view.resolved_refs.records[raw];
        return switch (record.ref) {
            .local_proc => |local| if (local.is_alias)
                try self.forwardedLocalAliasCalleeAtNode(local, record.expr, request_fn_node)
            else
                .{ .local = try self.lowerDraftLocalProcAtNode(
                    local,
                    self.view,
                    try self.localProcContextId(self.view, local.binder, local.expr),
                    source_fn_ty,
                    source_fn_key,
                    request_fn_node,
                    try self.evidenceForUseSiteAtNode(record.expr, request_fn_node),
                    record.recursive_reference,
                    .inherit,
                ) },
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .promoted_top_level_proc,
            => |proc| if (self.builder.forwardingCallableEvalForProcedureUse(proc)) |alias|
                try self.forwardedCallableEvalCalleeAtNode(alias, record.expr, request_fn_node)
            else
                try self.draftFnSlotForProcedureUseAtNode(
                    proc,
                    source_fn_ty,
                    source_fn_key,
                    request_fn_node,
                    try self.evidenceForProcedureUseAtNode(proc, record.expr, null, request_fn_node, .body_lowering),
                    record.recursive_reference,
                ),
            .platform_required_proc => |proc| if (self.builder.forwardingCallableEvalForProcedureUse(proc.procedure)) |alias|
                try self.forwardedCallableEvalCalleeAtNode(alias, record.expr, request_fn_node)
            else
                try self.draftFnSlotForProcedureUseAtNode(
                    proc.procedure,
                    source_fn_ty,
                    source_fn_key,
                    request_fn_node,
                    try self.evidenceForProcedureUseAtNode(proc.procedure, record.expr, proc.root_evidence, request_fn_node, .body_lowering),
                    record.recursive_reference,
                ),
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .platform_required_declaration, .platform_required_checked_error, .platform_required_const => Common.invariant("checked direct call target was not a procedure"),
        };
    }

    /// A call through a local exact procedure alias calls the alias's lookup
    /// directly. The alias owns an instantiation scope: its use-site evidence
    /// enters that scope, and the lookup's own evidence is resolved inside it,
    /// exactly as a value use of the alias lowers its lookup.
    fn forwardedLocalAliasCalleeAtNode(
        self: *BodyContext,
        alias: checked.LocalProcedureBinding,
        use_expr: checked.CheckedExprId,
        request_fn_node: NodeId,
    ) Allocator.Error!DraftFnSlot {
        const scope_id = alias.dispatch_scope orelse
            Common.invariant("generalized callable alias has no checked scheme scope");
        const edge = try self.evidenceForUseSiteAtNode(use_expr, request_fn_node);
        const evidence = try enterEvidenceScope(self.builder, self.evidence, scope_id, alias.expr, edge);
        const scope = self.view.templates.dispatch_scopes[@backingInt(scope_id)];
        const previous_instantiation = self.instantiation;
        const previous_evidence = self.evidence;
        self.instantiation = TypeInstantiationContext.init(self.allocator, self.builder.allocateInstantiationScope(), self.view.key.bytes);
        self.evidence = evidence;
        defer {
            self.instantiation.deinit();
            self.instantiation = previous_instantiation;
            self.evidence = previous_evidence;
        }
        try self.seedSubstitution(evidence.schema.?, edge.subst);
        try relateFunctionRequestInterface(self.graph, try self.instNode(scope.scheme_root), request_fn_node);
        return try self.forwardedLookupCalleeAtNode(alias.expr, request_fn_node);
    }

    /// A call through a top-level exact procedure alias calls the alias's
    /// lookup directly, inside the alias's entry-wrapper evidence scope, the
    /// same scope a value use of the alias lowers its lookup in.
    fn forwardedCallableEvalCalleeAtNode(
        self: *BodyContext,
        alias: Builder.CallableEvalUse,
        use_expr: checked.CheckedExprId,
        request_fn_node: NodeId,
    ) Allocator.Error!DraftFnSlot {
        const view = alias.view;
        const template = view.callable_eval_templates.templates[@backingInt(alias.template)];
        const lookup = template.forwarded_lookup orelse
            Common.invariant("forwarded callable-eval alias had no checked lookup");
        const root = view.compile_time_roots.root(template.root);
        const wrapper = view.entry_wrappers.lookupByRoot(template.root) orelse
            Common.invariant("callable eval template root had no checked entry wrapper");
        const edge = try self.evidenceForUseSiteAtNode(use_expr, request_fn_node);

        var body_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, view, self.method_scope, wrapper.template, self.graph, self.draft);
        defer body_ctx.deinit();
        const entry_template = view.templates.get(wrapper.template.template);
        const schema = templateSchemaIn(view, &entry_template);
        const subst = try body_ctx.substitutionFromCheckedTypes(view, schema.scheme_vars);
        body_ctx.evidence = rootEvidenceWithSubstitution(wrapper.template, schema, .{
            .subst = subst,
            .vector = edge.vector,
        });
        try body_ctx.seedSubstitution(schema, subst);
        body_ctx.frozen_sealed_emission = self.frozen_sealed_emission;
        body_ctx.frozen_type_finals = self.frozen_type_finals;
        body_ctx.frozen_codec_calls = self.frozen_codec_calls;
        body_ctx.frozen_field_defaults = self.frozen_field_defaults;
        const root_fn_key = view.types.rootKey(wrapper.checked_fn_root);
        body_ctx.owner_context_fn_key = root_fn_key;
        body_ctx.current_fn_key = root_fn_key;

        const wrapper_fn_node = try body_ctx.graphFunctionNode(&.{}, request_fn_node);
        try self.graph.unify(try body_ctx.instNode(wrapper.checked_fn_root), wrapper_fn_node);
        try self.graph.unify(try body_ctx.instNode(template.checked_fn_root), request_fn_node);
        try self.graph.unify(try body_ctx.instNode(root.checked_type), request_fn_node);
        return try body_ctx.forwardedLookupCalleeAtNode(lookup, request_fn_node);
    }

    /// The direct callee an alias's lookup names, requested at the alias
    /// call's own interface. A lookup of another alias forwards again.
    fn forwardedLookupCalleeAtNode(
        self: *BodyContext,
        lookup: checked.CheckedExprId,
        request_fn_node: NodeId,
    ) Allocator.Error!DraftFnSlot {
        const target = self.view.resolved_refs.lookupIdByCheckedExpr(lookup) orelse
            Common.invariant("forwarded procedure alias lookup had no resolved value");
        const lookup_ty = self.view.bodies.expr(lookup).ty;
        try relateFunctionRequestInterface(self.graph, try self.instNode(lookup_ty), request_fn_node);
        return try self.fnTemplateForDirectCallAtNode(
            target,
            lookup_ty,
            self.view.types.rootKey(lookup_ty),
            request_fn_node,
        );
    }

    /// The procedure a direct call finally reaches, following exact procedure
    /// aliases, and the checked module view that owns its resolved value. The
    /// callee's compiler-owned roles (call-site intrinsics, iterator
    /// procedures, `Str.inspect`, hosted `Try` adapters) belong to it.
    const FinalDirectTarget = struct {
        view: ModuleView,
        record: checked.ResolvedValueRefRecord,
    };

    fn finalDirectTarget(self: *BodyContext, target: checked.ResolvedValueId) FinalDirectTarget {
        const raw = @backingInt(target);
        if (raw >= self.view.resolved_refs.records.len) {
            Common.invariant("checked direct call target is outside resolved value table");
        }
        var view = self.view;
        var record = view.resolved_refs.records[raw];
        while (true) {
            switch (record.ref) {
                .local_proc => |local| if (local.is_alias) {
                    const final = local.alias_target orelse
                        Common.invariant("callable alias has no published target");
                    record = view.resolved_refs.records[@backingInt(final)];
                    continue;
                },
                .top_level_proc,
                .imported_proc,
                .hosted_proc,
                .promoted_top_level_proc,
                => |proc| if (self.builder.forwardingCallableEvalForProcedureUse(proc)) |alias| {
                    view = alias.view;
                    const template = view.callable_eval_templates.templates[@backingInt(alias.template)];
                    const lookup = view.resolved_refs.lookupIdByCheckedExpr(template.forwarded_lookup.?) orelse
                        Common.invariant("forwarded procedure alias lookup had no resolved value");
                    record = view.resolved_refs.records[@backingInt(lookup)];
                    continue;
                },
                .platform_required_proc => |required| if (self.builder.forwardingCallableEvalForProcedureUse(required.procedure)) |alias| {
                    view = alias.view;
                    const template = view.callable_eval_templates.templates[@backingInt(alias.template)];
                    const lookup = view.resolved_refs.lookupIdByCheckedExpr(template.forwarded_lookup.?) orelse
                        Common.invariant("forwarded procedure alias lookup had no resolved value");
                    record = view.resolved_refs.records[@backingInt(lookup)];
                    continue;
                },
                .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .platform_required_declaration, .platform_required_checked_error, .platform_required_const => {},
            }
            return .{ .view = view, .record = record };
        }
    }

    fn draftFnSlotForProcedureUseAtNode(
        self: *BodyContext,
        proc: checked.ProcedureUseTemplate,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        request_fn_node: NodeId,
        edge: EdgeEvidence,
        recursive_reference: bool,
    ) Allocator.Error!DraftFnSlot {
        const template_ref = self.builder.templateRefForProcedureUse(proc);
        return try self.builder.lowerDraftTemplateFromContext(
            self,
            template_ref,
            source_fn_ty,
            source_fn_key,
            request_fn_node,
            edge,
            if (recursive_reference) .recursive_reference else .instantiation,
            if (proc.iterator_procedure == .from_step) .exact_graph else .independent_roots,
            .inherit,
        );
    }

    fn lowerDraftLocalProcAtNode(
        self: *BodyContext,
        local: checked.LocalProcedureBinding,
        local_view: ModuleView,
        context_id: DraftLocalProcContextId,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        request_fn_node: NodeId,
        edge: EdgeEvidence,
        recursive_reference: bool,
        codec_contract_selection: CodecContractSelection,
    ) Allocator.Error!DraftFnTarget {
        const context = self.validateLocalProcContext(
            context_id,
            local_view.key.bytes,
            local.binder,
            local.expr,
            null,
        );
        const previous_view = self.view;
        const previous_source_file_id = self.source_file_id;
        const local_source_file_id = self.builder.sourceFileId(local_view);
        self.view = local_view;
        self.source_file_id = local_source_file_id;
        defer {
            self.view = previous_view;
            self.source_file_id = previous_source_file_id;
        }
        const crosses_module = !moduleBytesEqual(previous_view.key.bytes, local_view.key.bytes);
        const previous_binders = self.binders;
        const previous_typed_binders = self.typed_binders;
        if (crosses_module) {
            self.binders = try BinderMap.init(self.allocator, local_view.bodies.patternBinderCount());
            self.typed_binders = TypedBinders.init(self.allocator);
        }
        defer if (crosses_module) {
            self.binders.deinit();
            self.typed_binders.deinit();
            self.binders = previous_binders;
            self.typed_binders = previous_typed_binders;
        };
        var installed_context = try self.installLocalProcContext(context);
        defer installed_context.deinit();
        const previous_owner_template = self.owner_template;
        self.owner_template = context.owner_template;
        defer self.owner_template = previous_owner_template;
        const context_fn_key = self.localProcUseContextKey(context);
        const nested = try self.builder.nestedFnForExpr(
            self.view,
            context.owner_template,
            local.expr,
            context_fn_key,
            try self.localProcContextsDigest(),
            self.in_default_expr,
        );
        const requested_evidence = if (local.dispatch_scope) |scope|
            try enterEvidenceScope(self.builder, context.evidence, scope, local.expr, edge)
        else blk: {
            if (edge.vector.len != 0) {
                Common.invariant("local procedure without a checked evidence scope received use evidence");
            }
            break :blk context.evidence;
        };
        const lexical_owner_scope = try self.draft.enterOwner(context.lexical_owner);
        defer lexical_owner_scope.leave();
        // Recursion belongs to the requesting body, retained by the owner
        // scope, while specialization identity uses the declaration owner.
        // The declaration context's capture types are part of the
        // specialization identity: two enclosing instantiations can request
        // this local procedure at the same monomorphic function type while
        // capturing at different types, and those must not share a body.
        const capture_bindings = try self.localProcCaptureBindings(context);
        defer self.allocator.free(capture_bindings);
        const capture_entry_guards = try self.graph.arena().alloc(NodeId, capture_bindings.len);
        for (capture_bindings, capture_entry_guards) |binding, *node| {
            node.* = try binding.ty.toGraphNode(self.graph);
        }
        return try self.builder.lowerDraftNestedFromContext(
            self,
            lexical_owner_scope.previous,
            local.expr,
            nested,
            source_fn_ty,
            source_fn_key,
            request_fn_node,
            capture_entry_guards,
            requested_evidence,
            local.dispatch_scope,
            recursive_reference,
            .independent_roots,
            codec_contract_selection,
        );
    }

    const LocalProcCaptureBinding = struct {
        local: DraftLocalId,
        ty: DraftTypeCell,
    };

    /// The lexical-context bindings a local procedure captures at its
    /// declaration, deduplicated by CaptureId (first entry wins). Every
    /// consumer of a declaration context—capture entry guards, fn-def
    /// capture spans, and direct-call capture operands—derives from this one
    /// walk so they agree on count and order. Caller owns the returned slice.
    fn localProcCaptureBindings(
        self: *BodyContext,
        context: LocalProcContext,
    ) Allocator.Error![]LocalProcCaptureBinding {
        var seen = collections.DenseMap(checked.CaptureId, void).init(self.allocator);
        defer seen.deinit();
        var bindings = std.ArrayList(LocalProcCaptureBinding).empty;
        errdefer bindings.deinit(self.allocator);

        for (context.entries) |entry| {
            const local: DraftLocalId = @fromBackingInt(@intCast(entry.local));
            const raw = @backingInt(local);
            if (raw >= self.draft.locals.items.len) {
                Common.invariant("local procedure context capture referenced an unknown local");
            }
            const local_data = self.draft.locals.items[raw];
            const capture_id = local_data.capture_id orelse
                Common.invariant("local procedure context capture local had no capture identity");
            const seen_entry = try seen.getOrPut(capture_id);
            if (seen_entry.found_existing) continue;
            try bindings.append(self.allocator, .{ .local = local, .ty = local_data.ty });
        }

        return try bindings.toOwnedSlice(self.allocator);
    }

    fn localProcFnDefCaptureSpan(
        self: *BodyContext,
        context_id: DraftLocalProcContextId,
        module: [32]u8,
        binder: checked.PatternBinderId,
        expr: checked.CheckedExprId,
        context_anchor: ?checked.CheckedStatementId,
    ) Allocator.Error!DraftSpan(DraftFnDefCapture) {
        const context = self.validateLocalProcContext(
            context_id,
            module,
            binder,
            expr,
            context_anchor,
        );
        if (context.entries.len == 0) return DraftSpan(DraftFnDefCapture).empty();

        const bindings = try self.localProcCaptureBindings(context);
        defer self.allocator.free(bindings);
        var captures = std.ArrayList(DraftFnDefCapture).empty;
        defer captures.deinit(self.allocator);
        try captures.ensureTotalCapacityPrecise(self.allocator, bindings.len);

        for (bindings) |binding| {
            const value = try self.addExprWithTypeCell(
                binding.ty,
                .{ .local = binding.local },
            );
            captures.appendAssumeCapacity(.{ .id = self.captureKey(binding.local), .value = value });
        }

        return try self.addFnDefCaptureSpan(captures.items);
    }

    fn localProcCaptureExprSpan(
        self: *BodyContext,
        context_id: DraftLocalProcContextId,
        module: [32]u8,
        binder: checked.PatternBinderId,
        expr: checked.CheckedExprId,
        context_anchor: ?checked.CheckedStatementId,
    ) Allocator.Error!DraftSpan(DraftExprId) {
        const context = self.validateLocalProcContext(
            context_id,
            module,
            binder,
            expr,
            context_anchor,
        );
        if (context.entries.len == 0) return DraftSpan(DraftExprId).empty();

        const bindings = try self.localProcCaptureBindings(context);
        defer self.allocator.free(bindings);
        var captures = std.ArrayList(DraftExprId).empty;
        defer captures.deinit(self.allocator);
        try captures.ensureTotalCapacityPrecise(self.allocator, bindings.len);

        for (bindings) |binding| {
            captures.appendAssumeCapacity(try self.addExprWithTypeCell(
                binding.ty,
                .{ .local = binding.local },
            ));
        }

        return try self.addExprSpan(captures.items);
    }

    fn directCallCaptureSpan(self: *BodyContext, target: checked.ResolvedValueId) Allocator.Error!DraftSpan(DraftExprId) {
        const final = self.finalDirectTarget(target);
        return switch (final.record.ref) {
            .local_proc => |local| if (!moduleBytesEqual(final.view.key.bytes, self.view.key.bytes))
                Common.invariant("forwarded direct call reached a local procedure of another module")
            else
                try self.localProcCaptureExprSpan(
                    try self.localProcContextId(self.view, local.binder, local.expr),
                    self.view.key.bytes,
                    local.binder,
                    local.expr,
                    null,
                ),
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_proc,
            .promoted_top_level_proc,
            => DraftSpan(DraftExprId).empty(),
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .platform_required_declaration, .platform_required_checked_error, .platform_required_const => Common.invariant("checked direct call target was not a procedure"),
        };
    }

    fn methodTargetCaptureSpan(self: *BodyContext, lookup: MethodLookup) Allocator.Error!DraftSpan(DraftExprId) {
        return switch (lookup.target.kind) {
            .local_proc => |local| try self.localProcCaptureExprSpan(
                lookup.local_proc_context orelse
                    Common.invariant("local method target did not carry its declaration context"),
                lookup.view.key.bytes,
                local.binder,
                local.expr,
                local.context_anchor,
            ),
            .procedure,
            .structural,
            => DraftSpan(DraftExprId).empty(),
        };
    }

    fn currentLocalBindingForResolvedValue(self: *BodyContext, ref_id: checked.ResolvedValueId) ?CurrentLocal {
        const raw = @backingInt(ref_id);
        if (raw >= self.view.resolved_refs.records.len) {
            Common.invariant("checked lookup resolved value id was outside resolved value table");
        }
        const record = self.view.resolved_refs.records[raw];
        return switch (record.ref) {
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            => |local| .{
                .binder = local.binder,
                .local = self.binders.get(local.binder) orelse
                    Common.invariant("local lookup referenced an unbound pattern binder"),
            },
            .selected_hoisted_const => |selected| if (self.binders.get(selected.local.binder)) |local|
                .{ .binder = selected.local.binder, .local = local }
            else
                null,
            .local_proc,
            .top_level_const,
            .imported_const,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            .platform_required_proc,
            .promoted_top_level_proc,
            => null,
        };
    }

    fn currentConstLocalForResolvedValue(self: *BodyContext, ref_id: checked.ResolvedValueId) Allocator.Error!?DraftLocalId {
        var active_id = self.active_const_binding;
        if (active_id == null) return null;
        const raw = @backingInt(ref_id);
        if (raw >= self.view.resolved_refs.records.len) {
            Common.invariant("checked lookup resolved value id was outside resolved value table");
        }
        const record = self.view.resolved_refs.records[raw];
        const const_use = switch (record.ref) {
            .top_level_const, .imported_const => |value| value,
            .platform_required_const => |required| required.const_use,
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .selected_hoisted_const, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_proc, .promoted_top_level_proc => return null,
        };
        while (active_id) |id| {
            const index = @backingInt(id);
            const active = self.draft.active_const_bindings.items[index];
            if (constUseEql(active.const_use, const_use.const_ref)) {
                self.draft.active_const_bindings.items[index].used = true;
                try self.materializeActiveConstBinding(id);
                return active.local;
            }
            active_id = active.parent;
        }
        return null;
    }

    fn markActiveConstBinderUsed(self: *BodyContext, binder: checked.PatternBinderId) Allocator.Error!void {
        var active_id = self.active_const_binding;
        while (active_id) |id| {
            const index = @backingInt(id);
            const active = self.draft.active_const_bindings.items[index];
            if (moduleBytesEqual(checked.constModuleId(active.const_use).bytes, self.view.key.bytes) and active.binder == binder) {
                self.draft.active_const_bindings.items[index].used = true;
                try self.materializeActiveConstBinding(id);
                return;
            }
            active_id = active.parent;
        }
    }

    fn topLevelConstBinderForUse(store_view: ModuleView, const_use: checked.ConstLocator) ?checked.PatternBinderId {
        const owner = switch (const_use.owner) {
            .top_level_binding => |owner| owner,
            // A hoisted extraction root binds its result pattern. A reference
            // to that binder from a lambda inside the root's own scrutinee
            // recurses through it the way a top-level constant's lambda
            // recurses through the constant.
            .hoisted_expr => |hoisted| {
                if (!moduleBytesEqual(checked.constModuleId(const_use).bytes, store_view.key.bytes)) {
                    Common.invariant("hoisted const template referenced a different checked module");
                }
                const entry = store_view.hoisted_constants.lookupByExpr(hoisted.expr) orelse return null;
                const pattern = entry.pattern orelse return null;
                const raw_pattern = @backingInt(pattern);
                if (raw_pattern >= store_view.bodies.pattern_binder_by_pattern.len) {
                    Common.invariant("hoisted const result pattern was outside the binder index");
                }
                return store_view.bodies.pattern_binder_by_pattern[raw_pattern];
            },
        };
        if (!moduleBytesEqual(checked.constModuleId(const_use).bytes, store_view.key.bytes)) {
            Common.invariant("top-level const template referenced a different checked module");
        }
        const root_id = store_view.compile_time_roots.lookupIdByPattern(owner.pattern) orelse
            Common.invariant("top-level const template had no compile-time root");
        const root = store_view.compile_time_roots.root(root_id);
        if (root.kind != .constant) {
            Common.invariant("top-level const template did not reference a constant root");
        }
        if (root.module_idx != owner.module_idx) {
            Common.invariant("top-level const template root had a mismatched module index");
        }
        const pattern = root.pattern orelse
            Common.invariant("top-level const template root had no checked pattern");
        if (pattern != owner.pattern) {
            Common.invariant("top-level const template root had a mismatched checked pattern");
        }
        return switch (store_view.bodies.pattern(pattern).data) {
            .assign => |binder| binder,
            .pending, .as, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => Common.invariant("top-level const root pattern was not a binder"),
        };
    }

    fn inheritActiveConstBinding(self: *BodyContext, parent: *BodyContext) Allocator.Error!void {
        try self.inheritActiveConstBindingId(parent.active_const_binding);
    }

    fn inheritActiveConstBindingId(self: *BodyContext, active_id: ?ActiveConstBindingId) Allocator.Error!void {
        self.active_const_binding = active_id;
        var chain = std.ArrayList(ActiveConstBindingId).empty;
        defer chain.deinit(self.allocator);
        var cursor = active_id;
        while (cursor) |id| {
            try chain.append(self.allocator, id);
            cursor = self.draft.active_const_bindings.items[@backingInt(id)].parent;
        }
        var index = chain.items.len;
        while (index > 0) {
            index -= 1;
            const active = self.draft.active_const_bindings.items[@backingInt(chain.items[index])];
            if (!moduleBytesEqual(checked.constModuleId(active.const_use).bytes, self.view.key.bytes)) continue;
            try self.binders.put(active.binder, active.local);
        }
    }

    fn enterActiveConstBindingAtCell(
        self: *BodyContext,
        store_view: ModuleView,
        const_use: checked.ConstLocator,
        cell: DraftTypeCell,
        scope: *ActiveConstBindingScope,
    ) Allocator.Error!bool {
        const binder = topLevelConstBinderForUse(store_view, const_use) orelse return false;
        const local = try self.addFreshLocalWithBinderCell(
            self.builder.symbols.fresh(),
            cell,
            binder,
        );
        try self.bindLocalNameFromView(store_view, local, binder);
        const reservation = try self.addExprWithTypeCell(cell, .pending_deferred);
        const active_id: ActiveConstBindingId = @fromBackingInt(@intCast(@as(u32, @intCast(self.draft.active_const_bindings.items.len))));
        try self.draft.active_const_bindings.append(self.allocator, .{
            .parent = self.active_const_binding,
            .const_use = const_use,
            .binder = binder,
            .local = local,
            .cell = cell,
            .owner = self.draft.current_owner,
            .reservation = reservation,
        });
        const bound_in_current_view = moduleBytesEqual(
            checked.constModuleId(const_use).bytes,
            self.view.key.bytes,
        );
        scope.* = .{
            .active = active_id,
            .previous_active = self.active_const_binding,
            .binder = binder,
            .previous_local = if (bound_in_current_view) self.binders.get(binder) else null,
            .bound_in_current_view = bound_in_current_view,
            .entered = true,
        };
        // Pattern binder IDs are dense and local to a checked module. A const
        // restored from another module must remain in the active-const chain so
        // recursive uses preserve their identity, but its binder cannot be
        // installed in this module's lexical binder map. When lowering enters
        // the const's own module, inheritActiveConstBindingId installs it there.
        if (bound_in_current_view) {
            try self.binders.put(binder, local);
        }
        self.active_const_binding = active_id;
        return true;
    }

    fn copyActiveConstReservation(self: *BodyContext, reservation: DraftExprId, source: DraftExprId) void {
        const reservation_index = @backingInt(reservation);
        const source_index = @backingInt(source);
        self.draft.exprs.items[reservation_index] = self.draft.exprs.items[source_index];
        self.draft.expr_locs.items[reservation_index] = self.draft.expr_locs.items[source_index];
        self.draft.expr_regions.items[reservation_index] = self.draft.expr_regions.items[source_index];
        self.draft.expr_impossibility_proofs.items[reservation_index] = self.draft.expr_impossibility_proofs.items[source_index];
    }

    fn finishActiveConstBinding(self: *BodyContext, active_id: ActiveConstBindingId, source: DraftExprId) Allocator.Error!DraftExprId {
        const index = @backingInt(active_id);
        if (self.draft.active_const_bindings.items[index].restored_source != null) {
            Common.invariant("active const binding was finished more than once");
        }
        const reservation = self.draft.active_const_bindings.items[index].reservation;
        self.draft.active_const_bindings.items[index].restored_source = source;
        self.copyActiveConstReservation(reservation, source);
        try self.materializeActiveConstBinding(active_id);
        return reservation;
    }

    fn materializeActiveConstBinding(self: *BodyContext, active_id: ActiveConstBindingId) Allocator.Error!void {
        const index = @backingInt(active_id);
        const active = self.draft.active_const_bindings.items[index];
        if (!active.used or active.wrapped) return;
        const source = active.restored_source orelse return;

        const owner_scope = try self.draft.enterOwner(active.owner);
        defer owner_scope.leave();
        const saved_loc = self.builder.current_loc;
        defer self.builder.current_loc = saved_loc;
        const saved_region = self.builder.current_region;
        defer self.builder.current_region = saved_region;
        self.builder.current_loc = self.draft.expr_locs.items[@backingInt(source)];
        self.builder.current_region = self.draft.expr_regions.items[@backingInt(source)];

        const wrapped = try self.wrapRecursiveConstLocalAtTypeCell(active.local, active.cell, source);
        self.copyActiveConstReservation(active.reservation, wrapped);
        self.draft.expr_locs.items[@backingInt(active.reservation)] = self.draft.expr_locs.items[@backingInt(source)];
        self.draft.expr_regions.items[@backingInt(active.reservation)] = self.draft.expr_regions.items[@backingInt(source)];
        self.draft.expr_impossibility_proofs.items[@backingInt(active.reservation)] = self.draft.expr_impossibility_proofs.items[@backingInt(source)];
        self.draft.active_const_bindings.items[index].wrapped = true;
    }

    fn leaveActiveConstBinding(self: *BodyContext, scope: *const ActiveConstBindingScope) void {
        if (!scope.entered) return;
        if (scope.bound_in_current_view) {
            if (scope.previous_local) |previous| {
                self.binders.restore(scope.binder, previous);
            } else {
                _ = self.binders.remove(scope.binder);
            }
        }
        self.active_const_binding = scope.previous_active;
    }

    fn currentLocalForResolvedValue(self: *BodyContext, ref_id: checked.ResolvedValueId) Allocator.Error!?DraftLocalId {
        if (self.currentLocalBindingForResolvedValue(ref_id)) |binding| return binding.local;
        return try self.currentConstLocalForResolvedValue(ref_id);
    }

    fn currentTypedLocalBindingForResolvedValue(
        self: *BodyContext,
        ref_id: checked.ResolvedValueId,
        ty: Type.TypeId,
    ) ?CurrentLocal {
        const raw = @backingInt(ref_id);
        if (raw >= self.view.resolved_refs.records.len) {
            Common.invariant("checked lookup resolved value id was outside resolved value table");
        }
        const record = self.view.resolved_refs.records[raw];
        const binder = switch (record.ref) {
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            => |local| local.binder,
            .selected_hoisted_const => |selected| selected.local.binder,
            .local_proc,
            .top_level_const,
            .imported_const,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            .platform_required_proc,
            .promoted_top_level_proc,
            => return null,
        };
        return if (self.typed_binders.get(self.typedBinder(binder, ty))) |local|
            .{ .binder = binder, .local = local }
        else
            null;
    }

    fn currentLocalBindingAtType(
        self: *BodyContext,
        ref_id: checked.ResolvedValueId,
        ty: Type.TypeId,
    ) Allocator.Error!?CurrentLocal {
        const current = self.currentLocalBindingForResolvedValue(ref_id);
        if (current) |binding| {
            // `binders` is the lexical/SSA timeline, while `typed_binders`
            // holds alternative Monotype materializations of a checked binder
            // restored across a compile-time boundary. A same-typed mutable
            // version must shadow that older restored materialization.
            const matches = switch (self.localTypeCell(binding.local)) {
                .sealed => |local_ty| self.sameType(local_ty, ty),
                .graph_node => |local_node| self.graph.sameClass(
                    local_node,
                    try self.activeNodeFromType(ty),
                ),
            };
            if (matches) return binding;
        }
        return self.currentTypedLocalBindingForResolvedValue(ref_id, ty) orelse current;
    }

    fn lowerLocalBindingAtNode(
        self: *BodyContext,
        binding: CurrentLocal,
        checked_ty: checked.CheckedTypeId,
        expected_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const local_cell = self.localTypeCell(binding.local);
        try self.constrainCheckedInterfaceToCell(checkedBinderType(self.view, binding.binder), local_cell);
        try self.constrainCheckedInterfaceToCell(checked_ty, local_cell);
        return try self.lowerLocalAtRequestedNode(binding.local, local_cell, expected_node);
    }

    fn lowerLookupExprAtType(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        maybe_ref: ?checked.ResolvedValueId,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const ref_id = maybe_ref orelse Common.invariant("checked lookup reached Monotype without resolved value ref");
        const record = self.view.resolved_refs.records[@backingInt(ref_id)];
        switch (record.ref) {
            .platform_required_checked_error => return try self.addExpr(.{ .ty = ty, .data = .{ .checked_error = try self.addStringLiteral("platform requirement failed checking") } }),
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .selected_hoisted_const, .top_level_const, .imported_const, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_const, .platform_required_proc, .promoted_top_level_proc => {},
        }
        switch (record.ref) {
            .local_value,
            .pattern_binder,
            => {},
            .selected_hoisted_const => |selected| {
                // A local for the binder is the root's own in-progress value
                // or an active recursive restore of the constant; it is
                // consumed below instead of restoring the constant again.
                if (self.binders.get(selected.local.binder) == null) {
                    if (try self.restoreSelectedHoistedConstAtType(selected, ty)) |restored| return restored;
                }
            },
            .local_param,
            .local_mutable_version,
            .local_proc,
            .top_level_const,
            .imported_const,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            .platform_required_proc,
            .promoted_top_level_proc,
            => {},
        }
        if (try self.currentLocalBindingAtType(ref_id, ty)) |binding| {
            const local_id = binding.local;
            const binder_ty = checkedBinderType(self.view, binding.binder);
            const local_cell = self.localTypeCell(local_id);
            if (local_cell == .graph_node) {
                return try self.lowerLocalBindingAtNode(
                    binding,
                    checked_ty,
                    try self.activeNodeFromType(ty),
                );
            }
            const local_ty = try self.activeTypeFromCell(local_cell);
            if (self.checkedTypeIsClosed(binder_ty) and
                self.checkedTypeIsClosed(checked_ty) and
                self.sameType(local_ty, ty))
            {
                const checked_binder_ty = try self.lowerType(binder_ty);
                const checked_use_ty = try self.lowerType(checked_ty);
                if (!self.sameType(checked_binder_ty, local_ty) or
                    !self.sameType(checked_use_ty, ty))
                {
                    Common.invariant("closed checked local lookup differed from its sealed binding type");
                }
                return try self.addExprWithTypeCell(.{ .sealed = local_ty }, .{ .local = local_id });
            }
            // The local's Monotype identifies the binder's node in the
            // context that bound it; importing it unifies this context's
            // instantiation with that node before the use type is unified.
            try self.relateCheckedTypeToMono(binder_ty, local_ty);
            try self.relateCheckedTypeToMono(binder_ty, ty);
            try self.relateCheckedTypeToMono(checked_ty, ty);
            const live_ty = try self.lowerTypeView(binder_ty);
            const use_ty = if (self.sameType(ty, local_ty))
                local_ty
            else if (self.sameType(ty, live_ty))
                live_ty
            else
                Common.invariant("checked local lookup type differed from its expected Monotype use type");
            if (use_ty != local_ty) try self.setLocalType(local_id, use_ty);
            return try self.addExpr(.{ .ty = use_ty, .data = .{ .local = local_id } });
        }
        if (try self.currentConstLocalForResolvedValue(ref_id)) |local_id| {
            const local_cell = self.localTypeCell(local_id);
            try self.constrainCheckedInterfaceToCell(checked_ty, local_cell);
            return try self.lowerLocalAtRequestedNode(local_id, local_cell, try self.activeNodeFromType(ty));
        }

        switch (record.ref) {
            .top_level_const => |const_use| return try self.restoreConstUseAtType(
                const_use,
                ty,
                (try self.evidenceForUseSite(record.expr)).vector,
            ),
            .imported_const => |const_use| return try self.restoreConstUseAtType(
                const_use,
                ty,
                (try self.evidenceForUseSite(record.expr)).vector,
            ),
            .platform_required_const => |required| return try self.restoreConstUseAtType(
                required.const_use,
                ty,
                (try self.evidenceForUseSite(record.expr)).vector,
            ),
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .selected_hoisted_const,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_proc,
            .promoted_top_level_proc,
            => {},
        }

        switch (record.ref) {
            // The nested specialization applies its checked scope relations
            // before joining this contextual graph node.
            .local_proc => {},
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_const, .platform_required_proc, .promoted_top_level_proc => try self.constrainTypeToMono(checked_ty, ty),
        }
        return switch (record.ref) {
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .selected_hoisted_const,
            => Common.invariant("local lookup reached Monotype without a current local binding"),
            .local_proc => |local| blk: {
                const request_fn_node = try self.activeNodeFromType(ty);
                if (local.is_alias) Common.invariant("callable alias lookup reached value lookup lowering");
                const context_id = try self.localProcContextId(self.view, local.binder, local.expr);
                const fn_id = try self.lowerDraftLocalProcAtNode(
                    local,
                    self.view,
                    context_id,
                    checked_ty,
                    self.view.types.rootKey(checked_ty),
                    request_fn_node,
                    try self.evidenceForUseSiteAtNode(record.expr, request_fn_node),
                    record.recursive_reference,
                    .inherit,
                );
                const fn_node = try self.draftFnSlotTypeNode(.{ .local = fn_id }, request_fn_node);
                break :blk try self.addExprWithTypeCell(
                    DraftTypeCell.fromGraphNode(fn_node),
                    .{ .fn_def = .{ .fn_id = fn_id, .captures = try self.localProcFnDefCaptureSpan(
                        context_id,
                        self.view.key.bytes,
                        local.binder,
                        local.expr,
                        null,
                    ) } },
                );
            },
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .promoted_top_level_proc,
            => |proc| try self.lowerProcedureUseValueAtNode(proc, try self.activeNodeFromType(ty), record.expr, null, record.recursive_reference),
            .platform_required_proc => |proc| try self.lowerProcedureUseValueAtNode(proc.procedure, try self.activeNodeFromType(ty), record.expr, proc.root_evidence, record.recursive_reference),
            .top_level_const,
            .imported_const,
            .platform_required_const,
            => unreachable,
            .platform_required_declaration => Common.invariant("platform required declaration reached Monotype without a binding"),
            .platform_required_checked_error => return try self.addExpr(.{ .ty = ty, .data = .{ .checked_error = try self.addStringLiteral("platform requirement failed checking") } }),
        };
    }

    fn checkedTypeIsClosed(self: *const BodyContext, ty: checked.CheckedTypeId) bool {
        const raw = @backingInt(ty);
        if (raw >= self.view.types.roots.len) {
            Common.invariant("checked type closure query referenced a missing root");
        }
        return !self.view.types.roots[raw].contains_identity_variables;
    }

    /// The scheme alias task a lookup of `maybe_ref` lowers through at
    /// `expected_node`, when it names a generalized callable alias.
    fn schemeAliasLookupTask(self: *BodyContext, maybe_ref: ?checked.ResolvedValueId, expected_node: NodeId) ?LowerTask {
        const ref_id = maybe_ref orelse return null;
        const record = self.view.resolved_refs.records[@backingInt(ref_id)];
        return switch (record.ref) {
            .local_proc => |local| if (local.is_alias) .{ .scheme_alias = .{
                .alias = local,
                .use_expr = record.expr,
                .expected_node = expected_node,
            } } else null,
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_const, .platform_required_proc, .promoted_top_level_proc => null,
        };
    }

    fn lookupExprAtNodeStep(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        maybe_ref: ?checked.ResolvedValueId,
        expected_node: NodeId,
    ) Allocator.Error!LowerStep {
        if (self.schemeAliasLookupTask(maybe_ref, expected_node)) |task| return requestLowerTask(self, task);
        return loweredExprStep(try self.lowerLookupExprAtNode(checked_expr, maybe_ref, expected_node));
    }

    fn lookupExprAtTypeStep(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        maybe_ref: ?checked.ResolvedValueId,
        ty: Type.TypeId,
    ) Allocator.Error!LowerStep {
        if (maybe_ref) |ref_id| switch (self.view.resolved_refs.records[@backingInt(ref_id)].ref) {
            .local_proc => |local| if (local.is_alias) {
                return requestLowerTask(self, self.schemeAliasLookupTask(maybe_ref, try self.activeNodeFromType(ty)).?);
            },
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_const, .platform_required_proc, .promoted_top_level_proc => {},
        };
        return loweredExprStep(try self.lowerLookupExprAtType(checked_ty, maybe_ref, ty));
    }

    fn stepSchemeAlias(self: *BodyContext, task: *SchemeAliasTask, input: ?LowerResult) Allocator.Error!LowerStep {
        if (input) |lowered| {
            self.restoreSchemeAliasScope(task);
            return .{ .ret = lowered };
        }
        const alias = task.alias;
        const scope_id = alias.dispatch_scope orelse
            Common.invariant("generalized callable alias has no checked scheme scope");
        const edge = try self.evidenceForUseSiteAtNode(task.use_expr, task.expected_node);
        const evidence = try enterEvidenceScope(self.builder, self.evidence, scope_id, alias.expr, edge);
        const scope = self.view.templates.dispatch_scopes[@backingInt(scope_id)];
        const saved = try self.allocator.create(SchemeAliasSavedScope);
        saved.* = .{ .instantiation = self.instantiation, .evidence = self.evidence };
        task.saved = saved;
        self.instantiation = TypeInstantiationContext.init(self.allocator, self.builder.allocateInstantiationScope(), self.view.key.bytes);
        self.evidence = evidence;
        try self.seedSubstitution(evidence.schema.?, edge.subst);
        try relateFunctionRequestInterface(self.graph, try self.instNode(scope.scheme_root), task.expected_node);
        return requestLowerChild(self, alias.expr, DraftTypeCell.fromGraphNode(task.expected_node));
    }

    fn restoreSchemeAliasScope(self: *BodyContext, task: *SchemeAliasTask) void {
        const saved = task.saved orelse return;
        self.instantiation.deinit();
        self.instantiation = saved.instantiation;
        self.evidence = saved.evidence;
        self.allocator.destroy(saved);
        task.saved = null;
    }

    /// Whether lowering `ty` takes no input from the enclosing specialization:
    /// it is closed by digest, or every variable it reaches seals to its row
    /// default (`CheckedTypePayload.variableSealsToRowDefault`, the same
    /// variable decision the checked artifact's direct-dispatch classification
    /// makes). This is the sealing half of the `direct_closed` rule (design.md
    /// "Static Dispatch In Monotype").
    ///
    /// Trust boundary: the quantification half is not checked here. It is
    /// guaranteed by the two sealed-cell producers—`beginPatternStatementValue`
    /// through `closedDirectGraphFreeResultType`, whose cell only a
    /// `direct_closed` plan's result fills, and `lowerShapeFreePatternAtCell`
    /// fed by that same cell—together with digest-closed types, which reach
    /// no variable at all. A producer pairing a sealed cell with a tail some
    /// enclosing scheme quantifies is a misclassification upstream; this
    /// guard does not detect it.
    fn checkedTypeSealsWithoutSpecialization(
        self: *BodyContext,
        ty: checked.CheckedTypeId,
    ) Allocator.Error!bool {
        if (self.checkedTypeIsClosed(ty)) return true;
        var visited = collections.DenseMap(checked.CheckedTypeId, void).init(self.allocator);
        defer visited.deinit();
        var pending: std.ArrayListUnmanaged(checked.CheckedTypeId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, ty);
        while (pending.pop()) |next| {
            if ((try visited.getOrPut(next)).found_existing) continue;
            const start = pending.items.len;
            const payload = checkedPayload(self.view, next);
            switch (payload) {
                .pending => Common.invariant("pending checked type reached Monotype sealing scan"),
                .err, .empty_record, .empty_tag_union => {},
                .flex, .rigid => if (!payload.variableSealsToRowDefault()) return false,
                .alias => |alias| {
                    try pending.appendSlice(self.allocator, alias.args);
                    try pending.append(self.allocator, alias.backing);
                },
                .record => |record| {
                    for (record.fields) |field| {
                        try pending.append(self.allocator, field.ty);
                        if (field.kind.undeterminedVariable()) |variable| try pending.append(self.allocator, variable);
                    }
                    try pending.append(self.allocator, record.ext);
                },
                .tuple => |items| try pending.appendSlice(self.allocator, items),
                .nominal => |nominal| {
                    try pending.appendSlice(self.allocator, nominal.args);
                    try pending.appendSlice(self.allocator, nominal.padding_field_types);
                },
                .function => |function| {
                    try pending.appendSlice(self.allocator, function.args);
                    try pending.append(self.allocator, function.ret);
                },
                .tag_union => |tag_union| {
                    for (tag_union.tags) |tag| try pending.appendSlice(self.allocator, tag.argsSlice(self.view.types));
                    try pending.append(self.allocator, tag_union.ext);
                },
            }
            std.mem.reverse(checked.CheckedTypeId, pending.items[start..]);
        }
        return true;
    }

    fn lowerLookupExprAtNode(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        maybe_ref: ?checked.ResolvedValueId,
        expected_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const ref_id = maybe_ref orelse Common.invariant("checked lookup reached Monotype without resolved value ref");
        const record = self.view.resolved_refs.records[@backingInt(ref_id)];
        if (self.currentLocalBindingForResolvedValue(ref_id)) |binding| {
            return try self.lowerLocalBindingAtNode(
                binding,
                self.view.bodies.expr(checked_expr).ty,
                expected_node,
            );
        }
        if (try self.currentConstLocalForResolvedValue(ref_id)) |local_id| {
            const checked_ty = self.view.bodies.expr(checked_expr).ty;
            const local_cell = self.localTypeCell(local_id);
            try self.constrainCheckedInterfaceToCell(checked_ty, local_cell);
            return try self.lowerLocalAtRequestedNode(local_id, local_cell, expected_node);
        }
        switch (record.ref) {
            .selected_hoisted_const => |selected| {
                const entry = self.selectedHoistedConstEntry(selected);
                if (!self.loweringOwnHoistedConstRoot(entry)) {
                    return try self.deferConstUseAtNode(
                        self.view.bodies.expr(checked_expr).ty,
                        selected.const_use,
                        expected_node,
                        (try self.evidenceForUseSite(record.expr)).vector,
                        .{ .hoisted = entry },
                    );
                }
            },
            .top_level_const => |const_use| {
                return try self.deferConstUseAtNode(
                    self.view.bodies.expr(checked_expr).ty,
                    const_use,
                    expected_node,
                    (try self.evidenceForUseSite(record.expr)).vector,
                    .declared,
                );
            },
            .imported_const => |const_use| {
                return try self.deferConstUseAtNode(
                    self.view.bodies.expr(checked_expr).ty,
                    const_use,
                    expected_node,
                    (try self.evidenceForUseSite(record.expr)).vector,
                    .declared,
                );
            },
            .platform_required_const => |required| {
                return try self.deferConstUseAtNode(
                    self.view.bodies.expr(checked_expr).ty,
                    required.const_use,
                    expected_node,
                    (try self.evidenceForUseSite(record.expr)).vector,
                    .declared,
                );
            },
            .local_proc => |local| {
                if (local.is_alias) Common.invariant("callable alias lookup reached value lookup lowering");
                const checked_ty = self.view.bodies.expr(checked_expr).ty;
                const context_id = try self.localProcContextId(self.view, local.binder, local.expr);
                const fn_id = try self.lowerDraftLocalProcAtNode(
                    local,
                    self.view,
                    context_id,
                    checked_ty,
                    self.view.types.rootKey(checked_ty),
                    expected_node,
                    try self.evidenceForUseSiteAtNode(record.expr, expected_node),
                    record.recursive_reference,
                    .inherit,
                );
                const fn_node = try self.draftFnSlotTypeNode(.{ .local = fn_id }, expected_node);
                return try self.addExprWithTypeCell(
                    DraftTypeCell.fromGraphNode(fn_node),
                    .{ .fn_def = .{
                        .fn_id = fn_id,
                        .captures = try self.localProcFnDefCaptureSpan(
                            context_id,
                            self.view.key.bytes,
                            local.binder,
                            local.expr,
                            null,
                        ),
                    } },
                );
            },
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .promoted_top_level_proc,
            => |proc| return try self.lowerProcedureUseValueAtNode(
                proc,
                expected_node,
                record.expr,
                null,
                record.recursive_reference,
            ),
            .platform_required_proc => |proc| return try self.lowerProcedureUseValueAtNode(
                proc.procedure,
                expected_node,
                record.expr,
                proc.root_evidence,
                record.recursive_reference,
            ),
            // The required def failed checking, so its type never resolves;
            // crash at the use site instead of materializing the expected node.
            .platform_required_checked_error => return try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(expected_node), .{ .checked_error = try self.addStringLiteral("platform requirement failed checking") }),
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .platform_required_declaration => {},
        }
        const ty = try self.activeTypeFromNode(expected_node);
        return try self.lowerLookupExprAtType(self.view.bodies.expr(checked_expr).ty, maybe_ref, ty);
    }

    fn deferConstUseAtNode(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        const_use: checked.ConstUseTemplate,
        expected_node: NodeId,
        use_evidence: []const SpecEvidence,
        provenance: DraftConstUseProvenance,
    ) Allocator.Error!DraftExprId {
        switch (provenance) {
            .declared => switch (const_use.const_ref.owner) {
                .top_level_binding => {},
                // An exposed name bound by a top-level destructure is a
                // hoisted extraction root in its own module and a declared
                // value to every importer.
                .hoisted_expr => if (moduleBytesEqual(checked.constModuleId(const_use.const_ref).bytes, self.view.key.bytes)) {
                    Common.invariant("hoisted const use reached a declared deferred boundary");
                },
            },
            .hoisted => |entry| {
                switch (const_use.const_ref.owner) {
                    .hoisted_expr => {},
                    .top_level_binding => Common.invariant("declared const use reached a hoisted deferred boundary"),
                }
                if (!std.meta.eql(entry.const_ref, const_use.const_ref)) {
                    Common.invariant("deferred hoisted const provenance referenced a different const template");
                }
            },
        }
        const requested_node = try self.constUseTypeNode(checked_ty, const_use);
        try relateRequestComponent(self.graph, expected_node, requested_node);
        const expr = try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(requested_node),
            .pending_deferred,
        );
        const proof_reservation = try self.addImpossibilityProof(.pending);
        self.draft.expr_impossibility_proofs.items[@backingInt(expr)] = proof_reservation;
        const lexical = try self.captureCodecLexicalContext();
        errdefer {
            self.allocator.free(lexical.binders);
            self.allocator.free(lexical.local_procs);
        }
        try self.draft.deferred_const_uses.append(self.allocator, .{
            .view = self.view,
            .method_scope = self.method_scope,
            .owner_template = self.owner_template,
            .owner = self.draft.current_owner,
            .expr = expr,
            .request_node = expected_node,
            .witness_node = requested_node,
            .const_use = const_use,
            .provenance = provenance,
            .context_evidence = self.evidence,
            .use_evidence = use_evidence,
            .current_fn_key = self.current_fn_key,
            .active_const_binding = self.active_const_binding,
            .lexical = lexical,
            .proof_reservation = proof_reservation,
        });
        return expr;
    }

    fn lowerProcedureUseValueAtNode(
        self: *BodyContext,
        proc: checked.ProcedureUseTemplate,
        request_fn_node: NodeId,
        site_expr: checked.CheckedExprId,
        root_evidence: ?checked.CheckedEvidenceSpan,
        recursive_reference: bool,
    ) Allocator.Error!DraftExprId {
        if (self.builder.callableEvalForProcedureUse(proc)) |callable_eval| {
            const edge = try self.evidenceForUseSiteAtNode(site_expr, request_fn_node);
            return try self.lowerCallableEvalBindingValueAtNode(
                callable_eval.view,
                callable_eval.template,
                request_fn_node,
                edge.vector,
            );
        }
        const edge = try self.evidenceForProcedureUseAtNode(proc, site_expr, root_evidence, request_fn_node, .body_lowering);
        const source_fn_ty = proc.source_fn_ty_payload orelse
            Common.invariant("checked procedure value reached Monotype without a requested function type");
        const slot = try self.draftFnSlotForProcedureUseAtNode(
            proc,
            source_fn_ty,
            proc.source_fn_ty_template,
            request_fn_node,
            edge,
            recursive_reference,
        );
        const fn_id = try self.requireLocalDraftSlot(slot);
        const fn_node = try self.draftFnSlotTypeNode(slot, request_fn_node);
        return try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(fn_node),
            .{ .fn_def = .{ .fn_id = fn_id } },
        );
    }

    fn requireLocalDraftSlot(self: *BodyContext, slot: DraftFnSlot) Allocator.Error!DraftFnTarget {
        return switch (slot) {
            .local => |local| blk: {
                switch (local) {
                    .draft => |draft_fn| {
                        for (self.draft.template_specs.items) |*spec| {
                            if (spec.fn_id == draft_fn) {
                                spec.requires_local = true;
                                break;
                            }
                        } else Common.invariant("draft procedure value had no owning template specialization");
                    },
                    .final => {},
                }
                break :blk local;
            },
        };
    }

    fn draftFnSlotTypeNode(
        self: *BodyContext,
        slot: DraftFnSlot,
        imported_fallback: NodeId,
    ) Allocator.Error!NodeId {
        return switch (slot) {
            .local => |local| switch (local) {
                .draft => |draft_fn| try self.completedDraftCalleeWitness(
                    draft_fn,
                    try self.completeDeferredIteratorResult(draft_fn),
                ),
                .final => |final_fn| blk: {
                    const completed_node = try self.programFnSourceTypeNode(final_fn);
                    const request_fn = try self.graph.functionNodes(imported_fallback);
                    if (!try self.graph.containsIteratorInterface(request_fn.ret)) {
                        break :blk completed_node;
                    }
                    break :blk try self.adoptCompletedIteratorResult(
                        imported_fallback,
                        completed_node,
                    );
                },
            },
        };
    }

    /// A completed draft callee's type is immutable producer output: other
    /// requests with the same identity must seal to the same type. A caller
    /// therefore consumes a witness of it, so joining the call's result with
    /// the caller's own producers (the branches of an `if`, say) cannot change
    /// the callee's result representation. A callee still being lowered is
    /// shared instead, because its recursive edges must join its own live
    /// representation.
    fn completedDraftCalleeWitness(
        self: *BodyContext,
        draft_fn: DraftFnId,
        callee_node: NodeId,
    ) Allocator.Error!NodeId {
        const spec_index = self.draft.template_spec_by_fn.get(draft_fn) orelse return callee_node;
        if (self.draft.template_specs.items[spec_index].state != .lowered) return callee_node;
        return try self.graph.privateResultWitness(callee_node);
    }

    /// Relate a callee-authored iterator representation to the checked public
    /// request that selected it. The completed type is immutable producer
    /// output; the caller only records that explicit witness in its own graph.
    fn adoptCompletedIteratorResult(
        self: *BodyContext,
        request_node: NodeId,
        completed_node: NodeId,
    ) Allocator.Error!NodeId {
        const completed_fn = try self.graph.functionNodes(completed_node);
        if (!try self.graph.containsGeneratedPrivate(completed_fn.ret)) return completed_node;

        const request_fn = try self.graph.functionNodes(request_node);
        if (!try self.graph.containsIteratorInterface(request_fn.ret)) {
            Common.invariant("callee completed an iterator representation for a non-iterator request");
        }
        const source_interface = self.graph.requestSourceInterface(request_node) orelse request_node;
        // The completed node can be the memoized import shared by every call
        // site of this specialization, and distinct call sites legitimately
        // carry distinct public request interfaces. The registered interface
        // is therefore only a representative (the first caller's) for the
        // open-interface shape digest and template type-argument constraints;
        // each caller's own validation is the directed relation recorded
        // below, so later callers skip registration instead of tripping the
        // one-source conflict invariant.
        if (self.graph.requestSourceInterface(completed_node) == null) {
            try self.graph.registerRequestSourceInterface(completed_node, source_interface);
        }
        try relateFunctionRequestInterface(self.graph, source_interface, completed_node);
        return completed_node;
    }

    /// A public iterator result can carry a producer-authored private witness
    /// that only the callee body discovers. Lower that context-free callee into
    /// the same worker-owned graph and draft before the caller consumes the
    /// result. Other results keep the ordinary end-of-graph deferred path.
    fn completeDeferredIteratorResult(
        self: *BodyContext,
        draft_fn: DraftFnId,
    ) Allocator.Error!NodeId {
        const current_node = try self.draft.fns.items[@backingInt(draft_fn)].source.mono_fn_ty.toGraphNode(self.graph);
        // Only a deferred template specialization completes eagerly; every
        // other function keeps its current node without scanning its type.
        const spec_index = self.draft.template_spec_by_fn.get(draft_fn) orelse return current_node;
        const spec = self.draft.template_specs.items[spec_index];
        if (spec.state != .deferred) return current_node;

        const current_fn = try self.graph.functionNodes(current_node);
        const has_iterator_result = try self.graph.containsIteratorInterface(current_fn.ret);
        const has_private_result = try self.graph.containsGeneratedPrivate(current_fn.ret);
        if (!has_iterator_result or has_private_result) {
            return current_node;
        }
        // Representation-bearing inputs still belong to the caller's live
        // graph. Recursive adapters can change those inputs at each edge, so
        // their explicit forced-dynamic join must finish before the request is
        // converted to an immutable specialization key.
        for (current_fn.args) |arg| {
            if (try self.graph.containsGeneratedPrivate(arg)) return current_node;
        }
        // A same-family request inside the active root is an explicit
        // recursive edge. Its live graph must join the recursive argument and
        // result representations (and select forced-dynamic when required)
        // before any immutable specialization can be produced.
        if (self.builder.active_template_root) |active_root| {
            const family = DraftTemplateFamilyAddress.init(
                spec.template_ref,
                spec.method_scope,
                spec.source_fn_key,
            );
            if (active_root.graph == self.graph and
                active_root.family.sameRecursiveCallable(family) and
                (try specEvidenceVectorEql(self.allocator, active_root.evidence, spec.evidence)) and
                draftCodecContractSpecializationEql(
                    active_root.codec_contract,
                    spec.codec_contract,
                ))
            {
                return current_node;
            }
        }
        if (!try self.graph.typeIsResolved(spec.request_fn_node)) return current_node;

        const request_fn_ty = try self.activeTypeFromNode(spec.request_fn_node);
        const view = self.builder.moduleForDigest(names.procTemplateModuleDigest(spec.template_ref));
        const template = view.templates.get(spec.template_ref.template);
        // A hosted declaration has no Roc body that can author a private
        // iterator representation. Its public request remains the exact ABI.
        if (template.target == .hosted) return current_node;

        // Lower into the caller's worker-owned draft. The function keeps its
        // own ownership range, so ordered commit can retain or discard it
        // independently of the caller and map recursive references in one pass.
        self.draft.template_specs.items[spec_index].state = .lowering;
        self.builder.countBodyDiagnostic("eager_iterator_template_bodies_lowered");
        const completed_node = try self.builder.lowerDraftTemplateSpecBody(
            self,
            spec_index,
            view,
            template,
        );
        self.draft.template_specs.items[spec_index].eager_resolution = .{
            .request_fn_node = spec.request_fn_node,
            .fn_ty = request_fn_ty,
        };
        self.draft.template_specs.items[spec_index].lookup_request_fn_node = spec.request_fn_node;

        const completed_ty = try self.activeTypeFromNode(completed_node);
        // Adoption is keyed on the produced result representation, the same
        // predicate `adoptCompletedIteratorResult` applies: a completion whose
        // private evidence sits only in an argument must not replace the
        // caller's public request or register lookups for it.
        const eager_completed_fn = try self.graph.functionNodes(completed_node);
        if (!try self.graph.containsGeneratedPrivate(eager_completed_fn.ret)) return current_node;

        const raw_spec: u32 = @intCast(spec_index);
        _ = try self.adoptCompletedIteratorResult(current_node, completed_node);
        self.draft.fns.items[@backingInt(draft_fn)].source.mono_fn_ty = DraftTypeCell.fromGraphNode(completed_node);
        self.draft.template_specs.items[spec_index].request_fn_node = completed_node;
        const completed_spec = self.draft.template_specs.items[spec_index];
        const completed_source = self.draft.fns.items[@backingInt(draft_fn)].source;
        const lookup_prefix = try self.draft.template_spec_lookup.internPrefix(
            DraftTemplateFamilyAddress.init(
                completed_spec.template_ref,
                completed_spec.method_scope,
                completed_spec.source_fn_key,
            ),
            completed_source.evidence_digest.bytes,
        );
        try updateTemplateSpecInterfaceLookups(
            self.draft,
            self.allocator,
            self.graph,
            lookup_prefix,
            completed_node,
            @intCast(spec_index),
        );
        try registerTemplateSpecLookup(self.draft, .{
            .digest = .{
                .prefix = lookup_prefix,
                .kind = .closed,
                .digest = self.specializationTypeDigest(completed_ty).bytes,
            },
        }, raw_spec);
        return completed_node;
    }

    fn constUseMonoType(self: *BodyContext, const_use: checked.ConstUseTemplate) Allocator.Error!Type.TypeId {
        const requested_ty = const_use.requested_source_ty_payload orelse
            Common.invariant("checked const use reached Monotype without a requested checked type");
        const store_view = self.builder.moduleForId(checked.constModuleId(const_use.const_ref));
        const template = store_view.const_templates.get(const_use.const_ref);
        return switch (template.state) {
            .stored_const => |stored| try self.storedConstRootMonoType(store_view, stored, requested_ty),
            // An unimplemented declaration keeps its declared type; only the
            // value is missing, and reaching it crashes.
            .eval_template, .unimplemented => try self.lowerTypeView(requested_ty),
            .reserved => Common.invariant("reserved checked const template reached Monotype type selection"),
        };
    }

    fn constUseTypeNode(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        const_use: checked.ConstUseTemplate,
    ) Allocator.Error!NodeId {
        const requested_ty = const_use.requested_source_ty_payload orelse
            Common.invariant("checked const use reached Monotype without a requested checked type");
        const store_view = self.builder.moduleForId(checked.constModuleId(const_use.const_ref));
        const template = store_view.const_templates.get(const_use.const_ref);
        const requested_node = switch (template.state) {
            .stored_const => |stored| try self.storedConstRootTypeNode(store_view, stored, requested_ty),
            .eval_template, .unimplemented => try self.instNode(requested_ty),
            .reserved => Common.invariant("reserved checked const template reached Monotype type selection"),
        };
        return try self.relateCheckedNodeToProducedValue(try self.instNode(checked_ty), requested_node);
    }

    fn restoreConstUseAtType(
        self: *BodyContext,
        const_use: checked.ConstUseTemplate,
        ty: Type.TypeId,
        use_evidence: []const SpecEvidence,
    ) Allocator.Error!DraftExprId {
        const requested_ty = const_use.requested_source_ty_payload orelse
            Common.invariant("checked const use reached Monotype without a requested checked type");
        const previous_restore_evidence = self.restore_evidence;
        self.restore_evidence = rootEvidence(self.owner_template, use_evidence);
        defer self.restore_evidence = previous_restore_evidence;

        const store_view = self.builder.moduleForId(checked.constModuleId(const_use.const_ref));
        const template = store_view.const_templates.get(const_use.const_ref);
        return switch (template.state) {
            .stored_const => |stored| blk: {
                const stored_ty = try self.storedConstRootMonoType(store_view, stored, requested_ty);
                if (!self.sameType(ty, stored_ty)) {
                    Common.invariant("stored const representation differed from its expected Monotype type");
                }
                var active_const_scope: ActiveConstBindingScope = .{};
                const has_active_const_binding = try self.enterActiveConstBindingAtCell(
                    store_view,
                    const_use.const_ref,
                    try self.draftTypeCell(stored_ty),
                    &active_const_scope,
                );
                defer self.leaveActiveConstBinding(&active_const_scope);
                const restored = try self.restoredStaticDataCandidateNode(
                    store_view,
                    self.view,
                    stored.node,
                    stored_ty,
                    const_use.const_ref,
                    requested_ty,
                    .disallow,
                );
                if (has_active_const_binding) break :blk try self.finishActiveConstBinding(active_const_scope.active, restored);
                break :blk restored;
            },
            .reserved => Common.invariant("reserved checked const template reached Monotype"),
            .eval_template => |eval| blk: {
                try self.constrainTypeToMono(requested_ty, ty);
                break :blk try self.lowerConstEvalTemplateUse(store_view, eval, const_use.const_ref, ty, null, null);
            },
            .unimplemented => |declaration| blk: {
                try self.constrainTypeToMono(requested_ty, ty);
                const saved_loc = self.builder.current_loc;
                defer self.builder.current_loc = saved_loc;
                const saved_region = self.builder.current_region;
                defer self.builder.current_region = saved_region;
                self.builder.current_loc = try self.sourceLocFor(declaration.region);
                self.builder.current_region = declaration.region;
                break :blk try self.runtimeCrashExpr(ty, Common.unimplemented_declaration_crash);
            },
        };
    }

    /// Restore a checked const directly into the active specialization graph.
    /// This phase may add relations and deferred work, so it must not
    /// materialize a durable Monotype snapshot of `request_node`.
    fn restoreConstUseAtNode(
        self: *BodyContext,
        const_use: checked.ConstUseTemplate,
        request_node: NodeId,
        use_evidence: []const SpecEvidence,
    ) Allocator.Error!DraftExprId {
        const requested_ty = const_use.requested_source_ty_payload orelse
            Common.invariant("checked const use reached Monotype without a requested checked type");
        const previous_restore_evidence = self.restore_evidence;
        self.restore_evidence = rootEvidence(self.owner_template, use_evidence);
        defer self.restore_evidence = previous_restore_evidence;

        const store_view = self.builder.moduleForId(checked.constModuleId(const_use.const_ref));
        const template = store_view.const_templates.get(const_use.const_ref);
        return switch (template.state) {
            .stored_const => |stored| blk: {
                const stored_node = try self.storedConstRootTypeNode(store_view, stored, requested_ty);
                const interface_node = try self.instNode(requested_ty);
                try relateRequestComponent(self.graph, request_node, stored_node);
                var active_const_scope: ActiveConstBindingScope = .{};
                const has_active_const_binding = try self.enterActiveConstBindingAtCell(
                    store_view,
                    const_use.const_ref,
                    DraftTypeCell.fromGraphNode(interface_node),
                    &active_const_scope,
                );
                defer self.leaveActiveConstBinding(&active_const_scope);
                const restored = try self.restoredStaticDataCandidateNodeAtNode(
                    store_view,
                    self.view,
                    stored.node,
                    stored_node,
                    const_use.const_ref,
                    requested_ty,
                    .disallow,
                );
                if (has_active_const_binding) break :blk try self.finishActiveConstBinding(active_const_scope.active, restored);
                break :blk restored;
            },
            .reserved => Common.invariant("reserved checked const template reached Monotype"),
            .eval_template => |eval| blk: {
                try self.graph.unify(try self.instNode(requested_ty), request_node);
                break :blk try self.lowerConstEvalTemplateUseAtNode(
                    store_view,
                    eval,
                    const_use.const_ref,
                    request_node,
                    null,
                    null,
                );
            },
            .unimplemented => |declaration| blk: {
                try self.graph.unify(try self.instNode(requested_ty), request_node);
                const saved_loc = self.builder.current_loc;
                defer self.builder.current_loc = saved_loc;
                const saved_region = self.builder.current_region;
                defer self.builder.current_region = saved_region;
                self.builder.current_loc = try self.sourceLocFor(declaration.region);
                self.builder.current_region = declaration.region;
                break :blk try self.runtimeCrashExprAtCell(
                    DraftTypeCell.fromGraphNode(request_node),
                    Common.unimplemented_declaration_crash,
                );
            },
        };
    }

    /// Return the exact producer-owned runtime representation stored beside a
    /// ConstStore value. The checked source type is related to that witness
    /// here, and consumers use that representation directly instead of the
    /// source type or an incidental empty row.
    fn storedConstRootMonoType(
        self: *BodyContext,
        store_view: ModuleView,
        stored: checked.StoredConstTemplate,
        requested_ty: checked.CheckedTypeId,
    ) Allocator.Error!Type.TypeId {
        const stored_ty = try self.lowerConstCaptureType(store_view, stored.root_type);
        _ = try self.relateCheckedNodeToProducedValue(try self.instNode(requested_ty), try self.graph.importMonoIndependent(stored_ty));
        return stored_ty;
    }

    /// Return the active graph witness for a stored const root in the current
    /// request. Stored function values keep checked identity only, so graph
    /// restorations must not freeze their producer snapshot before the request
    /// has selected the callable signature that will re-lower the function.
    fn storedConstRootTypeNode(
        self: *BodyContext,
        store_view: ModuleView,
        stored: checked.StoredConstTemplate,
        requested_ty: checked.CheckedTypeId,
    ) Allocator.Error!NodeId {
        const stored_ty = try self.lowerConstCaptureType(store_view, stored.root_type);
        return try self.relateCheckedNodeToProducedValue(
            try self.instNode(requested_ty),
            try self.graph.importMonoIndependent(stored_ty),
        );
    }

    /// The edge of a template's root: its own quantified variables (no
    /// caller binds them) with the chain-free root evidence checking
    /// recorded for the template as contract provenance.
    fn rootEdgeEvidence(
        self: *BodyContext,
        view: ModuleView,
        template_ref: names.ProcTemplate,
        template: checked.CheckedProcedureTemplate,
    ) Allocator.Error!EdgeEvidence {
        return self.rootEdgeEvidenceForPurpose(view, template_ref, template, .body_lowering);
    }

    fn rootEdgeEvidenceForPurpose(
        self: *BodyContext,
        view: ModuleView,
        template_ref: names.ProcTemplate,
        template: checked.CheckedProcedureTemplate,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error!EdgeEvidence {
        const schema = templateSchemaIn(view, &template);
        const subst = try self.substitutionFromCheckedTypes(view, schema.scheme_vars);
        const refs = view.static_dispatch_plans.templateRootEvidence(template_ref.template);
        return .{
            .subst = subst,
            .vector = try self.deriveEvidenceVector(schema, subst, view, refs, purpose),
        };
    }

    fn lowerConstEvalTemplateUse(
        self: *BodyContext,
        store_view: ModuleView,
        eval: checked.ConstEvalTemplate,
        const_use: checked.ConstLocator,
        ty: Type.TypeId,
        source_region_override: ?base.Region,
        current_entry_root: ?EntryRoot,
    ) Allocator.Error!DraftExprId {
        return try self.lowerConstEvalTemplateUseAtNode(
            store_view,
            eval,
            const_use,
            try self.activeNodeFromType(ty),
            source_region_override,
            current_entry_root,
        );
    }

    fn lowerConstEvalTemplateUseAtNode(
        self: *BodyContext,
        store_view: ModuleView,
        eval: checked.ConstEvalTemplate,
        const_use: checked.ConstLocator,
        request_node: NodeId,
        source_region_override: ?base.Region,
        current_entry_root: ?EntryRoot,
    ) Allocator.Error!DraftExprId {
        const body = store_view.checked_const_bodies.get(eval.body);
        if (self.builder.comptimeValueReadDeclared(store_view, body.root)) {
            return self.declaredComptimeValueRead(store_view, body.root, DraftTypeCell.fromGraphNode(request_node), const_use);
        }
        const entry_template = store_view.templates.get(eval.entry_template.template);

        var body_ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self.builder,
            store_view,
            self.method_scope,
            eval.entry_template,
            self.graph,
            self.draft,
        );
        defer body_ctx.deinit();
        try body_ctx.inheritActiveConstBinding(self);
        const schema = templateSchemaIn(store_view, &entry_template);
        const root_evidence: EdgeEvidence = if (self.restore_evidence.vector.len < entry_template.evidence_params.len)
            try body_ctx.rootEdgeEvidence(store_view, eval.entry_template, entry_template)
        else
            .{
                .subst = try body_ctx.substitutionFromCheckedTypes(store_view, schema.scheme_vars),
                .vector = self.restore_evidence.vector,
            };
        body_ctx.evidence = rootEvidenceWithSubstitution(eval.entry_template, schema, root_evidence);
        try body_ctx.seedSubstitution(schema, root_evidence.subst);
        body_ctx.source_region_override = source_region_override;
        body_ctx.current_entry_root = current_entry_root orelse .{
            .module = store_view.key,
            .root = body.root,
        };

        var active_const_scope: ActiveConstBindingScope = .{};
        const has_active_const_binding = try body_ctx.enterActiveConstBindingAtCell(
            store_view,
            const_use,
            DraftTypeCell.fromGraphNode(request_node),
            &active_const_scope,
        );
        defer body_ctx.leaveActiveConstBinding(&active_const_scope);

        // A checked source key is stable while the request remains a live
        // graph node. Nested specializations additionally key their concrete
        // request through the draft graph, so no provisional TypeId digest is
        // needed here.
        const root_fn_key = store_view.types.rootKey(entry_template.checked_fn_root);
        body_ctx.owner_context_fn_key = root_fn_key;
        body_ctx.current_fn_key = root_fn_key;

        const wrapper_fn_node = try body_ctx.graphFunctionNode(&.{}, request_node);
        try self.graph.unify(
            try body_ctx.instNode(entry_template.checked_fn_root),
            wrapper_fn_node,
        );
        try self.graph.unify(try body_ctx.instNode(body.checked_type), request_node);

        const restored = try body_ctx.lowerComptimeRootExprAtCell(
            body.body_expr,
            DraftTypeCell.fromGraphNode(request_node),
        );
        if (has_active_const_binding) return try body_ctx.finishActiveConstBinding(active_const_scope.active, restored);
        return restored;
    }

    fn restoreConstNodeAtType(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, node, ty, null);
    }

    fn restoreConstNodeAtTypeWithStaticRoot(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        return try runConstRestore(self, store_view, type_view, node, ty, static_data_const_locator);
    }

    fn startConstRestore(
        self: *BodyContext,
        store_view: ModuleView,
        _: ModuleView,
        node: checked.ConstNodeId,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!ConstRestoreStart(DraftExprId) {
        const value = store_view.const_store.get(node);
        const representation: ActiveConstNodeRepresentation = .{ .sealed = ty };
        const cell = DraftTypeCell.fromSealed(ty);
        if (try self.materializedConstNodeExpr(store_view, node, representation, cell, static_data_const_locator)) |existing| return .{ .done = existing };

        switch (value) {
            .fn_value => {},
            .tag, .record, .tuple => if (self.nominalConstructionLayer(ty)) |layer| {
                return .{ .layer = .{ .child = node, .backing = layer.backing, .named = layer.named } };
            },
            .nominal => |nominal| if (self.nominalConstructionLayer(ty)) |layer| {
                return .{ .layer = .{ .child = nominal.backing, .backing = layer.backing, .named = layer.named } };
            },
            .pending, .zst, .scalar, .str, .list, .box, .crash, .checked_error => {},
        }

        if (try self.activeConstNodeBindingExpr(store_view, node, representation, cell)) |active| return .{ .done = active };

        try self.reserveConstNodeBinding(store_view, node, representation, cell);
        switch (value) {
            .fn_value => |fn_id| {
                const lowered = try self.restoreConstFn(store_view, fn_id, ty, static_data_const_locator);
                return .{ .done = try self.finishRestoredConstNode(store_view, node, ty, lowered, static_data_const_locator) };
            },
            .pending, .zst, .scalar, .str, .list, .box, .tuple, .record, .crash, .checked_error, .tag, .nominal => return .{ .value = value },
        }
    }

    fn finishConstRestoreLayer(
        self: *BodyContext,
        store_view: ModuleView,
        _: ModuleView,
        node: checked.ConstNodeId,
        ty: Type.TypeId,
        named: Type.TypeId,
        backing_expr: DraftExprId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const materialized = try self.addExpr(.{ .ty = named, .data = .{ .nominal = backing_expr } });
        try self.cacheMaterializedConstNode(store_view, node, .{ .sealed = ty }, materialized, static_data_const_locator);
        return materialized;
    }

    fn finishConstRestoreData(
        self: *BodyContext,
        store_view: ModuleView,
        _: ModuleView,
        node: checked.ConstNodeId,
        ty: Type.TypeId,
        data: BodyExprData,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const lowered = try self.addExpr(.{ .ty = ty, .data = data });
        return try self.finishRestoredConstNode(store_view, node, ty, lowered, static_data_const_locator);
    }

    /// Complete a sealed constant node's reserved binding with its lowered
    /// expression and reuse it for later requests.
    fn finishRestoredConstNode(
        self: *BodyContext,
        store_view: ModuleView,
        node: checked.ConstNodeId,
        ty: Type.TypeId,
        lowered: DraftExprId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const representation: ActiveConstNodeRepresentation = .{ .sealed = ty };
        const materialized = try self.finishConstNodeBinding(store_view, node, representation, DraftTypeCell.fromSealed(ty), lowered);
        try self.cacheMaterializedConstNode(store_view, node, representation, materialized, static_data_const_locator);
        return materialized;
    }

    fn restoredStaticDataCandidateNode(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        ty: Type.TypeId,
        const_locator: checked.ConstLocator,
        checked_type: checked.CheckedTypeId,
        bare_fn: Builder.BareFnCandidate,
    ) Allocator.Error!DraftExprId {
        if (!moduleBytesEqual(checked.constModuleId(const_locator).bytes, store_view.key.bytes)) {
            Common.invariant("static-data const context referenced a different ConstStore module");
        }
        if (self.constRestorationIsClosed() and
            self.builder.static_data_literals and
            try self.builder.constNodeHasStableStaticDataRepresentation(store_view, node) and
            self.builder.constNodeMayUseStaticDataCandidate(store_view, node, bare_fn))
        {
            const id = try self.draftStaticDataRequest(
                const_locator,
                node,
                checked_type,
                DraftTypeCell.fromSealed(ty),
            );
            const address: StaticDataCandidateAddress = .{
                .static_data = id,
                .owner = self.draft.current_owner,
            };
            if (self.draft.static_data_candidate_exprs.get(address)) |existing| return existing;

            const runtime_expr = try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, node, ty, const_locator);
            const candidate_expr = try self.addExpr(.{ .ty = ty, .data = .{ .static_data_candidate = .{
                .static_data = id,
                .storage = constStaticDataStorage(store_view, node),
                .runtime_expr = runtime_expr,
            } } });
            try self.draft.static_data_candidate_exprs.put(address, candidate_expr);
            return candidate_expr;
        }
        return try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, node, ty, const_locator);
    }

    fn restoredStaticDataCandidateNodeAtNode(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        request_node: NodeId,
        const_locator: checked.ConstLocator,
        checked_type: checked.CheckedTypeId,
        bare_fn: Builder.BareFnCandidate,
    ) Allocator.Error!DraftExprId {
        if (!moduleBytesEqual(checked.constModuleId(const_locator).bytes, store_view.key.bytes)) {
            Common.invariant("static-data const context referenced a different ConstStore module");
        }
        const runtime_expr = try self.restoreConstNodeAtNodeWithStaticRoot(
            store_view,
            type_view,
            node,
            request_node,
            const_locator,
        );
        if (self.constRestorationIsClosed() and
            self.builder.static_data_literals and
            try self.builder.constNodeHasStableStaticDataRepresentation(store_view, node) and
            self.builder.constNodeMayUseStaticDataCandidate(store_view, node, bare_fn))
        {
            const id = try self.draftStaticDataRequest(
                const_locator,
                node,
                checked_type,
                DraftTypeCell.fromGraphNode(request_node),
            );
            return try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(request_node), .{ .static_data_candidate = .{
                .static_data = id,
                .storage = constStaticDataStorage(store_view, node),
                .runtime_expr = runtime_expr,
            } });
        }
        return runtime_expr;
    }

    fn restoreConstNodeAtNode(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        request_node: NodeId,
    ) Allocator.Error!DraftExprId {
        return try self.restoreConstNodeAtNodeWithStaticRoot(
            store_view,
            type_view,
            node,
            request_node,
            null,
        );
    }

    /// A constant node restoring at a graph node. Its children restore at
    /// child nodes computed as a recursive walk would reach them.
    const ConstAtNodeFrame = struct {
        node: checked.ConstNodeId,
        request_node: NodeId,
        value: checked.ConstValue,
        /// How the node's expression is built once its children are restored.
        form: enum { constructor, nominal, data },
        /// A nominal's representation node.
        representation_node: NodeId = undefined,
        /// A box's payload or a nominal's backing.
        single_child: ?checked.ConstNodeId = null,
        children: []const checked.ConstNodeId = &.{},
        /// Each child's graph node, except a tag's, which is computed as its
        /// payload is reached. Owned.
        child_nodes: []NodeId = &.{},
        /// A record's field names, in stored child order. Owned.
        field_names: []@FieldType(InstField, "name") = &.{},
        tag_name: names.TagNameId = undefined,
        lowered: std.ArrayListUnmanaged(DraftExprId) = .empty,

        fn childCount(frame: *const ConstAtNodeFrame) usize {
            return if (frame.single_child != null) 1 else frame.children.len;
        }

        fn deinit(frame: *ConstAtNodeFrame, allocator: Allocator) void {
            allocator.free(frame.child_nodes);
            allocator.free(frame.field_names);
            frame.lowered.deinit(allocator);
        }
    };

    fn restoreConstNodeAtNodeWithStaticRoot(
        self: *BodyContext,
        store_view: ModuleView,
        _: ModuleView,
        root: checked.ConstNodeId,
        root_request_node: NodeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        var frames: std.ArrayListUnmanaged(ConstAtNodeFrame) = .empty;
        defer {
            for (frames.items) |*frame| frame.deinit(self.allocator);
            frames.deinit(self.allocator);
        }
        var delivered = try self.beginConstAtNode(&frames, store_view, root, root_request_node, static_data_const_locator);
        while (frames.items.len != 0) {
            const frame = &frames.items[frames.items.len - 1];
            if (delivered) |lowered| try frame.lowered.append(self.allocator, lowered);
            delivered = null;
            if (frame.lowered.items.len < frame.childCount()) {
                const index = frame.lowered.items.len;
                const child = frame.single_child orelse frame.children[index];
                const child_node = switch (frame.value) {
                    .tag => try self.graph.tagConstructionPayloadNode(frame.request_node, frame.tag_name, index),
                    .pending, .zst, .scalar, .str, .crash, .checked_error, .list, .box, .tuple, .record, .nominal, .fn_value => frame.child_nodes[index],
                };
                delivered = try self.beginConstAtNode(&frames, store_view, child, child_node, static_data_const_locator);
                continue;
            }
            var finished = frames.pop().?;
            defer finished.deinit(self.allocator);
            delivered = try self.finishConstAtNode(store_view, &finished, static_data_const_locator);
        }
        return delivered.?;
    }

    /// Start one node restoring at `request_node`: its expression when it is
    /// already built or has no children, else the frame restoring them.
    fn beginConstAtNode(
        self: *BodyContext,
        frames: *std.ArrayListUnmanaged(ConstAtNodeFrame),
        store_view: ModuleView,
        node: checked.ConstNodeId,
        request_node: NodeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!?DraftExprId {
        const value = store_view.const_store.get(node);
        const representation: ActiveConstNodeRepresentation = .{ .graph = request_node };
        const cell = DraftTypeCell.fromGraphNode(request_node);
        if (try self.materializedConstNodeExpr(store_view, node, representation, cell, static_data_const_locator)) |existing| return existing;
        if (try self.activeConstNodeBindingExpr(store_view, node, representation, cell)) |active| return active;

        try self.reserveConstNodeBinding(store_view, node, representation, cell);
        var frame = ConstAtNodeFrame{ .node = node, .request_node = request_node, .value = value, .form = .data };
        var frame_owned = true;
        errdefer if (frame_owned) frame.deinit(self.allocator);
        switch (value) {
            .fn_value => |fn_id| {
                const lowered = try self.restoreConstFnAtNodeWithStaticRoot(
                    store_view,
                    fn_id,
                    request_node,
                    static_data_const_locator,
                );
                const materialized = try self.finishConstNodeBinding(store_view, node, representation, cell, lowered);
                try self.cacheMaterializedConstNode(store_view, node, representation, materialized, static_data_const_locator);
                return materialized;
            },
            .tag, .record, .tuple => frame.form = .constructor,
            .nominal => |nominal| {
                frame.form = .nominal;
                frame.representation_node = (try self.constructorRepresentationNode(request_node));
                if ((try self.graph.content(frame.representation_node)) != .named) {
                    Common.invariant("ConstStore nominal restored without a nominal graph representation");
                }
                const named = (try self.graph.namedNodes(frame.representation_node));
                const backing = named.backing orelse
                    Common.invariant("ConstStore nominal restored with a named graph node that had no backing");
                frame.single_child = nominal.backing;
                frame.child_nodes = try self.allocator.dupe(NodeId, &.{backing.node});
            },
            .pending, .zst, .scalar, .str, .list, .box, .crash, .checked_error => {},
        }
        switch (value) {
            .list => |list| switch (list) {
                .nodes => |items| {
                    const element_node = try self.graph.listElementNode(request_node);
                    frame.children = items;
                    frame.child_nodes = try self.allocator.alloc(NodeId, items.len);
                    @memset(frame.child_nodes, element_node);
                },
                .empty, .packed_bytes => {},
            },
            .box => |payload| {
                frame.single_child = payload;
                frame.child_nodes = try self.allocator.dupe(NodeId, &.{try self.graph.boxElementNode(request_node)});
            },
            .tuple => |items| {
                const item_nodes = try self.graph.tupleItemNodes(request_node);
                if (item_nodes.len != items.len) Common.invariant("ConstStore tuple length differs from checked graph type");
                frame.children = items;
                frame.child_nodes = try self.allocator.dupe(NodeId, item_nodes);
            },
            .record => |items| {
                // ConstStore record children follow the lexicographic Monotype
                // field order used to build the LIR const plan, not the
                // checked constructor's original row-fragment order. Read the
                // flattened backing row so every stored child is paired with
                // its exact graph field cell.
                const record_node = switch ((try self.graph.content(request_node))) {
                    .named => |named| (named.backing orelse
                        Common.invariant("ConstStore record restored through a named graph node without a backing")).node,
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => request_node,
                };
                const graph_fields = (try self.graph.recordNodes(record_node)).fields;
                if (graph_fields.len != items.len) Common.invariant("ConstStore record length differs from checked graph type");
                const fields = try self.allocator.dupe(InstField, graph_fields);
                defer self.allocator.free(fields);
                std.mem.sort(
                    InstField,
                    fields,
                    self.nameStore(),
                    instRecordFieldLessThan,
                );
                frame.children = items;
                frame.child_nodes = try self.allocator.alloc(NodeId, fields.len);
                frame.field_names = try self.allocator.alloc(@FieldType(InstField, "name"), fields.len);
                for (fields, frame.child_nodes, frame.field_names) |field, *child_node, *name| {
                    child_node.* = field.ty;
                    name.* = field.name;
                }
            },
            .tag => |tag| {
                frame.tag_name = try self.nameStoreMut().internTagLabel(tag.tag_name);
                frame.children = tag.payloads;
            },
            .pending, .zst, .scalar, .str, .crash, .checked_error, .nominal, .fn_value => {},
        }
        if (frame.childCount() == 0) {
            frame_owned = false;
            defer frame.deinit(self.allocator);
            return try self.finishConstAtNode(store_view, &frame, static_data_const_locator);
        }
        try frames.append(self.allocator, frame);
        frame_owned = false;
        return null;
    }

    /// Build a node restored at a graph node from its restored children,
    /// completing its reserved binding.
    fn finishConstAtNode(
        self: *BodyContext,
        store_view: ModuleView,
        frame: *const ConstAtNodeFrame,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const request_node = frame.request_node;
        const lowered_children = frame.lowered.items;
        const cell = DraftTypeCell.fromGraphNode(request_node);
        const lowered = switch (frame.form) {
            .nominal => try self.addExprWithTypeCell(
                DraftTypeCell.fromGraphNode(frame.representation_node),
                .{ .nominal = lowered_children[0] },
            ),
            .constructor, .data => blk: {
                const data: BodyExprData = switch (frame.value) {
                    .pending => Common.invariant("pending ConstStore node reached Monotype restore"),
                    .zst => .unit,
                    .scalar => |scalar| restoreScalar(BodyExprData, scalar),
                    .str => |str| .{ .str_lit = try self.addStringView(
                        store_view.const_store.blobData(str.data),
                        str.offset,
                        str.len,
                    ) },
                    .crash => |str| .{ .crash = try self.addStringView(
                        store_view.const_store.blobData(str.data),
                        str.offset,
                        str.len,
                    ) },
                    .checked_error => |str| .{ .checked_error = try self.addStringView(
                        store_view.const_store.blobData(str.data),
                        str.offset,
                        str.len,
                    ) },
                    .list => |list| switch (list) {
                        .nodes => .{ .list = try self.addExprSpan(lowered_children) },
                        .empty => |capacity| try self.constEmptyListData(capacity),
                        .packed_bytes => |packed_list| .{ .bytes_lit = .{
                            .literal = try self.addConstBlobView(
                                store_view.key.bytes,
                                packed_list.bytes.data,
                                store_view.const_store.blobData(packed_list.bytes.data),
                                packed_list.bytes.offset,
                                packed_list.bytes.len,
                            ),
                            .len = packed_list.len,
                            .element = packed_list.element,
                            .product_width = packed_list.product_width,
                        } },
                    },
                    .box => .{ .low_level = .{
                        .op = .box_box,
                        .args = try self.addExprSpan(lowered_children),
                    } },
                    .tuple => .{ .tuple = try self.addExprSpan(lowered_children) },
                    .record => record: {
                        const fields = try self.allocator.alloc(DraftFieldExpr, lowered_children.len);
                        defer self.allocator.free(fields);
                        for (fields, frame.field_names, lowered_children) |*field, name, value| {
                            field.* = .{ .name = name, .value = value };
                        }
                        break :record .{ .record = try self.addFieldExprSpan(fields) };
                    },
                    .tag => .{ .tag = .{
                        .name = frame.tag_name,
                        .payloads = try self.addExprSpan(lowered_children),
                    } },
                    .nominal => Common.invariant("ConstStore nominal must be restored as an expression"),
                    .fn_value => Common.invariant("ConstStore function value must be restored as an expression"),
                };
                break :blk if (frame.form == .constructor)
                    try self.addConstructorExprAtNode(request_node, data)
                else
                    try self.addExprWithTypeCell(cell, data);
            },
        };
        const representation: ActiveConstNodeRepresentation = .{ .graph = request_node };
        const materialized = try self.finishConstNodeBinding(store_view, frame.node, representation, cell, lowered);
        try self.cacheMaterializedConstNode(store_view, frame.node, representation, materialized, static_data_const_locator);
        return materialized;
    }

    /// Forwards to the scope that owns the type store; the query itself
    /// has one implementation.
    fn constListElemType(self: *BodyContext, ty: Type.TypeId) Type.TypeId {
        return switch (self.typeStore().get(ty)) {
            .list => |elem_ty| elem_ty,
            .primitive, .named, .record, .tuple, .tag_union, .box, .func, .erased, .zst => Common.invariant("restored list constant had a non-list monotype type"),
        };
    }

    /// Forwards to the scope that owns the type store; the query itself
    /// has one implementation.
    fn constBoxPayloadType(self: *BodyContext, ty: Type.TypeId) Type.TypeId {
        return switch (self.typeStore().get(ty)) {
            .box => |elem_ty| elem_ty,
            .primitive, .named, .record, .tuple, .tag_union, .list, .func, .erased, .zst => Common.invariant("restored box constant had a non-box monotype type"),
        };
    }

    fn lowerConstCaptureType(
        self: *BodyContext,
        store_view: ModuleView,
        ty: check.ConstStore.ConstTypeId,
    ) Allocator.Error!Type.TypeId {
        var map = collections.DenseMap(check.ConstStore.ConstTypeId, Type.TypeId).init(self.allocator);
        defer map.deinit();
        const transaction = self.typeStore().beginTransaction();
        errdefer transaction.abort(self.typeStore());
        const speculative = try self.lowerConstCaptureTypeInner(store_view, ty, &map);
        var result = try self.typeStore().commitTransaction(
            self.nameStore(),
            transaction,
            speculative,
        );
        defer result.deinit();
        var lowered_types = map.valueIterator();
        while (lowered_types.next()) |lowered| {
            lowered.* = result.remapType(lowered.*);
        }
        return result.root;
    }

    /// One step of lowering a stored const type: a child type, or a label to
    /// intern into the program's name store, in the order lowering takes them.
    const ConstCaptureTypeOp = union(enum) {
        child: check.ConstStore.ConstTypeId,
        field_name: names.RecordFieldNameId,
        field_default: ?check.ConstStore.TypeFieldDefault,
        tag_name: names.TagNameId,
        /// A named type's definition, interned between its declared order and
        /// its backing.
        named_def: check.ConstStore.TypeDef,
        /// A named type's lowered arguments, the first `count` results, added
        /// as a span before its backing lowers.
        args_span: usize,
    };

    /// A step's result, read back by the frame that ran it.
    const ConstCaptureTypeResult = union(enum) {
        ty: Type.TypeId,
        field_name: names.RecordFieldNameId,
        field_default: ?Type.FieldDefault,
        tag_name: names.TagNameId,
        named_def: Type.TypeDef,
        span: Type.Span,
    };

    const ConstCaptureTypeFrame = struct {
        ty: check.ConstStore.ConstTypeId,
        /// Null for an alias, which shares its backing's type.
        slot: ?Type.Store.RecursiveSlot,
        ops_start: usize,
        next: usize,
        results_start: usize,
    };

    /// Lower a stored const type, memoized in `map`. Each composite type is
    /// an explicit frame whose steps run in order, so type depth never
    /// becomes native call depth.
    fn lowerConstCaptureTypeInner(
        self: *BodyContext,
        store_view: ModuleView,
        root: check.ConstStore.ConstTypeId,
        map: *collections.DenseMap(check.ConstStore.ConstTypeId, Type.TypeId),
    ) Allocator.Error!Type.TypeId {
        var frames: std.ArrayListUnmanaged(ConstCaptureTypeFrame) = .empty;
        defer frames.deinit(self.allocator);
        var ops: std.ArrayListUnmanaged(ConstCaptureTypeOp) = .empty;
        defer ops.deinit(self.allocator);
        var results: std.ArrayListUnmanaged(ConstCaptureTypeResult) = .empty;
        defer results.deinit(self.allocator);
        errdefer for (frames.items) |frame| {
            _ = map.remove(frame.ty);
            if (frame.slot) |slot| {
                self.typeStore().abortRecursive(slot);
                break;
            }
        };

        if (try self.enterConstCaptureType(store_view, root, map, &frames, &ops, results.items.len)) |ty| return ty;
        while (true) {
            const index = frames.items.len - 1;
            const frame = frames.items[index];
            if (frame.next < ops.items.len) {
                const op = ops.items[frame.next];
                frames.items[index].next += 1;
                const result: ConstCaptureTypeResult = switch (op) {
                    .child => |child| if (try self.enterConstCaptureType(store_view, child, map, &frames, &ops, results.items.len)) |ty| .{ .ty = ty } else continue,
                    .field_name => |name| .{ .field_name = try self.constRecordFieldName(store_view, name) },
                    .field_default => |default| .{ .field_default = try self.constFieldDefault(store_view, default) },
                    .tag_name => |name| .{ .tag_name = try self.constTagName(store_view, name) },
                    .named_def => |def| .{ .named_def = try self.constTypeDef(store_view, def) },
                    .args_span => |count| .{ .span = try self.addConstCaptureTypeSpan(results.items[frame.results_start..][0..count]) },
                };
                try results.append(self.allocator, result);
                continue;
            }

            const ty = try self.finishConstCaptureType(store_view, map, frame, results.items[frame.results_start..]);
            _ = frames.pop();
            ops.shrinkRetainingCapacity(frame.ops_start);
            results.shrinkRetainingCapacity(frame.results_start);
            if (frames.items.len == 0) return ty;
            try results.append(self.allocator, .{ .ty = ty });
        }
    }

    /// The lowered type when it is memoized; otherwise push the frame that
    /// lowers it.
    fn enterConstCaptureType(
        self: *BodyContext,
        store_view: ModuleView,
        ty: check.ConstStore.ConstTypeId,
        map: *collections.DenseMap(check.ConstStore.ConstTypeId, Type.TypeId),
        frames: *std.ArrayListUnmanaged(ConstCaptureTypeFrame),
        ops: *std.ArrayListUnmanaged(ConstCaptureTypeOp),
        results_start: usize,
    ) Allocator.Error!?Type.TypeId {
        if (map.get(ty)) |existing| return existing;
        const gpa = self.allocator;
        const type_store = &store_view.const_store.type_store;
        const stored = type_store.get(ty);
        const ops_start = ops.items.len;
        // Stored aliases retain the checked acyclic backing chain. Memoize
        // their runtime identity without recreating source-only wrappers.
        const slot: ?Type.Store.RecursiveSlot = if (stored == .named and stored.named.kind == .alias) null else blk: {
            const reserved = try self.typeStore().beginRecursive();
            try map.put(ty, reserved.ty);
            break :blk reserved;
        };
        try frames.append(gpa, .{ .ty = ty, .slot = slot, .ops_start = ops_start, .next = ops_start, .results_start = results_start });
        if (slot == null) {
            const backing = stored.named.backing orelse
                Common.invariant("stored transparent alias had no backing type");
            try ops.append(gpa, .{ .child = backing.ty });
            return null;
        }
        switch (stored) {
            .primitive, .zst, .erased => {},
            .list, .box => |elem| try ops.append(gpa, .{ .child = elem }),
            .tuple => |items| for (type_store.typeSpan(items)) |item| try ops.append(gpa, .{ .child = item }),
            .func => |func| {
                for (type_store.typeSpan(func.args)) |arg| try ops.append(gpa, .{ .child = arg });
                try ops.append(gpa, .{ .child = func.ret });
            },
            .record => |fields| for (type_store.fieldSpan(fields)) |field| {
                try ops.append(gpa, .{ .field_name = field.name });
                try ops.append(gpa, .{ .child = field.ty });
                if (field.value_ty) |value_ty| try ops.append(gpa, .{ .child = value_ty });
                try ops.append(gpa, .{ .field_default = field.default });
            },
            .tag_union => |tags| for (type_store.tagSpan(tags)) |tag| {
                for (type_store.typeSpan(tag.payloads)) |payload| try ops.append(gpa, .{ .child = payload });
                try ops.append(gpa, .{ .tag_name = tag.name });
                try ops.append(gpa, .{ .tag_name = tag.checked_name });
            },
            .named => |named| {
                for (type_store.typeSpan(named.args)) |arg| try ops.append(gpa, .{ .child = arg });
                for (type_store.declaredFieldSpan(named.declared_order)) |entry| switch (entry) {
                    .named => |name| try ops.append(gpa, .{ .field_name = name }),
                    .padding => |padding| try ops.append(gpa, .{ .child = padding }),
                };
                try ops.append(gpa, .{ .named_def = named.def });
                try ops.append(gpa, .{ .args_span = type_store.typeSpan(named.args).len });
                if (named.backing) |backing| try ops.append(gpa, .{ .child = backing.ty });
            },
        }
        return null;
    }

    fn finishConstCaptureType(
        self: *BodyContext,
        store_view: ModuleView,
        map: *collections.DenseMap(check.ConstStore.ConstTypeId, Type.TypeId),
        frame: ConstCaptureTypeFrame,
        results: []const ConstCaptureTypeResult,
    ) Allocator.Error!Type.TypeId {
        const slot = frame.slot orelse {
            const backing = results[0].ty;
            try map.put(frame.ty, backing);
            return backing;
        };
        const gpa = self.allocator;
        const type_store = &store_view.const_store.type_store;
        var cursor: usize = 0;
        const content: Type.Content = switch (type_store.get(frame.ty)) {
            .primitive => |primitive| .{ .primitive = monotypePrimitive(primitive) },
            .zst => .zst,
            .erased => |erased| .{ .erased = erased },
            .list => .{ .list = results[0].ty },
            .box => .{ .box = results[0].ty },
            .tuple => .{ .tuple = try self.addConstCaptureTypeSpan(results) },
            .func => .{ .func = .{
                .args = try self.addConstCaptureTypeSpan(results[0 .. results.len - 1]),
                .ret = results[results.len - 1].ty,
            } },
            .record => |fields| blk: {
                const source = type_store.fieldSpan(fields);
                const out = try gpa.alloc(Type.Field, source.len);
                defer gpa.free(out);
                for (source, out) |field, *slot_out| {
                    const name = results[cursor].field_name;
                    const field_ty = results[cursor + 1].ty;
                    cursor += 2;
                    const value_ty: ?Type.TypeId = if (field.value_ty != null) value_blk: {
                        const lowered = results[cursor].ty;
                        cursor += 1;
                        break :value_blk lowered;
                    } else null;
                    const default = results[cursor].field_default;
                    cursor += 1;
                    slot_out.* = .{ .name = name, .ty = field_ty, .value_ty = value_ty, .default = default };
                }
                break :blk .{ .record = try self.typeStore().addRecordFields(self.nameStore(), out) };
            },
            .tag_union => |tags| blk: {
                const source = type_store.tagSpan(tags);
                const out = try gpa.alloc(Type.Tag, source.len);
                defer gpa.free(out);
                for (source, out) |tag, *slot_out| {
                    const payload_count = type_store.typeSpan(tag.payloads).len;
                    const payloads = results[cursor..][0..payload_count];
                    cursor += payload_count;
                    const name = results[cursor].tag_name;
                    const checked_name = results[cursor + 1].tag_name;
                    cursor += 2;
                    slot_out.* = .{ .name = name, .checked_name = checked_name, .payloads = try self.addConstCaptureTypeSpan(payloads) };
                }
                break :blk .{ .tag_union = try self.typeStore().addTagVariants(self.nameStore(), out) };
            },
            .named => |named| blk: {
                const arg_count = type_store.typeSpan(named.args).len;
                cursor = arg_count;
                const declared = type_store.declaredFieldSpan(named.declared_order);
                const out_declared = try gpa.alloc(Type.DeclaredField, declared.len);
                defer gpa.free(out_declared);
                for (declared, out_declared) |entry, *slot_out| {
                    slot_out.* = switch (entry) {
                        .named => .{ .named = results[cursor].field_name },
                        .padding => .{ .padding = results[cursor].ty },
                    };
                    cursor += 1;
                }
                const def = results[cursor].named_def;
                const args_span = results[cursor + 1].span;
                cursor += 2;
                break :blk .{ .named = .{
                    .named_type = .{
                        .module = named.named_type.module,
                        .ty = named.named_type.ty,
                    },
                    .def = def,
                    .kind = monotypeNamedKind(named.kind),
                    .builtin_owner = named.builtin_owner,
                    .args = args_span,
                    .backing = if (named.backing) |backing| .{
                        .ty = results[cursor].ty,
                        .use = monotypeBackingUse(backing.use),
                        .authority = monotypeBackingAuthority(backing.authority),
                    } else null,
                    .declared_order = try self.typeStore().addDeclaredFields(out_declared),
                } };
            },
        };
        self.typeStore().finishRecursive(slot, content);
        return slot.ty;
    }

    fn addConstCaptureTypeSpan(self: *BodyContext, results: []const ConstCaptureTypeResult) Allocator.Error!Type.Span {
        const tys = try self.allocator.alloc(Type.TypeId, results.len);
        defer self.allocator.free(tys);
        for (results, tys) |result, *ty| ty.* = result.ty;
        return try self.typeStore().addSpan(tys);
    }

    fn constRecordFieldName(
        self: *BodyContext,
        store_view: ModuleView,
        name: names.RecordFieldNameId,
    ) Allocator.Error!names.RecordFieldNameId {
        return try self.nameStoreMut().internRecordFieldLabel(store_view.names.recordFieldLabelText(name));
    }

    /// Re-intern a field default's declaring-module identity from the const
    /// store's name table into the program name store, like
    /// `constRecordFieldName` does for the label.
    fn constFieldDefault(
        self: *BodyContext,
        store_view: ModuleView,
        default: ?check.ConstStore.TypeFieldDefault,
    ) Allocator.Error!?Type.FieldDefault {
        const field_default = default orelse return null;
        return .{
            .module = try self.nameStoreMut().internModuleIdentity(store_view.names.moduleIdentityBytes(field_default.module)),
            .expr_node = field_default.expr_node,
        };
    }

    fn constTagName(
        self: *BodyContext,
        store_view: ModuleView,
        name: names.TagNameId,
    ) Allocator.Error!names.TagNameId {
        return try self.nameStoreMut().internTagLabel(store_view.names.tagLabelText(name));
    }

    fn constTypeDef(
        self: *BodyContext,
        store_view: ModuleView,
        def: check.ConstStore.TypeDef,
    ) Allocator.Error!Type.TypeDef {
        return .{
            .module = try self.nameStoreMut().internModuleIdentity(store_view.names.moduleIdentityBytes(def.module)),
            .type_name = try self.nameStoreMut().internTypeName(store_view.names.typeNameText(def.type_name)),
            .source_decl = def.source_decl,
            .generated = def.generated,
            .iterator_representation = def.iterator_representation,
            .iterator_kind = def.iterator_kind,
            .iterator_depth = def.iterator_depth,
            .iterator_topology = if (def.iterator_topology) |topology| .{
                .len_field = try self.constRecordFieldName(store_view, topology.len_field),
                .step_field = try self.constRecordFieldName(store_view, topology.step_field),
                .known_tag = try self.constTagName(store_view, topology.known_tag),
                .unknown_tag = try self.constTagName(store_view, topology.unknown_tag),
                .done_tag = try self.constTagName(store_view, topology.done_tag),
                .one_tag = try self.constTagName(store_view, topology.one_tag),
                .skip_tag = try self.constTagName(store_view, topology.skip_tag),
                .item_field = try self.constRecordFieldName(store_view, topology.item_field),
                .rest_field = try self.constRecordFieldName(store_view, topology.rest_field),
            } else null,
        };
    }

    /// Forwards to the scope that owns the type store; the query itself
    /// has one implementation.
    fn constRecordFields(self: *BodyContext, ty: Type.TypeId) Type.StoreSpanBorrow(Type.Field, "fields") {
        return switch (self.typeStore().get(ty)) {
            .record => |fields| self.typeStore().fieldSpan(fields),
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("restored record constant had a non-record monotype type"),
        };
    }

    fn restoreConstFnAtNode(
        self: *BodyContext,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        request_fn_node: NodeId,
    ) Allocator.Error!DraftExprId {
        return try self.restoreConstFnAtNodeWithStaticRoot(
            store_view,
            fn_id,
            request_fn_node,
            null,
        );
    }

    fn restoreConstFnAtNodeWithStaticRoot(
        self: *BodyContext,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        request_fn_node: NodeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const raw = @backingInt(fn_id);
        if (raw >= store_view.const_store.fns.items.len) Common.invariant("ConstStore function id is out of range");
        const fn_value = store_view.const_store.getFn(@fromBackingInt(@intCast(raw)));
        switch (fn_value.fn_def) {
            .parser_runtime => return try self.restoreConstCodecRuntimeFnAtNode(
                .parser,
                store_view,
                fn_id,
                fn_value,
                request_fn_node,
                static_data_const_locator,
            ),
            .encoder_for_runtime => return try self.restoreConstCodecRuntimeFnAtNode(
                .encoder,
                store_view,
                fn_id,
                fn_value,
                request_fn_node,
                static_data_const_locator,
            ),
            .local_template, .imported_template, .nested, .local_hosted, .imported_hosted, .checked_generated => {},
        }
        if (fn_value.evidence_frames.len == 0 or fn_value.evidence_frame_head == null) {
            Common.invariant("stored checked function did not contain an explicit evidence root frame");
        }
        const retained_evidence = try self.materializeConstFnEvidence(fn_value);
        _ = self.builder.moduleForConstFnDef(fn_value.fn_def);
        const checked_template = templateForConstFnDef(fn_value.fn_def);
        // The recording owner template lives in its OWN module (for a
        // default-root stored function, the fn's module is the declaring
        // module, not the owner's).
        _ = self.builder.moduleForDigest(names.procTemplateModuleDigest(checked_template)).templates.get(checked_template.template);
        const fn_def = try self.builder.constFnDefToMono(fn_value.fn_def);
        if (fn_value.captures.len != 0) {
            return try self.restoreCapturingConstFnAtNode(
                store_view,
                fn_value,
                fn_def,
                request_fn_node,
                retained_evidence,
                static_data_const_locator,
            );
        }
        const restored_fn = try self.restoreConstFnTemplateAt(
            fn_value,
            fn_def,
            fn_value.source_fn_ty,
            fn_value.source_fn_key,
            retained_evidence,
            request_fn_node,
        );
        return try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(request_fn_node),
            .{ .fn_def = .{ .fn_id = restored_fn } },
        );
    }

    /// Restore a compile-time function value's template into a draft target.
    ///
    /// The two call sites take their source function type and key from
    /// different places: one from the stored `ConstFn`, one from the
    /// `FnTemplate` being specialized. Both travel as explicit arguments
    /// rather than being read off whichever record the caller happened to
    /// hold, because that choice is the caller's and not this function's.
    fn restoreConstFnTemplateAt(
        self: *BodyContext,
        fn_value: check.ConstStore.ConstFn,
        fn_def: Ast.FnDef,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        retained_evidence: EvidenceChain,
        request_fn_node: NodeId,
    ) Allocator.Error!DraftFnTarget {
        return switch (fn_def) {
            .nested => |nested| {
                const fn_view = self.builder.moduleForConstFnDef(fn_value.fn_def);
                var fn_ctx = try BodyContext.initWithMethodScope(
                    self.allocator,
                    self.builder,
                    fn_view,
                    self.method_scope,
                    ownerTemplateForConstFnDef(fn_value.fn_def),
                    self.graph,
                    self.draft,
                );
                fn_ctx.in_default_expr = constFnDefIsDefaultRoot(fn_value.fn_def);
                fn_ctx.evidence = retained_evidence;
                fn_ctx.inheritFrozenEmissionContext(self);
                defer fn_ctx.deinit();
                try fn_ctx.inheritActiveConstBinding(self);
                try fn_ctx.replayStoredEvidenceRelations(fn_ctx.evidence);
                fn_ctx.current_fn_key = nested.context_fn_key;
                const restored_local_proc_entries = try fn_ctx.enterRestoredLocalProcScope(nested, nested.context_fn_key);
                defer if (restored_local_proc_entries) |entries| fn_ctx.allocator.free(entries);
                return try self.builder.lowerDraftNestedFromContext(
                    &fn_ctx,
                    fn_ctx.draft.current_owner,
                    checkedLambdaExprIdForConstFn(fn_view, fn_value.fn_def),
                    nested,
                    source_fn_ty,
                    source_fn_key,
                    request_fn_node,
                    &.{},
                    fn_ctx.evidence,
                    null,
                    false,
                    .exact_graph,
                    .inherit,
                );
            },
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => blk: {
                const template_ref = templateForConstFnDef(fn_value.fn_def);
                const template_view = self.builder.moduleForDigest(names.procTemplateModuleDigest(template_ref));
                const template = template_view.templates.get(template_ref.template);
                // The stored value retains its dispatch selections; only the
                // substitution is read back from the restoring request.
                const subst = try self.substitutionAtRequest(templateSchemaIn(template_view, &template), request_fn_node);
                break :blk try self.requireLocalDraftSlot(try self.builder.lowerDraftTemplateFromContext(
                    self,
                    template_ref,
                    source_fn_ty,
                    source_fn_key,
                    request_fn_node,
                    .{ .subst = subst, .vector = retained_evidence.vector },
                    .instantiation,
                    .independent_roots,
                    .inherit,
                ));
            },
        };
    }

    fn restoreCapturingConstFnAtNode(
        self: *BodyContext,
        store_view: ModuleView,
        fn_value: check.ConstStore.ConstFn,
        fn_def: Ast.FnDef,
        request_fn_node: NodeId,
        retained_evidence: EvidenceChain,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const fn_view = self.builder.moduleForConstFnDef(fn_value.fn_def);
        var fn_ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self.builder,
            fn_view,
            self.method_scope,
            ownerTemplateForConstFnDef(fn_value.fn_def),
            self.graph,
            self.draft,
        );
        fn_ctx.in_default_expr = constFnDefIsDefaultRoot(fn_value.fn_def);
        fn_ctx.evidence = retained_evidence;
        fn_ctx.inheritFrozenEmissionContext(self);
        defer fn_ctx.deinit();
        try fn_ctx.inheritActiveConstBinding(self);
        try fn_ctx.replayStoredEvidenceRelations(fn_ctx.evidence);
        fn_ctx.current_fn_key = switch (fn_def) {
            .nested => |nested| nested.context_fn_key,
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => Common.invariant("capturing stored function had no nested function identity"),
        };
        _ = try checkedMonoRequestNode(
            self.graph,
            try fn_ctx.instNode(fn_value.source_fn_ty),
            request_fn_node,
            .exact,
        );

        const lambda_expr_id = checkedLambdaExprIdForConstFn(fn_view, fn_value.fn_def);
        const lambda_expr = fn_view.bodies.expr(lambda_expr_id);
        const captures = try self.allocator.alloc(struct {
            binder: checked.PatternBinderId,
            local: DraftLocalId,
            previous: ?DraftLocalId,
            previous_typed: ?DraftLocalId,
            ty: Type.TypeId,
            node: NodeId,
            value: DraftExprId,
        }, fn_value.captures.len);
        defer self.allocator.free(captures);
        var initialized: usize = 0;
        defer fn_ctx.unbindConstCaptures(captures[0..initialized]);

        for (fn_value.captures, 0..) |capture, index| {
            const binder = constCaptureBinder(capture.id);
            const lowered_ty = try fn_ctx.lowerConstCaptureType(store_view, capture.ty);
            const capture_node = try self.graph.importMono(lowered_ty);
            const capture_cell = DraftTypeCell.fromGraphNode(capture_node);
            const local = try fn_ctx.addFreshLocalWithBinderCell(self.builder.symbols.fresh(), capture_cell, binder);
            try fn_ctx.bindLocalName(local, binder);
            const previous = fn_ctx.binders.get(binder);
            try fn_ctx.binders.put(binder, local);
            errdefer fn_ctx.restoreBinder(binder, previous);
            const previous_typed = try fn_ctx.putTypedBinder(binder, lowered_ty, local);
            captures[index] = .{
                .binder = binder,
                .local = local,
                .previous = previous,
                .previous_typed = previous_typed,
                .ty = lowered_ty,
                .node = capture_node,
                .value = undefined,
            };
            initialized += 1;
        }
        for (fn_value.captures, 0..) |capture, index| {
            captures[index].value = if (static_data_const_locator) |const_locator|
                try fn_ctx.restoredStaticDataCandidateNodeAtNode(
                    store_view,
                    fn_view,
                    capture.value,
                    captures[index].node,
                    const_locator,
                    checkedBinderType(fn_view, constCaptureBinder(capture.id)),
                    .allow,
                )
            else
                try fn_ctx.restoreConstNodeAtNode(
                    store_view,
                    fn_view,
                    capture.value,
                    captures[index].node,
                );
        }

        const capture_nested = switch (fn_def) {
            .nested => |nested| nested,
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => Common.invariant("capturing stored function had no nested function identity"),
        };
        const restored_local_proc_entries = try fn_ctx.enterRestoredLocalProcScope(capture_nested, fn_ctx.current_fn_key);
        defer if (restored_local_proc_entries) |entries| fn_ctx.allocator.free(entries);

        const capture_entry_guards = try self.allocator.alloc(NodeId, captures.len);
        defer self.allocator.free(capture_entry_guards);
        for (captures, capture_entry_guards) |capture, *node| node.* = capture.node;
        const restored_fn_id = switch (lambda_expr.data) {
            .lambda => try self.builder.lowerDraftNestedFromContext(
                &fn_ctx,
                fn_ctx.draft.current_owner,
                lambda_expr_id,
                capture_nested,
                fn_value.source_fn_ty,
                fn_value.source_fn_key,
                request_fn_node,
                capture_entry_guards,
                fn_ctx.evidence,
                null,
                false,
                .exact_graph,
                .inherit,
            ),
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("stored capturing function did not reference a checked lambda"),
        };

        const capture_values = try self.allocator.alloc(DraftFnDefCapture, captures.len);
        defer self.allocator.free(capture_values);
        for (captures, 0..) |capture, index| {
            capture_values[index] = .{ .id = fn_ctx.captureKey(capture.local), .value = capture.value };
        }

        return try fn_ctx.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(request_fn_node),
            .{ .fn_def = .{
                .fn_id = restored_fn_id,
                .captures = try fn_ctx.addFnDefCaptureSpan(capture_values),
            } },
        );
    }

    fn restoreConstFn(
        self: *BodyContext,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const raw = @backingInt(fn_id);
        if (raw >= store_view.const_store.fns.items.len) Common.invariant("ConstStore function id is out of range");
        const fn_value = store_view.const_store.getFn(@fromBackingInt(@intCast(raw)));
        if (fn_value.fn_def == .parser_runtime) {
            return try self.restoreConstCodecRuntimeFn(.parser, store_view, fn_id, fn_value, ty, static_data_const_locator);
        }
        if (fn_value.fn_def == .encoder_for_runtime) {
            return try self.restoreConstCodecRuntimeFn(.encoder, store_view, fn_id, fn_value, ty, static_data_const_locator);
        }
        const template = try self.builder.restoredConstFnTemplateToMono(store_view, fn_id, fn_value, ty, false);
        if (fn_value.evidence_frames.len == 0 or fn_value.evidence_frame_head == null) {
            Common.invariant("stored checked function did not contain an explicit evidence root frame");
        }
        const retained_evidence = try self.materializeConstFnEvidence(fn_value);
        _ = self.builder.moduleForConstFnDef(fn_value.fn_def);
        const checked_template = templateForConstFnDef(fn_value.fn_def);
        // The recording owner template lives in its OWN module (for a
        // default-root stored function, the fn's module is the declaring
        // module, not the owner's).
        _ = self.builder.moduleForDigest(names.procTemplateModuleDigest(checked_template)).templates.get(checked_template.template);
        if (fn_value.captures.len != 0) {
            return try self.restoreCapturingConstFn(store_view, fn_value, template, ty, retained_evidence, static_data_const_locator);
        }
        const request_fn_node = try self.activeNodeFromType(ty);
        const restored_fn = try self.restoreConstFnTemplateAt(
            fn_value,
            template.fn_def,
            template.source_fn_ty,
            template.source_fn_key,
            retained_evidence,
            request_fn_node,
        );
        return try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(request_fn_node),
            .{ .fn_def = .{ .fn_id = restored_fn } },
        );
    }

    fn restoreCapturingConstFn(
        self: *BodyContext,
        store_view: ModuleView,
        fn_value: check.ConstStore.ConstFn,
        template: Ast.FnTemplate,
        ty: Type.TypeId,
        retained_evidence: EvidenceChain,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const fn_view = self.builder.moduleForConstFnDef(fn_value.fn_def);
        var fn_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, fn_view, self.method_scope, ownerTemplateForConstFnDef(fn_value.fn_def), self.graph, self.draft);
        fn_ctx.in_default_expr = constFnDefIsDefaultRoot(fn_value.fn_def);
        fn_ctx.evidence = retained_evidence;
        fn_ctx.inheritFrozenEmissionContext(self);
        defer fn_ctx.deinit();
        try fn_ctx.inheritActiveConstBinding(self);
        try fn_ctx.replayStoredEvidenceRelations(fn_ctx.evidence);
        fn_ctx.current_fn_key = switch (template.fn_def) {
            .nested => |nested| nested.context_fn_key,
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => Common.invariant("capturing stored function had no nested function identity"),
        };
        try fn_ctx.constrainTypeToMono(fn_value.source_fn_ty, ty);

        const lambda_expr_id = checkedLambdaExprIdForConstFn(fn_view, fn_value.fn_def);
        const lambda_expr = fn_view.bodies.expr(lambda_expr_id);

        const captures = try self.allocator.alloc(struct {
            binder: checked.PatternBinderId,
            local: DraftLocalId,
            previous: ?DraftLocalId,
            previous_typed: ?DraftLocalId,
            ty: Type.TypeId,
            value: DraftExprId,
        }, fn_value.captures.len);
        defer self.allocator.free(captures);
        var initialized: usize = 0;
        defer fn_ctx.unbindConstCaptures(captures[0..initialized]);

        for (fn_value.captures, 0..) |capture, index| {
            const binder = constCaptureBinder(capture.id);
            const lowered_ty = try fn_ctx.lowerConstCaptureType(store_view, capture.ty);
            const capture_cell = try fn_ctx.draftTypeCell(lowered_ty);
            const local = try fn_ctx.addFreshLocalWithBinderCell(self.builder.symbols.fresh(), capture_cell, binder);
            try fn_ctx.bindLocalName(local, binder);
            const previous = fn_ctx.binders.get(binder);
            try fn_ctx.binders.put(binder, local);
            errdefer fn_ctx.restoreBinder(binder, previous);
            const previous_typed = try fn_ctx.putTypedBinder(binder, lowered_ty, local);
            captures[index] = .{
                .binder = binder,
                .local = local,
                .previous = previous,
                .previous_typed = previous_typed,
                .ty = lowered_ty,
                .value = undefined,
            };
            initialized += 1;
        }
        for (fn_value.captures, 0..) |capture, index| {
            captures[index].value = if (static_data_const_locator) |const_locator|
                try fn_ctx.restoredStaticDataCandidateNode(store_view, fn_view, capture.value, captures[index].ty, const_locator, checkedBinderType(fn_view, constCaptureBinder(capture.id)), .allow)
            else
                try fn_ctx.restoreConstNodeAtType(store_view, fn_view, capture.value, captures[index].ty);
        }

        const capture_nested = switch (template.fn_def) {
            .nested => |nested| nested,
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => Common.invariant("capturing stored function had no nested function identity"),
        };
        const restored_local_proc_entries = try fn_ctx.enterRestoredLocalProcScope(capture_nested, fn_ctx.current_fn_key);
        defer if (restored_local_proc_entries) |entries| fn_ctx.allocator.free(entries);

        const request_fn_node = try fn_ctx.activeNodeFromType(ty);
        const capture_entry_guards = try self.allocator.alloc(NodeId, captures.len);
        defer self.allocator.free(capture_entry_guards);
        for (captures, capture_entry_guards) |capture, *node|
            node.* = try fn_ctx.activeNodeFromType(capture.ty);
        const restored_fn_id = switch (lambda_expr.data) {
            .lambda => try self.builder.lowerDraftNestedFromContext(
                &fn_ctx,
                fn_ctx.draft.current_owner,
                lambda_expr_id,
                capture_nested,
                template.source_fn_ty,
                template.source_fn_key,
                request_fn_node,
                capture_entry_guards,
                fn_ctx.evidence,
                null,
                false,
                .exact_graph,
                .inherit,
            ),
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("stored capturing function did not reference a checked lambda"),
        };

        const capture_values = try self.allocator.alloc(DraftFnDefCapture, captures.len);
        defer self.allocator.free(capture_values);
        for (captures, 0..) |capture, index| {
            capture_values[index] = .{ .id = fn_ctx.captureKey(capture.local), .value = capture.value };
        }

        return try fn_ctx.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(request_fn_node),
            .{ .fn_def = .{
                .fn_id = restored_fn_id,
                .captures = try fn_ctx.addFnDefCaptureSpan(capture_values),
            } },
        );
    }

    /// Hand one prepared stored codec restore to Phase B. Every relation the
    /// generated body needs has already been produced; what remains is
    /// generation from sealed types, which only the final snapshot supplies.
    fn deferStoredCodecRestore(
        self: *BodyContext,
        boundary: DraftDeferredStoredCodecRestore,
    ) Allocator.Error!void {
        var owned = boundary;
        owned.lexical = try self.captureCodecLexicalContext();
        var lexical_needs_cleanup = true;
        errdefer if (lexical_needs_cleanup) {
            self.allocator.free(owned.lexical.binders);
            self.allocator.free(owned.lexical.local_procs);
        };
        owned.codec_contract = try self.retainActiveCodecContract();
        errdefer if (lexical_needs_cleanup) owned.codec_contract.?.deinit(self.allocator);
        try self.draft.deferred_stored_codec_restores.append(self.allocator, owned);
        lexical_needs_cleanup = false;
    }

    /// Phase-B body generation for a stored `parser_for` constant. Mirrors the
    /// eager restore statement for statement; every type it consumes comes
    /// from the final sealer instead of a pre-freeze resolved view.
    fn emitStoredParserRuntimeBody(
        self: *BodyContext,
        boundary: DraftDeferredStoredCodecRestore,
        sealer: *GraphTypeFinals,
    ) Allocator.Error!DraftExprId {
        const runtime = switch (boundary.fn_value.fn_def) {
            .parser_runtime => |runtime| runtime,
            .local_template, .imported_template, .nested, .local_hosted, .imported_hosted, .checked_generated, .encoder_for_runtime => Common.invariant("non-parser function reached sealed parser runtime emission"),
        };
        // Phase B is the only caller: the four restores now refuse to run
        // against a frozen graph, so nothing reaches this body outside
        // `emitDraftDeferredStoredCodecRestores`, which sets this flag.
        if (!self.frozen_sealed_emission) Common.invariant("stored parser body emitted outside Phase B");
        const request_cell = DraftTypeCell.fromGraphNode(boundary.request_fn_node);
        const encoding_cell = DraftTypeCell.fromGraphNode(boundary.encoding_node);
        const encoding_ty = try sealer.sealNode(boundary.encoding_node);
        const shape_ty = try sealer.sealNode(boundary.shape_node);

        const runtime_fn = try self.graph.functionNodes(boundary.request_fn_node);
        if (runtime_fn.args.len != 1) Common.invariant("stored parser runtime function had an unexpected arity");
        const state_cell = DraftTypeCell.fromGraphNode(runtime_fn.args[0]);
        const ret_cell = DraftTypeCell.fromGraphNode(runtime_fn.ret);
        const state_ty = try sealer.sealNode(runtime_fn.args[0]);
        const ret_ty = try sealer.sealNode(runtime_fn.ret);
        const state_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), state_cell, null);
        const state_expr = try self.addExprWithTypeCell(state_cell, .{ .local = state_local });

        const str_ty = try self.primitiveType(.str);
        var precomputed_plan = BodyContext.ParserPrecomputedPlan.init(self.allocator);
        defer precomputed_plan.deinit();
        try self.buildParserRestoredPrecomputedPlan(
            &precomputed_plan,
            boundary.fn_value,
            boundary.store_view,
            boundary.view,
            shape_ty,
            str_ty,
        );

        const parsed = blk: {
            var capture_tys = std.ArrayList(Type.TypeId).empty;
            defer capture_tys.deinit(self.allocator);
            if (boundary.encoding_let != null) try capture_tys.append(self.allocator, encoding_ty);
            for (precomputed_plan.captures.items) |_| try capture_tys.append(self.allocator, str_ty);
            const demand_scope = try self.enterCallableBodyDemandScope(&.{state_ty}, capture_tys.items);
            defer demand_scope.leave();
            break :blk try self.lowerParseResultFromState(
                shape_ty,
                boundary.encoding_expr,
                encoding_ty,
                state_expr,
                state_ty,
                ret_ty,
                &precomputed_plan,
            );
        };
        const parsed_ty = try self.exprTypeCell(parsed).seal(self.graph, sealer);
        if (!try self.typeStore().typeEql(self.nameStore(), parsed_ty, ret_ty)) {
            // compilerBug, not invariant: the next statement retypes this
            // expression to the sealed return cell. `invariant` is
            // `unreachable` outside Debug, so a real divergence would
            // silently reinterpret the emitted body's layout in a release
            // build instead of reporting.
            Common.compilerBug("stored parser runtime body differed from its sealed return type");
        }
        self.draft.exprs.items[@backingInt(parsed)].ty = ret_cell;

        const stored_evidence = try self.storedEvidence(self.evidence);
        const evidence_digest = stored_evidence.digest;
        const draft_evidence = try self.draft.addStoredConstFnEvidence(stored_evidence);
        const runtime_fn_id = try self.draft.addFn(.{ .source = .{
            .fn_def = .{ .parser_runtime = .{
                .owner = runtime.owner,
                .expr = runtime.expr,
            } },
            .source_fn_ty = boundary.fn_value.source_fn_ty,
            .source_fn_key = boundary.fn_value.source_fn_key,
            .mono_fn_ty = request_cell,
            .const_evidence = draft_evidence.nodes,
            .const_evidence_frames = draft_evidence.frames,
            .const_evidence_frame_head = stored_evidence.head,
            .evidence_digest = evidence_digest,
        } });
        var parser_expr = try self.addExprWithTypeCell(request_cell, .{ .lambda = .{
            .fn_id = .{ .draft = runtime_fn_id },
            .args = try self.draft.addTypedLocalSpan(&.{
                .{ .local = state_local, .ty = state_cell },
            }),
            .body = parsed,
        } });
        var capture_index = precomputed_plan.captures.items.len;
        while (capture_index > 0) {
            capture_index -= 1;
            const capture = precomputed_plan.captures.items[capture_index];
            parser_expr = try self.wrapLetAtTypeCell(
                capture.local,
                try self.draftTypeCell(str_ty),
                capture.value,
                parser_expr,
                request_cell,
            );
        }
        if (boundary.encoding_let) |let_| {
            parser_expr = try self.wrapLetAtTypeCell(
                let_.local,
                encoding_cell,
                let_.value,
                parser_expr,
                request_cell,
            );
        }
        return try self.builder.wrapConstSourceCaptureLetsAtTypeCell(
            self,
            boundary.source_captures,
            parser_expr,
            request_cell,
        );
    }

    /// Phase-B body generation for a stored `encoder_for` constant, the
    /// encoder twin of `emitStoredParserRuntimeBody`.
    fn emitStoredEncoderForRuntimeBody(
        self: *BodyContext,
        boundary: DraftDeferredStoredCodecRestore,
        sealer: *GraphTypeFinals,
    ) Allocator.Error!DraftExprId {
        const runtime = switch (boundary.fn_value.fn_def) {
            .encoder_for_runtime => |runtime| runtime,
            .local_template, .imported_template, .nested, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime => Common.invariant("non-encoder_for function reached sealed encoder_for runtime emission"),
        };
        // Phase B is the only caller: the four restores now refuse to run
        // against a frozen graph, so nothing reaches this body outside
        // `emitDraftDeferredStoredCodecRestores`, which sets this flag.
        if (!self.frozen_sealed_emission) Common.invariant("stored encoder_for body emitted outside Phase B");
        const request_cell = DraftTypeCell.fromGraphNode(boundary.request_fn_node);
        const encoding_cell = DraftTypeCell.fromGraphNode(boundary.encoding_node);
        const encoding_ty = try sealer.sealNode(boundary.encoding_node);
        const shape_ty = try sealer.sealNode(boundary.shape_node);

        const runtime_fn = try self.graph.functionNodes(boundary.request_fn_node);
        if (runtime_fn.args.len != 2) Common.invariant("stored encoder_for runtime function had an unexpected arity");
        const value_cell = DraftTypeCell.fromGraphNode(runtime_fn.args[0]);
        const state_cell = DraftTypeCell.fromGraphNode(runtime_fn.args[1]);
        const ret_cell = DraftTypeCell.fromGraphNode(runtime_fn.ret);
        const value_ty = try sealer.sealNode(runtime_fn.args[0]);
        const state_ty = try sealer.sealNode(runtime_fn.args[1]);
        const ret_ty = try sealer.sealNode(runtime_fn.ret);
        const value_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), value_cell, null);
        const value_expr = try self.addExprWithTypeCell(value_cell, .{ .local = value_local });
        const state_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), state_cell, null);
        const state_expr = try self.addExprWithTypeCell(state_cell, .{ .local = state_local });

        const str_ty = try self.primitiveType(.str);
        var precomputed_plan = BodyContext.ParserPrecomputedPlan.init(self.allocator);
        defer precomputed_plan.deinit();
        precomputed_plan.next_capture_id = encoderForFirstFieldCaptureId();
        try self.buildEncodeRestoredPrecomputedPlan(
            &precomputed_plan,
            boundary.fn_value,
            boundary.store_view,
            boundary.view,
            shape_ty,
            encoding_ty,
            str_ty,
        );

        const saved_encoder_source_fn_ty = self.generated_encoder_source_fn_ty;
        const saved_encoder_source_expr = self.generated_encoder_source_expr;
        const saved_encoder_lambda_index = self.generated_encoder_lambda_index;
        self.generated_encoder_source_fn_ty = boundary.fn_value.source_fn_ty;
        self.generated_encoder_source_expr = runtime.expr;
        self.generated_encoder_lambda_index = 0;
        defer {
            self.generated_encoder_source_fn_ty = saved_encoder_source_fn_ty;
            self.generated_encoder_source_expr = saved_encoder_source_expr;
            self.generated_encoder_lambda_index = saved_encoder_lambda_index;
        }

        const encoded = blk: {
            var capture_tys = std.ArrayList(Type.TypeId).empty;
            defer capture_tys.deinit(self.allocator);
            if (boundary.encoding_let != null) try capture_tys.append(self.allocator, encoding_ty);
            for (precomputed_plan.captures.items) |_| try capture_tys.append(self.allocator, str_ty);
            const demand_scope = try self.enterCallableBodyDemandScope(&.{ value_ty, state_ty }, capture_tys.items);
            defer demand_scope.leave();
            break :blk try self.lowerEncodeShapeToState(
                shape_ty,
                value_expr,
                boundary.encoding_expr,
                encoding_ty,
                state_expr,
                state_ty,
                ret_ty,
                &precomputed_plan,
            );
        };
        const encoded_ty = try self.exprTypeCell(encoded).seal(self.graph, sealer);
        if (!try self.typeStore().typeEql(self.nameStore(), encoded_ty, ret_ty)) {
            // compilerBug, not invariant: the next statement retypes this
            // expression to the sealed return cell. `invariant` is
            // `unreachable` outside Debug, so a real divergence would
            // silently reinterpret the emitted body's layout in a release
            // build instead of reporting.
            Common.compilerBug("stored encoder_for runtime body differed from its sealed return type");
        }
        self.draft.exprs.items[@backingInt(encoded)].ty = ret_cell;

        const stored_evidence = try self.storedEvidence(self.evidence);
        const evidence_digest = stored_evidence.digest;
        const draft_evidence = try self.draft.addStoredConstFnEvidence(stored_evidence);
        const runtime_fn_id = try self.draft.addFn(.{ .source = .{
            .fn_def = .{ .encoder_for_runtime = .{
                .owner = runtime.owner,
                .expr = runtime.expr,
            } },
            .source_fn_ty = boundary.fn_value.source_fn_ty,
            .source_fn_key = boundary.fn_value.source_fn_key,
            .mono_fn_ty = request_cell,
            .const_evidence = draft_evidence.nodes,
            .const_evidence_frames = draft_evidence.frames,
            .const_evidence_frame_head = stored_evidence.head,
            .evidence_digest = evidence_digest,
        } });
        var encoder_expr = try self.addExprWithTypeCell(request_cell, .{ .lambda = .{
            .fn_id = .{ .draft = runtime_fn_id },
            .args = try self.draft.addTypedLocalSpan(&.{
                .{ .local = value_local, .ty = value_cell },
                .{ .local = state_local, .ty = state_cell },
            }),
            .body = encoded,
        } });
        var capture_index = precomputed_plan.captures.items.len;
        while (capture_index > 0) {
            capture_index -= 1;
            const capture = precomputed_plan.captures.items[capture_index];
            encoder_expr = try self.wrapLetAtTypeCell(
                capture.local,
                try self.draftTypeCell(str_ty),
                capture.value,
                encoder_expr,
                request_cell,
            );
        }
        if (boundary.encoding_let) |let_| {
            encoder_expr = try self.wrapLetAtTypeCell(
                let_.local,
                encoding_cell,
                let_.value,
                encoder_expr,
                request_cell,
            );
        }
        return try self.builder.wrapConstSourceCaptureLetsAtTypeCell(
            self,
            boundary.source_captures,
            encoder_expr,
            request_cell,
        );
    }

    fn restoreConstCodecRuntimeFn(
        self: *BodyContext,
        comptime kind: CodecKind,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        fn_value: check.ConstStore.ConstFn,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const codec_name = switch (kind) {
            .parser => "parser",
            .encoder => Ident.ENCODER_FOR_METHOD_NAME,
        };
        const encoding_capture_id = switch (kind) {
            .parser => parserEncodingCaptureId(),
            .encoder => encoderForEncodingCaptureId(),
        };
        const wrong_fn_def = "non-" ++ codec_name ++ " function reached " ++ codec_name ++ " runtime restore";
        const runtime = switch (kind) {
            .parser => switch (fn_value.fn_def) {
                .parser_runtime => |runtime| runtime,
                .local_template, .imported_template, .nested, .local_hosted, .imported_hosted, .checked_generated, .encoder_for_runtime => Common.invariant(wrong_fn_def),
            },
            .encoder => switch (fn_value.fn_def) {
                .encoder_for_runtime => |runtime| runtime,
                .local_template, .imported_template, .nested, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime => Common.invariant(wrong_fn_def),
            },
        };
        const fn_view = self.builder.moduleForDigest(names.procTemplateModuleDigest(runtime.owner));

        var fn_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, fn_view, self.method_scope, runtime.owner, self.graph, self.draft);
        defer fn_ctx.deinit();
        fn_ctx.inheritFrozenEmissionContext(self);
        try fn_ctx.inheritActiveConstBinding(self);
        fn_ctx.current_fn_key = restoredConstFnContextKey(store_view.key, fn_id, fn_value.source_fn_key);

        const expr = fn_view.bodies.expr(runtime.expr);
        const plan = dispatchPlanForRuntimeExpr(fn_view, runtime.expr);
        try fn_ctx.restoreGeneratedRuntimeEvidence(fn_value, plan);
        const callable_plan = fn_ctx.requireStoredRuntimeCallableDispatchPlan(plan);
        const plan_args = callable_plan.operands;
        const callable_node = try fn_ctx.instantiateCallableDispatchPlanCallNodeFromCaller(callable_plan, &fn_ctx, expr.ty, ty);
        const callable = try self.graph.functionNodes(callable_node);
        if (callable.args.len != 1) Common.invariant("stored " ++ codec_name ++ " constructor had an unexpected arity");
        // Mirrors the graph-native restore: the constructor was instantiated
        // against `ty`, so its result cell must be the request's own node.
        // Proving that here is what lets Phase B seal the request instead of
        // carrying a pre-freeze `Type.TypeId` across the boundary.
        if (!self.graph.sameClass(callable.ret, try fn_ctx.activeNodeFromType(ty))) {
            Common.invariant("stored " ++ codec_name ++ " constructor result cell differed from its restored function type");
        }
        const encoding_node = callable.args[0];
        const encoding_cell = DraftTypeCell.fromGraphNode(encoding_node);
        const request_fn_node = callable.ret;

        const shape_node = try fn_ctx.instNode(plan.dispatcher_ty);
        try fn_ctx.activateCodecContractForPlan(plan, callable_node, shape_node);
        const runtime_boundary = try fn_ctx.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(request_fn_node),
            .pending_deferred,
        );

        var encoding_let: ?DraftStoredCodecEncodingLet = null;
        const encoding_expr = if (constGeneratedCaptureNode(fn_value, encoding_capture_id)) |node| blk: {
            const local = try fn_ctx.addLocalWithBinderCell(self.builder.symbols.fresh(), encoding_cell, null);
            fn_ctx.setLocalCaptureId(local, encoding_capture_id);
            const let_value = if (static_data_const_locator) |const_locator|
                try fn_ctx.restoreConstNodeAtNodeWithStaticRoot(
                    store_view,
                    fn_view,
                    node,
                    encoding_node,
                    const_locator,
                )
            else
                try fn_ctx.restoreConstNodeAtNode(store_view, fn_view, node, encoding_node);
            encoding_let = .{ .local = local, .value = let_value };
            break :blk try fn_ctx.addExprWithTypeCell(encoding_cell, .{ .local = local });
        } else try fn_ctx.lowerDispatchOperandAtNode(plan_args[0], encoding_node);

        // Mirror of `deferStructuralSerializationAtNode`: the reservation
        // carries the encoding operand's impossibility proof from deferral
        // until Phase B replaces it with the emitted body's. Without this the
        // boundary is proof-less for the whole of Phase A.
        fn_ctx.draft.expr_impossibility_proofs.items[@backingInt(runtime_boundary)] =
            fn_ctx.exprImpossibilityProof(encoding_expr);

        const boundary = DraftDeferredStoredCodecRestore{
            .view = fn_view,
            .method_scope = fn_ctx.method_scope,
            .owner_template = runtime.owner,
            .owner = fn_ctx.draft.current_owner,
            .expr = runtime_boundary,
            .kind = kind,
            .store_view = store_view,
            .fn_value = fn_value,
            .request_fn_node = request_fn_node,
            .callable_node = callable_node,
            .encoding_node = encoding_node,
            .shape_node = shape_node,
            .encoding_expr = encoding_expr,
            .encoding_let = encoding_let,
            .source_captures = &.{},
            .active_const_binding = fn_ctx.active_const_binding,
            .evidence = fn_ctx.evidence,
            .current_fn_key = fn_ctx.current_fn_key,
            .lexical = undefined,
        };

        if (fn_ctx.frozen_sealed_emission) {
            // Unreachable by construction: the constructor instantiation above
            // ends in `freshInstNode` -> `InstGraph.newNode` ->
            // `requireRelationProduction`, so a frozen graph panics before
            // control reaches here. `emitDraftDeferredStoredCodecRestores` is
            // the only emitter of this body.
            Common.invariant("stored " ++ codec_name ++ " restore ran against a frozen instantiation graph");
        }

        _ = try fn_ctx.prepareStructuralCodecCallsAtNode(
            runtime_boundary,
            kind,
            shape_node,
            callable_node,
        );
        try fn_ctx.deferStoredCodecRestore(boundary);
        return runtime_boundary;
    }

    fn restoreConstCodecRuntimeFnAtNode(
        self: *BodyContext,
        comptime kind: CodecKind,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        fn_value: check.ConstStore.ConstFn,
        request_fn_node: NodeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const codec_name = switch (kind) {
            .parser => "parser",
            .encoder => Ident.ENCODER_FOR_METHOD_NAME,
        };
        const encoding_capture_id = switch (kind) {
            .parser => parserEncodingCaptureId(),
            .encoder => encoderForEncodingCaptureId(),
        };
        const wrong_fn_def = "non-" ++ codec_name ++ " function reached graph-native " ++ codec_name ++ " runtime restore";
        const runtime = switch (kind) {
            .parser => switch (fn_value.fn_def) {
                .parser_runtime => |runtime| runtime,
                .local_template, .imported_template, .nested, .local_hosted, .imported_hosted, .checked_generated, .encoder_for_runtime => Common.invariant(wrong_fn_def),
            },
            .encoder => switch (fn_value.fn_def) {
                .encoder_for_runtime => |runtime| runtime,
                .local_template, .imported_template, .nested, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime => Common.invariant(wrong_fn_def),
            },
        };
        const fn_view = self.builder.moduleForDigest(names.procTemplateModuleDigest(runtime.owner));

        var fn_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, fn_view, self.method_scope, runtime.owner, self.graph, self.draft);
        defer fn_ctx.deinit();
        fn_ctx.inheritFrozenEmissionContext(self);
        try fn_ctx.inheritActiveConstBinding(self);
        fn_ctx.current_fn_key = restoredConstFnContextKey(store_view.key, fn_id, fn_value.source_fn_key);

        var source_captures = try self.builder.bindConstSourceCaptures(
            &fn_ctx,
            store_view,
            fn_view,
            fn_value,
            static_data_const_locator,
        );
        defer self.builder.releaseConstSourceCaptures(&fn_ctx, &source_captures);

        const expr = fn_view.bodies.expr(runtime.expr);
        const plan = dispatchPlanForRuntimeExpr(fn_view, runtime.expr);
        try fn_ctx.restoreGeneratedRuntimeEvidence(fn_value, plan);
        const callable_plan = fn_ctx.requireStoredRuntimeCallableDispatchPlan(plan);
        const plan_args = callable_plan.operands;
        const callable_node = try fn_ctx.instantiateCallableDispatchPlanCallNodeFromCallerAtNode(
            callable_plan,
            &fn_ctx,
            expr.ty,
            request_fn_node,
            .expression_lowering,
        );
        const callable = try self.graph.functionNodes(callable_node);
        if (callable.args.len != 1) Common.invariant("stored " ++ codec_name ++ " constructor had an unexpected arity");
        if (!self.graph.sameClass(callable.ret, request_fn_node)) {
            Common.invariant("stored " ++ codec_name ++ " constructor result cell differed from its graph-native request");
        }
        const encoding_node = callable.args[0];
        const encoding_cell = DraftTypeCell.fromGraphNode(encoding_node);

        const runtime_fn = try self.graph.functionNodes(request_fn_node);
        const runtime_arity: usize = switch (kind) {
            .parser => 1,
            .encoder => 2,
        };
        if (runtime_fn.args.len != runtime_arity) Common.invariant("stored " ++ codec_name ++ " runtime function had an unexpected arity");

        const shape_node = try fn_ctx.instNode(plan.dispatcher_ty);
        try fn_ctx.activateCodecContractForPlan(plan, callable_node, shape_node);
        const runtime_boundary = try fn_ctx.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(request_fn_node),
            .pending_deferred,
        );

        var encoding_let: ?DraftStoredCodecEncodingLet = null;
        const encoding_expr = if (constGeneratedCaptureNode(fn_value, encoding_capture_id)) |node| blk: {
            const local = try fn_ctx.addLocalWithBinderCell(self.builder.symbols.fresh(), encoding_cell, null);
            fn_ctx.setLocalCaptureId(local, encoding_capture_id);
            const let_value = if (static_data_const_locator) |const_locator|
                try fn_ctx.restoreConstNodeAtNodeWithStaticRoot(
                    store_view,
                    fn_view,
                    node,
                    encoding_node,
                    const_locator,
                )
            else
                try fn_ctx.restoreConstNodeAtNode(store_view, fn_view, node, encoding_node);
            encoding_let = .{ .local = local, .value = let_value };
            break :blk try fn_ctx.addExprWithTypeCell(encoding_cell, .{ .local = local });
        } else try fn_ctx.lowerDispatchOperandAtNode(plan_args[0], encoding_node);

        // Mirror of `deferStructuralSerializationAtNode`: the reservation
        // carries the encoding operand's impossibility proof from deferral
        // until Phase B replaces it with the emitted body's. Without this the
        // boundary is proof-less for the whole of Phase A.
        fn_ctx.draft.expr_impossibility_proofs.items[@backingInt(runtime_boundary)] =
            fn_ctx.exprImpossibilityProof(encoding_expr);

        var boundary = DraftDeferredStoredCodecRestore{
            .view = fn_view,
            .method_scope = fn_ctx.method_scope,
            .owner_template = runtime.owner,
            .owner = fn_ctx.draft.current_owner,
            .expr = runtime_boundary,
            .kind = kind,
            .store_view = store_view,
            .fn_value = fn_value,
            .request_fn_node = request_fn_node,
            .callable_node = callable_node,
            .encoding_node = encoding_node,
            .shape_node = shape_node,
            .encoding_expr = encoding_expr,
            .encoding_let = encoding_let,
            .source_captures = source_captures.items,
            .active_const_binding = fn_ctx.active_const_binding,
            .evidence = fn_ctx.evidence,
            .current_fn_key = fn_ctx.current_fn_key,
            .lexical = undefined,
        };

        if (fn_ctx.frozen_sealed_emission) {
            // Unreachable by construction: the constructor instantiation above
            // ends in `freshInstNode` -> `InstGraph.newNode` ->
            // `requireRelationProduction`, so a frozen graph panics before
            // control reaches here. `emitDraftDeferredStoredCodecRestores` is
            // the only emitter of this body.
            Common.invariant("stored " ++ codec_name ++ " restore ran against a frozen instantiation graph");
        }

        _ = try fn_ctx.prepareStructuralCodecCallsAtNode(
            runtime_boundary,
            kind,
            shape_node,
            callable_node,
        );
        boundary.source_captures = try self.allocator.dupe(Builder.RestoredConstSourceCapture, source_captures.items);
        errdefer self.allocator.free(boundary.source_captures);
        try fn_ctx.deferStoredCodecRestore(boundary);
        return runtime_boundary;
    }

    /// What one constructor child contributes to its container's value
    /// witness.
    const ConstructorChildWitness = struct {
        /// The representation this child's slot carries in a container
        /// witness, whether or not this child is the one that requires the
        /// witness.
        slot: NodeId,
        /// Whether this child alone requires the container to be rebuilt at
        /// an exact value witness.
        requires_witness: bool,
    };

    /// Decide whether an emitted constructor child needs an exact value
    /// witness instead of the checked-public slot it was requested at, and
    /// which representation its slot carries when any sibling forces the
    /// container to be rebuilt. Every accepted difference must carry
    /// producer-authored representation or completion evidence; constructor
    /// lowering never guesses from shape.
    fn constructorChildWitness(
        self: *BodyContext,
        slot_node: NodeId,
        child_node: NodeId,
        comptime missing_evidence_message: []const u8,
    ) Allocator.Error!ConstructorChildWitness {
        if (self.graph.sameClass(slot_node, child_node)) {
            return .{ .slot = child_node, .requires_witness = false };
        }
        if (try self.graph.containsGeneratedPrivate(child_node)) {
            return .{ .slot = child_node, .requires_witness = true };
        }
        // A codec-authored private slot is the selected constructor
        // representation even when the user-authored opaque value lowered at
        // its public handle. Emitting a container witness from that public
        // child would discard the earlier producer selection, so a witness
        // driven by some other child keeps this slot private.
        if (try self.graph.containsGeneratedPrivate(slot_node)) {
            return .{ .slot = slot_node, .requires_witness = false };
        }
        if (try self.resultCompletesRequest(slot_node, child_node) or
            try self.producedValueHasExplicitRepresentationEvidence(slot_node, child_node))
        {
            return .{ .slot = child_node, .requires_witness = true };
        }
        Common.invariant(missing_evidence_message);
    }

    fn relateLookupExprAtNode(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        maybe_ref: ?checked.ResolvedValueId,
        expected_node: NodeId,
    ) Allocator.Error!void {
        const ref_id = maybe_ref orelse Common.invariant("checked lookup reached Monotype without resolved value ref");
        const expr = self.view.bodies.expr(checked_expr);
        if (self.currentLocalBindingForResolvedValue(ref_id)) |binding| {
            const local_cell = self.localTypeCell(binding.local);
            const local_node = try local_cell.toGraphNode(self.graph);
            try self.constrainCheckedInterfaceToCell(expr.ty, local_cell);
            try self.constrainCheckedInterfaceToCell(checkedBinderType(self.view, binding.binder), local_cell);
            try relateRequestComponent(self.graph, local_node, expected_node);
            return;
        }
        if (try self.currentConstLocalForResolvedValue(ref_id)) |local_id| {
            const local_cell = self.localTypeCell(local_id);
            const local_node = try local_cell.toGraphNode(self.graph);
            try self.constrainCheckedInterfaceToCell(expr.ty, local_cell);
            try relateRequestComponent(self.graph, local_node, expected_node);
            return;
        }
        const record = self.view.resolved_refs.records[@backingInt(ref_id)];
        const const_use: ?checked.ConstUseTemplate = switch (record.ref) {
            .selected_hoisted_const => |selected| selected.const_use,
            .top_level_const, .imported_const => |value| value,
            .platform_required_const => |required| required.const_use,
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_proc, .promoted_top_level_proc => null,
        };
        if (const_use) |value| {
            const witness_node = try self.constUseTypeNode(expr.ty, value);
            try relateRequestComponent(self.graph, expected_node, witness_node);
            return;
        }
        switch (record.ref) {
            .local_proc,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_proc,
            .promoted_top_level_proc,
            => {
                _ = try self.graph.functionNodes(expected_node);
                try constrainDeferredTemplateTypeArguments(
                    self.graph,
                    try self.instNode(expr.ty),
                    expected_node,
                );
                return;
            },
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .platform_required_declaration, .platform_required_checked_error, .platform_required_const => {},
        }
        try self.graph.unify(expected_node, try self.instNode(expr.ty));
    }

    fn relateExprAtNode(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        expected_node: NodeId,
    ) Allocator.Error!void {
        _ = try self.runEvidence(.{ .relate = .{ .expr = checked_expr, .expected_node = expected_node } });
    }

    /// Relate each constructor child to its slot, and list the lambda and
    /// closure children to draft at their slots. The list is owned.
    fn relateConstructorChildrenAtNodes(
        self: *BodyContext,
        checked_exprs: []const checked.CheckedExprId,
        nodes: []const NodeId,
    ) Allocator.Error![]DraftNestedCallable {
        if (checked_exprs.len != nodes.len) Common.invariant("constructor child count differed from graph construction arity");
        for (checked_exprs, nodes) |checked_expr, node| {
            try self.relateExprAtNode(checked_expr, node);
        }
        var drafts = std.ArrayList(DraftNestedCallable).empty;
        errdefer drafts.deinit(self.allocator);
        for (checked_exprs, nodes) |checked_expr, node| {
            if (self.isNestedCallableExpr(checked_expr)) try drafts.append(self.allocator, .{ .ctx = self, .expr = checked_expr, .request_fn_node = node });
        }
        return try drafts.toOwnedSlice(self.allocator);
    }

    const PreLoweredOperand = struct {
        index: usize,
        expr: DraftExprId,
    };

    const PreLoweredChild = struct {
        checked_expr: checked.CheckedExprId,
        expr: DraftExprId,
    };

    /// Pre-lowered constructor children by their checked expression.
    const PreLoweredIndex = std.AutoHashMapUnmanaged(checked.CheckedExprId, DraftExprId);

    fn preLoweredIndex(self: *BodyContext, children: []const PreLoweredChild) Allocator.Error!PreLoweredIndex {
        var index: PreLoweredIndex = .empty;
        errdefer index.deinit(self.allocator);
        try index.ensureTotalCapacity(self.allocator, @intCast(children.len));
        for (children) |child| index.putAssumeCapacity(child.checked_expr, child.expr);
        return index;
    }

    /// A record constructor's runtime fields by name, read once so a record of
    /// any width resolves each field in constant time.
    const ConstructionFields = struct {
        fields: []const InstField,
        by_name: std.AutoHashMapUnmanaged(names.RecordFieldNameId, u32),

        fn deinit(self: *ConstructionFields, allocator: Allocator) void {
            self.by_name.deinit(allocator);
        }

        fn get(self: *const ConstructionFields, name: names.RecordFieldNameId) InstField {
            const index = self.by_name.get(name) orelse
                Common.invariant("instantiation record constructor requested an absent field");
            return self.fields[index];
        }
    };

    fn constructionFields(self: *BodyContext, record_node: NodeId) Allocator.Error!ConstructionFields {
        const fields = (try self.graph.recordConstructionNodes(record_node)).fields;
        var by_name: std.AutoHashMapUnmanaged(names.RecordFieldNameId, u32) = .empty;
        errdefer by_name.deinit(self.allocator);
        try by_name.ensureTotalCapacity(self.allocator, @intCast(fields.len));
        for (fields, 0..) |field, index| by_name.putAssumeCapacity(field.name, @intCast(index));
        return .{ .fields = fields, .by_name = by_name };
    }

    /// A checked record expression's supplied values and unset labels by their
    /// graph-owned name, each label imported once.
    const RecordExprLabels = struct {
        /// The graph-owned name of each supplied field, in `record.fields` order.
        field_names: []names.RecordFieldNameId,
        values: std.AutoHashMapUnmanaged(names.RecordFieldNameId, checked.CheckedExprId),
        unsets: std.AutoHashMapUnmanaged(names.RecordFieldNameId, void),

        fn deinit(self: *RecordExprLabels, allocator: Allocator) void {
            allocator.free(self.field_names);
            self.values.deinit(allocator);
            self.unsets.deinit(allocator);
        }
    };

    fn recordExprLabels(self: *BodyContext, record: anytype) Allocator.Error!RecordExprLabels {
        const field_names = try self.allocator.alloc(names.RecordFieldNameId, record.fields.len);
        errdefer self.allocator.free(field_names);
        var values: std.AutoHashMapUnmanaged(names.RecordFieldNameId, checked.CheckedExprId) = .empty;
        errdefer values.deinit(self.allocator);
        var unsets: std.AutoHashMapUnmanaged(names.RecordFieldNameId, void) = .empty;
        errdefer unsets.deinit(self.allocator);
        try values.ensureTotalCapacity(self.allocator, @intCast(record.fields.len));
        for (record.fields, field_names) |field, *name| {
            name.* = try self.recordFieldName(self.view, field.label);
            const entry = values.getOrPutAssumeCapacity(name.*);
            if (!entry.found_existing) entry.value_ptr.* = field.value;
        }
        try unsets.ensureTotalCapacity(self.allocator, @intCast(record.unsets.len));
        for (record.unsets) |label| unsets.putAssumeCapacity(try self.recordFieldName(self.view, label), {});
        return .{ .field_names = field_names, .values = values, .unsets = unsets };
    }

    fn preLoweredOperandAt(_: *BodyContext, operands: []const PreLoweredOperand, index: usize) ?DraftExprId {
        for (operands) |operand| {
            if (operand.index == index) return operand.expr;
        }
        return null;
    }

    /// Relate each dispatch operand not already lowered to its callable
    /// slot, and list the lambda and closure operands to draft at their
    /// slots. The list is owned.
    fn relateDispatchOperandsAtNodes(
        self: *BodyContext,
        operands: []const static_dispatch.StaticDispatchOperand,
        nodes: []const NodeId,
        pre_lowered: []const PreLoweredOperand,
    ) Allocator.Error![]DraftNestedCallable {
        if (operands.len != nodes.len) Common.invariant("dispatch argument arity differs from function graph node");
        for (operands, nodes, 0..) |operand, node, index| {
            if (self.preLoweredOperandAt(pre_lowered, index)) |pre| {
                try relateRequestComponent(
                    self.graph,
                    node,
                    try self.exprTypeCell(pre).toGraphNode(self.graph),
                );
                continue;
            }
            switch (operand) {
                .checked_expr => |expr| try self.relateExprAtNode(expr, node),
                .generated_interpolation_segments,
                .generated_numeral,
                .generated_quote,
                => {},
            }
        }
        var drafts = std.ArrayList(DraftNestedCallable).empty;
        errdefer drafts.deinit(self.allocator);
        for (operands, nodes, 0..) |operand, node, index| {
            if (self.preLoweredOperandAt(pre_lowered, index) != null) continue;
            switch (operand) {
                .checked_expr => |expr| if (self.isNestedCallableExpr(expr)) {
                    try drafts.append(self.allocator, .{ .ctx = self, .expr = expr, .request_fn_node = node });
                },
                .generated_interpolation_segments,
                .generated_numeral,
                .generated_quote,
                => {},
            }
        }
        return try drafts.toOwnedSlice(self.allocator);
    }

    fn lowerDispatchOperandAtNode(
        self: *BodyContext,
        operand: static_dispatch.StaticDispatchOperand,
        node: NodeId,
    ) Allocator.Error!DraftExprId {
        return switch (operand) {
            .checked_expr => |expr| try self.lowerExprAtTypeCell(expr, DraftTypeCell.fromGraphNode(node)),
            .generated_interpolation_segments,
            .generated_numeral,
            .generated_quote,
            => try self.lowerDispatchOperandAtType(operand, try self.activeTypeFromNode(node)),
        };
    }

    fn lowerDispatchOperandAtType(
        self: *BodyContext,
        operand: static_dispatch.StaticDispatchOperand,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return (try self.runLower(.{ .operand_at_type = .{ .operand = operand, .ty = ty } })).exprValue();
    }

    fn recordFieldByText(self: *BodyContext, ty: Type.TypeId, text: []const u8) Type.Field {
        return self.recordFieldByTextOptional(ty, text) orelse
            Common.invariant("expected record field was absent from monotype type");
    }

    fn recordFieldByName(self: *BodyContext, ty: Type.TypeId, name: names.RecordFieldNameId) Type.Field {
        const fields = switch (self.shapeContent(ty)) {
            .record => |span| self.typeStore().fieldSpan(span),
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("expected record field belonged to a non-record monotype type"),
        };
        for (0..GuardedList.borrowLen(fields)) |index| {
            const field = GuardedList.at(fields, index);
            if (field.name == name) return field;
        }
        Common.invariant("expected record field id was absent from monotype type");
    }

    /// Forwards to the scope that owns the type store; the query itself
    /// has one implementation.
    fn recordFieldByTextOptional(self: *BodyContext, ty: Type.TypeId, text: []const u8) ?Type.Field {
        const fields = switch (self.shapeContent(ty)) {
            .record => |span| self.typeStore().fieldSpan(span),
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return null,
        };
        for (0..GuardedList.borrowLen(fields)) |index| {
            const field = GuardedList.at(fields, index);
            if (Ident.textEql(self.nameStore().recordFieldLabelText(field.name), text)) return field;
        }
        return null;
    }

    fn iterItemType(self: *BodyContext, ty: Type.TypeId) Type.TypeId {
        return switch (self.typeStore().get(ty)) {
            .named => |named| blk: {
                const args = self.typeStore().span(named.args);
                if (args.len != 1) Common.invariant("Iter nominal did not have one type argument");
                break :blk GuardedList.at(args, 0);
            },
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("generated interpolation iterator expected named Iter type"),
        };
    }

    fn lowerExprAtTypeCell(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        return try self.lowerExprAtTypeCellWithDemand(checked_expr, cell, .runtime_value);
    }

    fn lowerExprAtTypeCellWithDemand(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        cell: DraftTypeCell,
        demand: LoweringDemand,
    ) Allocator.Error!DraftExprId {
        return try self.lowerExprAtTypeCellWithKnownDivergence(
            checked_expr,
            cell,
            demand,
            self.checkedExprDivergesInLoweredRuntime(checked_expr),
        );
    }

    fn lowerExprAtTypeCellWithKnownDivergence(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        cell: DraftTypeCell,
        demand: LoweringDemand,
        expr_diverges: bool,
    ) Allocator.Error!DraftExprId {
        return (try self.runLower(.{ .at_type_cell = .{ .expr = checked_expr, .cell = cell, .demand = demand, .diverges = expr_diverges } })).exprValue();
    }

    fn selectExprRepresentationAtNode(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        expected_node: NodeId,
    ) Allocator.Error!void {
        try selectRequestRepresentation(
            self.graph,
            expected_node,
            try self.lowerExprTypeNode(checked_expr),
        );
    }

    fn stepFieldAccessLower(self: *BodyContext, task: *FieldAccessTask, input: ?LowerResult) Allocator.Error!LowerStep {
        const field = self.view.bodies.expr(task.expr).data.field_access;
        if (task.started) {
            const receiver = input.?.exprValue();
            return loweredExprStep(switch (task.target) {
                .node => if (task.optional)
                    try self.optionalChainRestAtNode(field.segments, 0, receiver, task.receiver_node, task.result_node)
                else
                    try self.addExprWithTypeCell(
                        DraftTypeCell.fromGraphNode(task.result_node),
                        .{ .field_access = .{
                            .receiver = receiver,
                            .segments = .{ .start = task.segments_start, .len = @intCast(field.segments.len) },
                        } },
                    ),
                .try_ty => |out_try_ty| try self.optionalChainRest(field.segments, 0, receiver, task.receiver_ty, out_try_ty),
            });
        }
        task.started = true;
        if (field.segments.len == 0) Common.invariant("checked field access path had no segments");
        const expected_node = switch (task.target) {
            .node => |node| node,
            .try_ty => {
                task.receiver_ty = try self.lowerExprType(field.receiver);
                return requestLowerChild(self, field.receiver, .{ .sealed = task.receiver_ty });
            },
        };
        if (fieldAccessAnySegmentOptional(field.segments)) {
            // A `.?` chain compiles to runtime slot tests producing the
            // chain's checked `Try` (design.md "Field Kinds (All-Dynamic
            // Optional Fields)"). Both the receiver and result stay attached
            // to the specialization graph until their active Monotypes are
            // needed by the runtime chain lowering.
            const checked_ty = self.view.bodies.expr(task.expr).ty;
            task.receiver_node = try self.lowerExprTypeNode(field.receiver);
            const observable = try self.fieldAccessTypeNode(checked_ty, field, null);
            try relateRequestComponent(self.graph, expected_node, observable);
            task.result_node = if (try self.graph.containsGeneratedPrivate(observable)) observable else expected_node;
            task.optional = true;
            return requestLowerChild(self, field.receiver, DraftTypeCell.fromGraphNode(task.receiver_node));
        }
        task.receiver_node = try self.lowerExprTypeNode(field.receiver);
        task.segments_start = @intCast(self.draft.field_access_segments.items.len);
        try self.draft.field_access_segments.ensureUnusedCapacity(self.allocator, field.segments.len);
        var prefix_node = task.receiver_node;
        for (field.segments) |segment| {
            const field_name = try self.recordFieldName(self.view, segment.field_name);
            prefix_node = try self.graph.requiredRecordFieldNode(prefix_node, field_name);
            self.draft.field_access_segments.appendAssumeCapacity(.{ .field = field_name });
        }
        try relateRequestComponent(self.graph, expected_node, prefix_node);
        task.result_node = if (try self.graph.containsGeneratedPrivate(prefix_node)) prefix_node else expected_node;
        return requestLowerChild(self, field.receiver, DraftTypeCell.fromGraphNode(task.receiver_node));
    }

    fn sameType(self: *BodyContext, expected: Type.TypeId, actual: Type.TypeId) bool {
        var equality = SameTypeEquality{
            .ctx = self,
            .visiting = std.AutoHashMap(TypePair, void).init(self.allocator),
        };
        defer equality.visiting.deinit();
        return SameTypeEquality.Eval.run(self.allocator, &equality, .{ .same = .{ .expected = expected, .actual = actual } }) catch
            Common.invariant("monotype equality could not record a recursive type pair");
    }

    const TypePair = struct {
        expected: Type.TypeId,
        actual: Type.TypeId,
    };

    /// Type equality through alias spellings. A pair is equal when either
    /// side's alias backing is equal to the other, or when their contents
    /// are; a pair already on the current path is equal by assumption, which
    /// is what lets recursive types answer. Evaluated on explicit stacks.
    const SameTypeEquality = struct {
        ctx: *BodyContext,
        visiting: std.AutoHashMap(TypePair, void),

        const Leaf = union(enum) {
            same: TypePair,
            content: TypePair,
        };
        const Eval = collections.AnyAll.Evaluation(Leaf, SameTypeEquality);

        pub fn enter(self: *SameTypeEquality, items: Eval.Items, leaf: Leaf) Allocator.Error!Eval.Expansion {
            const store = self.ctx.typeStore();
            switch (leaf) {
                .same => |pair| {
                    if (pair.expected == pair.actual) return .{ .value = true };
                    var count: usize = 0;
                    if (monoAliasBacking(store, pair.expected)) |backing| {
                        try items.add(.{ .same = .{ .expected = backing, .actual = pair.actual } });
                        count += 1;
                    }
                    if (monoAliasBacking(store, pair.actual)) |backing| {
                        try items.add(.{ .same = .{ .expected = pair.expected, .actual = backing } });
                        count += 1;
                    }
                    if (count == 0) return try self.enter(items, .{ .content = pair });
                    try items.add(.{ .content = pair });
                    return .{ .group = .any };
                },
                .content => |pair| {
                    const expected_digest = store.typeDigestCached(self.ctx.nameStore(), pair.expected, null);
                    const actual_digest = store.typeDigestCached(self.ctx.nameStore(), pair.actual, null);
                    if (std.mem.eql(u8, expected_digest.bytes[0..], actual_digest.bytes[0..])) return .{ .value = true };
                    if (self.visiting.contains(pair)) return .{ .value = true };
                    if (!try self.appendContentPairs(items, pair)) return .{ .value = false };
                    try self.visiting.put(pair, {});
                    return .{ .group = .all };
                },
            }
        }

        pub fn exit(self: *SameTypeEquality, leaf: Leaf, _: ?bool) Allocator.Error!void {
            switch (leaf) {
                .content => |pair| _ = self.visiting.remove(pair),
                .same => {},
            }
        }

        fn addPair(items: Eval.Items, expected: Type.TypeId, actual: Type.TypeId) Allocator.Error!void {
            try items.add(.{ .same = .{ .expected = expected, .actual = actual } });
        }

        fn addSpanPairs(self: *SameTypeEquality, items: Eval.Items, expected: Type.Span, actual: Type.Span) Allocator.Error!bool {
            const expected_items = self.ctx.typeStore().span(expected);
            const actual_items = self.ctx.typeStore().span(actual);
            if (expected_items.len != actual_items.len) return false;
            for (0..GuardedList.borrowLen(expected_items)) |index| {
                try addPair(items, GuardedList.at(expected_items, index), GuardedList.at(actual_items, index));
            }
            return true;
        }

        /// List the child pairs two types' contents are equal through;
        /// false when the contents already differ.
        fn appendContentPairs(self: *SameTypeEquality, items: Eval.Items, pair: TypePair) Allocator.Error!bool {
            const store = self.ctx.typeStore();
            const expected_content = store.get(pair.expected);
            const actual_content = store.get(pair.actual);
            switch (expected_content) {
                .primitive => |primitive| return actual_content == .primitive and actual_content.primitive == primitive,
                .named => |expected| {
                    if (actual_content != .named) return false;
                    const actual = actual_content.named;
                    if (!std.mem.eql(u8, expected.named_type.module.bytes[0..], actual.named_type.module.bytes[0..])) return false;
                    if (expected.def.module != actual.def.module) return false;
                    if (expected.def.source_decl != actual.def.source_decl) return false;
                    if (expected.def.source_decl == null and expected.def.type_name != actual.def.type_name) return false;
                    if (expected.kind != actual.kind) return false;
                    if (expected.builtin_owner != actual.builtin_owner) return false;
                    if (!try self.addSpanPairs(items, expected.args, actual.args)) return false;
                    if ((expected.backing == null) != (actual.backing == null)) return false;
                    if (expected.backing) |expected_backing| {
                        const actual_backing = actual.backing.?;
                        if (expected_backing.use != actual_backing.use) return false;
                        if (expected_backing.authority != actual_backing.authority) return false;
                        try addPair(items, expected_backing.ty, actual_backing.ty);
                    }
                    const expected_entries = store.declaredFieldSpan(expected.declared_order);
                    const actual_entries = store.declaredFieldSpan(actual.declared_order);
                    if (expected_entries.len != actual_entries.len) return false;
                    for (0..GuardedList.borrowLen(expected_entries)) |index| {
                        const expected_entry = GuardedList.at(expected_entries, index);
                        const actual_entry = GuardedList.at(actual_entries, index);
                        switch (expected_entry) {
                            .named => |expected_name| switch (actual_entry) {
                                .named => |actual_name| if (expected_name != actual_name) return false,
                                .padding => return false,
                            },
                            .padding => |expected_ty| switch (actual_entry) {
                                .named => return false,
                                .padding => |actual_ty| try addPair(items, expected_ty, actual_ty),
                            },
                        }
                    }
                    return true;
                },
                .record => |expected_span| {
                    if (actual_content != .record) return false;
                    const expected_fields = store.fieldSpan(expected_span);
                    const actual_fields = store.fieldSpan(actual_content.record);
                    if (expected_fields.len != actual_fields.len) return false;
                    for (0..GuardedList.borrowLen(expected_fields)) |index| {
                        const expected_field = GuardedList.at(expected_fields, index);
                        const actual_field = GuardedList.at(actual_fields, index);
                        if (expected_field.name != actual_field.name) return false;
                        if (expected_field.kind_state != actual_field.kind_state) return false;
                        if ((expected_field.value_ty == null) != (actual_field.value_ty == null)) return false;
                        try addPair(items, expected_field.ty, actual_field.ty);
                        if (expected_field.value_ty) |expected_value_ty| {
                            try addPair(items, expected_value_ty, actual_field.value_ty.?);
                        }
                    }
                    return true;
                },
                .tuple => |expected_items| {
                    if (actual_content != .tuple) return false;
                    return try self.addSpanPairs(items, expected_items, actual_content.tuple);
                },
                .tag_union => |expected_span| {
                    if (actual_content != .tag_union) return false;
                    const expected_tags = store.tagSpan(expected_span);
                    const actual_tags = store.tagSpan(actual_content.tag_union);
                    if (expected_tags.len != actual_tags.len) return false;
                    for (0..GuardedList.borrowLen(expected_tags)) |index| {
                        const expected_tag = GuardedList.at(expected_tags, index);
                        const actual_tag = GuardedList.at(actual_tags, index);
                        if (expected_tag.name != actual_tag.name) return false;
                        if (!try self.addSpanPairs(items, expected_tag.payloads, actual_tag.payloads)) return false;
                    }
                    return true;
                },
                .list => |elem| {
                    if (actual_content != .list) return false;
                    try addPair(items, elem, actual_content.list);
                    return true;
                },
                .box => |elem| {
                    if (actual_content != .box) return false;
                    try addPair(items, elem, actual_content.box);
                    return true;
                },
                .func => |function| {
                    if (actual_content != .func) return false;
                    if (!try self.addSpanPairs(items, function.args, actual_content.func.args)) return false;
                    try addPair(items, function.ret, actual_content.func.ret);
                    return true;
                },
                .erased => |erased| return actual_content == .erased and std.mem.eql(u8, erased.bytes[0..], actual_content.erased.bytes[0..]),
                .zst => return actual_content == .zst,
            }
        }
    };

    /// Materialize a checked field-default identity at `field_cell`.
    fn defaultedFieldValueFromDefaultAtCell(
        self: *BodyContext,
        default: checked.CheckedFieldDefault,
        field_cell: DraftTypeCell,
    ) Allocator.Error!?DraftExprId {
        const origin_module = default.origin() orelse return null;
        return try self.defaultedFieldValueAtCell(
            self.view.names.moduleIdentityBytes(origin_module),
            default.expr_node,
            field_cell,
        );
    }

    /// Materialize a Monotype field-default identity at `field_ty`.
    fn defaultedFieldValueFromMonoDefault(
        self: *BodyContext,
        default: Type.FieldDefault,
        field_ty: Type.TypeId,
    ) Allocator.Error!?DraftExprId {
        return try self.defaultedFieldValueFromMonoDefaultAtCell(default, .{ .sealed = field_ty });
    }

    fn defaultedFieldValueFromMonoDefaultAtCell(
        self: *BodyContext,
        default: Type.FieldDefault,
        field_cell: DraftTypeCell,
    ) Allocator.Error!?DraftExprId {
        return try self.defaultedFieldValueAtCell(
            self.nameStore().moduleIdentityBytes(default.module),
            default.expr_node,
            field_cell,
        );
    }

    /// Materialize a default by lowering its declaring module's archived
    /// checked expression at the construction site's field cell—
    /// per-specialization materialization (design.md "Defaulted Fields").
    /// Relation-producing callers pass live graph-node cells, while frozen
    /// consumers pass sealed field monotypes. There is no archived VALUE and
    /// no cross-root ordering: the inlined expression evaluates as part of
    /// whatever body consumes it (a comptime root's evaluation, or a runtime
    /// body). A foreign default lowers under a scoped view swap, mirroring
    /// `lowerDraftLocalProcAtNode`.
    fn defaultedFieldValueAtCell(
        self: *BodyContext,
        origin_hash: *const [32]u8,
        expr_node: u32,
        field_cell: DraftTypeCell,
    ) Allocator.Error!?DraftExprId {
        if (moduleViewIdentityMatches(self.view, origin_hash)) {
            const default_expr = self.view.bodies.defaultExpr(expr_node) orelse
                Common.invariant("defaulted field's default expression was not archived");
            // Each materialization is its own instantiation of the checked
            // default expression: two construction sites in one body may
            // demand different specializations, so they must not share the
            // consuming body's memoized checked-type nodes (`instNode`
            // caches by checked identity per context). Same mechanism as
            // the foreign branch below, minus the module swap.
            const previous_instantiation = self.instantiation;
            self.instantiation = TypeInstantiationContext.init(self.allocator, self.builder.allocateInstantiationScope(), self.view.key.bytes);
            const previous_in_default_expr = self.in_default_expr;
            self.in_default_expr = true;
            // The default is a closed expression: it binds nothing from the
            // consuming body, so it gets fresh binder state even in its own
            // module (the same rule boxy's `stepModuleExpr` applies).
            // Without this, a second materialization of the same default in
            // one body would capture the first's (or the consuming body's)
            // lexical binder entries into its local-procedure declaration
            // contexts and trip the one-context-per-binder invariant.
            const previous_binders = self.binders;
            const previous_typed_binders = self.typed_binders;
            self.binders = try BinderMap.init(self.allocator, self.view.bodies.patternBinderCount());
            self.typed_binders = TypedBinders.init(self.allocator);
            defer {
                self.binders.deinit();
                self.typed_binders.deinit();
                self.binders = previous_binders;
                self.typed_binders = previous_typed_binders;
                self.in_default_expr = previous_in_default_expr;
                self.instantiation.deinit();
                self.instantiation = previous_instantiation;
            }
            return try self.lowerExprAtTypeCell(default_expr, field_cell);
        }
        const declaring_view = self.builder.moduleForIdentityHash(origin_hash) orelse
            Common.invariant("defaulted field's declaring module was not present in the lowering input");
        const default_expr = declaring_view.bodies.defaultExpr(expr_node) orelse
            Common.invariant("defaulted field's default expression was not archived");

        const previous_view = self.view;
        const previous_source_file_id = self.source_file_id;
        const previous_instantiation = self.instantiation;
        self.view = declaring_view;
        self.source_file_id = self.builder.sourceFileId(declaring_view);
        // Checked-type lookups validate instantiation-context ownership, so
        // the foreign expression gets its own context, exactly like a
        // foreign nominal backing instantiation.
        self.instantiation = TypeInstantiationContext.init(self.allocator, self.builder.allocateInstantiationScope(), declaring_view.key.bytes);
        defer {
            self.instantiation.deinit();
            self.instantiation = previous_instantiation;
            self.view = previous_view;
            self.source_file_id = previous_source_file_id;
        }
        // The default is a closed expression: it binds nothing from the
        // consuming body, so foreign lowering gets fresh binder state
        // exactly like a cross-module local procedure.
        const previous_binders = self.binders;
        const previous_typed_binders = self.typed_binders;
        self.binders = try BinderMap.init(self.allocator, declaring_view.bodies.patternBinderCount());
        self.typed_binders = TypedBinders.init(self.allocator);
        const previous_in_default_expr = self.in_default_expr;
        self.in_default_expr = true;
        defer {
            self.in_default_expr = previous_in_default_expr;
            self.binders.deinit();
            self.typed_binders.deinit();
            self.binders = previous_binders;
            self.typed_binders = previous_typed_binders;
        }
        return try self.lowerExprAtTypeCell(default_expr, field_cell);
    }

    /// The explicit `??` identity carried by a field in `record_ty`.
    fn parserFieldDefaultFor(
        self: *BodyContext,
        record_ty: Type.TypeId,
        field_name: names.RecordFieldNameId,
    ) ?Type.FieldDefault {
        const span = switch (self.shapeContent(record_ty)) {
            .record => |span| span,
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return null,
        };
        const fields = self.typeStore().fieldSpan(span);
        for (0..GuardedList.borrowLen(fields)) |index| {
            const field = GuardedList.at(fields, index);
            if (field.name == field_name) return field.default;
        }
        return null;
    }

    /// Read the concrete kind selected on an immutable Monotype field.
    fn monotypeFieldKindTag(_: *BodyContext, field: Type.Field) checked.CheckedFieldKind.Tag {
        if (field.kind_state != .resolved) {
            Common.invariant("provisional field kind reached sealed record construction");
        }
        if (field.value_ty != null) {
            if (field.default != null) Common.invariant("optional Monotype field carried a default identity");
            return .optional;
        }
        return if (field.default != null) .defaulted else .required;
    }

    fn sealedDefaultedFieldIdentity(field: Type.Field) Type.FieldDefault {
        if (field.kind_state != .resolved or field.value_ty != null) {
            Common.invariant("sealed defaulted field did not have a resolved inline slot");
        }
        return field.default orelse
            Common.invariant("sealed defaulted field carried no Monotype default identity");
    }

    /// Read the kind selected by the checker for a destructured field.
    fn recordDestructFieldKind(
        self: *BodyContext,
        record_checked_ty: checked.CheckedTypeId,
        destruct: checked.CheckedRecordDestruct,
    ) Allocator.Error!checked.CheckedFieldKind.Tag {
        const target = try self.recordFieldName(self.view, destruct.label);
        return recordDestructKindFromResolution(try self.checkedRecordFieldByName(record_checked_ty, target)) orelse
            Common.invariant("record destructure field was missing from its checked row");
    }

    /// Whether a destructure needs checked-Try to runtime-slot translation.
    fn recordDestructsHaveOptionalField(
        self: *BodyContext,
        record_checked_ty: checked.CheckedTypeId,
        destructs: []const checked.CheckedRecordDestruct,
    ) Allocator.Error!bool {
        for (destructs) |destruct| {
            switch (destruct.kind) {
                .required, .sub_pattern => {
                    if ((try self.recordDestructFieldKind(record_checked_ty, destruct)) == .optional) return true;
                },
                .rest => {},
            }
        }
        return false;
    }

    /// The structural backing node behind a (possibly named) Try node.
    fn optionalTryBackingNode(self: *BodyContext, node: NodeId) Allocator.Error!NodeId {
        if ((try self.graph.content(node)) == .named) {
            const backing = (try self.graph.namedNodes(node)).backing orelse
                Common.invariant("optional destructure Try node had no runtime backing");
            if (backing.node == node) Common.invariant("optional destructure Try backing did not advance");
            return backing.node;
        }
        return node;
    }

    /// The Try value a destructured OPTIONAL field binds: a runtime test on
    /// the field's tagged slot—EXACTLY a one-segment `.?` access chain
    /// result (`optionalChainRest`, design.md "Field Kinds")—`Present(v)`
    /// yields `Ok(v)` and `Missing` yields `Err(MissingField)`, constructed
    /// at the binder's own checked `Try(payload, [MissingField])` node.
    fn optionalDestructTryExprAtNode(
        self: *BodyContext,
        slot_expr: DraftExprId,
        slot_node: NodeId,
        try_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const present_name = try self.nameStoreMut().internTagLabel(Builder.optional_slot_present_tag);
        const missing_name = try self.nameStoreMut().internTagLabel(Builder.optional_slot_missing_tag);
        const ok_name = try self.nameStoreMut().internTagLabel("Ok");
        const err_name = try self.nameStoreMut().internTagLabel("Err");
        const slot_cell = DraftTypeCell.fromGraphNode(slot_node);

        const payload_node = try self.graph.tagPayloadNode(slot_node, present_name, 0);
        const payload_cell = DraftTypeCell.fromGraphNode(payload_node);
        const payload_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), payload_cell, null);
        const present_pat = try self.addPatWithTypeCell(slot_cell, .{ .tag = .{
            .name = present_name,
            .payloads = try self.addPatSpan(&.{try self.addPatWithTypeCell(payload_cell, .{ .bind = payload_local })}),
        } });
        const ok_body = try self.addConstructorExprAtNode(try_node, .{ .tag = .{
            .name = ok_name,
            .payloads = try self.addExprSpan(&.{try self.addExprWithTypeCell(payload_cell, .{ .local = payload_local })}),
        } });

        const missing_pat = try self.addPatWithTypeCell(slot_cell, .{ .tag = .{
            .name = missing_name,
            .payloads = .empty(),
        } });
        const err_node = try self.graph.tagPayloadNode((try self.optionalTryBackingNode(try_node)), err_name, 0);
        const err_body = try self.addConstructorExprAtNode(try_node, .{ .tag = .{
            .name = err_name,
            .payloads = try self.addExprSpan(&.{try self.optionalDestructMissingFieldExprAtNode(err_node)}),
        } });

        const branches = [_]DraftBranch{
            .{ .pat = present_pat, .body = ok_body },
            .{ .pat = missing_pat, .body = err_body },
        };
        return try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(try_node), .{ .match_ = .{
            .scrutinee = slot_expr,
            .branches = try self.addBranchSpan(&branches),
        } });
    }

    /// The constant `MissingField` error value at the Try's error node (the
    /// closed `[MissingField]` union the checker minted for the binder).
    fn optionalDestructMissingFieldExprAtNode(self: *BodyContext, err_node: NodeId) Allocator.Error!DraftExprId {
        const missing_field_name = try self.nameStoreMut().internTagLabel("MissingField");
        return try self.addConstructorExprAtNode(err_node, .{ .tag = .{
            .name = missing_field_name,
            .payloads = .empty(),
        } });
    }

    /// Queue a translated optional-destruct binder whose value is the slot
    /// local materialized as Try.
    fn queueOptionalDestructSlotBind(
        self: *BodyContext,
        binder: checked.PatternBinderId,
        slot_local: DraftLocalId,
        slot_node: NodeId,
        result_node: NodeId,
    ) Allocator.Error!void {
        const binder_local = try self.materializePatternBinderAtCell(binder, DraftTypeCell.fromGraphNode(result_node));
        try self.optional_destruct_binds.append(self.allocator, .{
            .binder_local = binder_local,
            .value = .{ .slot_to_try = .{
                .slot_local = slot_local,
                .slot_node = slot_node,
                .try_node = result_node,
            } },
        });
    }

    /// Queue the binders of an `Err(p)` payload pattern translated to the
    /// slot's `Missing` tag: `p` matches the closed `[MissingField]` union,
    /// so its refutable part (`MissingField`) always matches and its binders
    /// bind the constant error value.
    fn queueOptionalDestructErrPayloadBinds(
        self: *BodyContext,
        root_pattern: checked.CheckedPatternId,
        err_node: NodeId,
    ) Allocator.Error!void {
        var pattern_id = root_pattern;
        while (true) {
            const pattern = self.view.bodies.pattern(pattern_id);
            switch (pattern.data) {
                .underscore => return,
                .assign => |binder| {
                    const binder_local = try self.materializePatternBinderAtCell(binder, DraftTypeCell.fromGraphNode(err_node));
                    try self.optional_destruct_binds.append(self.allocator, .{
                        .binder_local = binder_local,
                        .value = .{ .missing_err = .{ .err_node = err_node } },
                    });
                    return;
                },
                .as => |as| {
                    const binder_local = try self.materializePatternBinderAtCell(as.binder, DraftTypeCell.fromGraphNode(err_node));
                    try self.optional_destruct_binds.append(self.allocator, .{
                        .binder_local = binder_local,
                        .value = .{ .missing_err = .{ .err_node = err_node } },
                    });
                    pattern_id = as.pattern;
                },
                .applied_tag => |tag| {
                    // `[MissingField]` has exactly one payload-less tag; the
                    // pattern always matches once the slot is Missing.
                    if (tag.args.len != 0) {
                        Common.invariant("optional destructure MissingField pattern carried a payload");
                    }
                    return;
                },
                .pending,
                .nominal,
                .record_destructure,
                .list,
                .tuple,
                .numeral_literal,
                .str_literal,
                .str_interpolation,
                .runtime_error,
                => Common.invariant("optional destructure Err payload pattern had a non-[MissingField] checked shape"),
            }
        }
    }

    /// Take ownership of the optional-destruct binder preludes collected
    /// since `start`, restoring the collection to that length (the
    /// `drainPatternLiteralGuards` discipline).
    fn drainOptionalDestructBinds(self: *BodyContext, start: usize) Allocator.Error![]OptionalDestructBind {
        const drained = try self.allocator.dupe(OptionalDestructBind, self.optional_destruct_binds.items[start..]);
        self.optional_destruct_binds.shrinkRetainingCapacity(start);
        return drained;
    }

    /// Wrap an expression (a match branch's body or guard) in the queued
    /// optional-destruct binder preludes: one `let` per user binder,
    /// computing its Try (or constant error) value from the slot local the
    /// translated pattern bound.
    fn applyOptionalDestructBinds(
        self: *BodyContext,
        binds: []const OptionalDestructBind,
        body: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const BoundValue = struct {
            value: DraftExprId,
            cell: DraftTypeCell,
        };
        var result = body;
        const result_cell = self.exprTypeCell(body);
        var index = binds.len;
        while (index > 0) {
            index -= 1;
            const bind = binds[index];
            const bound: BoundValue = switch (bind.value) {
                .slot_to_try => |conv| blk: {
                    const slot_expr = try self.addExprWithTypeCell(
                        DraftTypeCell.fromGraphNode(conv.slot_node),
                        .{ .local = conv.slot_local },
                    );
                    break :blk .{
                        .value = try self.optionalDestructTryExprAtNode(slot_expr, conv.slot_node, conv.try_node),
                        .cell = DraftTypeCell.fromGraphNode(conv.try_node),
                    };
                },
                .missing_err => |err| .{
                    .value = try self.optionalDestructMissingFieldExprAtNode(err.err_node),
                    .cell = DraftTypeCell.fromGraphNode(err.err_node),
                },
            };
            result = try self.addExprWithTypeCell(result_cell, .{ .let_ = .{
                .bind = try self.addPatWithTypeCell(bound.cell, .{ .bind = bind.binder_local }),
                .value = bound.value,
                .rest = result,
            } });
        }
        return result;
    }

    /// How a checked-row field lookup resolved. `scheme_interior` is not a
    /// miss: the walk reached a row that is still a type VARIABLE at
    /// template lowering (a generalized scheme interior, e.g. the result
    /// row of a generic record update), which every read boundary treats
    /// required-equivalent per design.md "Kind defaulting as a checker
    /// pass". Only `absent`—a concrete row that does not carry the field—
    /// is a genuine miss.
    const CheckedFieldResolution = union(enum) {
        found: checked.CheckedRecordField,
        scheme_interior,
        absent,
    };

    fn recordDestructKindFromResolution(resolution: CheckedFieldResolution) ?checked.CheckedFieldKind.Tag {
        return switch (resolution) {
            .found => |field| field.kind.tag,
            .scheme_interior => .required,
            .absent => null,
        };
    }

    /// Find a checked field through aliases, nominal backing, and row tails.
    fn checkedRecordFieldByName(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        field_name: names.RecordFieldNameId,
    ) Allocator.Error!CheckedFieldResolution {
        const Visited = struct { module: @TypeOf(self.view.key.bytes), ty: checked.CheckedTypeId };
        var seen = std.AutoHashMap(Visited, void).init(self.allocator);
        defer seen.deinit();
        var view = self.view;
        var current = checked_ty;
        while (true) {
            const visit = Visited{ .module = view.key.bytes, .ty = current };
            if (seen.contains(visit)) return .absent;
            try seen.put(visit, {});
            switch (checkedPayload(view, current)) {
                .alias => |alias| current = alias.backing,
                .record => |record| {
                    for (record.fields) |checked_field| {
                        const lowered_name = try self.recordFieldName(view, checked_field.name);
                        if (lowered_name == field_name) return .{ .found = checked_field };
                    }
                    current = record.ext;
                },
                .nominal => |nominal| {
                    const lookup = self.builder.nominalDeclarationFor(view, nominal) orelse return .absent;
                    view = lookup.view;
                    current = lookup.declaration.backing;
                },
                .flex, .rigid => return .scheme_interior,
                .pending, .err, .tuple, .function, .empty_record, .tag_union, .empty_tag_union => return .absent,
            }
        }
    }

    /// Construct an optional field's tagged Present slot at its graph node
    /// (the closed `[#Missing, #Present(value)]` union). The supplied value's
    /// node was already unified into the slot union's Present payload by the
    /// caller, so no active Monotype view is demanded here.
    fn optionalSlotPresentExprAtNode(
        self: *BodyContext,
        slot_node: NodeId,
        value_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const present = try self.nameStoreMut().internTagLabel(Builder.optional_slot_present_tag);
        return try self.addConstructorExprAtNode(slot_node, .{ .tag = .{
            .name = present,
            .payloads = try self.addExprSpan(&[_]DraftExprId{value_expr}),
        } });
    }

    /// Construct an optional field's tagged slot in the missing state at its
    /// graph node.
    fn optionalSlotMissingExprAtNode(self: *BodyContext, slot_node: NodeId) Allocator.Error!DraftExprId {
        const missing = try self.nameStoreMut().internTagLabel(Builder.optional_slot_missing_tag);
        return try self.addConstructorExprAtNode(slot_node, .{ .tag = .{
            .name = missing,
            .payloads = .empty(),
        } });
    }

    fn optionalSlotPresentExpr(
        self: *BodyContext,
        slot_ty: Type.TypeId,
        slot: Builder.OptionalSlotInfo,
        value_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        if (!self.sameType(try self.exprType(value_expr), slot.payload_ty)) {
            Common.invariant("optional field's supplied value type differed from its slot payload type");
        }
        return try self.addExpr(.{
            .ty = slot_ty,
            .data = .{ .tag = .{
                .name = slot.present_tag.name,
                .payloads = try self.addExprSpan(&[_]DraftExprId{value_expr}),
            } },
        });
    }

    /// Construct an optional field's tagged slot in the missing state:
    /// `Missing` at the slot's union type.
    fn optionalSlotMissingExpr(self: *BodyContext, slot_ty: Type.TypeId) Allocator.Error!DraftExprId {
        const slot = try self.optionalSlotInfo(slot_ty);
        return try self.addExpr(.{
            .ty = slot_ty,
            .data = .{ .tag = .{
                .name = slot.missing_tag.name,
                .payloads = .empty(),
            } },
        });
    }

    /// An optional segment of an access chain whose match waits on the rest
    /// of the chain as its present branch.
    const PendingOptionalSegmentAtNode = struct {
        slot_cell: DraftTypeCell,
        slot_expr: DraftExprId,
        present_pat: DraftPatId,
        missing_name: names.TagNameId,
    };

    fn optionalChainRestAtNode(
        self: *BodyContext,
        segments: []const checked.CheckedFieldAccessSegment,
        start: usize,
        receiver: DraftExprId,
        receiver_node: NodeId,
        out_try_node: NodeId,
    ) Allocator.Error!DraftExprId {
        var pending = std.ArrayList(PendingOptionalSegmentAtNode).empty;
        defer pending.deinit(self.allocator);
        var current = receiver;
        var current_node = receiver_node;
        for (segments[start..]) |segment| {
            const field_name = try self.recordFieldName(self.view, segment.field_name);
            switch (segment.mode) {
                .required => {
                    const field_node = try self.graph.requiredRecordFieldNode(current_node, field_name);
                    current = try self.addExprWithTypeCell(
                        DraftTypeCell.fromGraphNode(field_node),
                        .{ .field_access = .{
                            .receiver = current,
                            .segments = try self.draft.addFieldAccessSegmentSpan(&.{.{ .field = field_name }}),
                        } },
                    );
                    current_node = field_node;
                },
                .optional => {
                    const field = try self.graph.optionalRecordFieldNodes(current_node, field_name);
                    const slot_cell = DraftTypeCell.fromGraphNode(field.slot);
                    const payload_cell = DraftTypeCell.fromGraphNode(field.value);
                    const slot_expr = try self.addExprWithTypeCell(slot_cell, .{ .field_access = .{
                        .receiver = current,
                        .segments = try self.draft.addFieldAccessSegmentSpan(&.{.{ .field = field_name }}),
                    } });

                    const present_name = try self.nameStoreMut().internTagLabel(Builder.optional_slot_present_tag);
                    const missing_name = try self.nameStoreMut().internTagLabel(Builder.optional_slot_missing_tag);
                    const payload_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), payload_cell, null);
                    const present_pat = try self.addPatWithTypeCell(slot_cell, .{ .tag = .{
                        .name = present_name,
                        .payloads = try self.addPatSpan(&.{try self.addPatWithTypeCell(payload_cell, .{ .bind = payload_local })}),
                    } });
                    try pending.append(self.allocator, .{
                        .slot_cell = slot_cell,
                        .slot_expr = slot_expr,
                        .present_pat = present_pat,
                        .missing_name = missing_name,
                    });
                    current = try self.addExprWithTypeCell(payload_cell, .{ .local = payload_local });
                    current_node = field.value;
                },
            }
        }

        const ok_name = try self.nameStoreMut().internTagLabel("Ok");
        var result = try self.addConstructorExprAtNode(out_try_node, .{ .tag = .{
            .name = ok_name,
            .payloads = try self.addExprSpan(&.{current}),
        } });
        // Each optional segment's match takes the rest of the chain as its
        // present branch, so the innermost segment's match is built first.
        var index = pending.items.len;
        while (index > 0) {
            index -= 1;
            const segment = pending.items[index];
            const missing_pat = try self.addPatWithTypeCell(segment.slot_cell, .{ .tag = .{
                .name = segment.missing_name,
                .payloads = .empty(),
            } });
            const err_name = try self.nameStoreMut().internTagLabel("Err");
            const err_node = try self.graph.tagPayloadNode((try self.optionalTryBackingNode(out_try_node)), err_name, 0);
            const missing_body = try self.addConstructorExprAtNode(out_try_node, .{ .tag = .{
                .name = err_name,
                .payloads = try self.addExprSpan(&.{try self.optionalDestructMissingFieldExprAtNode(err_node)}),
            } });

            const branches = [_]DraftBranch{
                .{ .pat = segment.present_pat, .body = result },
                .{ .pat = missing_pat, .body = missing_body },
            };
            result = try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(out_try_node), .{ .match_ = .{
                .scrutinee = segment.slot_expr,
                .branches = try self.addBranchSpan(&branches),
            } });
        }
        return result;
    }

    /// An optional segment of an access chain whose match waits on the rest
    /// of the chain as its present branch.
    const PendingOptionalSegment = struct {
        slot_ty: Type.TypeId,
        slot_expr: DraftExprId,
        present_pat: DraftPatId,
        missing_name: names.TagNameId,
    };

    fn optionalChainRest(
        self: *BodyContext,
        segments: []const checked.CheckedFieldAccessSegment,
        start: usize,
        receiver: DraftExprId,
        receiver_ty: Type.TypeId,
        out_try_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        var pending = std.ArrayList(PendingOptionalSegment).empty;
        defer pending.deinit(self.allocator);
        var current = receiver;
        var current_ty = receiver_ty;
        for (segments[start..]) |segment| {
            const field_name = try self.recordFieldName(self.view, segment.field_name);
            const slot_ty = self.recordFieldType(current_ty, field_name);
            switch (segment.mode) {
                .required => {
                    current = try self.addFieldAccessExpr(current, field_name, slot_ty);
                    current_ty = slot_ty;
                },
                .optional => {
                    const slot = try self.optionalSlotInfo(slot_ty);
                    const slot_expr = try self.addFieldAccessExpr(current, field_name, slot_ty);

                    const payload_local = try self.addLocal(self.builder.symbols.fresh(), slot.payload_ty);
                    const payload_pat = try self.bindPat(payload_local, slot.payload_ty);
                    const present_pat = try self.addPat(.{ .ty = slot_ty, .data = .{ .tag = .{
                        .name = slot.present_tag.name,
                        .payloads = try self.addPatSpan(&[_]DraftPatId{payload_pat}),
                    } } });
                    try pending.append(self.allocator, .{
                        .slot_ty = slot_ty,
                        .slot_expr = slot_expr,
                        .present_pat = present_pat,
                        .missing_name = slot.missing_tag.name,
                    });
                    current = try self.localExpr(payload_local, slot.payload_ty);
                    current_ty = slot.payload_ty;
                },
            }
        }

        var result = try self.tryOk(out_try_ty, current);
        // Each optional segment's match takes the rest of the chain as its
        // present branch, so the innermost segment's match is built first.
        var index = pending.items.len;
        while (index > 0) {
            index -= 1;
            const segment = pending.items[index];
            const missing_pat = try self.addPat(.{ .ty = segment.slot_ty, .data = .{ .tag = .{
                .name = segment.missing_name,
                .payloads = .empty(),
            } } });
            const err_ty = self.tryInfo(out_try_ty).err_ty;
            const missing_body = try self.tryErr(
                out_try_ty,
                try self.tagUnionValueWithoutPayload(err_ty, "MissingField"),
            );

            const branches = [_]DraftBranch{
                .{ .pat = segment.present_pat, .body = result },
                .{ .pat = missing_pat, .body = missing_body },
            };
            result = try self.addExpr(.{ .ty = out_try_ty, .data = .{ .match_ = .{
                .scrutinee = segment.slot_expr,
                .branches = try self.addBranchSpan(&branches),
            } } });
        }
        return result;
    }

    /// A record literal at a sealed record type. Its children lower as child
    /// tasks, in the order a direct walk lowers them, and the record is built
    /// from them once all are lowered.
    const RecordAtTypeTask = struct {
        record: @FieldType(checked.CheckedExprData, "record"),
        ty: Type.TypeId,
        /// The child expressions to lower, each with its target, in order.
        requests: []const RecordChildRequest,
        lowered: []PreLoweredChild,
        next: usize = 0,

        fn deinit(task: *RecordAtTypeTask, allocator: Allocator) void {
            allocator.free(task.requests);
            allocator.free(task.lowered);
            task.requests = &.{};
            task.lowered = &.{};
        }
    };

    const RecordChildRequest = struct {
        expr: checked.CheckedExprId,
        target: union(enum) {
            /// The record update's base, lowered at its own type.
            base,
            at_type: Type.TypeId,
            /// A proven-uninhabited field: a zero-branch match on the
            /// uninhabited scrutinee.
            uninhabited: Type.TypeId,
        },
    };

    fn beginRecordAtType(
        self: *BodyContext,
        record: @FieldType(checked.CheckedExprData, "record"),
        ty: Type.TypeId,
    ) Allocator.Error!LowerStep {
        var requests = std.ArrayList(RecordChildRequest).empty;
        errdefer requests.deinit(self.allocator);
        if (record.ext) |ext| {
            try requests.append(self.allocator, .{ .expr = ext, .target = .base });
            for (record.fields) |field| {
                const name = try self.recordFieldName(self.view, field.label);
                const target_field = self.recordField(ty, name);
                const target_ty = if (self.monotypeFieldKindTag(target_field) == .optional)
                    (try self.optionalSlotInfo(target_field.ty)).payload_ty
                else
                    target_field.ty;
                try requests.append(self.allocator, .{ .expr = field.value, .target = .{ .at_type = target_ty } });
            }
        } else {
            const target_fields = switch (self.shapeContent(ty)) {
                .record => |fields| fields,
                .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("record expression had a non-record monotype"),
            };
            const target_field_list = try GuardedList.dupe(self.allocator, Type.Field, self.typeStore().fieldSpan(target_fields));
            defer self.allocator.free(target_field_list);
            var labels = try self.recordExprLabels(record);
            defer labels.deinit(self.allocator);
            for (target_field_list) |field| {
                const field_value = labels.values.get(field.name) orelse continue;
                if (self.monotypeFieldKindTag(field) == .optional) {
                    try requests.append(self.allocator, .{ .expr = field_value, .target = .{ .at_type = (try self.optionalSlotInfo(field.ty)).payload_ty } });
                } else if (try self.typeIsProvenUninhabited(field.ty)) {
                    try requests.append(self.allocator, .{ .expr = field_value, .target = .{ .uninhabited = field.ty } });
                } else {
                    try requests.append(self.allocator, .{ .expr = field_value, .target = .{ .at_type = field.ty } });
                }
            }
        }
        const owned = try requests.toOwnedSlice(self.allocator);
        errdefer self.allocator.free(owned);
        const lowered = try self.allocator.alloc(PreLoweredChild, owned.len);
        return requestLowerTask(self, .{ .record_at_type = .{ .record = record, .ty = ty, .requests = owned, .lowered = lowered } });
    }

    fn stepRecordAtType(self: *BodyContext, task: *RecordAtTypeTask, input: ?LowerResult) Allocator.Error!LowerStep {
        if (input) |result| {
            const request = task.requests[task.next];
            const child = result.exprValue();
            task.lowered[task.next] = .{
                .checked_expr = request.expr,
                .expr = switch (request.target) {
                    .base, .at_type => child,
                    .uninhabited => |ty| try self.zeroBranchMatch(child, ty),
                },
            };
            task.next += 1;
        }
        if (task.next < task.requests.len) {
            const request = task.requests[task.next];
            return switch (request.target) {
                .base => requestLowerTask(self, .{ .expr = .{ .expr = request.expr } }),
                .at_type => |ty| requestLowerTask(self, .{ .at_type_cell = .{
                    .expr = request.expr,
                    .cell = .{ .sealed = ty },
                    .demand = .runtime_value,
                    .diverges = self.checkedExprDivergesInLoweredRuntime(request.expr),
                } }),
                .uninhabited => |ty| uninhabitedScrutineeStep(self, request.expr, .{ .sealed = ty }),
            };
        }
        return loweredExprStep(try self.lowerRecordExpr(task.record, task.ty, task.lowered));
    }

    fn lowerRecordExpr(
        self: *BodyContext,
        record: anytype,
        ty: Type.TypeId,
        pre_lowered: []const PreLoweredChild,
    ) Allocator.Error!DraftExprId {
        var labels = try self.recordExprLabels(record);
        defer labels.deinit(self.allocator);
        var pre_by_expr = try self.preLoweredIndex(pre_lowered);
        defer pre_by_expr.deinit(self.allocator);
        if (record.ext) |ext| {
            const base_expr = pre_by_expr.get(ext) orelse
                Common.invariant("record update lost its pre-lowered base child");
            const fields = try self.allocator.alloc(DraftFieldExpr, record.fields.len + record.unsets.len);
            defer self.allocator.free(fields);
            for (record.fields, 0..) |field, index| {
                const name = labels.field_names[index];
                const target_field = self.recordField(ty, name);
                const slot_ty = target_field.ty;
                const field_kind: checked.CheckedFieldKind.Tag =
                    self.monotypeFieldKindTag(target_field);
                fields[index] = .{
                    .name = name,
                    .value = value: {
                        // Supplied optional values enter the slot through #Present.
                        if (field_kind == .optional) {
                            const slot = try self.optionalSlotInfo(slot_ty);
                            const payload = if (pre_by_expr.get(field.value)) |pre| pre_blk: {
                                if (!self.sameType(slot.payload_ty, try self.exprType(pre))) {
                                    Common.invariant("record update child lowered at a type different from its finalized field type");
                                }
                                break :pre_blk pre;
                            } else Common.invariant("record update lost its pre-lowered field child");
                            break :value try self.optionalSlotPresentExpr(slot_ty, slot, payload);
                        }
                        break :value pre_by_expr.get(field.value) orelse
                            Common.invariant("record update lost its pre-lowered field child");
                    },
                };
            }
            // An UNSET field becomes an explicitly listed update field whose
            // value is the slot's Missing tag—the same construction an
            // omitted optional field uses (design.md "In Progress: Unsetting
            // an Optional Field"). The backend keeps copying unlisted slots
            // and writing listed ones.
            for (record.unsets, 0..) |label, unset_index| {
                const name = try self.recordFieldName(self.view, label);
                const target_field = self.recordField(ty, name);
                if (self.monotypeFieldKindTag(target_field) != .optional) {
                    Common.invariant("record update unset field was not optional after checking");
                }
                fields[record.fields.len + unset_index] = .{
                    .name = name,
                    .value = try self.optionalSlotMissingExpr(target_field.ty),
                };
            }
            return try self.addExpr(.{ .ty = ty, .data = .{ .record_update = .{
                .base = base_expr,
                .fields = try self.addFieldExprSpan(fields),
            } } });
        }

        // The closed constructor never lists unset fields explicitly—an
        // unset optional slot is constructed by the omitted-optional arm
        // below—but every unset label must still name an OPTIONAL field in
        // the row, the same validation the update arm above applies. Without
        // it, an unset of a defaulted field would silently take the
        // defaulted arm and materialize the default, diverging from boxy
        // lowering (which panics on the same input).
        for (record.unsets) |label| {
            const name = try self.recordFieldName(self.view, label);
            if (self.monotypeFieldKindTag(self.recordField(ty, name)) != .optional) {
                Common.invariant("record constructor unset field was not optional after checking");
            }
        }

        const target_fields = switch (self.shapeContent(ty)) {
            .record => |fields| fields,
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("record expression had a non-record monotype"),
        };
        const target_field_count: usize = @intCast(target_fields.len);
        const lowered = try self.allocator.alloc(DraftFieldExpr, target_field_count);
        defer self.allocator.free(lowered);
        const base_record = if (record.ext) |ext|
            pre_by_expr.get(ext) orelse
                Common.invariant("record constructor lost its pre-lowered base child")
        else
            null;
        const base_ty = if (base_record) |base_expr| try self.exprType(base_expr) else ty;
        const base_local = if (base_record) |_| try self.addLocal(self.builder.symbols.fresh(), base_ty) else null;
        const base_expr = if (base_local) |local| try self.localExpr(local, base_ty) else null;
        const target_field_list = try GuardedList.dupe(self.allocator, Type.Field, self.typeStore().fieldSpan(target_fields));
        defer self.allocator.free(target_field_list);

        // See lowerRecordExprAtNode: spread-carried reads bind before the
        // update's own field expressions run, so the base's last use precedes
        // any mutation they perform.
        const SpreadRead = struct { local: DraftLocalId, value: DraftExprId };
        const spread_reads = try self.allocator.alloc(?SpreadRead, target_field_count);
        defer self.allocator.free(spread_reads);
        @memset(spread_reads, null);

        for (0..target_field_count) |i| {
            const field = target_field_list[i];
            const field_kind: checked.CheckedFieldKind.Tag =
                self.monotypeFieldKindTag(field);
            const value = if (labels.values.get(field.name)) |field_value| supplied: {
                // A SUPPLIED OPTIONAL field wraps its value in the slot's
                // Present tag (design.md "Field Kinds"); the checked field
                // expression's type is the VALUE type, never the slot.
                if (field_kind == .optional) {
                    const slot = try self.optionalSlotInfo(field.ty);
                    const payload = if (pre_by_expr.get(field_value)) |pre| pre_blk: {
                        if (!self.sameType(slot.payload_ty, try self.exprType(pre))) {
                            Common.invariant("record constructor child lowered at a type different from its finalized field type");
                        }
                        break :pre_blk pre;
                    } else Common.invariant("record constructor lost its pre-lowered field child");
                    break :supplied try self.optionalSlotPresentExpr(field.ty, slot, payload);
                }
                if (pre_by_expr.get(field_value)) |pre| {
                    if (!self.sameType(field.ty, try self.exprType(pre))) {
                        Common.invariant("record constructor child lowered at a type different from its finalized field type");
                    }
                    break :supplied pre;
                }
                Common.invariant("record constructor lost its pre-lowered field child");
            } else if (base_expr) |base_value| blk: {
                // Record update copies unmentioned slots verbatim—for an
                // optional field that copies the tagged slot, presence state
                // included. (A MENTIONED optional field takes the supplied
                // branch above: the construction rule applies, the value wraps in
                // `Present` exactly as construction does.) The read is
                // hoisted into its own local so the base's last use ends
                // before any updated field's expression runs (see the
                // spread_reads comment above).
                const read = try self.addFieldAccessExpr(base_value, field.name, field.ty);
                const read_local = try self.addLocal(self.builder.symbols.fresh(), field.ty);
                spread_reads[i] = .{ .local = read_local, .value = read };
                break :blk try self.localExpr(read_local, field.ty);
            } else if (field_kind == .defaulted) defaulted: {
                const default = sealedDefaultedFieldIdentity(field);
                break :defaulted (try self.defaultedFieldValueFromMonoDefault(default, field.ty)) orelse
                    Common.invariant("sealed defaulted field had no archived default value");
            } else if (field_kind == .optional)
                // An OMITTED OPTIONAL field (admitted by width absorption)
                // constructs the slot's Missing tag.
                try self.optionalSlotMissingExpr(field.ty)
            else
                Common.invariant("closed record literal was missing a checked field value");
            lowered[i] = .{
                .name = field.name,
                .value = value,
            };
        }
        const field_binds = try self.bindRecordFieldsInSourceOrder(labels.field_names, lowered);
        defer self.allocator.free(field_binds);
        var record_expr = try self.addConstructorExpr(ty, .{ .record = try self.addFieldExprSpan(lowered) });
        record_expr = try self.wrapRecordFieldBinds(field_binds, .{ .sealed = ty }, record_expr);
        var spread_index: usize = target_field_count;
        while (spread_index > 0) {
            spread_index -= 1;
            const read = spread_reads[spread_index] orelse continue;
            record_expr = try self.addExpr(.{ .ty = ty, .data = .{ .let_ = .{
                .bind = try self.bindPat(read.local, target_field_list[spread_index].ty),
                .value = read.value,
                .rest = record_expr,
            } } });
        }
        if (base_record) |base_value| {
            return try self.addExpr(.{ .ty = ty, .data = .{ .let_ = .{
                .bind = try self.bindPat(base_local orelse Common.invariant("record update lowered base without a base local"), base_ty),
                .value = base_value,
                .rest = record_expr,
            } } });
        }
        return record_expr;
    }

    fn lowerRecordExprAtNode(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        record: anytype,
        record_node: NodeId,
        pre_lowered: []const PreLoweredChild,
    ) Allocator.Error!DraftExprId {
        var labels = try self.recordExprLabels(record);
        defer labels.deinit(self.allocator);
        var pre_by_expr = try self.preLoweredIndex(pre_lowered);
        defer pre_by_expr.deinit(self.allocator);
        var construction = try self.constructionFields(record_node);
        defer construction.deinit(self.allocator);
        if (record.ext) |ext| {
            const base_expr = pre_by_expr.get(ext) orelse
                Common.invariant("record graph update lost its pre-lowered base child");
            const fields = try self.allocator.alloc(DraftFieldExpr, record.fields.len + record.unsets.len);
            defer self.allocator.free(fields);
            for (record.fields, 0..) |field, index| {
                const name = labels.field_names[index];
                const pre = pre_by_expr.get(field.value) orelse
                    Common.invariant("record graph update lost its pre-lowered field child");
                const field_kind = try self.graph.recordConstructionFieldKindOf(construction.get(name));
                // A SUPPLIED OPTIONAL field's child was lowered at the slot's
                // Present payload; wrap it into the tagged slot at the slot's
                // graph node (design.md "Field Kinds (All-Dynamic Optional
                // Fields)"). Required and defaulted slots write the child
                // verbatim.
                const value = if (field_kind == .optional)
                    try self.optionalSlotPresentExprAtNode(
                        self.graph.rootNode(construction.get(name).ty),
                        pre,
                    )
                else
                    pre;
                fields[index] = .{ .name = name, .value = value };
            }
            // An UNSET field becomes an explicitly listed update field whose
            // value is the slot's Missing tag—the same construction an
            // omitted optional field uses (design.md "In Progress: Unsetting
            // an Optional Field"). The backend keeps copying unlisted slots
            // and writing listed ones. The Missing tag is constructed at the
            // slot's own graph node, so unset fields keep the checked
            // representation and take no part in witness selection below.
            for (record.unsets, 0..) |label, unset_index| {
                const name = try self.recordFieldName(self.view, label);
                const field_kind = try self.graph.recordConstructionFieldKindOf(construction.get(name));
                if (field_kind != .optional) {
                    Common.invariant("record graph update unset field was not optional after checking");
                }
                fields[record.fields.len + unset_index] = .{
                    .name = name,
                    .value = try self.optionalSlotMissingExprAtNode(
                        self.graph.rootNode(construction.get(name).ty),
                    ),
                };
            }
            // An updated field's producer-authored child can carry a
            // representation distinct from the checked-public field slot, so
            // updates run the same witness selection as closed constructors;
            // spread-carried fields keep their checked slots from the base.
            const target_fields = (try self.graph.recordConstructionNodes(record_node)).fields;
            const produced_fields = try self.allocator.alloc(InstField, target_fields.len);
            defer self.allocator.free(produced_fields);
            var requires_distinct_witness = false;
            for (0..target_fields.len) |index| {
                const field = target_fields[index];
                produced_fields[index] = field;
                const field_value = labels.values.get(field.name) orelse continue;
                // A supplied optional field's child is the slot's Present
                // payload, not the tagged slot itself, and it was already
                // wrapped above; its slot keeps the checked representation.
                if ((try self.graph.recordConstructionFieldKindOf(field)) == .optional) continue;
                const pre = pre_by_expr.get(field_value) orelse
                    Common.invariant("record graph update lost its pre-lowered field child");
                const child_node = try self.exprTypeCell(pre).toGraphNode(self.graph);
                const witness = try self.constructorChildWitness(
                    field.ty,
                    child_node,
                    "record graph update child differed without explicit representation evidence",
                );
                if (witness.requires_witness) requires_distinct_witness = true;
                produced_fields[index] = .{
                    .name = field.name,
                    .ty = witness.slot,
                    .value_ty = field.value_ty,
                    .kind = field.kind,
                    .default = field.default,
                };
            }
            const produced_node = if (requires_distinct_witness) blk: {
                const witness_fields = try self.graph.arena().dupe(InstField, produced_fields);
                const structural_node = try self.graph.newNode(.{ .record = .{
                    .fields = witness_fields,
                    .ext = try self.graph.newNode(.empty_record),
                } });
                const witness = try self.constructorWitnessWithStructuralNode(record_node, structural_node);
                break :blk try self.relateCheckedNodeToProducedValue(record_node, witness);
            } else record_node;
            return try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(produced_node), .{ .record_update = .{
                .base = base_expr,
                .fields = try self.addFieldExprSpan(fields),
            } });
        }

        // Same unset validation as the closed constructor in
        // `lowerRecordExpr` (and the graph update arm above): an unset label
        // must name an OPTIONAL field in the row; the omitted-optional arm
        // below then constructs its Missing slot. Without this, an unset of
        // a defaulted field would silently materialize the default.
        for (record.unsets) |label| {
            const name = try self.recordFieldName(self.view, label);
            if ((try self.graph.recordConstructionFieldKindOf(construction.get(name))) != .optional) {
                Common.invariant("record graph constructor unset field was not optional after checking");
            }
        }

        const target_fields = (try self.graph.recordConstructionNodes(record_node)).fields;
        const lowered = try self.allocator.alloc(DraftFieldExpr, target_fields.len);
        defer self.allocator.free(lowered);
        const produced_fields = try self.allocator.alloc(InstField, target_fields.len);
        defer self.allocator.free(produced_fields);
        var requires_distinct_witness = false;

        const base_record = if (record.ext) |ext|
            pre_by_expr.get(ext) orelse
                Common.invariant("record constructor lost its pre-lowered base child")
        else
            null;
        const base_cell = if (base_record) |base_value|
            self.exprTypeCell(base_value)
        else
            DraftTypeCell.fromGraphNode(record_node);
        const base_local = if (base_record != null)
            try self.addLocalWithBinderCell(self.builder.symbols.fresh(), base_cell, null)
        else
            null;
        const base_expr = if (base_local) |local|
            try self.addExprWithTypeCell(base_cell, .{ .local = local })
        else
            null;

        // Spread-carried fields are read out of the base before the update's
        // own field expressions run, each bound to its own local. Each field
        // read only accesses already-evaluated record storage, so scheduling
        // the reads first preserves effects and ends the base's last use ahead
        // of any mutation an updated field performs. Without it, the base stays
        // live across those mutations and only the field read scheduled last
        // by ascending field-name order finds its collection
        // uniquely referenced; every other field copies its whole value.
        const SpreadRead = struct { local: DraftLocalId, cell: DraftTypeCell, value: DraftExprId };
        const spread_reads = try self.allocator.alloc(?SpreadRead, target_fields.len);
        defer self.allocator.free(spread_reads);
        @memset(spread_reads, null);

        for (0..target_fields.len) |index| {
            const field = target_fields[index];
            const value = if (labels.values.get(field.name)) |field_value| blk: {
                const field_kind = try self.graph.recordConstructionFieldKindOf(field);
                const pre = pre_by_expr.get(field_value) orelse
                    Common.invariant("record graph constructor lost its pre-lowered field child");
                // A SUPPLIED OPTIONAL field's child was lowered at the slot's
                // Present payload; wrap it into the tagged slot (design.md
                // "Field Kinds (All-Dynamic Optional Fields)").
                if (field_kind == .optional) {
                    // The slot node is not resolved during expression
                    // lowering, so the construction stays in node space.
                    produced_fields[index] = field;
                    break :blk try self.optionalSlotPresentExprAtNode(field.ty, pre);
                }
                const child_node = try self.exprTypeCell(pre).toGraphNode(self.graph);
                // A producer-authored child can carry a representation
                // distinct from the checked-public field slot. A private
                // codec-authored slot carrying a public opaque handle keeps
                // its private representation in the witness instead.
                const witness = try self.constructorChildWitness(
                    field.ty,
                    child_node,
                    "record graph constructor child differed without explicit representation evidence",
                );
                if (witness.requires_witness) requires_distinct_witness = true;
                produced_fields[index] = .{
                    .name = field.name,
                    .ty = witness.slot,
                    .value_ty = field.value_ty,
                    .kind = field.kind,
                    .default = field.default,
                };
                break :blk pre;
            } else if (base_expr) |base_value| blk: {
                // Record update copies unmentioned slots verbatim—for an
                // optional field that copies the tagged slot, presence state
                // included.
                produced_fields[index] = field;
                const read_cell = DraftTypeCell.fromGraphNode(field.ty);
                const read = try self.addExprWithTypeCell(read_cell, .{ .field_access = .{
                    .receiver = base_value,
                    .segments = try self.draft.addFieldAccessSegmentSpan(&.{.{ .field = field.name }}),
                } });
                const read_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), read_cell, null);
                spread_reads[index] = .{ .local = read_local, .cell = read_cell, .value = read };
                break :blk try self.addExprWithTypeCell(read_cell, .{ .local = read_local });
            } else omitted: {
                produced_fields[index] = field;
                if (self.omittedRecordFieldDefault(checked_expr, field.name)) |default| {
                    const value_node = field.value_ty orelse field.ty;
                    break :omitted (try self.defaultedFieldValueFromDefaultAtCell(
                        default,
                        DraftTypeCell.fromGraphNode(value_node),
                    )) orelse
                        Common.invariant("checker-selected omitted default had no archived default value");
                }
                const field_kind = self.graph.recordOmittedFieldKindOf(field);
                break :omitted switch (field_kind) {
                    .defaulted => |default| blk: {
                        const value_node = field.value_ty orelse field.ty;
                        break :blk (try self.defaultedFieldValueFromMonoDefaultAtCell(
                            default,
                            DraftTypeCell.fromGraphNode(value_node),
                        )) orelse
                            Common.invariant("resolved defaulted field had no archived default value");
                    },
                    .optional => try self.optionalSlotMissingExprAtNode(field.ty),
                    .required => Common.invariant("closed record graph constructor was missing a required field value"),
                };
            };
            lowered[index] = .{ .name = field.name, .value = value };
        }

        const produced_node = if (requires_distinct_witness) blk: {
            const fields = try self.graph.arena().dupe(InstField, produced_fields);
            const structural_node = try self.graph.newNode(.{ .record = .{
                .fields = fields,
                .ext = try self.graph.newNode(.empty_record),
            } });
            const witness = try self.constructorWitnessWithStructuralNode(record_node, structural_node);
            break :blk try self.relateCheckedNodeToProducedValue(record_node, witness);
        } else record_node;
        const field_binds = try self.bindRecordFieldsInSourceOrder(labels.field_names, lowered);
        defer self.allocator.free(field_binds);
        var record_expr = try self.addConstructorExprAtNode(produced_node, .{ .record = try self.addFieldExprSpan(lowered) });
        record_expr = try self.wrapRecordFieldBinds(field_binds, DraftTypeCell.fromGraphNode(produced_node), record_expr);
        var spread_index: usize = target_fields.len;
        while (spread_index > 0) {
            spread_index -= 1;
            const read = spread_reads[spread_index] orelse continue;
            record_expr = try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(produced_node), .{ .let_ = .{
                .bind = try self.addPatWithTypeCell(read.cell, .{ .bind = read.local }),
                .value = read.value,
                .rest = record_expr,
            } });
        }
        if (base_record) |base_value| {
            const local = base_local orelse Common.invariant("record graph update lowered base without a base local");
            return try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(produced_node), .{ .let_ = .{
                .bind = try self.addPatWithTypeCell(base_cell, .{ .bind = local }),
                .value = base_value,
                .rest = record_expr,
            } });
        }
        return record_expr;
    }

    const RecordFieldBind = struct { local: DraftLocalId, cell: DraftTypeCell, value: DraftExprId };

    /// Record field values evaluate in source order, while a record
    /// constructor lists its fields in layout order. Only the supplied
    /// values whose evaluation is observable (`exprEvaluationIsUnobservable`)
    /// have an order to keep. When those values' source order (`source_names`,
    /// the checked record literal's field order) differs from their layout
    /// order in `lowered`, each of them is bound to a local and the
    /// constructor reads that local; the returned bindings are in source
    /// order. Every other value stays in its constructor slot, so a
    /// constructor operand moves into a local only when its evaluation order
    /// would otherwise change. When the orders agree, nothing is bound and
    /// the returned slice is empty.
    fn bindRecordFieldsInSourceOrder(
        self: *BodyContext,
        source_names: []const names.RecordFieldNameId,
        lowered: []DraftFieldExpr,
    ) Allocator.Error![]RecordFieldBind {
        const source_index_of_slot = try self.allocator.alloc(?usize, lowered.len);
        defer self.allocator.free(source_index_of_slot);
        var in_source_order = true;
        var previous: ?usize = null;
        var supplied: usize = 0;
        for (lowered, source_index_of_slot) |field, *source_index| {
            const index = for (source_names, 0..) |name, position| {
                if (name == field.name) break position;
            } else null;
            if (index != null) supplied += 1;
            source_index.* = if (index != null and !(try self.exprEvaluationIsUnobservable(field.value))) index else null;
            const ordered_index = source_index.* orelse continue;
            if (previous) |prev| {
                if (ordered_index < prev) in_source_order = false;
            }
            previous = ordered_index;
        }
        if (supplied != source_names.len) Common.invariant("record constructor did not lay out every supplied field");
        if (in_source_order) return &.{};

        const by_source = try self.allocator.alloc(?RecordFieldBind, source_names.len);
        defer self.allocator.free(by_source);
        @memset(by_source, null);
        var bound: usize = 0;
        for (lowered, source_index_of_slot) |*field, maybe_index| {
            const index = maybe_index orelse continue;
            const cell = self.exprTypeCell(field.value);
            const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), cell, null);
            by_source[index] = .{ .local = local, .cell = cell, .value = field.value };
            field.value = try self.addExprWithTypeCell(cell, .{ .local = local });
            bound += 1;
        }
        const binds = try self.allocator.alloc(RecordFieldBind, bound);
        var next: usize = 0;
        for (by_source) |maybe_bind| {
            const bind = maybe_bind orelse continue;
            binds[next] = bind;
            next += 1;
        }
        return binds;
    }

    /// Whether evaluating `root` can have no observable effect: it reads
    /// locals and builds values from literals and closures, and so cannot
    /// crash, call, print, or diverge. Moving such
    /// an evaluation before or after any other cannot be observed.
    fn exprEvaluationIsUnobservable(self: *BodyContext, root: DraftExprId) Allocator.Error!bool {
        var work: std.ArrayList(DraftExprId) = .empty;
        defer work.deinit(self.allocator);
        try work.append(self.allocator, root);
        while (work.pop()) |expr_id| {
            switch (self.draft.exprs.items[@backingInt(expr_id)].data) {
                .local,
                .unit,
                .int_lit,
                .frac_f32_lit,
                .frac_f64_lit,
                .dec_lit,
                .str_lit,
                .bytes_lit,
                .lambda,
                .fn_def,
                .fn_ref,
                => {},
                .nominal => |backing| try work.append(self.allocator, backing),
                .tag => |tag| try work.appendSlice(self.allocator, self.exprSpan(tag.payloads)),
                .tuple => |items| try work.appendSlice(self.allocator, self.exprSpan(items)),
                .record => |fields| for (self.fieldExprSpan(fields)) |field| {
                    try work.append(self.allocator, field.value);
                },
                .pending_deferred,
                .@"unreachable",
                .def_ref,
                .static_data_candidate,
                .comptime_value,
                .list,
                .record_update,
                .let_,
                .call_value,
                .call_proc,
                .low_level,
                .field_access,
                .tuple_access,
                .structural_eq,
                .structural_hash,
                .match_,
                .if_,
                .uninitialized,
                .uninitialized_payload,
                .if_initialized_payload,
                .try_sequence,
                .try_record_sequence,
                .block,
                .loop_,
                .break_,
                .continue_,
                .join_point,
                .jump,
                .return_,
                .crash,
                .checked_error,
                .comptime_branch_taken,
                .comptime_exhaustiveness_failed,
                .dbg,
                .expect_err,
                .expect,
                .literal_rejected,
                => return false,
            }
        }
        return true;
    }

    /// Bind `binds`' values, first source field outermost, around `body`.
    fn wrapRecordFieldBinds(
        self: *BodyContext,
        binds: []const RecordFieldBind,
        record_cell: DraftTypeCell,
        body: DraftExprId,
    ) Allocator.Error!DraftExprId {
        var result = body;
        var index = binds.len;
        while (index > 0) {
            index -= 1;
            const bind = binds[index];
            result = try self.addExprWithTypeCell(record_cell, .{ .let_ = .{
                .bind = try self.addPatWithTypeCell(bind.cell, .{ .bind = bind.local }),
                .value = bind.value,
                .rest = result,
            } });
        }
        return result;
    }

    fn omittedRecordFieldDefault(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        field_name: names.RecordFieldNameId,
    ) ?checked.CheckedFieldDefault {
        const wanted = self.nameStore().recordFieldLabelText(field_name);
        for (self.view.bodies.record_omitted_defaults) |entry| {
            if (entry.expr != checked_expr) continue;
            if (Ident.textEql(self.view.names.recordFieldLabelText(entry.field_name), wanted)) {
                return entry.default;
            }
        }
        return null;
    }

    fn ensureClosureAtNode(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        closure: anytype,
        request_fn_node: NodeId,
        capture_entry_guards: []const NodeId,
    ) Allocator.Error!DraftFnTarget {
        const lambda = self.view.bodies.expr(closure.lambda);
        if (lambda.data != .lambda) Common.invariant("checked closure did not point at a lambda expression");
        return try self.ensureNestedFnAtNode(expr_id, lambda.ty, request_fn_node, capture_entry_guards);
    }

    /// Lower the nested function at `expr_id`, whose checked function type is
    /// `source_fn_ty`, as a draft function requested at `request_fn_node`.
    fn ensureNestedFnAtNode(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        source_fn_ty: checked.CheckedTypeId,
        request_fn_node: NodeId,
        capture_entry_guards: []const NodeId,
    ) Allocator.Error!DraftFnTarget {
        const nested = try self.builder.nestedFnForExpr(
            self.view,
            self.owner_template,
            expr_id,
            self.current_fn_key,
            try self.localProcContextsDigest(),
            self.in_default_expr,
        );
        const nested_evidence = try self.evidenceForNestedSiteAtNode(nested, expr_id, request_fn_node);
        return try self.builder.lowerDraftNestedFromContext(
            self,
            self.draft.current_owner,
            expr_id,
            nested,
            source_fn_ty,
            self.view.types.rootKey(source_fn_ty),
            request_fn_node,
            capture_entry_guards,
            nested_evidence.chain,
            nested_evidence.owned_scope,
            false,
            .exact_graph,
            .inherit,
        );
    }

    fn lowerClosureCaptureExprSpan(self: *BodyContext, captures: []const checked.CheckedCapture) Allocator.Error!DraftSpan(DraftFnDefCapture) {
        if (captures.len == 0) return DraftSpan(DraftFnDefCapture).empty();

        var capture_values = std.ArrayList(DraftFnDefCapture).empty;
        defer capture_values.deinit(self.allocator);

        for (captures) |capture| {
            const binder = checkedCaptureBinder(self.view, capture.pattern);
            const local = self.binders.get(binder) orelse continue;
            try self.markActiveConstBinderUsed(binder);
            const cell = self.localTypeCell(local);
            try self.constrainCheckedInterfaceToCell(checkedBinderType(self.view, binder), cell);
            const value = try self.addExprWithTypeCell(
                cell,
                .{ .local = local },
            );
            try capture_values.append(self.allocator, .{ .id = capture.capture_id, .value = value });
        }

        return try self.addFnDefCaptureSpan(capture_values.items);
    }

    fn closureFunctionType(self: *BodyContext, closure: anytype) Allocator.Error!Type.TypeId {
        return try self.activeTypeFromNode(try self.closureFunctionNode(closure));
    }

    fn closureFunctionNode(self: *BodyContext, closure: anytype) Allocator.Error!NodeId {
        const lambda = self.view.bodies.expr(closure.lambda);
        if (lambda.data != .lambda) Common.invariant("checked closure did not point at a lambda expression");
        return try self.lambdaFunctionNode(lambda.ty, lambda.data.lambda);
    }

    fn lambdaFunctionType(self: *BodyContext, source_fn_ty: checked.CheckedTypeId, lambda: anytype) Allocator.Error!Type.TypeId {
        return try self.activeTypeFromNode(try self.lambdaFunctionNode(source_fn_ty, lambda));
    }

    fn lambdaFunctionNode(self: *BodyContext, source_fn_ty: checked.CheckedTypeId, lambda: anytype) Allocator.Error!NodeId {
        const fn_node = try self.instNode(source_fn_ty);
        const fn_nodes = try self.graph.functionNodes(fn_node);
        std.debug.assert(fn_nodes.args.len == lambda.args.len);
        for (lambda.args, fn_nodes.args) |pattern_id, arg_node| {
            try self.constrainCheckedInterfaceToCell(
                self.view.bodies.pattern(pattern_id).ty,
                DraftTypeCell.fromGraphNode(arg_node),
            );
        }
        return fn_node;
    }

    /// The type nodes of the captured locals a closure draft enters with.
    fn closureCaptureEntryNodes(self: *BodyContext, closure: @FieldType(checked.CheckedExprData, "closure")) Allocator.Error![]NodeId {
        var capture_nodes = std.ArrayList(NodeId).empty;
        defer capture_nodes.deinit(self.allocator);
        for (closure.captures) |capture| {
            const binder = checkedCaptureBinder(self.view, capture.pattern);
            const local = self.binders.get(binder) orelse continue;
            try self.markActiveConstBinderUsed(binder);
            const cell = self.localTypeCell(local);
            try self.constrainCheckedInterfaceToCell(checkedBinderType(self.view, binder), cell);
            try capture_nodes.append(self.allocator, try cell.toGraphNode(self.graph));
        }
        return try self.graph.arena().dupe(NodeId, capture_nodes.items);
    }

    /// Whether an expression is a lambda or closure, which is drafted at its
    /// request node before evidence that needs the request continues.
    fn isNestedCallableExpr(self: *BodyContext, expr_id: checked.CheckedExprId) bool {
        self.builder.countBodyDiagnostic("nested_callable_checks");
        return switch (self.view.bodies.expr(expr_id).data) {
            .lambda, .closure => true,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => false,
        };
    }

    fn ensureNestedCallableAtNode(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        request_fn_node: NodeId,
    ) Allocator.Error!void {
        switch (self.view.bodies.expr(expr_id).data) {
            .lambda => {
                self.builder.countBodyDiagnostic("nested_lambdas_prepared");
                _ = try self.ensureLambdaAtNode(expr_id, request_fn_node);
            },
            .closure => |closure| {
                self.builder.countBodyDiagnostic("nested_closures_prepared");
                _ = try self.ensureClosureAtNode(expr_id, closure, request_fn_node, try self.closureCaptureEntryNodes(closure));
            },
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
        }
    }

    fn ensureNestedCallablesAtNodes(
        self: *BodyContext,
        expr_ids: []const checked.CheckedExprId,
        request_fn_nodes: []const NodeId,
    ) Allocator.Error!void {
        if (expr_ids.len != request_fn_nodes.len) Common.invariant("nested callable argument count differed from graph function arity");
        for (expr_ids, request_fn_nodes) |expr_id, request_fn_node| {
            if (self.isNestedCallableExpr(expr_id)) try self.ensureNestedCallableAtNode(expr_id, request_fn_node);
        }
    }

    fn ensureLambdaAtNode(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        request_fn_node: NodeId,
    ) Allocator.Error!DraftFnTarget {
        return try self.ensureNestedFnAtNode(expr_id, self.view.bodies.expr(expr_id).ty, request_fn_node, &.{});
    }

    const NestedSiteEvidence = struct {
        chain: EvidenceChain,
        owned_scope: ?checked.DispatchScopeId,
    };

    /// Enter exactly the lexical dispatch scope recorded by checking for a
    /// nested procedure, consuming the producer-authored evidence source for
    /// that construction edge.
    fn evidenceForNestedSiteAtNode(
        self: *BodyContext,
        nested: Ast.NestedFn,
        expr_id: checked.CheckedExprId,
        request_fn_node: NodeId,
    ) Allocator.Error!NestedSiteEvidence {
        const raw_site = @backingInt(nested.site);
        if (raw_site >= self.view.nested_proc_sites.sites.len) {
            Common.invariant("nested function referenced a site absent from the CheckedModule procedure-site table");
        }
        const site = self.view.nested_proc_sites.sites[raw_site];
        const owner_matches = switch (site.owner) {
            .template => |site_owner| !self.in_default_expr and
                names.procedureTemplateRefEql(site_owner, self.owner_template),
            .default_root => self.in_default_expr,
        };
        if (!owner_matches or site.checked_expr == null or site.checked_expr.? != expr_id) {
            Common.invariant("nested function site did not match its checked expression owner");
        }

        const lexical_scope: LexicalDispatchScope = switch (site.lexical_scope) {
            .root => .root,
            .generalized => |scope| .{ .generalized = scope },
        };
        const owned_scope: ?checked.DispatchScopeId = switch (site.lexical_scope) {
            .root => null,
            .generalized => |scope_id| blk: {
                const raw_scope = @backingInt(scope_id);
                if (raw_scope >= self.view.templates.dispatch_scopes.len) {
                    Common.invariant("nested function site referenced an unknown checked dispatch scope");
                }
                break :blk if (self.view.templates.dispatch_scopes[raw_scope].checked_expr == expr_id)
                    scope_id
                else
                    null;
            },
        };
        if (std.meta.eql(self.evidence.scope.lexical, lexical_scope)) {
            return .{
                .chain = self.evidence,
                .owned_scope = owned_scope,
            };
        }

        const scope_id = owned_scope orelse switch (site.lexical_scope) {
            .root => Common.invariant("root nested function site was lowered from a non-root evidence scope"),
            .generalized => Common.invariant("nested function site was lowered outside its checked lexical evidence scope"),
        };
        const raw_scope = @backingInt(scope_id);
        const scope = self.view.templates.dispatch_scopes[raw_scope];
        const params = self.view.templates.evidence_params_pool[scope.evidence_params.start .. scope.evidence_params.start + scope.evidence_params.len];
        const edge = switch (site.evidence_source) {
            .inherited => Common.invariant("nested procedure that owned a dispatch scope declared inherited evidence"),
            .checked_site => blk: {
                const start: usize = site.evidence.start;
                const len: usize = site.evidence.len;
                if (start > self.view.static_dispatch_plans.evidence_refs.len or
                    len > self.view.static_dispatch_plans.evidence_refs.len - start)
                {
                    Common.invariant("nested procedure checked evidence was outside the producer table");
                }
                // The construction instantiates the scope's scheme: its root
                // related to the request binds every quantified variable.
                const scheme_vars = self.view.templates.scopeSchemeVars(&scope);
                var scheme_ctx = try self.nestedInstantiationContext(self.current_fn_key, self.evidence, scheme_vars);
                defer scheme_ctx.deinit();
                const scheme_root_node = try scheme_ctx.instNode(scope.scheme_root);
                try relateFunctionRequestInterface(self.graph, scheme_root_node, request_fn_node);
                const subst = try self.substitutionFromSchemeVars(&scheme_ctx, scheme_vars);
                break :blk EdgeEvidence{
                    .subst = subst,
                    .vector = try self.deriveEvidenceVector(
                        .{ .view = self.view, .root = scope.scheme_root, .scheme_vars = scheme_vars, .params = params, .params_start = scope.evidence_params.start },
                        subst,
                        self.view,
                        self.view.static_dispatch_plans.evidence_refs[start .. start + len],
                        .body_lowering,
                    ),
                };
            },
        };
        return .{
            .chain = try enterEvidenceScope(self.builder, self.evidence, scope_id, expr_id, edge),
            .owned_scope = scope_id,
        };
    }

    /// Whether the checked dispatch plan already names the exact graph-lowered
    /// procedure or local procedure that should receive the call request.
    fn dispatchUsesDirectGraphCallee(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
    ) bool {
        const evidence = switch (plan.resolution) {
            .direct_closed, .direct_parametric => |direct| direct.evidence,
            .direct_pending => Common.invariant("unfinalized direct call reached Monotype"),
            .evidence_dependent, .structural, .@"unreachable", .checked_error => return false,
        };
        const node = self.view.static_dispatch_plans.evidenceNode(evidence);
        return switch (node.target.kind) {
            .procedure => |procedure| procedure.runtime_target == .procedure,
            .local_proc => true,
            .structural => false,
        };
    }

    fn lowerDispatchExprAtType(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        expected_ret_cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        return (try self.runLower(.{ .dispatch = .{ .checked_ret_ty = checked_ret_ty, .maybe_plan = maybe_plan, .expected_ret_cell = expected_ret_cell } })).exprValue();
    }

    const ClosedDispatchOperands = union(enum) {
        args: DraftSpan(DraftExprId),
        uninhabited: DraftExprId,
    };

    fn applyDispatchResultMode(
        self: *BodyContext,
        mode: static_dispatch.StaticDispatchResultMode,
        expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        return switch (mode) {
            .value, .parser_for, .encoder_for, .map, .map_effectful => expr,
            .equality => |eq| if (eq.negated) blk: {
                const result_cell = self.exprTypeCell(expr);
                if (!(try self.typeCellHasBuiltinOwner(result_cell, .bool))) {
                    Common.invariant("checked equality dispatch returned a non-Bool value");
                }
                break :blk try self.addExprWithTypeCell(result_cell, .{ .low_level = .{
                    .op = .bool_not,
                    .args = try self.addExprSpan(&.{expr}),
                } });
            } else expr,
            // A resolved `to_hash` dispatch returns its Hasher result directly.
            .hash => expr,
        };
    }

    fn typeCellHasBuiltinOwner(
        self: *BodyContext,
        cell: DraftTypeCell,
        expected: static_dispatch.BuiltinOwner,
    ) Allocator.Error!bool {
        const owner = switch (cell) {
            .graph_node => |node| (try self.methodOwnerFromNode(node)),
            .sealed => |ty| methodOwnerFromType(self.typeStore(), ty),
        } orelse return false;
        return switch (owner) {
            .builtin => |actual| actual == expected,
            .nominal => false,
        };
    }

    /// A literal whose conversion is selected per specialization: the checked
    /// conversion call at this specialization's target, unwrapped to its value.
    fn lowerSpecializedLiteralConversion(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        value_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const plan = self.literalConversionPlan(expr_id);
        const try_ty = self.literalConversionTryType(plan);
        const try_node = try self.instNode(try_ty);
        const try_value = try self.lowerDispatchExprAtType(try_ty, plan, DraftTypeCell.fromGraphNode(try_node));
        const site = self.literalRejectionSite(expr_id);
        const value = try self.unwrapLiteralConversionAtNode(try_value, try_node, value_node, site);
        if (!self.builder.literal_roots) return value;
        // A conversion reaching a local procedure that needs its declaration
        // context runs where that context exists: in place, at runtime.
        if (self.dispatchPlanSelectsLocalProc(plan)) return value;
        return try self.literalRootRead(expr_id, site, value, value_node);
    }

    /// Whether a dispatch plan's resolution in this body selects a local
    /// procedure, as its target or anywhere in that target's nested evidence.
    fn dispatchPlanSelectsLocalProc(self: *BodyContext, plan_id: ?static_dispatch.StaticDispatchPlanId) bool {
        const id = plan_id orelse return false;
        const plan = self.view.static_dispatch_plans.plans[@backingInt(id)];
        return switch (plan.resolution) {
            .direct_closed => false,
            .direct_parametric => |direct| self.checkedEvidenceNodeSelectsLocalProc(direct.evidence),
            .evidence_dependent => |dependent| if (self.evidence.at(dependent.index)) |entry|
                specEvidenceSelectsLocalProc(selectCallableContract(entry, dependent.callable_contract) orelse entry)
            else
                false,
            .direct_pending, .structural, .checked_error, .@"unreachable" => false,
        };
    }

    fn checkedEvidenceNodeSelectsLocalProc(self: *BodyContext, node_id: static_dispatch.EvidenceNodeId) bool {
        const plans = self.view.static_dispatch_plans;
        const node = plans.evidenceNode(node_id);
        if (node.target.kind == .local_proc) return true;
        const nested = switch (node.nested) {
            .resolved => plans.nestedEvidence(node),
            .from_callable => return false,
        };
        for (nested) |evidence| {
            if (self.checkedEvidenceSelectsLocalProc(evidence)) return true;
        }
        return false;
    }

    fn checkedEvidenceSelectsLocalProc(self: *BodyContext, evidence: static_dispatch.CheckedEvidence) bool {
        const plans = self.view.static_dispatch_plans;
        for (plans.evidence_refs[evidence.callable_contracts.start..][0..evidence.callable_contracts.len]) |contract| {
            if (self.checkedEvidenceSelectsLocalProc(contract)) return true;
        }
        return switch (evidence.resolution) {
            .direct => |child| self.checkedEvidenceNodeSelectsLocalProc(child),
            .constraint => |constraint| if (self.evidence.at(constraint.index)) |entry| specEvidenceSelectsLocalProc(entry) else false,
            .structural, .from_callable, .from_scheme, .checked_error, .unreachable_value => false,
        };
    }

    /// A program whose compile-time roots are evaluated with it evaluates a
    /// specialized literal's conversion at compile time too: the conversion
    /// becomes the body of a literal root, and the specialization reads the
    /// root's completed value.
    fn literalRootRead(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        site: Common.LiteralRejectionSite,
        value: DraftExprId,
        value_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const value_cell = DraftTypeCell.fromGraphNode(value_node);
        const def_id = try self.draft.reserveDef(self.draft.current_owner);
        self.draft.setDef(def_id, .{
            .symbol = self.builder.symbols.fresh(),
            .fn_def = null,
            .fn_id = null,
            .identity_seed = .{ .kind = "literal-root", .extra = literalRootIdentity(self.view.key, expr_id) },
            .args = try self.addTypedLocalSpan(&.{}),
            .body = .{ .roc = value },
            .ret = value_cell,
        });
        const read = try self.draft.addLiteralRoot(def_id, self.view.key, site);
        // The call is representation evidence for the read; the read never
        // runs it.
        const callee = try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(try self.graphFunctionNode(&.{}, value_node)),
            .{ .def_ref = .{ .draft = def_id } },
        );
        const initializer = try self.addExprWithTypeCell(value_cell, .{ .call_value = .{
            .callee = callee,
            .args = try self.addExprSpan(&.{}),
        } });
        return try self.addExprWithTypeCell(value_cell, .{ .comptime_value = .{
            .root = read,
            .initializer = initializer,
        } });
    }

    /// The source literal a rejected conversion of this literal reports.
    fn literalRejectionSite(self: *BodyContext, expr_id: checked.CheckedExprId) Common.LiteralRejectionSite {
        return .{
            .owner = self.builder.loweringModuleId(self.view.key),
            .checked_expr = @backingInt(expr_id),
            .kind = switch (self.view.bodies.expr(expr_id).data) {
                .numeral => .numeral,
                .str_from_quote => .quote,
                .interpolation => .interpolation,
                .pending, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("literal rejection site did not point at a literal conversion expression"),
            },
        };
    }

    /// The checked conversion plan of a literal expression.
    fn literalConversionPlan(self: *BodyContext, expr_id: checked.CheckedExprId) ?static_dispatch.StaticDispatchPlanId {
        return switch (self.view.bodies.expr(expr_id).data) {
            .numeral => |numeral| numeral.plan,
            .str_from_quote => |quote| quote.plan,
            .pending, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("literal conversion did not point at a conversion expression"),
        };
    }

    /// The checked `Try` result type of a literal's conversion call.
    fn literalConversionTryType(self: *BodyContext, plan_id: ?static_dispatch.StaticDispatchPlanId) checked.CheckedTypeId {
        const id = plan_id orelse Common.invariant("checked literal conversion reached Monotype without a dispatch plan");
        const plan = self.view.static_dispatch_plans.plans[@backingInt(id)];
        if (plan.result_mode != .value) Common.invariant("checked literal conversion plan had a non-value result mode");
        return self.checkedFunctionType(plan.callable_ty).ret;
    }

    /// A literal-conversion root evaluates its literal's checked conversion
    /// call and validates it once. Its declared result and shared slot hold
    /// the `Ok` payload; `Err` terminates with the literal's own rejection.
    fn lowerLiteralConversionRootBody(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        ret_cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        const plan = self.literalConversionPlan(expr_id);
        const try_ty = self.literalConversionTryType(plan);
        const try_node = try self.instNode(try_ty);
        const value = try self.lowerDispatchExprAtType(try_ty, plan, DraftTypeCell.fromGraphNode(try_node));
        return try self.unwrapLiteralConversionAtNode(value, try_node, try ret_cell.toGraphNode(self.graph), self.literalRejectionSite(expr_id));
    }

    /// Lower one use of a literal whose conversion checking selected, as that
    /// literal's conversion root. The root evaluates the conversion once at
    /// compile time. A use restores the root's stored value once it is
    /// finalized; during finalization a use reads the root's declared
    /// compile-time value, whose guard reports a rejected conversion as the
    /// root's failure. A lowering that can do neither evaluates the same
    /// checked conversion call.
    fn lowerLiteralConversionAtNode(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        root_id: checked.ComptimeRootId,
        request_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const root = self.view.compile_time_roots.root(root_id);
        const kind = root.literalConversionKind() orelse
            Common.invariant("literal conversion root link named a non-conversion root");
        switch (root.payload) {
            .const_node => |node| return try self.restoreConstNodeAtNode(self.view, self.view, node, request_node),
            .pending => {},
            .fn_value, .discarded, .expect, .runtime => Common.invariant("literal conversion root stored a non-constant payload"),
        }
        if (self.builder.comptimeValueReadDeclared(self.view, root_id)) {
            return try self.declaredComptimeValueRead(self.view, root_id, DraftTypeCell.fromGraphNode(request_node), null);
        }
        const plan = self.literalConversionPlan(expr_id);
        const try_ty = self.literalConversionTryType(plan);
        const try_node = try self.instNode(try_ty);
        const try_value = try self.lowerDispatchExprAtType(try_ty, plan, DraftTypeCell.fromGraphNode(try_node));
        const site = self.literalRejectionSite(expr_id);
        const expected_kind: Common.LiteralRejectionKind = switch (kind) {
            .numeral => .numeral,
            .quote => .quote,
        };
        if (site.kind != expected_kind) Common.invariant("literal conversion root kind differed from its literal");
        const value = try self.unwrapLiteralConversionAtNode(try_value, try_node, request_node, site);
        // A conversion root no evaluation requested (its type holds a
        // callable, so the checker left it specialization-owned) is still
        // hoisted, as a literal root of this program.
        if (!self.builder.literal_roots) return value;
        return try self.literalRootRead(expr_id, site, value, request_node);
    }

    /// The value of a literal conversion's `Try` result: its `Ok` payload, or,
    /// when the conversion rejected the literal, a literal rejection carrying
    /// the conversion's error message.
    fn unwrapLiteralConversionAtNode(
        self: *BodyContext,
        try_value: DraftExprId,
        try_node: NodeId,
        value_node: NodeId,
        site: Common.LiteralRejectionSite,
    ) Allocator.Error!DraftExprId {
        const payloads = try self.graphTryPayloads(try_node);
        try relateRequestComponent(self.graph, payloads.ok, value_node);
        const ok_name = try self.nameStoreMut().internTagLabel("Ok");
        const err_name = try self.nameStoreMut().internTagLabel("Err");
        const try_cell = DraftTypeCell.fromGraphNode(try_node);
        const value_cell = DraftTypeCell.fromGraphNode(value_node);
        const err_cell = DraftTypeCell.fromGraphNode(payloads.err);

        var branches = std.ArrayList(DraftBranch).empty;
        defer branches.deinit(self.allocator);

        const ok_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), value_cell, null);
        try branches.append(self.allocator, .{
            .pat = try self.addPatWithTypeCell(try_cell, .{ .tag = .{
                .name = ok_name,
                .payloads = try self.addPatSpan(&.{try self.addPatWithTypeCell(value_cell, .{ .bind = ok_local })}),
            } }),
            .body = try self.addExprWithTypeCell(value_cell, .{ .local = ok_local }),
        });

        // Every tag of a literal conversion's error row carries its message.
        const error_tags = (try self.graph.tagRowNodes(payloads.err)).tags;
        for (error_tags) |error_tag| {
            if (error_tag.payloads.len != 1) Common.invariant("literal conversion error tag did not carry one message");
            const message_cell = DraftTypeCell.fromGraphNode(error_tag.payloads[0]);
            const message_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), message_cell, null);
            const error_pat = try self.addPatWithTypeCell(err_cell, .{ .tag = .{
                .name = error_tag.name,
                .payloads = try self.addPatSpan(&.{try self.addPatWithTypeCell(message_cell, .{ .bind = message_local })}),
            } });
            try branches.append(self.allocator, .{
                .pat = try self.addPatWithTypeCell(try_cell, .{ .tag = .{
                    .name = err_name,
                    .payloads = try self.addPatSpan(&.{error_pat}),
                } }),
                .body = try self.addExprWithTypeCell(value_cell, .{ .literal_rejected = .{
                    .msg = try self.addExprWithTypeCell(message_cell, .{ .local = message_local }),
                    .site = site,
                } }),
            });
        }
        return try self.addExprWithTypeCell(value_cell, .{ .match_ = .{
            .scrutinee = try_value,
            .branches = try self.addBranchSpan(branches.items),
        } });
    }

    /// Produce a numeric literal's constant—the ONE place in the compiler
    /// that turns a literal's exact digits into a bit pattern, always for
    /// the instantiated Monotype primitive. A custom numeric target keeps its
    /// real user-defined `from_numeral` dispatch call instead.
    fn lowerNumeralExpr(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        numeral: checked.CheckedNumeralData,
        target_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const primitive = switch (self.shapeContent(target_ty)) {
            .primitive => |p| p,
            .named, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return try self.lowerSpecializedLiteralConversion(expr_id, try self.graph.importMono(target_ty)),
        };
        const data = (try self.numeralBits(numeral.literal, primitive)) orelse blk: {
            // A value that does not fit its concrete integer or Dec target (a
            // literal forced to an unrepresentable type after monomorphization;
            // checking reports these, so this is unreachable for error-free
            // programs) matches the generic from_numeral behavior: a runtime
            // crash on the conversion's Err branch.
            const msg = try self.addStringLiteral("invalid numeric literal");
            break :blk BodyExprData{ .crash = msg };
        };
        return try self.addExpr(.{ .ty = target_ty, .data = data });
    }

    /// Specialize a checked quote conversion without guessing its target at
    /// the checked boundary. Primitive Str receives the literal directly;
    /// every custom target follows the explicit from_quote dispatch plan.
    fn lowerQuoteExpr(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        quote: checked.CheckedQuoteData,
        target_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        switch (self.shapeContent(target_ty)) {
            .primitive => |primitive| {
                if (primitive != .str) {
                    // Checking reports this literal-conversion mismatch. Keep
                    // error-path lowering total, matching raw strings and
                    // unrepresentable numerals, so diagnostics can complete.
                    return try self.addExpr(.{
                        .ty = target_ty,
                        .data = .{ .crash = try self.addStringLiteral("invalid string literal") },
                    });
                }
                return try self.lowerQuoteValue(quote.literal, target_ty);
            },
            .named, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return try self.lowerSpecializedLiteralConversion(expr_id, try self.graph.importMono(target_ty)),
        }
    }

    /// A numeric literal's scalar constant at a builtin numeric primitive—
    /// the payload both the expression and pattern lowerers map into their
    /// own IR node flavor.
    const NumeralScalarBits = union(enum) {
        int: can.CIR.IntValue,
        f32: f32,
        f64: f64,
        dec: builtins.dec.RocDec,
    };

    /// The literal's bit pattern at a builtin primitive, from its exact
    /// digits—the ONE place that turns digits into bits: integers by limb
    /// assembly with a fit check, Dec by exact scale shift, floats by
    /// correctly-rounded decimal→binary conversion (total: out-of-range
    /// rounds toward ±inf). Null when an integer or Dec target cannot
    /// represent the exact value; each caller maps null to its own failure
    /// mode (expression: runtime crash node; pattern: never-matching branch).
    /// Checking reports every such literal, so null is unreachable for
    /// error-free programs.
    fn numeralScalarBits(
        self: *BodyContext,
        literal: can.ModuleEnv.NumeralLiteral,
        primitive: Type.Primitive,
    ) Allocator.Error!?NumeralScalarBits {
        const exact = self.view.module_env.exactNumeral(literal);
        return switch (primitive) {
            .u8, .u16, .u32, .u64, .u128, .i8, .i16, .i32, .i64, .i128 => blk: {
                const bits = exact_numeral.intBits(exact, numeralTargetFromPrimitive(primitive)) orelse break :blk null;
                break :blk switch (bits) {
                    .i128 => |value| .{ .int = .{ .bytes = @bitCast(value), .kind = .i128 } },
                    .u128 => |value| .{ .int = .{ .bytes = @bitCast(value), .kind = .u128 } },
                };
            },
            .f32 => .{ .f32 = try exact_numeral.floatBits(f32, self.allocator, exact) },
            .f64 => .{ .f64 = try exact_numeral.floatBits(f64, self.allocator, exact) },
            .dec => blk: {
                const num = (try exact_numeral.decBits(self.allocator, exact)) orelse break :blk null;
                break :blk .{ .dec = .{ .num = num } };
            },
            // A non-numeric target cannot represent any numeral. Checking
            // reports every such literal, so this is reachable only while
            // running a program with reported errors; the caller's failure
            // mapping (crash node / never-matching branch) is the behavior.
            .bool, .str, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2 => null,
        };
    }

    /// A list of checked builtin numerals is already literal data. Preserve
    /// that fact before allocating per-element IR, using the same exact scalar
    /// conversion as ordinary numeral lowering. Custom conversion roots and
    /// dispatch plans remain computations and are not consumed here.
    fn lowerPackedNumeralList(self: *BodyContext, items: []const checked.CheckedExprId, primitive: Type.Primitive) Allocator.Error!?BodyExprData {
        if (items.len == 0) return null;
        const scalar: check.ConstStore.ConstPackedScalar = switch (primitive) {
            .u8 => .u8,
            .u16 => .u16,
            .u32 => .u32,
            .u64 => .u64,
            .u128 => .u128,
            .i8 => .i8,
            .i16 => .i16,
            .i32 => .i32,
            .i64 => .i64,
            .i128 => .i128,
            .f32 => .f32,
            .f64 => .f64,
            .dec => .dec,
            .bool, .str, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2 => return null,
        };
        for (items) |item| {
            const expr = self.view.bodies.expr(item);
            if (expr.data != .numeral) return null;
            if (expr.data.numeral.plan != null or expr.data.numeral.conversion_root != null) return null;
        }

        const width = scalar.byteWidth();
        const bytes = try self.allocator.alloc(u8, items.len * width);
        defer self.allocator.free(bytes);
        for (items, 0..) |item, index| {
            const numeral = self.view.bodies.expr(item).data.numeral;
            const bits = (try self.numeralScalarBits(numeral.literal, primitive)) orelse return null;
            var encoded: [16]u8 = undefined;
            switch (bits) {
                .int => |value| std.mem.writeInt(i128, &encoded, value.toI128(), .little),
                .f32 => |value| std.mem.writeInt(u32, encoded[0..4], @bitCast(value), .little),
                .f64 => |value| std.mem.writeInt(u64, encoded[0..8], @bitCast(value), .little),
                .dec => |value| std.mem.writeInt(i128, &encoded, value.num, .little),
            }
            @memcpy(bytes[index * width ..][0..width], encoded[0..width]);
        }
        return .{ .bytes_lit = .{
            .literal = try self.addStringLiteral(bytes),
            .len = @intCast(items.len),
            .element = scalar,
        } };
    }

    /// The expression flavor of `numeralScalarBits`; null passes through for
    /// the caller's crash-node mapping.
    fn numeralBits(
        self: *BodyContext,
        literal: can.ModuleEnv.NumeralLiteral,
        primitive: Type.Primitive,
    ) Allocator.Error!?BodyExprData {
        const bits = (try self.numeralScalarBits(literal, primitive)) orelse return null;
        return switch (bits) {
            .int => |value| .{ .int_lit = value },
            .f32 => |value| .{ .frac_f32_lit = value },
            .f64 => |value| .{ .frac_f64_lit = value },
            .dec => |value| .{ .dec_lit = value },
        };
    }

    /// Materialize a string literal as the `Str` argument of a `from_quote`
    /// dispatch call.
    /// An interpolation's literal segments, as the `List(Str)` its conversion
    /// receives: the first segment, then each part's following segment.
    fn lowerInterpolationSegments(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        list_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const interpolation = switch (self.view.bodies.expr(expr_id).data) {
            .interpolation => |value| value,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("interpolation segments operand referenced a non-interpolation expression"),
        };
        const str_ty = switch (self.shapeContent(list_ty)) {
            .list => |elem| elem,
            .primitive, .named, .record, .tuple, .tag_union, .box, .func, .erased, .zst => Common.invariant("interpolation segments operand had a non-list monotype"),
        };
        const segments = try self.allocator.alloc(DraftExprId, interpolation.segments.len);
        defer self.allocator.free(segments);
        for (interpolation.segments, segments) |checked_segment, *segment| {
            segment.* = try self.lowerInterpolationSegment(checked_segment, str_ty);
        }
        return try self.addExpr(.{ .ty = list_ty, .data = .{ .list = try self.addExprSpan(segments) } });
    }

    fn lowerInterpolationSegment(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        str_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return switch (self.view.bodies.expr(expr_id).data) {
            .str_segment => |literal| try self.lowerQuoteValue(literal, str_ty),
            .pending, .numeral, .str_from_quote, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("interpolation segment was not a checked string segment"),
        };
    }

    fn lowerQuoteValue(
        self: *BodyContext,
        literal: checked.CheckedStringLiteralId,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .str_lit = try self.lowerStringLiteral(literal) },
        });
    }

    fn lowerNumeralValue(
        self: *BodyContext,
        literal: can.ModuleEnv.NumeralLiteral,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const backing_ty = self.namedBackingType(ty) orelse
            Common.invariant("checked from_numeral argument was not the Numeral nominal type");
        const literal_tag = self.monoTagByText(backing_ty, "Literal");
        const payloads = self.typeStore().span(literal_tag.payloads);
        if (payloads.len != 1) Common.invariant("Numeral Literal tag must have one record payload");

        const record_expr = try self.lowerNumeralRecord(literal, GuardedList.at(payloads, 0));
        const backing_expr = try self.addExpr(.{
            .ty = backing_ty,
            .data = .{ .tag = .{
                .name = literal_tag.name,
                .payloads = try self.addExprSpan(&[_]DraftExprId{record_expr}),
            } },
        });
        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .nominal = backing_expr },
        });
    }

    fn lowerNumeralRecord(
        self: *BodyContext,
        literal: can.ModuleEnv.NumeralLiteral,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        if (!literal.isMaterialized()) {
            Common.invariant("checked from_numeral argument literal was not materialized");
        }
        const field_span = switch (self.shapeContent(ty)) {
            .record => |span| span,
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("Numeral Literal payload was not a record"),
        };
        const field_count: usize = @intCast(field_span.len);
        const lowered = try self.allocator.alloc(DraftFieldExpr, field_count);
        defer self.allocator.free(lowered);
        const fields = try GuardedList.dupe(self.allocator, Type.Field, self.typeStore().fieldSpan(field_span));
        defer self.allocator.free(fields);

        const before = self.view.module_env.numeralDigitsBefore(literal);
        const after = self.view.module_env.numeralDigitsAfter(literal);
        for (0..field_count) |i| {
            const field = fields[i];
            const label = self.nameStore().recordFieldLabelText(field.name);
            const value = if (Ident.textEql(label, "is_negative"))
                try self.boolLiteral(literal.isNegative(), field.ty)
            else if (Ident.textEql(label, "digits_before_pt"))
                try self.lowerU8List(before, field.ty)
            else if (Ident.textEql(label, "digits_after_pt"))
                try self.lowerU8List(after, field.ty)
            else if (Ident.textEql(label, "digits_after_pt_count"))
                try self.intLiteralExpr(literal.after_decimal_digit_count, field.ty)
            else
                Common.invariant("Numeral record contained an unexpected field");
            lowered[i] = .{ .name = field.name, .value = value };
        }

        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .record = try self.addFieldExprSpan(lowered) },
        });
    }

    fn lowerU8List(
        self: *BodyContext,
        values: []const u8,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const elem_ty = switch (self.shapeContent(ty)) {
            .list => |elem| elem,
            .primitive, .named, .record, .tuple, .tag_union, .box, .func, .erased, .zst => Common.invariant("Numeral digit field was not a List(U8)"),
        };
        const items = try self.allocator.alloc(DraftExprId, values.len);
        defer self.allocator.free(items);
        for (values, 0..) |value, i| {
            items[i] = try self.intLiteralExpr(value, elem_ty);
        }
        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .list = try self.addExprSpan(items) },
        });
    }

    fn monoTagByText(self: *BodyContext, ty: Type.TypeId, text: []const u8) Type.Tag {
        return self.monoTagByTextOptional(ty, text) orelse Common.invariant("expected tag was absent from monotype tag union");
    }

    fn monoTagByName(self: *BodyContext, ty: Type.TypeId, name: names.TagNameId) Type.Tag {
        const tags = switch (self.shapeContent(ty)) {
            .tag_union => |span| self.typeStore().tagSpan(span),
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => Common.invariant("expected tag belonged to a non-union monotype type"),
        };
        for (0..GuardedList.borrowLen(tags)) |index| {
            const tag = GuardedList.at(tags, index);
            if (tag.name == name) return tag;
        }
        Common.invariant("expected tag id was absent from monotype tag union");
    }

    fn monoTagByTextOptional(self: *BodyContext, ty: Type.TypeId, text: []const u8) ?Type.Tag {
        return switch (self.shapeContent(ty)) {
            .tag_union => |span| {
                const tags = self.typeStore().tagSpan(span);
                for (0..GuardedList.borrowLen(tags)) |index| {
                    const tag = GuardedList.at(tags, index);
                    if (Ident.textEql(self.nameStore().tagLabelText(tag.name), text)) return tag;
                }
                return null;
            },
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => null,
        };
    }

    /// Forwards to the scope that owns the type store; the query itself
    /// has one implementation.
    fn typeHasBuiltinOwner(self: *BodyContext, ty: Type.TypeId, owner: static_dispatch.BuiltinOwner) bool {
        return switch (methodOwnerFromType(self.typeStore(), ty) orelse return false) {
            .builtin => |actual| actual == owner,
            .nominal => false,
        };
    }

    fn setPayloadType(self: *BodyContext, ty: Type.TypeId) ?Type.TypeId {
        if (!self.typeHasBuiltinOwner(ty, .set)) return null;
        const named = switch (self.typeStore().get(ty)) {
            .named => |named| named,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("builtin Set type was not a named monotype"),
        };
        const args = self.typeStore().span(named.args);
        if (args.len != 1) Common.invariant("builtin Set type had an unexpected arity");
        return GuardedList.at(args, 0);
    }

    const DictEntryShape = struct {
        key_ty: Type.TypeId,
        value_ty: Type.TypeId,
    };

    fn dictEntryShape(self: *BodyContext, ty: Type.TypeId) ?DictEntryShape {
        if (!self.typeHasBuiltinOwner(ty, .dict)) return null;
        const named = switch (self.typeStore().get(ty)) {
            .named => |named| named,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("builtin Dict type was not a named monotype"),
        };
        const args = self.typeStore().span(named.args);
        if (args.len != 2) Common.invariant("builtin Dict type had an unexpected arity");
        return .{ .key_ty = GuardedList.at(args, 0), .value_ty = GuardedList.at(args, 1) };
    }

    fn listType(self: *BodyContext, elem_ty: Type.TypeId) Allocator.Error!Type.TypeId {
        return try self.typeStore().add(.{ .list = elem_ty });
    }

    fn tupleType(self: *BodyContext, item_tys: []const Type.TypeId) Allocator.Error!Type.TypeId {
        return try self.typeStore().add(.{
            .tuple = try self.typeStore().addSpan(item_tys),
        });
    }

    fn recordType(self: *BodyContext, fields: []const Type.Field) Allocator.Error!Type.TypeId {
        return try self.typeStore().add(.{
            .record = try self.typeStore().addRecordFields(self.nameStore(), fields),
        });
    }

    fn tagUnionType(self: *BodyContext, inputs: []const Type.Store.TagInput) Allocator.Error!Type.TypeId {
        const tags = try self.allocator.alloc(Type.Tag, inputs.len);
        defer self.allocator.free(tags);
        for (inputs, tags) |input, *tag| {
            tag.* = .{
                .name = input.name,
                .checked_name = input.checked_name,
                .payloads = try self.typeStore().addSpan(input.payloads),
            };
        }
        return try self.typeStore().add(.{
            .tag_union = try self.typeStore().addTagVariants(self.nameStore(), tags),
        });
    }

    /// Call the frozen format method `method` of the builtin container shape
    /// `owner_ty` with one argument of type `arg_ty`, producing `ret_ty`.
    fn lowerUnaryContainerMethodCall(
        self: *BodyContext,
        kind: CodecKind,
        comptime method: []const u8,
        comptime label: []const u8,
        comptime arg_description: []const u8,
        comptime ret_description: []const u8,
        owner_ty: Type.TypeId,
        arg_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        arg_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const prepared = try self.frozenFormatCodecCallForShape(kind, method, owner_ty);
        const lookup = prepared.lookup;
        const callable_mono_ty = prepared.callable_ty;
        const method_fn = self.functionShape(callable_mono_ty, label ++ " target method was not a function");
        const arg_tys = self.typeStore().span(method_fn.args);
        if (arg_tys.len != 1) Common.invariant(label ++ " target method had an unexpected arity");
        if (!self.sameType(GuardedList.at(arg_tys, 0), arg_ty)) Common.invariant(label ++ " argument type differed from " ++ arg_description);
        if (!self.sameType(method_fn.ret, ret_ty)) Common.invariant(label ++ " return type differed from " ++ ret_description);

        return try self.addExpr(.{
            .ty = ret_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(prepared.callee),
                .args = try self.addExprSpan(&[_]DraftExprId{arg_expr}),
                .captures = try self.methodTargetCaptureSpan(lookup),
            } },
        });
    }

    fn lowerSetFromList(
        self: *BodyContext,
        set_ty: Type.TypeId,
        list_ty: Type.TypeId,
        list_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        return try self.lowerUnaryContainerMethodCall(.parser, "from_list", "Set.from_list", "generated List type", "Set type", set_ty, list_ty, set_ty, list_expr);
    }

    fn lowerSetToList(
        self: *BodyContext,
        set_ty: Type.TypeId,
        list_ty: Type.TypeId,
        set_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        return try self.lowerUnaryContainerMethodCall(.encoder, "to_list", "Set.to_list", "Set type", "generated List type", set_ty, set_ty, list_ty, set_expr);
    }

    fn lowerDictWithCapacity(
        self: *BodyContext,
        dict_ty: Type.TypeId,
        capacity_expr: DraftExprId,
        capacity_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.lowerUnaryContainerMethodCall(.parser, "with_capacity", "Dict.with_capacity", "generated capacity type", "Dict type", dict_ty, capacity_ty, dict_ty, capacity_expr);
    }

    fn lowerDictInsert(
        self: *BodyContext,
        dict_ty: Type.TypeId,
        key_ty: Type.TypeId,
        value_ty: Type.TypeId,
        dict_expr: DraftExprId,
        key_expr: DraftExprId,
        value_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const prepared = try self.frozenFormatCodecCallForShape(.parser, "insert", dict_ty);
        const lookup = prepared.lookup;
        const callable_mono_ty = prepared.callable_ty;
        const insert_fn = self.functionShape(callable_mono_ty, "Dict.insert target method was not a function");
        const arg_tys = self.typeStore().span(insert_fn.args);
        if (arg_tys.len != 3) Common.invariant("Dict.insert target method had an unexpected arity");
        if (!self.sameType(GuardedList.at(arg_tys, 0), dict_ty)) Common.invariant("Dict.insert dict argument type differed from Dict type");
        if (!self.sameType(GuardedList.at(arg_tys, 1), key_ty)) Common.invariant("Dict.insert key argument type differed from key type");
        if (!self.sameType(GuardedList.at(arg_tys, 2), value_ty)) Common.invariant("Dict.insert value argument type differed from value type");
        if (!self.sameType(insert_fn.ret, dict_ty)) Common.invariant("Dict.insert return type differed from Dict type");

        return try self.addExpr(.{
            .ty = dict_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(prepared.callee),
                .args = try self.addExprSpan(&[_]DraftExprId{ dict_expr, key_expr, value_expr }),
                .captures = try self.methodTargetCaptureSpan(lookup),
            } },
        });
    }

    fn lowerDictToList(
        self: *BodyContext,
        dict_ty: Type.TypeId,
        list_ty: Type.TypeId,
        dict_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        return try self.lowerUnaryContainerMethodCall(.encoder, "to_list", "Dict.to_list", "Dict type", "generated List type", dict_ty, dict_ty, list_ty, dict_expr);
    }

    /// The format method (`prefix` plus the scalar's name) that reads or
    /// writes a builtin scalar type, or null when the type is not one.
    fn scalarCodecMethodName(self: *BodyContext, ty: Type.TypeId, comptime prefix: []const u8) ?[]const u8 {
        if (self.typeHasBuiltinOwner(ty, .bool)) return prefix ++ "bool";
        if (self.typeHasBuiltinOwner(ty, .str)) return prefix ++ "str";
        if (self.typeHasBuiltinOwner(ty, .u8)) return prefix ++ "u8";
        if (self.typeHasBuiltinOwner(ty, .i8)) return prefix ++ "i8";
        if (self.typeHasBuiltinOwner(ty, .u16)) return prefix ++ "u16";
        if (self.typeHasBuiltinOwner(ty, .i16)) return prefix ++ "i16";
        if (self.typeHasBuiltinOwner(ty, .u32)) return prefix ++ "u32";
        if (self.typeHasBuiltinOwner(ty, .i32)) return prefix ++ "i32";
        if (self.typeHasBuiltinOwner(ty, .u64)) return prefix ++ "u64";
        if (self.typeHasBuiltinOwner(ty, .i64)) return prefix ++ "i64";
        if (self.typeHasBuiltinOwner(ty, .u128)) return prefix ++ "u128";
        if (self.typeHasBuiltinOwner(ty, .i128)) return prefix ++ "i128";
        if (self.typeHasBuiltinOwner(ty, .dec)) return prefix ++ "dec";
        if (self.typeHasBuiltinOwner(ty, .f32)) return prefix ++ "f32";
        if (self.typeHasBuiltinOwner(ty, .f64)) return prefix ++ "f64";
        return null;
    }

    /// The shapes a derived codec reads out of a dict: always its value, plus
    /// its key when the key needs its own codec rather than the key-string
    /// methods. Every walk over a dict's codec-reachable shapes goes through
    /// here so the rule lives in one place.
    fn dictCodecShapes(self: *BodyContext, dict: DictEntryShape, buf: *[2]Type.TypeId) []const Type.TypeId {
        buf[0] = dict.value_ty;
        if (self.dictKeyIsStringRendered(dict.key_ty)) return buf[0..1];
        buf[1] = dict.key_ty;
        return buf[0..2];
    }

    /// Whether a dict key renders as a key string, which is what the
    /// `parse_key_*`/`encode_key_*` methods read and write. Any other key is
    /// read by its own codec behind `parse_key_start`/`encode_key_start`.
    fn dictKeyIsStringRendered(self: *BodyContext, ty: Type.TypeId) bool {
        return self.scalarCodecMethodName(ty, "parse_key_") != null or self.dictKeyUnitTags(ty) != null;
    }

    fn dictKeyUnitTags(self: *BodyContext, ty: Type.TypeId) ?Type.Span {
        switch (self.typeStore().get(ty)) {
            .named => |named| if (named.kind != .alias) return null,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => {},
        }
        const tags_span = switch (self.shapeContent(ty)) {
            .tag_union => |span| span,
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => return null,
        };
        const tags = self.typeStore().tagSpan(tags_span);
        if (tags.len == 0) return null;
        for (0..GuardedList.borrowLen(tags)) |index| {
            const tag = GuardedList.at(tags, index);
            if (self.typeStore().span(tag.payloads).len != 0) return null;
        }
        return tags_span;
    }

    fn dispatchResultMonoType(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        expected_ret_ty: ?Type.TypeId,
    ) Allocator.Error!?Type.TypeId {
        const ret_node = try self.dispatchResultTypeNode(checked_ret_ty, maybe_plan, expected_ret_ty);
        if (expected_ret_ty) |expected| return expected;
        return try self.activeTypeFromNode(ret_node);
    }

    fn dispatchResultTypeNode(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        expected_ret_ty: ?Type.TypeId,
    ) Allocator.Error!NodeId {
        return try self.dispatchResultTypeNodeInPhase(
            checked_ret_ty,
            maybe_plan,
            if (expected_ret_ty) |expected| try self.activeNodeFromType(expected) else null,
            .expression_lowering,
        );
    }

    fn interpolationResultTypeNode(
        self: *BodyContext,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        expected_ret_node: ?NodeId,
    ) Allocator.Error!NodeId {
        return (try self.runEvidence(.{ .interpolation_result = .{ .maybe_plan = maybe_plan, .expected_ret_node = expected_ret_node } })).nodeValue();
    }

    fn dispatchResultTypeNodeInPhase(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        expected_ret_node: ?NodeId,
        phase: DispatchInstantiationPhase,
    ) Allocator.Error!NodeId {
        return (try self.runEvidence(.{ .dispatch_result = .{ .checked_ret_ty = checked_ret_ty, .maybe_plan = maybe_plan, .expected_ret_node = expected_ret_node, .phase = phase } })).nodeValue();
    }

    /// Consume a CheckedModule-proved closed direct call without constructing a
    /// dispatch graph. The producer's runtime category is authoritative:
    /// exact low-level operations and ordinary procedures with ordinary result
    /// types have a sealed checked callable interface. Ordinary procedures
    /// returning a public iterator may complete private result evidence in
    /// their bodies, so those continue through the relation path below along
    /// with graph-participating and parametric/local/evidence-dependent calls.
    fn closedDirectGraphFreeResultNode(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        plan: static_dispatch.StaticDispatchCallPlan,
        expected_ret_node: ?NodeId,
    ) Allocator.Error!?NodeId {
        const ret_ty = (try self.closedDirectGraphFreeResultType(checked_ret_ty, plan)) orelse return null;
        const ret_node = try self.activeNodeFromType(ret_ty);
        if (expected_ret_node) |expected| {
            try relateRequestComponent(self.graph, ret_node, expected);
        }
        return ret_node;
    }

    /// Return the sealed result type stored in a closed direct call's
    /// producer-authored callable type. No specialization graph node is
    /// created here.
    fn closedDirectGraphFreeResultType(
        self: *BodyContext,
        _: checked.CheckedTypeId,
        plan: static_dispatch.StaticDispatchCallPlan,
    ) Allocator.Error!?Type.TypeId {
        const direct = switch (plan.resolution) {
            .direct_closed => |direct| direct,
            .direct_pending,
            .direct_parametric,
            .evidence_dependent,
            .structural,
            .checked_error,
            .@"unreachable",
            => return null,
        };
        const evidence = self.view.static_dispatch_plans.evidenceNode(direct.evidence);
        const procedure = switch (evidence.target.kind) {
            .procedure => |procedure| procedure,
            .local_proc, .structural => return null,
        };
        const runtime_target = procedure.runtime_target;
        switch (runtime_target) {
            .intrinsic, .graph_participating => return null,
            .procedure, .low_level => {},
        }

        const callable_ty = try self.lowerType(plan.callable_ty);
        const function = self.functionShape(
            callable_ty,
            "checked closed direct call had a non-function callable type",
        );
        return switch (runtime_target) {
            .low_level => function.ret,
            .procedure => if (try self.typeStore().containsIteratorInterface(function.ret))
                null
            else
                function.ret,
            .intrinsic, .graph_participating => unreachable,
        };
    }

    fn graphFreeResultTypeForExpr(self: *BodyContext, expr_id: checked.CheckedExprId) Allocator.Error!?Type.TypeId {
        // A restored hoisted const never performs its checked dispatch, so
        // that dispatch's graph-free classification does not describe the
        // restored value's type cell.
        if (self.restoredHoistedConstEntry(expr_id) != null) return null;
        const expr = self.view.bodies.expr(expr_id);
        const plan_id = switch (expr.data) {
            .dispatch_call => |plan| plan,
            .type_dispatch_call, .method_eq => |plan| plan,
            // An interpolation's value is its conversion result's `Ok` payload.
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .interpolation, .structural_eq, .structural_hash, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => return null,
        } orelse return null;
        const plan = self.view.static_dispatch_plans.plans[@backingInt(plan_id)];
        return try self.closedDirectGraphFreeResultType(expr.ty, plan);
    }

    fn callableDispatchResultTypeNodeInPhase(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        callable_plan: CallableDispatchPlan,
        expected_ret_node: ?NodeId,
        phase: DispatchInstantiationPhase,
    ) Allocator.Error!NodeId {
        return (try self.runEvidence(.{ .callable_dispatch_result = .{ .checked_ret_ty = checked_ret_ty, .maybe_plan = null, .callable_plan = callable_plan, .expected_ret_node = expected_ret_node, .phase = phase } })).nodeValue();
    }

    fn materializeConstFnEvidence(self: *BodyContext, fn_value: check.ConstStore.ConstFn) Allocator.Error!EvidenceChain {
        const frames = fn_value.evidence_frames;
        const head = fn_value.evidence_frame_head orelse
            Common.invariant("stored function evidence did not declare a head frame");
        if (frames.len == 0 or head != frames.len - 1) {
            Common.invariant("stored function evidence head did not name its final frame");
        }
        const owner = ownerTemplateForConstFnDef(fn_value.fn_def);
        const owner_view = self.builder.moduleForDigest(names.procTemplateModuleDigest(owner));
        var cursor: usize = 0;
        const arena = self.builder.evidence_arena.allocator();
        const restored = try arena.alloc(EvidenceChain, frames.len);
        for (frames, 0..) |frame, index| {
            if (frame.roots_start != cursor) {
                Common.invariant("stored function evidence frame roots were not contiguous");
            }
            const vector = try self.materializeConstFnEvidenceVector(fn_value.evidence, &cursor, frame.roots_len);
            const scope: LexicalDispatchScope = switch (frame.scope()) {
                .root => .root,
                .generalized => |scope_id| .{ .generalized = @fromBackingInt(@intCast(scope_id)) },
            };
            if (index == 0) {
                if (scope != .root or frame.parent != null) {
                    Common.invariant("stored function evidence did not begin at the checked root scope");
                }
                restored[index] = rootEvidence(owner, vector);
                restored[index].origin = .stored_function;
                continue;
            }
            if (scope == .root or frame.parent == null or frame.parent.? != index - 1) {
                Common.invariant("stored function evidence frame did not name its immediate lexical parent");
            }
            const scope_id = scope.generalized;
            const raw_scope = @backingInt(scope_id);
            if (raw_scope >= owner_view.templates.dispatch_scopes.len) {
                Common.invariant("stored function evidence referenced an unknown checked scope");
            }
            const scope_record = owner_view.templates.dispatch_scopes[raw_scope];
            const expected_parent: LexicalDispatchScope = if (scope_record.parent) |parent|
                .{ .generalized = parent }
            else
                .root;
            if (!std.meta.eql(restored[index - 1].scope.lexical, expected_parent)) {
                Common.invariant("stored function evidence parent differed from the checked lexical scope");
            }
            restored[index] = .{
                .scope = .{ .owner = owner, .lexical = scope },
                .origin = .stored_function,
                .vector = vector,
                .parent = &restored[index - 1],
            };
        }
        if (cursor != fn_value.evidence.len) {
            Common.invariant("stored function evidence contained unreferenced nodes");
        }
        const expected_head: LexicalDispatchScope = switch (fn_value.fn_def) {
            .nested => |nested| blk: {
                // A default-root-qualified stored function's site lives in
                // the DECLARING module (resolved by content identity); the
                // evidence frames themselves stay validated against the
                // recording owner template's module above, exactly as they
                // were captured during materialization (design.md "Defaulted
                // Fields"—const-store restore is the second sanctioned
                // resolver of default-root sites).
                const site_view = if (nested.default_root != null)
                    self.builder.moduleForConstFnDef(fn_value.fn_def)
                else
                    owner_view;
                const raw_site = @backingInt(nested.site);
                if (raw_site >= site_view.nested_proc_sites.sites.len) {
                    Common.invariant("stored nested function referenced an unknown checked site");
                }
                const site = site_view.nested_proc_sites.sites[raw_site];
                switch (site.owner) {
                    .template => |site_owner| {
                        if (nested.default_root != null) {
                            Common.invariant("stored default-root function referenced a template-owned checked site");
                        }
                        if (!names.procedureTemplateRefEql(site_owner, owner)) {
                            Common.invariant("stored nested function site belonged to a different checked template");
                        }
                    },
                    .default_root => if (nested.default_root == null) {
                        Common.invariant("stored nested function referenced a default-root checked site without a default-root qualifier");
                    },
                }
                break :blk switch (site.lexical_scope) {
                    .root => .root,
                    .generalized => |scope_id| .{ .generalized = scope_id },
                };
            },
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => .root,
        };
        if (!std.meta.eql(restored[head].scope.lexical, expected_head)) {
            Common.invariant("stored function evidence head differed from its checked nested site scope");
        }
        return restored[head];
    }

    fn instantiateStoredEvidence(self: *BodyContext, evidence: EvidenceChain) Allocator.Error!EvidenceChain {
        var count: usize = 0;
        var current: ?*const EvidenceChain = &evidence;
        while (current) |frame| : (current = frame.parent) count += 1;
        const frames = try self.builder.evidence_arena.allocator().alloc(EvidenceChain, count);
        var index = count;
        current = &evidence;
        while (current) |frame| : (current = frame.parent) {
            index -= 1;
            frames[index] = frame.*;
        }
        for (frames, 0..) |*frame, i| {
            const view = self.builder.moduleForDigest(names.procTemplateModuleDigest(frame.scope.owner));
            frame.* = try self.restoreEvidenceFrame(view, frame.scope.owner, frame.scope.lexical, frame.vector, if (i == 0) null else &frames[i - 1]);
        }
        return frames[count - 1];
    }

    /// Stored functions have graph-free evidence. Recreate its lexical
    /// substitution in the restoration context, where saved callable and
    /// capture interfaces will constrain the same checked identities. Every
    /// retained method contract also constrains the variables reached through
    /// its signature, even when its receiver is reachable from the callable.
    fn restoreEvidenceFrame(
        self: *BodyContext,
        view: ModuleView,
        owner: names.ProcTemplate,
        scope: LexicalDispatchScope,
        vector: []const SpecEvidence,
        parent: ?*const EvidenceChain,
    ) Allocator.Error!EvidenceChain {
        const schema = switch (scope) {
            .root => self.templateSchema(owner),
            .generalized => |id| self.scopeSchema(view, id),
        };
        const subst = try self.substitutionFromCheckedTypes(view, schema.scheme_vars);
        var ctx: ?BodyContext = null;
        defer if (ctx) |*context| context.deinit();
        for (schema.params, vector) |param, entry| {
            switch (entry) {
                .target => |target| {
                    if (ctx == null) {
                        ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, view, self.method_scope, owner, self.graph, self.draft);
                        try ctx.?.seedSubstitution(schema, subst);
                    }
                    try self.relateTargetToConstraint(target, &ctx.?, param);
                },
                .structural => |structural| if (structural.checked) |checked_structural| {
                    if (ctx == null) {
                        ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, view, self.method_scope, owner, self.graph, self.draft);
                        try ctx.?.seedSubstitution(schema, subst);
                    }
                    try self.relateStructuralEvidenceToConstraint(checked_structural, &ctx.?, param);
                },
                .from_callable, .from_scheme, .unreachable_value, .checked_error => {},
            }
        }
        return .{ .scope = .{ .owner = owner, .lexical = scope }, .schema = schema, .subst = subst, .vector = vector, .parent = parent };
    }

    /// A stored evidence vector being restored; `pending` holds the entry
    /// whose nested vector or callable contracts are restoring above it.
    const StoredEvidenceFrame = struct {
        out: []SpecEvidence,
        next: usize = 0,
        pending: ?union(enum) {
            nested: struct {
                materialized: *SpecEvidenceTarget,
                stored: @FieldType(check.ConstStore.ConstFnEvidence, "target"),
                nested_start: usize,
                subtree_len: usize,
            },
            /// The entry's own target, when it is one: the entry holds it
            /// by const pointer.
            contracts: ?*SpecEvidenceTarget,
        } = null,
    };

    /// Restore a pre-order evidence tree: each entry's node, its nested
    /// evidence, then its callable contracts. Nested evidence follows type
    /// nesting, so each nested vector is a frame rather than a native call.
    fn materializeConstFnEvidenceVector(
        self: *BodyContext,
        nodes: []const check.ConstStore.ConstFnEvidence,
        cursor: *usize,
        count: u32,
    ) Allocator.Error![]const SpecEvidence {
        const arena = self.builder.evidence_arena.allocator();
        var frames = std.ArrayList(StoredEvidenceFrame).empty;
        defer frames.deinit(self.allocator);
        try frames.append(self.allocator, .{ .out = try arena.alloc(SpecEvidence, count) });
        while (true) {
            const frame = &frames.items[frames.items.len - 1];
            if (frame.next == frame.out.len) {
                const finished = frames.pop().?;
                if (frames.items.len == 0) return finished.out;
                const parent = &frames.items[frames.items.len - 1];
                const pending = parent.pending.?;
                parent.pending = null;
                switch (pending) {
                    .nested => |nested| {
                        if (cursor.* - nested.nested_start != nested.subtree_len) {
                            Common.invariant("stored function nested evidence length differed from its subtree");
                        }
                        try self.finishStoredEvidenceTarget(nested.materialized, nested.stored, .{ .resolved = finished.out });
                        parent.out[parent.next] = .{ .target = nested.materialized };
                        if (nested.stored.callable_contracts != 0) {
                            parent.pending = .{ .contracts = nested.materialized };
                            try frames.append(self.allocator, .{ .out = try arena.alloc(SpecEvidence, nested.stored.callable_contracts) });
                            continue;
                        }
                    },
                    .contracts => |target| setSpecEvidenceCallableContracts(&parent.out[parent.next], target, finished.out),
                }
                parent.next += 1;
                continue;
            }
            if (cursor.* >= nodes.len) Common.invariant("stored function evidence ended before its declared vector length");
            const stored = nodes[cursor.*];
            cursor.* += 1;
            var contracts_target: ?*SpecEvidenceTarget = null;
            frame.out[frame.next] = switch (stored) {
                .target => |target| blk: {
                    const materialized = try arena.create(SpecEvidenceTarget);
                    switch (target.nested) {
                        .resolved => |resolved| {
                            frame.pending = .{ .nested = .{
                                .materialized = materialized,
                                .stored = target,
                                .nested_start = cursor.*,
                                .subtree_len = resolved.subtree_len,
                            } };
                            try frames.append(self.allocator, .{ .out = try arena.alloc(SpecEvidence, resolved.count) });
                            continue;
                        },
                        .from_callable => {
                            try self.finishStoredEvidenceTarget(materialized, target, .synthesize);
                            contracts_target = materialized;
                            break :blk .{ .target = materialized };
                        },
                    }
                },
                .structural => |stored_structural| blk: {
                    const restored_checked: ?CheckedSpecStructuralEvidence = if (stored_structural.checked) |stored_checked| restored: {
                        const view = self.builder.moduleForDigest(stored_checked.view);
                        if (!std.meta.eql(view.types.rootKey(stored_checked.dispatcher_ty), stored_checked.dispatcher_key) or
                            !std.meta.eql(view.types.rootKey(stored_checked.callable_ty), stored_checked.callable_key))
                        {
                            Common.invariant("stored structural evidence checked type identity changed during restoration");
                        }
                        const identity = if (stored_checked.generated_codec_derivation) |id|
                            view.static_dispatch_plans.generated_codec_derivations[@backingInt(id)].identity
                        else
                            null;
                        if (identity != stored_checked.generated_codec_identity)
                            Common.invariant("stored codec proof identity changed during restoration");
                        break :restored .{
                            .view = view,
                            .evidence = static_dispatch.StructuralEvidence{
                                .derivation = stored_structural.derivation,
                                .dispatcher_ty = stored_checked.dispatcher_ty,
                                .callable_ty = stored_checked.callable_ty,
                                .generated_codec_derivation = stored_checked.generated_codec_derivation,
                            },
                        };
                    } else null;
                    break :blk .{ .structural = .{
                        .derivation = stored_structural.derivation,
                        .checked = restored_checked,
                    } };
                },
                .from_callable => |use| .{ .from_callable = .{
                    .independent_callable = use.independent_callable,
                } },
                .from_scheme => |index| .{ .from_scheme = index },
                .unreachable_value => .unreachable_value,
                .checked_error => .checked_error,
            };
            const contract_count: u32 = switch (stored) {
                .target => |target| target.callable_contracts,
                .structural => |stored_structural| stored_structural.callable_contracts,
                .from_callable => |use| use.callable_contracts,
                .from_scheme, .unreachable_value, .checked_error => 0,
            };
            if (contract_count != 0) {
                frame.pending = .{ .contracts = contracts_target };
                try frames.append(self.allocator, .{ .out = try arena.alloc(SpecEvidence, contract_count) });
                continue;
            }
            frame.next += 1;
        }
    }

    fn setSpecEvidenceCallableContracts(entry: *SpecEvidence, target: ?*SpecEvidenceTarget, contracts: []const SpecEvidence) void {
        switch (entry.*) {
            .target => target.?.callable_contracts = contracts,
            .structural => |*structural| structural.callable_contracts = contracts,
            .from_callable => |*use| use.callable_contracts = contracts,
            .from_scheme, .unreachable_value, .checked_error => unreachable,
        }
    }

    fn finishStoredEvidenceTarget(
        self: *BodyContext,
        materialized: *SpecEvidenceTarget,
        target: @FieldType(check.ConstStore.ConstFnEvidence, "target"),
        nested: NestedSpecEvidence,
    ) Allocator.Error!void {
        materialized.* = .{
            .view = self.builder.moduleForDigest(target.view),
            .target = target.method,
            .instantiation = if (target.instantiation) |instantiation| .{
                .view = self.builder.moduleForDigest(instantiation.view),
                .callable_ty = instantiation.callable_ty,
            } else null,
            .local_proc_context = switch (target.method.kind) {
                .local_proc => |local| blk_context: {
                    const context_view = self.builder.moduleForDigest(target.view);
                    const context_id = try self.localProcContextId(context_view, local.binder, local.expr);
                    _ = self.validateLocalProcContext(
                        context_id,
                        self.builder.moduleForDigest(target.view).key.bytes,
                        local.binder,
                        local.expr,
                        local.context_anchor,
                    );
                    break :blk_context context_id;
                },
                .procedure, .structural => null,
            },
            .nested = nested,
        };
    }

    /// Select the producer-authored edge before materializing any evidence.
    /// Platform requirements carry app-owned root evidence; ordinary procedure
    /// uses carry their checked call-site or construction evidence. Direct calls,
    /// procedure values, and interface specialization share this selection.
    fn evidenceForProcedureUseAtNode(
        self: *BodyContext,
        proc: checked.ProcedureUseTemplate,
        expr: checked.CheckedExprId,
        root_evidence: ?checked.CheckedEvidenceSpan,
        request_fn_node: NodeId,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error!EdgeEvidence {
        if (root_evidence) |evidence| {
            return try self.checkedProcedureEdgeAtRequest(self.builder.templateRefForProcedureUse(proc), evidence, request_fn_node, purpose);
        }
        return try self.evidenceForUseSiteForPurposeAtNode(expr, purpose, request_fn_node);
    }

    /// Resolve every symbolic callable-path entry whose dispatcher is already
    /// known in the live specialization graph. Entries left open here are
    /// retained by ConstStore and resolved when that stored function is used.
    /// Applies one checked evidence path node to the graph node its parent
    /// selects. A tag label selects its tag union; the payload index after it
    /// selects the payload.
    const EvidencePathNodeStepper = struct {
        body: *BodyContext,
        view: ModuleView,

        pub fn apply(
            self: EvidencePathNodeStepper,
            node: NodeId,
            path_nodes: []const static_dispatch.EvidencePathNode,
            path_node: u32,
        ) Allocator.Error!?NodeId {
            return self.body.evidencePathNodeStep(self.view, node, path_nodes, path_node);
        }
    };

    fn evidencePathNodeStep(
        self: *BodyContext,
        view: ModuleView,
        node: NodeId,
        path_nodes: []const static_dispatch.EvidencePathNode,
        path_node: u32,
    ) Allocator.Error!?NodeId {
        const step = path_nodes[path_node].step;
        const content = (try self.graph.content(node));
        switch (step.stepKind()) {
            .fn_arg => switch (content) {
                .func => |function| {
                    if (step.data >= function.args.len) return null;
                    return function.args[step.data];
                },
                .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return null,
            },
            .fn_ret => switch (content) {
                .func => |function| return function.ret,
                .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return null,
            },
            .alias_arg, .nominal_arg => switch (content) {
                .named => |named| {
                    if (step.data >= named.args.len) return null;
                    return named.args[step.data];
                },
                .list, .box => |payload| {
                    if (step.data != 0) return null;
                    return payload;
                },
                .redirect, .leaf, .unresolved, .primitive, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return null,
            },
            .alias_backing, .nominal_backing => switch (content) {
                .named => |named| return (named.backing orelse return null).node,
                .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return null,
            },
            .tuple_elem => switch (content) {
                .tuple => |items| {
                    if (step.data >= items.len) return null;
                    return items[step.data];
                },
                .redirect, .leaf, .unresolved, .primitive, .list, .box, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return null,
            },
            .record_field => switch (content) {
                .record => return try self.graph.recordFieldValueNode(node, try self.recordFieldName(view, @fromBackingInt(step.data))),
                .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .empty_tag_union, .empty_record, .named, .erased, .zst => return null,
            },
            .tag_payload_tag => switch (content) {
                .tag_union => return node,
                .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return null,
            },
            .tag_payload_index => {
                const tag_node = path_nodes[path_node].parent;
                if (tag_node == static_dispatch.no_evidence_path_node) return null;
                const tag_step = path_nodes[tag_node].step;
                if (tag_step.stepKind() != .tag_payload_tag) return null;
                return switch (content) {
                    .tag_union => try self.graph.tagPayloadNode(
                        node,
                        try self.tagName(view, @fromBackingInt(@intCast(tag_step.data))),
                        step.data,
                    ),
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => null,
                };
            },
        }
    }

    fn resolveCallableEvidenceAtNode(
        self: *BodyContext,
        view: ModuleView,
        template: checked.CheckedProcedureTemplate,
        evidence: []const SpecEvidence,
        request_fn_node: NodeId,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error![]const SpecEvidence {
        const params = view.templates.evidenceParams(&template);
        if (evidence.len != params.len) {
            Common.invariant("callable-derived evidence length differed from its checked template");
        }
        const Replacement = struct { index: usize, entry: SpecEvidence };
        var replacements = std.ArrayList(Replacement).empty;
        defer replacements.deinit(self.allocator);
        var has_symbolic = false;
        var path_memo: static_dispatch.EvidencePathMemo(NodeId) = .{};
        defer path_memo.deinit(self.allocator);
        const path_stepper = EvidencePathNodeStepper{ .body = self, .view = view };
        for (evidence, 0..) |entry, index| switch (entry) {
            .from_callable => {
                has_symbolic = true;
                const param = params[index];
                if (param.path.len == 0) {
                    Common.invariant("callable-derived evidence named a pathless checked parameter");
                }
                const component_node = try path_memo.resolve(
                    self.allocator,
                    view.templates.evidence_path_nodes,
                    param.path.last,
                    0,
                    request_fn_node,
                    path_stepper,
                ) orelse
                    Common.invariant("callable-derived evidence path did not match its function request");
                const resolvable = (try self.methodOwnerFromNode(component_node)) != null or
                    param.structural != null or
                    try self.nodeIsProvenUninhabited(component_node) or
                    (try self.nodeFinalizesAsUninhabitedLeaf(component_node));
                if (resolvable) {
                    try replacements.append(self.allocator, .{
                        .index = index,
                        .entry = try self.synthesizeComponentEvidenceAtNodeForPurpose(
                            view,
                            param.method,
                            param.structural,
                            component_node,
                            purpose,
                        ),
                    });
                }
            },
            .target, .structural, .from_scheme, .unreachable_value, .checked_error => {},
        };
        if (has_symbolic) self.builder.countBodyDiagnostic("callable_evidence_symbolic_requests");
        if (replacements.items.len == 0) return evidence;
        // Evidence can be shared with another request or lexical frame, so it
        // is never written in place. A request that resolves every slot the
        // way the previous request over this vector did reads that copy back.
        // The callee template is identified by its module and its evidence
        // parameter row, which every request over it shares.
        var key_hasher = std.hash.Wyhash.init(0);
        key_hasher.update(&view.key.bytes);
        key_hasher.update(std.mem.asBytes(&@intFromPtr(params.ptr)));
        const key = key_hasher.final();
        const cached = try self.builder.resolved_callable_vectors.getOrPut(key);
        if (!cached.found_existing) cached.value_ptr.* = .empty;
        for (cached.value_ptr.items) |candidate| reuse: {
            if (candidate.len != evidence.len) break :reuse;
            var next_replacement: usize = 0;
            for (candidate, evidence, 0..) |cached_entry, source_entry, index| {
                if (next_replacement < replacements.items.len and replacements.items[next_replacement].index == index) {
                    if (!try specEvidenceEql(self.allocator, cached_entry, replacements.items[next_replacement].entry)) break :reuse;
                    next_replacement += 1;
                } else if (!try specEvidenceEql(self.allocator, cached_entry, source_entry)) break :reuse;
            }
            return candidate;
        }
        const resolved = try self.builder.evidence_arena.allocator().dupe(SpecEvidence, evidence);
        self.builder.countBodyDiagnostic("callable_evidence_vector_copies");
        for (replacements.items) |replacement| resolved[replacement.index] = replacement.entry;
        try cached.value_ptr.append(self.allocator, resolved);
        return resolved;
    }

    /// The substitution and evidence the scheme instantiated at `expr` (a
    /// value use resolved in this context's module) receives, or an empty
    /// edge when the use instantiates nothing.
    fn evidenceForUseSite(self: *BodyContext, expr: checked.CheckedExprId) Allocator.Error!EdgeEvidence {
        return self.evidenceForUseSiteForPurpose(expr, .body_lowering);
    }

    /// `evidenceForUseSite` for a use whose request interface is live at
    /// `request_node`: a use checking recorded no instantiation for derives
    /// its edge from that request.
    fn evidenceForUseSiteAtNode(self: *BodyContext, expr: checked.CheckedExprId, request_node: NodeId) Allocator.Error!EdgeEvidence {
        return self.evidenceForUseSiteForPurposeAtNode(expr, .body_lowering, request_node);
    }

    fn evidenceForUseSiteForPurposeAtNode(
        self: *BodyContext,
        expr: checked.CheckedExprId,
        purpose: EvidenceMaterializationPurpose,
        request_node: NodeId,
    ) Allocator.Error!EdgeEvidence {
        return self.evidenceForSite(self.view, expr, try self.useSiteSchema(expr), purpose, request_node);
    }

    fn evidenceForUseSiteForPurpose(
        self: *BodyContext,
        expr: checked.CheckedExprId,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error!EdgeEvidence {
        return self.evidenceForSite(self.view, expr, try self.useSiteSchema(expr), purpose, null);
    }

    /// The requirement schema of the scheme a resolved value reference
    /// instantiates: the referenced procedure template's, the local
    /// procedure's declaration scope's, or the const's evaluation entry
    /// template's.
    fn useSiteSchema(self: *BodyContext, expr: checked.CheckedExprId) Allocator.Error!SchemeRequirements {
        const raw_expr = @backingInt(expr);
        if (raw_expr >= self.view.resolved_refs.by_checked_expr.len) return emptySchema(self.view);
        const ref_id = self.view.resolved_refs.by_checked_expr[raw_expr] orelse return emptySchema(self.view);
        const record = self.view.resolved_refs.records[@backingInt(ref_id)];
        return switch (record.ref) {
            .top_level_proc, .imported_proc, .hosted_proc, .promoted_top_level_proc => |proc| self.procedureUseSchema(proc),
            .platform_required_proc => |proc| self.procedureUseSchema(proc.procedure),
            .local_proc => |local| self.scopeSchema(self.view, local.dispatch_scope),
            .top_level_const, .imported_const => |const_use| self.constUseSchema(const_use),
            .platform_required_const => |required| self.constUseSchema(required.const_use),
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .platform_required_declaration, .platform_required_checked_error => emptySchema(self.view),
        };
    }

    fn emptySchema(view: ModuleView) SchemeRequirements {
        return .{ .view = view, .root = null, .scheme_vars = &.{}, .params = &.{}, .params_start = 0 };
    }

    /// The schema of a generalized-local dispatch scope; a local procedure
    /// without a scope has no requirements and no quantified variables.
    fn scopeSchema(_: *BodyContext, view: ModuleView, maybe_scope: ?checked.DispatchScopeId) SchemeRequirements {
        const scope_id = maybe_scope orelse return emptySchema(view);
        const raw_scope = @backingInt(scope_id);
        if (raw_scope >= view.templates.dispatch_scopes.len) {
            Common.invariant("local procedure named a dispatch scope outside its checked template table");
        }
        const scope = view.templates.dispatch_scopes[raw_scope];
        return .{
            .view = view,
            .root = scope.scheme_root,
            .scheme_vars = view.templates.scopeSchemeVars(&scope),
            .params = view.templates.evidence_params_pool[scope.evidence_params.start .. scope.evidence_params.start + scope.evidence_params.len],
            .params_start = scope.evidence_params.start,
        };
    }

    fn procedureUseSchema(self: *BodyContext, proc: checked.ProcedureUseTemplate) SchemeRequirements {
        if (self.builder.callableEvalForProcedureUse(proc)) |callable_eval| {
            // A callable-eval binding lowers through its root's entry wrapper,
            // whose scheme is the binding's own.
            const raw_template = @backingInt(callable_eval.template);
            if (raw_template >= callable_eval.view.callable_eval_templates.templates.len) {
                Common.invariant("callable eval binding referenced a missing checked template");
            }
            const eval_template = callable_eval.view.callable_eval_templates.templates[raw_template];
            const wrapper = callable_eval.view.entry_wrappers.lookupByRoot(eval_template.root) orelse
                Common.invariant("callable eval template root had no checked entry wrapper");
            return self.templateSchema(wrapper.template);
        }
        return self.templateSchema(self.builder.templateRefForProcedureUse(proc));
    }

    fn templateSchema(self: *BodyContext, template_ref: names.ProcTemplate) SchemeRequirements {
        const view = self.builder.moduleForDigest(names.procTemplateModuleDigest(template_ref));
        const template = view.templates.get(template_ref.template);
        return templateSchemaIn(view, &template);
    }

    /// The schema of the entry template a const use evaluates through; a
    /// stored or unimplemented const lowers no template body.
    fn constUseSchema(self: *BodyContext, const_use: checked.ConstUseTemplate) SchemeRequirements {
        const store_view = self.builder.moduleForId(checked.constModuleId(const_use.const_ref));
        const template = store_view.const_templates.get(const_use.const_ref);
        return switch (template.state) {
            .eval_template => |eval| self.templateSchema(eval.entry_template),
            .stored_const, .reserved, .unimplemented => emptySchema(store_view),
        };
    }

    /// Evidence for `schema`'s scheme at a checked instantiation site in
    /// `site_view`: the site's recorded substitution as live cells of this
    /// context, with the site's own entries as contract provenance.
    fn evidenceForSite(
        self: *BodyContext,
        site_view: ModuleView,
        expr: checked.CheckedExprId,
        schema: SchemeRequirements,
        purpose: EvidenceMaterializationPurpose,
        request_node: ?NodeId,
    ) Allocator.Error!EdgeEvidence {
        const recorded = site_view.static_dispatch_plans.siteSubstitution(expr);
        if (recorded == null and schema.params.len != 0) {
            // Checking recorded no instantiation at this use (the edge is
            // compiler-generated): the request interface alone determines
            // the substitution.
            const node = request_node orelse Common.invariant("constrained scheme use had no checked substitution");
            return try self.deriveEdgeAtRequest(schema, node, purpose);
        }
        const tys = recorded orelse &.{};
        const subst = if (tys.len == schema.scheme_vars.len)
            try self.substitutionFromCheckedTypes(site_view, tys)
        else if (tys.len == 0)
            // Checking recorded no instantiation at this use, so nothing was
            // copied: the scheme's variables are all shared with the use
            // (a monomorphic value's still-open variables), and every slot is
            // the scheme variable's own cell.
            try self.substitutionFromCheckedTypes(schema.view, schema.scheme_vars)
        else
            Common.invariant("checked site substitution length differed from its scheme's quantified variables");
        const refs = site_view.static_dispatch_plans.siteEvidence(expr);
        return .{
            .subst = subst,
            .vector = if (refs) |site_refs|
                try self.deriveSiteEvidenceVector(schema, subst, site_view, site_refs, tys, purpose)
            else
                try self.deriveEvidenceVector(schema, subst, site_view, refs, purpose),
        };
    }

    /// `deriveCheckedEvidenceVector` for a checked use site, shared between
    /// lowering contexts when it cannot depend on one. Deriving a site's
    /// evidence reads only checked data, the site's substitution cells, and
    /// the enclosing evidence chain; with no parameter in that chain and a
    /// substitution of ground checked types, whose cells hold exactly those
    /// types in every context, the derived vector is the same wherever the
    /// site is lowered. Uses that checking replayed from one source share
    /// their evidence and substitution, so they derive it once. The
    /// contracts are still related in each context, since relating them
    /// binds that context's cells.
    fn deriveSiteEvidenceVector(
        self: *BodyContext,
        schema: SchemeRequirements,
        subst: SpecSubstitution,
        site_view: ModuleView,
        refs: []const static_dispatch.CheckedEvidence,
        checked_subst: []const checked.CheckedTypeId,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error![]const SpecEvidence {
        if (schema.params.len == 0) return &.{};
        const key: ?SiteEvidenceMemoKey = if (!self.evidenceChainHasEntries() and
            try self.builder.checkedTypesGround(site_view, checked_subst))
            .{
                .view = @intFromPtr(site_view),
                .method_scope = @intFromPtr(self.method_scope),
                .refs = @intFromPtr(refs.ptr),
                .refs_len = refs.len,
                .subst = @intFromPtr(checked_subst.ptr),
                .subst_len = checked_subst.len,
                .params = @intFromPtr(schema.params.ptr),
                .params_len = schema.params.len,
                .purpose = purpose,
            }
        else
            null;
        if (key) |shared| if (self.builder.site_evidence_memo.get(shared)) |memo| {
            if (purpose != .interface_summary_input) try self.relateEvidenceContracts(schema, subst, memo.contract);
            return memo.vector;
        };
        var contract: []const SpecEvidence = &.{};
        const vector = try self.deriveCheckedEvidenceVectorKeepingContract(schema, subst, site_view, refs, purpose, &contract);
        if (key) |shared| {
            if (!evidenceVectorHasLocalProcContext(contract) and !evidenceVectorHasLocalProcContext(vector)) {
                try self.builder.site_evidence_memo.put(shared, .{ .contract = contract, .vector = vector });
            }
        }
        return vector;
    }

    /// Whether any frame of this context's evidence chain carries evidence a
    /// requirement could be forwarded to or resolved against.
    fn evidenceChainHasEntries(self: *const BodyContext) bool {
        var frame: ?*const EvidenceChain = &self.evidence;
        while (frame) |current| : (frame = current.parent) {
            if (current.vector.len != 0) return true;
            if (current.schema) |schema| if (schema.params.len != 0) return true;
        }
        return false;
    }

    /// The substitution a scheme receives from a request its root is related
    /// to: the root instantiates in a context for the scheme's module, the
    /// request binds every quantified variable the root reaches, and the
    /// slots are read back from that context.
    fn substitutionAtRequest(self: *BodyContext, schema: SchemeRequirements, request_node: NodeId) Allocator.Error!SpecSubstitution {
        if (schema.scheme_vars.len == 0) return &.{};
        const root = schema.root orelse Common.invariant("scheme without a root type received a request substitution");
        var scheme_ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self.builder,
            schema.view,
            self.method_scope,
            self.owner_template,
            self.graph,
            self.draft,
        );
        defer scheme_ctx.deinit();
        const root_node = try scheme_ctx.instNode(root);
        try relateFunctionRequestInterface(self.graph, root_node, request_node);
        return try self.substitutionFromSchemeVars(&scheme_ctx, schema.scheme_vars);
    }

    /// The edge a producer-authored root (a platform requirement) supplies to
    /// a template at a live request: the substitution read from the request,
    /// with the root's recorded entries as contract provenance.
    fn checkedProcedureEdgeAtRequest(
        self: *BodyContext,
        template_ref: names.ProcTemplate,
        evidence_span: checked.CheckedEvidenceSpan,
        request_node: NodeId,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error!EdgeEvidence {
        const view = self.builder.moduleForId(evidence_span.checked_module);
        if (!moduleBytesEqual(view.key.bytes, names.procTemplateModuleDigest(template_ref).bytes)) {
            Common.invariant("root procedure evidence and procedure template belonged to different checked modules");
        }
        const start: usize = evidence_span.span.start;
        const len: usize = evidence_span.span.len;
        if (start > view.static_dispatch_plans.evidence_refs.len or
            len > view.static_dispatch_plans.evidence_refs.len - start)
        {
            Common.invariant("root procedure evidence range was outside its checked module");
        }
        const template = view.templates.get(template_ref.template);
        const schema = templateSchemaIn(view, &template);
        const subst = try self.substitutionAtRequest(schema, request_node);
        return .{
            .subst = subst,
            .vector = try self.deriveEvidenceVector(schema, subst, view, view.static_dispatch_plans.evidence_refs[start .. start + len], purpose),
        };
    }

    /// The edge of a compiler-generated use: its substitution read from the
    /// request and its evidence derived from that substitution.
    fn deriveEdgeAtRequest(
        self: *BodyContext,
        schema: SchemeRequirements,
        request_node: NodeId,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error!EdgeEvidence {
        const subst = try self.substitutionAtRequest(schema, request_node);
        return .{
            .subst = subst,
            .vector = try self.deriveEvidenceVector(schema, subst, schema.view, null, purpose),
        };
    }

    /// A root without a supplied substitution still owns every quantified
    /// slot, even when it has no method requirements. Instantiate those slots
    /// in this body's context so the root interface, descendants, and recursive
    /// requests all use the same cells. instNode installs them already; seeding
    /// them back into this context would only repeat the lookups.
    fn rootEvidenceAtOwnScheme(
        self: *BodyContext,
        template: checked.CheckedProcedureTemplate,
        vector: []const SpecEvidence,
    ) Allocator.Error!EvidenceChain {
        const schema = templateSchemaIn(self.view, &template);
        // These cells and their slot array live only as long as the body graph.
        // Stored function evidence retains the vector and scope, never slots.
        const slots = try self.graph.arena().alloc(SubstSlot, schema.scheme_vars.len);
        for (schema.scheme_vars, slots) |ty, *slot| {
            slot.* = switch (checkedPayload(self.view, ty)) {
                .err => .checked_error,
                .pending => Common.invariant("pending checked type reached a root substitution"),
                .flex, .rigid, .alias, .record, .tuple, .nominal, .function, .empty_record, .tag_union, .empty_tag_union => .{ .node = try self.instNode(ty) },
            };
        }
        return rootEvidenceWithSubstitution(self.owner_template, schema, .{ .subst = slots, .vector = vector });
    }

    /// Live slots for a substitution recorded as checked types of
    /// `site_view`, instantiated in this context (or in a context for that
    /// module when the site belongs to another one).
    fn substitutionFromCheckedTypes(
        self: *BodyContext,
        site_view: ModuleView,
        tys: []const checked.CheckedTypeId,
    ) Allocator.Error!SpecSubstitution {
        if (tys.len == 0) return &.{};
        const same_module = moduleBytesEqual(site_view.key.bytes, self.view.key.bytes);
        var site_ctx: ?BodyContext = if (same_module) null else try BodyContext.initWithMethodScope(
            self.allocator,
            self.builder,
            site_view,
            self.method_scope,
            self.owner_template,
            self.graph,
            self.draft,
        );
        defer if (site_ctx) |*ctx| ctx.deinit();
        const ctx: *BodyContext = if (site_ctx) |*ctx| ctx else self;
        const arena = self.builder.evidence_arena.allocator();
        const slots = try arena.alloc(SubstSlot, tys.len);
        for (tys, slots) |ty, *slot| {
            slot.* = switch (checkedPayload(site_view, ty)) {
                .err => .checked_error,
                .pending => Common.invariant("pending checked type reached a specialization substitution"),
                .flex, .rigid, .alias, .record, .tuple, .nominal, .function, .empty_record, .tag_union, .empty_tag_union => .{ .node = try ctx.instNode(ty) },
            };
        }
        return slots;
    }

    /// The substitution a scheme receives through the context that
    /// instantiated its root: each quantified variable read back from
    /// `scheme_ctx`, so every slot shares the cells the root relation
    /// established.
    fn substitutionFromSchemeVars(
        self: *BodyContext,
        scheme_ctx: *BodyContext,
        scheme_vars: []const checked.CheckedTypeId,
    ) Allocator.Error!SpecSubstitution {
        if (scheme_vars.len == 0) return &.{};
        const arena = self.builder.evidence_arena.allocator();
        const slots = try arena.alloc(SubstSlot, scheme_vars.len);
        for (scheme_vars, slots) |ty, *slot| slot.* = .{ .node = try scheme_ctx.instNode(ty) };
        return slots;
    }

    /// Instantiate a scheme under a substitution: bind each quantified
    /// variable's checked type to its slot cell before anything in this
    /// context instantiates the scheme, so every occurrence of the variable
    /// (in the root, in constraint callables, and at every edge inside the
    /// body) is that cell. A rejected slot binds nothing; an instantiation
    /// that reaches it is erroneous checked data.
    fn seedSubstitution(self: *BodyContext, schema: SchemeRequirements, subst: SpecSubstitution) Allocator.Error!void {
        if (subst.len != schema.scheme_vars.len) {
            Common.invariant("specialization substitution length differed from its scheme's quantified variables");
        }
        for (schema.scheme_vars, subst) |scheme_var, slot| {
            const node = switch (slot) {
                .node => |node| node,
                .checked_error => continue,
            };
            const scoped_ty = self.scopedCheckedType(scheme_var);
            if (try self.scopedNode(scoped_ty)) |existing| {
                if (!self.graph.sameClass(existing, node)) try self.graph.unify(existing, node);
                continue;
            }
            try self.putScopedNode(scoped_ty, node);
        }
    }

    /// Live slots for a sealed substitution imported into this context's
    /// graph.
    fn substitutionFromSealed(self: *BodyContext, sealed: SealedSubstitution) Allocator.Error!SpecSubstitution {
        if (sealed.len == 0) return &.{};
        const arena = self.builder.evidence_arena.allocator();
        const slots = try arena.alloc(SubstSlot, sealed.len);
        for (sealed, slots) |sealed_slot, *slot| {
            slot.* = switch (sealed_slot) {
                .checked_error => .checked_error,
                .ty => |ty| .{ .node = try self.activeNodeFromType(try self.importProgramType(ty)) },
            };
        }
        return slots;
    }

    /// Materialize only checked producer data not represented by the
    /// substitution-derived evidence. Direct targets retain their checked
    /// callable instantiation only for a requirement whose declared source is a
    /// constraint callable, where that relation binds hidden scheme slots.
    /// Their nested contract is retained recursively only when it contains
    /// such a relation or a terminal checked verdict/structural contract.
    fn materializeCheckedEvidenceRef(
        self: *BodyContext,
        site_view: ModuleView,
        ref: static_dispatch.CheckedEvidence,
        param: static_dispatch.EvidenceParamRecord,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error!SpecEvidence {
        const refs = [_]static_dispatch.CheckedEvidence{ref};
        var out: [1]SpecEvidence = undefined;
        try self.runCheckedEvidenceRefs(site_view, .{ .refs = &refs, .params = .{ .same = param }, .out = &out, .owner = .root }, purpose);
        return out[0];
    }

    /// A checked evidence reference that names no target node of its own.
    fn materializeIndirectCheckedEvidenceRef(
        self: *BodyContext,
        site_view: ModuleView,
        ref: static_dispatch.CheckedEvidence,
    ) Allocator.Error!SpecEvidence {
        return switch (ref.resolution) {
            .direct => Common.invariant("direct checked evidence names a target node"),
            .constraint => |constraint| blk: {
                const entry = self.evidence.at(constraint.index) orelse
                    Common.invariant("checked requirement reference was absent from its lexical evidence chain");
                // The side-vector indexes belong to the receiving schema.
                // The outer materializer applies its checked forwarding map.
                if (selectCallableContract(entry, constraint.callable_contract)) |contract| break :blk contract;
                if (!constraint.independent_callable) break :blk entry;
                break :blk switch (entry) {
                    .target => |target| independent: {
                        const independent_target = try self.builder.evidence_arena.allocator().create(SpecEvidenceTarget);
                        independent_target.* = .{
                            .view = target.view,
                            .target = target.target,
                            .instantiation = null,
                            .local_proc_context = target.local_proc_context,
                            .nested = self.dependentCallableNestedEvidence(constraint, target),
                        };
                        break :independent .{ .target = independent_target };
                    },
                    .from_callable => .{ .from_callable = .{
                        .independent_callable = true,
                    } },
                    .structural, .from_scheme, .unreachable_value, .checked_error => entry,
                };
            },
            .structural => |evidence| .{ .structural = .{
                .derivation = evidence.derivation,
                .checked = .{ .view = site_view, .evidence = evidence },
            } },
            .unreachable_value => .unreachable_value,
            .checked_error => .checked_error,
            .from_callable, .from_scheme => Common.invariant("symbolic checked evidence escaped a nested procedure construction recipe"),
        };
    }

    /// A checked target whose nested references are materializing. Nested
    /// target nodes follow type nesting, so each is a frame of its own.
    const EvidenceTargetFrame = struct {
        node: static_dispatch.EvidenceNode,
        retain_instantiation: bool,
        lookup: MethodLookup,
        target: *SpecEvidenceTarget,
        refs: []const static_dispatch.CheckedEvidence,
        params: []const static_dispatch.EvidenceParamRecord,
        nested: []SpecEvidence,
    };

    /// A vector of checked evidence references being materialized. Each
    /// reference materializes its primary evidence, then its callable
    /// contracts; a target's nested vector and a contract vector are frames
    /// of their own, so nested requirement depth never becomes native call
    /// depth.
    const CheckedRefsFrame = struct {
        refs: []const static_dispatch.CheckedEvidence,
        params: union(enum) {
            each: []const static_dispatch.EvidenceParamRecord,
            /// Every callable contract materializes under its owner's
            /// requirement.
            same: static_dispatch.EvidenceParamRecord,
        },
        out: []SpecEvidence,
        next: usize = 0,
        /// The current reference awaits its primary evidence or its
        /// contracts from the frame above.
        awaiting: enum { none, primary, contracts } = .none,
        owner: union(enum) {
            root,
            /// The target node whose nested vector this frame is.
            target: EvidenceTargetFrame,
            /// The primary evidence whose contract vector this frame is.
            contracts: SpecEvidence,
        },

        fn param(frame: *const CheckedRefsFrame) static_dispatch.EvidenceParamRecord {
            return switch (frame.params) {
                .each => |params| params[frame.next],
                .same => |same| same,
            };
        }
    };

    fn runCheckedEvidenceRefs(
        self: *BodyContext,
        site_view: ModuleView,
        root: CheckedRefsFrame,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error!void {
        const arena = self.builder.evidence_arena.allocator();
        var frames = std.ArrayList(CheckedRefsFrame).empty;
        defer frames.deinit(self.allocator);
        try frames.append(self.allocator, root);
        var delivered: ?SpecEvidence = null;
        while (true) {
            const frame = &frames.items[frames.items.len - 1];
            if (delivered) |value| {
                delivered = null;
                switch (frame.awaiting) {
                    .none => unreachable,
                    .primary => {
                        frame.awaiting = .none;
                        if (try self.beginCheckedEvidenceContracts(site_view, &frames, value)) continue;
                    },
                    .contracts => {
                        frame.awaiting = .none;
                        frame.out[frame.next] = value;
                        frame.next += 1;
                    },
                }
                continue;
            }
            if (frame.next < frame.refs.len) {
                const ref = frame.refs[frame.next];
                switch (ref.resolution) {
                    .direct => |node_id| {
                        const target = try self.enterEvidenceTarget(
                            site_view,
                            site_view.static_dispatch_plans.evidenceNode(node_id),
                            evidenceParamRequiresConstraintRelation(frame.param()),
                            purpose,
                        );
                        frame.awaiting = .primary;
                        try frames.append(self.allocator, .{
                            .refs = target.refs,
                            .params = .{ .each = target.params },
                            .out = target.nested,
                            .owner = .{ .target = target },
                        });
                    },
                    .constraint, .structural, .unreachable_value, .checked_error, .from_callable, .from_scheme => {
                        const primary = try self.materializeIndirectCheckedEvidenceRef(site_view, ref);
                        _ = try self.beginCheckedEvidenceContracts(site_view, &frames, primary);
                    },
                }
                continue;
            }
            const finished = frames.pop().?;
            delivered = switch (finished.owner) {
                .root => return,
                .target => |target| .{ .target = finishEvidenceTarget(site_view, target) },
                .contracts => |primary| blk: {
                    const original = evidenceCallableContracts(primary);
                    var changed: ?[]SpecEvidence = if (original.len == finished.out.len) null else try arena.alloc(SpecEvidence, finished.out.len);
                    for (finished.out, 0..) |entry, index| {
                        if (changed == null and !try specEvidenceEql(self.allocator, original[index], entry)) changed = try arena.dupe(SpecEvidence, original);
                        if (changed) |contracts| contracts[index] = entry;
                    }
                    break :blk try withCallableContracts(arena, primary, changed orelse original);
                },
            };
        }
    }

    /// Materialize the current reference's callable contracts over its
    /// primary evidence. Returns whether a contract frame now waits above
    /// the frame; otherwise the reference is complete.
    fn beginCheckedEvidenceContracts(
        self: *BodyContext,
        site_view: ModuleView,
        frames: *std.ArrayList(CheckedRefsFrame),
        primary: SpecEvidence,
    ) Allocator.Error!bool {
        const arena = self.builder.evidence_arena.allocator();
        const frame = &frames.items[frames.items.len - 1];
        const ref = frame.refs[frame.next];
        const complete: SpecEvidence = if (ref.callable_contracts.len == 0)
            try withCallableContracts(arena, primary, &.{})
        else switch (primary) {
            .from_scheme, .unreachable_value, .checked_error => primary,
            .target, .structural, .from_callable => {
                const contracts = site_view.static_dispatch_plans.evidence_refs[ref.callable_contracts.start..][0..ref.callable_contracts.len];
                const contract_frame: CheckedRefsFrame = .{
                    .refs = contracts,
                    .params = .{ .same = frame.param() },
                    .out = try arena.alloc(SpecEvidence, contracts.len),
                    .owner = .{ .contracts = primary },
                };
                frame.awaiting = .contracts;
                try frames.append(self.allocator, contract_frame);
                return true;
            },
        };
        frame.out[frame.next] = complete;
        frame.next += 1;
        return false;
    }

    fn enterEvidenceTarget(
        self: *BodyContext,
        site_view: ModuleView,
        node: static_dispatch.EvidenceNode,
        retain_instantiation: bool,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error!EvidenceTargetFrame {
        const base_lookup: MethodLookup = switch (node.target.kind) {
            .procedure => |procedure| .{
                .view = self.builder.moduleForDigest(names.procTemplateModuleDigest(procedure.template)),
                .target = node.target,
            },
            .local_proc => .{ .view = site_view, .target = node.target },
            .structural => Common.invariant("structural method target reached callable checked evidence"),
        };
        const lookup = try self.methodLookupForEvidencePurpose(base_lookup, purpose);
        const schema: SchemeRequirements = switch (lookup.target.kind) {
            .procedure => |procedure| blk: {
                const template = lookup.view.templates.get(procedure.template.template);
                break :blk templateSchemaIn(lookup.view, &template);
            },
            .local_proc => |local| self.scopeSchema(lookup.view, local.dispatch_scope),
            .structural => unreachable,
        };
        const target = try self.builder.evidence_arena.allocator().create(SpecEvidenceTarget);
        var frame: EvidenceTargetFrame = .{
            .node = node,
            .retain_instantiation = retain_instantiation,
            .lookup = lookup,
            .target = target,
            .refs = &.{},
            .params = &.{},
            .nested = &.{},
        };
        switch (node.nested) {
            .from_callable => {},
            .resolved => {
                const refs = site_view.static_dispatch_plans.nestedEvidence(node);
                if (refs.len != schema.params.len) {
                    Common.invariant("checked target nested evidence length differed from its requirement schema");
                }
                if (refs.len != 0) {
                    frame.refs = refs;
                    frame.params = schema.params;
                    frame.nested = try self.builder.evidence_arena.allocator().alloc(SpecEvidence, refs.len);
                }
            },
        }
        return frame;
    }

    fn finishEvidenceTarget(site_view: ModuleView, frame: EvidenceTargetFrame) *const SpecEvidenceTarget {
        frame.target.* = .{
            .view = frame.lookup.view,
            .target = frame.node.target,
            .instantiation = if (frame.retain_instantiation) switch (frame.node.instantiation) {
                .monomorphic => null,
                .callable, .derived_from_callable => |callable_ty| .{ .view = site_view, .callable_ty = callable_ty },
            } else null,
            .local_proc_context = frame.lookup.local_proc_context,
            .substitution = checkedTargetSubstitution(site_view, frame.node),
            .nested = if (frame.nested.len != 0 and evidenceVectorCarriesCheckedContract(frame.nested))
                .{ .resolved = frame.nested }
            else
                .synthesize,
        };
        return frame.target;
    }

    fn evidenceVectorCarriesCheckedContract(vector: []const SpecEvidence) bool {
        for (vector) |entry| switch (entry) {
            .target => |target| {
                if (target.instantiation != null or target.callable_contracts.len != 0) return true;
                // A local procedure's declaration context exists only where
                // this evidence was materialized; synthesis elsewhere does not
                // have it.
                if (target.local_proc_context != null) return true;
                switch (target.nested) {
                    .resolved => return true,
                    .synthesize => {},
                }
            },
            .structural => |structural| if (structural.checked != null) return true,
            .from_callable, .from_scheme, .unreachable_value, .checked_error => return true,
        };
        return false;
    }

    /// Overlay a checked contract on evidence already selected from the
    /// substitution. Keep the checked callable relation when the parameter
    /// requires it; otherwise retain only the nested producer contract.
    fn mergeCheckedEvidenceContract(
        self: *BodyContext,
        derived: SpecEvidence,
        contract: SpecEvidence,
    ) Allocator.Error!SpecEvidence {
        return switch (contract) {
            .target => |contract_target| switch (derived) {
                .target => |derived_target| blk: {
                    if (contract_target.instantiation != null) {
                        break :blk contract;
                    }
                    if (!std.meta.eql(derived_target.view.key, contract_target.view.key) or
                        !specMethodTargetEql(derived_target, contract_target))
                    {
                        Common.invariant("substitution-derived target differed from checked target contract");
                    }
                    if (contract_target.nested == .synthesize and contract_target.substitution == null and contract_target.callable_contracts.len == 0) break :blk derived;
                    const merged = try self.builder.evidence_arena.allocator().create(SpecEvidenceTarget);
                    merged.* = derived_target.*;
                    merged.instantiation = null;
                    merged.substitution = contract_target.substitution;
                    switch (contract_target.nested) {
                        .synthesize => {},
                        .resolved => |resolved| merged.nested = .{ .resolved = resolved },
                    }
                    merged.callable_contracts = contract_target.callable_contracts;
                    break :blk .{ .target = merged };
                },
                .structural, .from_callable, .from_scheme, .unreachable_value, .checked_error => Common.invariant("checked target contract differed from substitution-derived evidence kind"),
            },
            .structural, .from_callable, .from_scheme, .unreachable_value, .checked_error => contract,
        };
    }

    /// Evidence for every requirement of a scheme under a substitution.
    /// Target identity is selected from the substituted receiver. Checked
    /// entries contribute their explicit contracts and terminal verdicts
    /// alongside the substitution-derived target identity.
    fn deriveEvidenceVector(
        self: *BodyContext,
        schema: SchemeRequirements,
        subst: SpecSubstitution,
        site_view: ModuleView,
        site_refs: ?[]const static_dispatch.CheckedEvidence,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error![]const SpecEvidence {
        // An initializer with no requirements derives no method evidence.
        // Its value's use may still have a checked recipe for a callable
        // stored inside that value; that recipe is not an initializer edge.
        if (schema.params.len == 0) return &.{};
        if (site_refs) |refs| {
            return try self.deriveCheckedEvidenceVector(schema, subst, site_view, refs, purpose);
        }
        const arena = self.builder.evidence_arena.allocator();
        const out = try arena.alloc(SpecEvidence, schema.params.len);
        const derived = try self.allocator.alloc(bool, schema.params.len);
        defer self.allocator.free(derived);
        @memset(derived, false);
        for (schema.params, 0..) |param, k| {
            if (param.source == .scheme_requirement) {
                Common.invariant("composite scheme requirement had no checked call-site evidence");
            }
            if (param.slot.? >= subst.len) Common.invariant("requirement receiver slot was outside the request substitution");
            if (subst[param.slot.?] == .checked_error) {
                out[k] = .checked_error;
                derived[k] = true;
            }
        }

        // At a compiler-generated edge the scheme's constraint callables
        // instantiate over the request's slots in `scheme_ctx`, so relating a
        // selected target to its constraint binds every quantified variable
        // only that callable reaches. Each such binding can resolve another
        // requirement's receiver, so the derivation runs to a fixpoint before
        // any receiver is judged open. A forwarded structural codec
        // carries its checked callable, which can reach variables its receiver
        // does not (a parser's error row), so it is related like a target.
        // The context is created by the first relation.
        var scheme_ctx: ?BodyContext = null;
        defer if (scheme_ctx) |*ctx| ctx.deinit();
        var progress = true;
        while (progress) {
            progress = false;
            for (schema.params, 0..) |param, k| {
                if (derived[k]) continue;
                const node = subst[param.slot.?].node;
                if (self.forwardedRequirement(node, schema.view.names, param.method)) |forwarded| switch (forwarded) {
                    // Callable targets are selected again from this scheme's
                    // substitution below. Terminal evidence belongs to the
                    // enclosing requirement on this exact cell: structural
                    // codecs in particular carry their producer-authored
                    // checked contract only on that entry.
                    .structural, .from_callable, .from_scheme, .unreachable_value, .checked_error => {
                        out[k] = forwarded;
                        derived[k] = true;
                        progress = true;
                        switch (forwarded) {
                            .structural => |structural| if (structural.checked) |checked_structural| {
                                if (scheme_ctx == null) {
                                    scheme_ctx = try BodyContext.initWithMethodScope(
                                        self.allocator,
                                        self.builder,
                                        schema.view,
                                        self.method_scope,
                                        self.owner_template,
                                        self.graph,
                                        self.draft,
                                    );
                                    try scheme_ctx.?.seedSubstitution(schema, subst);
                                }
                                try self.relateStructuralEvidenceToConstraint(checked_structural, &scheme_ctx.?, param);
                            },
                            .target, .from_callable, .from_scheme, .unreachable_value, .checked_error => {},
                        }
                        continue;
                    },
                    .target => {},
                };
                if ((try self.methodOwnerFromNode(node)) == null) continue;
                out[k] = try self.synthesizeComponentEvidenceAtNodeForPurpose(schema.view, param.method, param.structural, node, purpose);
                derived[k] = true;
                progress = true;
                switch (out[k]) {
                    .target => |target| {
                        if (scheme_ctx == null) {
                            scheme_ctx = try BodyContext.initWithMethodScope(
                                self.allocator,
                                self.builder,
                                schema.view,
                                self.method_scope,
                                self.owner_template,
                                self.graph,
                                self.draft,
                            );
                            try scheme_ctx.?.seedSubstitution(schema, subst);
                        }
                        try self.relateTargetToConstraint(target, &scheme_ctx.?, param);
                    },
                    .structural, .from_callable, .from_scheme, .unreachable_value, .checked_error => {},
                }
            }
        }

        for (schema.params, 0..) |param, k| {
            if (derived[k]) continue;
            out[k] = try self.deriveOpenRequirement(schema.view, param, subst[param.slot.?].node, purpose);
        }
        return out;
    }

    /// Checked edges supply every target contract before receiver-based
    /// selection. Relate those contracts first: one method's signature can
    /// bind a different requirement's hidden receiver. Reuse the output vector
    /// for materialization and merging, without a second vector or fixpoint.
    fn deriveCheckedEvidenceVector(
        self: *BodyContext,
        schema: SchemeRequirements,
        subst: SpecSubstitution,
        site_view: ModuleView,
        refs: []const static_dispatch.CheckedEvidence,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error![]const SpecEvidence {
        var contract: []const SpecEvidence = &.{};
        return self.deriveCheckedEvidenceVectorKeepingContract(schema, subst, site_view, refs, purpose, &contract);
    }

    /// `deriveCheckedEvidenceVector`, also returning in `contract_out` a copy
    /// of the checked contracts as they were related, before substitution-
    /// derived targets were merged into them.
    fn deriveCheckedEvidenceVectorKeepingContract(
        self: *BodyContext,
        schema: SchemeRequirements,
        subst: SpecSubstitution,
        site_view: ModuleView,
        refs: []const static_dispatch.CheckedEvidence,
        purpose: EvidenceMaterializationPurpose,
        contract_out: *[]const SpecEvidence,
    ) Allocator.Error![]const SpecEvidence {
        if (refs.len != schema.params.len) Common.invariant("checked site evidence length differed from its scheme's requirements");
        const out = try self.builder.evidence_arena.allocator().alloc(SpecEvidence, schema.params.len);
        for (refs, schema.params, out, 0..) |ref, param, *entry, k| {
            if (param.source == .scheme_requirement) {
                if (param.slot != null) Common.invariant("composite requirement occupied a quantified-variable slot");
                entry.* = if (ref.resolution == .from_scheme)
                    .{ .from_scheme = @intCast(k) }
                else
                    try self.materializeCheckedEvidenceRef(site_view, ref, param, purpose);
                continue;
            }
            if (param.slot.? >= subst.len) Common.invariant("requirement receiver slot was outside the request substitution");
            entry.* = switch (ref.resolution) {
                .from_callable => .{ .from_callable = .{ .independent_callable = false } },
                .from_scheme => Common.invariant("abstract scheme evidence named an ordinary callable parameter"),
                .direct, .constraint, .structural, .unreachable_value, .checked_error => try self.materializeCheckedEvidenceRef(site_view, ref, param, purpose),
            };
            if (subst[param.slot.?] == .checked_error) {
                entry.* = switch (ref.resolution) {
                    .direct, .constraint => try self.mergeCheckedEvidenceContract(.checked_error, entry.*),
                    .structural, .from_callable, .from_scheme, .checked_error, .unreachable_value => .checked_error,
                };
            }
        }
        // Summary lookup describes the unrefined input. On a cache miss its
        // expansion applies these relations to detached substitution cells;
        // a hit replays the completed relation without repeating this work.
        contract_out.* = try self.builder.evidence_arena.allocator().dupe(SpecEvidence, out);
        if (purpose != .interface_summary_input) try self.relateEvidenceContracts(schema, subst, contract_out.*);
        for (schema.params, out) |param, *entry| {
            // Structural entries already carry the checked callable contracts
            // materialized above; only targets need receiver-based selection.
            if (param.source == .scheme_requirement or entry.* != .target) continue;
            const node = subst[param.slot.?].node;
            const derived = derive: {
                if (self.forwardedRequirement(node, schema.view.names, param.method)) |forwarded| switch (forwarded) {
                    .target => {},
                    .structural, .from_callable, .from_scheme, .unreachable_value, .checked_error => break :derive forwarded,
                };
                break :derive if ((try self.methodOwnerFromNode(node)) != null)
                    try self.synthesizeComponentEvidenceAtNodeForPurpose(schema.view, param.method, param.structural, node, purpose)
                else
                    try self.deriveOpenRequirement(schema.view, param, node, purpose);
            };
            entry.* = try self.mergeCheckedEvidenceContract(derived, entry.*);
        }
        return out;
    }

    /// Relate every selected contract in `contract` to the requirement it
    /// satisfies, over `schema`'s substitution `subst`. The relations of one
    /// requirement row and contract are summarized by the substitution's
    /// identity, so an equal substitution replays them in one step instead of
    /// relating each requirement again.
    fn relateEvidenceContracts(
        self: *BodyContext,
        schema: SchemeRequirements,
        subst: SpecSubstitution,
        contract: []const SpecEvidence,
    ) Allocator.Error!void {
        if (!evidenceContractRelatesAnything(contract)) return;
        var roots = std.ArrayList(NodeId).empty;
        defer roots.deinit(self.allocator);
        for (subst) |slot| if (slot == .node) try roots.append(self.allocator, slot.node);
        if (roots.items.len == 0 or !self.draft.interface_replay.use_finished_summaries) {
            return try self.relateEvidenceContractsAt(schema, subst, contract);
        }
        const pool = schema.view.templates.evidence_params_pool;
        if (schema.params_start > pool.len or schema.params.len > pool.len - schema.params_start or
            schema.params.ptr != pool[schema.params_start..].ptr)
        {
            Common.invariant("scheme requirements were not the checked requirement row they named");
        }

        var scratch = std.heap.ArenaAllocator.init(self.allocator);
        defer scratch.deinit();
        const input = try InterfaceConstraints.capture(self.graph, scratch.allocator(), roots.items);
        const shape = try input.identityInto(self.graph, scratch.allocator());
        const request_bytes = try scratch.allocator().alloc(u8, shape.bytes.len + subst.len);
        @memcpy(request_bytes[0..shape.bytes.len], shape.bytes);
        for (subst, request_bytes[shape.bytes.len..]) |slot, *byte| byte.* = if (slot == .checked_error) 1 else 0;
        const request: InterfaceConstraints.Identity = .{ .bytes = request_bytes, .leaves = shape.leaves };
        const evidence = try self.builder.constFnEvidence(rootEvidence(self.owner_template, contract));
        const address: InterfaceReplayAddress = .{
            .kind = .evidence_contracts,
            .family = .{
                .module = schema.view.key.bytes,
                .proc_base = schema.params_start,
                .template = @intCast(schema.params.len),
                .method_scope = self.method_scope.key.bytes,
                .source_fn_key = if (schema.root) |root| schema.view.types.rootKey(root).bytes else @splat(0),
            },
            .evidence_digest = evidence.digest.bytes,
            .input_digest = interfaceRequestBucket(request.bytes),
        };
        var verify_summary: ?InterfaceSummary = null;
        if (try self.findInterfaceSummary(address, evidence, request)) |summary| {
            self.builder.count("interface_summary_hits");
            if (std.debug.runtime_safety and self.builder.diagnostics != null and self.builder.interface_summary_checks < 16) {
                self.builder.interface_summary_checks += 1;
                self.builder.count("interface_summary_verifications");
                verify_summary = summary;
            } else {
                switch (summary) {
                    .unchanged => self.builder.count("interface_summary_unchanged_hits"),
                    .constraints => |constraints| {
                        for (try constraints.instantiate(self.graph), roots.items) |produced, root| {
                            try self.graph.unify(produced, root);
                        }
                    },
                }
                return;
            }
        }
        self.builder.count("interface_summary_expansions");
        // Relate independent copies of the substitution's cells, so unrelated
        // caller state cannot enter the retained result.
        const detached = try input.instantiate(self.graph);
        const detached_subst = try self.graph.arena().dupe(SubstSlot, subst);
        var next_root: usize = 0;
        for (detached_subst) |*slot| if (slot.* == .node) {
            slot.* = .{ .node = detached[next_root] };
            next_root += 1;
        };
        try self.relateEvidenceContractsAt(schema, detached_subst, contract);
        const constraints = try InterfaceConstraints.capture(self.graph, scratch.allocator(), detached);
        const summary: InterfaceSummary = if (try (try constraints.identityInto(self.graph, scratch.allocator())).eql(shape, self.typeStore(), self.nameStore()))
            .unchanged
        else
            .{ .constraints = constraints };
        if (verify_summary) |expected| {
            if (!try expected.equivalent(summary, input, self.graph, scratch.allocator())) {
                Common.compilerBug("cached evidence contract relations disagreed with a fresh expansion");
            }
        } else {
            _ = try self.insertInterfaceSummary(.{
                .address = address,
                .evidence = evidence,
                .request = request,
                .summary = summary,
            });
        }
        for (detached, roots.items) |produced, root| try self.graph.unify(produced, root);
    }

    fn relateEvidenceContractsAt(
        self: *BodyContext,
        schema: SchemeRequirements,
        subst: SpecSubstitution,
        contract: []const SpecEvidence,
    ) Allocator.Error!void {
        var checked_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, schema.view, self.method_scope, self.owner_template, self.graph, self.draft);
        defer checked_ctx.deinit();
        try checked_ctx.seedSubstitution(schema, subst);
        try self.relateMaterializedEvidenceConstraints(&checked_ctx, schema, contract);
    }

    /// Relate a selected target's callable to the constraint it satisfies,
    /// instantiated over the request's substitution in `scheme_ctx`.
    fn relateTargetToConstraint(
        self: *BodyContext,
        target: *const SpecEvidenceTarget,
        scheme_ctx: *BodyContext,
        param: static_dispatch.EvidenceParamRecord,
    ) Allocator.Error!void {
        const constraint_node = try scheme_ctx.instNode(param.callable_ty);
        const root_view = if (target.instantiation) |instantiation| instantiation.view else target.view;
        const root_fn_ty = if (target.instantiation) |instantiation| instantiation.callable_ty else target.target.callable_ty;
        const reachability = dispatchTargetAdapterReachability(target.target);
        const owner = switch (target.target.kind) {
            .procedure => |procedure| procedure.template,
            .local_proc => |local| self.localMethodOwnerTemplate(.{
                .view = target.view,
                .target = target.target,
                .local_proc_context = target.local_proc_context,
            }, local),
            .structural => unreachable,
        };
        var scratch = std.heap.ArenaAllocator.init(self.allocator);
        defer scratch.deinit();
        const input = try InterfaceConstraints.capture(self.graph, scratch.allocator(), &.{constraint_node});
        const request = try input.identityInto(self.graph, scratch.allocator());
        // This relation consumes only the selected checked signature, not its
        // nested dispatch evidence. Its source identity and adapter rule fully
        // determine the operation over the complete input constraint.
        const evidence = StoredConstFnEvidence.empty();
        const address: InterfaceReplayAddress = .{
            .kind = switch (reachability) {
                .adapter_reachable => .method_contract,
                .no_adapter => .local_method_contract,
            },
            .family = DraftTemplateFamilyAddress.init(owner, self.method_scope.key, root_view.types.rootKey(root_fn_ty)),
            .evidence_digest = @splat(0),
            .input_digest = interfaceRequestBucket(request.bytes),
        };
        const use_summaries = self.draft.interface_replay.use_finished_summaries;
        if (use_summaries) {
            if (try self.findInterfaceSummary(address, evidence, request)) |summary| {
                switch (summary) {
                    .unchanged => {},
                    .constraints => |constraints| try self.graph.unify((try constraints.instantiate(self.graph))[0], constraint_node),
                }
                return;
            }
        }
        // Relate an independent copy, so unrelated caller state cannot enter
        // the retained result. Open variables remain fresh on each replay.
        const detached = (try input.instantiate(self.graph))[0];
        const target_node = try self.instantiateEvidenceTargetSignature(target, address.family);
        try self.relateEvidenceTargetRootToRequest(root_view, root_fn_ty, target_node, detached, reachability);
        if (use_summaries) {
            const constraints = try InterfaceConstraints.capture(self.graph, scratch.allocator(), &.{detached});
            const summary: InterfaceSummary = if (try (try constraints.identityInto(self.graph, scratch.allocator())).eql(request, self.typeStore(), self.nameStore()))
                .unchanged
            else
                .{ .constraints = constraints };
            _ = try self.insertInterfaceSummary(.{
                .address = address,
                .evidence = evidence,
                .request = request,
                .summary = summary,
            });
        }
        try self.graph.unify(detached, constraint_node);
    }

    /// A checked procedure signature is independent of the request it will
    /// constrain. Snapshot its construction once, then instantiate fresh open
    /// cells for each relation, preserving independent callable evidence.
    fn instantiateEvidenceTargetSignature(
        self: *BodyContext,
        target: *const SpecEvidenceTarget,
        family: DraftTemplateFamilyAddress,
    ) Allocator.Error!NodeId {
        const cacheable = target.target.kind == .procedure and self.draft.interface_replay.use_finished_summaries;
        const address: InterfaceReplayAddress = .{
            .kind = .method_signature,
            .family = family,
            .evidence_digest = @splat(0),
            .input_digest = @splat(0),
        };
        const evidence = StoredConstFnEvidence.empty();
        const request: InterfaceConstraints.Identity = .{ .bytes = &.{}, .leaves = &.{} };
        if (cacheable) {
            if (try self.findInterfaceSummary(address, evidence, request)) |summary| {
                return switch (summary) {
                    .constraints => |constraints| (try constraints.instantiate(self.graph))[0],
                    .unchanged => Common.invariant("checked method signature snapshot had no root"),
                };
            }
        }
        const node = if (target.instantiation) |instantiation| blk: {
            var instantiation_ctx = try BodyContext.initWithMethodScope(
                self.allocator,
                self.builder,
                instantiation.view,
                self.method_scope,
                self.owner_template,
                self.graph,
                self.draft,
            );
            defer instantiation_ctx.deinit();
            break :blk try instantiation_ctx.instNode(instantiation.callable_ty);
        } else blk: {
            const lookup: MethodLookup = .{
                .view = target.view,
                .target = target.target,
                .local_proc_context = target.local_proc_context,
            };
            var target_ctx = try self.methodTargetContext(lookup);
            defer target_ctx.deinit();
            break :blk try target_ctx.instNode(lookup.target.callable_ty);
        };
        if (cacheable) {
            var scratch = std.heap.ArenaAllocator.init(self.allocator);
            defer scratch.deinit();
            _ = try self.insertInterfaceSummary(.{
                .address = address,
                .evidence = evidence,
                .request = request,
                .summary = .{ .constraints = try InterfaceConstraints.capture(self.graph, scratch.allocator(), &.{node}) },
            });
        }
        return node;
    }

    /// Relate a checked structural codec's callable to the scheme constraint
    /// it discharges. The checker validated the derivation at exactly this
    /// callable, so relating it binds every quantified variable the
    /// constraint reaches, including those absent from the scheme root: a
    /// parser's error row, for one, is reachable only through its constraint.
    fn relateStructuralEvidenceToConstraint(
        self: *BodyContext,
        structural: CheckedSpecStructuralEvidence,
        scheme_ctx: *BodyContext,
        param: static_dispatch.EvidenceParamRecord,
    ) Allocator.Error!void {
        var evidence_ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self.builder,
            structural.view,
            self.method_scope,
            self.owner_template,
            self.graph,
            self.draft,
        );
        defer evidence_ctx.deinit();
        evidence_ctx.instantiation.closed_types = .{ .leaves = try self.graph.newLeafScope() };
        const evidence_node = try evidence_ctx.instNode(structural.evidence.callable_ty);
        const constraint_node = try scheme_ctx.instNode(param.callable_ty);
        try relateRequestComponent(self.graph, evidence_node, constraint_node);
    }

    /// Parameters that retain the checked target's exact callable instantiation
    /// to bind variables absent from the scheme root. This classifies retained
    /// producer data, not which target signatures need relating: a target whose
    /// receiver is callable-root reachable can still bind other variables through
    /// its method signature when a materialized contract is consumed.
    fn evidenceParamRequiresConstraintRelation(param: static_dispatch.EvidenceParamRecord) bool {
        return switch (param.source) {
            .scheme_requirement, .constraint_callable, .use_site_only => true,
            .scheme_callable, .explicit_default, .erased_row_remainder => false,
        };
    }

    /// The requirement on a receiver cell that no target relation resolved: the
    /// enclosing specialization's requirement when the cell is one of its own
    /// quantified variables, the checker's literal default for a defaulted
    /// receiver (derived on a detached cell so the request stays open until
    /// a caller constrains it), or the structural or vacuous evidence a
    /// shape without a method owner admits.
    fn deriveOpenRequirement(
        self: *BodyContext,
        view: ModuleView,
        param: static_dispatch.EvidenceParamRecord,
        node: NodeId,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error!SpecEvidence {
        if (self.forwardedRequirement(node, view.names, param.method)) |forwarded| return forwarded;
        const default_phase: ?checked.NumericDefaultPhase = switch ((try self.graph.content(node))) {
            .redirect, .leaf => unreachable,
            .unresolved => |variable| variable.numeric_default_phase,
            .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => null,
        };
        if (default_phase) |phase| {
            if (checked.literal_defaulting.defaultTargetForPhase(phase)) |target| {
                const primitive: Type.Primitive = switch (target) {
                    .dec => .dec,
                    .str => .str,
                };
                const default_node = try self.graph.newNode(.{ .primitive = primitive });
                return try self.synthesizeComponentEvidenceAtNodeForPurpose(view, param.method, param.structural, default_node, purpose);
            }
        }
        return try self.synthesizeComponentEvidenceAtNodeForPurpose(view, param.method, param.structural, node, purpose);
    }

    /// The enclosing frame entry that already answers `method` for the
    /// cell `node` shares with a quantified variable of an enclosing scheme:
    /// a requirement on a still-open cell inside a body is the enclosing
    /// specialization's requirement on that same cell. Method IDs belong to
    /// their checked name store, so translate once per frame before comparing.
    fn forwardedRequirement(self: *BodyContext, node: NodeId, method_names: *const names.NameStore, method: names.MethodNameId) ?SpecEvidence {
        var frame: ?*const EvidenceChain = &self.evidence;
        while (frame) |current| : (frame = current.parent) {
            const schema = current.schema orelse continue;
            if (current.subst.len != schema.scheme_vars.len or current.vector.len != schema.params.len) {
                Common.invariant("evidence frame substitution or vector length differed from its scheme");
            }
            const frame_method = if (schema.view.names == method_names)
                method
            else
                schema.view.names.lookupMethodName(method_names.methodNameText(method)) orelse continue;
            for (schema.params, 0..) |param, k| {
                if (param.method != frame_method) continue;
                const receiver_slot = param.slot orelse continue;
                const slot = switch (current.subst[receiver_slot]) {
                    .node => |slot_node| slot_node,
                    .checked_error => continue,
                };
                if (!self.graph.sameClass(slot, node)) continue;
                return current.vector[k];
            }
        }
        return null;
    }

    /// Select the nested-evidence half of an evidence-slot reuse. Independent
    /// rank-1 callables derive callable-owned evidence from their own relation,
    /// but keep evidence owned entirely by the selected target. A recorded
    /// where-method use may also keep the slot's resolved vector: its checker
    /// instantiation copied only signature structure, sharing every
    /// evidence-bearing non-marker leaf.
    fn targetProcedureEvidenceSchema(
        self: *BodyContext,
        target: *const SpecEvidenceTarget,
    ) static_dispatch.ProcedureEvidenceSchema {
        const params = switch (target.target.kind) {
            .procedure => |procedure| blk: {
                const template = target.view.templates.get(procedure.template.template);
                break :blk target.view.templates.evidenceParams(&template);
            },
            .local_proc => |local| self.scopeSchema(target.view, local.dispatch_scope).params,
            .structural => Common.invariant("structural evidence target reached callable nested-evidence classification"),
        };
        return static_dispatch.procedureEvidenceSchema(params);
    }

    const DependentCallableEvidenceError = error{RequiresRecordSynthesis};

    fn dependentCallableNestedEvidenceForSchema(
        dependent: anytype,
        nested: NestedSpecEvidence,
        schema: static_dispatch.ProcedureEvidenceSchema,
    ) DependentCallableEvidenceError!NestedSpecEvidence {
        if (dependent.reuse_slot_nested_evidence and !dependent.independent_callable) {
            Common.invariant("checked dispatch requested slot nested evidence without an independent callable");
        }
        if (dependent.independent_callable and !dependent.reuse_slot_nested_evidence) {
            return switch (schema) {
                .from_target => nested,
                .requires_record => error.RequiresRecordSynthesis,
                .none, .from_callable => .synthesize,
            };
        }
        return nested;
    }

    fn dependentCallableNestedEvidenceChecked(
        self: *BodyContext,
        dependent: anytype,
        target: *const SpecEvidenceTarget,
    ) DependentCallableEvidenceError!NestedSpecEvidence {
        const schema = if (dependent.independent_callable and !dependent.reuse_slot_nested_evidence)
            self.targetProcedureEvidenceSchema(target)
        else
            static_dispatch.ProcedureEvidenceSchema.none;
        return dependentCallableNestedEvidenceForSchema(dependent, target.nested, schema);
    }

    fn dependentCallableNestedEvidence(
        self: *BodyContext,
        dependent: anytype,
        target: *const SpecEvidenceTarget,
    ) NestedSpecEvidence {
        if (selectCallableContract(.{ .target = target }, dependent.callable_contract)) |contract| {
            return switch (contract) {
                .target => |selected| selected.nested,
                .structural, .from_callable, .from_scheme, .unreachable_value, .checked_error => Common.invariant("callable target contract selected non-callable evidence"),
            };
        }
        return self.dependentCallableNestedEvidenceChecked(dependent, target) catch
            Common.invariant("independent dispatch callable attempted to synthesize SchemeUseRecord-supplied nested evidence");
    }

    /// The requirement-target contract a checked dispatch plan recorded for
    /// its target's own requirements: a direct plan's resolved nested
    /// entries. Every other edge derives the target's evidence from the
    /// callable alone.
    fn dispatchTargetContract(self: *BodyContext, plan: static_dispatch.StaticDispatchCallPlan) ?EvidenceContract {
        return switch (plan.resolution) {
            .direct_closed, .direct_parametric => |direct| blk: {
                const node = self.view.static_dispatch_plans.evidenceNode(direct.evidence);
                break :blk switch (node.nested) {
                    .resolved => .{ .view = self.view, .entries = self.view.static_dispatch_plans.nestedEvidence(node) },
                    .from_callable => null,
                };
            },
            .evidence_dependent, .structural, .checked_error, .@"unreachable" => null,
            .direct_pending => Common.invariant("unfinalized direct call reached Monotype"),
        };
    }

    /// The producer-authored evidence for the target selected by a dispatch
    /// plan. Direct plans point into the checked module. Evidence-dependent
    /// plans consume the fully materialized target entry supplied by their
    /// enclosing specialization; an independent callable deliberately keeps
    /// only that entry's target identity and derives against this call's own
    /// callable relation.
    fn dispatchTargetEvidenceSource(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
    ) TargetEvidenceSource {
        return switch (plan.resolution) {
            .direct_closed, .direct_parametric => if (self.dispatchTargetContract(plan)) |contract|
                .{ .checked = contract }
            else
                .derive,
            .evidence_dependent => |dependent| blk: {
                const entry = self.evidence.at(dependent.index) orelse
                    Common.invariant("dispatch target evidence was absent from its lexical chain");
                const target = switch (entry) {
                    .target => |target| target,
                    .structural, .from_callable, .from_scheme, .unreachable_value, .checked_error => Common.invariant("dispatch target evidence was not a callable target"),
                };
                break :blk switch (self.dependentCallableNestedEvidence(dependent, target)) {
                    .resolved => |resolved| .{ .materialized_contract = resolved },
                    .synthesize => .derive,
                };
            },
            .direct_pending => Common.invariant("unfinalized direct call reached Monotype"),
            .structural, .checked_error, .@"unreachable" => Common.invariant("non-callable dispatch requested target evidence"),
        };
    }

    /// The substitution of a direct dispatch target's scheme. A checked
    /// record substitutes the scheme the dispatch edge instantiated. When the
    /// evidence node says the substitution derives from its callable (a target
    /// reached through an exact procedure alias, or a numeric default owner),
    /// the target's own scheme is instantiated at the dispatch's callable
    /// instead.
    fn directDispatchTargetSubstitution(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
        lookup: MethodLookup,
        callable_node: NodeId,
    ) Allocator.Error!?SpecSubstitution {
        const direct = switch (plan.resolution) {
            .direct_closed, .direct_parametric => |direct| direct,
            .evidence_dependent, .structural, .checked_error, .@"unreachable", .direct_pending => return try self.dispatchTargetSubstitution(plan),
        };
        switch (self.view.static_dispatch_plans.evidenceNode(direct.evidence).instantiation) {
            .monomorphic, .callable => return try self.dispatchTargetSubstitution(plan),
            .derived_from_callable => {},
        }
        const procedure = switch (lookup.target.kind) {
            .procedure => |procedure| procedure,
            .local_proc, .structural => Common.invariant("a callable-derived substitution reached a non-procedure method target"),
        };
        const template = lookup.view.templates.get(procedure.template.template);
        var target_ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self.builder,
            lookup.view,
            self.method_scope,
            procedure.template,
            self.graph,
            self.draft,
        );
        defer target_ctx.deinit();
        const subst = try target_ctx.substitutionFromCheckedTypes(lookup.view, templateSchemaIn(lookup.view, &template).scheme_vars);
        try relateFunctionRequestInterface(self.graph, try target_ctx.instNode(template.checked_fn_root), callable_node);
        return subst;
    }

    fn dispatchTargetSubstitution(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
    ) Allocator.Error!?SpecSubstitution {
        const direct = switch (plan.resolution) {
            .direct_closed, .direct_parametric => |direct| direct,
            .evidence_dependent, .structural, .checked_error, .@"unreachable" => return null,
            .direct_pending => Common.invariant("unfinalized direct call reached Monotype"),
        };
        const node = self.view.static_dispatch_plans.evidenceNode(direct.evidence);
        const table = self.view.static_dispatch_plans;
        const start: usize = node.subst.start;
        const len: usize = node.subst.len;
        if (start > table.site_substitutions.len or len > table.site_substitutions.len - start) {
            Common.invariant("direct dispatch target substitution range was outside its checked module");
        }
        return try self.substitutionFromCheckedTypes(self.view, table.site_substitutions[start .. start + len]);
    }

    /// Seed a selected target's scheme context with the substitution checking
    /// applied where it selected the target, as a direct target specializes
    /// under its recorded substitution. The checked types are instantiated
    /// together in one context of the selecting module, so variables they
    /// share stay shared, and relating the target's root to the request then
    /// refines the slots that root reaches.
    fn seedCheckedTargetSubstitution(
        self: *BodyContext,
        target_ctx: *BodyContext,
        schema: SchemeRequirements,
        substitution: CheckedTargetSubstitution,
    ) Allocator.Error!void {
        var site_ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self.builder,
            substitution.view,
            self.method_scope,
            self.owner_template,
            self.graph,
            self.draft,
        );
        defer site_ctx.deinit();
        try target_ctx.seedSubstitution(schema, try site_ctx.substitutionFromCheckedTypes(substitution.view, substitution.tys));
    }

    /// The requirement contract a checked iterator dispatch call recorded for
    /// its target, mirroring `dispatchTargetContract`.
    fn iteratorCallContract(self: *BodyContext, call: static_dispatch.IteratorDispatchCall) ?EvidenceContract {
        return switch (call.resolution) {
            .direct_closed, .direct_parametric => |direct| blk: {
                const node = self.view.static_dispatch_plans.evidenceNode(direct.evidence);
                break :blk switch (node.nested) {
                    .resolved => .{ .view = self.view, .entries = self.view.static_dispatch_plans.nestedEvidence(node) },
                    .from_callable => null,
                };
            },
            .evidence_dependent, .structural, .checked_error, .@"unreachable" => null,
            .direct_pending => Common.invariant("unfinalized iterator direct call reached Monotype"),
        };
    }

    fn iteratorTargetEvidenceSource(
        self: *BodyContext,
        call: static_dispatch.IteratorDispatchCall,
    ) TargetEvidenceSource {
        return switch (call.resolution) {
            .direct_closed, .direct_parametric => if (self.iteratorCallContract(call)) |contract|
                .{ .checked = contract }
            else
                .derive,
            .evidence_dependent => |dependent| blk: {
                const entry = self.evidence.at(dependent.index) orelse
                    Common.invariant("iterator target evidence was absent from its lexical chain");
                const target = switch (entry) {
                    .target => |target| target,
                    .structural, .from_callable, .from_scheme, .unreachable_value, .checked_error => Common.invariant("iterator target evidence was not a callable target"),
                };
                break :blk switch (self.dependentCallableNestedEvidence(dependent, target)) {
                    .resolved => |resolved| .{ .materialized_contract = resolved },
                    .synthesize => .derive,
                };
            },
            .direct_pending => Common.invariant("unfinalized iterator direct call reached Monotype"),
            .structural, .checked_error, .@"unreachable" => Common.invariant("non-callable iterator dispatch requested target evidence"),
        };
    }

    /// A consumed evidence resolution: a concrete target or the checker's
    /// structural decision.
    const EvidenceResolved = union(enum) {
        target: MethodLookup,
        structural: SpecStructuralEvidence,
    };

    /// The plan's checked or edge-supplied resolution. Null is reserved for
    /// checked-error and explicitly unreachable dispatches.
    fn evidenceResolution(self: *BodyContext, plan: static_dispatch.StaticDispatchCallPlan) ?EvidenceResolved {
        switch (plan.resolution) {
            .direct_closed, .direct_parametric => |direct| {
                const node = self.view.static_dispatch_plans.evidenceNode(direct.evidence);
                var lookup = self.methodLookupForResolvedTarget(node.target);
                lookup.instantiation = switch (node.instantiation) {
                    .monomorphic => null,
                    .callable, .derived_from_callable => |callable_ty| .{ .view = self.view, .callable_ty = callable_ty },
                };
                return .{ .target = lookup };
            },
            .evidence_dependent => |dependent| {
                const entry = self.evidence.at(dependent.index) orelse
                    Common.invariant("dispatch resolution evidence was absent from its lexical chain");
                return switch (selectCallableContract(entry, dependent.callable_contract) orelse entry) {
                    .target => |target| .{
                        .target = .{
                            .view = target.view,
                            .target = target.target,
                            .instantiation = if (dependent.independent_callable and selectCallableContract(entry, dependent.callable_contract) == null)
                                null
                            else
                                target.instantiation,
                            .substitution = if (dependent.independent_callable)
                                null
                            else
                                target.substitution,
                            .local_proc_context = target.local_proc_context,
                        },
                    },
                    .structural => |derivation| .{ .structural = derivation },
                    // Unreachable and checked-error dispatches crash before
                    // target resolution.
                    .from_callable, .from_scheme, .unreachable_value, .checked_error => null,
                };
            },
            .structural => |derivation| return .{ .structural = .{
                .derivation = derivation,
                .checked = switch (derivation.kind()) {
                    .parser, .encoder => .{
                        .view = self.view,
                        .evidence = .{
                            .derivation = derivation,
                            .dispatcher_ty = plan.dispatcher_ty,
                            .callable_ty = plan.callable_ty,
                            .generated_codec_derivation = plan.generated_codec_derivation orelse
                                Common.invariant("direct structural codec plan had no checked derivation contract"),
                        },
                    },
                    .equality, .hash, .map, .map_effectful => null,
                },
            } },
            .direct_pending => Common.invariant("unfinalized direct call reached Monotype"),
            .checked_error, .@"unreachable" => return null,
        }
    }

    /// Restore the exact lexical dispatch vector captured with a generated
    /// runtime function. A direct structural source plan needs no vector: its
    /// checked plan itself owns the structural evidence and codec contract.
    fn restoreGeneratedRuntimeEvidence(
        self: *BodyContext,
        fn_value: check.ConstStore.ConstFn,
        plan: static_dispatch.StaticDispatchCallPlan,
    ) Allocator.Error!void {
        if (fn_value.evidence_frames.len != 0) {
            self.evidence = try self.materializeConstFnEvidence(fn_value);
            try self.replayStoredEvidenceRelations(self.evidence);
            return;
        }
        if (fn_value.evidence.len != 0 or fn_value.evidence_frame_head != null) {
            Common.invariant("stored generated runtime had malformed evidence topology");
        }
        switch (plan.resolution) {
            .structural => {},
            .evidence_dependent => Common.invariant("evidence-dependent stored generated runtime had no retained evidence"),
            .direct_closed, .direct_parametric => Common.invariant("stored generated runtime source plan resolved to a callable target"),
            .direct_pending => Common.invariant("unfinalized direct call reached Monotype"),
            .checked_error, .@"unreachable" => Common.invariant("stored generated runtime had a rejected dispatch plan"),
        }
    }

    fn activateCodecContractForPlan(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
        callable_node: NodeId,
        shape_node: NodeId,
    ) Allocator.Error!void {
        const resolution = self.evidenceResolution(plan) orelse
            Common.invariant("generated runtime source plan had no structural evidence");
        const structural = switch (resolution) {
            .structural => |structural| structural,
            .target => Common.invariant("generated runtime source plan resolved to a callable target"),
        };
        self.active_codec_contract = try self.instantiateCodecContract(
            structural,
            callable_node,
            shape_node,
        );
    }

    const DispatchCrashReason = enum { unreachable_value, checked_error };

    /// The crash a dispatch that cannot run lowers to. A rejected dispatch is
    /// checked-error code; an unreachable one is an ordinary crash.
    fn dispatchCrashData(self: *BodyContext, reason: DispatchCrashReason) Allocator.Error!BodyExprData {
        return switch (reason) {
            .unreachable_value => .{ .crash = try self.addStringLiteral("dispatch on a value that can never exist") },
            .checked_error => .{ .checked_error = try self.addStringLiteral("method dispatch failed to check") },
        };
    }

    /// A checked dispatch whose resolution names a callable target or structural
    /// derivation. Callable, dispatcher, and operand type instantiation accepts
    /// this wrapper instead of a raw plan. A rejected non-returning dispatch
    /// takes `DispatchRuntimePlan.crash`, so Monotype emits an ordinary Roc
    /// runtime crash without instantiating the rejected callable's type.
    const CallableDispatchPlan = struct {
        plan: static_dispatch.StaticDispatchCallPlan,
        operands: []const static_dispatch.StaticDispatchOperand,
    };

    /// The required gate before any dispatch type instantiation. `crash` means
    /// the dispatch emits an ordinary Roc runtime crash and returns no value.
    const DispatchRuntimePlan = union(enum) {
        callable: CallableDispatchPlan,
        crash: DispatchCrashReason,
    };

    fn dispatchRuntimePlan(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
    ) DispatchRuntimePlan {
        if (self.dispatchCrashReason(plan.resolution)) |reason| return .{ .crash = reason };
        return .{ .callable = .{
            .plan = plan,
            .operands = plan.argsSlice(self.view.static_dispatch_plans),
        } };
    }

    /// A stored generated parser/encoder runtime exists only after compile-time
    /// evaluation successfully consumed its constructor dispatch. ConstStore
    /// intentionally stores no evidence vector for these generated runtimes;
    /// their explicit runtime function tag is the producer-owned proof that a
    /// checked constraint plan is callable. Rejected plan-level resolutions can
    /// never provide that proof.
    fn requireStoredRuntimeCallableDispatchPlan(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
    ) CallableDispatchPlan {
        switch (plan.resolution) {
            .checked_error, .@"unreachable" => Common.invariant("stored generated runtime had a rejected dispatch plan"),
            .direct_pending => Common.invariant("unfinalized direct call reached Monotype"),
            .direct_closed, .direct_parametric, .evidence_dependent, .structural => {},
        }
        return .{
            .plan = plan,
            .operands = plan.argsSlice(self.view.static_dispatch_plans),
        };
    }

    /// Whether checking decided this is a rejected non-returning dispatch: its
    /// dispatcher is a value no edge can supply (unreachable), or checking
    /// rejected the requirement (a reported missing method). Monotype emits an
    /// ordinary Roc runtime crash instead of a dispatch call for both cases.
    fn dispatchCrashReason(self: *BodyContext, resolution: static_dispatch.CheckedCallResolution) ?DispatchCrashReason {
        return switch (resolution) {
            .@"unreachable" => .unreachable_value,
            .checked_error => .checked_error,
            .evidence_dependent => |dependent| if (self.evidence.at(dependent.index)) |entry| switch (selectCallableContract(entry, dependent.callable_contract) orelse entry) {
                .from_callable, .unreachable_value => .unreachable_value,
                .from_scheme => Common.invariant("abstract scheme requirement reached executable dispatch without use evidence"),
                .checked_error => .checked_error,
                .target, .structural => null,
            } else Common.invariant("dispatch runtime evidence was absent from its lexical chain"),
            .direct_pending => Common.invariant("unfinalized direct call reached Monotype"),
            .direct_closed, .direct_parametric, .structural => null,
        };
    }

    fn methodLookupForResolvedTarget(
        self: *BodyContext,
        target: static_dispatch.MethodTarget,
    ) MethodLookup {
        return switch (target.kind) {
            .procedure => |procedure| .{
                .view = self.builder.moduleForDigest(names.procTemplateModuleDigest(procedure.template)),
                .target = target,
            },
            .local_proc => .{
                .view = self.view,
                .target = target,
            },
            .structural => Common.invariant("structural method registry result reached callable checked evidence"),
        };
    }

    fn methodTargetContext(
        self: *BodyContext,
        lookup: MethodLookup,
    ) Allocator.Error!BodyContext {
        const owner_template = switch (lookup.target.kind) {
            .procedure => |procedure| procedure.template,
            .local_proc => |local| self.localMethodOwnerTemplate(lookup, local),
            .structural => Common.invariant("structural method registry result has no callable body context"),
        };
        return BodyContext.initWithMethodScope(self.allocator, self.builder, lookup.view, self.method_scope, owner_template, self.graph, self.draft);
    }

    fn localMethodOwnerTemplate(
        self: *BodyContext,
        lookup: MethodLookup,
        local: static_dispatch.LocalProcedureMethodTarget,
    ) names.ProcTemplate {
        if (lookup.local_proc_context) |context_id| {
            return self.validateLocalProcContext(
                context_id,
                lookup.view.key.bytes,
                local.binder,
                local.expr,
                local.context_anchor,
            ).owner_template;
        }
        // Without a lowered declaration instance, the target's checked
        // declaration names the procedure template whose body declares it.
        for (lookup.view.nested_proc_sites.sites) |site| {
            if (site.checked_expr == null or site.checked_expr.? != local.expr) continue;
            return switch (site.owner) {
                .template => |template| template,
                .default_root => Common.invariant("local method declaration had no owning procedure template"),
            };
        }
        Common.invariant("local method declaration had no checked nested procedure site");
    }

    /// `relateFunctionRequestInterface` for a resolved dispatch target. When
    /// the implementation publishes a closed result row and the request's row
    /// includes it, the two relate component-wise without unifying the rows,
    /// so the request survives to template completion where the widening
    /// adapter is generated (design.md "Result-Row Widening Adapter").
    fn relateDispatchTargetRequestInterface(
        self: *BodyContext,
        lookup: MethodLookup,
        target_node: NodeId,
        request_node: NodeId,
    ) Allocator.Error!void {
        if (try relateClosedResultRowRequestInterface(
            self.graph,
            lookup.view,
            lookup.target.callable_ty,
            target_node,
            request_node,
            dispatchTargetAdapterReachability(lookup.target),
        )) return;
        try relateFunctionRequestInterface(self.graph, target_node, request_node);
    }

    fn methodTargetNodeFromPlan(
        self: *BodyContext,
        lookup: MethodLookup,
        plan_ctx: *BodyContext,
        plan_callable_ty: checked.CheckedTypeId,
    ) Allocator.Error!NodeId {
        var target_ctx = try self.methodTargetContext(lookup);
        defer target_ctx.deinit();
        const target_node = try target_ctx.instantiateTargetFromPlanNode(
            lookup.target.callable_ty,
            plan_ctx,
            plan_callable_ty,
            dispatchTargetAdapterReachability(lookup.target),
        );
        if (lookup.instantiation) |instantiation| {
            var edge_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, instantiation.view, self.method_scope, self.owner_template, self.graph, self.draft);
            defer edge_ctx.deinit();
            const edge_node = try edge_ctx.instNode(instantiation.callable_ty);
            try self.relateDispatchTargetRequestInterface(lookup, target_node, edge_node);
        }
        return target_node;
    }

    fn generatedIteratorMethodRequestNode(
        self: *BodyContext,
        lookup: MethodLookup,
        public_target_node: NodeId,
        request_node: NodeId,
        operands: []const static_dispatch.StaticDispatchOperand,
    ) Allocator.Error!?NodeId {
        const procedure = self.iteratorProcedureForMethodTarget(lookup.target) orelse return null;
        const checked_args = try self.checkedExprDispatchOperands(operands) orelse return null;
        defer self.allocator.free(checked_args);
        const private_node = (try self.generatedIteratorFunctionNode(
            procedure,
            public_target_node,
            request_node,
            checked_args,
        )) orelse return null;
        try self.graph.registerRequestSourceInterface(private_node, public_target_node);
        try relateFunctionRequestInterface(self.graph, public_target_node, private_node);
        return private_node;
    }

    fn generatedIteratorPlanRequestNode(
        self: *BodyContext,
        lookup: MethodLookup,
        public_target_node: NodeId,
        request_node: NodeId,
        operands: []const static_dispatch.IteratorDispatchOperand,
    ) Allocator.Error!?NodeId {
        const procedure = self.iteratorProcedureForMethodTarget(lookup.target) orelse return null;
        const checked_args = try self.checkedExprIteratorDispatchOperands(operands) orelse return null;
        defer self.allocator.free(checked_args);
        const private_node = (try self.generatedIteratorFunctionNode(
            procedure,
            public_target_node,
            request_node,
            checked_args,
        )) orelse return null;
        try self.graph.registerRequestSourceInterface(private_node, public_target_node);
        try relateFunctionRequestInterface(self.graph, public_target_node, private_node);
        return private_node;
    }

    fn checkedExprDispatchOperands(
        self: *BodyContext,
        operands: []const static_dispatch.StaticDispatchOperand,
    ) Allocator.Error!?[]checked.CheckedExprId {
        const checked_args = try self.allocator.alloc(checked.CheckedExprId, operands.len);
        errdefer self.allocator.free(checked_args);
        for (operands, checked_args) |operand, *checked_arg| {
            checked_arg.* = switch (operand) {
                .checked_expr => |expr| expr,
                .generated_interpolation_segments,
                .generated_numeral,
                .generated_quote,
                => {
                    self.allocator.free(checked_args);
                    return null;
                },
            };
        }
        return checked_args;
    }

    fn checkedExprIteratorDispatchOperands(
        self: *BodyContext,
        operands: []const static_dispatch.IteratorDispatchOperand,
    ) Allocator.Error!?[]checked.CheckedExprId {
        const checked_args = try self.allocator.alloc(checked.CheckedExprId, operands.len);
        errdefer self.allocator.free(checked_args);
        for (operands, checked_args) |operand, *checked_arg| {
            checked_arg.* = switch (operand) {
                .checked_expr => |expr| expr,
                .loop_iterator_state => {
                    self.allocator.free(checked_args);
                    return null;
                },
            };
        }
        return checked_args;
    }

    fn methodTargetMonoTypeFromArgs(
        self: *BodyContext,
        lookup: MethodLookup,
        arg_tys: []const Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!Type.TypeId {
        if (self.frozen_sealed_emission) {
            if (try self.frozenCodecCallableFromArgs(lookup, arg_tys, ret_ty)) |prepared| return prepared;
            Common.invariant("sealed structural codec requested an unprepared callable");
        }
        var target_ctx = try self.methodTargetContext(lookup);
        defer target_ctx.deinit();
        return try target_ctx.instantiateTargetCallTypeFromMonoArgs(lookup.target.callable_ty, arg_tys, ret_ty);
    }

    fn withLocalProcContext(self: *BodyContext, lookup: MethodLookup) Allocator.Error!MethodLookup {
        var contextual = lookup;
        switch (lookup.target.kind) {
            .local_proc => |local| {
                const context_id = lookup.local_proc_context orelse
                    try self.localProcContextId(lookup.view, local.binder, local.expr);
                _ = self.validateLocalProcContext(
                    context_id,
                    lookup.view.key.bytes,
                    local.binder,
                    local.expr,
                    local.context_anchor,
                );
                contextual.local_proc_context = context_id;
            },
            .procedure, .structural => if (lookup.local_proc_context != null) {
                Common.invariant("non-local method target carried a local declaration context");
            },
        }
        return contextual;
    }

    fn methodLookupForEvidencePurpose(
        self: *BodyContext,
        lookup: MethodLookup,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error!MethodLookup {
        return switch (purpose) {
            .body_lowering => try self.withLocalProcContext(lookup),
            .specialization_interface, .interface_summary_input => blk: {
                if (lookup.local_proc_context != null) {
                    Common.invariant("checked specialization-interface evidence unexpectedly carried a draft-local context");
                }
                break :blk lookup;
            },
        };
    }

    fn validateLocalProcContext(
        self: *BodyContext,
        context_id: DraftLocalProcContextId,
        module: [32]u8,
        binder: checked.PatternBinderId,
        expr: checked.CheckedExprId,
        context_anchor: ?checked.CheckedStatementId,
    ) LocalProcContext {
        const raw_context = @backingInt(context_id);
        if (raw_context >= self.draft.local_proc_contexts.items.len) {
            Common.invariant("local procedure use referenced an unknown declaration context");
        }
        const context = self.draft.local_proc_contexts.items[raw_context];
        const declaration = context.declaration;
        if (!moduleBytesEqual(declaration.module, module) or declaration.binder != binder or declaration.expr != expr) {
            Common.invariant("local procedure context belonged to a different checked declaration");
        }
        if (context_anchor) |anchor| {
            if (declaration.context_anchor == null or declaration.context_anchor.? != anchor) {
                Common.invariant("local method context belonged to a different checked declaration anchor");
            }
        }
        return context;
    }

    fn synthesizeComponentEvidenceAtNodeForPurpose(
        self: *BodyContext,
        view: ModuleView,
        method: names.MethodNameId,
        structural: ?static_dispatch.StructuralKind,
        component_node: NodeId,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error!SpecEvidence {
        if ((try self.methodOwnerFromNode(component_node))) |owner| {
            if (try self.lookupMethodTarget(owner, view, method)) |result| {
                const found = switch (result) {
                    .rejected => return .checked_error,
                    .target => |found| found,
                };
                if (found.target.kind == .structural) {
                    return .{ .structural = .{ .derivation = structuralDerivationWithoutMap(found.target.kind.structural) } };
                }
                const arena = self.builder.evidence_arena.allocator();
                const target = try arena.create(SpecEvidenceTarget);
                const lookup = try self.methodLookupForEvidencePurpose(found, purpose);
                target.* = .{
                    .view = lookup.view,
                    .target = lookup.target,
                    .instantiation = null,
                    .local_proc_context = lookup.local_proc_context,
                    .nested = .synthesize,
                };
                return .{ .target = target };
            }
            if (structural) |kind| return .{ .structural = .{ .derivation = structuralDerivationWithoutMap(kind) } };
            Common.invariant("compiler-generated graph component owner had no exact checked method target");
        }
        if (try self.nodeIsProvenUninhabited(component_node) or (try self.nodeFinalizesAsUninhabitedLeaf(component_node))) {
            return switch (static_dispatch.unpinnedDispatchResolution(structural)) {
                .structural => .{ .structural = .{ .derivation = structuralDerivationWithoutMap(structural.?) } },
                .unreachable_value => .unreachable_value,
            };
        }
        if (structural) |kind| return .{ .structural = .{ .derivation = structuralDerivationWithoutMap(kind) } };
        Common.invariant("compiler-generated ownerless graph component had no checked structural or uninhabited evidence");
    }

    /// Whether an open leaf can only ever finalize as uninhabited. A checked
    /// variable the checker left unconstrained is bound by nothing but a
    /// specialization request, and requests are seeded before a body is
    /// lowered, so inside a body such a leaf's final content is its recorded
    /// default. Reading that default here keeps dispatch evidence independent
    /// of which callee interfaces have already been related on this path: an
    /// interface replay may close the same cell to that default at any time,
    /// and evidence read before and after it must agree.
    fn nodeFinalizesAsUninhabitedLeaf(self: *BodyContext, node: NodeId) Allocator.Error!bool {
        return switch ((try self.graph.content(node))) {
            .unresolved => |variable| blk: {
                if (variable.numeric_default_phase != null) break :blk false;
                if (variable.row_default) |row_default| break :blk row_default == .empty_tag_union;
                break :blk switch (variable.origin) {
                    .checked_variable => true,
                    .row_extension, .placeholder => false,
                };
            },
            .redirect, .leaf, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => false,
        };
    }

    /// Static-dispatch owner identity available directly from a live graph
    /// node. Aliases are transparent, matching `Type.Store.ownerHead`.
    fn methodOwnerFromNode(
        self: *BodyContext,
        node: NodeId,
    ) Allocator.Error!?static_dispatch.MethodOwner {
        var current = node;
        while (true) switch ((try self.graph.content(current))) {
            .redirect, .leaf => unreachable,
            .primitive => |primitive| return .{ .builtin = checked.builtinOwnerForPrimitive(primitive) },
            .list => return .{ .builtin = .list },
            .box => return .{ .builtin = .box },
            .named => |named| {
                if (named.builtin_owner) |owner| return .{ .builtin = owner };
                if (named.kind != .alias) return .{ .nominal = .{
                    .module = named.def.module,
                    .type_name = named.def.type_name,
                    .source_decl = named.def.source_decl,
                } };
                current = (named.backing orelse return null).node;
            },
            .unresolved,
            .tuple,
            .func,
            .tag_union,
            .record,
            .empty_tag_union,
            .empty_record,
            .erased,
            .zst,
            => return null,
        };
    }

    fn structuralDerivationWithoutMap(kind: static_dispatch.StructuralKind) static_dispatch.StructuralDerivation {
        return switch (kind) {
            .equality => .equality,
            .hash => .hash,
            .parser => .parser,
            .encoder => .encoder,
            .map, .map_effectful => Common.invariant("compiler-generated evidence cannot synthesize a derived map payload selection"),
        };
    }

    fn methodTargetCalleeWithMono(
        self: *BodyContext,
        lookup: MethodLookup,
        callable_mono_ty: Type.TypeId,
    ) Allocator.Error!DraftFnSlot {
        if (self.frozen_sealed_emission) {
            return try self.methodTargetCalleeWithClosedMono(lookup, callable_mono_ty);
        }
        const callable_node = try self.activeNodeFromType(callable_mono_ty);
        return try self.methodTargetCalleeAtNode(lookup, callable_node, null);
    }

    fn methodTargetCalleeWithClosedMono(
        self: *BodyContext,
        lookup: MethodLookup,
        callable_mono_ty: Type.TypeId,
    ) Allocator.Error!DraftFnSlot {
        if (try self.frozenCodecCallee(lookup, callable_mono_ty)) |prepared| return prepared;
        Common.invariant("sealed structural codec requested an unprepared callee");
    }

    fn methodLookupEql(_: *BodyContext, left: MethodLookup, right: MethodLookup) bool {
        return methodLookupIdentityEql(left, right);
    }

    fn frozenCodecCallableFromArgs(
        self: *BodyContext,
        lookup: MethodLookup,
        arg_tys: []const Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!?Type.TypeId {
        const prepared_calls = self.frozen_codec_calls orelse return null;
        for (prepared_calls.calls) |prepared| {
            if (!self.methodLookupEql(prepared.lookup, lookup)) continue;
            const function = self.functionShape(prepared.callable_ty, "prepared codec callable was not a function");
            const prepared_args = self.typeStore().span(function.args);
            if (prepared_args.len != arg_tys.len) continue;
            if (!try self.typeStore().typeEql(self.nameStore(), function.ret, ret_ty)) continue;
            var matches = true;
            for (0..arg_tys.len) |index| {
                if (!try self.typeStore().typeEql(
                    self.nameStore(),
                    GuardedList.at(prepared_args, index),
                    arg_tys[index],
                )) {
                    matches = false;
                    break;
                }
            }
            if (matches) return prepared.callable_ty;
        }
        return null;
    }

    fn frozenCodecCallee(
        self: *BodyContext,
        lookup: MethodLookup,
        callable_ty: Type.TypeId,
    ) Allocator.Error!?DraftFnSlot {
        const prepared_calls = self.frozen_codec_calls orelse return null;
        for (prepared_calls.calls) |prepared| {
            if (!self.methodLookupEql(prepared.lookup, lookup)) continue;
            if (try self.typeStore().typeEql(
                self.nameStore(),
                prepared.callable_ty,
                callable_ty,
            )) return prepared.callee;
        }
        return null;
    }

    fn frozenCustomCodecCallForShape(
        self: *BodyContext,
        kind: CodecKind,
        shape_ty: Type.TypeId,
    ) ?*const FrozenPreparedCodecCall {
        const prepared_calls = self.frozen_codec_calls orelse
            Common.invariant("sealed custom-codec query had no prepared call plan");
        return prepared_calls.customCall(kind, shape_ty);
    }

    fn frozenFormatCodecCall(
        self: *BodyContext,
        kind: CodecKind,
        method_name: []const u8,
    ) Allocator.Error!*const FrozenPreparedCodecCall {
        return try self.frozenFormatCodecCallInner(kind, method_name, null);
    }

    fn frozenFormatCodecCallForShape(
        self: *BodyContext,
        kind: CodecKind,
        method_name: []const u8,
        shape_ty: Type.TypeId,
    ) Allocator.Error!*const FrozenPreparedCodecCall {
        return try self.frozenFormatCodecCallInner(kind, method_name, shape_ty);
    }

    fn frozenFormatCodecCallInner(
        self: *BodyContext,
        kind: CodecKind,
        method_name: []const u8,
        shape_ty: ?Type.TypeId,
    ) Allocator.Error!*const FrozenPreparedCodecCall {
        const prepared_calls = self.frozen_codec_calls orelse
            Common.invariant("sealed format-method query had no prepared call plan");
        return try prepared_calls.formatCall(
            self.typeStore(),
            self.nameStore(),
            kind,
            method_name,
            shape_ty,
        ) orelse Common.invariant("sealed structural codec requested a format method absent from its checked contract");
    }

    /// Apply a checked target root to its live call request: exactly, unless
    /// the request carries a generated private iterator representation, which
    /// only its public interface relates.
    /// A request whose result row includes the target's closed published row
    /// keeps its extra labels here too (design.md "Result-Row Widening
    /// Adapter"); unifying the two rows is what the adapter exists to avoid.
    fn relateEvidenceTargetRootToRequest(
        self: *BodyContext,
        root_view: ModuleView,
        root_fn_ty: checked.CheckedTypeId,
        root_node: NodeId,
        request_fn_node: NodeId,
        reachability: AdapterReachability,
    ) Allocator.Error!void {
        if (try relateClosedResultRowRequestInterface(
            self.graph,
            root_view,
            root_fn_ty,
            root_node,
            request_fn_node,
            reachability,
        )) return;
        if (try self.graph.containsGeneratedPrivate(request_fn_node)) {
            try relateFunctionRequestInterface(self.graph, root_node, request_fn_node);
        } else {
            try self.graph.unify(root_node, request_fn_node);
        }
    }

    /// Request the specialization of a method target at a callable request.
    /// The target's scheme root is instantiated in the target's own context
    /// and related to the request, which binds every quantified variable of
    /// the scheme; the target's evidence is derived from that substitution,
    /// with `contract` (a checked plan's recorded nested entries) supplying
    /// structural contracts.
    fn methodTargetCalleeAtNode(
        self: *BodyContext,
        raw_lookup: MethodLookup,
        request_fn_node: NodeId,
        contract: ?EvidenceContract,
    ) Allocator.Error!DraftFnSlot {
        return try self.methodTargetCalleeAtNodeInner(
            raw_lookup,
            request_fn_node,
            if (contract) |checked_contract| .{ .checked = checked_contract } else .derive,
            .inherit,
        );
    }

    fn methodTargetCalleeAtNodeWithEvidence(
        self: *BodyContext,
        raw_lookup: MethodLookup,
        request_fn_node: NodeId,
        evidence_source: TargetEvidenceSource,
    ) Allocator.Error!DraftFnSlot {
        return try self.methodTargetCalleeAtNodeInner(
            raw_lookup,
            request_fn_node,
            evidence_source,
            .inherit,
        );
    }

    fn methodTargetCalleeAtNodeForCodec(
        self: *BodyContext,
        raw_lookup: MethodLookup,
        request_fn_node: NodeId,
        contract: EvidenceContract,
        codec_contract_anchor: CheckedCodecContractAnchor,
    ) Allocator.Error!DraftFnSlot {
        return try self.methodTargetCalleeAtNodeInner(
            raw_lookup,
            request_fn_node,
            .{ .checked = contract },
            .{ .anchored = codec_contract_anchor },
        );
    }

    /// Format methods with ordinary values and callable arguments need no
    /// enclosing codec contract. Generated writer arguments retain their own
    /// prepared calls; the method's checked callable and evidence fully
    /// determine its specialization.
    fn methodTargetCalleeAtNodeForFormat(
        self: *BodyContext,
        lookup: MethodLookup,
        request_fn_node: NodeId,
        contract: EvidenceContract,
    ) Allocator.Error!DraftFnSlot {
        return try self.methodTargetCalleeAtNodeInner(lookup, request_fn_node, .{ .checked = contract }, .independent);
    }

    fn methodTargetCalleeAtNodeInner(
        self: *BodyContext,
        raw_lookup: MethodLookup,
        request_fn_node: NodeId,
        evidence_source: TargetEvidenceSource,
        codec_contract_selection: CodecContractSelection,
    ) Allocator.Error!DraftFnSlot {
        const lookup = try self.withLocalProcContext(raw_lookup);
        const source_fn_ty = lookup.target.callable_ty;
        const source_fn_key = lookup.view.types.rootKey(source_fn_ty);
        return switch (lookup.target.kind) {
            .procedure => |procedure| blk: {
                const template = lookup.view.templates.get(procedure.template.template);
                const schema = templateSchemaIn(lookup.view, &template);
                var target_ctx = try self.methodTargetContext(lookup);
                defer target_ctx.deinit();
                if (lookup.substitution) |substitution| try self.seedCheckedTargetSubstitution(&target_ctx, schema, substitution);
                const target_root_node = try target_ctx.instNode(template.checked_fn_root);
                try self.relateEvidenceTargetRootToRequest(lookup.view, template.checked_fn_root, target_root_node, request_fn_node, dispatchTargetAdapterReachability(lookup.target));
                const edge = try self.deriveTargetEdge(&target_ctx, schema, evidence_source);
                break :blk try self.builder.lowerDraftTemplateFromContext(
                    self,
                    procedure.template,
                    source_fn_ty,
                    source_fn_key,
                    request_fn_node,
                    edge,
                    .instantiation,
                    if (procedure.runtime_target.iteratorProcedure() == .from_step) .exact_graph else .independent_roots,
                    codec_contract_selection,
                );
            },
            .local_proc => |local| blk: {
                const schema = self.scopeSchema(lookup.view, local.dispatch_scope);
                var target_ctx = try self.methodTargetContext(lookup);
                defer target_ctx.deinit();
                if (lookup.substitution) |substitution| try self.seedCheckedTargetSubstitution(&target_ctx, schema, substitution);
                const target_root_node = try target_ctx.instNode(source_fn_ty);
                try self.relateEvidenceTargetRootToRequest(lookup.view, source_fn_ty, target_root_node, request_fn_node, dispatchTargetAdapterReachability(lookup.target));
                const edge = try self.deriveTargetEdge(&target_ctx, schema, evidence_source);
                break :blk .{ .local = try self.lowerDraftLocalProcAtNode(
                    .{
                        .binder = local.binder,
                        .expr = local.expr,
                        .dispatch_scope = local.dispatch_scope,
                    },
                    lookup.view,
                    lookup.local_proc_context orelse
                        Common.invariant("local method target did not carry its declaration context"),
                    source_fn_ty,
                    source_fn_key,
                    request_fn_node,
                    edge,
                    false,
                    codec_contract_selection,
                ) };
            },
            .structural => Common.invariant("structural method registry result has no callable procedure body"),
        };
    }

    fn relateMaterializedEvidenceConstraints(
        self: *BodyContext,
        target_ctx: *BodyContext,
        schema: SchemeRequirements,
        contract: []const SpecEvidence,
    ) Allocator.Error!void {
        if (contract.len != schema.params.len) {
            Common.invariant("materialized target contract length differed from its scheme requirements");
        }
        for (schema.params, contract) |param, entry| {
            // Even a callable-root receiver's method can bind variables
            // reached only through its constraint signature. Every
            // selected target supplies that relation exactly once;
            // selection itself needs no graph-driven fixpoint here.
            try self.relateMaterializedEvidenceConstraint(target_ctx, param, entry);
            const contracts = evidenceCallableContracts(entry);
            if (contracts.len == 0 and entry == .target) {
                // Checking omits side-vector evidence when each independent
                // callable can derive it from the selected target. The schema
                // still records every callable relation, including variables
                // absent from the scheme root; relate each to a fresh instance
                // of the declaration rather than the primary use's signature.
                var independent_target = entry.target.*;
                independent_target.instantiation = null;
                independent_target.substitution = null;
                const callables = schema.view.templates.evidence_param_callables[param.callable_contracts.start..][0..param.callable_contracts.len];
                for (callables) |callable| {
                    var contract_param = param;
                    contract_param.callable_ty = callable;
                    contract_param.callable_contracts = .{};
                    try self.relateTargetToConstraint(&independent_target, target_ctx, contract_param);
                }
            } else if (contracts.len != 0) {
                if (contracts.len != param.callable_contracts.len) Common.invariant("callable contracts differed from their checked schema");
                const callables = schema.view.templates.evidence_param_callables[param.callable_contracts.start..][0..param.callable_contracts.len];
                for (contracts, callables) |contract_entry, callable| {
                    var contract_param = param;
                    contract_param.callable_ty = callable;
                    contract_param.callable_contracts = .{};
                    try self.relateMaterializedEvidenceConstraint(target_ctx, contract_param, contract_entry);
                }
            }
        }
    }

    fn relateMaterializedEvidenceConstraint(
        self: *BodyContext,
        target_ctx: *BodyContext,
        param: static_dispatch.EvidenceParamRecord,
        entry: SpecEvidence,
    ) Allocator.Error!void {
        self.builder.count("evidence_contract_relations");
        switch (entry) {
            .target => |target| try self.relateTargetToConstraint(target, target_ctx, param),
            .structural => |structural| if (structural.checked) |checked_structural| {
                try self.relateStructuralEvidenceToConstraint(checked_structural, target_ctx, param);
            },
            .from_callable, .from_scheme, .unreachable_value, .checked_error => {},
        }
    }

    /// The substitution and evidence a target scheme receives from a request
    /// its root was related to in `target_ctx`.
    fn deriveTargetEdge(
        self: *BodyContext,
        target_ctx: *BodyContext,
        schema: SchemeRequirements,
        evidence_source: TargetEvidenceSource,
    ) Allocator.Error!EdgeEvidence {
        const subst = try self.substitutionFromSchemeVars(target_ctx, schema.scheme_vars);
        const vector = switch (evidence_source) {
            .derive => try self.deriveEvidenceVector(
                schema,
                subst,
                self.view,
                null,
                .body_lowering,
            ),
            .checked => |contract| try self.deriveEvidenceVector(
                schema,
                subst,
                contract.view,
                contract.entries,
                .body_lowering,
            ),
            .materialized_contract => |contract| blk: {
                try self.relateMaterializedEvidenceConstraints(target_ctx, schema, contract);
                // Reuse is authorized by the checked dispatch plan. Independent
                // callables without that proof use .derive instead. This contract
                // already supplies every target and terminal verdict, including
                // composite requirements with no substitution slot.
                break :blk try normalizeMaterializedEvidence(self.builder.evidence_arena.allocator(), contract);
            },
        };
        return .{
            .subst = subst,
            .vector = vector,
        };
    }

    /// Lower a checker-classified direct target at the already-instantiated
    /// request interface. CheckedModule construction performed the target
    /// instantiation and recorded the substitution it applied, so the
    /// target's evidence derives from that record without instantiating the
    /// target's checked root again.
    fn methodTargetCalleeDirectAtNode(
        self: *BodyContext,
        raw_lookup: MethodLookup,
        request_fn_node: NodeId,
        plan: static_dispatch.StaticDispatchCallPlan,
    ) Allocator.Error!DraftFnSlot {
        const lookup = try self.withLocalProcContext(raw_lookup);
        const source_fn_ty = lookup.target.callable_ty;
        const source_fn_key = lookup.view.types.rootKey(source_fn_ty);
        const subst = (try self.directDispatchTargetSubstitution(plan, lookup, request_fn_node)) orelse
            Common.invariant("direct dispatch target had no checked substitution");
        const contract: ?[]const static_dispatch.CheckedEvidence = if (self.dispatchTargetContract(plan)) |c| c.entries else null;
        return switch (lookup.target.kind) {
            .procedure => |procedure| blk: {
                const template = lookup.view.templates.get(procedure.template.template);
                if (subst.len != template.scheme_vars.len) {
                    Common.invariant("direct dispatch target substitution length differed from its scheme");
                }
                const schema = templateSchemaIn(lookup.view, &template);
                const edge: EdgeEvidence = .{
                    .subst = subst,
                    .vector = try self.deriveEvidenceVector(schema, subst, self.view, contract, .body_lowering),
                };
                break :blk try self.builder.lowerDraftTemplateFromContext(
                    self,
                    procedure.template,
                    source_fn_ty,
                    source_fn_key,
                    request_fn_node,
                    edge,
                    .instantiation,
                    if (procedure.runtime_target.iteratorProcedure() == .from_step) .exact_graph else .independent_roots,
                    .inherit,
                );
            },
            .local_proc => |local| blk: {
                const schema = self.scopeSchema(lookup.view, local.dispatch_scope);
                if (subst.len != schema.scheme_vars.len) {
                    Common.invariant("direct local method target substitution length differed from its scope scheme");
                }
                const edge: EdgeEvidence = .{
                    .subst = subst,
                    .vector = try self.deriveEvidenceVector(schema, subst, self.view, contract, .body_lowering),
                };
                break :blk .{ .local = try self.lowerDraftLocalProcAtNode(
                    .{
                        .binder = local.binder,
                        .expr = local.expr,
                        .dispatch_scope = local.dispatch_scope,
                    },
                    lookup.view,
                    lookup.local_proc_context orelse
                        Common.invariant("direct local method target did not carry its declaration context"),
                    source_fn_ty,
                    source_fn_key,
                    request_fn_node,
                    edge,
                    false,
                    .inherit,
                ) };
            },
            .structural => Common.invariant("direct checked call targeted a structural derivation"),
        };
    }

    /// Lower or reuse an ordinary procedure specialization so its callee-authored
    /// iterator result is available before the caller chooses
    /// representation-sensitive lowering. This is an expression-lowering step,
    /// not a read-only graph query: it may create a draft specialization.
    fn lowerAndCompleteIteratorMethodResultAtNode(
        self: *BodyContext,
        lookup: MethodLookup,
        request_fn_node: NodeId,
        plan: static_dispatch.StaticDispatchCallPlan,
        direct: bool,
    ) Allocator.Error!NodeId {
        // The target kind is an O(1) tag compare and rejects every builtin
        // iterator method (the registry classifies iterator owners as
        // `.graph_participating`), so it runs before the structural
        // containment walks below.
        switch (lookup.target.kind) {
            .procedure => |procedure| switch (procedure.runtime_target) {
                .procedure => {},
                .intrinsic, .low_level, .graph_participating => return request_fn_node,
            },
            .local_proc => {},
            .structural => return request_fn_node,
        }
        const request_fn = try self.graph.functionNodes(request_fn_node);
        if (!try self.graph.containsIteratorInterface(request_fn.ret) or
            try self.graph.containsGeneratedPrivate(request_fn.ret))
        {
            return request_fn_node;
        }
        // Materialized only past the guards above: most dispatches return
        // without consuming evidence, and materialization arena-allocates one
        // vector per target.
        const slot = if (direct)
            try self.methodTargetCalleeDirectAtNode(lookup, request_fn_node, plan)
        else
            try self.methodTargetCalleeAtNodeWithEvidence(
                lookup,
                request_fn_node,
                self.dispatchTargetEvidenceSource(plan),
            );
        return try self.draftFnSlotTypeNode(slot, request_fn_node);
    }

    fn resolvedDispatchCallData(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
        lookup: MethodLookup,
        callable_node: NodeId,
        args: DraftSpan(DraftExprId),
    ) Allocator.Error!BodyExprData {
        const contextual_lookup = try self.withLocalProcContext(lookup);
        return .{ .call_proc = .{
            .callee = draftProcCalleeForSlot(try self.methodTargetCalleeAtNodeWithEvidence(
                contextual_lookup,
                callable_node,
                self.dispatchTargetEvidenceSource(plan),
            )),
            .args = args,
            .iterator_procedure = self.iteratorProcedureForMethodTarget(contextual_lookup.target),
            .captures = try self.methodTargetCaptureSpan(contextual_lookup),
        } };
    }

    fn resolvedDirectDispatchCallData(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
        lookup: MethodLookup,
        callable_node: NodeId,
        args: DraftSpan(DraftExprId),
    ) Allocator.Error!BodyExprData {
        const contextual_lookup = try self.withLocalProcContext(lookup);
        return .{ .call_proc = .{
            .callee = draftProcCalleeForSlot(try self.methodTargetCalleeDirectAtNode(
                contextual_lookup,
                callable_node,
                plan,
            )),
            .args = args,
            .iterator_procedure = self.iteratorProcedureForMethodTarget(contextual_lookup.target),
            .captures = try self.methodTargetCaptureSpan(contextual_lookup),
        } };
    }

    /// Relate a structural equality's operand nodes, returning its result
    /// type; its operands lower next.
    fn beginStructuralEqualityAtNode(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
        callable_node: NodeId,
    ) Allocator.Error!Type.TypeId {
        const eq = switch (plan.result_mode) {
            .equality => |eq| eq,
            .value, .hash, .parser_for, .encoder_for, .map, .map_effectful => Common.invariant("non-equality dispatch plan reached graph equality lowering"),
        };
        if (!eq.structural_allowed) {
            Common.invariant("structural equality dispatch plan did not permit structural equality");
        }

        const fn_nodes = try self.graph.functionNodes(callable_node);
        if (fn_nodes.args.len != 2) {
            Common.invariant("structural equality callable graph node must have two operands");
        }
        try self.graph.unify(fn_nodes.args[0], fn_nodes.args[1]);
        return try self.resolvedTypeViewForNode(fn_nodes.ret);
    }

    fn finishStructuralEqualityAtNode(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
        callable_node: NodeId,
        ret_ty: Type.TypeId,
        operands_span: DraftSpan(DraftExprId),
    ) Allocator.Error!DraftExprId {
        const eq = plan.result_mode.equality;
        const fn_nodes = try self.graph.functionNodes(callable_node);
        const operands = self.exprSpan(operands_span);
        if (operands.len != 2) {
            Common.invariant("structural equality dispatch did not lower two operands");
        }

        const operand_node = switch (try self.structuralDerivationOperandFromNode(fn_nodes.args[0])) {
            .sealed => |operand_ty| {
                if (eq.discriminant) |discriminant| {
                    if (discriminant.value_operand >= operands.len) Common.invariant("tag-discriminant equality named a missing operand");
                    return try self.lowerEqualityAgainstTag(
                        operands[discriminant.value_operand],
                        operand_ty,
                        try self.tagName(self.view, discriminant.tag),
                        eq.negated,
                        ret_ty,
                    );
                }
                return try self.lowerStructuralEqFromOperands(
                    operand_ty,
                    operands[0],
                    operands[1],
                    eq.negated,
                    ret_ty,
                );
            },
            .deferred => |operand_node| operand_node,
        };
        if (eq.discriminant) |discriminant| {
            if (discriminant.value_operand >= operands.len) Common.invariant("tag-discriminant equality named a missing operand");
            const value = operands[discriminant.value_operand];
            return try self.deferStructuralDerivationOperandsAtNode(
                ret_ty,
                operand_node,
                value,
                value,
                .{ .tag_discriminant = .{
                    .value = value,
                    .tag = try self.tagName(self.view, discriminant.tag),
                    .negated = eq.negated,
                } },
            );
        }
        return try self.deferStructuralEqOperandsAtNode(ret_ty, operand_node, operands[0], operands[1], eq.negated);
    }

    /// The hash counterpart of `beginStructuralEqualityAtNode`: the hashed
    /// value's node may still carry live row defaults, so the derivation
    /// defers to final graph sealing instead of forcing an eager resolved
    /// view. The hasher operand and result share one concrete type.
    fn beginStructuralHashAtNode(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
        callable_node: NodeId,
    ) Allocator.Error!Type.TypeId {
        const hash = switch (plan.result_mode) {
            .hash => |hash| hash,
            .value, .equality, .parser_for, .encoder_for, .map, .map_effectful => Common.invariant("non-hash dispatch plan reached graph hash lowering"),
        };
        if (!hash.structural_allowed) {
            Common.invariant("structural hash dispatch plan did not permit structural hashing");
        }

        const fn_nodes = try self.graph.functionNodes(callable_node);
        if (fn_nodes.args.len != 2) {
            Common.invariant("structural hash callable graph node must have two operands");
        }
        try self.graph.unify(fn_nodes.args[1], fn_nodes.ret);
        return try self.resolvedTypeViewForNode(fn_nodes.ret);
    }

    fn finishStructuralHashAtNode(
        self: *BodyContext,
        callable_node: NodeId,
        ret_ty: Type.TypeId,
        operands_span: DraftSpan(DraftExprId),
    ) Allocator.Error!DraftExprId {
        const fn_nodes = try self.graph.functionNodes(callable_node);
        const operands = self.exprSpan(operands_span);
        if (operands.len != 2) {
            Common.invariant("structural hash dispatch did not lower two operands");
        }

        return switch (try self.structuralDerivationOperandFromNode(fn_nodes.args[0])) {
            .sealed => |value_ty| try self.lowerHashExpr(value_ty, operands[0], operands[1], ret_ty),
            .deferred => |value_node| try self.deferStructuralDerivationOperandsAtNode(
                ret_ty,
                value_node,
                operands[0],
                operands[1],
                .hash,
            ),
        };
    }

    fn deferStructuralSerializationAtNode(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
        structural: SpecStructuralEvidence,
        callable_node: NodeId,
        shape_node: NodeId,
        pre_lowered: []const PreLoweredOperand,
    ) Allocator.Error!DraftExprId {
        const callable = try self.graph.functionNodes(callable_node);
        if (callable.args.len != 1) {
            Common.invariant("structural serialization callable graph node must have one encoding operand");
        }
        const encoding = self.preLoweredOperandAt(pre_lowered, 0) orelse
            Common.invariant("structural serialization encoding operand was not lowered before deferral");
        const expr = try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(callable.ret), .pending_deferred);
        self.draft.expr_impossibility_proofs.items[@backingInt(expr)] = self.exprImpossibilityProof(encoding);
        const lexical = try self.captureCodecLexicalContext();
        var lexical_needs_cleanup = true;
        errdefer if (lexical_needs_cleanup) {
            self.allocator.free(lexical.binders);
            self.allocator.free(lexical.local_procs);
        };
        try self.draft.deferred_structural_serializations.append(self.allocator, .{
            .view = self.view,
            .method_scope = self.method_scope,
            .owner_template = self.owner_template,
            .owner = self.draft.current_owner,
            .expr = expr,
            .plan = plan,
            .callable_node = callable_node,
            .shape_node = shape_node,
            .structural = structural,
            .encoding = encoding,
            .evidence = self.evidence,
            .current_fn_key = self.current_fn_key,
            .lexical = lexical,
        });
        lexical_needs_cleanup = false;
        const kind: CodecKind = switch (plan.result_mode) {
            .parser_for => .parser,
            .encoder_for => .encoder,
            .value, .equality, .hash, .map, .map_effectful => Common.invariant("non-codec result mode reached structural serialization deferral"),
        };
        const previous_contract = self.active_codec_contract;
        const previous_call_count = self.instantiated_codec_calls.items.len;
        defer {
            self.active_codec_contract = previous_contract;
            self.instantiated_codec_calls.shrinkRetainingCapacity(previous_call_count);
        }
        self.active_codec_contract = try self.instantiateCodecContract(
            structural,
            callable_node,
            shape_node,
        );
        var seen = collections.DenseMap(NodeId, void).init(self.allocator);
        defer seen.deinit();
        _ = try self.prepareCustomCodecCallsAtNode(expr, kind, shape_node, callable_node, &seen);
        return expr;
    }

    /// The two lowered operands of a structural derivation plus `derived_ty`,
    /// the type being derived on, which the terminal lowering needs.
    const StructuralBinaryOperands = struct {
        first: DraftExprId,
        second: DraftExprId,
        derived_ty: Type.TypeId,
    };

    /// Lower the value and hasher operands of a structural hash dispatch,
    /// honoring a `pre_lowered` operand at index 0 or 1. `noun` is the derivation
    /// name used only in invariant diagnostics.
    fn lowerStructuralBinaryOperands(
        self: *BodyContext,
        comptime noun: []const u8,
        plan: static_dispatch.StaticDispatchCallPlan,
        callable_mono_ty: Type.TypeId,
        arg_ctx: *BodyContext,
        pre_lowered: []const PreLoweredOperand,
    ) Allocator.Error!StructuralBinaryOperands {
        const plan_args = plan.argsSlice(self.view.static_dispatch_plans);
        if (plan_args.len != 2) Common.invariant("structural " ++ noun ++ " dispatch plan must have two operands");
        const fn_data = self.functionShape(callable_mono_ty, "checked structural " ++ noun ++ " target had a non-function type");
        // Copy because the recursive operand lowering below may reallocate
        // types.span, dangling the slice; only the scalar derived type escapes.
        const arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(fn_data.args));
        defer self.allocator.free(arg_tys);
        if (arg_tys.len != 2) Common.invariant("structural " ++ noun ++ " callable type must have two operands");
        const first = self.preLoweredOperandAt(pre_lowered, 0) orelse
            try arg_ctx.lowerDispatchOperandAtType(plan_args[0], arg_tys[0]);
        const second = self.preLoweredOperandAt(pre_lowered, 1) orelse
            try arg_ctx.lowerDispatchOperandAtType(plan_args[1], arg_tys[1]);
        return .{ .first = first, .second = second, .derived_ty = arg_tys[0] };
    }

    /// Lower derived `map`/`map!` into the exhaustive tag match selected by
    /// checking. The payload-slot plan is explicit evidence; Monotype never
    /// re-runs eligibility or guesses which payload should be transformed.
    fn lowerStructuralMap(
        self: *BodyContext,
        comptime noun: []const u8,
        plan: static_dispatch.StaticDispatchCallPlan,
        map_plan: static_dispatch.DerivedMapPlan,
        callable_mono_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        arg_ctx: *BodyContext,
        pre_lowered: []const PreLoweredOperand,
    ) Allocator.Error!DraftExprId {
        switch (plan.result_mode) {
            .map => |mode| if (!mode.structural_allowed) Common.invariant("structural map dispatch plan did not permit structural map lowering"),
            .map_effectful => |mode| if (!mode.structural_allowed) Common.invariant("structural map! dispatch plan did not permit structural map! lowering"),
            .value, .equality, .hash, .parser_for, .encoder_for => Common.invariant("non-map dispatch plan reached structural map lowering"),
        }

        const operands = try self.lowerStructuralBinaryOperands(noun, plan, callable_mono_ty, arg_ctx, pre_lowered);
        const input_ty = operands.derived_ty;
        const transform_ty = try self.exprType(operands.second);
        const transform_fn = self.functionShape(transform_ty, "checked derived map transform had a non-function type");
        const transform_arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(transform_fn.args));
        defer self.allocator.free(transform_arg_tys);
        if (transform_arg_tys.len != 1) Common.invariant("checked derived map transform did not have one argument");

        const selected_name = try self.tagName(self.view, map_plan.tag);
        const input_selected_tag = self.tagByName(input_ty, selected_name);
        const output_selected_tag = self.tagByName(ret_ty, selected_name);
        const input_selected_payloads = self.typeStore().span(input_selected_tag.payloads);
        const output_selected_payloads = self.typeStore().span(output_selected_tag.payloads);
        if (map_plan.payload_index >= input_selected_payloads.len or map_plan.payload_index >= output_selected_payloads.len) {
            Common.invariant("checked derived map payload plan was outside the selected tag's payloads");
        }
        const selected_index: usize = @intCast(map_plan.payload_index);
        if (!self.sameType(transform_arg_tys[0], GuardedList.at(input_selected_payloads, selected_index))) {
            Common.invariant("checked derived map transform argument differed from the selected input payload");
        }
        if (!self.sameType(transform_fn.ret, GuardedList.at(output_selected_payloads, selected_index))) {
            Common.invariant("checked derived map transform result differed from the selected output payload");
        }

        const input_tags = try GuardedList.dupe(self.allocator, Type.Tag, self.tagUnionTags(input_ty));
        defer self.allocator.free(input_tags);
        const branches = try self.allocator.alloc(DraftBranch, input_tags.len);
        defer self.allocator.free(branches);

        const transform_local = try self.addLocal(self.builder.symbols.fresh(), transform_ty);
        for (input_tags, 0..) |input_tag, branch_index| {
            const input_payload_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(input_tag.payloads));
            defer self.allocator.free(input_payload_tys);
            const output_tag = self.tagByName(ret_ty, input_tag.name);
            const output_payload_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(output_tag.payloads));
            defer self.allocator.free(output_payload_tys);
            if (input_payload_tys.len != output_payload_tys.len) {
                Common.invariant("derived map changed an unselected tag's payload arity");
            }

            const payload_pats = try self.allocator.alloc(DraftPatId, input_payload_tys.len);
            defer self.allocator.free(payload_pats);
            const output_payloads = try self.allocator.alloc(DraftExprId, output_payload_tys.len);
            defer self.allocator.free(output_payloads);
            for (input_payload_tys, output_payload_tys, 0..) |input_payload_ty, output_payload_ty, payload_index| {
                const payload_local = try self.addLocal(self.builder.symbols.fresh(), input_payload_ty);
                payload_pats[payload_index] = try self.bindPat(payload_local, input_payload_ty);
                const input_payload = try self.localExpr(payload_local, input_payload_ty);
                if (input_tag.name == selected_name and payload_index == selected_index) {
                    const transform = try self.localExpr(transform_local, transform_ty);
                    output_payloads[payload_index] = try self.addExpr(.{
                        .ty = output_payload_ty,
                        .data = .{ .call_value = .{
                            .callee = transform,
                            .args = try self.addExprSpan(&.{input_payload}),
                        } },
                    });
                } else {
                    if (!self.sameType(input_payload_ty, output_payload_ty)) {
                        Common.invariant("derived map changed an unselected payload type");
                    }
                    output_payloads[payload_index] = input_payload;
                }
            }

            const body = try self.addConstructorExpr(ret_ty, .{ .tag = .{
                .name = output_tag.name,
                .payloads = try self.addExprSpan(output_payloads),
            } });
            const branch_pat = try self.addConstructorPat(input_ty, .{ .tag = .{
                .name = input_tag.name,
                .payloads = try self.addPatSpan(payload_pats),
            } });
            branches[branch_index] = .{ .pat = branch_pat, .body = body };
        }

        const input_local = try self.addLocal(self.builder.symbols.fresh(), input_ty);
        const match_expr = try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(input_local, input_ty),
            .branches = try self.addBranchSpan(branches),
        } } });
        const bind_transform = try self.wrapLet(transform_local, transform_ty, operands.second, match_expr, ret_ty);
        return try self.wrapLet(input_local, input_ty, operands.first, bind_transform, ret_ty);
    }

    fn lowerStructuralParser(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
        callable_mono_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        arg_ctx: *BodyContext,
        pre_lowered: []const PreLoweredOperand,
        shape_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const parser = switch (plan.result_mode) {
            .parser_for => |parser_for| parser_for,
            .value, .equality, .hash, .encoder_for, .map, .map_effectful => Common.invariant("non-parser_for dispatch plan reached structural parse lowering"),
        };
        if (!parser.structural_allowed) Common.invariant("structural parser dispatch plan did not permit structural parser lowering");

        const fn_data = self.functionShape(callable_mono_ty, "checked structural parser target had a non-function type");
        const arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(fn_data.args));
        defer self.allocator.free(arg_tys);
        const plan_args = plan.argsSlice(self.view.static_dispatch_plans);
        if (arg_tys.len != 1 or plan_args.len != 1) Common.invariant("structural parser callable type must have one encoding argument");
        if (!self.sameType(fn_data.ret, ret_ty)) Common.invariant("structural parser return type differed from dispatch expression type");

        const runtime_fn = self.functionShape(ret_ty, "checked structural parser return had a non-function type");
        const runtime_arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(runtime_fn.args));
        defer self.allocator.free(runtime_arg_tys);
        if (runtime_arg_tys.len != 1) Common.invariant("structural parser runtime function must have one state argument");

        const top_level_null_try = self.tryNullInfo(shape_ty);
        const nominal_scalar_backing = if (self.nominalExprBackingType(shape_ty)) |backing_ty|
            self.scalarCodecMethodName(backing_ty, "parse_") != null
        else
            false;
        if (self.scalarCodecMethodName(shape_ty, "parse_") == null and top_level_null_try == null and !nominal_scalar_backing) {
            if (self.setPayloadType(shape_ty)) |elem_ty| {
                if (!try self.parseFieldTypeIsSupported(elem_ty, false)) Common.invariant("structural parser set element type was not supported");
            } else if (self.dictEntryShape(shape_ty)) |dict| {
                if (!self.dictKeyIsStringRendered(dict.key_ty) and !try self.parseFieldTypeIsSupported(dict.key_ty, false)) {
                    Common.invariant("structural parser dict key type was not supported");
                }
                if (!try self.parseFieldTypeIsSupported(dict.value_ty, false)) Common.invariant("structural parser dict value type was not supported");
            } else {
                switch (self.shapeContent(shape_ty)) {
                    .list => |elem_ty| {
                        if (!try self.parseFieldTypeIsSupported(elem_ty, false)) Common.invariant("structural parser list element type was not supported");
                    },
                    .box => |payload_ty| {
                        if (!try self.parseFieldTypeIsSupported(payload_ty, false)) Common.invariant("structural parser box payload type was not supported");
                    },
                    .tuple => |span| {
                        const elem_tys = self.typeStore().span(span);
                        for (0..GuardedList.borrowLen(elem_tys)) |index| {
                            const elem_ty = GuardedList.at(elem_tys, index);
                            if (!try self.parseFieldTypeIsSupported(elem_ty, false)) Common.invariant("structural parser tuple element type was not supported");
                        }
                    },
                    .record => |fields_span| blk: {
                        const fields = self.typeStore().fieldSpan(fields_span);
                        for (0..GuardedList.borrowLen(fields)) |index| {
                            const field = GuardedList.at(fields, index);
                            if (!try self.parseFieldTypeIsSupported(field.ty, true)) Common.invariant("structural parser record field type was not supported");
                        }
                        break :blk;
                    },
                    .tag_union => |tags_span| blk: {
                        const tags = self.typeStore().tagSpan(tags_span);
                        if (tags.len == 0) Common.invariant("structural parser empty tag union reached postcheck lowering");
                        for (0..GuardedList.borrowLen(tags)) |tag_index| {
                            const tag = GuardedList.at(tags, tag_index);
                            const payload_tys = self.typeStore().span(tag.payloads);
                            for (0..GuardedList.borrowLen(payload_tys)) |payload_index| {
                                const payload_ty = GuardedList.at(payload_tys, payload_index);
                                if (!try self.parseFieldTypeIsSupported(payload_ty, false)) Common.invariant("structural parser tag-union payload type was not supported");
                            }
                        }
                        break :blk;
                    },
                    .zst => {},
                    .primitive, .named, .func, .erased => Common.invariant("structural parser dispatcher was not a supported structural type"),
                }
            }
        }

        const encoding_value = self.preLoweredOperandAt(pre_lowered, 0) orelse
            try arg_ctx.lowerDispatchOperandAtType(plan_args[0], arg_tys[0]);
        const encoding_local = try self.addLocal(self.builder.symbols.fresh(), arg_tys[0]);
        self.setLocalCaptureId(encoding_local, parserEncodingCaptureId());
        const state_local = try self.addLocal(self.builder.symbols.fresh(), runtime_arg_tys[0]);

        const str_ty = try self.primitiveType(.str);
        var precomputed_plan = ParserPrecomputedPlan.init(self.allocator);
        defer precomputed_plan.deinit();
        try self.buildParserConstructionPrecomputedPlan(
            &precomputed_plan,
            shape_ty,
            try self.localExpr(encoding_local, arg_tys[0]),
            arg_tys[0],
            str_ty,
        );

        const parsed = blk: {
            var capture_tys = std.ArrayList(Type.TypeId).empty;
            defer capture_tys.deinit(self.allocator);
            try capture_tys.append(self.allocator, arg_tys[0]);
            for (precomputed_plan.captures.items) |_| try capture_tys.append(self.allocator, str_ty);
            const demand_scope = try self.enterCallableBodyDemandScope(&.{runtime_arg_tys[0]}, capture_tys.items);
            defer demand_scope.leave();
            break :blk try self.lowerParseShapeHelperCall(
                shape_ty,
                try self.localExpr(encoding_local, arg_tys[0]),
                arg_tys[0],
                try self.localExpr(state_local, runtime_arg_tys[0]),
                runtime_arg_tys[0],
                runtime_fn.ret,
                &precomputed_plan,
            );
        };
        const fn_id = try self.addFn(.{
            .fn_def = .{ .parser_runtime = .{
                .owner = self.owner_template,
                .expr = plan.expr,
            } },
            .source_fn_ty = plan.callable_ty,
            .source_fn_key = generatedCodecRuntimeKey("roc.generated_structural_parser_runtime", self.current_fn_key, plan.expr),
            .mono_fn_ty = ret_ty,
            .evidence_digest = Ast.fnEvidenceDigest(&.{}, &.{}, null),
        });
        var parser_expr = try self.addExpr(.{ .ty = ret_ty, .data = .{ .lambda = .{
            .fn_id = .{ .draft = fn_id },
            .args = try self.addTypedLocalSpan(&.{
                .{ .local = state_local, .ty = runtime_arg_tys[0] },
            }),
            .body = parsed,
        } } });
        var capture_index = precomputed_plan.captures.items.len;
        while (capture_index > 0) {
            capture_index -= 1;
            const capture = precomputed_plan.captures.items[capture_index];
            parser_expr = try self.wrapLet(capture.local, str_ty, capture.value, parser_expr, ret_ty);
        }
        return try self.wrapLet(encoding_local, arg_tys[0], encoding_value, parser_expr, ret_ty);
    }

    fn lowerStructuralEncoderFor(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
        callable_mono_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        arg_ctx: *BodyContext,
        pre_lowered: []const PreLoweredOperand,
        shape_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const encoder_for = switch (plan.result_mode) {
            .encoder_for => |encoder_for| encoder_for,
            .value, .equality, .hash, .parser_for, .map, .map_effectful => Common.invariant("non-encoder_for dispatch plan reached structural encoder_for lowering"),
        };
        if (!encoder_for.structural_allowed) Common.invariant("structural encoder_for dispatch plan did not permit structural encoder_for lowering");

        const fn_data = self.functionShape(callable_mono_ty, "checked structural encoder_for target had a non-function type");
        const arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(fn_data.args));
        defer self.allocator.free(arg_tys);
        const plan_args = plan.argsSlice(self.view.static_dispatch_plans);
        if (arg_tys.len != 1 or plan_args.len != 1) Common.invariant("structural encoder_for callable type must have one encoding argument");
        if (!self.sameType(fn_data.ret, ret_ty)) Common.invariant("structural encoder_for return type differed from dispatch expression type");

        const runtime_fn = self.functionShape(ret_ty, "checked structural encoder_for return had a non-function type");
        const runtime_arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(runtime_fn.args));
        defer self.allocator.free(runtime_arg_tys);
        if (runtime_arg_tys.len != 2) Common.invariant("structural encoder_for runtime function must have value and state arguments");

        if (!try self.encodeFieldTypeIsSupported(shape_ty, arg_tys[0])) Common.invariant("structural encoder_for dispatcher was not a supported structural type");

        const encoding_value = self.preLoweredOperandAt(pre_lowered, 0) orelse
            try arg_ctx.lowerDispatchOperandAtType(plan_args[0], arg_tys[0]);

        const encoding_local = try self.addLocal(self.builder.symbols.fresh(), arg_tys[0]);
        const value_local = try self.addLocal(self.builder.symbols.fresh(), runtime_arg_tys[0]);
        const state_local = try self.addLocal(self.builder.symbols.fresh(), runtime_arg_tys[1]);
        self.setLocalCaptureId(encoding_local, encoderForEncodingCaptureId());

        const str_ty = try self.primitiveType(.str);
        var precomputed_plan = ParserPrecomputedPlan.init(self.allocator);
        defer precomputed_plan.deinit();
        precomputed_plan.next_capture_id = encoderForFirstFieldCaptureId();
        try self.buildEncodeConstructionPrecomputedPlan(
            &precomputed_plan,
            shape_ty,
            try self.localExpr(encoding_local, arg_tys[0]),
            arg_tys[0],
            str_ty,
        );

        const runtime_source_fn_key = generatedCodecRuntimeKey("roc.generated_structural_encoder_for_runtime", self.current_fn_key, plan.expr);
        const saved_current_fn_key = self.current_fn_key;
        const saved_encoder_source_fn_ty = self.generated_encoder_source_fn_ty;
        const saved_encoder_source_expr = self.generated_encoder_source_expr;
        const saved_encoder_lambda_index = self.generated_encoder_lambda_index;
        self.current_fn_key = runtime_source_fn_key;
        self.generated_encoder_source_fn_ty = plan.callable_ty;
        self.generated_encoder_source_expr = plan.expr;
        self.generated_encoder_lambda_index = 0;
        defer {
            self.current_fn_key = saved_current_fn_key;
            self.generated_encoder_source_fn_ty = saved_encoder_source_fn_ty;
            self.generated_encoder_source_expr = saved_encoder_source_expr;
            self.generated_encoder_lambda_index = saved_encoder_lambda_index;
        }

        const encoded = blk: {
            var capture_tys = std.ArrayList(Type.TypeId).empty;
            defer capture_tys.deinit(self.allocator);
            try capture_tys.append(self.allocator, arg_tys[0]);
            for (precomputed_plan.captures.items) |_| try capture_tys.append(self.allocator, str_ty);
            const demand_scope = try self.enterCallableBodyDemandScope(runtime_arg_tys, capture_tys.items);
            defer demand_scope.leave();
            break :blk try self.lowerEncodeShapeToState(
                shape_ty,
                try self.localExpr(value_local, runtime_arg_tys[0]),
                try self.localExpr(encoding_local, arg_tys[0]),
                arg_tys[0],
                try self.localExpr(state_local, runtime_arg_tys[1]),
                runtime_arg_tys[1],
                runtime_fn.ret,
                &precomputed_plan,
            );
        };
        const fn_id = try self.addFn(.{
            .fn_def = .{ .encoder_for_runtime = .{
                .owner = self.owner_template,
                .expr = plan.expr,
            } },
            .source_fn_ty = plan.callable_ty,
            .source_fn_key = runtime_source_fn_key,
            .mono_fn_ty = ret_ty,
            .evidence_digest = Ast.fnEvidenceDigest(&.{}, &.{}, null),
        });
        var encoder_expr = try self.addExpr(.{ .ty = ret_ty, .data = .{ .lambda = .{
            .fn_id = .{ .draft = fn_id },
            .args = try self.addTypedLocalSpan(&.{
                .{ .local = value_local, .ty = runtime_arg_tys[0] },
                .{ .local = state_local, .ty = runtime_arg_tys[1] },
            }),
            .body = encoded,
        } } });
        var capture_index = precomputed_plan.captures.items.len;
        while (capture_index > 0) {
            capture_index -= 1;
            const capture = precomputed_plan.captures.items[capture_index];
            encoder_expr = try self.wrapLet(capture.local, str_ty, capture.value, encoder_expr, ret_ty);
        }
        return try self.wrapLet(encoding_local, arg_tys[0], encoding_value, encoder_expr, ret_ty);
    }

    /// The inputs every position of one generated encoder shares.
    const EncodeInputs = struct {
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    };

    /// A value encoded into a state.
    const EncodeValue = struct {
        shape_ty: Type.TypeId,
        value_expr: DraftExprId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
    };

    /// A container encoder's element loop over `len_local`, writing each
    /// element through `writer_expr`.
    const EncodeLoop = struct {
        method: EncodeContainerMethod,
        len_local: DraftLocalId,
        index_local: DraftLocalId,
        loop_state_local: DraftLocalId,
        writer_expr: DraftExprId,
    };

    /// One pending piece of a generated encoder. Each piece allocates its
    /// locals, expressions, patterns, and helper definitions in the order a
    /// direct walk would, waiting on a frame for each component it encodes.
    const EncodeTask = union(enum) {
        shape: struct { inputs: EncodeInputs, value: EncodeValue, value_local: DraftLocalId = undefined, backing_local: DraftLocalId = undefined, backing_ty: Type.TypeId = undefined },
        /// A callback lambda writing the value into the state it is given.
        value_thunk: struct { inputs: EncodeInputs, value_ty: Type.TypeId, value_expr: DraftExprId, state_ty: Type.TypeId, ret_ty: Type.TypeId, state_local: DraftLocalId = undefined, thunk_ty: Type.TypeId = undefined },
        /// A call to the helper encoding the value's type.
        helper_call: struct { inputs: EncodeInputs, value: EncodeValue },
        /// The helper encoding values of a type.
        def: struct {
            inputs: EncodeInputs,
            value_ty: Type.TypeId,
            state_ty: Type.TypeId,
            ret_ty: Type.TypeId,
            def_id: DraftDefId = undefined,
            plan_inputs: ?*SerializationPlanInputs = null,
            helper_plan: ?*SerializationHelperPlan = null,
            value_local: DraftLocalId = undefined,
            state_local: DraftLocalId = undefined,
            encoding_local: DraftLocalId = undefined,
        },
        tuple: struct { inputs: EncodeInputs, value: EncodeValue, item_tys: []Type.TypeId, u64_ty: Type.TypeId = undefined, method: EncodeContainerMethod = undefined, body_state_local: DraftLocalId = undefined, writer_local: DraftLocalId = undefined },
        /// Tuple items or tag payloads written one after another, each
        /// sequenced after the previous item's state.
        items: struct {
            inputs: EncodeInputs,
            kind: enum { tuple_items, tag_payloads },
            value_expr: DraftExprId,
            item_tys: []const Type.TypeId,
            payload_exprs: []const DraftExprId,
            state_expr: DraftExprId,
            method: EncodeContainerMethod,
            writer_expr: DraftExprId,
            index: usize = 0,
            written: std.ArrayList(EncodeWrittenItem) = .empty,
        },
        list: struct { inputs: EncodeInputs, value: EncodeValue, elem_ty: Type.TypeId, loop: EncodeLoop = undefined, body_state_local: DraftLocalId = undefined, writer_local: DraftLocalId = undefined, len_value: DraftExprId = undefined, u64_ty: Type.TypeId = undefined },
        dict: struct {
            inputs: EncodeInputs,
            value: EncodeValue,
            key_ty: Type.TypeId,
            item_ty: Type.TypeId,
            loop: EncodeLoop = undefined,
            entries_local: DraftLocalId = undefined,
            entries_ty: Type.TypeId = undefined,
            entries_expr: DraftExprId = undefined,
            body_state_local: DraftLocalId = undefined,
            writer_local: DraftLocalId = undefined,
            len_value: DraftExprId = undefined,
            u64_ty: Type.TypeId = undefined,
        },
        /// One pass of a list or dict element loop.
        loop_body: struct { inputs: EncodeInputs, kind: enum { list, dict }, elem_ty: Type.TypeId, key_ty: Type.TypeId, entry_ty: Type.TypeId, value_expr: DraftExprId, loop: EncodeLoop, done_cond: DraftExprId = undefined, finish_body: DraftExprId = undefined },
        list_element: struct { inputs: EncodeInputs, elem_ty: Type.TypeId, value_expr: DraftExprId, loop: EncodeLoop, element_expr: DraftExprId = undefined, element_local: DraftLocalId = undefined, index_expr: DraftExprId = undefined },
        dict_entry: struct {
            inputs: EncodeInputs,
            key_ty: Type.TypeId,
            value_ty: Type.TypeId,
            entry_ty: Type.TypeId,
            entries_expr: DraftExprId,
            loop: EncodeLoop,
            index_expr: DraftExprId = undefined,
            item_value_expr: DraftExprId = undefined,
            key_writer: DraftExprId = undefined,
        },
        key_thunk: struct { inputs: EncodeInputs, key_ty: Type.TypeId, key_expr: DraftExprId, state_ty: Type.TypeId, ret_ty: Type.TypeId, state_local: DraftLocalId = undefined, thunk_ty: Type.TypeId = undefined },
        key_to_state: struct { inputs: EncodeInputs, value: EncodeValue, start_expr: DraftExprId = undefined, opened_local: DraftLocalId = undefined },
        null_try: struct { inputs: EncodeInputs, value: EncodeValue, info: TryNullInfo, ok_pat: DraftPatId = undefined, try_info: TryInfo = undefined },
        record: struct {
            inputs: EncodeInputs,
            value: EncodeValue,
            record_fields: []Type.Field = &.{},
            renamed_field_locals: []const DraftLocalId = &.{},
            owned_renamed_field_locals: ?[]DraftLocalId = null,
            owned_renamed_field_values: ?[]DraftExprId = null,
            u64_ty: Type.TypeId = undefined,
            method: EncodeContainerMethod = undefined,
            body_state_local: DraftLocalId = undefined,
            writer_local: DraftLocalId = undefined,
        },
        /// Record fields written one after another, each sequenced after the
        /// previous field's state.
        record_fields: struct {
            inputs: EncodeInputs,
            value_expr: DraftExprId,
            record_fields: []const Type.Field,
            renamed_field_locals: []const DraftLocalId,
            state_expr: DraftExprId,
            method: EncodeContainerMethod,
            writer_expr: DraftExprId,
            index: usize = 0,
            field_value_expr: DraftExprId = undefined,
            field_form: enum { present, optional, slot } = .present,
            optional_info: TryInfo = undefined,
            field_try_info: TryInfo = undefined,
            slot: Builder.OptionalSlotInfo = undefined,
            present_pat: DraftPatId = undefined,
            written: std.ArrayList(EncodeWrittenItem) = .empty,
        },
        /// A present field's value written through the field writer.
        present_field: struct { inputs: EncodeInputs, state_expr: DraftExprId, method: EncodeContainerMethod, renamed_field_expr: DraftExprId, writer_expr: DraftExprId, value_ty: Type.TypeId, value_expr: DraftExprId },
        tag_union: struct {
            inputs: EncodeInputs,
            value: EncodeValue,
            tags_span: Type.Span,
            tags: []Type.Tag = &.{},
            value_ty: Type.TypeId = undefined,
            pat: DraftPatId = undefined,
            branches: []DraftBranch = &.{},
            index: usize = 0,
            payload_tys: []Type.TypeId = &.{},
            payload_exprs: []DraftExprId = &.{},
        },
        tag_branch: struct {
            inputs: EncodeInputs,
            tag_union_ty: Type.TypeId,
            tag: Type.Tag,
            payload_exprs: []const DraftExprId,
            payload_tys: []const Type.TypeId,
            state_expr: DraftExprId,
            state_ty: Type.TypeId,
            ret_ty: Type.TypeId,
            tag_name_expr: DraftExprId = undefined,
            u64_ty: Type.TypeId = undefined,
            method: EncodeContainerMethod = undefined,
            body_state_local: DraftLocalId = undefined,
            writer_local: DraftLocalId = undefined,
        },
    };

    /// A written item's result and the local its successor's state binds.
    const EncodeWrittenItem = struct {
        try_expr: DraftExprId,
        done_local: DraftLocalId,
    };

    const EncodeResult = union(enum) {
        expr: DraftExprId,
        def: DraftDefId,
    };

    const EncodeFrame = struct {
        task: EncodeTask,
        stage: u8 = 0,
        /// The callable-body demand scope this frame entered, left when the
        /// frame finishes.
        scope: ?CallableBodyDemandScope = null,
    };

    const EncodeStep = union(enum) {
        /// Encode a component; the frame resumes with its result.
        child: EncodeTask,
        /// This frame's result is the component's result.
        tail: EncodeTask,
        done: EncodeResult,
    };

    fn lowerEncodeShapeToState(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        var frames = std.ArrayList(EncodeFrame).empty;
        defer {
            var index = frames.items.len;
            while (index > 0) {
                index -= 1;
                self.releaseEncodeFrame(&frames.items[index]);
            }
            frames.deinit(self.allocator);
        }
        try frames.append(self.allocator, .{ .task = .{ .shape = .{
            .inputs = .{ .encoding_expr = encoding_expr, .encoding_ty = encoding_ty, .precomputed_plan = precomputed_plan },
            .value = .{ .shape_ty = shape_ty, .value_expr = value_expr, .state_expr = state_expr, .state_ty = state_ty, .ret_ty = ret_ty },
        } } });
        var input: ?EncodeResult = null;
        while (true) {
            const frame = &frames.items[frames.items.len - 1];
            const step = try self.stepEncode(frame, input);
            input = null;
            switch (step) {
                .child => |task| try frames.append(self.allocator, .{ .task = task }),
                .tail => |task| {
                    self.releaseEncodeFrame(frame);
                    frame.* = .{ .task = task };
                },
                .done => |result| {
                    var finished = frames.pop().?;
                    self.releaseEncodeFrame(&finished);
                    if (frames.items.len == 0) return result.expr;
                    input = result;
                },
            }
        }
    }

    /// Leave the frame's demand scope and free what it owns. Idempotent.
    fn releaseEncodeFrame(self: *BodyContext, frame: *EncodeFrame) void {
        if (frame.scope) |scope| scope.leave();
        frame.scope = null;
        switch (frame.task) {
            .def => |*def| {
                if (def.helper_plan) |plan| {
                    plan.deinit(self.allocator);
                    self.allocator.destroy(plan);
                }
                def.helper_plan = null;
                if (def.plan_inputs) |inputs| {
                    inputs.deinit(self.allocator);
                    self.allocator.destroy(inputs);
                }
                def.plan_inputs = null;
            },
            .tuple => |*tuple| {
                self.allocator.free(tuple.item_tys);
                tuple.item_tys = &.{};
            },
            .items => |*items| items.written.deinit(self.allocator),
            .record => |*record| {
                self.allocator.free(record.record_fields);
                record.record_fields = &.{};
                if (record.owned_renamed_field_locals) |locals| self.allocator.free(locals);
                record.owned_renamed_field_locals = null;
                if (record.owned_renamed_field_values) |values| self.allocator.free(values);
                record.owned_renamed_field_values = null;
            },
            .record_fields => |*fields| fields.written.deinit(self.allocator),
            .tag_union => |*tag_union| {
                self.allocator.free(tag_union.tags);
                tag_union.tags = &.{};
                self.allocator.free(tag_union.branches);
                tag_union.branches = &.{};
                self.allocator.free(tag_union.payload_tys);
                tag_union.payload_tys = &.{};
                self.allocator.free(tag_union.payload_exprs);
                tag_union.payload_exprs = &.{};
            },
            .shape, .value_thunk, .helper_call, .list, .dict, .loop_body, .list_element, .dict_entry, .key_thunk, .key_to_state, .null_try, .present_field, .tag_branch => {},
        }
    }

    fn encodeExpr(expr: DraftExprId) EncodeStep {
        return .{ .done = .{ .expr = expr } };
    }

    fn stepEncode(self: *BodyContext, frame: *EncodeFrame, input: ?EncodeResult) Allocator.Error!EncodeStep {
        const stage = frame.stage;
        frame.stage += 1;
        switch (frame.task) {
            .shape => |*task| return try self.stepEncodeShape(task, stage, input),
            .value_thunk => |*task| {
                if (stage == 0) {
                    task.thunk_ty = try self.encodeValueThunkType(task.state_ty, task.ret_ty);
                    task.state_local = try self.addLocal(self.builder.symbols.fresh(), task.state_ty);
                    frame.scope = try self.enterCallableBodyDemandScope(&.{task.state_ty}, &.{ task.value_ty, task.inputs.encoding_ty });
                    return .{ .child = .{ .helper_call = .{ .inputs = task.inputs, .value = .{
                        .shape_ty = task.value_ty,
                        .value_expr = task.value_expr,
                        .state_expr = try self.localExpr(task.state_local, task.state_ty),
                        .state_ty = task.state_ty,
                        .ret_ty = task.ret_ty,
                    } } } };
                }
                frame.scope.?.leave();
                frame.scope = null;
                return encodeExpr(try self.lowerGeneratedEncoderCallbackLambda(
                    task.thunk_ty,
                    &.{.{ .local = task.state_local, .ty = task.state_ty }},
                    input.?.expr,
                ));
            },
            .helper_call => |*task| {
                if (stage == 0) return .{ .child = .{ .def = .{
                    .inputs = task.inputs,
                    .value_ty = task.value.shape_ty,
                    .state_ty = task.value.state_ty,
                    .ret_ty = task.value.ret_ty,
                } } };
                const def_id = input.?.def;
                const value_ty = task.value.shape_ty;
                var plan_inputs = try self.serializationPlanInputs(.encoder, value_ty, task.inputs.precomputed_plan);
                defer plan_inputs.deinit(self.allocator);
                const str_ty = try self.primitiveType(.str);
                const arg_tys = try self.allocator.alloc(Type.TypeId, 3 + plan_inputs.locals.items.len);
                defer self.allocator.free(arg_tys);
                const args = try self.allocator.alloc(DraftExprId, arg_tys.len);
                defer self.allocator.free(args);
                arg_tys[0] = value_ty;
                arg_tys[1] = task.value.state_ty;
                arg_tys[2] = task.inputs.encoding_ty;
                args[0] = task.value.value_expr;
                args[1] = task.value.state_expr;
                args[2] = task.inputs.encoding_expr;
                for (plan_inputs.locals.items, 0..) |local, index| {
                    arg_tys[3 + index] = str_ty;
                    args[3 + index] = try self.localExpr(local, str_ty);
                }
                const fn_ty = try self.functionType(arg_tys, task.value.ret_ty);
                const callee = try self.addExpr(.{
                    .ty = fn_ty,
                    .data = .{ .def_ref = .{ .draft = def_id } },
                });
                return encodeExpr(try self.addExpr(.{
                    .ty = task.value.ret_ty,
                    .data = .{ .call_value = .{
                        .callee = callee,
                        .args = try self.addExprSpan(args),
                    } },
                }));
            },
            .def => |*task| return try self.stepEncodeDef(task, stage, input),
            .tuple => |*task| {
                if (stage == 0) {
                    task.u64_ty = try self.primitiveType(.u64);
                    const tuple_ty = try self.exprType(task.value.value_expr);
                    task.method = try self.resolveEncodeContainerMethod("encode_tuple", .tuple, tuple_ty, task.value.state_ty, task.value.ret_ty);
                    task.body_state_local = try self.addLocal(self.builder.symbols.fresh(), task.method.container_state_ty);
                    task.writer_local = try self.addLocal(self.builder.symbols.fresh(), task.method.writer_ty);
                    frame.scope = try self.enterCallableBodyDemandScope(
                        &.{ task.method.container_state_ty, task.method.writer_ty },
                        &.{ tuple_ty, task.inputs.encoding_ty },
                    );
                    return .{ .child = .{ .items = .{
                        .inputs = task.inputs,
                        .kind = .tuple_items,
                        .value_expr = task.value.value_expr,
                        .item_tys = task.item_tys,
                        .payload_exprs = &.{},
                        .state_expr = try self.localExpr(task.body_state_local, task.method.container_state_ty),
                        .method = task.method,
                        .writer_expr = try self.localExpr(task.writer_local, task.method.writer_ty),
                    } } };
                }
                frame.scope.?.leave();
                frame.scope = null;
                const u64_ty = task.u64_ty;
                const body_lambda = try self.lowerGeneratedEncoderCallbackLambda(
                    task.method.body_ty,
                    &.{
                        .{ .local = task.body_state_local, .ty = task.method.container_state_ty },
                        .{ .local = task.writer_local, .ty = task.method.writer_ty },
                    },
                    input.?.expr,
                );
                return encodeExpr(try self.lowerEncodeContainerMethodCall(
                    task.method,
                    &.{ task.value.state_expr, try self.intLiteralExpr(@intCast(task.item_tys.len), u64_ty), body_lambda },
                ));
            },
            .items => |*task| {
                if (stage != 0) {
                    const item_writer = input.?.expr;
                    const item_try = try self.addExpr(.{
                        .ty = task.method.container_result_ty,
                        .data = .{ .call_value = .{
                            .callee = task.writer_expr,
                            .args = try self.addExprSpan(&[_]DraftExprId{ task.state_expr, item_writer }),
                        } },
                    });
                    const item_done_local = try self.addLocal(self.builder.symbols.fresh(), task.method.container_state_ty);
                    try task.written.append(self.allocator, .{ .try_expr = item_try, .done_local = item_done_local });
                    task.state_expr = try self.localExpr(item_done_local, task.method.container_state_ty);
                    task.index += 1;
                }
                if (task.index < task.item_tys.len) {
                    const item_ty = task.item_tys[task.index];
                    const item_expr = switch (task.kind) {
                        .tuple_items => try self.addExpr(.{ .ty = item_ty, .data = .{ .tuple_access = .{
                            .tuple = task.value_expr,
                            .elem_index = @intCast(task.index),
                        } } }),
                        .tag_payloads => task.payload_exprs[task.index],
                    };
                    return .{ .child = .{ .value_thunk = .{
                        .inputs = task.inputs,
                        .value_ty = item_ty,
                        .value_expr = item_expr,
                        .state_ty = task.method.state_ty,
                        .ret_ty = task.method.result_ty,
                    } } };
                }
                return encodeExpr(try self.foldEncodeWritten(task.method, task.written.items, try self.tryOk(task.method.container_result_ty, task.state_expr)));
            },
            .list => |*task| {
                if (stage == 0) {
                    task.u64_ty = try self.primitiveType(.u64);
                    const list_ty = try self.exprType(task.value.value_expr);
                    const method = try self.resolveEncodeContainerMethod("encode_list", .list, list_ty, task.value.state_ty, task.value.ret_ty);
                    task.body_state_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
                    task.writer_local = try self.addLocal(self.builder.symbols.fresh(), method.writer_ty);
                    const len_local = try self.addLocal(self.builder.symbols.fresh(), task.u64_ty);
                    const index_local = try self.addLocal(self.builder.symbols.fresh(), task.u64_ty);
                    const loop_state_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
                    task.len_value = try self.lowLevelExpr(.list_len, &.{task.value.value_expr}, task.u64_ty);
                    frame.scope = try self.enterCallableBodyDemandScope(
                        &.{ method.container_state_ty, method.writer_ty },
                        &.{ list_ty, task.inputs.encoding_ty, task.u64_ty },
                    );
                    task.loop = .{
                        .method = method,
                        .len_local = len_local,
                        .index_local = index_local,
                        .loop_state_local = loop_state_local,
                        .writer_expr = try self.localExpr(task.writer_local, method.writer_ty),
                    };
                    return .{ .child = .{ .loop_body = .{
                        .inputs = task.inputs,
                        .kind = .list,
                        .elem_ty = task.elem_ty,
                        .key_ty = undefined,
                        .entry_ty = undefined,
                        .value_expr = task.value.value_expr,
                        .loop = task.loop,
                    } } };
                }
                const loop_expr = try self.encodeLoopExpr(task.loop, task.body_state_local, task.u64_ty, input.?.expr);
                frame.scope.?.leave();
                frame.scope = null;
                const method = task.loop.method;
                const body_lambda = try self.lowerGeneratedEncoderCallbackLambda(
                    method.body_ty,
                    &.{
                        .{ .local = task.body_state_local, .ty = method.container_state_ty },
                        .{ .local = task.writer_local, .ty = method.writer_ty },
                    },
                    loop_expr,
                );
                const encode_list = try self.lowerEncodeContainerMethodCall(
                    method,
                    &.{ task.value.state_expr, try self.localExpr(task.loop.len_local, task.u64_ty), body_lambda },
                );
                return encodeExpr(try self.wrapLet(task.loop.len_local, task.u64_ty, task.len_value, encode_list, task.value.ret_ty));
            },
            .dict => |*task| return try self.stepEncodeDict(frame, task, stage, input),
            .loop_body => |*task| {
                if (stage == 0) {
                    const u64_ty = try self.primitiveType(.u64);
                    const bool_ty = try self.primitiveType(.bool);
                    const index_expr = try self.localExpr(task.loop.index_local, u64_ty);
                    const len_expr = try self.localExpr(task.loop.len_local, u64_ty);
                    task.done_cond = try self.lowLevelExpr(.num_is_eq, &.{ index_expr, len_expr }, bool_ty);
                    task.finish_body = try self.addExpr(.{
                        .ty = task.loop.method.container_result_ty,
                        .data = .{ .break_ = try self.tryOk(task.loop.method.container_result_ty, try self.localExpr(task.loop.loop_state_local, task.loop.method.container_state_ty)) },
                    });
                    return switch (task.kind) {
                        .list => .{ .child = .{ .list_element = .{
                            .inputs = task.inputs,
                            .elem_ty = task.elem_ty,
                            .value_expr = task.value_expr,
                            .loop = task.loop,
                        } } },
                        .dict => .{ .child = .{ .dict_entry = .{
                            .inputs = task.inputs,
                            .key_ty = task.key_ty,
                            .value_ty = task.elem_ty,
                            .entry_ty = task.entry_ty,
                            .entries_expr = task.value_expr,
                            .loop = task.loop,
                        } } },
                    };
                }
                return encodeExpr(try self.ifExpr(task.done_cond, task.finish_body, input.?.expr, task.loop.method.container_result_ty));
            },
            .list_element => |*task| {
                const method = task.loop.method;
                const u64_ty = try self.primitiveType(.u64);
                if (stage == 0) {
                    task.index_expr = try self.localExpr(task.loop.index_local, u64_ty);
                    task.element_expr = try self.lowLevelExpr(.list_get_unsafe, &.{ task.value_expr, task.index_expr }, task.elem_ty);
                    task.element_local = try self.addLocal(self.builder.symbols.fresh(), task.elem_ty);
                    return .{ .child = .{ .value_thunk = .{
                        .inputs = task.inputs,
                        .value_ty = task.elem_ty,
                        .value_expr = try self.localExpr(task.element_local, task.elem_ty),
                        .state_ty = method.state_ty,
                        .ret_ty = method.result_ty,
                    } } };
                }
                const element_writer = input.?.expr;
                const element_try = try self.addExpr(.{
                    .ty = method.container_result_ty,
                    .data = .{ .call_value = .{
                        .callee = task.loop.writer_expr,
                        .args = try self.addExprSpan(&[_]DraftExprId{
                            try self.localExpr(task.loop.loop_state_local, method.container_state_ty),
                            element_writer,
                        }),
                    } },
                });
                const element_done_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
                const continue_expr = try self.encodeLoopContinue(method, task.index_expr, element_done_local, u64_ty);
                const after_element = try self.sequenceEncodeTry(element_try, method.container_result_ty, element_done_local, continue_expr, method.container_result_ty);
                return encodeExpr(try self.wrapLet(task.element_local, task.elem_ty, task.element_expr, after_element, method.container_result_ty));
            },
            .dict_entry => |*task| {
                const method = task.loop.method;
                const u64_ty = try self.primitiveType(.u64);
                switch (stage) {
                    0 => {
                        task.index_expr = try self.localExpr(task.loop.index_local, u64_ty);
                        const entry_expr = try self.lowLevelExpr(.list_get_unsafe, &.{ task.entries_expr, task.index_expr }, task.entry_ty);
                        const key_expr = try self.addExpr(.{ .ty = task.key_ty, .data = .{ .tuple_access = .{
                            .tuple = entry_expr,
                            .elem_index = 0,
                        } } });
                        const entry_expr_for_value = try self.lowLevelExpr(.list_get_unsafe, &.{ task.entries_expr, task.index_expr }, task.entry_ty);
                        task.item_value_expr = try self.addExpr(.{ .ty = task.value_ty, .data = .{ .tuple_access = .{
                            .tuple = entry_expr_for_value,
                            .elem_index = 1,
                        } } });
                        return .{ .child = .{ .key_thunk = .{
                            .inputs = task.inputs,
                            .key_ty = task.key_ty,
                            .key_expr = key_expr,
                            .state_ty = method.state_ty,
                            .ret_ty = method.result_ty,
                        } } };
                    },
                    1 => {
                        task.key_writer = input.?.expr;
                        return .{ .child = .{ .value_thunk = .{
                            .inputs = task.inputs,
                            .value_ty = task.value_ty,
                            .value_expr = task.item_value_expr,
                            .state_ty = method.state_ty,
                            .ret_ty = method.result_ty,
                        } } };
                    },
                    else => {
                        const value_writer = input.?.expr;
                        const value_try = try self.addExpr(.{
                            .ty = method.container_result_ty,
                            .data = .{ .call_value = .{
                                .callee = task.loop.writer_expr,
                                .args = try self.addExprSpan(&[_]DraftExprId{
                                    try self.localExpr(task.loop.loop_state_local, method.container_state_ty),
                                    task.key_writer,
                                    value_writer,
                                }),
                            } },
                        });
                        const value_done_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
                        const continue_expr = try self.encodeLoopContinue(method, task.index_expr, value_done_local, u64_ty);
                        return encodeExpr(try self.sequenceEncodeTry(value_try, method.container_result_ty, value_done_local, continue_expr, method.container_result_ty));
                    },
                }
            },
            .key_thunk => |*task| {
                // A dict key is written by the same kind of thunk a value
                // uses, so the format controls how a key is rendered rather
                // than receiving a Str the driver already committed to.
                if (stage == 0) {
                    task.thunk_ty = try self.functionType(&.{task.state_ty}, task.ret_ty);
                    task.state_local = try self.addLocal(self.builder.symbols.fresh(), task.state_ty);
                    return .{ .child = .{ .key_to_state = .{ .inputs = task.inputs, .value = .{
                        .shape_ty = task.key_ty,
                        .value_expr = task.key_expr,
                        .state_expr = try self.localExpr(task.state_local, task.state_ty),
                        .state_ty = task.state_ty,
                        .ret_ty = task.ret_ty,
                    } } } };
                }
                return encodeExpr(try self.lowerGeneratedEncoderCallbackLambda(
                    task.thunk_ty,
                    &.{.{ .local = task.state_local, .ty = task.state_ty }},
                    input.?.expr,
                ));
            },
            .key_to_state => |*task| {
                const value = task.value;
                if (stage == 0) {
                    if (self.scalarCodecMethodName(value.shape_ty, "encode_key_")) |method_name| {
                        return encodeExpr(try self.lowerEncodeFormatMethod(
                            method_name,
                            &.{ task.inputs.encoding_expr, value.value_expr, value.state_expr },
                            &.{ task.inputs.encoding_ty, value.shape_ty, value.state_ty },
                            value.shape_ty,
                            value.ret_ty,
                        ));
                    }
                    if (self.dictKeyUnitTags(value.shape_ty)) |tags_span| {
                        const str_ty = try self.primitiveType(.str);
                        const key_string = try self.lowerEncodeUnitTagDictKeyToString(tags_span, value.shape_ty, value.value_expr, str_ty);
                        return encodeExpr(try self.lowerEncodeFormatMethod(
                            "encode_key_str",
                            &.{ task.inputs.encoding_expr, key_string, value.state_expr },
                            &.{ task.inputs.encoding_ty, str_ty, value.state_ty },
                            str_ty,
                            value.ret_ty,
                        ));
                    }
                    // Mirrors the parse side: a key the format cannot render as
                    // a key string is written by the key's own encoder, after
                    // `encode_key_start` opens the key position.
                    task.start_expr = try self.lowerEncodeFormatMethod(
                        "encode_key_start",
                        &.{ task.inputs.encoding_expr, value.state_expr },
                        &.{ task.inputs.encoding_ty, value.state_ty },
                        null,
                        value.ret_ty,
                    );
                    task.opened_local = try self.addLocal(self.builder.symbols.fresh(), value.state_ty);
                    return .{ .child = .{ .helper_call = .{ .inputs = task.inputs, .value = .{
                        .shape_ty = value.shape_ty,
                        .value_expr = value.value_expr,
                        .state_expr = try self.localExpr(task.opened_local, value.state_ty),
                        .state_ty = value.state_ty,
                        .ret_ty = value.ret_ty,
                    } } } };
                }
                return encodeExpr(try self.sequenceEncodeTry(task.start_expr, value.ret_ty, task.opened_local, input.?.expr, value.ret_ty));
            },
            .null_try => |*task| {
                const value = task.value;
                if (stage == 0) {
                    task.try_info = self.tryInfo(value.shape_ty);
                    const ok_payload_local = try self.addLocal(self.builder.symbols.fresh(), task.info.ok_payload_ty);
                    const ok_payload_pat = try self.bindPat(ok_payload_local, task.info.ok_payload_ty);
                    const ok_backing_pat = try self.addPat(.{ .ty = task.try_info.backing_ty, .data = .{ .tag = .{
                        .name = task.try_info.ok_tag.name,
                        .payloads = try self.addPatSpan(&[_]DraftPatId{ok_payload_pat}),
                    } } });
                    task.ok_pat = try self.addPat(.{ .ty = value.shape_ty, .data = .{ .nominal = ok_backing_pat } });
                    return .{ .child = .{ .shape = .{ .inputs = task.inputs, .value = .{
                        .shape_ty = task.info.ok_payload_ty,
                        .value_expr = try self.localExpr(ok_payload_local, task.info.ok_payload_ty),
                        .state_expr = value.state_expr,
                        .state_ty = value.state_ty,
                        .ret_ty = value.ret_ty,
                    } } } };
                }
                const ok_body = input.?.expr;
                const null_tag = self.monoTagByText(task.info.err_ty, "Null");
                if (self.typeStore().span(null_tag.payloads).len != 0) Common.invariant("JSON Null marker unexpectedly had payloads");
                const null_payload_pat = try self.addPat(.{ .ty = task.info.err_ty, .data = .{ .tag = .{
                    .name = null_tag.name,
                    .payloads = .empty(),
                } } });
                const err_backing_pat = try self.addPat(.{ .ty = task.try_info.backing_ty, .data = .{ .tag = .{
                    .name = task.try_info.err_tag.name,
                    .payloads = try self.addPatSpan(&[_]DraftPatId{null_payload_pat}),
                } } });
                const err_pat = try self.addPat(.{ .ty = value.shape_ty, .data = .{ .nominal = err_backing_pat } });
                const err_body = try self.lowerEncodeFormatMethod("encode_null", &.{value.state_expr}, &.{value.state_ty}, null, value.ret_ty);

                const branches = [_]DraftBranch{
                    .{ .pat = task.ok_pat, .body = ok_body },
                    .{ .pat = err_pat, .body = err_body },
                };
                return encodeExpr(try self.addExpr(.{ .ty = value.ret_ty, .data = .{ .match_ = .{
                    .scrutinee = value.value_expr,
                    .branches = try self.addBranchSpan(&branches),
                } } }));
            },
            .record => |*task| return try self.stepEncodeRecord(frame, task, stage, input),
            .record_fields => |*task| return try self.stepEncodeRecordFields(task, stage, input),
            .present_field => |*task| {
                if (stage == 0) return .{ .child = .{ .value_thunk = .{
                    .inputs = task.inputs,
                    .value_ty = task.value_ty,
                    .value_expr = task.value_expr,
                    .state_ty = task.method.state_ty,
                    .ret_ty = task.method.result_ty,
                } } };
                return encodeExpr(try self.addExpr(.{
                    .ty = task.method.container_result_ty,
                    .data = .{ .call_value = .{
                        .callee = task.writer_expr,
                        .args = try self.addExprSpan(&[_]DraftExprId{ task.state_expr, task.renamed_field_expr, input.?.expr }),
                    } },
                }));
            },
            .tag_union => |*task| return try self.stepEncodeTagUnion(task, stage, input),
            .tag_branch => |*task| {
                if (stage == 0) {
                    if (task.payload_exprs.len != task.payload_tys.len) Common.invariant("tag union encode payload arity mismatch");
                    task.tag_name_expr = try self.stringExpr(self.nameStore().tagLabelText(task.tag.name), try self.primitiveType(.str));
                    task.u64_ty = try self.primitiveType(.u64);
                    task.method = try self.resolveEncodeContainerMethod("encode_tag", .tag, task.tag_union_ty, task.state_ty, task.ret_ty);
                    task.body_state_local = try self.addLocal(self.builder.symbols.fresh(), task.method.container_state_ty);
                    task.writer_local = try self.addLocal(self.builder.symbols.fresh(), task.method.writer_ty);
                    var capture_tys = std.ArrayList(Type.TypeId).empty;
                    defer capture_tys.deinit(self.allocator);
                    try capture_tys.appendSlice(self.allocator, task.payload_tys);
                    try capture_tys.append(self.allocator, task.inputs.encoding_ty);
                    frame.scope = try self.enterCallableBodyDemandScope(
                        &.{ task.method.container_state_ty, task.method.writer_ty },
                        capture_tys.items,
                    );
                    return .{ .child = .{ .items = .{
                        .inputs = task.inputs,
                        .kind = .tag_payloads,
                        .value_expr = undefined,
                        .item_tys = task.payload_tys,
                        .payload_exprs = task.payload_exprs,
                        .state_expr = try self.localExpr(task.body_state_local, task.method.container_state_ty),
                        .method = task.method,
                        .writer_expr = try self.localExpr(task.writer_local, task.method.writer_ty),
                    } } };
                }
                frame.scope.?.leave();
                frame.scope = null;
                const u64_ty = task.u64_ty;
                const payloads_lambda = try self.lowerGeneratedEncoderCallbackLambda(
                    task.method.body_ty,
                    &.{
                        .{ .local = task.body_state_local, .ty = task.method.container_state_ty },
                        .{ .local = task.writer_local, .ty = task.method.writer_ty },
                    },
                    input.?.expr,
                );
                return encodeExpr(try self.lowerEncodeContainerMethodCall(
                    task.method,
                    &.{ task.state_expr, task.tag_name_expr, try self.intLiteralExpr(@intCast(task.payload_tys.len), u64_ty), payloads_lambda },
                ));
            },
        }
    }

    /// Sequence written items from the last to the first around `tail`: each
    /// item's result binds its successor's state.
    fn foldEncodeWritten(self: *BodyContext, method: EncodeContainerMethod, written: []const EncodeWrittenItem, tail: DraftExprId) Allocator.Error!DraftExprId {
        var result = tail;
        var index = written.len;
        while (index > 0) {
            index -= 1;
            result = try self.sequenceEncodeTry(written[index].try_expr, method.container_result_ty, written[index].done_local, result, method.container_result_ty);
        }
        return result;
    }

    /// Continue a container loop at the next index with the state `done_local`
    /// binds.
    fn encodeLoopContinue(
        self: *BodyContext,
        method: EncodeContainerMethod,
        index_expr: DraftExprId,
        done_local: DraftLocalId,
        u64_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const next_index = try self.lowLevelExpr(.num_plus, &.{ index_expr, try self.intLiteralExpr(1, u64_ty) }, u64_ty);
        return try self.addExpr(.{ .ty = method.container_result_ty, .data = .{ .continue_ = .{
            .values = try self.addExprSpan(&[_]DraftExprId{
                next_index,
                try self.localExpr(done_local, method.container_state_ty),
            }),
        } } });
    }

    /// The loop running a container's element pass from index zero.
    fn encodeLoopExpr(
        self: *BodyContext,
        loop: EncodeLoop,
        body_state_local: DraftLocalId,
        u64_ty: Type.TypeId,
        loop_body: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const params = [_]BodyTypedLocal{
            .{ .local = loop.index_local, .ty = u64_ty },
            .{ .local = loop.loop_state_local, .ty = loop.method.container_state_ty },
        };
        const initial_values = [_]DraftExprId{
            try self.intLiteralExpr(0, u64_ty),
            try self.localExpr(body_state_local, loop.method.container_state_ty),
        };
        return try self.addExpr(.{ .ty = loop.method.container_result_ty, .data = .{ .loop_ = .{
            .params = try self.addTypedLocalSpan(&params),
            .initial_values = try self.addExprSpan(&initial_values),
            .body = loop_body,
        } } });
    }

    fn stepEncodeShape(
        self: *BodyContext,
        task: *@FieldType(EncodeTask, "shape"),
        stage: u8,
        input: ?EncodeResult,
    ) Allocator.Error!EncodeStep {
        const value = task.value;
        if (stage != 0) {
            const unwrap_pat = try self.addPat(.{
                .ty = value.shape_ty,
                .data = .{ .nominal = try self.bindPat(task.backing_local, task.backing_ty) },
            });
            const branch = DraftBranch{ .pat = unwrap_pat, .body = input.?.expr };
            const matched = try self.addExpr(.{ .ty = value.ret_ty, .data = .{ .match_ = .{
                .scrutinee = try self.localExpr(task.value_local, value.shape_ty),
                .branches = try self.addBranchSpan(&[_]DraftBranch{branch}),
            } } });
            return encodeExpr(try self.wrapLet(task.value_local, value.shape_ty, value.value_expr, matched, value.ret_ty));
        }
        const shape_ty = value.shape_ty;
        if (self.tryNullInfo(shape_ty)) |info| {
            return .{ .tail = .{ .null_try = .{ .inputs = task.inputs, .value = value, .info = info } } };
        }
        if (self.dictEntryShape(shape_ty)) |dict| {
            return .{ .tail = .{ .dict = .{ .inputs = task.inputs, .value = value, .key_ty = dict.key_ty, .item_ty = dict.value_ty } } };
        }
        if (self.setPayloadType(shape_ty)) |payload_ty| {
            const list_ty = try self.listType(payload_ty);
            var list_value = value;
            list_value.value_expr = try self.lowerSetToList(shape_ty, list_ty, value.value_expr);
            return .{ .tail = .{ .list = .{ .inputs = task.inputs, .value = list_value, .elem_ty = payload_ty } } };
        }
        // The checked nominal codec owns this value, regardless of its backing shape.
        if (self.frozenCustomCodecCallForShape(.encoder, shape_ty)) |prepared| {
            return encodeExpr(try self.lowerCustomEncoderForState(
                prepared.*,
                shape_ty,
                value.value_expr,
                task.inputs.encoding_expr,
                task.inputs.encoding_ty,
                value.state_expr,
                value.state_ty,
                value.ret_ty,
            ));
        }
        switch (self.shapeContent(shape_ty)) {
            .list => |elem_ty| return .{ .tail = .{ .list = .{ .inputs = task.inputs, .value = value, .elem_ty = elem_ty } } },
            .tuple => |items| {
                const item_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(items));
                return .{ .tail = .{ .tuple = .{ .inputs = task.inputs, .value = value, .item_tys = item_tys } } };
            },
            .box => |payload_ty| {
                var unboxed = value;
                unboxed.shape_ty = payload_ty;
                unboxed.value_expr = try self.lowLevelExpr(.box_unbox, &.{value.value_expr}, payload_ty);
                return .{ .tail = .{ .shape = .{ .inputs = task.inputs, .value = unboxed } } };
            },
            .primitive, .named, .record, .tag_union, .func, .erased, .zst => {},
        }
        if (self.scalarCodecMethodName(shape_ty, "encode_")) |method_name| {
            return encodeExpr(try self.lowerEncodeFormatMethod(method_name, &.{ value.value_expr, value.state_expr }, &.{ shape_ty, value.state_ty }, shape_ty, value.ret_ty));
        }
        // A nominal opaque with a scalar backing and no custom encoder (e.g. `Username := Str`)
        // encodes as its backing: unwrap one nominal layer and encode the scalar.
        if (self.nominalExprBackingType(shape_ty)) |backing_ty| {
            if (self.scalarCodecMethodName(backing_ty, "encode_") != null) {
                task.backing_ty = backing_ty;
                task.value_local = try self.addLocal(self.builder.symbols.fresh(), shape_ty);
                task.backing_local = try self.addLocal(self.builder.symbols.fresh(), backing_ty);
                var backing = value;
                backing.shape_ty = backing_ty;
                backing.value_expr = try self.localExpr(task.backing_local, backing_ty);
                return .{ .child = .{ .shape = .{ .inputs = task.inputs, .value = backing } } };
            }
        }
        return switch (self.shapeContent(shape_ty)) {
            .record, .zst => .{ .tail = .{ .record = .{ .inputs = task.inputs, .value = value } } },
            .tag_union => |tags_span| .{ .tail = .{ .tag_union = .{ .inputs = task.inputs, .value = value, .tags_span = tags_span } } },
            .primitive, .named, .tuple, .list, .box, .func, .erased => Common.invariant("encoder_for selected an unsupported shape"),
        };
    }

    /// The helper encoding values of `task.value_ty`, reserved before its body
    /// is lowered so a recursive type's helper calls itself.
    fn stepEncodeDef(
        self: *BodyContext,
        task: *@FieldType(EncodeTask, "def"),
        stage: u8,
        input: ?EncodeResult,
    ) Allocator.Error!EncodeStep {
        const address = GeneratedEncoderDefAddress{
            .value_ty = @backingInt(task.value_ty),
            .encoding_ty = @backingInt(task.inputs.encoding_ty),
            .state_ty = @backingInt(task.state_ty),
            .result = self.typeStore().typeDigestCached(self.nameStore(), task.ret_ty, null),
        };
        if (stage == 0) {
            if (self.encoder_defs.get(address)) |entry| return .{ .done = .{ .def = entry.id() } };

            task.def_id = try self.draft.reserveDef(self.draft.current_owner);
            try self.encoder_defs.put(address, .{ .reserved = task.def_id });

            const plan_inputs = try self.allocator.create(SerializationPlanInputs);
            plan_inputs.* = self.serializationPlanInputs(.encoder, task.value_ty, task.inputs.precomputed_plan) catch |err| {
                self.allocator.destroy(plan_inputs);
                return err;
            };
            task.plan_inputs = plan_inputs;
            const str_ty = try self.primitiveType(.str);
            if (task.inputs.precomputed_plan) |plan| {
                const helper_plan = try self.allocator.create(SerializationHelperPlan);
                helper_plan.* = self.cloneSerializationHelperPlan(plan, plan_inputs, str_ty) catch |err| {
                    self.allocator.destroy(helper_plan);
                    return err;
                };
                task.helper_plan = helper_plan;
            }

            task.value_local = try self.addLocal(self.builder.symbols.fresh(), task.value_ty);
            task.state_local = try self.addLocal(self.builder.symbols.fresh(), task.state_ty);
            task.encoding_local = try self.addLocal(self.builder.symbols.fresh(), task.inputs.encoding_ty);
            const value_expr = try self.localExpr(task.value_local, task.value_ty);
            const encoding_expr = try self.localExpr(task.encoding_local, task.inputs.encoding_ty);
            const state_expr = try self.localExpr(task.state_local, task.state_ty);
            return .{ .child = .{ .shape = .{
                .inputs = .{
                    .encoding_expr = encoding_expr,
                    .encoding_ty = task.inputs.encoding_ty,
                    .precomputed_plan = if (task.helper_plan) |plan| &plan.plan else null,
                },
                .value = .{
                    .shape_ty = task.value_ty,
                    .value_expr = value_expr,
                    .state_expr = state_expr,
                    .state_ty = task.state_ty,
                    .ret_ty = task.ret_ty,
                },
            } } };
        }
        const body = input.?.expr;
        const plan_input_count = task.plan_inputs.?.locals.items.len;
        const args = try self.allocator.alloc(BodyTypedLocal, 3 + plan_input_count);
        defer self.allocator.free(args);
        args[0] = .{ .local = task.value_local, .ty = task.value_ty };
        args[1] = .{ .local = task.state_local, .ty = task.state_ty };
        args[2] = .{ .local = task.encoding_local, .ty = task.inputs.encoding_ty };
        if (task.helper_plan) |plan| {
            @memcpy(args[3..], plan.args);
        } else if (plan_input_count != 0) {
            Common.invariant("structural encoder helper had plan inputs without a precomputed plan");
        }
        self.draft.setDef(task.def_id, .{
            .symbol = self.builder.symbols.fresh(),
            .fn_def = null,
            .fn_id = null,
            .identity_seed = .{ .kind = "encode-shape-helper", .cells = .{ DraftTypeCell.fromSealed(task.value_ty), DraftTypeCell.fromSealed(task.inputs.encoding_ty), DraftTypeCell.fromSealed(task.state_ty), DraftTypeCell.fromSealed(task.ret_ty) } },
            .args = try self.addTypedLocalSpan(args),
            .body = .{ .roc = body },
            .ret = try self.draftTypeCell(task.ret_ty),
        });
        try self.encoder_defs.put(address, .{ .ready = task.def_id });
        return .{ .done = .{ .def = task.def_id } };
    }

    fn stepEncodeDict(
        self: *BodyContext,
        frame: *EncodeFrame,
        task: *@FieldType(EncodeTask, "dict"),
        stage: u8,
        input: ?EncodeResult,
    ) Allocator.Error!EncodeStep {
        const dict_ty = task.value.shape_ty;
        if (stage == 0) {
            const entry_ty = try self.tupleType(&.{ task.key_ty, task.item_ty });
            task.entries_ty = try self.listType(entry_ty);
            task.entries_expr = try self.lowerDictToList(dict_ty, task.entries_ty, task.value.value_expr);
            task.entries_local = try self.addLocal(self.builder.symbols.fresh(), task.entries_ty);
            task.u64_ty = try self.primitiveType(.u64);
            const method = try self.resolveEncodeContainerMethod("encode_dict", .dict, dict_ty, task.value.state_ty, task.value.ret_ty);
            task.body_state_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
            task.writer_local = try self.addLocal(self.builder.symbols.fresh(), method.writer_ty);
            const len_local = try self.addLocal(self.builder.symbols.fresh(), task.u64_ty);
            const index_local = try self.addLocal(self.builder.symbols.fresh(), task.u64_ty);
            const loop_state_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
            task.len_value = try self.lowLevelExpr(.list_len, &.{try self.localExpr(task.entries_local, task.entries_ty)}, task.u64_ty);
            frame.scope = try self.enterCallableBodyDemandScope(
                &.{ method.container_state_ty, method.writer_ty },
                &.{ task.entries_ty, task.inputs.encoding_ty, task.u64_ty },
            );
            const entries_expr = try self.localExpr(task.entries_local, task.entries_ty);
            task.loop = .{
                .method = method,
                .len_local = len_local,
                .index_local = index_local,
                .loop_state_local = loop_state_local,
                .writer_expr = try self.localExpr(task.writer_local, method.writer_ty),
            };
            return .{ .child = .{ .loop_body = .{
                .inputs = task.inputs,
                .kind = .dict,
                .elem_ty = task.item_ty,
                .key_ty = task.key_ty,
                .entry_ty = entry_ty,
                .value_expr = entries_expr,
                .loop = task.loop,
            } } };
        }
        const loop_expr = try self.encodeLoopExpr(task.loop, task.body_state_local, task.u64_ty, input.?.expr);
        frame.scope.?.leave();
        frame.scope = null;
        const method = task.loop.method;
        const body_lambda = try self.lowerGeneratedEncoderCallbackLambda(
            method.body_ty,
            &.{
                .{ .local = task.body_state_local, .ty = method.container_state_ty },
                .{ .local = task.writer_local, .ty = method.writer_ty },
            },
            loop_expr,
        );
        const encode_dict = try self.lowerEncodeContainerMethodCall(
            method,
            &.{ task.value.state_expr, try self.localExpr(task.loop.len_local, task.u64_ty), body_lambda },
        );
        const with_len = try self.wrapLet(task.loop.len_local, task.u64_ty, task.len_value, encode_dict, task.value.ret_ty);
        return encodeExpr(try self.wrapLet(task.entries_local, task.entries_ty, task.entries_expr, with_len, task.value.ret_ty));
    }

    fn stepEncodeRecord(
        self: *BodyContext,
        frame: *EncodeFrame,
        task: *@FieldType(EncodeTask, "record"),
        stage: u8,
        input: ?EncodeResult,
    ) Allocator.Error!EncodeStep {
        const value = task.value;
        if (stage == 0) {
            const ret_info = self.tryInfo(value.ret_ty);
            if (!self.sameType(ret_info.ok_ty, value.state_ty)) Common.invariant("encoder_for record return Ok type differed from state type");

            task.record_fields = try GuardedList.dupe(self.allocator, Type.Field, switch (self.shapeContent(value.shape_ty)) {
                .record => |span| self.typeStore().fieldSpan(span),
                .zst => self.typeStore().fieldSpan(.empty()),
                .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased => Common.invariant("encoder_for record requested for a non-record shape"),
            });

            const str_ty = try self.primitiveType(.str);
            const precomputed = if (task.inputs.precomputed_plan) |plan| self.parserPlanGet(plan, value.shape_ty) else null;
            if (precomputed) |record| {
                if (record.renamed_field_locals.len != task.record_fields.len) Common.invariant("encoder_for precomputed renamed field arity differed from record field count");
                task.renamed_field_locals = record.renamed_field_locals;
            } else {
                const locals = try self.allocator.alloc(DraftLocalId, task.record_fields.len);
                task.owned_renamed_field_locals = locals;
                const values = try self.allocator.alloc(DraftExprId, task.record_fields.len);
                task.owned_renamed_field_values = values;
                for (task.record_fields, 0..) |field, index| {
                    locals[index] = try self.addLocal(self.builder.symbols.fresh(), str_ty);
                    values[index] = try self.renamedRecordFieldNameExpr(.encoder, task.inputs.encoding_expr, task.inputs.encoding_ty, field, str_ty);
                }
                task.renamed_field_locals = locals;
            }

            task.u64_ty = try self.primitiveType(.u64);
            task.method = try self.resolveEncodeContainerMethod("encode_record", .record, value.shape_ty, value.state_ty, value.ret_ty);
            task.body_state_local = try self.addLocal(self.builder.symbols.fresh(), task.method.container_state_ty);
            task.writer_local = try self.addLocal(self.builder.symbols.fresh(), task.method.writer_ty);
            var capture_tys = std.ArrayList(Type.TypeId).empty;
            defer capture_tys.deinit(self.allocator);
            if (task.record_fields.len != 0) {
                try capture_tys.append(self.allocator, try self.exprType(value.value_expr));
                try capture_tys.append(self.allocator, task.inputs.encoding_ty);
                for (task.renamed_field_locals) |_| try capture_tys.append(self.allocator, str_ty);
            }
            frame.scope = try self.enterCallableBodyDemandScope(
                &.{ task.method.container_state_ty, task.method.writer_ty },
                capture_tys.items,
            );
            return .{ .child = .{ .record_fields = .{
                .inputs = task.inputs,
                .value_expr = value.value_expr,
                .record_fields = task.record_fields,
                .renamed_field_locals = task.renamed_field_locals,
                .state_expr = try self.localExpr(task.body_state_local, task.method.container_state_ty),
                .method = task.method,
                .writer_expr = try self.localExpr(task.writer_local, task.method.writer_ty),
            } } };
        }
        frame.scope.?.leave();
        frame.scope = null;
        const str_ty = try self.primitiveType(.str);
        const u64_ty = task.u64_ty;
        const fields_lambda = try self.lowerGeneratedEncoderCallbackLambda(
            task.method.body_ty,
            &.{
                .{ .local = task.body_state_local, .ty = task.method.container_state_ty },
                .{ .local = task.writer_local, .ty = task.method.writer_ty },
            },
            input.?.expr,
        );
        var body = try self.lowerEncodeContainerMethodCall(
            task.method,
            &.{ value.state_expr, try self.intLiteralExpr(@intCast(task.record_fields.len), u64_ty), fields_lambda },
        );
        if (task.owned_renamed_field_values) |renamed_field_values| {
            var index = task.renamed_field_locals.len;
            while (index > 0) {
                index -= 1;
                body = try self.wrapLet(task.renamed_field_locals[index], str_ty, renamed_field_values[index], body, value.ret_ty);
            }
        }
        return encodeExpr(body);
    }

    /// Each field waits on its value writer; a field that may be missing
    /// matches on its presence around that writer.
    fn stepEncodeRecordFields(
        self: *BodyContext,
        task: *@FieldType(EncodeTask, "record_fields"),
        stage: u8,
        input: ?EncodeResult,
    ) Allocator.Error!EncodeStep {
        const method = task.method;
        if (stage != 0) {
            const written = input.?.expr;
            const field_try = switch (task.field_form) {
                .present => written,
                .optional => blk: {
                    const optional_info = task.optional_info;
                    const field_ty = task.record_fields[task.index].ty;
                    const missing_tag = self.monoTagByText(optional_info.err_ty, "Missing");
                    if (self.typeStore().span(missing_tag.payloads).len != 0) Common.invariant("Missing marker unexpectedly had payloads");
                    const missing_payload_pat = try self.addPat(.{ .ty = optional_info.err_ty, .data = .{ .tag = .{
                        .name = missing_tag.name,
                        .payloads = .empty(),
                    } } });
                    const missing_backing_pat = try self.addPat(.{ .ty = optional_info.backing_ty, .data = .{ .tag = .{
                        .name = task.field_try_info.err_tag.name,
                        .payloads = try self.addPatSpan(&[_]DraftPatId{missing_payload_pat}),
                    } } });
                    const missing_pat = try self.addPat(.{
                        .ty = field_ty,
                        .data = .{ .nominal = missing_backing_pat },
                    });
                    break :blk try self.encodeFieldPresenceMatch(method, task.field_value_expr, task.present_pat, written, missing_pat, task.state_expr);
                },
                .slot => blk: {
                    const missing_pat = try self.addPat(.{ .ty = task.record_fields[task.index].ty, .data = .{ .tag = .{
                        .name = task.slot.missing_tag.name,
                        .payloads = .empty(),
                    } } });
                    break :blk try self.encodeFieldPresenceMatch(method, task.field_value_expr, task.present_pat, written, missing_pat, task.state_expr);
                },
            };
            const after_field_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
            try task.written.append(self.allocator, .{ .try_expr = field_try, .done_local = after_field_local });
            task.state_expr = try self.localExpr(after_field_local, method.container_state_ty);
            task.index += 1;
        }
        if (task.index >= task.record_fields.len) {
            return encodeExpr(try self.foldEncodeWritten(method, task.written.items, try self.tryOk(method.container_result_ty, task.state_expr)));
        }

        const field = task.record_fields[task.index];
        task.field_value_expr = try self.addFieldAccessExpr(task.value_expr, field.name, field.ty);
        var value_ty = field.ty;
        var value_expr = task.field_value_expr;
        if (try self.missingTryInfo(field.ty)) |optional_info| {
            const try_info = self.tryInfo(field.ty);
            if (!self.sameType(try_info.ok_ty, optional_info.ok_ty)) Common.invariant("optional encoder_for field Ok payload differed from optional info");
            if (!self.sameType(try_info.err_ty, optional_info.err_ty)) Common.invariant("optional encoder_for field Err payload differed from optional info");
            task.field_form = .optional;
            task.optional_info = optional_info;
            task.field_try_info = try_info;

            const ok_payload_local = try self.addLocal(self.builder.symbols.fresh(), optional_info.ok_ty);
            const ok_payload_pat = try self.bindPat(ok_payload_local, optional_info.ok_ty);
            const ok_backing_pat = try self.addPat(.{ .ty = optional_info.backing_ty, .data = .{ .tag = .{
                .name = try_info.ok_tag.name,
                .payloads = try self.addPatSpan(&[_]DraftPatId{ok_payload_pat}),
            } } });
            task.present_pat = try self.addPat(.{
                .ty = field.ty,
                .data = .{ .nominal = ok_backing_pat },
            });
            value_ty = optional_info.ok_ty;
            value_expr = try self.localExpr(ok_payload_local, optional_info.ok_ty);
        } else if (self.optionalFieldSlot(field.ty)) |slot| {
            // A `?:` slot is structural (no nominal wrapper), so the match is
            // directly on the reserved-label tags (design.md "Field Kinds
            // (All-Dynamic Optional Fields)").
            task.field_form = .slot;
            task.slot = slot;
            const payload_local = try self.addLocal(self.builder.symbols.fresh(), slot.payload_ty);
            const payload_pat = try self.bindPat(payload_local, slot.payload_ty);
            task.present_pat = try self.addPat(.{ .ty = field.ty, .data = .{ .tag = .{
                .name = slot.present_tag.name,
                .payloads = try self.addPatSpan(&[_]DraftPatId{payload_pat}),
            } } });
            value_ty = slot.payload_ty;
            value_expr = try self.localExpr(payload_local, slot.payload_ty);
        } else {
            task.field_form = .present;
        }
        const str_ty = try self.primitiveType(.str);
        return .{ .child = .{ .present_field = .{
            .inputs = task.inputs,
            .state_expr = task.state_expr,
            .method = method,
            .renamed_field_expr = try self.localExpr(task.renamed_field_locals[task.index], str_ty),
            .writer_expr = task.writer_expr,
            .value_ty = value_ty,
            .value_expr = value_expr,
        } } };
    }

    /// Match a maybe-missing field: a present value writes through
    /// `present_body`, and a missing one passes `state_expr` through.
    fn encodeFieldPresenceMatch(
        self: *BodyContext,
        method: EncodeContainerMethod,
        field_value_expr: DraftExprId,
        present_pat: DraftPatId,
        present_body: DraftExprId,
        missing_pat: DraftPatId,
        state_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const missing_body = try self.tryOk(method.container_result_ty, state_expr);
        const branches = [_]DraftBranch{
            .{ .pat = present_pat, .body = present_body },
            .{ .pat = missing_pat, .body = missing_body },
        };
        return try self.addExpr(.{ .ty = method.container_result_ty, .data = .{ .match_ = .{
            .scrutinee = field_value_expr,
            .branches = try self.addBranchSpan(&branches),
        } } });
    }

    fn stepEncodeTagUnion(
        self: *BodyContext,
        task: *@FieldType(EncodeTask, "tag_union"),
        stage: u8,
        input: ?EncodeResult,
    ) Allocator.Error!EncodeStep {
        if (stage == 0) {
            task.tags = try GuardedList.dupe(self.allocator, Type.Tag, self.typeStore().tagSpan(task.tags_span));
            if (task.tags.len == 0) Common.invariant("encoder_for selected an empty tag union");
            task.value_ty = try self.exprType(task.value.value_expr);
            task.branches = try self.allocator.alloc(DraftBranch, task.tags.len);
        } else {
            task.branches[task.index] = .{ .pat = task.pat, .body = input.?.expr };
            self.allocator.free(task.payload_tys);
            task.payload_tys = &.{};
            self.allocator.free(task.payload_exprs);
            task.payload_exprs = &.{};
            task.index += 1;
        }
        if (task.index == task.tags.len) {
            return encodeExpr(try self.addExpr(.{ .ty = task.value.ret_ty, .data = .{ .match_ = .{
                .scrutinee = task.value.value_expr,
                .branches = try self.addBranchSpan(task.branches),
            } } }));
        }

        const tag = task.tags[task.index];
        task.payload_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(tag.payloads));
        const payload_pats = try self.allocator.alloc(DraftPatId, task.payload_tys.len);
        defer self.allocator.free(payload_pats);
        task.payload_exprs = try self.allocator.alloc(DraftExprId, task.payload_tys.len);
        for (task.payload_tys, 0..) |payload_ty, payload_index| {
            const payload_local = try self.addLocal(self.builder.symbols.fresh(), payload_ty);
            payload_pats[payload_index] = try self.bindPat(payload_local, payload_ty);
            task.payload_exprs[payload_index] = try self.localExpr(payload_local, payload_ty);
        }
        task.pat = try self.addPat(.{ .ty = task.value_ty, .data = .{ .tag = .{
            .name = tag.name,
            .payloads = try self.addPatSpan(payload_pats),
        } } });
        return .{ .child = .{ .tag_branch = .{
            .inputs = task.inputs,
            .tag_union_ty = task.value_ty,
            .tag = tag,
            .payload_exprs = task.payload_exprs,
            .payload_tys = task.payload_tys,
            .state_expr = task.value.state_expr,
            .state_ty = task.value.state_ty,
            .ret_ty = task.value.ret_ty,
        } } };
    }

    fn functionType(self: *BodyContext, arg_tys: []const Type.TypeId, ret_ty: Type.TypeId) Allocator.Error!Type.TypeId {
        return try self.typeStore().add(.{ .func = .{
            .args = try self.typeStore().addSpan(arg_tys),
            .ret = ret_ty,
        } });
    }

    fn encodeValueThunkType(self: *BodyContext, state_ty: Type.TypeId, ret_ty: Type.TypeId) Allocator.Error!Type.TypeId {
        return try self.functionType(&.{state_ty}, ret_ty);
    }

    const EncodeContainerKind = enum { tag, record, tuple, list, dict };

    const EncodeContainerMethod = struct {
        lookup: MethodLookup,
        callee: DraftFnSlot,
        callable_ty: Type.TypeId,
        state_ty: Type.TypeId,
        result_ty: Type.TypeId,
        container_state_ty: Type.TypeId,
        container_result_ty: Type.TypeId,
        writer_ty: Type.TypeId,
        body_ty: Type.TypeId,
    };

    fn resolveEncodeContainerMethod(
        self: *BodyContext,
        method_name: []const u8,
        kind: EncodeContainerKind,
        shape_ty: Type.TypeId,
        state_ty: Type.TypeId,
        result_ty: Type.TypeId,
    ) Allocator.Error!EncodeContainerMethod {
        const prepared = try self.frozenFormatCodecCallForShape(.encoder, method_name, shape_ty);
        const callable_ty = prepared.callable_ty;
        const method_fn = self.functionShape(callable_ty, "container encoder method was not a function");
        const method_args = self.typeStore().span(method_fn.args);
        const expected_arity: usize = if (kind == .tag) 4 else 3;
        if (method_args.len != expected_arity) Common.invariant("container encoder method had an unexpected arity");
        if (!self.sameType(GuardedList.at(method_args, 0), state_ty)) Common.invariant("container encoder input state type differed from the encoder state type");
        if (!self.sameType(method_fn.ret, result_ty)) Common.invariant("container encoder result type differed from the encoder result type");

        const u64_ty = try self.primitiveType(.u64);
        const str_ty = try self.primitiveType(.str);
        const body_index: usize = expected_arity - 1;
        if (kind == .tag) {
            if (!self.sameType(GuardedList.at(method_args, 1), str_ty)) Common.invariant("tag encoder name argument was not Str");
            if (!self.sameType(GuardedList.at(method_args, 2), u64_ty)) Common.invariant("tag encoder payload count argument was not U64");
        } else if (!self.sameType(GuardedList.at(method_args, 1), u64_ty)) {
            Common.invariant("container encoder item count argument was not U64");
        }

        const body_ty = GuardedList.at(method_args, body_index);
        const body_fn = self.functionShape(body_ty, "container encoder body callback was not a function");
        const body_args = self.typeStore().span(body_fn.args);
        if (body_args.len != 2) Common.invariant("container encoder body callback had an unexpected arity");
        const container_state_ty = GuardedList.at(body_args, 0);
        const writer_ty = GuardedList.at(body_args, 1);
        const container_result_ty = body_fn.ret;

        const outer_result = self.tryInfo(result_ty);
        if (!self.sameType(outer_result.ok_ty, state_ty)) Common.invariant("container encoder result Ok type differed from the encoder state type");
        const container_result = self.tryInfo(container_result_ty);
        if (!self.sameType(container_result.ok_ty, container_state_ty)) Common.invariant("container encoder callback result Ok type differed from its state type");
        if (!self.sameType(container_result.err_ty, outer_result.err_ty)) Common.invariant("container encoder callback and outer result error types differed");

        const writer_fn = self.functionShape(writer_ty, "container encoder writer was not a function");
        const writer_args = self.typeStore().span(writer_fn.args);
        const expected_writer_arity: usize = switch (kind) {
            .record, .dict => 3,
            .tag, .tuple, .list => 2,
        };
        if (writer_args.len != expected_writer_arity) Common.invariant("container encoder writer had an unexpected arity");
        if (!self.sameType(GuardedList.at(writer_args, 0), container_state_ty)) Common.invariant("container encoder writer state type differed from the callback state type");
        if (!self.sameType(writer_fn.ret, container_result_ty)) Common.invariant("container encoder writer result type differed from the callback result type");
        if (kind == .record and !self.sameType(GuardedList.at(writer_args, 1), str_ty)) Common.invariant("record encoder field name argument was not Str");
        if (kind == .dict) {
            const key_writer_fn = self.functionShape(GuardedList.at(writer_args, 1), "dict encoder key writer was not a function");
            const key_writer_args = self.typeStore().span(key_writer_fn.args);
            if (key_writer_args.len != 1) Common.invariant("dict encoder key writer had an unexpected arity");
            if (!self.sameType(GuardedList.at(key_writer_args, 0), state_ty)) Common.invariant("dict encoder key writer state type differed from the encoder state type");
            if (!self.sameType(key_writer_fn.ret, result_ty)) Common.invariant("dict encoder key writer result type differed from the encoder result type");
        }

        const value_writer_ty = GuardedList.at(writer_args, expected_writer_arity - 1);
        const value_writer_fn = self.functionShape(value_writer_ty, "container encoder value writer was not a function");
        const value_writer_args = self.typeStore().span(value_writer_fn.args);
        if (value_writer_args.len != 1) Common.invariant("container encoder value writer had an unexpected arity");
        if (!self.sameType(GuardedList.at(value_writer_args, 0), state_ty)) Common.invariant("container encoder value writer state type differed from the encoder state type");
        if (!self.sameType(value_writer_fn.ret, result_ty)) Common.invariant("container encoder value writer result type differed from the encoder result type");

        return .{
            .lookup = prepared.lookup,
            .callee = prepared.callee,
            .callable_ty = callable_ty,
            .state_ty = state_ty,
            .result_ty = result_ty,
            .container_state_ty = container_state_ty,
            .container_result_ty = container_result_ty,
            .writer_ty = writer_ty,
            .body_ty = body_ty,
        };
    }

    fn lowerEncodeContainerMethodCall(
        self: *BodyContext,
        method: EncodeContainerMethod,
        args: []const DraftExprId,
    ) Allocator.Error!DraftExprId {
        return try self.addExpr(.{
            .ty = method.result_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(method.callee),
                .args = try self.addExprSpan(args),
                .captures = try self.methodTargetCaptureSpan(method.lookup),
            } },
        });
    }

    fn lowerGeneratedEncoderCallbackLambda(
        self: *BodyContext,
        lambda_ty: Type.TypeId,
        args: []const BodyTypedLocal,
        body: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const source_fn_ty = self.generated_encoder_source_fn_ty orelse
            Common.invariant("generated encoder callback requested outside generated encoder lowering");
        const source_expr = self.generated_encoder_source_expr orelse
            Common.invariant("generated encoder callback source expression was missing");
        const lambda_index = self.generated_encoder_lambda_index;
        self.generated_encoder_lambda_index += 1;
        const fn_id = try self.addFn(.{
            .fn_def = .{ .encoder_for_runtime = .{
                .owner = self.owner_template,
                .expr = source_expr,
            } },
            .source_fn_ty = source_fn_ty,
            .source_fn_key = generatedEncoderCallbackKey(self.current_fn_key, source_expr, lambda_index),
            .mono_fn_ty = lambda_ty,
            .evidence_digest = Ast.fnEvidenceDigest(&.{}, &.{}, null),
        });
        return try self.addExpr(.{ .ty = lambda_ty, .data = .{ .lambda = .{
            .fn_id = .{ .draft = fn_id },
            .args = try self.addTypedLocalSpan(args),
            .body = body,
        } } });
    }

    fn lowerEncodeUnitTagDictKeyToString(
        self: *BodyContext,
        tags_span: Type.Span,
        key_ty: Type.TypeId,
        key_expr: DraftExprId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const str_ty = try self.primitiveType(.str);
        const tags = try GuardedList.dupe(self.allocator, Type.Tag, self.typeStore().tagSpan(tags_span));
        defer self.allocator.free(tags);
        const branches = try self.allocator.alloc(DraftBranch, tags.len);
        defer self.allocator.free(branches);
        for (tags, 0..) |tag, index| {
            if (self.typeStore().span(tag.payloads).len != 0) Common.invariant("dict unit tag key had payloads");
            const pat = try self.addPat(.{ .ty = key_ty, .data = .{ .tag = .{
                .name = tag.name,
                .payloads = .empty(),
            } } });
            branches[index] = .{
                .pat = pat,
                .body = try self.stringExpr(self.nameStore().tagLabelText(tag.name), str_ty),
            };
        }
        if (!self.sameType(ret_ty, str_ty)) Common.invariant("dict unit tag key name type was not Str");
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = key_expr,
            .branches = try self.addBranchSpan(branches),
        } } });
    }

    fn encodeRecordFieldPayloadType(self: *BodyContext, field_ty: Type.TypeId) Allocator.Error!Type.TypeId {
        if (try self.missingTryInfo(field_ty)) |optional_info| {
            return optional_info.ok_ty;
        }
        if (self.optionalFieldSlot(field_ty)) |slot| {
            return slot.payload_ty;
        }
        return field_ty;
    }

    fn lowerCustomEncoderForState(
        self: *BodyContext,
        prepared: FrozenPreparedCodecCall,
        shape_ty: Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const runtime_fn_ty = try self.functionType(&.{ shape_ty, state_ty }, ret_ty);
        const callable_mono_ty = prepared.callable_ty;
        const encode_fn = self.functionShape(callable_mono_ty, "custom encoder_for target was not a function");
        const encode_arg_tys = self.typeStore().span(encode_fn.args);
        if (encode_arg_tys.len != 1) Common.invariant("custom encoder_for target had an unexpected arity");
        if (!self.sameType(GuardedList.at(encode_arg_tys, 0), encoding_ty)) Common.invariant("custom encoder_for encoding type differed from input encoding type");
        if (!self.sameType(encode_fn.ret, runtime_fn_ty)) Common.invariant("custom encoder_for runtime function type differed from expected type");

        const encoder_expr = try self.addExpr(.{
            .ty = runtime_fn_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(prepared.callee),
                .args = try self.addExprSpan(&[_]DraftExprId{encoding_expr}),
                .captures = try self.methodTargetCaptureSpan(prepared.lookup),
            } },
        });
        return try self.addExpr(.{
            .ty = ret_ty,
            .data = .{ .call_value = .{
                .callee = encoder_expr,
                .args = try self.addExprSpan(&[_]DraftExprId{ value_expr, state_expr }),
            } },
        });
    }

    fn lowerEncodeFormatMethod(
        self: *BodyContext,
        method_name: []const u8,
        arg_exprs: []const DraftExprId,
        arg_tys: []const Type.TypeId,
        subject_ty: ?Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const prepared = if (subject_ty) |shape_ty|
            try self.frozenFormatCodecCallForShape(.encoder, method_name, shape_ty)
        else
            try self.frozenFormatCodecCall(.encoder, method_name);
        const callable_mono_ty = prepared.callable_ty;
        const encode_fn = self.functionShape(callable_mono_ty, "encoder_for target method was not a function");
        const actual_arg_tys = self.typeStore().span(encode_fn.args);
        if (actual_arg_tys.len != arg_tys.len) Common.invariant("encoder_for target method had an unexpected arity");
        for (0..GuardedList.borrowLen(actual_arg_tys)) |index| {
            const actual = GuardedList.at(actual_arg_tys, index);
            const expected = arg_tys[index];
            if (!self.sameType(actual, expected)) Common.invariant("encoder_for target method argument type differed from expected type");
        }
        if (!self.sameType(encode_fn.ret, ret_ty)) Common.invariant("encoder_for target method return type differed from expected type");
        return try self.addExpr(.{
            .ty = ret_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(prepared.callee),
                .args = try self.addExprSpan(arg_exprs),
                .captures = try self.methodTargetCaptureSpan(prepared.lookup),
            } },
        });
    }

    fn lowerParseFormatMethod(
        self: *BodyContext,
        method_name: []const u8,
        arg_exprs: []const DraftExprId,
        arg_tys: []const Type.TypeId,
        subject_ty: ?Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const prepared = if (subject_ty) |shape_ty|
            try self.frozenFormatCodecCallForShape(.parser, method_name, shape_ty)
        else
            try self.frozenFormatCodecCall(.parser, method_name);
        const callable_mono_ty = prepared.callable_ty;
        const parse_fn = self.functionShape(callable_mono_ty, "parser_for target method was not a function");
        const actual_arg_tys = self.typeStore().span(parse_fn.args);
        if (actual_arg_tys.len != arg_tys.len) Common.invariant("parser_for target method had an unexpected arity");
        for (0..GuardedList.borrowLen(actual_arg_tys)) |index| {
            const actual = GuardedList.at(actual_arg_tys, index);
            const expected = arg_tys[index];
            if (!self.sameType(actual, expected)) Common.invariant("parser_for target method argument type differed from expected type");
        }
        if (!self.sameType(self.tryInfo(parse_fn.ret).ok_ty, self.tryInfo(ret_ty).ok_ty)) Common.invariant("parser_for target method success type differed from expected type");
        return try self.addExpr(.{
            .ty = parse_fn.ret,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(prepared.callee),
                .args = try self.addExprSpan(arg_exprs),
                .captures = try self.methodTargetCaptureSpan(prepared.lookup),
            } },
        });
    }

    fn cloneNamedTypeWithArgs(
        self: *BodyContext,
        template_ty: Type.TypeId,
        args: []const Type.TypeId,
        backing_ty: Type.TypeId,
    ) Allocator.Error!Type.TypeId {
        const template = switch (self.typeStore().get(template_ty)) {
            .named => |named| named,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("compiler helper expected a named template type"),
        };
        return try self.cloneNamedTypeWithBackingAuthority(
            template_ty,
            args,
            backing_ty,
            template.backing.?.authority,
        );
    }

    fn cloneNamedTypeWithBackingAuthority(
        self: *BodyContext,
        template_ty: Type.TypeId,
        args: []const Type.TypeId,
        backing_ty: Type.TypeId,
        authority: Type.BackingAuthority,
    ) Allocator.Error!Type.TypeId {
        const template = switch (self.typeStore().get(template_ty)) {
            .named => |named| named,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("compiler helper expected a named template type"),
        };
        // The clone owns fresh declared-order rows rather than aliasing the
        // template's span: digests and equality are content-addressed either
        // way, but self-contained rows keep the clone's validity independent
        // of which store region its template's rows happened to live in.
        const declared_order = try GuardedList.dupe(
            self.builder.allocator,
            Type.DeclaredField,
            self.typeStore().declaredFieldSpan(template.declared_order),
        );
        defer self.builder.allocator.free(declared_order);
        return try self.typeStore().add(.{ .named = .{
            .named_type = template.named_type,
            .def = template.def,
            .kind = template.kind,
            .builtin_owner = template.builtin_owner,
            .args = try self.typeStore().addSpan(args),
            .backing = .{ .ty = backing_ty, .use = template.backing.?.use, .authority = authority },
            .declared_order = try self.typeStore().addDeclaredFields(declared_order),
        } });
    }

    const TryNullInfo = struct {
        backing_ty: Type.TypeId,
        ok_payload_ty: Type.TypeId,
        err_ty: Type.TypeId,
    };

    const TryInfo = struct {
        backing_ty: Type.TypeId,
        ok_ty: Type.TypeId,
        err_ty: Type.TypeId,
        ok_tag: Type.Tag,
        err_tag: Type.Tag,
    };

    const RecordFieldMatchMode = enum {
        direct,
        exact,
        caseless,
    };

    const StaticFieldLane = struct {
        offset: u32,
        active_len: u32,
    };

    fn recordPresenceWordCount(field_count: usize) usize {
        return (field_count + 63) / 64;
    }

    fn recordPresenceWordIndex(field_index: usize) usize {
        return field_index / 64;
    }

    fn recordPresenceMask(field_index: usize) u64 {
        return @as(u64, 1) << @as(u6, @intCast(field_index % 64));
    }

    fn selectStaticFieldLane(lengths: []const u32, texts: []const []const u8, length: u32) StaticFieldLane {
        if (lengths.len != texts.len) Common.invariant("record parser dispatch text arity did not match field lengths");
        if (length == 0 or length > 24) Common.invariant("static field lane requested for an unsupported field length");

        var group_count: usize = 0;
        for (lengths, texts) |field_len, text| {
            if (field_len != length) continue;
            if (text.len != length) Common.invariant("record parser dispatch text length did not match precomputed length");
            group_count += 1;
        }
        if (group_count == 0) Common.invariant("static field lane requested for an empty length bucket");

        var best = StaticFieldLane{ .offset = 0, .active_len = @min(length, 8) };
        var best_distinct: usize = 0;
        const offsets = [_]u32{ 0, 8, 16 };
        for (offsets) |offset| {
            if (offset >= length) continue;
            const active_len: u32 = @min(length - offset, 8);
            var distinct: usize = 0;
            for (texts, lengths, 0..) |text, field_len, text_index| {
                if (field_len != length) continue;
                const word = staticFieldLaneWord(text, offset, active_len);
                var seen = false;
                var previous: usize = 0;
                while (previous < text_index) : (previous += 1) {
                    if (lengths[previous] != length) continue;
                    if (staticFieldLaneWord(texts[previous], offset, active_len) == word) {
                        seen = true;
                        break;
                    }
                }
                if (!seen) distinct += 1;
            }
            if (distinct > best_distinct) {
                best = .{ .offset = offset, .active_len = active_len };
                best_distinct = distinct;
                if (distinct == group_count) break;
            }
        }
        return best;
    }

    fn staticFieldLaneWord(text: []const u8, offset: u32, active_len: u32) u64 {
        if (active_len > 8) Common.invariant("static field lane exceeded one word");
        const offset_usize: usize = @intCast(offset);
        const active_len_usize: usize = @intCast(active_len);
        if (offset_usize > text.len or active_len_usize > text.len - offset_usize) Common.invariant("static field lane exceeded field text");
        var word: u64 = 0;
        var index: u32 = 0;
        while (index < active_len) : (index += 1) {
            word |= @as(u64, text[offset_usize + @as(usize, @intCast(index))]) << @intCast(index * 8);
        }
        return word;
    }

    fn fieldLengthAlreadyHandled(lengths: []const u32, index: usize, length: u32) bool {
        var i = index + 1;
        while (i < lengths.len) : (i += 1) {
            if (lengths[i] == length) return true;
        }
        return false;
    }

    fn tryInfo(self: *BodyContext, try_ty: Type.TypeId) TryInfo {
        const backing_ty = self.namedBackingType(try_ty) orelse Common.invariant("expected a named Try type");
        const ok_tag = self.monoTagByText(backing_ty, "Ok");
        const err_tag = self.monoTagByText(backing_ty, "Err");
        const ok_payloads = self.typeStore().span(ok_tag.payloads);
        const err_payloads = self.typeStore().span(err_tag.payloads);
        if (ok_payloads.len != 1 or err_payloads.len != 1) Common.invariant("Try tags must each carry one payload");
        return .{
            .backing_ty = backing_ty,
            .ok_ty = GuardedList.at(ok_payloads, 0),
            .err_ty = GuardedList.at(err_payloads, 0),
            .ok_tag = ok_tag,
            .err_tag = err_tag,
        };
    }

    fn tryInfoOptional(self: *BodyContext, try_ty: Type.TypeId) ?TryInfo {
        const backing_ty = self.namedBackingType(try_ty) orelse return null;
        const ok_tag = self.monoTagByTextOptional(backing_ty, "Ok") orelse return null;
        const err_tag = self.monoTagByTextOptional(backing_ty, "Err") orelse return null;
        const ok_payloads = self.typeStore().span(ok_tag.payloads);
        const err_payloads = self.typeStore().span(err_tag.payloads);
        if (ok_payloads.len != 1 or err_payloads.len != 1) return null;
        return .{
            .backing_ty = backing_ty,
            .ok_ty = GuardedList.at(ok_payloads, 0),
            .err_ty = GuardedList.at(err_payloads, 0),
            .ok_tag = ok_tag,
            .err_tag = err_tag,
        };
    }

    fn missingTryInfo(self: *BodyContext, try_ty: Type.TypeId) Allocator.Error!?TryInfo {
        if (self.frozenCustomCodecCallForShape(.parser, try_ty) != null) return null;
        const info = self.tryInfoOptional(try_ty) orelse return null;
        return if (self.typeIsExactUnitTagUnion(info.err_ty, "Missing")) info else null;
    }

    fn tryTypeLike(
        self: *BodyContext,
        template_try_ty: Type.TypeId,
        ok_ty: Type.TypeId,
        err_ty: Type.TypeId,
    ) Allocator.Error!Type.TypeId {
        const address = GeneratedTryTypeAddress{
            .template_ty = @backingInt(template_try_ty),
            .ok_ty = @backingInt(ok_ty),
            .err_ty = @backingInt(err_ty),
        };
        if (self.draft.generated_try_types.get(address)) |ty| return ty;

        const template_backing = self.namedBackingType(template_try_ty) orelse Common.invariant("Try template type had no backing");
        const template_tags = switch (self.shapeContent(template_backing)) {
            .tag_union => |span| try GuardedList.dupe(self.allocator, Type.Tag, self.typeStore().tagSpan(span)),
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => Common.invariant("Try template backing type was not a tag union"),
        };
        defer self.allocator.free(template_tags);
        const tags = try self.allocator.alloc(Type.Store.TagInput, template_tags.len);
        defer self.allocator.free(tags);
        const payloads = try self.allocator.alloc(Type.TypeId, template_tags.len);
        defer self.allocator.free(payloads);

        var found_ok = false;
        var found_err = false;
        for (template_tags, 0..) |tag, index| {
            const text = self.nameStore().tagLabelText(tag.name);
            const payload_ty = if (Ident.textEql(text, "Ok")) blk: {
                found_ok = true;
                break :blk ok_ty;
            } else if (Ident.textEql(text, "Err")) blk: {
                found_err = true;
                break :blk err_ty;
            } else {
                Common.invariant("Try backing type contained an unexpected tag");
            };
            payloads[index] = payload_ty;
            tags[index] = .{
                .name = tag.name,
                .checked_name = tag.checked_name,
                .payloads = payloads[index..][0..1],
            };
        }
        if (!found_ok or !found_err) Common.invariant("Try backing type did not contain Ok and Err tags");

        const backing_ty = try self.tagUnionType(tags);
        const args = [_]Type.TypeId{ ok_ty, err_ty };
        const ty = try self.cloneNamedTypeWithArgs(template_try_ty, &args, backing_ty);
        try self.draft.generated_try_types.put(address, ty);
        return ty;
    }

    fn tryOk(self: *BodyContext, try_ty: Type.TypeId, value_expr: DraftExprId) Allocator.Error!DraftExprId {
        const info = self.tryInfo(try_ty);
        const value_ty = try self.exprType(value_expr);
        if (!self.sameType(value_ty, info.ok_ty)) Common.invariant("Try.Ok payload type differed from Try Ok type");
        const backing_expr = try self.addExpr(.{
            .ty = info.backing_ty,
            .data = .{ .tag = .{
                .name = info.ok_tag.name,
                .payloads = try self.addExprSpan(&[_]DraftExprId{value_expr}),
            } },
        });
        return try self.addExpr(.{
            .ty = try_ty,
            .data = .{ .nominal = backing_expr },
        });
    }

    fn tryErr(self: *BodyContext, try_ty: Type.TypeId, err_expr: DraftExprId) Allocator.Error!DraftExprId {
        const info = self.tryInfo(try_ty);
        const err_ty = try self.exprType(err_expr);
        if (!self.sameType(err_ty, info.err_ty)) Common.invariant("Try.Err payload type differed from Try Err type");
        const backing_expr = try self.addExpr(.{
            .ty = info.backing_ty,
            .data = .{ .tag = .{
                .name = info.err_tag.name,
                .payloads = try self.addExprSpan(&[_]DraftExprId{err_expr}),
            } },
        });
        return try self.addExpr(.{
            .ty = try_ty,
            .data = .{ .nominal = backing_expr },
        });
    }

    /// An infallible source contributes only its success continuation.
    fn sequenceInfallibleParser(
        self: *BodyContext,
        source: DraftExprId,
        source_ty: Type.TypeId,
        ok_payload: DraftPatId,
        ok_body: DraftExprId,
        target_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const info = self.tryInfo(source_ty);
        const ok_backing = try self.addPat(.{ .ty = info.backing_ty, .data = .{ .tag = .{
            .name = info.ok_tag.name,
            .payloads = try self.addPatSpan(&.{ok_payload}),
        } } });
        const ok = try self.addPat(.{ .ty = source_ty, .data = .{ .nominal = ok_backing } });
        return try self.addExpr(.{ .ty = target_ty, .data = .{ .match_ = .{
            .scrutinee = source,
            .branches = try self.addBranchSpan(&.{.{ .pat = ok, .body = ok_body }}),
        } } });
    }

    /// Keep ordinary Try sequencing (including its cold error edge and direct
    /// record-field binding). The error continuation converts straight into
    /// the final result; no intermediate widened Try is materialized.
    fn sequenceParserErrorConversion(
        self: *BodyContext,
        sequence: union(enum) { value: DraftTrySequence, record: DraftTryRecordSequence },
        source_err_ty: Type.TypeId,
        target_ty: Type.TypeId,
        err_target: ?DraftExprId,
    ) Allocator.Error!DraftExprId {
        const join = try self.reserveGeneratedJoinPoint(target_ty);
        const err_local = try self.addLocal(self.builder.symbols.fresh(), source_err_ty);
        const converted = try self.injectErrorRow(try self.localExpr(err_local, source_err_ty), source_err_ty, self.tryInfo(target_ty).err_ty);
        const body = if (err_target) |target|
            try self.jumpToGeneratedJoin(target, &.{converted}, &.{}, &.{}, target_ty)
        else
            try self.tryErr(target_ty, converted);
        const data: BodyExprData = switch (sequence) {
            .value => |value| blk: {
                var seq = value;
                seq.err_target = join;
                break :blk .{ .try_sequence = seq };
            },
            .record => |record| blk: {
                var seq = record;
                seq.err_target = join;
                break :blk .{ .try_record_sequence = seq };
            },
        };
        const remainder = try self.addExpr(.{ .ty = target_ty, .data = data });
        try self.completeGeneratedJoinPoint(join, &.{.{ .local = err_local, .ty = source_err_ty }}, &.{}, body, remainder);
        return join;
    }

    fn sequenceTry(
        self: *BodyContext,
        try_expr: DraftExprId,
        try_ty: Type.TypeId,
        ok_local: DraftLocalId,
        ok_body: DraftExprId,
        out_try_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.sequenceTryTo(try_expr, try_ty, ok_local, ok_body, out_try_ty, null);
    }

    fn sequenceTryTo(
        self: *BodyContext,
        try_expr: DraftExprId,
        try_ty: Type.TypeId,
        ok_local: DraftLocalId,
        ok_body: DraftExprId,
        out_try_ty: Type.TypeId,
        err_target: ?DraftExprId,
    ) Allocator.Error!DraftExprId {
        const source_ty = try self.exprType(try_expr);
        const info = self.tryInfo(source_ty);
        if (!self.sameType(info.ok_ty, self.tryInfo(try_ty).ok_ty)) Common.invariant("sequenced Try success type differed from expected type");
        const out_info = self.tryInfo(out_try_ty);
        if (self.typeIsClosedEmptyTagUnion(info.err_ty)) {
            return try self.sequenceInfallibleParser(try_expr, source_ty, try self.bindPat(ok_local, info.ok_ty), ok_body, out_try_ty);
        }

        const data: BodyExprData = .{ .try_sequence = .{
            .try_expr = try_expr,
            .ok_local = ok_local,
            .err_is_cold = true,
            .err_target = err_target,
            .ok_body = ok_body,
        } };
        if (!self.sameType(info.err_ty, out_info.err_ty)) {
            return try self.sequenceParserErrorConversion(.{ .value = data.try_sequence }, info.err_ty, out_try_ty, err_target);
        }
        return try self.addExpr(.{ .ty = out_try_ty, .data = data });
    }

    fn sequenceEncodeTry(
        self: *BodyContext,
        try_expr: DraftExprId,
        try_ty: Type.TypeId,
        ok_local: DraftLocalId,
        ok_body: DraftExprId,
        out_try_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const info = self.tryInfo(try_ty);
        const out_info = self.tryInfo(out_try_ty);
        if (!self.sameType(info.err_ty, out_info.err_ty)) Common.invariant("sequenced encoder_for Try error type differed from output Try error type");

        if (!self.typeIsClosedEmptyTagUnion(info.err_ty)) {
            return try self.sequenceTry(try_expr, try_ty, ok_local, ok_body, out_try_ty);
        }

        const ok_payload_pat = try self.bindPat(ok_local, info.ok_ty);
        const ok_backing_pat = try self.addPat(.{ .ty = info.backing_ty, .data = .{ .tag = .{
            .name = info.ok_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{ok_payload_pat}),
        } } });
        const ok_pat = try self.addPat(.{ .ty = try_ty, .data = .{ .nominal = ok_backing_pat } });
        const branches = [_]DraftBranch{.{ .pat = ok_pat, .body = ok_body }};
        return try self.addExpr(.{ .ty = out_try_ty, .data = .{ .match_ = .{
            .scrutinee = try_expr,
            .branches = try self.addBranchSpan(&branches),
        } } });
    }

    fn typeIsClosedEmptyTagUnion(self: *BodyContext, ty: Type.TypeId) bool {
        var current = ty;
        while (true) switch (self.typeStore().get(current)) {
            .named => |named| {
                const backing = named.backing orelse return false;
                if (backing.use != .inspectable) return false;
                current = backing.ty;
            },
            .tag_union => |span| return self.typeStore().tagSpan(span).len == 0,
            .primitive, .record, .tuple, .list, .box, .func, .erased, .zst => return false,
        };
    }

    fn sequenceTryRecord(
        self: *BodyContext,
        try_expr: DraftExprId,
        try_ty: Type.TypeId,
        value_local: DraftLocalId,
        value_field: names.RecordFieldNameId,
        rest_local: DraftLocalId,
        rest_field: names.RecordFieldNameId,
        ok_body: DraftExprId,
        out_try_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.sequenceTryRecordTo(
            try_expr,
            try_ty,
            value_local,
            value_field,
            rest_local,
            rest_field,
            ok_body,
            out_try_ty,
            null,
        );
    }

    fn sequenceTryRecordTo(
        self: *BodyContext,
        try_expr: DraftExprId,
        try_ty: Type.TypeId,
        value_local: DraftLocalId,
        value_field: names.RecordFieldNameId,
        rest_local: DraftLocalId,
        rest_field: names.RecordFieldNameId,
        ok_body: DraftExprId,
        out_try_ty: Type.TypeId,
        err_target: ?DraftExprId,
    ) Allocator.Error!DraftExprId {
        const source_ty = try self.exprType(try_expr);
        const info = self.tryInfo(source_ty);
        if (!self.sameType(info.ok_ty, self.tryInfo(try_ty).ok_ty)) Common.invariant("sequenced Try record success type differed from expected type");
        const out_info = self.tryInfo(out_try_ty);

        if (!self.sameType(self.recordFieldType(info.ok_ty, value_field), try self.localType(value_local))) {
            Common.invariant("sequenced Try record value local type differed from Ok record field");
        }
        if (!self.sameType(self.recordFieldType(info.ok_ty, rest_field), try self.localType(rest_local))) {
            Common.invariant("sequenced Try record rest local type differed from Ok record field");
        }

        if (self.typeIsClosedEmptyTagUnion(info.err_ty)) {
            const fields = [_]DraftRecordDestruct{
                .{ .name = value_field, .pattern = try self.bindPat(value_local, try self.localType(value_local)) },
                .{ .name = rest_field, .pattern = try self.bindPat(rest_local, try self.localType(rest_local)) },
            };
            const ok_pat = try self.addPat(.{ .ty = info.ok_ty, .data = .{ .record = try self.addRecordDestructSpan(&fields) } });
            return try self.sequenceInfallibleParser(try_expr, source_ty, ok_pat, ok_body, out_try_ty);
        }

        const data: BodyExprData = .{ .try_record_sequence = .{
            .try_expr = try_expr,
            .value_local = value_local,
            .value_field = value_field,
            .rest_local = rest_local,
            .rest_field = rest_field,
            .err_is_cold = true,
            .err_target = err_target,
            .ok_body = ok_body,
        } };
        if (!self.sameType(info.err_ty, out_info.err_ty)) {
            return try self.sequenceParserErrorConversion(.{ .record = data.try_record_sequence }, info.err_ty, out_try_ty, err_target);
        }
        return try self.addExpr(.{ .ty = out_try_ty, .data = data });
    }

    fn recordFieldType(self: *BodyContext, record_ty: Type.TypeId, field_name: names.RecordFieldNameId) Type.TypeId {
        return switch (self.shapeContent(record_ty)) {
            .record => |fields_span| {
                const fields = self.typeStore().fieldSpan(fields_span);
                for (0..GuardedList.borrowLen(fields)) |index| {
                    const field = GuardedList.at(fields, index);
                    if (field.name == field_name) return field.ty;
                }
                Common.invariant("record field was absent from monotype record");
            },
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("record field operation expected a record type"),
        };
    }

    /// A pending step of a codec support check: a type to check, or a type
    /// to take back off `codec_support_path` once its components pass. A
    /// type already on the path is assumed supported, which closes recursive
    /// types. An encoder's `field` is a record field type whose payload type
    /// is read when the check reaches it.
    const CodecSupportStep = union(enum) {
        check: struct { ty: Type.TypeId, allow_missing: bool = false },
        field: Type.TypeId,
        leave: Type.TypeId,
    };

    /// Take every type the unfinished steps hold back off the support path.
    fn abandonCodecSupportCheck(self: *BodyContext, pending: []const CodecSupportStep) void {
        for (pending) |step| switch (step) {
            .leave => |ty| _ = self.codec_support_path.remove(ty),
            .check, .field => {},
        };
    }

    /// Push `tys` so they are checked in order.
    fn pushCodecSupportChecks(self: *BodyContext, pending: *std.ArrayList(CodecSupportStep), tys: anytype, allow_missing: bool) Allocator.Error!void {
        var index = GuardedList.borrowLen(tys);
        while (index > 0) {
            index -= 1;
            try pending.append(self.allocator, .{ .check = .{ .ty = GuardedList.at(tys, index), .allow_missing = allow_missing } });
        }
    }

    /// Push a tag union's payload types so they are checked in order; false
    /// when the union has no tags.
    fn pushCodecSupportPayloads(self: *BodyContext, pending: *std.ArrayList(CodecSupportStep), tags_span: Type.Span) Allocator.Error!bool {
        const tags = self.typeStore().tagSpan(tags_span);
        if (tags.len == 0) return false;
        const start = pending.items.len;
        for (0..GuardedList.borrowLen(tags)) |tag_index| {
            const tag = GuardedList.at(tags, tag_index);
            const payload_tys = self.typeStore().span(tag.payloads);
            for (0..GuardedList.borrowLen(payload_tys)) |payload_index| {
                try pending.append(self.allocator, .{ .check = .{ .ty = GuardedList.at(payload_tys, payload_index) } });
            }
        }
        std.mem.reverse(CodecSupportStep, pending.items[start..]);
        return true;
    }

    fn parseFieldTypeIsSupported(self: *BodyContext, root_ty: Type.TypeId, root_allow_missing: bool) Allocator.Error!bool {
        var pending = std.ArrayList(CodecSupportStep).empty;
        defer pending.deinit(self.allocator);
        errdefer self.abandonCodecSupportCheck(pending.items);
        try pending.append(self.allocator, .{ .check = .{ .ty = root_ty, .allow_missing = root_allow_missing } });
        while (pending.pop()) |step| {
            const check_step = switch (step) {
                .check => |check_step| check_step,
                .leave => |ty| {
                    _ = self.codec_support_path.remove(ty);
                    continue;
                },
                .field => unreachable,
            };
            if (!try self.stepParseFieldSupport(&pending, check_step.ty, check_step.allow_missing)) {
                self.abandonCodecSupportCheck(pending.items);
                return false;
            }
        }
        return true;
    }

    /// Check `ty` itself, pushing its components; false when `ty` is not
    /// supported.
    fn stepParseFieldSupport(self: *BodyContext, pending: *std.ArrayList(CodecSupportStep), ty: Type.TypeId, allow_missing: bool) Allocator.Error!bool {
        if (self.codec_support_path.contains(ty)) return true;
        try self.codec_support_path.put(ty, {});
        pending.append(self.allocator, .{ .leave = ty }) catch |err| {
            _ = self.codec_support_path.remove(ty);
            return err;
        };
        if (self.scalarCodecMethodName(ty, "parse_") != null) return true;
        if (try self.missingTryInfo(ty)) |info| {
            if (!allow_missing) return false;
            try pending.append(self.allocator, .{ .check = .{ .ty = info.ok_ty } });
            return true;
        }
        if (self.optionalFieldSlot(ty)) |slot| {
            if (!allow_missing) return false;
            try pending.append(self.allocator, .{ .check = .{ .ty = slot.payload_ty } });
            return true;
        }
        if (self.tryNullInfo(ty)) |info| {
            try pending.append(self.allocator, .{ .check = .{ .ty = info.ok_payload_ty } });
            return true;
        }
        if (self.frozenCustomCodecCallForShape(.parser, ty) != null) return true;
        if (self.nominalExprBackingType(ty)) |backing_ty| {
            if (self.scalarCodecMethodName(backing_ty, "parse_") != null) return true;
        }
        if (self.setPayloadType(ty)) |payload_ty| {
            try pending.append(self.allocator, .{ .check = .{ .ty = payload_ty } });
            return true;
        }
        if (self.dictEntryShape(ty)) |dict| {
            try pending.append(self.allocator, .{ .check = .{ .ty = dict.value_ty } });
            if (!self.dictKeyIsStringRendered(dict.key_ty)) try pending.append(self.allocator, .{ .check = .{ .ty = dict.key_ty } });
            return true;
        }
        switch (self.shapeContent(ty)) {
            .list => |elem_ty| try pending.append(self.allocator, .{ .check = .{ .ty = elem_ty } }),
            .box => |payload_ty| try pending.append(self.allocator, .{ .check = .{ .ty = payload_ty } }),
            .tuple => |span| try self.pushCodecSupportChecks(pending, self.typeStore().span(span), false),
            .record => |fields_span| {
                const fields = self.typeStore().fieldSpan(fields_span);
                const start = pending.items.len;
                for (0..GuardedList.borrowLen(fields)) |index| {
                    try pending.append(self.allocator, .{ .check = .{ .ty = GuardedList.at(fields, index).ty, .allow_missing = true } });
                }
                std.mem.reverse(CodecSupportStep, pending.items[start..]);
            },
            .tag_union => |tags_span| return try self.pushCodecSupportPayloads(pending, tags_span),
            .zst => {},
            .primitive, .named, .func, .erased => return false,
        }
        return true;
    }

    fn encodeFieldTypeIsSupported(self: *BodyContext, root_ty: Type.TypeId, _: Type.TypeId) Allocator.Error!bool {
        var pending = std.ArrayList(CodecSupportStep).empty;
        defer pending.deinit(self.allocator);
        errdefer self.abandonCodecSupportCheck(pending.items);
        try pending.append(self.allocator, .{ .check = .{ .ty = root_ty } });
        while (pending.pop()) |step| {
            const ty = switch (step) {
                .check => |check_step| check_step.ty,
                .field => |field_ty| try self.encodeRecordFieldPayloadType(field_ty),
                .leave => |ty| {
                    _ = self.codec_support_path.remove(ty);
                    continue;
                },
            };
            if (!try self.stepEncodeFieldSupport(&pending, ty)) {
                self.abandonCodecSupportCheck(pending.items);
                return false;
            }
        }
        return true;
    }

    /// Check `ty` itself, pushing its components; false when `ty` is not
    /// supported.
    fn stepEncodeFieldSupport(self: *BodyContext, pending: *std.ArrayList(CodecSupportStep), ty: Type.TypeId) Allocator.Error!bool {
        if (self.codec_support_path.contains(ty)) return true;
        try self.codec_support_path.put(ty, {});
        pending.append(self.allocator, .{ .leave = ty }) catch |err| {
            _ = self.codec_support_path.remove(ty);
            return err;
        };
        if (self.scalarCodecMethodName(ty, "encode_") != null) return true;
        if (self.tryNullInfo(ty)) |info| {
            try pending.append(self.allocator, .{ .check = .{ .ty = info.ok_payload_ty } });
            return true;
        }
        if (self.frozenCustomCodecCallForShape(.encoder, ty) != null) return true;
        if (self.nominalExprBackingType(ty)) |backing_ty| {
            if (self.scalarCodecMethodName(backing_ty, "encode_") != null) return true;
        }
        if (self.setPayloadType(ty)) |payload_ty| {
            try pending.append(self.allocator, .{ .check = .{ .ty = payload_ty } });
            return true;
        }
        if (self.dictEntryShape(ty)) |dict| {
            try pending.append(self.allocator, .{ .check = .{ .ty = dict.value_ty } });
            if (!self.dictKeyIsStringRendered(dict.key_ty)) try pending.append(self.allocator, .{ .check = .{ .ty = dict.key_ty } });
            return true;
        }
        switch (self.shapeContent(ty)) {
            .list => |elem_ty| try pending.append(self.allocator, .{ .check = .{ .ty = elem_ty } }),
            .box => |payload_ty| try pending.append(self.allocator, .{ .check = .{ .ty = payload_ty } }),
            .tuple => |span| try self.pushCodecSupportChecks(pending, self.typeStore().span(span), false),
            .record => |fields_span| {
                const fields = self.typeStore().fieldSpan(fields_span);
                const start = pending.items.len;
                for (0..GuardedList.borrowLen(fields)) |index| {
                    try pending.append(self.allocator, .{ .field = GuardedList.at(fields, index).ty });
                }
                std.mem.reverse(CodecSupportStep, pending.items[start..]);
            },
            .tag_union => |tags_span| return try self.pushCodecSupportPayloads(pending, tags_span),
            .zst => {},
            .primitive, .named, .func, .erased => return false,
        }
        return true;
    }

    const GraphTryPayloads = struct {
        ok: NodeId,
        err: NodeId,
    };

    fn graphTryPayloads(self: *BodyContext, try_node: NodeId) Allocator.Error!GraphTryPayloads {
        const named = switch ((try self.graph.content(try_node))) {
            .named => |named| named,
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => Common.invariant("codec method result was not a named Try type"),
        };
        const backing = named.backing orelse Common.invariant("codec Try type had no checked backing");
        const ok_name = try self.nameStoreMut().internTagLabel("Ok");
        const err_name = try self.nameStoreMut().internTagLabel("Err");
        const tags = (try self.graph.tagRowNodes(backing.node)).tags;
        const ok = graphTagByName(tags, ok_name) orelse Common.invariant("codec Try backing had no Ok tag");
        const err = graphTagByName(tags, err_name) orelse Common.invariant("codec Try backing had no Err tag");
        if (ok.payloads.len != 1 or err.payloads.len != 1) {
            Common.invariant("codec Try tags did not have one payload each");
        }
        return .{ .ok = ok.payloads[0], .err = err.payloads[0] };
    }

    const ParserResultNodes = struct { value: NodeId, rest: NodeId, err: NodeId };

    fn graphParserResultNodes(self: *BodyContext, try_node: NodeId) Allocator.Error!ParserResultNodes {
        const payloads = try self.graphTryPayloads(try_node);
        const value_name = try self.nameStoreMut().internRecordFieldLabel("value");
        const rest_name = try self.nameStoreMut().internRecordFieldLabel("rest");
        return .{
            .value = try self.graph.recordFieldNode(payloads.ok, value_name),
            .rest = try self.graph.recordFieldNode(payloads.ok, rest_name),
            .err = payloads.err,
        };
    }

    /// Relate the payloads of a declared parser method's errors to the
    /// enclosing structural parser row without equating the two rows. The
    /// method result is exact; emission explicitly injects that row into
    /// the enclosing result, whose additional structural errors remain owned by
    /// the enclosing parser producer.
    fn relateParserErrorInjection(
        self: *BodyContext,
        source_err: NodeId,
        target_err: NodeId,
    ) Allocator.Error!void {
        if (self.graph.rootNode(source_err) == self.graph.rootNode(target_err)) return;
        const source_tags = (try self.graph.tagRowNodes(source_err)).tags;
        if (source_tags.len == 0) return;
        const target_tags = (try self.graph.tagRowNodes(target_err)).tags;
        var target_index: usize = 0;
        for (source_tags) |source_tag| {
            while (target_index < target_tags.len and self.nameStore().tagLabelTextLessThan(target_tags[target_index].name, source_tag.name)) : (target_index += 1) {}
            if (target_index == target_tags.len or target_tags[target_index].name != source_tag.name) Common.invariant("parser error row was not included in the enclosing parser row");
            const target_tag = target_tags[target_index];
            if (source_tag.payloads.len != target_tag.payloads.len) {
                Common.invariant("custom parser error injection changed tag payload arity");
            }
            for (source_tag.payloads, target_tag.payloads) |source_payload, target_payload| {
                try relateRequestComponent(self.graph, source_payload, target_payload);
            }
        }
    }

    fn preparedCodecCallExists(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        kind: CodecKind,
        purpose: CodecCallPurpose,
        method_name: []const u8,
        contract_view: [32]u8,
        contract_derivation: static_dispatch.GeneratedCodecDerivationId,
        method_role: u32,
    ) bool {
        for (self.draft.prepared_codec_calls.items) |prepared| {
            if (prepared.boundary_expr != boundary_expr or
                prepared.kind != kind or
                prepared.purpose != purpose or
                prepared.contract_derivation != contract_derivation or
                prepared.method_role != method_role or
                !moduleBytesEqual(prepared.contract_view, contract_view) or
                !std.mem.eql(u8, prepared.method_name, method_name)) continue;
            return true;
        }
        return false;
    }

    fn preparedRequiredCodecCallExists(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        kind: CodecKind,
        exact: anytype,
    ) bool {
        return self.preparedCodecCallExists(
            boundary_expr,
            kind,
            .format,
            exact.method_name,
            exact.anchor.view.key.bytes,
            exact.anchor.derivation,
            exact.method_role,
        );
    }

    /// Phase-A relation production for one `??` field default reachable from
    /// a deferred codec boundary's shape: lower the checked default
    /// expression at the field's inline value node while the graph still
    /// accepts relations, and record the finished draft expression for
    /// Phase-B parser emission to consume (mirrors `prepareCustomCodecCall`).
    fn prepareDefaultedFieldValue(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        default: Type.FieldDefault,
        field_node: NodeId,
    ) Allocator.Error!bool {
        for (self.draft.prepared_field_defaults.items) |prepared| {
            if (prepared.boundary_expr != boundary_expr) continue;
            if (!std.meta.eql(prepared.default, default)) continue;
            if (self.graph.sameClass(prepared.field_node, field_node)) return false;
        }
        const value = (try self.defaultedFieldValueAtCell(
            self.nameStore().moduleIdentityBytes(default.module),
            default.expr_node,
            DraftTypeCell.fromGraphNode(field_node),
        )) orelse Common.invariant("structural parser field default had no archived expression");
        try self.draft.prepared_field_defaults.append(self.allocator, .{
            .boundary_expr = boundary_expr,
            .default = default,
            .field_node = field_node,
            .value = value,
        });
        return true;
    }

    fn prepareStructuralCodecCallsAtNode(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        kind: CodecKind,
        shape_node: NodeId,
        boundary_callable_node: NodeId,
    ) Allocator.Error!bool {
        const active = self.active_codec_contract orelse
            Common.invariant("structural codec preparation had no checker-authored contract");
        if (active.kind != kind) {
            Common.invariant("structural codec preparation used a contract of the wrong kind");
        }
        for (self.codec_contract_expansion_stack.items) |ancestor| {
            if (ancestor.derivation != active.derivation or
                !moduleBytesEqual(ancestor.view, active.view.key.bytes) or
                !self.graph.sameClass(ancestor.shape_node, shape_node)) continue;
            return false;
        }
        const ancestry_len = self.codec_contract_expansion_stack.items.len;
        try self.codec_contract_expansion_stack.append(self.allocator, .{
            .view = active.view.key.bytes,
            .derivation = active.derivation,
            .shape_node = shape_node,
        });
        defer self.codec_contract_expansion_stack.shrinkRetainingCapacity(ancestry_len);

        var added_relation = false;
        if (kind == .parser) {
            var invalid_value_seen = collections.DenseMap(NodeId, void).init(self.allocator);
            defer invalid_value_seen.deinit();
            if (try self.graphParserShapeNeedsInvalidValue(shape_node, &invalid_value_seen)) {
                added_relation = try self.prepareParserInvalidValueCodecCall(
                    boundary_expr,
                    shape_node,
                    boundary_callable_node,
                );
            }
        }
        var seen = collections.DenseMap(NodeId, void).init(self.allocator);
        defer seen.deinit();
        const added = try self.prepareCustomCodecCallsAtNode(
            boundary_expr,
            kind,
            shape_node,
            boundary_callable_node,
            &seen,
        ) or added_relation;
        self.debugVerifyGeneratedCodecContractConsumed(active);
        return added;
    }

    /// `ParseTagUnionSpec.parse` decodes only the selected tag's payloads; the
    /// enclosing format method has already consumed the tag name. Preparing a
    /// full tag-union parser here would re-enter the same format method before
    /// the current synthetic parser is registered.
    fn prepareParseTagUnionPayloadCodecCalls(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        union_node: NodeId,
        boundary_callable_node: NodeId,
    ) Allocator.Error!bool {
        var added_relation = false;

        var invalid_value_seen = collections.DenseMap(NodeId, void).init(self.allocator);
        defer invalid_value_seen.deinit();
        var seen = collections.DenseMap(NodeId, void).init(self.allocator);
        defer seen.deinit();

        for ((try self.graph.tagRowNodes(union_node)).tags) |tag| {
            for (tag.payloads) |payload| {
                if (try self.graphParserShapeNeedsInvalidValue(payload, &invalid_value_seen)) {
                    added_relation = try self.prepareParserInvalidValueCodecCall(
                        boundary_expr,
                        payload,
                        boundary_callable_node,
                    ) or added_relation;
                }
                added_relation = try self.prepareCustomCodecCallsAtNode(
                    boundary_expr,
                    .parser,
                    payload,
                    boundary_callable_node,
                    &seen,
                ) or added_relation;
            }
        }
        return added_relation;
    }

    fn sealedPreparedCodecCallsForBoundary(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        sealer: *GraphTypeFinals,
    ) Allocator.Error!FrozenPreparedCodecCalls {
        var out = std.ArrayList(FrozenPreparedCodecCall).empty;
        errdefer out.deinit(self.allocator);
        for (self.draft.prepared_codec_calls.items) |prepared| {
            if (prepared.boundary_expr != boundary_expr) continue;
            try out.append(self.allocator, .{
                .kind = prepared.kind,
                .purpose = prepared.purpose,
                .method_name = prepared.method_name,
                .method_role = prepared.method_role,
                .subject_bearing = prepared.subject_bearing,
                .contract_view = prepared.contract_view,
                .contract_derivation = prepared.contract_derivation,
                .shape_ty = try sealer.sealNode(prepared.shape_node),
                .lookup = prepared.lookup,
                .callable_ty = try sealer.sealNode(prepared.callable_node),
                .callee = prepared.callee,
            });
        }
        return try FrozenPreparedCodecCalls.init(
            self.allocator,
            self.typeStore(),
            self.nameStore(),
            try out.toOwnedSlice(self.allocator),
        );
    }

    fn sealedPreparedFieldDefaultsForBoundary(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        sealer: *GraphTypeFinals,
    ) Allocator.Error!FrozenPreparedFieldDefaults {
        var out = std.ArrayList(FrozenPreparedFieldDefault).empty;
        errdefer out.deinit(self.allocator);
        for (self.draft.prepared_field_defaults.items) |prepared| {
            if (prepared.boundary_expr != boundary_expr) continue;
            try out.append(self.allocator, .{
                .default = prepared.default,
                .field_ty = try sealer.sealNode(prepared.field_node),
                .value = prepared.value,
            });
        }
        return .{ .entries = try out.toOwnedSlice(self.allocator) };
    }

    fn instantiateCodecContract(
        self: *BodyContext,
        structural: SpecStructuralEvidence,
        callable_node: NodeId,
        shape_node: NodeId,
    ) Allocator.Error!ActiveCodecContract {
        const checked_structural = structural.checked orelse
            Common.invariant("structural codec reached Monotype without its checked derivation contract");
        const derivation_id = checked_structural.evidence.generated_codec_derivation orelse
            Common.invariant("checked structural codec evidence had no generated derivation contract");
        if (@backingInt(derivation_id) >= checked_structural.view.static_dispatch_plans.generated_codec_derivations.len) {
            Common.invariant("checked structural codec evidence referenced a missing generated derivation");
        }
        const derivation = checked_structural.view.static_dispatch_plans.generated_codec_derivations[@backingInt(derivation_id)];
        const kind: CodecKind = switch (structural.derivation.kind()) {
            .parser => .parser,
            .encoder => .encoder,
            .equality, .hash, .map, .map_effectful => Common.invariant("non-codec structural evidence carried a generated codec contract"),
        };
        const checked_kind: static_dispatch.GeneratedCodecDerivationKind = switch (kind) {
            .parser => .parser,
            .encoder => .encoder,
        };
        if (derivation.kind != checked_kind or checked_structural.evidence.derivation.kind() != structural.derivation.kind()) {
            Common.invariant("checked structural codec evidence referenced a derivation of the wrong kind");
        }

        return try self.instantiateCheckedCodecContract(
            checked_structural.view,
            derivation_id,
            kind,
            .{ .callable_node = callable_node, .shape_node = shape_node },
        );
    }

    fn instantiateCodecContractAtCall(
        self: *BodyContext,
        anchor: CheckedCodecContractAnchor,
        constructor_node: NodeId,
        shape_node: NodeId,
    ) Allocator.Error!void {
        if (@backingInt(anchor.derivation) >= anchor.view.static_dispatch_plans.generated_codec_derivations.len) {
            Common.invariant("checked codec call anchor referenced a missing derivation");
        }
        const derivation = anchor.view.static_dispatch_plans.generated_codec_derivations[@backingInt(anchor.derivation)];
        if (anchor.call_index >= derivation.calls.len) {
            Common.invariant("checked codec call anchor referenced a missing generated call");
        }
        var active = try self.instantiateCheckedCodecContract(
            anchor.view,
            anchor.derivation,
            anchor.kind,
            .{ .callable_node = constructor_node, .shape_node = shape_node },
        );
        active.grounding_call_index = anchor.call_index;
        self.active_codec_contract = active;
    }

    /// Select the checker-authored subject role for a container reached while
    /// walking one active generated body. Only the active declaration-backed
    /// boundary is validated against its structural body shape; nested named
    /// containers are validated against their own public shape.
    fn codecContractSubjectNode(
        self: *BodyContext,
        shape_node: NodeId,
        structural_node: NodeId,
    ) Allocator.Error!NodeId {
        const active = self.active_codec_contract orelse
            Common.invariant("generated codec subject selection had no active contract");
        const derivation = active.view.static_dispatch_plans.generated_codec_derivations[@backingInt(active.derivation)];
        if (derivation.body_shape_ty == derivation.shape_ty) return shape_node;
        const boundary_shape_node = active.shape_node;
        return if (self.graph.sameClass(boundary_shape_node, shape_node)) structural_node else shape_node;
    }

    fn bindCheckedCodecContractType(
        self: *BodyContext,
        contract_ctx: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        node: NodeId,
    ) Allocator.Error!void {
        const scoped_ty = contract_ctx.scopedCheckedType(checked_ty);
        if (try contract_ctx.scopedNode(scoped_ty)) |existing| {
            try relateRequestComponent(self.graph, existing, node);
        } else {
            try contract_ctx.putScopedNode(scoped_ty, node);
        }
    }

    /// Instantiate a checked contract component before relating it to the
    /// specialization boundary. Unlike a root substitution, this preserves
    /// the checked IDs of nested row fragments and container children, which
    /// are the exact subject identities carried by generated-call slots.
    fn relateCheckedCodecContractType(
        self: *BodyContext,
        contract_ctx: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        node: NodeId,
    ) Allocator.Error!void {
        const scoped_ty = contract_ctx.scopedCheckedType(checked_ty);
        const checked_node = try contract_ctx.instNode(checked_ty);
        try relateCheckedNodeToMono(self.graph, checked_node, node);
        // The recursive relation above preserves every nested checked ID.
        // Rebind this component root to the specialization's authoritative
        // node so a generated call that names the same checked role receives
        // that exact node instead of the checked representation wrapper.
        try contract_ctx.putScopedNode(scoped_ty, node);
    }

    fn bindCodecContractBoundary(
        self: *BodyContext,
        contract_ctx: *BodyContext,
        derivation: static_dispatch.GeneratedCodecDerivation,
        kind: CodecKind,
        callable_node: NodeId,
        shape_node: NodeId,
    ) Allocator.Error!void {
        const constructor = try self.graph.functionNodes(callable_node);
        if (constructor.args.len != 1) {
            Common.invariant("generated codec boundary constructor did not have one encoding argument");
        }
        const runtime = try self.graph.functionNodes(constructor.ret);
        const source_has_distinct_body_shape = derivation.source_body_shape_ty != derivation.source_shape_ty;
        const frozen_has_distinct_body_shape = derivation.body_shape_ty != derivation.shape_ty;
        if (source_has_distinct_body_shape != frozen_has_distinct_body_shape) {
            Common.invariant("generated codec source and frozen body-shape roles disagreed");
        }
        const body_shape_node = if (source_has_distinct_body_shape) blk: {
            const named = switch ((try self.graph.content(shape_node))) {
                .named => |named| named,
                .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => Common.invariant("generated codec declared a distinct body shape for a non-nominal boundary"),
            };
            break :blk (named.backing orelse
                Common.invariant("generated codec nominal boundary had no body-shape backing")).node;
        } else shape_node;
        const state_node, const error_node = switch (kind) {
            .parser => blk: {
                if (runtime.args.len != 1) {
                    Common.invariant("generated parser boundary runtime did not have one state argument");
                }
                const result = try self.graphParserResultNodes(runtime.ret);
                try relateRequestComponent(self.graph, result.value, shape_node);
                try relateRequestComponent(self.graph, result.rest, runtime.args[0]);
                break :blk .{ runtime.args[0], result.err };
            },
            .encoder => blk: {
                if (runtime.args.len != 2) {
                    Common.invariant("generated encoder boundary runtime did not have value and state arguments");
                }
                try relateRequestComponent(self.graph, runtime.args[0], shape_node);
                const result = try self.graphTryPayloads(runtime.ret);
                try relateRequestComponent(self.graph, result.ok, runtime.args[1]);
                break :blk .{ runtime.args[1], result.err };
            },
        };

        // The source and frozen producer roles together are the codec
        // contract's complete substitution interface. Binding both sets here
        // gives every checker-authored edge the same authoritative boundary
        // nodes without rediscovering or widening a type in Monotype.
        try self.bindCheckedCodecContractType(contract_ctx, derivation.source_constructor_ty, callable_node);
        try self.bindCheckedCodecContractType(contract_ctx, derivation.source_runtime_ty, constructor.ret);
        try self.relateCheckedCodecContractType(contract_ctx, derivation.source_shape_ty, shape_node);
        try self.relateCheckedCodecContractType(contract_ctx, derivation.source_body_shape_ty, body_shape_node);
        try self.bindCheckedCodecContractType(contract_ctx, derivation.source_encoding_ty, constructor.args[0]);
        try self.bindCheckedCodecContractType(contract_ctx, derivation.source_state_ty, state_node);
        try self.bindCheckedCodecContractType(contract_ctx, derivation.source_error_ty, error_node);
        if (derivation.constructor_ty != derivation.source_constructor_ty) {
            try self.bindCheckedCodecContractType(contract_ctx, derivation.constructor_ty, callable_node);
        }
        if (derivation.runtime_ty != derivation.source_runtime_ty) {
            try self.bindCheckedCodecContractType(contract_ctx, derivation.runtime_ty, constructor.ret);
        }
        if (derivation.shape_ty != derivation.source_shape_ty) {
            try self.relateCheckedCodecContractType(contract_ctx, derivation.shape_ty, shape_node);
        }
        if (derivation.body_shape_ty != derivation.source_body_shape_ty) {
            try self.relateCheckedCodecContractType(contract_ctx, derivation.body_shape_ty, body_shape_node);
        }
        if (derivation.encoding_ty != derivation.source_encoding_ty) {
            try self.bindCheckedCodecContractType(contract_ctx, derivation.encoding_ty, constructor.args[0]);
        }
        if (derivation.state_ty != derivation.source_state_ty) {
            try self.bindCheckedCodecContractType(contract_ctx, derivation.state_ty, state_node);
        }
        if (derivation.error_ty != derivation.source_error_ty) {
            try self.bindCheckedCodecContractType(contract_ctx, derivation.error_ty, error_node);
        }
    }

    fn instantiateCheckedCodecContract(
        self: *BodyContext,
        checked_view: ModuleView,
        derivation_id: static_dispatch.GeneratedCodecDerivationId,
        kind: CodecKind,
        boundary: CodecContractBoundary,
    ) Allocator.Error!ActiveCodecContract {
        if (@backingInt(derivation_id) >= checked_view.static_dispatch_plans.generated_codec_derivations.len) {
            Common.invariant("checked codec anchor referenced a missing generated derivation");
        }
        const derivation = checked_view.static_dispatch_plans.generated_codec_derivations[@backingInt(derivation_id)];
        const checked_kind: static_dispatch.GeneratedCodecDerivationKind = switch (kind) {
            .parser => .parser,
            .encoder => .encoder,
        };
        if (derivation.kind != checked_kind) {
            Common.invariant("checked codec anchor referenced a derivation of the wrong kind");
        }

        var contract_ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self.builder,
            checked_view,
            self.method_scope,
            self.owner_template,
            self.graph,
            self.draft,
        );
        defer contract_ctx.deinit();
        contract_ctx.evidence = self.evidence;
        contract_ctx.instantiation.closed_types = .{ .leaves = try self.graph.newLeafScope() };
        try self.bindCodecContractBoundary(
            &contract_ctx,
            derivation,
            kind,
            boundary.callable_node,
            boundary.shape_node,
        );

        const calls_start = self.instantiated_codec_calls.items.len;
        errdefer self.instantiated_codec_calls.shrinkRetainingCapacity(calls_start);
        for (derivation.callsSlice(checked_view.static_dispatch_plans), 0..) |call, call_index| {
            const instantiated_callable = try contract_ctx.instNode(call.callable_ty);
            try self.instantiated_codec_calls.append(self.allocator, .{
                .view = checked_view,
                .call_index = @intCast(call_index),
                .checked = call,
                .dispatcher_node = try contract_ctx.instNode(call.dispatcher_ty),
                .callable_node = instantiated_callable,
                .subject_node = if (call.subject_ty) |subject_ty| try contract_ctx.instNode(subject_ty) else null,
                .resolution = switch (call.resolution) {
                    .callable => |node_id| .{ .callable = node_id },
                    .structural => |nested| .{ .structural = nested },
                    .pending => Common.invariant("unlinked generated codec call reached Monotype"),
                    .checked_error => Common.invariant("rejected generated codec call reached Monotype"),
                },
            });
        }
        const instantiated_calls = self.instantiated_codec_calls.items[calls_start..];
        return .{
            .view = checked_view,
            .derivation = derivation_id,
            .kind = kind,
            .evidence = self.evidence,
            .calls_start = calls_start,
            .calls_len = self.instantiated_codec_calls.items.len - calls_start,
            .method_call_slots = try self.codecMethodCallSlots(instantiated_calls),
            .grounding_call_index = null,
            .constructor_node = boundary.callable_node,
            .shape_node = boundary.shape_node,
        };
    }

    fn activeCodecCalls(self: *const BodyContext) []const InstantiatedGeneratedCodecCall {
        const active = self.active_codec_contract orelse return &.{};
        if (active.calls_start > self.instantiated_codec_calls.items.len or
            active.calls_len > self.instantiated_codec_calls.items.len - active.calls_start)
        {
            Common.invariant("active generated codec contract referenced an invalid instantiated-call span");
        }
        return self.instantiated_codec_calls.items[active.calls_start..][0..active.calls_len];
    }

    fn codecMethodCallSlots(
        self: *BodyContext,
        calls: []const InstantiatedGeneratedCodecCall,
    ) Allocator.Error![]CodecMethodCallSlot {
        // At most one slot per call is needed. The returned prefix excludes
        // duplicate roles; the backing storage is graph-arena owned because
        // active contracts can survive through deferred Phase-A preparation.
        const slots = try self.graph.arena().alloc(CodecMethodCallSlot, calls.len);
        var len: usize = 0;
        for (calls, 0..) |call, call_index| {
            var exists = false;
            for (slots[0..len]) |slot| {
                if (slot.method != call.checked.method or
                    slot.method_role != call.checked.method_role) continue;
                if ((slot.subject_node == null) != (call.subject_node == null)) {
                    Common.invariant("checked generated codec role mixed subject-bearing and reusable calls");
                }
                exists = true;
                break;
            }
            if (exists) continue;
            if (call_index > std.math.maxInt(u32)) {
                Common.invariant("checked generated codec call index exceeded its identity range");
            }
            slots[len] = .{
                .method = call.checked.method,
                .method_role = call.checked.method_role,
                .subject_node = call.subject_node,
                .call_index = @intCast(call_index),
            };
            len += 1;
        }
        return slots[0..len];
    }

    fn activeCodecContractContainsLocalTarget(self: *const BodyContext) bool {
        for (self.activeCodecCalls()) |call| switch (call.resolution) {
            .structural => {},
            .callable => |node_id| switch (call.view.static_dispatch_plans.evidenceNode(node_id).target.kind) {
                .local_proc => return true,
                .procedure, .structural => {},
            },
        };
        return false;
    }

    fn activeCodecContractContext(self: *BodyContext) ?DraftCodecContractContext {
        const active = self.active_codec_contract orelse return null;
        const grounding_index = active.grounding_call_index orelse return null;
        for (self.activeCodecCalls()) |call| {
            if (call.call_index != grounding_index) continue;
            return .{
                .anchor = .{
                    .view = active.view,
                    .derivation = active.derivation,
                    .call_index = grounding_index,
                    .kind = active.kind,
                },
                .constructor_node = active.constructor_node,
                .shape_node = active.shape_node,
            };
        }
        Common.invariant("active generated codec contract lost its grounding call");
    }

    fn activeCodecContractContextForAnchor(
        self: *BodyContext,
        anchor: CheckedCodecContractAnchor,
    ) DraftCodecContractContext {
        const active = self.active_codec_contract orelse
            Common.invariant("generated codec call specialization had no active contract");
        if (!moduleBytesEqual(active.view.key.bytes, anchor.view.key.bytes) or
            active.derivation != anchor.derivation or
            active.kind != anchor.kind or
            anchor.call_index >= active.calls_len)
        {
            Common.invariant("generated codec call anchor disagreed with its active contract");
        }
        return .{ .anchor = anchor, .constructor_node = active.constructor_node, .shape_node = active.shape_node };
    }

    fn retainActiveCodecContract(self: *BodyContext) Allocator.Error!RetainedCodecContract {
        const active = self.active_codec_contract orelse
            Common.invariant("generated codec intrinsic was deferred outside a generated codec contract");
        const calls = try self.allocator.dupe(InstantiatedGeneratedCodecCall, self.activeCodecCalls());
        errdefer self.allocator.free(calls);
        const method_call_slots = try self.allocator.dupe(CodecMethodCallSlot, active.method_call_slots);
        return .{
            .view = active.view,
            .derivation = active.derivation,
            .kind = active.kind,
            .evidence = active.evidence,
            .calls = calls,
            .method_call_slots = method_call_slots,
            .grounding_call_index = active.grounding_call_index,
            .constructor_node = active.constructor_node,
            .shape_node = active.shape_node,
        };
    }

    fn installRetainedCodecContract(
        self: *BodyContext,
        retained: RetainedCodecContract,
    ) Allocator.Error!void {
        if (self.active_codec_contract != null or self.instantiated_codec_calls.items.len != 0) {
            Common.invariant("retained generated codec contract was installed into a nonempty context");
        }
        try self.instantiated_codec_calls.appendSlice(self.allocator, retained.calls);
        self.active_codec_contract = .{
            .view = retained.view,
            .derivation = retained.derivation,
            .kind = retained.kind,
            .evidence = retained.evidence,
            .calls_start = 0,
            .calls_len = retained.calls.len,
            .method_call_slots = try self.graph.arena().dupe(CodecMethodCallSlot, retained.method_call_slots),
            .grounding_call_index = retained.grounding_call_index,
            .constructor_node = retained.constructor_node,
            .shape_node = retained.shape_node,
        };
    }

    fn generatedCodecCall(
        self: *BodyContext,
        method_name: []const u8,
        subject_node: ?NodeId,
    ) Allocator.Error!?InstantiatedGeneratedCodecCall {
        const active = self.active_codec_contract orelse return null;
        if (active.calls_start > self.instantiated_codec_calls.items.len or
            active.calls_len > self.instantiated_codec_calls.items.len - active.calls_start)
        {
            Common.invariant("active generated codec contract referenced an invalid instantiated-call span");
        }
        const requested_has_subject = subject_node != null;
        const calls = self.instantiated_codec_calls.items[active.calls_start..][0..active.calls_len];
        var selected: ?CodecMethodCallSlot = null;
        for (active.method_call_slots) |slot| {
            if (!std.mem.eql(u8, active.view.names.methodNameText(slot.method), method_name) or
                (slot.subject_node != null) != requested_has_subject) continue;
            if (subject_node) |requested_subject| {
                if (!(try self.sameCodecSubject(slot.subject_node.?, requested_subject))) continue;
            }
            if (selected != null) {
                Common.invariant("checked generated codec contract had overlapping direct call roles");
            }
            selected = slot;
        }
        const slot = selected orelse return null;
        if (slot.call_index >= calls.len) {
            Common.invariant("checked generated codec direct call slot was out of bounds");
        }
        if (@import("builtin").mode == .debug) {
            for (calls) |*candidate| {
                if (candidate.checked.method != slot.method or
                    candidate.checked.method_role != slot.method_role or
                    (candidate.subject_node != null) != requested_has_subject) continue;
                candidate.debug_consumed = true;
            }
        }
        return calls[slot.call_index];
    }

    fn sameCodecSubject(self: *BodyContext, checked_subject: NodeId, requested_subject: NodeId) Allocator.Error!bool {
        // A declaration-backed nominal opens its backing in a declaration
        // scope, independently from the checked codec contract's snapshot.
        // Closed primitives and named applications still have exact constant-
        // time identities even when those two producer paths allocate distinct
        // graph nodes; no wider structural comparison is permitted here.
        const checked_content = (try self.graph.content(checked_subject));
        const requested_content = (try self.graph.content(requested_subject));
        switch (checked_content) {
            .primitive => |checked_primitive| return switch (requested_content) {
                .primitive => |requested_primitive| checked_primitive == requested_primitive,
                .redirect, .leaf, .unresolved, .named, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => false,
            },
            .named => return (try self.graph.sameRelatedNamedInstance(checked_subject, requested_subject)),
            .redirect, .leaf, .unresolved, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return self.graph.sameClass(checked_subject, requested_subject),
        }
    }

    fn debugVerifyGeneratedCodecContractConsumed(
        self: *BodyContext,
        active: ActiveCodecContract,
    ) void {
        if (@import("builtin").mode != .debug or active.grounding_call_index != null) return;
        if (active.calls_start > self.instantiated_codec_calls.items.len or
            active.calls_len > self.instantiated_codec_calls.items.len - active.calls_start)
        {
            Common.invariant("generated codec consumption audit received an invalid call span");
        }
        for (self.instantiated_codec_calls.items[active.calls_start..][0..active.calls_len]) |call| {
            if (!call.debug_consumed) {
                base.invariant(
                    "postcheck invariant violated: Monotype did not consume checker-required generated codec call {s} role {} (subject: {s})",
                    .{
                        call.view.names.methodNameText(call.checked.method),
                        call.checked.method_role,
                        if (call.checked.subject_ty == null) "none" else "present",
                    },
                );
            }
        }
    }

    fn generatedCodecBoundaryCall(
        self: *BodyContext,
        kind: CodecKind,
        shape_node: NodeId,
    ) Allocator.Error!?InstantiatedGeneratedCodecCall {
        const method_name = switch (kind) {
            .parser => Ident.PARSER_FOR_METHOD_NAME,
            .encoder => Ident.ENCODER_FOR_METHOD_NAME,
        };
        const active = self.active_codec_contract orelse return null;
        if ((try self.graph.content(shape_node)) != .named) return null;
        // Repeated occurrences of one nominal subject share the checker's
        // method role, so the role slot selects the boundary call exactly as it
        // does for every other generated codec call.
        const selected = (try self.generatedCodecCall(method_name, shape_node)) orelse return null;
        const selected_subject = selected.subject_node orelse
            Common.invariant("checked generated codec boundary call had no nominal subject");
        if ((try self.graph.content(selected_subject)) != .named) {
            Common.invariant("checked generated codec boundary subject was not nominal");
        }
        // At its own anchor shape the active contract is this nominal's
        // derivation. A call there that names the same derivation is the
        // nominal's recursive reference to itself, which the active contract
        // already covers, so the anchor is not a nested boundary.
        switch (selected.resolution) {
            .structural => |nested| if (nested == active.derivation and
                self.graph.sameClass(active.shape_node, shape_node)) return null,
            .callable => {},
        }
        return selected;
    }

    fn requiredGeneratedCodecTarget(
        self: *BodyContext,
        method_name: []const u8,
        subject_node: ?NodeId,
    ) Allocator.Error!struct {
        lookup: MethodLookup,
        method_name: []const u8,
        method_role: u32,
        subject_bearing: bool,
        callable_node: NodeId,
        contract: EvidenceContract,
        anchor: CheckedCodecContractAnchor,
    } {
        const call = (try self.generatedCodecCall(method_name, subject_node)) orelse
            base.invariant(
                "postcheck invariant violated: checked generated codec contract was missing required method call {s} (subject: {s})",
                .{ method_name, if (subject_node == null) "none" else "present" },
            );
        const lookup = switch (call.resolution) {
            .callable => try self.generatedCodecCallLookup(call),
            .structural => Common.invariant("generated codec format call resolved to a structural derivation"),
        };
        return .{
            // The instantiated callable is carried by `callable_node`.
            // Keeping it out of the lookup identity lets frozen emission
            // match the same target without re-instantiating checked types.
            .lookup = lookup,
            .method_name = call.view.names.methodNameText(call.checked.method),
            .method_role = call.checked.method_role,
            .subject_bearing = call.subject_node != null,
            .callable_node = call.callable_node,
            .contract = .{
                .view = call.view,
                .entries = call.view.static_dispatch_plans.generatedCodecCallEvidence(call.checked),
            },
            .anchor = blk: {
                const active = self.active_codec_contract orelse
                    Common.invariant("generated codec call had no active checker contract");
                if (!moduleBytesEqual(active.view.key.bytes, call.view.key.bytes)) {
                    Common.invariant("generated codec call belonged to a different active checker contract");
                }
                break :blk .{
                    .view = active.view,
                    .derivation = active.derivation,
                    .call_index = call.call_index,
                    .kind = active.kind,
                };
            },
        };
    }

    /// Resolve a generated call's exact checked target in the artifact view
    /// that owns it. The consuming BodyContext can belong to a different
    /// module (for example, a generic encoder boundary calling an app-defined
    /// nominal encoder), so local-procedure context is resolved there too.
    fn generatedCodecCallLookup(
        self: *BodyContext,
        call: InstantiatedGeneratedCodecCall,
    ) Allocator.Error!MethodLookup {
        const node_id = switch (call.resolution) {
            .callable => |node_id| node_id,
            .structural => Common.invariant("structural generated codec call had no callable evidence target"),
        };
        const node = call.view.static_dispatch_plans.evidenceNode(node_id);
        const previous_view = self.view;
        const previous_source_file_id = self.source_file_id;
        const previous_evidence = self.evidence;
        const active = self.active_codec_contract orelse
            Common.invariant("generated codec call materialized outside its active contract");
        if (!moduleBytesEqual(active.view.key.bytes, call.view.key.bytes)) {
            Common.invariant("generated codec call materialized through a different active contract");
        }
        self.view = call.view;
        self.source_file_id = self.builder.sourceFileId(call.view);
        self.evidence = active.evidence;
        defer {
            self.view = previous_view;
            self.source_file_id = previous_source_file_id;
            self.evidence = previous_evidence;
        }
        return try self.methodLookupForEvidencePurpose(
            self.methodLookupForResolvedTarget(node.target),
            .body_lowering,
        );
    }

    fn activateNestedCodecContract(
        self: *BodyContext,
        call: InstantiatedGeneratedCodecCall,
        shape_node: NodeId,
    ) Allocator.Error!ActiveCodecContract {
        const nested_id = switch (call.resolution) {
            .structural => |nested| nested,
            .callable => Common.invariant("callable generated codec target reached nested structural activation"),
        };
        const derivation: static_dispatch.StructuralDerivation = switch ((self.active_codec_contract orelse
            Common.invariant("nested codec activation had no parent contract")).kind) {
            .parser => .parser,
            .encoder => .encoder,
        };
        return try self.instantiateCodecContract(.{
            .derivation = derivation,
            .checked = .{
                .view = call.view,
                .evidence = .{
                    .derivation = derivation,
                    .dispatcher_ty = call.checked.dispatcher_ty,
                    .callable_ty = call.checked.callable_ty,
                    .generated_codec_derivation = nested_id,
                },
            },
        }, call.callable_node, shape_node);
    }

    fn prepareCustomCodecCall(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        kind: CodecKind,
        shape_node: NodeId,
        boundary_callable_node: NodeId,
        checked_call: InstantiatedGeneratedCodecCall,
    ) Allocator.Error!bool {
        const lookup = switch (checked_call.resolution) {
            .callable => try self.generatedCodecCallLookup(checked_call),
            .structural => Common.invariant("structural generated codec call reached callable preparation"),
        };
        const active = self.active_codec_contract orelse
            Common.invariant("custom codec call had no active checker contract");
        if (!moduleBytesEqual(active.view.key.bytes, checked_call.view.key.bytes)) {
            Common.invariant("custom codec call belonged to a different active checker contract");
        }
        const method_name = checked_call.view.names.methodNameText(checked_call.checked.method);
        if (self.preparedCodecCallExists(
            boundary_expr,
            kind,
            .custom,
            method_name,
            active.view.key.bytes,
            active.derivation,
            checked_call.checked.method_role,
        )) return false;

        const boundary_callable = try self.graph.functionNodes(boundary_callable_node);
        if (boundary_callable.args.len != 1) Common.invariant("structural codec constructor did not have one encoding argument");
        const encoding_node = boundary_callable.args[0];
        const runtime = try self.graph.functionNodes(boundary_callable.ret);

        const target_node = checked_call.callable_node;
        const target = try self.graph.functionNodes(target_node);
        if (target.args.len != 1) Common.invariant("custom codec target did not have one encoding argument");
        try relateRequestComponent(self.graph, target.args[0], encoding_node);
        const target_runtime = try self.graph.functionNodes(target.ret);

        switch (kind) {
            .parser => {
                if (runtime.args.len != 1 or target_runtime.args.len != 1) {
                    Common.invariant("custom parser runtime did not have one state argument");
                }
                try relateRequestComponent(self.graph, target_runtime.args[0], runtime.args[0]);
                const outer_result = try self.graphParserResultNodes(runtime.ret);
                const target_result = try self.graphParserResultNodes(target_runtime.ret);
                try relateRequestComponent(self.graph, target_result.value, shape_node);
                try relateRequestComponent(self.graph, target_result.rest, outer_result.rest);
                try self.relateParserErrorInjection(target_result.err, outer_result.err);
            },
            .encoder => {
                if (runtime.args.len != 2 or target_runtime.args.len != 2) {
                    Common.invariant("custom encoder runtime did not have value and state arguments");
                }
                try relateRequestComponent(self.graph, target_runtime.args[0], shape_node);
                try relateRequestComponent(self.graph, target_runtime.args[1], runtime.args[1]);
                try relateRequestComponent(self.graph, target_runtime.ret, runtime.ret);
            },
        }
        const callee = try self.methodTargetCalleeAtNodeForCodec(
            lookup,
            target_node,
            .{
                .view = checked_call.view,
                .entries = checked_call.view.static_dispatch_plans.generatedCodecCallEvidence(checked_call.checked),
            },
            .{
                .view = active.view,
                .derivation = active.derivation,
                .call_index = checked_call.call_index,
                .kind = active.kind,
            },
        );
        try self.draft.prepared_codec_calls.append(self.allocator, .{
            .boundary_expr = boundary_expr,
            .kind = kind,
            .purpose = .custom,
            .method_name = method_name,
            .method_role = checked_call.checked.method_role,
            .subject_bearing = checked_call.subject_node != null,
            .contract_view = active.view.key.bytes,
            .contract_derivation = active.derivation,
            .shape_node = shape_node,
            .lookup = lookup,
            .callable_node = target_node,
            .callee = callee,
        });
        return true;
    }

    /// Resolve the callee for the required codec target `exact` and record
    /// the prepared call for `boundary_expr`.
    fn appendPreparedRequiredCodecCall(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        kind: CodecKind,
        shape_node: NodeId,
        exact: anytype,
    ) Allocator.Error!void {
        const callee = try self.methodTargetCalleeAtNodeForFormat(exact.lookup, exact.callable_node, exact.contract);
        try self.draft.prepared_codec_calls.append(self.allocator, .{
            .boundary_expr = boundary_expr,
            .kind = kind,
            .method_name = exact.method_name,
            .method_role = exact.method_role,
            .subject_bearing = exact.subject_bearing,
            .contract_view = exact.anchor.view.key.bytes,
            .contract_derivation = exact.anchor.derivation,
            .shape_node = shape_node,
            .lookup = exact.lookup,
            .callable_node = exact.callable_node,
            .callee = callee,
        });
    }

    fn prepareRenameRecordFieldCodecCall(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        kind: CodecKind,
        shape_node: NodeId,
        boundary_callable_node: NodeId,
    ) Allocator.Error!bool {
        const boundary = try self.graph.functionNodes(boundary_callable_node);
        if (boundary.args.len != 1) Common.invariant("structural parser constructor did not have one encoding argument");
        const encoding_node = boundary.args[0];
        const exact = try self.requiredGeneratedCodecTarget("rename_field", null);
        if (self.preparedRequiredCodecCallExists(boundary_expr, kind, exact)) return false;

        const target_node = exact.callable_node;
        const target = try self.graph.functionNodes(target_node);
        if (target.args.len != 2) Common.invariant("rename_field target did not have two arguments");
        const str_node = try self.graph.newNode(.{ .primitive = .str });
        try relateRequestComponent(self.graph, target.args[0], encoding_node);
        try relateRequestComponent(self.graph, target.args[1], str_node);
        try relateRequestComponent(self.graph, target.ret, str_node);

        try self.appendPreparedRequiredCodecCall(boundary_expr, kind, shape_node, exact);
        return true;
    }

    fn prepareEncodeContainerCodecCall(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        shape_node: NodeId,
        contract_subject_node: NodeId,
        boundary_callable_node: NodeId,
        method_name: []const u8,
    ) Allocator.Error!bool {
        const boundary = try self.graph.functionNodes(boundary_callable_node);
        if (boundary.args.len != 1) Common.invariant("structural encoder constructor did not have one encoding argument");
        const runtime = try self.graph.functionNodes(boundary.ret);
        if (runtime.args.len != 2) Common.invariant("structural encoder runtime did not have value and state arguments");
        const state_node = runtime.args[1];
        const exact = try self.requiredGeneratedCodecTarget(method_name, contract_subject_node);
        if (self.preparedRequiredCodecCallExists(boundary_expr, .encoder, exact)) return false;

        const target_node = exact.callable_node;
        const target = try self.graph.functionNodes(target_node);
        if (target.args.len < 1) Common.invariant("container encoder target had no state argument");
        try relateRequestComponent(self.graph, target.args[0], state_node);
        try relateRequestComponent(self.graph, target.ret, runtime.ret);

        try self.appendPreparedRequiredCodecCall(boundary_expr, .encoder, shape_node, exact);
        return true;
    }

    /// The shapes a derived codec reads out of a builtin keyed container: a
    /// dict's value and its key, or a set's element. Empty for anything else.
    ///
    /// A key the format renders as a key string is read by the `parse_key_*`
    /// and `encode_key_*` methods rather than by a shape codec, so only a key
    /// that needs its own codec is included.
    fn graphBuiltinContainerShapeNodes(self: *BodyContext, node: NodeId, buf: *[2]NodeId) Allocator.Error![]const NodeId {
        const named = switch ((try self.graph.content(node))) {
            .named => |named| named,
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return &.{},
        };
        const owner = named.builtin_owner orelse return &.{};
        switch (owner) {
            .dict => {
                if (named.args.len != 2) Common.invariant("builtin Dict node had an unexpected arity");
                buf[0] = named.args[1];
                if ((try self.graphNodeIsStringRenderedDictKey(named.args[0]))) return buf[0..1];
                buf[1] = named.args[0];
                return buf[0..2];
            },
            .set => {
                if (named.args.len != 1) Common.invariant("builtin Set node had an unexpected arity");
                buf[0] = named.args[0];
                return buf[0..1];
            },
            .list, .box, .fields, .field, .bool, .str, .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, .parse_tag_union_spec, .crypto_sha256_digest, .crypto_sha256_hasher, .crypto_blake3_digest, .crypto_blake3_hasher, .iter, .stream => return &.{},
        }
    }

    /// Whether a dict key node is one the `parse_key_*`/`encode_key_*` methods
    /// read, which is every key kind that renders as a key string.
    fn graphNodeIsStringRenderedDictKey(self: *BodyContext, node: NodeId) Allocator.Error!bool {
        switch ((try self.graph.content(node))) {
            .tag_union => |row| {
                for (row.tags) |tag| {
                    if (tag.payloads.len != 0) return false;
                }
                return true;
            },
            .named => |named| {
                const owner = named.builtin_owner orelse return false;
                return switch (owner) {
                    .bool, .str, .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec => true,
                    .list, .box, .dict, .set, .fields, .field, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, .parse_tag_union_spec, .crypto_sha256_digest, .crypto_sha256_hasher, .crypto_blake3_digest, .crypto_blake3_hasher, .iter, .stream => false,
                };
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_tag_union, .empty_record, .erased, .zst => return false,
        }
    }

    fn graphNodeIsBuiltinTry(self: *BodyContext, node: NodeId) Allocator.Error!bool {
        const named = switch ((try self.graph.content(node))) {
            .named => |named| named,
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return false,
        };
        return self.builder.isBuiltinTryDef(self.nameStore(), named.def);
    }

    fn graphShapeNode(self: *BodyContext, raw_node: NodeId) Allocator.Error!NodeId {
        var node = raw_node;
        while (true) {
            switch ((try self.graph.content(node))) {
                .named => |named| if (named.backing) |backing| {
                    node = backing.node;
                    continue;
                },
                .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => {},
            }
            return node;
        }
    }

    /// A pending step of a parser record-shape walk: a node to visit, or the
    /// codec contract to restore once a node's components are visited.
    const GraphParserShapeStep = union(enum) {
        node: NodeId,
        restore_contract: struct { contract: ?ActiveCodecContract, call_count: usize },
    };

    /// Record shapes reachable from `root` in pre-order, each visited once. A
    /// structural codec boundary's nested contract is active while its
    /// components are visited.
    fn appendGraphParserRecordShapes(
        self: *BodyContext,
        root: NodeId,
        shapes: *std.ArrayList(NodeId),
        seen: *collections.DenseMap(NodeId, void),
    ) Allocator.Error!void {
        var pending = std.ArrayList(GraphParserShapeStep).empty;
        defer pending.deinit(self.allocator);
        errdefer {
            // Restore the outermost contract any unfinished node activated.
            for (pending.items) |step| switch (step) {
                .restore_contract => |restore| {
                    self.active_codec_contract = restore.contract;
                    self.instantiated_codec_calls.shrinkRetainingCapacity(restore.call_count);
                    break;
                },
                .node => {},
            };
        }
        try pending.append(self.allocator, .{ .node = root });
        while (pending.pop()) |step| {
            const node = switch (step) {
                .node => |node| node,
                .restore_contract => |restore| {
                    self.active_codec_contract = restore.contract;
                    self.instantiated_codec_calls.shrinkRetainingCapacity(restore.call_count);
                    continue;
                },
            };
            const seen_entry = try seen.getOrPut(node);
            if (seen_entry.found_existing) continue;

            if ((try self.graphNodeIsBuiltinTry(node))) {
                const payloads = try self.graphTryPayloads(node);
                try pending.append(self.allocator, .{ .node = payloads.ok });
                continue;
            }
            if ((try self.generatedCodecBoundaryCall(.parser, node))) |codec_call| {
                switch (codec_call.resolution) {
                    .callable => continue,
                    .structural => {
                        try pending.append(self.allocator, .{ .restore_contract = .{
                            .contract = self.active_codec_contract,
                            .call_count = self.instantiated_codec_calls.items.len,
                        } });
                        self.active_codec_contract = try self.activateNestedCodecContract(codec_call, node);
                    },
                }
            }

            const children_start = pending.items.len;
            switch ((try self.graph.content(node))) {
                .list, .box => |elem| try pending.append(self.allocator, .{ .node = elem }),
                .tuple => |items| for (items) |item| try pending.append(self.allocator, .{ .node = item }),
                .record => {
                    try shapes.append(self.allocator, node);
                    for ((try self.graph.recordNodes(node)).fields) |field|
                        try pending.append(self.allocator, .{ .node = self.graph.codecFieldValueNode(field) });
                },
                .tag_union => {
                    for ((try self.graph.tagRowNodes(node)).tags) |tag|
                        for (tag.payloads) |payload|
                            try pending.append(self.allocator, .{ .node = payload });
                },
                .named => |named| {
                    if (named.builtin_owner == .set and named.args.len == 1) {
                        try pending.append(self.allocator, .{ .node = named.args[0] });
                    } else if (named.builtin_owner == .dict and named.args.len == 2) {
                        try pending.append(self.allocator, .{ .node = named.args[1] });
                    } else if (named.backing) |backing| {
                        try pending.append(self.allocator, .{ .node = backing.node });
                    }
                },
                .redirect, .leaf => unreachable,
                .unresolved, .primitive, .empty_tag_union, .empty_record, .func, .erased, .zst => {},
            }
            std.mem.reverse(GraphParserShapeStep, pending.items[children_start..]);
        }
    }

    fn generatedParseTagUnionSpecBackingNode(
        self: *BodyContext,
        union_node: NodeId,
    ) Allocator.Error!NodeId {
        var record_shapes = std.ArrayList(NodeId).empty;
        defer record_shapes.deinit(self.allocator);
        var seen = collections.DenseMap(NodeId, void).init(self.allocator);
        defer seen.deinit();
        try self.appendGraphParserRecordShapes(union_node, &record_shapes, &seen);

        const str_node = try self.graph.newNode(.{ .primitive = .str });
        const outer_fields = try self.graph.arena().alloc(InstField, record_shapes.items.len);
        for (record_shapes.items, outer_fields, 0..) |record_shape, *outer_field, record_index| {
            const record_fields = (try self.graph.recordNodes(record_shape)).fields;
            const inner_fields = try self.graph.arena().alloc(InstField, record_fields.len);
            for (inner_fields, 0..) |*inner_field, field_index| {
                inner_field.* = .{
                    .name = try self.generatedParseTagUnionSpecBackingFieldName(field_index),
                    .ty = str_node,
                    .default = null,
                };
            }
            outer_field.* = .{
                .name = try self.generatedParseTagUnionSpecBackingRecordFieldName(record_index),
                .ty = try self.graph.newNode(.{ .record = .{
                    .fields = inner_fields,
                    .ext = try self.graph.newNode(.empty_record),
                } }),
                .default = null,
            };
        }
        return try self.graph.newNode(.{ .record = .{
            .fields = outer_fields,
            .ext = try self.graph.newNode(.empty_record),
        } });
    }

    fn cloneGraphNamedWithBackingAuthority(
        self: *BodyContext,
        template_node: NodeId,
        args: []const NodeId,
        backing_node: NodeId,
        authority: Type.BackingAuthority,
    ) Allocator.Error!NodeId {
        const template = switch ((try self.graph.content(template_node))) {
            .named => |named| named,
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => Common.invariant("generated codec protocol template was not a named graph node"),
        };
        return try self.graph.newNode(try self.graph.namedContent(.{
            .named_type = template.named_type,
            .def = template.def,
            .kind = template.kind,
            .builtin_owner = template.builtin_owner,
            .args = try self.graph.arena().dupe(NodeId, args),
            .backing = .{
                .node = backing_node,
                .use = (template.backing orelse Common.invariant("generated codec protocol template had no checked backing")).use,
                .authority = authority,
            },
            .declared_order = template.declared_order,
        }));
    }

    fn cloneGraphNamedWithGeneratedBacking(
        self: *BodyContext,
        template_node: NodeId,
        args: []const NodeId,
        backing_node: NodeId,
    ) Allocator.Error!NodeId {
        return try self.cloneGraphNamedWithBackingAuthority(
            template_node,
            args,
            backing_node,
            .generated_private,
        );
    }

    fn graphClosedRecord(self: *BodyContext, fields: []const InstField) Allocator.Error!NodeId {
        return try self.graph.newNode(.{ .record = .{
            .fields = try self.graph.arena().dupe(InstField, fields),
            .ext = try self.graph.newNode(.empty_record),
        } });
    }

    /// The `parse_record_field` event row at the checked-evidence boundary.
    /// `freshParseRecordFieldEventVar` in check/Check.zig builds the same row
    /// and must agree with this one.
    fn graphParseRecordEvent(
        self: *BodyContext,
        state_node: NodeId,
        field_handle_node: NodeId,
    ) Allocator.Error!NodeId {
        const rest_name = try self.nameStoreMut().internRecordFieldLabel("rest");
        const field_label = try self.nameStoreMut().internRecordFieldLabel("field");
        const name_label = try self.nameStoreMut().internRecordFieldLabel("name");
        const str_node = try self.graph.newNode(.{ .primitive = .str });
        const field_payload = try self.graphClosedRecord(&.{
            .{ .name = field_label, .ty = field_handle_node, .default = null },
            .{ .name = rest_name, .ty = state_node, .default = null },
        });
        const try_field_payload = try self.graphClosedRecord(&.{
            .{ .name = name_label, .ty = str_node, .default = null },
            .{ .name = rest_name, .ty = state_node, .default = null },
        });
        const tag_texts = [_][]const u8{ "Continue", "Done", "Field", "TryField", "TryFieldCaseless" };
        const payloads = [_]NodeId{ state_node, state_node, field_payload, try_field_payload, try_field_payload };
        const tags = try self.graph.arena().alloc(InstTag, tag_texts.len);
        for (tag_texts, payloads, tags) |text, payload, *tag| {
            const name = try self.nameStoreMut().internTagLabel(text);
            tag.* = .{
                .name = name,
                .checked_name = name,
                .payloads = try self.graph.arena().dupe(NodeId, &.{payload}),
            };
        }
        return try self.graph.newNode(.{ .tag_union = .{
            .tags = tags,
            .ext = try self.graph.newNode(.empty_tag_union),
        } });
    }

    fn graphTryLike(
        self: *BodyContext,
        template_try: NodeId,
        ok_node: NodeId,
        err_node: NodeId,
    ) Allocator.Error!NodeId {
        const ok_name = try self.nameStoreMut().internTagLabel("Ok");
        const err_name = try self.nameStoreMut().internTagLabel("Err");
        const backing = try self.graph.newNode(.{ .tag_union = .{
            .tags = try self.graph.arena().dupe(InstTag, &.{
                .{ .name = ok_name, .checked_name = ok_name, .payloads = try self.graph.arena().dupe(NodeId, &.{ok_node}) },
                .{ .name = err_name, .checked_name = err_name, .payloads = try self.graph.arena().dupe(NodeId, &.{err_node}) },
            }),
            .ext = try self.graph.newNode(.empty_tag_union),
        } });
        return try self.cloneGraphNamedWithBackingAuthority(
            template_try,
            &.{ ok_node, err_node },
            backing,
            .checked_public,
        );
    }

    /// The encoding argument, state argument, and result nodes of a structural
    /// parser constructor: a function of the encoding returning the runtime
    /// function of the state.
    fn parserBoundaryNodes(self: *BodyContext, boundary_callable_node: NodeId) Allocator.Error!struct { NodeId, NodeId, ParserResultNodes } {
        const boundary = try self.graph.functionNodes(boundary_callable_node);
        if (boundary.args.len != 1) Common.invariant("structural parser constructor did not have one encoding argument");
        const runtime = try self.graph.functionNodes(boundary.ret);
        if (runtime.args.len != 1) Common.invariant("structural parser runtime did not have one state argument");
        return .{ boundary.args[0], runtime.args[0], try self.graphParserResultNodes(runtime.ret) };
    }

    fn prepareParseRecordFieldCodecCall(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        // Emission indexes the prepared call by the public value shape, while
        // the checker-authored method edge names the exact structural backing
        // whose generated record body calls `parse_record_field`.
        shape_node: NodeId,
        contract_subject_node: NodeId,
        boundary_callable_node: NodeId,
    ) Allocator.Error!bool {
        const encoding_node, const state_node, const outer_result = try self.parserBoundaryNodes(boundary_callable_node);
        const exact = try self.requiredGeneratedCodecTarget("parse_record_field", contract_subject_node);
        const lookup = exact.lookup;
        if (self.preparedRequiredCodecCallExists(boundary_expr, .parser, exact)) return false;

        const target_node = exact.callable_node;
        const target = try self.graph.functionNodes(target_node);
        if (target.args.len != 3) Common.invariant("parse_record_field target did not have three arguments");
        try relateRequestComponent(self.graph, target.args[0], encoding_node);
        try relateRequestComponent(self.graph, target.args[2], state_node);
        const target_try = try self.graphTryPayloads(target.ret);
        try self.relateParserErrorInjection(target_try.err, outer_result.err);

        const field_tag_name = try self.nameStoreMut().internTagLabel("Field");
        const field_tag = graphTagByName((try self.graph.tagRowNodes(target_try.ok)).tags, field_tag_name) orelse
            Common.invariant("parse_record_field event type had no Field tag");
        if (field_tag.payloads.len != 1) Common.invariant("parse_record_field Field event did not have one payload");
        const field_label = try self.nameStoreMut().internRecordFieldLabel("field");
        const field_handle_template = try self.graph.recordFieldNode(field_tag.payloads[0], field_label);
        const u64_node = try self.graph.newNode(.{ .primitive = .u64 });
        const str_node = try self.graph.newNode(.{ .primitive = .str });
        const field_handle_backing = try self.graphClosedRecord(&.{
            .{ .name = try self.nameStoreMut().internRecordFieldLabel("index"), .ty = u64_node, .default = null },
            .{ .name = try self.nameStoreMut().internRecordFieldLabel("name"), .ty = str_node, .default = null },
            .{ .name = try self.nameStoreMut().internRecordFieldLabel("name_len"), .ty = u64_node, .default = null },
        });
        const field_handle = try self.cloneGraphNamedWithGeneratedBacking(
            field_handle_template,
            &.{shape_node},
            field_handle_backing,
        );

        const record_fields = switch ((try self.graph.content((try self.graphShapeNode(shape_node))))) {
            .zst, .empty_record => &.{},
            .record => (try self.graph.recordNodes((try self.graphShapeNode(shape_node)))).fields,
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .named, .empty_tag_union, .erased => Common.invariant("generated parse tag-union specification shape was not a record"),
        };
        const item_fields = try self.graph.arena().alloc(InstField, record_fields.len);
        for (item_fields, 0..) |*field, index| {
            field.* = .{
                .name = try self.generatedParseTagUnionSpecBackingFieldName(index),
                .ty = field_handle,
                .default = null,
            };
        }
        const items = try self.graphClosedRecord(item_fields);
        const fields_backing = try self.graphClosedRecord(&.{
            .{ .name = try self.nameStoreMut().internRecordFieldLabel("items"), .ty = items, .default = null },
            .{ .name = try self.nameStoreMut().internRecordFieldLabel("shortest_name"), .ty = u64_node, .default = null },
            .{ .name = try self.nameStoreMut().internRecordFieldLabel("longest_name"), .ty = u64_node, .default = null },
        });
        const fields_node = try self.cloneGraphNamedWithGeneratedBacking(
            target.args[1],
            &.{shape_node},
            fields_backing,
        );
        const event_node = try self.graphParseRecordEvent(state_node, field_handle);
        const result_node = try self.graphTryLike(target.ret, event_node, target_try.err);
        const request_node = try functionRequestNode(
            self.graph,
            target_node,
            &.{ encoding_node, fields_node, state_node },
            result_node,
        );
        const callee = try self.methodTargetCalleeAtNodeForFormat(lookup, request_node, exact.contract);
        try self.draft.prepared_codec_calls.append(self.allocator, .{
            .boundary_expr = boundary_expr,
            .kind = .parser,
            .method_name = exact.method_name,
            .method_role = exact.method_role,
            .subject_bearing = exact.subject_bearing,
            .contract_view = exact.anchor.view.key.bytes,
            .contract_derivation = exact.anchor.derivation,
            .shape_node = shape_node,
            .lookup = lookup,
            .callable_node = request_node,
            .callee = callee,
        });
        return true;
    }

    fn prepareSkipRecordFieldCodecCall(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        shape_node: NodeId,
        boundary_callable_node: NodeId,
    ) Allocator.Error!bool {
        const encoding_node, const state_node, const outer_result = try self.parserBoundaryNodes(boundary_callable_node);
        const exact = try self.requiredGeneratedCodecTarget("skip_record_field", null);
        if (self.preparedRequiredCodecCallExists(boundary_expr, .parser, exact)) return false;

        const target_node = exact.callable_node;
        const target = try self.graph.functionNodes(target_node);
        if (target.args.len != 2) Common.invariant("skip_record_field target did not have two arguments");
        try relateRequestComponent(self.graph, target.args[0], encoding_node);
        try relateRequestComponent(self.graph, target.args[1], state_node);
        const target_try = try self.graphTryPayloads(target.ret);
        try relateRequestComponent(self.graph, target_try.ok, state_node);
        try self.relateParserErrorInjection(target_try.err, outer_result.err);

        try self.appendPreparedRequiredCodecCall(boundary_expr, .parser, shape_node, exact);
        return true;
    }

    fn prepareParseTagUnionCodecCall(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        // Emission uses the public value shape; the contract subject is the
        // checker-authored role selected for this generated body.
        shape_node: NodeId,
        contract_subject_node: NodeId,
        boundary_callable_node: NodeId,
    ) Allocator.Error!bool {
        const encoding_node, const state_node, const outer_result = try self.parserBoundaryNodes(boundary_callable_node);

        const exact = try self.requiredGeneratedCodecTarget("parse_tag_union", contract_subject_node);
        const lookup = exact.lookup;
        if (self.preparedRequiredCodecCallExists(boundary_expr, .parser, exact)) return false;

        const target_node = exact.callable_node;
        const target = try self.graph.functionNodes(target_node);
        if (target.args.len != 3) Common.invariant("parse_tag_union target did not have three arguments");
        try relateRequestComponent(self.graph, target.args[0], encoding_node);
        try relateRequestComponent(self.graph, target.args[2], state_node);
        const target_result = try self.graphParserResultNodes(target.ret);
        try relateRequestComponent(self.graph, target_result.value, shape_node);
        try relateRequestComponent(self.graph, target_result.rest, outer_result.rest);
        try relateRequestComponent(self.graph, target_result.err, outer_result.err);

        const private_spec = try self.cloneGraphNamedWithGeneratedBacking(
            target.args[1],
            &.{shape_node},
            try self.generatedParseTagUnionSpecBackingNode(shape_node),
        );
        const request_node = try functionRequestNode(
            self.graph,
            target_node,
            &.{ encoding_node, private_spec, state_node },
            target.ret,
        );
        const callee = try self.methodTargetCalleeAtNodeForCodec(lookup, request_node, exact.contract, exact.anchor);
        try self.draft.prepared_codec_calls.append(self.allocator, .{
            .boundary_expr = boundary_expr,
            .kind = .parser,
            .method_name = exact.method_name,
            .method_role = exact.method_role,
            .subject_bearing = exact.subject_bearing,
            .contract_view = exact.anchor.view.key.bytes,
            .contract_derivation = exact.anchor.derivation,
            .shape_node = shape_node,
            .lookup = lookup,
            .callable_node = request_node,
            .callee = callee,
        });
        return true;
    }

    fn graphErrorIsExactUnitTag(
        self: *BodyContext,
        node: NodeId,
        tag_text: []const u8,
    ) Allocator.Error!bool {
        switch ((try self.graph.content(node))) {
            .tag_union, .named => {},
            .unresolved, .empty_tag_union, .redirect, .leaf, .primitive, .list, .box, .tuple, .func, .record, .empty_record, .erased, .zst => return false,
        }
        if (!try self.graph.tagRowIsClosed(node)) return false;
        const tags = (try self.graph.tagRowNodes(node)).tags;
        if (tags.len != 1 or tags[0].payloads.len != 0) return false;
        return Ident.textEql(self.nameStore().tagLabelText(tags[0].name), tag_text);
    }

    fn graphMissingTryOkNode(self: *BodyContext, node: NodeId) Allocator.Error!?NodeId {
        if (!(try self.graphNodeIsBuiltinTry(node))) return null;
        const payloads = try self.graphTryPayloads(node);
        return if (try self.graphErrorIsExactUnitTag(payloads.err, "Missing")) payloads.ok else null;
    }

    fn graphNodeHasJsonScalarParser(self: *BodyContext, node: NodeId) Allocator.Error!bool {
        return (try self.graphScalarCodecMethodName(node, "parse_")) != null;
    }

    /// The format method (`prefix` plus the scalar's name) that reads or
    /// writes a builtin scalar node, or null when the node is not one.
    fn graphScalarCodecMethodName(self: *BodyContext, node: NodeId, comptime prefix: []const u8) Allocator.Error!?[]const u8 {
        const owner = switch ((try self.methodOwnerFromNode(node)) orelse return null) {
            .builtin => |builtin| builtin,
            .nominal => return null,
        };
        return switch (owner) {
            .bool => prefix ++ "bool",
            .str => prefix ++ "str",
            .u8 => prefix ++ "u8",
            .i8 => prefix ++ "i8",
            .u16 => prefix ++ "u16",
            .i16 => prefix ++ "i16",
            .u32 => prefix ++ "u32",
            .i32 => prefix ++ "i32",
            .u64 => prefix ++ "u64",
            .i64 => prefix ++ "i64",
            .u128 => prefix ++ "u128",
            .i128 => prefix ++ "i128",
            .f32 => prefix ++ "f32",
            .f64 => prefix ++ "f64",
            .dec => prefix ++ "dec",
            .list, .box, .dict, .set, .fields, .field, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, .parse_tag_union_spec, .crypto_sha256_digest, .crypto_sha256_hasher, .crypto_blake3_digest, .crypto_blake3_hasher, .iter, .stream => null,
        };
    }

    fn prepareParseScalarCodecCall(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        shape_node: NodeId,
        boundary_callable_node: NodeId,
        method_name: []const u8,
    ) Allocator.Error!bool {
        const encoding_node, const state_node, const outer_result = try self.parserBoundaryNodes(boundary_callable_node);
        const exact = try self.requiredGeneratedCodecTarget(method_name, shape_node);
        if (self.preparedRequiredCodecCallExists(boundary_expr, .parser, exact)) return false;

        const target_node = exact.callable_node;
        const target = try self.graph.functionNodes(target_node);
        if (target.args.len != 2) Common.invariant("scalar parser target did not have two arguments");
        try relateRequestComponent(self.graph, target.args[0], encoding_node);
        try relateRequestComponent(self.graph, target.args[1], state_node);
        const target_result = try self.graphParserResultNodes(target.ret);
        try relateRequestComponent(self.graph, target_result.value, shape_node);
        try relateRequestComponent(self.graph, target_result.rest, outer_result.rest);
        try self.relateParserErrorInjection(target_result.err, outer_result.err);

        try self.appendPreparedRequiredCodecCall(boundary_expr, .parser, shape_node, exact);
        return true;
    }

    fn prepareParseFormatControlCodecCall(
        self: *BodyContext,
        boundary_expr: DraftExprId,
