    fn prepareDictCollectionCodecCalls(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        kind: CodecKind,
        dict_node: NodeId,
        key_node: NodeId,
        value_node: NodeId,
    ) Allocator.Error!bool {
        const entry_node = try self.graph.newNode(.{ .tuple = try self.graph.arena().dupe(NodeId, &.{ key_node, value_node }) });
        const entries_node = try self.graph.newNode(.{ .list = entry_node });
        return switch (kind) {
            .parser => blk: {
                const u64_node = try self.graph.newNode(.{ .primitive = .u64 });
                var added = try self.prepareOwnedCodecMethodCall(
                    boundary_expr,
                    kind,
                    dict_node,
                    dict_node,
                    "with_capacity",
                    &.{u64_node},
                    dict_node,
                );
                added = try self.prepareOwnedCodecMethodCall(
                    boundary_expr,
                    kind,
                    dict_node,
                    dict_node,
                    "insert",
                    &.{ dict_node, key_node, value_node },
                    dict_node,
                ) or added;
                break :blk added;
            },
            .encoder => try self.prepareOwnedCodecMethodCall(
                boundary_expr,
                kind,
                dict_node,
                dict_node,
                "to_list",
                &.{dict_node},
                entries_node,
            ),
        };
    }

    /// A pending step of an invalid-value search: a node, or the remaining
    /// fields of a record or payloads of a tag union, read in order as the
    /// search reaches them.
    const InvalidValueStep = union(enum) {
        node: NodeId,
        fields: struct { fields: []const InstField, next: usize },
        payloads: struct { tags: []const InstTag, tag: usize, payload: usize },
    };

    /// Whether any shape reachable from `root` needs the format's invalid
    /// value. Components are searched depth first in source order, each node
    /// once.
    fn graphParserShapeNeedsInvalidValue(
        self: *BodyContext,
        root: NodeId,
        seen: *collections.DenseMap(NodeId, void),
    ) Allocator.Error!bool {
        var pending = std.ArrayList(InvalidValueStep).empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, .{ .node = root });
        while (pending.pop()) |step| {
            const node = switch (step) {
                .node => |node| node,
                .fields => |fields| {
                    if (fields.next == fields.fields.len) continue;
                    try pending.append(self.allocator, .{ .fields = .{ .fields = fields.fields, .next = fields.next + 1 } });
                    const value_node = self.graph.codecFieldValueNode(fields.fields[fields.next]);
                    if (try self.graphMissingTryOkNode(value_node)) |payload| {
                        try pending.append(self.allocator, .{ .node = payload });
                        continue;
                    }
                    switch (self.graph.codecFieldKind(fields.fields[fields.next])) {
                        .optional, .defaulted, .required => try pending.append(self.allocator, .{ .node = value_node }),
                    }
                    continue;
                },
                .payloads => |payloads| {
                    if (payloads.tag == payloads.tags.len) continue;
                    const tag = payloads.tags[payloads.tag];
                    if (payloads.payload == tag.payloads.len) {
                        try pending.append(self.allocator, .{ .payloads = .{ .tags = payloads.tags, .tag = payloads.tag + 1, .payload = 0 } });
                        continue;
                    }
                    try pending.append(self.allocator, .{ .payloads = .{ .tags = payloads.tags, .tag = payloads.tag, .payload = payloads.payload + 1 } });
                    try pending.append(self.allocator, .{ .node = tag.payloads[payloads.payload] });
                    continue;
                },
            };
            const entry = try seen.getOrPut(node);
            if (entry.found_existing) continue;

            if ((try self.graphNodeHasJsonScalarParser(node))) continue;
            if ((try self.generatedCodecBoundaryCall(.parser, node)) != null) continue;
            if ((try self.graphNodeIsBuiltinTry(node))) {
                const payloads = try self.graphTryPayloads(node);
                if (try self.graphErrorIsExactUnitTag(payloads.err, "Missing") or
                    try self.graphErrorIsExactUnitTag(payloads.err, "Null"))
                {
                    try pending.append(self.allocator, .{ .node = payloads.ok });
                }
                continue;
            }

            switch ((try self.graph.content(node))) {
                .list, .box => |payload| try pending.append(self.allocator, .{ .node = payload }),
                .tuple => return true,
                .record => try pending.append(self.allocator, .{ .fields = .{ .fields = (try self.graph.recordNodes(node)).fields, .next = 0 } }),
                .tag_union => try pending.append(self.allocator, .{ .payloads = .{ .tags = (try self.graph.tagRowNodes(node)).tags, .tag = 0, .payload = 0 } }),
                .named => |named| {
                    if (named.builtin_owner == .set and named.args.len == 1) {
                        try pending.append(self.allocator, .{ .node = named.args[0] });
                    } else if (named.builtin_owner == .dict and named.args.len == 2) {
                        if ((try self.graphScalarCodecMethodName(named.args[0], "parse_key_")) != null) {
                            // A builtin scalar key is decoded directly by its
                            // exact `parse_key_*` method.
                            try pending.append(self.allocator, .{ .node = named.args[1] });
                        } else if ((try self.graphNodeIsStringRenderedDictKey(named.args[0]))) {
                            if (try self.graphNodeIsUnitTagUnion(named.args[0])) return true;
                            try pending.append(self.allocator, .{ .node = named.args[1] });
                        } else {
                            try pending.append(self.allocator, .{ .node = named.args[1] });
                            try pending.append(self.allocator, .{ .node = named.args[0] });
                        }
                    } else if (named.backing) |backing| {
                        try pending.append(self.allocator, .{ .node = backing.node });
                    }
                },
                .redirect, .leaf => unreachable,
                .unresolved,
                .primitive,
                .empty_tag_union,
                .empty_record,
                .func,
                .erased,
                .zst,
                => {},
            }
        }
        return false;
    }

    fn graphNodeIsUnitTagUnion(self: *BodyContext, raw_node: NodeId) Allocator.Error!bool {
        const node = (try self.graphShapeNode(raw_node));
        switch ((try self.graph.content(node))) {
            .tag_union, .named => {},
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_tag_union, .empty_record, .erased, .zst => return false,
        }
        if (!try self.graph.tagRowIsClosed(node)) return false;
        const tags = (try self.graph.tagRowNodes(node)).tags;
        if (tags.len == 0) return false;
        for (tags) |tag| {
            if (tag.payloads.len != 0) return false;
        }
        return true;
    }

    fn prepareCustomCodecCallsAtNode(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        kind: CodecKind,
        raw_shape_node: NodeId,
        boundary_callable_node: NodeId,
        seen: *collections.DenseMap(NodeId, void),
    ) Allocator.Error!bool {
        const shape_node = raw_shape_node;
        const seen_entry = try seen.getOrPut(shape_node);
        if (seen_entry.found_existing) return false;

        if ((try self.generatedCodecBoundaryCall(kind, shape_node))) |codec_call| {
            switch (codec_call.resolution) {
                .callable => return try self.prepareCustomCodecCall(
                    boundary_expr,
                    kind,
                    shape_node,
                    boundary_callable_node,
                    codec_call,
                ),
                .structural => {
                    const previous_contract = self.active_codec_contract;
                    const previous_call_count = self.instantiated_codec_calls.items.len;
                    defer {
                        self.active_codec_contract = previous_contract;
                        self.instantiated_codec_calls.shrinkRetainingCapacity(previous_call_count);
                    }
                    self.active_codec_contract = try self.activateNestedCodecContract(codec_call, shape_node);
                    return try self.prepareStructuralCodecCallsAtNode(
                        boundary_expr,
                        kind,
                        shape_node,
                        codec_call.callable_node,
                    );
                },
            }
        }

        if (kind == .parser) {
            if ((try self.graphScalarCodecMethodName(shape_node, "parse_"))) |method_name| {
                return try self.prepareParseScalarCodecCall(
                    boundary_expr,
                    shape_node,
                    boundary_callable_node,
                    method_name,
                );
            }
        } else if ((try self.graphScalarCodecMethodName(shape_node, "encode_"))) |method_name| {
            return try self.prepareEncodeScalarCodecCall(
                boundary_expr,
                shape_node,
                boundary_callable_node,
                method_name,
            );
        }

        // A nominal opaque with a scalar backing (e.g. `Username := Str`) prepares the codec for
        // its backing scalar; the encoder/parser reaches it after unwrapping the nominal.
        switch ((try self.graph.content(shape_node))) {
            .named => |named| if (named.backing) |backing| {
                const backing_is_scalar = if (kind == .parser)
                    (try self.graphScalarCodecMethodName(backing.node, "parse_")) != null
                else
                    (try self.graphScalarCodecMethodName(backing.node, "encode_")) != null;
                if (backing_is_scalar) {
                    return try self.prepareCustomCodecCallsAtNode(boundary_expr, kind, backing.node, boundary_callable_node, seen);
                }
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => {},
        }

        if ((try self.graphNodeIsBuiltinTry(shape_node))) {
            const payloads = try self.graphTryPayloads(shape_node);
            var added = false;
            if (try self.graphErrorIsExactUnitTag(payloads.err, "Null")) {
                added = switch (kind) {
                    .parser => try self.prepareParseFormatControlCodecCall(
                        boundary_expr,
                        shape_node,
                        null,
                        boundary_callable_node,
                        "parse_null",
                        true,
                    ),
                    .encoder => try self.prepareEncodeNullCodecCall(
                        boundary_expr,
                        shape_node,
                        boundary_callable_node,
                    ),
                };
            }
            return try self.prepareCustomCodecCallsAtNode(
                boundary_expr,
                kind,
                payloads.ok,
                boundary_callable_node,
                seen,
            ) or added;
        }

        switch ((try self.graph.content(shape_node))) {
            .named => |named| if (named.builtin_owner) |owner| switch (owner) {
                .set => {
                    if (named.args.len != 1) Common.invariant("builtin Set graph node had an unexpected arity");
                    const list_node = try self.graph.newNode(.{ .list = named.args[0] });
                    var added = if (kind == .parser)
                        try self.prepareParseListFormatCodecCalls(boundary_expr, list_node, shape_node, boundary_callable_node)
                    else
                        try self.prepareEncodeContainerCodecCall(boundary_expr, list_node, shape_node, boundary_callable_node, "encode_list");
                    added = try self.prepareSetCollectionCodecCall(
                        boundary_expr,
                        kind,
                        shape_node,
                        named.args[0],
                    ) or added;
                    added = try self.prepareCustomCodecCallsAtNode(boundary_expr, kind, named.args[0], boundary_callable_node, seen) or added;
                    return added;
                },
                .dict => {
                    if (named.args.len != 2) Common.invariant("builtin Dict graph node had an unexpected arity");
                    var added = if (kind == .parser)
                        try self.prepareParseDictFormatCodecCalls(boundary_expr, shape_node, shape_node, boundary_callable_node)
                    else
                        try self.prepareEncodeContainerCodecCall(boundary_expr, shape_node, shape_node, boundary_callable_node, "encode_dict");
                    added = try self.prepareDictKeyCodecCalls(
                        boundary_expr,
                        kind,
                        named.args[0],
                        boundary_callable_node,
                        seen,
                    ) or added;
                    added = try self.prepareDictCollectionCodecCalls(
                        boundary_expr,
                        kind,
                        shape_node,
                        named.args[0],
                        named.args[1],
                    ) or added;
                    added = try self.prepareCustomCodecCallsAtNode(boundary_expr, kind, named.args[1], boundary_callable_node, seen) or added;
                    return added;
                },
                .list, .box, .fields, .field, .bool, .str, .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, .parse_tag_union_spec, .crypto_sha256_digest, .crypto_sha256_hasher, .crypto_blake3_digest, .crypto_blake3_hasher, .iter, .stream => {},
            },
            .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => {},
        }

        // A dict's and a set's own backings are private representation that no
        // codec reads. Walking into one prepares calls over internals that are
        // never parsed or encoded, so the walk uses the element shape the codec
        // actually reaches instead.
        var container_buf: [2]NodeId = undefined;
        const container_shapes = (try self.graphBuiltinContainerShapeNodes(shape_node, &container_buf));
        if (container_shapes.len != 0) {
            var container_added = false;
            for (container_shapes) |container_shape| {
                container_added = try self.prepareCustomCodecCallsAtNode(
                    boundary_expr,
                    kind,
                    container_shape,
                    boundary_callable_node,
                    seen,
                ) or container_added;
            }
            return container_added;
        }

        var added = false;
        const structural_node = (try self.graphShapeNode(shape_node));
        const contract_subject_node = try self.codecContractSubjectNode(shape_node, structural_node);
        switch ((try self.graph.content(structural_node))) {
            .list => |elem| {
                if (kind == .parser) {
                    added = try self.prepareParseListFormatCodecCalls(
                        boundary_expr,
                        shape_node,
                        contract_subject_node,
                        boundary_callable_node,
                    ) or added;
                } else {
                    added = try self.prepareEncodeContainerCodecCall(
                        boundary_expr,
                        shape_node,
                        contract_subject_node,
                        boundary_callable_node,
                        "encode_list",
                    ) or added;
                }
                added = try self.prepareCustomCodecCallsAtNode(boundary_expr, kind, elem, boundary_callable_node, seen) or added;
            },
            .box => |elem| added = try self.prepareCustomCodecCallsAtNode(boundary_expr, kind, elem, boundary_callable_node, seen) or added,
            .tuple => |items| {
                if (kind == .parser) {
                    added = try self.prepareParseTupleFormatCodecCalls(
                        boundary_expr,
                        shape_node,
                        contract_subject_node,
                        boundary_callable_node,
                    ) or added;
                } else {
                    added = try self.prepareEncodeContainerCodecCall(
                        boundary_expr,
                        shape_node,
                        contract_subject_node,
                        boundary_callable_node,
                        "encode_tuple",
                    ) or added;
                }
                for (items) |item| {
                    added = try self.prepareCustomCodecCallsAtNode(boundary_expr, kind, item, boundary_callable_node, seen) or added;
                }
            },
            .record, .zst, .empty_record => {
                const fields = switch ((try self.graph.content(structural_node))) {
                    .record => (try self.graph.recordNodes(structural_node)).fields,
                    .zst, .empty_record => &.{},
                    .redirect, .leaf, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .named, .empty_tag_union, .erased => Common.invariant("record codec preparation reached a non-record shape"),
                };
                if (kind == .encoder) {
                    added = try self.prepareEncodeContainerCodecCall(
                        boundary_expr,
                        shape_node,
                        contract_subject_node,
                        boundary_callable_node,
                        "encode_record",
                    ) or added;
                }
                if (kind == .parser) {
                    if (fields.len != 0) {
                        added = try self.prepareRenameRecordFieldCodecCall(
                            boundary_expr,
                            kind,
                            shape_node,
                            boundary_callable_node,
                        ) or added;
                    }
                    added = try self.prepareSkipRecordFieldCodecCall(
                        boundary_expr,
                        shape_node,
                        boundary_callable_node,
                    ) or added;
                    added = try self.prepareParseRecordFieldCodecCall(
                        boundary_expr,
                        shape_node,
                        contract_subject_node,
                        boundary_callable_node,
                    ) or added;
                    added = try self.prepareParseFormatControlCodecCall(
                        boundary_expr,
                        shape_node,
                        contract_subject_node,
                        boundary_callable_node,
                        "parse_record_start",
                        false,
                    ) or added;
                    added = try self.prepareParseFormatControlCodecCall(
                        boundary_expr,
                        shape_node,
                        contract_subject_node,
                        boundary_callable_node,
                        "parse_record_after_field",
                        false,
                    ) or added;
                } else if (fields.len != 0) {
                    added = try self.prepareRenameRecordFieldCodecCall(
                        boundary_expr,
                        kind,
                        shape_node,
                        boundary_callable_node,
                    ) or added;
                }
                for (fields) |field| {
                    if (kind == .parser) {
                        if (field.default) |default| {
                            added = try self.prepareDefaultedFieldValue(boundary_expr, default, field.ty) or added;
                        }
                    }
                    added = try self.prepareCustomCodecCallsAtNode(
                        boundary_expr,
                        kind,
                        self.graph.codecFieldValueNode(field),
                        boundary_callable_node,
                        seen,
                    ) or added;
                }
            },
            .tag_union => {
                if (kind == .encoder) {
                    added = try self.prepareEncodeContainerCodecCall(
                        boundary_expr,
                        shape_node,
                        contract_subject_node,
                        boundary_callable_node,
                        "encode_tag",
                    ) or added;
                }
                if (kind == .parser) {
                    added = try self.prepareParseTagUnionCodecCall(
                        boundary_expr,
                        shape_node,
                        contract_subject_node,
                        boundary_callable_node,
                    ) or added;
                }
                for ((try self.graph.tagRowNodes(structural_node)).tags) |tag| {
                    for (tag.payloads) |payload|
                        added = try self.prepareCustomCodecCallsAtNode(boundary_expr, kind, payload, boundary_callable_node, seen) or added;
                }
            },
            .named => {},
            .redirect, .leaf => unreachable,
            .unresolved, .primitive, .empty_tag_union, .func, .erased => {},
        }
        return added;
    }

    fn tryNullInfo(self: *BodyContext, ty: Type.TypeId) ?TryNullInfo {
        const backing_ty = self.namedBackingType(ty) orelse return null;
        const ok_tag = self.monoTagByTextOptional(backing_ty, "Ok") orelse return null;
        const err_tag = self.monoTagByTextOptional(backing_ty, "Err") orelse return null;
        const ok_payloads = self.typeStore().span(ok_tag.payloads);
        const err_payloads = self.typeStore().span(err_tag.payloads);
        if (ok_payloads.len != 1 or err_payloads.len != 1) return null;
        const err_ty = GuardedList.at(err_payloads, 0);
        if (!self.typeIsExactUnitTagUnion(err_ty, "Null")) return null;
        return .{
            .backing_ty = backing_ty,
            .ok_payload_ty = GuardedList.at(ok_payloads, 0),
            .err_ty = err_ty,
        };
    }

    fn tagUnionValueWithoutPayload(self: *BodyContext, ty: Type.TypeId, tag_text: []const u8) Allocator.Error!DraftExprId {
        const tag = self.monoTagByText(ty, tag_text);
        if (self.typeStore().span(tag.payloads).len != 0) Common.invariant("JSON Try marker tag unexpectedly had payloads");
        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .tag = .{
                .name = tag.name,
                .payloads = .empty(),
            } },
        });
    }

    fn typeIsExactUnitTagUnion(self: *BodyContext, ty: Type.TypeId, tag_text: []const u8) bool {
        const tags = switch (self.shapeContent(ty)) {
            .tag_union => |span| self.typeStore().tagSpan(span),
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => return false,
        };
        if (tags.len != 1) return false;
        const tag = GuardedList.at(tags, 0);
        if (self.typeStore().span(tag.payloads).len != 0) return false;
        return Ident.textEql(self.nameStore().tagLabelText(tag.name), tag_text);
    }

    fn finishOptionalRecordFieldFromPresencePayload(
        self: *BodyContext,
        next_body: DraftExprId,
        ret_ty: Type.TypeId,
        record_slots: ParseRecordSlots,
        field: Type.Field,
        field_index: usize,
        field_local: DraftLocalId,
    ) Allocator.Error!DraftExprId {
        const field_ty = field.ty;
        const maybe_try_info = try self.missingTryInfo(field_ty);
        if (maybe_try_info == null and self.optionalFieldSlot(field_ty) == null) {
            Common.invariant("optional record finish requested for a field that is neither Try-optional nor a `?:` slot");
        }
        const payload_local = record_slots.payload_locals[field_index];
        const payload_ty = record_slots.payload_tys[field_index];
        if (!self.sameType(payload_ty, field_ty)) {
            Common.invariant("generated optional record payload type differed from field type");
        }
        if (!self.sameType(try self.localType(field_local), field_ty)) {
            Common.invariant("record finish field local type differed from optional field type");
        }

        const missing_field = if (maybe_try_info) |optional_info|
            try self.tryErr(field_ty, try self.tagUnionValueWithoutPayload(optional_info.err_ty, "Missing"))
        else
            // An absent `?:` field materializes the slot's `#Missing` tag
            // (design.md "Field Kinds (All-Dynamic Optional Fields)").
            try self.optionalSlotMissingExpr(field_ty);
        const present_field = try self.localExpr(payload_local, payload_ty);
        const presence_word = recordPresenceWordIndex(field_index);
        const is_present_expr = try self.localExpr(record_slots.presence_locals[presence_word], record_slots.presence_tys[presence_word]);
        const field_value = try self.addExpr(.{ .ty = field_ty, .data = .{ .if_initialized_payload = .{
            .cond = is_present_expr,
            .cond_mask = recordPresenceMask(field_index),
            .payload = payload_local,
            .uninitialized_is_cold = false,
            .initialized = present_field,
            .uninitialized = missing_field,
        } } });
        return try self.wrapLet(field_local, field_ty, field_value, next_body, ret_ty);
    }

    /// The `??`-defaulted sibling of
    /// `finishOptionalRecordFieldFromPresencePayload`: an absent key
    /// materializes the field's archived default constant into the inline
    /// slot—exactly the construction-site omission behavior `{}`
    /// literals get (design.md "Defaulted Fields"). A present key already parsed at
    /// the field's inline type into the payload slot.
    fn finishDefaultedRecordFieldFromPresencePayload(
        self: *BodyContext,
        next_body: DraftExprId,
        ret_ty: Type.TypeId,
        record_slots: ParseRecordSlots,
        field: Type.Field,
        field_index: usize,
        field_local: DraftLocalId,
        default: Type.FieldDefault,
    ) Allocator.Error!DraftExprId {
        const field_ty = field.ty;
        const payload_local = record_slots.payload_locals[field_index];
        const payload_ty = record_slots.payload_tys[field_index];
        if (!self.sameType(payload_ty, field_ty)) {
            Common.invariant("generated defaulted record payload type differed from field type");
        }
        if (!self.sameType(try self.localType(field_local), field_ty)) {
            Common.invariant("record finish field local type differed from defaulted field type");
        }

        // Materializing a default lowers a checked expression, which is
        // relation production. Phase-B (frozen) emission therefore consumes
        // the value prepared while the graph still accepted relations;
        // Phase-A generation lowers it directly.
        const default_field = if (self.frozen_sealed_emission) blk: {
            const prepared = self.frozen_field_defaults orelse
                Common.invariant("frozen parser emission had no prepared field-default table");
            break :blk prepared.take(default, field_ty) orelse
                Common.invariant("frozen parser emission demanded an unprepared defaulted-field value");
        } else (try self.defaultedFieldValueFromMonoDefault(default, field_ty)) orelse
            Common.invariant("defaulted record parse finish had no archived default to materialize");
        const present_field = try self.localExpr(payload_local, payload_ty);
        const presence_word = recordPresenceWordIndex(field_index);
        const is_present_expr = try self.localExpr(record_slots.presence_locals[presence_word], record_slots.presence_tys[presence_word]);
        const field_value = try self.addExpr(.{ .ty = field_ty, .data = .{ .if_initialized_payload = .{
            .cond = is_present_expr,
            .cond_mask = recordPresenceMask(field_index),
            .payload = payload_local,
            .uninitialized_is_cold = false,
            .initialized = present_field,
            .uninitialized = default_field,
        } } });
        return try self.wrapLet(field_local, field_ty, field_value, next_body, ret_ty);
    }

    fn missingRequiredFieldError(
        self: *BodyContext,
        field_name_expr: DraftExprId,
        err_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const str_ty = try self.primitiveType(.str);
        if (!self.sameType(try self.exprType(field_name_expr), str_ty)) {
            Common.invariant("generated missing required field name was not Str");
        }
        // The checker adds `MissingRequiredField(Str)` to the error row of every
        // derived parser that owns a required field, so the checked row always
        // carries it here.
        const missing_tag = self.monoTagByTextOptional(err_ty, "MissingRequiredField") orelse
            Common.invariant("derived parser with a required field had no MissingRequiredField in its checked error row");
        const payload_tys = self.typeStore().span(missing_tag.payloads);
        if (payload_tys.len != 1 or !self.sameType(GuardedList.at(payload_tys, 0), str_ty)) {
            Common.invariant("MissingRequiredField in parser error row did not carry one Str payload");
        }
        return try self.addExpr(.{
            .ty = err_ty,
            .data = .{ .tag = .{
                .name = missing_tag.name,
                .payloads = try self.addExprSpan(&[_]DraftExprId{field_name_expr}),
            } },
        });
    }

    fn invalidValueError(
        self: *BodyContext,
        encoding_expr: DraftExprId,
        state_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        err_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const prepared = try self.frozenFormatCodecCall(.parser, "invalid_value");
        const lookup = prepared.lookup;
        const callable_mono_ty = prepared.callable_ty;
        const invalid_fn = self.functionShape(callable_mono_ty, "invalid_value target method was not a function");
        const arg_tys = self.typeStore().span(invalid_fn.args);
        if (arg_tys.len != 2) Common.invariant("invalid_value target method had an unexpected arity");
        if (!self.sameType(GuardedList.at(arg_tys, 0), encoding_ty)) Common.invariant("invalid_value encoding type differed from parser encoding type");
        if (!self.sameType(GuardedList.at(arg_tys, 1), state_ty)) Common.invariant("invalid_value state type differed from parser state type");
        if (!self.sameType(invalid_fn.ret, err_ty)) Common.invariant("invalid_value return type differed from parse error type");

        return try self.addExpr(.{
            .ty = err_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(prepared.callee),
                .args = try self.addExprSpan(&[_]DraftExprId{ encoding_expr, state_expr }),
                .captures = try self.methodTargetCaptureSpan(lookup),
                .is_cold = true,
            } },
        });
    }

    fn stepDirectStructural(self: *BodyContext, task: *DirectStructuralTask, input: ?LowerResult) Allocator.Error!LowerStep {
        const data = self.view.bodies.expr(task.expr).data;
        switch (task.stage) {
            .start => {
                task.ret_ty = switch (task.ret) {
                    .context => |ty| ty,
                    .checked => |checked_ret_ty| try self.lowerTypeView(checked_ret_ty),
                };
                switch (data) {
                    .structural_eq => |eq| {
                        switch (try self.structuralEqualityOperandType(eq)) {
                            .sealed => |operand_ty| task.operand_ty = operand_ty,
                            .deferred => |operand_node| task.operand_node = operand_node,
                        }
                        if (eq.discriminant) |discriminant| {
                            task.stage = .discriminant;
                            return requestLowerChild(self, discriminant.value, self.directStructuralOperandCell(task));
                        }
                        task.stage = .lhs;
                        return requestLowerChild(self, eq.lhs, self.directStructuralOperandCell(task));
                    },
                    .structural_hash => |h| {
                        switch (try self.structuralHashOperandType(h)) {
                            .sealed => |operand_ty| task.operand_ty = operand_ty,
                            .deferred => |operand_node| task.operand_node = operand_node,
                        }
                        task.stage = .hash_value;
                        return requestLowerChild(self, h.value, self.directStructuralOperandCell(task));
                    },
                    .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("direct structural task reached a non-structural expression"),
                }
            },
            .discriminant => {
                const eq = data.structural_eq;
                const discriminant = eq.discriminant.?;
                const value = input.?.exprValue();
                if (task.operand_ty) |operand_ty| {
                    return try self.finishDirectStructural(task, try self.lowerEqualityAgainstTag(
                        value,
                        operand_ty,
                        try self.tagName(self.view, discriminant.tag),
                        eq.negated,
                        task.ret_ty,
                    ));
                }
                return try self.finishDirectStructural(task, try self.deferStructuralDerivationOperandsAtNode(
                    task.ret_ty,
                    task.operand_node,
                    value,
                    value,
                    .{ .tag_discriminant = .{
                        .value = value,
                        .tag = try self.tagName(self.view, discriminant.tag),
                        .negated = eq.negated,
                    } },
                ));
            },
            .lhs => {
                task.lhs = input.?.exprValue();
                task.stage = .rhs;
                return requestLowerChild(self, data.structural_eq.rhs, self.directStructuralOperandCell(task));
            },
            .rhs => {
                const eq = data.structural_eq;
                const rhs = input.?.exprValue();
                if (task.operand_ty) |operand_ty| {
                    return try self.finishDirectStructural(task, try self.lowerStructuralEqFromOperands(operand_ty, task.lhs, rhs, eq.negated, task.ret_ty));
                }
                return try self.finishDirectStructural(task, try self.deferStructuralDerivationOperandsAtNode(
                    task.ret_ty,
                    task.operand_node,
                    task.lhs,
                    rhs,
                    .{ .equality = .{ .negated = eq.negated } },
                ));
            },
            .hash_value => {
                task.lhs = input.?.exprValue();
                task.stage = .hash_hasher;
                return requestLowerChild(self, data.structural_hash.hasher, .{ .sealed = task.ret_ty });
            },
            .hash_hasher => {
                const hasher = input.?.exprValue();
                if (task.operand_ty) |operand_ty| {
                    return try self.finishDirectStructural(task, try self.lowerHashExpr(operand_ty, task.lhs, hasher, task.ret_ty));
                }
                return try self.finishDirectStructural(task, try self.deferStructuralDerivationOperandsAtNode(
                    task.ret_ty,
                    task.operand_node,
                    task.lhs,
                    hasher,
                    .hash,
                ));
            },
        }
    }

    fn directStructuralOperandCell(_: *BodyContext, task: *const DirectStructuralTask) DraftTypeCell {
        if (task.operand_ty) |operand_ty| return .{ .sealed = operand_ty };
        return DraftTypeCell.fromGraphNode(task.operand_node);
    }

    fn finishDirectStructural(self: *BodyContext, task: *const DirectStructuralTask, lowered: DraftExprId) Allocator.Error!LowerStep {
        switch (task.ret) {
            .context => |ty| if (!self.sameType(ty, try self.exprType(lowered))) switch (task.stage) {
                .hash_hasher => Common.invariant("checked structural hash lowered at a type different from its context type"),
                .start, .discriminant, .lhs, .rhs, .hash_value => Common.invariant("checked structural equality lowered at a type different from its context type"),
            },
            .checked => {},
        }
        return loweredExprStep(lowered);
    }

    fn lowerStructuralEqFromOperands(
        self: *BodyContext,
        operand_ty: Type.TypeId,
        lhs: DraftExprId,
        rhs: DraftExprId,
        negated: bool,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        var result = try self.lowerEqualityExpr(operand_ty, lhs, rhs, Ident.IS_EQ_METHOD_NAME, ret_ty);
        if (negated) {
            result = try self.lowLevelExpr(.bool_not, &.{result}, ret_ty);
        }
        return result;
    }

    fn lowerEqualityAgainstTag(
        self: *BodyContext,
        value: DraftExprId,
        value_ty: Type.TypeId,
        tag_name: names.TagNameId,
        negated: bool,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const tag_pat = try self.addPat(.{ .ty = value_ty, .data = .{ .tag = .{
            .name = tag_name,
            .payloads = .empty(),
        } } });
        const other_pat = try self.addPat(.{ .ty = value_ty, .data = .wildcard });
        const branches = [_]DraftBranch{
            .{ .pat = tag_pat, .body = try self.boolLiteral(!negated, ret_ty) },
            .{ .pat = other_pat, .body = try self.boolLiteral(negated, ret_ty) },
        };
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = value,
            .branches = try self.addBranchSpan(&branches),
        } } });
    }

    const StructuralDerivationOperand = union(enum) {
        sealed: Type.TypeId,
        deferred: NodeId,
    };

    fn structuralEqualityOperandType(self: *BodyContext, eq: anytype) Allocator.Error!StructuralDerivationOperand {
        const lhs_checked_ty = self.view.bodies.expr(eq.lhs).ty;
        const rhs_checked_ty = self.view.bodies.expr(eq.rhs).ty;

        try self.constrainCheckedTypeRelations(lhs_checked_ty, self, rhs_checked_ty);

        if (try self.structuralDerivationExprResultNode(eq.lhs)) |lhs_node| {
            return try self.constrainStructuralEqualityOperandNode(lhs_node, eq.rhs, rhs_checked_ty);
        }
        if (try self.structuralDerivationExprResultNode(eq.rhs)) |rhs_node| {
            return try self.constrainStructuralEqualityOperandNode(rhs_node, eq.lhs, lhs_checked_ty);
        }

        const operand_node = try self.instNode(lhs_checked_ty);
        return try self.structuralDerivationOperandFromNode(operand_node);
    }

    /// The hashed value's node may still carry live row defaults (a tag
    /// union built from tag constructors, for example), so it resolves to a
    /// sealed type only when the graph already resolved it and otherwise
    /// defers the derivation to final graph sealing.
    fn structuralHashOperandType(self: *BodyContext, h: anytype) Allocator.Error!StructuralDerivationOperand {
        const value_node = (try self.structuralDerivationExprResultNode(h.value)) orelse
            try self.instNode(self.view.bodies.expr(h.value).ty);
        return try self.structuralDerivationOperandFromNode(value_node);
    }

    fn deferStructuralEqOperandsAtNode(
        self: *BodyContext,
        ret_ty: Type.TypeId,
        operand_node: NodeId,
        lhs: DraftExprId,
        rhs: DraftExprId,
        negated: bool,
    ) Allocator.Error!DraftExprId {
        return try self.deferStructuralDerivationOperandsAtNode(
            ret_ty,
            operand_node,
            lhs,
            rhs,
            .{ .equality = .{ .negated = negated } },
        );
    }

    fn deferStructuralDerivationOperandsAtNode(
        self: *BodyContext,
        ret_ty: Type.TypeId,
        operand_node: NodeId,
        lhs: DraftExprId,
        rhs: DraftExprId,
        mode: DraftStructuralDerivationMode,
    ) Allocator.Error!DraftExprId {
        const expr = try self.addExprWithTypeCell(.{ .sealed = ret_ty }, .pending_deferred);
        self.draft.expr_impossibility_proofs.items[@backingInt(expr)] = try self.anyImpossibilityProof(&.{
            self.exprImpossibilityProof(lhs),
            self.exprImpossibilityProof(rhs),
        });
        const lexical = try self.captureCodecLexicalContext();
        errdefer {
            self.allocator.free(lexical.binders);
            self.allocator.free(lexical.local_procs);
        }
        try self.draft.deferred_structural_eqs.append(self.allocator, .{
            .view = self.view,
            .method_scope = self.method_scope,
            .owner_template = self.owner_template,
            .owner = self.draft.current_owner,
            .expr = expr,
            .operand_node = operand_node,
            .ret_ty = ret_ty,
            .lhs = lhs,
            .rhs = rhs,
            .mode = mode,
            .evidence = self.evidence,
            .current_fn_key = self.current_fn_key,
            .lexical = lexical,
        });
        return expr;
    }

    /// Resolves the graph node a structural derivation operand evaluates to, when that
    /// operand is a result-producing expression (call, dispatch, lookup, field access).
    /// For equality, the shared operand node is taken from this result so an open tag
    /// literal on the other side cannot narrow it. Returns null for any other expression
    /// shape (e.g. a tag literal): the caller then instantiates the operand's checked type
    /// instead, so this must not materialize a Monotype view.
    fn structuralDerivationExprResultNode(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
    ) Allocator.Error!?NodeId {
        if (self.checkedExprDivergesInLoweredRuntime(expr_id)) return null;
        const expr = self.view.bodies.expr(expr_id);
        return switch (expr.data) {
            .call => |call| try self.callResultTypeNode(expr_id, expr.ty, call, null),
            .dispatch_call => |plan| try self.dispatchResultTypeNode(expr.ty, plan, null),
            .interpolation => |interpolation| try self.interpolationResultTypeNode(interpolation.plan, null),
            .type_dispatch_call, .method_eq => |plan| try self.dispatchResultTypeNode(expr.ty, plan, null),
            .lookup_local => |lookup| try self.lookupExprTypeNode(expr.ty, lookup.resolved),
            .lookup_external, .lookup_required => |resolved| try self.lookupExprTypeNode(expr.ty, resolved),
            .field_access => |field| try self.fieldAccessTypeNode(expr.ty, field, null),
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .list, .empty_list, .tuple, .match_, .if_, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .structural_eq, .structural_hash, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => null,
        };
    }

    fn constrainStructuralEqualityOperandNode(
        self: *BodyContext,
        operand_node: NodeId,
        other_expr_id: checked.CheckedExprId,
        other_checked_ty: checked.CheckedTypeId,
    ) Allocator.Error!StructuralDerivationOperand {
        try self.graph.unify(operand_node, try self.instNode(other_checked_ty));
        if (try self.structuralDerivationExprResultNode(other_expr_id)) |other_node| {
            try self.graph.unify(operand_node, other_node);
        }
        return try self.structuralDerivationOperandFromNode(operand_node);
    }

    fn structuralDerivationOperandFromNode(
        self: *BodyContext,
        operand_node: NodeId,
    ) Allocator.Error!StructuralDerivationOperand {
        if (try self.graph.typeIsResolved(operand_node)) {
            return .{ .sealed = try self.activeTypeFromNode(operand_node) };
        }
        return .{ .deferred = operand_node };
    }

    fn structuralDerivationMethodName(mode: DraftStructuralDerivationMode) []const u8 {
        return switch (mode) {
            .equality => Ident.IS_EQ_METHOD_NAME,
            .tag_discriminant => Common.invariant("tag-discriminant equality requested a structural method name"),
            .hash => Ident.TO_HASH_METHOD_NAME,
        };
    }

    /// Prepare the component method calls a structural derivation at
    /// `root` makes, visiting its components depth first in source order,
    /// each node once.
    fn prepareStructuralEqNode(
        self: *BodyContext,
        boundary_index: usize,
        mode: DraftStructuralDerivationMode,
        root: NodeId,
        result_ty: Type.TypeId,
        seen: *collections.DenseMap(NodeId, void),
        added_method_call: *bool,
    ) Allocator.Error!void {
        var pending = std.ArrayList(NodeId).empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, root);
        while (pending.pop()) |raw_node| {
            const entry = try seen.getOrPut(raw_node);
            if (entry.found_existing) continue;

            const children_start = pending.items.len;
            switch ((try self.graph.content(raw_node))) {
                .list => {
                    const lookup = try self.withLocalProcContext(try self.builtinListDerivationLookup(structuralDerivationMethodName(mode)));
                    if (lookup.target.kind == .structural) {
                        Common.invariant("owned List derivation resolved to a structural registry implementation");
                    }
                    try self.prepareStructuralEqMethodCall(
                        boundary_index,
                        mode,
                        raw_node,
                        result_ty,
                        lookup,
                        added_method_call,
                    );
                },
                .tuple => try pending.appendSlice(self.allocator, try self.graph.tupleItemNodes(raw_node)),
                .record => {
                    for ((try self.graph.recordNodes(raw_node)).fields) |field| try pending.append(self.allocator, field.ty);
                },
                .tag_union => {
                    for ((try self.graph.tagRowNodes(raw_node)).tags) |tag| try pending.appendSlice(self.allocator, tag.payloads);
                },
                .named => named: {
                    const named = (try self.graph.namedNodes(raw_node));
                    if ((try self.methodOwnerFromNode(raw_node))) |owner| {
                        if (try self.lookupMethodTargetByName(owner, structuralDerivationMethodName(mode))) |result| {
                            // A rejected declaration is this component's
                            // comparison; emission lowers it to a checked error
                            // without calling anything or expanding the backing.
                            const raw_lookup = switch (result) {
                                .rejected => break :named,
                                .target => |raw_lookup| raw_lookup,
                            };
                            const lookup = try self.withLocalProcContext(raw_lookup);
                            switch (lookup.target.kind) {
                                .structural => |kind| {
                                    const expected: static_dispatch.StructuralKind = switch (mode) {
                                        .equality => .equality,
                                        .tag_discriminant => Common.invariant("tag-discriminant equality requested structural evidence"),
                                        .hash => .hash,
                                    };
                                    if (kind != expected) {
                                        Common.invariant("named structural derivation resolved to a different structural registry implementation");
                                    }
                                },
                                .procedure, .local_proc => {
                                    try self.prepareStructuralEqMethodCall(
                                        boundary_index,
                                        mode,
                                        raw_node,
                                        result_ty,
                                        lookup,
                                        added_method_call,
                                    );
                                    break :named;
                                },
                            }
                        }
                    }
                    if (named.backing) |backing| try pending.append(self.allocator, backing.node);
                },
                .redirect, .leaf => unreachable,
                .unresolved,
                .primitive,
                .empty_tag_union,
                .empty_record,
                .func,
                .box,
                .erased,
                .zst,
                => {},
            }
            std.mem.reverse(NodeId, pending.items[children_start..]);
        }
    }

    fn prepareStructuralEqMethodCall(
        self: *BodyContext,
        boundary_index: usize,
        mode: DraftStructuralDerivationMode,
        node: NodeId,
        result_ty: Type.TypeId,
        lookup: MethodLookup,
        added_method_call: *bool,
    ) Allocator.Error!void {
        for (self.draft.structural_eq_method_calls.items) |planned| {
            if (planned.boundary != boundary_index) continue;
            if (self.graph.sameClass(planned.node, node)) return;
        }
        const ret_node = try self.graph.importMono(result_ty);
        const callable_node = switch (mode) {
            .equality => try self.graphFunctionNode(&.{ node, node }, ret_node),
            .tag_discriminant => Common.invariant("tag-discriminant equality requested a structural method call"),
            .hash => try self.graphFunctionNode(&.{ node, ret_node }, ret_node),
        };
        const callee = try self.methodTargetCalleeAtNode(lookup, callable_node, null);
        try self.draft.structural_eq_method_calls.append(self.allocator, .{
            .boundary = @intCast(boundary_index),
            .node = node,
            .callee = callee,
        });
        added_method_call.* = true;
    }

    /// Whether `shape` is a type the structural-derivation ladders (is_eq /
    /// to_hash) expand a layer at a time, guarding recursion through an
    /// expansion stack. Aggregates and transparent nominals expand; scalars,
    /// owned wrappers (List/Box), and opaque nominals bottom out instead.
    fn structurallyExpands(shape: Type.Content) bool {
        return switch (shape) {
            .record, .tuple, .tag_union => true,
            .named => |named| named.backing != null,
            .primitive, .list, .box, .func, .erased, .zst => false,
        };
    }

    fn lowerEqualityExpr(
        self: *BodyContext,
        ty: Type.TypeId,
        lhs: DraftExprId,
        rhs: DraftExprId,
        method_name: []const u8,
        bool_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.lowerDerivation(EqDeriver, ty, .{ .lhs = lhs, .rhs = rhs }, .{
            .method_name = method_name,
            .result_ty = bool_ty,
        });
    }

    /// Hash `value` (of `value_ty`) into `hasher`, producing a new Hasher of
    /// `hasher_ty`. The threading is "innermost first": each component feeds the
    /// hasher accumulated so far.
    fn lowerHashExpr(
        self: *BodyContext,
        value_ty: Type.TypeId,
        value: DraftExprId,
        hasher: DraftExprId,
        hasher_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.lowerDerivation(HashDeriver, value_ty, .{ .value = value, .hasher = hasher }, .{
            .method_name = Ident.TO_HASH_METHOD_NAME,
            .result_ty = hasher_ty,
        });
    }

    // Generic structural-derivation driver.
    //
    // is_eq and to_hash share one ladder: walk a type one layer at a time on
    // an explicit frame stack, decomposing aggregates (records/tuples/tag unions) and transparent
    // nominals that have no exact component method. A List or named component
    // with an exact method dispatches to that method before its representation
    // can be inspected. Scalars, opaque nominals, and other inline-handled
    // leaves emit a leaf node (`structural_eq` / `structural_hash`). Recursion is
    // broken by an expansion stack plus a memoized generated helper def.
    //
    // The per-derivation specifics are supplied by a comptime `Deriver` type
    // (`EqDeriver` / `HashDeriver`). A Deriver provides:
    //   - `Operand`: the operands threaded into one derivation step (equality
    //     holds two `DraftExprId`; hashing holds the value plus the running
    //     hasher accumulator).
    //   - the expansion-stack and memoized-def-cache accessors plus the helper
    //     fn type, so recursion breaks identically for both.
    //   - `leaf`: emit the leaf node for inline-handled shapes.
    //   - `componentForField` / `componentForTuple`: build a component's
    //     operands from the aggregate operands and the running fold state.
    //   - `combineSeed` / `combine` plus `forward`: fold the per-component
    //     results (equality conjoins component bools with AND; hashing threads
    //     the accumulator left to right).
    //   - `methodArgTypes`: method call types.
    //   - `namedEnter` / `namedExit` and `tagUnionEnter`, `tagBranchEnter`,
    //     `tagPayloadOperand`, `tagBranchExit`, `tagUnionExit`: the parts of an
    //     unwrapped nominal and a tag-union match that differ structurally
    //     between the two derivations, around the components the driver
    //     derives between them.
    //
    // A `DerivationCtx` carries the runtime parameters shared by every step:
    // the derivation's result type (Bool / Hasher) and the method name.

    const DerivationCtx = struct {
        method_name: []const u8,
        result_ty: Type.TypeId,
    };

    /// One pending piece of a structural derivation. Each piece allocates its
    /// locals, expressions, and patterns in the order a direct walk would,
    /// waiting on a frame for each component it derives.
    fn DerivationTask(comptime D: type) type {
        return union(enum) {
            /// Derive at `ty`, dispatching to its exact method when it has one.
            derive: struct { ty: Type.TypeId, operand: D.Operand },
            /// Expand `ty` structurally without consulting its exact method
            /// target. Generated recursive helper bodies start here so they do
            /// not resolve their own method back into a self-call. `marked`
            /// once `ty` is on the active expansion stack.
            expansion: struct { ty: Type.TypeId, operand: D.Operand, marked: bool = false },
            /// A call to the memoized recursive helper for `ty`.
            call: struct { ty: Type.TypeId, operand: D.Operand },
            /// The memoized recursive helper for `value_ty`. `unmarked` while
            /// the caller's active expansion mark is lifted for its body.
            def: struct {
                value_ty: Type.TypeId,
                def_id: DraftDefId = undefined,
                self_local: DraftLocalId = undefined,
                aux_local: DraftLocalId = undefined,
                second_ty: Type.TypeId = undefined,
                unmarked: bool = false,
            },
            /// Record fields or tuple items folded into one result, in
            /// `D.forward` order.
            aggregate: struct {
                operand: D.Operand,
                fields: []Type.Field = &.{},
                items: []Type.TypeId = &.{},
                state: DraftExprId = undefined,
                next: usize = 0,
            },
            /// A nominal compared through its unwrapped backing.
            named: struct { named_ty: Type.TypeId, backing_ty: Type.TypeId, operand: D.Operand, locals: D.NamedLocals = undefined },
            /// A tag union matched variant by variant, each variant's payloads
            /// folded in `D.forward` order.
            tag_union: struct {
                ty: Type.TypeId,
                tags_span: Type.Span,
                operand: D.Operand,
                locals: D.TagUnionLocals = undefined,
                tags: []Type.Tag = &.{},
                branches: []DraftBranch = &.{},
                index: usize = 0,
                branch_active: bool = false,
                payloads: []Type.TypeId = &.{},
                branch: D.TagBranchPayloads = .{},
                state: DraftExprId = undefined,
                next: usize = 0,
            },
        };
    }

    const DerivationResult = union(enum) {
        expr: DraftExprId,
        def: DraftDefId,
    };

    fn DerivationStep(comptime D: type) type {
        return union(enum) {
            /// Derive a component; the frame resumes with its result.
            child: DerivationTask(D),
            /// This frame's result is the component's result.
            tail: DerivationTask(D),
            done: DerivationResult,
        };
    }

    /// A derivation reads each operand once per component, so the operands
    /// are bound to locals first: each evaluates exactly once, in order, and
    /// before any component comparison or hash runs (including a component
    /// whose rejected method crashes).
    fn lowerDerivation(
        self: *BodyContext,
        comptime D: type,
        ty: Type.TypeId,
        operand: D.Operand,
        ctx: DerivationCtx,
    ) Allocator.Error!DraftExprId {
        const values = D.callArgs(operand);
        const second_ty = D.helperSecondArgType(ty, ctx.result_ty);
        const first_local = try self.addLocal(self.builder.symbols.fresh(), ty);
        const second_local = try self.addLocal(self.builder.symbols.fresh(), second_ty);
        const derived = try self.lowerDerivationOfBound(D, ty, D.helperOperand(
            try self.localExpr(first_local, ty),
            try self.localExpr(second_local, second_ty),
        ), ctx);
        const bind_second = try self.addExpr(.{ .ty = ctx.result_ty, .data = .{ .let_ = .{
            .bind = try self.bindPat(second_local, second_ty),
            .value = values[1],
            .rest = derived,
        } } });
        return try self.addExpr(.{ .ty = ctx.result_ty, .data = .{ .let_ = .{
            .bind = try self.bindPat(first_local, ty),
            .value = values[0],
            .rest = bind_second,
        } } });
    }

    fn lowerDerivationOfBound(
        self: *BodyContext,
        comptime D: type,
        ty: Type.TypeId,
        operand: D.Operand,
        ctx: DerivationCtx,
    ) Allocator.Error!DraftExprId {
        const Frame = struct { task: DerivationTask(D), stage: u8 = 0 };
        var frames = std.ArrayList(Frame).empty;
        defer {
            var index = frames.items.len;
            while (index > 0) {
                index -= 1;
                self.releaseDerivationTask(D, &frames.items[index].task);
            }
            frames.deinit(self.allocator);
        }
        try frames.append(self.allocator, .{ .task = .{ .derive = .{ .ty = ty, .operand = operand } } });
        var input: ?DerivationResult = null;
        while (true) {
            const frame = &frames.items[frames.items.len - 1];
            const stage = frame.stage;
            frame.stage += 1;
            const step = try self.stepDerivation(D, &frame.task, stage, input, ctx);
            input = null;
            switch (step) {
                .child => |task| try frames.append(self.allocator, .{ .task = task }),
                .tail => |task| {
                    self.releaseDerivationTask(D, &frame.task);
                    frame.* = .{ .task = task };
                },
                .done => |result| {
                    var finished = frames.pop().?;
                    self.releaseDerivationTask(D, &finished.task);
                    if (frames.items.len == 0) return result.expr;
                    input = result;
                },
            }
        }
    }

    /// Free what the task owns and restore any expansion mark it holds.
    /// Idempotent.
    fn releaseDerivationTask(self: *BodyContext, comptime D: type, task: *DerivationTask(D)) void {
        switch (task.*) {
            .expansion => |*expansion| {
                if (expansion.marked) _ = D.expansionStack(self).remove(expansion.ty);
                expansion.marked = false;
            },
            .def => |*def| {
                if (def.unmarked) D.expansionStack(self).putAssumeCapacity(def.value_ty, {});
                def.unmarked = false;
            },
            .aggregate => |*aggregate| {
                self.allocator.free(aggregate.fields);
                aggregate.fields = &.{};
                self.allocator.free(aggregate.items);
                aggregate.items = &.{};
            },
            .tag_union => |*tag_union| {
                self.allocator.free(tag_union.tags);
                tag_union.tags = &.{};
                self.allocator.free(tag_union.branches);
                tag_union.branches = &.{};
                self.allocator.free(tag_union.payloads);
                tag_union.payloads = &.{};
                tag_union.branch.deinit(self.allocator);
            },
            .derive, .call, .named => {},
        }
    }

    fn derivationExpr(expr: DraftExprId, comptime D: type) DerivationStep(D) {
        return .{ .done = .{ .expr = expr } };
    }

    /// A nominal's derivation: record and tuple backings decompose through the
    /// nominal operands so field and tuple access see the nominal layout;
    /// other backings are unwrapped and derived in their backing
    /// representation.
    fn derivationNamedTask(self: *BodyContext, comptime D: type, named_ty: Type.TypeId, backing_ty: Type.TypeId, operand: D.Operand) Allocator.Error!DerivationTask(D) {
        return switch (self.typeStore().get(backing_ty)) {
            .record => |fields| try self.derivationRecordTask(D, fields, operand),
            .tuple => |items| try self.derivationTupleTask(D, items, operand),
            .primitive, .named, .tag_union, .list, .box, .func, .erased, .zst => .{ .named = .{
                .named_ty = named_ty,
                .backing_ty = backing_ty,
                .operand = operand,
            } },
        };
    }

    fn derivationRecordTask(self: *BodyContext, comptime D: type, fields: Type.Span, operand: D.Operand) Allocator.Error!DerivationTask(D) {
        // Copied because deriving a component may reallocate the type store's fields.
        return .{ .aggregate = .{
            .operand = operand,
            .fields = try GuardedList.dupe(self.allocator, Type.Field, self.typeStore().fieldSpan(fields)),
        } };
    }

    fn derivationTupleTask(self: *BodyContext, comptime D: type, items: Type.Span, operand: D.Operand) Allocator.Error!DerivationTask(D) {
        // Copied because deriving a component may reallocate the type store's spans.
        return .{ .aggregate = .{
            .operand = operand,
            .items = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(items)),
        } };
    }

    fn stepDerivation(
        self: *BodyContext,
        comptime D: type,
        task: *DerivationTask(D),
        stage: u8,
        input: ?DerivationResult,
        ctx: DerivationCtx,
    ) Allocator.Error!DerivationStep(D) {
        switch (task.*) {
            .derive => |derive| {
                const ty = derive.ty;
                switch (self.typeStore().get(ty)) {
                    .list => {
                        const lookup = switch (try self.derivationMethodLookup(ty, ctx.method_name) orelse
                            Common.invariant(D.missing_component_method_msg)) {
                            .rejected => Common.invariant("builtin List derivation target was a rejected declaration"),
                            .target => |lookup| lookup,
                        };
                        if (lookup.target.kind == .structural) {
                            Common.invariant("owned List derivation resolved to a structural registry implementation");
                        }
                        return derivationExpr(try self.derivationMethodCall(D, lookup, ty, derive.operand, ctx), D);
                    },
                    .named => {
                        if (try self.derivationMethodLookup(ty, ctx.method_name)) |result| {
                            const lookup = switch (result) {
                                // The component's own method is its comparison,
                                // and its declaration was rejected: the same
                                // `checked_error` a direct dispatch to it is.
                                .rejected => return derivationExpr(try self.addExpr(.{
                                    .ty = ctx.result_ty,
                                    .data = try self.dispatchCrashData(.checked_error),
                                }), D),
                                .target => |lookup| lookup,
                            };
                            switch (lookup.target.kind) {
                                .structural => |kind| if (kind != D.structural_kind) {
                                    Common.invariant("structural registry implementation did not match the active derivation");
                                },
                                .procedure, .local_proc => return derivationExpr(try self.derivationMethodCall(D, lookup, ty, derive.operand, ctx), D),
                            }
                        }
                    },
                    .primitive, .record, .tuple, .tag_union, .box, .func, .erased, .zst => {},
                }
                return .{ .tail = .{ .expansion = .{ .ty = ty, .operand = derive.operand } } };
            },
            .expansion => |*expansion| {
                if (stage != 0) {
                    if (expansion.marked) _ = D.expansionStack(self).remove(expansion.ty);
                    expansion.marked = false;
                    return .{ .done = input.? };
                }
                const ty = expansion.ty;
                const operand = expansion.operand;
                const shape = self.typeStore().get(ty);
                if (structurallyExpands(shape)) {
                    const stack = D.expansionStack(self);
                    if (stack.contains(ty)) return .{ .tail = .{ .call = .{ .ty = ty, .operand = operand } } };
                    try stack.put(ty, {});
                    expansion.marked = true;
                }
                const body: ?DerivationTask(D) = switch (shape) {
                    .list => Common.invariant("structural derivation expansion reached a List; List derivations dispatch to a method target"),
                    .record => |fields| try self.derivationRecordTask(D, fields, operand),
                    .tuple => |items| try self.derivationTupleTask(D, items, operand),
                    .tag_union => |tags| .{ .tag_union = .{ .ty = ty, .tags_span = tags, .operand = operand } },
                    .named => |named| if (named.backing) |backing| try self.derivationNamedTask(D, ty, backing.ty, operand) else null,
                    .primitive, .zst, .func, .erased, .box => null,
                };
                if (body) |component| return .{ .child = component };
                const leaf = try D.leaf(self, operand, ctx);
                if (expansion.marked) _ = D.expansionStack(self).remove(ty);
                expansion.marked = false;
                return derivationExpr(leaf, D);
            },
            .call => |call| {
                if (stage == 0) return .{ .child = .{ .def = .{ .value_ty = call.ty } } };
                const callee = try self.addExprWithTypeCell(
                    try D.fnType(self, call.ty, ctx.result_ty),
                    .{ .def_ref = .{ .draft = input.?.def } },
                );
                const args = D.callArgs(call.operand);
                return derivationExpr(try self.addExpr(.{
                    .ty = ctx.result_ty,
                    .data = .{ .call_value = .{
                        .callee = callee,
                        .args = try self.addExprSpan(&args),
                    } },
                }), D);
            },
            .def => |*def| {
                const cache = D.defCache(self);
                const address = D.defAddress(def.value_ty, ctx.result_ty);
                if (stage == 0) {
                    if (cache.get(address)) |entry| return .{ .done = .{ .def = entry.id() } };

                    def.def_id = try self.draft.reserveDef(self.draft.current_owner);
                    try cache.put(address, .{ .reserved = def.def_id });

                    // A helper takes two args: the value (`value_ty`) and a second operand
                    // whose type is derivation-specific (the other equality operand at
                    // `value_ty`, or the running hasher at `result_ty`).
                    def.second_ty = D.helperSecondArgType(def.value_ty, ctx.result_ty);
                    def.self_local = try self.addLocal(self.builder.symbols.fresh(), def.value_ty);
                    def.aux_local = try self.addLocal(self.builder.symbols.fresh(), def.second_ty);
                    const self_expr = try self.localExpr(def.self_local, def.value_ty);
                    const aux_expr = try self.localExpr(def.aux_local, def.second_ty);

                    // The helper body is the structural expansion for this type. The
                    // caller's active mark is lifted while it lowers so the body expands
                    // exactly one layer and only recursive edges inside that layer call
                    // back to the reserved helper.
                    if (!D.expansionStack(self).remove(def.value_ty)) {
                        Common.invariant("recursive structural derivation helper requested outside an active expansion");
                    }
                    def.unmarked = true;
                    return .{ .child = .{ .expansion = .{ .ty = def.value_ty, .operand = D.helperOperand(self_expr, aux_expr) } } };
                }
                const args = try self.addTypedLocalSpan(&.{
                    .{ .local = def.self_local, .ty = def.value_ty },
                    .{ .local = def.aux_local, .ty = def.second_ty },
                });
                self.draft.setDef(def.def_id, .{
                    .symbol = self.builder.symbols.fresh(),
                    .fn_def = null,
                    .identity_seed = .{ .kind = @typeName(D), .cells = .{ DraftTypeCell.fromSealed(def.value_ty), DraftTypeCell.fromSealed(ctx.result_ty), null, null } },
                    .args = args,
                    .body = .{ .roc = input.?.expr },
                    .ret = try self.draftTypeCell(ctx.result_ty),
                });
                try cache.put(address, .{ .ready = def.def_id });
                D.expansionStack(self).putAssumeCapacity(def.value_ty, {});
                def.unmarked = false;
                return .{ .done = .{ .def = def.def_id } };
            },
            .aggregate => |*aggregate| {
                if (stage == 0) {
                    aggregate.state = try D.combineSeed(self, aggregate.operand, ctx);
                } else {
                    aggregate.state = try D.combine(self, aggregate.state, input.?.expr, ctx);
                    aggregate.next += 1;
                }
                const len = aggregate.fields.len + aggregate.items.len;
                if (aggregate.next == len) return derivationExpr(aggregate.state, D);
                const index = if (D.forward) aggregate.next else len - 1 - aggregate.next;
                if (aggregate.fields.len != 0) {
                    const field = aggregate.fields[index];
                    const component = try D.componentForField(self, aggregate.operand, aggregate.state, field);
                    return .{ .child = .{ .derive = .{ .ty = field.ty, .operand = component } } };
                }
                const item_ty = aggregate.items[index];
                const component = try D.componentForTuple(self, aggregate.operand, aggregate.state, item_ty, index);
                return .{ .child = .{ .derive = .{ .ty = item_ty, .operand = component } } };
            },
            .named => |*named| {
                if (stage == 0) {
                    const entry = try D.namedEnter(self, named.backing_ty, named.operand);
                    named.locals = entry.locals;
                    return .{ .child = .{ .derive = .{ .ty = named.backing_ty, .operand = entry.operand } } };
                }
                return derivationExpr(try D.namedExit(self, named.named_ty, named.backing_ty, named.locals, named.operand, input.?.expr, ctx), D);
            },
            .tag_union => |*tag_union| {
                if (stage == 0) {
                    tag_union.locals = try D.tagUnionEnter(self, tag_union.ty);
                    // Copied because deriving a payload may reallocate the type store's spans.
                    tag_union.tags = try GuardedList.dupe(self.allocator, Type.Tag, self.typeStore().tagSpan(tag_union.tags_span));
                    tag_union.branches = try self.allocator.alloc(DraftBranch, tag_union.tags.len);
                } else {
                    tag_union.state = try D.combine(self, tag_union.state, input.?.expr, ctx);
                    tag_union.next += 1;
                }
                while (true) {
                    if (tag_union.branch_active) {
                        const payload_count = tag_union.payloads.len;
                        if (tag_union.next < payload_count) {
                            const index = if (D.forward) tag_union.next else payload_count - 1 - tag_union.next;
                            return .{ .child = .{ .derive = .{
                                .ty = tag_union.payloads[index],
                                .operand = D.tagPayloadOperand(tag_union.branch, index, tag_union.state),
                            } } };
                        }
                        tag_union.branches[tag_union.index] = try D.tagBranchExit(
                            self,
                            tag_union.ty,
                            tag_union.locals,
                            tag_union.tags[tag_union.index],
                            tag_union.branch,
                            tag_union.state,
                            tag_union.tags.len == 1,
                            ctx,
                        );
                        tag_union.branch.deinit(self.allocator);
                        self.allocator.free(tag_union.payloads);
                        tag_union.payloads = &.{};
                        tag_union.branch_active = false;
                        tag_union.index += 1;
                    }
                    if (tag_union.index == tag_union.tags.len) {
                        return derivationExpr(try D.tagUnionExit(self, tag_union.ty, tag_union.locals, tag_union.operand, tag_union.branches, ctx), D);
                    }
                    const tag = tag_union.tags[tag_union.index];
                    tag_union.payloads = try GuardedList.dupe(self.allocator, Type.TypeId, self.typeStore().span(tag.payloads));
                    tag_union.branch_active = true;
                    tag_union.next = 0;
                    tag_union.state = try D.tagBranchEnter(self, tag_union.ty, tag_union.payloads, @intCast(tag_union.index), tag_union.operand, &tag_union.branch, ctx);
                }
            },
        }
    }

    fn derivationMethodLookup(
        self: *BodyContext,
        ty: Type.TypeId,
        method_name: []const u8,
    ) Allocator.Error!?MethodLookupResult {
        const owner = methodOwnerFromType(self.typeStore(), ty) orelse return null;
        return switch ((try self.lookupMethodTargetByName(owner, method_name)) orelse return null) {
            .rejected => .rejected,
            .target => |lookup| .{ .target = try self.withLocalProcContext(lookup) },
        };
    }

    /// The builtin List method a structural derivation dispatches to. The
    /// builtin module checks without diagnostics, so its registry declares
    /// every List derivation method with a target.
    fn builtinListDerivationLookup(self: *BodyContext, method_name: []const u8) Allocator.Error!MethodLookup {
        return switch ((try self.lookupMethodTargetByName(.{ .builtin = .list }, method_name)) orelse
            Common.invariant("checked method registry is missing the List structural derivation target")) {
            .rejected => Common.invariant("builtin List derivation target was a rejected declaration"),
            .target => |lookup| lookup,
        };
    }

    /// Dispatch a component to its exact checked method target, shared by every
    /// derivation. The argument types come from the comptime `Deriver`; the
    /// operand-to-args mapping reuses `D.callArgs`.
    fn derivationMethodCall(
        self: *BodyContext,
        comptime D: type,
        lookup: MethodLookup,
        ty: Type.TypeId,
        operand: D.Operand,
        ctx: DerivationCtx,
    ) Allocator.Error!DraftExprId {
        const callee = planned: {
            if (self.frozen_equality_method_calls) |planned_calls| {
                break :planned planned_calls.get(ty) orelse
                    Common.invariant("frozen structural derivation emission reached an unplanned component method");
            }
            const arg_tys = D.methodArgTypes(ty, ctx.result_ty);
            const callable_mono_ty = try self.methodTargetMonoTypeFromArgs(lookup, &arg_tys, ctx.result_ty);
            break :planned try self.methodTargetCalleeWithMono(lookup, callable_mono_ty);
        };
        const args = D.callArgs(operand);
        return try self.addExpr(.{ .ty = ctx.result_ty, .data = .{ .call_proc = .{
            .callee = draftProcCalleeForSlot(callee),
            .args = try self.addExprSpan(&args),
            .captures = try self.methodTargetCaptureSpan(lookup),
        } } });
    }

    /// A primitive `bool` constant: an integer literal of the bool type,
    /// 1 for true and 0 for false.
    fn boolLiteral(self: *BodyContext, value: bool, bool_ty: Type.TypeId) Allocator.Error!DraftExprId {
        return try self.intLiteralExpr(if (value) 1 else 0, bool_ty);
    }

    /// Emit `Hasher.write_u64(hasher, value)` as a low-level operation.
    fn hasherWriteU64(
        self: *BodyContext,
        hasher: DraftExprId,
        value: u64,
        hasher_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const u64_ty = try self.primitiveType(.u64);
        const value_expr = try self.intLiteralExpr(value, u64_ty);
        return try self.lowLevelExpr(.hasher_write_u64, &.{ hasher, value_expr }, hasher_ty);
    }

    const BranchOutput = union(enum) {
        value: DraftTypeCell,
        state_result: struct {
            result_cell: DraftTypeCell,
            state_cell: DraftTypeCell,
            merge_binders: []const MergeBinder,
        },
        state_only: struct {
            state_cell: DraftTypeCell,
            merge_binders: []const MergeBinder,
        },
    };

    fn branchOutputCell(_: *BodyContext, output: BranchOutput) DraftTypeCell {
        return switch (output) {
            .value => |cell| cell,
            inline .state_result, .state_only => |state| state.state_cell,
        };
    }

    /// Whether any node of the pattern must materialize on its own. Each
    /// pattern's answer is memoized, computed after its subpatterns' from an
    /// explicit work list.
    fn patternNeedsExplicitBinding(self: *BodyContext, root: checked.CheckedPatternId) Allocator.Error!bool {
        if (self.explicit_binding_memo.get(root)) |known| return known;
        const Visit = struct { pattern: checked.CheckedPatternId, children_done: bool };
        var pending: std.ArrayListUnmanaged(Visit) = .empty;
        defer pending.deinit(self.allocator);
        var children: std.ArrayListUnmanaged(checked.CheckedPatternId) = .empty;
        defer children.deinit(self.allocator);
        try pending.append(self.allocator, .{ .pattern = root, .children_done = false });
        while (pending.pop()) |visit| {
            if (self.explicit_binding_memo.contains(visit.pattern)) continue;
            children.clearRetainingCapacity();
            try self.appendExplicitBindingChildren(visit.pattern, &children);
            if (!visit.children_done) {
                try pending.append(self.allocator, .{ .pattern = visit.pattern, .children_done = true });
                for (children.items) |child| {
                    if (!self.explicit_binding_memo.contains(child)) {
                        try pending.append(self.allocator, .{ .pattern = child, .children_done = false });
                    }
                }
                continue;
            }
            var needs = try self.patternRequiresOwnMaterialization(visit.pattern);
            for (children.items) |child| {
                if (self.explicit_binding_memo.get(child).?) needs = true;
            }
            try self.explicit_binding_memo.put(self.allocator, visit.pattern, needs);
        }
        return self.explicit_binding_memo.get(root).?;
    }

    /// The subpatterns whose explicit-binding need a pattern inherits.
    fn appendExplicitBindingChildren(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        children: *std.ArrayListUnmanaged(checked.CheckedPatternId),
    ) Allocator.Error!void {
        switch (self.view.bodies.pattern(pattern_id).data) {
            .record_destructure => |destructs| for (destructs) |destruct| {
                try children.append(self.allocator, switch (destruct.kind) {
                    .required, .sub_pattern => |child| child,
                    .rest => |rest| rest,
                });
            },
            .as => |as| try children.append(self.allocator, as.pattern),
            .applied_tag => |tag| try children.appendSlice(self.allocator, tag.args),
            .nominal => |nominal| try children.append(self.allocator, nominal.backing_pattern),
            .tuple => |items| try children.appendSlice(self.allocator, items),
            .list,
            .assign,
            .numeral_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .pending,
            .runtime_error,
            => {},
        }
    }

    fn patternRequiresOwnMaterialization(self: *BodyContext, pattern_id: checked.CheckedPatternId) Allocator.Error!bool {
        const pattern = self.view.bodies.pattern(pattern_id);
        return switch (pattern.data) {
            .list => true,
            .record_destructure => |destructs| self.recordDestructsNeedExplicitRest(destructs) or
                try self.recordDestructsHaveOptionalField(pattern.ty, destructs),
            .assign,
            .as,
            .applied_tag,
            .nominal,
            .tuple,
            .numeral_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .pending,
            .runtime_error,
            => false,
        };
    }

    const CheckedPatternRefutabilityAdapter = struct {
        pub const PatternId = checked.CheckedPatternId;

        ctx: *BodyContext,

        pub fn patternClass(self: @This(), pattern_id: PatternId) PatternRefutability.PatternClass {
            const pattern = self.ctx.view.bodies.pattern(pattern_id);
            return switch (pattern.data) {
                .pending,
                .assign,
                .underscore,
                .runtime_error,
                => .cannot_miss,
                .as,
                .nominal,
                => .child,
                .tuple => .sequence,
                .record_destructure => .record,
                .list => .list,
                .applied_tag,
                .numeral_literal,
                .str_literal,
                .str_interpolation,
                => .can_miss,
            };
        }

        pub fn child(self: @This(), pattern_id: PatternId) PatternId {
            const pattern = self.ctx.view.bodies.pattern(pattern_id);
            return switch (pattern.data) {
                .as => |as| as.pattern,
                .nominal => |nominal| nominal.backing_pattern,
                .pending,
                .assign,
                .applied_tag,
                .record_destructure,
                .list,
                .tuple,
                .numeral_literal,
                .str_literal,
                .str_interpolation,
                .underscore,
                .runtime_error,
                => unreachable,
            };
        }

        pub fn sequenceLen(self: @This(), pattern_id: PatternId) usize {
            const pattern = self.ctx.view.bodies.pattern(pattern_id);
            const items = pattern.data.tuple;
            return items.len;
        }

        pub fn sequenceChild(self: @This(), pattern_id: PatternId, index: usize) PatternId {
            const pattern = self.ctx.view.bodies.pattern(pattern_id);
            const items = pattern.data.tuple;
            return items[index];
        }

        pub fn recordLen(self: @This(), pattern_id: PatternId) usize {
            const pattern = self.ctx.view.bodies.pattern(pattern_id);
            const destructs = pattern.data.record_destructure;
            return destructs.len;
        }

        pub fn recordChild(self: @This(), pattern_id: PatternId, index: usize) PatternId {
            const pattern = self.ctx.view.bodies.pattern(pattern_id);
            return switch (pattern.data.record_destructure[index].kind) {
                .required, .sub_pattern, .rest => |child_pattern| child_pattern,
            };
        }

        pub fn listFixedLen(self: @This(), pattern_id: PatternId) usize {
            const pattern = self.ctx.view.bodies.pattern(pattern_id);
            const list = pattern.data.list;
            return list.patterns.len;
        }

        pub fn listHasRest(self: @This(), pattern_id: PatternId) bool {
            const pattern = self.ctx.view.bodies.pattern(pattern_id);
            const list = pattern.data.list;
            return list.rest != null;
        }

        pub fn listRestPattern(self: @This(), pattern_id: PatternId) ?PatternId {
            const pattern = self.ctx.view.bodies.pattern(pattern_id);
            const list = pattern.data.list;
            return list.rest.?.pattern;
        }
    };

    fn patternCanMiss(self: *BodyContext, pattern_id: checked.CheckedPatternId) Allocator.Error!bool {
        return PatternRefutability.canMiss(CheckedPatternRefutabilityAdapter, .{ .ctx = self }, self.allocator, pattern_id);
    }

    fn recordDestructsNeedExplicitRest(self: *BodyContext, destructs: []const checked.CheckedRecordDestruct) bool {
        for (destructs) |destruct| {
            switch (destruct.kind) {
                .rest => |child| if (!self.patternIsIgnored(child)) return true,
                .required, .sub_pattern => {},
            }
        }
        return false;
    }

    fn listPatternCondition(
        self: *BodyContext,
        scrutinee: DraftExprId,
        list: anytype,
    ) Allocator.Error!DraftExprId {
        const u64_ty = try self.primitiveType(.u64);
        const bool_ty = try self.primitiveType(.bool);
        const len = try self.lowLevelExpr(.list_len, &.{scrutinee}, u64_ty);
        const required = try self.intLiteralExpr(list.patterns.len, u64_ty);
        const op: can.CIR.Expr.LowLevel = if (list.rest == null) .num_is_eq else .num_is_gte;
        return try self.lowLevelExpr(op, &.{ len, required }, bool_ty);
    }

    fn wrapPatternMatch(
        self: *BodyContext,
        value: DraftExprId,
        value_cell: DraftTypeCell,
        pattern: DraftPatId,
        success: DraftExprId,
        miss: DraftExprId,
        result_cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        const wildcard = try self.addPatWithTypeCell(value_cell, .wildcard);
        const branches = [_]DraftBranch{
            .{ .pat = pattern, .body = success },
            .{ .pat = wildcard, .body = miss },
        };
        return try self.addExprWithTypeCell(result_cell, .{ .match_ = .{
            .scrutinee = value,
            .branches = try self.addBranchSpan(&branches),
        } });
    }

    /// The binding of a lambda's `index`th materialized argument, continuing
    /// with the remaining arguments and then the lambda body.
    fn materializedArgsRequest(
        self: *BodyContext,
        args: []const MaterializedArg,
        index: usize,
        lambda: checked.CheckedExprId,
        body: checked.CheckedExprId,
        result_cell: DraftTypeCell,
    ) Allocator.Error!MaterializeRequest {
        const arg = args[index];
        const miss = try self.addExprWithTypeCell(result_cell, .{ .crash = try self.addStringLiteral("pattern match failed") });
        return .{
            .pattern = arg.pattern,
            .value = arg.value,
            .value_cell = arg.ty,
            .result_cell = result_cell,
            .continuation = .{ .materialized_args = .{
                .args = args,
                .index = index + 1,
                .lambda = lambda,
                .body = body,
            } },
            .miss = miss,
            .success_guard = null,
            .mode = .then_root,
        };
    }

    /// One pattern to bind against a value before a continuation.
    const MaterializeRequest = struct {
        pattern: checked.CheckedPatternId,
        value: DraftExprId,
        value_cell: DraftTypeCell,
        result_cell: DraftTypeCell,
        continuation: BindingContinuation,
        miss: DraftExprId,
        success_guard: ?PatternSuccessGuard,
        mode: enum {
            /// `lowerMaterializedPatternThen`: a root binding, guarding its
            /// success on its own pattern.
            then_root,
            /// A pattern bound under the given success guard.
            inner,
            /// `lowerMaterializedPatternValueThen`.
            value_then,
        },
        /// An enclosing root already registered this pattern's binders.
        registered: bool = false,
    };

    /// A step of a binding's continuation program, run from the innermost
    /// continuation outward: each step wraps the continuation built so far.
    const MaterializeStep = union(enum) {
        /// Bind a descendant plan's pattern against its local.
        plan: PendingMaterializedPattern,
        /// Match `value` against `pat`, continuing on success.
        wrap: struct { value: DraftExprId, cell: DraftTypeCell, pat: DraftPatId },
        /// Guard the continuation on a list pattern's length condition.
        list_cond: struct { value: DraftExprId, pattern: checked.CheckedPatternId },
        /// Bind a fresh local to the value before the continuation.
        let_value: struct { local: DraftLocalId, value: DraftExprId, cell: DraftTypeCell },
        /// Replace the continuation with this request's binding.
        request: MaterializeRequest,
        /// Lower the binding's continuation. It is a distinct lexical
        /// lowering boundary: declarations and reassignments there allocate
        /// their own locals rather than reuse the pattern's pre-registered
        /// binders, and it lowers under the pattern's success guard.
        success: struct {
            continuation: BindingContinuation,
            result_cell: DraftTypeCell,
            success_guard: ?PatternSuccessGuard,
        },
        /// Leave the continuation's lowering boundary: restore the settings
        /// its `success` step replaced.
        success_done: struct {
            entered: bool,
            reuse: bool,
            guard_frames: ?RuntimeDemandGuardFrameStack,
        },
        /// Match a directly bound pattern around the continuation, applying
        /// its optional-field binds and literal guards. Owns both slices.
        leaf: struct {
            value: DraftExprId,
            cell: DraftTypeCell,
            pat: DraftPatId,
            literal_guards: []PatternLiteralGuard,
            optional_binds: []OptionalDestructBind,
        },
    };

    const MaterializeFrame = struct {
        steps_start: usize,
        next: usize,
        continuation: DraftExprId,
        miss: DraftExprId,
        result_cell: DraftTypeCell,
        /// The binder-reuse setting to restore once this binding is built.
        saved_reuse: ?bool,
    };

    const MaterializeRun = struct {
        frames: std.ArrayListUnmanaged(MaterializeFrame) = .empty,
        steps: std.ArrayListUnmanaged(MaterializeStep) = .empty,

        fn deinit(materialize_run: *MaterializeRun, allocator: Allocator) void {
            materialize_run.steps.deinit(allocator);
            materialize_run.frames.deinit(allocator);
        }
    };

    fn lowerMaterializedPatternValueThen(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        value: DraftExprId,
        value_cell: DraftTypeCell,
        result_cell: DraftTypeCell,
        continuation: BindingContinuation,
        miss: DraftExprId,
        success_guard: ?PatternSuccessGuard,
    ) Allocator.Error!DraftExprId {
        return try self.runMaterialize(.{
            .pattern = pattern_id,
            .value = value,
            .value_cell = value_cell,
            .result_cell = result_cell,
            .continuation = continuation,
            .miss = miss,
            .success_guard = success_guard,
            .mode = .value_then,
        });
    }

    fn runMaterialize(self: *BodyContext, root: MaterializeRequest) Allocator.Error!DraftExprId {
        return (try self.runLower(.{ .materialize = .{ .root = root } })).exprValue();
    }

    /// Bind a pattern and every descendant plan it materializes. Each
    /// binding is an explicit frame whose continuation program runs step by
    /// step, and a continuation that lowers checked code lowers as a child
    /// task, so neither pattern depth nor the continuation's nesting becomes
    /// native call depth.
    const MaterializeTask = struct {
        root: MaterializeRequest,
        run: MaterializeRun = .{},
        started: bool = false,
        /// The return boundary a composed lambda body continuation crosses.
        return_boundary: ?DraftTypeCell = null,
    };

    /// Restore what unfinished frames and continuation boundaries replaced,
    /// innermost first, and free unexecuted leaf steps' slices.
    fn releaseMaterializeTask(self: *BodyContext, task: *MaterializeTask) void {
        const materialize_run = &task.run;
        var frame_index = materialize_run.frames.items.len;
        while (frame_index > 0) {
            frame_index -= 1;
            const frame = materialize_run.frames.items[frame_index];
            const end = if (frame_index + 1 < materialize_run.frames.items.len)
                materialize_run.frames.items[frame_index + 1].steps_start
            else
                materialize_run.steps.items.len;
            var step_index = end;
            while (step_index > frame.steps_start) {
                step_index -= 1;
                switch (materialize_run.steps.items[step_index]) {
                    .success_done => |done| if (done.entered) {
                        self.reuse_pre_registered_pattern_binders = done.reuse;
                        if (done.guard_frames) |frames| self.runtime_demand_guard_frames = frames;
                    },
                    .leaf => |leaf| if (step_index >= frame.next) {
                        self.allocator.free(leaf.literal_guards);
                        self.allocator.free(leaf.optional_binds);
                    },
                    .plan, .wrap, .list_cond, .let_value, .request, .success => {},
                }
            }
            if (frame.saved_reuse) |saved| self.reuse_pre_registered_pattern_binders = saved;
        }
        materialize_run.deinit(self.allocator);
        task.run = .{};
    }

    fn stepMaterialize(self: *BodyContext, task: *MaterializeTask, input: ?LowerResult) Allocator.Error!LowerStep {
        const materialize_run = &task.run;
        if (!task.started) {
            task.started = true;
            if (try self.enterMaterialize(materialize_run, task.root)) |expr| return loweredExprStep(expr);
        } else {
            var lowered = input.?.exprValue();
            if (task.return_boundary) |ret_cell| {
                lowered = try self.addExprWithTypeCell(ret_cell, .{ .return_ = .{ .value = lowered, .target = ret_cell } });
                task.return_boundary = null;
            }
            self.currentMaterializeFrame(materialize_run).continuation = lowered;
        }

        var delivered: DraftExprId = undefined;
        var has_delivery = false;
        while (true) {
            const index = materialize_run.frames.items.len - 1;
            if (has_delivery) {
                materialize_run.frames.items[index].continuation = delivered;
                has_delivery = false;
            }
            const frame = materialize_run.frames.items[index];
            if (frame.next < materialize_run.steps.items.len) {
                const step_index = frame.next;
                const step = materialize_run.steps.items[step_index];
                materialize_run.frames.items[index].next += 1;
                const request: MaterializeRequest = switch (step) {
                    .plan => |plan| .{
                        .pattern = plan.pattern,
                        .value = try self.addExprWithTypeCell(plan.cell, .{ .local = plan.local }),
                        .value_cell = plan.cell,
                        .result_cell = frame.result_cell,
                        .continuation = .{ .expr = frame.continuation },
                        .miss = frame.miss,
                        .success_guard = null,
                        .mode = .inner,
                        .registered = true,
                    },
                    .request => |request| request,
                    .wrap => |wrap| {
                        materialize_run.frames.items[index].continuation = try self.wrapPatternMatch(
                            wrap.value,
                            wrap.cell,
                            wrap.pat,
                            frame.continuation,
                            frame.miss,
                            frame.result_cell,
                        );
                        continue;
                    },
                    .list_cond => |list_cond| {
                        const list = self.view.bodies.pattern(list_cond.pattern).data.list;
                        const cond = try self.listPatternCondition(list_cond.value, list);
                        const branches = [_]DraftIfBranch{.{ .cond = cond, .body = frame.continuation }};
                        materialize_run.frames.items[index].continuation = try self.addExprWithTypeCell(frame.result_cell, .{ .if_ = .{
                            .branches = try self.addIfBranchSpan(&branches),
                            .final_else = frame.miss,
                        } });
                        continue;
                    },
                    .let_value => |let_value| {
                        materialize_run.frames.items[index].continuation = try self.addExprWithTypeCell(frame.result_cell, .{ .let_ = .{
                            .bind = try self.addPatWithTypeCell(let_value.cell, .{ .bind = let_value.local }),
                            .value = let_value.value,
                            .rest = frame.continuation,
                        } });
                        continue;
                    },
                    .success => |success| {
                        materialize_run.steps.items[step_index + 1].success_done = .{
                            .entered = true,
                            .reuse = self.reuse_pre_registered_pattern_binders,
                            .guard_frames = null,
                        };
                        self.reuse_pre_registered_pattern_binders = false;
                        if (success.success_guard) |guard| {
                            materialize_run.steps.items[step_index + 1].success_done.guard_frames = self.runtime_demand_guard_frames;
                            self.runtime_demand_guard_frames = try self.withPatternSuccessRuntimeDemandGuardFrame(guard);
                        }
                        switch (success.continuation) {
                            .expr => |expr| materialize_run.frames.items[index].continuation = expr,
                            .materialized_args => |args| {
                                if (args.index >= args.args.len) {
                                    return try self.materializedLambdaBodyStep(task, args.lambda, args.body, success.result_cell);
                                }
                                const next = try self.materializedArgsRequest(args.args, args.index, args.lambda, args.body, success.result_cell);
                                if (try self.enterMaterialize(materialize_run, next)) |expr| {
                                    materialize_run.frames.items[index].continuation = expr;
                                }
                            },
                            .iterator_body => |body| return try self.loopBodyStep(body.body, body.result_cell, body.rest_expr, body.carries),
                        }
                        continue;
                    },
                    .success_done => |done| {
                        self.reuse_pre_registered_pattern_binders = done.reuse;
                        if (done.guard_frames) |frames| self.runtime_demand_guard_frames = frames;
                        materialize_run.steps.items[step_index].success_done.entered = false;
                        continue;
                    },
                    .leaf => |leaf| {
                        defer self.allocator.free(leaf.literal_guards);
                        defer self.allocator.free(leaf.optional_binds);
                        var success = frame.continuation;
                        if (leaf.optional_binds.len > 0) {
                            success = try self.applyOptionalDestructBinds(leaf.optional_binds, success);
                        }
                        const rest = try self.applyPatternLiteralGuardsAtCell(
                            leaf.literal_guards,
                            success,
                            frame.miss,
                            frame.result_cell,
                        );
                        materialize_run.frames.items[index].continuation = try self.wrapPatternMatch(leaf.value, leaf.cell, leaf.pat, rest, frame.miss, frame.result_cell);
                        continue;
                    },
                };
                if (try self.enterMaterialize(materialize_run, request)) |expr| {
                    materialize_run.frames.items[index].continuation = expr;
                }
                continue;
            }

            _ = materialize_run.frames.pop();
            materialize_run.steps.shrinkRetainingCapacity(frame.steps_start);
            if (frame.saved_reuse) |saved| self.reuse_pre_registered_pattern_binders = saved;
            if (materialize_run.frames.items.len == 0) return loweredExprStep(frame.continuation);
            delivered = frame.continuation;
            has_delivery = true;
        }
    }

    /// Lower a lambda body at its function's return cell once every
    /// materialized argument is bound. A body whose
    /// checked type is not the function's checked result lowers at its own
    /// type's cell: its residual error extension is shared with the return
    /// row and settles when the return settles. It crosses the explicit
    /// return boundary once lowered.
    fn materializedLambdaBodyStep(
        self: *BodyContext,
        task: *MaterializeTask,
        lambda_id: checked.CheckedExprId,
        checked_body: checked.CheckedExprId,
        ret_cell: DraftTypeCell,
    ) Allocator.Error!LowerStep {
        if (self.checkedExprDivergesInLoweredRuntime(checked_body)) {
            return requestLowerChild(self, checked_body, ret_cell);
        }
        const body_ty = self.view.bodies.expr(checked_body).ty;
        const fn_ret_ty = self.checkedFunctionType(self.view.bodies.expr(lambda_id).ty).ret;
        if (resolvedPayload(self.view, body_ty).root == resolvedPayload(self.view, fn_ret_ty).root) {
            return requestLowerChild(self, checked_body, ret_cell);
        }
        const body_cell = DraftTypeCell.fromGraphNode(try self.lowerTypeNode(body_ty));
        task.return_boundary = ret_cell;
        return requestLowerChild(self, checked_body, body_cell);
    }

    /// Lower a binding's continuation first among its frame's steps.
    fn appendMaterializeSuccessSteps(self: *BodyContext, materialize_run: *MaterializeRun, request: MaterializeRequest) Allocator.Error!void {
        try materialize_run.steps.append(self.allocator, .{ .success = .{
            .continuation = request.continuation,
            .result_cell = request.result_cell,
            .success_guard = request.success_guard,
        } });
        try materialize_run.steps.append(self.allocator, .{ .success_done = .{
            .entered = false,
            .reuse = false,
            .guard_frames = null,
        } });
    }

    fn pushMaterializeFrame(
        self: *BodyContext,
        materialize_run: *MaterializeRun,
        request: MaterializeRequest,
        saved_reuse: ?bool,
    ) Allocator.Error!void {
        try materialize_run.frames.append(self.allocator, .{
            .steps_start = materialize_run.steps.items.len,
            .next = materialize_run.steps.items.len,
            .continuation = undefined,
            .miss = request.miss,
            .result_cell = request.result_cell,
            .saved_reuse = saved_reuse,
        });
    }

    /// A binding needing no descendant plans, built at once; otherwise null
    /// after pushing the frame whose program builds it.
    fn enterMaterialize(self: *BodyContext, materialize_run: *MaterializeRun, request_in: MaterializeRequest) Allocator.Error!?DraftExprId {
        var request = request_in;
        switch (request.mode) {
            .value_then => {
                const value_node = try request.value_cell.toGraphNode(self.graph);
                try self.constrainCheckedInterfaceToCell(self.view.bodies.pattern(request.pattern).ty, request.value_cell);
                if (!try self.patternNeedsExplicitBinding(request.pattern)) {
                    try self.pushMaterializedPatternValueLeaf(materialize_run, request, value_node, null);
                    return null;
                }

                const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), request.value_cell, null);
                const local_expr = try self.addExprWithTypeCell(request.value_cell, .{ .local = local });
                try self.pushMaterializeFrame(materialize_run, request, null);
                try materialize_run.steps.append(self.allocator, .{ .request = .{
                    .pattern = request.pattern,
                    .value = local_expr,
                    .value_cell = request.value_cell,
                    .result_cell = request.result_cell,
                    .continuation = request.continuation,
                    .miss = request.miss,
                    .success_guard = null,
                    .mode = .then_root,
                } });
                try materialize_run.steps.append(self.allocator, .{ .let_value = .{
                    .local = local,
                    .value = request.value,
                    .cell = request.value_cell,
                } });
                return null;
            },
            .then_root => {
                try self.constrainCheckedInterfaceToCell(self.view.bodies.pattern(request.pattern).ty, request.value_cell);
                request.success_guard = .{
                    .root_pattern = request.pattern,
                    .root_node = try request.value_cell.toGraphNode(self.graph),
                };
                request.mode = .inner;
            },
            .inner => {},
        }

        try self.constrainCheckedInterfaceToCell(self.view.bodies.pattern(request.pattern).ty, request.value_cell);
        const value_node = try request.value_cell.toGraphNode(self.graph);
        // A descendant plan's binders were registered with its root's.
        if (!request.registered) try self.preRegisterPatternBindersAtNode(request.pattern, value_node);
        const saved_reuse = self.reuse_pre_registered_pattern_binders;
        self.reuse_pre_registered_pattern_binders = true;
        const pattern = self.view.bodies.pattern(request.pattern);
        const variant: enum { list, record_rest, wrapped, value } = switch (pattern.data) {
            .list => .list,
            .record_destructure => |destructs| if (self.recordDestructsNeedExplicitRest(destructs) or
                try self.recordDestructsHaveOptionalField(pattern.ty, destructs))
                .record_rest
            else if (try self.patternNeedsExplicitBinding(request.pattern))
                .wrapped
            else
                .value,
            .assign,
            .numeral_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .pending,
            .runtime_error,
            => .value,
            .as,
            .applied_tag,
            .nominal,
            .tuple,
            => if (try self.patternNeedsExplicitBinding(request.pattern)) .wrapped else .value,
        };
        if (variant == .value) {
            errdefer self.reuse_pre_registered_pattern_binders = saved_reuse;
            const leaf_node = try request.value_cell.toGraphNode(self.graph);
            try self.constrainCheckedInterfaceToCell(pattern.ty, request.value_cell);
            if (try self.patternNeedsExplicitBinding(request.pattern)) {
                Common.invariant("explicitly materialized pattern reached direct value binding");
            }
            try self.pushMaterializedPatternValueLeaf(materialize_run, request, leaf_node, saved_reuse);
            return null;
        }

        try self.pushMaterializeFrame(materialize_run, request, saved_reuse);
        switch (variant) {
            .value => unreachable,
            .list => try self.prepareListPatternBinding(materialize_run, request, value_node),
            .record_rest => try self.prepareRecordRestPatternBinding(materialize_run, request, value_node),
            .wrapped => {
                var pending = std.ArrayList(PendingMaterializedPattern).empty;
                defer pending.deinit(self.allocator);
                const shell = try self.lowerPatternShellAtNode(request.pattern, value_node, &pending);
                if (pending.items.len == 0) {
                    Common.invariant("recursive materialized wrapper produced no explicit descendant plan");
                }
                try self.appendMaterializeSuccessSteps(materialize_run, request);
                try self.appendPendingMaterializeSteps(materialize_run, pending.items);
                try materialize_run.steps.append(self.allocator, .{ .wrap = .{ .value = request.value, .cell = request.value_cell, .pat = shell } });
            },
        }
        return null;
    }

    fn currentMaterializeFrame(_: *BodyContext, materialize_run: *MaterializeRun) *MaterializeFrame {
        return &materialize_run.frames.items[materialize_run.frames.items.len - 1];
    }

    /// Queue descendant plans innermost first: the last plan binds closest to
    /// the continuation.
    fn appendPendingMaterializeSteps(
        self: *BodyContext,
        materialize_run: *MaterializeRun,
        pending: []const PendingMaterializedPattern,
    ) Allocator.Error!void {
        var index = pending.len;
        while (index > 0) {
            index -= 1;
            try materialize_run.steps.append(self.allocator, .{ .plan = pending[index] });
        }
    }

    /// Bind a pattern that needs no explicit descendant plans directly
    /// against its value: a frame whose program lowers the continuation and
    /// then matches the pattern around it.
    fn pushMaterializedPatternValueLeaf(
        self: *BodyContext,
        materialize_run: *MaterializeRun,
        request: MaterializeRequest,
        value_node: NodeId,
        saved_reuse: ?bool,
    ) Allocator.Error!void {
        const guards_start = self.pattern_literal_guards.items.len;
        const binds_start = self.optional_destruct_binds.items.len;
        const pat = try self.lowerPatternAtNode(request.pattern, value_node);
        const literal_guards = try self.drainPatternLiteralGuards(guards_start);
        errdefer self.allocator.free(literal_guards);
        const optional_binds = try self.drainOptionalDestructBinds(binds_start);
        errdefer self.allocator.free(optional_binds);
        try materialize_run.frames.ensureUnusedCapacity(self.allocator, 1);
        try materialize_run.steps.ensureUnusedCapacity(self.allocator, 3);
        try self.pushMaterializeFrame(materialize_run, request, saved_reuse);
        try self.appendMaterializeSuccessSteps(materialize_run, request);
        materialize_run.steps.appendAssumeCapacity(.{ .leaf = .{
            .value = request.value,
            .cell = request.value_cell,
            .pat = pat,
            .literal_guards = literal_guards,
            .optional_binds = optional_binds,
        } });
    }

    fn prepareListPatternBinding(
        self: *BodyContext,
        materialize_run: *MaterializeRun,
        request: MaterializeRequest,
        value_node: NodeId,
    ) Allocator.Error!void {
        const list = self.view.bodies.pattern(request.pattern).data.list;
        const value = request.value;
        const value_cell = request.value_cell;
        const elem_node = try self.graph.listElementNode(value_node);
        const elem_cell = DraftTypeCell.fromGraphNode(elem_node);
        const values = try self.allocator.alloc(DraftExprId, list.patterns.len);
        defer self.allocator.free(values);
        const patterns = try self.allocator.alloc(DraftPatId, list.patterns.len);
        defer self.allocator.free(patterns);
        const pending_per_item = try self.allocator.alloc(std.ArrayList(PendingMaterializedPattern), list.patterns.len);
        defer {
            for (pending_per_item) |*pending| pending.deinit(self.allocator);
            self.allocator.free(pending_per_item);
        }
        for (pending_per_item) |*pending| pending.* = .empty;
        const u64_ty = try self.primitiveType(.u64);
        const needs_len = if (list.rest) |rest| rest.index < list.patterns.len or rest.pattern != null else false;
        const len = if (needs_len) try self.lowLevelExpr(.list_len, &.{value}, u64_ty) else null;

        for (list.patterns, 0..) |pattern_id, index| {
            const item_index = try self.listPatternItemIndex(index, list.patterns.len, list.rest, len, u64_ty);
            values[index] = try self.addExprWithTypeCell(elem_cell, .{ .low_level = .{
                .op = .list_get_unsafe,
                .args = try self.addExprSpan(&.{ value, item_index }),
            } });
            patterns[index] = try self.lowerPatternPlanPlaceholderAtNode(pattern_id, elem_node, &pending_per_item[index]);
        }

        var rest_pat: ?DraftPatId = null;
        var rest_value: ?DraftExprId = null;
        var rest_pending = std.ArrayList(PendingMaterializedPattern).empty;
        defer rest_pending.deinit(self.allocator);
        if (list.rest) |rest| {
            if (rest.pattern) |rest_pattern| {
                const list_len = len orelse try self.lowLevelExpr(.list_len, &.{value}, u64_ty);
                const fixed_count = try self.intLiteralExpr(list.patterns.len, u64_ty);
                const rest_len = try self.lowLevelExpr(.num_minus, &.{ list_len, fixed_count }, u64_ty);
                const rest_start = try self.intLiteralExpr(rest.index, u64_ty);
                const range = try self.sublistRangeExpr(rest_start, rest_len, u64_ty);
                rest_value = try self.addExprWithTypeCell(value_cell, .{ .low_level = .{
                    .op = .list_sublist,
                    .args = try self.addExprSpan(&.{ value, range }),
                } });
                rest_pat = try self.lowerPatternPlanPlaceholderAtNode(rest_pattern, value_node, &rest_pending);
            }
        }

        try self.appendMaterializeSuccessSteps(materialize_run, request);
        const has_rest_plan = rest_pat != null;
        const rest_index = if (list.rest) |rest| rest.index else 0;
        var sequence_index = patterns.len + @intFromBool(has_rest_plan);
        while (sequence_index > 0) {
            sequence_index -= 1;
            if (has_rest_plan and sequence_index == rest_index) {
                try self.appendPendingMaterializeSteps(materialize_run, rest_pending.items);
                try materialize_run.steps.append(self.allocator, .{ .wrap = .{
                    .value = rest_value orelse Common.invariant("list rest pattern had no lowered rest value"),
                    .cell = value_cell,
                    .pat = rest_pat.?,
                } });
                continue;
            }
            const fixed_index = sequence_index - @intFromBool(has_rest_plan and sequence_index > rest_index);
            try self.appendPendingMaterializeSteps(materialize_run, pending_per_item[fixed_index].items);
            try materialize_run.steps.append(self.allocator, .{ .wrap = .{
                .value = values[fixed_index],
                .cell = elem_cell,
                .pat = patterns[fixed_index],
            } });
        }
        try materialize_run.steps.append(self.allocator, .{ .list_cond = .{ .value = value, .pattern = request.pattern } });
    }

    fn prepareRecordRestPatternBinding(
        self: *BodyContext,
        materialize_run: *MaterializeRun,
        request: MaterializeRequest,
        value_node: NodeId,
    ) Allocator.Error!void {
        const PreparedChild = struct {
            value: DraftExprId,
            cell: DraftTypeCell,
            shell: DraftPatId,
            pending: std.ArrayList(PendingMaterializedPattern),
        };
        const pattern = self.view.bodies.pattern(request.pattern);
        const record_checked_ty = pattern.ty;
        const destructs = pattern.data.record_destructure;
        const value = request.value;
        const prepared = try self.allocator.alloc(?PreparedChild, destructs.len);
        defer {
            for (prepared) |*entry| {
                if (entry.*) |*child| child.pending.deinit(self.allocator);
            }
            self.allocator.free(prepared);
        }
        for (prepared) |*entry| entry.* = null;

        for (destructs, 0..) |destruct, index| {
            var pending = std.ArrayList(PendingMaterializedPattern).empty;
            var pending_owned = true;
            defer if (pending_owned) pending.deinit(self.allocator);
            switch (destruct.kind) {
                .required, .sub_pattern => |child| {
                    const name = try self.recordFieldName(self.view, destruct.label);
                    const field_node = try self.graph.recordFieldNode(value_node, name);
                    const field_cell = DraftTypeCell.fromGraphNode(field_node);
                    const field_value = try self.addExprWithTypeCell(field_cell, .{
                        .field_access = .{
                            .receiver = value,
                            .segments = try self.draft.addFieldAccessSegmentSpan(&.{.{ .field = name }}),
                        },
                    });
                    if ((try self.recordDestructFieldKind(record_checked_ty, destruct)) == .optional) {
                        // The field's slot holds the tagged
                        // `[#Missing, #Present(v)]` union; the bound value is
                        // that slot materialized as the binder's checked
                        // `Try(v, [MissingField])` (design.md "Field
                        // Kinds"), against which the sub-pattern matches.
                        const try_node = try self.instNode(self.view.bodies.pattern(child).ty);
                        const try_value = try self.optionalDestructTryExprAtNode(field_value, field_node, try_node);
                        prepared[index] = .{
                            .value = try_value,
                            .cell = DraftTypeCell.fromGraphNode(try_node),
                            .shell = try self.lowerPatternPlanPlaceholderAtNode(child, try_node, &pending),
                            .pending = pending,
                        };
                        pending_owned = false;
                        continue;
                    }
                    prepared[index] = .{
                        .value = field_value,
                        .cell = field_cell,
                        .shell = try self.lowerPatternPlanPlaceholderAtNode(child, field_node, &pending),
                        .pending = pending,
                    };
                    pending_owned = false;
                },
                .rest => |child| {
                    if (self.patternIsIgnored(child)) continue;
                    const rest_node = try self.recordRestNodeForPattern(value_node, destructs, child);
                    const rest_cell = DraftTypeCell.fromGraphNode(rest_node);
                    prepared[index] = .{
                        .value = try self.lowerRecordRestValueWithTypeCell(value, value_node, rest_cell, rest_node),
                        .cell = rest_cell,
                        .shell = try self.lowerPatternPlanPlaceholderAtNode(child, rest_node, &pending),
                        .pending = pending,
                    };
                    pending_owned = false;
                },
            }
        }

        try self.appendMaterializeSuccessSteps(materialize_run, request);
        var i = destructs.len;
        while (i > 0) {
            i -= 1;
            const child = prepared[i] orelse continue;
            try self.appendPendingMaterializeSteps(materialize_run, child.pending.items);
            try materialize_run.steps.append(self.allocator, .{ .wrap = .{ .value = child.value, .cell = child.cell, .pat = child.shell } });
        }
    }

    fn listPatternItemIndex(
        self: *BodyContext,
        index: usize,
        pattern_count: usize,
        rest: ?checked.CheckedListRestPattern,
        len: ?DraftExprId,
        u64_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        if (rest) |rest_info| {
            if (index >= rest_info.index) {
                const list_len = len orelse Common.invariant("list pattern trailing item index required list length");
                const trailing_count = try self.intLiteralExpr(pattern_count - index, u64_ty);
                return try self.lowLevelExpr(.num_minus, &.{ list_len, trailing_count }, u64_ty);
            }
        }
        return try self.intLiteralExpr(index, u64_ty);
    }

    fn sublistRangeExpr(
        self: *BodyContext,
        start: DraftExprId,
        len: DraftExprId,
        u64_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const len_name = try self.nameStoreMut().internRecordFieldLabel("len");
        const start_name = try self.nameStoreMut().internRecordFieldLabel("start");
        const fields = [_]Type.Field{
            .{ .name = len_name, .ty = u64_ty, .default = null },
            .{ .name = start_name, .ty = u64_ty, .default = null },
        };
        const ty = try self.typeStore().internRecord(self.nameStore(), &fields);
        const exprs = [_]DraftFieldExpr{
            .{ .name = len_name, .value = len },
            .{ .name = start_name, .value = start },
        };
        return try self.addExpr(.{ .ty = ty, .data = .{ .record = try self.addFieldExprSpan(&exprs) } });
    }

    fn lowerRecordRestValueWithTypeCell(
        self: *BodyContext,
        value: DraftExprId,
        value_node: NodeId,
        rest_cell: DraftTypeCell,
        rest_node: NodeId,
    ) Allocator.Error!DraftExprId {
        try self.relateRecordRestNodeToSource(value_node, rest_node);
        const rest_fields = try self.allocator.dupe(InstField, (try self.graph.recordNodes(rest_node)).fields);
        defer self.allocator.free(rest_fields);
        std.mem.sort(InstField, rest_fields, self.nameStore(), instRecordFieldLessThan);
        const fields = try self.allocator.alloc(DraftFieldExpr, rest_fields.len);
        defer self.allocator.free(fields);
        for (rest_fields, 0..) |field, i| {
            fields[i] = .{
                .name = field.name,
                .value = try self.addExprWithTypeCell(
                    DraftTypeCell.fromGraphNode(try self.graph.recordFieldNode(value_node, field.name)),
                    .{ .field_access = .{
                        .receiver = value,
                        .segments = try self.draft.addFieldAccessSegmentSpan(&.{.{ .field = field.name }}),
                    } },
                ),
            };
        }
        return try self.addExprWithTypeCell(rest_cell, .{
            .record = try self.addFieldExprSpan(fields),
        });
    }

    fn relateRecordRestNodeToSource(
        self: *BodyContext,
        source_node: NodeId,
        rest_node: NodeId,
    ) Allocator.Error!void {
        const rest_fields = (try self.graph.recordNodes(rest_node)).fields;
        for (rest_fields) |field| {
            try self.graph.unify(field.ty, try self.graph.recordFieldNode(source_node, field.name));
        }
    }

    fn recordRestNodeForPattern(
        self: *BodyContext,
        source_node: NodeId,
        destructs: []const checked.CheckedRecordDestruct,
        rest_pattern: checked.CheckedPatternId,
    ) Allocator.Error!NodeId {
        const source_fields = (try self.graph.recordNodes(source_node)).fields;
        var remaining = std.ArrayList(InstField).empty;
        defer remaining.deinit(self.allocator);
        for (source_fields) |field| {
            var consumed = false;
            for (destructs) |destruct| switch (destruct.kind) {
                .required, .sub_pattern => {
                    const name = try self.recordFieldName(self.view, destruct.label);
                    if (field.name == name) consumed = true;
                },
                .rest => {},
            };
            if (!consumed) try remaining.append(self.allocator, field);
        }

        const rest_node = if (remaining.items.len == 0)
            try self.graph.newNode(.empty_record)
        else
            try self.graph.newNode(.{ .record = .{
                .fields = try self.graph.arena().dupe(InstField, remaining.items),
                .ext = try self.graph.newNode(.empty_record),
            } });
        try self.graph.unify(
            try self.lowerTypeNode(self.view.bodies.pattern(rest_pattern).ty),
            rest_node,
        );
        return rest_node;
    }

    fn runtimeCrashExpr(self: *BodyContext, ty: Type.TypeId, message: []const u8) Allocator.Error!DraftExprId {
        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .crash = try self.addStringLiteral(message) },
        });
    }

    fn runtimeCrashExprAtCell(self: *BodyContext, cell: DraftTypeCell, message: []const u8) Allocator.Error!DraftExprId {
        return try self.addExprWithTypeCell(cell, .{ .crash = try self.addStringLiteral(message) });
    }

    fn comptimeExhaustivenessFailedExpr(self: *BodyContext, ty: Type.TypeId, site: DraftComptimeSiteId) Allocator.Error!DraftExprId {
        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .comptime_exhaustiveness_failed = site },
        });
    }

    /// Compile-time sites carry the checked module whose exhaustiveness-site
    /// ids and regions they name. That is the view this body is lowered from,
    /// which is not the program's root module when a specialization lowers an
    /// imported body, and which the site's eventual procedure cannot reveal.
    fn addComptimeSite(
        self: *BodyContext,
        kind: Ast.ComptimeSiteKind,
        region: base.Region,
        checked_site: ?checked.CheckedExhaustivenessSiteId,
        branch_regions: []const base.Region,
    ) Allocator.Error!DraftComptimeSiteId {
        return try self.draft.addComptimeSite(kind, self.builder.loweringModuleId(self.view.key), region, checked_site, branch_regions);
    }

    fn wrapComptimeBranch(
        self: *BodyContext,
        site: ?DraftComptimeSiteId,
        branch_index: usize,
        body: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const actual_site = site orelse return body;
        return try self.addExprWithTypeCell(self.exprTypeCell(body), .{ .comptime_branch_taken = .{
            .site = actual_site,
            .branch_index = @intCast(branch_index),
            .body = body,
        } });
    }

    fn matchComptimeSite(self: *BodyContext, expr_id: checked.CheckedExprId, match: anytype) Allocator.Error!?DraftComptimeSiteId {
        if (match.skip_exhaustiveness) return null;
        const shared_site_kind: ExhaustivenessContext.SiteKind = switch (match.comptime_site_kind) {
            .match => .match,
            .destructure => .destructure,
        };
        if (!self.shouldRecordComptimeSite(shared_site_kind)) return null;
        const branch_regions = try self.matchBranchRegions(match.branches);
        defer self.allocator.free(branch_regions);
        const expr = self.view.bodies.expr(expr_id);
        const site_kind: Ast.ComptimeSiteKind = switch (shared_site_kind) {
            .match => .match,
            .destructure => .destructure,
            .if_ => Common.invariant("if site kind reached match comptime site lowering"),
        };
        const checked_site = if (ExhaustivenessContext.siteHasPendingStaticDiagnostic(shared_site_kind))
            switch (shared_site_kind) {
                .match => self.view.exhaustiveness_sites.lookupByMatchExpr(expr_id),
                .destructure => blk: {
                    if (match.branches.len != 1) break :blk null;
                    const patterns = match.branches[0].patternsSlice(self.view.bodies);
                    if (patterns.len != 1) break :blk null;
                    break :blk self.view.exhaustiveness_sites.lookupByDestructurePattern(patterns[0].pattern);
                },
                .if_ => Common.invariant("if site kind reached checked match site lookup"),
            }
        else
            null;
        return try self.addComptimeSite(site_kind, expr.source_region, checked_site, branch_regions);
    }

    fn matchBranchRegions(self: *BodyContext, branches: []const checked.CheckedMatchBranch) Allocator.Error![]base.Region {
        const regions = try self.allocator.alloc(base.Region, branchCount(branches));
        var index: usize = 0;
        for (branches) |branch| {
            for (branch.patternsSlice(self.view.bodies)) |pattern| {
                regions[index] = self.view.bodies.pattern(pattern.pattern).source_region;
                index += 1;
            }
        }
        return regions;
    }

    fn ifComptimeSite(self: *BodyContext, expr_id: checked.CheckedExprId, if_: anytype) Allocator.Error!?DraftComptimeSiteId {
        if (!if_.warn_unused_branches) return null;
        if (!self.shouldRecordComptimeSite(.if_)) return null;
        const branch_regions = try self.ifBranchRegions(if_);
        defer self.allocator.free(branch_regions);
        const expr = self.view.bodies.expr(expr_id);
        return try self.addComptimeSite(.if_, expr.source_region, null, branch_regions);
    }

    fn ifBranchRegions(self: *BodyContext, if_: anytype) Allocator.Error![]base.Region {
        const regions = try self.allocator.alloc(base.Region, if_.branches.len + 1);
        for (if_.branches, 0..) |branch, index| {
            regions[index] = self.view.bodies.expr(branch.cond).source_region;
        }
        regions[if_.branches.len] = self.view.bodies.expr(if_.final_else).source_region;
        return regions;
    }

    fn matchScrutineeTypeNode(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
    ) Allocator.Error!NodeId {
        const expr = self.view.bodies.expr(checked_expr);
        const public_node = try self.instNode(expr.ty);
        if (!try self.graph.containsIteratorInterface(public_node)) {
            return try self.lowerExprTypeNode(checked_expr);
        }
        // The scrutinee's branches are lowered against this node, so a
        // deferred iterator result is completed here on purpose: the match
        // must read the representation the producer actually returns.
        return switch (expr.data) {
            .call,
            .dispatch_call,
            .field_access,
            .tuple_access,
            .interpolation,
            .type_dispatch_call,
            .method_eq,
            => (try self.exprCallResultEvidenceNode(checked_expr, null)) orelse
                try self.lowerExprTypeNode(checked_expr),
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .structural_eq, .structural_hash, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => try self.lowerExprTypeNode(checked_expr),
        };
    }

    fn runtimeDemandGuardFrameAddress(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        kind: RuntimeDemandGuardFrameKind,
    ) RuntimeDemandGuardFrameAddress {
        return self.runtimeDemandGuardFrameAddressRaw(@backingInt(pattern_id), kind);
    }

    fn runtimeDemandGuardFrameAddressRaw(
        self: *BodyContext,
        site: u32,
        kind: RuntimeDemandGuardFrameKind,
    ) RuntimeDemandGuardFrameAddress {
        return .{
            .module = self.view.key.bytes,
            .owner_module = names.procTemplateModuleDigest(self.owner_template).bytes,
            .owner_proc_base = @backingInt(self.owner_template.proc_base),
            .owner_template = @backingInt(self.owner_template.template),
            .pattern = site,
            .kind = kind,
        };
    }

    fn withMatchBranchRuntimeDemandGuardFrame(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
    ) Allocator.Error!RuntimeDemandGuardFrameStack {
        const address = self.runtimeDemandGuardFrameAddress(pattern_id, .match_branch);
        if (runtimeDemandGuardFrameStackContains(self.draft, self.runtime_demand_guard_frames, address))
            return self.runtime_demand_guard_frames;
        // A frame whose proof can never hold exempts nothing; pushing it would
        // only fragment specialization identity across guard contexts.
        const proof = (try self.maybeNodesImpossibilityProof(try self.runtimeDemandGuardsForPattern(pattern_id, node))) orelse
            return self.runtime_demand_guard_frames;
        return try addRuntimeDemandGuardFrame(
            self.draft,
            self.runtime_demand_guard_frames,
            address,
            proof,
        );
    }

    fn withPatternSuccessRuntimeDemandGuardFrame(
        self: *BodyContext,
        guard: PatternSuccessGuard,
    ) Allocator.Error!RuntimeDemandGuardFrameStack {
        const address = self.runtimeDemandGuardFrameAddress(guard.root_pattern, .pattern_success);
        const proof = (try self.maybeNodesImpossibilityProof(try self.runtimeDemandGuardsForPattern(guard.root_pattern, guard.root_node))) orelse
            return self.runtime_demand_guard_frames;
        return try addRuntimeDemandGuardFrame(
            self.draft,
            self.runtime_demand_guard_frames,
            address,
            proof,
        );
    }

    fn withIteratorOneRuntimeDemandGuardFrame(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        step: IterStepShape,
    ) Allocator.Error!RuntimeDemandGuardFrameStack {
        const address = self.runtimeDemandGuardFrameAddress(pattern_id, .iterator_one);
        if (runtimeDemandGuardFrameStackContains(self.draft, self.runtime_demand_guard_frames, address))
            return self.runtime_demand_guard_frames;
        const item_guards = try self.runtimeDemandGuardsForPattern(pattern_id, step.one_item.node);
        const guards = try self.graph.arena().alloc(NodeId, item_guards.len + 1);
        guards[0] = step.one_payload_node;
        @memcpy(guards[1..], item_guards);
        const proof = (try self.maybeNodesImpossibilityProof(guards)) orelse
            return self.runtime_demand_guard_frames;
        return try addRuntimeDemandGuardFrame(
            self.draft,
            self.runtime_demand_guard_frames,
            address,
            proof,
        );
    }

    fn withStatementSuccessRuntimeDemandGuardFrame(
        self: *BodyContext,
        statement_id: checked.CheckedStatementId,
        proof: RuntimeImpossibilityProofId,
    ) Allocator.Error!RuntimeDemandGuardFrameStack {
        // Checked statement IDs are unique within the module, and the owner
        // template is part of the address. Unlike recursive branch frames,
        // statement-success frames therefore cannot already be active.
        return try pushRuntimeDemandGuardFrame(
            self.draft,
            self.runtime_demand_guard_frames,
            self.runtimeDemandGuardFrameAddressRaw(@backingInt(statement_id), .statement_success),
            proof,
        );
    }

    fn runtimeDemandGuardFrameAddresses(
        self: *BodyContext,
    ) Allocator.Error![]const RuntimeDemandGuardFrameAddress {
        const addresses = try self.graph.arena().alloc(RuntimeDemandGuardFrameAddress, self.runtime_demand_guard_frames.depth);
        var address_index = addresses.len;
        var frame_id = self.runtime_demand_guard_frames.head;
        while (frame_id) |id| {
            const frame = runtimeDemandGuardFrame(self.draft, id);
            address_index -= 1;
            addresses[address_index] = frame.address;
            frame_id = frame.parent;
        }
        if (address_index != 0) {
            Common.invariant("runtime-demand guard stack length did not match its parent chain");
        }
        return addresses;
    }

    fn runtimeDemandGuardsForPattern(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
    ) Allocator.Error![]const NodeId {
        var guards = std.ArrayList(NodeId).empty;
        defer guards.deinit(self.allocator);
        var seen = collections.DenseMap(NodeId, void).init(self.allocator);
        defer seen.deinit();
        var active = std.AutoHashMap(PatternNodeVisit, void).init(self.allocator);
        defer active.deinit();
        // The pattern is walked in source order from an explicit work list;
        // a pattern/node pair repeated on the current path is an invariant
        // violation, since every descent must advance.
        var pending: std.ArrayListUnmanaged(PatternBinderVisit) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, .{ .visit = .{ .pattern = pattern_id, .node = node } });
        while (pending.pop()) |item| switch (item) {
            .exit => |key| _ = active.remove(key),
            .visit => |key| {
                if (active.contains(key)) {
                    Common.invariant("runtime demand guard walk repeated an active pattern/node visit");
                }
                try active.put(key, {});
                try pending.append(self.allocator, .{ .exit = key });
                const start = pending.items.len;
                try self.collectRuntimeDemandGuardsStep(key.pattern, key.node, &guards, &seen, &pending);
                std.mem.reverse(PatternBinderVisit, pending.items[start..]);
            },
        };
        return try self.graph.arena().dupe(NodeId, guards.items);
    }

    /// Record one pattern's demand guard; its subpatterns go on `pending`
    /// with the graph nodes they inspect.
    fn collectRuntimeDemandGuardsStep(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
        guards: *std.ArrayList(NodeId),
        seen: *collections.DenseMap(NodeId, void),
        pending: *std.ArrayListUnmanaged(PatternBinderVisit),
    ) Allocator.Error!void {
        const seen_entry = try seen.getOrPut(node);
        if (!seen_entry.found_existing) try guards.append(self.allocator, node);

        const pattern = self.view.bodies.pattern(pattern_id);
        switch (pattern.data) {
            .applied_tag => |tag| {
                if ((try self.graph.content(node)) == .named) {
                    const backing = (try self.graph.namedNodes(node)).backing orelse
                        Common.invariant("nominal tag demand guard had no runtime backing");
                    if (backing.node == node) Common.invariant("nominal tag demand guard backing did not advance");
                    return try self.queuePatternBinderVisit(pending, pattern_id, backing.node);
                }
                const name = try self.tagName(self.view, tag.name);
                for (tag.args, 0..) |arg, payload_index| {
                    try self.queuePatternBinderVisit(pending, arg, try self.graph.tagPayloadNode(node, name, payload_index));
                }
            },
            .nominal => |nominal| {
                const backing = (try self.graph.namedNodes(node)).backing orelse
                    Common.invariant("nominal demand guard had no runtime backing");
                if (backing.node == node) Common.invariant("nominal demand guard backing did not advance");
                try self.queuePatternBinderVisit(pending, nominal.backing_pattern, backing.node);
            },
            .record_destructure => |destructs| {
                if ((try self.graph.content(node)) == .named) {
                    const backing = (try self.graph.namedNodes(node)).backing orelse
                        Common.invariant("nominal record demand guard had no runtime backing");
                    if (backing.node == node) Common.invariant("nominal record demand guard backing did not advance");
                    return try self.queuePatternBinderVisit(pending, pattern_id, backing.node);
                }
                for (destructs) |destruct| {
                    const child = switch (destruct.kind) {
                        .required, .sub_pattern => |child| child,
                        .rest => |rest| {
                            if (self.patternIsIgnored(rest)) continue;
                            const rest_node = try self.recordRestNodeForPattern(node, destructs, rest);
                            try self.queuePatternBinderVisit(pending, rest, rest_node);
                            continue;
                        },
                    };
                    // A destructured OPTIONAL field's sub-pattern runs in
                    // Try space (its own checked-type node), not against the
                    // record's tagged slot node—mirror the walk the
                    // binder registration and pattern lowering use.
                    if ((try self.recordDestructFieldKind(pattern.ty, destruct)) == .optional) {
                        try self.queuePatternBinderVisit(pending, child, try self.instNode(self.view.bodies.pattern(child).ty));
                        continue;
                    }
                    const name = try self.recordFieldName(self.view, destruct.label);
                    try self.queuePatternBinderVisit(pending, child, try self.graph.recordFieldNode(node, name));
                }
            },
            .list => |list| {
                if (list.patterns.len != 0) {
                    const elem = try self.graph.listElementNode(node);
                    const elem_seen = try seen.getOrPut(elem);
                    if (!elem_seen.found_existing) try guards.append(self.allocator, elem);
                    for (list.patterns) |child| {
                        try self.queuePatternBinderVisit(pending, child, elem);
                    }
                }
                if (list.rest) |rest| {
                    if (rest.pattern) |rest_pattern| {
                        try self.queuePatternBinderVisit(pending, rest_pattern, node);
                    }
                }
            },
            .tuple => |items| {
                if ((try self.graph.content(node)) == .named) {
                    const backing = (try self.graph.namedNodes(node)).backing orelse
                        Common.invariant("nominal tuple demand guard had no runtime backing");
                    if (backing.node == node) Common.invariant("nominal tuple demand guard backing did not advance");
                    return try self.queuePatternBinderVisit(pending, pattern_id, backing.node);
                }
                const item_nodes = try self.graph.tupleItemNodes(node);
                if (items.len != item_nodes.len) Common.invariant("tuple demand guard arity differed from graph tuple arity");
                for (items, item_nodes) |item, item_node| {
                    try self.queuePatternBinderVisit(pending, item, item_node);
                }
            },
            .as => |as| try self.queuePatternBinderVisit(pending, as.pattern, node),
            .str_interpolation => |str| {
                for (str.steps) |step| {
                    if (step.capture) |capture| {
                        try self.queuePatternBinderVisit(pending, capture, node);
                    }
                }
            },
            .pending,
            .assign,
            .numeral_literal,
            .str_literal,
            .underscore,
            .runtime_error,
            => {},
        }
    }

    /// Save every binder of `pattern_id` in the order its binders were bound:
    /// an `as` binder after its subpattern's.
    fn savePatternBinders(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        saved: *std.ArrayList(BinderRestore),
    ) Allocator.Error!void {
        const Step = union(enum) { pattern: checked.CheckedPatternId, binder: checked.PatternBinderId };
        var pending: std.ArrayListUnmanaged(Step) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, .{ .pattern = pattern_id });
        while (pending.pop()) |step| {
            const next_pattern = switch (step) {
                .binder => |binder| {
                    try self.saveBinder(binder, saved);
                    continue;
                },
                .pattern => |next| next,
            };
            const start = pending.items.len;
            switch (self.view.bodies.pattern(next_pattern).data) {
                .assign => |binder| try self.saveBinder(binder, saved),
                .as => |as| {
                    try pending.append(self.allocator, .{ .pattern = as.pattern });
                    try pending.append(self.allocator, .{ .binder = as.binder });
                },
                .applied_tag => |tag| for (tag.args) |arg| try pending.append(self.allocator, .{ .pattern = arg }),
                .nominal => |nominal| try pending.append(self.allocator, .{ .pattern = nominal.backing_pattern }),
                .record_destructure => |destructs| {
                    for (destructs) |destruct| {
                        const child = switch (destruct.kind) {
                            .required, .sub_pattern, .rest => |child_pattern| child_pattern,
                        };
                        try pending.append(self.allocator, .{ .pattern = child });
                    }
                },
                .list => |list| {
                    for (list.patterns) |child| try pending.append(self.allocator, .{ .pattern = child });
                    if (list.rest) |rest| if (rest.pattern) |rest_pattern| try pending.append(self.allocator, .{ .pattern = rest_pattern });
                },
                .tuple => |items| for (items) |child| try pending.append(self.allocator, .{ .pattern = child }),
                .str_interpolation => |str| {
                    for (str.steps) |str_step| {
                        if (str_step.capture) |capture| try pending.append(self.allocator, .{ .pattern = capture });
                    }
                },
                .pending,
                .numeral_literal,
                .str_literal,
                .underscore,
                .runtime_error,
                => {},
            }
            std.mem.reverse(Step, pending.items[start..]);
        }
    }

    fn saveBinder(
        self: *BodyContext,
        binder: checked.PatternBinderId,
        saved: *std.ArrayList(BinderRestore),
    ) Allocator.Error!void {
        for (saved.items) |item| {
            if (item.binder == binder) return;
        }
        try saved.append(self.allocator, .{
            .binder = binder,
            .previous = self.binders.get(binder),
        });
    }

    fn applyAlternativeBinderRemaps(
        self: *BodyContext,
        remaps: []const checked.CheckedAlternativeBinderRemap,
    ) Allocator.Error!void {
        for (remaps) |remap| {
            const local = self.binders.get(remap.candidate_binder) orelse
                Common.invariant("match alternative binder remap referenced an unbound candidate binder");
            // All alternatives implement the arm's one checked capture slot.
            // Preserve each local's separate runtime identity and lexical binder.
            self.draft.locals.items[@backingInt(local)].checked_capture_id =
                checked.CaptureId.fromBinder(remap.representative_binder);
            try self.binders.put(remap.representative_binder, local);
        }
    }

    fn restoreBinders(self: *BodyContext, saved: []const BinderRestore) void {
        var index = saved.len;
        while (index > 0) {
            index -= 1;
            if (saved[index].previous) |previous| {
                self.binders.restore(saved[index].binder, previous);
            } else {
                _ = self.binders.remove(saved[index].binder);
            }
        }
    }

    /// Start from the exact specialized request so branch constructors retain
    /// its type constraints before selecting nested-callable evidence. Producer
    /// selection may replace `selected` with a distinct private representation;
    /// `declared` remains the outer interface, including when it is immutable.
    const ControlFlowResultSelection = struct {
        declared: DraftTypeCell,
        selected: DraftTypeCell,
        has_value: bool = false,
    };

    /// Discover producer-authored representation evidence before emitting any
    /// branch. Public-only evidence does not constrain the selection: every
    /// inhabited branch will consume the final selected request during the
    /// subsequent emission pass. Generated-private evidence is joined now, so
    /// source order cannot make an already-emitted branch authoritative.
    fn prepareControlFlowResultSelection(
        self: *BodyContext,
        selection: *ControlFlowResultSelection,
        checked_value: checked.CheckedExprId,
    ) Allocator.Error!void {
        const selected_node = try selection.selected.toGraphNode(self.graph);
        const produced_node = (try self.controlFlowResultEvidenceNode(checked_value, selected_node)) orelse return;
        if (!try self.graph.containsGeneratedPrivate(produced_node)) return;

        try selectRequestRepresentation(self.graph, selected_node, produced_node);
        const selected_private = try self.graph.containsGeneratedPrivate(selected_node);
        const produced_private = try self.graph.containsGeneratedPrivate(produced_node);
        if (selected_private == produced_private) return;
        if (!selected_private and produced_private) {
            selection.selected = DraftTypeCell.fromGraphNode(produced_node);
            return;
        }
        Common.invariant("control-flow representation prepass lost generated-private evidence");
    }

    /// Resolve the exact result evidence of a branch producer against the
    /// shared live request. This is the node-native counterpart of call-
    /// argument evidence: it deliberately keeps the expected graph cell live
    /// so recursive producers see the same fixed point during discovery and
    /// emission.
    fn controlFlowResultEvidenceNode(
        self: *BodyContext,
        value: checked.CheckedExprId,
        expected_node: NodeId,
    ) Allocator.Error!?NodeId {
        // A block without statements produces its final expression's value.
        var checked_value = value;
        while (true) {
            if (self.checkedExprDivergesInLoweredRuntime(checked_value)) return null;
            const expr = self.view.bodies.expr(checked_value);
            switch (expr.data) {
                .block => |block| if (block.statements.len == 0) {
                    checked_value = block.final_expr;
                    continue;
                },
                .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
            }
            break;
        }
        const expr = self.view.bodies.expr(checked_value);
        return switch (expr.data) {
            .call => |call| blk: {
                const target = call.direct_target orelse break :blk null;
                const source_fn_ty = self.directCallInstantiationSourceFnType(target, call.source_fn_ty_payload);
                const fn_node = try self.directCallRequestNode(
                    checked_value,
                    target,
                    call,
                    expr.ty,
                    source_fn_ty,
                    expected_node,
                );
                const fn_nodes = try self.graph.functionNodes(fn_node);
                if (try self.graph.containsGeneratedPrivate(fn_nodes.ret)) break :blk fn_nodes.ret;
                if (!try self.graph.containsIteratorInterface(fn_nodes.ret)) break :blk fn_nodes.ret;

                try self.ensureNestedCallablesAtNodes(call.args, fn_nodes.args);
                const completed = try self.completedDirectCalleeAtNode(checked_value, target, source_fn_ty, fn_node);
                break :blk (try self.graph.functionNodes(completed.fn_node)).ret;
            },
            .dispatch_call => |plan| try self.dispatchResultTypeNodeInPhase(
                expr.ty,
                plan,
                expected_node,
                .expression_lowering,
            ),
            .interpolation => |interpolation| try self.interpolationResultTypeNode(interpolation.plan, expected_node),
            .type_dispatch_call => |plan| try self.dispatchResultTypeNodeInPhase(
                expr.ty,
                plan,
                expected_node,
                .expression_lowering,
            ),
            .method_eq => |plan| try self.dispatchResultTypeNodeInPhase(
                expr.ty,
                plan,
                expected_node,
                .expression_lowering,
            ),
            .field_access => try self.lowerExprTypeNode(checked_value),
            // Lookups are use-sites. Once a generated-private request is
            // selected, branch emission validates the lookup against that
            // request; the prepass must not join the raw stored binding cell.
            .lookup_local,
            .lookup_external,
            .lookup_required,
            => if (try self.graph.containsGeneratedPrivate(expected_node))
                expected_node
            else
                try self.lowerExprTypeNode(checked_value),
            .block => null,
            .tuple, .record, .tag, .nominal, .list => if (self.propagate_constructor_value_evidence)
                try self.exprProducedValueEvidenceNode(checked_value, expected_node)
            else
                null,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .empty_list, .match_, .if_, .empty_record, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .structural_eq, .structural_hash, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => null,
        };
    }

    fn includeControlFlowResult(
        self: *BodyContext,
        selection: *ControlFlowResultSelection,
        value: DraftExprId,
    ) Allocator.Error!void {
        if (self.exprImpossibilityProof(value) != null) return;
        const selected_node = try selection.selected.toGraphNode(self.graph);
        const value_cell = self.exprTypeCell(value);
        const value_node = try value_cell.toGraphNode(self.graph);
        try selectRequestRepresentation(self.graph, selected_node, value_node);

        const selected_private = try self.graph.containsGeneratedPrivate(selected_node);
        const value_private = try self.graph.containsGeneratedPrivate(value_node);
        if (selected_private != value_private) {
            if (!selected_private and value_private) {
                // A finished private producer remains immutable and therefore
                // cannot merge into the live public accumulator. Carry its
                // exact cell forward, then retag earlier branches after the
                // final representation has been selected.
                selection.selected = value_cell;
            } else {
                Common.invariant("control-flow branch could not use its selected runtime representation");
            }
        }
        selection.has_value = true;
        self.draft.exprs.items[@backingInt(value)].ty = selection.selected;
    }

    fn finishControlFlowResultSelection(
        self: *BodyContext,
        selection: ControlFlowResultSelection,
    ) Allocator.Error!DraftTypeCell {
        // A control-flow expression whose every branch terminates never
        // produces a runtime result. Its checked result variable may therefore
        // remain unconstrained, and cannot supply representation evidence for
        // the enclosing continuation's declared result cell.
        if (!selection.has_value) return selection.declared;

        const declared_node = try selection.declared.toGraphNode(self.graph);
        const selected_node = try selection.selected.toGraphNode(self.graph);
        try relateRequestComponent(self.graph, declared_node, selected_node);
        return if (try self.graph.containsGeneratedPrivate(selected_node))
            selection.selected
        else
            selection.declared;
    }

    fn stateMergeBinders(self: *BodyContext, expr_id: checked.CheckedExprId) Allocator.Error![]MergeBinder {
        var reassigned = std.ArrayList(checked.PatternBinderId).empty;
        defer reassigned.deinit(self.allocator);
        try self.collectReassignedBindersInExpr(expr_id, &reassigned);

        var merge_binders = std.ArrayList(MergeBinder).empty;
        errdefer merge_binders.deinit(self.allocator);
        for (reassigned.items) |binder| {
            const before = self.binders.get(binder) orelse continue;
            try merge_binders.append(self.allocator, .{
                .binder = binder,
                .before = before,
                .ty = self.localTypeCell(before),
            });
        }
        return try merge_binders.toOwnedSlice(self.allocator);
    }

    fn stateResultTypeCell(
        self: *BodyContext,
        merge_binders: []const MergeBinder,
        result_cell: DraftTypeCell,
    ) Allocator.Error!DraftTypeCell {
        const nodes = try self.graph.arena().alloc(NodeId, merge_binders.len + 1);
        for (merge_binders, 0..) |merge, index| {
            nodes[index] = try merge.ty.toGraphNode(self.graph);
        }
        nodes[merge_binders.len] = try result_cell.toGraphNode(self.graph);
        return DraftTypeCell.fromGraphNode(try self.graph.newNode(.{ .tuple = nodes }));
    }

    fn unwrapStateResultAtTypeCells(
        self: *BodyContext,
        state_expr: DraftExprId,
        state_cell: DraftTypeCell,
        result_cell: DraftTypeCell,
        merge_binders: []const MergeBinder,
    ) Allocator.Error!DraftExprId {
        const pattern_items = try self.allocator.alloc(DraftPatId, merge_binders.len + 1);
        defer self.allocator.free(pattern_items);
        for (merge_binders, 0..) |merge, index| {
            const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), merge.ty, merge.binder);
            try self.bindLocalName(local, merge.binder);
            try self.binders.put(merge.binder, local);
            pattern_items[index] = try self.addPatWithTypeCell(merge.ty, .{ .bind = local });
        }

        const result_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), result_cell, null);
        pattern_items[merge_binders.len] = try self.addPatWithTypeCell(result_cell, .{ .bind = result_local });
        const bind_pat = try self.addPatWithTypeCell(state_cell, .{ .tuple = try self.addPatSpan(pattern_items) });
        const rest = try self.addExprWithTypeCell(result_cell, .{ .local = result_local });

        return try self.addExprWithTypeCell(result_cell, .{ .let_ = .{
            .bind = bind_pat,
            .value = state_expr,
            .rest = rest,
        } });
    }

    fn stateOnlyTypeCell(
        self: *BodyContext,
        merge_binders: []const MergeBinder,
    ) Allocator.Error!DraftTypeCell {
        if (merge_binders.len == 0) return .{ .sealed = try self.unitType() };
        if (merge_binders.len == 1) return merge_binders[0].ty;
        const nodes = try self.graph.arena().alloc(NodeId, merge_binders.len);
        for (merge_binders, 0..) |merge, index| nodes[index] = try merge.ty.toGraphNode(self.graph);
        return DraftTypeCell.fromGraphNode(try self.graph.newNode(.{ .tuple = nodes }));
    }

    fn composeNestedStateResultAtTypeCells(
        self: *BodyContext,
        nested_state: DraftExprId,
        nested_state_cell: DraftTypeCell,
        result_cell: DraftTypeCell,
        nested_merge_binders: []const MergeBinder,
        outer_state_cell: DraftTypeCell,
        outer_merge_binders: []const MergeBinder,
    ) Allocator.Error!DraftExprId {
        const pattern_items = try self.allocator.alloc(DraftPatId, nested_merge_binders.len + 1);
        defer self.allocator.free(pattern_items);
        for (nested_merge_binders, 0..) |merge, index| {
            const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), merge.ty, merge.binder);
            try self.bindLocalName(local, merge.binder);
            try self.binders.put(merge.binder, local);
            pattern_items[index] = try self.addPatWithTypeCell(merge.ty, .{ .bind = local });
        }

        const result_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), result_cell, null);
        pattern_items[nested_merge_binders.len] = try self.addPatWithTypeCell(result_cell, .{ .bind = result_local });
        const bind_pat = try self.addPatWithTypeCell(
            nested_state_cell,
            .{ .tuple = try self.addPatSpan(pattern_items) },
        );
        const result = try self.addExprWithTypeCell(result_cell, .{ .local = result_local });
        const rest = try self.stateResultTupleExprAtTypeCells(
            outer_state_cell,
            outer_merge_binders,
            result,
        );

        return try self.addExprWithTypeCell(outer_state_cell, .{ .let_ = .{
            .bind = bind_pat,
            .value = nested_state,
            .rest = rest,
        } });
    }

    fn stateResultTupleExprAtTypeCells(
        self: *BodyContext,
        state_cell: DraftTypeCell,
        merge_binders: []const MergeBinder,
        result: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const items = try self.allocator.alloc(DraftExprId, merge_binders.len + 1);
        defer self.allocator.free(items);
        for (merge_binders, 0..) |merge, index| {
            const current = self.binders.get(merge.binder) orelse merge.before;
            items[index] = try self.addExprWithTypeCell(merge.ty, .{ .local = current });
        }
        items[merge_binders.len] = result;
        return try self.addExprWithTypeCell(state_cell, .{ .tuple = try self.addExprSpan(items) });
    }

    fn stateResultAfterValueAtTypeCells(
        self: *BodyContext,
        state_cell: DraftTypeCell,
        result_cell: DraftTypeCell,
        merge_binders: []const MergeBinder,
        value: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), result_cell, null);
        const local_expr = try self.addExprWithTypeCell(result_cell, .{ .local = local });
        return try self.addExprWithTypeCell(state_cell, .{ .let_ = .{
            .bind = try self.addPatWithTypeCell(result_cell, .{ .bind = local }),
            .value = value,
            .rest = try self.stateResultTupleExprAtTypeCells(state_cell, merge_binders, local_expr),
        } });
    }

    fn stateOnlyTupleExprAtTypeCell(
        self: *BodyContext,
        state_cell: DraftTypeCell,
        merge_binders: []const MergeBinder,
    ) Allocator.Error!DraftExprId {
        if (merge_binders.len == 0) return try self.addExprWithTypeCell(state_cell, .unit);
        if (merge_binders.len == 1) {
            const merge = merge_binders[0];
            const current = self.binders.get(merge.binder) orelse merge.before;
            return try self.addExprWithTypeCell(merge.ty, .{ .local = current });
        }
        const items = try self.allocator.alloc(DraftExprId, merge_binders.len);
        defer self.allocator.free(items);
        for (merge_binders, 0..) |merge, index| {
            const current = self.binders.get(merge.binder) orelse merge.before;
            items[index] = try self.addExprWithTypeCell(merge.ty, .{ .local = current });
        }
        return try self.addExprWithTypeCell(state_cell, .{ .tuple = try self.addExprSpan(items) });
    }

    fn stateOnlyPatternAtTypeCell(
        self: *BodyContext,
        state_cell: DraftTypeCell,
        merge_binders: []const MergeBinder,
    ) Allocator.Error!DraftPatId {
        if (merge_binders.len == 0) return try self.addPatWithTypeCell(state_cell, .wildcard);
        if (merge_binders.len == 1) {
            const merge = merge_binders[0];
            const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), merge.ty, merge.binder);
            try self.bindLocalName(local, merge.binder);
            try self.binders.put(merge.binder, local);
            return try self.addPatWithTypeCell(state_cell, .{ .bind = local });
        }
        const pattern_items = try self.allocator.alloc(DraftPatId, merge_binders.len);
        defer self.allocator.free(pattern_items);
        for (merge_binders, 0..) |merge, index| {
            const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), merge.ty, merge.binder);
            try self.bindLocalName(local, merge.binder);
            try self.binders.put(merge.binder, local);
            pattern_items[index] = try self.addPatWithTypeCell(merge.ty, .{ .bind = local });
        }
        return try self.addPatWithTypeCell(state_cell, .{ .tuple = try self.addPatSpan(pattern_items) });
    }

    fn releaseBlockTask(self: *BodyContext, task: *BlockTask) void {
        self.restoreSourceLocation(&task.statement_saved);
        self.allocator.free(task.expanded_merge_binders);
        task.expanded_merge_binders = &.{};
        self.allocator.free(task.recursive_binders);
        task.recursive_binders = &.{};
        self.allocator.free(task.recursive_locals);
        task.recursive_locals = &.{};
        if (task.stage != .start) {
            self.runtime_demand_guard_frames = task.saved_guard_frames;
            self.allocator.free(task.lowered.items);
            task.lowered.items = &.{};
            task.stage = .start;
        }
    }

    /// Lower a block's statements in order, then its tail. Every statement
    /// and the final expression lower as child tasks.
    fn stepBlock(self: *BodyContext, task: *BlockTask, input: ?LowerResult) Allocator.Error!LowerStep {
        switch (task.stage) {
            .start => {
                task.lowered.items = try self.allocator.alloc(DraftStmtId, task.statements.len);
                task.saved_guard_frames = self.runtime_demand_guard_frames;
                task.stage = .statements;
            },
            .statements, .finished => unreachable,
            .uninhabited_statement => {
                task.lowered.termination = .{ .uninhabited = input.?.exprValue() };
                return self.beginBlockTail(task);
            },
            .statement => {
                if (!try self.finishBlockStatement(task, input.?.statementValue())) return self.beginBlockTail(task);
                task.stage = .statements;
            },
            .expanded => {
                try self.finishExpandedPatternStatement(task, input.?.exprValue());
                const termination: StatementTermination = if (task.statement_diverges) .checked_control_transfer else .none;
                if (!try self.finishBlockStatement(task, .{ .stmt = null, .termination = termination })) return self.beginBlockTail(task);
                task.stage = .statements;
            },
            .recursive_direct => {
                const saved_loc = self.builder.current_loc;
                defer self.builder.current_loc = saved_loc;
                const saved_region = self.builder.current_region;
                defer self.builder.current_region = saved_region;
                const region = self.view.bodies.statement(task.statement).source_region;
                self.builder.current_loc = try self.sourceLocFor(region);
                self.builder.current_region = region;
                const value = input.?.exprValue();
                const requested_cell = task.recursive_direct_cell;
                switch (requested_cell) {
                    .sealed => |requested_ty| switch (self.exprTypeCell(value)) {
                        .sealed => |produced_ty| if (!self.sameType(requested_ty, produced_ty)) Common.invariant("recursive declaration value produced a different sealed type"),
                        .graph_node => Common.invariant("recursive declaration value produced a graph-backed type for a sealed request"),
                    },
                    .graph_node => |requested_node| try relateRequestComponent(self.graph, requested_node, try self.exprTypeCell(value).toGraphNode(self.graph)),
                }
                const stmt = try self.addStmt(.{ .let_ = .{ .pat = task.recursive_direct_pat, .value = value, .recursive = true } });
                if (!try self.finishBlockStatement(task, .{ .stmt = stmt, .termination = .none })) return self.beginBlockTail(task);
                task.stage = .statements;
            },
            .final_expr => return self.finishBlockFinal(task, input.?.exprValue()),
            .discarded_final => {
                const final_result = input.?.statementValue();
                if (final_result.stmt) |stmt| try task.lowered.append(self.allocator, stmt);
                task.lowered.termination = final_result.termination;
                return self.finishDiscardingBlock(task);
            },
        }

        while (task.index < task.statements.len) {
            const statement = task.statements[task.index];
            task.index += 1;
            var snapshots: std.ArrayList(DraftStmtId) = .empty;
            defer snapshots.deinit(self.allocator);
            try self.registerLocalAssociatedProcedures(statement, &snapshots);
            for (snapshots.items) |stmt| try task.lowered.append(self.allocator, stmt);
            // Checking records divergence per statement, and marks a block
            // divergent when any statement in it diverges. That output
            // decides whether callers demand the block's own type from its
            // final expression or the effect type from a value that never
            // materializes, so it outranks every statement-local judgement
            // here: a divergent statement transfers control, which makes it
            // observable however little else the statement does, and leaves
            // the rest of the block unreachable.
            const statement_diverges = self.checkedStatementDivergesInLoweredRuntime(statement);
            if (!statement_diverges and !self.checkedStatementHasRuntimeEffect(statement)) continue;
            if (self.blockStatementLocalProcDecl(statement)) |decl| {
                // Declaring a local procedure runs nothing but the snapshots
                // of its reassignable captures.
                if (!self.view.bodies.patternBinder(self.localProcBinder(decl.pattern)).is_scheme_alias) {
                    snapshots.clearRetainingCapacity();
                    try self.registerLocalProc(decl.pattern, decl.expr, statement, &snapshots);
                    for (snapshots.items) |stmt| try task.lowered.append(self.allocator, stmt);
                }
                continue;
            }
            task.statement = statement;
            task.statement_start = task.lowered.len;
            task.statement_diverges = statement_diverges;
            if (!statement_diverges) {
                if (try self.uninhabitedStatementScrutineeStep(statement)) |step| {
                    task.stage = .uninhabited_statement;
                    return step;
                }
            }
            if (!statement_diverges) {
                if (try self.beginRecursiveDeclStatement(task)) |step| {
                    task.stage = .recursive_direct;
                    return step;
                }
            }
            if (try self.beginExpandedPatternStatement(task)) |step| {
                task.stage = .expanded;
                return step;
            }
            task.stage = .statement;
            return requestLowerTask(self, .{ .statement = .{ .statement = statement, .diverges = statement_diverges } });
        }
        return self.beginBlockTail(task);
    }

    /// Lower the block's tail once its statements are lowered.
    fn beginBlockTail(self: *BodyContext, task: *BlockTask) Allocator.Error!LowerStep {
        task.stage = .final_expr;
        switch (task.tail) {
            .value => {},
            .loop_continue, .state_only => {
                if (!statementTerminationIsNone(task.lowered.termination)) return self.finishDiscardingBlock(task);
                task.stage = .discarded_final;
                return requestLowerTask(self, .{ .discarded = .{ .expr = task.final_expr } });
            },
            .state_result => |tail| {
                const state_cell = tail.state.state_cell;
                switch (task.lowered.termination) {
                    .uninhabited => |scrutinee| return self.finishStatementsBlock(task, try self.zeroBranchMatchAtTypeCell(scrutinee, state_cell)),
                    .checked_control_transfer => return self.finishStatementsBlock(task, try self.addExprWithTypeCell(state_cell, .@"unreachable")),
                    .none => {},
                }
                if (try self.nodeIsProvenUninhabited(tail.result_node)) {
                    task.final_wrap = state_cell;
                    return uninhabitedScrutineeStep(self, task.final_expr, tail.state.result_cell);
                }
                return requestLowerTask(self, .{ .value_then_state = .{
                    .body = task.final_expr,
                    .result_cell = tail.state.result_cell,
                    .state_cell = state_cell,
                    .merge_binders = tail.state.merge_binders,
                } });
            },
        }
        if (task.typed) |ty| {
            switch (task.lowered.termination) {
                .checked_control_transfer => return self.finishBlockValue(task, try self.unreachableAfterTerminatingStatementExpr(ty)),
                .uninhabited => |scrutinee| return self.finishBlockValue(task, try self.zeroBranchMatch(scrutinee, ty)),
                .none => {
                    if (self.checkedExprDivergesInLoweredRuntime(task.final_expr)) {
                        return divergentStep(self, task.final_expr, .{ .at_type = ty });
                    }
                    if (try self.typeIsProvenUninhabited(ty)) {
                        task.final_wrap = .{ .sealed = ty };
                        return uninhabitedScrutineeStep(self, task.final_expr, .{ .sealed = ty });
                    }
                    return requestLowerChild(self, task.final_expr, .{ .sealed = ty });
                },
            }
        }
        task.result_node = try task.result_cell.toGraphNode(self.graph);
        const result_node = task.result_node;
        switch (task.lowered.termination) {
            .checked_control_transfer => return self.finishBlockValue(task, try self.addExprWithTypeCell(task.result_cell, .@"unreachable")),
            .uninhabited => |scrutinee| return self.finishBlockValue(task, try self.addExprWithTypeCell(task.result_cell, .{ .match_ = .{
                .scrutinee = scrutinee,
                .branches = try self.addBranchSpan(&.{}),
                .comptime_site = null,
            } })),
            .none => {
                if (!self.checkedExprDivergesInLoweredRuntime(task.final_expr) and try self.nodeIsProvenUninhabited(result_node)) {
                    task.final_wrap = task.result_cell;
                    return uninhabitedScrutineeStep(self, task.final_expr, task.result_cell);
                }
                return requestLowerChild(self, task.final_expr, task.result_cell);
            },
        }
    }

    fn finishBlockFinal(self: *BodyContext, task: *BlockTask, lowered: DraftExprId) Allocator.Error!LowerStep {
        const final_expr = if (task.final_wrap) |cell|
            try self.zeroBranchMatchAtTypeCell(lowered, cell)
        else
            lowered;
        return switch (task.tail) {
            .value => self.finishBlockValue(task, final_expr),
            .state_result => self.finishStatementsBlock(task, final_expr),
            .loop_continue, .state_only => unreachable,
        };
    }

    /// A block whose final expression was discarded ends in its tail's
    /// continuation once its statements run normally.
    fn finishDiscardingBlock(self: *BodyContext, task: *BlockTask) Allocator.Error!LowerStep {
        const cell = task.result_cell;
        const statements = try self.addStmtSpan(task.lowered.items[0..task.lowered.len]);
        const final_expr = switch (task.lowered.termination) {
            .uninhabited => |scrutinee| try self.zeroBranchMatchAtTypeCell(scrutinee, cell),
            .checked_control_transfer => try self.addExprWithTypeCell(cell, .@"unreachable"),
            .none => switch (task.tail) {
                .loop_continue => |loop| if (loop.rest_expr) |rest_expr|
                    try self.continueWithState(cell, rest_expr, loop.carries)
                else
                    try self.continueWithCurrentState(cell, loop.carries),
                .state_only => |state| try self.stateOnlyTupleExprAtTypeCell(cell, state.merge_binders),
                .value, .state_result => unreachable,
            },
        };
        return loweredExprStep(try self.addExprWithTypeCell(cell, .{ .block = .{
            .statements = statements,
            .final_expr = final_expr,
        } }));
    }

    fn finishStatementsBlock(self: *BodyContext, task: *BlockTask, final_expr: DraftExprId) Allocator.Error!LowerStep {
        return loweredExprStep(try self.addExprWithTypeCell(task.result_cell, .{ .block = .{
            .statements = try self.addStmtSpan(task.lowered.items[0..task.lowered.len]),
            .final_expr = final_expr,
        } }));
    }

    fn enterStatementSourceLocation(self: *BodyContext, source_region: base.Region) Allocator.Error!SavedSourceLocation {
        const saved: SavedSourceLocation = .{
            .loc = self.builder.current_loc,
            .region = self.builder.current_region,
        };
        self.builder.current_loc = try self.sourceLocFor(source_region);
        self.builder.current_region = source_region;
        return saved;
    }

    /// Record one lowered statement; returns false when it ends the block.
    fn finishBlockStatement(self: *BodyContext, task: *BlockTask, result: LoweredStatement) Allocator.Error!bool {
        self.restoreSourceLocation(&task.statement_saved);
        if (result.stmt) |stmt| try task.lowered.append(self.allocator, stmt);
        if (task.recursive_binders.len != 0) {
            if (!statementTerminationIsNone(result.termination)) Common.invariant("non-divergent recursive declaration terminated its block");
            try self.finishRecursiveDeclStatement(task);
        }
        {
            var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
            defer timing_scope.end();
            if (try self.anyStmtSpanImpossibilityProof(task.lowered.items[task.statement_start..task.lowered.len])) |proof| {
                self.runtime_demand_guard_frames = try self.withStatementSuccessRuntimeDemandGuardFrame(task.statement, proof);
            }
        }
        switch (result.termination) {
            .none => return true,
            .checked_control_transfer, .uninhabited => {
                task.lowered.termination = result.termination;
                return false;
            },
        }
    }

    fn finishBlockValue(self: *BodyContext, task: *BlockTask, final_expr: DraftExprId) Allocator.Error!LowerStep {
        if (task.typed) |ty| {
            const data: BodyExprData = .{ .block = .{
                .statements = try self.addStmtSpan(task.lowered.items[0..task.lowered.len]),
                .final_expr = final_expr,
            } };
            if (task.as_data) return .{ .ret = .{ .data = data } };
            return loweredExprStep(try self.addExpr(.{ .ty = ty, .data = data }));
        }
        // A block is representation-transparent: preserve an exact
        // producer-authored runtime representation from its final expression.
        // Ordinary public results continue to use the enclosing request cell,
        // whose graph may still be unresolved at this draft boundary.
        const result_node = task.result_node;
        const value_cell = switch (task.lowered.termination) {
            .none => blk: {
                const produced_cell = self.exprTypeCell(final_expr);
                const produced_node = try produced_cell.toGraphNode(self.graph);
                break :blk if (try self.resultCompletesRequest(result_node, produced_node) or
                    try self.graph.containsGeneratedPrivate(produced_node))
                    produced_cell
                else
                    task.result_cell;
            },
            .checked_control_transfer, .uninhabited => task.result_cell,
        };
        const block = try self.addExprWithTypeCell(value_cell, .{ .block = .{
            .statements = try self.addStmtSpan(task.lowered.items[0..task.lowered.len]),
            .final_expr = final_expr,
        } });
        return loweredExprStep(block);
    }

    const StatementTermination = union(enum) {
        none,
        checked_control_transfer,
        uninhabited: DraftExprId,
    };

    const LoweredStatements = struct {
        items: []DraftStmtId,
        len: usize,
        termination: StatementTermination,

        fn append(self: *LoweredStatements, allocator: Allocator, stmt: DraftStmtId) Allocator.Error!void {
            if (self.len == self.items.len) {
                const grown = try allocator.realloc(self.items, self.items.len + 1);
                self.items = grown;
            }
            self.items[self.len] = stmt;
            self.len += 1;
        }
    };

    /// A statement whose value is proven uninhabited ends its block: lower
    /// the value as a child scrutinee. Returns null for every other
    /// statement.
    fn uninhabitedStatementScrutineeStep(
        self: *BodyContext,
        statement_id: checked.CheckedStatementId,
    ) Allocator.Error!?LowerStep {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
        defer timing_scope.end();
        const statement = self.view.bodies.statement(statement_id);
        const expr_id = switch (statement.data) {
            .decl => |decl| if (self.statementDeclIsLocalProc(decl.pattern, decl.expr)) return null else decl.expr,
            .promoted_proc => return null,
            inline .var_, .reassign => |decl| decl.expr,
            .expr, .dbg => |expr| expr,
            .expect => |expr| if (self.builder.inline_expects == .run) expr else return null,
            .pending, .var_uninitialized, .crash, .for_, .while_, .infinite_loop, .breakable_loop, .break_, .return_, .import_, .alias_decl, .where_alias_decl, .nominal_decl, .type_anno, .type_var_alias, .runtime_error => return null,
        };
        // An explicit checked runtime error emits a crash and has a deliberately
        // erroneous source type. Probing its type node here would demand an
        // instantiation checking intentionally did not produce.
        if (self.view.bodies.expr(expr_id).data == .runtime_error) return null;
        if (try self.graphFreeResultTypeForExpr(expr_id)) |ty| {
            if (!try self.typeIsProvenUninhabited(ty)) return null;
            return uninhabitedScrutineeStep(self, expr_id, .{ .sealed = ty });
        }
        const node = try self.lowerExprTypeNode(expr_id);
        if (!try self.nodeIsProvenUninhabited(node)) return null;
        return uninhabitedScrutineeStep(self, expr_id, DraftTypeCell.fromGraphNode(node));
    }

    fn statementTerminationIsNone(termination: StatementTermination) bool {
        return switch (termination) {
            .none => true,
            .checked_control_transfer, .uninhabited => false,
        };
    }

    /// Reserve a recursive declaration's binders before its initializer lowers.
    fn beginRecursiveDeclStatement(self: *BodyContext, task: *BlockTask) Allocator.Error!?LowerStep {
        const statement = self.view.bodies.statement(task.statement);
        const decl = switch (statement.data) {
            .decl => |decl| decl,
            .pending, .promoted_proc, .var_, .var_uninitialized, .reassign, .crash, .dbg, .expr, .expect, .for_, .while_, .infinite_loop, .breakable_loop, .break_, .return_, .import_, .alias_decl, .where_alias_decl, .nominal_decl, .type_anno, .type_var_alias, .runtime_error => return null,
        };
        if (!decl.recursive or self.statementDeclIsLocalProc(decl.pattern, decl.expr)) return null;
        const saved_loc = self.builder.current_loc;
        defer self.builder.current_loc = saved_loc;
        const saved_region = self.builder.current_region;
        defer self.builder.current_region = saved_region;
        self.builder.current_loc = try self.sourceLocFor(statement.source_region);
        self.builder.current_region = statement.source_region;
        const merge_binders: []MergeBinder = switch (self.view.bodies.expr(decl.expr).data) {
            .if_, .match_, .for_ => try self.stateMergeBinders(decl.expr),
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .hosted_lambda, .run_low_level => try self.allocator.alloc(MergeBinder, 0),
        };
        defer self.allocator.free(merge_binders);
        if (merge_binders.len == 0 and self.view.bodies.pattern(decl.pattern).data == .assign) {
            const pattern = decl.pattern;
            const expr = decl.expr;
            const requested_cell: DraftTypeCell = if (try self.graphFreeResultTypeForExpr(expr)) |ty|
                .{ .sealed = ty }
            else
                DraftTypeCell.fromGraphNode(try self.lowerExprTypeNode(expr));
            if (requested_cell == .graph_node) {
                try self.constrainCheckedInterfaceToCell(self.view.bodies.pattern(pattern).ty, requested_cell);
            }
            const pat = try self.lowerShapeFreePatternAtCell(pattern, requested_cell);
            task.recursive_direct_pat = pat;
            task.recursive_direct_cell = requested_cell;
            return requestLowerChild(self, expr, requested_cell);
        }
        var pattern_binders = std.ArrayList(BinderRestore).empty;
        defer pattern_binders.deinit(self.allocator);
        try self.savePatternBinders(decl.pattern, &pattern_binders);
        task.recursive_binders = try self.allocator.alloc(checked.PatternBinderId, pattern_binders.items.len + merge_binders.len);
        const binders = task.recursive_binders;
        task.recursive_locals = try self.allocator.alloc(DraftLocalId, binders.len);
        const recursive_locals = task.recursive_locals;
        for (pattern_binders.items, 0..) |item, index| {
            const cell = DraftTypeCell.fromGraphNode(try self.instNode(checkedBinderType(self.view, item.binder)));
            const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), cell, item.binder);
            try self.bindLocalName(local, item.binder);
            try self.binders.put(item.binder, local);
            binders[index] = item.binder;
            recursive_locals[index] = local;
        }
        // A reassigned `var` keeps its previous version while the value is
        // lowered; only the statement's result version is recursive-bound.
        for (merge_binders, pattern_binders.items.len..) |merge, index| {
            const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), merge.ty, merge.binder);
            try self.bindLocalName(local, merge.binder);
            binders[index] = merge.binder;
            recursive_locals[index] = local;
        }

        return null;
    }

    /// Wrap the initializer's ordinary statements in its recursive tuple binding.
    fn finishRecursiveDeclStatement(self: *BodyContext, task: *BlockTask) Allocator.Error!void {
        const saved_loc = self.builder.current_loc;
        defer self.builder.current_loc = saved_loc;
        const saved_region = self.builder.current_region;
        defer self.builder.current_region = saved_region;
        const region = self.view.bodies.statement(task.statement).source_region;
        self.builder.current_loc = try self.sourceLocFor(region);
        self.builder.current_region = region;
        const binders = task.recursive_binders;
        const recursive_locals = task.recursive_locals;
        defer {
            self.allocator.free(task.recursive_binders);
            task.recursive_binders = &.{};
            self.allocator.free(task.recursive_locals);
            task.recursive_locals = &.{};
        }
        const item_nodes = try self.graph.arena().alloc(NodeId, binders.len);
        const items = try self.allocator.alloc(DraftExprId, binders.len);
        defer self.allocator.free(items);
        const pats = try self.allocator.alloc(DraftPatId, binders.len);
        defer self.allocator.free(pats);
        for (binders, recursive_locals, 0..) |binder, recursive_local, index| {
            const bound = self.binders.get(binder) orelse
                Common.invariant("recursive declaration lowering did not bind one of its binders");
            const bound_cell = self.localTypeCell(bound);
            const recursive_cell = self.localTypeCell(recursive_local);
            item_nodes[index] = try bound_cell.toGraphNode(self.graph);
            try relateRequestComponent(self.graph, try recursive_cell.toGraphNode(self.graph), item_nodes[index]);
            items[index] = try self.addExprWithTypeCell(bound_cell, .{ .local = bound });
            pats[index] = try self.addPatWithTypeCell(recursive_cell, .{ .bind = recursive_local });
            try self.binders.put(binder, recursive_local);
        }
        const tuple_cell = DraftTypeCell.fromGraphNode(try self.graph.newNode(.{ .tuple = item_nodes }));
        const tuple = try self.addExprWithTypeCell(tuple_cell, .{ .tuple = try self.addExprSpan(items) });
        const value = try self.addExprWithTypeCell(tuple_cell, .{ .block = .{
            .statements = try self.addStmtSpan(task.lowered.items[task.statement_start..task.lowered.len]),
            .final_expr = tuple,
        } });
        task.lowered.len = task.statement_start;
        try task.lowered.append(self.allocator, try self.addStmt(.{ .let_ = .{
            .pat = try self.addPatWithTypeCell(tuple_cell, .{ .tuple = try self.addPatSpan(pats) }),
            .value = value,
            .recursive = true,
        } }));
    }

    /// Start a pattern statement that binds several block statements, its
    /// value lowering as a child. Returns null for every other statement.
    fn beginExpandedPatternStatement(self: *BodyContext, task: *BlockTask) Allocator.Error!?LowerStep {
        const statement = self.view.bodies.statement(task.statement);
        const pattern, const expr = switch (statement.data) {
            .decl => |decl| blk: {
                if (self.statementDeclIsLocalProc(decl.pattern, decl.expr)) return null;
                break :blk .{ decl.pattern, decl.expr };
            },
            .promoted_proc => return null,
            inline .var_, .reassign => |decl| .{ decl.pattern, decl.expr },
            .pending, .var_uninitialized, .crash, .dbg, .expr, .expect, .for_, .while_, .infinite_loop, .breakable_loop, .break_, .return_, .import_, .alias_decl, .where_alias_decl, .nominal_decl, .type_anno, .type_var_alias, .runtime_error => return null,
        };
        task.statement_saved = try self.enterStatementSourceLocation(statement.source_region);
        errdefer self.restoreSourceLocation(&task.statement_saved);

        if (try self.beginStatefulControlPatternStatement(task, pattern, expr)) |step| return step;

        const destructs = switch (self.view.bodies.pattern(pattern).data) {
            .record_destructure => |destructs| destructs,
            .pending, .assign, .as, .applied_tag, .nominal, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => {
                self.restoreSourceLocation(&task.statement_saved);
                return null;
            },
        };
        // Expand into per-field `let` STATEMENTS both for an explicit rest
        // binder and for any OPTIONAL destructured field: statement-level
        // lets keep the binders bound for the rest of the block, whereas the
        // materialized statement-EXPRESSION route scopes its internal binds
        // to that expression (the lift capture analysis is lexical), which
        // would leave later statements reading free locals.
        if (!self.recordDestructsNeedExplicitRest(destructs) and
            !try self.recordDestructsHaveOptionalField(self.view.bodies.pattern(pattern).ty, destructs))
        {
            self.restoreSourceLocation(&task.statement_saved);
            return null;
        }

        const value_node = try self.lowerExprTypeNode(expr);
        const value_cell = DraftTypeCell.fromGraphNode(value_node);
        try self.constrainCheckedInterfaceToCell(self.view.bodies.pattern(pattern).ty, value_cell);
        task.expanded = .{ .record = .{
            .pattern = pattern,
            .destructs = destructs,
            .value_node = value_node,
            .value_cell = value_cell,
        } };
        return requestLowerChild(self, expr, value_cell);
    }

    /// A statement-position `if`/`match`/`for` can both produce the
    /// statement value and reassign surrounding binders. Keep that nested
    /// state tuple intact until the statement destructures it. The
    /// reassigned locals and the result local are then bound by an ordinary
    /// block statement, so they remain in scope for every later statement
    /// and loop back edge.
    fn beginStatefulControlPatternStatement(
        self: *BodyContext,
        task: *BlockTask,
        pattern: checked.CheckedPatternId,
        expr_id: checked.CheckedExprId,
    ) Allocator.Error!?LowerStep {
        switch (self.view.bodies.expr(expr_id).data) {
            .if_, .match_, .for_ => {},
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .hosted_lambda, .run_low_level => return null,
        }

        task.expanded_merge_binders = try self.stateMergeBinders(expr_id);
        const merge_binders = task.expanded_merge_binders;
        if (merge_binders.len == 0) {
            self.allocator.free(task.expanded_merge_binders);
            task.expanded_merge_binders = &.{};
            return null;
        }

        const value_cell = DraftTypeCell.fromGraphNode(try self.lowerExprTypeNode(expr_id));
        try self.constrainCheckedInterfaceToCell(self.view.bodies.pattern(pattern).ty, value_cell);
        const state_cell = try self.stateResultTypeCell(merge_binders, value_cell);
        task.expanded = .{ .stateful = .{
            .pattern = pattern,
            .value_cell = value_cell,
            .state_cell = state_cell,
        } };
        if (self.view.bodies.expr(expr_id).data == .for_) {
            return requestLowerTask(self, .{ .value_then_state = .{
                .body = expr_id,
                .result_cell = value_cell,
                .state_cell = state_cell,
                .merge_binders = merge_binders,
            } });
        }
        return self.controlFlowOutputStep(expr_id, value_cell, .{ .state_result = .{
            .result_cell = value_cell,
            .state_cell = state_cell,
            .merge_binders = merge_binders,
        } });
    }

    /// Bind an expanded pattern statement's lowered value as block statements.
    fn finishExpandedPatternStatement(self: *BodyContext, task: *BlockTask, value: DraftExprId) Allocator.Error!void {
        const statement = self.view.bodies.statement(task.statement);
        const lowered = &task.lowered;
        switch (task.expanded) {
            .record => |record| {
                const pattern = record.pattern;
                const value_cell = record.value_cell;
                const source_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), value_cell, null);
                try lowered.append(self.allocator, try self.addStmt(.{ .let_ = .{
                    .pat = try self.addPatWithTypeCell(value_cell, .{ .bind = source_local }),
                    .value = value,
                } }));

                const source_expr = try self.addExprWithTypeCell(value_cell, .{ .local = source_local });
                const comptime_site = if (self.shouldRecordComptimeSite(.destructure) and try self.patternCanMiss(pattern))
                    try self.addComptimeSite(.destructure, statement.source_region, self.view.exhaustiveness_sites.lookupByDestructurePattern(pattern), &.{})
                else
                    null;
                try self.appendRecordRestPatternStatements(
                    source_expr,
                    record.value_node,
                    self.view.bodies.pattern(pattern).ty,
                    record.destructs,
                    lowered,
                    comptime_site,
                );
            },
            .stateful => |stateful| {
                const pattern = stateful.pattern;
                const value_cell = stateful.value_cell;
                const state_cell = stateful.state_cell;
                const merge_binders = task.expanded_merge_binders;
                const state_pattern_items = try self.allocator.alloc(DraftPatId, merge_binders.len + 1);
                defer self.allocator.free(state_pattern_items);
                for (merge_binders, 0..) |merge, index| {
                    const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), merge.ty, merge.binder);
                    try self.bindLocalName(local, merge.binder);
                    try self.binders.put(merge.binder, local);
                    state_pattern_items[index] = try self.addPatWithTypeCell(merge.ty, .{ .bind = local });
                }
                const result_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), value_cell, null);
                state_pattern_items[merge_binders.len] = try self.addPatWithTypeCell(value_cell, .{ .bind = result_local });
                try lowered.append(self.allocator, try self.addStmt(.{ .let_ = .{
                    .pat = try self.addPatWithTypeCell(
                        state_cell,
                        .{ .tuple = try self.addPatSpan(state_pattern_items) },
                    ),
                    .value = value,
                } }));

                const result = try self.addExprWithTypeCell(value_cell, .{ .local = result_local });
                const comptime_site = if (self.shouldRecordComptimeSite(.destructure) and try self.patternCanMiss(pattern))
                    try self.addComptimeSite(
                        .destructure,
                        statement.source_region,
                        self.view.exhaustiveness_sites.lookupByDestructurePattern(pattern),
                        &.{},
                    )
                else
                    null;
                if (!try self.patternNeedsExplicitBinding(pattern)) {
                    const result_pattern = if (self.patternIsShapeFree(pattern))
                        try self.lowerShapeFreePatternAtCell(pattern, value_cell)
                    else
                        try self.lowerPatternAtNode(pattern, try value_cell.toGraphNode(self.graph));
                    try lowered.append(self.allocator, try self.addStmt(.{ .let_ = .{
                        .pat = result_pattern,
                        .value = result,
                        .comptime_site = comptime_site,
                    } }));
                } else {
                    const unit_ty = try self.unitType();
                    var unit = try self.addExpr(.{ .ty = unit_ty, .data = .unit });
                    unit = try self.wrapComptimeBranch(comptime_site, 0, unit);
                    const miss = if (comptime_site) |site|
                        try self.comptimeExhaustivenessFailedExpr(unit_ty, site)
                    else
                        try self.runtimeCrashExpr(unit_ty, "pattern match failed");
                    try lowered.append(self.allocator, try self.addStmt(.{ .expr = try self.lowerMaterializedPatternValueThen(
                        pattern,
                        result,
                        value_cell,
                        .{ .sealed = unit_ty },
                        .{ .expr = unit },
                        miss,
                        null,
                    ) }));
                }
                self.allocator.free(task.expanded_merge_binders);
                task.expanded_merge_binders = &.{};
            },
        }
    }

    fn appendRecordRestPatternStatements(
        self: *BodyContext,
        value: DraftExprId,
        value_node: NodeId,
        record_checked_ty: checked.CheckedTypeId,
        destructs: []const checked.CheckedRecordDestruct,
        lowered: *LoweredStatements,
        comptime_site: ?DraftComptimeSiteId,
    ) Allocator.Error!void {
        for (destructs) |destruct| {
            switch (destruct.kind) {
                .required, .sub_pattern => |child| {
                    const name = try self.recordFieldName(self.view, destruct.label);
                    const field_node = try self.graph.recordFieldNode(value_node, name);
                    const field_cell = DraftTypeCell.fromGraphNode(field_node);
                    const field_value = try self.addExprWithTypeCell(field_cell, .{
                        .field_access = .{
                            .receiver = value,
                            .segments = try self.draft.addFieldAccessSegmentSpan(&.{.{ .field = name }}),
                        },
                    });
                    if ((try self.recordDestructFieldKind(record_checked_ty, destruct)) == .optional) {
                        // A destructured OPTIONAL field binds its slot
                        // materialized as `Try(v, [MissingField])` (design.md
                        // "Field Kinds").
                        const try_node = try self.instNode(self.view.bodies.pattern(child).ty);
                        const try_value = try self.optionalDestructTryExprAtNode(field_value, field_node, try_node);
                        try lowered.append(self.allocator, try self.addStmt(.{ .let_ = .{
                            .pat = try self.lowerPatternAtNode(child, try_node),
                            .value = try_value,
                            .comptime_site = if (try self.patternCanMiss(child)) comptime_site else null,
                        } }));
                        continue;
                    }
                    try lowered.append(self.allocator, try self.addStmt(.{ .let_ = .{
                        .pat = try self.lowerPatternAtNode(child, field_node),
                        .value = field_value,
                        .comptime_site = if (try self.patternCanMiss(child)) comptime_site else null,
                    } }));
                },
                .rest => |child| {
                    if (self.patternIsIgnored(child)) continue;
                    const rest_node = try self.recordRestNodeForPattern(value_node, destructs, child);
                    const rest_cell = DraftTypeCell.fromGraphNode(rest_node);
                    const rest_value = try self.lowerRecordRestValueWithTypeCell(
                        value,
                        value_node,
                        rest_cell,
                        rest_node,
                    );
                    try lowered.append(self.allocator, try self.addStmt(.{ .let_ = .{
                        .pat = try self.lowerPatternAtNode(child, rest_node),
                        .value = rest_value,
                        .comptime_site = if (try self.patternCanMiss(child)) comptime_site else null,
                    } }));
                },
            }
        }
    }

    /// Whether a declaration's binder is restored from its hoisted root rather
    /// than bound by lowering the declaration. A guarded root's declaration
    /// always stays and evaluates its original right-hand side, so a failure
    /// surfaces at the declaration just as it does without the root.
    fn hoistedBindingRestored(self: *const BodyContext, pattern: checked.CheckedPatternId) bool {
        const entry = self.view.hoisted_constants.lookupByPattern(pattern) orelse return false;
        return !self.view.compile_time_roots.root(entry.root).guarded;
    }

    fn checkedStatementHasRuntimeEffect(self: *BodyContext, statement_id: checked.CheckedStatementId) bool {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
        defer timing_scope.end();
        const raw = @backingInt(statement_id);
        if (raw >= self.view.bodies.statementCount()) {
            Common.invariant("checked runtime statement filter referenced a missing statement");
        }
        return switch (self.view.bodies.statement(@fromBackingInt(@intCast(raw))).data) {
            .decl => |decl| switch (self.view.bodies.expr(decl.expr).data) {
                // A dangling annotation carries diagnostics and checked type
                // information but has no runtime value to bind.
                .anno_only => false,
                .pending => Common.invariant("pending checked declaration reached Monotype runtime statement filter"),
                .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .break_, .return_, .for_, .hosted_lambda, .run_low_level => !self.hoistedBindingRestored(decl.pattern) and
                    !self.view.compile_time_roots.validationResolvedByPattern(decl.pattern),
            },
            .var_,
            .var_uninitialized,
            .reassign,
            .crash,
            .dbg,
            .expr,
            .for_,
            .while_,
            .infinite_loop,
            .breakable_loop,
            .break_,
            .return_,
            .runtime_error,
            => true,
            .expect => self.builder.inline_expects.includesConditions(),
            // A promoted procedure is declared by its own template, not by a
            // statement of the body that contains its source.
            .promoted_proc => false,
            .import_,
            .alias_decl,
            .where_alias_decl,
            .nominal_decl,
            .type_anno,
            .type_var_alias,
            => false,
            .pending => Common.invariant("pending checked statement reached Monotype runtime statement filter"),
        };
    }

    fn exprIdAsDivergentData(self: *BodyContext, expr: DraftExprId) Allocator.Error!BodyExprData {
        return .{ .block = .{
            .statements = try self.addStmtSpan(&[_]DraftStmtId{}),
            .final_expr = expr,
        } };
    }

    fn unreachableAfterTerminatingStatementExpr(self: *BodyContext, ty: Type.TypeId) Allocator.Error!DraftExprId {
        return try self.addExpr(.{ .ty = ty, .data = .@"unreachable" });
    }

    fn checkedInlineExpectMode(self: *const BodyContext) checked.InlineExpectMode {
        return self.builder.inline_expects.continuationMode();
    }

    fn checkedStatementDivergesInLoweredRuntime(self: *BodyContext, statement_id: checked.CheckedStatementId) bool {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
        defer timing_scope.end();
        if (self.specializationDispatchDivergence()) |divergence| {
            const raw = @backingInt(statement_id);
            if (raw >= divergence.statements.len) Common.invariant("specialization divergence referenced a missing checked statement");
            return switch (self.checkedInlineExpectMode()) {
                .run => divergence.statements[raw],
                .omit => divergence.statements_without_inline_expects[raw],
            };
        }
        return self.view.bodies.statementDiverges(statement_id, self.checkedInlineExpectMode());
    }

    fn checkedExprDivergesInLoweredRuntime(self: *BodyContext, expr_id: checked.CheckedExprId) bool {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
        defer timing_scope.end();
        if (self.specializationDispatchDivergence()) |divergence| {
            const raw = @backingInt(expr_id);
            if (raw >= divergence.exprs.len) Common.invariant("specialization divergence referenced a missing checked expression");
            return switch (self.checkedInlineExpectMode()) {
                .run => divergence.exprs[raw],
                .omit => divergence.exprs_without_inline_expects[raw],
            };
        }
        return self.view.bodies.exprDiverges(expr_id, self.checkedInlineExpectMode());
    }

    const LoopCarry = struct {
        binder: checked.PatternBinderId,
        initial_local: DraftLocalId,
        param_local: DraftLocalId,
        ty: DraftTypeCell,
    };

    const LoopContext = struct {
        result_cell: DraftTypeCell,
        carries: []const LoopCarry,
    };

    fn loopExitStatement(self: *BodyContext, expr: DraftExprId, carries: []const LoopCarry, loop_cell: DraftTypeCell) Allocator.Error!DraftStmt {
        if (carries.len == 0) return .{ .expr = expr };
        return .{ .let_ = .{
            .pat = try self.finalCarryPattern(carries, loop_cell),
            .value = expr,
        } };
    }

    const WhileCondition = enum {
        checked,
        always_true,
    };

    fn iteratorMethodLookup(self: *BodyContext, plan: static_dispatch.IteratorDispatchCall) MethodLookup {
        return switch (plan.resolution) {
            .direct_closed, .direct_parametric => |direct| blk: {
                const node = self.view.static_dispatch_plans.evidenceNode(direct.evidence);
                var lookup = self.methodLookupForResolvedTarget(node.target);
                lookup.instantiation = switch (node.instantiation) {
                    .monomorphic => null,
                    .callable, .derived_from_callable => |callable_ty| .{ .view = self.view, .callable_ty = callable_ty },
                };
                break :blk lookup;
            },
            .evidence_dependent => |dependent| if (self.evidence.at(dependent.index)) |entry| switch (selectCallableContract(entry, dependent.callable_contract) orelse entry) {
                .target => |target| .{
                    .view = target.view,
                    .target = target.target,
                    // Shared evidence carries the callable instantiation of
                    // whichever same-name relation the caller materialized.
                    // An independent relation supplies only the target
                    // identity and instantiates against its own plan.
                    .instantiation = if (dependent.independent_callable and selectCallableContract(entry, dependent.callable_contract) == null)
                        null
                    else
                        target.instantiation,
                    .local_proc_context = target.local_proc_context,
                },
                .structural, .from_callable, .from_scheme, .unreachable_value, .checked_error => Common.invariant("iterator dispatch evidence was not a resolved callable target"),
            } else Common.invariant("iterator method evidence was absent from its lexical chain"),
            .direct_pending => Common.invariant("unfinalized iterator direct call reached Monotype"),
            .structural, .checked_error, .@"unreachable" => Common.invariant("iterator dispatch plan resolution was not a callable target"),
        };
    }

    fn instantiateIteratorPlanCallNodeFromCaller(
        self: *BodyContext,
        source_fn_ty: checked.CheckedTypeId,
        caller: *BodyContext,
        operands: []const static_dispatch.IteratorDispatchOperand,
        loop_iterator: ?DraftTypedLocal,
        expected_ret_ty: ?DraftTypeCell,
    ) Allocator.Error!NodeId {
        const function = self.checkedFunctionType(source_fn_ty);
        if (function.args.len != operands.len) {
            Common.invariant("checked iterator dispatch target arity differs from its function type");
        }
        const fn_node = try self.instNode(source_fn_ty);
        const function_nodes = try self.graph.functionNodes(fn_node);
        const request_args = try self.graph.arena().alloc(NodeId, function.args.len);
        var contains_generated_private = false;
        for (function_nodes.args, operands, request_args) |formal_node, operand, *request_arg| {
            switch (operand) {
                .checked_expr => |checked_arg| {
                    const arg_ty = caller.view.bodies.expr(checked_arg).ty;
                    const public_node = try caller.instNode(arg_ty);
                    try relateRequestComponent(self.graph, formal_node, public_node);
                    const evidence_node = if (caller.propagate_constructor_value_evidence)
                        try caller.exprCallArgumentEvidenceNode(checked_arg)
                    else
                        try caller.exprCallResultEvidenceNode(checked_arg, null);
                    if (evidence_node) |evidence| {
                        request_arg.* = try checkedMonoRequestNode(
                            self.graph,
                            public_node,
                            evidence,
                            .exact,
                        );
                    } else {
                        request_arg.* = formal_node;
                    }
                },
                .loop_iterator_state => {
                    const iterator = loop_iterator orelse Common.invariant("iterator .next dispatch reached Monotype without a loop iterator local");
                    request_arg.* = try checkedMonoRequestNode(
                        self.graph,
                        formal_node,
                        try iterator.ty.toGraphNode(self.graph),
                        .exact,
                    );
                },
            }
            if (try self.graph.containsGeneratedPrivate(request_arg.*)) contains_generated_private = true;
        }
        var request_ret = function_nodes.ret;
        if (expected_ret_ty) |expected| {
            const expected_node = try expected.toGraphNode(self.graph);
            request_ret = if (try self.graph.containsGeneratedPrivate(expected_node))
                expected_node
            else
                try checkedMonoRequestNode(self.graph, function_nodes.ret, expected_node, .exact);
            if (try self.graph.containsGeneratedPrivate(request_ret)) contains_generated_private = true;
        }
        if (contains_generated_private) return try self.graphFunctionNode(request_args, request_ret);
        return fn_node;
    }

    fn iteratorOperandNode(
        self: *BodyContext,
        operand: static_dispatch.IteratorDispatchOperand,
        loop_iterator: ?DraftTypedLocal,
    ) Allocator.Error!NodeId {
        return switch (operand) {
            .checked_expr => |expr| try self.lowerExprTypeNode(expr),
            .loop_iterator_state => if (loop_iterator) |iterator|
                try iterator.ty.toGraphNode(self.graph)
            else
                Common.invariant("iterator .next dispatch reached Monotype without a loop iterator local"),
        };
    }

    fn iteratorDonePattern(self: *BodyContext, step: IterStepShape) Allocator.Error!DraftPatId {
        return try self.addPatWithTypeCell(DraftTypeCell.fromGraphNode(step.step_node), .{ .tag = .{
            .name = try self.tagName(self.view, step.done_tag),
            .payloads = .empty(),
        } });
    }

    fn uninhabitedIteratorOneBranch(
        self: *BodyContext,
        step: IterStepShape,
        body: DraftExprId,
    ) Allocator.Error!DraftBranch {
        const payload_pat = try self.addPatWithTypeCell(DraftTypeCell.fromGraphNode(step.one_payload_node), .wildcard);
        const tag_pat = try self.addPatWithTypeCell(DraftTypeCell.fromGraphNode(step.step_node), .{ .tag = .{
            .name = try self.tagName(self.view, step.one_tag),
            .payloads = try self.addPatSpan(&[_]DraftPatId{payload_pat}),
        } });
        return .{ .pat = tag_pat, .body = body };
    }

    fn iteratorSkipBranch(
        self: *BodyContext,
        result_cell: DraftTypeCell,
        step: IterStepShape,
        iterator_cell: DraftTypeCell,
        carries: []const LoopCarry,
    ) Allocator.Error!DraftBranch {
        const rest_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), iterator_cell, null);
        const record_pat = try self.iteratorSkipPayloadPattern(step, iterator_cell, rest_local);
        const tag_pat = try self.addPatWithTypeCell(DraftTypeCell.fromGraphNode(step.step_node), .{ .tag = .{
            .name = try self.tagName(self.view, step.skip_tag),
            .payloads = try self.addPatSpan(&[_]DraftPatId{record_pat}),
        } });
        const rest_expr = try self.addExprWithTypeCell(iterator_cell, .{ .local = rest_local });
        return .{
            .pat = tag_pat,
            .body = try self.continueWithState(result_cell, rest_expr, carries),
        };
    }

    fn iteratorOnePayloadPattern(
        self: *BodyContext,
        item_pattern: checked.CheckedPatternId,
        step: IterStepShape,
        iterator_cell: DraftTypeCell,
        rest_local: DraftLocalId,
        item_local: ?DraftLocalId,
    ) Allocator.Error!DraftPatId {
        const item_pat = if (item_local) |local|
            try self.addPatWithTypeCell(DraftTypeCell.fromGraphNode(step.one_item.node), .{ .bind = local })
        else
            try self.lowerPatternAtNode(item_pattern, step.one_item.node);
        const item_field = self.iteratorRecordDestruct(step.one_item.name, item_pat);
        const rest_field = self.iteratorRecordDestruct(step.one_rest.name, try self.addPatWithTypeCell(iterator_cell, .{ .bind = rest_local }));
        const fields = [_]DraftRecordDestruct{ item_field, rest_field };
        return try self.addPatWithTypeCell(
            DraftTypeCell.fromGraphNode(step.one_payload_node),
            .{ .record = try self.addRecordDestructSpan(&fields) },
        );
    }

    fn iteratorSkipPayloadPattern(
        self: *BodyContext,
        step: IterStepShape,
        iterator_cell: DraftTypeCell,
        rest_local: DraftLocalId,
    ) Allocator.Error!DraftPatId {
        const rest_field = self.iteratorRecordDestruct(step.skip_rest.name, try self.addPatWithTypeCell(iterator_cell, .{ .bind = rest_local }));
        const fields = [_]DraftRecordDestruct{rest_field};
        return try self.addPatWithTypeCell(
            DraftTypeCell.fromGraphNode(step.skip_payload_node),
            .{ .record = try self.addRecordDestructSpan(&fields) },
        );
    }

    fn iteratorRecordDestruct(
        _: *BodyContext,
        field: names.RecordFieldNameId,
        pattern: DraftPatId,
    ) DraftRecordDestruct {
        return .{
            .name = field,
            .pattern = pattern,
        };
    }

    fn pushLoopContext(self: *BodyContext, result_cell: DraftTypeCell, carries: []const LoopCarry) Allocator.Error!void {
        try self.loop_contexts.append(self.allocator, .{
            .result_cell = result_cell,
            .carries = carries,
        });
    }

    fn popLoopContext(self: *BodyContext) void {
        _ = self.loop_contexts.pop();
    }

    fn currentLoopContext(self: *BodyContext) LoopContext {
        if (self.loop_contexts.items.len == 0) Common.invariant("break statement reached Monotype outside an explicit loop expression");
        return self.loop_contexts.items[self.loop_contexts.items.len - 1];
    }

    fn breakCurrentLoopExpr(self: *BodyContext) Allocator.Error!DraftExprId {
        const loop = self.currentLoopContext();
        const data = try self.breakCurrentLoopExprData();
        return try self.addExprWithTypeCell(loop.result_cell, data);
    }

    fn breakCurrentLoopExprData(self: *BodyContext) Allocator.Error!BodyExprData {
        const loop = self.currentLoopContext();
        return if (loop.carries.len == 0)
            .{ .break_ = null }
        else
            .{ .break_ = try self.loopStateExpr(loop.result_cell, loop.carries) };
    }

    fn continueWith(self: *BodyContext, cell: DraftTypeCell, values: []const DraftExprId) Allocator.Error!DraftExprId {
        return try self.addExprWithTypeCell(cell, .{ .continue_ = .{
            .values = try self.addExprSpan(values),
        } });
    }

    fn continueWithCurrentState(
        self: *BodyContext,
        result_cell: DraftTypeCell,
        carries: []const LoopCarry,
    ) Allocator.Error!DraftExprId {
        if (carries.len == 0) return try self.continueWith(result_cell, &.{});

        const values = try self.allocator.alloc(DraftExprId, carries.len);
        defer self.allocator.free(values);
        for (carries, 0..) |carry, i| {
            const current = self.binders.get(carry.binder) orelse Common.invariant("loop-carried mutable binder was absent");
            values[i] = try self.loopCarryCurrentExpr(carry, current, .recursive_feedback);
        }
        return try self.continueWith(result_cell, values);
    }

    fn continueWithState(
        self: *BodyContext,
        result_cell: DraftTypeCell,
        rest_expr: DraftExprId,
        carries: []const LoopCarry,
    ) Allocator.Error!DraftExprId {
        const values = try self.allocator.alloc(DraftExprId, 1 + carries.len);
        defer self.allocator.free(values);
        values[0] = rest_expr;
        for (carries, 0..) |carry, i| {
            const current = self.binders.get(carry.binder) orelse Common.invariant("loop-carried mutable binder was absent");
            values[i + 1] = try self.loopCarryCurrentExpr(carry, current, .recursive_feedback);
        }
        return try self.continueWith(result_cell, values);
    }

    fn loopStateExpr(self: *BodyContext, result_cell: DraftTypeCell, carries: []const LoopCarry) Allocator.Error!DraftExprId {
        if (carries.len == 0) Common.invariant("empty loop state requested");
        if (carries.len == 1) {
            const current = self.binders.get(carries[0].binder) orelse Common.invariant("loop-carried mutable binder was absent");
            return try self.loopCarryCurrentExpr(carries[0], current, .exit_state);
        }

        const items = try self.allocator.alloc(DraftExprId, carries.len);
        defer self.allocator.free(items);
        for (carries, 0..) |carry, i| {
            const current = self.binders.get(carry.binder) orelse Common.invariant("loop-carried mutable binder was absent");
            items[i] = try self.loopCarryCurrentExpr(carry, current, .exit_state);
        }
        return try self.addExprWithTypeCell(result_cell, .{ .tuple = try self.addExprSpan(items) });
    }

    const LoopCarryFeedback = enum {
        recursive_feedback,
        exit_state,
    };

    fn loopCarryCurrentExpr(
        self: *BodyContext,
        carry: LoopCarry,
        current: DraftLocalId,
        feedback: LoopCarryFeedback,
    ) Allocator.Error!DraftExprId {
        const carry_node = try carry.ty.toGraphNode(self.graph);
        const current_node = try self.localTypeCell(current).toGraphNode(self.graph);
        if (feedback == .recursive_feedback) {
            // A continue edge is producer-authored recursive value flow even
            // when an earlier assignment already joined the current value to
            // the loop parameter. Record the edge itself; representation
            // finalization will force only slots that actually joined distinct
            // minted iterator identities.
            self.graph.markRecursiveValueSlot(carry_node);
        }
        if (!self.graph.sameClass(carry_node, current_node)) {
            try selectRequestRepresentation(self.graph, carry_node, current_node);
        }
        return try self.addExprWithTypeCell(carry.ty, .{ .local = current });
    }

    fn loopStateTypeCell(self: *BodyContext, unit_ty: Type.TypeId, carries: []const LoopCarry) Allocator.Error!DraftTypeCell {
        if (carries.len == 0) return .{ .sealed = unit_ty };
        if (carries.len == 1) return carries[0].ty;

        const nodes = try self.graph.arena().alloc(NodeId, carries.len);
        for (carries, 0..) |carry, i| nodes[i] = try carry.ty.toGraphNode(self.graph);
        return DraftTypeCell.fromGraphNode(try self.graph.newNode(.{ .tuple = nodes }));
    }

    fn unitType(self: *BodyContext) Allocator.Error!Type.TypeId {
        return try self.typeStore().internRecord(self.nameStore(), &.{});
    }

    fn prepareLoopCarries(self: *BodyContext, plan: ?checked.LoopMutationPlanId) Allocator.Error![]LoopCarry {
        var carries = std.ArrayList(LoopCarry).empty;
        errdefer carries.deinit(self.allocator);
        for (self.loopMutationBinders(plan)) |binder| {
            const initial = self.binders.get(binder) orelse continue;
            const ty = self.localTypeCell(initial);
            // The loop parameter is an ordinary version of the binder's local:
            // it must carry the binder so closures in the loop body that
            // capture it declare the binder's CaptureId.
            const param_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), ty, binder);
            try self.bindLocalName(param_local, binder);
            try carries.append(self.allocator, .{
                .binder = binder,
                .initial_local = initial,
                .param_local = param_local,
                .ty = ty,
            });
        }
        return try carries.toOwnedSlice(self.allocator);
    }

    fn finalCarryPattern(self: *BodyContext, carries: []const LoopCarry, result_cell: DraftTypeCell) Allocator.Error!DraftPatId {
        if (carries.len == 0) Common.invariant("empty loop carry pattern requested");
        if (carries.len == 1) {
            const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), carries[0].ty, carries[0].binder);
            try self.bindLocalName(local, carries[0].binder);
            try self.binders.put(carries[0].binder, local);
            return try self.addPatWithTypeCell(result_cell, .{ .bind = local });
        }

        const items = try self.allocator.alloc(DraftPatId, carries.len);
        defer self.allocator.free(items);
        for (carries, 0..) |carry, i| {
            const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), carry.ty, carry.binder);
            try self.bindLocalName(local, carry.binder);
            try self.binders.put(carry.binder, local);
            items[i] = try self.addPatWithTypeCell(carry.ty, .{ .bind = local });
        }
        return try self.addPatWithTypeCell(result_cell, .{ .tuple = try self.addPatSpan(items) });
    }

    const ReassignedBinderItem = union(enum) {
        expr: checked.CheckedExprId,
        loop_mutations: ?checked.LoopMutationPlanId,
        /// A binder a statement reassigns directly, in its source position.
        binder: checked.PatternBinderId,
    };

    /// One expression whose reassigned binders are being collected: its
    /// parts in `items[items_start..items_end]`, and its unique binders so
    /// far in `binders[binders_start..]`.
    const ReassignedBinderFrame = struct {
        expr: checked.CheckedExprId,
        items_start: usize,
        items_end: usize,
        next: usize,
        binders_start: usize,
    };

    /// Collect the binders an expression reassigns, in source order. Each
    /// expression's binders are its parts' binders in order, first occurrence
    /// kept, so every expression's list is memoized for the compilation: a
    /// nest of stateful expressions each asking for its own binders reads its
    /// children's lists instead of walking them again.
    fn collectReassignedBindersInExpr(
        self: *BodyContext,
        root: checked.CheckedExprId,
        out: *std.ArrayList(checked.PatternBinderId),
    ) Allocator.Error!void {
        const gpa = self.allocator;
        if (self.builder.reassigned_binders_memo.get(self.reassignedBinderAddress(root)) == null) {
            var frames: std.ArrayList(ReassignedBinderFrame) = .empty;
            defer frames.deinit(gpa);
            var items: std.ArrayList(ReassignedBinderItem) = .empty;
            defer items.deinit(gpa);
            var binders: std.ArrayList(checked.PatternBinderId) = .empty;
            defer binders.deinit(gpa);
            try self.pushReassignedBinderFrame(&frames, &items, &binders, root);
            while (frames.items.len != 0) {
                const frame = &frames.items[frames.items.len - 1];
                if (frame.next == frame.items_end) {
                    const finished = frames.pop().?;
                    const span = try self.memoizeReassignedBinders(finished.expr, binders.items[finished.binders_start..]);
                    binders.shrinkRetainingCapacity(finished.binders_start);
                    items.shrinkRetainingCapacity(finished.items_start);
                    if (frames.items.len != 0) {
                        const parent_start = frames.items[frames.items.len - 1].binders_start;
                        for (self.builder.reassigned_binder_pool.items[span.start..][0..span.len]) |binder| {
                            try appendUniqueBinderFrom(gpa, &binders, parent_start, binder);
                        }
                    }
                    continue;
                }
                const item = items.items[frame.next];
                frame.next += 1;
                const binders_start = frame.binders_start;
                switch (item) {
                    .binder => |binder| try appendUniqueBinderFrom(gpa, &binders, binders_start, binder),
                    .loop_mutations => |plan| for (self.loopMutationBinders(plan)) |binder| {
                        try appendUniqueBinderFrom(gpa, &binders, binders_start, binder);
                    },
                    .expr => |expr_id| if (self.builder.reassigned_binders_memo.get(self.reassignedBinderAddress(expr_id))) |span| {
                        for (self.builder.reassigned_binder_pool.items[span.start..][0..span.len]) |binder| {
                            try appendUniqueBinderFrom(gpa, &binders, binders_start, binder);
                        }
                    } else {
                        try self.pushReassignedBinderFrame(&frames, &items, &binders, expr_id);
                    },
                }
            }
        }
        const span = self.builder.reassigned_binders_memo.get(self.reassignedBinderAddress(root)).?;
        for (self.builder.reassigned_binder_pool.items[span.start..][0..span.len]) |binder| try self.appendUniqueBinder(out, binder);
    }

    fn pushReassignedBinderFrame(
        self: *BodyContext,
        frames: *std.ArrayList(ReassignedBinderFrame),
        items: *std.ArrayList(ReassignedBinderItem),
        binders: *const std.ArrayList(checked.PatternBinderId),
        expr_id: checked.CheckedExprId,
    ) Allocator.Error!void {
        const items_start = items.items.len;
        try self.pushReassignedExprParts(items, expr_id);
        try frames.append(self.allocator, .{
            .expr = expr_id,
            .items_start = items_start,
            .items_end = items.items.len,
            .next = items_start,
            .binders_start = binders.items.len,
        });
    }

    fn reassignedBinderAddress(self: *const BodyContext, expr_id: checked.CheckedExprId) ReassignedBinderAddress {
        return .{ .module = self.view.key, .expr = expr_id };
    }

    fn memoizeReassignedBinders(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        binders: []const checked.PatternBinderId,
    ) Allocator.Error!ReassignedBinderSpan {
        const span: ReassignedBinderSpan = .{ .start = self.builder.reassigned_binder_pool.items.len, .len = binders.len };
        try self.builder.reassigned_binder_pool.appendSlice(self.builder.allocator, binders);
        try self.builder.reassigned_binders_memo.put(self.builder.allocator, self.reassignedBinderAddress(expr_id), span);
        return span;
    }

    fn appendUniqueBinderFrom(
        gpa: Allocator,
        binders: *std.ArrayList(checked.PatternBinderId),
        start: usize,
        binder: checked.PatternBinderId,
    ) Allocator.Error!void {
        for (binders.items[start..]) |existing| {
            if (existing == binder) return;
        }
        try binders.append(gpa, binder);
    }

    fn pushReassignedExprParts(self: *BodyContext, pending: *std.ArrayList(ReassignedBinderItem), expr_id: checked.CheckedExprId) Allocator.Error!void {
        const gpa = self.allocator;
        const expr = self.view.bodies.expr(expr_id);
        switch (expr.data) {
            .str => |segments| for (segments) |segment| try pending.append(gpa, .{ .expr = segment }),
            .list, .tuple => |items| for (items) |child| try pending.append(gpa, .{ .expr = child }),
            .match_ => |match| {
                try pending.append(gpa, .{ .expr = match.cond });
                for (match.branches) |branch| {
                    if (branch.guard) |guard| try pending.append(gpa, .{ .expr = guard });
                    try pending.append(gpa, .{ .expr = branch.value });
                }
            },
            .if_ => |if_| {
                for (if_.branches) |branch| {
                    try pending.append(gpa, .{ .expr = branch.cond });
                    try pending.append(gpa, .{ .expr = branch.body });
                }
                try pending.append(gpa, .{ .expr = if_.final_else });
            },
            .call => |call| {
                try pending.append(gpa, .{ .expr = call.func });
                for (call.args) |arg| try pending.append(gpa, .{ .expr = arg });
            },
            .record => |record| {
                if (record.ext) |ext| try pending.append(gpa, .{ .expr = ext });
                for (record.fields) |field| try pending.append(gpa, .{ .expr = field.value });
            },
            .block => |block| {
                for (block.statements) |statement| try self.pushReassignedStatementParts(pending, statement);
                try pending.append(gpa, .{ .expr = block.final_expr });
            },
            .tag => |tag| for (tag.args) |arg| try pending.append(gpa, .{ .expr = arg }),
            .nominal => |nominal| try pending.append(gpa, .{ .expr = nominal.backing_expr }),
            .binop => |binop| {
                try pending.append(gpa, .{ .expr = binop.lhs });
                try pending.append(gpa, .{ .expr = binop.rhs });
            },
            .unary_minus,
            .unary_not,
            .dbg,
            => |child| try pending.append(gpa, .{ .expr = child }),
            // An expect body can only reassign vars declared inside it, so
            // it never changes state an enclosing construct carries.
            .expect => {},
            .expect_err => |expect_err| try pending.append(gpa, .{ .expr = expect_err.expr }),
            .field_access => |field| try pending.append(gpa, .{ .expr = field.receiver }),
            .structural_eq => |eq| {
                try pending.append(gpa, .{ .expr = eq.lhs });
                try pending.append(gpa, .{ .expr = eq.rhs });
            },
            .structural_hash => |h| {
                try pending.append(gpa, .{ .expr = h.value });
                try pending.append(gpa, .{ .expr = h.hasher });
            },
            .tuple_access => |access| try pending.append(gpa, .{ .expr = access.tuple }),
            .return_ => |ret| try pending.append(gpa, .{ .expr = ret.expr }),
            .for_ => |for_| {
                try pending.append(gpa, .{ .expr = for_.expr });
                try pending.append(gpa, .{ .loop_mutations = for_.mutations });
            },
            .run_low_level => |low_level| for (low_level.args) |arg| try pending.append(gpa, .{ .expr = arg }),
            .lambda,
            .closure,
            .hosted_lambda,
            .pending,
            .numeral,
            .str_from_quote,
            .str_segment,
            .bytes_literal,
            .lookup_local,
            .lookup_external,
            .lookup_required,
            .empty_list,
            .empty_record,
            .zero_argument_tag,
            .dispatch_call,
            .interpolation,
            .method_eq,
            .type_dispatch_call,
            .runtime_error,
            .crash,
            .ellipsis,
            .anno_only,
            .break_,
            => {},
        }
    }

    /// A statement's reassigned binders come before those of its parts.
    fn pushReassignedStatementParts(
        self: *BodyContext,
        pending: *std.ArrayList(ReassignedBinderItem),
        statement_id: checked.CheckedStatementId,
    ) Allocator.Error!void {
        const gpa = self.allocator;
        const statement = self.view.bodies.statement(statement_id);
        switch (statement.data) {
            .decl => |decl| try pending.append(gpa, .{ .expr = decl.expr }),
            .var_ => |var_| try pending.append(gpa, .{ .expr = var_.expr }),
            .var_uninitialized, .promoted_proc => {},
            .reassign => |reassign| {
                for (reassign.reassigned_binders) |binder| try pending.append(gpa, .{ .binder = binder });
                try pending.append(gpa, .{ .expr = reassign.expr });
            },
            .dbg,
            .expr,
            => |expr| try pending.append(gpa, .{ .expr = expr }),
            .expect => {},
            .for_ => |for_| {
                try pending.append(gpa, .{ .expr = for_.expr });
                try pending.append(gpa, .{ .loop_mutations = for_.mutations });
            },
            inline .while_, .infinite_loop, .breakable_loop => |loop| try pending.append(gpa, .{ .loop_mutations = loop.mutations }),
            .return_ => |ret| try pending.append(gpa, .{ .expr = ret.expr }),
            .pending,
            .crash,
            .break_,
            .import_,
            .alias_decl,
            .where_alias_decl,
            .nominal_decl,
            .type_anno,
            .type_var_alias,
            .runtime_error,
            => {},
        }
    }

    /// The published binders a loop carries.
    fn loopMutationBinders(self: *BodyContext, plan: ?checked.LoopMutationPlanId) []const checked.PatternBinderId {
        const range = self.view.bodies.loopMutations(plan orelse Common.invariant("checked loop omitted its mutation plan")).binders;
        return self.view.bodies.patternBinderIdPool()[range.start..][0..range.len];
    }

    fn appendUniqueBinder(
        self: *BodyContext,
        out: *std.ArrayList(checked.PatternBinderId),
        binder: checked.PatternBinderId,
    ) Allocator.Error!void {
        for (out.items) |existing| {
            if (existing == binder) return;
        }
        try out.append(self.allocator, binder);
    }

    const IterStepShape = struct {
        step_node: NodeId,
        done_tag: names.TagNameId,
        one_tag: names.TagNameId,
        skip_tag: names.TagNameId,
        one_payload_node: NodeId,
        skip_payload_node: NodeId,
        one_item: IterStepField,
        one_rest: IterStepField,
        skip_rest: IterStepField,
    };

    const IterStepField = struct {
        name: names.RecordFieldNameId,
        node: NodeId,
    };

    fn iteratorStepShape(
        self: *BodyContext,
        plan: static_dispatch.IteratorForPlan,
        iterator_cell: DraftTypeCell,
    ) Allocator.Error!IterStepShape {
        const topology = plan.step_topology;
        const iterator_node = try iterator_cell.toGraphNode(self.graph);
        const step_node = if ((try self.isGeneratedIteratorEvidenceNode(iterator_node)))
            try self.generatedIteratorStepReturnNode(iterator_node)
        else
            try self.lowerTypeNode(plan.step_ty);
        const done_tag_name = try self.tagName(self.view, topology.done_tag);
        const one_tag_name = try self.tagName(self.view, topology.one_tag);
        const skip_tag_name = try self.tagName(self.view, topology.skip_tag);
        try self.requireIteratorStepTagArity(step_node, done_tag_name, 0);
        try self.requireIteratorStepTagArity(step_node, one_tag_name, 1);
        try self.requireIteratorStepTagArity(step_node, skip_tag_name, 1);
        const one_payload_node = try self.graph.tagPayloadNode(step_node, one_tag_name, 0);
        const skip_payload_node = try self.graph.tagPayloadNode(step_node, skip_tag_name, 0);
        try self.constrainCheckedInterfaceToCell(topology.one_payload_ty, DraftTypeCell.fromGraphNode(one_payload_node));
        try self.constrainCheckedInterfaceToCell(topology.skip_payload_ty, DraftTypeCell.fromGraphNode(skip_payload_node));
        const item_field = try self.recordFieldName(self.view, topology.item_field);
        const rest_field = try self.recordFieldName(self.view, topology.rest_field);

        return .{
            .step_node = step_node,
            .done_tag = topology.done_tag,
            .one_tag = topology.one_tag,
            .skip_tag = topology.skip_tag,
            .one_payload_node = one_payload_node,
            .skip_payload_node = skip_payload_node,
            .one_item = .{ .name = item_field, .node = try self.graph.recordFieldNode(one_payload_node, item_field) },
            .one_rest = .{ .name = rest_field, .node = try self.graph.recordFieldNode(one_payload_node, rest_field) },
            .skip_rest = .{ .name = rest_field, .node = try self.graph.recordFieldNode(skip_payload_node, rest_field) },
        };
    }

    fn requireIteratorStepTagArity(
        self: *BodyContext,
        step_node: NodeId,
        tag_name: names.TagNameId,
        expected_arity: usize,
    ) Allocator.Error!void {
        for ((try self.graph.tagRowNodes(step_node)).tags) |tag| {
            if (tag.name != tag_name) continue;
            if (tag.payloads.len != expected_arity) {
                Common.invariant("iterator step tag differed from its checker-recorded payload arity");
            }
            return;
        }
        Common.invariant("iterator step type omitted a checker-recorded tag");
    }

    const LoweredStatement = struct {
        stmt: ?DraftStmtId,
        termination: StatementTermination,
    };

    const LoweredPatternStatement = struct {
        stmt: ?DraftStmt,
        termination: StatementTermination,
    };

    fn finishLoweredStatement(
        self: *BodyContext,
        stmt: DraftStmt,
        termination: StatementTermination,
        statement_diverges: bool,
    ) Allocator.Error!LoweredStatement {
        return .{
            .stmt = try self.addStmt(stmt),
            .termination = switch (termination) {
                .none => if (statement_diverges) .checked_control_transfer else .none,
                .checked_control_transfer, .uninhabited => termination,
            },
        };
    }

    fn lowerUninitializedPatternStatement(
        self: *BodyContext,
        pattern: checked.CheckedPatternId,
    ) Allocator.Error!DraftPatId {
        const checked_pattern = self.view.bodies.pattern(pattern);
        if (checked_pattern.data != .assign) {
            Common.invariant("checked uninitialized variable pattern was not a binder");
        }
        const node = try self.lowerTypeNode(checked_pattern.ty);
        return try self.lowerShapeFreePatternAtCell(pattern, DraftTypeCell.fromGraphNode(node));
    }

    /// The cell a pattern statement's value lowers at, related to the
    /// checked pattern's type.
    fn beginPatternStatementValue(
        self: *BodyContext,
        pattern: checked.CheckedPatternId,
        expr: checked.CheckedExprId,
    ) Allocator.Error!DraftTypeCell {
        const requested_cell: DraftTypeCell = if (try self.graphFreeResultTypeForExpr(expr)) |ty|
            .{ .sealed = ty }
        else
            DraftTypeCell.fromGraphNode(try self.lowerExprTypeNode(expr));
        // The checked pattern is explicit evidence for the value's shape.
        // Apply that relation before either the value or a shape-dependent
        // pattern asks for a concrete view of the graph-backed value type.
        switch (requested_cell) {
            .sealed => |ty| try self.requireClosedCheckedType(self.view.bodies.pattern(pattern).ty, ty),
            .graph_node => try self.constrainCheckedInterfaceToCell(self.view.bodies.pattern(pattern).ty, requested_cell),
        }
        return requested_cell;
    }

    /// Bind a pattern statement's lowered value.
    fn finishPatternStatement(
        self: *BodyContext,
        pattern: checked.CheckedPatternId,
        source_region: base.Region,
        requested_cell: DraftTypeCell,
        value: DraftExprId,
    ) Allocator.Error!LoweredPatternStatement {
        const produced_cell = self.exprTypeCell(value);
        const value_cell = switch (requested_cell) {
            .sealed => |requested_ty| blk: {
                const produced_ty = switch (produced_cell) {
                    .sealed => |ty| ty,
                    .graph_node => Common.invariant("graph-free closed dispatch produced a graph-backed result"),
                };
                if (!self.sameType(requested_ty, produced_ty)) {
                    Common.invariant("graph-free closed dispatch produced a different sealed result type");
                }
                break :blk produced_cell;
            },
            .graph_node => |requested_node| blk: {
                const produced_node = try produced_cell.toGraphNode(self.graph);
                const completes_request = try self.resultCompletesRequest(requested_node, produced_node);
                const contains_generated_private = try self.graph.containsGeneratedPrivate(produced_node);
                break :blk if (completes_request or contains_generated_private)
                    produced_cell
                else
                    requested_cell;
            },
        };
        const comptime_site = if (self.shouldRecordComptimeSite(.destructure) and try self.patternCanMiss(pattern))
            try self.addComptimeSite(.destructure, source_region, self.view.exhaustiveness_sites.lookupByDestructurePattern(pattern), &.{})
        else
            null;
        if (!try self.patternNeedsExplicitBinding(pattern)) {
            const pat = if (self.patternIsShapeFree(pattern))
                try self.lowerShapeFreePatternAtCell(pattern, value_cell)
            else
                try self.lowerPatternAtNode(pattern, try value_cell.toGraphNode(self.graph));
            return .{ .stmt = .{ .let_ = .{
                .pat = pat,
                .value = value,
                .comptime_site = comptime_site,
            } }, .termination = .none };
        }

        const unit_ty = try self.unitType();
        var unit = try self.addExpr(.{ .ty = unit_ty, .data = .unit });
        unit = try self.wrapComptimeBranch(comptime_site, 0, unit);
        const miss = if (comptime_site) |site|
            try self.comptimeExhaustivenessFailedExpr(unit_ty, site)
        else
            try self.runtimeCrashExpr(unit_ty, "pattern match failed");
        return .{
            .stmt = .{ .expr = try self.lowerMaterializedPatternValueThen(
                pattern,
                value,
                value_cell,
                .{ .sealed = unit_ty },
                .{ .expr = unit },
                miss,
                null,
            ) },
            .termination = .none,
        };
    }

    fn patternIsShapeFree(self: *BodyContext, pattern_id: checked.CheckedPatternId) bool {
        var current = pattern_id;
        while (true) switch (self.view.bodies.pattern(current).data) {
            .assign, .underscore => return true,
            .as => |as| current = as.pattern,
            .pending, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .runtime_error => return false,
        };
    }

    fn lowerShapeFreePatternAtCell(
        self: *BodyContext,
        root_pattern: checked.CheckedPatternId,
        ty_cell: DraftTypeCell,
    ) Allocator.Error!DraftPatId {
        // An `as` chain binds each layer before the pattern beneath it.
        var as_locals: std.ArrayListUnmanaged(DraftLocalId) = .empty;
        defer as_locals.deinit(self.allocator);
        var pattern_id = root_pattern;
        const data: BodyPatData = while (true) {
            const pattern = self.view.bodies.pattern(pattern_id);
            switch (ty_cell) {
                .sealed => |ty| try self.requireClosedCheckedType(pattern.ty, ty),
                .graph_node => |value_node| {
                    const pattern_node = try self.instNode(pattern.ty);
                    if (!try self.resultCompletesRequest(pattern_node, value_node) or
                        try self.graph.containsGeneratedPrivate(value_node))
                    {
                        try self.constrainCheckedInterfaceToCell(pattern.ty, ty_cell);
                    }
                },
            }
            switch (pattern.data) {
                .assign => |binder| break .{ .bind = try self.materializePatternBinderAtCell(binder, ty_cell) },
                .as => |as| {
                    try as_locals.append(self.allocator, try self.materializePatternBinderAtCell(as.binder, ty_cell));
                    pattern_id = as.pattern;
                },
                .underscore => break .wildcard,
                .pending, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .runtime_error => Common.invariant("shape-dependent pattern reached shape-free graph-cell lowering"),
            }
        };
        var pat = try self.addPatWithTypeCell(ty_cell, data);
        while (as_locals.pop()) |local| {
            pat = try self.addPatWithTypeCell(ty_cell, .{ .as = .{ .pattern = pat, .local = local } });
        }
        return pat;
    }

    fn currentOwnerPatternBinderLocal(
        self: *BodyContext,
        binder: checked.PatternBinderId,
    ) ?DraftLocalId {
        const local = self.binders.get(binder) orelse return null;
        return if (self.draft.currentOwnerOwnsCore(.locals, @backingInt(local))) local else null;
    }

    fn materializePatternBinderAtCell(
        self: *BodyContext,
        binder: checked.PatternBinderId,
        cell: DraftTypeCell,
    ) Allocator.Error!DraftLocalId {
        if (self.reuse_pre_registered_pattern_binders) {
            const local = self.currentOwnerPatternBinderLocal(binder) orelse
                Common.invariant("pattern binder was not pre-registered before materialization");
            switch (cell) {
                .sealed => |sealed| if (@backingInt(sealed) >= self.typeStore().epochBoundary().types) {
                    Common.invariant("pattern binder adopted a type from another store");
                },
                .graph_node => {},
            }
            self.draft.setLocalType(local, cell);
            return local;
        }
        const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), cell, binder);
        try self.bindLocalName(local, binder);
        try self.binders.put(binder, local);
        return local;
    }

    fn zeroBranchMatch(self: *BodyContext, scrutinee: DraftExprId, ty: Type.TypeId) Allocator.Error!DraftExprId {
        return try self.zeroBranchMatchAtTypeCell(scrutinee, .{ .sealed = ty });
    }

    fn zeroBranchMatchAtTypeCell(
        self: *BodyContext,
        scrutinee: DraftExprId,
        cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        return try self.addExprWithTypeCell(cell, .{ .match_ = .{
            .scrutinee = scrutinee,
            .branches = try self.addBranchSpan(&.{}),
            .comptime_site = null,
        } });
    }

    fn registerLocalProc(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        expr: checked.CheckedExprId,
        context_anchor: checked.CheckedStatementId,
        snapshots: *std.ArrayList(DraftStmtId),
    ) Allocator.Error!void {
        try self.registerLocalProcDeclaration(.{
            .module = self.view.key.bytes,
            .binder = self.localProcBinder(pattern_id),
            .expr = expr,
            .context_anchor = context_anchor,
        }, snapshots);
    }

    fn registerLocalAssociatedProcedures(
        self: *BodyContext,
        statement_id: checked.CheckedStatementId,
        snapshots: *std.ArrayList(DraftStmtId),
    ) Allocator.Error!void {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .local_proc_context);
        defer timing_scope.end();
        for (self.view.method_registry.entries) |entry| switch ((entry.target orelse continue).kind) {
            .local_proc => |local| {
                if (local.context_anchor == statement_id) {
                    try self.registerLocalProcDeclaration(.{
                        .module = self.view.key.bytes,
                        .binder = local.binder,
                        .expr = local.expr,
                        .context_anchor = local.context_anchor,
                    }, snapshots);
                }
            },
            .procedure, .structural => {},
        };
    }

    /// Register a local procedure's declaration context. A closure's
    /// captures are the values its captured binders hold at its declaration,
    /// while a reassignable binder keeps one local that each reassignment
    /// rebinds. So each captured reassignable binder's current value is
    /// bound to a snapshot local at the declaration (appended to
    /// `snapshots`, to run where the declaration does), and the context
    /// names the snapshot, which every construction of the procedure's
    /// callable and its body read.
    fn registerLocalProcDeclaration(
        self: *BodyContext,
        declaration: DraftLocalProcDeclaration,
        snapshots: *std.ArrayList(DraftStmtId),
    ) Allocator.Error!void {
        const address = declaration.address();
        const current = try self.captureLocalProcContext(declaration);
        defer self.releaseLocalProcContext(current);
        const existing_context: ?LocalProcContext = if (self.local_proc_contexts.get(address)) |existing_id| blk: {
            const raw_existing = @backingInt(existing_id);
            if (raw_existing >= self.draft.local_proc_contexts.items.len) {
                Common.invariant("local procedure binder referenced an unknown declaration context");
            }
            break :blk self.draft.local_proc_contexts.items[raw_existing];
        } else null;
        try self.snapshotReassignableCaptures(declaration.expr, current.entries, if (existing_context) |existing| existing.entries else null, snapshots);

        if (existing_context) |existing| {
            if (!moduleBytesEqual(existing.declaration.module, declaration.module) or
                existing.declaration.binder != declaration.binder or
                existing.declaration.expr != declaration.expr)
            {
                Common.invariant("local procedure binder named two checked declarations");
            }
            if (!try localProcContextEql(self.allocator, existing, current)) {
                Common.invariant("local procedure binder had two declaration contexts");
            }
        } else {
            const context_id: DraftLocalProcContextId = @fromBackingInt(@intCast(@as(u32, @intCast(self.draft.local_proc_contexts.items.len))));
            try self.draft.local_proc_contexts.append(self.allocator, try self.cloneLocalProcContext(current));
            try self.local_proc_contexts.putPermanent(address, context_id);
        }
    }

    /// Whether the declared closure `expr` captures the reassignable
    /// `binder`, whose declaration-time value it then reads from a snapshot.
    fn localProcSnapshotsBinder(self: *BodyContext, expr: checked.CheckedExprId, binder: checked.PatternBinderId) bool {
        if (!self.view.bodies.patternBinder(binder).reassignable) return false;
        const captures = switch (self.view.bodies.expr(expr).data) {
            .closure => |closure| closure.captures,
            .lambda, .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => return false,
        };
        for (captures) |capture| {
            if (checkedCaptureBinder(self.view, capture.pattern) == binder) return true;
        }
        return false;
    }

    /// Point each of `entries` whose binder the declared closure `expr`
    /// captures and that is reassignable at a snapshot local bound to the
    /// binder's current value, appending that binding to `snapshots`. A
    /// declaration lowered again reuses the snapshot locals its first
    /// lowering recorded (`existing`).
    fn snapshotReassignableCaptures(
        self: *BodyContext,
        expr: checked.CheckedExprId,
        entries: []LexicalBinderEntry,
        existing: ?[]const LexicalBinderEntry,
        snapshots: *std.ArrayList(DraftStmtId),
    ) Allocator.Error!void {
        for (entries, 0..) |*entry, index| {
            if (entry.kind != 0) continue;
            const binder: checked.PatternBinderId = @fromBackingInt(entry.binder);
            if (!self.localProcSnapshotsBinder(expr, binder)) continue;

            const current: DraftLocalId = @fromBackingInt(entry.local);
            const cell = self.localTypeCell(current);
            const snapshot: DraftLocalId = if (existing) |recorded| blk: {
                if (recorded.len != entries.len or recorded[index].binder != entry.binder) {
                    Common.invariant("local procedure declaration lowered again with a different lexical context");
                }
                break :blk @fromBackingInt(recorded[index].local);
            } else blk: {
                const local = try self.draft.addCaptureSnapshotLocal(self.builder.symbols.fresh(), cell);
                try self.bindLocalName(local, binder);
                break :blk local;
            };
            try snapshots.append(self.allocator, try self.addStmt(.{ .let_ = .{
                .pat = try self.addPatWithTypeCell(cell, .{ .bind = snapshot }),
                .value = try self.addExprWithTypeCell(cell, .{ .local = current }),
            } }));
            entry.local = @backingInt(snapshot);
        }
    }

    fn localProcContextId(
        self: *BodyContext,
        view: ModuleView,
        binder: checked.PatternBinderId,
        expr: checked.CheckedExprId,
    ) Allocator.Error!DraftLocalProcContextId {
        const address = DraftLocalProcAddress{ .module = view.key.bytes, .binder = binder, .expr = expr };
        if (self.local_proc_contexts.get(address)) |context| return context;

        const restored = self.restored_local_proc_scope orelse
            Common.invariant("local procedure use reached Monotype before its declaration context");
        var context_anchor: ?checked.CheckedStatementId = null;
        for (view.method_registry.entries) |entry| switch ((entry.target orelse continue).kind) {
            .local_proc => |local| {
                if (local.binder != binder or local.expr != expr) continue;
                if (context_anchor) |existing| {
                    if (existing != local.context_anchor) {
                        Common.invariant("restored local procedure had conflicting checked declaration anchors");
                    }
                } else context_anchor = local.context_anchor;
            },
            .procedure, .structural => {},
        };

        const declaration = DraftLocalProcDeclaration{
            .module = view.key.bytes,
            .binder = binder,
            .expr = expr,
            .context_anchor = context_anchor,
        };
        const context_id: DraftLocalProcContextId = @fromBackingInt(@intCast(@as(u32, @intCast(self.draft.local_proc_contexts.items.len))));
        const entries = try self.allocator.dupe(LexicalBinderEntry, restored.entries);
        self.draft.local_proc_contexts.append(self.allocator, .{
            .declaration = declaration,
            .lexical_owner = self.draft.current_owner,
            .owner_template = self.owner_template,
            .base_key = restored.base_key,
            .restored_specialization_key = restoredLocalProcUseContextKey(restored.base_key, restored.source_context_digest, binder),
            .entries = entries,
            .evidence = self.restoredLocalProcDeclarationEvidence(view, expr),
        }) catch |err| {
            self.allocator.free(entries);
            return err;
        };
        try self.local_proc_contexts.putPermanent(address, context_id);
        return context_id;
    }

    fn restoredLocalProcDeclarationEvidence(
        self: *BodyContext,
        view: ModuleView,
        expr: checked.CheckedExprId,
    ) EvidenceChain {
        var site: ?checked.NestedProcSite = null;
        for (view.nested_proc_sites.sites) |candidate| {
            if (candidate.checked_expr == null or candidate.checked_expr.? != expr) continue;
            switch (candidate.owner) {
                .template => |site_owner| {
                    if (self.in_default_expr) continue;
                    if (!names.procedureTemplateRefEql(site_owner, self.owner_template)) continue;
                },
                .default_root => if (!self.in_default_expr) continue,
            }
            if (site != null) Common.invariant("restored local procedure matched multiple checked nested sites");
            site = candidate;
        }
        const nested_site = site orelse
            Common.invariant("restored local procedure had no checked nested site");
        const wanted: LexicalDispatchScope = switch (nested_site.lexical_scope) {
            .root => .root,
            .generalized => |scope_id| blk: {
                const raw_scope = @backingInt(scope_id);
                if (raw_scope >= view.templates.dispatch_scopes.len) {
                    Common.invariant("restored local procedure nested site named an unknown evidence scope");
                }
                const scope = view.templates.dispatch_scopes[raw_scope];
                break :blk if (scope.checked_expr == expr)
                    (if (scope.parent) |parent| .{ .generalized = parent } else .root)
                else
                    .{ .generalized = scope_id };
            },
        };

        return self.evidence.atScope(.{
            .owner = self.owner_template,
            .lexical = wanted,
        }) orelse Common.invariant("restored local procedure evidence omitted its checked lexical parent");
    }

    fn localProcBinder(self: *BodyContext, pattern_id: checked.CheckedPatternId) checked.PatternBinderId {
        const pattern = self.view.bodies.pattern(pattern_id);
        return switch (pattern.data) {
            .assign => |binder| binder,
            .pending, .as, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => Common.invariant("local procedure declaration pattern was not a binder"),
        };
    }

    /// The declaration a block statement makes, when it declares a local
    /// procedure.
    fn blockStatementLocalProcDecl(self: *BodyContext, statement_id: checked.CheckedStatementId) ?@FieldType(checked.CheckedStatementData, "decl") {
        const statement = self.view.bodies.statement(statement_id);
        if (statement.data != .decl) return null;
        const decl = statement.data.decl;
        if (!self.statementDeclIsLocalProc(decl.pattern, decl.expr)) return null;
        return decl;
    }

    fn statementDeclIsLocalProc(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        expr_id: checked.CheckedExprId,
    ) bool {
        // A local procedure declaration has a named binder. A lambda assigned
        // to an ignored or erroneous pattern remains an ordinary value.
        const pattern = self.view.bodies.pattern(pattern_id);
        if (pattern.data != .assign) return false;
        if (self.view.bodies.patternBinder(pattern.data.assign).is_scheme_alias) return true;
        return switch (self.view.bodies.expr(expr_id).data) {
            .lambda, .closure => true,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => false,
        };
    }

    /// Where a typed pattern's lowered node is typed: an explicit cell, or
    /// the draft cell of a concrete type.
    const PatTarget = union(enum) { cell: DraftTypeCell, ty: Type.TypeId };

    /// A typed subpattern still to lower, at an explicit target or at the
    /// pat_run's target for its type.
    const PatTypeOp = struct { pattern: checked.CheckedPatternId, ty: Type.TypeId, target: ?PatTarget = null };

    /// A typed pattern whose subpatterns are still lowering. Its ops occupy
    /// `ops[ops_start..]`; each subpattern's result lands in `results`.
    const PatTypeFrame = struct {
        kind: union(enum) {
            nominal: PatTarget,
            as: struct { target: PatTarget, local: DraftLocalId },
            tag: struct { target: PatTarget, name: names.TagNameId },
            tuple: PatTarget,
            list: struct { target: PatTarget, count: usize, rest: ?list_rest.Rest },
            record: PatTarget,
        },
        ops_start: usize,
        next: usize,
        results_start: usize,
        names_start: usize,
    };

    const PatTypeRun = struct {
        frames: std.ArrayListUnmanaged(PatTypeFrame) = .empty,
        ops: std.ArrayListUnmanaged(PatTypeOp) = .empty,
        results: std.ArrayListUnmanaged(DraftPatId) = .empty,
        field_names: std.ArrayListUnmanaged(names.RecordFieldNameId) = .empty,

        fn deinit(pat_run: *PatTypeRun, allocator: Allocator) void {
            pat_run.field_names.deinit(allocator);
            pat_run.results.deinit(allocator);
            pat_run.ops.deinit(allocator);
            pat_run.frames.deinit(allocator);
        }
    };

    fn lowerPatternAtType(self: *BodyContext, pattern_id: checked.CheckedPatternId, ty: Type.TypeId) Allocator.Error!DraftPatId {
        return try self.lowerPatternAtTypeCell(pattern_id, try self.draftTypeCell(ty), ty);
    }

    fn lowerPatternAtTypeCell(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        ty_cell: DraftTypeCell,
        ty: Type.TypeId,
    ) Allocator.Error!DraftPatId {
        var pat_run = PatTypeRun{};
        defer pat_run.deinit(self.allocator);
        if (try self.enterPatType(&pat_run, pattern_id, ty, .{ .cell = ty_cell })) |pat| return pat;
        return try self.runPatType(&pat_run);
    }

    /// Drive typed pattern frames to completion. Each composite pattern is an
    /// explicit frame whose subpatterns lower in source order, so pattern
    /// depth never becomes native call depth.
    fn runPatType(self: *BodyContext, pat_run: *PatTypeRun) Allocator.Error!DraftPatId {
        while (true) {
            const index = pat_run.frames.items.len - 1;
            const frame = pat_run.frames.items[index];
            if (frame.next < pat_run.ops.items.len) {
                const op = pat_run.ops.items[frame.next];
                pat_run.frames.items[index].next += 1;
                const target: PatTarget = op.target orelse .{ .cell = try self.draftTypeCell(op.ty) };
                if (try self.enterPatType(pat_run, op.pattern, op.ty, target)) |pat| {
                    try pat_run.results.append(self.allocator, pat);
                }
                continue;
            }

            const pat = try self.finishPatType(pat_run, frame);
            _ = pat_run.frames.pop();
            pat_run.ops.shrinkRetainingCapacity(frame.ops_start);
            pat_run.results.shrinkRetainingCapacity(frame.results_start);
            pat_run.field_names.shrinkRetainingCapacity(frame.names_start);
            if (pat_run.frames.items.len == 0) return pat;
            try pat_run.results.append(self.allocator, pat);
        }
    }

    fn pushPatTypeFrame(self: *BodyContext, pat_run: *PatTypeRun, kind: @FieldType(PatTypeFrame, "kind")) Allocator.Error!void {
        try pat_run.frames.append(self.allocator, .{
            .kind = kind,
            .ops_start = pat_run.ops.items.len,
            .next = pat_run.ops.items.len,
            .results_start = pat_run.results.items.len,
            .names_start = pat_run.field_names.items.len,
        });
    }

    fn appendPatTypeChildren(
        self: *BodyContext,
        pat_run: *PatTypeRun,
        checked_patterns: []const checked.CheckedPatternId,
        tys: anytype,
    ) Allocator.Error!void {
        if (checked_patterns.len != GuardedList.borrowLen(tys)) Common.invariant("pattern arity differs from concrete checked type");
        const stable_tys = try GuardedList.dupe(self.allocator, Type.TypeId, tys);
        defer self.allocator.free(stable_tys);
        for (checked_patterns, stable_tys) |child, child_ty| {
            try pat_run.ops.append(self.allocator, .{ .pattern = child, .ty = child_ty });
        }
    }

    /// The pattern a leaf lowers to, or null after pushing the frames that
    /// lower a composite one.
    fn enterPatType(
        self: *BodyContext,
        pat_run: *PatTypeRun,
        pattern_id: checked.CheckedPatternId,
        ty: Type.TypeId,
        target: PatTarget,
    ) Allocator.Error!?DraftPatId {
        const pattern = self.view.bodies.pattern(pattern_id);
        switch (pattern.data) {
            .assign => {},
            .pending, .as, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => try self.constrainCheckedInterfaceToCell(pattern.ty, target.cell),
        }
        const data: BodyPatData = switch (pattern.data) {
            .pending,
            .runtime_error,
            => Common.invariant("non-runtime checked pattern reached Monotype lowering"),
            .assign => |binder| .{ .bind = try self.materializePatternBinderAtCell(binder, target.cell) },
            .as => |as| {
                const local = try self.materializePatternBinderAtCell(as.binder, target.cell);
                try self.pushPatTypeFrame(pat_run, .{ .as = .{ .target = target, .local = local } });
                try pat_run.ops.append(self.allocator, .{ .pattern = as.pattern, .ty = ty, .target = target });
                return null;
            },
            .applied_tag, .record_destructure, .tuple => {
                if (self.nominalConstructionLayer(ty)) |layer| {
                    try self.pushPatTypeFrame(pat_run, .{ .nominal = target });
                    try self.enterConstructorPatWrapped(pat_run, pattern_id, layer.backing);
                    return null;
                }
                try self.enterStructuralPatType(pat_run, pattern_id, ty, target);
                return null;
            },
            .nominal => |nominal| {
                const backing_ty = if (self.nominalConstructionLayer(ty)) |layer|
                    layer.backing
                else
                    self.namedBackingType(ty) orelse ty;
                try self.pushPatTypeFrame(pat_run, .{ .nominal = target });
                try pat_run.ops.append(self.allocator, .{ .pattern = nominal.backing_pattern, .ty = backing_ty });
                return null;
            },
            .list => |list| {
                const elem_ty = self.constListElemType(ty);
                try self.pushPatTypeFrame(pat_run, .{ .list = .{
                    .target = target,
                    .count = list.patterns.len,
                    .rest = if (list.rest) |rest| .{ .index = rest.index, .has_pattern = rest.pattern != null } else null,
                } });
                for (list.patterns) |child| try pat_run.ops.append(self.allocator, .{ .pattern = child, .ty = elem_ty });
                if (list.rest) |rest| {
                    // A captured rest binds the remaining slice, which has the same
                    // list type as the scrutinee.
                    if (rest.pattern) |rest_pattern| try pat_run.ops.append(self.allocator, .{ .pattern = rest_pattern, .ty = ty });
                }
                return null;
            },
            .numeral_literal => |num| try self.lowerNumeralLiteralPattern(pattern_id, num, ty),
            .str_literal => |str| try self.lowerStringLiteralPattern(pattern_id, str, ty),
            .str_interpolation => |str| try self.lowerStrPattern(str, ty),
            .underscore => .wildcard,
        };
        return try self.addPatAtTarget(target, data);
    }

    /// Push the nominal layer frames of a constructor pattern's type, then
    /// the structural pattern at the innermost backing.
    fn enterConstructorPatWrapped(
        self: *BodyContext,
        pat_run: *PatTypeRun,
        pattern_id: checked.CheckedPatternId,
        ty: Type.TypeId,
    ) Allocator.Error!void {
        var current = ty;
        while (self.nominalConstructionLayer(current)) |layer| {
            try self.pushPatTypeFrame(pat_run, .{ .nominal = .{ .ty = layer.named } });
            current = layer.backing;
        }
        switch (self.view.bodies.pattern(pattern_id).data) {
            .applied_tag, .record_destructure, .tuple => {},
            .pending, .assign, .as, .nominal, .list, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => Common.invariant("nominal constructor pattern lowering reached a non-constructor checked pattern"),
        }
        try self.enterStructuralPatType(pat_run, pattern_id, current, .{ .ty = current });
    }

    fn enterStructuralPatType(
        self: *BodyContext,
        pat_run: *PatTypeRun,
        pattern_id: checked.CheckedPatternId,
        ty: Type.TypeId,
        target: PatTarget,
    ) Allocator.Error!void {
        const pattern = self.view.bodies.pattern(pattern_id);
        switch (pattern.data) {
            .applied_tag => |tag| {
                const name = try self.tagName(self.view, tag.name);
                try self.pushPatTypeFrame(pat_run, .{ .tag = .{ .target = target, .name = name } });
                try self.appendPatTypeChildren(pat_run, tag.args, self.tagPayloadTypes(ty, name));
            },
            .tuple => |items| {
                try self.pushPatTypeFrame(pat_run, .{ .tuple = target });
                try self.appendPatTypeChildren(pat_run, items, self.tupleItemTypes(ty));
            },
            .record_destructure => |destructs| {
                try self.pushPatTypeFrame(pat_run, .{ .record = target });
                for (destructs) |destruct| {
                    const child = switch (destruct.kind) {
                        .required, .sub_pattern => |child_pattern| child_pattern,
                        .rest => |rest_pattern| {
                            if (self.patternIsIgnored(rest_pattern)) continue;
                            Common.invariant("record rest pattern must be lowered to explicit rest-record construction before Monotype output");
                        },
                    };
                    // Optional-field destructs never reach the typed pattern family:
                    // the explicit-binding routes and match translation own them
                    // (design.md "Field Kinds").
                    if ((try self.recordDestructFieldKind(pattern.ty, destruct)) == .optional) {
                        Common.invariant("optional-field record destructure reached typed pattern lowering");
                    }
                    const name = try self.recordFieldName(self.view, destruct.label);
                    try pat_run.field_names.append(self.allocator, name);
                    try pat_run.ops.append(self.allocator, .{ .pattern = child, .ty = self.recordFieldType(ty, name) });
                }
            },
            .pending, .assign, .as, .nominal, .list, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => unreachable,
        }
    }

    fn addPatAtTarget(self: *BodyContext, target: PatTarget, data: BodyPatData) Allocator.Error!DraftPatId {
        return switch (target) {
            .cell => |cell| try self.addPatWithTypeCell(cell, data),
            .ty => |ty| try self.addPat(.{ .ty = ty, .data = data }),
        };
    }

    fn finishPatType(self: *BodyContext, pat_run: *PatTypeRun, frame: PatTypeFrame) Allocator.Error!DraftPatId {
        const results = pat_run.results.items[frame.results_start..];
        switch (frame.kind) {
            .nominal => |target| return try self.addPatAtTarget(target, .{ .nominal = results[0] }),
            .as => |as| return try self.addPatAtTarget(as.target, .{ .as = .{ .pattern = results[0], .local = as.local } }),
            .tag => |tag| return try self.addPatAtTarget(tag.target, .{ .tag = .{
                .name = tag.name,
                .payloads = try self.addPatSpan(results),
            } }),
            .tuple => |target| return try self.addPatAtTarget(target, .{ .tuple = try self.addPatSpan(results) }),
            .list => |list| {
                const rest: ?DraftListRestPattern = if (list.rest) |rest| .{
                    .index = rest.index,
                    .pattern = if (rest.has_pattern) results[list.count] else null,
                } else null;
                return try self.addPatAtTarget(list.target, .{ .list = .{
                    .patterns = try self.addPatSpan(results[0..list.count]),
                    .rest = rest,
                } });
            },
            .record => |target| {
                const field_names = pat_run.field_names.items[frame.names_start..];
                std.debug.assert(field_names.len == results.len);
                const lowered = try self.allocator.alloc(DraftRecordDestruct, results.len);
                defer self.allocator.free(lowered);
                for (lowered, field_names, results) |*slot, name, pat| slot.* = .{ .name = name, .pattern = pat };
                return try self.addPatAtTarget(target, .{ .record = try self.addRecordDestructSpan(lowered) });
            },
        }
    }

    /// Register every user binder before lowering a continuation that may use
    /// it. Each binder keeps the exact graph cell supplied by the checked
    /// pattern node that the materialized pattern will inspect at runtime.
    fn preRegisterPatternBindersAtNode(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
    ) Allocator.Error!void {
        try self.registerPatternBindersAtNodeInMap(pattern_id, node, &self.binders, false);
    }

    /// Register the binders of `pattern_id` at `node` in source order. The
    /// pattern is walked from an explicit work list; a pattern/node pair
    /// repeated on the current path is an invariant violation, since every
    /// descent must advance.
    fn registerPatternBindersAtNodeInMap(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
        binders: *BinderMap,
        rebind_existing: bool,
    ) Allocator.Error!void {
        var active = std.AutoHashMap(PatternNodeVisit, void).init(self.allocator);
        defer active.deinit();
        var pending: std.ArrayListUnmanaged(PatternBinderVisit) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, .{ .visit = .{ .pattern = pattern_id, .node = node } });
        while (pending.pop()) |item| switch (item) {
            .exit => |key| _ = active.remove(key),
            .visit => |key| {
                if (active.contains(key)) {
                    Common.invariant("materialized pattern binder prepass repeated a pattern/node visit");
                }
                try active.put(key, {});
                try pending.append(self.allocator, .{ .exit = key });
                const start = pending.items.len;
                try self.preRegisterPatternBindersAtNodeStep(key.pattern, key.node, binders, rebind_existing, &pending);
                std.mem.reverse(PatternBinderVisit, pending.items[start..]);
            },
        };
    }

    const PatternBinderVisit = union(enum) {
        visit: PatternNodeVisit,
        /// Every descendant of this visit is registered.
        exit: PatternNodeVisit,
    };

    fn preRegisterPatternBinderAtNode(
        self: *BodyContext,
        binder: checked.PatternBinderId,
        node: NodeId,
        binders: *BinderMap,
        rebind_existing: bool,
    ) Allocator.Error!void {
        if (binders.get(binder)) |existing| {
            if (self.draft.currentOwnerOwnsCore(.locals, @backingInt(existing))) {
                if (rebind_existing) {
                    self.draft.setLocalType(existing, DraftTypeCell.fromGraphNode(node));
                    return;
                }
                const existing_node = try self.localTypeCell(existing).toGraphNode(self.graph);
                if (!self.graph.sameClass(existing_node, node)) {
                    Common.invariant("materialized pattern binder was pre-registered at a different graph class");
                }
                return;
            }
        }
        if (rebind_existing) {
            Common.invariant("match pattern binder was not pre-registered before exact record-field/tag-payload binding");
        }
        const cell = DraftTypeCell.fromGraphNode(node);
        const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), cell, binder);
        try self.bindLocalName(local, binder);
        try binders.put(binder, local);
    }

    /// Register one pattern's own binder; its subpatterns go on `pending`
    /// with the graph nodes they bind at.
    fn preRegisterPatternBindersAtNodeStep(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
        binders: *BinderMap,
        rebind_existing: bool,
        pending: *std.ArrayListUnmanaged(PatternBinderVisit),
    ) Allocator.Error!void {
        const pattern = self.view.bodies.pattern(pattern_id);
        switch (pattern.data) {
            .assign => |binder| try self.preRegisterPatternBinderAtNode(binder, node, binders, rebind_existing),
            .as => |as| {
                try self.preRegisterPatternBinderAtNode(as.binder, node, binders, rebind_existing);
                try self.queuePatternBinderVisit(pending, as.pattern, node);
            },
            .applied_tag => |tag| {
                if ((try self.graph.content(node)) == .named) {
                    const backing = (try self.graph.namedNodes(node)).backing orelse
                        Common.invariant("nominal tag pattern had no runtime backing");
                    if (backing.node == node) Common.invariant("nominal tag pattern backing did not advance");
                    try self.queuePatternBinderVisit(pending, pattern_id, backing.node);
                } else {
                    const name = try self.tagName(self.view, tag.name);
                    for (tag.args, 0..) |arg, payload_index| {
                        try self.queuePatternBinderVisit(pending, arg, try self.graph.tagPayloadNode(node, name, payload_index));
                    }
                }
            },
            .nominal => |nominal| {
                const backing = (try self.graph.namedNodes(node)).backing orelse
                    Common.invariant("nominal pattern had no runtime backing");
                if (backing.node == node) Common.invariant("nominal pattern backing did not advance");
                try self.queuePatternBinderVisit(pending, nominal.backing_pattern, backing.node);
            },
            .record_destructure => |destructs| {
                if ((try self.graph.content(node)) == .named) {
                    const backing = (try self.graph.namedNodes(node)).backing orelse
                        Common.invariant("nominal record pattern had no runtime backing");
                    if (backing.node == node) Common.invariant("nominal record pattern backing did not advance");
                    try self.queuePatternBinderVisit(pending, pattern_id, backing.node);
                } else {
                    for (destructs) |destruct| switch (destruct.kind) {
                        .required, .sub_pattern => |child| {
                            // A destructured OPTIONAL field's binders hold the
                            // slot materialized as Try, so they register at
                            // the sub-pattern's own checked-type node, not
                            // the record's tagged slot node (design.md
                            // "Field Kinds").
                            if ((try self.recordDestructFieldKind(pattern.ty, destruct)) == .optional) {
                                try self.queuePatternBinderVisit(pending, child, try self.instNode(self.view.bodies.pattern(child).ty));
                                continue;
                            }
                            const name = try self.recordFieldName(self.view, destruct.label);
                            try self.queuePatternBinderVisit(pending, child, try self.graph.recordFieldNode(node, name));
                        },
                        .rest => |rest| {
                            if (self.patternIsIgnored(rest)) continue;
                            const rest_node = try self.recordRestNodeForPattern(node, destructs, rest);
                            try self.queuePatternBinderVisit(pending, rest, rest_node);
                        },
                    };
                }
            },
            .list => |list| {
                const elem_node = try self.graph.listElementNode(node);
                for (list.patterns) |child| try self.queuePatternBinderVisit(pending, child, elem_node);
                if (list.rest) |rest| {
                    if (rest.pattern) |rest_pattern| {
                        try self.queuePatternBinderVisit(pending, rest_pattern, node);
                    }
                }
            },
            .tuple => |items| {
                if ((try self.graph.content(node)) == .named) {
                    const backing = (try self.graph.namedNodes(node)).backing orelse
                        Common.invariant("nominal tuple pattern had no runtime backing");
                    if (backing.node == node) Common.invariant("nominal tuple pattern backing did not advance");
                    try self.queuePatternBinderVisit(pending, pattern_id, backing.node);
                } else {
                    const item_nodes = try self.graph.tupleItemNodes(node);
                    if (items.len != item_nodes.len) Common.invariant("tuple pattern arity differed from graph tuple arity");
                    for (items, item_nodes) |item, item_node| {
                        try self.queuePatternBinderVisit(pending, item, item_node);
                    }
                }
            },
            .str_interpolation => |str| {
                for (str.steps) |step| {
                    if (step.capture) |capture| try self.queuePatternBinderVisit(pending, capture, node);
                }
            },
            .pending,
            .numeral_literal,
            .str_literal,
            .underscore,
            .runtime_error,
            => {},
        }
    }

    fn queuePatternBinderVisit(
        self: *BodyContext,
        pending: *std.ArrayListUnmanaged(PatternBinderVisit),
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
    ) Allocator.Error!void {
        try pending.append(self.allocator, .{ .visit = .{ .pattern = pattern_id, .node = node } });
    }

    /// Lower the directly representable shell of a recursively materialized
    /// pattern. Descendants needing runtime field, item, or tag-payload reads
    /// become compiler-local binders and explicit pending plans.
    fn lowerPatternShellAtNode(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
        pending: *std.ArrayList(PendingMaterializedPattern),
    ) Allocator.Error!DraftPatId {
        var active = std.AutoHashMap(PatternNodeVisit, void).init(self.allocator);
        defer active.deinit();
        return try self.lowerPatternShellAtNodeInner(pattern_id, node, pending, &active);
    }

    /// A chain of nominal wrappers descends to its backing in a loop; the
    /// wrappers are applied around the backing's shell afterward.
    fn lowerPatternShellAtNodeInner(
        self: *BodyContext,
        root_pattern: checked.CheckedPatternId,
        root_node: NodeId,
        pending: *std.ArrayList(PendingMaterializedPattern),
        active: *std.AutoHashMap(PatternNodeVisit, void),
    ) Allocator.Error!DraftPatId {
        var wrappers: std.ArrayListUnmanaged(DraftTypeCell) = .empty;
        defer wrappers.deinit(self.allocator);
        var pattern_id = root_pattern;
        var node = root_node;
        var shell = while (true) {
            const key: PatternNodeVisit = .{ .pattern = pattern_id, .node = node };
            if (active.contains(key)) {
                Common.invariant("materialized pattern shell repeated an active pattern/node visit");
            }
            try active.put(key, {});
            switch (try self.lowerPatternShellLevel(pattern_id, node, pending)) {
                .shell => |shell| break shell,
                .nominal => |next| {
                    try wrappers.append(self.allocator, DraftTypeCell.fromGraphNode(next.representation_node));
                    pattern_id = next.pattern;
                    node = next.backing;
                },
            }
        };
        while (wrappers.pop()) |wrapper_cell| {
            shell = try self.addPatWithTypeCell(wrapper_cell, .{ .nominal = shell });
        }
        return shell;
    }

    /// One level of a materialization shell: the lowered shell, or the
    /// nominal backing the shell continues into.
    fn lowerPatternShellLevel(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
        pending: *std.ArrayList(PendingMaterializedPattern),
    ) Allocator.Error!union(enum) {
        shell: DraftPatId,
        nominal: struct { representation_node: NodeId, pattern: checked.CheckedPatternId, backing: NodeId },
    } {
        const cell = DraftTypeCell.fromGraphNode(node);
        if (try self.patternRequiresOwnMaterialization(pattern_id)) {
            return .{ .shell = try self.lowerPatternPlanPlaceholderAtNode(pattern_id, node, pending) };
        }

        const pattern = self.view.bodies.pattern(pattern_id);
        const representation_node = (try self.constructorRepresentationNode(node));
        const data: BodyPatData = switch (pattern.data) {
            .as => |as| .{ .as = .{
                .pattern = try self.lowerPatternPlanPlaceholderAtNode(as.pattern, node, pending),
                .local = self.currentOwnerPatternBinderLocal(as.binder) orelse
                    Common.invariant("materialized as-pattern binder was not pre-registered"),
            } },
            .applied_tag => |tag| blk: {
                if ((try self.graph.content(representation_node)) == .named) {
                    const backing = (try self.graph.namedNodes(representation_node)).backing orelse
                        Common.invariant("nominal tag pattern had no runtime backing");
                    if (backing.node == representation_node) Common.invariant("nominal tag pattern shell backing did not advance");
                    return .{ .nominal = .{ .representation_node = representation_node, .pattern = pattern_id, .backing = backing.node } };
                }
                const name = try self.tagName(self.view, tag.name);
                const payloads = try self.allocator.alloc(DraftPatId, tag.args.len);
                defer self.allocator.free(payloads);
                for (tag.args, 0..) |arg, payload_index| {
                    payloads[payload_index] = try self.lowerPatternPlanPlaceholderAtNode(
                        arg,
                        try self.graph.tagPayloadNode(representation_node, name, payload_index),
                        pending,
                    );
                }
                break :blk .{ .tag = .{ .name = name, .payloads = try self.addPatSpan(payloads) } };
            },
            .nominal => |nominal| {
                if ((try self.graph.content(representation_node)) != .named) {
                    Common.invariant("checked nominal pattern had no nominal graph representation");
                }
                const backing = (try self.graph.namedNodes(representation_node)).backing orelse
                    Common.invariant("nominal pattern had no runtime backing");
                if (backing.node == representation_node) Common.invariant("nominal pattern shell backing did not advance");
                return .{ .nominal = .{ .representation_node = representation_node, .pattern = nominal.backing_pattern, .backing = backing.node } };
            },
            .record_destructure => |destructs| blk: {
                if ((try self.graph.content(representation_node)) == .named) {
                    const backing = (try self.graph.namedNodes(representation_node)).backing orelse
                        Common.invariant("nominal record pattern had no runtime backing");
                    if (backing.node == representation_node) Common.invariant("nominal record pattern shell backing did not advance");
                    return .{ .nominal = .{ .representation_node = representation_node, .pattern = pattern_id, .backing = backing.node } };
                }
                var lowered = std.ArrayList(DraftRecordDestruct).empty;
                defer lowered.deinit(self.allocator);
                for (destructs) |destruct| {
                    const child = switch (destruct.kind) {
                        .required, .sub_pattern => |child| child,
                        .rest => |rest| {
                            if (self.patternIsIgnored(rest)) continue;
                            Common.invariant("record-rest pattern reached directly representable materialization shell");
                        },
                    };
                    const name = try self.recordFieldName(self.view, destruct.label);
                    try lowered.append(self.allocator, .{
                        .name = name,
                        .pattern = try self.lowerPatternPlanPlaceholderAtNode(
                            child,
                            try self.graph.recordFieldNode(representation_node, name),
                            pending,
                        ),
                    });
                }
                break :blk .{ .record = try self.addRecordDestructSpan(lowered.items) };
            },
            .tuple => |items| blk: {
                if ((try self.graph.content(representation_node)) == .named) {
                    const backing = (try self.graph.namedNodes(representation_node)).backing orelse
                        Common.invariant("nominal tuple pattern had no runtime backing");
                    if (backing.node == representation_node) Common.invariant("nominal tuple pattern shell backing did not advance");
                    return .{ .nominal = .{ .representation_node = representation_node, .pattern = pattern_id, .backing = backing.node } };
                }
                const item_nodes = try self.graph.tupleItemNodes(representation_node);
                if (items.len != item_nodes.len) Common.invariant("tuple pattern arity differed from graph tuple arity");
                const lowered = try self.allocator.alloc(DraftPatId, items.len);
                defer self.allocator.free(lowered);
                for (items, item_nodes, 0..) |item, item_node, index| {
                    lowered[index] = try self.lowerPatternPlanPlaceholderAtNode(item, item_node, pending);
                }
                break :blk .{ .tuple = try self.addPatSpan(lowered) };
            },
            .assign,
            .numeral_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            => return .{ .shell = try self.lowerPatternAtNode(pattern_id, node) },
            .list => unreachable,
            .pending,
            .runtime_error,
            => Common.invariant("non-runtime checked pattern reached materialization shell lowering"),
        };
        return .{ .shell = try self.addPatWithTypeCell(cell, data) };
    }

    fn lowerPatternPlanPlaceholderAtNode(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
        pending: *std.ArrayList(PendingMaterializedPattern),
    ) Allocator.Error!DraftPatId {
        const cell = DraftTypeCell.fromGraphNode(node);
        const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), cell, null);
        try pending.append(self.allocator, .{ .pattern = pattern_id, .local = local, .cell = cell });
        return try self.addPatWithTypeCell(cell, .{ .bind = local });
    }

    /// Lower a checked pattern directly from the live graph cells that its
    /// checked type has already related to the match scrutinee. Shape-free
    /// patterns retain the outer cell without inspecting it; constructor
    /// patterns project only the children they explicitly mention.
    fn lowerPatternAtNode(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
    ) Allocator.Error!DraftPatId {
        return try self.lowerPatternAtNodeInner(pattern_id, node, null);
    }

    fn lowerMatchPatternAtNode(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
        guard: ?DraftExprId,
        body: DraftExprId,
        record_rests: *std.ArrayList(PendingMatchRecordRestBinding),
    ) Allocator.Error!DraftPatId {
        var match_lowering = MatchPatternLowering{
            .guard = guard,
            .body = body,
            .record_rests = record_rests,
        };
        return try self.lowerPatternAtNodeInner(pattern_id, node, &match_lowering);
    }

    /// One step of lowering a pattern at graph nodes: a subpattern to lower,
    /// or a record rest to bind in its place among the fields.
    const PatNodeOp = union(enum) {
        at_node: struct {
            pattern: checked.CheckedPatternId,
            node: NodeId,
            /// Whether the subpattern lowers under the pat_run's match lowering.
            in_match: bool,
        },
        optional_slot: struct {
            pattern: checked.CheckedPatternId,
            slot_node: NodeId,
            result_node: NodeId,
        },
        record_rest: checked.CheckedPatternId,
    };

    /// A pattern whose subpatterns are still lowering. Its ops occupy
    /// `ops[ops_start..]`; each subpattern's result lands in `results`.
    const PatNodeFrame = struct {
        kind: union(enum) {
            /// Wrap the backing's pattern in one nominal layer at `cell`.
            nominal: DraftTypeCell,
            as: struct { cell: DraftTypeCell, local: DraftLocalId },
            tag: struct { cell: DraftTypeCell, name: names.TagNameId },
            list: struct { cell: DraftTypeCell, count: usize, rest: ?list_rest.Rest },
            tuple: DraftTypeCell,
            record: struct {
                pattern: checked.CheckedPatternId,
                cell: DraftTypeCell,
                node: NodeId,
                /// The record local a needed rest binding captures.
                source_local: ?DraftLocalId = null,
            },
            optional_as: struct { cell: DraftTypeCell, local: DraftLocalId },
            optional_present: struct { cell: DraftTypeCell, name: names.TagNameId },
        },
        ops_start: usize,
        next: usize,
        results_start: usize,
        names_start: usize,
    };

    const list_rest = struct {
        const Rest = struct { index: u32, has_pattern: bool };
    };

    const PatNodeRun = struct {
        match_lowering: ?*MatchPatternLowering,
        frames: std.ArrayListUnmanaged(PatNodeFrame) = .empty,
        ops: std.ArrayListUnmanaged(PatNodeOp) = .empty,
        results: std.ArrayListUnmanaged(DraftPatId) = .empty,
        /// Field names of record frames in flight, one pat_run per record.
        field_names: std.ArrayListUnmanaged(names.RecordFieldNameId) = .empty,

        fn deinit(pat_run: *PatNodeRun, allocator: Allocator) void {
            pat_run.field_names.deinit(allocator);
            pat_run.results.deinit(allocator);
            pat_run.ops.deinit(allocator);
            pat_run.frames.deinit(allocator);
        }
    };

    fn lowerPatternAtNodeInner(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
        match_lowering: ?*MatchPatternLowering,
    ) Allocator.Error!DraftPatId {
        return try self.runPatNode(.{ .at_node = .{ .pattern = pattern_id, .node = node, .in_match = true } }, match_lowering);
    }

    /// Lower a pattern tree at graph nodes. Each composite pattern is an
    /// explicit frame whose subpatterns lower in source order, so pattern
    /// depth never becomes native call depth.
    fn runPatNode(self: *BodyContext, root: PatNodeOp, match_lowering: ?*MatchPatternLowering) Allocator.Error!DraftPatId {
        var pat_run = PatNodeRun{ .match_lowering = match_lowering };
        defer pat_run.deinit(self.allocator);
        if (try self.enterPatNode(&pat_run, root)) |pat| return pat;
        while (true) {
            const index = pat_run.frames.items.len - 1;
            const frame = pat_run.frames.items[index];
            if (frame.next < pat_run.ops.items.len) {
                const op = pat_run.ops.items[frame.next];
                pat_run.frames.items[index].next += 1;
                switch (op) {
                    .record_rest => |rest| try self.bindPatNodeRecordRest(&pat_run, index, rest),
                    .at_node, .optional_slot => if (try self.enterPatNode(&pat_run, op)) |pat| {
                        try pat_run.results.append(self.allocator, pat);
                    },
                }
                continue;
            }

            const pat = try self.finishPatNode(&pat_run, frame);
            _ = pat_run.frames.pop();
            pat_run.ops.shrinkRetainingCapacity(frame.ops_start);
            pat_run.results.shrinkRetainingCapacity(frame.results_start);
            pat_run.field_names.shrinkRetainingCapacity(frame.names_start);
            if (pat_run.frames.items.len == 0) return pat;
            try pat_run.results.append(self.allocator, pat);
        }
    }

    fn pushPatNodeFrame(self: *BodyContext, pat_run: *PatNodeRun, kind: @FieldType(PatNodeFrame, "kind")) Allocator.Error!void {
        try pat_run.frames.append(self.allocator, .{
            .kind = kind,
            .ops_start = pat_run.ops.items.len,
            .next = pat_run.ops.items.len,
            .results_start = pat_run.results.items.len,
            .names_start = pat_run.field_names.items.len,
        });
    }

    fn appendPatNodeChild(self: *BodyContext, pat_run: *PatNodeRun, pattern: checked.CheckedPatternId, node: NodeId, in_match: bool) Allocator.Error!void {
        try pat_run.ops.append(self.allocator, .{ .at_node = .{ .pattern = pattern, .node = node, .in_match = in_match } });
    }

    /// The pattern a leaf op lowers to, or null after pushing the frame that
    /// lowers a composite one.
    fn enterPatNode(self: *BodyContext, pat_run: *PatNodeRun, op: PatNodeOp) Allocator.Error!?DraftPatId {
        switch (op) {
            .record_rest => unreachable,
            .at_node => |at| return try self.enterPatNodeAtNode(pat_run, at.pattern, at.node, at.in_match),
            .optional_slot => |slot| return try self.enterPatNodeOptionalSlot(pat_run, slot.pattern, slot.slot_node, slot.result_node),
        }
    }

    fn enterPatNodeAtNode(
        self: *BodyContext,
        pat_run: *PatNodeRun,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
        in_match: bool,
    ) Allocator.Error!?DraftPatId {
        if (try self.patternNeedsExplicitBinding(pattern_id) and
            !self.allow_recursive_pattern_lowering_for_match)
        {
            Common.invariant("recursively materialized pattern reached ordinary graph pattern lowering");
        }
        const pattern = self.view.bodies.pattern(pattern_id);
        const cell = DraftTypeCell.fromGraphNode(node);
        const representation_node = (try self.constructorRepresentationNode(node));
        const data: BodyPatData = switch (pattern.data) {
            .pending,
            .runtime_error,
            => Common.invariant("non-runtime checked pattern reached graph-native Monotype lowering"),
            .assign => |binder| .{ .bind = try self.materializePatternBinderAtCell(binder, cell) },
            .as => |as| {
                const local = try self.materializePatternBinderAtCell(as.binder, cell);
                try self.pushPatNodeFrame(pat_run, .{ .as = .{ .cell = cell, .local = local } });
                try self.appendPatNodeChild(pat_run, as.pattern, node, in_match);
                return null;
            },
            .applied_tag => |tag| {
                if ((try self.graph.content(representation_node)) == .named) {
                    const backing = (try self.graph.namedNodes(representation_node)).backing orelse
                        Common.invariant("nominal tag pattern had no runtime backing");
                    try self.pushPatNodeFrame(pat_run, .{ .nominal = DraftTypeCell.fromGraphNode(representation_node) });
                    try self.appendPatNodeChild(pat_run, pattern_id, backing.node, in_match);
                    return null;
                }
                const name = try self.tagName(self.view, tag.name);
                try self.pushPatNodeFrame(pat_run, .{ .tag = .{ .cell = cell, .name = name } });
                for (tag.args, 0..) |arg, payload_index| {
                    try self.appendPatNodeChild(pat_run, arg, try self.graph.tagPayloadNode(representation_node, name, payload_index), in_match);
                }
                return null;
            },
            .nominal => |nominal| {
                if ((try self.graph.content(representation_node)) != .named) {
                    Common.invariant("checked nominal pattern had no nominal graph representation");
                }
                const backing = (try self.graph.namedNodes(representation_node)).backing orelse
                    Common.invariant("nominal pattern had no runtime backing");
                try self.pushPatNodeFrame(pat_run, .{ .nominal = DraftTypeCell.fromGraphNode(representation_node) });
                try self.appendPatNodeChild(pat_run, nominal.backing_pattern, backing.node, in_match);
                return null;
            },
            .record_destructure => |destructs| {
                if ((try self.graph.content(representation_node)) == .named) {
                    const backing = (try self.graph.namedNodes(representation_node)).backing orelse
                        Common.invariant("nominal record pattern had no runtime backing");
                    if (backing.node == representation_node) Common.invariant("nominal record pattern backing did not advance");
                    try self.pushPatNodeFrame(pat_run, .{ .nominal = DraftTypeCell.fromGraphNode(representation_node) });
                    try self.appendPatNodeChild(pat_run, pattern_id, backing.node, in_match);
                    return null;
                }
                try self.pushPatNodeFrame(pat_run, .{ .record = .{ .pattern = pattern_id, .cell = cell, .node = node } });
                const record_checked_ty = pattern.ty;
                for (destructs) |destruct| {
                    switch (destruct.kind) {
                        .required, .sub_pattern => |child| {
                            const name = try self.recordFieldName(self.view, destruct.label);
                            try pat_run.field_names.append(self.allocator, name);
                            if ((try self.recordDestructFieldKind(record_checked_ty, destruct)) == .optional) {
                                // A destructured OPTIONAL field's sub-pattern is typed
                                // at the nominal Try while the slot holds the tagged
                                // `[#Missing, #Present(v)]` union: translate it into
                                // slot space, queueing binder preludes for the
                                // enclosing branch (design.md "Field Kinds").
                                try pat_run.ops.append(self.allocator, .{ .optional_slot = .{
                                    .pattern = child,
                                    .slot_node = try self.graph.recordFieldNode(representation_node, name),
                                    .result_node = try self.instNode(self.view.bodies.pattern(child).ty),
                                } });
                                continue;
                            }
                            try self.appendPatNodeChild(pat_run, child, try self.graph.recordFieldNode(representation_node, name), in_match);
                        },
                        .rest => |rest| {
                            if (self.patternIsIgnored(rest)) continue;
                            try pat_run.ops.append(self.allocator, .{ .record_rest = rest });
                        },
                    }
                }
                return null;
            },
            .list => |list| {
                const elem_node = try self.graph.listElementNode(node);
                try self.pushPatNodeFrame(pat_run, .{ .list = .{
                    .cell = cell,
                    .count = list.patterns.len,
                    .rest = if (list.rest) |rest| .{ .index = rest.index, .has_pattern = rest.pattern != null } else null,
                } });
                for (list.patterns) |child| try self.appendPatNodeChild(pat_run, child, elem_node, in_match);
                if (list.rest) |rest| {
                    if (rest.pattern) |rest_pattern| try self.appendPatNodeChild(pat_run, rest_pattern, node, in_match);
                }
                return null;
            },
            .tuple => |items| {
                if ((try self.graph.content(representation_node)) == .named) {
                    const backing = (try self.graph.namedNodes(representation_node)).backing orelse
                        Common.invariant("nominal tuple pattern had no runtime backing");
                    try self.pushPatNodeFrame(pat_run, .{ .nominal = DraftTypeCell.fromGraphNode(representation_node) });
                    try self.appendPatNodeChild(pat_run, pattern_id, backing.node, in_match);
                    return null;
                }
                const item_nodes = try self.graph.tupleItemNodes(representation_node);
                if (items.len != item_nodes.len) Common.invariant("tuple pattern arity differed from graph tuple arity");
                try self.pushPatNodeFrame(pat_run, .{ .tuple = cell });
                for (items, item_nodes) |item, item_node| try self.appendPatNodeChild(pat_run, item, item_node, in_match);
                return null;
            },
            .numeral_literal => |num| blk: {
                const ty = try self.activeTypeFromNode(node);
                break :blk try self.lowerNumeralLiteralPattern(pattern_id, num, ty);
            },
            .str_literal => |str| blk: {
                const ty = try self.activeTypeFromNode(node);
                break :blk try self.lowerStringLiteralPattern(pattern_id, str, ty);
            },
            .str_interpolation => |str| try self.lowerStrPattern(str, try self.activeTypeFromNode(node)),
            .underscore => .wildcard,
        };
        return try self.addPatWithTypeCell(cell, data);
    }

    fn enterPatNodeOptionalSlot(
        self: *BodyContext,
        pat_run: *PatNodeRun,
        root_child: checked.CheckedPatternId,
        slot_node: NodeId,
        root_result_node: NodeId,
    ) Allocator.Error!?DraftPatId {
        const slot_cell = DraftTypeCell.fromGraphNode(slot_node);
        var child = root_child;
        var result_node = root_result_node;
        // A nominal Try pattern translates as its backing.
        const pattern = while (true) {
            const pattern = self.view.bodies.pattern(child);
            switch (pattern.data) {
                .nominal => |nominal| {
                    child = nominal.backing_pattern;
                    result_node = (try self.optionalTryBackingNode(result_node));
                },
                .pending, .assign, .as, .applied_tag, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => break pattern,
            }
        };
        const data: BodyPatData = switch (pattern.data) {
            .nominal => unreachable,
            .underscore => .wildcard,
            .assign => |binder| blk: {
                const slot_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), slot_cell, null);
                try self.queueOptionalDestructSlotBind(binder, slot_local, slot_node, result_node);
                break :blk .{ .bind = slot_local };
            },
            .as => |as| {
                const slot_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), slot_cell, null);
                try self.queueOptionalDestructSlotBind(as.binder, slot_local, slot_node, result_node);
                try self.pushPatNodeFrame(pat_run, .{ .optional_as = .{ .cell = slot_cell, .local = slot_local } });
                try pat_run.ops.append(self.allocator, .{ .optional_slot = .{ .pattern = as.pattern, .slot_node = slot_node, .result_node = result_node } });
                return null;
            },
            .applied_tag => |tag| blk: {
                const tag_name = try self.tagName(self.view, tag.name);
                const ok_name = try self.nameStoreMut().internTagLabel("Ok");
                const err_name = try self.nameStoreMut().internTagLabel("Err");
                const present_name = try self.nameStoreMut().internTagLabel(Builder.optional_slot_present_tag);
                const missing_name = try self.nameStoreMut().internTagLabel(Builder.optional_slot_missing_tag);
                if (tag.args.len != 1) {
                    Common.invariant("optional destructure Try pattern tag did not carry exactly one payload");
                }
                if (tag_name == ok_name) {
                    const payload_node = try self.graph.tagPayloadNode(slot_node, present_name, 0);
                    try self.pushPatNodeFrame(pat_run, .{ .optional_present = .{ .cell = slot_cell, .name = present_name } });
                    try self.appendPatNodeChild(pat_run, tag.args[0], payload_node, false);
                    return null;
                }
                if (tag_name == err_name) {
                    const err_node = try self.graph.tagPayloadNode(
                        (try self.optionalTryBackingNode(result_node)),
                        err_name,
                        0,
                    );
                    try self.queueOptionalDestructErrPayloadBinds(tag.args[0], err_node);
                    break :blk .{ .tag = .{
                        .name = missing_name,
                        .payloads = .empty(),
                    } };
                }
                Common.invariant("optional destructure Try pattern used a tag other than Ok or Err");
            },
            .pending,
            .runtime_error,
            .record_destructure,
            .tuple,
            .list,
            .numeral_literal,
            .str_literal,
            .str_interpolation,
            => Common.invariant("optional destructure sub-pattern had a non-Try checked shape"),
        };
        return try self.addPatWithTypeCell(slot_cell, data);
    }

    /// Bind a named record rest in place among its record's fields, when the
    /// guard or body reads it.
    fn bindPatNodeRecordRest(self: *BodyContext, pat_run: *PatNodeRun, index: usize, rest: checked.CheckedPatternId) Allocator.Error!void {
        const record = &pat_run.frames.items[index].kind.record;
        const lowering = pat_run.match_lowering orelse
            Common.invariant("record rest pattern must be lowered to explicit rest-record construction before Monotype output");
        const rest_data = self.view.bodies.pattern(rest).data;
        if (rest_data != .assign) Common.invariant("named record rest was not an assignment pattern");
        const rest_binder = rest_data.assign;
        const rest_local = self.currentOwnerPatternBinderLocal(rest_binder) orelse
            Common.invariant("record rest binder was not pre-registered at its exact graph node");
        const needed_by_guard = if (lowering.guard) |guard|
            try self.exprDependsOnFreeLocal(guard, rest_local)
        else
            false;
        const needed_by_body = try self.exprDependsOnFreeLocal(lowering.body, rest_local);
        if (!needed_by_guard and !needed_by_body) return;

        const captured = record.source_local orelse blk: {
            const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), record.cell, null);
            pat_run.frames.items[index].kind.record.source_local = local;
            break :blk local;
        };
        const rest_cell = self.localTypeCell(rest_local);
        try lowering.record_rests.append(self.allocator, .{
            .source_local = captured,
            .source_node = pat_run.frames.items[index].kind.record.node,
            .rest_local = rest_local,
            .rest_node = try rest_cell.toGraphNode(self.graph),
            .rest_cell = rest_cell,
            .before_guard = needed_by_guard,
        });
    }

    fn finishPatNode(self: *BodyContext, pat_run: *PatNodeRun, frame: PatNodeFrame) Allocator.Error!DraftPatId {
        const results = pat_run.results.items[frame.results_start..];
        switch (frame.kind) {
            .nominal => |cell| return try self.addPatWithTypeCell(cell, .{ .nominal = results[0] }),
            inline .as, .optional_as => |as| return try self.addPatWithTypeCell(as.cell, .{ .as = .{ .pattern = results[0], .local = as.local } }),
            .tag => |tag| return try self.addPatWithTypeCell(tag.cell, .{ .tag = .{
                .name = tag.name,
                .payloads = try self.addPatSpan(results),
            } }),
            .optional_present => |present| return try self.addPatWithTypeCell(present.cell, .{ .tag = .{
                .name = present.name,
                .payloads = try self.addPatSpan(results),
            } }),
            .tuple => |cell| return try self.addPatWithTypeCell(cell, .{ .tuple = try self.addPatSpan(results) }),
            .list => |list| {
                const rest: ?DraftListRestPattern = if (list.rest) |rest| .{
                    .index = rest.index,
                    .pattern = if (rest.has_pattern) results[list.count] else null,
                } else null;
                return try self.addPatWithTypeCell(list.cell, .{ .list = .{
                    .patterns = try self.addPatSpan(results[0..list.count]),
                    .rest = rest,
                } });
            },
            .record => |record| {
                const field_names = pat_run.field_names.items[frame.names_start..];
                std.debug.assert(field_names.len == results.len);
                const lowered = try self.allocator.alloc(DraftRecordDestruct, results.len);
                defer self.allocator.free(lowered);
                for (lowered, field_names, results) |*slot, name, pat| slot.* = .{ .name = name, .pattern = pat };
                const record_pattern = try self.addPatWithTypeCell(record.cell, .{
                    .record = try self.addRecordDestructSpan(lowered),
                });
                const captured = record.source_local orelse return record_pattern;
                return try self.addPatWithTypeCell(record.cell, .{ .as = .{
                    .pattern = record_pattern,
                    .local = captured,
                } });
            },
        }
    }

    fn lowerMatchRecordRestBindings(
        self: *BodyContext,
        pending: []const PendingMatchRecordRestBinding,
        original_body: DraftExprId,
    ) Allocator.Error!LoweredMatchRecordRestBindings {
        var guard_bindings = std.ArrayList(DraftStmtId).empty;
        defer guard_bindings.deinit(self.allocator);
        var body_bindings = std.ArrayList(DraftStmtId).empty;
        defer body_bindings.deinit(self.allocator);

        for (pending) |binding| {
            const source_cell = DraftTypeCell.fromGraphNode(binding.source_node);
            const source = try self.addExprWithTypeCell(source_cell, .{ .local = binding.source_local });
            const value = try self.lowerRecordRestValueWithTypeCell(
                source,
                binding.source_node,
                binding.rest_cell,
                binding.rest_node,
            );
            const stmt = try self.addStmt(.{ .let_ = .{
                .pat = try self.addPatWithTypeCell(binding.rest_cell, .{ .bind = binding.rest_local }),
                .value = value,
            } });
            if (binding.before_guard) {
                try guard_bindings.append(self.allocator, stmt);
            } else {
                try body_bindings.append(self.allocator, stmt);
            }
        }

        const body = if (body_bindings.items.len == 0)
            original_body
        else
            try self.addExprWithTypeCell(self.exprTypeCell(original_body), .{ .block = .{
                .statements = try self.addStmtSpan(body_bindings.items),
                .final_expr = original_body,
            } });
        return .{
            .guard_bindings = try self.addStmtSpan(guard_bindings.items),
            .body = body,
        };
    }

    fn lowerStrPattern(
        self: *BodyContext,
        str: anytype,
        ty: Type.TypeId,
    ) Allocator.Error!BodyPatData {
        const steps = try self.allocator.alloc(DraftStrPatternStep, str.steps.len);
        defer self.allocator.free(steps);

        for (str.steps, 0..) |step, i| {
            steps[i] = .{
                .capture = if (step.capture) |capture| try self.lowerPatternAtType(capture, ty) else null,
                .delimiter = try self.lowerStringLiteral(step.delimiter),
            };
        }

        return .{ .str_pattern = .{
            .prefix = try self.lowerStringLiteral(str.prefix),
            .steps = try self.addStrPatternStepSpan(steps),
            .end = switch (str.end) {
                .exact => .exact,
                .tail => .tail,
            },
        } };
    }

    fn patternIsIgnored(self: *BodyContext, pattern_id: checked.CheckedPatternId) bool {
        return switch (self.view.bodies.pattern(pattern_id).data) {
            .underscore => true,
            .pending, .assign, .as, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .runtime_error => false,
        };
    }

    /// Specialize a checker-retained generalized numeral pattern at its
    /// concrete Monotype. Builtin numeric primitives consume the parser-owned
    /// exact digits directly; only a genuinely custom target executes the
    /// checker-selected conversion and equality guard.
    fn lowerNumeralLiteralPattern(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        numeral: anytype,
        ty: Type.TypeId,
    ) Allocator.Error!BodyPatData {
        return switch (self.shapeContent(ty)) {
            .primitive => try self.numeralPatBits(numeral.literal, ty),
            .named, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => if (numeral.guard) |guard|
                try self.bindLiteralGuardPattern(pattern_id, guard, ty)
            else
                Common.invariant("custom numeral pattern had no checked conversion"),
        };
    }

    /// Specialize a checker-retained generalized quote pattern at its concrete
    /// Monotype. Primitive Str uses the literal directly; another primitive
    /// can never match, and a custom target uses the checked conversion guard.
    fn lowerStringLiteralPattern(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        str: anytype,
        ty: Type.TypeId,
    ) Allocator.Error!BodyPatData {
        return switch (self.shapeContent(ty)) {
            .primitive => |primitive| if (primitive == .str)
                .{ .str_lit = try self.lowerStringLiteral(str.literal) }
            else
                try self.bindNeverMatchPattern(ty),
            .named, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => if (str.guard) |guard|
                try self.bindLiteralGuardPattern(pattern_id, guard, ty)
            else
                Common.invariant("custom string pattern had no checked conversion"),
        };
    }

    /// Lower a literal pattern on a non-builtin number type to a fresh bind,
    /// recording an equality condition for the enclosing match branch.
    fn bindLiteralGuardPattern(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        condition: checked.CheckedExprId,
        ty: Type.TypeId,
    ) Allocator.Error!BodyPatData {
        const binder = self.view.bodies.literalPatternBinder(pattern_id);
        const local = if (self.currentOwnerPatternBinderLocal(binder)) |existing| existing else blk: {
            const new_local = try self.addLocalWithBinder(self.builder.symbols.fresh(), ty, binder);
            try self.bindLocalName(new_local, binder);
            try self.binders.put(binder, new_local);
            break :blk new_local;
        };
        try self.pattern_literal_guards.append(self.allocator, .{ .condition = condition });
        return .{ .bind = local };
    }

    /// Lower a literal pattern whose value its concrete type cannot represent
    /// to a fresh bind guarded by a constant-false condition: the branch
    /// falls through to the next one, exactly as if the scrutinee had been
    /// compared against the unrepresentable value.
    fn bindNeverMatchPattern(self: *BodyContext, ty: Type.TypeId) Allocator.Error!BodyPatData {
        const local = try self.addLocal(self.builder.symbols.fresh(), ty);
        try self.pattern_literal_guards.append(self.allocator, .never);
        return .{ .bind = local };
    }

    /// Consume the ordinary checked equality expression retained by the
    /// pattern. Structural and callable equality use the same dispatch path
    /// as source `==`, including specialization evidence and local captures.
    fn lowerPatternLiteralEq(self: *BodyContext, entry: PatternLiteralGuard) Allocator.Error!DraftExprId {
        return switch (entry) {
            .condition => |condition| try self.lowerExpr(condition),
            .never => try self.boolLiteral(false, try self.primitiveType(.bool)),
        };
    }

    /// Take ownership of the literal-equality conditions collected since
    /// `start`, restoring the collection to that length.
    fn drainPatternLiteralGuards(self: *BodyContext, start: usize) Allocator.Error![]PatternLiteralGuard {
        const drained = try self.allocator.dupe(PatternLiteralGuard, self.pattern_literal_guards.items[start..]);
        self.pattern_literal_guards.shrinkRetainingCapacity(start);
        return drained;
    }

    fn applyPatternLiteralGuardsAtCell(
        self: *BodyContext,
        guards: []const PatternLiteralGuard,
        body: DraftExprId,
        fallback: DraftExprId,
        result_cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        var result = body;
        var index = guards.len;
        while (index > 0) {
            index -= 1;
            const branches = [_]DraftIfBranch{.{
                .cond = try self.lowerPatternLiteralEq(guards[index]),
                .body = result,
            }};
            result = try self.addExprWithTypeCell(result_cell, .{ .if_ = .{
                .branches = try self.addIfBranchSpan(&branches),
                .final_else = fallback,
            } });
        }
        return result;
    }

    /// Conjoin the branch's collected literal-equality conditions with its
    /// (optional) user guard, literal conditions first.
    fn conjoinPatternLiteralGuards(self: *BodyContext, user_guard: ?DraftExprId) Allocator.Error!?DraftExprId {
        if (self.pattern_literal_guards.items.len == 0) return user_guard;
        if (self.pattern_literal_guards.items.len == 1 and user_guard == null) {
            const condition = try self.lowerPatternLiteralEq(self.pattern_literal_guards.items[0]);
            self.pattern_literal_guards.clearRetainingCapacity();
            return condition;
        }
        const bool_ty = try self.primitiveType(.bool);
        const yes = try self.boolLiteral(true, bool_ty);
        const no = try self.boolLiteral(false, bool_ty);
        // Source Bool values and internal comparison predicates need not have
        // the same Monotype representation. Consume each as a condition and
        // produce one explicit primitive predicate, rather than returning a
        // source guard as a branch of a primitive-typed expression.
        var cond = if (user_guard) |guard| try self.ifExpr(guard, yes, no, bool_ty) else yes;
        var i = self.pattern_literal_guards.items.len;
        while (i > 0) {
            i -= 1;
            const eq = try self.lowerPatternLiteralEq(self.pattern_literal_guards.items[i]);
            cond = try self.ifExpr(eq, cond, no, bool_ty);
        }
        self.pattern_literal_guards.clearRetainingCapacity();
        return cond;
    }

    /// The pattern flavor of `numeralScalarBits`: an unrepresentable value
    /// lowers to a never-matching branch instead of an expression crash node
    /// (checking reports it; the arm falls through, since e.g. an I8 can
    /// never equal 300).
    fn numeralPatBits(self: *BodyContext, literal: can.ModuleEnv.NumeralLiteral, ty: Type.TypeId) Allocator.Error!BodyPatData {
        const primitive = switch (self.shapeContent(ty)) {
            .primitive => |p| p,
            .named, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("numeric literal pattern at a non-primitive Monotype type without a conversion"),
        };
        const bits = (try self.numeralScalarBits(literal, primitive)) orelse
            return try self.bindNeverMatchPattern(ty);
        return switch (bits) {
            .int => |value| .{ .int_lit = value },
            .f32 => |value| .{ .frac_f32_lit = value },
            .f64 => |value| .{ .frac_f64_lit = value },
            .dec => |value| .{ .dec_lit = value },
        };
    }
};

/// The exact-numeral target for a numeric Monotype primitive.
fn numeralTargetFromPrimitive(primitive: Type.Primitive) exact_numeral.Target {
    return switch (primitive) {
        .bool, .str, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2 => Common.invariant("non-numeric Monotype primitive has no numeral target"),
        inline .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec => |p| @field(exact_numeral.Target, @tagName(p)),
    };
}

test "completion path retains ancestors across distinct sibling visits" {
    var path = BodyContext.RequestCompletionPath.init(std.testing.allocator);
    defer path.deinit();
    const ancestor: BodyContext.RequestCompletionPair = .{
        .request = @fromBackingInt(1),
        .produced = @fromBackingInt(2),
    };
    try std.testing.expect(try path.enter(ancestor));
    for (3..4096) |index| {
        const sibling: BodyContext.RequestCompletionPair = .{
            .request = @fromBackingInt(@intCast(index)),
            .produced = @fromBackingInt(@intCast(index + 4096)),
        };
        try std.testing.expect(try path.enter(sibling));
        try std.testing.expect(!try path.enter(ancestor));
        try std.testing.expect(!try path.enter(sibling));
        path.leave(sibling);
        try std.testing.expectEqual(@as(usize, 1), path.map.count());
    }
    path.leave(ancestor);
    try std.testing.expectEqual(@as(usize, 0), path.map.count());
    try std.testing.expect(try path.enter(ancestor));
    path.leave(ancestor);
}

test "completion relation preserves recursive and shared DAG outcomes" {
    const allocator = std.testing.allocator;
    var types = Type.Store.init(allocator);
    defer types.deinit();
    var name_store = names.NameStore.init(allocator);
    defer name_store.deinit();
    const graph = try InstGraph.create(allocator, &types, &name_store);
    defer graph.destroy();
    var builder: Builder = undefined;
    builder.timing = null;
    var ctx: BodyContext = undefined;
    ctx.allocator = allocator;
    ctx.builder = &builder;
    ctx.graph = graph;
    ctx.inhabitation_visiting = .{};
    defer ctx.inhabitation_visiting.deinit(allocator);
    ctx.inhabitation_entered = .empty;
    defer ctx.inhabitation_entered.deinit(allocator);
    ctx.settled_node_uninhabited = .{ .empty, .empty };
    defer for (&ctx.settled_node_uninhabited) |*memo| memo.deinit(allocator);
    ctx.node_uninhabited_scratch = .{};
    defer ctx.node_uninhabited_scratch.deinit(allocator);

    for ([_]BodyContext.RequestCompletion{ .unchanged, .completed, .mismatch }) |expected| {
        // Each side is a recursive list of pairs. Repeated tuple edges below
        // revisit the same cycle after a sibling traversal has left the path.
        const request_items = try graph.arena().alloc(NodeId, 2);
        const produced_items = try graph.arena().alloc(NodeId, 2);
        const request_tuple = try graph.newNode(.{ .tuple = request_items });
        const produced_tuple = try graph.newNode(.{ .tuple = produced_items });
        request_items[0] = try graph.newNode(.{ .list = request_tuple });
        produced_items[0] = try graph.newNode(.{ .list = produced_tuple });
        request_items[1] = try graph.newNode(if (expected == .completed)
            .empty_tag_union
        else
            .{ .primitive = .i64 });
        produced_items[1] = try graph.newNode(.{ .primitive = if (expected == .mismatch) .str else .i64 });

        const request_siblings = try graph.arena().alloc(NodeId, 64);
        const produced_siblings = try graph.arena().alloc(NodeId, 64);
        @memset(request_siblings, request_items[0]);
        @memset(produced_siblings, produced_items[0]);
        const request = try graph.newNode(.{ .tuple = request_siblings });
        const produced = try graph.newNode(.{ .tuple = produced_siblings });
        var path = BodyContext.RequestCompletionPath.init(allocator);
        defer path.deinit();
        try std.testing.expectEqual(expected, try ctx.requestCompletionRelation(request, produced, &path, null));
        try std.testing.expectEqual(@as(usize, 0), path.map.count());
    }
}

test "materialized evidence normalization borrows unchanged contracts without allocating" {
    var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{ .fail_index = 0 });
    const target: SpecEvidenceTarget = .{
        .view = undefined,
        .target = undefined,
        .instantiation = null,
        .local_proc_context = null,
        .nested = .synthesize,
    };
    const contract = [_]SpecEvidence{
        .{ .target = &target },
        .{ .structural = .{ .derivation = .encoder } },
        .{ .from_callable = .{ .independent_callable = true } },
        .{ .from_scheme = 7 },
        .unreachable_value,
        .checked_error,
    };
    const normalized = try normalizeMaterializedEvidence(failing.allocator(), &contract);
    try std.testing.expect(normalized.ptr == &contract);
    try std.testing.expectEqual(@as(usize, contract.len), normalized.len);
    try std.testing.expectEqual(@as(usize, 0), (try normalizeMaterializedEvidence(failing.allocator(), &.{})).len);
}

test "materialized evidence normalization copies once and preserves unconsumed nested relations" {
    // One vector allocation and two changed targets, regardless of the other
    // entries or the size of their shared nested contracts.
    var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{ .fail_index = 3 });
    const allocator = failing.allocator();
    const nested_target: SpecEvidenceTarget = .{
        .view = undefined,
        .target = undefined,
        .instantiation = .{ .view = undefined, .callable_ty = @fromBackingInt(@intCast(1)) },
        .local_proc_context = @fromBackingInt(@intCast(7)),
        .nested = .synthesize,
    };
    const nested = [_]SpecEvidence{.{ .target = &nested_target }};
    var target = nested_target;
    target.nested = .{ .resolved = &nested };
    var unchanged = target;
    unchanged.instantiation = null;
    const contract = [_]SpecEvidence{
        .{ .target = &unchanged },
        .{ .target = &target },
        .{ .structural = .{ .derivation = .encoder } },
        .{ .target = &target },
    };
    const normalized = try normalizeMaterializedEvidence(allocator, &contract);
    defer allocator.free(normalized);
    defer allocator.destroy(normalized[1].target);
    defer allocator.destroy(normalized[3].target);
    try std.testing.expect(normalized.ptr != &contract);
    try std.testing.expect(normalized[0].target == &unchanged);
    try std.testing.expect(normalized[2] == .structural);
    for ([_]usize{ 1, 3 }) |index| {
        const changed = normalized[index].target;
        try std.testing.expect(changed != &target);
        try std.testing.expect(changed.instantiation == null);
        try std.testing.expectEqual(target.local_proc_context, changed.local_proc_context);
        try std.testing.expect(changed.nested.resolved.ptr == &nested);
        try std.testing.expect(changed.nested.resolved[0].target == &nested_target);
        try std.testing.expect(changed.nested.resolved[0].target.instantiation != null);
    }
    try std.testing.expect(target.instantiation != null);
    // Already-normalized evidence takes the allocation-free path on reuse.
    try std.testing.expect((try normalizeMaterializedEvidence(allocator, normalized)).ptr == normalized.ptr);
}

test "independent callable keeps target-owned evidence and rejects per-use record synthesis" {
    const resolved_entries = [_]SpecEvidence{.unreachable_value};
    const nested = NestedSpecEvidence{ .resolved = &resolved_entries };
    const reuse = static_dispatch.ConstraintEvidenceRef{
        .index = .{ .depth = 0, .index = 0 },
        .independent_callable = true,
        .reuse_slot_nested_evidence = true,
    };
    const reused = try BodyContext.dependentCallableNestedEvidenceForSchema(
        reuse,
        nested,
        .requires_record,
    );
    switch (reused) {
        .resolved => |resolved| {
            try std.testing.expectEqual(@as(usize, 1), resolved.len);
            try std.testing.expect(resolved.ptr == resolved_entries[0..].ptr);
        },
        .synthesize => return error.TestUnexpectedResult,
    }

    const synthesize = static_dispatch.ConstraintEvidenceRef{
        .index = .{ .depth = 0, .index = 0 },
        .independent_callable = true,
        .reuse_slot_nested_evidence = false,
    };
    const target_owned = try BodyContext.dependentCallableNestedEvidenceForSchema(
        synthesize,
        nested,
        .from_target,
    );
    switch (target_owned) {
        .resolved => |resolved| try std.testing.expect(resolved.ptr == resolved_entries[0..].ptr),
        .synthesize => return error.TestUnexpectedResult,
    }
    try std.testing.expectError(
        error.RequiresRecordSynthesis,
        BodyContext.dependentCallableNestedEvidenceForSchema(
            synthesize,
            nested,
            .requires_record,
        ),
    );
    const callable_derived = try BodyContext.dependentCallableNestedEvidenceForSchema(
        synthesize,
        nested,
        .from_callable,
    );
    try std.testing.expect(callable_derived == .synthesize);
}

test "queued specialization skips a body claimed immediately before dispatch" {
    const allocator = std.testing.allocator;
    var program = Ast.Program.init(allocator);
    defer program.deinit();
    const ty = try program.types.internZst(&program.names);
    const template_ref = names.ProcTemplate{
        .artifact = .{},
        // Both fields are only carried by jobs that are skipped below.
        .proc_base = undefined,
        .template = undefined,
    };
    const fn_template = Ast.FnTemplate{
        .fn_def = .{ .local_template = template_ref },
        // This test never lowers the template, so its checked type is not read.
        .source_fn_ty = undefined,
        .source_fn_key = .{},
        .mono_fn_ty = ty,
    };

    var diagnostics: Diagnostics = .{};
    var builder: Builder = undefined;
    builder.active_graph = null;
    builder.active_body_draft = null;
    builder.post_check_executor = null;
    builder.pending_spec_jobs = .empty;
    defer builder.pending_spec_jobs.deinit(allocator);
    builder.next_spec_dispatch_index = 0;
    builder.next_spec_accept_index = 0;
    builder.counters = null;
    builder.diagnostics = &diagnostics;
    builder.active_spec_job_diagnostics = null;
    builder.spec_store = specialize.SpecBuilder.init(
        allocator,
        &program.names,
        &program.types,
        &program.specs,
    );
    defer builder.spec_store.deinit();
    builder.lowered_templates = collections.DenseMap(Ast.FnId, LoweredTemplate).init(allocator);
    defer builder.lowered_templates.deinit();

    const makeReservedJob = struct {
        fn make(
            builder_: *Builder,
            program_: *Ast.Program,
            template_ref_: names.ProcTemplate,
            fn_template_: Ast.FnTemplate,
            ty_: Type.TypeId,
            dispatch_index: u64,
        ) Allocator.Error!PendingSpecJob {
            const fn_id: Ast.FnId = @fromBackingInt(@intCast(@as(u32, @intCast(dispatch_index))));
            const def_id: Ast.DefId = @fromBackingInt(@intCast(@as(u32, @intCast(dispatch_index))));
            const identity = Ast.SpecIdentity{
                .callable = .{ .generated = @fromBackingInt(@intCast(@as(u32, @intCast(dispatch_index)))) },
                .method_scope = .{},
                .evidence_digest = .{},
                .codec_contract_digest = .{},
                .codec_contract = null,
                .request_fn_ty_digest = .{},
                .request_fn_ty = ty_,
            };
            const spec = try program_.addSpec(.{
                .identity = identity,
                .request_fn_ty = ty_,
                .request_fn_ty_digest = identity.request_fn_ty_digest,
                .solved_fn_ty = ty_,
                .solved_fn_ty_digest = identity.request_fn_ty_digest,
                .fn_id = fn_id,
                .status = .reserved,
            });
            try builder_.lowered_templates.put(fn_id, .{
                .def = def_id,
                .spec = spec,
                .evidence = &.{},
            });

            return .{
                .dispatch_index = dispatch_index,
                .spec = spec,
                .reservation = .{
                    .def = def_id,
                    .fn_id = fn_id,
                    .symbol = @fromBackingInt(@intCast(@as(u32, @intCast(dispatch_index)))),
                },
                .fn_template = fn_template_,
                .template_ref = template_ref_,
                .method_scope = .{},
                // The job is marked ready before draining, so its type is not read.
                .source_fn_ty = undefined,
                .source_fn_key = .{},
                .fn_ty = ty_,
                .evidence = &.{},
                .subst = null,
                .signature_relation = .independent_roots,
                .codec_contract = null,
                .widened_result_row = false,
            };
        }
    }.make;

    const first = try makeReservedJob(&builder, &program, template_ref, fn_template, ty, 0);
    try builder.pending_spec_jobs.append(allocator, first);
    builder.next_spec_dispatch_index += 1;
    builder.countBodyDiagnostic("spec_jobs_enqueued");
    const second = try makeReservedJob(&builder, &program, template_ref, fn_template, ty, 1);
    try builder.pending_spec_jobs.append(allocator, second);
    builder.next_spec_dispatch_index += 1;
    builder.countBodyDiagnostic("spec_jobs_enqueued");
    try std.testing.expectEqual(Ast.SpecStatus.reserved, builder.spec_store.recordStatus(first.spec));
    try std.testing.expectEqual(Ast.SpecStatus.reserved, builder.spec_store.recordStatus(second.spec));

    // Immediate representation-sensitive callers claim both reservations while
    // their original FIFO entries remain queued.
    builder.spec_store.markLowering(first.spec);
    try builder.spec_store.markReady(first.spec, first.fn_ty, .{});
    builder.spec_store.markLowering(second.spec);
    try builder.spec_store.markReady(second.spec, second.fn_ty, .{});
    try std.testing.expectEqual(Ast.SpecStatus.ready, builder.spec_store.recordStatus(first.spec));
    try std.testing.expectEqual(Ast.SpecStatus.ready, builder.spec_store.recordStatus(second.spec));

    try builder.drainPendingSpecJobs();

    try std.testing.expectEqual(@as(u64, 2), builder.next_spec_accept_index);
    try std.testing.expectEqual(@as(usize, 0), builder.pending_spec_jobs.len);
    try std.testing.expectEqual(@as(u64, 2), diagnostics.body.spec_jobs_enqueued);
    try std.testing.expectEqual(@as(u64, 2), diagnostics.body.spec_jobs_skipped_ready);
    try std.testing.expectEqual(@as(u64, 0), diagnostics.body.spec_jobs_executed);
    try std.testing.expectEqual(@as(u64, 0), diagnostics.body.spec_job_shards_lowered);
    try std.testing.expectEqual(@as(u64, 0), diagnostics.body.spec_job_shards_committed);
}

