test "draft specialization lookup preserves family evidence and request identity" {
    const allocator = std.testing.allocator;
    var type_store = Type.Store.init(allocator);
    defer type_store.deinit();
    var name_store = names.NameStore.init(allocator);
    defer name_store.deinit();
    const graph = try InstGraph.create(allocator, &type_store, &name_store);
    defer graph.destroy();
    const first_node = try graph.newNode(.{ .primitive = .bool });
    const second_node = try graph.newNode(.{ .primitive = .str });
    inline for (.{ DraftTemplateFamilyAddress, DraftNestedFamilyAddress }) |Family| {
        const Lookup = DraftSpecLookup(Family);
        var lookup = Lookup.init(allocator);
        defer lookup.deinit();
        const family = std.mem.zeroes(Family);
        const evidence = @as([32]u8, @splat(0));
        const prefix = try lookup.internPrefix(family, evidence);
        try std.testing.expectEqual(prefix, try lookup.internPrefix(family, evidence));

        // The same bytes can name a structural type, a permanent graph node,
        // or an open shape. Those request domains must remain disjoint.
        const addresses = [_]Lookup.Address{
            .{ .digest = .{ .prefix = prefix, .kind = .closed, .digest = @splat(0) } },
            .{ .open = .{ .prefix = prefix, .node = first_node } },
            .{ .digest = .{ .prefix = prefix, .kind = .open_shape, .digest = @splat(0) } },
            .{ .open = .{ .prefix = prefix, .node = second_node } },
        };
        for (addresses, 0..) |address, raw_spec| {
            try std.testing.expect(lookup.get(address) == null);
            try lookup.add(address, @intCast(raw_spec));
        }

        // Every family qualifier and evidence byte contributes to identity.
        // Growing the prefix table must also preserve previously issued IDs.
        inline for (@typeInfo(Family).@"struct".field_names) |field_name| {
            const changes = if (@typeInfo(@FieldType(Family, field_name)) == .array) @typeInfo(@FieldType(Family, field_name)).array.len else 1;
            for (0..changes) |byte| {
                var different_family = family;
                if (@typeInfo(@FieldType(Family, field_name)) == .array) {
                    @field(different_family, field_name)[byte] = 1;
                } else if (@FieldType(Family, field_name) == u32) {
                    @field(different_family, field_name) = 1;
                } else if (@FieldType(Family, field_name) == bool) {
                    @field(different_family, field_name) = true;
                } else {
                    @compileError("unsupported specialization family qualifier");
                }
                const other = try lookup.internPrefix(different_family, evidence);
                try std.testing.expect(other != prefix);
                var address = addresses[0];
                address.digest.prefix = other;
                try std.testing.expect(lookup.get(address) == null);
                try lookup.add(address, 0);
            }
        }
        for (0..evidence.len) |byte| {
            var different_evidence = evidence;
            different_evidence[byte] = 1;
            const other = try lookup.internPrefix(family, different_evidence);
            try std.testing.expect(other != prefix);
            var address = addresses[0];
            address.digest.prefix = other;
            try std.testing.expect(lookup.get(address) == null);
            try lookup.add(address, 0);
        }
        try std.testing.expectEqual(prefix, try lookup.internPrefix(family, evidence));
        for (addresses, 0..) |address, raw_spec| {
            var candidates = lookup.get(address).?;
            try std.testing.expectEqual(@as(u32, @intCast(raw_spec)), candidates.next().?);
            try std.testing.expect(candidates.next() == null);
        }

        lookup.deinit();
        lookup = Lookup.init(allocator);
        try std.testing.expect(lookup.isEmpty());
        const fresh_prefix = try lookup.internPrefix(family, evidence);
        var address = addresses[0];
        address.digest.prefix = fresh_prefix;
        try std.testing.expect(lookup.get(address) == null);
    }
}

test "draft specialization candidates retain insertion order across overflow growth and allocation failure" {
    const Scenario = struct {
        fn run(allocator: Allocator) (Allocator.Error || error{TestUnexpectedResult})!void {
            var type_store = Type.Store.init(allocator);
            defer type_store.deinit();
            var name_store = names.NameStore.init(allocator);
            defer name_store.deinit();
            const graph = try InstGraph.create(allocator, &type_store, &name_store);
            defer graph.destroy();
            const request_node = try graph.newNode(.{ .primitive = .bool });
            var other_nodes: [20]NodeId = undefined;
            for (&other_nodes) |*node| node.* = try graph.newNode(.{ .primitive = .str });
            inline for (.{ DraftTemplateFamilyAddress, DraftNestedFamilyAddress }) |Family| {
                const Lookup = DraftSpecLookup(Family);
                var lookup = Lookup.init(allocator);
                defer lookup.deinit();
                const prefix = try lookup.internPrefix(std.mem.zeroes(Family), @splat(0));
                const addresses = [_]Lookup.Address{
                    .{ .open = .{ .prefix = prefix, .node = request_node } },
                    .{ .digest = .{ .prefix = prefix, .kind = .closed, .digest = @splat(0) } },
                    .{ .digest = .{ .prefix = prefix, .kind = .open_shape, .digest = @splat(0) } },
                };
                for (addresses) |address| {
                    // Every u32 is a valid candidate ID, including zero and
                    // the maximum value; neither acts as an empty marker.
                    try lookup.add(address, std.math.maxInt(u32));
                    for (0..20) |i| {
                        const raw_spec: u32 = @intCast(i);
                        try lookup.add(address, raw_spec);
                        try lookup.add(address, raw_spec);
                        try lookup.add(address, std.math.maxInt(u32));
                        // Other buckets grow the indexes and overflow table
                        // between appends to the bucket being checked.
                        const other: Lookup.Address = .{ .open = .{
                            .prefix = prefix,
                            .node = other_nodes[i],
                        } };
                        try lookup.add(other, raw_spec);
                        try lookup.add(other, std.math.maxInt(u32));
                    }
                    try std.testing.expect(lookup.openPairs(prefix).len == 61);
                    var candidates = lookup.get(address).?;
                    try std.testing.expect(candidates.next().? == std.math.maxInt(u32));
                    for (0..20) |i| try std.testing.expect(candidates.next().? == i);
                    try std.testing.expect(candidates.next() == null);
                    for (0..20) |i| {
                        var other = lookup.get(.{ .open = .{
                            .prefix = prefix,
                            .node = other_nodes[i],
                        } }).?;
                        try std.testing.expect(other.next().? == i);
                        try std.testing.expect(other.next().? == std.math.maxInt(u32));
                        try std.testing.expect(other.next() == null);
                    }
                }
            }
        }
    };
    try Scenario.run(std.testing.allocator);
    try std.testing.checkAllAllocationFailures(std.testing.allocator, Scenario.run, .{});
}

test "draft specialization open lookup follows unions within its prefix" {
    const gpa = std.testing.allocator;
    var type_store = Type.Store.init(gpa);
    defer type_store.deinit();
    var name_store = names.NameStore.init(gpa);
    defer name_store.deinit();
    const graph = try InstGraph.create(gpa, &type_store, &name_store);
    defer graph.destroy();
    var lookup = DraftTemplateSpecLookup.init(gpa);
    defer lookup.deinit();
    const family = std.mem.zeroes(DraftTemplateFamilyAddress);
    const prefix = try lookup.internPrefix(family, @splat(0));
    const other_prefix = try lookup.internPrefix(family, @splat(1));
    try std.testing.expectEqual(@as(usize, 0), lookup.openPairs(prefix).len);
    const arg = try graph.newNode(.{ .unresolved = InstVariable.checkedVariable(null, null) });
    const ret = try graph.newNode(.{ .unresolved = InstVariable.checkedVariable(null, null) });
    const registered = try graph.newNode(.{ .unresolved = InstVariable.checkedVariable(null, null) });
    const unrelated = try graph.newNode(.{ .unresolved = InstVariable.checkedVariable(null, null) });
    try lookup.add(.{ .open = .{ .prefix = prefix, .node = registered } }, 7);
    try lookup.add(.{ .open = .{ .prefix = prefix, .node = registered } }, 8);
    try lookup.add(.{ .open = .{ .prefix = prefix, .node = registered } }, 7);
    try lookup.add(.{ .open = .{ .prefix = prefix, .node = unrelated } }, 9);
    try lookup.add(.{ .open = .{ .prefix = other_prefix, .node = arg } }, 10);
    const roots = [_]NodeId{ arg, ret };
    var before = DraftTemplateSpecLookup.OpenIterator{ .pairs = lookup.openPairs(prefix), .graph = graph, .interface_roots = &roots };
    try std.testing.expectEqual(null, before.next());
    // The registered permanent node becomes an alias only after registration.
    // Thousands of unrelated registrations join the same live class, but do
    // not enlarge this prefix's candidate inventory.
    try graph.unify(arg, registered);
    for (0..2000) |i| {
        const node = try graph.newNode(.{ .unresolved = InstVariable.checkedVariable(null, null) });
        try lookup.add(.{ .open = .{ .prefix = other_prefix, .node = node } }, @intCast(i + 11));
        try graph.unify(arg, node);
    }
    try std.testing.expectEqual(@as(usize, 3), lookup.openPairs(prefix).len);
    var after = DraftTemplateSpecLookup.OpenIterator{ .pairs = lookup.openPairs(prefix), .graph = graph, .interface_roots = &roots };
    try std.testing.expectEqual(@as(?u32, 7), after.next());
    try std.testing.expectEqual(@as(?u32, 8), after.next());
    try std.testing.expectEqual(null, after.next());
    // Return-only overlap must also retain candidates for recursive checks.
    try graph.unify(ret, unrelated);
    var returned = DraftTemplateSpecLookup.OpenIterator{ .pairs = lookup.openPairs(prefix), .graph = graph, .interface_roots = &roots };
    try std.testing.expectEqual(@as(?u32, 7), returned.next());
    try std.testing.expectEqual(@as(?u32, 8), returned.next());
    try std.testing.expectEqual(@as(?u32, 9), returned.next());
    try std.testing.expectEqual(null, returned.next());
}

test "open draft recursive provenance joins fresh interface cells only while lowering" {
    const gpa = std.testing.allocator;

    var type_store = Type.Store.init(gpa);
    defer type_store.deinit();
    var name_store = names.NameStore.init(gpa);
    defer name_store.deinit();
    const graph = try InstGraph.create(gpa, &type_store, &name_store);
    defer graph.destroy();
    var draft = BodyDraftStore.init(gpa);
    defer draft.deinit();

    const shared_ret = try graph.newNode(.{ .primitive = .bool });
    const active_arg = try graph.newNode(.{ .unresolved = InstVariable.checkedVariable(null, .empty_tag_union) });
    const recursive_ret = try graph.newNode(.{ .unresolved = InstVariable.checkedVariable(null, .empty_tag_union) });
    const active_fn = try graph.newNode(.{ .func = .{
        .args = try graph.arena().dupe(NodeId, &.{active_arg}),
        .ret = shared_ret,
    } });
    const recursive_fn = try graph.newNode(.{ .func = .{
        .args = try graph.arena().dupe(NodeId, &.{active_arg}),
        .ret = recursive_ret,
    } });
    const shared_frame = RuntimeDemandGuardFrameAddress{
        .module = @as([32]u8, @splat(1)),
        .owner_module = @as([32]u8, @splat(2)),
        .owner_proc_base = 3,
        .owner_template = 4,
        .pattern = 5,
        .kind = .match_branch,
    };
    const active_proof = try appendRuntimeImpossibilityProof(&draft, gpa, .never);
    const recursive_proof = try appendRuntimeImpossibilityProof(&draft, gpa, .always);
    var frames = RuntimeDemandGuardFrameStack{};
    frames = try addRuntimeDemandGuardFrame(&draft, frames, shared_frame, active_proof);
    const recursive_frames = try addRuntimeDemandGuardFrame(&draft, frames, shared_frame, recursive_proof);
    try std.testing.expectEqual(@as(u32, 1), recursive_frames.depth);
    const recursive_head = runtimeDemandGuardFrame(&draft, recursive_frames.head.?);
    try std.testing.expectEqual(active_proof, recursive_head.proof);
    var success_frame = shared_frame;
    success_frame.kind = .pattern_success;
    const success_frames = try addRuntimeDemandGuardFrame(&draft, recursive_frames, success_frame, recursive_proof);
    try std.testing.expectEqual(@as(u32, 2), success_frames.depth);
    const success_head = runtimeDemandGuardFrame(&draft, success_frames.head.?);
    try std.testing.expectEqual(recursive_proof, success_head.proof);
    try std.testing.expectEqual(recursive_frames.head, success_head.parent);
    var nested_frame = shared_frame;
    nested_frame.pattern += 1;
    frames = try addRuntimeDemandGuardFrame(&draft, recursive_frames, nested_frame, recursive_proof);
    try std.testing.expectEqual(@as(u32, 2), frames.depth);

    try std.testing.expect(!(try graph.sameFunctionInterface(active_fn, recursive_fn)));
    try std.testing.expect(!draftOpenCandidateQualifies(.lowering, false, false, false));
    try std.testing.expect(!draftOpenCandidateQualifies(.lowering, false, true, false));
    try std.testing.expect(draftOpenCandidateQualifies(.lowering, false, true, true));
    try graph.unify(active_fn, recursive_fn);
    try std.testing.expect((try graph.sameFunctionInterface(active_fn, recursive_fn)));
    try std.testing.expect(graph.sameClass(shared_ret, recursive_ret));

    const independent_arg = try graph.newNode(.{ .unresolved = InstVariable.checkedVariable(null, .empty_tag_union) });
    const independent_fn = try graph.newNode(.{ .func = .{
        .args = try graph.arena().dupe(NodeId, &.{independent_arg}),
        .ret = shared_ret,
    } });
    try std.testing.expect(!(try graph.sameFunctionInterface(active_fn, independent_fn)));
    try std.testing.expect(!draftOpenCandidateQualifies(.lowered, false, true, true));
    try std.testing.expect(!graph.sameClass(active_arg, independent_arg));

    const active_subst = [_]SubstSlot{.{ .node = active_arg }};
    const same_subst = [_]SubstSlot{.{ .node = active_arg }};
    const different_subst = [_]SubstSlot{.{ .node = independent_arg }};
    const checked_error_subst = [_]SubstSlot{.checked_error};
    try std.testing.expect(substitutionsShareClasses(graph, &active_subst, &same_subst));
    try std.testing.expect(!substitutionsShareClasses(graph, &active_subst, &different_subst));
    try std.testing.expect(!substitutionsShareClasses(graph, &active_subst, &checked_error_subst));
    try std.testing.expect(substitutionsShareClasses(graph, &checked_error_subst, &checked_error_subst));

    // An exact request reuses a completed specialization regardless of the
    // requesting guard context; reuses under a different context are recorded
    // and re-verified against the specialization's demands at seal.
    try std.testing.expect(draftOpenCandidateQualifies(.lowered, true, false, false));
}

