    try std.testing.expect(!try graph.finalizesAsUninhabited(step));
    try std.testing.expect(try graph.finalizesAsUninhabited(one_payload));
}

test "frozen runtime impossibility proofs evaluate node constants alternatives and conjunctions" {
    const gpa = std.testing.allocator;

    var type_store = Type.Store.init(gpa);
    defer type_store.deinit();
    var name_store = names.NameStore.init(gpa);
    defer name_store.deinit();
    const graph = try InstGraph.create(gpa, &type_store, &name_store);
    defer graph.destroy();

    const empty_node = try graph.newNode(.empty_tag_union);
    const inhabited_node = try graph.newNode(.{ .primitive = .bool });
    try graph.freezeRelations();

    var draft = BodyDraftStore.init(gpa);
    defer draft.deinit();

    const empty_proof = try appendRuntimeImpossibilityProof(&draft, gpa, .{ .node = empty_node });
    const inhabited_proof = try appendRuntimeImpossibilityProof(&draft, gpa, .{ .node = inhabited_node });
    const never_proof = try appendRuntimeImpossibilityProof(&draft, gpa, .never);
    const always_proof = try appendRuntimeImpossibilityProof(&draft, gpa, .always);

    try draft.impossibility_proof_ids.appendSlice(gpa, &.{ inhabited_proof, always_proof });
    const any_proof = try appendRuntimeImpossibilityProof(&draft, gpa, .{ .any = .{ .start = 0, .len = 2 } });
    try draft.impossibility_proof_ids.appendSlice(gpa, &.{ empty_proof, always_proof });
    const all_proof = try appendRuntimeImpossibilityProof(&draft, gpa, .{ .all = .{ .start = 2, .len = 2 } });
    try draft.impossibility_proof_ids.appendSlice(gpa, &.{ empty_proof, never_proof });
    const failed_all_proof = try appendRuntimeImpossibilityProof(&draft, gpa, .{ .all = .{ .start = 4, .len = 2 } });

    var evaluator = try FrozenRuntimeImpossibilityProofEvaluator.init(gpa, graph, &draft);
    defer evaluator.deinit(gpa);
    try std.testing.expect(try evaluator.holds(empty_proof));
    try std.testing.expect(!try evaluator.holds(inhabited_proof));
    try std.testing.expect(!try evaluator.holds(never_proof));
    try std.testing.expect(try evaluator.holds(always_proof));
    try std.testing.expect(try evaluator.holds(any_proof));
    try std.testing.expect(try evaluator.holds(all_proof));
    try std.testing.expect(!try evaluator.holds(failed_all_proof));
    try std.testing.expect(!try evaluator.holds(null));
}

test "runtime impossibility proof constructors canonicalize boolean constants" {
    const gpa = std.testing.allocator;
    var draft = BodyDraftStore.init(gpa);
    defer draft.deinit();

    const never_proof = try appendRuntimeImpossibilityProof(&draft, gpa, .never);
    const always_proof = try appendRuntimeImpossibilityProof(&draft, gpa, .always);
    const dynamic_proof = try appendRuntimeImpossibilityProof(&draft, gpa, .pending);

    try std.testing.expectEqual(
        @as(?RuntimeImpossibilityProofId, null),
        try anyRuntimeImpossibilityProof(&draft, gpa, &.{ never_proof, null }),
    );
    try std.testing.expectEqual(
        @as(?RuntimeImpossibilityProofId, dynamic_proof),
        try anyRuntimeImpossibilityProof(&draft, gpa, &.{ never_proof, dynamic_proof }),
    );
    try std.testing.expectEqual(
        @as(?RuntimeImpossibilityProofId, always_proof),
        try anyRuntimeImpossibilityProof(&draft, gpa, &.{ dynamic_proof, always_proof }),
    );
    try std.testing.expectEqual(
        @as(?RuntimeImpossibilityProofId, null),
        try allRuntimeImpossibilityProof(&draft, gpa, &.{ always_proof, never_proof, dynamic_proof }),
    );
    try std.testing.expectEqual(
        @as(?RuntimeImpossibilityProofId, dynamic_proof),
        try allRuntimeImpossibilityProof(&draft, gpa, &.{ always_proof, dynamic_proof }),
    );
    const empty_all = (try allRuntimeImpossibilityProof(&draft, gpa, &.{})).?;
    try std.testing.expect(draft.impossibility_proofs.items[@backingInt(empty_all)] == .always);
}

test "monotype sameType keeps failed alias alternatives out of recursion stack" {
    var program = Ast.Program.init(std.testing.allocator);
    defer program.deinit();
    const graph = try InstGraph.create(std.testing.allocator, &program.types, &program.names);
    defer graph.destroy();

    const module_identity = try program.names.internModuleIdentity(&(@as([32]u8, @splat(0xAB))));
    const type_name = try program.names.internTypeName("Alias");
    const checked_ty: checked.CheckedTypeId = @fromBackingInt(@intCast(1));
    const i64_ty = try program.types.add(.{ .primitive = .i64 });
    const str_ty = try program.types.add(.{ .primitive = .str });
    const alias_i64 = try program.types.add(.{ .named = .{
        .named_type = .{ .module = .{}, .ty = checked_ty },
        .def = .{ .module = module_identity, .type_name = type_name },
        .kind = .alias,
        .args = Type.Span.empty(),
        .backing = .{ .ty = i64_ty, .use = .inspectable },
    } });
    const alias_str = try program.types.add(.{ .named = .{
        .named_type = .{ .module = .{}, .ty = checked_ty },
        .def = .{ .module = module_identity, .type_name = type_name },
        .kind = .alias,
        .args = Type.Span.empty(),
        .backing = .{ .ty = str_ty, .use = .inspectable },
    } });

    var builder: Builder = undefined;
    builder.program = &program;
    builder.active_body_draft = null;
    var ctx: BodyContext = undefined;
    ctx.spare_inst_frames = .empty;
    defer ctx.deinitSpareInstFrames();
    ctx.allocator = std.testing.allocator;
    ctx.builder = &builder;
    ctx.graph = graph;

    try std.testing.expect(ctx.sameType(alias_i64, i64_ty));
    try std.testing.expect(ctx.sameType(str_ty, alias_str));
    try std.testing.expect(!ctx.sameType(alias_i64, alias_str));
    try std.testing.expect(!ctx.sameType(alias_str, alias_i64));
}

test "body context inspects graph-owned types despite program TypeId collisions" {
    const gpa = std.testing.allocator;

    var program = Ast.Program.init(gpa);
    defer program.deinit();
    var graph_types = Type.Store.init(gpa);
    defer graph_types.deinit();
    const graph = try InstGraph.create(gpa, &graph_types, &program.names);
    defer graph.destroy();

    const program_ty = try program.types.add(.{ .primitive = .bool });
    const graph_ty = try graph_types.add(.{ .primitive = .u64 });
    try std.testing.expectEqual(@backingInt(program_ty), @backingInt(graph_ty));

    var draft = BodyDraftStore.init(gpa);
    defer draft.deinit();
    var builder: Builder = undefined;
    builder.program = &program;
    builder.active_body_draft = null;
    builder.bool_ty = program_ty;
    builder.timing = null;
    var ctx: BodyContext = undefined;
    ctx.spare_inst_frames = .empty;
    defer ctx.deinitSpareInstFrames();
    ctx.allocator = gpa;
    ctx.builder = &builder;
    ctx.graph = graph;
    ctx.draft = &draft;

    try std.testing.expect(ctx.typeStore() == &graph_types);
    try std.testing.expectEqual(Type.Content{ .primitive = .u64 }, ctx.shapeContent(graph_ty));
    const imported_bool = try ctx.primitiveType(.bool);
    try std.testing.expect(imported_bool != graph_ty);
    try std.testing.expectEqual(Type.Content{ .primitive = .bool }, ctx.shapeContent(imported_bool));

    const impossible = try graph_types.add(.{
        .tag_union = try graph_types.addTagVariants(&program.names, &.{}),
    });
    const shared_payload = try graph_types.addSpan(&.{impossible});
    const first_name = try program.names.internTagLabel("First");
    const second_name = try program.names.internTagLabel("Second");
    const repeated_impossible_payload = try graph_types.add(.{
        .tag_union = try graph_types.addTagVariants(&program.names, &.{
            .{ .name = first_name, .checked_name = first_name, .payloads = shared_payload },
            .{ .name = second_name, .checked_name = second_name, .payloads = shared_payload },
        }),
    });
    try std.testing.expect(try ctx.typeIsProvenUninhabited(repeated_impossible_payload));
}

test "frozen codec format index resolves equivalent TypeIds only for agreeing role targets" {
    const gpa = std.testing.allocator;

    var type_store = Type.Store.init(gpa);
    defer type_store.deinit();
    var name_store = names.NameStore.init(gpa);
    defer name_store.deinit();

    const field_name = try name_store.internRecordFieldLabel("value");
    const first_str = try type_store.add(.{ .primitive = .str });
    const first_shape = try type_store.add(.{ .record = try type_store.addRecordFields(&name_store, &.{
        .{ .name = field_name, .ty = first_str, .default = null },
    }) });
    const second_str = try type_store.add(.{ .primitive = .str });
    const second_shape = try type_store.add(.{ .record = try type_store.addRecordFields(&name_store, &.{
        .{ .name = field_name, .ty = second_str, .default = null },
    }) });
    try std.testing.expect(first_shape != second_shape);
    try std.testing.expect(try type_store.typeEql(&name_store, first_shape, second_shape));

    var view_data: ModuleViewData = undefined;
    const view = &view_data;
    view.key = .{};
    // These opaque ids are deliberate synthetic identities: this unit only
    // compares call targets for equality and never dereferences their source
    // tables. Keep the identities explicit instead of manufacturing dummy
    // table entries unrelated to the format-index behavior under test.
    const target: static_dispatch.MethodTarget = .{
        .module_idx = 0,
        .def_idx = @fromBackingInt(@intCast(1)),
        .kind = .{ .procedure = .{
            .proc = .{ .proc_base = @fromBackingInt(@intCast(2)) },
            .template = .{ .proc_base = @fromBackingInt(@intCast(2)), .template = @fromBackingInt(@intCast(3)) },
        } },
        .callable_ty = @fromBackingInt(@intCast(4)),
    };
    const lookup = MethodLookup{ .view = view, .target = target };
    const callee = DraftFnSlot{ .local = .{ .draft = @fromBackingInt(@intCast(5)) } };
    const calls = try gpa.alloc(FrozenPreparedCodecCall, 2);
    calls[0] = .{
        .kind = .parser,
        .purpose = .format,
        .method_name = "parse_record_field",
        .method_role = 0,
        .subject_bearing = true,
        .contract_view = @as([32]u8, @splat(0)),
        .contract_derivation = @fromBackingInt(@intCast(6)),
        .shape_ty = first_shape,
        .lookup = lookup,
        .callable_ty = first_str,
        .callee = callee,
    };
    calls[1] = calls[0];
    calls[1].method_role = 1;
    calls[1].shape_ty = second_shape;
    calls[1].callable_ty = second_str;

    var frozen = try FrozenPreparedCodecCalls.init(gpa, &type_store, &name_store, calls);
    defer frozen.deinit(gpa);
    const selected = (try frozen.formatCall(
        &type_store,
        &name_store,
        .parser,
        "parse_record_field",
        second_shape,
    )).?;
    try std.testing.expectEqual(@as(u32, 0), selected.method_role);
}

test "graph constructor representation follows aliases and preserves nominal layers" {
    const gpa = std.testing.allocator;

    var type_store = Type.Store.init(gpa);
    defer type_store.deinit();
    var name_store = names.NameStore.init(gpa);
    defer name_store.deinit();
    const graph = try InstGraph.create(gpa, &type_store, &name_store);
    defer graph.destroy();

    const module_identity = try name_store.internModuleIdentity(&(@as([32]u8, @splat(0xAC))));
    const alias_name = try name_store.internTypeName("Alias");
    const nominal_name = try name_store.internTypeName("Nominal");
    const outer_alias_name = try name_store.internTypeName("OuterAlias");
    const structural = try graph.newNode(.empty_tag_union);
    const alias = try graph.newNode(try graph.namedContent(.{
        .named_type = .{ .module = .{}, .ty = @fromBackingInt(@intCast(1)) },
        .def = .{ .module = module_identity, .type_name = alias_name },
        .kind = .alias,
        .builtin_owner = null,
        .args = try graph.arena().alloc(NodeId, 0),
        .backing = .{ .node = structural, .use = .inspectable },
    }));
    const nominal = try graph.newNode(try graph.namedContent(.{
        .named_type = .{ .module = .{}, .ty = @fromBackingInt(@intCast(2)) },
        .def = .{ .module = module_identity, .type_name = nominal_name },
        .kind = .nominal,
        .builtin_owner = null,
        .args = try graph.arena().alloc(NodeId, 0),
        .backing = .{ .node = alias, .use = .inspectable },
    }));
    const outer_alias = try graph.newNode(try graph.namedContent(.{
        .named_type = .{ .module = .{}, .ty = @fromBackingInt(@intCast(3)) },
        .def = .{ .module = module_identity, .type_name = outer_alias_name },
        .kind = .alias,
        .builtin_owner = null,
        .args = try graph.arena().alloc(NodeId, 0),
        .backing = .{ .node = nominal, .use = .inspectable },
    }));

    var ctx: BodyContext = undefined;
    ctx.spare_inst_frames = .empty;
    defer ctx.deinitSpareInstFrames();
    ctx.graph = graph;
    try std.testing.expectEqual(structural, (try ctx.constructorRepresentationNode(structural)));
    try std.testing.expectEqual(structural, (try ctx.constructorRepresentationNode(alias)));
    try std.testing.expectEqual(nominal, (try ctx.constructorRepresentationNode(nominal)));
    try std.testing.expectEqual(nominal, (try ctx.constructorRepresentationNode(outer_alias)));
}

test "issue 11288: root substitutions share lexical cells and isolate separate instantiations" {
    const gpa = std.testing.allocator;
    var name_store = names.NameStore.init(gpa);
    defer name_store.deinit();
    var type_store = Type.Store.init(gpa);
    defer type_store.deinit();
    const graph = try InstGraph.create(gpa, &type_store, &name_store);
    defer graph.destroy();
    var checked_types = checked.CheckedTypeStore{};
    defer checked_types.deinit(gpa);
    const outer_ty = try checked_types.reserveSyntheticTypeRoot(gpa, .{}, true);
    const inner_ty = try checked_types.reserveSyntheticTypeRoot(gpa, .{}, true);
    try checked_types.fillSyntheticTypeRoot(gpa, outer_ty, .{ .flex = .{} });
    try checked_types.fillSyntheticTypeRoot(gpa, inner_ty, .{ .flex = .{} });
    const fn_ty = try checked_types.appendSyntheticFunctionRoot(gpa, .pure, &.{outer_ty}, outer_ty);
    var scheme_vars = [_]checked.CheckedTypeId{outer_ty};
    const templates = checked.CheckedProcedureTemplateTable{ .scheme_vars_pool = &scheme_vars };
    var template: checked.CheckedProcedureTemplate = undefined;
    template.checked_fn_root = fn_ty;
    template.scheme_vars = .{ .start = 0, .len = 1 };
    template.evidence_params = .{};

    // Only type instantiation and lexical binding are exercised here.
    var builder: Builder = undefined;
    builder.next_instantiation_scope = 0;
    builder.timing = null;
    builder.diagnostics = null;
    builder.active_spec_job_diagnostics = null;
    var ctx: BodyContext = undefined;
    ctx.spare_inst_frames = .empty;
    defer ctx.deinitSpareInstFrames();
    ctx.allocator = gpa;
    ctx.builder = &builder;
    ctx.graph = graph;
    ctx.owner_template = std.mem.zeroes(names.ProcTemplate);
    var ctx_view: ModuleViewData = undefined;
    ctx.view = &ctx_view;
    ctx_view.key = .{ .bytes = @splat(0) };
    ctx_view.types = checked_types.view();
    ctx_view.templates = &templates;
    ctx.resolves_enclosing_variables = false;
    ctx.relation_variables = null;
    ctx.constructing_scheme_vars = &.{};
    ctx.instantiation = TypeInstantiationContext.init(gpa, builder.allocateInstantiationScope(), ctx.view.key.bytes);
    // An evidence chain without frames: no scope is read.
    ctx.evidence = .{ .scope = undefined };
    defer ctx.instantiation.deinit();

    const root = try ctx.rootEvidenceAtOwnScheme(template, &.{});
    const outer_node = root.subst[0].node;
    const root_node = try ctx.instNode(fn_ty);
    const str_node = try graph.newNode(.{ .primitive = .str });
    const request = try graph.newNode(.{ .func = .{ .args = try graph.arena().dupe(NodeId, &.{str_node}), .ret = str_node } });
    try relateConstructionFunctionRequestInterface(graph, root_node, request);
    try std.testing.expect(graph.sameClass(outer_node, str_node));

    var child = ctx;
    child.instantiation = TypeInstantiationContext.init(gpa, builder.allocateInstantiationScope(), ctx.view.key.bytes);
    defer child.instantiation.deinit();
    const inner_node = try graph.newNode(.{ .primitive = .i64 });
    child.evidence = .{
        .scope = root.scope,
        .schema = .{ .view = ctx.view, .root = null, .scheme_vars = &.{inner_ty}, .params = &.{}, .params_start = 0 },
        .subst = &.{.{ .node = inner_node }},
        .parent = &root,
    };
    child.resolves_enclosing_variables = true;
    try std.testing.expect(graph.sameClass(try child.instNode(outer_ty), str_node));
    try std.testing.expect(graph.sameClass(try child.instNode(inner_ty), inner_node));

    // A sibling root of the same checked scheme can have a different type.
    // Even within one graph its checked identities must instantiate afresh.
    var sibling = ctx;
    sibling.instantiation = TypeInstantiationContext.init(gpa, builder.allocateInstantiationScope(), ctx.view.key.bytes);
    defer sibling.instantiation.deinit();
    const sibling_root = try sibling.rootEvidenceAtOwnScheme(template, &.{});
    const sibling_node = try sibling.instNode(fn_ty);
    const sibling_request = try graph.newNode(.{ .func = .{ .args = try graph.arena().dupe(NodeId, &.{inner_node}), .ret = inner_node } });
    try relateConstructionFunctionRequestInterface(graph, sibling_node, sibling_request);
    try std.testing.expect(graph.sameClass(sibling_root.subst[0].node, inner_node));
    try std.testing.expect(!graph.sameClass(outer_node, sibling_root.subst[0].node));
    try std.testing.expect(graph.sameClass(try child.instNode(outer_ty), str_node));
}

test "issue 11265: forwarded evidence compares methods in their owning name stores" {
    const gpa = std.testing.allocator;
    var frame_names = names.NameStore.init(gpa);
    defer frame_names.deinit();
    var caller_names = names.NameStore.init(gpa);
    defer caller_names.deinit();
    const frame_encode = try frame_names.internMethodName(Ident.ENCODER_FOR_METHOD_NAME);
    const frame_decode = try frame_names.internMethodName("decode");
    const caller_decode = try caller_names.internMethodName("decode");
    const caller_encode = try caller_names.internMethodName(Ident.ENCODER_FOR_METHOD_NAME);
    const caller_hash = try caller_names.internMethodName(Ident.TO_HASH_METHOD_NAME);
    try std.testing.expectEqual(frame_encode, caller_decode);
    try std.testing.expect(frame_decode != caller_decode);

    var type_store = Type.Store.init(gpa);
    defer type_store.deinit();
    const graph = try InstGraph.create(gpa, &type_store, &frame_names);
    defer graph.destroy();
    const receiver = try graph.newNode(.{ .primitive = .str });
    const other_receiver = try graph.newNode(.{ .primitive = .i64 });
    const unrelated_receiver = try graph.newNode(.{ .primitive = .dec });
    const alias = try graph.newNode(.{ .primitive = .str });
    try graph.unify(receiver, alias);

    var checked_types = checked.CheckedTypeStore{};
    defer checked_types.deinit(gpa);
    const receiver_ty = try checked_types.reserveSyntheticTypeRoot(gpa, .{}, true);
    const other_receiver_ty = try checked_types.reserveSyntheticTypeRoot(gpa, .{}, true);
    try checked_types.fillSyntheticTypeRoot(gpa, receiver_ty, .{ .flex = .{} });
    try checked_types.fillSyntheticTypeRoot(gpa, other_receiver_ty, .{ .flex = .{} });
    const result_ty = try checked_types.appendSyntheticPayloadRoot(gpa, &frame_names, .empty_record);
    const encode_ty = try checked_types.appendSyntheticFunctionRoot(gpa, .pure, &.{receiver_ty}, result_ty);
    const other_decode_ty = try checked_types.appendSyntheticFunctionRoot(gpa, .pure, &.{other_receiver_ty}, other_receiver_ty);
    const decode_ty = try checked_types.appendSyntheticFunctionRoot(gpa, .pure, &.{receiver_ty}, receiver_ty);

    var frame_view_data: ModuleViewData = undefined;
    const frame_view = &frame_view_data;
    frame_view.names = &frame_names;
    frame_view.types = checked_types.view();
    const params = [_]static_dispatch.EvidenceParamRecord{
        .{ .method = frame_encode, .dispatcher_ty = receiver_ty, .callable_ty = encode_ty, .slot = 0, .runtime_dictionary = true },
        .{ .method = frame_decode, .dispatcher_ty = other_receiver_ty, .callable_ty = other_decode_ty, .slot = 1, .runtime_dictionary = true },
        .{ .method = frame_decode, .dispatcher_ty = receiver_ty, .callable_ty = decode_ty, .slot = 0, .runtime_dictionary = true },
    };
    const frame: EvidenceChain = .{
        .scope = undefined,
        .schema = .{
            .view = frame_view,
            .root = null,
            .scheme_vars = &.{ receiver_ty, other_receiver_ty },
            .params = &params,
            .params_start = 0,
        },
        .subst = &.{ .{ .node = receiver }, .{ .node = other_receiver } },
        .vector = &.{ .{ .structural = .{ .derivation = .encoder } }, .checked_error, .{ .structural = .{ .derivation = .parser } } },
    };
    var ctx: BodyContext = undefined;
    ctx.spare_inst_frames = .empty;
    defer ctx.deinitSpareInstFrames();
    ctx.graph = graph;
    ctx.evidence = frame;

    // Different methods with equal IDs must stay distinct, and the same
    // method with different IDs must still find its exact receiver's evidence.
    try std.testing.expectEqual(.parser, ctx.forwardedRequirement(alias, &caller_names, caller_decode).?.structural.derivation);
    try std.testing.expectEqual(.encoder, ctx.forwardedRequirement(receiver, &caller_names, caller_encode).?.structural.derivation);
    try std.testing.expectEqual(.parser, ctx.forwardedRequirement(receiver, &frame_names, frame_decode).?.structural.derivation);
    try std.testing.expect(ctx.forwardedRequirement(receiver, &caller_names, caller_hash) == null);
    try std.testing.expect(ctx.forwardedRequirement(unrelated_receiver, &caller_names, caller_decode) == null);

    // A name absent from an inner frame must continue to the lexical parent,
    // even if that inner store assigns its ID to another method.
    var inner_names = names.NameStore.init(gpa);
    defer inner_names.deinit();
    const inner_method = try inner_names.internMethodName(Ident.IS_EQ_METHOD_NAME);
    try std.testing.expectEqual(caller_decode, inner_method);
    var inner_view_data: ModuleViewData = undefined;
    const inner_view = &inner_view_data;
    inner_view.names = &inner_names;
    inner_view.types = checked_types.view();
    ctx.evidence = .{
        .scope = undefined,
        .schema = .{
            .view = inner_view,
            .root = null,
            .scheme_vars = &.{receiver_ty},
            .params = &.{.{ .method = inner_method, .dispatcher_ty = receiver_ty, .callable_ty = decode_ty, .slot = 0, .runtime_dictionary = true }},
            .params_start = 0,
        },
        .subst = &.{.{ .node = receiver }},
        .vector = &.{.{ .structural = .{ .derivation = .equality } }},
        .parent = &frame,
    };
    try std.testing.expectEqual(.parser, ctx.forwardedRequirement(receiver, &caller_names, caller_decode).?.structural.derivation);
}

test "specialization evidence equality includes exact target instantiation" {
    var roots: [11]checked.CheckedTypeRoot = undefined;
    for (&roots, 0..) |*root, index| {
        root.* = .{ .id = @fromBackingInt(@intCast(@as(u32, @intCast(index)))), .key = .{} };
        root.key.bytes[0] = @intCast(index);
    }
    // A fresh checked identity may have a distinct raw id while retaining the
    // same canonical type topology.
    roots[10].key = roots[8].key;

    var target_view_data: ModuleViewData = undefined;
    const target_view = &target_view_data;
    target_view.key = .{};
    target_view.key.bytes[0] = 1;
    target_view.types = .{ .roots = &roots };
    var other_target_view_data: ModuleViewData = undefined;
    const other_target_view = &other_target_view_data;
    other_target_view.key = .{};
    other_target_view.key.bytes[0] = 2;
    other_target_view.types = .{ .roots = &roots };
    var instantiation_view_data: ModuleViewData = undefined;
    const instantiation_view = &instantiation_view_data;
    instantiation_view.key = .{};
    instantiation_view.key.bytes[0] = 3;
    instantiation_view.types = .{ .roots = &roots };
    var other_instantiation_view_data: ModuleViewData = undefined;
    const other_instantiation_view = &other_instantiation_view_data;
    other_instantiation_view.key = .{};
    other_instantiation_view.key.bytes[0] = 4;
    other_instantiation_view.types = .{ .roots = &roots };

    const method: static_dispatch.MethodTarget = .{
        .module_idx = 5,
        .def_idx = @fromBackingInt(@intCast(6)),
        .kind = .{ .procedure = .{
            .proc = .{ .proc_base = @fromBackingInt(@intCast(7)) },
            .template = .{ .proc_base = @fromBackingInt(@intCast(7)), .template = @fromBackingInt(@intCast(8)) },
        } },
        .callable_ty = @fromBackingInt(@intCast(7)),
    };
    const exact: SpecEvidenceTarget = .{
        .view = target_view,
        .target = method,
        .instantiation = .{ .view = instantiation_view, .callable_ty = @fromBackingInt(@intCast(8)) },
        .local_proc_context = null,
        .nested = .{ .resolved = &.{.{ .structural = .{ .derivation = .equality } }} },
    };
    try std.testing.expect(try specEvidenceEql(std.testing.allocator, .{ .target = &exact }, .{ .target = &exact }));

    var different_target_view = exact;
    different_target_view.view = other_target_view;
    try std.testing.expect(!try specEvidenceEql(std.testing.allocator, .{ .target = &exact }, .{ .target = &different_target_view }));

    var different_instantiation_view = exact;
    different_instantiation_view.instantiation.?.view = other_instantiation_view;
    try std.testing.expect(!try specEvidenceEql(std.testing.allocator, .{ .target = &exact }, .{ .target = &different_instantiation_view }));

    var different_callable = exact;
    different_callable.instantiation.?.callable_ty = @fromBackingInt(@intCast(9));
    try std.testing.expect(!try specEvidenceEql(std.testing.allocator, .{ .target = &exact }, .{ .target = &different_callable }));

    var equivalent_fresh_callable = exact;
    equivalent_fresh_callable.instantiation.?.callable_ty = @fromBackingInt(@intCast(10));
    try std.testing.expect(try specEvidenceEql(std.testing.allocator, .{ .target = &exact }, .{ .target = &equivalent_fresh_callable }));

    var unresolved_nested = exact;
    unresolved_nested.nested = .synthesize;
    try std.testing.expect(!try specEvidenceEql(std.testing.allocator, .{ .target = &exact }, .{ .target = &unresolved_nested }));

    var monomorphic = exact;
    monomorphic.instantiation = null;
    var monomorphic_other_view = monomorphic;
    monomorphic_other_view.view = other_target_view;
    monomorphic_other_view.target = method;
    try std.testing.expect(!try specEvidenceEql(std.testing.allocator, .{ .target = &monomorphic }, .{ .target = &monomorphic_other_view }));

    var monomorphic_other_caller = monomorphic;
    monomorphic_other_caller.instantiation = null;
    try std.testing.expect(try specEvidenceEql(std.testing.allocator, .{ .target = &monomorphic }, .{ .target = &monomorphic_other_caller }));

    const local_method: static_dispatch.MethodTarget = .{
        .module_idx = 5,
        .def_idx = @fromBackingInt(@intCast(6)),
        .kind = .{ .local_proc = .{
            .binder = @fromBackingInt(@intCast(7)),
            .expr = @fromBackingInt(@intCast(8)),
            .context_anchor = @fromBackingInt(@intCast(9)),
        } },
        .callable_ty = @fromBackingInt(@intCast(10)),
    };
    var first_local = monomorphic;
    first_local.target = local_method;
    const first_context: DraftLocalProcContextId = @fromBackingInt(@intCast(1));
    const second_context: DraftLocalProcContextId = @fromBackingInt(@intCast(2));
    first_local.local_proc_context = first_context;
    var second_local = first_local;
    second_local.local_proc_context = second_context;
    try std.testing.expect(!try specEvidenceEql(std.testing.allocator, .{ .target = &first_local }, .{ .target = &second_local }));
    try std.testing.expect(try specEvidenceRequiresLocalContext(std.testing.allocator, &.{.{ .target = &first_local }}));
}

/// Structural `is_eq` specifics for the generic derivation driver
/// (`BodyContext.lowerDerivation`). Equality threads two operands, builds a
/// component access on each, and conjoins the per-component bools with AND so
/// the first inequality short-circuits to `false`.
const EqDeriver = struct {
    const structural_kind: static_dispatch.StructuralKind = .equality;

    const Operand = struct {
        lhs: DraftExprId,
        rhs: DraftExprId,
    };

    /// Right-to-left so the AND fold nests the later components inside the
    /// earlier `if` bodies, matching source field/element order.
    const forward = false;

    fn expansionStack(self: *BodyContext) *collections.DenseMap(Type.TypeId, void) {
        return &self.equality_expansion_stack;
    }

    fn defCache(self: *BodyContext) *std.AutoHashMap(GeneratedHelperDefAddress, DraftGeneratedHelperDefEntry) {
        return &self.equality_defs;
    }

    fn defAddress(value_ty: Type.TypeId, result_ty: Type.TypeId) GeneratedHelperDefAddress {
        return .{ .value_ty = @backingInt(value_ty), .result_ty = @backingInt(result_ty) };
    }

    fn fnType(self: *BodyContext, value_ty: Type.TypeId, result_ty: Type.TypeId) Allocator.Error!DraftTypeCell {
        return try self.graphFunctionTypeCellFromMono(&.{ value_ty, value_ty }, result_ty);
    }

    fn callArgs(operand: Operand) [2]DraftExprId {
        return .{ operand.lhs, operand.rhs };
    }

    fn helperSecondArgType(value_ty: Type.TypeId, _: Type.TypeId) Type.TypeId {
        return value_ty;
    }

    fn helperOperand(self_expr: DraftExprId, aux_expr: DraftExprId) Operand {
        return .{ .lhs = self_expr, .rhs = aux_expr };
    }

    fn leaf(self: *BodyContext, operand: Operand, ctx: BodyContext.DerivationCtx) Allocator.Error!DraftExprId {
        return try self.addExpr(.{ .ty = ctx.result_ty, .data = .{ .structural_eq = .{
            .lhs = operand.lhs,
            .rhs = operand.rhs,
            .negated = false,
        } } });
    }

    fn combineSeed(self: *BodyContext, _: Operand, ctx: BodyContext.DerivationCtx) Allocator.Error!DraftExprId {
        return try self.boolLiteral(true, ctx.result_ty);
    }

    fn combine(self: *BodyContext, state: DraftExprId, component: DraftExprId, ctx: BodyContext.DerivationCtx) Allocator.Error!DraftExprId {
        return try self.ifExpr(component, state, try self.boolLiteral(false, ctx.result_ty), ctx.result_ty);
    }

    fn componentForField(self: *BodyContext, operand: Operand, _: DraftExprId, field: Type.Field) Allocator.Error!Operand {
        const lhs_field = try self.addFieldAccessExpr(operand.lhs, field.name, field.ty);
        const rhs_field = try self.addFieldAccessExpr(operand.rhs, field.name, field.ty);
        return .{ .lhs = lhs_field, .rhs = rhs_field };
    }

    fn componentForTuple(self: *BodyContext, operand: Operand, _: DraftExprId, item_ty: Type.TypeId, index: usize) Allocator.Error!Operand {
        const lhs_item = try self.addExpr(.{ .ty = item_ty, .data = .{ .tuple_access = .{
            .tuple = operand.lhs,
            .elem_index = @intCast(index),
        } } });
        const rhs_item = try self.addExpr(.{ .ty = item_ty, .data = .{ .tuple_access = .{
            .tuple = operand.rhs,
            .elem_index = @intCast(index),
        } } });
        return .{ .lhs = lhs_item, .rhs = rhs_item };
    }

    const missing_component_method_msg = "checked method registry is missing List equality target";

    fn methodArgTypes(ty: Type.TypeId, _: Type.TypeId) [2]Type.TypeId {
        return .{ ty, ty };
    }

    const NamedLocals = struct { lhs: DraftLocalId, rhs: DraftLocalId };

    const NamedEntry = struct { locals: NamedLocals, operand: Operand };

    /// Unwrap both nominal operands into backing locals; the backing
    /// comparison reads those locals.
    fn namedEnter(self: *BodyContext, backing_ty: Type.TypeId, _: Operand) Allocator.Error!NamedEntry {
        const lhs_inner = try self.addLocal(self.builder.symbols.fresh(), backing_ty);
        const rhs_inner = try self.addLocal(self.builder.symbols.fresh(), backing_ty);
        return .{
            .locals = .{ .lhs = lhs_inner, .rhs = rhs_inner },
            .operand = .{
                .lhs = try self.localExpr(lhs_inner, backing_ty),
                .rhs = try self.localExpr(rhs_inner, backing_ty),
            },
        };
    }

    fn namedExit(self: *BodyContext, named_ty: Type.TypeId, backing_ty: Type.TypeId, locals: NamedLocals, operand: Operand, compare: DraftExprId, ctx: BodyContext.DerivationCtx) Allocator.Error!DraftExprId {
        const lhs_pat = try self.addPat(.{ .ty = named_ty, .data = .{ .nominal = try self.bindPat(locals.lhs, backing_ty) } });
        const rhs_pat = try self.addPat(.{ .ty = named_ty, .data = .{ .nominal = try self.bindPat(locals.rhs, backing_ty) } });

        const bind_rhs = try self.addExpr(.{ .ty = ctx.result_ty, .data = .{ .let_ = .{
            .bind = rhs_pat,
            .value = operand.rhs,
            .rest = compare,
        } } });
        return try self.addExpr(.{ .ty = ctx.result_ty, .data = .{ .let_ = .{
            .bind = lhs_pat,
            .value = operand.lhs,
            .rest = bind_rhs,
        } } });
    }

    // Structural equality on a tag union decomposes into nested matches so that each
    // payload is compared. This dispatches owned payload types (e.g. List) to their
    // `is_eq` methods, matching how record and tuple fields are handled. Leaving tag
    // unions as a `structural_eq` node would defer the payload comparison to the LIR
    // structural-equality lowering, which can only compare inline-comparable types and
    // panics on owned types such as lists.

    /// Both operands bind to locals so each is evaluated exactly once and the
    /// right-hand side can be re-scrutinised inside every left-hand-side branch.
    const TagUnionLocals = struct { lhs: DraftLocalId, rhs: DraftLocalId };

    fn tagUnionEnter(self: *BodyContext, ty: Type.TypeId) Allocator.Error!TagUnionLocals {
        const lhs_local = try self.addLocal(self.builder.symbols.fresh(), ty);
        const rhs_local = try self.addLocal(self.builder.symbols.fresh(), ty);
        return .{ .lhs = lhs_local, .rhs = rhs_local };
    }

    const TagBranchPayloads = struct {
        lhs_pats: []DraftPatId = &.{},
        rhs_pats: []DraftPatId = &.{},
        lhs_exprs: []DraftExprId = &.{},
        rhs_exprs: []DraftExprId = &.{},

        fn deinit(payloads: *TagBranchPayloads, allocator: Allocator) void {
            allocator.free(payloads.lhs_pats);
            allocator.free(payloads.rhs_pats);
            allocator.free(payloads.lhs_exprs);
            allocator.free(payloads.rhs_exprs);
            payloads.* = .{};
        }
    };

    /// Bind one variant's payloads on both sides. The branch's conjunction of
    /// pairwise payload comparisons starts at true: a variant with no payloads
    /// is equal once both discriminants match.
    fn tagBranchEnter(self: *BodyContext, _: Type.TypeId, payloads: []const Type.TypeId, _: u64, _: Operand, branch: *TagBranchPayloads, ctx: BodyContext.DerivationCtx) Allocator.Error!DraftExprId {
        branch.lhs_pats = try self.allocator.alloc(DraftPatId, payloads.len);
        branch.rhs_pats = try self.allocator.alloc(DraftPatId, payloads.len);
        branch.lhs_exprs = try self.allocator.alloc(DraftExprId, payloads.len);
        branch.rhs_exprs = try self.allocator.alloc(DraftExprId, payloads.len);
        for (payloads, 0..) |payload_ty, i| {
            const lhs_payload_local = try self.addLocal(self.builder.symbols.fresh(), payload_ty);
            const rhs_payload_local = try self.addLocal(self.builder.symbols.fresh(), payload_ty);
            branch.lhs_pats[i] = try self.bindPat(lhs_payload_local, payload_ty);
            branch.rhs_pats[i] = try self.bindPat(rhs_payload_local, payload_ty);
            branch.lhs_exprs[i] = try self.localExpr(lhs_payload_local, payload_ty);
            branch.rhs_exprs[i] = try self.localExpr(rhs_payload_local, payload_ty);
        }
        return try self.boolLiteral(true, ctx.result_ty);
    }

    fn tagPayloadOperand(branch: TagBranchPayloads, index: usize, _: DraftExprId) Operand {
        return .{ .lhs = branch.lhs_exprs[index], .rhs = branch.rhs_exprs[index] };
    }

    /// One branch of the outer match: it matches the left operand against
    /// `tag`, binding its payloads, then matches the right operand against the
    /// same tag. When both sides carry `tag`, the payloads compare pairwise
    /// (`body`); any other right-hand variant yields `false`.
    fn tagBranchExit(self: *BodyContext, ty: Type.TypeId, locals: TagUnionLocals, tag: Type.Tag, branch: TagBranchPayloads, body: DraftExprId, single_variant: bool, ctx: BodyContext.DerivationCtx) Allocator.Error!DraftBranch {
        const rhs_tag_pat = try self.addPat(.{ .ty = ty, .data = .{ .tag = .{
            .name = tag.name,
            .payloads = try self.addPatSpan(branch.rhs_pats),
        } } });
        const rhs_scrutinee = try self.localExpr(locals.rhs, ty);
        const inner_match = if (single_variant) blk: {
            const inner_branches = [_]DraftBranch{.{ .pat = rhs_tag_pat, .body = body }};
            break :blk try self.addExpr(.{ .ty = ctx.result_ty, .data = .{ .match_ = .{
                .scrutinee = rhs_scrutinee,
                .branches = try self.addBranchSpan(&inner_branches),
            } } });
        } else blk: {
            const wildcard = try self.addPat(.{ .ty = ty, .data = .wildcard });
            const inner_branches = [_]DraftBranch{
                .{ .pat = rhs_tag_pat, .body = body },
                .{ .pat = wildcard, .body = try self.boolLiteral(false, ctx.result_ty) },
            };
            break :blk try self.addExpr(.{ .ty = ctx.result_ty, .data = .{ .match_ = .{
                .scrutinee = rhs_scrutinee,
                .branches = try self.addBranchSpan(&inner_branches),
            } } });
        };

        const lhs_tag_pat = try self.addPat(.{ .ty = ty, .data = .{ .tag = .{
            .name = tag.name,
            .payloads = try self.addPatSpan(branch.lhs_pats),
        } } });
        return .{ .pat = lhs_tag_pat, .body = inner_match };
    }

    fn tagUnionExit(self: *BodyContext, ty: Type.TypeId, locals: TagUnionLocals, operand: Operand, branches: []const DraftBranch, ctx: BodyContext.DerivationCtx) Allocator.Error!DraftExprId {
        const match_expr = try self.addExpr(.{ .ty = ctx.result_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(locals.lhs, ty),
            .branches = try self.addBranchSpan(branches),
        } } });

        const bind_rhs = try self.addExpr(.{ .ty = ctx.result_ty, .data = .{ .let_ = .{
            .bind = try self.bindPat(locals.rhs, ty),
            .value = operand.rhs,
            .rest = match_expr,
        } } });
        return try self.addExpr(.{ .ty = ctx.result_ty, .data = .{ .let_ = .{
            .bind = try self.bindPat(locals.lhs, ty),
            .value = operand.lhs,
            .rest = bind_rhs,
        } } });
    }
};

/// Structural `to_hash` specifics for the generic derivation driver. Hashing
/// threads a single value plus a running Hasher accumulator: each component
/// feeds the hasher accumulated so far, left to right.
const HashDeriver = struct {
    const structural_kind: static_dispatch.StructuralKind = .hash;

    const Operand = struct {
        value: DraftExprId,
        hasher: DraftExprId,
    };

    /// Left-to-right: each component hashes into the accumulator threaded from
    /// the previous one.
    const forward = true;

    fn expansionStack(self: *BodyContext) *collections.DenseMap(Type.TypeId, void) {
        return &self.hash_expansion_stack;
    }

    fn defCache(self: *BodyContext) *std.AutoHashMap(GeneratedHelperDefAddress, DraftGeneratedHelperDefEntry) {
        return &self.hash_defs;
    }

    fn defAddress(value_ty: Type.TypeId, result_ty: Type.TypeId) GeneratedHelperDefAddress {
        return .{ .value_ty = @backingInt(value_ty), .result_ty = @backingInt(result_ty) };
    }

    fn fnType(self: *BodyContext, value_ty: Type.TypeId, result_ty: Type.TypeId) Allocator.Error!DraftTypeCell {
        return try self.hashFnTypeCell(value_ty, result_ty);
    }

    fn callArgs(operand: Operand) [2]DraftExprId {
        return .{ operand.value, operand.hasher };
    }

    fn helperSecondArgType(_: Type.TypeId, result_ty: Type.TypeId) Type.TypeId {
        return result_ty;
    }

    fn helperOperand(self_expr: DraftExprId, aux_expr: DraftExprId) Operand {
        return .{ .value = self_expr, .hasher = aux_expr };
    }

    fn leaf(self: *BodyContext, operand: Operand, ctx: BodyContext.DerivationCtx) Allocator.Error!DraftExprId {
        return try self.addExpr(.{ .ty = ctx.result_ty, .data = .{ .structural_hash = .{
            .value = operand.value,
            .hasher = operand.hasher,
        } } });
    }

    fn combineSeed(_: *BodyContext, operand: Operand, _: BodyContext.DerivationCtx) Allocator.Error!DraftExprId {
        return operand.hasher;
    }

    fn combine(_: *BodyContext, _: DraftExprId, component: DraftExprId, _: BodyContext.DerivationCtx) Allocator.Error!DraftExprId {
        return component;
    }

    fn componentForField(self: *BodyContext, operand: Operand, state: DraftExprId, field: Type.Field) Allocator.Error!Operand {
        const field_value = try self.addFieldAccessExpr(operand.value, field.name, field.ty);
        return .{ .value = field_value, .hasher = state };
    }

    fn componentForTuple(self: *BodyContext, operand: Operand, state: DraftExprId, item_ty: Type.TypeId, index: usize) Allocator.Error!Operand {
        const item_value = try self.addExpr(.{ .ty = item_ty, .data = .{ .tuple_access = .{
            .tuple = operand.value,
            .elem_index = @intCast(index),
        } } });
        return .{ .value = item_value, .hasher = state };
    }

    const missing_component_method_msg = "checked method registry is missing List to_hash target";

    fn methodArgTypes(ty: Type.TypeId, result_ty: Type.TypeId) [2]Type.TypeId {
        return .{ ty, result_ty };
    }

    const NamedLocals = struct { inner: DraftLocalId };

    const NamedEntry = struct { locals: NamedLocals, operand: Operand };

    fn namedEnter(self: *BodyContext, backing_ty: Type.TypeId, operand: Operand) Allocator.Error!NamedEntry {
        const inner = try self.addLocal(self.builder.symbols.fresh(), backing_ty);
        return .{
            .locals = .{ .inner = inner },
            .operand = .{
                .value = try self.localExpr(inner, backing_ty),
                .hasher = operand.hasher,
            },
        };
    }

    fn namedExit(self: *BodyContext, named_ty: Type.TypeId, backing_ty: Type.TypeId, locals: NamedLocals, operand: Operand, hashed: DraftExprId, ctx: BodyContext.DerivationCtx) Allocator.Error!DraftExprId {
        const pat = try self.addPat(.{ .ty = named_ty, .data = .{ .nominal = try self.bindPat(locals.inner, backing_ty) } });
        return try self.addExpr(.{ .ty = ctx.result_ty, .data = .{ .let_ = .{
            .bind = pat,
            .value = operand.value,
            .rest = hashed,
        } } });
    }

    // A tag-union hash writes the discriminant index into the hasher, then
    // matches on the value and threads the active variant's payloads through.

    /// The value binds to a local so it is matched exactly once.
    const TagUnionLocals = struct { value: DraftLocalId };

    fn tagUnionEnter(self: *BodyContext, value_ty: Type.TypeId) Allocator.Error!TagUnionLocals {
        return .{ .value = try self.addLocal(self.builder.symbols.fresh(), value_ty) };
    }

    const TagBranchPayloads = struct {
        pats: []DraftPatId = &.{},
        exprs: []DraftExprId = &.{},

        fn deinit(payloads: *TagBranchPayloads, allocator: Allocator) void {
            allocator.free(payloads.pats);
            allocator.free(payloads.exprs);
            payloads.* = .{};
        }
    };

    /// Bind one variant's payloads; the branch's hasher starts with the
    /// discriminant index written.
    fn tagBranchEnter(self: *BodyContext, _: Type.TypeId, payloads: []const Type.TypeId, variant_index: u64, operand: Operand, branch: *TagBranchPayloads, ctx: BodyContext.DerivationCtx) Allocator.Error!DraftExprId {
        branch.pats = try self.allocator.alloc(DraftPatId, payloads.len);
        branch.exprs = try self.allocator.alloc(DraftExprId, payloads.len);
        for (payloads, 0..) |payload_ty, i| {
            const payload_local = try self.addLocal(self.builder.symbols.fresh(), payload_ty);
            branch.pats[i] = try self.bindPat(payload_local, payload_ty);
            branch.exprs[i] = try self.localExpr(payload_local, payload_ty);
        }
        return try self.hasherWriteU64(operand.hasher, variant_index, ctx.result_ty);
    }

    fn tagPayloadOperand(branch: TagBranchPayloads, index: usize, hasher: DraftExprId) Operand {
        return .{ .value = branch.exprs[index], .hasher = hasher };
    }

    fn tagBranchExit(self: *BodyContext, value_ty: Type.TypeId, _: TagUnionLocals, tag: Type.Tag, branch: TagBranchPayloads, acc: DraftExprId, _: bool, _: BodyContext.DerivationCtx) Allocator.Error!DraftBranch {
        const tag_pat = try self.addPat(.{ .ty = value_ty, .data = .{ .tag = .{
            .name = tag.name,
            .payloads = try self.addPatSpan(branch.pats),
        } } });
        return .{ .pat = tag_pat, .body = acc };
    }

    fn tagUnionExit(self: *BodyContext, value_ty: Type.TypeId, locals: TagUnionLocals, operand: Operand, branches: []const DraftBranch, ctx: BodyContext.DerivationCtx) Allocator.Error!DraftExprId {
        const match_expr = try self.addExpr(.{ .ty = ctx.result_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(locals.value, value_ty),
            .branches = try self.addBranchSpan(branches),
        } } });

        return try self.addExpr(.{ .ty = ctx.result_ty, .data = .{ .let_ = .{
            .bind = try self.bindPat(locals.value, value_ty),
            .value = operand.value,
            .rest = match_expr,
        } } });
    }
};

fn moduleViewData(view: checked.ImportedModuleView) ModuleViewData {
    return .{
        .code_generation_key = view.code_generation_key,
        .key = view.key,
        .module_env = view.module_env,
        .module_identity = view.module_identity,
        .names = checked.importedNames(view),
        .types = view.checked_types,
        .bodies = view.checked_bodies,
        .exhaustiveness_sites = view.exhaustiveness_sites,
        .checked_const_bodies = view.checked_const_bodies,
        .templates = view.checked_procedure_templates,
        .compile_time_roots = view.compile_time_roots,
        .entry_wrappers = view.entry_wrappers,
        .intrinsic_wrappers = view.intrinsic_wrappers,
        .hosted_procs = view.hosted_procs,
        .hosted_bindings = view.hosted_bindings,
        .static_dispatch_plans = view.static_dispatch_plans,
        .method_registry = view.method_registry,
        .method_lookup_scope = view.method_lookup_scope,
        .resolved_refs = view.resolved_value_refs,
        .nested_proc_sites = view.nested_proc_sites,
        .exported_procedure_bindings = view.exported_procedure_bindings,
        .exported_const_templates = view.exported_const_templates,
        .top_level_procedure_bindings = view.top_level_procedure_bindings,
        .platform_required_bindings = view.platform_required_bindings,
        .callable_eval_templates = view.callable_eval_templates,
        .hoisted_constants = view.hoisted_constants,
        .const_templates = view.const_templates,
        .const_store = view.const_store,
        .interface_capabilities = view.interface_capabilities,
    };
}

fn moduleViewIdentityMatches(view: ModuleView, origin_hash: *const [32]u8) bool {
    return base.ModuleIdentity.eql(&view.module_identity.stable_hash, origin_hash);
}

/// Restore a `ConstStore` value into one lowering scope's expression data.
///
/// `Builder` and `BodyContext` emit into different stores and different
/// expression-data types, but the restoration itself is one set of rules:
/// which const shapes map to which expression forms, plus the length
/// invariants relating a stored aggregate to its checked type. `restorer` is
/// scope is emitting; it supplies its own store through `constEmit()`, its data
/// type through `ConstExprData`, its scalar mapping through `constScalarData`,
/// its type and name queries through scope-owned methods, and the recursive descent
/// through `restoreConstNodeAtTypeWithStaticRoot`, which genuinely differs
/// between the two.
/// How a restorer starts one stored constant node.
fn ConstRestoreStart(comptime Id: type) type {
    return union(enum) {
        /// The node's expression, already built or reused.
        done: Id,
        /// A nominal construction layer: `child` restored at `backing`,
        /// wrapped in `named`.
        layer: ConstRestoreLayer,
        /// The node's stored value, built once its children are restored.
        value: checked.ConstValue,
    };
}

const ConstRestoreLayer = struct {
    child: checked.ConstNodeId,
    backing: Type.TypeId,
    named: Type.TypeId,
};

fn ConstRestoreFrame(comptime Id: type) type {
    return struct {
        node: checked.ConstNodeId,
        ty: Type.TypeId,
        layer: ?ConstRestoreLayer = null,
        started: bool = false,
        value: checked.ConstValue = undefined,
        /// A box's payload or a nominal's backing.
        single_child: ?checked.ConstNodeId = null,
        children: []const checked.ConstNodeId = &.{},
        tag_name: names.TagNameId = undefined,
        lowered: std.ArrayListUnmanaged(Id) = .empty,

        fn childCount(frame: *const @This()) usize {
            return if (frame.single_child != null) 1 else frame.children.len;
        }

        fn child(frame: *const @This(), index: usize) checked.ConstNodeId {
            return frame.single_child orelse frame.children[index];
        }
    };
}

/// Restore a stored constant's node tree at `root_ty` on explicit frames:
/// each node's children are restored in order before the node itself.
fn runConstRestore(
    restorer: anytype,
    store_view: ModuleView,
    type_view: ModuleView,
    root: checked.ConstNodeId,
    root_ty: Type.TypeId,
    static_data_const_locator: ?checked.ConstLocator,
) Allocator.Error!@TypeOf(restorer.*).ConstExprId {
    const Id = @TypeOf(restorer.*).ConstExprId;
    var frames: std.ArrayListUnmanaged(ConstRestoreFrame(Id)) = .empty;
    defer {
        for (frames.items) |*frame| frame.lowered.deinit(restorer.allocator);
        frames.deinit(restorer.allocator);
    }
    var delivered = try beginConstRestoreNode(restorer, &frames, store_view, type_view, root, root_ty, static_data_const_locator);
    while (frames.items.len != 0) {
        const frame = &frames.items[frames.items.len - 1];
        if (frame.layer) |layer| {
            if (!frame.started) {
                frame.started = true;
                delivered = try beginConstRestoreNode(restorer, &frames, store_view, type_view, layer.child, layer.backing, static_data_const_locator);
                continue;
            }
            const finished = frames.pop().?;
            delivered = try restorer.finishConstRestoreLayer(store_view, type_view, finished.node, finished.ty, layer.named, delivered.?, static_data_const_locator);
            continue;
        }
        if (delivered) |lowered| try frame.lowered.append(restorer.allocator, lowered);
        delivered = null;
        if (frame.lowered.items.len < frame.childCount()) {
            const index = frame.lowered.items.len;
            const child_ty = constRestoreChildType(restorer, frame, index);
            delivered = try beginConstRestoreNode(restorer, &frames, store_view, type_view, frame.child(index), child_ty, static_data_const_locator);
            continue;
        }
        var finished = frames.pop().?;
        defer finished.lowered.deinit(restorer.allocator);
        const data = try constRestoreData(restorer, store_view, &finished);
        delivered = try restorer.finishConstRestoreData(store_view, type_view, finished.node, finished.ty, data, static_data_const_locator);
    }
    return delivered.?;
}

/// Start one node: its expression when the restorer has it or it has no
/// children, else the frame that restores its children.
fn beginConstRestoreNode(
    restorer: anytype,
    frames: anytype,
    store_view: ModuleView,
    type_view: ModuleView,
    node: checked.ConstNodeId,
    ty: Type.TypeId,
    static_data_const_locator: ?checked.ConstLocator,
) Allocator.Error!?@TypeOf(restorer.*).ConstExprId {
    const value = switch (try restorer.startConstRestore(store_view, type_view, node, ty, static_data_const_locator)) {
        .done => |expr| return expr,
        .layer => |layer| {
            try frames.append(restorer.allocator, .{ .node = node, .ty = ty, .layer = layer });
            return null;
        },
        .value => |value| value,
    };
    var frame: ConstRestoreFrame(@TypeOf(restorer.*).ConstExprId) = .{ .node = node, .ty = ty, .value = value };
    switch (value) {
        .box => |payload| frame.single_child = payload,
        .list => |list| switch (list) {
            .nodes => |items| frame.children = items,
            .empty, .packed_bytes => {},
        },
        .tuple => |items| {
            if (restorer.tupleItemTypes(ty).len != items.len) Common.invariant("ConstStore tuple length differs from checked type");
            frame.children = items;
        },
        .record => |items| {
            if (restorer.constRecordFields(ty).len != items.len) Common.invariant("ConstStore record length differs from checked type");
            frame.children = items;
        },
        .tag => |tag| {
            frame.tag_name = try restorer.constNameStore().internTagLabel(tag.tag_name);
            if (restorer.tagPayloadTypes(ty, frame.tag_name).len != tag.payloads.len) Common.invariant("ConstStore tag payload count differs from checked type");
            frame.children = tag.payloads;
        },
        .nominal => |nominal| frame.single_child = nominal.backing,
        .pending, .zst, .scalar, .str, .crash, .checked_error, .fn_value => {},
    }
    if (frame.childCount() == 0) {
        const data = try constRestoreData(restorer, store_view, &frame);
        return try restorer.finishConstRestoreData(store_view, type_view, node, ty, data, static_data_const_locator);
    }
    try frames.append(restorer.allocator, frame);
    return null;
}

/// The type child `index` of a restoring node is restored at.
fn constRestoreChildType(restorer: anytype, frame: anytype, index: usize) Type.TypeId {
    return switch (frame.value) {
        .box => restorer.constBoxPayloadType(frame.ty),
        .list => restorer.constListElemType(frame.ty),
        .tuple => GuardedList.at(restorer.tupleItemTypes(frame.ty), index),
        .record => GuardedList.at(restorer.constRecordFields(frame.ty), index).ty,
        .tag => GuardedList.at(restorer.tagPayloadTypes(frame.ty, frame.tag_name), index),
        .nominal => restorer.namedBackingType(frame.ty) orelse frame.ty,
        .pending, .zst, .scalar, .str, .crash, .checked_error, .fn_value => Common.invariant("ConstStore leaf node had a restored child"),
    };
}

/// A restored node's expression data, from its restored children.
fn constRestoreData(
    restorer: anytype,
    store_view: ModuleView,
    frame: anytype,
) Allocator.Error!@TypeOf(restorer.*).ConstExprData {
    const emit = restorer.constEmit();
    const lowered = frame.lowered.items;
    return switch (frame.value) {
        .pending => Common.invariant("pending ConstStore node reached Monotype restore"),
        .zst => .unit,
        .scalar => |scalar| restorer.constScalarData(scalar),
        .str => |str| .{ .str_lit = try emit.addStringView(
            store_view.const_store.blobData(str.data),
            str.offset,
            str.len,
        ) },
        .crash => |str| .{ .crash = try emit.addStringView(
            store_view.const_store.blobData(str.data),
            str.offset,
            str.len,
        ) },
        .checked_error => |str| .{ .checked_error = try emit.addStringView(
            store_view.const_store.blobData(str.data),
            str.offset,
            str.len,
        ) },
        .box => .{ .low_level = .{
            .op = .box_box,
            .args = try emit.addExprSpan(lowered),
        } },
        .list => |list| switch (list) {
            .nodes => .{ .list = try emit.addExprSpan(lowered) },
            .empty => |capacity| try restorer.constEmptyListData(capacity),
            .packed_bytes => |packed_list| .{ .bytes_lit = .{
                .literal = try emit.addConstBlobView(
                    store_view.key.bytes,
                    packed_list.bytes.data,
                    store_view.const_store.blobData(packed_list.bytes.data),
                    packed_list.bytes.offset,
                    packed_list.bytes.len,
                ),
                .len = packed_list.len,
                .element = packed_list.element,
                .product_width = packed_list.product_width,
            } },
        },
        .tuple => .{ .tuple = try emit.addExprSpan(lowered) },
        .record => blk: {
            const Field = @TypeOf(restorer.*).ConstFieldExpr;
            const fields = restorer.constRecordFields(frame.ty);
            const restored = try restorer.allocator.alloc(Field, lowered.len);
            defer restorer.allocator.free(restored);
            for (restored, lowered, 0..) |*field, value, index| {
                field.* = .{ .name = GuardedList.at(fields, index).name, .value = value };
            }
            break :blk .{ .record = try emit.addFieldExprSpan(restored) };
        },
        .tag => .{ .tag = .{
            .name = frame.tag_name,
            .payloads = try emit.addExprSpan(lowered),
        } },
        .nominal => .{ .nominal = lowered[0] },
        .fn_value => Common.invariant("ConstStore function value must be restored as an expression"),
    };
}

fn restoreScalar(comptime Data: type, scalar: checked.ConstScalar) Data {
    return switch (scalar) {
        .i8, .i16, .i32, .i64, .i128 => |value| .{ .int_lit = signedIntLiteral(value) },
        .u8, .u16, .u32, .u64, .u128 => |value| .{ .int_lit = unsignedIntLiteral(value) },
        .f32_bits => |bits| .{ .frac_f32_lit = @bitCast(bits) },
        .f64_bits => |bits| .{ .frac_f64_lit = @bitCast(bits) },
        .dec_bits => |bits| .{ .dec_lit = .{ .num = bits } },
    };
}

fn signedIntLiteral(value: anytype) can.CIR.IntValue {
    const widened: i128 = @intCast(value);
    return .{ .bytes = @bitCast(widened), .kind = .i128 };
}

fn unsignedIntLiteral(value: anytype) can.CIR.IntValue {
    const widened: u128 = @intCast(value);
    return .{ .bytes = @bitCast(widened), .kind = .u128 };
}

fn generatedCodecRuntimeKey(
    comptime domain: []const u8,
    current_fn_key: names.TypeDigest,
    source_expr_id: checked.CheckedExprId,
) names.TypeDigest {
    var hasher = TypeDigestHasher.init();
    hasher.update(domain);
    hasher.update(&current_fn_key.bytes);
    var source_expr_bytes = std.mem.nativeToLittle(u32, @backingInt(source_expr_id));
    hasher.update(std.mem.asBytes(&source_expr_bytes));
    return .{ .bytes = hasher.finalResult() };
}

fn generatedEncoderCallbackKey(
    current_fn_key: names.TypeDigest,
    source_expr_id: checked.CheckedExprId,
    index: u64,
) names.TypeDigest {
    var hasher = TypeDigestHasher.init();
    hasher.update("roc.generated_structural_encoder_callback");
    hasher.update(&current_fn_key.bytes);
    var source_expr_bytes = std.mem.nativeToLittle(u32, @backingInt(source_expr_id));
    hasher.update(std.mem.asBytes(&source_expr_bytes));
    var index_bytes = std.mem.nativeToLittle(u64, index);
    hasher.update(std.mem.asBytes(&index_bytes));
    return .{ .bytes = hasher.finalResult() };
}

fn restoredConstFnContextKey(
    module_key: checked.ModuleId,
    fn_id: checked.ConstFnId,
    source_fn_key: names.TypeDigest,
) names.TypeDigest {
    var hasher = TypeDigestHasher.init();
    hasher.update("roc.restored_const_fn_context");
    hasher.update(&module_key.bytes);
    hasher.update(&source_fn_key.bytes);
    var fn_id_bytes = std.mem.nativeToLittle(u32, @backingInt(fn_id));
    hasher.update(std.mem.asBytes(&fn_id_bytes));
    return .{ .bytes = hasher.finalResult() };
}

fn restoredLocalProcUseContextKey(
    restored_fn_key: names.TypeDigest,
    source_contexts: names.TypeDigest,
    binder: checked.PatternBinderId,
) names.TypeDigest {
    var hasher = TypeDigestHasher.init();
    hasher.update("roc.monotype.restored_local_proc_context");
    hasher.update(&restored_fn_key.bytes);
    hasher.update(&source_contexts.bytes);
    hashU32(&hasher, @backingInt(binder));
    return .{ .bytes = hasher.finalResult() };
}

fn parserEncodingCaptureId() u32 {
    return 0;
}

fn encoderForEncodingCaptureId() u32 {
    return 0;
}

fn encoderForFirstFieldCaptureId() usize {
    return 1;
}

fn generatedFieldNamesIterStepKey(
    current_fn_key: names.TypeDigest,
    source_expr_id: checked.CheckedExprId,
    index: usize,
    mode: FieldNamesIterMode,
) names.TypeDigest {
    var hasher = TypeDigestHasher.init();
    hasher.update("roc.generated_fields_iter_step");
    hasher.update(&current_fn_key.bytes);
    var source_expr_bytes = std.mem.nativeToLittle(u32, @backingInt(source_expr_id));
    hasher.update(std.mem.asBytes(&source_expr_bytes));
    var index_bytes = std.mem.nativeToLittle(u64, @intCast(index));
    hasher.update(std.mem.asBytes(&index_bytes));
    const mode_byte: u8 = switch (mode) {
        .all => 0,
        .for_size => 1,
    };
    hasher.update(&[_]u8{mode_byte});
    return .{ .bytes = hasher.finalResult() };
}

/// Whether any segment of a checked field-access path is a `.?` access, which
/// routes the whole chain through the optional-chain lowering (one flat Try).
fn fieldAccessAnySegmentOptional(segments: []const checked.CheckedFieldAccessSegment) bool {
    for (segments) |segment| {
        if (segment.mode == .optional) return true;
    }
    return false;
}

fn checkedPayload(view: ModuleView, checked_ty: checked.CheckedTypeId) checked.CheckedTypePayload {
    const raw = @backingInt(checked_ty);
    if (raw >= view.types.payloadCount()) Common.invariant("checked type id outside checked type store");
    return view.types.payload(checked_ty);
}

fn schemeRoot(view: ModuleView, source_scheme: anytype, comptime missing_message: []const u8) checked.CheckedTypeId {
    const scheme = view.types.schemeForKey(source_scheme) orelse Common.invariant(missing_message);
    return scheme.root;
}

fn checkedLambdaExprIdForConstFn(view: ModuleView, fn_def: anytype) checked.CheckedExprId {
    return switch (fn_def) {
        .nested => |nested| blk: {
            const site = checkedNestedSite(view, nested);
            const expr_id = site.checked_expr orelse Common.invariant("stored nested function had no checked expression site");
            const expr = view.bodies.expr(expr_id);
            break :blk switch (expr.data) {
                .lambda => expr_id,
                .closure => |closure| closure.lambda,
                .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("stored nested function site did not point at a lambda or closure"),
            };
        },
        .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => Common.invariant("capturing stored function must reference a checked nested function"),
    };
}

fn ownerTemplateForConstFnDef(fn_def: anytype) names.ProcTemplate {
    return switch (fn_def) {
        .nested => |nested| nested.owner,
        inline .parser_runtime, .encoder_for_runtime => |runtime| runtime.owner,
        .local_template,
        .imported_template,
        .local_hosted,
        .imported_hosted,
        .checked_generated,
        => |template| template,
    };
}

/// Whether a stored function definition names a default-root site (a lambda
/// inside a defaulted-field expression, design.md "Defaulted Fields").
/// Restore contexts for such functions run in default-materialization mode:
/// `in_default_expr` set, view swapped to the declaring module, and no
/// owner-template dispatch relations instantiated.
fn constFnDefIsDefaultRoot(fn_def: anytype) bool {
    return switch (fn_def) {
        .nested => |nested| nested.default_root != null,
        .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => false,
    };
}

fn templateForConstFnDef(fn_def: check.ConstStore.FnDef) names.ProcTemplate {
    return switch (fn_def) {
        .local_template,
        .imported_template,
        .local_hosted,
        .imported_hosted,
        .checked_generated,
        => |template| template,
        .nested => |nested| nested.owner,
        .parser_runtime, .encoder_for_runtime => Common.invariant("generated runtime function has no checked evidence template"),
    };
}

fn checkedNestedSite(view: ModuleView, nested: anytype) checked.NestedProcSite {
    // A default-root-qualified stored function names the declaring module's
    // default root as the site owner; `view` is already that module
    // (`moduleForConstFnDef` resolves it by content identity), so the match
    // is by site id against the `.default_root` owner (design.md "Defaulted
    // Fields"—const-store restore is the second sanctioned resolver of
    // default-root sites, after live default materialization).
    const wants_default_root = nested.default_root != null;
    for (view.nested_proc_sites.sites) |site| {
        if (site.site != nested.site) continue;
        switch (site.owner) {
            .template => |site_owner| {
                if (wants_default_root) continue;
                if (!names.procedureTemplateRefEql(site_owner, nested.owner)) continue;
            },
            .default_root => if (!wants_default_root) continue,
        }
        return site;
    }
    Common.invariant("stored nested function referenced a missing checked nested site");
}

fn checkedBinderType(view: ModuleView, binder: checked.PatternBinderId) checked.CheckedTypeId {
    const raw = @backingInt(binder);
    if (raw >= view.bodies.patternBinderCount()) Common.invariant("stored function capture binder is outside checked body store");
    const pattern = view.bodies.patternBinder(@fromBackingInt(@intCast(raw))).pattern;
    const pattern_raw = @backingInt(pattern);
    if (pattern_raw >= view.bodies.patternCount()) Common.invariant("stored function capture pattern is outside checked body store");
    return view.bodies.pattern(@fromBackingInt(@intCast(pattern_raw))).ty;
}

fn checkedCaptureBinder(view: ModuleView, pattern: checked.CheckedPatternId) checked.PatternBinderId {
    const raw = @backingInt(pattern);
    if (raw >= view.bodies.pattern_binder_by_pattern.len) Common.invariant("checked closure capture pattern was outside the binder index");
    return view.bodies.pattern_binder_by_pattern[raw] orelse
        Common.invariant("checked closure capture pattern had no binder");
}

fn constCaptureBinder(id: check.ConstStore.CaptureId) checked.PatternBinderId {
    if (!id.isCanonical()) Common.invariant("generated capture reached source lambda restore");
    return id.binder();
}

fn constGeneratedCaptureNode(fn_value: check.ConstStore.ConstFn, capture_id: u32) ?checked.ConstNodeId {
    const needle = checked.CaptureId.generatedCheck(capture_id);
    for (fn_value.captures) |capture| {
        if (capture.id == needle) return capture.value;
    }
    return null;
}

fn monotypePrimitive(primitive: check.ConstStore.Primitive) Type.Primitive {
    return std.meta.stringToEnum(Type.Primitive, @tagName(primitive)) orelse
        Common.invariant("ConstStore primitive had no Monotype primitive equivalent");
}

fn monotypeNamedKind(kind: check.ConstStore.TypeNamedKind) Type.NamedKind {
    return switch (kind) {
        .nominal => .nominal,
        .@"opaque" => .@"opaque",
        .alias => Common.invariant("stored transparent alias reserved a Monotype wrapper"),
    };
}

fn monotypeBackingUse(use: check.ConstStore.TypeBackingUse) Type.BackingUse {
    return switch (use) {
        .inspectable => .inspectable,
        .runtime_layout_only => .runtime_layout_only,
    };
}

fn monotypeBackingAuthority(authority: check.ConstStore.TypeBackingAuthority) Type.BackingAuthority {
    return switch (authority) {
        .checked_public => .checked_public,
        .generated_private => .generated_private,
    };
}

fn constStrNodeByteLen(view: ModuleView, node: checked.ConstNodeId) u32 {
    return switch (view.const_store.get(node)) {
        .str => |str| str.len,
        .pending, .zst, .scalar, .list, .box, .tuple, .record, .crash, .checked_error, .tag, .nominal, .fn_value => Common.invariant("stored parser renamed field capture was not a Str constant"),
    };
}

fn constStrNodeBytes(view: ModuleView, node: checked.ConstNodeId) []const u8 {
    return switch (view.const_store.get(node)) {
        .str => |str| view.const_store.strBytes(str),
        .pending, .zst, .scalar, .list, .box, .tuple, .record, .crash, .checked_error, .tag, .nominal, .fn_value => Common.invariant("stored parser renamed field capture was not a Str constant"),
    };
}

fn dispatchPlanForRuntimeExpr(view: ModuleView, expr_id: checked.CheckedExprId) static_dispatch.StaticDispatchCallPlan {
    const plan_id = dispatchPlanIdForRuntimeExpr(view, expr_id);
    return view.static_dispatch_plans.plans[@backingInt(plan_id)];
}

fn dispatchPlanIdForRuntimeExpr(view: ModuleView, expr_id: checked.CheckedExprId) static_dispatch.StaticDispatchPlanId {
    const expr = view.bodies.expr(expr_id);
    const plan_id = switch (expr.data) {
        .dispatch_call => |maybe| maybe orelse Common.invariant("stored serialization dispatch expression had no dispatch plan"),
        .type_dispatch_call => |maybe| maybe orelse Common.invariant("stored serialization type dispatch expression had no dispatch plan"),
        .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .interpolation, .structural_eq, .structural_hash, .method_eq, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("stored serialization runtime function did not reference a dispatch expression"),
    };
    const plan_raw = @backingInt(plan_id);
    if (plan_raw >= view.static_dispatch_plans.plans.len) Common.invariant("stored serialization dispatch plan is outside plan table");
    return plan_id;
}

/// Builds without libc (the playground) never read the environment and
/// compile no trace output.
const pack_trace_available = @import("builtin").link_libc;

/// `ROC_PACK_TRACE` is set: print every object cache lookup.
fn packTraceEnabled() bool {
    return std.c.getenv("ROC_PACK_TRACE") != null;
}

fn moduleDigestFromId(key: checked.ModuleId) names.CheckedModuleDigest {
    return .{ .bytes = key.bytes };
}

/// Content bytes identifying a procedure-use root: the module it was
/// requested from, the request's kind and checked source site, and the
/// procedure binding's declared function type key.
/// The literal a literal root converts; its return type joins the
/// definition's identity when the definition seals.
fn literalRootIdentity(module: checked.ModuleId, expr_id: checked.CheckedExprId) [32]u8 {
    var hasher = TypeDigestHasher.init();
    hasher.update("roc.monotype.literal-root.v1");
    hasher.update(&module.bytes);
    hashU32(&hasher, @backingInt(expr_id));
    return hasher.finalResult();
}

fn procedureUseRootIdentity(request: checked.RootRequest, procedure: checked.ProcedureUseTemplate, source_module: checked.ModuleId) [32]u8 {
    var hasher = TypeDigestHasher.init();
    hasher.update("roc.monotype.procedure-use-root.v1");
    hasher.update(&source_module.bytes);
    hasher.update(@tagName(request.kind));
    hasher.update(@tagName(request.source));
    switch (request.source) {
        .def => |def| hashU32(&hasher, @backingInt(def)),
        .expr => |expr| hashU32(&hasher, @backingInt(expr)),
        .statement => |statement| hashU32(&hasher, @backingInt(statement)),
        .required_binding => |binding| hashU32(&hasher, binding),
        .hoisted => {},
    }
    if (request.compile_time_root) |root| {
        hasher.update("compile-time-root");
        hashU32(&hasher, @backingInt(root));
    }
    hasher.update(&procedure.source_fn_ty_template.bytes);
    return hasher.finalResult();
}

fn hashU32(hasher: *TypeDigestHasher, value: u32) void {
    const little = std.mem.nativeToLittle(u32, value);
    hasher.update(std.mem.asBytes(&little));
}

fn hostedTemplate(hosted: anytype) names.ProcTemplate {
    const Hosted = @TypeOf(hosted);
    if (Hosted == names.ProcTemplate) return hosted;
    if (Hosted == Ast.HostedFn) return hosted.template;
    @compileError("unsupported hosted function payload");
}

fn methodOwnerFromType(types: *const Type.Store, ty: Type.TypeId) ?static_dispatch.MethodOwner {
    return switch (types.ownerHead(ty)) {
        .none => null,
        .builtin => |owner| .{ .builtin = owner },
        .named_type => |def| .{ .nominal = .{
            .module = def.module,
            .type_name = def.type_name,
            .source_decl = def.source_decl,
        } },
    };
}

/// Decides whether a graph node is proven uninhabited. A node on the active
/// path is not.
const NodeUninhabitedScan = struct {
    body: *BodyContext,
    backing_access: BodyContext.UninhabitedBackingAccess,
    /// Encounters whose answer later graph work can change: an unresolved
    /// node, a named node's backing, or a node already on the path. A node
    /// whose expansion saw none has a settled answer.
    unsettled_hits: usize = 0,

    const Evaluation = AnyAll.Evaluation(NodeId, NodeUninhabitedScan);

    fn settled(self: *NodeUninhabitedScan) *std.AutoHashMapUnmanaged(NodeId, bool) {
        return &self.body.settled_node_uninhabited[@backingInt(self.backing_access)];
    }

    pub fn enter(self: *NodeUninhabitedScan, items: Evaluation.Items, node: NodeId) Allocator.Error!Evaluation.Expansion {
        const body = self.body;
        const root = body.graph.rootNode(node);
        const root_index = @backingInt(root);
        if (body.inhabitation_visiting.bit_length <= root_index) {
            try body.inhabitation_visiting.resize(body.allocator, root_index + 1, false);
        }
        if (body.inhabitation_visiting.isSet(root_index)) {
            self.unsettled_hits += 1;
            return .{ .value = false };
        }
        if (self.settled().get(root)) |answer| return .{ .value = answer };
        // An unread leaf is exactly its finished type, whose answer is
        // settled.
        if (body.graph.leafType(root)) |ty| return .{ .value = try body.typeIsProvenUninhabitedWith(ty, self.backing_access) };

        const expansion: Evaluation.Expansion = switch ((try body.graph.content(root))) {
            .redirect => |target| blk: {
                try items.add(target);
                break :blk .{ .group = .any };
            },
            .leaf => unreachable,
            .empty_tag_union => .{ .value = true },
            .named => |named| blk: {
                self.unsettled_hits += 1;
                const backing = named.backing orelse break :blk .{ .value = false };
                if (backing.use != .inspectable and self.backing_access != .runtime_layout) break :blk .{ .value = false };
                try items.add(backing.node);
                break :blk .{ .group = .any };
            },
            .box => |payload| blk: {
                try items.add(payload);
                break :blk .{ .group = .any };
            },
            .tuple => |elems| blk: {
                for (elems) |elem| try items.add(elem);
                break :blk .{ .group = .any };
            },
            .record => |record| blk: {
                for (record.fields) |field| try items.add(field.ty);
                break :blk .{ .group = .any };
            },
            // Uninhabited when its extension is and every tag has an
            // uninhabited payload.
            .tag_union => |tag_union| blk: {
                try items.add(tag_union.ext);
                for (tag_union.tags) |tag| {
                    try items.group(.any, tag.payloads.len);
                    for (tag.payloads) |payload| try items.add(payload);
                }
                break :blk .{ .group = .all };
            },
            .unresolved => blk: {
                self.unsettled_hits += 1;
                break :blk .{ .value = false };
            },
            .primitive,
            .list,
            .func,
            .empty_record,
            .erased,
            .zst,
            => .{ .value = false },
        };
        if (expansion == .group) {
            body.inhabitation_visiting.set(root_index);
            try body.inhabitation_entered.put(body.allocator, root, self.unsettled_hits);
        }
        return expansion;
    }

    pub fn exit(self: *NodeUninhabitedScan, node: NodeId, result: ?bool) std.mem.Allocator.Error!void {
        const body = self.body;
        const root = body.graph.rootNode(node);
        body.inhabitation_visiting.unset(@backingInt(root));
        const hits_before = (body.inhabitation_entered.fetchRemove(root) orelse return).value;
        const answer = result orelse return;
        if (self.unsettled_hits == hits_before) try self.settled().put(body.allocator, root, answer);
    }
};

/// Decides whether a runtime impossibility proof holds, memoizing each
/// proof node's result.
const ImpossibilityProofScan = struct {
    body: *BodyContext,
    memo: []?bool,
    active: []bool,

    const Evaluation = AnyAll.Evaluation(RuntimeImpossibilityProofId, ImpossibilityProofScan);

    pub fn enter(self: *ImpossibilityProofScan, items: Evaluation.Items, proof_id: RuntimeImpossibilityProofId) Allocator.Error!Evaluation.Expansion {
        const body = self.body;
        const index = @backingInt(proof_id);
        if (index >= body.draft.impossibility_proofs.items.len) {
            Common.invariant("runtime impossibility proof referenced a missing active proof node");
        }
        if (self.memo[index]) |result| return .{ .value = result };
        if (self.active[index]) Common.invariant("active runtime impossibility proof graph contained a cycle");
        const expansion: Evaluation.Expansion = switch (body.draft.impossibility_proofs.items[index]) {
            .node => |node| .{ .value = try body.nodeIsProvenUninhabited(node) },
            .never => .{ .value = false },
            .always => .{ .value = true },
            .pending => Common.invariant("runtime impossibility proof reservation was not filled during deferred preparation"),
            .forward => |child| blk: {
                try items.add(child);
                break :blk .{ .group = .any };
            },
            .any => |span| blk: {
                for (body.impossibilityProofSpan(span)) |child| try items.add(child);
                break :blk .{ .group = .any };
            },
            .all => |span| blk: {
                for (body.impossibilityProofSpan(span)) |child| try items.add(child);
                break :blk .{ .group = .all };
            },
        };
        switch (expansion) {
            .value => |result| self.memo[index] = result,
            .group => self.active[index] = true,
        }
        return expansion;
    }

    pub fn exit(self: *ImpossibilityProofScan, proof_id: RuntimeImpossibilityProofId, result: ?bool) std.mem.Allocator.Error!void {
        const index = @backingInt(proof_id);
        self.active[index] = false;
        if (result) |value| self.memo[index] = value;
    }
};

/// Decides whether a checked pattern is proven uninhabited: its own type is,
/// or one of its subpatterns is.
const PatternUninhabitedScan = struct {
    body: *BodyContext,

    const Evaluation = AnyAll.Evaluation(checked.CheckedPatternId, PatternUninhabitedScan);

    pub fn enter(self: *PatternUninhabitedScan, items: Evaluation.Items, pattern_id: checked.CheckedPatternId) Allocator.Error!Evaluation.Expansion {
        const body = self.body;
        const pattern = body.view.bodies.pattern(pattern_id);
        if (try body.nodeIsProvenUninhabited(try body.instNode(pattern.ty))) return .{ .value = true };
        switch (pattern.data) {
            .as => |as| try items.add(as.pattern),
            .applied_tag => |tag| for (tag.args) |arg| try items.add(arg),
            .nominal => |nominal| try items.add(nominal.backing_pattern),
            .record_destructure => |destructs| for (destructs) |destruct| {
                try items.add(switch (destruct.kind) {
                    .required, .sub_pattern, .rest => |child| child,
                });
            },
            .list => |list| {
                for (list.patterns) |child| try items.add(child);
                if (list.rest) |rest| {
                    if (rest.pattern) |rest_pattern| try items.add(rest_pattern);
                }
            },
            .tuple => |children| for (children) |child| try items.add(child),
            .str_interpolation => |str| for (str.steps) |step| {
                if (step.capture) |capture| try items.add(capture);
            },
            .pending,
            .assign,
            .numeral_literal,
            .str_literal,
            .underscore,
            .runtime_error,
            => return .{ .value = false },
        }
        return .{ .group = .any };
    }

    pub fn exit(_: *PatternUninhabitedScan, _: checked.CheckedPatternId, _: ?bool) std.mem.Allocator.Error!void {}
};

fn instRecordFieldLessThan(
    name_store: *const names.NameStore,
    lhs: InstField,
    rhs: InstField,
) bool {
    return name_store.recordFieldLabelTextLessThan(lhs.name, rhs.name);
}

fn nominalHasDeclarationBacking(nominal: checked.CheckedNominalType) bool {
    return switch (nominal.representation) {
        .opaque_without_backing => false,
        .builtin => |builtin| checked.builtinNominalHasDeclarationBacking(builtin),
        .local_declaration,
        .imported_declaration,
        .local_box_payload_capability,
        .imported_box_payload_capability,
        => true,
    };
}

fn builtinOwner(builtin: ?checked.CheckedBuiltinNominal) ?static_dispatch.BuiltinOwner {
    return switch (builtin orelse return null) {
        .bool => .bool,
        .str => .str,
        .u8 => .u8,
        .i8 => .i8,
        .u16 => .u16,
        .i16 => .i16,
        .u32 => .u32,
        .i32 => .i32,
        .u64 => .u64,
        .i64 => .i64,
        .u128 => .u128,
        .i128 => .i128,
        .f32 => .f32,
        .f64 => .f64,
        .dec => .dec,
        .u8x16 => .u8x16,
        .i8x16 => .i8x16,
        .u16x8 => .u16x8,
        .i16x8 => .i16x8,
        .u32x4 => .u32x4,
        .i32x4 => .i32x4,
        .u64x2 => .u64x2,
        .i64x2 => .i64x2,
        .list => .list,
        .box => .box,
        .dict => .dict,
        .set => .set,
        .parse_tag_union_spec => .parse_tag_union_spec,
        .fields => .fields,
        .field => .field,
        .try_ => null,
        .iter => .iter,
        .stream => .stream,
        .crypto_sha256_digest => .crypto_sha256_digest,
        .crypto_sha256_hasher => .crypto_sha256_hasher,
        .crypto_blake3_digest => .crypto_blake3_digest,
        .crypto_blake3_hasher => .crypto_blake3_hasher,
    };
}

const ResolvedPayload = struct {
    root: checked.CheckedTypeId,
    payload: checked.CheckedTypePayload,
};

fn resolvedPayload(view: ModuleView, ty: checked.CheckedTypeId) ResolvedPayload {
    var current = ty;
    var remaining = view.types.payloadCount();
    while (remaining > 0) : (remaining -= 1) {
        const payload = checkedPayload(view, current);
        switch (payload) {
            .alias => |alias| current = alias.backing,
            .pending, .err, .flex, .rigid, .record, .tuple, .nominal, .function, .empty_record, .tag_union, .empty_tag_union => return .{ .root = current, .payload = payload },
        }
    }
    Common.invariant("checked type alias chain was cyclic");
}

fn branchCount(branches: anytype) usize {
    var count: usize = 0;
    for (branches) |branch| count += branch.pt_len;
    return count;
}

fn moduleBytesEqual(a: [32]u8, b: [32]u8) bool {
    return std.mem.eql(u8, a[0..], b[0..]);
}

fn methodLookupIdentityEql(left: MethodLookup, right: MethodLookup) bool {
    if (!moduleBytesEqual(left.view.key.bytes, right.view.key.bytes)) return false;
    if (!std.meta.eql(left.target, right.target)) return false;
    if (left.local_proc_context != right.local_proc_context) return false;
    if (left.instantiation) |left_instantiation| {
        const right_instantiation = right.instantiation orelse return false;
        return moduleBytesEqual(left_instantiation.view.key.bytes, right_instantiation.view.key.bytes) and
            left_instantiation.callable_ty == right_instantiation.callable_ty;
    }
    return right.instantiation == null;
}

fn constUseEql(a: checked.ConstLocator, b: checked.ConstLocator) bool {
    const left_checked_module = checked.constModuleId(a);
    const right_checked_module = checked.constModuleId(b);
    return moduleBytesEqual(left_checked_module.bytes, right_checked_module.bytes) and
        constOwnerEql(a.owner, b.owner) and
        a.template == b.template and
        std.mem.eql(u8, a.source_scheme.bytes[0..], b.source_scheme.bytes[0..]);
}

fn constOwnerEql(a: checked.ConstOwner, b: checked.ConstOwner) bool {
    if (std.meta.activeTag(a) != std.meta.activeTag(b)) return false;
    return switch (a) {
        .top_level_binding => |left| blk: {
            const right = b.top_level_binding;
            break :blk left.module_idx == right.module_idx and left.pattern == right.pattern;
        },
        .hoisted_expr => |left| blk: {
            const right = b.hoisted_expr;
            break :blk left.module_idx == right.module_idx and left.expr == right.expr;
        },
    };
}

fn verifyMonotypeTypeStore(program: *const Ast.Program) void {
    if (program.types.verify(&program.names)) |err| switch (err) {
        .type_digest_count_mismatch => Common.invariant("Monotype type digest section length differed from type node count"),
        .type_span_out_of_bounds => Common.invariant("Monotype type span was out of bounds"),
        .field_span_out_of_bounds => Common.invariant("Monotype field span was out of bounds"),
        .tag_span_out_of_bounds => Common.invariant("Monotype tag span was out of bounds"),
        .declared_field_span_out_of_bounds => Common.invariant("Monotype declared field span was out of bounds"),
        .type_ref_out_of_bounds => Common.invariant("Monotype type reference was out of bounds"),
        .record_fields_not_sorted => Common.invariant("Monotype record fields were not normalized"),
        .tag_union_tags_not_sorted => Common.invariant("Monotype tag union variants were not normalized"),
    };
}

fn verifyMonotypeCompletedTypeIds(program: *const Ast.Program) void {
    if (program.view().verifyCompletedTypeIds()) |err| switch (err) {
        .type_store_not_frozen => Common.invariant("completed Monotype program view used a mutable type store"),
        .spec_type_out_of_bounds => Common.invariant("completed Monotype specialization record referenced a missing type"),
        .fn_type_out_of_bounds => Common.invariant("completed Monotype function referenced a missing type"),
        .def_type_out_of_bounds => Common.invariant("completed Monotype definition referenced a missing type"),
        .nested_def_type_out_of_bounds => Common.invariant("completed Monotype nested definition referenced a missing type"),
        .expr_type_out_of_bounds => Common.invariant("completed Monotype expression referenced a missing type"),
        .pat_type_out_of_bounds => Common.invariant("completed Monotype pattern referenced a missing type"),
        .local_type_out_of_bounds => Common.invariant("completed Monotype local referenced a missing type"),
        .typed_local_type_out_of_bounds => Common.invariant("completed Monotype typed local referenced a missing type"),
        .layout_request_type_out_of_bounds => Common.invariant("completed Monotype layout request referenced a missing type"),
        .runtime_schema_request_type_out_of_bounds => Common.invariant("completed Monotype runtime schema request referenced a missing type"),
    };
}

fn verifyMonotypeCallTargets(program: *const Ast.Program) void {
    if (program.view().verifyCallTargets()) |err| switch (err) {
        .local_fn_out_of_bounds => Common.invariant("Monotype direct call referenced a missing local function"),
        .local_fn_type_out_of_bounds => Common.invariant("Monotype direct call referenced a local function with a missing function type"),
        .local_fn_type_not_function => Common.invariant("Monotype direct call referenced a local function with a non-function type"),
        .local_fn_definition_arity_mismatch => Common.invariant("Monotype local function definition arity differed from its function type"),
        .local_call_arity_mismatch => Common.invariant("Monotype direct call arity differed from the callee function type"),
        .lifted_fn_before_lifting => Common.invariant("Monotype direct call referenced a lifted function before Monotype lifting"),
    };
}

fn sameTypeDef(left: Type.TypeDef, right: Type.TypeDef) bool {
    return left.module == right.module and
        left.type_name == right.type_name and
        left.source_decl == right.source_decl;
}

fn sameTypeDefAcrossStores(
    left_names: *const names.NameStore,
    left: Type.TypeDef,
    right_names: *const names.NameStore,
    right: Type.TypeDef,
) bool {
    return std.mem.eql(
        u8,
        left_names.moduleIdentityBytes(left.module),
        right_names.moduleIdentityBytes(right.module),
    ) and
        Ident.textEql(
            left_names.typeNameText(left.type_name),
            right_names.typeNameText(right.type_name),
        ) and
        left.source_decl == right.source_decl;
}

const CheckedTypeAddress = struct {
    module_bytes: [32]u8,
    type_id: u32,
};

/// A scheme's quantified-variable list, by the identity of its storage.
const SchemeVarsAddress = struct {
    ptr: usize,
    len: usize,
};

fn checkedTypeAddress(view: ModuleView, checked_ty: checked.CheckedTypeId) CheckedTypeAddress {
    return .{
        .module_bytes = view.key.bytes,
        .type_id = @backingInt(checked_ty),
    };
}

const ReassignedBinderSpan = struct { start: usize, len: usize };

const ReassignedBinderAddress = struct {
    module: checked.ModuleId,
    expr: checked.CheckedExprId,
};

const NestedSiteAddress = struct {
    module_bytes: [32]u8,
    owner_proc_base: u32,
    owner_template: u32,
    expr: u32,

    fn from(
        module_key: checked.ModuleId,
        owner: names.ProcTemplate,
        expr_id: checked.CheckedExprId,
    ) NestedSiteAddress {
        return .{
            .module_bytes = module_key.bytes,
            .owner_proc_base = @backingInt(owner.proc_base),
            .owner_template = @backingInt(owner.template),
            .expr = @backingInt(expr_id),
        };
    }
};

test "hosted Try adapter narrows requested private representations by declared labels" {
    const allocator = std.testing.allocator;
    var program = Ast.Program.init(allocator);
    defer program.deinit();

    var builder: Builder = undefined;
    builder.allocator = allocator;
    builder.program = &program;
    builder.active_body_draft = null;

    const module_identity = try program.names.internModuleIdentity(&(@as([32]u8, @splat(0xA7))));
    const opaque_def = Type.TypeDef{
        .module = module_identity,
        .type_name = try program.names.internTypeName("HostedPrivate"),
    };
    const try_def = Type.TypeDef{
        .module = module_identity,
        .type_name = try program.names.internTypeName("Try"),
    };
    const opaque_named = Type.NamedType{ .module = .{}, .ty = @fromBackingInt(@intCast(1)) };
    const try_named = Type.NamedType{ .module = .{}, .ty = @fromBackingInt(@intCast(2)) };
    const i64_ty = try program.types.add(.{ .primitive = .i64 });
    const str_ty = try program.types.add(.{ .primitive = .str });
    const public_opaque = try program.types.add(.{ .named = .{
        .named_type = opaque_named,
        .def = opaque_def,
        .kind = .@"opaque",
        .args = .empty(),
        .backing = .{ .ty = i64_ty, .use = .runtime_layout_only, .authority = .checked_public },
    } });
    const private_opaque = try program.types.add(.{ .named = .{
        .named_type = opaque_named,
        .def = opaque_def,
        .kind = .@"opaque",
        .args = .empty(),
        .backing = .{ .ty = i64_ty, .use = .runtime_layout_only, .authority = .generated_private },
    } });
    const public_box = try program.types.add(.{ .box = public_opaque });
    const private_box = try program.types.add(.{ .box = private_opaque });

    const host_err = try program.names.internTagLabel("HostErr");
    const caller_err = try program.names.internTagLabel("CallerErr");
    const declared_err = try program.types.add(.{ .tag_union = try program.types.addTagVariants(&program.names, &.{.{
        .name = host_err,
        .checked_name = host_err,
        .payloads = try program.types.addSpan(&.{public_opaque}),
    }}) });
    const requested_err = try program.types.add(.{ .tag_union = try program.types.addTagVariants(&program.names, &.{
        .{
            .name = host_err,
            .checked_name = host_err,
            .payloads = try program.types.addSpan(&.{private_opaque}),
        },
        .{
            .name = caller_err,
            .checked_name = caller_err,
            .payloads = try program.types.addSpan(&.{str_ty}),
        },
    }) });

    const ok_name = try program.names.internTagLabel("Ok");
    const err_name = try program.names.internTagLabel("Err");
    const capability = HostedTryAdapterCapability{
        .def = try_def,
        .ok_tag = ok_name,
        .err_tag = err_name,
        .ok_type_arg_index = 0,
        .err_type_arg_index = 1,
    };
    const template_backing = try program.types.add(.{ .tag_union = try program.types.addTagVariants(&program.names, &.{
        .{
            .name = ok_name,
            .checked_name = ok_name,
            .payloads = try program.types.addSpan(&.{public_box}),
        },
        .{
            .name = err_name,
            .checked_name = err_name,
            .payloads = try program.types.addSpan(&.{declared_err}),
        },
    }) });
    const try_template = try program.types.add(.{ .named = .{
        .named_type = try_named,
        .def = try_def,
        .kind = .nominal,
        .args = try program.types.addSpan(&.{ public_box, declared_err }),
        .backing = .{ .ty = template_backing, .use = .inspectable },
    } });
    const declared_try = try builder.hostedTryTypeLike(capability, try_template, public_box, declared_err);
    const requested_try = try builder.hostedTryTypeLike(capability, try_template, private_box, requested_err);
    const declared_fn = try builder.closedFunctionType(&.{public_box}, declared_try);
    const requested_fn = try builder.closedFunctionType(&.{private_box}, requested_try);

    const source_fn = (try builder.resultRowWideningAdapterSourceType(capability, declared_fn, requested_fn)) orelse
        return error.TestExpectedEqual;
    const source = builder.functionShape(source_fn, "test source was not a function");
    const source_args = program.types.span(source.args);
    try std.testing.expectEqual(@as(usize, 1), source_args.len);
    try std.testing.expect(try builder.sameMonoType(GuardedList.at(source_args, 0), private_box));
    const source_try = try builder.hostedTryInfo(capability, source.ret);
    try std.testing.expect(try builder.sameMonoType(source_try.ok_ty, private_box));
    const source_err_tags = builder.tagUnionTags(source_try.err_ty);
    try std.testing.expectEqual(@as(usize, 1), source_err_tags.len);
    const source_host_err = GuardedList.at(source_err_tags, 0);
    try std.testing.expectEqual(host_err, source_host_err.name);
    const source_payloads = program.types.span(source_host_err.payloads);
    try std.testing.expectEqual(@as(usize, 1), source_payloads.len);
    try std.testing.expect(try builder.sameMonoType(GuardedList.at(source_payloads, 0), private_opaque));
    try std.testing.expect(try builder.errorRowIsIncludedIn(source_try.err_ty, requested_err));

    const impostor_def = Type.TypeDef{
        .module = module_identity,
        .type_name = try program.names.internTypeName("UserResult"),
    };
    var impostor_declared_content = program.types.get(declared_try).named;
    impostor_declared_content.def = impostor_def;
    const impostor_declared = try program.types.add(.{ .named = impostor_declared_content });
    var impostor_requested_content = program.types.get(requested_try).named;
    impostor_requested_content.def = impostor_def;
    const impostor_requested = try program.types.add(.{ .named = impostor_requested_content });
    const impostor_declared_fn = try builder.closedFunctionType(&.{public_box}, impostor_declared);
    const impostor_requested_fn = try builder.closedFunctionType(&.{private_box}, impostor_requested);
    try std.testing.expectEqual(
        @as(?Type.TypeId, null),
        try builder.resultRowWideningAdapterSourceType(capability, impostor_declared_fn, impostor_requested_fn),
    );
}

test "hosted Try info accepts alias-wrapped nominal arguments over unwrapped backing payloads" {
    // Regression test: checking may present one unified type both
    // alias-wrapped and unwrapped—a hosted declaration like basic-cli's
    // `cmd_exec_output! : Cmd => Try(CmdOutputSuccess, [NonZeroExitCode(CmdOutputFailure), ..])`
    // lowered with the `Try` nominal's error argument still naming the
    // `CmdOutputFailure` alias while the backing row's payload had resolved
    // it to its record. Recognizing the capability mapping must use type
    // equality (alias-transparent), not stored-identity digests, or lowering
    // dies with "hosted Try capability payload mapping disagreed with its
    // nominal arguments".
    const allocator = std.testing.allocator;
    var program = Ast.Program.init(allocator);
    defer program.deinit();

    var builder: Builder = undefined;
    builder.allocator = allocator;
    builder.program = &program;
    builder.active_body_draft = null;

    const module_identity = try program.names.internModuleIdentity(&(@as([32]u8, @splat(0xB2))));
    const try_def = Type.TypeDef{
        .module = module_identity,
        .type_name = try program.names.internTypeName("Try"),
    };
    const failure_alias_def = Type.TypeDef{
        .module = module_identity,
        .type_name = try program.names.internTypeName("HostFailure"),
    };
    const try_named = Type.NamedType{ .module = .{}, .ty = @fromBackingInt(@intCast(1)) };
    const failure_named = Type.NamedType{ .module = .{}, .ty = @fromBackingInt(@intCast(2)) };

    const i64_ty = try program.types.add(.{ .primitive = .i64 });
    const str_ty = try program.types.add(.{ .primitive = .str });

    const failure_record = try program.types.add(.{ .record = try program.types.addRecordFields(&program.names, &.{.{
        .name = try program.names.internRecordFieldLabel("exit_code"),
        .ty = i64_ty,
        .default = null,
    }}) });
    const failure_alias = try program.types.add(.{ .named = .{
        .named_type = failure_named,
        .def = failure_alias_def,
        .kind = .alias,
        .args = .empty(),
        .backing = .{ .ty = failure_record, .use = .inspectable },
    } });

    const host_err = try program.names.internTagLabel("HostErr");
    const caller_err = try program.names.internTagLabel("CallerErr");
    const err_row_with_alias = try program.types.add(.{ .tag_union = try program.types.addTagVariants(&program.names, &.{.{
        .name = host_err,
        .checked_name = host_err,
        .payloads = try program.types.addSpan(&.{failure_alias}),
    }}) });
    const err_row_bare = try program.types.add(.{ .tag_union = try program.types.addTagVariants(&program.names, &.{.{
        .name = host_err,
        .checked_name = host_err,
        .payloads = try program.types.addSpan(&.{failure_record}),
    }}) });

    const ok_name = try program.names.internTagLabel("Ok");
    const err_name = try program.names.internTagLabel("Err");
    const capability = HostedTryAdapterCapability{
        .def = try_def,
        .ok_tag = ok_name,
        .err_tag = err_name,
        .ok_type_arg_index = 0,
        .err_type_arg_index = 1,
    };
    const declared_backing = try program.types.add(.{ .tag_union = try program.types.addTagVariants(&program.names, &.{
        .{
            .name = ok_name,
            .checked_name = ok_name,
            .payloads = try program.types.addSpan(&.{str_ty}),
        },
        .{
            .name = err_name,
            .checked_name = err_name,
            .payloads = try program.types.addSpan(&.{err_row_bare}),
        },
    }) });
    const declared_try = try program.types.add(.{ .named = .{
        .named_type = try_named,
        .def = try_def,
        .kind = .nominal,
        .args = try program.types.addSpan(&.{ str_ty, err_row_with_alias }),
        .backing = .{ .ty = declared_backing, .use = .inspectable },
    } });

    try std.testing.expect(try builder.sameMonoType(failure_alias, failure_record));
    const declared_info = (try builder.hostedTryInfoOrNull(capability, declared_try)) orelse
        return error.TestExpectedEqual;
    try std.testing.expect(try builder.sameMonoType(declared_info.err_ty, err_row_bare));

    // A request that widens the declared error row must still produce an
    // adapter source type from the alias-carrying declared type.
    const requested_err = try program.types.add(.{ .tag_union = try program.types.addTagVariants(&program.names, &.{
        .{
            .name = host_err,
            .checked_name = host_err,
            .payloads = try program.types.addSpan(&.{failure_record}),
        },
        .{
            .name = caller_err,
            .checked_name = caller_err,
            .payloads = try program.types.addSpan(&.{str_ty}),
        },
    }) });
    const requested_try = try builder.hostedTryTypeLike(capability, declared_try, str_ty, requested_err);
    const declared_fn = try builder.closedFunctionType(&.{i64_ty}, declared_try);
    const requested_fn = try builder.closedFunctionType(&.{i64_ty}, requested_try);
    const source_fn = (try builder.resultRowWideningAdapterSourceType(capability, declared_fn, requested_fn)) orelse
        return error.TestExpectedEqual;
    const source = builder.functionShape(source_fn, "test source was not a function");
    const source_try = try builder.hostedTryInfo(capability, source.ret);
    const source_err_tags = builder.tagUnionTags(source_try.err_ty);
    try std.testing.expectEqual(@as(usize, 1), source_err_tags.len);
    try std.testing.expectEqual(host_err, GuardedList.at(source_err_tags, 0).name);
}

test "hosted Try graph walk crosses transparent alias layers to the Try nominal" {
    // `graphHostedTryInfoOrNull` is the relation side of the same recognition
    // `Builder.hostedTryNamedOrNull` performs while lowering, and the two must
    // agree. No end-to-end fixture reaches the crossing—instantiating a
    // checked root resolves alias layers, so even a hosted result declared as
    // `IoResult(Str)` arrives as the bare `Try` nominal
    // (test/fx-open/hosted_alias_try_question.roc)—so the alias chain is
    // built here directly, including a two-layer chain no single-step guard
    // would walk.
    const gpa = std.testing.allocator;

    var type_store = Type.Store.init(gpa);
    defer type_store.deinit();

    var name_store = names.NameStore.init(gpa);
    defer name_store.deinit();

    const graph = try InstGraph.create(gpa, &type_store, &name_store);
    defer graph.destroy();

    const module_identity = try name_store.internModuleIdentity(&(@as([32]u8, @splat(0xC4))));
    const try_def: Type.TypeDef = .{ .module = module_identity, .type_name = try name_store.internTypeName("Try") };
    const alias_def: Type.TypeDef = .{ .module = module_identity, .type_name = try name_store.internTypeName("IoResult") };
    const outer_alias_def: Type.TypeDef = .{ .module = module_identity, .type_name = try name_store.internTypeName("OuterResult") };
    const impostor_def: Type.TypeDef = .{ .module = module_identity, .type_name = try name_store.internTypeName("UserResult") };
    const try_named: Type.NamedType = .{ .module = .{}, .ty = @fromBackingInt(@intCast(1)) };
    const alias_named: Type.NamedType = .{ .module = .{}, .ty = @fromBackingInt(@intCast(2)) };
    const outer_alias_named: Type.NamedType = .{ .module = .{}, .ty = @fromBackingInt(@intCast(3)) };

    const ok_node = try graph.newNode(.{ .primitive = .str });
    const err_node = try graph.newNode(.empty_tag_union);
    const try_node = try graph.newNode(try graph.namedContent(.{
        .named_type = try_named,
        .def = try_def,
        .kind = .nominal,
        .builtin_owner = null,
        .args = try graph.arena().dupe(NodeId, &.{ ok_node, err_node }),
        .backing = .{ .node = try graph.newNode(.empty_tag_union), .use = .inspectable },
    }));
    const alias_node = try graph.newNode(try graph.namedContent(.{
        .named_type = alias_named,
        .def = alias_def,
        .kind = .alias,
        .builtin_owner = null,
        .args = try graph.arena().alloc(NodeId, 0),
        .backing = .{ .node = try_node, .use = .inspectable },
    }));
    const outer_alias_node = try graph.newNode(try graph.namedContent(.{
        .named_type = outer_alias_named,
        .def = outer_alias_def,
        .kind = .alias,
        .builtin_owner = null,
        .args = try graph.arena().alloc(NodeId, 0),
        .backing = .{ .node = alias_node, .use = .inspectable },
    }));

    const capability = HostedTryAdapterCapability{
        .def = try_def,
        .ok_tag = try name_store.internTagLabel("Ok"),
        .err_tag = try name_store.internTagLabel("Err"),
        .ok_type_arg_index = 0,
        .err_type_arg_index = try_error_type_arg_index,
    };

    const direct = (try graphHostedTryInfoOrNull(graph, capability, try_node)) orelse return error.TestExpectedEqual;
    try std.testing.expectEqual(ok_node, direct.ok);
    try std.testing.expectEqual(err_node, direct.err);

    const one_layer = (try graphHostedTryInfoOrNull(graph, capability, alias_node)) orelse return error.TestExpectedEqual;
    try std.testing.expectEqual(ok_node, one_layer.ok);
    try std.testing.expectEqual(err_node, one_layer.err);

    const two_layers = (try graphHostedTryInfoOrNull(graph, capability, outer_alias_node)) orelse return error.TestExpectedEqual;
    try std.testing.expectEqual(ok_node, two_layers.ok);
    try std.testing.expectEqual(err_node, two_layers.err);

    // A nominal that is not the capability's `Try` is not crossed into: only a
    // transparent alias layer is followed.
    const impostor_node = try graph.newNode(try graph.namedContent(.{
        .named_type = alias_named,
        .def = impostor_def,
        .kind = .nominal,
        .builtin_owner = null,
        .args = try graph.arena().dupe(NodeId, &.{ ok_node, err_node }),
        .backing = .{ .node = try_node, .use = .inspectable },
    }));
    try std.testing.expect((try graphHostedTryInfoOrNull(graph, capability, impostor_node)) == null);
}

test "hosted extern boundary admits only the declared host ABI type" {
    const allocator = std.testing.allocator;
    var program = Ast.Program.init(allocator);
    defer program.deinit();

    var builder: Builder = undefined;
    builder.allocator = allocator;
    builder.program = &program;
    builder.active_body_draft = null;

    const module_identity = try program.names.internModuleIdentity(&(@as([32]u8, @splat(0xC3))));
    const try_def = Type.TypeDef{
        .module = module_identity,
        .type_name = try program.names.internTypeName("Try"),
    };
    const try_named = Type.NamedType{ .module = .{}, .ty = @fromBackingInt(@intCast(4)) };
    const str_ty = try program.types.add(.{ .primitive = .str });
    const i32_ty = try program.types.add(.{ .primitive = .i32 });

    const ok_name = try program.names.internTagLabel("Ok");
    const err_name = try program.names.internTagLabel("Err");
    const host_err = try program.names.internTagLabel("HostErr");
    const exit_err = try program.names.internTagLabel("Exit");
    const capability = HostedTryAdapterCapability{
        .def = try_def,
        .ok_tag = ok_name,
        .err_tag = err_name,
        .ok_type_arg_index = 0,
        .err_type_arg_index = 1,
    };

    const declared_err = try program.types.add(.{ .tag_union = try program.types.addTagVariants(&program.names, &.{.{
        .name = host_err,
        .checked_name = host_err,
        .payloads = try program.types.addSpan(&.{str_ty}),
    }}) });
    const widened_err = try program.types.add(.{ .tag_union = try program.types.addTagVariants(&program.names, &.{
        .{
            .name = host_err,
            .checked_name = host_err,
            .payloads = try program.types.addSpan(&.{str_ty}),
        },
        .{
            .name = exit_err,
            .checked_name = exit_err,
            .payloads = try program.types.addSpan(&.{i32_ty}),
        },
    }) });

    const template_backing = try program.types.add(.{ .tag_union = try program.types.addTagVariants(&program.names, &.{
        .{
            .name = ok_name,
            .checked_name = ok_name,
            .payloads = try program.types.addSpan(&.{str_ty}),
        },
        .{
            .name = err_name,
            .checked_name = err_name,
            .payloads = try program.types.addSpan(&.{declared_err}),
        },
    }) });
    const try_template = try program.types.add(.{ .named = .{
        .named_type = try_named,
        .def = try_def,
        .kind = .nominal,
        .args = try program.types.addSpan(&.{ str_ty, declared_err }),
        .backing = .{ .ty = template_backing, .use = .inspectable },
    } });

    const declared_try = try builder.hostedTryTypeLike(capability, try_template, str_ty, declared_err);
    const widened_try = try builder.hostedTryTypeLike(capability, try_template, str_ty, widened_err);
    const declared_fn = try builder.closedFunctionType(&.{str_ty}, declared_try);

    // An extern emitted at a separately built copy of the declared type is the
    // same boundary; only its shape decides, not the `TypeId` it was built as.
    const declared_twin_fn = try builder.closedFunctionType(&.{str_ty}, declared_try);
    try std.testing.expect(try builder.hostedExternMatchesDeclaredAbi(declared_fn, declared_twin_fn, .exact));

    // A widened error row, a narrowed one, and a changed argument each mean the
    // host's value would be read at a layout the host never wrote.
    const widened_fn = try builder.closedFunctionType(&.{str_ty}, widened_try);
    try std.testing.expect(!try builder.hostedExternMatchesDeclaredAbi(declared_fn, widened_fn, .exact));

    const empty_err = try program.types.add(.{ .tag_union = try program.types.addTagVariants(&program.names, &.{}) });
    const narrowed_try = try builder.hostedTryTypeLike(capability, try_template, str_ty, empty_err);
    const narrowed_fn = try builder.closedFunctionType(&.{str_ty}, narrowed_try);
    try std.testing.expect(!try builder.hostedExternMatchesDeclaredAbi(declared_fn, narrowed_fn, .exact));

    const wrong_arg_fn = try builder.closedFunctionType(&.{i32_ty}, declared_try);
    try std.testing.expect(!try builder.hostedExternMatchesDeclaredAbi(declared_fn, wrong_arg_fn, .exact));

    // A generic hosted declaration lowers its variable slots to empty tag
    // unions, and a use instantiates them. The slots accept the instantiation;
    // the positions the declaration made concrete do not move.
    const slot_ty = try program.types.add(.{ .tag_union = try program.types.addTagVariants(&program.names, &.{}) });
    const generic_declared_fn = try builder.closedFunctionType(&.{str_ty}, try program.types.add(.{ .box = slot_ty }));
    const instantiated_fn = try builder.closedFunctionType(&.{str_ty}, try program.types.add(.{ .box = i32_ty }));
    try std.testing.expect(try builder.hostedExternMatchesDeclaredAbi(
        generic_declared_fn,
        instantiated_fn,
        .declared_variable_slots_match_any,
    ));
    try std.testing.expect(!try builder.hostedExternMatchesDeclaredAbi(
        generic_declared_fn,
        instantiated_fn,
        .exact,
    ));

    const instantiated_wrong_arg_fn = try builder.closedFunctionType(&.{i32_ty}, try program.types.add(.{ .box = i32_ty }));
    try std.testing.expect(!try builder.hostedExternMatchesDeclaredAbi(
        generic_declared_fn,
        instantiated_wrong_arg_fn,
        .declared_variable_slots_match_any,
    ));

    // The instantiation direction is the declaration's alone: an emitted type
    // with a slot where the declaration is concrete is still a violation.
    try std.testing.expect(!try builder.hostedExternMatchesDeclaredAbi(
        instantiated_fn,
        generic_declared_fn,
        .declared_variable_slots_match_any,
    ));

    var message_buf: [hosted_extern_abi_message_max]u8 = undefined;
    const message = hostedExternAbiViolationMessage(
        &message_buf,
        "roc_fallible_str_ok",
        program.types.typeDigest(&program.names, declared_fn),
        program.types.typeDigest(&program.names, widened_fn),
    );
    try std.testing.expect(std.mem.find(u8, message, "roc_fallible_str_ok") != null);
    try std.testing.expect(std.mem.find(u8, message, "host ABI") != null);

    // An over-long symbol still reports; the message stays inside its buffer.
    const long_symbol = "roc_" ++ (@as([400]u8, @splat('x')));
    const long_message = hostedExternAbiViolationMessage(
        &message_buf,
        long_symbol,
        program.types.typeDigest(&program.names, declared_fn),
        program.types.typeDigest(&program.names, widened_fn),
    );
    try std.testing.expect(long_message.len <= message_buf.len);
    try std.testing.expect(std.mem.find(u8, long_message, "roc_xxxx") != null);
}

test "request component relation follows root authority before nested private evidence" {
    const gpa = std.testing.allocator;

    var type_store = Type.Store.init(gpa);
    defer type_store.deinit();

    var name_store = names.NameStore.init(gpa);
    defer name_store.deinit();

    const graph = try InstGraph.create(gpa, &type_store, &name_store);
    defer graph.destroy();

    const module_identity = try name_store.internModuleIdentity(&(@as([32]u8, @splat(0xE1))));
    const type_name = try name_store.internTypeName("OuterEvidence");
    const inner_type_name = try name_store.internTypeName("InnerEvidence");
    const named_type: Type.NamedType = .{ .module = .{}, .ty = @fromBackingInt(@intCast(8)) };
    const inner_named_type: Type.NamedType = .{ .module = .{}, .ty = @fromBackingInt(@intCast(9)) };
    const def: Type.TypeDef = .{ .module = module_identity, .type_name = type_name };
    const inner_def: Type.TypeDef = .{ .module = module_identity, .type_name = inner_type_name };
    const private_arg = try graph.newNode(try graph.namedContent(.{
        .named_type = inner_named_type,
        .def = inner_def,
        .kind = .@"opaque",
        .builtin_owner = .fields,
        .args = try graph.arena().alloc(NodeId, 0),
        .backing = .{
            .node = try graph.newNode(.empty_record),
            .use = .runtime_layout_only,
            .authority = .generated_private,
        },
    }));
    const public = try graph.newNode(try graph.namedContent(.{
        .named_type = named_type,
        .def = def,
        .kind = .@"opaque",
        .builtin_owner = .fields,
        .args = try graph.arena().dupe(NodeId, &.{private_arg}),
        .backing = .{ .node = try graph.newNode(.empty_record), .use = .runtime_layout_only },
    }));
    const private = try graph.newNode(try graph.namedContent(.{
        .named_type = named_type,
        .def = def,
        .kind = .@"opaque",
        .builtin_owner = .fields,
        .args = try graph.arena().dupe(NodeId, &.{private_arg}),
        .backing = .{
            .node = try graph.newNode(.empty_record),
            .use = .runtime_layout_only,
            .authority = .generated_private,
        },
    }));

    try relateRequestComponent(graph, public, private);

    try std.testing.expect(!graph.sameClass(public, private));
    try std.testing.expectEqual(Type.BackingAuthority.checked_public, (try graph.content(public)).named.backing.?.authority);
    try std.testing.expectEqual(Type.BackingAuthority.generated_private, (try graph.content(private)).named.backing.?.authority);
}

