test "checked-to-mono relation preserves generated-private evidence inside a composite" {
    const gpa = std.testing.allocator;

    var type_store = Type.Store.init(gpa);
    defer type_store.deinit();

    var name_store = names.NameStore.init(gpa);
    defer name_store.deinit();

    const graph = try InstGraph.create(gpa, &type_store, &name_store);
    defer graph.destroy();

    const module_identity = try name_store.internModuleIdentity(&(@as([32]u8, @splat(0xCE))));
    const type_name = try name_store.internTypeName("CompositeEvidence");
    const named_type: Type.NamedType = .{ .module = .{}, .ty = @fromBackingInt(@intCast(1)) };
    const def: Type.TypeDef = .{ .module = module_identity, .type_name = type_name };
    const checked_backing = try graph.newNode(.empty_record);
    const mono_backing = try graph.newNode(.empty_record);
    const checked_opaque = try graph.newNode(try graph.namedContent(.{
        .named_type = named_type,
        .def = def,
        .kind = .@"opaque",
        .builtin_owner = .fields,
        .args = try graph.arena().alloc(NodeId, 0),
        .backing = .{ .node = checked_backing, .use = .runtime_layout_only },
    }));
    const mono_opaque = try graph.newNode(try graph.namedContent(.{
        .named_type = named_type,
        .def = def,
        .kind = .@"opaque",
        .builtin_owner = .fields,
        .args = try graph.arena().alloc(NodeId, 0),
        .backing = .{
            .node = mono_backing,
            .use = .runtime_layout_only,
            .authority = .generated_private,
        },
    }));
    const checked_composite = try graph.newNode(.{ .list = checked_opaque });
    const mono_composite = try graph.newNode(.{ .list = mono_opaque });

    try relateCheckedNodeToMono(graph, checked_composite, mono_composite);

    try std.testing.expect(!graph.sameClass(checked_composite, mono_composite));
    try std.testing.expect(graph.sameClass(try graph.listElementNode(checked_composite), checked_opaque));
    try std.testing.expect(graph.sameClass(try graph.listElementNode(mono_composite), mono_opaque));
    try std.testing.expect(!graph.sameClass(checked_opaque, mono_opaque));
    try std.testing.expect(!graph.sameClass(checked_backing, mono_backing));
    try std.testing.expectEqual(Type.BackingAuthority.checked_public, (try graph.content(checked_opaque)).named.backing.?.authority);
    try std.testing.expectEqual(Type.BackingAuthority.generated_private, (try graph.content(mono_opaque)).named.backing.?.authority);
}

test "checked-to-mono relation joins exact tag request roots without collapsing named payloads" {
    const gpa = std.testing.allocator;

    var type_store = Type.Store.init(gpa);
    defer type_store.deinit();

    var name_store = names.NameStore.init(gpa);
    defer name_store.deinit();

    const graph = try InstGraph.create(gpa, &type_store, &name_store);
    defer graph.destroy();

    const module_identity = try name_store.internModuleIdentity(&(@as([32]u8, @splat(0xCF))));
    const type_name = try name_store.internTypeName("PayloadEvidence");
    const tag_name = try name_store.internTagLabel("One");
    const named_type: Type.NamedType = .{ .module = .{}, .ty = @fromBackingInt(@intCast(2)) };
    const def: Type.TypeDef = .{ .module = module_identity, .type_name = type_name };
    const checked_backing = try graph.newNode(.empty_record);
    const mono_backing = try graph.newNode(.empty_record);
    const checked_payload = try graph.newNode(try graph.namedContent(.{
        .named_type = named_type,
        .def = def,
        .kind = .@"opaque",
        .builtin_owner = .fields,
        .args = try graph.arena().alloc(NodeId, 0),
        .backing = .{ .node = checked_backing, .use = .runtime_layout_only },
    }));
    const mono_payload = try graph.newNode(try graph.namedContent(.{
        .named_type = named_type,
        .def = def,
        .kind = .@"opaque",
        .builtin_owner = .fields,
        .args = try graph.arena().alloc(NodeId, 0),
        .backing = .{ .node = mono_backing, .use = .runtime_layout_only },
    }));
    const checked_row = try graph.newNode(.{ .tag_union = .{
        .tags = try graph.arena().dupe(InstTag, &.{.{
            .name = tag_name,
            .checked_name = tag_name,
            .payloads = try graph.arena().dupe(NodeId, &.{checked_payload}),
        }}),
        .ext = try graph.newNode(.empty_tag_union),
    } });
    const mono_row = try graph.newNode(.{ .tag_union = .{
        .tags = try graph.arena().dupe(InstTag, &.{.{
            .name = tag_name,
            .checked_name = tag_name,
            .payloads = try graph.arena().dupe(NodeId, &.{mono_payload}),
        }}),
        .ext = try graph.newNode(.empty_tag_union),
    } });

    try relateCheckedNodeToMono(graph, checked_row, mono_row);

    try std.testing.expect(graph.sameClass(checked_row, mono_row));
    try std.testing.expect(!graph.sameClass(checked_payload, mono_payload));
    try std.testing.expect(graph.sameClass(checked_backing, mono_backing));
}

test "issue 11235: request arguments normalize overlapping return extensions before residual matching" {
    const gpa = std.testing.allocator;
    var type_store = Type.Store.init(gpa);
    defer type_store.deinit();
    var name_store = names.NameStore.init(gpa);
    defer name_store.deinit();
    const graph = try InstGraph.create(gpa, &type_store, &name_store);
    defer graph.destroy();

    const a = try name_store.internTagLabel("A");
    const tags = [_]solve.InstTag{.{ .name = a, .checked_name = a, .payloads = &.{} }};
    const tail = try graph.newNode(.{ .unresolved = solve.InstVariable.row(.empty_tag_union) });
    const checked_ret = try graph.newNode(.{ .tag_union = .{
        .tags = try graph.arena().dupe(solve.InstTag, &tags),
        .ext = tail,
    } });
    const checked_fn = try graph.newNode(.{ .func = .{
        .args = try graph.arena().dupe(NodeId, &.{tail}),
        .ret = checked_ret,
    } });
    const request_row = try graph.newNode(.{ .tag_union = .{
        .tags = try graph.arena().dupe(solve.InstTag, &tags),
        .ext = try graph.newNode(.empty_tag_union),
    } });
    const request_fn = try graph.newNode(.{ .func = .{
        .args = try graph.arena().dupe(NodeId, &.{request_row}),
        .ret = request_row,
    } });

    _ = try checkedMonoRequestNode(graph, checked_fn, request_fn, .construction);
    try std.testing.expect(graph.sameClass(checked_fn, request_fn));
    try std.testing.expect(graph.sameClass(tail, request_row));
    const normalized = try graph.tagRowNodes(checked_ret);
    try std.testing.expectEqual(@as(usize, 1), normalized.tags.len);
    try std.testing.expectEqual(a, normalized.tags[0].name);
    try std.testing.expect(try graph.tagRowIsClosed(checked_ret));
}

test "direct call request preserves generated-private return provenance" {
    const gpa = std.testing.allocator;

    var type_store = Type.Store.init(gpa);
    defer type_store.deinit();
    var name_store = names.NameStore.init(gpa);
    defer name_store.deinit();
    const graph = try InstGraph.create(gpa, &type_store, &name_store);
    defer graph.destroy();

    const module_identity = try name_store.internModuleIdentity(&(@as([32]u8, @splat(0xD3))));
    const type_name = try name_store.internTypeName("DirectReturnEvidence");
    const named_type: Type.NamedType = .{ .module = .{}, .ty = @fromBackingInt(@intCast(4)) };
    const def: Type.TypeDef = .{ .module = module_identity, .type_name = type_name };
    const public_backing = try graph.newNode(.empty_record);
    const private_backing = try graph.newNode(.empty_record);
    const public_opaque = try graph.newNode(try graph.namedContent(.{
        .named_type = named_type,
        .def = def,
        .kind = .@"opaque",
        .builtin_owner = null,
        .args = try graph.arena().alloc(NodeId, 0),
        .backing = .{ .node = public_backing, .use = .runtime_layout_only },
    }));
    const private_opaque = try graph.newNode(try graph.namedContent(.{
        .named_type = named_type,
        .def = def,
        .kind = .@"opaque",
        .builtin_owner = null,
        .args = try graph.arena().alloc(NodeId, 0),
        .backing = .{ .node = private_backing, .use = .runtime_layout_only, .authority = .generated_private },
    }));
    const public_ret = try graph.newNode(.{ .list = public_opaque });
    const private_ret = try graph.newNode(.{ .list = private_opaque });
    const args = try graph.arena().alloc(NodeId, 0);
    const public_fn = try graph.newNode(.{ .func = .{ .args = args, .ret = public_ret } });

    const request_ret = try checkedMonoRequestNode(graph, public_ret, private_ret, .exact);
    const request_fn = try functionRequestNode(graph, public_fn, args, request_ret);

    try std.testing.expect(request_fn != public_fn);
    try std.testing.expectEqual(private_ret, (try graph.functionNodes(request_fn)).ret);
    try std.testing.expect(!graph.sameClass(public_ret, private_ret));
    try std.testing.expectEqual(Type.BackingAuthority.checked_public, (try graph.content(public_opaque)).named.backing.?.authority);
    try std.testing.expectEqual(Type.BackingAuthority.generated_private, (try graph.content(private_opaque)).named.backing.?.authority);
}

