test "draft type cell seals graph nodes into closed monotypes" {
    const gpa = std.testing.allocator;

    var type_store = Type.Store.init(gpa);
    defer type_store.deinit();

    var name_store = names.NameStore.init(gpa);
    defer name_store.deinit();

    const graph = try InstGraph.create(gpa, &type_store, &name_store);
    defer graph.destroy();

    const node = try graph.newNode(.{ .primitive = .u64 });
    try graph.freezeRelations();
    var finals = GraphTypeFinals.init(graph);
    defer finals.deinit();

    var cell = DraftTypeCell.fromGraphNode(node);
    try cell.sealInPlace(graph, &finals);
    cell.assertSealed();
    const sealed = cell.sealed;
    try std.testing.expect(!try graph.typeHasActiveSnapshots(sealed));
    const sealed_content = type_store.get(sealed);
    if (sealed_content != .primitive) return error.TestExpectedEqual;
    try std.testing.expectEqual(.u64, sealed_content.primitive);
}

test "draft sealed type cell validation distinguishes durable and active snapshots" {
    const gpa = std.testing.allocator;

    var type_store = Type.Store.init(gpa);
    defer type_store.deinit();

    var name_store = names.NameStore.init(gpa);
    defer name_store.deinit();

    const graph = try InstGraph.create(gpa, &type_store, &name_store);
    defer graph.destroy();

    const closed = try type_store.add(.{ .primitive = .u64 });
    const closed_cell = DraftTypeCell.fromSealed(closed);
    try std.testing.expect(!try closed_cell.sealedHasActiveSnapshots(graph));
    const closed_active_cell = try DraftTypeCell.fromActiveType(graph, closed);
    if (closed_active_cell != .sealed) return error.TestExpectedEqual;
    try std.testing.expectEqual(closed, closed_active_cell.sealed);

    const active_snapshot = try graph.activeTypeViewForNode(try graph.newNode(.{ .primitive = .u64 }));
    const active_snapshot_cell: DraftTypeCell = .{ .sealed = active_snapshot };
    try std.testing.expect(try active_snapshot_cell.sealedHasActiveSnapshots(graph));
    if (try DraftTypeCell.fromActiveType(graph, active_snapshot) != .graph_node) return error.TestExpectedEqual;
    try std.testing.expect(!try DraftTypeCell.fromGraphNode(try graph.newNode(.{ .primitive = .bool })).sealedHasActiveSnapshots(graph));
}

test "body draft store appends draft-local ids spans and type cells" {
    const gpa = std.testing.allocator;

    var program = Ast.Program.init(gpa);
    defer program.deinit();

    const graph = try InstGraph.create(gpa, &program.types, &program.names);
    defer graph.destroy();

    var draft = BodyDraftStore.init(gpa);
    defer draft.deinit();

    const ty = DraftTypeCell.fromGraphNode(try graph.newNode(.{ .primitive = .u64 }));
    var symbol_gen = Common.SymbolGen{};
    const local = try draft.addLocal(symbol_gen.fresh(), ty, null, null);
    const pat = try draft.addPat(.{ .ty = ty, .data = .{ .bind = local } });
    const expr = try draft.addExpr(.{ .ty = ty, .data = .{ .local = local } });
    const expr_span = try draft.addExprSpan(&.{expr});
    const pat_span = try draft.addPatSpan(&.{pat});
    const typed_local_span = try draft.addTypedLocalSpan(&.{.{ .local = local, .ty = ty }});
    const field_name = try program.names.internRecordFieldLabel("field");
    const nested_field_name = try program.names.internRecordFieldLabel("nested");
    const existing_access_segments = try program.addFieldAccessSegmentSpan(&.{.{ .field = field_name }});
    const field_span = try draft.addFieldExprSpan(&.{.{ .name = field_name, .value = expr }});
    const access_segment_span = try draft.addFieldAccessSegmentSpan(&.{
        .{ .field = field_name },
        .{ .field = nested_field_name },
    });
    const destruct_span = try draft.addRecordDestructSpan(&.{.{ .name = field_name, .pattern = pat }});
    const branch_span = try draft.addBranchSpan(&.{.{ .pat = pat, .body = expr }});
    const if_branch_span = try draft.addIfBranchSpan(&.{.{ .cond = expr, .body = expr }});
    const literal = try draft.addStringLiteral("literal");
    const str_step_span = try draft.addStrPatternStepSpan(&.{.{ .capture = pat, .delimiter = literal }});
    const declared_field_span = try draft.addDeclaredFieldSpan(&.{
        .{ .named = field_name },
        .{ .padding = ty },
    });
    const site = try draft.addComptimeSite(.if_, .first, base.Region.zero(), null, &.{base.Region.zero()});
    const source_file = try program.addSourceFile(.{ .name = "module.roc", .qualified_name = "test.module.roc", .module_identity = @splat(0) });
    try draft.setLocalName(local, "value");
    const record_pat = try draft.addPat(.{ .ty = ty, .data = .{ .record = destruct_span } });
    const str_pat = try draft.addPat(.{ .ty = ty, .data = .{ .str_pattern = .{
        .prefix = literal,
        .steps = str_step_span,
        .end = .exact,
    } } });
    const record_expr = try draft.addExpr(.{ .ty = ty, .data = .{ .record = field_span } });
    const match_expr = try draft.addExpr(.{ .ty = ty, .data = .{ .match_ = .{
        .scrutinee = expr,
        .branches = branch_span,
        .comptime_site = site,
    } } });
    const if_expr = try draft.addExpr(.{ .ty = ty, .data = .{ .if_ = .{
        .branches = if_branch_span,
        .final_else = expr,
    } } });
    const field_access_expr = try draft.addExpr(.{ .ty = ty, .data = .{ .field_access = .{
        .receiver = expr,
        .segments = access_segment_span,
    } } });
    const stmt = try draft.addStmt(.{ .let_ = .{
        .pat = pat,
        .value = expr,
        .comptime_site = site,
    } });
    const stmt_span = try draft.addStmtSpan(&.{stmt});

    try std.testing.expectEqual(@as(usize, 1), draft.locals.items.len);
    try std.testing.expectEqual(@as(usize, 3), draft.pats.items.len);
    try std.testing.expectEqual(@as(usize, 5), draft.exprs.items.len);
    try std.testing.expectEqual(@as(usize, 1), draft.stmts.items.len);
    try std.testing.expectEqual(@as(u32, 0), expr_span.start);
    try std.testing.expectEqual(@as(u32, 1), expr_span.len);
    try std.testing.expectEqual(@as(u32, 0), pat_span.start);
    try std.testing.expectEqual(@as(u32, 1), pat_span.len);
    try std.testing.expectEqual(@as(u32, 0), typed_local_span.start);
    try std.testing.expectEqual(@as(u32, 1), typed_local_span.len);
    try std.testing.expectEqual(@as(u32, 0), stmt_span.start);
    try std.testing.expectEqual(@as(u32, 1), stmt_span.len);
    try std.testing.expectEqual(@as(u32, 0), field_span.start);
    try std.testing.expectEqual(@as(u32, 1), field_span.len);
    try std.testing.expectEqual(@as(u32, 0), existing_access_segments.start);
    try std.testing.expectEqual(@as(u32, 1), existing_access_segments.len);
    try std.testing.expectEqual(@as(u32, 0), access_segment_span.start);
    try std.testing.expectEqual(@as(u32, 2), access_segment_span.len);
    try std.testing.expectEqual(@as(u32, 0), destruct_span.start);
    try std.testing.expectEqual(@as(u32, 1), destruct_span.len);
    try std.testing.expectEqual(@as(u32, 0), branch_span.start);
    try std.testing.expectEqual(@as(u32, 1), branch_span.len);
    try std.testing.expectEqual(@as(u32, 0), if_branch_span.start);
    try std.testing.expectEqual(@as(u32, 1), if_branch_span.len);
    try std.testing.expectEqual(@as(u32, 0), str_step_span.start);
    try std.testing.expectEqual(@as(u32, 1), str_step_span.len);
    try std.testing.expectEqual(@as(u32, 0), declared_field_span.start);
    try std.testing.expectEqual(@as(u32, 2), declared_field_span.len);
    try std.testing.expectEqual(@as(usize, 1), draft.string_literals.items.len);
    try std.testing.expectEqual(@as(usize, 1), draft.comptime_sites.items.len);
    try std.testing.expectEqual(@as(u32, 0), source_file);
    try std.testing.expectEqual(@as(usize, 1), draft.local_names.items.len);
    try std.testing.expect(draft.local_names.items[@backingInt(local)].len != 0);

    try graph.freezeRelations();
    var sealer = GraphTypeFinals.init(graph);
    defer sealer.deinit();
    try draft.sealCoreIntoProgram(&program, graph, &sealer);

    const sealed_local: Ast.LocalId = @fromBackingInt(@intCast(@backingInt(local)));
    const sealed_pat: Ast.PatId = @fromBackingInt(@intCast(@backingInt(pat)));
    const sealed_record_pat: Ast.PatId = @fromBackingInt(@intCast(@backingInt(record_pat)));
    const sealed_str_pat: Ast.PatId = @fromBackingInt(@intCast(@backingInt(str_pat)));
    const sealed_expr: Ast.ExprId = @fromBackingInt(@intCast(@backingInt(expr)));
    const sealed_record_expr: Ast.ExprId = @fromBackingInt(@intCast(@backingInt(record_expr)));
    const sealed_match_expr: Ast.ExprId = @fromBackingInt(@intCast(@backingInt(match_expr)));
    const sealed_if_expr: Ast.ExprId = @fromBackingInt(@intCast(@backingInt(if_expr)));
    const sealed_field_access_expr: Ast.ExprId = @fromBackingInt(@intCast(@backingInt(field_access_expr)));
    const sealed_literal: Ast.StringLiteralId = @fromBackingInt(@intCast(@backingInt(literal)));
    const sealed_site: Ast.ComptimeSiteId = @fromBackingInt(@intCast(@backingInt(site)));

    try std.testing.expectEqual(@as(usize, 1), program.localCount());
    try std.testing.expectEqual(@as(usize, 3), program.patCount());
    try std.testing.expectEqual(@as(usize, 5), program.exprCount());
    try std.testing.expectEqual(@as(usize, 1), program.stmtCount());
    try std.testing.expectEqual(@as(usize, 1), program.sourceFileCount());
    try std.testing.expectEqual(@as(usize, 1), program.stringLiteralCount());
    try std.testing.expectEqual(@as(usize, 1), program.comptimeSiteCount());
    try std.testing.expectEqual(@as(usize, 1), program.fieldExprCount());
    try std.testing.expectEqual(@as(usize, 3), program.fieldAccessSegmentCount());
    try std.testing.expectEqual(@as(usize, 1), program.recordDestructCount());
    try std.testing.expectEqual(@as(usize, 1), program.strPatternStepCount());
    try std.testing.expectEqual(@as(usize, 1), program.branchCount());
    try std.testing.expectEqual(@as(usize, 1), program.ifBranchCount());
    try std.testing.expectEqualStrings("literal", program.stringLiteralText(sealed_literal));
    try std.testing.expectEqual(Ast.ComptimeSiteKind.if_, program.comptimeSite(sealed_site).kind);
    try std.testing.expectEqual(@as(usize, 1), program.comptimeSite(sealed_site).branch_regions.len);
    try std.testing.expectEqualStrings("value", program.localName(sealed_local));
    try std.testing.expectEqual(field_name, program.getFieldExprAt(0).name);
    try std.testing.expectEqual(sealed_expr, program.getFieldExprAt(0).value);
    try std.testing.expectEqual(field_name, program.fieldAccessSegmentAt(existing_access_segments, 0).field);
    try std.testing.expectEqual(field_name, program.getRecordDestructAt(0).name);
    try std.testing.expectEqual(sealed_pat, program.getRecordDestructAt(0).pattern);
    try std.testing.expectEqual(@as(?Ast.PatId, sealed_pat), program.getStrPatternStepAt(0).capture);
    try std.testing.expectEqual(sealed_literal, program.getStrPatternStepAt(0).delimiter);
    try std.testing.expectEqual(sealed_pat, program.getBranchAt(0).pat);
    try std.testing.expectEqual(sealed_expr, program.getBranchAt(0).body);
    try std.testing.expectEqual(sealed_expr, program.getIfBranchAt(0).cond);
    try std.testing.expectEqual(sealed_expr, program.getIfBranchAt(0).body);
    {
        const data = program.getPatAt(0).data;
        if (data != .bind) return error.TestExpectedEqual;
        try std.testing.expectEqual(sealed_local, data.bind);
    }
    {
        const data = program.getPat(sealed_record_pat).data;
        if (data != .record) return error.TestExpectedEqual;
        const span = data.record;
        try std.testing.expectEqual(@as(u32, 0), span.start);
        try std.testing.expectEqual(@as(u32, 1), span.len);
    }
    {
        const data = program.getPat(sealed_str_pat).data;
        if (data != .str_pattern) return error.TestExpectedEqual;
        const pattern = data.str_pattern;
        try std.testing.expectEqual(sealed_literal, pattern.prefix);
        try std.testing.expectEqual(@as(u32, 0), pattern.steps.start);
        try std.testing.expectEqual(@as(u32, 1), pattern.steps.len);
        try std.testing.expectEqual(Ast.StrPatternEnd.exact, pattern.end);
    }
    {
        const data = program.getExprAt(0).data;
        if (data != .local) return error.TestExpectedEqual;
        try std.testing.expectEqual(sealed_local, data.local);
    }
    {
        const data = program.getExpr(sealed_record_expr).data;
        if (data != .record) return error.TestExpectedEqual;
        const span = data.record;
        try std.testing.expectEqual(@as(u32, 0), span.start);
        try std.testing.expectEqual(@as(u32, 1), span.len);
    }
    {
        const data = program.getExpr(sealed_match_expr).data;
        if (data != .match_) return error.TestExpectedEqual;
        const match_ = data.match_;
        try std.testing.expectEqual(sealed_expr, match_.scrutinee);
        try std.testing.expectEqual(@as(u32, 0), match_.branches.start);
        try std.testing.expectEqual(@as(u32, 1), match_.branches.len);
        try std.testing.expectEqual(@as(?Ast.ComptimeSiteId, sealed_site), match_.comptime_site);
    }
    {
        const data = program.getExpr(sealed_if_expr).data;
        if (data != .if_) return error.TestExpectedEqual;
        const if_ = data.if_;
        try std.testing.expectEqual(@as(u32, 0), if_.branches.start);
        try std.testing.expectEqual(@as(u32, 1), if_.branches.len);
        try std.testing.expectEqual(sealed_expr, if_.final_else);
    }
    {
        const data = program.getExpr(sealed_field_access_expr).data;
        if (data != .field_access) return error.TestExpectedEqual;
        const access = data.field_access;
        try std.testing.expectEqual(sealed_expr, access.receiver);
        try std.testing.expectEqual(@as(u32, 1), access.segments.start);
        try std.testing.expectEqual(@as(u32, 2), access.segments.len);
        try std.testing.expectEqual(field_name, program.fieldAccessSegmentAt(access.segments, 0).field);
        try std.testing.expectEqual(nested_field_name, program.fieldAccessSegmentAt(access.segments, 1).field);
    }
    {
        const sealed_stmt = program.getStmtAt(0);
        if (sealed_stmt != .let_) return error.TestExpectedEqual;
        const let_ = sealed_stmt.let_;
        try std.testing.expectEqual(sealed_pat, let_.pat);
        try std.testing.expectEqual(sealed_expr, let_.value);
        try std.testing.expectEqual(@as(?Ast.ComptimeSiteId, sealed_site), let_.comptime_site);
    }
}

test "body draft static data candidates use ordered commit ids" {
    const allocator = std.testing.allocator;
    var program = Ast.Program.init(allocator);
    defer program.deinit();
    const graph = try InstGraph.create(allocator, &program.types, &program.names);
    defer graph.destroy();
    try graph.freezeRelations();
    var sealer = GraphTypeFinals.init(graph);
    defer sealer.deinit();
    var committed_types = CommittedGraphTypes.shared(graph, &sealer);
    var draft = BodyDraftStore.init(allocator);
    defer draft.deinit();

    const draft_static: DraftStaticDataId = @fromBackingInt(@intCast(@as(u32, @intCast(0))));
    const draft_runtime: DraftExprId = @fromBackingInt(@intCast(@as(u32, @intCast(0))));
    const committed_static: Common.StaticDataId = @fromBackingInt(@intCast(@as(u32, @intCast(17))));
    var comptime_roots = collections.DenseMap(DraftComptimeValueRootId, Common.ComptimeValueRootId).init(allocator);
    defer comptime_roots.deinit();
    const sealed = try draft.sealCoreExprData(
        &program,
        BodyDraftStore.finalIdOffsets(&program),
        &committed_types,
        &.{committed_static},
        &comptime_roots,
        .{ .static_data_candidate = .{
            .storage = .{ .string_backing = 23 },
            .static_data = draft_static,
            .runtime_expr = draft_runtime,
        } },
    );
    if (sealed != .static_data_candidate) return error.TestExpectedEqual;
    try std.testing.expectEqual(committed_static, sealed.static_data_candidate.static_data);
    try std.testing.expectEqual(@as(u64, 23), sealed.static_data_candidate.storage.string_backing);
    try std.testing.expectEqual(
        @as(Ast.ExprId, @fromBackingInt(@intCast(@as(u32, @intCast(0))))),
        sealed.static_data_candidate.runtime_expr,
    );
}

test "specialization workspace retains bidirectional type relocation across serial epochs" {
    const allocator = std.testing.allocator;
    var program = Ast.Program.init(allocator);
    defer program.deinit();

    const program_bool = try program.types.internPrimitive(&program.names, .bool);
    const program_field = try program.names.internRecordFieldLabel("program_value");
    const program_record = try program.types.internRecord(&program.names, &.{
        .{ .name = program_field, .ty = program_bool, .default = null },
    });
    var committed_list: Type.TypeId = undefined;
    var committed_record: Type.TypeId = undefined;
    var committed_workspace_field: names.RecordFieldNameId = undefined;

    {
        var workspace = SpecJobWorkspace.init(allocator);
        defer workspace.deinit();

        var workspace_bool: Type.TypeId = undefined;
        var workspace_record: Type.TypeId = undefined;
        var workspace_list: Type.TypeId = undefined;
        var ingress_count_after_first_epoch: usize = undefined;
        var committed_count_after_first_epoch: usize = undefined;
        var ingress_name_count_after_first_epoch: usize = undefined;
        var committed_name_count_after_first_epoch: usize = undefined;

        {
            const epoch = workspace.beginEpoch(&program);
            defer workspace.finishEpoch(epoch);

            const ingress = workspace.programTypeRelocation(&program);
            var imported = try workspace.types.importTypes(
                &workspace.name_store,
                &program.types,
                &program.names,
                ingress,
                &.{ program_bool, program_record },
            );
            defer imported.deinit();
            workspace_bool = imported.roots[0];
            workspace_record = imported.roots[1];
            workspace_list = try workspace.types.internList(&workspace.name_store, workspace_bool);
            const program_field_count_before_private_name = program.names.recordFieldLabelCount();
            const workspace_field = try workspace.name_store.internRecordFieldLabel("workspace_value");
            const workspace_owned_record = try workspace.types.internRecord(&workspace.name_store, &.{
                .{ .name = workspace_field, .ty = workspace_list, .default = null },
            });
            try std.testing.expectEqual(
                program_field_count_before_private_name,
                program.names.recordFieldLabelCount(),
            );

            const committed = workspace.committedTypeRelocation(&program);
            var exported = try program.types.importTypes(
                &program.names,
                &workspace.types,
                &workspace.name_store,
                committed,
                &.{ workspace_list, workspace_owned_record },
            );
            defer exported.deinit();
            committed_list = exported.roots[0];
            committed_record = exported.roots[1];
            try std.testing.expectEqual(
                program_field_count_before_private_name + 1,
                program.names.recordFieldLabelCount(),
            );
            const committed_workspace_fields = program.types.fieldSpan(switch (program.types.get(committed_record)) {
                .record => |fields| fields,
                .primitive, .named, .tuple, .tag_union, .box, .list, .func, .erased, .zst => return error.TestExpectedEqual,
            });
            committed_workspace_field = GuardedList.at(committed_workspace_fields, 0).name;

            ingress_count_after_first_epoch = ingress.mappedCount();
            committed_count_after_first_epoch = committed.mappedCount();
            ingress_name_count_after_first_epoch = ingress.namesRelocation().mappedCount();
            committed_name_count_after_first_epoch = committed.namesRelocation().mappedCount();
            const workspace_program_fields = workspace.types.fieldSpan(switch (workspace.types.get(workspace_record)) {
                .record => |fields| fields,
                .primitive, .named, .tuple, .tag_union, .box, .list, .func, .erased, .zst => return error.TestExpectedEqual,
            });
            const workspace_program_field = GuardedList.at(workspace_program_fields, 0).name;
            try std.testing.expectEqualStrings(
                "program_value",
                workspace.name_store.recordFieldLabelText(workspace_program_field),
            );
        }

        {
            const epoch = workspace.beginEpoch(&program);
            defer workspace.finishEpoch(epoch);

            const ingress = workspace.programTypeRelocation(&program);
            const committed = workspace.committedTypeRelocation(&program);
            try std.testing.expectEqual(ingress_count_after_first_epoch, ingress.mappedCount());
            try std.testing.expectEqual(committed_count_after_first_epoch, committed.mappedCount());
            try std.testing.expectEqual(ingress_name_count_after_first_epoch, ingress.namesRelocation().mappedCount());
            try std.testing.expectEqual(committed_name_count_after_first_epoch, committed.namesRelocation().mappedCount());
            try std.testing.expectEqual(workspace_bool, ingress.get(&program.types, program_bool).?);
            try std.testing.expectEqual(workspace_record, ingress.get(&program.types, program_record).?);
            try std.testing.expectEqual(committed_list, committed.get(&workspace.types, workspace_list).?);

            // Importing a type produced by the reverse relocation must converge
            // on the workspace's existing canonical type rather than duplicate it.
            var imported_list = try workspace.types.importTypes(
                &workspace.name_store,
                &program.types,
                &program.names,
                ingress,
                &.{committed_list},
            );
            defer imported_list.deinit();
            try std.testing.expectEqual(workspace_list, imported_list.roots[0]);

            // Both stores may keep growing after the cumulative maps are created.
            const program_unit = try program.types.internZst(&program.names);
            var imported_unit = try workspace.types.importTypes(
                &workspace.name_store,
                &program.types,
                &program.names,
                ingress,
                &.{program_unit},
            );
            defer imported_unit.deinit();
            try std.testing.expectEqual(.zst, workspace.types.get(imported_unit.roots[0]));
            try std.testing.expectEqual(workspace_bool, ingress.get(&program.types, program_bool).?);
            try std.testing.expectEqual(committed_list, committed.get(&workspace.types, workspace_list).?);
        }
    }

    // Coordinator output remains self-contained after the persistent workspace dies.
    const committed_bool = switch (program.types.get(committed_list)) {
        .list => |element| element,
        .primitive, .named, .record, .tuple, .tag_union, .box, .func, .erased, .zst => return error.TestExpectedEqual,
    };
    const committed_primitive = switch (program.types.get(committed_bool)) {
        .primitive => |primitive| primitive,
        .named, .record, .tuple, .tag_union, .box, .list, .func, .erased, .zst => return error.TestExpectedEqual,
    };
    try std.testing.expectEqual(.bool, committed_primitive);
    const committed_fields = program.types.fieldSpan(switch (program.types.get(committed_record)) {
        .record => |fields| fields,
        .primitive, .named, .tuple, .tag_union, .box, .list, .func, .erased, .zst => return error.TestExpectedEqual,
    });
    try std.testing.expectEqual(@as(usize, 1), GuardedList.borrowLen(committed_fields));
    try std.testing.expectEqual(committed_workspace_field, GuardedList.at(committed_fields, 0).name);
    try std.testing.expectEqualStrings(
        "workspace_value",
        program.names.recordFieldLabelText(GuardedList.at(committed_fields, 0).name),
    );
}

test "specialization store epochs survive workspace teardown and absorb cumulatively" {
    const allocator = std.testing.allocator;
    var program = Ast.Program.init(allocator);
    defer program.deinit();

    var first_epoch: ?SpecJobStoreEpoch = null;
    defer if (first_epoch) |*epoch| epoch.deinit();
    var empty_epoch: ?SpecJobStoreEpoch = null;
    defer if (empty_epoch) |*epoch| epoch.deinit();
    var second_epoch: ?SpecJobStoreEpoch = null;
    defer if (second_epoch) |*epoch| epoch.deinit();
    var private_record: Type.TypeId = undefined;
    var private_union: Type.TypeId = undefined;

    {
        var workspace = SpecJobWorkspace.init(allocator);
        defer workspace.deinit();

        const first = workspace.beginEpoch(&program);
        const field_name = try workspace.name_store.internRecordFieldLabel("epoch_value");
        const primitive = try workspace.types.internPrimitive(&workspace.name_store, .u64);
        private_record = try workspace.types.internRecord(&workspace.name_store, &.{
            .{ .name = field_name, .ty = primitive, .default = null },
        });
        first_epoch = try workspace.captureStoreEpoch(first);
        workspace.finishEpoch(first);

        const empty = workspace.beginEpoch(&program);
        empty_epoch = try workspace.captureStoreEpoch(empty);
        workspace.finishEpoch(empty);

        const second = workspace.beginEpoch(&program);
        const tag_name = try workspace.name_store.internTagLabel("EpochValue");
        private_union = try workspace.types.internTagUnion(&workspace.name_store, &.{
            .{
                .name = tag_name,
                .checked_name = tag_name,
                .payloads = &.{private_record},
            },
        });
        second_epoch = try workspace.captureStoreEpoch(second);
        workspace.finishEpoch(second);

        // Result epochs must not borrow source arrays: grow both stores after
        // capture, then destroy the workspace before coordinator absorption.
        var index: u32 = 0;
        while (index < 256) : (index += 1) {
            var digest = @as([32]u8, @splat(0));
            std.mem.writeInt(u32, digest[0..4], index, .little);
            _ = try workspace.types.internErased(
                &workspace.name_store,
                .{ .bytes = digest },
            );
            var text_buffer: [32]u8 = undefined;
            const text = try std.fmt.bufPrint(&text_buffer, "post_epoch_{d}", .{index});
            _ = try workspace.name_store.internRecordFieldLabel(text);
        }
    }

    var commit_domain = SpecJobCommitDomain.init(allocator);
    defer commit_domain.deinit();
    try commit_domain.absorb(&first_epoch.?);
    try std.testing.expect(std.meta.eql(
        commit_domain.types.epochBoundary(),
        first_epoch.?.types.end,
    ));
    const private_fields = commit_domain.types.fieldSpan(switch (commit_domain.types.get(private_record)) {
        .record => |fields| fields,
        .primitive, .named, .tuple, .tag_union, .box, .list, .func, .erased, .zst => return error.TestExpectedEqual,
    });
    try std.testing.expectEqualStrings(
        "epoch_value",
        commit_domain.name_store.recordFieldLabelText(GuardedList.at(private_fields, 0).name),
    );
    const relocation = commit_domain.committedTypeRelocation(&program);
    var imported_record = try program.types.importTypes(
        &program.names,
        &commit_domain.types,
        &commit_domain.name_store,
        relocation,
        &.{private_record},
    );
    defer imported_record.deinit();
    const committed_record = imported_record.roots[0];

    const types_before_empty = commit_domain.types.epochBoundary();
    const names_before_empty = commit_domain.name_store.epochBoundary();
    try commit_domain.absorb(&empty_epoch.?);
    try std.testing.expect(std.meta.eql(types_before_empty, commit_domain.types.epochBoundary()));
    try std.testing.expect(std.meta.eql(names_before_empty, commit_domain.name_store.epochBoundary()));

    try commit_domain.absorb(&second_epoch.?);
    try std.testing.expect(std.meta.eql(
        commit_domain.types.epochBoundary(),
        second_epoch.?.types.end,
    ));
    const private_tags = commit_domain.types.tagSpan(switch (commit_domain.types.get(private_union)) {
        .tag_union => |tags| tags,
        .primitive, .named, .record, .tuple, .box, .list, .func, .erased, .zst => return error.TestExpectedEqual,
    });
    const private_tag = GuardedList.at(private_tags, 0);
    try std.testing.expectEqualStrings(
        "EpochValue",
        commit_domain.name_store.tagLabelText(private_tag.name),
    );
    try std.testing.expectEqual(
        private_record,
        GuardedList.at(commit_domain.types.span(private_tag.payloads), 0),
    );

    var imported = try program.types.importTypes(
        &program.names,
        &commit_domain.types,
        &commit_domain.name_store,
        relocation,
        &.{private_union},
    );
    defer imported.deinit();
    const committed_union = imported.roots[0];

    commit_domain.deinit();
    commit_domain = SpecJobCommitDomain.init(allocator);
    const committed_tags = program.types.tagSpan(switch (program.types.get(committed_union)) {
        .tag_union => |tags| tags,
        .primitive, .named, .record, .tuple, .box, .list, .func, .erased, .zst => return error.TestExpectedEqual,
    });
    const committed_tag = GuardedList.at(committed_tags, 0);
    try std.testing.expectEqualStrings(
        "EpochValue",
        program.names.tagLabelText(committed_tag.name),
    );
    try std.testing.expectEqual(
        committed_record,
        GuardedList.at(program.types.span(committed_tag.payloads), 0),
    );
    try std.testing.expect(program.types.verify(&program.names) == null);
}

test "specialization store epoch absorption preserves boundaries on allocation failure" {
    const allocator = std.testing.allocator;
    var program = Ast.Program.init(allocator);
    defer program.deinit();
    var workspace = SpecJobWorkspace.init(allocator);
    defer workspace.deinit();

    const workspace_epoch = workspace.beginEpoch(&program);
    const field_name = try workspace.name_store.internRecordFieldLabel("retry_value");
    const primitive = try workspace.types.internPrimitive(&workspace.name_store, .u64);
    const record = try workspace.types.internRecord(&workspace.name_store, &.{
        .{ .name = field_name, .ty = primitive, .default = null },
    });
    var first_epoch = try workspace.captureStoreEpoch(workspace_epoch);
    defer first_epoch.deinit();
    workspace.finishEpoch(workspace_epoch);

    const next_workspace_epoch = workspace.beginEpoch(&program);
    const tag_name = try workspace.name_store.internTagLabel("RetryValue");
    const union_ty = try workspace.types.internTagUnion(&workspace.name_store, &.{
        .{
            .name = tag_name,
            .checked_name = tag_name,
            .payloads = &.{record},
        },
    });
    var second_epoch = try workspace.captureStoreEpoch(next_workspace_epoch);
    defer second_epoch.deinit();
    workspace.finishEpoch(next_workspace_epoch);

    const Helper = struct {
        fn absorbWithRetry(
            domain: *SpecJobCommitDomain,
            source_epoch: *const SpecJobStoreEpoch,
            injected_error: *?Allocator.Error,
        ) Allocator.Error!void {
            const types_before = domain.types.epochBoundary();
            const names_before = domain.name_store.epochBoundary();
            domain.absorb(source_epoch) catch |err| {
                std.debug.assert(std.meta.eql(types_before, domain.types.epochBoundary()));
                std.debug.assert(std.meta.eql(names_before, domain.name_store.epochBoundary()));
                std.debug.assert(injected_error.* == null);
                try domain.absorb(source_epoch);
                injected_error.* = err;
            };
            std.debug.assert(std.meta.eql(source_epoch.types.end, domain.types.epochBoundary()));
            std.debug.assert(std.meta.eql(source_epoch.names.end, domain.name_store.epochBoundary()));
        }

        fn run(
            failing_allocator: Allocator,
            source_first: *const SpecJobStoreEpoch,
            source_second: *const SpecJobStoreEpoch,
            expected_record: Type.TypeId,
            expected_union: Type.TypeId,
        ) Allocator.Error!void {
            var domain = SpecJobCommitDomain.init(failing_allocator);
            defer domain.deinit();
            var injected_error: ?Allocator.Error = null;
            try absorbWithRetry(&domain, source_first, &injected_error);
            try absorbWithRetry(&domain, source_second, &injected_error);

            const fields = domain.types.fieldSpan(switch (domain.types.get(expected_record)) {
                .record => |span| span,
                .primitive, .named, .tuple, .tag_union, .box, .list, .func, .erased, .zst => unreachable,
            });
            std.debug.assert(std.mem.eql(
                u8,
                "retry_value",
                domain.name_store.recordFieldLabelText(GuardedList.at(fields, 0).name),
            ));
            const tags = domain.types.tagSpan(switch (domain.types.get(expected_union)) {
                .tag_union => |span| span,
                .primitive, .named, .record, .tuple, .box, .list, .func, .erased, .zst => unreachable,
            });
            const tag = GuardedList.at(tags, 0);
            std.debug.assert(std.mem.eql(
                u8,
                "RetryValue",
                domain.name_store.tagLabelText(tag.name),
            ));
            std.debug.assert(GuardedList.at(domain.types.span(tag.payloads), 0) == expected_record);
            if (injected_error) |err| return err;
        }
    };
    try std.testing.checkAllAllocationFailures(
        allocator,
        Helper.run,
        .{ &first_epoch, &second_epoch, record, union_ty },
    );
}

test "executor lane retains Monotype state within a run and resets it between runs" {
    const allocator = std.testing.allocator;
    var lane_state = base.post_check_task_executor.LaneState.init(allocator);
    defer lane_state.deinit();
    const executor_worker = base.post_check_task_executor.Worker{
        .id = 0,
        .allocator = allocator,
        .scratch = allocator,
        .lane_state = &lane_state,
    };
    var inputs: SpecJobWorkerInputs = undefined;
    inputs.run_id = @fromBackingInt(@intCast(1));

    const first = try Builder.ensureSpecJobLaneState(executor_worker, &inputs);
    first.worker.tasks_started = 7;
    const same_run = try Builder.ensureSpecJobLaneState(executor_worker, &inputs);
    try std.testing.expectEqual(first, same_run);
    try std.testing.expectEqual(@as(u64, 7), same_run.worker.tasks_started);

    inputs.run_id = @fromBackingInt(@intCast(2));
    const next_run = try Builder.ensureSpecJobLaneState(executor_worker, &inputs);
    try std.testing.expectEqual(first, next_run);
    try std.testing.expectEqual(@as(u64, 0), next_run.worker.tasks_started);
    try std.testing.expectEqual(inputs.run_id, next_run.run_id);
}

test "body draft comptime roots relocate independent shards and survive source destruction" {
    const allocator = std.testing.allocator;
    var program = Ast.Program.init(allocator);
    defer program.deinit();
    const descriptors = [_]Common.ComptimeValueRoot{
        .{
            .module = .{ .bytes = @splat(0x31) },
            .root = .{ .checked = @fromBackingInt(@intCast(7)) },
            .const_locator = .{
                .artifact = .{ .bytes = @splat(0x41) },
                .owner = .{ .hoisted_expr = .{ .module_idx = 19, .expr = @fromBackingInt(@intCast(23)) } },
                .template = @fromBackingInt(@intCast(29)),
                .source_scheme = .{ .bytes = @splat(0x51) },
            },
        },
        .{
            .module = .{ .bytes = @splat(0x32) },
            .root = .{ .checked = @fromBackingInt(@intCast(11)) },
            .const_locator = null,
        },
    };
    var committed: [2]Common.ComptimeValueRootId = undefined;
    for (descriptors, 0..) |descriptor, shard_index| {
        // Each independently owned shard starts at ordinal zero. Only its
        // retained draft, not a worker Program, supplies metadata at commit.
        var draft = BodyDraftStore.init(allocator);
        defer draft.deinit();
        const root = try draft.addComptimeValueRoot(descriptor);
        try std.testing.expectEqual(@as(u32, 0), @backingInt(root));
        const graph = try InstGraph.create(allocator, &program.types, &program.names);
        defer graph.destroy();
        const unit_node = try graph.newNode(.zst);
        const cell = DraftTypeCell.fromGraphNode(unit_node);
        const initializer = try draft.addExpr(.{ .ty = cell, .data = .unit });
        for (0..2) |_| {
            _ = try draft.addExpr(.{ .ty = cell, .data = .{ .comptime_value = .{
                .root = root,
                .initializer = initializer,
            } } });
        }
        try graph.freezeRelations();
        var sealer = GraphTypeFinals.init(graph);
        defer sealer.deinit();
        try draft.sealTypeCellsInPlace(graph, &sealer);
        draft.discardGraphStateAfterSeal();
        draft.assertGraphStateDiscarded();
        try draft.sealCoreIntoProgram(&program, graph, &sealer);
        const first = program.getExprAt(shard_index * 3 + 1).data.comptime_value;
        const second = program.getExprAt(shard_index * 3 + 2).data.comptime_value;
        try std.testing.expectEqual(first.root, second.root);
        try std.testing.expectEqual(first.initializer, second.initializer);
        try std.testing.expectEqual(@as(u32, @intCast(shard_index * 3)), @backingInt(first.initializer));
        committed[shard_index] = first.root;
    }
    // Both source owners are dead. Equal local ordinals must not alias, and
    // duplicate references must have copied each exact descriptor only once.
    try std.testing.expect(committed[0] != committed[1]);
    try std.testing.expectEqual(@as(u32, 1), @backingInt(committed[1]));
    for (descriptors, committed) |descriptor, root| {
        try std.testing.expectEqualDeep(descriptor, program.getComptimeValueRoot(root));
    }
}

test "body draft commit relocates core type and name fields out of private stores" {
    const allocator = std.testing.allocator;

    var program = Ast.Program.init(allocator);
    defer program.deinit();
    _ = try program.types.internPrimitive(&program.names, .bool);
    _ = try program.names.internRecordFieldLabel("unrelated");
    _ = try program.names.internTagLabel("Unrelated");
    _ = try program.names.internTypeName("Unrelated");
    _ = try program.names.internModuleIdentity(&(@as([32]u8, @splat(0xFF))));
    _ = try program.names.internExportName("unrelated");

    var sealed_list: Type.TypeId = undefined;
    var debug_symbol: Common.Symbol = undefined;
    {
        var private_names = names.NameStore.init(allocator);
        defer private_names.deinit();
        var private_types = Type.Store.init(allocator);
        defer private_types.deinit();
        const graph = try InstGraph.create(allocator, &private_types, &private_names);
        defer graph.destroy();

        var draft = BodyDraftStore.init(allocator);
        defer draft.deinit();
        const unit_node = try graph.newNode(.zst);
        const list_node = try graph.newNode(.{ .list = unit_node });
        const unit_cell = DraftTypeCell.fromGraphNode(unit_node);
        const list_cell = DraftTypeCell.fromGraphNode(list_node);

        var symbol_gen = Common.SymbolGen{};
        const local = try draft.addLocal(symbol_gen.fresh(), list_cell, null, null);
        const bind_pat = try draft.addPat(.{ .ty = list_cell, .data = .{ .bind = local } });
        const expr = try draft.addExpr(.{ .ty = list_cell, .data = .{ .local = local } });
        const field_name = try private_names.internRecordFieldLabel("value");
        const tag_name = try private_names.internTagLabel("Value");
        const field_exprs = try draft.addFieldExprSpan(&.{.{ .name = field_name, .value = expr }});
        _ = try draft.addExpr(.{ .ty = list_cell, .data = .{ .record = field_exprs } });
        _ = try draft.addExpr(.{ .ty = list_cell, .data = .{ .tag = .{
            .name = tag_name,
            .payloads = DraftSpan(DraftExprId).empty(),
        } } });
        const access_segments = try draft.addFieldAccessSegmentSpan(&.{.{ .field = field_name }});
        _ = try draft.addExpr(.{ .ty = list_cell, .data = .{ .field_access = .{
            .receiver = expr,
            .segments = access_segments,
        } } });
        _ = try draft.addPat(.{ .ty = list_cell, .data = .{ .tag = .{
            .name = tag_name,
            .payloads = DraftSpan(DraftPatId).empty(),
        } } });
        const destructs = try draft.addRecordDestructSpan(&.{.{ .name = field_name, .pattern = bind_pat }});
        _ = try draft.addPat(.{ .ty = list_cell, .data = .{ .record = destructs } });
        _ = try draft.addTypedLocalSpan(&.{.{ .local = local, .ty = list_cell }});
        _ = try draft.addStmt(.{ .return_ = .{ .value = expr, .target = unit_cell } });
        debug_symbol = symbol_gen.fresh();
        try draft.proc_debug_names.append(allocator, .{
            .symbol = debug_symbol,
            .name = try private_names.internExportName("helper"),
        });
        const module_bytes = @as([32]u8, @splat(0xAB));
        const module = try private_names.internModuleIdentity(&module_bytes);
        const type_name = try private_names.internTypeName("Model");
        try draft.runtime_schema_requests.append(allocator, .{
            .def = .{ .module = module, .type_name = type_name },
            .ty = list_cell,
        });
        try draft.runtime_schema_requests.append(allocator, .{
            .def = .{ .module = module, .type_name = type_name },
            .ty = list_cell,
        });

        try graph.freezeRelations();
        var sealer = GraphTypeFinals.init(graph);
        defer sealer.deinit();
        var relocation = Type.Store.TypeRelocation.init(
            allocator,
            &private_types,
            &private_names,
            &program.types,
            &program.names,
        );
        defer relocation.deinit();
        var committed_types = CommittedGraphTypes.relocated(
            graph,
            &sealer,
            &program.types,
            &program.names,
            &relocation,
        );
        try draft.sealCoreIntoProgramWithMap(
            &program,
            &committed_types,
            &.{},
            BodyDraftStore.finalIdOffsets(&program),
            null,
            null,
            null,
        );
        sealed_list = program.getLocal(@fromBackingInt(@intCast(@backingInt(local)))).ty;
    }

    // Program storage must remain self-contained after all private owners die.
    const sealed_unit = switch (program.types.get(sealed_list)) {
        .list => |element| element,
        .primitive, .named, .record, .tuple, .tag_union, .box, .func, .erased, .zst => return error.TestExpectedEqual,
    };
    try std.testing.expectEqual(.zst, program.types.get(sealed_unit));
    try std.testing.expectEqual(sealed_list, program.getPatAt(0).ty);
    try std.testing.expectEqual(sealed_list, program.getExprAt(0).ty);
    try std.testing.expectEqual(sealed_list, GuardedList.at(program.typedLocalSpan(.{ .start = 0, .len = 1 }), 0).ty);
    const sealed_record_expr = program.getExprAt(1).data.record;
    try std.testing.expectEqualStrings(
        "value",
        program.names.recordFieldLabelText(GuardedList.at(program.fieldExprSpan(sealed_record_expr), 0).name),
    );
    try std.testing.expectEqualStrings("Value", program.names.tagLabelText(program.getExprAt(2).data.tag.name));
    const sealed_access = program.getExprAt(3).data.field_access;
    try std.testing.expectEqualStrings(
        "value",
        program.names.recordFieldLabelText(program.fieldAccessSegmentAt(sealed_access.segments, 0).field),
    );
    try std.testing.expectEqualStrings("Value", program.names.tagLabelText(program.getPatAt(1).data.tag.name));
    try std.testing.expectEqualStrings(
        "value",
        program.names.recordFieldLabelText(GuardedList.at(program.recordDestructSpan(program.getPatAt(2).data.record), 0).name),
    );
    try std.testing.expectEqualStrings("helper", program.names.exportNameText(program.procDebugName(debug_symbol).?));
    try std.testing.expectEqual(@as(usize, 1), program.runtimeSchemaRequestsView().len);
    const schema = program.runtimeSchemaRequestsView()[0];
    try std.testing.expectEqualSlices(u8, &(@as([32]u8, @splat(0xAB))), program.names.moduleIdentityBytes(schema.def.module));
    try std.testing.expectEqualStrings("Model", program.names.typeNameText(schema.def.type_name));
    const sealed_stmt = program.getStmtAt(0);
    if (sealed_stmt != .return_) return error.TestExpectedEqual;
    try std.testing.expectEqual(sealed_unit, sealed_stmt.return_.target);
    program.freeze();
    try std.testing.expectEqual(@as(?Ast.CompletedTypeIdVerifyError, null), program.view().verifyCompletedTypeIds());
}

test "body draft ownership runs restore the parent across nested lowering" {
    const allocator = std.testing.allocator;
    const outer_fn: DraftFnId = @fromBackingInt(@intCast(10));
    const inner_fn: DraftFnId = @fromBackingInt(@intCast(11));
    var draft = BodyDraftStore.init(allocator);
    defer draft.deinit();

    try draft.expr_ids.append(allocator, @fromBackingInt(@intCast(20)));
    {
        const outer = try draft.enterOwner(.{ .draft_fn = outer_fn });
        defer outer.leave();
        try draft.expr_ids.append(allocator, @fromBackingInt(@intCast(1)));
        {
            const inner = try draft.enterOwner(.{ .draft_fn = inner_fn });
            defer inner.leave();
            try draft.expr_ids.append(allocator, @fromBackingInt(@intCast(2)));
        }
        try draft.expr_ids.append(allocator, @fromBackingInt(@intCast(3)));
    }
    try draft.finishOwnerRuns();

    try std.testing.expectEqual(@as(usize, 4), draft.owner_runs.items.len);
    const kind = @backingInt(DraftCoreKind.expr_ids);
    try std.testing.expect(std.meta.eql(DraftOwner.root, draft.owner_runs.items[0].owner));
    try std.testing.expect(std.meta.eql(DraftOwner{ .draft_fn = outer_fn }, draft.owner_runs.items[1].owner));
    try std.testing.expect(std.meta.eql(DraftOwner{ .draft_fn = inner_fn }, draft.owner_runs.items[2].owner));
    try std.testing.expect(std.meta.eql(DraftOwner{ .draft_fn = outer_fn }, draft.owner_runs.items[3].owner));
    for (draft.owner_runs.items, 0..) |owner_run, index| {
        try std.testing.expectEqual(@as(u32, @intCast(index)), owner_run.starts[kind]);
        try std.testing.expectEqual(@as(u32, @intCast(index + 1)), owner_run.ends[kind]);
    }
}

test "body draft owner scopes leave without allocating under allocation failure" {
    const Scenario = struct {
        fn run(allocator: std.mem.Allocator) Allocator.Error!void {
            const outer_fn: DraftFnId = @fromBackingInt(@intCast(10));
            const inner_fn: DraftFnId = @fromBackingInt(@intCast(11));
            var draft = BodyDraftStore.init(allocator);
            defer draft.deinit();

            try draft.expr_ids.append(allocator, @fromBackingInt(@intCast(20)));
            {
                const outer = try draft.enterOwner(.{ .draft_fn = outer_fn });
                defer outer.leave();
                try draft.expr_ids.append(allocator, @fromBackingInt(@intCast(1)));
                {
                    // Re-entering the current owner records no run on entry,
                    // yet its exit still needs a reserved slot.
                    const same = try draft.enterOwner(.{ .draft_fn = outer_fn });
                    defer same.leave();
                    try draft.expr_ids.append(allocator, @fromBackingInt(@intCast(2)));
                    {
                        const inner = try draft.enterOwner(.{ .draft_fn = inner_fn });
                        defer inner.leave();
                        try draft.expr_ids.append(allocator, @fromBackingInt(@intCast(3)));
                    }
                }
                try draft.expr_ids.append(allocator, @fromBackingInt(@intCast(4)));
            }
            try draft.finishOwnerRuns();
        }
    };
    try std.testing.checkAllAllocationFailures(std.testing.allocator, Scenario.run, .{});
}

test "body draft core ownership distinguishes sibling materializations" {
    const allocator = std.testing.allocator;
    const first_fn: DraftFnId = @fromBackingInt(@intCast(1));
    const second_fn: DraftFnId = @fromBackingInt(@intCast(2));
    var draft = BodyDraftStore.init(allocator);
    defer draft.deinit();

    const first_scope = try draft.enterOwner(.{ .draft_fn = first_fn });
    const first_literal = try draft.addStringLiteral("first");
    try std.testing.expect(draft.currentOwnerOwnsCore(.string_literals, @backingInt(first_literal)));

    const second_scope = try draft.enterOwner(.{ .draft_fn = second_fn });
    try std.testing.expect(!draft.currentOwnerOwnsCore(.string_literals, @backingInt(first_literal)));
    const second_literal = try draft.addStringLiteral("second");
    try std.testing.expect(draft.currentOwnerOwnsCore(.string_literals, @backingInt(second_literal)));
    second_scope.leave();

    try std.testing.expect(draft.currentOwnerOwnsCore(.string_literals, @backingInt(first_literal)));
    try std.testing.expect(!draft.currentOwnerOwnsCore(.string_literals, @backingInt(second_literal)));
    first_scope.leave();
}

